# General Takuzu / Binairo solver using human-like deduction first, then tightly pruned search.
# Grid symbols:
#   'B' black
#   'W' white
#   None unknown

from copy import deepcopy

VALS = ('B', 'W')


def opposite(v):
    return 'W' if v == 'B' else 'B'


def solve(observation):
    grid = deepcopy(observation['data'])
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    if not valid_partial(grid):
        return "No Solution"

    res = search(grid)
    return res if isinstance(res, list) else "No Solution"


def valid_partial(grid):
    n = len(grid)
    half = n // 2

    # row checks
    seen_full_rows = set()
    for r in range(n):
        row = grid[r]
        b = row.count('B')
        w = row.count('W')
        if b > half or w > half:
            return False
        for c in range(n - 2):
            a, b1, c1 = row[c], row[c + 1], row[c + 2]
            if a is not None and a == b1 == c1:
                return False
        if None not in row:
            t = tuple(row)
            if t in seen_full_rows:
                return False
            seen_full_rows.add(t)

    # column checks
    seen_full_cols = set()
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        b = col.count('B')
        w = col.count('W')
        if b > half or w > half:
            return False
        for r in range(n - 2):
            a, b1, c1 = col[r], col[r + 1], col[r + 2]
            if a is not None and a == b1 == c1:
                return False
        if None not in col:
            t = tuple(col)
            if t in seen_full_cols:
                return False
            seen_full_cols.add(t)

    return True


def line_deductions(line):
    n = len(line)
    half = n // 2
    out = list(line)
    changed = False

    # Rule 1: count balancing
    b = out.count('B')
    w = out.count('W')
    if b > half or w > half:
        return None
    if b == half:
        for i in range(n):
            if out[i] is None:
                out[i] = 'W'
                changed = True
    elif w == half:
        for i in range(n):
            if out[i] is None:
                out[i] = 'B'
                changed = True

    # Rule 2: avoid triples
    progress = True
    while progress:
        progress = False
        for i in range(n - 2):
            a, b1, c = out[i], out[i + 1], out[i + 2]

            if a is not None and a == b1 and c is None:
                out[i + 2] = opposite(a)
                changed = True
                progress = True
            elif a is None and b1 is not None and b1 == c:
                out[i] = opposite(b1)
                changed = True
                progress = True
            elif a is not None and c is not None and a == c and b1 is None:
                out[i + 1] = opposite(a)
                changed = True
                progress = True

        b = out.count('B')
        w = out.count('W')
        if b > half or w > half:
            return None
        if b == half:
            for i in range(n):
                if out[i] is None:
                    out[i] = 'W'
                    changed = True
                    progress = True
        elif w == half:
            for i in range(n):
                if out[i] is None:
                    out[i] = 'B'
                    changed = True
                    progress = True

    # final triple / count validation
    b = out.count('B')
    w = out.count('W')
    if b > half or w > half:
        return None
    for i in range(n - 2):
        a, b1, c = out[i], out[i + 1], out[i + 2]
        if a is not None and a == b1 == c:
            return None

    return out if changed else line


def line_can_match_partial(candidate, partial):
    for a, b in zip(candidate, partial):
        if b is not None and a != b:
            return False
    return True


def generate_line_patterns(n):
    half = n // 2
    patterns = []

    def rec(pos, line, b, w):
        if b > half or w > half:
            return
        if pos >= 3 and line[pos - 1] == line[pos - 2] == line[pos - 3]:
            return
        if pos == n:
            if b == half and w == half:
                patterns.append(tuple(line))
            return
        line.append('B')
        rec(pos + 1, line, b + 1, w)
        line.pop()

        line.append('W')
        rec(pos + 1, line, b, w + 1)
        line.pop()

    rec(0, [], 0, 0)
    return patterns


def get_domains(grid, patterns):
    n = len(grid)
    row_domains = []
    col_domains = []

    full_rows = {tuple(grid[r]) for r in range(n) if None not in grid[r]}
    cols = [[grid[r][c] for r in range(n)] for c in range(n)]
    full_cols = {tuple(cols[c]) for c in range(n) if None not in cols[c]}

    for r in range(n):
        row = grid[r]
        dom = [p for p in patterns if line_can_match_partial(p, row)]
        if None not in row:
            dom = [tuple(row)] if tuple(row) in dom else []
        else:
            # if a row becomes full, it must be unique among existing full rows except itself
            filtered = []
            for p in dom:
                if p in full_rows:
                    continue
                filtered.append(p)
            dom = filtered if filtered else dom
        row_domains.append(dom)

    for c in range(n):
        col = cols[c]
        dom = [p for p in patterns if line_can_match_partial(p, col)]
        if None not in col:
            dom = [tuple(col)] if tuple(col) in dom else []
        else:
            filtered = []
            for p in dom:
                if p in full_cols:
                    continue
                filtered.append(p)
            dom = filtered if filtered else dom
        col_domains.append(dom)

    return row_domains, col_domains


def propagate(grid, patterns):
    n = len(grid)

    while True:
        if not valid_partial(grid):
            return None

        changed = False

        # Basic line deductions on rows
        for r in range(n):
            new_row = line_deductions(grid[r])
            if new_row is None:
                return None
            if new_row != grid[r]:
                grid[r] = new_row
                changed = True

        # Basic line deductions on columns
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            new_col = line_deductions(col)
            if new_col is None:
                return None
            if new_col != col:
                for r in range(n):
                    grid[r][c] = new_col[r]
                changed = True

        if not valid_partial(grid):
            return None

        # Domain-based deductions
        row_domains, col_domains = get_domains(grid, patterns)
        if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
            return None

        # Intersect row domains into cells
        for r in range(n):
            if None in grid[r]:
                dom = row_domains[r]
                for c in range(n):
                    if grid[r][c] is None:
                        vals = {p[c] for p in dom}
                        if len(vals) == 1:
                            grid[r][c] = next(iter(vals))
                            changed = True

        # Intersect column domains into cells
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if None in col:
                dom = col_domains[c]
                for r in range(n):
                    if grid[r][c] is None:
                        vals = {p[r] for p in dom}
                        if len(vals) == 1:
                            grid[r][c] = next(iter(vals))
                            changed = True

        if not valid_partial(grid):
            return None

        # Uniqueness-driven pair deductions for rows:
        # if a row has exactly 2 unknowns and matches a full row on known cells,
        # it must differ somewhere, so remaining unknown choices may be forced by domains already.
        # Implemented generically via domain pruning against existing full rows/cols.
        row_domains, col_domains = get_domains(grid, patterns)
        if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
            return None

        # If a row/col domain is singleton, write it.
        for r in range(n):
            if len(row_domains[r]) == 1:
                p = row_domains[r][0]
                for c in range(n):
                    if grid[r][c] != p[c]:
                        grid[r][c] = p[c]
                        changed = True

        for c in range(n):
            if len(col_domains[c]) == 1:
                p = col_domains[c][0]
                for r in range(n):
                    if grid[r][c] != p[r]:
                        grid[r][c] = p[r]
                        changed = True

        if not changed:
            return grid


def is_solved(grid):
    n = len(grid)
    if any(None in row for row in grid):
        return False
    if not valid_partial(grid):
        return False
    return True


def choose_branch(grid, patterns):
    n = len(grid)
    row_domains, col_domains = get_domains(grid, patterns)

    best = None

    # Prefer the most constrained line domain > 1
    for r in range(n):
        d = row_domains[r]
        if 1 < len(d) and (best is None or len(d) < best[0]):
            best = (len(d), 'row', r, d)

    for c in range(n):
        d = col_domains[c]
        if 1 < len(d) and (best is None or len(d) < best[0]):
            best = (len(d), 'col', c, d)

    if best is not None:
        _, kind, idx, dom = best
        return kind, idx, dom

    # Fallback: choose cell with smallest feasible values from row/col domains
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                rv = {p[c] for p in row_domains[r]}
                cv = {p[r] for p in col_domains[c]}
                vals = tuple(sorted(rv & cv))
                if len(vals) == 0:
                    return 'cell', (r, c), ()
                if len(vals) == 1:
                    return 'cell', (r, c), vals
                return 'cell', (r, c), vals

    return None


def search(grid):
    n = len(grid)
    patterns = generate_line_patterns(n)
    grid = propagate(grid, patterns)
    if grid is None:
        return None
    if is_solved(grid):
        return grid

    branch = choose_branch(grid, patterns)
    if branch is None:
        return None

    kind = branch[0]

    if kind == 'row':
        _, r, dom = branch
        for p in dom:
            ng = deepcopy(grid)
            ng[r] = list(p)
            res = search(ng)
            if res is not None:
                return res
        return None

    if kind == 'col':
        _, c, dom = branch
        for p in dom:
            ng = deepcopy(grid)
            for r in range(n):
                ng[r][c] = p[r]
            res = search(ng)
            if res is not None:
                return res
        return None

    _, (r, c), vals = branch
    for v in vals:
        ng = deepcopy(grid)
        ng[r][c] = v
        res = search(ng)
        if res is not None:
            return res
    return None


