# Consecutive Sudoku / Kropki-Latin solver
# Human-like logic:
# - maintain row/column uniqueness candidates
# - enforce dot/non-dot adjacency constraints
# - propagate singles / hidden singles
# - use local support pruning on every edge
# - branch only on most constrained cell when logic stalls

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    n = len(data)
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        v = 1
        while mask:
            if mask & 1:
                vals.append(v)
            v += 1
            mask >>= 1
        return vals

    def popcount(x):
        return x.bit_count()

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def single_value(mask):
        return mask.bit_length()

    dot_set = set()
    for a, b in adjacent:
        dot_set.add((a, b))

    neighbors = [[] for _ in range(n * n)]
    edge_has_dot = {}

    def cell_id(r, c):
        return r * n + c

    for r in range(n):
        for c in range(n):
            u = cell_id(r, c)
            if c + 1 < n:
                mid = (float(r), c + 0.5)
                v = cell_id(r, c + 1)
                has_dot = mid in dot_set
                neighbors[u].append(v)
                neighbors[v].append(u)
                edge_has_dot[(u, v)] = has_dot
                edge_has_dot[(v, u)] = has_dot
            if r + 1 < n:
                mid = (r + 0.5, float(c))
                v = cell_id(r + 1, c)
                has_dot = mid in dot_set
                neighbors[u].append(v)
                neighbors[v].append(u)
                edge_has_dot[(u, v)] = has_dot
                edge_has_dot[(v, u)] = has_dot

    support_dot = [0] * (n + 1)
    support_nodot = [0] * (n + 1)
    for v in range(1, n + 1):
        m_dot = 0
        m_nodot = 0
        for w in range(1, n + 1):
            if abs(v - w) == 1:
                m_dot |= bit(w)
            else:
                m_nodot |= bit(w)
        support_dot[v] = m_dot
        support_nodot[v] = m_nodot

    row_cells = [[cell_id(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[cell_id(r, c) for r in range(n)] for c in range(n)]

    initial_domains = [full_mask] * (n * n)
    row_used = [0] * n
    col_used = [0] * n

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            idx = cell_id(r, c)
            if v is not None:
                m = bit(v)
                if row_used[r] & m or col_used[c] & m:
                    return "No Solution"
                initial_domains[idx] = m
                row_used[r] |= m
                col_used[c] |= m

    for r in range(n):
        forbidden = row_used[r]
        for c in range(n):
            idx = cell_id(r, c)
            if not is_single(initial_domains[idx]):
                initial_domains[idx] &= ~forbidden & full_mask
                if initial_domains[idx] == 0:
                    return "No Solution"

    for c in range(n):
        forbidden = col_used[c]
        for r in range(n):
            idx = cell_id(r, c)
            if not is_single(initial_domains[idx]):
                initial_domains[idx] &= ~forbidden & full_mask
                if initial_domains[idx] == 0:
                    return "No Solution"

    def enforce_edge_pair(mask_a, mask_b, has_dot):
        new_a = 0
        new_b = 0
        vals_a = mask_to_values(mask_a)
        vals_b = mask_to_values(mask_b)
        present_b = set(vals_b)
        present_a = set(vals_a)

        if has_dot:
            for va in vals_a:
                if ((va > 1 and (va - 1) in present_b) or (va < n and (va + 1) in present_b)):
                    new_a |= bit(va)
            for vb in vals_b:
                if ((vb > 1 and (vb - 1) in present_a) or (vb < n and (vb + 1) in present_a)):
                    new_b |= bit(vb)
        else:
            for va in vals_a:
                if support_nodot[va] & mask_b:
                    new_a |= bit(va)
            for vb in vals_b:
                if support_nodot[vb] & mask_a:
                    new_b |= bit(vb)
        return new_a, new_b

    def propagate(domains):
        domains = domains[:]
        changed = True
        while changed:
            changed = False

            # Row/column fixed values remove from peers
            for r in range(n):
                fixed = 0
                for idx in row_cells[r]:
                    if is_single(domains[idx]):
                        fixed |= domains[idx]
                for idx in row_cells[r]:
                    if not is_single(domains[idx]):
                        new_mask = domains[idx] & (~fixed & full_mask)
                        if new_mask == 0:
                            return None
                        if new_mask != domains[idx]:
                            domains[idx] = new_mask
                            changed = True

            for c in range(n):
                fixed = 0
                for idx in col_cells[c]:
                    if is_single(domains[idx]):
                        fixed |= domains[idx]
                for idx in col_cells[c]:
                    if not is_single(domains[idx]):
                        new_mask = domains[idx] & (~fixed & full_mask)
                        if new_mask == 0:
                            return None
                        if new_mask != domains[idx]:
                            domains[idx] = new_mask
                            changed = True

            # Hidden singles in rows
            for r in range(n):
                for v in range(1, n + 1):
                    m = bit(v)
                    places = []
                    for idx in row_cells[r]:
                        if domains[idx] & m:
                            places.append(idx)
                    if not places:
                        return None
                    if len(places) == 1 and domains[places[0]] != m:
                        domains[places[0]] = m
                        changed = True

            # Hidden singles in columns
            for c in range(n):
                for v in range(1, n + 1):
                    m = bit(v)
                    places = []
                    for idx in col_cells[c]:
                        if domains[idx] & m:
                            places.append(idx)
                    if not places:
                        return None
                    if len(places) == 1 and domains[places[0]] != m:
                        domains[places[0]] = m
                        changed = True

            # Adjacency support pruning
            for u in range(n * n):
                mu = domains[u]
                for v in neighbors[u]:
                    if u < v:
                        mv = domains[v]
                        nu, nv = enforce_edge_pair(mu, mv, edge_has_dot[(u, v)])
                        if nu == 0 or nv == 0:
                            return None
                        if nu != mu:
                            domains[u] = nu
                            mu = nu
                            changed = True
                        if nv != mv:
                            domains[v] = nv
                            changed = True

            # If a cell is fixed, remove value from row/col peers immediately
            for r in range(n):
                seen = 0
                for idx in row_cells[r]:
                    if is_single(domains[idx]):
                        if seen & domains[idx]:
                            return None
                        seen |= domains[idx]
            for c in range(n):
                seen = 0
                for idx in col_cells[c]:
                    if is_single(domains[idx]):
                        if seen & domains[idx]:
                            return None
                        seen |= domains[idx]

        return domains

    def solved(domains):
        return all(is_single(m) for m in domains)

    def choose_cell(domains):
        best = -1
        best_key = None
        for r in range(n):
            for c in range(n):
                idx = cell_id(r, c)
                m = domains[idx]
                pc = popcount(m)
                if pc > 1:
                    support_score = 0
                    for nb in neighbors[idx]:
                        support_score += popcount(domains[nb])
                    key = (pc, support_score)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = idx
        return best

    def order_values(idx, domains):
        vals = mask_to_values(domains[idx])
        scored = []
        for v in vals:
            score = 0
            m = bit(v)
            r, c = divmod(idx, n)
            for peer in row_cells[r]:
                if peer != idx and (domains[peer] & m):
                    score += 1
            for peer in col_cells[c]:
                if peer != idx and (domains[peer] & m):
                    score += 1
            for nb in neighbors[idx]:
                if edge_has_dot[(idx, nb)]:
                    score += popcount(domains[nb] & support_dot[v])
                else:
                    score += popcount(domains[nb] & support_nodot[v])
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if solved(domains):
            return domains

        idx = choose_cell(domains)
        if idx == -1:
            return domains

        for v in order_values(idx, domains):
            nd = domains[:]
            nd[idx] = bit(v)
            res = dfs(nd)
            if res is not None:
                return res
        return None

    result = dfs(initial_domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(result[cell_id(r, c)]))
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

