from collections import defaultdict, deque
import json

# Generalized Minesweeper solver for partially-clued boards:
# - Number cells are revealed clues.
# - None cells are hidden cells that may or may not contain mines.
# Output is a same-sized grid of 'F' for mines and None otherwise.

def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0

    hidden = {(r, c) for r in range(h) for c in range(w) if data[r][c] is None}
    clues = {(r, c): data[r][c] for r in range(h) for c in range(w) if data[r][c] is not None}

    nbr8 = {}
    for r in range(h):
        for c in range(w):
            cur = []
            for dr in (-1, 0, 1):
                nr = r + dr
                if 0 <= nr < h:
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nc = c + dc
                        if 0 <= nc < w:
                            cur.append((nr, nc))
            nbr8[(r, c)] = cur

    clue_to_hidden = {}
    hidden_to_clues = defaultdict(list)
    for cell, val in clues.items():
        hs = [p for p in nbr8[cell] if p in hidden]
        clue_to_hidden[cell] = hs
        for p in hs:
            hidden_to_clues[p].append(cell)

    # Variables that actually matter are hidden cells adjacent to at least one clue.
    frontier = sorted([p for p in hidden if hidden_to_clues[p]])
    unconstrained = sorted(hidden - set(frontier))

    # If there are unconstrained hidden cells, the puzzle is underdetermined unless
    # all solutions agree on them. With only local clues, they do not appear in constraints,
    # so they can never be proved mines. We therefore require a full consistent assignment
    # and mark only those forced by constraints. If multiple solutions differ only there,
    # answer uses None on those cells.
    var_index = {p: i for i, p in enumerate(frontier)}

    # Build clue equations over frontier vars only.
    equations = []
    for clue_cell, val in clues.items():
        vars_ = [var_index[p] for p in clue_to_hidden[clue_cell] if p in var_index]
        equations.append((tuple(vars_), val))

    # Immediate contradiction checks.
    for vars_, total in equations:
        if total < 0 or total > len(vars_):
            return "No Solution"

    # Connected components on frontier variables via shared clues.
    var_graph = [[] for _ in frontier]
    clue_vars = []
    for vars_, total in equations:
        clue_vars.append(vars_)
        m = len(vars_)
        for i in range(m):
            vi = vars_[i]
            for j in range(i + 1, m):
                vj = vars_[j]
                var_graph[vi].append(vj)
                var_graph[vj].append(vi)

    comps = []
    seen = [False] * len(frontier)
    for i in range(len(frontier)):
        if not seen[i]:
            dq = [i]
            seen[i] = True
            comp = []
            while dq:
                x = dq.pop()
                comp.append(x)
                for y in var_graph[x]:
                    if not seen[y]:
                        seen[y] = True
                        dq.append(y)
            comps.append(sorted(comp))

    if not frontier:
        # No constrained hidden cells. All hidden cells are unconstrained, so no mines can be deduced uniquely.
        ans = [[None for _ in range(w)] for _ in range(h)]
        return json.dumps(ans)

    # Map clues to components they belong to.
    comp_solutions = []
    comp_for_var = {}
    for ci, comp in enumerate(comps):
        for v in comp:
            comp_for_var[v] = ci

    clues_by_comp = [[] for _ in comps]
    for eq_idx, (vars_, total) in enumerate(equations):
        if vars_:
            ci = comp_for_var[vars_[0]]
            clues_by_comp[ci].append((vars_, total))

    # Human-like propagation:
    # For each component, repeatedly apply:
    # - exact fill: remaining mines 0 => all safe; remaining mines == undecided => all mines
    # - subset rule between constraints A subset B
    # Then branch on the most constrained variable if needed.
    def solve_component(comp_vars, comp_eqs):
        local_vars = list(comp_vars)
        lindex = {g: i for i, g in enumerate(local_vars)}
        eqs = []
        var_to_eqs = [[] for _ in local_vars]
        for vars_, total in comp_eqs:
            lv = tuple(sorted(lindex[v] for v in vars_))
            eqs.append([list(lv), total])
        for ei, (vs, total) in enumerate(eqs):
            for v in vs:
                var_to_eqs[v].append(ei)

        # Collect all satisfying assignments for this component.
        solutions = []
        assign = [-1] * len(local_vars)  # -1 unknown, 0 safe, 1 mine

        def propagate():
            changed = True
            while changed:
                changed = False

                # Basic exact-fill rules.
                for vs, total in eqs:
                    unknown = []
                    s = 0
                    for v in vs:
                        av = assign[v]
                        if av == -1:
                            unknown.append(v)
                        else:
                            s += av
                    rem = total - s
                    if rem < 0 or rem > len(unknown):
                        return False
                    if not unknown:
                        if rem != 0:
                            return False
                        continue
                    if rem == 0:
                        for v in unknown:
                            if assign[v] == -1:
                                assign[v] = 0
                                changed = True
                            elif assign[v] != 0:
                                return False
                    elif rem == len(unknown):
                        for v in unknown:
                            if assign[v] == -1:
                                assign[v] = 1
                                changed = True
                            elif assign[v] != 1:
                                return False

                # Subset-difference rules on residual constraints.
                residuals = []
                for vs, total in eqs:
                    u = []
                    s = 0
                    for v in vs:
                        av = assign[v]
                        if av == -1:
                            u.append(v)
                        else:
                            s += av
                    rem = total - s
                    if rem < 0 or rem > len(u):
                        return False
                    residuals.append((tuple(u), rem))

                # Use pairwise subset reasoning.
                nres = len(residuals)
                for i in range(nres):
                    Ai, ai = residuals[i]
                    if not Ai:
                        continue
                    setAi = set(Ai)
                    for j in range(nres):
                        if i == j:
                            continue
                        Bj, bj = residuals[j]
                        if not Bj:
                            continue
                        setBj = set(Bj)
                        if setAi.issubset(setBj):
                            diff = [v for v in Bj if v not in setAi]
                            d = bj - ai
                            if d < 0 or d > len(diff):
                                return False
                            if diff:
                                if d == 0:
                                    for v in diff:
                                        if assign[v] == -1:
                                            assign[v] = 0
                                            changed = True
                                        elif assign[v] != 0:
                                            return False
                                elif d == len(diff):
                                    for v in diff:
                                        if assign[v] == -1:
                                            assign[v] = 1
                                            changed = True
                                        elif assign[v] != 1:
                                            return False
            return True

        def choose_var():
            best = None
            best_score = -1
            for v in range(len(local_vars)):
                if assign[v] != -1:
                    continue
                # Most constrained variable first.
                score = len(var_to_eqs[v])
                # Prefer smaller equations around it.
                score2 = 0
                for ei in var_to_eqs[v]:
                    score2 += 10 - min(9, len(eqs[ei][0]))
                key = (score, score2)
                if key > (best_score, -1):
                    best_score = score
                    best = v
            return best

        def dfs():
            if not propagate():
                return
            v = choose_var()
            if v is None:
                solutions.append(assign[:])
                return

            # Try values in a heuristic order based on nearby residual demand.
            mine_bias = 0
            safe_bias = 0
            for ei in var_to_eqs[v]:
                vs, total = eqs[ei]
                s = 0
                u = 0
                for x in vs:
                    ax = assign[x]
                    if ax == -1:
                        u += 1
                    else:
                        s += ax
                rem = total - s
                if u > 0:
                    mine_bias += rem
                    safe_bias += (u - rem)
            order = (1, 0) if mine_bias >= safe_bias else (0, 1)

            snapshot = assign[:]
            for val in order:
                assign[v] = val
                dfs()
                assign[:] = snapshot

        dfs()
        return local_vars, solutions

    all_forced = {}
    for ci, comp in enumerate(comps):
        local_vars, sols = solve_component(comp, clues_by_comp[ci])
        if not sols:
            return "No Solution"
        # Keep only forced variables across all component solutions.
        for li, gv in enumerate(local_vars):
            first = sols[0][li]
            forced = all(sol[li] == first for sol in sols[1:])
            if forced:
                all_forced[gv] = first

    ans = [[None for _ in range(w)] for _ in range(h)]
    for gv, val in all_forced.items():
        if val == 1:
            r, c = frontier[gv]
            ans[r][c] = 'F'

    # Unconstrained hidden cells and non-forced frontier cells remain None.
    return json.dumps(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

