from collections import deque, defaultdict

# Generalized Minesweeper-style solver:
# - Variables are only cells with None in observation.
# - Every numbered cell imposes an exact-count constraint over adjacent unknown cells.
# - Solver emphasizes human-like propagation:
#   * local zero/full deductions
#   * subset/superset difference deductions
#   * component decomposition
#   * constrained branching on most-informative variable only when needed

def solve(observation):
    grid = observation['data']
    if not grid or not grid[0]:
        return str([])

    R, C = len(grid), len(grid[0])

    def nbrs(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if nr < 0 or nr >= R:
                continue
            for dc in (-1, 0, 1):
                nc = c + dc
                if dc == 0 and dr == 0:
                    continue
                if 0 <= nc < C:
                    yield nr, nc

    # Unknown cells are the candidate mine cells.
    unknowns = []
    var_index = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] is None:
                var_index[(r, c)] = len(unknowns)
                unknowns.append((r, c))

    nvars = len(unknowns)

    # Build exact constraints from numbered clues.
    constraints = []
    var_to_constraints = [[] for _ in range(nvars)]

    for r in range(R):
        for c in range(C):
            clue = grid[r][c]
            if clue is None:
                continue
            cells = []
            for nr, nc in nbrs(r, c):
                if grid[nr][nc] is None:
                    cells.append(var_index[(nr, nc)])
            # Exact count among neighboring unknowns.
            constraints.append((frozenset(cells), clue))

    # Remove duplicate constraints if any.
    tmp = {}
    for s, k in constraints:
        if s in tmp and tmp[s] != k:
            return "No Solution"
        tmp[s] = k
    constraints = [(set(s), k) for s, k in tmp.items()]

    # Immediate contradiction checks on raw constraints.
    for s, k in constraints:
        if k < 0 or k > len(s):
            return "No Solution"

    # Map vars to constraints.
    for ci, (s, k) in enumerate(constraints):
        for v in s:
            var_to_constraints[v].append(ci)

    # Variables not touched by any clue are unconstrained, but in standard single-solution
    # mine-identification tasks they should remain non-mines unless forced otherwise.
    # We treat them as variables too; if disconnected and unconstrained they default to 0
    # because otherwise multiple solutions would exist. Search still verifies consistency.
    touched = [False] * nvars
    for s, _ in constraints:
        for v in s:
            touched[v] = True

    # Build connected components on variables via shared constraints.
    # Unconstrained variables become singleton components and default to 0.
    visited = [False] * nvars
    components = []

    for v in range(nvars):
        if visited[v]:
            continue
        if not touched[v]:
            visited[v] = True
            components.append(([v], []))
            continue
        q = deque([v])
        visited[v] = True
        comp_vars = set()
        comp_cons = set()
        while q:
            x = q.popleft()
            comp_vars.add(x)
            for ci in var_to_constraints[x]:
                if ci in comp_cons:
                    continue
                comp_cons.add(ci)
                s, _ = constraints[ci]
                for y in s:
                    if not visited[y]:
                        visited[y] = True
                        q.append(y)
        components.append((sorted(comp_vars), sorted(comp_cons)))

    final_assign = [0] * nvars  # default all non-mines

    def solve_component(comp_vars, comp_cons):
        if not comp_cons:
            return {v: 0 for v in comp_vars}

        gvar_map = {v: i for i, v in enumerate(comp_vars)}
        local_to_global = list(comp_vars)

        local_constraints = []
        local_var_to_constraints = [[] for _ in comp_vars]
        for lci, gci in enumerate(comp_cons):
            s, k = constraints[gci]
            ls = set(gvar_map[v] for v in s if v in gvar_map)
            if k < 0 or k > len(ls):
                return None
            local_constraints.append([ls, k])
            for lv in ls:
                local_var_to_constraints[lv].append(lci)

        n = len(comp_vars)
        assign = [-1] * n  # -1 unknown, 0 safe, 1 mine

        # Per-constraint dynamic counts.
        c_unknown = [len(s) for s, _ in local_constraints]
        c_mines = [0] * len(local_constraints)

        # Fast support structures for subset reasoning.
        def current_sets():
            # Return active residual exact constraints: residual unknown set -> residual mines needed
            mp = {}
            for i, (s0, k0) in enumerate(local_constraints):
                rem = set()
                km = k0
                for v in s0:
                    a = assign[v]
                    if a == -1:
                        rem.add(v)
                    elif a == 1:
                        km -= 1
                fs = frozenset(rem)
                if km < 0 or km > len(rem):
                    return None
                if fs in mp and mp[fs] != km:
                    return None
                mp[fs] = km
            return [(set(s), k) for s, k in mp.items()]

        trail = []

        def set_var(v, val):
            cur = assign[v]
            if cur != -1:
                return cur == val
            assign[v] = val
            trail.append(v)
            for ci in local_var_to_constraints[v]:
                c_unknown[ci] -= 1
                if val == 1:
                    c_mines[ci] += 1
                need = local_constraints[ci][1] - c_mines[ci]
                if need < 0 or need > c_unknown[ci]:
                    return False
            return True

        def undo(mark):
            while len(trail) > mark:
                v = trail.pop()
                val = assign[v]
                for ci in local_var_to_constraints[v]:
                    c_unknown[ci] += 1
                    if val == 1:
                        c_mines[ci] -= 1
                assign[v] = -1

        def propagate():
            changed = True
            while changed:
                changed = False

                # Basic exact-count propagation.
                for ci, (s, k) in enumerate(local_constraints):
                    need = k - c_mines[ci]
                    unk = c_unknown[ci]
                    if need < 0 or need > unk:
                        return False
                    if unk == 0:
                        continue
                    if need == 0 or need == unk:
                        force = 1 if need == unk else 0
                        for v in s:
                            if assign[v] == -1:
                                if not set_var(v, force):
                                    return False
                                changed = True

                # Advanced human-like subset difference propagation.
                residual = current_sets()
                if residual is None:
                    return False

                # Remove trivial empty constraints already checked.
                residual = [(s, k) for s, k in residual if s]

                # Pairwise subset reasoning:
                # If A subset B then B\A has exactly kB-kA mines.
                # If diff count is 0 => all in B\A safe; if equals size(diff) => all mines.
                m = len(residual)
                for i in range(m):
                    A, a = residual[i]
                    for j in range(m):
                        if i == j:
                            continue
                        B, b = residual[j]
                        if len(A) > len(B):
                            continue
                        if A.issubset(B):
                            D = B - A
                            d = b - a
                            if d < 0 or d > len(D):
                                return False
                            if D and (d == 0 or d == len(D)):
                                force = 1 if d == len(D) else 0
                                for v in D:
                                    if assign[v] == -1:
                                        if not set_var(v, force):
                                            return False
                                        changed = True
            return True

        def choose_var():
            # Most informative variable: appears in many tight constraints.
            best_v = None
            best_score = None
            for v in range(n):
                if assign[v] != -1:
                    continue
                deg = len(local_var_to_constraints[v])
                tight = 0
                span = 0
                for ci in local_var_to_constraints[v]:
                    need = local_constraints[ci][1] - c_mines[ci]
                    unk = c_unknown[ci]
                    if unk > 0:
                        # Smaller margin => tighter.
                        margin = min(need, unk - need)
                        tight += (unk - margin)
                        span += unk
                score = (deg, tight, -span)
                if best_score is None or score > best_score:
                    best_score = score
                    best_v = v
            return best_v

        def dfs():
            if not propagate():
                return False
            v = choose_var()
            if v is None:
                return True

            # Branch order heuristic: try value suggested by local pressure.
            mine_pressure = 0
            safe_pressure = 0
            for ci in local_var_to_constraints[v]:
                need = local_constraints[ci][1] - c_mines[ci]
                unk = c_unknown[ci]
                if unk <= 0:
                    continue
                mine_pressure += need / unk
                safe_pressure += (unk - need) / unk

            order = (1, 0) if mine_pressure >= safe_pressure else (0, 1)

            for val in order:
                mark = len(trail)
                if set_var(v, val) and dfs():
                    return True
                undo(mark)
            return False

        if not dfs():
            return None

        return {local_to_global[i]: assign[i] if assign[i] != -1 else 0 for i in range(n)}

    for comp_vars, comp_cons in components:
        res = solve_component(comp_vars, comp_cons)
        if res is None:
            return "No Solution"
        for gv, val in res.items():
            final_assign[gv] = val

    answer = [[None for _ in range(C)] for _ in range(R)]
    for (r, c), idx in var_index.items():
        if final_assign[idx] == 1:
            answer[r][c] = 'F'
        else:
            answer[r][c] = None

    # Final verification.
    def is_mine(rr, cc):
        if grid[rr][cc] is not None:
            return 0
        return 1 if answer[rr][cc] == 'F' else 0

    for r in range(R):
        for c in range(C):
            clue = grid[r][c]
            if clue is None:
                continue
            s = 0
            for nr, nc in nbrs(r, c):
                s += is_mine(nr, nc)
            if s != clue:
                return "No Solution"

    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

