from collections import deque

B = 'B'
W = 'W'
U = None


def solve(observation):
    data = observation['data']
    n = len(data)
    board = [row[:] for row in data]

    def inside(r, c):
        return 0 <= r < n and 0 <= c < n

    def neighbors(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < n:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < n:
            yield r, c + 1

    def opposite(v):
        return W if v == B else B

    def clone_board(bd):
        return [row[:] for row in bd]

    def unknown_count(bd):
        return sum(cell is None for row in bd for cell in row)

    def all_cells_of_color(bd, color):
        out = []
        for r in range(n):
            row = bd[r]
            for c in range(n):
                if row[c] == color:
                    out.append((r, c))
        return out

    def connected_components_of_allowed(bd, color):
        allowed = [[bd[r][c] != opposite(color) for c in range(n)] for r in range(n)]
        vis = [[False] * n for _ in range(n)]
        comps = []
        for r in range(n):
            for c in range(n):
                if allowed[r][c] and not vis[r][c]:
                    q = deque([(r, c)])
                    vis[r][c] = True
                    comp = []
                    has_fixed = False
                    while q:
                        x, y = q.popleft()
                        comp.append((x, y))
                        if bd[x][y] == color:
                            has_fixed = True
                        for nx, ny in neighbors(x, y):
                            if allowed[nx][ny] and not vis[nx][ny]:
                                vis[nx][ny] = True
                                q.append((nx, ny))
                    comps.append((comp, has_fixed))
        return comps

    def impossible_connectivity(bd, color):
        comps = connected_components_of_allowed(bd, color)
        fixed_comps = [comp for comp, has_fixed in comps if has_fixed]
        return len(fixed_comps) > 1

    def final_connected(bd, color):
        cells = all_cells_of_color(bd, color)
        if not cells:
            return False
        s = cells[0]
        seen = {s}
        q = deque([s])
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors(r, c):
                if bd[nr][nc] == color and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return len(seen) == len(cells)

    def violates_2x2(bd):
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [bd[r][c], bd[r + 1][c], bd[r][c + 1], bd[r + 1][c + 1]]
                if vals[0] is not None and vals.count(vals[0]) == 4:
                    return True
        return False

    def force_assign(bd, r, c, val, queue):
        cur = bd[r][c]
        if cur is not None:
            return cur == val
        bd[r][c] = val
        queue.append((r, c))
        return True

    def apply_2x2_rule(bd, queue):
        changed = False
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                vals = [bd[x][y] for x, y in cells]
                if vals.count(None) == 0:
                    if vals.count(B) == 4 or vals.count(W) == 4:
                        return None
                elif vals.count(None) == 1:
                    idx = vals.index(None)
                    known = [v for v in vals if v is not None]
                    if len(set(known)) == 1:
                        need = opposite(known[0])
                        x, y = cells[idx]
                        if not force_assign(bd, x, y, need, queue):
                            return None
                        changed = True
        return changed

    def apply_line_patterns(bd, queue):
        changed = False
        # Pattern A A ? => third opposite; ? A A => first opposite
        for r in range(n):
            for c in range(n - 2):
                a, b, d = bd[r][c], bd[r][c + 1], bd[r][c + 2]
                if a is not None and a == b and d is None:
                    if not force_assign(bd, r, c + 2, opposite(a), queue):
                        return None
                    changed = True
                if b is not None and b == d and a is None:
                    if not force_assign(bd, r, c, opposite(b), queue):
                        return None
                    changed = True
                if a is not None and d is not None and a == d and b is None:
                    if not force_assign(bd, r, c + 1, opposite(a), queue):
                        return None
                    changed = True
        for c in range(n):
            for r in range(n - 2):
                a, b, d = bd[r][c], bd[r + 1][c], bd[r + 2][c]
                if a is not None and a == b and d is None:
                    if not force_assign(bd, r + 2, c, opposite(a), queue):
                        return None
                    changed = True
                if b is not None and b == d and a is None:
                    if not force_assign(bd, r, c, opposite(b), queue):
                        return None
                    changed = True
                if a is not None and d is not None and a == d and b is None:
                    if not force_assign(bd, r + 1, c, opposite(a), queue):
                        return None
                    changed = True
        return changed

    def color_articulation_forbidden(bd, color):
        # If a fixed color cell is the sole bridge connecting two fixed-color groups
        # through currently available cells, then assigning opposite color there would be impossible.
        # Human-like local check: for each unknown cell, if making it opposite splits the allowed area
        # containing all fixed-color cells into >1 components, then it must be color.
        changed = False
        queue = deque()
        for r in range(n):
            for c in range(n):
                if bd[r][c] is None:
                    test = clone_board(bd)
                    test[r][c] = opposite(color)
                    if impossible_connectivity(test, color):
                        if not force_assign(bd, r, c, color, queue):
                            return None
                        changed = True
        return changed

    def dead_end_cells(bd):
        # If assigning a color would isolate that color's fixed cells into multiple impossible regions, forbid it.
        changed = False
        queue = deque()
        for r in range(n):
            for c in range(n):
                if bd[r][c] is None:
                    bad_b = False
                    bad_w = False
                    test = clone_board(bd)
                    test[r][c] = B
                    if violates_2x2(test) or impossible_connectivity(test, B) or impossible_connectivity(test, W):
                        bad_b = True
                    test = clone_board(bd)
                    test[r][c] = W
                    if violates_2x2(test) or impossible_connectivity(test, B) or impossible_connectivity(test, W):
                        bad_w = True
                    if bad_b and bad_w:
                        return None
                    if bad_b:
                        if not force_assign(bd, r, c, W, queue):
                            return None
                        changed = True
                    elif bad_w:
                        if not force_assign(bd, r, c, B, queue):
                            return None
                        changed = True
        return changed

    def propagate(bd):
        queue = deque((r, c) for r in range(n) for c in range(n) if bd[r][c] is not None)
        while True:
            any_change = False

            res = apply_2x2_rule(bd, queue)
            if res is None:
                return None
            any_change |= res

            res = apply_line_patterns(bd, queue)
            if res is None:
                return None
            any_change |= res

            res = dead_end_cells(bd)
            if res is None:
                return None
            any_change |= res

            res = color_articulation_forbidden(bd, B)
            if res is None:
                return None
            any_change |= res

            res = color_articulation_forbidden(bd, W)
            if res is None:
                return None
            any_change |= res

            if violates_2x2(bd):
                return None
            if impossible_connectivity(bd, B) or impossible_connectivity(bd, W):
                return None

            if not any_change:
                break
        return bd

    def candidate_score(bd, r, c, val):
        score = 0
        # Prefer assignments constrained by neighbors and 2x2 participation
        for nr, nc in neighbors(r, c):
            if bd[nr][nc] == val:
                score += 3
            elif bd[nr][nc] == opposite(val):
                score += 1
        for rr in (r - 1, r):
            for cc in (c - 1, c):
                if 0 <= rr < n - 1 and 0 <= cc < n - 1:
                    vals = []
                    unk = 0
                    same = 0
                    for x, y in ((rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)):
                        v = val if (x, y) == (r, c) else bd[x][y]
                        vals.append(v)
                    if vals.count(val) == 3 and vals.count(None) == 1:
                        score += 4
                    if vals.count(opposite(val)) == 3:
                        score -= 2
        return score

    def choose_cell(bd):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if bd[r][c] is None:
                    legal = []
                    for val in (B, W):
                        test = clone_board(bd)
                        test[r][c] = val
                        if not violates_2x2(test) and not impossible_connectivity(test, B) and not impossible_connectivity(test, W):
                            legal.append(val)
                    if not legal:
                        return (r, c, [])
                    key = (len(legal), -max(candidate_score(bd, r, c, v) for v in legal))
                    if best is None or key < best_key:
                        ordered = sorted(legal, key=lambda v: -candidate_score(bd, r, c, v))
                        best = (r, c, ordered)
                        best_key = key
                        if len(legal) == 1:
                            return best
        return best

    def search(bd):
        bd = propagate(clone_board(bd))
        if bd is None:
            return None
        if unknown_count(bd) == 0:
            if final_connected(bd, B) and final_connected(bd, W) and not violates_2x2(bd):
                return bd
            return None
        choice = choose_cell(bd)
        if choice is None:
            return None
        r, c, vals = choice
        if not vals:
            return None
        for val in vals:
            nxt = clone_board(bd)
            nxt[r][c] = val
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    result = search(board)
    if result is None:
        return "No Solution"
    return str(result)


