# Generalized solver for consecutive-adjacency Latin square puzzles.
# It uses strong propagation based on:
# - Latin constraints (row/column uniqueness)
# - adjacency/non-adjacency consecutive constraints
# - hidden singles in rows/columns
# - support-based arc consistency on neighboring cells
# and only then branches on the most constrained cell.

def solve(observation):
    data = observation['data']
    adjacent = observation['adjacent']
    n = len(data)
    all_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_to_val(b):
        return b.bit_length()

    # Build adjacency requirement map for orthogonally adjacent pairs.
    req = {}
    adj_set = set((float(r), float(c)) for r, c in adjacent)

    for r in range(n):
        for c in range(n - 1):
            req[((r, c), (r, c + 1))] = ((float(r), c + 0.5) in adj_set)
            req[((r, c + 1), (r, c))] = req[((r, c), (r, c + 1))]
    for r in range(n - 1):
        for c in range(n):
            req[((r, c), (r + 1, c))] = ((r + 0.5, float(c)) in adj_set)
            req[((r + 1, c), (r, c))] = req[((r, c), (r + 1, c))]

    neighbors = {}
    for r in range(n):
        for c in range(n):
            lst = []
            if r > 0:
                lst.append((r - 1, c))
            if r + 1 < n:
                lst.append((r + 1, c))
            if c > 0:
                lst.append((r, c - 1))
            if c + 1 < n:
                lst.append((r, c + 1))
            neighbors[(r, c)] = lst

    # Precompute support masks for consecutive / non-consecutive relations.
    cons_support = [0] * (n + 1)
    noncons_support = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < n:
            m |= bit(v + 1)
        cons_support[v] = m
        noncons_support[v] = all_mask & ~m

    # Domains
    dom = [[all_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                dom[r][c] = bit(data[r][c])

    def is_single(mask):
        return mask and (mask & (mask - 1) == 0)

    def board_copy(board):
        return [row[:] for row in board]

    def assign(board, r, c, newmask):
        old = board[r][c]
        nm = old & newmask
        if nm == 0:
            return False, False
        if nm == old:
            return True, False
        board[r][c] = nm
        return True, True

    def support_filter(mask_a, mask_b, must_consecutive):
        out = 0
        for b in bits(mask_a):
            v = bit_to_val(b)
            supp = cons_support[v] if must_consecutive else noncons_support[v]
            if supp & mask_b:
                out |= b
        return out

    def propagate(board):
        changed = True
        while changed:
            changed = False

            # 1) Row/column singleton elimination and contradiction checks.
            for r in range(n):
                singles = 0
                for c in range(n):
                    m = board[r][c]
                    if m == 0:
                        return False
                    if is_single(m):
                        if singles & m:
                            return False
                        singles |= m
                for c in range(n):
                    if not is_single(board[r][c]):
                        ok, ch = assign(board, r, c, all_mask & ~singles)
                        if not ok:
                            return False
                        changed |= ch

            for c in range(n):
                singles = 0
                for r in range(n):
                    m = board[r][c]
                    if m == 0:
                        return False
                    if is_single(m):
                        if singles & m:
                            return False
                        singles |= m
                for r in range(n):
                    if not is_single(board[r][c]):
                        ok, ch = assign(board, r, c, all_mask & ~singles)
                        if not ok:
                            return False
                        changed |= ch

            # 2) Hidden singles in rows.
            for r in range(n):
                pos = [0] * (n + 1)
                cnt = [0] * (n + 1)
                for c in range(n):
                    m = board[r][c]
                    for b in bits(m):
                        v = bit_to_val(b)
                        cnt[v] += 1
                        pos[v] = c
                for v in range(1, n + 1):
                    if cnt[v] == 0:
                        return False
                    if cnt[v] == 1:
                        ok, ch = assign(board, r, pos[v], bit(v))
                        if not ok:
                            return False
                        changed |= ch

            # 3) Hidden singles in columns.
            for c in range(n):
                pos = [0] * (n + 1)
                cnt = [0] * (n + 1)
                for r in range(n):
                    m = board[r][c]
                    for b in bits(m):
                        v = bit_to_val(b)
                        cnt[v] += 1
                        pos[v] = r
                for v in range(1, n + 1):
                    if cnt[v] == 0:
                        return False
                    if cnt[v] == 1:
                        ok, ch = assign(board, pos[v], c, bit(v))
                        if not ok:
                            return False
                        changed |= ch

            # 4) Arc consistency for consecutive / non-consecutive adjacent pairs.
            for r in range(n):
                for c in range(n):
                    m1 = board[r][c]
                    for nr, nc in neighbors[(r, c)]:
                        if (r, c) > (nr, nc):
                            continue
                        must = req[((r, c), (nr, nc))]
                        m2 = board[nr][nc]
                        f1 = support_filter(m1, m2, must)
                        if f1 == 0:
                            return False
                        if f1 != m1:
                            board[r][c] = f1
                            m1 = f1
                            changed = True
                        f2 = support_filter(m2, m1, must)
                        if f2 == 0:
                            return False
                        if f2 != m2:
                            board[nr][nc] = f2
                            changed = True

            # 5) Stronger singleton-induced propagation:
            # if one side is fixed, neighbor relation can cut immediately;
            # row/col uniqueness for missing values already handled above.

            # 6) Basic contradiction: if all unsolved cells in row/col cannot realize each value.
            # Covered by hidden-single counts == 0, but keep final zero check.
            for r in range(n):
                for c in range(n):
                    if board[r][c] == 0:
                        return False

        return True

    def solved(board):
        return all(is_single(board[r][c]) for r in range(n) for c in range(n))

    def choose_cell(board):
        best = None
        best_key = None
        for r in range(n):
            row_used = 0
            for c in range(n):
                if is_single(board[r][c]):
                    row_used |= board[r][c]
            for c in range(n):
                m = board[r][c]
                if is_single(m):
                    continue
                col_used = 0
                for rr in range(n):
                    if is_single(board[rr][c]):
                        col_used |= board[rr][c]
                degree = len(neighbors[(r, c)])
                # Smaller domain first; then more constrained by used values / degree.
                key = (m.bit_count(), -((row_used | col_used).bit_count()), -degree, r, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def order_values(board, r, c):
        m = board[r][c]
        scored = []
        for b in bits(m):
            v = bit_to_val(b)
            score = 0
            for nr, nc in neighbors[(r, c)]:
                nm = board[nr][nc]
                must = req[((r, c), (nr, nc))]
                supp = cons_support[v] if must else noncons_support[v]
                score += (nm & supp).bit_count()
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def search(board):
        if not propagate(board):
            return None
        if solved(board):
            return board

        r, c = choose_cell(board)
        vals = order_values(board, r, c)

        for v in vals:
            nb = board_copy(board)
            nb[r][c] = bit(v)
            ans = search(nb)
            if ans is not None:
                return ans
        return None

    result = search(dom)
    if result is None:
        return "No Solution"

    grid = [[bit_to_val(result[r][c]) for c in range(n)] for r in range(n)]
    return str(grid)


