from collections import deque
import ast

# General Hashiwokakero solver using strong propagation + bounded search.
# Output format: dictionary {((r1, c1), (r2, c2)): count}

def solve(observation):
    data = observation["data"]
    n = len(data)

    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, data[r][c]))

    m = len(islands)
    if m == 0:
        return "{}"

    # Build visibility graph: nearest island in each orthogonal direction.
    edge_map = {}
    edges = []
    neighbors = [[] for _ in range(m)]

    def add_edge(a, b):
        if a > b:
            a, b = b, a
        if (a, b) in edge_map:
            return
        i = len(edges)
        (r1, c1, _), (r2, c2, _) = islands[a], islands[b]
        orient = 'H' if r1 == r2 else 'V'
        edges.append({
            "u": a,
            "v": b,
            "orient": orient,
            "span": (min(r1, r2), max(r1, r2), min(c1, c2), max(c1, c2)),
        })
        edge_map[(a, b)] = i
        neighbors[a].append(i)
        neighbors[b].append(i)

    for i, (r, c, _) in enumerate(islands):
        # right
        cc = c + 1
        while cc < n:
            if data[r][cc] is not None:
                add_edge(i, pos_to_idx[(r, cc)])
                break
            cc += 1
        # down
        rr = r + 1
        while rr < n:
            if data[rr][c] is not None:
                add_edge(i, pos_to_idx[(rr, c)])
                break
            rr += 1

    ecount = len(edges)

    # Crossing matrix.
    crosses = [[] for _ in range(ecount)]

    def edge_cross(e1, e2):
        a = edges[e1]
        b = edges[e2]
        if a["orient"] == b["orient"]:
            return False
        if a["orient"] == 'H':
            h, v = a, b
        else:
            h, v = b, a
        hr = islands[h["u"]][0]
        hc1 = islands[h["u"]][1]
        hc2 = islands[h["v"]][1]
        if hc1 > hc2:
            hc1, hc2 = hc2, hc1
        vc = islands[v["u"]][1]
        vr1 = islands[v["u"]][0]
        vr2 = islands[v["v"]][0]
        if vr1 > vr2:
            vr1, vr2 = vr2, vr1
        # strict interior crossing only; endpoints are islands and cannot be crossings
        return (vr1 < hr < vr2) and (hc1 < vc < hc2)

    for i in range(ecount):
        for j in range(i + 1, ecount):
            if edge_cross(i, j):
                crosses[i].append(j)
                crosses[j].append(i)

    req = [x[2] for x in islands]

    # State arrays.
    lo = [0] * ecount
    hi = [2] * ecount

    # Immediate upper bound from island degrees.
    for ei, e in enumerate(edges):
        hi[ei] = min(2, req[e["u"]], req[e["v"]])

    # If an island has single neighbor, that edge fixed immediately by req and cap.
    # Propagation handles this generally.

    def clone_state(lo, hi):
        return lo[:], hi[:]

    def island_bounds(lo, hi, idx):
        s_lo = 0
        s_hi = 0
        undec = []
        for ei in neighbors[idx]:
            s_lo += lo[ei]
            s_hi += hi[ei]
            if lo[ei] != hi[ei]:
                undec.append(ei)
        return s_lo, s_hi, undec

    def set_lo(ei, val, lo, hi, q):
        if val > hi[ei]:
            return False
        if val > lo[ei]:
            lo[ei] = val
            q.append(("edge", ei))
        return True

    def set_hi(ei, val, lo, hi, q):
        if val < lo[ei]:
            return False
        if val < hi[ei]:
            hi[ei] = val
            q.append(("edge", ei))
        return True

    def set_eq(ei, val, lo, hi, q):
        return set_lo(ei, val, lo, hi, q) and set_hi(ei, val, lo, hi, q)

    def connectivity_components_positive_possible(lo, hi):
        # Graph on islands using edges with hi > 0
        seen = [False] * m
        comps = []
        for s in range(m):
            if seen[s]:
                continue
            seen[s] = True
            dq = [s]
            comp = []
            while dq:
                u = dq.pop()
                comp.append(u)
                for ei in neighbors[u]:
                    if hi[ei] <= 0:
                        continue
                    e = edges[ei]
                    v = e["v"] if e["u"] == u else e["u"]
                    if not seen[v]:
                        seen[v] = True
                        dq.append(v)
            comps.append(comp)
        return comps

    def positive_fixed_components(lo):
        # Graph on islands using edges with lo > 0
        seen = [False] * m
        comps = []
        for s in range(m):
            if seen[s]:
                continue
            seen[s] = True
            dq = [s]
            comp = []
            while dq:
                u = dq.pop()
                comp.append(u)
                for ei in neighbors[u]:
                    if lo[ei] <= 0:
                        continue
                    e = edges[ei]
                    v = e["v"] if e["u"] == u else e["u"]
                    if not seen[v]:
                        seen[v] = True
                        dq.append(v)
            comps.append(comp)
        return comps

    def bridge_candidates_between_sets(comp_a_set, comp_b_set, hi):
        cand = []
        for ei, e in enumerate(edges):
            if hi[ei] <= 0:
                continue
            ua = e["u"] in comp_a_set
            va = e["v"] in comp_a_set
            ub = e["u"] in comp_b_set
            vb = e["v"] in comp_b_set
            if (ua and vb) or (va and ub):
                cand.append(ei)
        return cand

    def propagate(lo, hi):
        q = deque()

        for ei in range(ecount):
            q.append(("edge", ei))
        for i in range(m):
            q.append(("island", i))

        while q:
            typ, idx = q.popleft()

            if typ == "edge":
                ei = idx
                if lo[ei] > hi[ei]:
                    return False

                # Crossing rule: a positive bridge forbids crossing edges.
                if lo[ei] > 0:
                    for ej in crosses[ei]:
                        if not set_hi(ej, 0, lo, hi, q):
                            return False

                # If an edge is impossible, nothing else here.
                # Tighten by endpoint capacities.
                e = edges[ei]
                u, v = e["u"], e["v"]
                su_lo, su_hi, _ = island_bounds(lo, hi, u)
                sv_lo, sv_hi, _ = island_bounds(lo, hi, v)
                # Individual edge max constrained by residual endpoint capacities.
                max_u = req[u] - (su_lo - lo[ei])
                max_v = req[v] - (sv_lo - lo[ei])
                if not set_hi(ei, min(hi[ei], max_u, max_v, 2), lo, hi, q):
                    return False

            else:
                i = idx
                s_lo, s_hi, undec = island_bounds(lo, hi, i)
                need = req[i]
                if s_lo > need or s_hi < need:
                    return False

                # Classic island forcing:
                # remaining exact demand among undecided edges.
                rem = need - s_lo
                cap = s_hi - s_lo

                if rem == 0:
                    for ei in undec:
                        if not set_hi(ei, 0, lo, hi, q):
                            return False
                elif rem == cap:
                    for ei in undec:
                        if not set_lo(ei, hi[ei], lo, hi, q):
                            return False
                else:
                    # Per-edge lower/upper forcing.
                    for ei in undec:
                        other_hi = s_hi - hi[ei]
                        other_lo = s_lo - lo[ei]
                        # minimum this edge must take
                        min_needed = max(lo[ei], need - other_hi)
                        # maximum this edge may take
                        max_allowed = min(hi[ei], need - other_lo)
                        if not set_lo(ei, min_needed, lo, hi, q):
                            return False
                        if not set_hi(ei, max_allowed, lo, hi, q):
                            return False

                # If island still needs positive degree and only one/two limited ways remain,
                # above arithmetic usually covers it.

            # Global feasibility checks, but only after local changes:
            comps_possible = connectivity_components_positive_possible(lo, hi)
            if len(comps_possible) > 1:
                # If components cannot possibly connect, fail.
                # Build component id map.
                comp_id = {}
                for ci, comp in enumerate(comps_possible):
                    for u in comp:
                        comp_id[u] = ci
                inter_edges = 0
                for ei, e in enumerate(edges):
                    if hi[ei] <= 0:
                        continue
                    if comp_id[e["u"]] != comp_id[e["v"]]:
                        inter_edges += 1
                        break
                if inter_edges == 0:
                    return False

            # Forced connectivity via already-positive components:
            fixed_comps = positive_fixed_components(lo)
            if len(fixed_comps) > 1:
                # Every fixed component must still have at least one possible external connection unless final complete.
                all_exact = all(sum(lo[ei] for ei in neighbors[i]) == req[i] for i in range(m))
                if not all_exact:
                    comp_sets = [set(c) for c in fixed_comps]
                    for s in comp_sets:
                        has_external = False
                        for ei, e in enumerate(edges):
                            if hi[ei] <= 0:
                                continue
                            in_u = e["u"] in s
                            in_v = e["v"] in s
                            if in_u ^ in_v:
                                has_external = True
                                break
                        if not has_external:
                            return False
                else:
                    if len(fixed_comps) != 1:
                        return False

        return True

    def is_solved(lo, hi):
        for ei in range(ecount):
            if lo[ei] != hi[ei]:
                return False
        # exact degrees
        for i in range(m):
            if sum(lo[ei] for ei in neighbors[i]) != req[i]:
                return False
        # connected
        comps = positive_fixed_components(lo)
        return len(comps) == 1

    def choose_branch_edge(lo, hi):
        best = None
        best_key = None
        for ei in range(ecount):
            if lo[ei] == hi[ei]:
                continue
            e = edges[ei]
            u, v = e["u"], e["v"]
            su_lo, su_hi, _ = island_bounds(lo, hi, u)
            sv_lo, sv_hi, _ = island_bounds(lo, hi, v)
            rem_u = req[u] - su_lo
            rem_v = req[v] - sv_lo
            width = hi[ei] - lo[ei]
            cross_pressure = sum(1 for ej in crosses[ei] if hi[ej] > 0)
            key = (width, -(rem_u + rem_v), -cross_pressure)
            if best_key is None or key < best_key:
                best_key = key
                best = ei
        return best

    def search(lo, hi):
        if not propagate(lo, hi):
            return None
        if is_solved(lo, hi):
            return lo

        ei = choose_branch_edge(lo, hi)
        if ei is None:
            return None

        # Try human-like stronger option first: if positive is plausible, try higher values before zero
        # because bridges often drive deductions and connectivity.
        vals = list(range(hi[ei], lo[ei] - 1, -1))
        if 0 in vals and vals[0] != 0:
            vals = [v for v in vals if v != 0] + [0]

        for v in vals:
            lo2, hi2 = clone_state(lo, hi)
            q = deque()
            if not set_eq(ei, v, lo2, hi2, q):
                continue
            res = search(lo2, hi2)
            if res is not None:
                return res
        return None

    res = search(lo[:], hi[:])
    if res is None:
        return "No Solution"

    ans = {}
    for ei, cnt in enumerate(res):
        if cnt > 0:
            u = edges[ei]["u"]
            v = edges[ei]["v"]
            p1 = (islands[u][0], islands[u][1])
            p2 = (islands[v][0], islands[v][1])
            if p1 > p2:
                p1, p2 = p2, p1
            ans[(p1, p2)] = cnt

    return str(ans)


