from collections import defaultdict, deque

def solve(observation):
    region_grid = observation["region"]
    row_target = observation["row_water_counts"]
    col_target = observation["col_water_counts"]

    R = len(region_grid)
    C = len(region_grid[0]) if R else 0

    regions = defaultdict(list)
    for r in range(R):
        for c in range(C):
            regions[region_grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    region_cells_by_col = {}
    region_rows_sorted = {}
    region_prefix_cells = {}
    region_prefix_rows = {}
    region_max_height = {}

    for rid in region_ids:
        cells = regions[rid]
        by_col = defaultdict(list)
        rowset = set()
        for r, c in cells:
            by_col[c].append(r)
            rowset.add(r)
        for c in by_col:
            by_col[c].sort(reverse=True)
        rows_sorted = sorted(rowset)
        row_to_prefix = {}
        prefix_h = {}
        for h in range(0, len(rows_sorted) + 1):
            if h == 0:
                row_to_prefix[h] = []
                prefix_h[h] = set()
            else:
                water_rows = set(rows_sorted[-h:])
                prefix_h[h] = water_rows
                row_to_prefix[h] = [(r, c) for (r, c) in cells if r in water_rows]
        region_cells_by_col[rid] = by_col
        region_rows_sorted[rid] = rows_sorted
        region_prefix_cells[rid] = row_to_prefix
        region_prefix_rows[rid] = prefix_h
        region_max_height[rid] = len(rows_sorted)

    row_regions = [set() for _ in range(R)]
    col_regions = [set() for _ in range(C)]
    for rid, cells in regions.items():
        for r, c in cells:
            row_regions[r].add(rid)
            col_regions[c].add(rid)

    row_cells_in_region_height = {r: defaultdict(int) for r in range(R)}
    col_cells_in_region_height = {c: defaultdict(int) for c in range(C)}
    for rid in region_ids:
        rows_sorted = region_rows_sorted[rid]
        for h in range(0, region_max_height[rid] + 1):
            rowset = region_prefix_rows[rid][h]
            if h == 0:
                continue
            for rr in rowset:
                row_cells_in_region_height[rr][(rid, h)] = sum(1 for (r, c) in regions[rid] if r == rr and r in rowset)
            for cc, rr_list in region_cells_by_col[rid].items():
                cnt = sum(1 for rr in rr_list if rr in rowset)
                if cnt:
                    col_cells_in_region_height[cc][(rid, h)] = cnt

    row_region_count_at_height = {r: defaultdict(dict) for r in range(R)}
    col_region_count_at_height = {c: defaultdict(dict) for c in range(C)}
    for rid in region_ids:
        maxh = region_max_height[rid]
        for h in range(0, maxh + 1):
            rowset = region_prefix_rows[rid][h]
            rowcnt = defaultdict(int)
            colcnt = defaultdict(int)
            for rr, cc in regions[rid]:
                if rr in rowset:
                    rowcnt[rr] += 1
                    colcnt[cc] += 1
            for rr, v in rowcnt.items():
                row_region_count_at_height[rr][rid][h] = v
            for cc, v in colcnt.items():
                col_region_count_at_height[cc][rid][h] = v

    # Precompute per-region contributions by height.
    reg_row_contrib = {}
    reg_col_contrib = {}
    for rid in region_ids:
        maxh = region_max_height[rid]
        row_list = []
        col_list = []
        for h in range(maxh + 1):
            rv = [0] * R
            cv = [0] * C
            rowset = region_prefix_rows[rid][h]
            for r, c in regions[rid]:
                if r in rowset:
                    rv[r] += 1
                    cv[c] += 1
            row_list.append(tuple(rv))
            col_list.append(tuple(cv))
        reg_row_contrib[rid] = row_list
        reg_col_contrib[rid] = col_list

    # Candidate heights per region.
    domains = {rid: set(range(region_max_height[rid] + 1)) for rid in region_ids}

    # Fast feasibility using interval sums on rows/cols.
    def current_bounds(dom):
        row_min = [0] * R
        row_max = [0] * R
        col_min = [0] * C
        col_max = [0] * C
        for rid in region_ids:
            hs = dom[rid]
            min_h = min(hs)
            max_h = max(hs)
            rmin = reg_row_contrib[rid][min_h]
            rmax = reg_row_contrib[rid][max_h]
            cmin = reg_col_contrib[rid][min_h]
            cmax = reg_col_contrib[rid][max_h]
            for i in range(R):
                row_min[i] += rmin[i]
                row_max[i] += cmax[0] * 0 + rmax[i]
            for j in range(C):
                col_min[j] += cmin[j]
                col_max[j] += cmax[j]
        return row_min, row_max, col_min, col_max

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            row_min, row_max, col_min, col_max = current_bounds(dom)
            for r in range(R):
                if not (row_min[r] <= row_target[r] <= row_max[r]):
                    return None
            for c in range(C):
                if not (col_min[c] <= col_target[c] <= col_max[c]):
                    return None

            # Region-wise pruning using row/col necessity.
            for rid in region_ids:
                hs = dom[rid]
                if len(hs) == 1:
                    continue
                keep = set()
                others_row_min = [row_min[i] for i in range(R)]
                others_row_max = [row_max[i] for i in range(R)]
                others_col_min = [col_min[j] for j in range(C)]
                others_col_max = [col_max[j] for j in range(C)]

                rid_min_h = min(hs)
                rid_max_h = max(hs)
                rid_row_min = reg_row_contrib[rid][rid_min_h]
                rid_row_max = reg_row_contrib[rid][rid_max_h]
                rid_col_min = reg_col_contrib[rid][rid_min_h]
                rid_col_max = reg_col_contrib[rid][rid_max_h]

                for i in range(R):
                    others_row_min[i] -= rid_row_min[i]
                    others_row_max[i] -= rid_row_max[i]
                for j in range(C):
                    others_col_min[j] -= rid_col_min[j]
                    others_col_max[j] -= rid_col_max[j]

                for h in hs:
                    rv = reg_row_contrib[rid][h]
                    cv = reg_col_contrib[rid][h]
                    ok = True
                    for i in range(R):
                        total = others_row_min[i] + rv[i]
                        if total > row_target[i]:
                            ok = False
                            break
                        total2 = others_row_max[i] + rv[i]
                        if total2 < row_target[i]:
                            ok = False
                            break
                    if ok:
                        for j in range(C):
                            total = others_col_min[j] + cv[j]
                            if total > col_target[j]:
                                ok = False
                                break
                            total2 = others_col_max[j] + cv[j]
                            if total2 < col_target[j]:
                                ok = False
                                break
                    if ok:
                        keep.add(h)

                if not keep:
                    return None
                if keep != hs:
                    dom[rid] = keep
                    changed = True

            # Exact line forcing when residual freedom matches.
            row_min, row_max, col_min, col_max = current_bounds(dom)

            # For each row/col, if target equals min or max, prune candidate heights that would exceed/undershoot.
            for r in range(R):
                if row_target[r] == row_min[r]:
                    for rid in list(row_regions[r]):
                        hs = dom[rid]
                        if len(hs) == 1:
                            continue
                        min_contrib = min(reg_row_contrib[rid][h][r] for h in hs)
                        keep = {h for h in hs if reg_row_contrib[rid][h][r] == min_contrib}
                        if not keep:
                            return None
                        if keep != hs:
                            dom[rid] = keep
                            changed = True
                if row_target[r] == row_max[r]:
                    for rid in list(row_regions[r]):
                        hs = dom[rid]
                        if len(hs) == 1:
                            continue
                        max_contrib = max(reg_row_contrib[rid][h][r] for h in hs)
                        keep = {h for h in hs if reg_row_contrib[rid][h][r] == max_contrib}
                        if not keep:
                            return None
                        if keep != hs:
                            dom[rid] = keep
                            changed = True

            for c in range(C):
                if col_target[c] == col_min[c]:
                    for rid in list(col_regions[c]):
                        hs = dom[rid]
                        if len(hs) == 1:
                            continue
                        min_contrib = min(reg_col_contrib[rid][h][c] for h in hs)
                        keep = {h for h in hs if reg_col_contrib[rid][h][c] == min_contrib}
                        if not keep:
                            return None
                        if keep != hs:
                            dom[rid] = keep
                            changed = True
                if col_target[c] == col_max[c]:
                    for rid in list(col_regions[c]):
                        hs = dom[rid]
                        if len(hs) == 1:
                            continue
                        max_contrib = max(reg_col_contrib[rid][h][c] for h in hs)
                        keep = {h for h in hs if reg_col_contrib[rid][h][c] == max_contrib}
                        if not keep:
                            return None
                        if keep != hs:
                            dom[rid] = keep
                            changed = True

        return dom

    def is_solved(dom):
        return all(len(dom[rid]) == 1 for rid in region_ids)

    def build_grid(dom):
        grid = [[None for _ in range(C)] for _ in range(R)]
        for rid in region_ids:
            h = next(iter(dom[rid]))
            rowset = region_prefix_rows[rid][h]
            for r, c in regions[rid]:
                if r in rowset:
                    grid[r][c] = 'W'
        return grid

    def verify(grid):
        for r in range(R):
            if sum(1 for c in range(C) if grid[r][c] == 'W') != row_target[r]:
                return False
        for c in range(C):
            if sum(1 for r in range(R) if grid[r][c] == 'W') != col_target[c]:
                return False
        for rid in region_ids:
            cells = regions[rid]
            water_rows = {r for r, c in cells if grid[r][c] == 'W'}
            if water_rows:
                mx = max(water_rows)
                mn = min(water_rows)
                expected = {rr for rr in set(r for r, c in cells) if rr >= mn}
                if water_rows != expected:
                    return False
        return True

    def choose_region(dom):
        best = None
        best_key = None
        for rid in region_ids:
            if len(dom[rid]) <= 1:
                continue
            vals = sorted(dom[rid])
            # Prefer small domain, high impact on unsatisfied lines.
            impact = 0
            for h in vals:
                impact += sum(reg_row_contrib[rid][h]) + sum(reg_col_contrib[rid][h])
            key = (len(vals), -impact)
            if best_key is None or key < best_key:
                best_key = key
                best = rid
        return best

    def search(dom):
        dom = {rid: set(v) for rid, v in dom.items()}
        dom = propagate(dom)
        if dom is None:
            return None
        if is_solved(dom):
            grid = build_grid(dom)
            if verify(grid):
                return grid
            return None

        rid = choose_region(dom)
        vals = sorted(dom[rid])

        # Value ordering: try heights whose row/col totals best fit residual demand.
        row_min, row_max, col_min, col_max = current_bounds(dom)
        scores = []
        current_min_h = min(dom[rid])
        current_max_h = max(dom[rid])
        others_row_min = [row_min[i] - reg_row_contrib[rid][current_min_h][i] for i in range(R)]
        others_row_max = [row_max[i] - reg_row_contrib[rid][current_max_h][i] for i in range(R)]
        others_col_min = [col_min[j] - reg_col_contrib[rid][current_min_h][j] for j in range(C)]
        others_col_max = [col_max[j] - reg_col_contrib[rid][current_max_h][j] for j in range(C)]

        for h in vals:
            rv = reg_row_contrib[rid][h]
            cv = reg_col_contrib[rid][h]
            score = 0
            for i in range(R):
                center = (others_row_min[i] + others_row_max[i]) / 2.0
                score += abs((row_target[i] - center) - rv[i])
            for j in range(C):
                center = (others_col_min[j] + others_col_max[j]) / 2.0
                score += abs((col_target[j] - center) - cv[j])
            scores.append((score, h))
        for _, h in sorted(scores):
            ndom = {k: set(v) for k, v in dom.items()}
            ndom[rid] = {h}
            ans = search(ndom)
            if ans is not None:
                return ans
        return None

    ans = search(domains)
    if ans is None:
        return "No Solution"
    return str(ans)

