# Akari / Light Up solver
# - Human-like deduction first:
#   * numbered black saturation / exclusion
#   * forced illumination when a white cell has only one feasible bulb source
#   * visibility-based exclusion from placed bulbs
#   * contradiction checks using lower/upper bounds around numbered blacks
# - Search only when propagation stalls:
#   * branch on the most constrained undecided cell
#   * prefer variables that affect both illumination and numbered constraints

from copy import deepcopy

BULB = 1
NOBULB = 0
UNDECIDED = -1

def solve(observation):
    data = observation['data']
    n = len(data)

    black = {}
    whites = []
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                whites.append((r, c))
            else:
                black[(r, c)] = v

    white_set = set(whites)

    # Precompute line-of-sight segments and visibility.
    vis = {}
    segments = []

    # Row segments
    for r in range(n):
        c = 0
        while c < n:
            while c < n and (r, c) in black:
                c += 1
            start = c
            cur = []
            while c < n and (r, c) not in black:
                cur.append((r, c))
                c += 1
            if cur:
                segments.append(tuple(cur))

    # Column segments
    for c in range(n):
        r = 0
        while r < n:
            while r < n and (r, c) in black:
                r += 1
            cur = []
            while r < n and (r, c) not in black:
                cur.append((r, c))
                r += 1
            if cur:
                segments.append(tuple(cur))

    # Visibility by walking in four directions.
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for cell in whites:
        r, c = cell
        s = set()
        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            while 0 <= rr < n and 0 <= cc < n and (rr, cc) not in black:
                s.add((rr, cc))
                rr += dr
                cc += dc
        vis[cell] = tuple(sorted(s))

    # Candidate bulb sources for each white cell: any visible cell or itself.
    coverers = {}
    for w in whites:
        s = set(vis[w])
        s.add(w)
        coverers[w] = tuple(sorted(s))

    # Numbered black adjacency data.
    num_cells = []
    adj_white = {}
    white_to_nums = {w: [] for w in whites}
    for (r, c), v in black.items():
        if isinstance(v, int) and v >= 0:
            nums = []
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                if (rr, cc) in white_set:
                    nums.append((rr, cc))
                    white_to_nums[(rr, cc)].append((r, c))
            adj_white[(r, c)] = tuple(nums)
            num_cells.append((r, c))

    # Heuristic support: for each white cell, line conflicts if both bulbs.
    bulb_conflicts = {w: set(vis[w]) for w in whites}
    for w in whites:
        bulb_conflicts[w].add(w)

    # State arrays using dict for sparse/simple generalized handling.
    state = {w: UNDECIDED for w in whites}

    def serialize_answer(st):
        grid = [[None for _ in range(n)] for _ in range(n)]
        for (r, c) in whites:
            if st[(r, c)] == BULB:
                grid[r][c] = 'B'
            else:
                grid[r][c] = None
        return str(grid)

    def can_place_bulb(st, cell):
        if st[cell] == NOBULB:
            return False
        for v in vis[cell]:
            if st[v] == BULB:
                return False
        for nb in white_to_nums[cell]:
            req = black[nb]
            bulbs = 0
            for a in adj_white[nb]:
                if st[a] == BULB or a == cell:
                    bulbs += 1
            if bulbs > req:
                return False
        return True

    def cell_is_lit(st, cell):
        if st[cell] == BULB:
            return True
        for v in coverers[cell]:
            if v != cell and st[v] == BULB:
                return True
        return False

    def fixed_contradiction(st):
        # Numbered black lower/upper bounds.
        for nb in num_cells:
            req = black[nb]
            bulbs = 0
            undec = 0
            for a in adj_white[nb]:
                if st[a] == BULB:
                    bulbs += 1
                elif st[a] == UNDECIDED:
                    undec += 1
            if bulbs > req:
                return True
            if bulbs + undec < req:
                return True

        # Bulb-to-bulb line of sight.
        for w in whites:
            if st[w] == BULB:
                for v in vis[w]:
                    if st[v] == BULB:
                        return True

        # Any unlit cell with no possible covering source left.
        for w in whites:
            if cell_is_lit(st, w):
                continue
            possible = False
            for s in coverers[w]:
                if st[s] == BULB:
                    possible = True
                    break
                if st[s] == UNDECIDED and can_place_bulb(st, s):
                    possible = True
                    break
            if not possible:
                return True

        # For any white cell forced not bulb and not lit, at least one potential source must remain.
        return False

    def assign(st, cell, val, queue):
        cur = st[cell]
        if cur == val:
            return True
        if cur != UNDECIDED and cur != val:
            return False
        if val == BULB and not can_place_bulb(st, cell):
            return False
        st[cell] = val
        queue.append(cell)
        return True

    def propagate(st):
        queue = list(whites)

        while queue:
            _ = queue.pop()

            if fixed_contradiction(st):
                return False

            changed = True
            while changed:
                changed = False

                # Rule 1: visibility exclusion from bulbs.
                for w in whites:
                    if st[w] == BULB:
                        for v in vis[w]:
                            if st[v] == UNDECIDED:
                                if not assign(st, v, NOBULB, queue):
                                    return False
                                changed = True

                # Rule 2: numbered black exactness.
                for nb in num_cells:
                    req = black[nb]
                    bulbs = []
                    undec = []
                    for a in adj_white[nb]:
                        if st[a] == BULB:
                            bulbs.append(a)
                        elif st[a] == UNDECIDED:
                            undec.append(a)
                    b = len(bulbs)
                    u = len(undec)

                    if b > req or b + u < req:
                        return False
                    if b == req:
                        for a in undec:
                            if not assign(st, a, NOBULB, queue):
                                return False
                            changed = True
                    elif b + u == req:
                        for a in undec:
                            if not assign(st, a, BULB, queue):
                                return False
                            changed = True

                # Rule 3: if a white cell has only one feasible source of light, force it.
                for w in whites:
                    if cell_is_lit(st, w):
                        continue
                    feas = []
                    for s in coverers[w]:
                        if st[s] == BULB:
                            feas = [s]
                            break
                        if st[s] == UNDECIDED and can_place_bulb(st, s):
                            feas.append(s)
                    if not feas:
                        return False
                    if len(feas) == 1:
                        s = feas[0]
                        if st[s] != BULB:
                            if not assign(st, s, BULB, queue):
                                return False
                            changed = True

                # Rule 4: impossible bulb positions become NOBULB.
                for w in whites:
                    if st[w] == UNDECIDED and not can_place_bulb(st, w):
                        if not assign(st, w, NOBULB, queue):
                            return False
                        changed = True

                # Rule 5: for each numbered black, if an undecided adjacent cell is required by all completions.
                for nb in num_cells:
                    req = black[nb]
                    neigh = adj_white[nb]
                    bulbs = [a for a in neigh if st[a] == BULB]
                    undec = [a for a in neigh if st[a] == UNDECIDED]
                    need = req - len(bulbs)
                    if need < 0 or need > len(undec):
                        return False
                    if need == 0 or not undec:
                        continue
                    # If excluding a cell makes it impossible to reach req, that cell is forced BULB.
                    for a in undec:
                        remaining = len(undec) - 1
                        if len(bulbs) + remaining < req:
                            if not assign(st, a, BULB, queue):
                                return False
                            changed = True

            if fixed_contradiction(st):
                return False

        return True

    def solved(st):
        for w in whites:
            if st[w] == UNDECIDED:
                return False
        for w in whites:
            if not cell_is_lit(st, w):
                return False
        for nb in num_cells:
            req = black[nb]
            cnt = sum(1 for a in adj_white[nb] if st[a] == BULB)
            if cnt != req:
                return False
        return True

    def choose_branch_cell(st):
        best = None
        best_score = None
        for w in whites:
            if st[w] != UNDECIDED:
                continue

            can_b = can_place_bulb(st, w)
            can_n = True
            # NOBULB impossible if it would leave this cell unlightable.
            if not cell_is_lit(st, w):
                feasible_other = False
                for s in coverers[w]:
                    if s == w:
                        continue
                    if st[s] == BULB:
                        feasible_other = True
                        break
                    if st[s] == UNDECIDED and can_place_bulb(st, s):
                        feasible_other = True
                        break
                if not feasible_other:
                    can_n = False

            if can_b and not can_n:
                return w
            if can_n and not can_b:
                return w

            # Higher score = more constrained / influential.
            if can_b and can_n:
                illum_need = 0 if cell_is_lit(st, w) else 1
                numbered_pressure = len(white_to_nums[w])
                line_degree = len(vis[w])
                source_count = 0
                for s in coverers[w]:
                    if st[s] == UNDECIDED and can_place_bulb(st, s):
                        source_count += 1
                score = (source_count, -numbered_pressure, -line_degree, -illum_need)
                if best is None or score < best_score:
                    best = w
                    best_score = score

        return best

    def branch_order(st, cell):
        # Prefer BULB when it is strongly supported by illumination necessity / numbered constraints.
        bulb_priority = 0
        if not cell_is_lit(st, cell):
            bulb_priority += 2
        bulb_priority += len(white_to_nums[cell])

        for nb in white_to_nums[cell]:
            req = black[nb]
            bulbs = sum(1 for a in adj_white[nb] if st[a] == BULB)
            undec = sum(1 for a in adj_white[nb] if st[a] == UNDECIDED)
            if bulbs + undec == req:
                bulb_priority += 3
            if bulbs == req:
                bulb_priority -= 4

        if can_place_bulb(st, cell) and bulb_priority >= 0:
            return (BULB, NOBULB)
        return (NOBULB, BULB)

    def dfs(st):
        if not propagate(st):
            return None
        if solved(st):
            return st

        cell = choose_branch_cell(st)
        if cell is None:
            return None

        for val in branch_order(st, cell):
            if val == BULB and not can_place_bulb(st, cell):
                continue
            nxt = st.copy()
            q = []
            if not assign(nxt, cell, val, q):
                continue
            res = dfs(nxt)
            if res is not None:
                return res
        return None

    result = dfs(state)
    if result is None:
        return "No Solution"
    return serialize_answer(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))

