# Consecutive sudoku / Latin-square-with-adjacency solver.
# The code is generalized for NxN grids with optional givens and consecutive-dot constraints.
# It uses bitset domains, strong propagation, hidden singles, and only then a tightly pruned search.

ALL_CACHE = {}

def bit_count(x):
    return x.bit_count()

def lowbit(x):
    return x & -x

def bits_iter(mask):
    while mask:
        b = mask & -mask
        yield b
        mask ^= b

def bit_to_val(bit):
    return bit.bit_length()

def mask_to_vals(mask):
    return [bit_to_val(b) for b in bits_iter(mask)]

def make_all_mask(n):
    if n not in ALL_CACHE:
        ALL_CACHE[n] = (1 << n) - 1
    return ALL_CACHE[n]

def consecutive_support_masks(n):
    # For each value bit v, precompute neighbor-values-that-are-consecutive mask.
    all_mask = make_all_mask(n)
    sup = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= 1 << (v - 2)
        if v < n:
            m |= 1 << v
        sup[v] = m
    # For arbitrary domain mask, union of supports can be computed quickly by iteration.
    return sup, all_mask

def parse_observation(observation):
    data = observation['data']
    n = len(data)
    adj_set = set()
    for x, y in observation['adjacent']:
        adj_set.add((x, y))
    return n, data, adj_set

def build_structure(n, adj_set):
    idx = lambda r, c: r * n + c
    cells = [(r, c) for r in range(n) for c in range(n)]

    row_cells = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c) for r in range(n)] for c in range(n)]

    neighbors = [[] for _ in range(n * n)]     # Latin all-different neighbors
    consec_edges = [[] for _ in range(n * n)]  # edges requiring consecutive
    nonconsec_edges = [[] for _ in range(n * n)]  # orthogonal adjacency without dot

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            seen = set()
            for j in row_cells[r]:
                if j != i and j not in seen:
                    neighbors[i].append(j)
                    seen.add(j)
            for j in col_cells[c]:
                if j != i and j not in seen:
                    neighbors[i].append(j)
                    seen.add(j)

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if c + 1 < n:
                j = idx(r, c + 1)
                mid = (float(r), c + 0.5)
                if mid in adj_set:
                    consec_edges[i].append(j)
                    consec_edges[j].append(i)
                else:
                    nonconsec_edges[i].append(j)
                    nonconsec_edges[j].append(i)
            if r + 1 < n:
                j = idx(r + 1, c)
                mid = (r + 0.5, float(c))
                if mid in adj_set:
                    consec_edges[i].append(j)
                    consec_edges[j].append(i)
                else:
                    nonconsec_edges[i].append(j)
                    nonconsec_edges[j].append(i)

    units = row_cells + col_cells
    cell_units = [[] for _ in range(n * n)]
    for uix, unit in enumerate(units):
        for i in unit:
            cell_units[i].append(uix)

    return {
        'cells': cells,
        'row_cells': row_cells,
        'col_cells': col_cells,
        'neighbors': neighbors,
        'consec_edges': consec_edges,
        'nonconsec_edges': nonconsec_edges,
        'units': units,
        'cell_units': cell_units,
    }

def support_from_domain(domain_mask, support_table):
    m = 0
    for b in bits_iter(domain_mask):
        m |= support_table[bit_to_val(b)]
    return m

def remove_value(domains, i, bit, queue):
    old = domains[i]
    if old & bit == 0:
        return True
    new = old & ~bit
    if new == 0:
        return False
    if new != old:
        domains[i] = new
        queue.append(i)
    return True

def assign_value(domains, i, bit, queue):
    old = domains[i]
    if old == bit:
        return True
    if old & bit == 0:
        return False
    domains[i] = bit
    queue.append(i)
    return True

def propagate(domains, structure, n, support_table):
    all_mask = make_all_mask(n)
    neighbors = structure['neighbors']
    consec_edges = structure['consec_edges']
    nonconsec_edges = structure['nonconsec_edges']
    units = structure['units']

    queue = [i for i in range(n * n) if bit_count(domains[i]) == 1]

    # Initial broad filtering from all cells through adjacency constraints.
    # This catches givens and also allows domain-domain pruning before search.
    # We simply process all cells once as changed.
    in_queue = [False] * (n * n)
    for i in range(n * n):
        if not in_queue[i]:
            queue.append(i)
            in_queue[i] = True

    while queue:
        i = queue.pop()
        in_queue[i] = False
        di = domains[i]
        if di == 0:
            return False

        # Latin all-different: a solved value removes itself from row/column peers.
        if bit_count(di) == 1:
            for j in neighbors[i]:
                if not remove_value(domains, j, di, queue):
                    return False
                if not in_queue[j]:
                    in_queue[j] = True

        # Consecutive edges: both directions arc consistency.
        si = support_from_domain(di, support_table)
        for j in consec_edges[i]:
            dj = domains[j]
            ndj = dj & si
            if ndj == 0:
                return False
            if ndj != dj:
                domains[j] = ndj
                if not in_queue[j]:
                    queue.append(j)
                    in_queue[j] = True

        # Non-consecutive edges:
        # If one side is fixed to v, the other cannot be v-1 or v+1.
        if bit_count(di) == 1:
            v = bit_to_val(di)
            bad = support_table[v]
            for j in nonconsec_edges[i]:
                dj = domains[j]
                ndj = dj & ~bad
                if ndj == 0:
                    return False
                if ndj != dj:
                    domains[j] = ndj
                    if not in_queue[j]:
                        queue.append(j)
                        in_queue[j] = True

        # If the other side is fixed, current domain must also respect it.
        for j in nonconsec_edges[i]:
            dj = domains[j]
            if bit_count(dj) == 1:
                vj = bit_to_val(dj)
                bad = support_table[vj]
                ndi = domains[i] & ~bad
                if ndi == 0:
                    return False
                if ndi != domains[i]:
                    domains[i] = ndi
                    if not in_queue[i]:
                        queue.append(i)
                        in_queue[i] = True
                    di = ndi

    # Repeated hidden singles and stronger line reasoning until stable.
    changed = True
    while changed:
        changed = False

        # Hidden singles in each row/column.
        for unit in units:
            present = 0
            for i in unit:
                present |= domains[i]
            if present != all_mask:
                return False
            for val in range(1, n + 1):
                bit = 1 << (val - 1)
                places = []
                for i in unit:
                    if domains[i] & bit:
                        places.append(i)
                if not places:
                    return False
                if len(places) == 1:
                    if not assign_value(domains, places[0], bit, []):
                        return False

        # Naked subsets on rows/cols, limited to small subsets for efficiency.
        for unit in units:
            buckets = {}
            for i in unit:
                m = domains[i]
                bc = bit_count(m)
                if 2 <= bc <= 3:
                    buckets.setdefault(m, []).append(i)
            for m, cells in buckets.items():
                k = bit_count(m)
                if len(cells) == k:
                    for i in unit:
                        if i not in cells:
                            old = domains[i]
                            new = old & ~m
                            if new == 0:
                                return False
                            if new != old:
                                domains[i] = new
                                changed = True

        # Re-run adjacency consistency globally after subset/hidden-single deductions.
        q = list(range(n * n))
        inq = [True] * (n * n)
        while q:
            i = q.pop()
            inq[i] = False
            di = domains[i]
            if di == 0:
                return False

            if bit_count(di) == 1:
                for j in neighbors[i]:
                    if domains[j] & di:
                        nd = domains[j] & ~di
                        if nd == 0:
                            return False
                        if nd != domains[j]:
                            domains[j] = nd
                            if not inq[j]:
                                q.append(j)
                                inq[j] = True
                            changed = True

            si = support_from_domain(di, support_table)
            for j in consec_edges[i]:
                dj = domains[j]
                ndj = dj & si
                if ndj == 0:
                    return False
                if ndj != dj:
                    domains[j] = ndj
                    if not inq[j]:
                        q.append(j)
                        inq[j] = True
                    changed = True

            if bit_count(di) == 1:
                v = bit_to_val(di)
                bad = support_table[v]
                for j in nonconsec_edges[i]:
                    dj = domains[j]
                    ndj = dj & ~bad
                    if ndj == 0:
                        return False
                    if ndj != dj:
                        domains[j] = ndj
                        if not inq[j]:
                            q.append(j)
                            inq[j] = True
                        changed = True

            for j in nonconsec_edges[i]:
                dj = domains[j]
                if bit_count(dj) == 1:
                    bad = support_table[bit_to_val(dj)]
                    ndi = domains[i] & ~bad
                    if ndi == 0:
                        return False
                    if ndi != domains[i]:
                        domains[i] = ndi
                        if not inq[i]:
                            q.append(i)
                            inq[i] = True
                        changed = True

        # Detect duplicate solved values in units.
        for unit in units:
            seen = 0
            for i in unit:
                d = domains[i]
                if bit_count(d) == 1:
                    if seen & d:
                        return False
                    seen |= d

    return True

def choose_branch_cell(domains, structure, n):
    # Human-like: branch on the most constrained unsolved cell,
    # tie-break by strongest interaction count.
    consec_edges = structure['consec_edges']
    nonconsec_edges = structure['nonconsec_edges']
    best = None
    best_key = None
    for i, d in enumerate(domains):
        bc = bit_count(d)
        if bc <= 1:
            continue
        degree = len(consec_edges[i]) * 2 + len(nonconsec_edges[i])
        key = (bc, -degree)
        if best_key is None or key < best_key:
            best_key = key
            best = i
    return best

def order_values(i, domains, structure, n, support_table):
    # Least-constraining value ordering.
    d = domains[i]
    vals = []
    for b in bits_iter(d):
        score = 0
        v = bit_to_val(b)
        sup = support_table[v]
        for j in structure['consec_edges'][i]:
            score += bit_count(domains[j] & sup)
        for j in structure['nonconsec_edges'][i]:
            score += bit_count(domains[j] & ~sup)
        vals.append((score, b))
    vals.sort(reverse=True)
    return [b for _, b in vals]

def solved(domains):
    return all(bit_count(d) == 1 for d in domains)

def search(domains, structure, n, support_table):
    if not propagate(domains, structure, n, support_table):
        return None
    if solved(domains):
        return domains

    i = choose_branch_cell(domains, structure, n)
    if i is None:
        return domains

    for b in order_values(i, domains, structure, n, support_table):
        new_domains = domains[:]
        if new_domains[i] & b == 0:
            continue
        new_domains[i] = b
        res = search(new_domains, structure, n, support_table)
        if res is not None:
            return res
    return None

def domains_from_observation(observation, n):
    all_mask = make_all_mask(n)
    data = observation['data']
    domains = [all_mask] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return None
                domains[r * n + c] = 1 << (v - 1)
    return domains

def format_solution(domains, n):
    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(bit_to_val(domains[r * n + c]))
        grid.append(row)
    return str(grid)

def solve(observation):
    n, data, adj_set = parse_observation(observation)
    structure = build_structure(n, adj_set)
    support_table, _ = consecutive_support_masks(n)
    domains = domains_from_observation(observation, n)
    if domains is None:
        return "No Solution"
    result = search(domains, structure, n, support_table)
    if result is None:
        return "No Solution"
    return format_solution(result, n)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 1], [0, 0, 0, 2, 1], [3, 0, 2, 2, 1], [3, 0, 2, 2, 2], [2, 2, 2, 2, 2]], 'row_stitch_counts': [2, 3, 3, 3, 3], 'col_stitch_counts': [4, 3, 2, 2, 3]}

from collections import defaultdict, deque

# Generalized solver for the stitch puzzle described in the prompt.
# Model:
# - We have an N x N cell grid and an N x N hole grid.
# - For every orthogonally adjacent pair of cells in different regions, exactly one of the
#   two "side" stitch positions must be chosen.
# - A stitch is an edge between orthogonally adjacent holes.
# - No hole may be used by more than one stitch.
# - Row/column clues count used holes in each hole-row / hole-column.


def solve(observation):
    region = observation["region"]
    row_target = observation["row_stitch_counts"]
    col_target = observation["col_stitch_counts"]
    n = len(region)

    # Enumerate all possible stitch edges on the N x N hole lattice.
    # Horizontal edge: ((r,c),(r,c+1)) with 0<=r<n, 0<=c<n-1
    # Vertical edge:   ((r,c),(r+1,c)) with 0<=r<n-1, 0<=c<n
    edges = []
    edge_index = {}
    edge_holes = []
    hole_to_edges = defaultdict(list)

    def add_edge(a, b):
        idx = len(edges)
        edges.append((a, b))
        edge_index[(a, b)] = idx
        edge_index[(b, a)] = idx
        edge_holes.append((a, b))
        hole_to_edges[a].append(idx)
        hole_to_edges[b].append(idx)

    for r in range(n):
        for c in range(n - 1):
            add_edge((r, c), (r, c + 1))
    for r in range(n - 1):
        for c in range(n):
            add_edge((r, c), (r + 1, c))

    # Boundaries between different regions induce binary choices.
    # For a vertical cell boundary between (r,c) and (r,c+1), the two possible stitches are:
    # left side vertical edge:  ((r,c+1),(r+1,c+1))
    # right side vertical edge: ((r,c),(r+1,c))
    # More invariantly, they are the two vertical edges with endpoints on the two rows spanning the cells.
    #
    # For a horizontal cell boundary between (r,c) and (r+1,c), the two possible stitches are:
    # upper horizontal edge: ((r+1,c),(r+1,c+1))
    # lower horizontal edge: ((r,c),(r,c+1))
    #
    # Geometrically these are the two stitches that can cross / connect that boundary.
    constraints = []  # each is tuple(edge_a, edge_b) meaning exactly one is true
    edge_to_constraints = defaultdict(list)

    # Vertical neighboring cells
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                e1 = edge_index[((r, c), (r + 1, c))] if r < n - 1 else None
                e2 = edge_index[((r, c + 1), (r + 1, c + 1))] if r < n - 1 else None
                # The image/prompt uses N x N holes, so only boundaries fully spanned by existing holes matter.
                # For a cell-row r, the side stitches are vertical edges between hole-rows r and r+1.
                if e1 is None or e2 is None:
                    return "No Solution"
                ci = len(constraints)
                constraints.append((e1, e2))
                edge_to_constraints[e1].append(ci)
                edge_to_constraints[e2].append(ci)

    # Horizontal neighboring cells
    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                e1 = edge_index[((r, c), (r, c + 1))] if c < n - 1 else None
                e2 = edge_index[((r + 1, c), (r + 1, c + 1))] if c < n - 1 else None
                if e1 is None or e2 is None:
                    return "No Solution"
                ci = len(constraints)
                constraints.append((e1, e2))
                edge_to_constraints[e1].append(ci)
                edge_to_constraints[e2].append(ci)

    m = len(edges)
    holes = [(r, c) for r in range(n) for c in range(n)]
    hole_index = {h: i for i, h in enumerate(holes)}
    hcount = len(holes)

    # Row/column incidence for holes
    hole_row = [h[0] for h in holes]
    hole_col = [h[1] for h in holes]

    # State:
    # edge_state[e] in {-1,0,1} unknown/false/true
    # constraint true count and unknown count tracked incrementally
    # hole_used[i] in {-1,0,1} unknown logically derived from incident true edges, but we track:
    #   true if an incident edge is true; false when all incident edges false.
    # row/col used counts and undecided potential counts.
    incident_unknown = [len(hole_to_edges[h]) for h in holes]
    incident_true = [0] * hcount

    edge_state = [-1] * m

    con_true = [0] * len(constraints)
    con_unknown = [2] * len(constraints)

    # For row/col hole counting
    row_used = [0] * n
    col_used = [0] * n
    row_unknown = [0] * n
    col_unknown = [0] * n
    hole_state = [-1] * hcount  # -1 unknown, 0 unused, 1 used
    for i, h in enumerate(holes):
        row_unknown[hole_row[i]] += 1
        col_unknown[hole_col[i]] += 1

    assign_stack = []

    def set_hole_state(hi, val):
        cur = hole_state[hi]
        if cur == val:
            return True
        if cur != -1:
            return False
        hole_state[hi] = val
        r = hole_row[hi]
        c = hole_col[hi]
        row_unknown[r] -= 1
        col_unknown[c] -= 1
        if val == 1:
            row_used[r] += 1
            col_used[c] += 1
        assign_stack.append(("hole", hi))
        return check_rowcol_bounds_single(r, c)

    def check_rowcol_bounds_single(r, c):
        if row_used[r] > row_target[r]:
            return False
        if row_used[r] + row_unknown[r] < row_target[r]:
            return False
        if col_used[c] > col_target[c]:
            return False
        if col_used[c] + col_unknown[c] < col_target[c]:
            return False
        return True

    def force_hole_from_incident(hi):
        if incident_true[hi] > 1:
            return False
        if incident_true[hi] == 1:
            return set_hole_state(hi, 1)
        if incident_unknown[hi] == 0:
            return set_hole_state(hi, 0)
        return True

    def set_edge(e, val):
        cur = edge_state[e]
        if cur == val:
            return True
        if cur != -1:
            return False
        edge_state[e] = val
        assign_stack.append(("edge", e))

        a, b = edge_holes[e]
        ai = hole_index[a]
        bi = hole_index[b]

        # update hole incident counts
        incident_unknown[ai] -= 1
        incident_unknown[bi] -= 1
        if val == 1:
            incident_true[ai] += 1
            incident_true[bi] += 1

        # update constraints
        for ci in edge_to_constraints[e]:
            con_unknown[ci] -= 1
            if val == 1:
                con_true[ci] += 1

        # local checks
        if not force_hole_from_incident(ai):
            return False
        if not force_hole_from_incident(bi):
            return False
        for ci in edge_to_constraints[e]:
            t = con_true[ci]
            u = con_unknown[ci]
            if t > 1:
                return False
            if t + u < 1:
                return False
        return True

    def undo(to_size):
        while len(assign_stack) > to_size:
            typ, idx = assign_stack.pop()
            if typ == "hole":
                hi = idx
                val = hole_state[hi]
                r = hole_row[hi]
                c = hole_col[hi]
                if val == 1:
                    row_used[r] -= 1
                    col_used[c] -= 1
                row_unknown[r] += 1
                col_unknown[c] += 1
                hole_state[hi] = -1
            else:
                e = idx
                val = edge_state[e]
                a, b = edge_holes[e]
                ai = hole_index[a]
                bi = hole_index[b]
                for ci in edge_to_constraints[e]:
                    if val == 1:
                        con_true[ci] -= 1
                    con_unknown[ci] += 1
                if val == 1:
                    incident_true[ai] -= 1
                    incident_true[bi] -= 1
                incident_unknown[ai] += 1
                incident_unknown[bi] += 1
                edge_state[e] = -1

    def propagate():
        changed = True
        while changed:
            changed = False

            # Constraint propagation: exactly one true among each pair.
            for ci, (e1, e2) in enumerate(constraints):
                t = con_true[ci]
                u = con_unknown[ci]
                if t > 1 or t + u < 1:
                    return False
                if t == 1:
                    if edge_state[e1] == -1:
                        if not set_edge(e1, 0):
                            return False
                        changed = True
                    if edge_state[e2] == -1:
                        if not set_edge(e2, 0):
                            return False
                        changed = True
                elif u == 1:
                    if edge_state[e1] == -1:
                        if not set_edge(e1, 1):
                            return False
                        changed = True
                    if edge_state[e2] == -1:
                        if not set_edge(e2, 1):
                            return False
                        changed = True

            # Hole degree propagation and no-sharing rule.
            for hi, h in enumerate(holes):
                if incident_true[hi] > 1:
                    return False
                if hole_state[hi] == 1:
                    # all remaining incident unknown edges must be false
                    if incident_true[hi] != 1:
                        return False
                    for e in hole_to_edges[h]:
                        if edge_state[e] == -1:
                            if not set_edge(e, 0):
                                return False
                            changed = True
                elif hole_state[hi] == 0:
                    # no incident true/unknown can remain true
                    if incident_true[hi] != 0:
                        return False
                    for e in hole_to_edges[h]:
                        if edge_state[e] == -1:
                            if not set_edge(e, 0):
                                return False
                            changed = True
                else:
                    # If one true exists, hole is used.
                    if incident_true[hi] == 1:
                        if not set_hole_state(hi, 1):
                            return False
                        changed = True
                    elif incident_unknown[hi] == 0:
                        if not set_hole_state(hi, 0):
                            return False
                        changed = True
                    elif incident_true[hi] == 0 and incident_unknown[hi] == 1:
                        # If row/col requires this hole status, can infer by clues later.
                        pass

            # Row/column clue propagation on holes.
            for r in range(n):
                if row_used[r] > row_target[r] or row_used[r] + row_unknown[r] < row_target[r]:
                    return False
                if row_used[r] == row_target[r]:
                    for c in range(n):
                        hi = hole_index[(r, c)]
                        if hole_state[hi] == -1:
                            if not set_hole_state(hi, 0):
                                return False
                            changed = True
                elif row_used[r] + row_unknown[r] == row_target[r]:
                    for c in range(n):
                        hi = hole_index[(r, c)]
                        if hole_state[hi] == -1:
                            if not set_hole_state(hi, 1):
                                return False
                            changed = True

            for c in range(n):
                if col_used[c] > col_target[c] or col_used[c] + col_unknown[c] < col_target[c]:
                    return False
                if col_used[c] == col_target[c]:
                    for r in range(n):
                        hi = hole_index[(r, c)]
                        if hole_state[hi] == -1:
                            if not set_hole_state(hi, 0):
                                return False
                            changed = True
                elif col_used[c] + col_unknown[c] == col_target[c]:
                    for r in range(n):
                        hi = hole_index[(r, c)]
                        if hole_state[hi] == -1:
                            if not set_hole_state(hi, 1):
                                return False
                            changed = True

        return True

    def complete():
        if any(edge_state[e] == -1 for e in range(m)):
            return False
        if any(hole_state[hi] == -1 for hi in range(hcount)):
            return False
        if any(con_true[ci] != 1 for ci in range(len(constraints))):
            return False
        if any(row_used[r] != row_target[r] for r in range(n)):
            return False
        if any(col_used[c] != col_target[c] for c in range(n)):
            return False
        return True

    def choose_branch():
        # Most constrained unresolved exact-one constraint first.
        best = None
        best_score = None
        for ci, (e1, e2) in enumerate(constraints):
            if con_true[ci] == 0 and con_unknown[ci] == 2:
                # score by endpoint flexibility; smaller is better
                holes_set = list(edge_holes[e1] + edge_holes[e2])
                score = 0
                for h in holes_set:
                    hi = hole_index[h]
                    score += incident_unknown[hi]
                if best is None or score < best_score:
                    best = ("constraint", ci)
                    best_score = score
        if best is not None:
            return best

        # Next unresolved hole with strong row/col pressure.
        for hi in range(hcount):
            if hole_state[hi] == -1:
                r = hole_row[hi]
                c = hole_col[hi]
                need_row = row_target[r] - row_used[r]
                need_col = col_target[c] - col_used[c]
                return ("hole", hi, 1 if need_row + need_col > 0 else 0)

        # Fallback unresolved edge
        for e in range(m):
            if edge_state[e] == -1:
                return ("edge", e)
        return None

    def dfs():
        if not propagate():
            return False
        if complete():
            return True

        choice = choose_branch()
        if choice is None:
            return False

        mark = len(assign_stack)

        if choice[0] == "constraint":
            _, ci = choice
            e1, e2 = constraints[ci]
            # Branch on one of the pair being true.
            for first, second in ((e1, e2), (e2, e1)):
                if edge_state[first] in (-1, 1) and edge_state[second] in (-1, 0):
                    if set_edge(first, 1) and set_edge(second, 0):
                        if dfs():
                            return True
                undo(mark)
            return False

        if choice[0] == "hole":
            _, hi, preferred = choice
            vals = [preferred, 1 - preferred]
            h = holes[hi]
            for v in vals:
                if set_hole_state(hi, v):
                    if dfs():
                        return True
                undo(mark)
            return False

        if choice[0] == "edge":
            _, e = choice
            # Prefer false first unless edge is highly forced by current counts.
            for v in (0, 1):
                if set_edge(e, v):
                    if dfs():
                        return True
                undo(mark)
            return False

        return False

    if not dfs():
        return "No Solution"

    result = []
    for e, st in enumerate(edge_state):
        if st == 1:
            a, b = edge_holes[e]
            result.append([a, b])
    return str(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[-1, None, -1, None, None, None, -1], [None, None, 2, None, None, None, None], [None, None, None, None, None, 1, 1], [None, None, None, 1, None, None, None], [1, -1, None, None, None, None, None], [None, None, None, None, -1, None, None], [0, None, None, None, 1, None, -1]]}

# Akari / Light Up solver using strong logical propagation plus constrained search.
# Board encoding in OBSERVATION:
#   None -> white cell
#   -1   -> unnumbered black cell
#   0..4 -> numbered black cell
#
# Returned answer:
#   string representation of N x N grid with 'B' for bulbs and None elsewhere

from copy import deepcopy

UNKNOWN = 0
BULB = 1
NOBULB = 2

def solve(observation):
    data = observation['data']
    n = len(data)

    white_cells = []
    black_cells = []
    numbered = []

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                white_cells.append((r, c))
            else:
                black_cells.append((r, c))
                if v >= 0:
                    numbered.append((r, c, v))

    white_set = set(white_cells)

    # Precompute line-of-sight segments and visibility relations.
    visible = {}
    for r, c in white_cells:
        arr = []
        rr = r - 1
        while rr >= 0 and data[rr][c] is None:
            arr.append((rr, c))
            rr -= 1
        rr = r + 1
        while rr < n and data[rr][c] is None:
            arr.append((rr, c))
            rr += 1
        cc = c - 1
        while cc >= 0 and data[r][cc] is None:
            arr.append((r, cc))
            cc -= 1
        cc = c + 1
        while cc < n and data[r][cc] is None:
            arr.append((r, cc))
            cc += 1
        visible[(r, c)] = tuple(arr)

    illuminates = {}
    for cell in white_cells:
        illuminates[cell] = (cell,) + visible[cell]

    lit_by = {cell: [] for cell in white_cells}
    for cell in white_cells:
        for t in illuminates[cell]:
            lit_by[t].append(cell)
    for cell in white_cells:
        lit_by[cell] = tuple(lit_by[cell])

    # Candidate bulb groups by uninterrupted row/col segments.
    row_segments = []
    row_seg_of = {}
    for r in range(n):
        c = 0
        while c < n:
            if data[r][c] is None:
                seg = []
                while c < n and data[r][c] is None:
                    seg.append((r, c))
                    c += 1
                idx = len(row_segments)
                row_segments.append(tuple(seg))
                for cell in seg:
                    row_seg_of[cell] = idx
            else:
                c += 1

    col_segments = []
    col_seg_of = {}
    for c in range(n):
        r = 0
        while r < n:
            if data[r][c] is None:
                seg = []
                while r < n and data[r][c] is None:
                    seg.append((r, c))
                    r += 1
                idx = len(col_segments)
                col_segments.append(tuple(seg))
                for cell in seg:
                    col_seg_of[cell] = idx
            else:
                r += 1

    # Adjacency of numbered black cells.
    adj_number = {}
    numbers_touching_cell = {cell: [] for cell in white_cells}
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    for r, c, v in numbered:
        neigh = []
        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n and data[rr][cc] is None:
                neigh.append((rr, cc))
                numbers_touching_cell[(rr, cc)].append((r, c))
        adj_number[(r, c)] = tuple(neigh)
    for cell in white_cells:
        numbers_touching_cell[cell] = tuple(numbers_touching_cell[cell])

    class State:
        __slots__ = (
            'status', 'lit_count', 'unlit_unknown_count',
            'num_bulbs', 'num_unknown',
            'row_bulbs', 'row_unknown',
            'col_bulbs', 'col_unknown',
            'queue', 'contradiction'
        )

        def __init__(self):
            self.status = {cell: UNKNOWN for cell in white_cells}
            self.lit_count = {cell: 0 for cell in white_cells}
            self.unlit_unknown_count = len(white_cells)
            self.num_bulbs = {}
            self.num_unknown = {}
            for r, c, v in numbered:
                neigh = adj_number[(r, c)]
                self.num_bulbs[(r, c)] = 0
                self.num_unknown[(r, c)] = len(neigh)
            self.row_bulbs = [0] * len(row_segments)
            self.row_unknown = [len(seg) for seg in row_segments]
            self.col_bulbs = [0] * len(col_segments)
            self.col_unknown = [len(seg) for seg in col_segments]
            self.queue = []
            self.contradiction = False

        def clone(self):
            s = State.__new__(State)
            s.status = self.status.copy()
            s.lit_count = self.lit_count.copy()
            s.unlit_unknown_count = self.unlit_unknown_count
            s.num_bulbs = self.num_bulbs.copy()
            s.num_unknown = self.num_unknown.copy()
            s.row_bulbs = self.row_bulbs[:]
            s.row_unknown = self.row_unknown[:]
            s.col_bulbs = self.col_bulbs[:]
            s.col_unknown = self.col_unknown[:]
            s.queue = self.queue[:]
            s.contradiction = self.contradiction
            return s

    def mark_no_bulb(st, cell):
        if st.contradiction:
            return False
        cur = st.status[cell]
        if cur == NOBULB:
            return False
        if cur == BULB:
            st.contradiction = True
            return False
        st.status[cell] = NOBULB
        st.row_unknown[row_seg_of[cell]] -= 1
        st.col_unknown[col_seg_of[cell]] -= 1
        for numcell in numbers_touching_cell[cell]:
            st.num_unknown[numcell] -= 1
        st.queue.append(('cell', cell))
        for numcell in numbers_touching_cell[cell]:
            st.queue.append(('num', numcell))
        st.queue.append(('seg_r', row_seg_of[cell]))
        st.queue.append(('seg_c', col_seg_of[cell]))
        return True

    def place_bulb(st, cell):
        if st.contradiction:
            return False
        cur = st.status[cell]
        if cur == BULB:
            return False
        if cur == NOBULB:
            st.contradiction = True
            return False

        # Cannot see another bulb in row/col.
        for other in visible[cell]:
            if st.status[other] == BULB:
                st.contradiction = True
                return False

        # Number constraints local feasibility.
        for numcell in numbers_touching_cell[cell]:
            r, c = numcell
            need = data[r][c]
            if st.num_bulbs[numcell] + 1 > need:
                st.contradiction = True
                return False

        st.status[cell] = BULB
        st.row_bulbs[row_seg_of[cell]] += 1
        st.row_unknown[row_seg_of[cell]] -= 1
        st.col_bulbs[col_seg_of[cell]] += 1
        st.col_unknown[col_seg_of[cell]] -= 1
        for numcell in numbers_touching_cell[cell]:
            st.num_bulbs[numcell] += 1
            st.num_unknown[numcell] -= 1

        for lit in illuminates[cell]:
            if st.lit_count[lit] == 0 and st.status[lit] == UNKNOWN:
                st.unlit_unknown_count -= 1
            st.lit_count[lit] += 1

        st.queue.append(('cell', cell))
        st.queue.append(('seg_r', row_seg_of[cell]))
        st.queue.append(('seg_c', col_seg_of[cell]))
        for numcell in numbers_touching_cell[cell]:
            st.queue.append(('num', numcell))

        # Any visible cell can no longer hold a bulb.
        for other in visible[cell]:
            if st.status[other] == UNKNOWN:
                mark_no_bulb(st, other)
        return True

    def force_from_number(st, numcell):
        if st.contradiction:
            return
        r, c = numcell
        need = data[r][c]
        bulbs = st.num_bulbs[numcell]
        unknown = st.num_unknown[numcell]
        if bulbs > need or bulbs + unknown < need:
            st.contradiction = True
            return
        if unknown == 0:
            return
        if bulbs == need:
            for cell in adj_number[numcell]:
                if st.status[cell] == UNKNOWN:
                    mark_no_bulb(st, cell)
        elif bulbs + unknown == need:
            for cell in adj_number[numcell]:
                if st.status[cell] == UNKNOWN:
                    place_bulb(st, cell)

    def force_from_segment(st, axis, idx):
        if st.contradiction:
            return
        bulbs = st.row_bulbs[idx] if axis == 'r' else st.col_bulbs[idx]
        unknown = st.row_unknown[idx] if axis == 'r' else st.col_unknown[idx]
        if bulbs > 1:
            st.contradiction = True
            return
        if bulbs == 1:
            seg = row_segments[idx] if axis == 'r' else col_segments[idx]
            for cell in seg:
                if st.status[cell] == UNKNOWN:
                    mark_no_bulb(st, cell)

    def force_from_cell_illumination(st, cell):
        if st.contradiction:
            return
        if st.lit_count[cell] > 0:
            return
        if st.status[cell] == NOBULB:
            candidates = []
            for src in lit_by[cell]:
                if st.status[src] == UNKNOWN:
                    # src can still be a bulb only if no bulb already in its row/col segments
                    if st.row_bulbs[row_seg_of[src]] == 0 and st.col_bulbs[col_seg_of[src]] == 0:
                        ok = True
                        for numcell in numbers_touching_cell[src]:
                            r, c = numcell
                            if st.num_bulbs[numcell] + 1 > data[r][c]:
                                ok = False
                                break
                        if ok:
                            candidates.append(src)
            if not candidates:
                st.contradiction = True
                return
            if len(candidates) == 1:
                place_bulb(st, candidates[0])
        elif st.status[cell] == UNKNOWN:
            # If the only way to light this cell is placing a bulb here.
            candidates = []
            for src in lit_by[cell]:
                if st.status[src] == UNKNOWN:
                    if st.row_bulbs[row_seg_of[src]] == 0 and st.col_bulbs[col_seg_of[src]] == 0:
                        ok = True
                        for numcell in numbers_touching_cell[src]:
                            r, c = numcell
                            if st.num_bulbs[numcell] + 1 > data[r][c]:
                                ok = False
                                break
                        if ok:
                            candidates.append(src)
            if not candidates:
                st.contradiction = True
                return
            if len(candidates) == 1:
                place_bulb(st, candidates[0])

    def propagate(st):
        # Seed checks
        for numcell in adj_number:
            st.queue.append(('num', numcell))
        for i in range(len(row_segments)):
            st.queue.append(('seg_r', i))
        for i in range(len(col_segments)):
            st.queue.append(('seg_c', i))
        for cell in white_cells:
            st.queue.append(('cell', cell))

        while st.queue and not st.contradiction:
            typ, obj = st.queue.pop()
            if typ == 'num':
                force_from_number(st, obj)
            elif typ == 'seg_r':
                force_from_segment(st, 'r', obj)
            elif typ == 'seg_c':
                force_from_segment(st, 'c', obj)
            else:
                force_from_cell_illumination(st, obj)

        if st.contradiction:
            return False

        # Global feasibility: every still-unlit cell must have some potential source.
        for cell in white_cells:
            if st.lit_count[cell] == 0:
                possible = False
                for src in lit_by[cell]:
                    s = st.status[src]
                    if s == BULB:
                        possible = True
                        break
                    if s == UNKNOWN:
                        if st.row_bulbs[row_seg_of[src]] == 0 and st.col_bulbs[col_seg_of[src]] == 0:
                            ok = True
                            for numcell in numbers_touching_cell[src]:
                                r, c = numcell
                                if st.num_bulbs[numcell] + 1 > data[r][c]:
                                    ok = False
                                    break
                            if ok:
                                possible = True
                                break
                if not possible:
                    st.contradiction = True
                    return False

        # Exact completion check for numbers.
        for r, c, v in numbered:
            numcell = (r, c)
            bulbs = st.num_bulbs[numcell]
            unknown = st.num_unknown[numcell]
            if bulbs > v or bulbs + unknown < v:
                st.contradiction = True
                return False

        return True

    def is_solved(st):
        if st.contradiction:
            return False
        for cell in white_cells:
            if st.lit_count[cell] == 0:
                return False
        for r, c, v in numbered:
            if st.num_bulbs[(r, c)] != v:
                return False
        return True

    def branching_candidates(st):
        # Human-like choice:
        # 1) numbered-cell frontiers with tight possibilities
        # 2) unlit cell with few possible lighting sources
        best = None
        best_score = None

        for r, c, v in numbered:
            numcell = (r, c)
            need = v - st.num_bulbs[numcell]
            if need <= 0 or st.num_unknown[numcell] <= 0:
                continue
            unknowns = [cell for cell in adj_number[numcell] if st.status[cell] == UNKNOWN]
            if unknowns:
                score = (0, len(unknowns), abs(len(unknowns) - need))
                if best_score is None or score < best_score:
                    best_score = score
                    best = ('number', numcell, unknowns, need)

        for cell in white_cells:
            if st.lit_count[cell] == 0:
                candidates = []
                for src in lit_by[cell]:
                    if st.status[src] == UNKNOWN:
                        if st.row_bulbs[row_seg_of[src]] == 0 and st.col_bulbs[col_seg_of[src]] == 0:
                            ok = True
                            for numcell in numbers_touching_cell[src]:
                                r, c = numcell
                                if st.num_bulbs[numcell] + 1 > data[r][c]:
                                    ok = False
                                    break
                            if ok:
                                candidates.append(src)
                    elif st.status[src] == BULB:
                        candidates = [src]
                        break
                if len(candidates) > 1:
                    score = (1, len(candidates), 0)
                    if best_score is None or score < best_score:
                        best_score = score
                        best = ('light', cell, candidates, 1)

        if best is not None:
            return best

        # Fallback: pick an UNKNOWN cell with many constraints around it.
        best_cell = None
        best_val = None
        for cell in white_cells:
            if st.status[cell] == UNKNOWN:
                val = (
                    len(numbers_touching_cell[cell]) * -1,
                    -(1 if st.lit_count[cell] == 0 else 0),
                    -(len(lit_by[cell]))
                )
                if best_val is None or val < best_val:
                    best_val = val
                    best_cell = cell
        if best_cell is not None:
            return ('cell', best_cell, [best_cell], 1)
        return None

    def search(st):
        if not propagate(st):
            return None
        if is_solved(st):
            return st

        choice = branching_candidates(st)
        if choice is None:
            return None

        kind, anchor, options, need = choice

        if kind == 'number':
            # Branch on combinations for exact need among adjacency options, but heavily pruned.
            unknowns = [cell for cell in options if st.status[cell] == UNKNOWN]
            m = len(unknowns)
            if need < 0 or need > m:
                return None

            # Generate combinations recursively, smallest first.
            comb = []

            def gen(i, left):
                if left < 0 or left > m - i:
                    return
                if i == m:
                    if left == 0:
                        yield tuple(comb)
                    return
                cell = unknowns[i]
                # Try bulb first if need is tight.
                comb.append(cell)
                yield from gen(i + 1, left - 1)
                comb.pop()
                yield from gen(i + 1, left)

            for chosen in gen(0, need):
                chosen_set = set(chosen)
                ns = st.clone()
                ok = True
                for cell in unknowns:
                    if cell in chosen_set:
                        place_bulb(ns, cell)
                    else:
                        mark_no_bulb(ns, cell)
                    if ns.contradiction:
                        ok = False
                        break
                if not ok:
                    continue
                res = search(ns)
                if res is not None:
                    return res
            return None

        elif kind == 'light':
            # Branch by selecting which source lights this cell.
            # Prefer placing bulb on the cell itself if possible.
            options = sorted(options, key=lambda x: (x != anchor, len(lit_by[x])))
            tried = set()
            for cell in options:
                if cell in tried:
                    continue
                tried.add(cell)
                ns = st.clone()
                place_bulb(ns, cell)
                if ns.contradiction:
                    continue
                res = search(ns)
                if res is not None:
                    return res
            return None

        else:
            cell = anchor
            # Branch prefer bulb then no bulb if cell currently unlit, else prefer no bulb.
            orders = [BULB, NOBULB] if st.lit_count[cell] == 0 else [NOBULB, BULB]
            for act in orders:
                ns = st.clone()
                if act == BULB:
                    place_bulb(ns, cell)
                else:
                    mark_no_bulb(ns, cell)
                if ns.contradiction:
                    continue
                res = search(ns)
                if res is not None:
                    return res
            return None

    init = State()
    result = search(init)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, c in white_cells:
        if result.status[(r, c)] == BULB:
            answer[r][c] = 'B'
    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 2, None, None, None, None], [None, 1, -1, None, None, -1, None], [None, None, None, None, None, 0, -1], [None, None, None, None, None, None, None], [0, -1, None, None, None, None, None], [None, 1, None, None, 1, 2, None], [None, None, None, None, -1, None, None]]}

# Akari / Light Up solver.
# Board encoding in observation['data']:
#   None -> white cell
#   -1   -> black unnumbered cell
#   0..4 -> black numbered cell requiring exactly that many adjacent bulbs
#
# Output:
#   string representation of NxN grid of 'B' or None values.

from copy import deepcopy

BULB = 1
EMPTY = 0
UNKNOWN = -1


def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0

    white_cells = []
    black_cells = set()
    numbered = {}
    idx_of = {}
    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if v is None:
                idx_of[(r, c)] = len(white_cells)
                white_cells.append((r, c))
            else:
                black_cells.add((r, c))
                if v != -1:
                    numbered[(r, c)] = v

    wcount = len(white_cells)

    # Visibility segments: maximal white runs in rows/cols.
    row_seg_id = [[-1] * m for _ in range(n)]
    col_seg_id = [[-1] * m for _ in range(n)]
    row_segments = []
    col_segments = []

    sid = 0
    for r in range(n):
        c = 0
        while c < m:
            if data[r][c] is None:
                cells = []
                while c < m and data[r][c] is None:
                    row_seg_id[r][c] = sid
                    cells.append(idx_of[(r, c)])
                    c += 1
                row_segments.append(cells)
                sid += 1
            else:
                c += 1

    sid = 0
    for c in range(m):
        r = 0
        while r < n:
            if data[r][c] is None:
                cells = []
                while r < n and data[r][c] is None:
                    col_seg_id[r][c] = sid
                    cells.append(idx_of[(r, c)])
                    r += 1
                col_segments.append(cells)
                sid += 1
            else:
                r += 1

    num_row_segments = len(row_segments)
    num_col_segments = len(col_segments)

    cell_row_seg = [None] * wcount
    cell_col_seg = [None] * wcount
    for i, (r, c) in enumerate(white_cells):
        cell_row_seg[i] = row_seg_id[r][c]
        cell_col_seg[i] = col_seg_id[r][c]

    # For each cell, all visible white cells including itself.
    visible = [set() for _ in range(wcount)]
    for seg in row_segments:
        s = set(seg)
        for i in seg:
            visible[i].update(s)
    for seg in col_segments:
        s = set(seg)
        for i in seg:
            visible[i].update(s)

    # Conflict graph excluding self.
    conflicts = [sorted(v - {i}) for i, v in enumerate(visible)]

    # For coverage: a white cell is lit by any bulb in its visibility set.
    coverers = [sorted(v) for v in visible]

    # Numbered black constraints.
    num_list = []
    num_target = []
    num_adj = []
    cell_to_num_constraints = [[] for _ in range(wcount)]

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    for pos, target in numbered.items():
        r, c = pos
        adj = []
        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m and data[rr][cc] is None:
                idx = idx_of[(rr, cc)]
                adj.append(idx)
        k = len(num_list)
        num_list.append(pos)
        num_target.append(target)
        num_adj.append(adj)
        for idx in adj:
            cell_to_num_constraints[idx].append(k)

    # Segment membership lists for fast propagation.
    row_seg_cells = [list(seg) for seg in row_segments]
    col_seg_cells = [list(seg) for seg in col_segments]

    class State:
        __slots__ = (
            'assign', 'lit_count', 'row_bulb', 'col_bulb',
            'num_bulbs', 'num_unknown',
            'undecided_count', 'bulb_count'
        )

        def __init__(self):
            self.assign = [UNKNOWN] * wcount
            self.lit_count = [0] * wcount
            self.row_bulb = [0] * num_row_segments
            self.col_bulb = [0] * num_col_segments
            self.num_bulbs = [0] * len(num_list)
            self.num_unknown = [len(adj) for adj in num_adj]
            self.undecided_count = wcount
            self.bulb_count = 0

        def clone(self):
            s = State()
            s.assign = self.assign[:]
            s.lit_count = self.lit_count[:]
            s.row_bulb = self.row_bulb[:]
            s.col_bulb = self.col_bulb[:]
            s.num_bulbs = self.num_bulbs[:]
            s.num_unknown = self.num_unknown[:]
            s.undecided_count = self.undecided_count
            s.bulb_count = self.bulb_count
            return s

    def can_set_empty(state, idx):
        if state.assign[idx] != UNKNOWN:
            return state.assign[idx] == EMPTY
        # Numbered constraints cannot be made impossible.
        for ci in cell_to_num_constraints[idx]:
            bulbs = state.num_bulbs[ci]
            unknown = state.num_unknown[ci]
            target = num_target[ci]
            # If this unknown becomes fixed non-bulb:
            if bulbs > target:
                return False
            if bulbs + (unknown - 1) < target:
                return False
        # Coverage feasibility: if this cell is unlit and all possible coverers become impossible, fail.
        if state.lit_count[idx] == 0:
            possible = False
            for j in coverers[idx]:
                aj = state.assign[j]
                if aj == BULB:
                    possible = True
                    break
                if aj == UNKNOWN and state.row_bulb[cell_row_seg[j]] == 0 and state.col_bulb[cell_col_seg[j]] == 0:
                    possible = True
                    break
            if not possible:
                return False
        return True

    def can_set_bulb(state, idx):
        if state.assign[idx] != UNKNOWN:
            return state.assign[idx] == BULB
        rs = cell_row_seg[idx]
        cs = cell_col_seg[idx]
        if state.row_bulb[rs] > 0 or state.col_bulb[cs] > 0:
            return False
        # Numbered constraints
        for ci in cell_to_num_constraints[idx]:
            bulbs = state.num_bulbs[ci]
            unknown = state.num_unknown[ci]
            target = num_target[ci]
            if bulbs + 1 > target:
                return False
            if bulbs + 1 + (unknown - 1) < target:
                return False
        return True

    def set_empty(state, idx):
        if state.assign[idx] == EMPTY:
            return True
        if not can_set_empty(state, idx):
            return False
        state.assign[idx] = EMPTY
        state.undecided_count -= 1
        for ci in cell_to_num_constraints[idx]:
            state.num_unknown[ci] -= 1
        return True

    def set_bulb(state, idx):
        if state.assign[idx] == BULB:
            return True
        if not can_set_bulb(state, idx):
            return False
        state.assign[idx] = BULB
        state.undecided_count -= 1
        state.bulb_count += 1
        rs = cell_row_seg[idx]
        cs = cell_col_seg[idx]
        state.row_bulb[rs] += 1
        state.col_bulb[cs] += 1
        for j in visible[idx]:
            state.lit_count[j] += 1
        for ci in cell_to_num_constraints[idx]:
            state.num_bulbs[ci] += 1
            state.num_unknown[ci] -= 1
        return True

    def finalize_checks(state):
        # Number constraints exactness
        for ci, target in enumerate(num_target):
            if state.num_bulbs[ci] != target:
                return False
        # Every white cell illuminated
        for i in range(wcount):
            if state.lit_count[i] == 0:
                return False
        # No two bulbs see each other ensured by segment counts, but verify.
        for rs in range(num_row_segments):
            if state.row_bulb[rs] > 1:
                return False
        for cs in range(num_col_segments):
            if state.col_bulb[cs] > 1:
                return False
        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # Immediate contradiction checks on numbered cells.
            for ci, target in enumerate(num_target):
                bulbs = state.num_bulbs[ci]
                unknown = state.num_unknown[ci]
                if bulbs > target or bulbs + unknown < target:
                    return False

            # Numbered black cell deductions.
            for ci, target in enumerate(num_target):
                bulbs = state.num_bulbs[ci]
                unknown = state.num_unknown[ci]
                if unknown == 0:
                    continue
                need = target - bulbs
                if need == 0:
                    for idx in num_adj[ci]:
                        if state.assign[idx] == UNKNOWN:
                            if not set_empty(state, idx):
                                return False
                            changed = True
                elif need == unknown:
                    for idx in num_adj[ci]:
                        if state.assign[idx] == UNKNOWN:
                            if not set_bulb(state, idx):
                                return False
                            changed = True

            # Segment deductions: at most one bulb per segment; if segment already has bulb, rest empty.
            for rs, cells in enumerate(row_seg_cells):
                if state.row_bulb[rs] > 1:
                    return False
                if state.row_bulb[rs] == 1:
                    for idx in cells:
                        if state.assign[idx] == UNKNOWN:
                            if not set_empty(state, idx):
                                return False
                            changed = True
                else:
                    # If an unlit cell in this segment can only be lit from this row-segment choice and
                    # every other potential coverer is impossible except a single candidate, force it later via coverage.
                    pass

            for cs, cells in enumerate(col_seg_cells):
                if state.col_bulb[cs] > 1:
                    return False
                if state.col_bulb[cs] == 1:
                    for idx in cells:
                        if state.assign[idx] == UNKNOWN:
                            if not set_empty(state, idx):
                                return False
                            changed = True

            # A cell that can no longer be bulb must be empty.
            for idx in range(wcount):
                if state.assign[idx] == UNKNOWN and not can_set_bulb(state, idx):
                    if not set_empty(state, idx):
                        return False
                    changed = True

            # Coverage deductions:
            # Every unlit white cell must still have at least one feasible coverer.
            # If exactly one feasible coverer remains, force it bulb.
            for cell in range(wcount):
                if state.lit_count[cell] > 0:
                    continue
                feasible = []
                for j in coverers[cell]:
                    aj = state.assign[j]
                    if aj == BULB:
                        feasible = [j]
                        break
                    if aj == UNKNOWN and can_set_bulb(state, j):
                        feasible.append(j)
                if not feasible:
                    return False
                if len(feasible) == 1 and state.assign[feasible[0]] == UNKNOWN:
                    if not set_bulb(state, feasible[0]):
                        return False
                    changed = True

            # If a whole segment has no bulb yet and only one feasible candidate remains that can light
            # any currently unlit cell uniquely in that segment, this often forces placement.
            # We implement a stronger exact-one-possible-in-segment rule only when all other cells are impossible.
            for rs, cells in enumerate(row_seg_cells):
                if state.row_bulb[rs] == 0:
                    cand = [idx for idx in cells if state.assign[idx] == UNKNOWN and can_set_bulb(state, idx)]
                    if len(cand) == 0:
                        # Then every cell in this segment must be lit vertically already.
                        for idx in cells:
                            if state.lit_count[idx] == 0:
                                return False
                    elif len(cand) == 1:
                        idx = cand[0]
                        # Only force if some cell in the segment is currently unlit and cannot be lit otherwise.
                        force = False
                        for x in cells:
                            if state.lit_count[x] == 0:
                                others = 0
                                for j in coverers[x]:
                                    if j == idx:
                                        continue
                                    aj = state.assign[j]
                                    if aj == BULB:
                                        others += 1
                                        break
                                    if aj == UNKNOWN and can_set_bulb(state, j):
                                        others += 1
                                        break
                                if others == 0:
                                    force = True
                                    break
                        if force:
                            if not set_bulb(state, idx):
                                return False
                            changed = True

            for cs, cells in enumerate(col_seg_cells):
                if state.col_bulb[cs] == 0:
                    cand = [idx for idx in cells if state.assign[idx] == UNKNOWN and can_set_bulb(state, idx)]
                    if len(cand) == 0:
                        for idx in cells:
                            if state.lit_count[idx] == 0:
                                return False
                    elif len(cand) == 1:
                        idx = cand[0]
                        force = False
                        for x in cells:
                            if state.lit_count[x] == 0:
                                others = 0
                                for j in coverers[x]:
                                    if j == idx:
                                        continue
                                    aj = state.assign[j]
                                    if aj == BULB:
                                        others += 1
                                        break
                                    if aj == UNKNOWN and can_set_bulb(state, j):
                                        others += 1
                                        break
                                if others == 0:
                                    force = True
                                    break
                        if force:
                            if not set_bulb(state, idx):
                                return False
                            changed = True

        return True

    def choose_branch_cell(state):
        # Human-like heuristic:
        # Prefer cells involved in numbered constraints and critical coverage,
        # minimizing feasible options and maximizing impact.
        best = None
        best_key = None

        for idx in range(wcount):
            if state.assign[idx] != UNKNOWN:
                continue

            bulb_ok = can_set_bulb(state, idx)
            empty_ok = can_set_empty(state, idx)
            if not bulb_ok and not empty_ok:
                return idx, None
            if bulb_ok ^ empty_ok:
                return idx, BULB if bulb_ok else EMPTY

            # Impact score.
            num_pressure = 0
            for ci in cell_to_num_constraints[idx]:
                target = num_target[ci]
                need = target - state.num_bulbs[ci]
                unk = state.num_unknown[ci]
                num_pressure += 4 - abs(need) + (5 - unk)

            coverage_need = sum(1 for x in visible[idx] if state.lit_count[x] == 0)
            seg_tight = 0
            rs = cell_row_seg[idx]
            cs = cell_col_seg[idx]
            seg_tight += len([x for x in row_seg_cells[rs] if state.assign[x] == UNKNOWN])
            seg_tight += len([x for x in col_seg_cells[cs] if state.assign[x] == UNKNOWN])

            key = (-num_pressure, -coverage_need, seg_tight, -len(visible[idx]))
            if best_key is None or key < best_key:
                best_key = key
                best = idx

        return best, None

    def search(state):
        if not propagate(state):
            return None

        if state.undecided_count == 0:
            if finalize_checks(state):
                return state
            return None

        idx, forced = choose_branch_cell(state)
        if idx is None:
            return None

        branches = []
        if forced is None:
            # Prefer bulb first when it covers more unmet cells and is legal.
            bulb_gain = sum(1 for x in visible[idx] if state.lit_count[x] == 0)
            if can_set_bulb(state, idx) and can_set_empty(state, idx):
                if bulb_gain > 0:
                    branches = [BULB, EMPTY]
                else:
                    branches = [EMPTY, BULB]
            elif can_set_bulb(state, idx):
                branches = [BULB]
            elif can_set_empty(state, idx):
                branches = [EMPTY]
            else:
                return None
        else:
            branches = [forced]

        for val in branches:
            ns = state.clone()
            ok = set_bulb(ns, idx) if val == BULB else set_empty(ns, idx)
            if not ok:
                continue
            res = search(ns)
            if res is not None:
                return res
        return None

    init = State()
    result = search(init)
    if result is None:
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for idx, (r, c) in enumerate(white_cells):
        if result.assign[idx] == BULB:
            ans[r][c] = 'B'
    return str(ans)


