# Generalized solver for shapeless 1-star:
# - exactly one star per row
# - exactly one star per column
# - stars may not touch orthogonally or diagonally
# - black cells are forbidden
#
# The model is equivalent to choosing one allowed column for each row, with:
#   1) all chosen columns distinct
#   2) adjacent rows may not choose equal or neighboring columns
#
# The solver emphasizes human-like deduction:
# - candidate generation
# - forced placements by row/column singles
# - Hall-style feasibility checks on row/column subsets
# - interval-based local adjacency support checks
# - propagation under assumptions before branching
# - branch on most constrained row

def solve(observation):
    grid = observation['data']
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"

    full_mask = (1 << n) - 1

    blocked = [0] * n
    row_masks = [0] * n
    col_allowed_rows = [0] * n

    for r in range(n):
        mask = 0
        bmask = 0
        for c in range(n):
            if grid[r][c] == 'B':
                bmask |= 1 << c
            else:
                mask |= 1 << c
                col_allowed_rows[c] |= 1 << r
        blocked[r] = bmask
        row_masks[r] = mask
        if mask == 0:
            return "No Solution"

    def bit_count(x):
        return x.bit_count()

    def iter_bits(x):
        while x:
            lsb = x & -x
            yield lsb.bit_length() - 1
            x ^= lsb

    def neighbors_col_mask(c):
        m = 1 << c
        if c > 0:
            m |= 1 << (c - 1)
        if c + 1 < n:
            m |= 1 << (c + 1)
        return m

    adj_masks = [neighbors_col_mask(c) for c in range(n)]

    def support_mask(prev_mask):
        # Columns in a row that are compatible with at least one column from adjacent row.
        # For chosen column p in previous/next row, forbidden here are p-1,p,p+1.
        # Aggregate allowed support from candidate set prev_mask.
        out = 0
        for c in iter_bits(prev_mask):
            out |= (full_mask ^ adj_masks[c])
        return out & full_mask

    def rows_mask_to_indices(mask):
        return [i for i in range(n) if (mask >> i) & 1]

    def contiguous_unsolved_segments(cands):
        segments = []
        i = 0
        while i < n:
            if bit_count(cands[i]) == 1:
                i += 1
                continue
            j = i
            while j + 1 < n and bit_count(cands[j + 1]) > 1:
                j += 1
            segments.append((i, j))
            i = j + 1
        return segments

    def segment_dp_support(cands, a, b):
        # Human-like local lookahead:
        # within a contiguous unsolved row segment [a..b], mark candidates that can
        # participate in some non-touching assignment (ignoring columns uniqueness
        # outside the segment, but respecting row adjacency inside).
        fwd = [0] * (b - a + 1)
        bwd = [0] * (b - a + 1)

        fwd[0] = cands[a]
        if fwd[0] == 0:
            return False, None
        for idx, r in enumerate(range(a + 1, b + 1), start=1):
            allowed = support_mask(fwd[idx - 1])
            fwd[idx] = cands[r] & allowed
            if fwd[idx] == 0:
                return False, None

        bwd[-1] = cands[b]
        if bwd[-1] == 0:
            return False, None
        for rev_idx, r in enumerate(range(b - 1, a - 1, -1), start=1):
            pos = (b - a) - rev_idx
            allowed = support_mask(bwd[pos + 1])
            bwd[pos] = cands[r] & allowed
            if bwd[pos] == 0:
                return False, None

        supported = [0] * (b - a + 1)
        for i, r in enumerate(range(a, b + 1)):
            m = cands[r]
            if i > 0:
                m &= support_mask(fwd[i - 1])
            if i + 1 < len(bwd):
                m &= support_mask(bwd[i + 1])
            if m == 0:
                return False, None
            supported[i] = m
        return True, supported

    def hall_check_rows_to_cols(cands):
        # For every subset of unresolved rows, number of union columns must be at least subset size.
        # Efficient enough for small N, strong deduction for Latin/permutation structure.
        unsolved = [r for r in range(n) if cands[r] and bit_count(cands[r]) > 1]
        m = len(unsolved)
        if m <= 1:
            return True
        row_unions = [cands[r] for r in unsolved]
        total = 1 << m
        unions = [0] * total
        for s in range(1, total):
            lsb = s & -s
            i = lsb.bit_length() - 1
            unions[s] = unions[s ^ lsb] | row_unions[i]
            if bit_count(unions[s]) < bit_count(s):
                return False
        return True

    def hall_deduce(cands):
        # If a subset of k rows has union of exactly k columns, those columns are excluded elsewhere.
        changed = False
        unsolved = [r for r in range(n) if bit_count(cands[r]) > 1]
        m = len(unsolved)
        if m <= 1:
            return changed, True
        row_unions = [cands[r] for r in unsolved]
        total = 1 << m
        unions = [0] * total
        subset_size = [0] * total
        for s in range(1, total):
            lsb = s & -s
            i = lsb.bit_length() - 1
            p = s ^ lsb
            unions[s] = unions[p] | row_unions[i]
            subset_size[s] = subset_size[p] + 1
        for s in range(1, total):
            k = subset_size[s]
            u = unions[s]
            if bit_count(u) != k:
                continue
            subset_rows = 0
            for i, r in enumerate(unsolved):
                if (s >> i) & 1:
                    subset_rows |= 1 << r
            for r in range(n):
                if (subset_rows >> r) & 1:
                    continue
                nm = cands[r] & ~u
                if nm != cands[r]:
                    if nm == 0:
                        return True, False
                    cands[r] = nm
                    changed = True
        return changed, True

    def propagate(initial_cands):
        cands = initial_cands[:]

        while True:
            changed = False

            # Basic row non-emptiness.
            for r in range(n):
                if cands[r] == 0:
                    return None

            # Column availability and forced-by-column.
            col_rows = [0] * n
            for r in range(n):
                for c in iter_bits(cands[r]):
                    col_rows[c] |= 1 << r

            for c in range(n):
                rows_mask = col_rows[c]
                if rows_mask == 0:
                    return None
                if rows_mask & (rows_mask - 1) == 0:
                    r = rows_mask.bit_length() - 1
                    forced = 1 << c
                    if cands[r] != forced:
                        if not (cands[r] & forced):
                            return None
                        cands[r] = forced
                        changed = True

            # Row singles enforce unique column and no-touch on adjacent rows.
            singles_cols = 0
            single_col_of_row = [-1] * n
            for r in range(n):
                if cands[r] & (cands[r] - 1) == 0:
                    c = cands[r].bit_length() - 1
                    single_col_of_row[r] = c
                    singles_cols |= 1 << c

            for r in range(n):
                if bit_count(cands[r]) > 1:
                    nm = cands[r] & ~singles_cols
                    if nm == 0:
                        return None
                    if nm != cands[r]:
                        cands[r] = nm
                        changed = True

            for r in range(n):
                c = single_col_of_row[r]
                if c == -1:
                    continue
                forbid = adj_masks[c]
                if r > 0:
                    nm = cands[r - 1] & ~forbid
                    if nm == 0:
                        return None
                    if nm != cands[r - 1]:
                        cands[r - 1] = nm
                        changed = True
                if r + 1 < n:
                    nm = cands[r + 1] & ~forbid
                    if nm == 0:
                        return None
                    if nm != cands[r + 1]:
                        cands[r + 1] = nm
                        changed = True

            # Adjacent-row mutual support filtering.
            for r in range(n - 1):
                left_support = support_mask(cands[r + 1])
                nm = cands[r] & left_support
                if nm == 0:
                    return None
                if nm != cands[r]:
                    cands[r] = nm
                    changed = True

                right_support = support_mask(cands[r])
                nm = cands[r + 1] & right_support
                if nm == 0:
                    return None
                if nm != cands[r + 1]:
                    cands[r + 1] = nm
                    changed = True

            # Segment local DP support.
            for a, b in contiguous_unsolved_segments(cands):
                ok, supported = segment_dp_support(cands, a, b)
                if not ok:
                    return None
                for i, r in enumerate(range(a, b + 1)):
                    if supported[i] != cands[r]:
                        cands[r] = supported[i]
                        changed = True

            # Hall deduction / feasibility.
            changed_hall, ok = hall_deduce(cands)
            if not ok:
                return None
            changed |= changed_hall

            if not hall_check_rows_to_cols(cands):
                return None

            # Final solved consistency.
            solved = all(bit_count(cands[r]) == 1 for r in range(n))
            if solved:
                used = 0
                for r in range(n):
                    c = cands[r].bit_length() - 1
                    if (used >> c) & 1:
                        return None
                    used |= 1 << c
                    if r > 0:
                        cp = cands[r - 1].bit_length() - 1
                        if abs(cp - c) <= 1:
                            return None
                return cands

            if not changed:
                return cands

    def choose_branch_row(cands):
        # Most constrained unresolved row, with tie-break by constrained neighborhood.
        best_r = -1
        best_key = None
        for r in range(n):
            k = bit_count(cands[r])
            if k <= 1:
                continue
            pressure = 0
            if r > 0:
                pressure += bit_count(cands[r - 1])
            if r + 1 < n:
                pressure += bit_count(cands[r + 1])
            key = (k, pressure)
            if best_key is None or key < best_key:
                best_key = key
                best_r = r
        return best_r

    def ordered_candidates_for_row(cands, r):
        # Prefer columns that constrain neighbors/columns most.
        used_single_cols = 0
        for rr in range(n):
            if bit_count(cands[rr]) == 1:
                used_single_cols |= cands[rr]

        items = []
        for c in iter_bits(cands[r]):
            score = 0
            score += 3 * bit_count(col_allowed_rows[c] & ~rows_mask_to_bitmask_of_solved(cands))
            if r > 0:
                score += bit_count(cands[r - 1] & adj_masks[c])
            if r + 1 < n:
                score += bit_count(cands[r + 1] & adj_masks[c])
            if (used_single_cols >> c) & 1:
                score += 1000
            items.append((score, c))
        items.sort()
        return [c for _, c in items]

    def rows_mask_to_bitmask_of_solved(cands):
        m = 0
        for r in range(n):
            if bit_count(cands[r]) == 1:
                m |= 1 << r
        return m

    def search(cands):
        cands = propagate(cands)
        if cands is None:
            return None
        if all(bit_count(cands[r]) == 1 for r in range(n)):
            return cands

        r = choose_branch_row(cands)
        if r == -1:
            return None

        for c in ordered_candidates_for_row(cands, r):
            nc = cands[:]
            nc[r] = 1 << c
            res = search(nc)
            if res is not None:
                return res
        return None

    result = search(row_masks)
    if result is None:
        return "No Solution"

    answer = []
    for r in range(n):
        row = [None] * n
        c = result[r].bit_length() - 1
        row[c] = 'S'
        answer.append(row)
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 4, None, None, 1], [None, None, 8, None, None], [None, 6, 9, None, 5], [None, None, 6, None, None], [1, None, None, None, 3]]}

# General solver for the "3x3 neighborhood black-count" puzzle.
# Output format: same-sized grid using 'B' for black and None for white.

def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return []

    R, C = len(data), len(data[0])
    N = R * C

    def vid(r, c):
        return r * C + c

    def rc(v):
        return divmod(v, C)

    # Domains: -1 unknown, 0 white, 1 black
    state = [-1] * N

    # Constraint structures
    constraints = []
    cell_to_constraints = [[] for _ in range(N)]

    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is None:
                continue
            scope = []
            for rr in range(max(0, r - 1), min(R, r + 2)):
                for cc in range(max(0, c - 1), min(C, c + 2)):
                    scope.append(vid(rr, cc))
            idx = len(constraints)
            constraints.append({
                'target': val,
                'cells': scope,
            })
            for v in scope:
                cell_to_constraints[v].append(idx)

    # Fast per-constraint counts
    black_count = [0] * len(constraints)
    unknown_count = [len(con['cells']) for con in constraints]

    # Pairwise overlap metadata for stronger propagation
    pair_index = {}
    pair_meta = []
    for i in range(len(constraints)):
        si = set(constraints[i]['cells'])
        for j in range(i + 1, len(constraints)):
            sj = set(constraints[j]['cells'])
            inter = si & sj
            if inter:
                only_i = list(si - inter)
                only_j = list(sj - inter)
                meta = {
                    'i': i,
                    'j': j,
                    'inter': list(inter),
                    'only_i': only_i,
                    'only_j': only_j,
                }
                pair_index[(i, j)] = len(pair_meta)
                pair_meta.append(meta)

    trail = []

    def assign(v, val, queue):
        cur = state[v]
        if cur == val:
            return True
        if cur != -1:
            return False
        state[v] = val
        trail.append(('cell', v))
        for ci in cell_to_constraints[v]:
            trail.append(('count', ci, black_count[ci], unknown_count[ci]))
            unknown_count[ci] -= 1
            if val == 1:
                black_count[ci] += 1
            queue.append(ci)
        return True

    def revert(mark):
        while len(trail) > mark:
            item = trail.pop()
            if item[0] == 'cell':
                _, v = item
                state[v] = -1
            else:
                _, ci, b, u = item
                black_count[ci] = b
                unknown_count[ci] = u

    def constraint_bounds_ok(ci):
        t = constraints[ci]['target']
        b = black_count[ci]
        u = unknown_count[ci]
        return b <= t <= b + u

    def force_from_constraint(ci, queue):
        if not constraint_bounds_ok(ci):
            return False
        con = constraints[ci]
        t = con['target']
        b = black_count[ci]
        u = unknown_count[ci]

        # If all remaining unknowns must be white
        if b == t:
            for v in con['cells']:
                if state[v] == -1:
                    if not assign(v, 0, queue):
                        return False

        # If all remaining unknowns must be black
        elif b + u == t:
            for v in con['cells']:
                if state[v] == -1:
                    if not assign(v, 1, queue):
                        return False

        return True

    def pairwise_propagate(queue):
        # Human-like overlap reasoning:
        # For two constraints A and B with overlap O:
        # Let required black in A be ra in [minA,maxA] for O induced by A-only cells,
        # and similarly from B. Intersecting these bounds can force cells.
        for meta in pair_meta:
            i = meta['i']
            j = meta['j']

            ta = constraints[i]['target']
            tb = constraints[j]['target']

            ba, ua = black_count[i], unknown_count[i]
            bb, ub = black_count[j], unknown_count[j]

            if not (ba <= ta <= ba + ua and bb <= tb <= bb + ub):
                return False

            # Count known/unknown in partitions
            ai_b = ai_u = 0
            bj_b = bj_u = 0
            o_b = o_u = 0

            for v in meta['only_i']:
                sv = state[v]
                if sv == -1:
                    ai_u += 1
                elif sv == 1:
                    ai_b += 1

            for v in meta['only_j']:
                sv = state[v]
                if sv == -1:
                    bj_u += 1
                elif sv == 1:
                    bj_b += 1

            for v in meta['inter']:
                sv = state[v]
                if sv == -1:
                    o_u += 1
                elif sv == 1:
                    o_b += 1

            rem_a = ta - ba
            rem_b = tb - bb

            # x = number of black unknowns in overlap
            # A gives: rem_a - ai_u <= x <= rem_a
            # but also 0 <= x <= o_u
            lo_a = max(0, rem_a - ai_u)
            hi_a = min(o_u, rem_a)

            lo_b = max(0, rem_b - bj_u)
            hi_b = min(o_u, rem_b)

            lo = max(lo_a, lo_b)
            hi = min(hi_a, hi_b)

            if lo > hi:
                return False

            # If overlap black count fixed, can force side partitions.
            # For A-only unknowns, they must supply rem_a - x blacks.
            # If x fixed at hi=lo, and this implies all A-only unknowns black/white, force them.
            if lo == hi:
                x = lo
                need_ai = rem_a - x
                if need_ai < 0 or need_ai > ai_u:
                    return False
                if need_ai == 0:
                    for v in meta['only_i']:
                        if state[v] == -1:
                            if not assign(v, 0, queue):
                                return False
                elif need_ai == ai_u:
                    for v in meta['only_i']:
                        if state[v] == -1:
                            if not assign(v, 1, queue):
                                return False

                need_bj = rem_b - x
                if need_bj < 0 or need_bj > bj_u:
                    return False
                if need_bj == 0:
                    for v in meta['only_j']:
                        if state[v] == -1:
                            if not assign(v, 0, queue):
                                return False
                elif need_bj == bj_u:
                    for v in meta['only_j']:
                        if state[v] == -1:
                            if not assign(v, 1, queue):
                                return False

                # If overlap itself fixed to all-black or all-white, force it.
                if x == 0:
                    for v in meta['inter']:
                        if state[v] == -1:
                            if not assign(v, 0, queue):
                                return False
                elif x == o_u:
                    for v in meta['inter']:
                        if state[v] == -1:
                            if not assign(v, 1, queue):
                                return False

            # Difference bounds:
            # (ta - blacksAknown) - (tb - blacksBknown) = blacks(A-only unk) - blacks(B-only unk)
            # This can sometimes force one side if extreme.
            diff = rem_a - rem_b
            if diff == ai_u and bj_u == 0:
                for v in meta['only_i']:
                    if state[v] == -1:
                        if not assign(v, 1, queue):
                            return False
            if diff == -bj_u and ai_u == 0:
                for v in meta['only_j']:
                    if state[v] == -1:
                        if not assign(v, 1, queue):
                            return False

        return True

    def propagate(initial_constraints=None):
        if initial_constraints is None:
            queue = list(range(len(constraints)))
        else:
            queue = list(initial_constraints)

        inq = [False] * len(constraints)
        for ci in queue:
            inq[ci] = True

        while queue:
            ci = queue.pop()
            inq[ci] = False
            if not force_from_constraint(ci, queue):
                return False
            # Newly appended constraints may duplicate; that is acceptable.

        # Global pairwise pass until stable
        changed = True
        while changed:
            before = len(trail)
            queue2 = []
            if not pairwise_propagate(queue2):
                return False
            while queue2:
                ci = queue2.pop()
                if not force_from_constraint(ci, queue2):
                    return False
            changed = len(trail) != before

        # Final consistency check
        for ci in range(len(constraints)):
            if not constraint_bounds_ok(ci):
                return False
        return True

    if not propagate():
        return "No Solution"

    all_cells = list(range(N))

    def score_var(v):
        # Prefer variables in many tight constraints
        s = 0
        for ci in cell_to_constraints[v]:
            t = constraints[ci]['target']
            b = black_count[ci]
            u = unknown_count[ci]
            slack = (t - b) + (b + u - t)
            s += 100 - 10 * u - slack
        return s

    def choose_var():
        best = None
        best_key = None
        for v in all_cells:
            if state[v] != -1:
                continue
            deg = len(cell_to_constraints[v])
            if deg == 0:
                key = (-1, 0, -v)
            else:
                key = (deg, score_var(v), -v)
            if best is None or key > best_key:
                best = v
                best_key = key
        return best

    def value_order(v):
        # Try value more compatible with nearby constraints first
        black_pressure = 0
        white_pressure = 0
        for ci in cell_to_constraints[v]:
            t = constraints[ci]['target']
            b = black_count[ci]
            u = unknown_count[ci]
            rem = t - b
            if rem * 2 > u:
                black_pressure += 1
            elif rem * 2 < u:
                white_pressure += 1
        if black_pressure > white_pressure:
            return (1, 0)
        return (0, 1)

    def is_complete():
        return all(s != -1 for s in state)

    def final_check():
        for ci, con in enumerate(constraints):
            if black_count[ci] != con['target']:
                return False
        return True

    def dfs():
        if is_complete():
            return final_check()

        v = choose_var()
        if v is None:
            return final_check()

        for val in value_order(v):
            mark = len(trail)
            queue = []
            if assign(v, val, queue) and propagate(queue):
                if dfs():
                    return True
            revert(mark)
        return False

    if not dfs():
        return "No Solution"

    answer = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if state[vid(r, c)] == 1 else None)
        answer.append(row)
    return answer


if __name__ == "__main__":
    print(solve(OBSERVATION))

