# Shapeless Stars, 1-star variant:
# - exactly 1 star in each row
# - exactly 1 star in each column
# - stars cannot touch, including diagonally
# - black cells cannot contain stars
#
# This is equivalent to selecting one allowed column per row such that:
# 1) selected columns form a permutation
# 2) adjacent rows cannot use equal or neighboring columns
#
# The solver below is generalized and emphasizes human-like deduction:
# - candidate generation from obstacles
# - repeated forced-placement and hidden-single style propagation
# - Hall-style subset checks on rows/columns
# - interval/adjacency aware feasibility checks between row order neighbors
# - only then a highly pruned search with best-variable branching

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    full_mask = (1 << n) - 1

    # Allowed cells by obstacle pattern.
    row_masks = []
    col_masks = [0] * n
    for r in range(n):
        mask = 0
        for c in range(n):
            if data[r][c] != 'B':
                mask |= 1 << c
                col_masks[c] |= 1 << r
        if mask == 0:
            return "No Solution"
        row_masks.append(mask)

    # Precompute adjacency-forbidden columns for each column choice.
    neighbor_mask = [0] * n
    for c in range(n):
        m = 1 << c
        if c > 0:
            m |= 1 << (c - 1)
        if c + 1 < n:
            m |= 1 << (c + 1)
        neighbor_mask[c] = m

    # Helpers
    def popcount(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_index(bit):
        return bit.bit_length() - 1

    def masks_to_board(chosen_cols):
        board = [[None for _ in range(n)] for _ in range(n)]
        for r, c in enumerate(chosen_cols):
            if c is None:
                return "No Solution"
            board[r][c] = 'S'
        return str(board)

    def singleton_index(mask):
        if mask and (mask & (mask - 1)) == 0:
            return bit_index(mask)
        return None

    def propagate(domains):
        # domains[r] is bitmask of candidate columns for row r
        domains = domains[:]

        changed = True
        while changed:
            changed = False

            # Contradiction: any row empty.
            for r in range(n):
                if domains[r] == 0:
                    return None

            # Column support masks from current row domains.
            col_support = [0] * n
            for r in range(n):
                m = domains[r]
                while m:
                    b = m & -m
                    c = bit_index(b)
                    col_support[c] |= 1 << r
                    m ^= b

            # Contradiction: any column unavailable.
            for c in range(n):
                if col_support[c] == 0:
                    return None

            # Rule 1: naked singles in rows -> remove same column from other rows,
            # and remove adjacent columns from adjacent rows.
            forced_rows = []
            for r in range(n):
                s = singleton_index(domains[r])
                if s is not None:
                    forced_rows.append((r, s))

            if forced_rows:
                for r, c in forced_rows:
                    col_bit = 1 << c

                    # Unique column globally.
                    for rr in range(n):
                        if rr != r and (domains[rr] & col_bit):
                            new_mask = domains[rr] & ~col_bit
                            if new_mask != domains[rr]:
                                domains[rr] = new_mask
                                if new_mask == 0:
                                    return None
                                changed = True

                    # No touching with adjacent rows only matters because each row has one star.
                    if r > 0:
                        new_mask = domains[r - 1] & ~neighbor_mask[c]
                        if new_mask != domains[r - 1]:
                            domains[r - 1] = new_mask
                            if new_mask == 0:
                                return None
                            changed = True
                    if r + 1 < n:
                        new_mask = domains[r + 1] & ~neighbor_mask[c]
                        if new_mask != domains[r + 1]:
                            domains[r + 1] = new_mask
                            if new_mask == 0:
                                return None
                            changed = True

            # Rebuild support after changes if needed.
            if changed:
                continue

            # Rule 2: hidden singles in columns.
            for c in range(n):
                support = 0
                cnt = 0
                for r in range(n):
                    if domains[r] & (1 << c):
                        support = r
                        cnt += 1
                        if cnt > 1:
                            break
                if cnt == 0:
                    return None
                if cnt == 1:
                    new_mask = 1 << c
                    if domains[support] != new_mask:
                        domains[support] = new_mask
                        changed = True

            if changed:
                continue

            # Rule 3: neighboring row compatibility pruning.
            # Every candidate in row r must have some compatible candidate in row r+1, and vice versa.
            for r in range(n - 1):
                m1 = domains[r]
                m2 = domains[r + 1]

                # Filter m1 by existence of support in m2 outside neighboring columns.
                keep1 = 0
                t = m1
                while t:
                    b = t & -t
                    c = bit_index(b)
                    if m2 & ~neighbor_mask[c]:
                        keep1 |= b
                    t ^= b
                if keep1 != m1:
                    domains[r] = keep1
                    if keep1 == 0:
                        return None
                    changed = True

                # Filter m2 by existence of support in row r.
                keep2 = 0
                t = m2
                while t:
                    b = t & -t
                    c = bit_index(b)
                    if domains[r] & ~neighbor_mask[c]:
                        keep2 |= b
                    t ^= b
                if keep2 != m2:
                    domains[r + 1] = keep2
                    if keep2 == 0:
                        return None
                    changed = True

            if changed:
                continue

            # Rule 4: Hall-style subset checks on rows (small subsets only, effective and human-like).
            # If k rows together can only occupy k columns, those columns are excluded from other rows.
            # Also detect impossible subset where union size < subset size.
            row_order = sorted(range(n), key=lambda r: popcount(domains[r]))
            limit = min(n, 5)
            subsets = []

            # Generate only combinations among the most constrained rows for efficiency.
            constrained = row_order[:min(n, 7)]

            def gen_subsets(arr, start, need, cur):
                if need == 0:
                    subsets.append(tuple(cur))
                    return
                stop = len(arr) - need + 1
                for i in range(start, stop):
                    cur.append(arr[i])
                    gen_subsets(arr, i + 1, need - 1, cur)
                    cur.pop()

            for k in range(2, limit + 1):
                gen_subsets(constrained, 0, k, [])

            any_subset_change = False
            for subset in subsets:
                union = 0
                for r in subset:
                    union |= domains[r]
                u = popcount(union)
                k = len(subset)
                if u < k:
                    return None
                if u == k:
                    subset_mask = 0
                    for r in subset:
                        subset_mask |= 1 << r
                    for r in range(n):
                        if not ((subset_mask >> r) & 1):
                            new_mask = domains[r] & ~union
                            if new_mask != domains[r]:
                                domains[r] = new_mask
                                if new_mask == 0:
                                    return None
                                any_subset_change = True
            if any_subset_change:
                changed = True
                continue

            # Rule 5: symmetric Hall-style subset checks on columns (small subsets).
            col_support = [0] * n
            for r in range(n):
                m = domains[r]
                while m:
                    b = m & -m
                    c = bit_index(b)
                    col_support[c] |= 1 << r
                    m ^= b

            col_order = sorted(range(n), key=lambda c: popcount(col_support[c]))
            constrained_cols = col_order[:min(n, 7)]
            subsets = []
            for k in range(2, limit + 1):
                gen_subsets(constrained_cols, 0, k, [])

            any_subset_change = False
            for subset in subsets:
                union_rows = 0
                col_union_mask = 0
                for c in subset:
                    union_rows |= col_support[c]
                    col_union_mask |= 1 << c
                u = popcount(union_rows)
                k = len(subset)
                if u < k:
                    return None
                if u == k:
                    # These rows must take these columns only.
                    rows_mask = union_rows
                    rr = rows_mask
                    while rr:
                        rb = rr & -rr
                        r = bit_index(rb)
                        new_mask = domains[r] & col_union_mask
                        if new_mask != domains[r]:
                            domains[r] = new_mask
                            if new_mask == 0:
                                return None
                            any_subset_change = True
                        rr ^= rb
            if any_subset_change:
                changed = True
                continue

        return domains

    def feasible_completion(domains):
        # Fast necessary checks used during search.

        # Distinct columns feasibility: Hall-lite by candidate unions over constrained rows.
        rows = sorted(range(n), key=lambda r: popcount(domains[r]))
        union = 0
        for i, r in enumerate(rows, 1):
            union |= domains[r]
            if popcount(union) < i:
                return False

        # Adjacent row pair compatibility.
        for r in range(n - 1):
            m1 = domains[r]
            m2 = domains[r + 1]
            ok = False
            t = m1
            while t and not ok:
                b = t & -t
                c = bit_index(b)
                if m2 & ~neighbor_mask[c]:
                    ok = True
                t ^= b
            if not ok:
                return False

        return True

    def choose_branch_row(domains):
        # Most constrained row, tie-broken by impact on neighbors/columns.
        best_r = None
        best_key = None
        for r in range(n):
            cnt = popcount(domains[r])
            if cnt <= 1:
                continue
            impact = 0
            m = domains[r]
            while m:
                b = m & -m
                c = bit_index(b)
                # Prefer candidates in scarce columns and with stronger adjacency effect.
                col_scarcity = 0
                for rr in range(n):
                    if domains[rr] & (1 << c):
                        col_scarcity += 1
                impact += col_scarcity
                m ^= b
            key = (cnt, impact)
            if best_key is None or key < best_key:
                best_key = key
                best_r = r
        return best_r

    def ordered_values_for_row(domains, r):
        # Least-constraining value ordering with local human-like preference:
        # prefer columns that are scarce (more forced) and that preserve supports in adjacent rows.
        vals = []
        m = domains[r]
        while m:
            b = m & -m
            c = bit_index(b)

            score = 0

            # Scarcer columns first.
            support = 0
            for rr in range(n):
                if domains[rr] & b:
                    support += 1
            score += support * 10

            # Preserve options in neighbors.
            if r > 0:
                remain = popcount(domains[r - 1] & ~neighbor_mask[c])
                score -= remain
            if r + 1 < n:
                remain = popcount(domains[r + 1] & ~neighbor_mask[c])
                score -= remain

            vals.append((score, c))
            m ^= b
        vals.sort()
        return [c for _, c in vals]

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if not feasible_completion(domains):
            return None

        done = True
        chosen = [None] * n
        for r in range(n):
            s = singleton_index(domains[r])
            if s is None:
                done = False
            else:
                chosen[r] = s

        if done:
            # Final validation.
            if len(set(chosen)) != n:
                return None
            for r in range(n - 1):
                if abs(chosen[r] - chosen[r + 1]) <= 1:
                    return None
            for r, c in enumerate(chosen):
                if data[r][c] == 'B':
                    return None
            return chosen

        r = choose_branch_row(domains)
        if r is None:
            return None

        for c in ordered_values_for_row(domains, r):
            new_domains = domains[:]
            new_domains[r] = 1 << c
            res = search(new_domains)
            if res is not None:
                return res
        return None

    solution = search(row_masks)
    if solution is None:
        return "No Solution"
    return masks_to_board(solution)


