from collections import deque

B = 1
W = 0
U = -1

def solve(observation):
    data = observation['data']
    n = len(data)
    board = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                board[r][c] = B
            elif v == 'W':
                board[r][c] = W

    neighbors = {}
    for r in range(n):
        for c in range(n):
            lst = []
            if r > 0:
                lst.append((r - 1, c))
            if r + 1 < n:
                lst.append((r + 1, c))
            if c > 0:
                lst.append((r, c - 1))
            if c + 1 < n:
                lst.append((r, c + 1))
            neighbors[(r, c)] = lst

    all_cells = [(r, c) for r in range(n) for c in range(n)]

    def color_char(v):
        return 'B' if v == B else 'W'

    def opposite(v):
        return 1 - v

    def clone_board(bd):
        return [row[:] for row in bd]

    def assign(bd, r, c, val, queue):
        cur = bd[r][c]
        if cur == val:
            return True
        if cur != U:
            return False
        bd[r][c] = val
        queue.append((r, c))
        return True

    def enforce_2x2_local(bd, r, c, queue):
        for rr in range(max(0, r - 1), min(n - 1, r) + 1):
            for cc in range(max(0, c - 1), min(n - 1, c) + 1):
                cells = [(rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)]
                vals = [bd[x][y] for x, y in cells]
                cnt_b = sum(v == B for v in vals)
                cnt_w = sum(v == W for v in vals)
                cnt_u = sum(v == U for v in vals)
                if cnt_b == 4 or cnt_w == 4:
                    return False
                if cnt_u == 1:
                    idx = vals.index(U)
                    ur, uc = cells[idx]
                    if cnt_b == 3:
                        if not assign(bd, ur, uc, W, queue):
                            return False
                    elif cnt_w == 3:
                        if not assign(bd, ur, uc, B, queue):
                            return False
        return True

    def enforce_line_patterns_around(bd, r, c, queue):
        # Human-like local deductions:
        # 1) If two same colors sandwich an unknown in a line, middle must be opposite.
        # 2) If two adjacent same colors and one side unknown in line, that unknown must be opposite.
        for dr, dc in ((1, 0), (0, 1)):
            for k in range(-2, 1):
                cells = []
                ok = True
                for t in range(3):
                    rr = r + (k + t) * dr
                    cc = c + (k + t) * dc
                    if not (0 <= rr < n and 0 <= cc < n):
                        ok = False
                        break
                    cells.append((rr, cc))
                if not ok:
                    continue
                vals = [bd[x][y] for x, y in cells]
                if vals[0] != U and vals[0] == vals[2] and vals[1] == U:
                    if not assign(bd, cells[1][0], cells[1][1], opposite(vals[0]), queue):
                        return False
                if vals[0] != U and vals[0] == vals[1] and vals[2] == U:
                    if not assign(bd, cells[2][0], cells[2][1], opposite(vals[0]), queue):
                        return False
                if vals[1] != U and vals[1] == vals[2] and vals[0] == U:
                    if not assign(bd, cells[0][0], cells[0][1], opposite(vals[1]), queue):
                        return False
        return True

    def component_info(bd, color):
        seen = set()
        comps = []
        color_cells = []
        unknowns = []
        for r, c in all_cells:
            v = bd[r][c]
            if v == color:
                color_cells.append((r, c))
            elif v == U:
                unknowns.append((r, c))
        for cell in color_cells:
            if cell in seen:
                continue
            q = deque([cell])
            seen.add(cell)
            comp = []
            frontier_unknown = set()
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in neighbors[(x, y)]:
                    nv = bd[nx][ny]
                    if nv == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
                    elif nv == U:
                        frontier_unknown.add((nx, ny))
            comps.append((comp, frontier_unknown))
        return comps, color_cells, unknowns

    def reachable_unknown_or_color_region(bd, color, starts):
        # Cells usable by this color: current color cells + unknowns
        allowed = set()
        for r, c in all_cells:
            if bd[r][c] == color or bd[r][c] == U:
                allowed.add((r, c))
        if not starts:
            return allowed
        q = deque()
        seen = set()
        for s in starts:
            if s in allowed:
                q.append(s)
                seen.add(s)
        while q:
            x, y = q.popleft()
            for nx, ny in neighbors[(x, y)]:
                if (nx, ny) in allowed and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    q.append((nx, ny))
        return seen

    def connectivity_prune_and_forcing(bd, queue):
        # For each color:
        # - if multiple fixed components cannot possibly connect through unknowns => contradiction
        # - unknown cells that are unusable by a color when multiple components exist must be opposite
        for color in (B, W):
            comps, color_cells, unknowns = component_info(bd, color)
            if not color_cells:
                continue

            usable = set()
            for r, c in all_cells:
                if bd[r][c] == color or bd[r][c] == U:
                    usable.add((r, c))

            # Reachability among usable cells from first component
            start = color_cells[0]
            reach = reachable_unknown_or_color_region(bd, color, [start])

            for cell in color_cells:
                if cell not in reach:
                    return False

            if len(comps) >= 2:
                # Unknowns outside common necessary reachable area cannot help this color.
                # Strong easy deduction: if an unknown cannot reach any fixed color cell through usable cells, it must be opposite.
                for r, c in unknowns:
                    if (r, c) not in reach:
                        if not assign(bd, r, c, opposite(color), queue):
                            return False

                # If a component has no frontier unknown and more than one component exists => impossible
                for comp, frontier in comps:
                    if not frontier:
                        return False

        return True

    def articulation_forcing_for_color(bd, color, queue):
        # If removing an unknown from the color+unknown graph disconnects fixed color cells, that unknown is mandatory for that color.
        fixed = [(r, c) for r, c in all_cells if bd[r][c] == color]
        if len(fixed) <= 1:
            return True

        allowed = [(r, c) for r, c in all_cells if bd[r][c] in (color, U)]
        allowed_set = set(allowed)

        root = fixed[0]
        base_reach = reachable_unknown_or_color_region(bd, color, [root])
        for cell in fixed:
            if cell not in base_reach:
                return False

        unknowns = [(r, c) for r, c in all_cells if bd[r][c] == U]
        for ur, uc in unknowns:
            # quick skip: only examine if adjacent to at least two usable areas / near colored structure
            touch = 0
            for nr, nc in neighbors[(ur, uc)]:
                if bd[nr][nc] in (color, U):
                    touch += 1
            if touch < 2:
                continue

            # BFS without this unknown
            q = deque([root])
            seen = {root}
            while q:
                x, y = q.popleft()
                for nx, ny in neighbors[(x, y)]:
                    if (nx, ny) == (ur, uc):
                        continue
                    if (nx, ny) in allowed_set and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            bad = False
            for cell in fixed:
                if cell not in seen:
                    bad = True
                    break
            if bad:
                if not assign(bd, ur, uc, color, queue):
                    return False
        return True

    def no_enclosed_opposite_islands(bd):
        # Final/near-final necessary check:
        # For each color, every component in fixed-only graph must have access to unknown or be sole component.
        for color in (B, W):
            comps, color_cells, _ = component_info(bd, color)
            if len(comps) <= 1:
                continue
            for comp, frontier in comps:
                if not frontier:
                    return False
        return True

    def propagate(bd):
        queue = deque()
        for r, c in all_cells:
            if bd[r][c] != U:
                queue.append((r, c))

        while queue:
            r, c = queue.popleft()
            if not enforce_2x2_local(bd, r, c, queue):
                return None
            if not enforce_line_patterns_around(bd, r, c, queue):
                return None

            # Neighborhood contradiction checks for already fixed cells can be extended here.

        changed = True
        while changed:
            changed = False
            before = sum(bd[r][c] != U for r, c in all_cells)

            queue2 = deque()
            if not connectivity_prune_and_forcing(bd, queue2):
                return None
            if not articulation_forcing_for_color(bd, B, queue2):
                return None
            if not articulation_forcing_for_color(bd, W, queue2):
                return None

            while queue2:
                rr, cc = queue2.popleft()
                if not enforce_2x2_local(bd, rr, cc, queue2):
                    return None
                if not enforce_line_patterns_around(bd, rr, cc, queue2):
                    return None

            if not no_enclosed_opposite_islands(bd):
                return None

            after = sum(bd[r][c] != U for r, c in all_cells)
            changed = after > before

        return bd

    def final_valid(bd):
        # Full assignment checks
        for r in range(n - 1):
            for c in range(n - 1):
                s = bd[r][c] + bd[r + 1][c] + bd[r][c + 1] + bd[r + 1][c + 1]
                if s == 0 or s == 4:
                    return False

        for color in (B, W):
            cells = [(r, c) for r, c in all_cells if bd[r][c] == color]
            if not cells:
                return False
            q = deque([cells[0]])
            seen = {cells[0]}
            while q:
                x, y = q.popleft()
                for nx, ny in neighbors[(x, y)]:
                    if bd[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if len(seen) != len(cells):
                return False
        return True

    def score_cell(bd, r, c):
        # Choose unknown with strongest local impact
        score = 0
        for nr, nc in neighbors[(r, c)]:
            if bd[nr][nc] != U:
                score += 3
        for rr in range(max(0, r - 1), min(n - 1, r) + 1):
            for cc in range(max(0, c - 1), min(n - 1, c) + 1):
                vals = [bd[rr][cc], bd[rr + 1][cc], bd[rr][cc + 1], bd[rr + 1][cc + 1]]
                if vals.count(U) <= 2:
                    score += 4
        return score

    def pick_branch_cell(bd):
        best = None
        best_score = -1
        for r, c in all_cells:
            if bd[r][c] == U:
                s = score_cell(bd, r, c)
                if s > best_score:
                    best_score = s
                    best = (r, c)
        return best

    def branch_order(bd, r, c):
        # Prefer color matching more neighbors to promote connectivity.
        cnt = {B: 0, W: 0}
        for nr, nc in neighbors[(r, c)]:
            if bd[nr][nc] in (B, W):
                cnt[bd[nr][nc]] += 1
        if cnt[B] > cnt[W]:
            return [B, W]
        if cnt[W] > cnt[B]:
            return [W, B]
        return [B, W]

    def dfs(bd):
        bd = propagate(bd)
        if bd is None:
            return None

        done = True
        for r, c in all_cells:
            if bd[r][c] == U:
                done = False
                break
        if done:
            return bd if final_valid(bd) else None

        r, c = pick_branch_cell(bd)
        for val in branch_order(bd, r, c):
            nb = clone_board(bd)
            q = deque()
            if not assign(nb, r, c, val, q):
                continue
            while q:
                rr, cc = q.popleft()
                if not enforce_2x2_local(nb, rr, cc, q):
                    nb = None
                    break
                if not enforce_line_patterns_around(nb, rr, cc, q):
                    nb = None
                    break
            if nb is None:
                continue
            ans = dfs(nb)
            if ans is not None:
                return ans
        return None

    result = dfs(board)
    if result is None:
        return "No Solution"
    return [[color_char(result[r][c]) for c in range(n)] for r in range(n)]

