            a, b, _ = edges[ei]
            p1 = (islands[a][0], islands[a][1])
            p2 = (islands[b][0], islands[b][1])
            if p1 > p2:
                p1, p2 = p2, p1
            out[(p1, p2)] = val
    return str(out)


def build_edges(islands, pos_to_idx, n, data):
    edges = []
    incident = [[] for _ in islands]

    # Horizontal visibility
    for r in range(n):
        prev = None
        for c in range(n):
            if data[r][c] is not None:
                cur = pos_to_idx[(r, c)]
                if prev is not None:
                    a, b = prev, cur
                    ei = len(edges)
                    edges.append((a, b, 'H'))
                    incident[a].append(ei)
                    incident[b].append(ei)
                prev = cur

    # Vertical visibility
    for c in range(n):
        prev = None
        for r in range(n):
            if data[r][c] is not None:
                cur = pos_to_idx[(r, c)]
                if prev is not None:
                    a, b = prev, cur
                    ei = len(edges)
                    edges.append((a, b, 'V'))
                    incident[a].append(ei)
                    incident[b].append(ei)
                prev = cur

    return edges, incident


def build_crossings(edges, islands):
    crossings = [[] for _ in edges]
    for i, (a1, b1, o1) in enumerate(edges):
        r1a, c1a, _ = islands[a1]
        r1b, c1b, _ = islands[b1]
        if o1 == 'H':
            hr = r1a
            hc1, hc2 = sorted((c1a, c1b))
        else:
            vc = c1a
            vr1, vr2 = sorted((r1a, r1b))

        for j in range(i + 1, len(edges)):
            a2, b2, o2 = edges[j]
            if o1 == o2:
                continue

            if o1 == 'H':
                r2a, c2a, _ = islands[a2]
                r2b, c2b, _ = islands[b2]
                vc = c2a
                vr1, vr2 = sorted((r2a, r2b))
                if hc1 < vc < hc2 and vr1 < hr < vr2:
                    crossings[i].append(j)
                    crossings[j].append(i)
            else:
                r2a, c2a, _ = islands[a2]
                r2b, c2b, _ = islands[b2]
                hr = r2a
                hc1, hc2 = sorted((c2a, c2b))
                if hc1 < vc < hc2 and vr1 < hr < vr2:
                    crossings[i].append(j)
                    crossings[j].append(i)
    return crossings


def init_state(islands, edges, incident):
    m = len(edges)
    low = [0] * m
    high = [2] * m
    value = [None] * m

    req = [need for _, _, need in islands]

    return {
        'low': low,
        'high': high,
        'value': value,
        'req': req,
    }


def copy_state(state):
    return {
        'low': state['low'][:],
        'high': state['high'][:],
        'value': state['value'][:],
        'req': state['req'][:],
    }


def set_edge_range(state, ei, new_low, new_high):
    low = state['low'][ei]
    high = state['high'][ei]
    nl = max(low, new_low)
    nh = min(high, new_high)
    if nl > nh:
        return False, False
    changed = (nl != low or nh != high)
    state['low'][ei] = nl
    state['high'][ei] = nh
    if nl == nh:
        state['value'][ei] = nl
    return True, changed


def fix_edge(state, ei, val):
    return set_edge_range(state, ei, val, val)


def node_bounds(state, incident, node):
    lo = 0
    hi = 0
    undec = []
    for ei in incident[node]:
        lo += state['low'][ei]
        hi += state['high'][ei]
        if state['low'][ei] != state['high'][ei]:
            undec.append(ei)
    return lo, hi, undec


def propagate(state, islands, edges, incident, crossings):
    q_nodes = deque(range(len(islands)))
    q_edges = deque(range(len(edges)))
    in_q_nodes = [True] * len(islands)
    in_q_edges = [True] * len(edges)

    while q_nodes or q_edges:
        while q_edges:
            ei = q_edges.popleft()
            in_q_edges[ei] = False

            # crossing propagation: if edge has min > 0, crossing edges must be 0
            if state['low'][ei] > 0:
                for ej in crossings[ei]:
                    ok, ch = set_edge_range(state, ej, 0, 0)
                    if not ok:
                        return False
                    if ch:
                        a, b, _ = edges[ej]
                        for v in (a, b):
                            if not in_q_nodes[v]:
                                in_q_nodes[v] = True
                                q_nodes.append(v)
                        if not in_q_edges[ej]:
                            in_q_edges[ej] = True
                            q_edges.append(ej)

            # if crossing edge forced positive, this one must be 0
            for ej in crossings[ei]:
                if state['low'][ej] > 0:
                    ok, ch = set_edge_range(state, ei, 0, 0)
                    if not ok:
                        return False
                    if ch:
                        a, b, _ = edges[ei]
                        for v in (a, b):
                            if not in_q_nodes[v]:
                                in_q_nodes[v] = True
                                q_nodes.append(v)
                        if not in_q_edges[ei]:
                            in_q_edges[ei] = True
                            q_edges.append(ei)
                    break

        while q_nodes:
            v = q_nodes.popleft()
            in_q_nodes[v] = False

            need = islands[v][2]
            lo, hi, undec = node_bounds(state, incident, v)

            if lo > need or hi < need:
                return False

            # Exact fill / exact exclusion
            if lo == need:
                for ei in incident[v]:
                    if state['high'][ei] > state['low'][ei]:
                        ok, ch = fix_edge(state, ei, state['low'][ei])
                        if not ok:
                            return False
                        if ch:
                            a, b, _ = edges[ei]
                            other = b if a == v else a
                            for u in (v, other):
                                if not in_q_nodes[u]:
                                    in_q_nodes[u] = True
                                    q_nodes.append(u)
                            if not in_q_edges[ei]:
                                in_q_edges[ei] = True
                                q_edges.append(ei)
                continue

            if hi == need:
                for ei in incident[v]:
                    if state['high'][ei] > state['low'][ei]:
                        ok, ch = fix_edge(state, ei, state['high'][ei])
                        if not ok:
                            return False
                        if ch:
                            a, b, _ = edges[ei]
                            other = b if a == v else a
                            for u in (v, other):
                                if not in_q_nodes[u]:
                                    in_q_nodes[u] = True
                                    q_nodes.append(u)
                            if not in_q_edges[ei]:
                                in_q_edges[ei] = True
                                q_edges.append(ei)
                continue

            # Per-edge bound tightening from node total
            total_low = lo
            total_high = hi
            for ei in incident[v]:
                el = state['low'][ei]
                eh = state['high'][ei]
                # edge must be at least need - (sum max of others)
                min_needed = need - (total_high - eh)
                # edge can be at most need - (sum min of others)
                max_allowed = need - (total_low - el)
                ok, ch = set_edge_range(state, ei, min_needed, max_allowed)
                if not ok:
                    return False
                if ch:
                    a, b, _ = edges[ei]
                    other = b if a == v else a
                    for u in (v, other):
                        if not in_q_nodes[u]:
                            in_q_nodes[u] = True
                            q_nodes.append(u)
                    if not in_q_edges[ei]:
                        in_q_edges[ei] = True
                        q_edges.append(ei)

            # Human-like "all remaining edges positive" inference:
            # if node still needs at least count(remaining edges), each remaining edge >=1
            lo2, hi2, _ = node_bounds(state, incident, v)
            rem = need - lo2
            cand = [ei for ei in incident[v] if state['high'][ei] > state['low'][ei] or state['low'][ei] == 0]
            pos_capable = [ei for ei in cand if state['high'][ei] >= 1]
            if rem > 0 and rem == len(pos_capable):
                for ei in pos_capable:
                    ok, ch = set_edge_range(state, ei, 1, state['high'][ei])
                    if not ok:
                        return False
                    if ch:
                        a, b, _ = edges[ei]
                        other = b if a == v else a
                        for u in (v, other):
                            if not in_q_nodes[u]:
                                in_q_nodes[u] = True
                                q_nodes.append(u)
                        if not in_q_edges[ei]:
                            in_q_edges[ei] = True
                            q_edges.append(ei)

        if not connectivity_feasible(state, islands, edges, incident):
            return False

    return True


def connectivity_feasible(state, islands, edges, incident):
    n = len(islands)

    # Every island with positive requirement must still be able to connect somehow.
    for v in range(n):
        need = islands[v][2]
        lo, hi, _ = node_bounds(state, incident, v)
        if need > 0 and hi == 0:
            return False
        # if node still needs bridges, but every incident edge is fixed 0 -> impossible
        if lo < need and all(state['high'][ei] == 0 for ei in incident[v]):
            return False

    # Components in graph of edges that can still be positive.
    comps = potential_components(state, edges, n)
    if len(comps) == 1:
        return True

    comp_id = [-1] * n
    for i, comp in enumerate(comps):
        for v in comp:
            comp_id[v] = i

    # Need at least len(comps)-1 potential inter-component connectors.
    # Since original visible edges are only between islands, check whether any edge between components can still be >0.
    bridgeable_pairs = set()
    for ei, (a, b, _) in enumerate(edges):
        if state['high'][ei] > 0:
            ca = comp_id[a]
            cb = comp_id[b]
            if ca != cb:
                if ca > cb:
                    ca, cb = cb, ca
                bridgeable_pairs.add((ca, cb))

    # In practice potential_components already contracts via high>0, so cross-comp edges shouldn't exist.
    # Thus if multiple components remain under high>0 graph, impossible.
    if len(comps) > 1:
        return False

    return True


def potential_components(state, edges, n_nodes):
    g = [[] for _ in range(n_nodes)]
    for ei, (a, b, _) in enumerate(edges):
        if state['high'][ei] > 0:
            g[a].append(b)
            g[b].append(a)
    seen = [False] * n_nodes
    comps = []
    for s in range(n_nodes):
        if not seen[s]:
            stack = [s]
            seen[s] = True
            comp = []
            while stack:
                v = stack.pop()
                comp.append(v)
                for w in g[v]:
                    if not seen[w]:
                        seen[w] = True
                        stack.append(w)
            comps.append(comp)
    return comps


def is_solved(state, islands, edges, incident):
    for ei in range(len(edges)):
        if state['low'][ei] != state['high'][ei]:
            return False
    for v in range(len(islands)):
        need = islands[v][2]
        lo, hi, _ = node_bounds(state, incident, v)
        if lo != need or hi != need:
            return False
    return final_connected(state, edges, len(islands))


def final_connected(state, edges, n_nodes):
    g = [[] for _ in range(n_nodes)]
    for ei, (a, b, _) in enumerate(edges):
        if state['low'][ei] > 0:
            g[a].append(b)
            g[b].append(a)
    seen = [False] * n_nodes
    stack = [0]
    seen[0] = True
    while stack:
        v = stack.pop()
        for w in g[v]:
            if not seen[w]:
                seen[w] = True
                stack.append(w)
    return all(seen)


def choose_branch_edge(state, islands, edges, incident, crossings):
    best = None
    best_score = None
    for ei, (a, b, _) in enumerate(edges):
        l = state['low'][ei]
        h = state['high'][ei]
        if l == h:
            continue

        # Smaller domain first; more constrained endpoints/crossings preferred
        domain = h - l + 1
        slack_a = node_slack(state, incident, islands, a)
        slack_b = node_slack(state, incident, islands, b)
        cross = len(crossings[ei])
        score = (domain, slack_a + slack_b, -cross)
        if best_score is None or score < best_score:
            best_score = score
            best = ei
    return best


def node_slack(state, incident, islands, v):
    need = islands[v][2]
    lo, hi, _ = node_bounds(state, incident, v)
    return (need - lo) + (hi - need)


def search(state, islands, edges, incident, crossings):
    if is_solved(state, islands, edges, incident):
        return state

    ei = choose_branch_edge(state, islands, edges, incident, crossings)
    if ei is None:
        return None

    l = state['low'][ei]
    h = state['high'][ei]

    # Value ordering:
    # prefer forced-looking positive values before 0 to mimic human solving of connectivity,
    # unless 0 is the only lower bound.
    vals = []
    if l <= 1 <= h:
        vals.append(1)
    if l <= 2 <= h:
        vals.append(2)
    if l <= 0 <= h:
        vals.append(0)

    # Remove duplicates while preserving order
    ordered = []
    seen = set()
    for v in vals:
        if v not in seen:
            seen.add(v)
            ordered.append(v)

    for val in ordered:
        st = copy_state(state)
        ok, _ = fix_edge(st, ei, val)
        if not ok:
            continue
        if not propagate(st, islands, edges, incident, crossings):
            continue
        res = search(st, islands, edges, incident, crossings)
        if res is not None:
            return res
    return None


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 1, 1, 1, 1, 1, 2, 2], [0, 3, 4, 1, 5, 5, 5, 6, 6, 2], [0, 3, 4, 1, 1, 1, 5, 5, 2, 2], [0, 3, 4, 1, 7, 7, 7, 7, 8, 2], [0, 3, 4, 4, 4, 9, 9, 10, 8, 8], [3, 3, 4, 9, 9, 9, 10, 10, 8, 8], [3, 11, 9, 9, 12, 12, 10, 13, 14, 8], [15, 11, 11, 12, 12, 12, 13, 13, 14, 16], [15, 11, 17, 17, 17, 13, 13, 18, 19, 16], [15, 11, 17, 18, 18, 18, 18, 18, 19, 16]], 'row_water_counts': [5, 3, 3, 7, 1, 1, 5, 6, 3, 2], 'col_water_counts': [3, 2, 2, 6, 4, 5, 4, 4, 4, 2]}

from collections import defaultdict, deque

# General solver for the "water level per region" puzzle.
# Each region chooses a height h in [0, size], meaning exactly the lowest h cells
# of that region (by row order within the region) are water.
# Row/column totals must match the clues exactly.
#
# The solver emphasizes:
# - region-domain modeling by possible water heights
# - aggressive propagation using row/column residual bounds
# - local consistency by removing unsupported heights
# - branch on most constrained region only when necessary

def solve(observation):
    region_grid = observation['region']
    row_targets = observation['row_water_counts']
    col_targets = observation['col_water_counts']

    if not region_grid or not region_grid[0]:
        return "No Solution"

    R = len(region_grid)
    C = len(region_grid[0])

    # Validate rectangular grid
    for row in region_grid:
        if len(row) != C:
            return "No Solution"

    # Build region cell lists
    region_cells = defaultdict(list)
    for r in range(R):
        for c in range(C):
            region_cells[region_grid[r][c]].append((r, c))

    region_ids = sorted(region_cells)
    n_regions = len(region_ids)
    ridx_of = {rid: i for i, rid in enumerate(region_ids)}

    # Sort cells in each region from top to bottom; rule says if a cell is water,
    # all cells of that region below it are also water. Thus water forms a suffix
    # of the region ordered by row descending, equivalently lowest h cells by row.
    # Since boundaries are orthogonal and regions in this puzzle type are x-monotone
    # enough for the stated rule, ordering by row descending is sufficient:
    # all cells in strictly lower rows must be included before higher rows.
    #
    # To support exact row/col contributions for each possible height, we sort by
    # (-row, stable col) so the first h chosen cells are the lowest cells.
    region_ordered_cells = []
    region_sizes = []
    region_prefix_row = []
    region_prefix_col = []

    for rid in region_ids:
        cells = sorted(region_cells[rid], key=lambda rc: (-rc[0], rc[1]))
        region_ordered_cells.append(cells)
        k = len(cells)
        region_sizes.append(k)

        # pref_row[h][r] = number of water cells contributed to row r by taking height h
        # pref_col[h][c] = analogous for columns
        pr = [[0] * R for _ in range(k + 1)]
        pc = [[0] * C for _ in range(k + 1)]
        for h in range(1, k + 1):
            rr, cc = cells[h - 1]
            prev_r = pr[h - 1]
            prev_c = pc[h - 1]
            cur_r = prev_r[:]
            cur_c = prev_c[:]
            cur_r[rr] += 1
            cur_c[cc] += 1
            pr[h] = cur_r
            pc[h] = cur_c
        region_prefix_row.append(pr)
        region_prefix_col.append(pc)

    # For each region and row/col, possible contributions from each height.
    # These tiny tables enable fast support checks.
    region_row_values = []
    region_col_values = []
    for i in range(n_regions):
        k = region_sizes[i]
        row_vals = [set() for _ in range(R)]
        col_vals = [set() for _ in range(C)]
        for h in range(k + 1):
            rv = region_prefix_row[i][h]
            cv = region_prefix_col[i][h]
            for r in range(R):
                row_vals[r].add(rv[r])
            for c in range(C):
                col_vals[c].add(cv[c])
        region_row_values.append(row_vals)
        region_col_values.append(col_vals)

    # Domain of each region = possible heights 0..size
    domains = [set(range(region_sizes[i] + 1)) for i in range(n_regions)]

    # Incidence lists for fast updates
    row_regions = [[] for _ in range(R)]
    col_regions = [[] for _ in range(C)]
    for i in range(n_regions):
        seen_rows = set()
        seen_cols = set()
        for r, c in region_ordered_cells[i]:
            if r not in seen_rows:
                row_regions[r].append(i)
                seen_rows.add(r)
            if c not in seen_cols:
                col_regions[c].append(i)
                seen_cols.add(c)

    # Quick impossible checks on total water
    total_row = sum(row_targets)
    total_col = sum(col_targets)
    if total_row != total_col:
        return "No Solution"

    total_cells = R * C
    if total_row < 0 or total_row > total_cells:
        return "No Solution"

    # Precompute per-region/per-height row and col contrib arrays for speed
    def row_contrib(i, h, r):
        return region_prefix_row[i][h][r]

    def col_contrib(i, h, c):
        return region_prefix_col[i][h][c]

    def compute_bounds(domains):
        row_min = [0] * R
        row_max = [0] * R
        col_min = [0] * C
        col_max = [0] * C

        for i in range(n_regions):
            dom = domains[i]
            if not dom:
                return None
            # For each row/col, min/max contribution over current domain
            # Domains are small; direct scan is efficient.
            for r in range(R):
                vals = [row_contrib(i, h, r) for h in dom]
                row_min[r] += min(vals)
                row_max[r] += max(vals)
            for c in range(C):
                vals = [col_contrib(i, h, c) for h in dom]
                col_min[c] += min(vals)
                col_max[c] += max(vals)

        return row_min, row_max, col_min, col_max

    def feasible_totals(domains):
        b = compute_bounds(domains)
        if b is None:
            return False
        row_min, row_max, col_min, col_max = b
        for r in range(R):
            if row_targets[r] < row_min[r] or row_targets[r] > row_max[r]:
                return False
        for c in range(C):
            if col_targets[c] < col_min[c] or col_targets[c] > col_max[c]:
                return False
        return True

    def prune(domains):
        # Constraint propagation until fixed point.
        # Returns pruned copy or None if contradiction.
        domains = [set(d) for d in domains]

        while True:
            changed = False

            bounds = compute_bounds(domains)
            if bounds is None:
                return None
            row_min, row_max, col_min, col_max = bounds

            for r in range(R):
                if row_targets[r] < row_min[r] or row_targets[r] > row_max[r]:
                    return None
            for c in range(C):
                if col_targets[c] < col_min[c] or col_targets[c] > col_max[c]:
                    return None

            # Remove unsupported heights by row bounds
            for i in range(n_regions):
                dom = domains[i]
                if len(dom) == 1:
                    continue
                remove = set()

                # Precompute other-regions bounds for rows/cols touched by region i
                touched_rows = set(r for r, _ in region_ordered_cells[i])
                touched_cols = set(c for _, c in region_ordered_cells[i])

                other_row_min = {}
                other_row_max = {}
                for r in touched_rows:
                    vals = [row_contrib(i, h, r) for h in dom]
                    imin = min(vals)
                    imax = max(vals)
                    other_row_min[r] = row_min[r] - imin
                    other_row_max[r] = row_max[r] - imax

                other_col_min = {}
                other_col_max = {}
                for c in touched_cols:
                    vals = [col_contrib(i, h, c) for h in dom]
                    imin = min(vals)
                    imax = max(vals)
                    other_col_min[c] = col_min[c] - imin
                    other_col_max[c] = col_max[c] - imax

                for h in list(dom):
                    ok = True
                    for r in touched_rows:
                        v = row_contrib(i, h, r)
                        if row_targets[r] < other_row_min[r] + v or row_targets[r] > other_row_max[r] + v:
                            ok = False
                            break
                    if ok:
                        for c in touched_cols:
                            v = col_contrib(i, h, c)
                            if col_targets[c] < other_col_min[c] + v or col_targets[c] > other_col_max[c] + v:
                                ok = False
                                break
                    if not ok:
                        remove.add(h)

                if remove:
                    dom -= remove
                    if not dom:
                        return None
                    changed = True

            if changed:
                continue

            # Stronger line-based subset DP support:
            # For each row and each participating region, retain only heights whose
            # row contribution can participate in some exact sum for that row.
            for r in range(R):
                regs = row_regions[r]
                if not regs:
                    if row_targets[r] != 0:
                        return None
                    continue

                contrib_lists = []
                for i in regs:
                    vals = defaultdict(set)
                    for h in domains[i]:
                        vals[row_contrib(i, h, r)].add(h)
                    contrib_lists.append((i, vals))

                suffix = [set() for _ in range(len(regs) + 1)]
                suffix[len(regs)] = {0}
                for idx in range(len(regs) - 1, -1, -1):
                    _, vals = contrib_lists[idx]
                    sums = set()
                    for v in vals:
                        for s in suffix[idx + 1]:
                            ns = v + s
                            if ns <= row_targets[r]:
                                sums.add(ns)
                    suffix[idx] = sums

                if row_targets[r] not in suffix[0]:
                    return None

                prefix = {0}
                for idx, (i, vals) in enumerate(contrib_lists):
                    supported_heights = set()
                    for v, hs in vals.items():
                        need_set = suffix[idx + 1]
                        for p in prefix:
                            need = row_targets[r] - (p + v)
                            if need in need_set:
                                supported_heights.update(hs)
                                break
                    new_dom = domains[i] & supported_heights
                    if not new_dom:
                        return None
                    if new_dom != domains[i]:
                        domains[i] = new_dom
                        changed = True

                    new_prefix = set()
                    for p in prefix:
                        for v in vals:
                            ns = p + v
                            if ns <= row_targets[r]:
                                new_prefix.add(ns)
                    prefix = new_prefix

            if changed:
                continue

            # Same exact-sum support for columns
            for c in range(C):
                regs = col_regions[c]
                if not regs:
                    if col_targets[c] != 0:
                        return None
                    continue

                contrib_lists = []
                for i in regs:
                    vals = defaultdict(set)
                    for h in domains[i]:
                        vals[col_contrib(i, h, c)].add(h)
                    contrib_lists.append((i, vals))

                suffix = [set() for _ in range(len(regs) + 1)]
                suffix[len(regs)] = {0}
                for idx in range(len(regs) - 1, -1, -1):
                    _, vals = contrib_lists[idx]
                    sums = set()
                    for v in vals:
                        for s in suffix[idx + 1]:
                            ns = v + s
                            if ns <= col_targets[c]:
                                sums.add(ns)
                    suffix[idx] = sums

                if col_targets[c] not in suffix[0]:
                    return None

                prefix = {0}
                for idx, (i, vals) in enumerate(contrib_lists):
                    supported_heights = set()
                    for v, hs in vals.items():
                        need_set = suffix[idx + 1]
                        for p in prefix:
                            need = col_targets[c] - (p + v)
                            if need in need_set:
                                supported_heights.update(hs)
                                break
                    new_dom = domains[i] & supported_heights
                    if not new_dom:
                        return None
                    if new_dom != domains[i]:
                        domains[i] = new_dom
                        changed = True

                    new_prefix = set()
                    for p in prefix:
                        for v in vals:
                            ns = p + v
                            if ns <= col_targets[c]:
                                new_prefix.add(ns)
                    prefix = new_prefix

            if not changed:
                break

        return domains

    def select_branch_region(domains):
        # Most constrained region first, tie-break by largest impact on lines.
        best = None
        best_key = None
        for i, dom in enumerate(domains):
            if len(dom) <= 1:
                continue
            touched = len(set(r for r, _ in region_ordered_cells[i])) + len(set(c for _, c in region_ordered_cells[i]))
            key = (len(dom), -touched, -region_sizes[i], i)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def ordered_values(i, domains):
        # Least-commitment / clue-aligned value ordering:
        # prefer heights near the domain median and also those balancing total.
        vals = sorted(domains[i])
        return vals

    def is_complete(domains):
        return all(len(d) == 1 for d in domains)

    def build_answer(domains):
        height_of = [next(iter(domains[i])) for i in range(n_regions)]
        ans = [[None for _ in range(C)] for _ in range(R)]
        for i, h in enumerate(height_of):
            for idx, (r, c) in enumerate(region_ordered_cells[i]):
                if idx < h:
                    ans[r][c] = 'W'
        # Final verification
        for r in range(R):
            if sum(1 for c in range(C) if ans[r][c] == 'W') != row_targets[r]:
                return "No Solution"
        for c in range(C):
            if sum(1 for r in range(R) if ans[r][c] == 'W') != col_targets[c]:
                return "No Solution"
        return str(ans)

    def search(domains):
        domains = prune(domains)
        if domains is None:
            return None
        if is_complete(domains):
            return domains

        i = select_branch_region(domains)
        if i is None:
            return None

        for h in ordered_values(i, domains):
            nd = [set(d) for d in domains]
            nd[i] = {h}
            res = search(nd)
            if res is not None:
                return res
        return None

    if not feasible_totals(domains):
        return "No Solution"

    result = search(domains)
    if result is None:
        return "No Solution"
    return build_answer(result)


