from collections import deque

# Solver for the "count black cells in each numbered cell's 3x3 neighborhood" puzzle.
# Representation:
# - variable per cell: -1 unknown, 0 white, 1 black
# - each numbered clue creates a sum constraint over up to 9 variables


def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0
    n = h * w

    def idx(r, c):
        return r * w + c

    def rc(i):
        return divmod(i, w)

    # Build constraints from numbered cells
    constraints = []
    var_to_constraints = [[] for _ in range(n)]
    for r in range(h):
        for c in range(w):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    cells.append(idx(rr, cc))
            cid = len(constraints)
            constraints.append({"target": val, "vars": cells})
            for v in cells:
                var_to_constraints[v].append(cid)

    # For each constraint, maintain:
    # - black_assigned count
    # - unknown_count
    # - unknown bitset/list tracking through current assignment is handled by scanning vars;
    #   small constraints (<=9), so scanning is cheap and simple.
    assign = [-1] * n

    # Cached neighborhoods for variable scoring
    neighbors = [[] for _ in range(n)]
    for i in range(n):
        seen = set()
        for cid in var_to_constraints[i]:
            for v in constraints[cid]["vars"]:
                if v != i:
                    seen.add(v)
        neighbors[i] = list(seen)

    # Fast consistency + propagation
    def propagate(trail, initial_queue):
        q = deque(initial_queue)
        inq = [False] * len(constraints)
        for cid in initial_queue:
            inq[cid] = True

        while q:
            cid = q.popleft()
            inq[cid] = False
            con = constraints[cid]
            target = con["target"]
            vars_ = con["vars"]

            black = 0
            unknowns = []
            for v in vars_:
                a = assign[v]
                if a == 1:
                    black += 1
                elif a == -1:
                    unknowns.append(v)

            u = len(unknowns)
            if black > target or black + u < target:
                return False

            need = target - black
            if u == 0:
                if need != 0:
                    return False
                continue

            # Human-like forced deductions:
            # if all unknowns must be black
            if need == u:
                for v in unknowns:
                    if assign[v] == -1:
                        assign[v] = 1
                        trail.append(v)
                        for ncid in var_to_constraints[v]:
                            if not inq[ncid]:
                                q.append(ncid)
                                inq[ncid] = True
                    elif assign[v] != 1:
                        return False

            # if all unknowns must be white
            elif need == 0:
                for v in unknowns:
                    if assign[v] == -1:
                        assign[v] = 0
                        trail.append(v)
                        for ncid in var_to_constraints[v]:
                            if not inq[ncid]:
                                q.append(ncid)
                                inq[ncid] = True
                    elif assign[v] != 0:
                        return False

        return True

    # Additional pairwise/subset-style human deductions by comparing overlapping constraints.
    # For small puzzle sizes, we can derive "difference bounds" dynamically when branching.
    # This is not a SAT/ILP solver; it mirrors human region-comparison logic.
    #
    # If A subset B:
    #   sum(B\A) = targetB - targetA after accounting for assigned cells.
    # So B\A can become fully forced if that residual is 0 or all remaining in B\A.
    subset_pairs = []
    for i, ca in enumerate(constraints):
        sa = set(ca["vars"])
        for j, cb in enumerate(constraints):
            if i == j:
                continue
            sb = set(cb["vars"])
            if sa < sb:
                subset_pairs.append((i, j, list(sb - sa)))
    # Deduplicate useful pairs
    uniq = {}
    for a, b, diff in subset_pairs:
        uniq[(a, b)] = diff
    subset_pairs = [(a, b, diff) for (a, b), diff in uniq.items()]

    def propagate_subsets(trail):
        changed = True
        while changed:
            changed = False
            for a, b, diff in subset_pairs:
                ca = constraints[a]
                cb = constraints[b]

                black_a = unk_a = 0
                for v in ca["vars"]:
                    av = assign[v]
                    if av == 1:
                        black_a += 1
                    elif av == -1:
                        unk_a += 1

                black_b = unk_b = 0
                for v in cb["vars"]:
                    av = assign[v]
                    if av == 1:
                        black_b += 1
                    elif av == -1:
                        unk_b += 1

                if black_a > ca["target"] or black_a + unk_a < ca["target"]:
                    return False
                if black_b > cb["target"] or black_b + unk_b < cb["target"]:
                    return False

                # Residual possible sum on diff region:
                # exact relation only if all cells in A and B are considered with assignments;
                # target residual = (targetB - black(B∩assigned)) - (targetA - black(A∩assigned))
                # More directly:
                rem_a = ca["target"] - black_a
                rem_b = cb["target"] - black_b
                # unknowns in A and B contribute to rem_a and rem_b respectively.
                # Since A subset B, diff unknown contribution needed is rem_b - rem_a from cells in diff,
                # provided unknowns in A are shared in both counts.
                need_diff = rem_b - rem_a

                unknown_diff = [v for v in diff if assign[v] == -1]
                black_diff = sum(1 for v in diff if assign[v] == 1)

                need_unknown_diff = need_diff - black_diff
                if need_unknown_diff < 0 or need_unknown_diff > len(unknown_diff):
                    return False

                if unknown_diff:
                    if need_unknown_diff == 0:
                        for v in unknown_diff:
                            assign[v] = 0
                            trail.append(v)
                            changed = True
                    elif need_unknown_diff == len(unknown_diff):
                        for v in unknown_diff:
                            assign[v] = 1
                            trail.append(v)
                            changed = True

            if changed:
                q = []
                seen = set()
                for v in trail[-(sum(1 for _ in [])):]:
                    pass
                # Simpler: recheck all constraints after subset deductions.
                if not propagate(trail, list(range(len(constraints)))):
                    return False
        return True

    # Initial propagation from all clues
    trail = []
    if not propagate(trail, list(range(len(constraints)))):
        return "No Solution"
    if not propagate_subsets(trail):
        return "No Solution"

    # Branching heuristic:
    # choose variable with strongest involvement in nearly-tight constraints.
    def choose_var():
        best_v = -1
        best_score = None
        for v in range(n):
            if assign[v] != -1:
                continue
            score = 0
            tightness = 0
            for cid in var_to_constraints[v]:
                con = constraints[cid]
                black = 0
                unk = 0
                for u in con["vars"]:
                    a = assign[u]
                    if a == 1:
                        black += 1
                    elif a == -1:
                        unk += 1
                rem = con["target"] - black
                # Higher score for smaller uncertainty and stronger local effect
                score += 20 - unk
                if rem == 0 or rem == unk:
                    score += 100
                tightness += abs(2 * rem - unk)
            key = (score, tightness, len(var_to_constraints[v]), len(neighbors[v]))
            if best_score is None or key > best_score:
                best_score = key
                best_v = v
        return best_v

    def value_order(v):
        # Try the value that better satisfies nearby constraints.
        black_bias = 0
        white_bias = 0
        for cid in var_to_constraints[v]:
            con = constraints[cid]
            black = 0
            unk = 0
            for u in con["vars"]:
                a = assign[u]
                if a == 1:
                    black += 1
                elif a == -1:
                    unk += 1
            rem = con["target"] - black
            # if rem is large, black is favored; if small, white is favored
            black_bias += rem
            white_bias += unk - rem
        return (1, 0) if black_bias >= white_bias else (0, 1)

    def undo(tr):
        while tr:
            v = tr.pop()
            assign[v] = -1

    def dfs():
        v = choose_var()
        if v == -1:
            # fully assigned, verify all constraints exactly
            for con in constraints:
                total = 0
                for u in con["vars"]:
                    total += assign[u]
                if total != con["target"]:
                    return False
            return True

        for val in value_order(v):
            local_trail = []
            assign[v] = val
            local_trail.append(v)

            if propagate(local_trail, var_to_constraints[v]) and propagate_subsets(local_trail):
                if dfs():
                    return True

            undo(local_trail)

        return False

    if not dfs():
        return "No Solution"

    ans = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if assign[idx(r, c)] == 1 else None)
        ans.append(row)
    return str(ans)


