# General solver for the "3x3 black count" puzzle.
# A cell is either black ('B') or white (None).
# Each numbered cell states how many black cells appear in its own 3x3 neighborhood.

from copy import deepcopy

def neighborhood_cells(r, c, h, w):
    cells = []
    for rr in range(max(0, r - 1), min(h, r + 2)):
        for cc in range(max(0, c - 1), min(w, c + 2)):
            cells.append((rr, cc))
    return cells

def build_model(data):
    h = len(data)
    w = len(data[0]) if h else 0

    vars_list = [(r, c) for r in range(h) for c in range(w)]
    var_index = {cell: i for i, cell in enumerate(vars_list)}

    constraints = []
    cell_to_constraints = [[] for _ in range(h * w)]

    for r in range(h):
        for c in range(w):
            v = data[r][c]
            if v is None:
                continue
            cells = neighborhood_cells(r, c, h, w)
            idxs = [var_index[cell] for cell in cells]
            cid = len(constraints)
            constraints.append({
                'target': v,
                'vars': idxs,
            })
            for idx in idxs:
                cell_to_constraints[idx].append(cid)

    return h, w, vars_list, var_index, constraints, cell_to_constraints

def init_state(nvars, constraints):
    assignment = [-1] * nvars  # -1 unknown, 0 white, 1 black
    con_unknown = [len(con['vars']) for con in constraints]
    con_sum = [0] * len(constraints)
    return assignment, con_unknown, con_sum

def assign_var(idx, val, assignment, con_unknown, con_sum, cell_to_constraints, constraints, trail):
    cur = assignment[idx]
    if cur == val:
        return True
    if cur != -1:
        return False

    assignment[idx] = val
    trail.append(('var', idx))

    for cid in cell_to_constraints[idx]:
        con_unknown[cid] -= 1
        con_sum[cid] += val
        trail.append(('con', cid, val))

        target = constraints[cid]['target']
        s = con_sum[cid]
        u = con_unknown[cid]
        if s > target or s + u < target:
            return False
    return True

def undo(trail, assignment, con_unknown, con_sum):
    while trail:
        item = trail.pop()
        if item[0] == 'var':
            _, idx = item
            assignment[idx] = -1
        else:
            _, cid, val = item
            con_unknown[cid] += 1
            con_sum[cid] -= val

def propagate(assignment, con_unknown, con_sum, constraints, cell_to_constraints):
    ncons = len(constraints)
    changed = True
    while changed:
        changed = False

        for cid in range(ncons):
            target = constraints[cid]['target']
            s = con_sum[cid]
            u = con_unknown[cid]
            if s > target or s + u < target:
                return False

            if u == 0:
                if s != target:
                    return False
                continue

            need = target - s
            vars_in_con = constraints[cid]['vars']

            if need == 0:
                for idx in vars_in_con:
                    if assignment[idx] == -1:
                        if not assign_var(idx, 0, assignment, con_unknown, con_sum, cell_to_constraints, constraints, []):
                            return False
                        changed = True
            elif need == u:
                for idx in vars_in_con:
                    if assignment[idx] == -1:
                        if not assign_var(idx, 1, assignment, con_unknown, con_sum, cell_to_constraints, constraints, []):
                            return False
                        changed = True

        # Strengthened local pairwise human-like deduction:
        # If two constraints overlap, compare residual domains.
        # For A subset B:
        # residual(B\A) blacks = needB - needA when all residual(A) can match.
        # We derive forced cells when difference reaches min/max.
        for a in range(ncons):
            target_a = constraints[a]['target'] - con_sum[a]
            vars_a = [x for x in constraints[a]['vars'] if assignment[x] == -1]
            set_a = set(vars_a)
            ua = len(vars_a)

            if target_a < 0 or target_a > ua:
                return False

            for b in range(ncons):
                if a == b:
                    continue
                target_b = constraints[b]['target'] - con_sum[b]
                vars_b = [x for x in constraints[b]['vars'] if assignment[x] == -1]
                set_b = set(vars_b)
                ub = len(vars_b)

                if target_b < 0 or target_b > ub:
                    return False

                if not set_a or not set_b:
                    continue

                if set_a.issubset(set_b):
                    extra = list(set_b - set_a)
                    d = target_b - target_a
                    if d < 0 or d > len(extra):
                        return False
                    if d == 0:
                        for idx in extra:
                            if assignment[idx] == -1:
                                if not assign_var(idx, 0, assignment, con_unknown, con_sum, cell_to_constraints, constraints, []):
                                    return False
                                changed = True
                    elif d == len(extra):
                        for idx in extra:
                            if assignment[idx] == -1:
                                if not assign_var(idx, 1, assignment, con_unknown, con_sum, cell_to_constraints, constraints, []):
                                    return False
                                changed = True

    return True

def choose_branch_var(assignment, constraints, con_unknown, con_sum, cell_to_constraints):
    best_idx = None
    best_score = None

    for idx, val in enumerate(assignment):
        if val != -1:
            continue
        score = 0
        for cid in cell_to_constraints[idx]:
            # Prefer variables in tighter constraints.
            u = con_unknown[cid]
            need = constraints[cid]['target'] - con_sum[cid]
            score += 10 - u
            score += min(need, u - need)
        if best_score is None or score > best_score:
            best_score = score
            best_idx = idx
    return best_idx

def branch_order(idx, assignment, constraints, con_unknown, con_sum, cell_to_constraints):
    # Estimate whether black or white is more constrained.
    score_black = 0
    score_white = 0
    for cid in cell_to_constraints[idx]:
        target = constraints[cid]['target']
        s = con_sum[cid]
        u = con_unknown[cid]
        need = target - s
        # If assign black, residual need becomes need-1 over u-1 vars.
        rb = need - 1
        rw = need
        if 0 <= rb <= u - 1:
            score_black += min(rb, (u - 1) - rb)
        else:
            score_black -= 1000
        if 0 <= rw <= u - 1:
            score_white += min(rw, (u - 1) - rw)
        else:
            score_white -= 1000
    # Lower score first = tighter.
    if score_black <= score_white:
        return (1, 0)
    return (0, 1)

def search(assignment, con_unknown, con_sum, constraints, cell_to_constraints):
    if not propagate(assignment, con_unknown, con_sum, constraints, cell_to_constraints):
        return None

    if all(v != -1 for v in assignment):
        return assignment[:]

    idx = choose_branch_var(assignment, constraints, con_unknown, con_sum, cell_to_constraints)
    if idx is None:
        return assignment[:]

    for val in branch_order(idx, assignment, constraints, con_unknown, con_sum, cell_to_constraints):
        trail = []
        if assign_var(idx, val, assignment, con_unknown, con_sum, cell_to_constraints, constraints, trail):
            result = search(assignment, con_unknown, con_sum, constraints, cell_to_constraints)
            if result is not None:
                return result
        undo(trail, assignment, con_unknown, con_sum)

    return None

def format_answer(solution, h, w):
    out = []
    k = 0
    for _ in range(h):
        row = []
        for _ in range(w):
            row.append('B' if solution[k] == 1 else None)
            k += 1
        out.append(row)
    return str(out)

def solve(observation):
    data = observation['data']
    h, w, vars_list, var_index, constraints, cell_to_constraints = build_model(data)
    assignment, con_unknown, con_sum = init_state(h * w, constraints)
    result = search(assignment, con_unknown, con_sum, constraints, cell_to_constraints)
    if result is None:
        return "No Solution"
    return format_answer(result, h, w)

if __name__ == "__main__":
    print(solve(OBSERVATION))

