# Generalized Takuzu / Binairo solver using human-like deduction first,
# then tightly-pruned search only when needed.

from copy import deepcopy


B = 'B'
W = 'W'


def opposite(v):
    return B if v == W else W


def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    if n == 0:
        return []
    if any(len(row) != n for row in grid):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    if not is_consistent_grid(grid):
        return "No Solution"

    solved = search(grid)
    return solved if solved is not None else "No Solution"


def is_consistent_grid(grid):
    n = len(grid)
    half = n // 2

    # Given row/column local constraints
    for r in range(n):
        row = grid[r]
        if row.count(B) > half or row.count(W) > half:
            return False
        if has_triple(row):
            return False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if col.count(B) > half or col.count(W) > half:
            return False
        if has_triple(col):
            return False

    # Completed rows/cols must be unique
    complete_rows = {}
    for r in range(n):
        row = tuple(grid[r])
        if None not in row:
            if row in complete_rows:
                return False
            complete_rows[row] = r

    complete_cols = {}
    for c in range(n):
        col = tuple(grid[r][c] for r in range(n))
        if None not in col:
            if col in complete_cols:
                return False
            complete_cols[col] = c

    # Partial uniqueness pruning:
    # if two rows can still become identical and both are one move from being forced identical in contradiction, prune.
    # Strong but safe check: if a partial row already matches a completed row in all fixed positions and has no way to differ.
    completed_rows = [tuple(grid[r]) for r in range(n) if None not in grid[r]]
    for r in range(n):
        row = grid[r]
        if None in row:
            for crow in completed_rows:
                possible_equal = True
                for a, b in zip(row, crow):
                    if a is not None and a != b:
                        possible_equal = False
                        break
                if possible_equal:
                    # It is only invalid if all Nones are forced to equal by counts/triples? Hard to prove cheaply.
                    # So no rejection here.
                    pass

    completed_cols = [tuple(grid[r][c] for r in range(n)) for c in range(n) if all(grid[r][c] is not None for r in range(n))]
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if None in col:
            for ccol in completed_cols:
                possible_equal = True
                for a, b in zip(col, ccol):
                    if a is not None and a != b:
                        possible_equal = False
                        break
                if possible_equal:
                    pass

    return True


def has_triple(seq):
    for i in range(len(seq) - 2):
        a, b, c = seq[i], seq[i + 1], seq[i + 2]
        if a is not None and a == b == c:
            return True
    return False


def line_possibilities(line):
    n = len(line)
    half = n // 2
    out = []
    arr = [None] * n

    def rec(i, bcnt, wcnt):
        if bcnt > half or wcnt > half:
            return
        if i >= 3 and arr[i - 1] == arr[i - 2] == arr[i - 3]:
            return

        if i == n:
            if bcnt == half and wcnt == half:
                out.append(tuple(arr))
            return

        fixed = line[i]
        if fixed is not None:
            arr[i] = fixed
            rec(i + 1, bcnt + (fixed == B), wcnt + (fixed == W))
            arr[i] = None
            return

        # Value ordering can help but keep simple
        for v in (B, W):
            arr[i] = v
            rec(i + 1, bcnt + (v == B), wcnt + (v == W))
        arr[i] = None

    rec(0, 0, 0)
    return out


def row_patterns(grid, r):
    return line_possibilities(grid[r])


def col_patterns(grid, c):
    return line_possibilities([grid[r][c] for r in range(len(grid))])


def propagate(grid):
    n = len(grid)

    while True:
        changed = False

        if not is_consistent_grid(grid):
            return None

        # Basic local human rules on rows
        for r in range(n):
            row = grid[r]
            res = apply_local_line_rules(row)
            if res is None:
                return None
            if res:
                changed = True

        # Basic local human rules on columns
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            res = apply_local_line_rules(col)
            if res is None:
                return None
            if res:
                for r in range(n):
                    if grid[r][c] != col[r]:
                        grid[r][c] = col[r]
                        changed = True

        if not is_consistent_grid(grid):
            return None

        # Pattern-based deductions from all valid completions of each row
        for r in range(n):
            pats = row_patterns(grid, r)
            if not pats:
                return None

            # Uniqueness against completed other rows
            completed_others = {tuple(grid[rr]) for rr in range(n) if rr != r and None not in grid[rr]}
            pats = [p for p in pats if p not in completed_others]
            if not pats:
                return None

            for c in range(n):
                vals = {p[c] for p in pats}
                if len(vals) == 1 and grid[r][c] is None:
                    grid[r][c] = vals.pop()
                    changed = True

        # Pattern-based deductions from all valid completions of each column
        for c in range(n):
            pats = col_patterns(grid, c)
            if not pats:
                return None

            completed_others = {
                tuple(grid[r][cc] for r in range(n))
                for cc in range(n)
                if cc != c and all(grid[r][cc] is not None for r in range(n))
            }
            pats = [p for p in pats if p not in completed_others]
            if not pats:
                return None

            for r in range(n):
                vals = {p[r] for p in pats}
                if len(vals) == 1 and grid[r][c] is None:
                    grid[r][c] = vals.pop()
                    changed = True

        if not is_consistent_grid(grid):
            return None

        # Human-like uniqueness rule:
        # If a partial row differs from a completed row in all but one undecided place, that place is forced opposite.
        for r in range(n):
            if None not in grid[r]:
                continue
            row = grid[r]
            for rr in range(n):
                if rr == r or None in grid[rr]:
                    continue
                crow = grid[rr]
                unknowns = []
                conflict = False
                for c in range(n):
                    if row[c] is None:
                        unknowns.append(c)
                    elif row[c] != crow[c]:
                        conflict = True
                        break
                if conflict:
                    continue
                if len(unknowns) == 1:
                    c = unknowns[0]
                    forced = opposite(crow[c])
                    if grid[r][c] is None:
                        grid[r][c] = forced
                        changed = True
                    elif grid[r][c] != forced:
                        return None

        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if None not in col:
                continue
            for cc in range(n):
                if cc == c:
                    continue
                ccol = [grid[r][cc] for r in range(n)]
                if None in ccol:
                    continue
                unknowns = []
                conflict = False
                for r in range(n):
                    if grid[r][c] is None:
                        unknowns.append(r)
                    elif grid[r][c] != ccol[r]:
                        conflict = True
                        break
                if conflict:
                    continue
                if len(unknowns) == 1:
                    r = unknowns[0]
                    forced = opposite(ccol[r])
                    if grid[r][c] is None:
                        grid[r][c] = forced
                        changed = True
                    elif grid[r][c] != forced:
                        return None

        if not changed:
            break

    return grid


def apply_local_line_rules(line):
    n = len(line)
    changed = False
    half = n // 2

    # Rule: if two same adjacent, neighbors must be opposite
    for i in range(n - 1):
        if line[i] is not None and line[i] == line[i + 1]:
            v = opposite(line[i])
            if i - 1 >= 0:
                if line[i - 1] is None:
                    line[i - 1] = v
                    changed = True
                elif line[i - 1] != v:
                    return None
            if i + 2 < n:
                if line[i + 2] is None:
                    line[i + 2] = v
                    changed = True
                elif line[i + 2] != v:
                    return None

    # Rule: X ? X => middle opposite
    for i in range(n - 2):
        if line[i] is not None and line[i] == line[i + 2]:
            v = opposite(line[i])
            if line[i + 1] is None:
                line[i + 1] = v
                changed = True
            elif line[i + 1] != v:
                return None

    # Rule: counts
    bcnt = line.count(B)
    wcnt = line.count(W)
    if bcnt > half or wcnt > half:
        return None
    if bcnt == half:
        for i in range(n):
            if line[i] is None:
                line[i] = W
                changed = True
    if wcnt == half:
        for i in range(n):
            if line[i] is None:
                line[i] = B
                changed = True

    # Check no triples
    if has_triple(line):
        return None

    # Re-check counts
    if line.count(B) > half or line.count(W) > half:
        return None

    return changed


def is_solved(grid):
    n = len(grid)
    if any(None in row for row in grid):
        return False
    return is_consistent_grid(grid)


def choose_branch(grid):
    n = len(grid)

    best = None

    # Prefer row/col with fewest legal patterns > 1
    for r in range(n):
        if None in grid[r]:
            pats = row_patterns(grid, r)
            completed_others = {tuple(grid[rr]) for rr in range(n) if rr != r and None not in grid[rr]}
            pats = [p for p in pats if p not in completed_others]
            k = len(pats)
            if k == 0:
                return ('dead', None)
            if k > 1 and (best is None or k < best[0]):
                best = (k, ('row', r, pats))

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if None in col:
            pats = col_patterns(grid, c)
            completed_others = {
                tuple(grid[r][cc] for r in range(n))
                for cc in range(n)
                if cc != c and all(grid[r][cc] is not None for r in range(n))
            }
            pats = [p for p in pats if p not in completed_others]
            k = len(pats)
            if k == 0:
                return ('dead', None)
            if k > 1 and (best is None or k < best[0]):
                best = (k, ('col', c, pats))

    if best is not None:
        return best[1]

    # Fallback: choose a cell with minimal domain inferred from row/col patterns
    best_cell = None
    best_domain = None
    for r in range(n):
        rpats = None
        if None in grid[r]:
            rpats = row_patterns(grid, r)
            completed_others = {tuple(grid[rr]) for rr in range(n) if rr != r and None not in grid[rr]}
            rpats = [p for p in rpats if p not in completed_others]
            if not rpats:
                return ('dead', None)
        for c in range(n):
            if grid[r][c] is not None:
                continue
            if rpats is None:
                rpats = row_patterns(grid, r)
            row_vals = {p[c] for p in rpats}

            cpats = col_patterns(grid, c)
            completed_others = {
                tuple(grid[rr][cc] for rr in range(n))
                for cc in range(n)
                if cc != c and all(grid[rr][cc] is not None for rr in range(n))
            }
            cpats = [p for p in cpats if p not in completed_others]
            if not cpats:
                return ('dead', None)
            col_vals = {p[r] for p in cpats}

            domain = row_vals & col_vals
            if not domain:
                return ('dead', None)
            if best_domain is None or len(domain) < len(best_domain):
                best_domain = domain
                best_cell = (r, c, tuple(sorted(domain)))
                if len(domain) == 1:
                    return ('cell',) + best_cell

    if best_cell is None:
        return None
    return ('cell',) + best_cell


def search(grid):
    grid = deepcopy(grid)
    grid = propagate(grid)
    if grid is None:
        return None
    if is_solved(grid):
        return grid

    branch = choose_branch(grid)
    if branch is None:
        return grid if is_solved(grid) else None
    if branch[0] == 'dead':
        return None

    kind = branch[0]

    if kind == 'row':
        _, r, pats = branch
        # Try patterns with highest immediate agreement pressure first
        pats = sorted(pats, key=lambda p: score_pattern_row(grid, r, p), reverse=True)
        for p in pats:
            newg = deepcopy(grid)
            newg[r] = list(p)
            ans = search(newg)
            if ans is not None:
                return ans
        return None

    if kind == 'col':
        _, c, pats = branch
        pats = sorted(pats, key=lambda p: score_pattern_col(grid, c, p), reverse=True)
        for p in pats:
            newg = deepcopy(grid)
            for r in range(len(grid)):
                newg[r][c] = p[r]
            ans = search(newg)
            if ans is not None:
                return ans
        return None

    if kind == 'cell':
        _, r, c, domain = branch
        for v in domain:
            newg = deepcopy(grid)
            newg[r][c] = v
            ans = search(newg)
            if ans is not None:
                return ans
        return None

    return None


def score_pattern_row(grid, r, pat):
    score = 0
    n = len(grid)
    for c in range(n):
        if grid[r][c] is None:
            score += 1
            col = [grid[rr][c] for rr in range(n)]
            if col.count(pat[c]) == n // 2 - 1:
                score += 1
    return score


def score_pattern_col(grid, c, pat):
    score = 0
    n = len(grid)
    for r in range(n):
        if grid[r][c] is None:
            score += 1
            row = grid[r]
            if row.count(pat[r]) == n // 2 - 1:
                score += 1
    return score


