from collections import defaultdict, deque
import json


def solve(observation):
    data = observation["data"]
    n = len(data)

    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, data[r][c]))

    m = len(islands)
    if m == 0:
        return "{}"

    # Build candidate edges between nearest visible islands horizontally/vertically.
    edges = []
    edge_of_pair = {}
    neighbors = [[] for _ in range(m)]

    # Row visibility
    for r in range(n):
        cols = [c for c in range(len(data[r])) if data[r][c] is not None]
        cols.sort()
        for i in range(len(cols) - 1):
            c1, c2 = cols[i], cols[i + 1]
            a = pos_to_idx[(r, c1)]
            b = pos_to_idx[(r, c2)]
            idx = len(edges)
            edges.append({
                "u": a,
                "v": b,
                "cells": [(r, c) for c in range(c1 + 1, c2)],
                "ori": "H",
            })
            edge_of_pair[tuple(sorted((a, b)))] = idx
            neighbors[a].append(idx)
            neighbors[b].append(idx)

    # Column visibility
    for c in range(n):
        rows = [r for r in range(n) if data[r][c] is not None]
        rows.sort()
        for i in range(len(rows) - 1):
            r1, r2 = rows[i], rows[i + 1]
            a = pos_to_idx[(r1, c)]
            b = pos_to_idx[(r2, c)]
            idx = len(edges)
            edges.append({
                "u": a,
                "v": b,
                "cells": [(r, c) for r in range(r1 + 1, r2)],
                "ori": "V",
            })
            edge_of_pair[tuple(sorted((a, b)))] = idx
            neighbors[a].append(idx)
            neighbors[b].append(idx)

    ecount = len(edges)

    # Crossing relationships.
    cell_h = {}
    cell_v = {}
    for ei, e in enumerate(edges):
        if e["ori"] == "H":
            for cell in e["cells"]:
                cell_h[cell] = ei
        else:
            for cell in e["cells"]:
                cell_v[cell] = ei

    crossings = [set() for _ in range(ecount)]
    for cell in set(cell_h).intersection(cell_v):
        eh = cell_h[cell]
        ev = cell_v[cell]
        crossings[eh].add(ev)
        crossings[ev].add(eh)

    deg = [v for _, _, v in islands]

    # State arrays: for each edge count in {0,1,2,None unresolved}
    vals = [None] * ecount
    rem = deg[:]
    unresolved = [set(neighbors[i]) for i in range(m)]

    # Domains via min/max per edge
    lo = [0] * ecount
    hi = [2] * ecount

    # Human-like forced deductions with propagation.
    def set_edge(state, ei, value, queue):
        vals, rem, unresolved, lo, hi = state
        cur = vals[ei]
        if cur is not None:
            return cur == value
        if value < lo[ei] or value > hi[ei]:
            return False
        vals[ei] = value
        lo[ei] = value
        hi[ei] = value
        u = edges[ei]["u"]
        v = edges[ei]["v"]
        rem[u] -= value
        rem[v] -= value
        if rem[u] < 0 or rem[v] < 0:
            return False
        unresolved[u].discard(ei)
        unresolved[v].discard(ei)

        # Positive bridge blocks all crossings.
        if value > 0:
            for cj in crossings[ei]:
                if vals[cj] is None:
                    if hi[cj] == 0:
                        continue
                    hi[cj] = 0
                    if lo[cj] > hi[cj]:
                        return False
                    queue.append(("tighten", cj))
                elif vals[cj] > 0:
                    return False

        queue.append(("node", u))
        queue.append(("node", v))
        for cj in crossings[ei]:
            queue.append(("edge", cj))
        return True

    def tighten_hi(state, ei, new_hi, queue):
        vals, rem, unresolved, lo, hi = state
        if vals[ei] is not None:
            return vals[ei] <= new_hi
        if new_hi >= hi[ei]:
            return True
        hi[ei] = new_hi
        if lo[ei] > hi[ei]:
            return False
        queue.append(("edge", ei))
        u = edges[ei]["u"]
        v = edges[ei]["v"]
        queue.append(("node", u))
        queue.append(("node", v))
        return True

    def tighten_lo(state, ei, new_lo, queue):
        vals, rem, unresolved, lo, hi = state
        if vals[ei] is not None:
            return vals[ei] >= new_lo
        if new_lo <= lo[ei]:
            return True
        lo[ei] = new_lo
        if lo[ei] > hi[ei]:
            return False
        queue.append(("edge", ei))
        u = edges[ei]["u"]
        v = edges[ei]["v"]
        queue.append(("node", u))
        queue.append(("node", v))
        return True

    def apply_edge_local(state, ei, queue):
        vals, rem, unresolved, lo, hi = state
        if vals[ei] is not None:
            return True
        u = edges[ei]["u"]
        v = edges[ei]["v"]

        # Endpoint capacity limits.
        cap = min(2, rem[u], rem[v])
        if not tighten_hi(state, ei, cap, queue):
            return False

        # If any crossing edge already positive, this edge must be zero.
        for cj in crossings[ei]:
            if vals[cj] is not None and vals[cj] > 0:
                return set_edge(state, ei, 0, queue)

        # If domain collapses, assign.
        if lo[ei] == hi[ei]:
            return set_edge(state, ei, lo[ei], queue)
        return True

    def apply_node_local(state, i, queue):
        vals, rem, unresolved, lo, hi = state
        if rem[i] < 0:
            return False
        incident = list(unresolved[i])
        if rem[i] == 0:
            for ei in incident:
                if not set_edge(state, ei, 0, queue):
                    return False
            return True
        if not incident:
            return rem[i] == 0

        mins = 0
        maxs = 0
        for ei in incident:
            mins += lo[ei]
            maxs += hi[ei]
        if rem[i] < mins or rem[i] > maxs:
            return False

        # Exact fill / full saturation.
        if rem[i] == mins:
            for ei in incident:
                if not set_edge(state, ei, lo[ei], queue):
                    return False
            return True
        if rem[i] == maxs:
            for ei in incident:
                if not set_edge(state, ei, hi[ei], queue):
                    return False
            return True

        # Per-edge lower/upper forcing from sum constraints.
        for ei in incident:
            other_min = mins - lo[ei]
            other_max = maxs - hi[ei]
            need_lo = rem[i] - other_max
            need_hi = rem[i] - other_min
            if need_lo > lo[ei]:
                if not tighten_lo(state, ei, need_lo, queue):
                    return False
            if need_hi < hi[ei]:
                if not tighten_hi(state, ei, need_hi, queue):
                    return False

        # Single-bridge island of degree 1 must connect exactly one bridge on its only edge.
        if len(incident) == 1:
            ei = incident[0]
            return set_edge(state, ei, rem[i], queue)

        # If rem is 1, all incident edges upper bounded except one possibility can force zeros/one.
        # Generalized by subset-free arithmetic above; keep a simple strong rule:
        positive_candidates = [ei for ei in incident if hi[ei] > 0]
        if rem[i] == 1 and len(positive_candidates) == 1:
            if not set_edge(state, positive_candidates[0], 1, queue):
                return False

        return True

    def connected_possible(state):
        vals, rem, unresolved, lo, hi = state

        # Components using edges that can still be positive or already positive.
        g = [[] for _ in range(m)]
        for ei, e in enumerate(edges):
            if vals[ei] is not None:
                if vals[ei] > 0:
                    g[e["u"]].append(e["v"])
                    g[e["v"]].append(e["u"])
            else:
                if hi[ei] > 0:
                    g[e["u"]].append(e["v"])
                    g[e["v"]].append(e["u"])

        seen = [False] * m
        comps = 0
        for i in range(m):
            if not seen[i]:
                comps += 1
                dq = [i]
                seen[i] = True
                while dq:
                    x = dq.pop()
                    for y in g[x]:
                        if not seen[y]:
                            seen[y] = True
                            dq.append(y)
        return comps == 1

    def final_connected(state):
        vals, rem, unresolved, lo, hi = state
        g = [[] for _ in range(m)]
        for ei, e in enumerate(edges):
            if vals[ei] == 1 or vals[ei] == 2:
                g[e["u"]].append(e["v"])
                g[e["v"]].append(e["u"])
        seen = [False] * m
        dq = [0]
        seen[0] = True
        while dq:
            x = dq.pop()
            for y in g[x]:
                if not seen[y]:
                    seen[y] = True
                    dq.append(y)
        return all(seen)

    def propagate(state):
        queue = deque()
        for i in range(m):
            queue.append(("node", i))
        for ei in range(ecount):
            queue.append(("edge", ei))

        while queue:
            typ, idx = queue.popleft()
            if typ == "node":
                if not apply_node_local(state, idx, queue):
                    return False
            elif typ == "edge":
                if not apply_edge_local(state, idx, queue):
                    return False
            else:  # tighten marker
                if not apply_edge_local(state, idx, queue):
                    return False

        # Global possibility check.
        if any(r < 0 for r in state[1]):
            return False
        if not connected_possible(state):
            return False

        # No isolated satisfied subgraph before all edges decided:
        # if a component already closed off from the rest by all zero/forbidden edges, impossible.
        if not bridge_components_can_merge(state):
            return False

        return True

    def bridge_components_can_merge(state):
        vals, rem, unresolved, lo, hi = state

        # Components formed by currently positive bridges.
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        for ei, e in enumerate(edges):
            if vals[ei] is not None and vals[ei] > 0:
                union(e["u"], e["v"])

        comps = defaultdict(list)
        for i in range(m):
            comps[find(i)].append(i)
        if len(comps) == 1:
            return True

        # Build graph between positive-components using undecided/possible positive edges.
        cg = defaultdict(set)
        keys = list(comps.keys())
        for ei, e in enumerate(edges):
            possible = (vals[ei] is None and hi[ei] > 0) or (vals[ei] is not None and vals[ei] > 0)
            if not possible:
                continue
            a = find(e["u"])
            b = find(e["v"])
            if a != b:
                cg[a].add(b)
                cg[b].add(a)

        start = keys[0]
        seen = {start}
        dq = [start]
        while dq:
            x = dq.pop()
            for y in cg[x]:
                if y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(keys)

    def solved(state):
        vals, rem, unresolved, lo, hi = state
        if any(r != 0 for r in rem):
            return False
        if any(v is None for v in vals):
            return False
        return final_connected(state)

    def clone_state(state):
        vals, rem, unresolved, lo, hi = state
        return (
            vals[:],
            rem[:],
            [set(s) for s in unresolved],
            lo[:],
            hi[:],
        )

    def score_edge(state, ei):
        vals, rem, unresolved, lo, hi = state
        if vals[ei] is not None:
            return -1
        u = edges[ei]["u"]
        v = edges[ei]["v"]
        domain = hi[ei] - lo[ei] + 1
        cross = len(crossings[ei])
        pressure = rem[u] + rem[v]
        # Smaller domain first, then more crossings, then tighter endpoints.
        return (10 - domain) * 100 + cross * 10 + pressure

    def search(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        # Choose most constrained unresolved edge.
        best_ei = None
        best_score = None
        for ei in range(ecount):
            if state[0][ei] is None:
                s = score_edge(state, ei)
                if best_score is None or s > best_score:
                    best_score = s
                    best_ei = ei
        if best_ei is None:
            return None

        lo_v = state[3][best_ei]
        hi_v = state[4][best_ei]

        # Try human-like preference: if an endpoint is tight, higher counts first, else lower first.
        u = edges[best_ei]["u"]
        v = edges[best_ei]["v"]
        prefer_high = (state[1][u] >= sum(state[4][e] for e in state[2][u]) - 1) or (
            state[1][v] >= sum(state[4][e] for e in state[2][v]) - 1
        )
        values = list(range(lo_v, hi_v + 1))
        if prefer_high:
            values.reverse()

        for val in values:
            st2 = clone_state(state)
            q = deque()
            if set_edge(st2, best_ei, val, q):
                # run queued local implications immediately
                while q:
                    typ, idx = q.popleft()
                    if typ == "node":
                        if not apply_node_local(st2, idx, q):
                            break
                    elif typ == "edge":
                        if not apply_edge_local(st2, idx, q):
                            break
                    else:
                        if not apply_edge_local(st2, idx, q):
                            break
                else:
                    res = search(st2)
                    if res is not None:
                        return res
        return None

    initial = (vals, rem, unresolved, lo, hi)
    result = search(initial)
    if result is None:
        return "No Solution"

    vals = result[0]
    answer = {}
    for ei, count in enumerate(vals):
        if count and count > 0:
            u = edges[ei]["u"]
            v = edges[ei]["v"]
            p1 = (islands[u][0], islands[u][1])
            p2 = (islands[v][0], islands[v][1])
            if p1 > p2:
                p1, p2 = p2, p1
            answer[(p1, p2)] = count

    return json.dumps(
        {str(k): v for k, v in sorted(answer.items(), key=lambda kv: kv[0])},
        separators=(",", ":")
    )


