    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, None, None, 'W', 'W', None, None, 'B'], ['W', None, 'B', None, None, 'W', 'W', None], ['W', None, None, None, None, 'W', None, None], [None, None, None, 'B', None, None, None, None], [None, None, 'W', None, None, None, 'B', None], [None, None, None, None, None, None, None, 'B'], [None, None, 'W', None, 'W', 'W', None, None]]}

# Takuzu / Binairo solver using human-like deduction first, then tightly-pruned search.

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    if n == 0:
        return []
    m = len(grid[0])
    if n != m or n % 2 != 0:
        return "No Solution"

    HALF = n // 2
    VALS = ('B', 'W')

    def opp(v):
        return 'W' if v == 'B' else 'B'

    def row_counts(r):
        b = w = u = 0
        row = grid[r]
        for x in row:
            if x == 'B':
                b += 1
            elif x == 'W':
                w += 1
            else:
                u += 1
        return b, w, u

    def col_counts(c):
        b = w = u = 0
        for r in range(n):
            x = grid[r][c]
            if x == 'B':
                b += 1
            elif x == 'W':
                w += 1
            else:
                u += 1
        return b, w, u

    def line_has_triple(line):
        for i in range(len(line) - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]
            if a is not None and a == b == c:
                return True
        return False

    def partial_line_ok(line):
        cnt_b = sum(1 for x in line if x == 'B')
        cnt_w = sum(1 for x in line if x == 'W')
        cnt_u = sum(1 for x in line if x is None)
        if cnt_b > HALF or cnt_w > HALF:
            return False
        if cnt_b + cnt_u < HALF or cnt_w + cnt_u < HALF:
            return False
        if line_has_triple(line):
            return False
        return True

    def all_rows_cols_basic_ok():
        for r in range(n):
            if not partial_line_ok(grid[r]):
                return False
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if not partial_line_ok(col):
                return False
        return True

    def uniqueness_partial_ok():
        # Completed rows/cols must be unique; near-complete rows/cols can force cells.
        completed_rows = {}
        for r in range(n):
            row = tuple(grid[r])
            if None not in row:
                if row in completed_rows:
                    return False
                completed_rows[row] = r

        completed_cols = {}
        for c in range(n):
            col = tuple(grid[r][c] for r in range(n))
            if None not in col:
                if col in completed_cols:
                    return False
                completed_cols[col] = c

        # Two partial rows cannot both become equal if one is complete and the other has no flexibility
        for r1 in range(n):
            row1 = grid[r1]
            for r2 in range(r1 + 1, n):
                row2 = grid[r2]
                possible_equal = True
                for a, b in zip(row1, row2):
                    if a is not None and b is not None and a != b:
                        possible_equal = False
                        break
                if not possible_equal:
                    continue
                # If both are complete or one is complete and all unknowns in the other are forced equal, reject only when actually equal complete.
                if None not in row1 and None not in row2 and tuple(row1) == tuple(row2):
                    return False

        for c1 in range(n):
            col1 = [grid[r][c1] for r in range(n)]
            for c2 in range(c1 + 1, n):
                col2 = [grid[r][c2] for r in range(n)]
                possible_equal = True
                for a, b in zip(col1, col2):
                    if a is not None and b is not None and a != b:
                        possible_equal = False
                        break
                if not possible_equal:
                    continue
                if None not in col1 and None not in col2 and tuple(col1) == tuple(col2):
                    return False
        return True

    def can_place(r, c, v):
        old = grid[r][c]
        grid[r][c] = v

        row = grid[r]
        if not partial_line_ok(row):
            grid[r][c] = old
            return False

        col = [grid[i][c] for i in range(n)]
        if not partial_line_ok(col):
            grid[r][c] = old
            return False

        # Uniqueness check for completed rows/cols
        if None not in row:
            t = tuple(row)
            for rr in range(n):
                if rr != r and None not in grid[rr] and tuple(grid[rr]) == t:
                    grid[r][c] = old
                    return False

        if None not in col:
            t = tuple(col)
            for cc in range(n):
                if cc != c:
                    other = tuple(grid[i][cc] for i in range(n))
                    if None not in other and other == t:
                        grid[r][c] = old
                        return False

        grid[r][c] = old
        return True

    def set_cell(r, c, v, queue):
        cur = grid[r][c]
        if cur is not None:
            return cur == v
        if not can_place(r, c, v):
            return False
        grid[r][c] = v
        queue.append(('row', r))
        queue.append(('col', c))
        return True

    def apply_local_patterns_line(line_get, line_len, idx, queue, is_row):
        changed = False
        vals = [line_get(i) for i in range(line_len)]

        # Rule: XX_ -> XXO, _XX -> OXX, X_X -> XOX
        for i in range(line_len - 2):
            a, b, c = vals[i], vals[i + 1], vals[i + 2]
            if a is not None and a == b and c is None:
                r, cc = (idx, i + 2) if is_row else (i + 2, idx)
                if not set_cell(r, cc, opp(a), queue):
                    return None
                vals[i + 2] = opp(a)
                changed = True
            if a is None and b is not None and b == c:
                r, cc = (idx, i) if is_row else (i, idx)
                if not set_cell(r, cc, opp(b), queue):
                    return None
                vals[i] = opp(b)
                changed = True
            if a is not None and c is not None and a == c and b is None:
                r, cc = (idx, i + 1) if is_row else (i + 1, idx)
                if not set_cell(r, cc, opp(a), queue):
                    return None
                vals[i + 1] = opp(a)
                changed = True

        # Rule: count balance
        cnt_b = sum(1 for x in vals if x == 'B')
        cnt_w = sum(1 for x in vals if x == 'W')
        if cnt_b > HALF or cnt_w > HALF:
            return None
        if cnt_b == HALF:
            for i, x in enumerate(vals):
                if x is None:
                    r, cc = (idx, i) if is_row else (i, idx)
                    if not set_cell(r, cc, 'W', queue):
                        return None
                    changed = True
        elif cnt_w == HALF:
            for i, x in enumerate(vals):
                if x is None:
                    r, cc = (idx, i) if is_row else (i, idx)
                    if not set_cell(r, cc, 'B', queue):
                        return None
                    changed = True

        return changed

    def apply_uniqueness_for_rows(queue):
        changed = False
        complete_rows = [(r, tuple(grid[r])) for r in range(n) if None not in grid[r]]
        for r in range(n):
            row = grid[r]
            if row.count(None) != 2:
                continue
            unknowns = [i for i, x in enumerate(row) if x is None]
            for rr, full in complete_rows:
                if rr == r:
                    continue
                mismatches = []
                compatible = True
                for c in range(n):
                    if row[c] is not None and row[c] != full[c]:
                        compatible = False
                        break
                    if row[c] is None:
                        mismatches.append(c)
                if compatible and len(mismatches) == 2:
                    c1, c2 = mismatches
                    # Cannot match full row exactly, so at least one differs.
                    # If one value is forced to match by balance or triple, this often resolves through can_place checks.
                    for c in (c1, c2):
                        need = full[c]
                        forbid = need
                        allow = opp(need)
                        if can_place(r, c, allow) and not can_place(r, c, forbid):
                            if not set_cell(r, c, allow, queue):
                                return None
                            changed = True
        return changed

    def apply_uniqueness_for_cols(queue):
        changed = False
        complete_cols = []
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if None not in col:
                complete_cols.append((c, tuple(col)))
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if col.count(None) != 2:
                continue
            unknowns = [i for i, x in enumerate(col) if x is None]
            for cc, full in complete_cols:
                if cc == c:
                    continue
                mismatches = []
                compatible = True
                for r in range(n):
                    if col[r] is not None and col[r] != full[r]:
                        compatible = False
                        break
                    if col[r] is None:
                        mismatches.append(r)
                if compatible and len(mismatches) == 2:
                    r1, r2 = mismatches
                    for r in (r1, r2):
                        need = full[r]
                        forbid = need
                        allow = opp(need)
                        if can_place(r, c, allow) and not can_place(r, c, forbid):
                            if not set_cell(r, c, allow, queue):
                                return None
                            changed = True
        return changed

    def propagate():
        if not all_rows_cols_basic_ok() or not uniqueness_partial_ok():
            return False
        queue = []
        for r in range(n):
            queue.append(('row', r))
        for c in range(n):
            queue.append(('col', c))

        while queue:
            typ, idx = queue.pop()
            if typ == 'row':
                res = apply_local_patterns_line(lambda j: grid[idx][j], n, idx, queue, True)
                if res is None:
                    return False
                res2 = apply_uniqueness_for_rows(queue)
                if res2 is None:
                    return False
            else:
                res = apply_local_patterns_line(lambda i: grid[i][idx], n, idx, queue, False)
                if res is None:
                    return False
                res2 = apply_uniqueness_for_cols(queue)
                if res2 is None:
                    return False

            if not all_rows_cols_basic_ok() or not uniqueness_partial_ok():
                return False
        return True

    def candidates_for_cell(r, c):
        if grid[r][c] is not None:
            return [grid[r][c]]
        poss = []
        for v in VALS:
            if can_place(r, c, v):
                poss.append(v)
        return poss

    def choose_branch_cell():
        best = None
        best_score = None
        for r in range(n):
            row_unknown = grid[r].count(None)
            for c in range(n):
                if grid[r][c] is None:
                    poss = candidates_for_cell(r, c)
                    if not poss:
                        return (r, c, [])
                    # Higher pressure score: fewer candidates, fuller row/col
                    col_unknown = sum(1 for i in range(n) if grid[i][c] is None)
                    score = (len(poss), row_unknown + col_unknown)
                    if best is None or score < best_score:
                        best = (r, c, poss)
                        best_score = score
                        if len(poss) == 1:
                            return best
        return best

    def is_solved():
        for r in range(n):
            if None in grid[r]:
                return False
        if not all_rows_cols_basic_ok() or not uniqueness_partial_ok():
            return False
        return True

    def snapshot():
        return [row[:] for row in grid]

    def restore(state):
        for r in range(n):
            grid[r][:] = state[r]

    def dfs():
        if not propagate():
            return False
        if is_solved():
            return True

        choice = choose_branch_cell()
        if choice is None:
            return False
        r, c, poss = choice
        if not poss:
            return False

        # Prefer value that better balances row/col.
        rb, rw, _ = row_counts(r)
        cb, cw, _ = col_counts(c)

        def pref(v):
            score = 0
            if v == 'B':
                score += abs((rb + 1) - HALF) + abs((cb + 1) - HALF)
            else:
                score += abs((rw + 1) - HALF) + abs((cw + 1) - HALF)
            return score

        poss = sorted(poss, key=pref)

        state = snapshot()
        for v in poss:
            if can_place(r, c, v):
                grid[r][c] = v
                if dfs():
                    return True
                restore(state)
        return False

    if dfs():
        return [row[:] for row in grid]
    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 0, 0, 0, 1, 1, 2, 2], [3, 3, 0, 0, 0, 0, 4, 1, 2, 2], [5, 3, 3, 0, 0, 4, 4, 1, 2, 2], [5, 5, 5, 0, 0, 0, 1, 1, 2, 2], [5, 6, 0, 0, 7, 7, 1, 2, 2, 2], [5, 6, 6, 6, 6, 8, 1, 2, 2, 2], [5, 5, 9, 9, 8, 8, 2, 2, 2, 10], [11, 11, 9, 9, 12, 12, 12, 2, 2, 10], [11, 9, 9, 13, 13, 13, 2, 2, 10, 10], [11, 11, 9, 9, 14, 14, 14, 10, 10, 15]], 'row_water_counts': [6, 7, 7, 8, 6, 6, 2, 6, 8, 8], 'col_water_counts': [9, 7, 6, 7, 9, 8, 8, 4, 3, 3]}

from copy import deepcopy

def solve(observation):
    region_grid = observation['region']
    row_target = observation['row_water_counts']
    col_target = observation['col_water_counts']

    R = len(region_grid)
    C = len(region_grid[0])

    # Build region cell lists and vertical spans.
    region_cells = {}
    for r in range(R):
        for c in range(C):
            rid = region_grid[r][c]
            region_cells.setdefault(rid, []).append((r, c))

    regions = sorted(region_cells)
    reg_index = {rid: i for i, rid in enumerate(regions)}

    # For each region, map row -> cells in that row.
    reg_rows = {}
    reg_row_order = {}
    reg_prefix_counts = {}
    reg_possible_levels = {}
    cell_to_region = [[reg_index[region_grid[r][c]] for c in range(C)] for r in range(R)]

    for rid in regions:
        cells = region_cells[rid]
        row_map = {}
        for r, c in cells:
            row_map.setdefault(r, []).append(c)
        rows = sorted(row_map)
        reg_rows[rid] = row_map
        reg_row_order[rid] = rows

        # A legal water assignment for a region is determined by a "cut row":
        # choose k rows from the bottom among the region's occupied rows; all cells
        # in those rows are water, all above are dry. This matches the rule that
        # water in a region forms a bottom-up stack with a single level.
        prefix = [0]
        for r in reversed(rows):
            prefix.append(prefix[-1] + len(row_map[r]))
        reg_prefix_counts[rid] = prefix
        reg_possible_levels[rid] = set(range(len(rows) + 1))

    NREG = len(regions)

    # Contribution tables:
    # contrib_rows[reg][level][r] = # water cells in row r if region reg uses level
    # contrib_cols[reg][level][c] = # water cells in col c if region reg uses level
    contrib_rows = []
    contrib_cols = []
    level_sizes = []
    for rid in regions:
        rows = reg_row_order[rid]
        row_map = reg_rows[rid]
        levels_r = []
        levels_c = []
        sizes = []
        for k in range(len(rows) + 1):
            rr = [0] * R
            cc = [0] * C
            for r in rows[-k:] if k else []:
                rr[r] = len(row_map[r])
                for c in row_map[r]:
                    cc[c] += 1
            levels_r.append(rr)
            levels_c.append(cc)
            sizes.append(sum(rr))
        contrib_rows.append(levels_r)
        contrib_cols.append(levels_c)
        level_sizes.append(sizes)

    # Domains: each region -> set(levels)
    domains = [set(reg_possible_levels[rid]) for rid in regions]

    # Utility: compute row/col min-max from current domains.
    def bounds(domains):
        row_min = [0] * R
        row_max = [0] * R
        col_min = [0] * C
        col_max = [0] * C
        for i in range(NREG):
            dr = domains[i]
            # Since all contributions are nonnegative and independent, min/max per row/col
            # can be taken over allowed levels for each region.
            rows_min = [10**9] * R
            rows_max = [0] * R
            cols_min = [10**9] * C
            cols_max = [0] * C
            for lv in dr:
                rr = contrib_rows[i][lv]
                cc = contrib_cols[i][lv]
                for r in range(R):
                    v = rr[r]
                    if v < rows_min[r]:
                        rows_min[r] = v
                    if v > rows_max[r]:
                        rows_max[r] = v
                for c in range(C):
                    v = cc[c]
                    if v < cols_min[c]:
                        cols_min[c] = v
                    if v > cols_max[c]:
                        cols_max[c] = v
            for r in range(R):
                row_min[r] += rows_min[r]
                row_max[r] += rows_max[r]
            for c in range(C):
                col_min[c] += cols_min[c]
                col_max[c] += cols_max[c]
        return row_min, row_max, col_min, col_max

    def feasible(domains):
        row_min, row_max, col_min, col_max = bounds(domains)
        for r in range(R):
            if not (row_min[r] <= row_target[r] <= row_max[r]):
                return False
        for c in range(C):
            if not (col_min[c] <= col_target[c] <= col_max[c]):
                return False
        return True

    def prune(domains):
        # Repeated human-like propagation:
        # remove any region level that makes some row/col impossible.
        changed = True
        while changed:
            changed = False

            if not feasible(domains):
                return None

            # Singleton consequences can tighten all row/col ranges.
            row_min, row_max, col_min, col_max = bounds(domains)

            # For each region level, test local support against row/col residual bounds.
            for i in range(NREG):
                if len(domains[i]) == 1:
                    continue

                remove = set()
                other_domains = domains

                # Precompute bounds excluding region i
                ex_row_min = row_min[:]
                ex_row_max = row_max[:]
                ex_col_min = col_min[:]
                ex_col_max = col_max[:]

                # subtract this region's current aggregate min/max contribution
                rows_min_i = [10**9] * R
                rows_max_i = [0] * R
                cols_min_i = [10**9] * C
                cols_max_i = [0] * C
                for lv in other_domains[i]:
                    rr = contrib_rows[i][lv]
                    cc = contrib_cols[i][lv]
                    for r in range(R):
                        v = rr[r]
                        if v < rows_min_i[r]:
                            rows_min_i[r] = v
                        if v > rows_max_i[r]:
                            rows_max_i[r] = v
                    for c in range(C):
                        v = cc[c]
                        if v < cols_min_i[c]:
                            cols_min_i[c] = v
                        if v > cols_max_i[c]:
                            cols_max_i[c] = v

                for r in range(R):
                    ex_row_min[r] -= rows_min_i[r]
                    ex_row_max[r] -= rows_max_i[r]
                for c in range(C):
                    ex_col_min[c] -= cols_min_i[c]
                    ex_col_max[c] -= cols_max_i[c]

                for lv in list(domains[i]):
                    rr = contrib_rows[i][lv]
                    cc = contrib_cols[i][lv]
                    ok = True
                    for r in range(R):
                        need = row_target[r] - rr[r]
                        if need < ex_row_min[r] or need > ex_row_max[r]:
                            ok = False
                            break
                    if ok:
                        for c in range(C):
                            need = col_target[c] - cc[c]
                            if need < ex_col_min[c] or need > ex_col_max[c]:
                                ok = False
                                break
                    if not ok:
                        remove.add(lv)

                if remove:
                    domains[i] -= remove
                    if not domains[i]:
                        return None
                    changed = True

            if not feasible(domains):
                return None

        return domains

    def is_solved(domains):
        return all(len(d) == 1 for d in domains)

    def construct_grid(domains):
        ans = [[None for _ in range(C)] for _ in range(R)]
        for i, rid in enumerate(regions):
            lv = next(iter(domains[i]))
            rows = reg_row_order[rid]
            water_rows = set(rows[-lv:] if lv else [])
            for r, c in region_cells[rid]:
                if r in water_rows:
                    ans[r][c] = 'W'
        return ans

    def exact_check(grid):
        for r in range(R):
            if sum(1 for c in range(C) if grid[r][c] == 'W') != row_target[r]:
                return False
        for c in range(C):
            if sum(1 for r in range(R) if grid[r][c] == 'W') != col_target[c]:
                return False
        return True

    def search(domains):
        domains = prune([set(d) for d in domains])
        if domains is None:
            return None
        if is_solved(domains):
            grid = construct_grid(domains)
            if exact_check(grid):
                return grid
            return None

        # Choose most constrained region, tie-break by largest impact range.
        best_i = None
        best_key = None
        for i, d in enumerate(domains):
            if len(d) > 1:
                impact = max(level_sizes[i][lv] for lv in d) - min(level_sizes[i][lv] for lv in d)
                key = (len(d), -impact, i)
                if best_key is None or key < best_key:
                    best_key = key
                    best_i = i

        # Try levels in an informed order: larger levels first if total remaining water is high.
        row_min, row_max, col_min, col_max = bounds(domains)
        remaining_water_est = sum(row_target)
        order = sorted(domains[best_i], key=lambda lv: -level_sizes[best_i][lv])

        for lv in order:
            new_domains = [set(d) for d in domains]
            new_domains[best_i] = {lv}
            result = search(new_domains)
            if result is not None:
                return result
        return None

    grid = search(domains)
    if grid is None:
        return "No Solution"
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None, None, None], [None, -1, 3, None, -1, None, None, -1, -1, None], [None, -1, None, -1, None, None, None, None, 0, None], [None, None, None, None, None, None, None, 2, None, None], [None, None, None, None, None, None, None, None, -1, None], [None, -1, None, None, None, None, None, None, None, None], [None, None, 3, None, None, None, None, None, None, None], [None, -1, None, None, None, None, 1, None, -1, None], [None, 0, 1, None, None, 1, None, 1, 0, None], [None, None, None, None, None, None, None, None, None, None]]}

# Akari / Light Up solver with strong human-like deduction and constrained search.
# Board encoding in observation['data']:
#   None -> white cell
#   -1   -> black unnumbered cell
#   0..4 -> black numbered cell

from copy import deepcopy

BULB = 1
NOBULB = -1
UNKNOWN = 0


def solve(observation):
    board = observation["data"]
    n = len(board)
    if n == 0:
        return "[]"
    m = len(board[0])

    white_cells = []
    white_index = {}
    black_numbered = []
    is_black = [[False] * m for _ in range(n)]

    for r in range(n):
        for c in range(m):
            v = board[r][c]
            if v is None:
                white_index[(r, c)] = len(white_cells)
                white_cells.append((r, c))
            else:
                is_black[r][c] = True
                if v != -1:
                    black_numbered.append((r, c, v))

    wcount = len(white_cells)

    # Visibility segments: maximal white runs in rows/cols separated by black cells.
    row_segments = []
    row_seg_of = {}
    for r in range(n):
        c = 0
        while c < m:
            if board[r][c] is None:
                seg = []
                while c < m and board[r][c] is None:
                    seg.append((r, c))
                    c += 1
                sid = len(row_segments)
                row_segments.append(seg)
                for cell in seg:
                    row_seg_of[cell] = sid
            else:
                c += 1

    col_segments = []
    col_seg_of = {}
    for c in range(m):
        r = 0
        while r < n:
            if board[r][c] is None:
                seg = []
                while r < n and board[r][c] is None:
                    seg.append((r, c))
                    r += 1
                sid = len(col_segments)
                col_segments.append(seg)
                for cell in seg:
                    col_seg_of[cell] = sid
            else:
                r += 1

    # For each white cell, collect all visible cells including itself.
    visible = [[] for _ in range(wcount)]
    for idx, cell in enumerate(white_cells):
        rs = row_segments[row_seg_of[cell]]
        cs = col_segments[col_seg_of[cell]]
        s = []
        seen = set()
        for x in rs:
            if x not in seen:
                s.append(white_index[x])
                seen.add(x)
        for x in cs:
            if x not in seen:
                s.append(white_index[x])
                seen.add(x)
        visible[idx] = s

    # Segment membership by white index.
    row_seg_cells_idx = [[white_index[cell] for cell in seg] for seg in row_segments]
    col_seg_cells_idx = [[white_index[cell] for cell in seg] for seg in col_segments]

    # Numbered black adjacency.
    clue_neighbors = []
    clues = []
    cell_to_clues = [[] for _ in range(wcount)]
    for br, bc, num in black_numbered:
        neigh = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = br + dr, bc + dc
            if 0 <= nr < n and 0 <= nc < m and board[nr][nc] is None:
                idx = white_index[(nr, nc)]
                neigh.append(idx)
        clues.append(num)
        clue_neighbors.append(neigh)
        cid = len(clue_neighbors) - 1
        for idx in neigh:
            cell_to_clues[idx].append(cid)

    # Illumination support list: which cells can illuminate each white cell.
    illuminating_options = [list(v) for v in visible]
    cell_seen_by = [[] for _ in range(wcount)]
    for lit in range(wcount):
        for b in illuminating_options[lit]:
            cell_seen_by[b].append(lit)

    # State object uses incremental recomputation on propagation loop.
    def initial_state():
        return {
            "assign": [UNKNOWN] * wcount,  # UNKNOWN / BULB / NOBULB
        }

    def clone_state(state):
        return {"assign": state["assign"][:]}

    def bulb_conflict(assign, idx):
        if assign[idx] == BULB:
            return False
        for j in visible[idx]:
            if j != idx and assign[j] == BULB:
                return True
        return False

    def can_still_be_bulb(assign, idx):
        if assign[idx] == NOBULB:
            return False
        return not bulb_conflict(assign, idx)

    def illuminated_now(assign, idx):
        for j in visible[idx]:
            if assign[j] == BULB:
                return True
        return False

    def candidate_bulbs_for_cell(assign, idx):
        out = []
        for j in illuminating_options[idx]:
            if can_still_be_bulb(assign, j):
                out.append(j)
        return out

    def segment_bulb_info(assign, seg_cells):
        placed = 0
        possible = []
        for idx in seg_cells:
            if assign[idx] == BULB:
                placed += 1
            elif can_still_be_bulb(assign, idx):
                possible.append(idx)
        return placed, possible

    def clue_info(assign, cid):
        neigh = clue_neighbors[cid]
        fixed_bulbs = 0
        candidates = []
        for idx in neigh:
            if assign[idx] == BULB:
                fixed_bulbs += 1
            elif can_still_be_bulb(assign, idx):
                candidates.append(idx)
        return fixed_bulbs, candidates

    def set_value(assign, idx, val):
        cur = assign[idx]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        if val == BULB:
            if bulb_conflict(assign, idx):
                return False
            assign[idx] = BULB
            # Human rule: all visible peers cannot be bulbs.
            for j in visible[idx]:
                if j != idx:
                    if assign[j] == BULB:
                        return False
                    if assign[j] == UNKNOWN:
                        assign[j] = NOBULB
        else:
            assign[idx] = NOBULB
        return True

    def propagate(state):
        assign = state["assign"]
        changed = True
        while changed:
            changed = False

            # Rule 1: enforce numbered clues exactly.
            for cid, need in enumerate(clues):
                fixed_bulbs, candidates = clue_info(assign, cid)
                if fixed_bulbs > need:
                    return False
                if fixed_bulbs + len(candidates) < need:
                    return False
                if fixed_bulbs == need:
                    for idx in candidates:
                        if assign[idx] == UNKNOWN:
                            if not set_value(assign, idx, NOBULB):
                                return False
                            changed = True
                elif fixed_bulbs + len(candidates) == need:
                    for idx in candidates:
                        if assign[idx] != BULB:
                            if not set_value(assign, idx, BULB):
                                return False
                            changed = True

            # Rule 2: at most one bulb in any row/col segment.
            for seg in row_seg_cells_idx:
                placed, possible = segment_bulb_info(assign, seg)
                if placed > 1:
                    return False
                if placed == 1:
                    for idx in possible:
                        if assign[idx] == UNKNOWN:
                            if not set_value(assign, idx, NOBULB):
                                return False
                            changed = True
            for seg in col_seg_cells_idx:
                placed, possible = segment_bulb_info(assign, seg)
                if placed > 1:
                    return False
                if placed == 1:
                    for idx in possible:
                        if assign[idx] == UNKNOWN:
                            if not set_value(assign, idx, NOBULB):
                                return False
                            changed = True

            # Rule 3: every white cell must be illuminable; if only one candidate remains, it must be a bulb.
            for idx in range(wcount):
                if illuminated_now(assign, idx):
                    continue
                cands = candidate_bulbs_for_cell(assign, idx)
                if not cands:
                    return False
                if len(cands) == 1:
                    only = cands[0]
                    if assign[only] != BULB:
                        if not set_value(assign, only, BULB):
                            return False
                        changed = True

            # Rule 4: segment coverage forcing.
            # If an entire segment currently has no bulb and only one place can still host a bulb,
            # that place must be a bulb because every cell in the segment needs row/col illumination somewhere.
            for seg in row_seg_cells_idx:
                placed, possible = segment_bulb_info(assign, seg)
                if placed == 0 and len(possible) == 0:
                    # Segment could still be lit vertically; this is not immediate contradiction.
                    pass
                elif placed == 0 and len(possible) == 1:
                    idx = possible[0]
                    # Only force if at least one cell in segment lacks any non-segment alternative.
                    must = False
                    segset = set(seg)
                    for cell in seg:
                        if illuminated_now(assign, cell):
                            continue
                        cands = candidate_bulbs_for_cell(assign, cell)
                        alt = [x for x in cands if x not in segset]
                        if not alt:
                            must = True
                            break
                    if must and assign[idx] != BULB:
                        if not set_value(assign, idx, BULB):
                            return False
                        changed = True

            for seg in col_seg_cells_idx:
                placed, possible = segment_bulb_info(assign, seg)
                if placed == 0 and len(possible) == 0:
                    pass
                elif placed == 0 and len(possible) == 1:
                    idx = possible[0]
                    must = False
                    segset = set(seg)
                    for cell in seg:
                        if illuminated_now(assign, cell):
                            continue
                        cands = candidate_bulbs_for_cell(assign, cell)
                        alt = [x for x in cands if x not in segset]
                        if not alt:
                            must = True
                            break
                    if must and assign[idx] != BULB:
                        if not set_value(assign, idx, BULB):
                            return False
                        changed = True

            # Rule 5: if a cell can no longer be a bulb due to conflicts, mark NOBULB.
            for idx in range(wcount):
                if assign[idx] == UNKNOWN and not can_still_be_bulb(assign, idx):
                    if not set_value(assign, idx, NOBULB):
                        return False
                    changed = True

        # Final consistency scan after fixpoint.
        for cid, need in enumerate(clues):
            fixed_bulbs, candidates = clue_info(assign, cid)
            if fixed_bulbs > need or fixed_bulbs + len(candidates) < need:
                return False
        for seg in row_seg_cells_idx:
            placed, _ = segment_bulb_info(assign, seg)
            if placed > 1:
                return False
        for seg in col_seg_cells_idx:
            placed, _ = segment_bulb_info(assign, seg)
            if placed > 1:
                return False
        for idx in range(wcount):
            if not illuminated_now(assign, idx):
                if not candidate_bulbs_for_cell(assign, idx):
                    return False

        return True

    def solved(state):
        assign = state["assign"]
        for idx in range(wcount):
            if not illuminated_now(assign, idx):
                return False
        for cid, need in enumerate(clues):
            fixed_bulbs, candidates = clue_info(assign, cid)
            if fixed_bulbs != need or candidates:
                # candidates may exist but if fixed_bulbs==need propagation would remove them;
                # keep strict check on actual adjacent bulbs:
                actual = sum(1 for x in clue_neighbors[cid] if assign[x] == BULB)
                if actual != need:
                    return False
        return True

    def choose_branch_cell(state):
        assign = state["assign"]

        # Priority 1: unresolved clue with smallest candidate slack.
        best = None
        best_key = None
        for cid, need in enumerate(clues):
            fixed_bulbs, candidates = clue_info(assign, cid)
            if candidates and fixed_bulbs < need:
                slack = len(candidates) - (need - fixed_bulbs)
                key = (0, len(candidates), slack)
                if best_key is None or key < best_key:
                    best_key = key
                    best = ("clue", cid, candidates, need - fixed_bulbs)

        # Priority 2: unlit cell with fewest illumination choices.
        for idx in range(wcount):
            if not illuminated_now(assign, idx):
                cands = candidate_bulbs_for_cell(assign, idx)
                key = (1, len(cands), 0)
                if best_key is None or key < best_key:
                    best_key = key
                    best = ("cover", idx, cands, 1)

        # Priority 3: undecided cell with strongest interaction.
        if best is None:
            for idx in range(wcount):
                if assign[idx] == UNKNOWN:
                    degree = len(visible[idx]) + len(cell_to_clues[idx]) * 3
                    cands = [idx]
                    key = (2, 0, -degree)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = ("cell", idx, cands, 1)
        return best

    def search(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        branch = choose_branch_cell(state)
        if branch is None:
            return None

        kind, ref, cands, req = branch

        if kind == "clue":
            # Branch on which subset of clue candidates are bulbs, but keep it compact:
            # pick one candidate with highest impact and try bulb first, then nobulb.
            ordered = sorted(
                cands,
                key=lambda idx: (
                    -len(visible[idx]),
                    -len(cell_to_clues[idx]),
                ),
            )
            idx = ordered[0]
            for val in (BULB, NOBULB):
                ns = clone_state(state)
                if set_value(ns["assign"], idx, val):
                    res = search(ns)
                    if res is not None:
                        return res
            return None

        if kind == "cover":
            # One of these candidates must illuminate the target; try the most constrained/high-impact first.
            target = ref
            ordered = sorted(
                cands,
                key=lambda idx: (
                    len(candidate_bulbs_for_cell(state["assign"], idx)),
                    -len([x for x in cell_seen_by[idx] if not illuminated_now(state["assign"], x)]),
                    -len(cell_to_clues[idx]),
                ),
            )
            tried_no = set()
            for idx in ordered:
                ns = clone_state(state)
                if set_value(ns["assign"], idx, BULB):
                    res = search(ns)
                    if res is not None:
                        return res
                tried_no.add(idx)
                # If trying this bulb fails, we can eliminate it and continue.
                state2 = clone_state(state)
                ok = True
                for j in tried_no:
                    if not set_value(state2["assign"], j, NOBULB):
                        ok = False
                        break
                if ok:
                    # If only one candidate remains after eliminations, recursion handles it.
                    pass
            return None

        # kind == "cell"
        idx = ref
        for val in (BULB, NOBULB):
            ns = clone_state(state)
            if set_value(ns["assign"], idx, val):
                res = search(ns)
                if res is not None:
                    return res
        return None

    state = initial_state()
    result = search(state)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(m)] for _ in range(n)]
    for idx, (r, c) in enumerate(white_cells):
        if result["assign"][idx] == BULB:
            answer[r][c] = 'B'
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, 6, None, 1, None, None], [None, None, None, None, None, None, None], [4, None, None, None, 7, 1, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, 2, None, None]], 'adjacent': [[0.0, 3.5], [0.5, 1.0], [0.5, 3.0], [0.5, 6.0], [1.5, 0.0], [2.0, 2.5], [2.5, 3.0], [3.0, 1.5], [3.0, 5.5], [3.5, 1.0], [3.5, 6.0], [4.0, 2.5], [4.0, 4.5], [4.5, 0.0], [4.5, 4.0], [5.0, 2.5], [5.0, 5.5], [5.5, 5.0], [5.5, 6.0], [6.0, 1.5], [6.0, 5.5]]}

# Generalized Kropki-like consecutive-only Latin square solver.
# Dots indicate consecutive values; absence of a dot between orthogonally adjacent cells
# means values are NOT consecutive.

from collections import deque

def solve(observation):
    grid = observation['data']
    n = len(grid)
    full_mask = (1 << n) - 1

    # Parse adjacency dots into horizontal/vertical edge sets.
    dot_h = set()  # (r,c) means between (r,c) and (r,c+1)
    dot_v = set()  # (r,c) means between (r,c) and (r+1,c)
    for rr, cc in observation['adjacent']:
        if abs(rr - round(rr)) < 1e-9 and abs(cc * 2 - round(cc * 2)) < 1e-9 and abs(cc - int(cc) - 0.5) < 1e-9:
            r = int(round(rr))
            c = int(cc - 0.5)
            if 0 <= r < n and 0 <= c < n - 1:
                dot_h.add((r, c))
        elif abs(cc - round(cc)) < 1e-9 and abs(rr * 2 - round(rr * 2)) < 1e-9 and abs(rr - int(rr) - 0.5) < 1e-9:
            r = int(rr - 0.5)
            c = int(round(cc))
            if 0 <= r < n - 1 and 0 <= c < n:
                dot_v.add((r, c))

    # Cell indexing.
    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    # Precompute neighbor relationships with consecutive / non-consecutive requirement.
    neighbors = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if c + 1 < n:
                j = idx(r, c + 1)
                is_dot = (r, c) in dot_h
                neighbors[i].append((j, is_dot))
                neighbors[j].append((i, is_dot))
            if r + 1 < n:
                j = idx(r + 1, c)
                is_dot = (r, c) in dot_v
                neighbors[i].append((j, is_dot))
                neighbors[j].append((i, is_dot))

    # Precompute value masks.
    bit = [1 << (v - 1) for v in range(n + 1)]
    consec_mask = [0] * (n + 1)
    nonconsec_mask = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit[v - 1]
        if v < n:
            m |= bit[v + 1]
        consec_mask[v] = m
        nonconsec_mask[v] = full_mask ^ m

    # Initial domains and row/col availability.
    domains = [full_mask] * (n * n)
    row_avail = [full_mask] * n
    col_avail = [full_mask] * n

    for r in range(n):
        seen = set()
        for c in range(n):
            v = grid[r][c]
            if v is not None:
                if not (1 <= v <= n) or v in seen:
                    return "No Solution"
                seen.add(v)

    for c in range(n):
        seen = set()
        for r in range(n):
            v = grid[r][c]
            if v is not None:
                if v in seen:
                    return "No Solution"
                seen.add(v)

    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v is not None:
                m = bit[v]
                domains[idx(r, c)] = m
                if row_avail[r] & m == 0 or col_avail[c] & m == 0:
                    return "No Solution"
                row_avail[r] &= ~m
                col_avail[c] &= ~m

    # Apply row/col availability to unsolved cells.
    for i in range(n * n):
        r, c = rc(i)
        domains[i] &= row_avail[r] | domains[i]
        domains[i] &= col_avail[c] | domains[i]
        if grid[r][c] is None:
            domains[i] &= row_avail[r] & col_avail[c]
        if domains[i] == 0:
            return "No Solution"

    def popcount(x):
        return x.bit_count()

    def single_value(mask):
        return mask.bit_length()

    # Human-like propagation engine.
    def propagate(domains, row_avail, col_avail):
        q = deque(range(n * n))
        inq = [True] * (n * n)

        def enqueue(i):
            if not inq[i]:
                inq[i] = True
                q.append(i)

        # Initial row/col hidden-single queues use row/col scans when needed.
        row_dirty = [True] * n
        col_dirty = [True] * n

        # Assignment bookkeeping based on singleton domains.
        assigned = [0] * (n * n)
        for i in range(n * n):
            if domains[i] and domains[i] & (domains[i] - 1) == 0:
                assigned[i] = 1

        while True:
            progress = False

            while q:
                i = q.popleft()
                inq[i] = False
                r, c = rc(i)
                mask = domains[i]
                if mask == 0:
                    return False

                # Keep domain aligned with row/col availability.
                allowed = mask if assigned[i] else (mask & row_avail[r] & col_avail[c])
                if allowed != mask:
                    domains[i] = allowed
                    mask = allowed
                    if mask == 0:
                        return False
                    progress = True

                # If singleton, commit to row/col uniqueness and push effects.
                if mask & (mask - 1) == 0:
                    vbit = mask
                    if not assigned[i]:
                        if row_avail[r] & vbit == 0 or col_avail[c] & vbit == 0:
                            return False
                        row_avail[r] &= ~vbit
                        col_avail[c] &= ~vbit
                        assigned[i] = 1
                        progress = True
                        row_dirty[r] = True
                        col_dirty[c] = True
                        # Other cells in row/col lose this value.
                        for cc in range(n):
                            j = idx(r, cc)
                            if j != i and domains[j] & vbit:
                                domains[j] &= ~vbit
                                if domains[j] == 0:
                                    return False
                                enqueue(j)
                        for rr in range(n):
                            j = idx(rr, c)
                            if j != i and domains[j] & vbit:
                                domains[j] &= ~vbit
                                if domains[j] == 0:
                                    return False
                                enqueue(j)

                    v = single_value(mask)
                    # Consecutive / non-consecutive adjacency filtering.
                    for j, is_dot in neighbors[i]:
                        old = domains[j]
                        new = old & (consec_mask[v] if is_dot else nonconsec_mask[v])
                        if new != old:
                            domains[j] = new
                            if new == 0:
                                return False
                            enqueue(j)
                            progress = True
                            rr, cc = rc(j)
                            row_dirty[rr] = True
                            col_dirty[cc] = True

                else:
                    # If neighbor singleton exists, filter this side too.
                    for j, is_dot in neighbors[i]:
                        om = domains[j]
                        if om and om & (om - 1) == 0:
                            v = single_value(om)
                            new = mask & (consec_mask[v] if is_dot else nonconsec_mask[v])
                            if new != mask:
                                domains[i] = new
                                mask = new
                                if new == 0:
                                    return False
                                progress = True
                                row_dirty[r] = True
                                col_dirty[c] = True

            # Hidden singles in rows.
            for r in range(n):
                if not row_dirty[r]:
                    continue
                row_dirty[r] = False
                need = row_avail[r]
                while need:
                    vbit = need & -need
                    need -= vbit
                    places = []
                    for c in range(n):
                        i = idx(r, c)
                        if domains[i] & vbit:
                            places.append(i)
                            if len(places) > 1:
                                break
                    if not places:
                        return False
                    if len(places) == 1:
                        i = places[0]
                        if domains[i] != vbit:
                            domains[i] = vbit
                            enqueue(i)
                            progress = True

            # Hidden singles in columns.
            for c in range(n):
                if not col_dirty[c]:
                    continue
                col_dirty[c] = False
                need = col_avail[c]
                while need:
                    vbit = need & -need
                    need -= vbit
                    places = []
                    for r in range(n):
                        i = idx(r, c)
                        if domains[i] & vbit:
                            places.append(i)
                            if len(places) > 1:
                                break
                    if not places:
                        return False
                    if len(places) == 1:
                        i = places[0]
                        if domains[i] != vbit:
                            domains[i] = vbit
                            enqueue(i)
                            progress = True

            # Pairwise edge reasoning:
            # For each adjacent pair, delete values that have no supporting counterpart.
            for i in range(n * n):
                mi = domains[i]
                if mi == 0:
                    return False
                for j, is_dot in neighbors[i]:
                    if j < i:
                        continue
                    mj = domains[j]
                    if mj == 0:
                        return False
                    allowed_i = 0
                    allowed_j = 0

                    x = mi
                    while x:
                        b = x & -x
                        x -= b
                        v = b.bit_length()
                        support = mj & (consec_mask[v] if is_dot else nonconsec_mask[v])
                        if support:
                            allowed_i |= b
                            allowed_j |= support
                    if allowed_i != mi:
                        domains[i] = allowed_i
                        if allowed_i == 0:
                            return False
                        enqueue(i)
                        rr, cc = rc(i)
                        row_dirty[rr] = True
                        col_dirty[cc] = True
                        progress = True
                    if allowed_j != mj:
                        domains[j] = allowed_j
                        if allowed_j == 0:
                            return False
                        enqueue(j)
                        rr, cc = rc(j)
                        row_dirty[rr] = True
                        col_dirty[cc] = True
                        progress = True

            # Hall-set style subset elimination for rows/cols (small/generalized).
            # If k cells together contain exactly k values, remove those values from others.
            def subset_reduce(indices):
                unsolved = [i for i in indices if domains[i] & (domains[i] - 1)]
                m = len(unsolved)
                if m < 2:
                    return False, True
                changed = False

                # Group identical masks and also inspect combinations up to size 4.
                masks = {}
                for i in unsolved:
                    masks.setdefault(domains[i], []).append(i)

                for mask, cells in list(masks.items()):
                    k = popcount(mask)
                    if 1 < k == len(cells):
                        for i in indices:
                            if i not in cells and domains[i] & mask:
                                domains[i] &= ~mask
                                if domains[i] == 0:
                                    return True, False
                                enqueue(i)
                                changed = True

                # Combinations of 2..4 cells, enough for effective human-like pruning.
                L = unsolved
                lim = min(4, len(L))
                for size in range(2, lim + 1):
                    stack = [(0, [], 0)]
                    while stack:
                        start, chosen, union = stack.pop()
                        if len(chosen) == size:
                            if popcount(union) == size:
                                chosen_set = set(chosen)
                                for i in indices:
                                    if i not in chosen_set and domains[i] & union:
                                        domains[i] &= ~union
                                        if domains[i] == 0:
                                            return True, False
                                        enqueue(i)
                                        changed = True
                            continue
                        remaining_needed = size - len(chosen)
                        for p in range(len(L) - remaining_needed, start - 1, -1):
                            i = L[p]
                            new_union = union | domains[i]
                            if popcount(new_union) > size:
                                continue
                            stack.append((p + 1, chosen + [i], new_union))
                return changed, True

            any_subset_progress = False
            for r in range(n):
                changed, ok = subset_reduce([idx(r, c) for c in range(n)])
                if not ok:
                    return False
                any_subset_progress |= changed
            for c in range(n):
                changed, ok = subset_reduce([idx(r, c) for r in range(n)])
                if not ok:
                    return False
                any_subset_progress |= changed

            if any_subset_progress:
                progress = True

            # Validate all still-placeable values in rows/cols.
            for r in range(n):
                need = row_avail[r]
                while need:
                    vbit = need & -need
                    need -= vbit
                    found = False
                    for c in range(n):
                        if domains[idx(r, c)] & vbit:
                            found = True
                            break
                    if not found:
                        return False
            for c in range(n):
                need = col_avail[c]
                while need:
                    vbit = need & -need
                    need -= vbit
                    found = False
                    for r in range(n):
                        if domains[idx(r, c)] & vbit:
                            found = True
                            break
                    if not found:
                        return False

            if not progress:
                break

        return True

    def is_solved(domains):
        return all(m and (m & (m - 1) == 0) for m in domains)

    def search(domains, row_avail, col_avail):
        if not propagate(domains, row_avail, col_avail):
            return None
        if is_solved(domains):
            return domains

        # Choose most constrained cell, tie-break by strongest adjacency degree.
        best = None
        best_key = None
        for i, m in enumerate(domains):
            pc = popcount(m)
            if pc > 1:
                # Lower candidates first; more constrained neighbors next.
                neigh_strength = sum(2 if is_dot else 1 for _, is_dot in neighbors[i])
                key = (pc, -neigh_strength)
                if best_key is None or key < best_key:
                    best_key = key
                    best = i

        if best is None:
            return None

        # Order candidates by least-constraining support.
        cand_scores = []
        m = domains[best]
        x = m
        while x:
            b = x & -x
            x -= b
            v = b.bit_length()
            score = 0
            for j, is_dot in neighbors[best]:
                support = domains[j] & (consec_mask[v] if is_dot else nonconsec_mask[v])
                score += popcount(support)
            cand_scores.append((score, b))
        cand_scores.sort()

        for _, vbit in cand_scores:
            nd = domains[:]
            nr = row_avail[:]
            nc = col_avail[:]
            nd[best] = vbit
            res = search(nd, nr, nc)
            if res is not None:
                return res
        return None

    result = search(domains[:], row_avail[:], col_avail[:])
    if result is None:
        return "No Solution"

    ans = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(result[idx(r, c)]))
        ans.append(row)
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

