from copy import deepcopy

def solve(observation):
    data = observation['data']
    n = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append({'pos': (r, c), 'need': data[r][c]})

    m = len(islands)
    if m == 0:
        return "{}"

    edges = []
    adj = [[] for _ in range(m)]

    def add_edge(a, b):
        idx = len(edges)
        pa = islands[a]['pos']
        pb = islands[b]['pos']
        horizontal = pa[0] == pb[0]
        segment = (min(pa[0], pb[0]), min(pa[1], pb[1]), max(pa[0], pb[0]), max(pa[1], pb[1]))
        edges.append({
            'u': a,
            'v': b,
            'pos1': pa,
            'pos2': pb,
            'horizontal': horizontal,
            'cross': set(),
            'segment': segment,
        })
        adj[a].append(idx)
        adj[b].append(idx)

    # visible neighbors
    for i, isl in enumerate(islands):
        r, c = isl['pos']
        cc = c - 1
        while cc >= 0:
            if data[r][cc] is not None:
                j = pos_to_idx[(r, cc)]
                if j > i:
                    add_edge(i, j)
                break
            cc -= 1
        cc = c + 1
        while cc < n:
            if data[r][cc] is not None:
                j = pos_to_idx[(r, cc)]
                if j > i:
                    add_edge(i, j)
                break
            cc += 1
        rr = r - 1
        while rr >= 0:
            if data[rr][c] is not None:
                j = pos_to_idx[(rr, c)]
                if j > i:
                    add_edge(i, j)
                break
            rr -= 1
        rr = r + 1
        while rr < n:
            if data[rr][c] is not None:
                j = pos_to_idx[(rr, c)]
                if j > i:
                    add_edge(i, j)
                break
            rr += 1

    ecount = len(edges)

    # crossings
    for i in range(ecount):
        e1 = edges[i]
        r1a, c1a = e1['pos1']
        r1b, c1b = e1['pos2']
        for j in range(i + 1, ecount):
            e2 = edges[j]
            if e1['horizontal'] == e2['horizontal']:
                continue
            h = e1 if e1['horizontal'] else e2
            v = e2 if e1['horizontal'] else e1
            rh = h['pos1'][0]
            ch1, ch2 = sorted([h['pos1'][1], h['pos2'][1]])
            cv = v['pos1'][1]
            rv1, rv2 = sorted([v['pos1'][0], v['pos2'][0]])
            if rv1 < rh < rv2 and ch1 < cv < ch2:
                edges[i]['cross'].add(j)
                edges[j]['cross'].add(i)

    neighbors = [[e for e in adj[i]] for i in range(m)]

    class State:
        __slots__ = ('lo', 'hi', 'rem', 'deg', 'changed')

        def __init__(self):
            self.lo = [0] * ecount
            self.hi = [2] * ecount
            self.rem = [islands[i]['need'] for i in range(m)]
            self.deg = [0] * m
            self.changed = list(range(ecount))

        def copy(self):
            s = State()
            s.lo = self.lo[:]
            s.hi = self.hi[:]
            s.rem = self.rem[:]
            s.deg = self.deg[:]
            s.changed = self.changed[:]
            return s

    def set_edge(state, ei, new_lo=None, new_hi=None):
        lo = state.lo[ei]
        hi = state.hi[ei]
        if new_lo is None:
            new_lo = lo
        if new_hi is None:
            new_hi = hi
        if new_lo < lo:
            new_lo = lo
        if new_hi > hi:
            new_hi = hi
        if new_lo > new_hi:
            return False
        if new_lo == lo and new_hi == hi:
            return True

        u = edges[ei]['u']
        v = edges[ei]['v']

        old_lo = lo
        old_hi = hi
        d_lo = new_lo - old_lo
        d_hi = old_hi - new_hi

        state.lo[ei] = new_lo
        state.hi[ei] = new_hi

        if d_lo:
            state.rem[u] -= d_lo
            state.rem[v] -= d_lo
            state.deg[u] += d_lo
            state.deg[v] += d_lo
        if d_hi:
            pass

        if state.rem[u] < 0 or state.rem[v] < 0:
            return False

        # crossing elimination when edge forced positive
        if old_lo == 0 and new_lo > 0:
            for ce in edges[ei]['cross']:
                if not set_edge(state, ce, new_hi=0):
                    return False

        state.changed.append(ei)
        return True

    def island_bounds(state, i):
        s_lo = 0
        s_hi = 0
        for ei in neighbors[i]:
            s_lo += state.lo[ei]
            s_hi += state.hi[ei]
        return s_lo, s_hi

    def component_info_positive(state):
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra != rb:
                parent[rb] = ra

        for ei in range(ecount):
            if state.lo[ei] > 0:
                union(edges[ei]['u'], edges[ei]['v'])

        comps = {}
        for i in range(m):
            r = find(i)
            comps.setdefault(r, []).append(i)
        return list(comps.values()), find

    def connectivity_prune(state):
        comps, find = component_info_positive(state)
        if len(comps) == 1:
            return True

        possible_links = 0
        comp_id = {}
        for ci, comp in enumerate(comps):
            for x in comp:
                comp_id[x] = ci

        seen = set()
        for ei in range(ecount):
            if state.hi[ei] == 0:
                continue
            u = edges[ei]['u']
            v = edges[ei]['v']
            cu = comp_id[find(u)]
            cv = comp_id[find(v)]
            if cu != cv:
                key = (min(cu, cv), max(cu, cv), ei)
                seen.add(key)
        possible_links = len(seen)
        return possible_links >= len(comps) - 1

    def local_feasible(state):
        for i in range(m):
            lo_sum, hi_sum = island_bounds(state, i)
            need = islands[i]['need']
            if lo_sum > need or hi_sum < need:
                return False
            if state.rem[i] != need - lo_sum:
                return False
        return True

    def apply_island_rules(state):
        progress = True
        while progress:
            progress = False
            for i in range(m):
                need = islands[i]['need']
                lo_sum, hi_sum = island_bounds(state, i)
                if lo_sum > need or hi_sum < need:
                    return False
                rem = need - lo_sum
                free = hi_sum - lo_sum

                if rem < 0 or rem > free:
                    return False

                es = neighbors[i]
                # exact fill: all remaining capacities must be used
                if rem == free:
                    for ei in es:
                        if state.lo[ei] < state.hi[ei]:
                            if not set_edge(state, ei, new_lo=state.hi[ei]):
                                return False
                            progress = True

                # no remaining: all undecided to 0 above lo
                if rem == 0:
                    for ei in es:
                        if state.hi[ei] > state.lo[ei]:
                            if not set_edge(state, ei, new_hi=state.lo[ei]):
                                return False
                            progress = True

                # human-style lower-bound forcing:
                # if excluding an edge makes target unreachable, force enough on that edge
                current_hi = {ei: state.hi[ei] for ei in es}
                for ei in es:
                    others_hi = hi_sum - current_hi[ei]
                    min_needed_on_e = max(state.lo[ei], need - others_hi)
                    if min_needed_on_e > state.lo[ei]:
                        if not set_edge(state, ei, new_lo=min_needed_on_e):
                            return False
                        progress = True

                # if an edge can contribute nothing without overfilling others, cap it down
                current_lo = {ei: state.lo[ei] for ei in es}
                for ei in es:
                    others_lo = lo_sum - current_lo[ei]
                    max_allowed_on_e = min(state.hi[ei], need - others_lo)
                    if max_allowed_on_e < state.hi[ei]:
                        if not set_edge(state, ei, new_hi=max_allowed_on_e):
                            return False
                        progress = True

                # single-neighbor and parity-like direct deductions emerge from above

            if not local_feasible(state):
                return False
            if not connectivity_prune(state):
                return False
        return True

    def final_connected(state):
        comps, _ = component_info_positive(state)
        return len(comps) == 1

    def solved(state):
        if not local_feasible(state):
            return False
        for ei in range(ecount):
            if state.lo[ei] != state.hi[ei]:
                return False
        return final_connected(state)

    def choose_branch_edge(state):
        best = None
        best_score = None
        for ei in range(ecount):
            lo = state.lo[ei]
            hi = state.hi[ei]
            if lo == hi:
                continue
            u = edges[ei]['u']
            v = edges[ei]['v']
            score = (
                (hi - lo),
                -(len(edges[ei]['cross'])),
                -(state.rem[u] + state.rem[v]),
                -(islands[u]['need'] + islands[v]['need'])
            )
            if best_score is None or score < best_score:
                best_score = score
                best = ei
        return best

    def branch_values(state, ei):
        lo = state.lo[ei]
        hi = state.hi[ei]
        vals = list(range(lo, hi + 1))
        # Prefer forced-looking values: 0, 2, 1 or nearest extremes
        order = []
        for v in (0, 2, 1):
            if v in vals and v not in order:
                order.append(v)
        for v in vals:
            if v not in order:
                order.append(v)
        return order

    def search(state):
        if not apply_island_rules(state):
            return None
        if solved(state):
            return state

        ei = choose_branch_edge(state)
        if ei is None:
            return None

        for val in branch_values(state, ei):
            if val < state.lo[ei] or val > state.hi[ei]:
                continue
            ns = state.copy()
            if set_edge(ns, ei, new_lo=val, new_hi=val):
                res = search(ns)
                if res is not None:
                    return res
        return None

    init = State()
    # Initial quick degree caps from island degrees
    for ei in range(ecount):
        u = edges[ei]['u']
        v = edges[ei]['v']
        cap = min(2, islands[u]['need'], islands[v]['need'])
        if cap < 2:
            if not set_edge(init, ei, new_hi=cap):
                return "No Solution"

    result = search(init)
    if result is None:
        return "No Solution"

    answer = {}
    for ei, e in enumerate(edges):
        cnt = result.lo[ei]
        if cnt > 0:
            a = e['pos1']
            b = e['pos2']
            if a > b:
                a, b = b, a
            answer[(a, b)] = cnt
    return str(answer)

