# Takuzu / Binairo solver using human-like deduction first, then tightly-pruned search.
# The image is parsed into OBSERVATION above using:
# - black circle -> 'B'
# - white circle -> 'W'
# - empty cell -> None

from itertools import combinations

B = 'B'
W = 'W'


def opp(v):
    return W if v == B else B


def transpose(grid):
    n = len(grid)
    return [[grid[r][c] for r in range(n)] for c in range(n)]


def row_counts(line):
    b = sum(1 for x in line if x == B)
    w = sum(1 for x in line if x == W)
    u = sum(1 for x in line if x is None)
    return b, w, u


def line_no_three_possible(line):
    n = len(line)
    for i in range(n - 2):
        seg = line[i:i + 3]
        if None not in seg and seg[0] == seg[1] == seg[2]:
            return False
    return True


def line_capacity_ok(line):
    n = len(line)
    half = n // 2
    b, w, _ = row_counts(line)
    return b <= half and w <= half


def line_basic_ok(line):
    return line_capacity_ok(line) and line_no_three_possible(line)


def generate_valid_lines_from_partial(partial):
    n = len(partial)
    half = n // 2
    res = []

    def rec(i, line, b, w):
        if b > half or w > half:
            return
        if i >= 2 and line[i - 1] == line[i - 2]:
            forced = opp(line[i - 1])
            pv = partial[i]
            if pv is not None and pv != forced:
                return
            line.append(forced)
            rec(i + 1, line, b + (forced == B), w + (forced == W))
            line.pop()
            return

        pv = partial[i]
        vals = (pv,) if pv is not None else (B, W)
        remain = n - i - 1
        for v in vals:
            nb = b + (v == B)
            nw = w + (v == W)
            if nb > half or nw > half:
                continue
            if remain >= 0:
                if nb + remain < half or nw + remain < half:
                    continue
            if i >= 2 and line[i - 1] == line[i - 2] == v:
                continue
            line.append(v)
            rec(i + 1, line, nb, nw)
            line.pop()

    rec(0, [], 0, 0)
    return res if False else _collect_valid_lines(partial)


def _collect_valid_lines(partial):
    n = len(partial)
    half = n // 2
    out = []

    def rec(i, line, b, w):
        if b > half or w > half:
            return
        if i == n:
            if b == half and w == half:
                out.append(tuple(line))
            return

        pv = partial[i]
        vals = (pv,) if pv is not None else (B, W)
        for v in vals:
            nb = b + (v == B)
            nw = w + (v == W)
            if nb > half or nw > half:
                continue
            rem = n - i - 1
            if nb + rem < half or nw + rem < half:
                continue
            if i >= 2 and line[i - 1] == line[i - 2] == v:
                continue
            line.append(v)
            rec(i + 1, line, nb, nw)
            line.pop()

    rec(0, [], 0, 0)
    return out


def all_valid_patterns(n):
    empty = [None] * n
    return _collect_valid_lines(empty)


def line_compatible(a, b):
    return all(x is None or x == y for x, y in zip(a, b))


def deduce_from_triples(line):
    n = len(line)
    changed = False
    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and a == b and c is None:
            line[i + 2] = opp(a)
            changed = True
        elif a is not None and c is not None and a == c and b is None:
            line[i + 1] = opp(a)
            changed = True
        elif b is not None and c is not None and b == c and a is None:
            line[i] = opp(b)
            changed = True
    return changed


def deduce_from_counts(line):
    n = len(line)
    half = n // 2
    b, w, u = row_counts(line)
    if u == 0:
        return False
    changed = False
    if b == half:
        for i, v in enumerate(line):
            if v is None:
                line[i] = W
                changed = True
    elif w == half:
        for i, v in enumerate(line):
            if v is None:
                line[i] = B
                changed = True
    return changed


def partial_equal_knowns(a, b):
    for x, y in zip(a, b):
        if x is not None and y is not None and x != y:
            return False
    return True


def uniqueness_prune_lines(lines):
    n = len(lines)
    changed = False
    complete = [i for i, row in enumerate(lines) if None not in row]
    for i in complete:
        for j in range(n):
            if i == j or None not in lines[j]:
                continue
            # If row j differs from complete row i only in unknown spots,
            # then all unknowns in j are forced to the opposite of row i at least in one position.
            same_possible = True
            unknown_positions = []
            for k, (a, b) in enumerate(zip(lines[i], lines[j])):
                if b is None:
                    unknown_positions.append(k)
                elif a != b:
                    same_possible = False
                    break
            if same_possible and unknown_positions:
                # If exactly one unknown remains, force opposite at that spot.
                if len(unknown_positions) == 1:
                    k = unknown_positions[0]
                    lines[j][k] = opp(lines[i][k])
                    changed = True
    return changed


def validate_grid(grid):
    n = len(grid)
    half = n // 2

    for r in range(n):
        row = grid[r]
        if not line_basic_ok(row):
            return False
        if None not in row:
            if row.count(B) != half or row.count(W) != half:
                return False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if not line_basic_ok(col):
            return False
        if None not in col:
            if col.count(B) != half or col.count(W) != half:
                return False

    full_rows = [tuple(row) for row in grid if None not in row]
    if len(full_rows) != len(set(full_rows)):
        return False

    cols = transpose(grid)
    full_cols = [tuple(col) for col in cols if None not in col]
    if len(full_cols) != len(set(full_cols)):
        return False

    return True


def propagate(grid, row_domains=None, col_domains=None, patterns=None):
    n = len(grid)
    if patterns is None:
        patterns = all_valid_patterns(n)

    if row_domains is None:
        row_domains = []
        for r in range(n):
            partial = grid[r]
            dom = [p for p in patterns if line_compatible(partial, p)]
            row_domains.append(dom)

    if col_domains is None:
        t = transpose(grid)
        col_domains = []
        for c in range(n):
            partial = t[c]
            dom = [p for p in patterns if line_compatible(partial, p)]
            col_domains.append(dom)

    changed = True
    while changed:
        changed = False

        # Local human-style deductions on rows
        for r in range(n):
            row = grid[r]
            if deduce_from_triples(row):
                changed = True
            if deduce_from_counts(row):
                changed = True
            if not line_basic_ok(row):
                return None

        # Local human-style deductions on columns
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            col_changed = False
            if deduce_from_triples(col):
                col_changed = True
            if deduce_from_counts(col):
                col_changed = True
            if col_changed:
                for r in range(n):
                    grid[r][c] = col[r]
                changed = True
            if not line_basic_ok(col):
                return None

        # Human-style uniqueness pressure
        if uniqueness_prune_lines(grid):
            changed = True
        tgrid = transpose(grid)
        if uniqueness_prune_lines(tgrid):
            grid[:] = transpose(tgrid)
            changed = True

        # Recompute row domains and force common cells
        new_row_domains = []
        for r in range(n):
            partial = grid[r]
            dom = [p for p in patterns if line_compatible(partial, p)]
            # uniqueness against completed other rows
            completed_other = {tuple(grid[i]) for i in range(n) if i != r and None not in grid[i]}
            dom = [p for p in dom if p not in completed_other or tuple(partial) == p]
            if not dom:
                return None
            new_row_domains.append(dom)

            for c in range(n):
                vals = {p[c] for p in dom}
                if len(vals) == 1 and grid[r][c] is None:
                    grid[r][c] = next(iter(vals))
                    changed = True

        row_domains = new_row_domains

        # Recompute col domains and force common cells
        t = transpose(grid)
        new_col_domains = []
        for c in range(n):
            partial = t[c]
            dom = [p for p in patterns if line_compatible(partial, p)]
            completed_other = {tuple(t[i]) for i in range(n) if i != c and None not in t[i]}
            dom = [p for p in dom if p not in completed_other or tuple(partial) == p]
            if not dom:
                return None
            new_col_domains.append(dom)

            for r in range(n):
                vals = {p[r] for p in dom}
                if len(vals) == 1 and grid[r][c] is None:
                    grid[r][c] = next(iter(vals))
                    changed = True

        col_domains = new_col_domains

        if not validate_grid(grid):
            return None

    return grid, row_domains, col_domains


def is_solved(grid):
    return all(None not in row for row in grid) and validate_grid(grid)


def choose_branch(grid, row_domains, col_domains):
    n = len(grid)
    best = None

    for r in range(n):
        if None in grid[r]:
            m = len(row_domains[r])
            if m > 1:
                score = (m, 'r', r)
                if best is None or score < best:
                    best = score

    t = transpose(grid)
    for c in range(n):
        if None in t[c]:
            m = len(col_domains[c])
            if m > 1:
                score = (m, 'c', c)
                if best is None or score < best:
                    best = score

    return best


def search(grid, row_domains=None, col_domains=None, patterns=None):
    prop = propagate([row[:] for row in grid], row_domains, col_domains, patterns)
    if prop is None:
        return None
    grid, row_domains, col_domains = prop

    if is_solved(grid):
        return grid

    choice = choose_branch(grid, row_domains, col_domains)
    if choice is None:
        return None

    _, kind, idx = choice
    n = len(grid)

    if kind == 'r':
        candidates = row_domains[idx]
        # Try most constraining rows first: patterns that best fit current column domains
        scored = []
        for p in candidates:
            score = 0
            for c in range(n):
                cd = col_domains[c]
                score += sum(1 for cp in cd if cp[idx] == p[c])
            scored.append((score, p))
        scored.sort()
        for _, p in scored:
            new_grid = [row[:] for row in grid]
            new_grid[idx] = list(p)
            res = search(new_grid, None, None, patterns)
            if res is not None:
                return res
    else:
        candidates = col_domains[idx]
        scored = []
        for p in candidates:
            score = 0
            for r in range(n):
                rd = row_domains[r]
                score += sum(1 for rp in rd if rp[idx] == p[r])
            scored.append((score, p))
        scored.sort()
        for _, p in scored:
            new_grid = [row[:] for row in grid]
            for r in range(n):
                new_grid[r][idx] = p[r]
            res = search(new_grid, None, None, patterns)
            if res is not None:
                return res

    return None


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or n % 2 != 0:
        return "No Solution"

    grid = [row[:] for row in data]
    patterns = all_valid_patterns(n)

    ans = search(grid, patterns=patterns)
    if ans is None:
        return "No Solution"
    return ans


