# Binary puzzle / Takuzu solver with strong human-like propagation and restrained search.
# Symbols:
#   'B' -> black
#   'W' -> white
#   None -> unknown

from itertools import product


def opposite(v):
    return 'W' if v == 'B' else 'B'


def line_has_triple(line):
    for i in range(len(line) - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and a == b == c:
            return True
    return False


def count_bw(line):
    b = sum(1 for x in line if x == 'B')
    w = sum(1 for x in line if x == 'W')
    u = sum(1 for x in line if x is None)
    return b, w, u


def line_complete(line):
    return all(x is not None for x in line)


def valid_line_partial(line, half):
    b, w, u = count_bw(line)
    if b > half or w > half:
        return False
    if line_has_triple(line):
        return False
    if b + u < half or w + u < half:
        return False
    return True


def valid_line_complete(line, half):
    if not line_complete(line):
        return False
    b, w, _ = count_bw(line)
    return b == half and w == half and not line_has_triple(line)


def generate_valid_patterns(length, half):
    patterns = []

    def rec(pos, line, b, w):
        if b > half or w > half:
            return
        if pos >= 2 and line[pos - 1] == line[pos - 2]:
            forced = opposite(line[pos - 1])
            if b + (forced == 'B') > half or w + (forced == 'W') > half:
                return
            line.append(forced)
            rec(pos + 1, line, b + (forced == 'B'), w + (forced == 'W'))
            line.pop()
            return
        if pos == length:
            if b == half and w == half:
                patterns.append(tuple(line))
            return
        remaining = length - pos
        if b < half:
            line.append('B')
            rec(pos + 1, line, b + 1, w)
            line.pop()
        if w < half:
            line.append('W')
            rec(pos + 1, line, b, w + 1)
            line.pop()

    rec(0, [], 0, 0)
    return patterns


def compatible_pattern(pattern, line):
    for a, b in zip(pattern, line):
        if b is not None and a != b:
            return False
    return True


def transpose(grid):
    return [list(col) for col in zip(*grid)]


def deduce_from_adjacency(line):
    n = len(line)
    changed = False
    line = list(line)

    for i in range(n - 2):
        a, b, c = line[i], line[i + 1], line[i + 2]
        if a is not None and a == b and c is None:
            line[i + 2] = opposite(a)
            changed = True
        elif a is not None and c is not None and a == c and b is None:
            line[i + 1] = opposite(a)
            changed = True
        elif b is not None and c is not None and b == c and a is None:
            line[i] = opposite(b)
            changed = True

    return line, changed


def deduce_from_counts(line, half):
    line = list(line)
    b, w, u = count_bw(line)
    changed = False
    if u == 0:
        return line, changed
    if b == half:
        for i, v in enumerate(line):
            if v is None:
                line[i] = 'W'
                changed = True
    elif w == half:
        for i, v in enumerate(line):
            if v is None:
                line[i] = 'B'
                changed = True
    return line, changed


def deduce_from_uniqueness_line(line, completed_others, half):
    # Human-like rule:
    # If a line has exactly two blanks and matches a completed peer except at those blanks,
    # then the blanks must be the opposite arrangement that avoids duplication.
    n = len(line)
    idxs = [i for i, v in enumerate(line) if v is None]
    if len(idxs) != 2:
        return list(line), False
    a, b = idxs
    line = list(line)
    changed = False

    needed_b = half - sum(1 for x in line if x == 'B')
    needed_w = half - sum(1 for x in line if x == 'W')
    candidates = []
    for va in ('B', 'W'):
        for vb in ('B', 'W'):
            trial = line[:]
            trial[a] = va
            trial[b] = vb
            if valid_line_complete(trial, half):
                candidates.append(tuple(trial))

    if not candidates:
        return line, False

    filtered = []
    for cand in candidates:
        if cand not in completed_others:
            filtered.append(cand)

    if filtered:
        candidates = filtered

    for i in range(n):
        vals = {cand[i] for cand in candidates}
        if len(vals) == 1 and line[i] is None:
            line[i] = vals.pop()
            changed = True

    return line, changed


def reduce_line_by_patterns(line, patterns):
    comp = [p for p in patterns if compatible_pattern(p, line)]
    if not comp:
        return None, None
    out = list(line)
    changed = False
    for i, v in enumerate(line):
        if v is None:
            vals = {p[i] for p in comp}
            if len(vals) == 1:
                out[i] = next(iter(vals))
                changed = True
    return out, comp if changed or True else comp


def grid_signature(grid):
    return tuple(tuple(r) for r in grid)


def validate_grid_partial(grid, row_patterns, col_patterns):
    n = len(grid)
    half = n // 2

    for r in range(n):
        if not valid_line_partial(grid[r], half):
            return False
        if not any(compatible_pattern(p, grid[r]) for p in row_patterns):
            return False

    cols = transpose(grid)
    for c in range(n):
        if not valid_line_partial(cols[c], half):
            return False
        if not any(compatible_pattern(p, cols[c]) for p in col_patterns):
            return False

    complete_rows = [tuple(row) for row in grid if line_complete(row)]
    if len(complete_rows) != len(set(complete_rows)):
        return False

    complete_cols = [tuple(col) for col in cols if line_complete(col)]
    if len(complete_cols) != len(set(complete_cols)):
        return False

    return True


def propagate(grid, all_patterns):
    n = len(grid)
    half = n // 2
    row_patterns = all_patterns[n]
    col_patterns = row_patterns

    changed = True
    while changed:
        changed = False

        # Row-wise deductions
        completed_rows = {tuple(row) for row in grid if line_complete(row)}
        for r in range(n):
            row = grid[r]

            new_row, ch = deduce_from_adjacency(row)
            if ch:
                grid[r] = new_row
                changed = True

            new_row, ch = deduce_from_counts(grid[r], half)
            if ch:
                grid[r] = new_row
                changed = True

            new_row, comps = reduce_line_by_patterns(grid[r], row_patterns)
            if new_row is None:
                return None
            if new_row != grid[r]:
                grid[r] = new_row
                changed = True

            new_row, ch = deduce_from_uniqueness_line(grid[r], completed_rows - {tuple(grid[r])}, half)
            if ch:
                grid[r] = new_row
                changed = True

            if not valid_line_partial(grid[r], half):
                return None

        # Column-wise deductions
        cols = transpose(grid)
        completed_cols = {tuple(col) for col in cols if line_complete(col)}
        for c in range(n):
            col = cols[c]

            new_col, ch = deduce_from_adjacency(col)
            if ch:
                cols[c] = new_col
                changed = True

            new_col, ch = deduce_from_counts(cols[c], half)
            if ch:
                cols[c] = new_col
                changed = True

            new_col, comps = reduce_line_by_patterns(cols[c], col_patterns)
            if new_col is None:
                return None
            if new_col != cols[c]:
                cols[c] = new_col
                changed = True

            new_col, ch = deduce_from_uniqueness_line(cols[c], completed_cols - {tuple(cols[c])}, half)
            if ch:
                cols[c] = new_col
                changed = True

            if not valid_line_partial(cols[c], half):
                return None

        if changed:
            grid = transpose(cols)

        if not validate_grid_partial(grid, row_patterns, col_patterns):
            return None

    return grid


def choose_branch(grid, patterns):
    n = len(grid)

    # Choose the most constrained row/column based on compatible pattern count.
    best = None

    for r in range(n):
        if any(v is None for v in grid[r]):
            comp = [p for p in patterns if compatible_pattern(p, grid[r])]
            score = len(comp)
            if score == 0:
                return ('row', r, [])
            if best is None or score < best[2]:
                best = ('row', r, score, comp)

    cols = transpose(grid)
    for c in range(n):
        if any(v is None for v in cols[c]):
            comp = [p for p in patterns if compatible_pattern(p, cols[c])]
            score = len(comp)
            if score == 0:
                return ('col', c, [])
            if best is None or score < best[2]:
                best = ('col', c, score, comp)

    if best is None:
        return None
    return best[0], best[1], best[3]


def solve_grid(grid, all_patterns):
    n = len(grid)
    patterns = all_patterns[n]

    grid = [row[:] for row in grid]
    grid = propagate(grid, all_patterns)
    if grid is None:
        return None

    if all(all(v is not None for v in row) for row in grid):
        cols = transpose(grid)
        half = n // 2
        if all(valid_line_complete(row, half) for row in grid) and all(valid_line_complete(col, half) for col in cols):
            if len({tuple(r) for r in grid}) == n and len({tuple(c) for c in cols}) == n:
                return grid
        return None

    branch = choose_branch(grid, patterns)
    if branch is None:
        return None

    kind, idx, comps = branch
    if not comps:
        return None

    # Try candidate full patterns for the chosen line, but only among compatible valid lines.
    for p in comps:
        new_grid = [row[:] for row in grid]
        if kind == 'row':
            new_grid[idx] = list(p)
        else:
            for r in range(n):
                new_grid[r][idx] = p[r]

        result = solve_grid(new_grid, all_patterns)
        if result is not None:
            return result

    return None


def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)

    if n == 0 or any(len(row) != n for row in grid) or n % 2 != 0:
        return "No Solution"

    all_patterns = {n: generate_valid_patterns(n, n // 2)}

    if not validate_grid_partial(grid, all_patterns[n], all_patterns[n]):
        return "No Solution"

    solved = solve_grid(grid, all_patterns)
    return solved if solved is not None else "No Solution"


