# Solver for the "3x3 black-count" puzzle.
# Output format:
#   same-sized grid using 'B' for black cells and None for white cells
#
# The solver is generalized and uses:
# - local neighborhood constraints
# - strong propagation from min/max feasible black counts
# - hidden-single style deductions from exact residuals
# - contradiction-driven backtracking with most-constrained branching

from copy import deepcopy

def solve(observation):
    data = observation['data']
    h = len(data)
    w = len(data[0]) if h else 0
    n = h * w

    def idx(r, c):
        return r * w + c

    def rc(i):
        return divmod(i, w)

    # Constraint list: each numbered cell constrains its 3x3 neighborhood.
    constraints = []
    cell_to_constraints = [[] for _ in range(n)]
    neigh_cache = {}

    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                cells = []
                for rr in range(max(0, r - 1), min(h, r + 2)):
                    for cc in range(max(0, c - 1), min(w, c + 2)):
                        cells.append(idx(rr, cc))
                cid = len(constraints)
                constraints.append({
                    'target': data[r][c],
                    'cells': cells,
                })
                for v in cells:
                    cell_to_constraints[v].append(cid)

    # For pairwise local deductions, we keep neighboring numbered cells of each cell.
    for r in range(h):
        for c in range(w):
            v = idx(r, c)
            neigh_cache[v] = set()
            for cid in cell_to_constraints[v]:
                for u in constraints[cid]['cells']:
                    neigh_cache[v].add(u)
            neigh_cache[v].discard(v)

    # State:
    #   -1 unknown
    #    0 white
    #    1 black
    state = [-1] * n

    # For each constraint, maintain:
    # known_black, unknown_count
    known_black = [0] * len(constraints)
    unknown_count = [len(c['cells']) for c in constraints]

    # Fast residual computation:
    # residual black still needed among unknowns
    #   rem = target - known_black
    #
    # Feasibility:
    #   0 <= rem <= unknown_count

    assign_stack = []

    def set_cell(v, value, reason_queue):
        cur = state[v]
        if cur == value:
            return True
        if cur != -1:
            return False
        state[v] = value
        assign_stack.append(v)

        for cid in cell_to_constraints[v]:
            unknown_count[cid] -= 1
            if value == 1:
                known_black[cid] += 1
            rem = constraints[cid]['target'] - known_black[cid]
            unk = unknown_count[cid]
            if rem < 0 or rem > unk:
                return False
            reason_queue.append(cid)
        return True

    def undo(to_len):
        while len(assign_stack) > to_len:
            v = assign_stack.pop()
            val = state[v]
            for cid in cell_to_constraints[v]:
                unknown_count[cid] += 1
                if val == 1:
                    known_black[cid] -= 1
            state[v] = -1

    def propagate():
        # Queue of constraints whose bounds may force cells.
        queue = list(range(len(constraints)))
        in_queue = [True] * len(constraints)

        while queue:
            cid = queue.pop()
            in_queue[cid] = False
            c = constraints[cid]
            rem = c['target'] - known_black[cid]
            unk = unknown_count[cid]

            if rem < 0 or rem > unk:
                return False

            # Human-like direct deduction:
            # if rem == 0 => all unknowns in this neighborhood are white
            # if rem == unk => all unknowns in this neighborhood are black
            if unk:
                if rem == 0 or rem == unk:
                    forced_val = 1 if rem == unk else 0
                    touched = []
                    for v in c['cells']:
                        if state[v] == -1:
                            if not set_cell(v, forced_val, touched):
                                return False
                    for x in touched:
                        if not in_queue[x]:
                            in_queue[x] = True
                            queue.append(x)

            # Slightly stronger human-style "only places left" reasoning
            # via overlapping constraints:
            # For any two constraints A and B, inspect A\B or B\A when residuals
            # make one side fully determined.
            # This is still local and cheap due to tiny 3x3 neighborhoods.
            Acells = c['cells']
            Aset = None
            Arem = rem
            Aunk_cells = [v for v in Acells if state[v] == -1]
            if Aunk_cells:
                for other in range(len(constraints)):
                    if other == cid:
                        continue
                    # Only compare nearby constraints that share cells.
                    # A quick skip:
                    if not any(v in cell_to_constraints[Aunk_cells[0]] for v in []):
                        pass
                    oc = constraints[other]
                    # Fast overlap test on tiny lists
                    overlap = False
                    for v in Acells:
                        if v in oc['cells']:
                            overlap = True
                            break
                    if not overlap:
                        continue

                    Brem = oc['target'] - known_black[other]
                    Bunk = unknown_count[other]
                    if Brem < 0 or Brem > Bunk:
                        return False

                    if Aset is None:
                        Aset = set(Acells)
                    Bset = set(oc['cells'])

                    A_only = []
                    B_only = []
                    inter_unknown = 0

                    for v in Aset:
                        if v not in Bset and state[v] == -1:
                            A_only.append(v)
                    for v in Bset:
                        if v not in Aset and state[v] == -1:
                            B_only.append(v)
                    for v in Aset & Bset:
                        if state[v] == -1:
                            inter_unknown += 1

                    # Bounds:
                    # blacks in intersection for A must be in [Arem-len(A_only), Arem]
                    # blacks in intersection for B must be in [Brem-len(B_only), Brem]
                    lowA = max(0, Arem - len(A_only))
                    highA = min(inter_unknown, Arem)
                    lowB = max(0, Brem - len(B_only))
                    highB = min(inter_unknown, Brem)

                    lo = max(lowA, lowB)
                    hi = min(highA, highB)
                    if lo > hi:
                        return False

                    # If A_only must contribute exactly 0 or all its cells, force them.
                    # Because Arem - intersection_count is fixed when lo==hi.
                    if lo == hi:
                        inter_blacks = lo
                        need_A_only = Arem - inter_blacks
                        if need_A_only == 0 or need_A_only == len(A_only):
                            forced_val = 1 if need_A_only == len(A_only) else 0
                            touched = []
                            for v in A_only:
                                if not set_cell(v, forced_val, touched):
                                    return False
                            for x in touched:
                                if not in_queue[x]:
                                    in_queue[x] = True
                                    queue.append(x)

                        need_B_only = Brem - inter_blacks
                        if need_B_only == 0 or need_B_only == len(B_only):
                            forced_val = 1 if need_B_only == len(B_only) else 0
                            touched = []
                            for v in B_only:
                                if not set_cell(v, forced_val, touched):
                                    return False
                            for x in touched:
                                if not in_queue[x]:
                                    in_queue[x] = True
                                    queue.append(x)

        return True

    def choose_branch_var():
        # Most-constrained unknown cell:
        # prioritize smallest feasible domain under neighborhood pressure.
        best_v = None
        best_score = None

        for v in range(n):
            if state[v] != -1:
                continue

            possible0 = True
            possible1 = True
            pressure = 0
            tightness = 0

            for cid in cell_to_constraints[v]:
                target = constraints[cid]['target']
                kb = known_black[cid]
                unk = unknown_count[cid]
                rem = target - kb

                # If v=0, rem must fit in remaining unk-1 cells.
                if not (0 <= rem <= unk - 1):
                    possible0 = False
                # If v=1, rem-1 must fit in remaining unk-1 cells.
                if not (0 <= rem - 1 <= unk - 1):
                    possible1 = False

                pressure += 1
                tightness += min(rem, unk - rem)

            if not possible0 and not possible1:
                return None, None
            if possible0 and not possible1:
                return v, [0]
            if possible1 and not possible0:
                return v, [1]

            score = (-pressure, tightness)
            if best_score is None or score < best_score:
                best_score = score
                best_v = v

        return best_v, [0, 1] if best_v is not None else (None, None)

    def search():
        if not propagate():
            return False

        # If all cells assigned, solution found.
        done = True
        for v in range(n):
            if state[v] == -1:
                done = False
                break
        if done:
            return True

        v, domain = choose_branch_var()
        if v is None:
            return False

        # Value ordering: prefer value supported by tighter local constraints.
        # Compute simple heuristic.
        if len(domain) == 2:
            score_black = 0
            score_white = 0
            for cid in cell_to_constraints[v]:
                rem = constraints[cid]['target'] - known_black[cid]
                unk = unknown_count[cid]
                if rem == unk:
                    score_black += 5
                if rem == 0:
                    score_white += 5
                score_black += rem
                score_white += (unk - rem)
            if score_black > score_white:
                domain = [1, 0]
            else:
                domain = [0, 1]

        base = len(assign_stack)
        for val in domain:
            touched = []
            if set_cell(v, val, touched):
                if search():
                    return True
            undo(base)
        return False

    if search():
        ans = []
        for r in range(h):
            row = []
            for c in range(w):
                row.append('B' if state[idx(r, c)] == 1 else None)
            ans.append(row)
        return str(ans)
    return "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

