# Generalized solver for consecutive-adjacency Latin square puzzles (Kropki-style, black-dot-only meaning consecutive,
# and absence of dot means not consecutive for orthogonal neighbors).

from collections import deque

ALL = None

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length()
            mask ^= lsb

    def popcount(x):
        return x.bit_count()

    # Build edge map: orthogonally adjacent cells, True iff consecutive-required dot exists.
    dotted = set()
    for a, b in observation['adjacent']:
        dotted.add((a, b))

    edge = {}
    neighbors = [[] for _ in range(n * n)]

    def idx(r, c):
        return r * n + c

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if c + 1 < n:
                has_dot = (float(r), c + 0.5) in dotted
                j = idx(r, c + 1)
                edge[(i, j)] = edge[(j, i)] = has_dot
                neighbors[i].append(j)
                neighbors[j].append(i)
            if r + 1 < n:
                has_dot = (r + 0.5, float(c)) in dotted
                j = idx(r + 1, c)
                edge[(i, j)] = edge[(j, i)] = has_dot
                neighbors[i].append(j)
                neighbors[j].append(i)

    # Allowed pair masks for consecutive / non-consecutive relation.
    consec_mask = [0] * (n + 1)
    nonconsec_mask = [0] * (n + 1)
    for v in range(1, n + 1):
        m1 = 0
        if v > 1:
            m1 |= bit(v - 1)
        if v < n:
            m1 |= bit(v + 1)
        consec_mask[v] = m1
        nonconsec_mask[v] = full_mask & ~m1

    # Domains.
    domains = [full_mask] * (n * n)
    row_missing = [full_mask for _ in range(n)]
    col_missing = [full_mask for _ in range(n)]

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            i = idx(r, c)
            if v is not None:
                domains[i] = bit(v)

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if popcount(domains[i]) == 1:
                v = domains[i].bit_length()
                row_missing[r] &= ~bit(v)
                col_missing[c] &= ~bit(v)

    # Initial row/col pruning from givens.
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            domains[i] &= row_missing[r] | domains[i]
            domains[i] &= col_missing[c] | domains[i]

    # Precompute unit cell indices.
    row_cells = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c) for r in range(n)] for c in range(n)]

    def singleton_value(mask):
        return mask.bit_length() if mask and (mask & (mask - 1)) == 0 else None

    def restrict_by_neighbor(mask_i, mask_j, has_dot):
        # Return filtered mask_i keeping values having support in mask_j.
        out = 0
        mm = mask_i
        while mm:
            lsb = mm & -mm
            v = lsb.bit_length()
            allowed = consec_mask[v] if has_dot else nonconsec_mask[v]
            if mask_j & allowed:
                out |= lsb
            mm ^= lsb
        return out

    def copy_state(domains, row_missing, col_missing):
        return domains[:], row_missing[:], col_missing[:]

    def assign(domains, row_missing, col_missing, cell, value_mask, queue):
        old = domains[cell]
        new = old & value_mask
        if new == 0:
            return False
        if new == old:
            return True
        domains[cell] = new
        queue.append(cell)
        return True

    def propagate(domains, row_missing, col_missing, initial_cells=None):
        queue = deque(initial_cells or range(n * n))

        # Rebuild missing masks from current singletons.
        row_missing[:] = [full_mask for _ in range(n)]
        col_missing[:] = [full_mask for _ in range(n)]
        for r in range(n):
            for c in range(n):
                m = domains[idx(r, c)]
                if m == 0:
                    return False
                if popcount(m) == 1:
                    v = m.bit_length()
                    b = bit(v)
                    if not (row_missing[r] & b):
                        return False
                    if not (col_missing[c] & b):
                        return False
                    row_missing[r] &= ~b
                    col_missing[c] &= ~b

        in_queue = [False] * (n * n)
        for x in queue:
            in_queue[x] = True

        def push(x):
            if not in_queue[x]:
                in_queue[x] = True
                queue.append(x)

        while queue:
            i = queue.popleft()
            in_queue[i] = False
            r, c = divmod(i, n)
            mi = domains[i]
            if mi == 0:
                return False

            # Latin constraints with row/column missing masks.
            allowed = row_missing[r] | mi
            nm = mi & allowed
            allowed = col_missing[c] | nm
            nm &= allowed
            if nm == 0:
                return False
            if nm != mi:
                domains[i] = nm
                mi = nm
                for j in row_cells[r]:
                    if j != i:
                        push(j)
                for j in col_cells[c]:
                    if j != i:
                        push(j)
                for j in neighbors[i]:
                    push(j)

            # If singleton, remove from row/column peers.
            if popcount(mi) == 1:
                v = mi.bit_length()
                b = bit(v)
                if row_missing[r] & b:
                    row_missing[r] &= ~b
                    for j in row_cells[r]:
                        if j != i:
                            mj = domains[j]
                            if mj & b:
                                nj = mj & ~b
                                if nj == 0:
                                    return False
                                if nj != mj:
                                    domains[j] = nj
                                    push(j)
                                    for k in neighbors[j]:
                                        push(k)
                    for j in row_cells[r]:
                        push(j)
                if col_missing[c] & b:
                    col_missing[c] &= ~b
                    for j in col_cells[c]:
                        if j != i:
                            mj = domains[j]
                            if mj & b:
                                nj = mj & ~b
                                if nj == 0:
                                    return False
                                if nj != mj:
                                    domains[j] = nj
                                    push(j)
                                    for k in neighbors[j]:
                                        push(k)
                    for j in col_cells[c]:
                        push(j)

            # Consecutive / non-consecutive adjacency propagation.
            for j in neighbors[i]:
                mj = domains[j]
                has_dot = edge[(i, j)]
                ni = restrict_by_neighbor(domains[i], mj, has_dot)
                if ni == 0:
                    return False
                if ni != domains[i]:
                    domains[i] = ni
                    mi = ni
                    for k in row_cells[r]:
                        if k != i:
                            push(k)
                    for k in col_cells[c]:
                        if k != i:
                            push(k)
                    for k in neighbors[i]:
                        push(k)

                nj = restrict_by_neighbor(domains[j], domains[i], has_dot)
                if nj == 0:
                    return False
                if nj != mj:
                    domains[j] = nj
                    push(j)
                    rr, cc = divmod(j, n)
                    for k in row_cells[rr]:
                        if k != j:
                            push(k)
                    for k in col_cells[cc]:
                        if k != j:
                            push(k)
                    for k in neighbors[j]:
                        push(k)

            # Hidden singles in row.
            for unit in (row_cells[r], col_cells[c]):
                missing_vals = 0
                seen_single = 0
                for u in unit:
                    mu = domains[u]
                    if popcount(mu) == 1:
                        seen_single |= mu
                    missing_vals |= mu
                # If a value can only appear in one cell in the unit, assign it.
                vals = missing_vals
                while vals:
                    lsb = vals & -vals
                    count_pos = 0
                    last_u = -1
                    for u in unit:
                        if domains[u] & lsb:
                            count_pos += 1
                            last_u = u
                            if count_pos > 1:
                                break
                    if count_pos == 0:
                        return False
                    if count_pos == 1 and domains[last_u] != lsb:
                        domains[last_u] = lsb
                        push(last_u)
                        rr, cc = divmod(last_u, n)
                        for k in row_cells[rr]:
                            if k != last_u:
                                push(k)
                        for k in col_cells[cc]:
                            if k != last_u:
                                push(k)
                        for k in neighbors[last_u]:
                            push(k)
                    vals ^= lsb

                # Hall-style subset rule via candidate signatures.
                groups = {}
                for u in unit:
                    mu = domains[u]
                    if popcount(mu) > 1:
                        groups.setdefault(mu, []).append(u)
                for mask, cells in groups.items():
                    pc = popcount(mask)
                    if len(cells) == pc and pc >= 2:
                        for u in unit:
                            if u not in cells:
                                mu = domains[u]
                                nu = mu & ~mask
                                if nu == 0:
                                    return False
                                if nu != mu:
                                    domains[u] = nu
                                    push(u)
                                    rr, cc = divmod(u, n)
                                    for k in neighbors[u]:
                                        push(k)

        # Final consistency: row/col cannot miss impossible values.
        for r in range(n):
            for v in range(1, n + 1):
                b = bit(v)
                count = 0
                for i in row_cells[r]:
                    if domains[i] & b:
                        count += 1
                if count != 1:
                    return False
        for c in range(n):
            for v in range(1, n + 1):
                b = bit(v)
                count = 0
                for i in col_cells[c]:
                    if domains[i] & b:
                        count += 1
                if count != 1:
                    return False
        return True

    def solved(domains):
        return all(popcount(m) == 1 for m in domains)

    def choose_branch_cell(domains):
        # MRV + degree-like tie-breaker using constrained neighbors and unit pressure.
        best = None
        best_key = None
        for i, m in enumerate(domains):
            pc = popcount(m)
            if pc <= 1:
                continue
            r, c = divmod(i, n)
            deg = sum(1 for j in neighbors[i] if popcount(domains[j]) > 1)
            key = (pc, -(deg + sum(popcount(domains[j]) > 1 for j in row_cells[r]) + sum(popcount(domains[j]) > 1 for j in col_cells[c])))
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def value_order(cell, domains):
        # Least-constraining-value estimate.
        r, c = divmod(cell, n)
        m = domains[cell]
        scores = []
        for v in bits(m):
            b = bit(v)
            score = 0
            for j in row_cells[r]:
                if j != cell and (domains[j] & b):
                    score += 1
            for j in col_cells[c]:
                if j != cell and (domains[j] & b):
                    score += 1
            for j in neighbors[cell]:
                allowed = consec_mask[v] if edge[(cell, j)] else nonconsec_mask[v]
                score += popcount(domains[j] & ~allowed)
            scores.append((score, b))
        scores.sort()
        return [b for _, b in scores]

    if not propagate(domains, row_missing, col_missing):
        return "No Solution"

    def dfs(domains, row_missing, col_missing):
        if solved(domains):
            grid = [[domains[idx(r, c)].bit_length() for c in range(n)] for r in range(n)]
            return str(grid)

        cell = choose_branch_cell(domains)
        if cell is None:
            return "No Solution"

        for vm in value_order(cell, domains):
            nd, nr, nc = copy_state(domains, row_missing, col_missing)
            nd[cell] = vm
            if propagate(nd, nr, nc, [cell]):
                ans = dfs(nd, nr, nc)
                if ans != "No Solution":
                    return ans
        return "No Solution"

    return dfs(domains, row_missing, col_missing)

