# Generalized consecutive-adjacency Latin square solver.
# The puzzle is:
# - Fill NxN with 1..N
# - Each row/column is a permutation
# - Dots indicate consecutive values
# - Lack of dot between orthogonally adjacent cells means not consecutive
#
# The implementation emphasizes human-like deduction:
# 1) Candidate initialization from givens.
# 2) Repeated propagation by:
#    - given assignments
#    - row/column used values
#    - adjacency (consecutive / not consecutive)
#    - hidden singles in rows/columns
#    - pairwise support checks on adjacent cells
# 3) Search only on most constrained cell when logic stalls.

from collections import deque

ALL_MASK_CACHE = {}

def bit(v):
    return 1 << (v - 1)

def popcount(x):
    return x.bit_count()

def mask_values(mask, n):
    return [i + 1 for i in range(n) if (mask >> i) & 1]

def min_value(mask):
    return (mask & -mask).bit_length()

def value_of_singleton(mask):
    return (mask.bit_length())

def consecutive_mask(mask, n):
    # Values that can be consecutive with some value in mask.
    res = 0
    if mask << 1:
        res |= (mask << 1)
    res |= (mask >> 1)
    return res & ((1 << n) - 1)

def nonconsecutive_mask(mask, n):
    return ((1 << n) - 1) & ~consecutive_mask(mask, n)

def parse_observation(observation):
    data = observation['data']
    n = len(data)
    dots = set((float(r), float(c)) for r, c in observation['adjacent'])
    return n, data, dots

def neighbors(n, r, c):
    if r > 0:
        yield r - 1, c, (r - 0.5, c)
    if r + 1 < n:
        yield r + 1, c, (r + 0.5, c)
    if c > 0:
        yield r, c - 1, (r, c - 0.5)
    if c + 1 < n:
        yield r, c + 1, (r, c + 0.5)

class State:
    __slots__ = ('n', 'full', 'domains', 'row_used', 'col_used', 'dots', 'queue')
    def __init__(self, n, dots):
        self.n = n
        self.full = (1 << n) - 1
        self.domains = [[self.full for _ in range(n)] for _ in range(n)]
        self.row_used = [0] * n
        self.col_used = [0] * n
        self.dots = dots
        self.queue = deque()

    def clone(self):
        other = State(self.n, self.dots)
        other.domains = [row[:] for row in self.domains]
        other.row_used = self.row_used[:]
        other.col_used = self.col_used[:]
        other.queue = deque(self.queue)
        return other

def assign(state, r, c, val):
    m = bit(val)
    cur = state.domains[r][c]
    if cur == m:
        return True
    if not (cur & m):
        return False
    return reduce_domain(state, r, c, m)

def reduce_domain(state, r, c, new_mask):
    cur = state.domains[r][c]
    new_mask &= cur
    if new_mask == cur:
        return True
    if new_mask == 0:
        return False
    state.domains[r][c] = new_mask
    state.queue.append((r, c))
    if popcount(new_mask) == 1 and popcount(cur) != 1:
        v = value_of_singleton(new_mask)
        vm = bit(v)
        if state.row_used[r] & vm and cur != vm:
            return False
        if state.col_used[c] & vm and cur != vm:
            return False
        state.row_used[r] |= vm
        state.col_used[c] |= vm
    return True

def initial_setup(state, data):
    n = state.n
    # Apply givens first.
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                if not assign(state, r, c, data[r][c]):
                    return False
    # Queue everything for broad initial propagation.
    for r in range(n):
        for c in range(n):
            state.queue.append((r, c))
    return propagate(state)

def enforce_row_col_used(state, r, c):
    mask = state.domains[r][c]
    forbidden = state.row_used[r] | state.col_used[c]
    if popcount(mask) == 1:
        v = value_of_singleton(mask)
        forbidden &= ~bit(v)
    return reduce_domain(state, r, c, mask & ~forbidden)

def enforce_adjacency_local(state, r, c):
    n = state.n
    mask = state.domains[r][c]
    if mask == 0:
        return False

    for nr, nc, mid in neighbors(n, r, c):
        nmask = state.domains[nr][nc]
        dotted = mid in state.dots
        allowed_for_this = consecutive_mask(nmask, n) if dotted else nonconsecutive_mask(nmask, n)
        new_mask = mask & allowed_for_this
        if new_mask != mask:
            if not reduce_domain(state, r, c, new_mask):
                return False
            mask = new_mask
            if mask == 0:
                return False

    # Also prune neighbors by support from this cell.
    mask = state.domains[r][c]
    for nr, nc, mid in neighbors(n, r, c):
        nmask = state.domains[nr][nc]
        dotted = mid in state.dots
        allowed_for_neighbor = consecutive_mask(mask, n) if dotted else nonconsecutive_mask(mask, n)
        if not reduce_domain(state, nr, nc, nmask & allowed_for_neighbor):
            return False
    return True

def hidden_singles_unit(state, cells):
    n = state.n
    count_masks = [0] * (n + 1)
    places = [None] * (n + 1)
    for r, c in cells:
        mask = state.domains[r][c]
        x = mask
        while x:
            b = x & -x
            v = b.bit_length()
            count_masks[v] += 1
            places[v] = (r, c)
            x ^= b
    for v in range(1, n + 1):
        if count_masks[v] == 0:
            return False
        if count_masks[v] == 1:
            r, c = places[v]
            if not assign(state, r, c, v):
                return False
    return True

def propagate(state):
    n = state.n
    while True:
        while state.queue:
            r, c = state.queue.popleft()
            if not enforce_row_col_used(state, r, c):
                return False
            if not enforce_adjacency_local(state, r, c):
                return False

            mask = state.domains[r][c]
            if popcount(mask) == 1:
                v = value_of_singleton(mask)
                vm = bit(v)
                # Eliminate from peers.
                for cc in range(n):
                    if cc != c:
                        peer = state.domains[r][cc]
                        if peer & vm:
                            if not reduce_domain(state, r, cc, peer & ~vm):
                                return False
                for rr in range(n):
                    if rr != r:
                        peer = state.domains[rr][c]
                        if peer & vm:
                            if not reduce_domain(state, rr, c, peer & ~vm):
                                return False

        snapshot = tuple(tuple(row) for row in state.domains)

        # Hidden singles in rows and columns.
        for r in range(n):
            if not hidden_singles_unit(state, [(r, c) for c in range(n)]):
                return False
        for c in range(n):
            if not hidden_singles_unit(state, [(r, c) for r in range(n)]):
                return False

        # Hall-set-lite: naked pairs in rows and columns.
        for is_row in (True, False):
            for idx in range(n):
                cells = [(idx, c) for c in range(n)] if is_row else [(r, idx) for r in range(n)]
                pairs = {}
                for r, c in cells:
                    m = state.domains[r][c]
                    if popcount(m) == 2:
                        pairs.setdefault(m, []).append((r, c))
                for m, ps in pairs.items():
                    if len(ps) == 2:
                        for r, c in cells:
                            if (r, c) not in ps:
                                if state.domains[r][c] & m:
                                    if not reduce_domain(state, r, c, state.domains[r][c] & ~m):
                                        return False

        if state.queue:
            continue

        new_snapshot = tuple(tuple(row) for row in state.domains)
        if new_snapshot == snapshot:
            break

    # Final consistency checks.
    full = state.full
    for r in range(n):
        union = 0
        for c in range(n):
            m = state.domains[r][c]
            if m == 0:
                return False
            union |= m
        if union != full:
            return False
    for c in range(n):
        union = 0
        for r in range(n):
            m = state.domains[r][c]
            if m == 0:
                return False
            union |= m
        if union != full:
            return False
    return True

def solved(state):
    n = state.n
    for r in range(n):
        for c in range(n):
            if popcount(state.domains[r][c]) != 1:
                return False
    return True

def choose_branch_cell(state):
    n = state.n
    best = None
    best_score = None
    for r in range(n):
        for c in range(n):
            m = state.domains[r][c]
            pc = popcount(m)
            if pc <= 1:
                continue
            # Most constrained variable + adjacency pressure.
            deg = 0
            for nr, nc, mid in neighbors(n, r, c):
                deg += 2 if mid in state.dots else 1
                deg += 1 if popcount(state.domains[nr][nc]) > 1 else 0
            score = (pc, -deg)
            if best_score is None or score < best_score:
                best_score = score
                best = (r, c)
    return best

def order_values(state, r, c):
    n = state.n
    vals = mask_values(state.domains[r][c], n)
    scored = []
    for v in vals:
        score = 0
        vm = bit(v)
        # Prefer values compatible with neighbors and less conflicting in row/col.
        for nr, nc, mid in neighbors(n, r, c):
            nm = state.domains[nr][nc]
            allowed = consecutive_mask(vm, n) if mid in state.dots else nonconsecutive_mask(vm, n)
            score += popcount(nm & allowed)
        row_conf = sum(1 for cc in range(n) if cc != c and (state.domains[r][cc] & vm))
        col_conf = sum(1 for rr in range(n) if rr != r and (state.domains[rr][c] & vm))
        scored.append((-(score), row_conf + col_conf, v))
    scored.sort()
    return [v for _, __, v in scored]

def search(state):
    if not propagate(state):
        return None
    if solved(state):
        return state

    cell = choose_branch_cell(state)
    if cell is None:
        return None
    r, c = cell

    for v in order_values(state, r, c):
        child = state.clone()
        if assign(child, r, c, v):
            res = search(child)
            if res is not None:
                return res

    return None

def format_solution(state):
    n = state.n
    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            m = state.domains[r][c]
            if popcount(m) != 1:
                return "No Solution"
            row.append(value_of_singleton(m))
        grid.append(row)
    return str(grid)

def solve(observation):
    n, data, dots = parse_observation(observation)
    state = State(n, dots)
    if not initial_setup(state, data):
        return "No Solution"
    res = search(state)
    if res is None:
        return "No Solution"
    return format_solution(res)

if __name__ == "__main__":
    print(solve(OBSERVATION))

