# Generalized solver for consecutive-adjacency Latin square puzzles.
# Strategy:
# 1) Represent each cell by a bitmask of candidates.
# 2) Apply strong human-like propagation:
#    - row/column elimination from fixed digits
#    - hidden singles in row/column
#    - edge-based consecutive / non-consecutive filtering
#    - support checking on each adjacency edge
#    - Hall-set / naked-subset reductions on rows and columns
#    - singleton forcing loop until fixpoint
# 3) If unresolved, branch on the most constrained cell and continue propagation.
#
# This is not naive brute force: every recursive step performs substantial deduction,
# uses MRV branching, and updates are heavily pruned by adjacency support tests.

from itertools import combinations

def solve(observation):
    data = observation['data']
    dots = observation['adjacent']
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def is_single(mask):
        return mask and (mask & (mask - 1) == 0)

    def single_value(mask):
        return mask.bit_length()

    # Precompute masks for consecutive and non-consecutive compatibility.
    consec_mask = [0] * (n + 1)
    nonconsec_mask = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < n:
            m |= bit(v + 1)
        consec_mask[v] = m
        nonconsec_mask[v] = full & ~m

    # Build adjacency map for all orthogonally adjacent pairs.
    edge_has_dot = set()
    for a, b in dots:
        edge_has_dot.add((a, b))

    neighbors = [[] for _ in range(n * n)]

    def idx(r, c):
        return r * n + c

    for r in range(n):
        for c in range(n):
            u = idx(r, c)
            for dr, dc, mid in ((0, 1, (float(r), c + 0.5)),
                                (1, 0, (r + 0.5, float(c)))):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    v = idx(rr, cc)
                    has_dot = mid in edge_has_dot
                    neighbors[u].append((v, has_dot))
                    neighbors[v].append((u, has_dot))

    row_cells = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c) for r in range(n)] for c in range(n)]

    # Initial candidate masks.
    masks = [full] * (n * n)
    for r in range(n):
        for c in range(n):
            val = data[r][c]
            if val is not None:
                masks[idx(r, c)] = bit(val)

    def assign(state, p, new_mask):
        old = state[p]
        nm = old & new_mask
        if nm == 0:
            return False
        if nm == old:
            return True
        state[p] = nm
        return True

    def filter_by_edge(state, p, q, has_dot):
        mp = state[p]
        mq = state[q]
        np = 0
        for vp in values(mp):
            support = consec_mask[vp] if has_dot else nonconsec_mask[vp]
            if support & mq:
                np |= bit(vp)
        if np == 0:
            return False
        nq = 0
        for vq in values(mq):
            support = consec_mask[vq] if has_dot else nonconsec_mask[vq]
            if support & np:
                nq |= bit(vq)
        if nq == 0:
            return False
        state[p] = np
        state[q] = nq
        return True

    def eliminate_fixed_from_unit(state, cells):
        fixed_union = 0
        for p in cells:
            if is_single(state[p]):
                fixed_union |= state[p]
        for p in cells:
            if not is_single(state[p]):
                nm = state[p] & ~fixed_union
                if nm == 0:
                    return False
                state[p] = nm
        # Duplicate fixed digits forbidden.
        seen = 0
        for p in cells:
            if is_single(state[p]):
                if seen & state[p]:
                    return False
                seen |= state[p]
        return True

    def hidden_singles_unit(state, cells):
        for v in range(1, n + 1):
            b = bit(v)
            places = []
            for p in cells:
                if state[p] & b:
                    places.append(p)
                    if len(places) > 1 and is_single(state[places[0]]) and state[places[0]] == b:
                        break
            if not places:
                return False
            if len(places) == 1:
                state[places[0]] = b
        return True

    def subset_reduction_unit(state, cells):
        # Human-like naked/hidden subsets (Hall sets), bounded for efficiency.
        uns = [p for p in cells if not is_single(state[p])]
        m = len(uns)
        if m < 2:
            return True
        limit = min(4, m - 1)
        cell_masks = [state[p] for p in uns]
        for k in range(2, limit + 1):
            for comb in combinations(range(m), k):
                union = 0
                for i in comb:
                    union |= cell_masks[i]
                if popcount(union) == k:
                    # Naked subset: remove union from other cells in unit.
                    chosen = {uns[i] for i in comb}
                    for p in cells:
                        if p not in chosen:
                            nm = state[p] & ~union
                            if nm == 0:
                                return False
                            state[p] = nm
        # Hidden subsets: if a set of k values appears only in k cells, restrict those cells.
        vals = list(range(1, n + 1))
        for k in range(2, min(4, n - 1) + 1):
            for combv in combinations(vals, k):
                union_vals = 0
                for v in combv:
                    union_vals |= bit(v)
                carriers = []
                for p in cells:
                    if state[p] & union_vals:
                        carriers.append(p)
                if 1 <= len(carriers) < k:
                    return False
                if len(carriers) == k:
                    for p in carriers:
                        nm = state[p] & union_vals
                        if nm == 0:
                            return False
                        state[p] = nm
        return True

    def propagate(state):
        changed = True
        while changed:
            before = tuple(state)

            # Row/column Latin propagation.
            for r in range(n):
                if not eliminate_fixed_from_unit(state, row_cells[r]):
                    return None
            for c in range(n):
                if not eliminate_fixed_from_unit(state, col_cells[c]):
                    return None

            # Hidden singles.
            for r in range(n):
                if not hidden_singles_unit(state, row_cells[r]):
                    return None
            for c in range(n):
                if not hidden_singles_unit(state, col_cells[c]):
                    return None

            # Adjacency support filtering.
            for p in range(n * n):
                for q, has_dot in neighbors[p]:
                    if p < q:
                        if not filter_by_edge(state, p, q, has_dot):
                            return None

            # Re-run Latin elimination after edge reductions.
            for r in range(n):
                if not eliminate_fixed_from_unit(state, row_cells[r]):
                    return None
            for c in range(n):
                if not eliminate_fixed_from_unit(state, col_cells[c]):
                    return None

            # Subset logic.
            for r in range(n):
                if not subset_reduction_unit(state, row_cells[r]):
                    return None
            for c in range(n):
                if not subset_reduction_unit(state, col_cells[c]):
                    return None

            # Final consistency checks.
            for p in range(n * n):
                if state[p] == 0:
                    return None
            for r in range(n):
                seen = 0
                for p in row_cells[r]:
                    if is_single(state[p]):
                        if seen & state[p]:
                            return None
                        seen |= state[p]
            for c in range(n):
                seen = 0
                for p in col_cells[c]:
                    if is_single(state[p]):
                        if seen & state[p]:
                            return None
                        seen |= state[p]

            changed = tuple(state) != before

        return state

    def solved(state):
        return all(is_single(m) for m in state)

    def choose_branch_cell(state):
        best_p = -1
        best_score = None
        for p, m in enumerate(state):
            pc = popcount(m)
            if pc > 1:
                # Prefer minimum remaining values; tie-break by number of constrained neighbors.
                deg = sum(1 for _q, _d in neighbors[p])
                score = (pc, -deg)
                if best_score is None or score < best_score:
                    best_score = score
                    best_p = p
        return best_p

    def order_values(state, p):
        # Least-constraining-value heuristic using row/col + adjacency impact.
        r, c = divmod(p, n)
        peers = set(row_cells[r] + col_cells[c])
        peers.discard(p)
        scored = []
        for v in values(state[p]):
            b = bit(v)
            impact = 0
            for q in peers:
                if state[q] & b:
                    impact += 1
            for q, has_dot in neighbors[p]:
                support = consec_mask[v] if has_dot else nonconsec_mask[v]
                impact += popcount(state[q] & ~support)
            scored.append((impact, v))
        scored.sort()
        return [v for _, v in scored]

    def dfs(state):
        state = propagate(state[:])
        if state is None:
            return None
        if solved(state):
            return state

        p = choose_branch_cell(state)
        if p < 0:
            return None

        for v in order_values(state, p):
            child = state[:]
            child[p] = bit(v)
            ans = dfs(child)
            if ans is not None:
                return ans
        return None

    ans = dfs(masks)
    if ans is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(ans[idx(r, c)]))
        grid.append(row)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

