from collections import defaultdict, deque

# Generalized solver for the stitch puzzle described by OBSERVATION.
# Model:
# - Each required boundary adjacency between different regions corresponds to one "edge-variable".
# - That variable can be realized by exactly one of the two endpoint unit segments on the shared side.
# - Unit segments live on the hole grid, use two orthogonally adjacent holes, and no two selected segments may share a hole.
# - Row/column clues count used holes per hole-row/hole-column.

def solve(observation):
    region = observation["region"]
    row_target = observation["row_stitch_counts"]
    col_target = observation["col_stitch_counts"]
    n = len(region)

    edge_opts, seg_to_edges, holes_of_seg, seg_rows, seg_cols = build_model(region)
    if edge_opts is None:
        return "No Solution"

    state = init_state(n, edge_opts, seg_to_edges, holes_of_seg, seg_rows, seg_cols, row_target, col_target)
    if not propagate(state):
        return "No Solution"

    result = search(state)
    if result is None:
        return "No Solution"

    answer = []
    for seg in sorted(result["selected"]):
        h1, h2 = holes_of_seg[seg]
        answer.append([h1, h2])
    return repr(answer)


def build_model(region):
    n = len(region)
    edge_opts = []
    seg_to_edges = defaultdict(list)
    holes_of_seg = {}
    seg_rows = {}
    seg_cols = {}

    def add_seg(kind, r, c):
        # kind 'H': between holes (r,c) and (r,c+1)
        # kind 'V': between holes (r,c) and (r+1,c)
        key = (kind, r, c)
        if key not in holes_of_seg:
            if kind == 'H':
                h1, h2 = (r, c), (r, c + 1)
            else:
                h1, h2 = (r, c), (r + 1, c)
            holes_of_seg[key] = (h1, h2)
            rs = {h1[0], h2[0]}
            cs = {h1[1], h2[1]}
            seg_rows[key] = rs
            seg_cols[key] = cs
        return key

    # For each orthogonally adjacent differing-region cell pair, create one edge-variable.
    # It can be stitched by one of the two unit segments at the side's endpoints.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                # Shared vertical cell side from hole (r,c+1) to (r+1,c+1)
                opt1 = add_seg('V', r, c + 1)
                opt2 = add_seg('V', r, c + 1)  # same geometrical side? Need unit segment at endpoints, not whole side.
                # According to rule/diagram, a stitch is unit length between adjacent holes.
                # For a cell boundary, the crossing stitch may be placed on one of the two endpoint segments perpendicular? No.
                # Here we interpret "connected by exactly one stitch" as one stitch lying on the shared border segment.
                # Since border between adjacent cells is itself one unit long, there is exactly one possible stitch.
                # Thus each differing adjacency induces exactly one mandatory segment.
                edge_idx = len(edge_opts)
                edge_opts.append([opt1])
                seg_to_edges[opt1].append(edge_idx)

    # Rebuild correctly for horizontal adjacencies too
    current_len = len(edge_opts)
    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                opt1 = add_seg('H', r + 1, c)
                edge_idx = len(edge_opts)
                edge_opts.append([opt1])
                seg_to_edges[opt1].append(edge_idx)

    # Normalize singleton options and detect impossible duplicate demands on same segment:
    # If the exact same segment is required by multiple region adjacencies, it would need to satisfy all.
    # That's allowed only if "every pair ... is connected by exactly one stitch" means one stitch can serve only one pair.
    # Since pairs are distinct boundaries, same segment cannot represent multiple boundaries simultaneously.
    # Hence multiple edge-vars sharing same singleton segment is impossible.
    forced_count = defaultdict(int)
    for opts in edge_opts:
        if len(opts) != 1:
            return None, None, None, None, None
        forced_count[opts[0]] += 1
    if any(v > 1 for v in forced_count.values()):
        return None, None, None, None, None

    return edge_opts, dict(seg_to_edges), holes_of_seg, seg_rows, seg_cols


def init_state(n, edge_opts, seg_to_edges, holes_of_seg, seg_rows, seg_cols, row_target, col_target):
    row_used = [0] * n
    col_used = [0] * n

    hole_to_selected_count = defaultdict(int)
    hole_to_incident = defaultdict(list)
    for seg, (h1, h2) in holes_of_seg.items():
        hole_to_incident[h1].append(seg)
        hole_to_incident[h2].append(seg)

    possible = set(holes_of_seg.keys())
    selected = set()
    banned = set()

    # Since every edge currently singleton-required, all are initially unresolved but effectively forced.
    edge_status = [0] * len(edge_opts)  # 0 unresolved, 1 satisfied, -1 impossible

    return {
        "n": n,
        "edge_opts": edge_opts,
        "seg_to_edges": seg_to_edges,
        "holes_of_seg": holes_of_seg,
        "seg_rows": seg_rows,
        "seg_cols": seg_cols,
        "row_target": row_target,
        "col_target": col_target,
        "row_used": row_used,
        "col_used": col_used,
        "hole_to_selected_count": hole_to_selected_count,
        "hole_to_incident": hole_to_incident,
        "possible": possible,
        "selected": selected,
        "banned": banned,
        "edge_status": edge_status,
        "queue_force": deque(),
    }


def clone_state(state):
    new = {
        "n": state["n"],
        "edge_opts": state["edge_opts"],
        "seg_to_edges": state["seg_to_edges"],
        "holes_of_seg": state["holes_of_seg"],
        "seg_rows": state["seg_rows"],
        "seg_cols": state["seg_cols"],
        "row_target": state["row_target"],
        "col_target": state["col_target"],
        "row_used": state["row_used"][:],
        "col_used": state["col_used"][:],
        "hole_to_selected_count": defaultdict(int, state["hole_to_selected_count"]),
        "hole_to_incident": state["hole_to_incident"],
        "possible": set(state["possible"]),
        "selected": set(state["selected"]),
        "banned": set(state["banned"]),
        "edge_status": state["edge_status"][:],
        "queue_force": deque(state["queue_force"]),
    }
    return new


def ban_seg(state, seg):
    if seg in state["selected"]:
        return False
    if seg in state["banned"]:
        return True
    state["banned"].add(seg)
    state["possible"].discard(seg)
    for e in state["seg_to_edges"].get(seg, []):
        if state["edge_status"][e] == 0:
            opts = state["edge_opts"][e]
            avail = [s for s in opts if s not in state["banned"]]
            if not avail:
                state["edge_status"][e] = -1
                return False
            if len(avail) == 1:
                state["queue_force"].append(avail[0])
    return True


def select_seg(state, seg):
    if seg in state["banned"]:
        return False
    if seg in state["selected"]:
        return True
    h1, h2 = state["holes_of_seg"][seg]
    if state["hole_to_selected_count"][h1] or state["hole_to_selected_count"][h2]:
        return False

    state["selected"].add(seg)
    state["possible"].discard(seg)

    for h in (h1, h2):
        state["hole_to_selected_count"][h] += 1
        if state["hole_to_selected_count"][h] > 1:
            return False
        rr, cc = h
        state["row_used"][rr] += 1
        state["col_used"][cc] += 1
        if state["row_used"][rr] > state["row_target"][rr]:
            return False
        if state["col_used"][cc] > state["col_target"][cc]:
            return False
        for other in state["hole_to_incident"][h]:
            if other != seg:
                if not ban_seg(state, other):
                    return False

    for e in state["seg_to_edges"].get(seg, []):
        if state["edge_status"][e] == 1:
            return False
        state["edge_status"][e] = 1
        for other in state["edge_opts"][e]:
            if other != seg:
                if not ban_seg(state, other):
                    return False
    return True


def row_col_bounds_ok(state):
    n = state["n"]
    row_rem = [0] * n
    col_rem = [0] * n
    for seg in state["possible"]:
        if seg in state["selected"]:
            continue
        for r in state["seg_rows"][seg]:
            row_rem[r] += 1
        for c in state["seg_cols"][seg]:
            col_rem[c] += 1

    for i in range(n):
        need = state["row_target"][i] - state["row_used"][i]
        if need < 0 or need > row_rem[i]:
            return False
    for j in range(n):
        need = state["col_target"][j] - state["col_used"][j]
        if need < 0 or need > col_rem[j]:
            return False
    return True


def force_from_counts(state):
    changed = True
    while changed:
        changed = False
        n = state["n"]

        row_cands = [[] for _ in range(n)]
        col_cands = [[] for _ in range(n)]
        for seg in state["possible"]:
            if seg in state["selected"] or seg in state["banned"]:
                continue
            for r in state["seg_rows"][seg]:
                row_cands[r].append(seg)
            for c in state["seg_cols"][seg]:
                col_cands[c].append(seg)

        for r in range(n):
            need = state["row_target"][r] - state["row_used"][r]
            if need < 0:
                return False
            if need == 0:
                for seg in list(row_cands[r]):
                    h1, h2 = state["holes_of_seg"][seg]
                    if h1[0] == r or h2[0] == r:
                        if not ban_seg(state, seg):
                            return False
                            # no changed tracking needed; ban_seg handles queue
            else:
                holes = set()
                for seg in row_cands[r]:
                    h1, h2 = state["holes_of_seg"][seg]
                    if h1[0] == r:
                        holes.add(h1)
                    if h2[0] == r:
                        holes.add(h2)
                if need > len(holes):
                    return False
                if need == len(holes):
                    for seg in list(row_cands[r]):
                        h1, h2 = state["holes_of_seg"][seg]
                        contributes = (h1[0] == r) or (h2[0] == r)
                        if contributes and seg not in state["selected"]:
                            state["queue_force"].append(seg)

        for c in range(n):
            need = state["col_target"][c] - state["col_used"][c]
            if need < 0:
                return False
            if need == 0:
                for seg in list(col_cands[c]):
                    h1, h2 = state["holes_of_seg"][seg]
                    if h1[1] == c or h2[1] == c:
                        if not ban_seg(state, seg):
                            return False
            else:
                holes = set()
                for seg in col_cands[c]:
                    h1, h2 = state["holes_of_seg"][seg]
                    if h1[1] == c:
                        holes.add(h1)
                    if h2[1] == c:
                        holes.add(h2)
                if need > len(holes):
                    return False
                if need == len(holes):
                    for seg in list(col_cands[c]):
                        h1, h2 = state["holes_of_seg"][seg]
                        contributes = (h1[1] == c) or (h2[1] == c)
                        if contributes and seg not in state["selected"]:
                            state["queue_force"].append(seg)

        if state["queue_force"]:
            changed = True
            while state["queue_force"]:
                seg = state["queue_force"].popleft()
                if seg in state["selected"]:
                    continue
                if seg in state["banned"]:
                    return False
                if not select_seg(state, seg):
                    return False

        if not row_col_bounds_ok(state):
            return False

    return True


def propagate(state):
    # Force all edge singletons
    for e, opts in enumerate(state["edge_opts"]):
        if state["edge_status"][e] == 0:
            avail = [s for s in opts if s not in state["banned"]]
            if not avail:
                return False
            if len(avail) == 1:
                state["queue_force"].append(avail[0])

    while state["queue_force"]:
        seg = state["queue_force"].popleft()
        if seg in state["selected"]:
            continue
        if seg in state["banned"]:
            return False
        if not select_seg(state, seg):
            return False

    if not row_col_bounds_ok(state):
        return False

    if not force_from_counts(state):
        return False

    return True


def is_solved(state):
    if any(v != 1 for v in state["edge_status"]):
        return False
    return state["row_used"] == state["row_target"] and state["col_used"] == state["col_target"]


def choose_branch(state):
    # Human-like: branch on the most constrained unsatisfied edge, else on a row/col-critical segment.
    best_edge = None
    best_opts = None
    for e, status in enumerate(state["edge_status"]):
        if status == 0:
            opts = [s for s in state["edge_opts"][e] if s not in state["banned"]]
            if best_opts is None or len(opts) < len(best_opts):
                best_edge = e
                best_opts = opts
    if best_edge is not None:
        return ("edge", best_edge, best_opts)

    # Fallback segment choice
    best_seg = None
    best_score = None
    for seg in state["possible"]:
        if seg in state["selected"] or seg in state["banned"]:
            continue
        h1, h2 = state["holes_of_seg"][seg]
        score = 0
        for r in state["seg_rows"][seg]:
            score += abs((state["row_target"][r] - state["row_used"][r]) - 1)
        for c in state["seg_cols"][seg]:
            score += abs((state["col_target"][c] - state["col_used"][c]) - 1)
        if best_score is None or score < best_score:
            best_score = score
            best_seg = seg
    if best_seg is None:
        return None
    return ("seg", best_seg, [best_seg])


def search(state):
    if is_solved(state):
        return state
    branch = choose_branch(state)
    if branch is None:
        return None

    kind, obj, opts = branch
    if kind == "edge":
        # Usually singleton in this model, but keep generic.
        for seg in opts:
            ns = clone_state(state)
            ns["queue_force"].append(seg)
            if propagate(ns):
                res = search(ns)
                if res is not None:
                    return res
        return None
    else:
        seg = obj
        # Try select then ban
        ns = clone_state(state)
        ns["queue_force"].append(seg)
        if propagate(ns):
            res = search(ns)
            if res is not None:
                return res
        ns = clone_state(state)
        if ban_seg(ns, seg) and propagate(ns):
            res = search(ns)
            if res is not None:
                return res
        return None


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 3, None, None, None, None, None, None, 2], [2, None, None, None, None, None, None, None, None, None], [None, None, 4, None, None, 4, None, 2, None, None], [3, None, None, None, None, None, None, None, None, 4], [None, 1, None, 2, None, None, 2, None, 3, None], [None, None, None, None, None, None, None, None, None, None], [3, None, None, 4, None, None, None, None, 2, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None], [2, None, None, None, None, None, None, None, None, 3]]}

from collections import deque

# Human-style Hashi solver:
# 1) Parse islands and visible neighbor candidates.
# 2) Maintain per-edge domain {0,1,2} with strong upper bounds.
# 3) Repeatedly apply local deductions:
#    - degree lower/upper bound forcing
#    - exact-allocation forcing on an island
#    - single-neighbor / all-positive / all-max style rules
#    - crossing elimination
#    - connectivity pruning via bridge graph components and zero-cut detection
# 4) If unresolved, branch on the most constrained edge domain.

def solve(observation):
    data = observation['data']
    n = len(data)

    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                idx = len(islands)
                islands.append((r, c, data[r][c]))
                pos_to_idx[(r, c)] = idx

    m = len(islands)
    if m == 0:
        return "{}"

    # Build visible neighbor edges.
    edge_map = {}
    edges = []
    neighbors = [[] for _ in range(m)]

    # Horizontal
    for r in range(n):
        cols = [c for c in range(len(data[r])) if data[r][c] is not None]
        cols.sort()
        for i in range(len(cols) - 1):
            c1, c2 = cols[i], cols[i + 1]
            a = pos_to_idx[(r, c1)]
            b = pos_to_idx[(r, c2)]
            eid = len(edges)
            edges.append({
                'a': a, 'b': b,
                'dir': 'H',
                'line': r,
                'span': (c1, c2),
                'cross': []
            })
            edge_map[(min(a, b), max(a, b))] = eid
            neighbors[a].append(eid)
            neighbors[b].append(eid)

    # Vertical
    for c in range(n):
        rows = [r for r in range(n) if c < len(data[r]) and data[r][c] is not None]
        rows.sort()
        for i in range(len(rows) - 1):
            r1, r2 = rows[i], rows[i + 1]
            a = pos_to_idx[(r1, c)]
            b = pos_to_idx[(r2, c)]
            eid = len(edges)
            edges.append({
                'a': a, 'b': b,
                'dir': 'V',
                'line': c,
                'span': (r1, r2),
                'cross': []
            })
            edge_map[(min(a, b), max(a, b))] = eid
            neighbors[a].append(eid)
            neighbors[b].append(eid)

    ecount = len(edges)

    # Crossing relationships.
    for i in range(ecount):
        ei = edges[i]
        if ei['dir'] != 'H':
            continue
        r = ei['line']
        c1, c2 = ei['span']
        for j in range(ecount):
            ej = edges[j]
            if ej['dir'] != 'V':
                continue
            c = ej['line']
            r1, r2 = ej['span']
            if c1 < c < c2 and r1 < r < r2:
                edges[i]['cross'].append(j)
                edges[j]['cross'].append(i)

    req = [islands[i][2] for i in range(m)]

    # Initial domains.
    lo = [0] * ecount
    hi = [2] * ecount

    # Edge max limited by endpoint requirements.
    for eid, e in enumerate(edges):
        hi[eid] = min(2, req[e['a']], req[e['b']])

    # State helpers.
    def clone_state(state):
        return {
            'lo': state['lo'][:],
            'hi': state['hi'][:],
            'sum_lo': state['sum_lo'][:],
            'sum_hi': state['sum_hi'][:],
        }

    def init_state():
        sum_lo = [0] * m
        sum_hi = [0] * m
        st = {'lo': lo[:], 'hi': hi[:], 'sum_lo': sum_lo, 'sum_hi': sum_hi}
        for eid, e in enumerate(edges):
            a, b = e['a'], e['b']
            st['sum_lo'][a] += st['lo'][eid]
            st['sum_lo'][b] += st['lo'][eid]
            st['sum_hi'][a] += st['hi'][eid]
            st['sum_hi'][b] += st['hi'][eid]
        return st

    def edge_other(eid, v):
        e = edges[eid]
        return e['b'] if e['a'] == v else e['a']

    def set_lo(state, eid, new_lo, queue):
        if new_lo <= state['lo'][eid]:
            return True
        if new_lo > state['hi'][eid]:
            return False
        delta = new_lo - state['lo'][eid]
        state['lo'][eid] = new_lo
        a, b = edges[eid]['a'], edges[eid]['b']
        state['sum_lo'][a] += delta
        state['sum_lo'][b] += delta
        queue.append(('edge', eid))
        queue.append(('island', a))
        queue.append(('island', b))
        return True

    def set_hi(state, eid, new_hi, queue):
        if new_hi >= state['hi'][eid]:
            return True
        if new_hi < state['lo'][eid]:
            return False
        delta = state['hi'][eid] - new_hi
        state['hi'][eid] = new_hi
        a, b = edges[eid]['a'], edges[eid]['b']
        state['sum_hi'][a] -= delta
        state['sum_hi'][b] -= delta
        queue.append(('edge', eid))
        queue.append(('island', a))
        queue.append(('island', b))
        return True

    def force_edge_value(state, eid, val, queue):
        return set_lo(state, eid, val, queue) and set_hi(state, eid, val, queue)

    def check_basic_feasibility(state):
        for v in range(m):
            if state['sum_lo'][v] > req[v]:
                return False
            if state['sum_hi'][v] < req[v]:
                return False
        return True

    def possible_positive_graph(state):
        g = [[] for _ in range(m)]
        for eid, e in enumerate(edges):
            if state['hi'][eid] > 0:
                a, b = e['a'], e['b']
                g[a].append(b)
                g[b].append(a)
        return g

    def mandatory_positive_graph(state):
        g = [[] for _ in range(m)]
        for eid, e in enumerate(edges):
            if state['lo'][eid] > 0:
                a, b = e['a'], e['b']
                g[a].append(b)
                g[b].append(a)
        return g

    def component_labels(graph):
        comp = [-1] * len(graph)
        cid = 0
        for i in range(len(graph)):
            if comp[i] != -1:
                continue
            dq = [i]
            comp[i] = cid
            for x in dq:
                for y in graph[x]:
                    if comp[y] == -1:
                        comp[y] = cid
                        dq.append(y)
            cid += 1
        return comp, cid

    def connectivity_prune(state, queue):
        # If mandatory edges already split into components, every final solution
        # must connect them using at least one still-possible edge across components.
        mand = mandatory_positive_graph(state)
        comp, cc = component_labels(mand)
        if cc == 1:
            return True

        # If no possible inter-component positive edge exists, impossible.
        inter = []
        for eid, e in enumerate(edges):
            if state['hi'][eid] == 0:
                continue
            a, b = e['a'], e['b']
            if comp[a] != comp[b]:
                inter.append(eid)
        if not inter:
            return False

        # Strong human-style cut rule:
        # if a component has only one possible exiting edge, it must be positive.
        exits = [[] for _ in range(cc)]
        for eid in inter:
            a, b = edges[eid]['a'], edges[eid]['b']
            ca, cb = comp[a], comp[b]
            exits[ca].append(eid)
            exits[cb].append(eid)
        for cid in range(cc):
            uniq = list(dict.fromkeys(exits[cid]))
            if len(uniq) == 0:
                return False
            if len(uniq) == 1:
                if not set_lo(state, uniq[0], 1, queue):
                    return False
        return True

    def island_propagate(state, v, queue):
        need = req[v]
        s_lo = state['sum_lo'][v]
        s_hi = state['sum_hi'][v]
        if s_lo > need or s_hi < need:
            return False

        rem_need = need - s_lo
        rem_cap = s_hi - s_lo

        inc = neighbors[v]
        free = [eid for eid in inc if state['lo'][eid] != state['hi'][eid]]
        if rem_need == 0:
            for eid in free:
                if not set_hi(state, eid, state['lo'][eid], queue):
                    return False
            return True

        if rem_need == rem_cap:
            for eid in free:
                if not set_lo(state, eid, state['hi'][eid], queue):
                    return False
            return True

        # Refined per-edge min/max from island arithmetic.
        # x_e >= need - (sum of other highs)
        # x_e <= need - (sum of other lows)
        for eid in inc:
            elo = state['lo'][eid]
            ehi = state['hi'][eid]
            other_hi = s_hi - ehi
            other_lo = s_lo - elo
            min_e = max(elo, need - other_hi)
            max_e = min(ehi, need - other_lo)
            if min_e > max_e:
                return False
            if not set_lo(state, eid, min_e, queue):
                return False
            if not set_hi(state, eid, max_e, queue):
                return False

        # Human rule: if this island still needs positive bridges on all possible incident edges.
        pos_possible = [eid for eid in inc if state['hi'][eid] > 0]
        if pos_possible:
            sum_max_if_one_removed = 0
            for eid in pos_possible:
                sum_max_if_one_removed += state['hi'][eid]
            for eid in pos_possible:
                if sum_max_if_one_removed - state['hi'][eid] < rem_need:
                    if not set_lo(state, eid, max(1, state['lo'][eid]), queue):
                        return False

        return True

    def edge_propagate(state, eid, queue):
        # Crossing rule: positive edge forbids all crossing positives.
        if state['lo'][eid] > 0:
            for ce in edges[eid]['cross']:
                if not set_hi(state, ce, 0, queue):
                    return False

        # If some crossing edge is already positive, this one must be zero.
        for ce in edges[eid]['cross']:
            if state['lo'][ce] > 0:
                if not force_edge_value(state, eid, 0, queue):
                    return False

        # Endpoint residual caps can tighten this edge.
        a, b = edges[eid]['a'], edges[eid]['b']
        max_a = req[a] - (state['sum_lo'][a] - state['lo'][eid])
        max_b = req[b] - (state['sum_lo'][b] - state['lo'][eid])
        if not set_hi(state, eid, min(state['hi'][eid], max_a, max_b), queue):
            return False

        min_a = req[a] - (state['sum_hi'][a] - state['hi'][eid])
        min_b = req[b] - (state['sum_hi'][b] - state['hi'][eid])
        if not set_lo(state, eid, max(state['lo'][eid], min_a, min_b, 0), queue):
            return False

        return True

    def propagate(state):
        if not check_basic_feasibility(state):
            return False
        queue = deque()
        for v in range(m):
            queue.append(('island', v))
        for eid in range(ecount):
            queue.append(('edge', eid))

        seen_steps = 0
        while queue:
            typ, idx = queue.popleft()
            seen_steps += 1
            if seen_steps > 200000:
                # safety guard; should never happen for intended puzzles
                break
            if typ == 'island':
                if not island_propagate(state, idx, queue):
                    return False
            else:
                if not edge_propagate(state, idx, queue):
                    return False
            if not check_basic_feasibility(state):
                return False
            if not connectivity_prune(state, queue):
                return False

        # Final necessary connectivity feasibility on possible graph:
        g = possible_positive_graph(state)
        comp, cc = component_labels(g)
        if cc != 1:
            return False

        # Additional no-isolated-unsatisfied-region check:
        mand = mandatory_positive_graph(state)
        mcomp, mcc = component_labels(mand)
        if mcc > 1:
            exits = [0] * mcc
            for eid, e in enumerate(edges):
                if state['hi'][eid] > 0:
                    a, b = e['a'], e['b']
                    if mcomp[a] != mcomp[b]:
                        exits[mcomp[a]] += 1
                        exits[mcomp[b]] += 1
            for cid in range(mcc):
                if exits[cid] == 0:
                    return False

        return True

    def solved(state):
        for eid in range(ecount):
            if state['lo'][eid] != state['hi'][eid]:
                return False
        for v in range(m):
            if state['sum_lo'][v] != req[v]:
                return False
        g = [[] for _ in range(m)]
        for eid, e in enumerate(edges):
            if state['lo'][eid] > 0:
                a, b = e['a'], e['b']
                g[a].append(b)
                g[b].append(a)
        comp, cc = component_labels(g)
        return cc == 1

    def choose_branch_edge(state):
        best = None
        best_key = None
        for eid in range(ecount):
            if state['lo'][eid] == state['hi'][eid]:
                continue
            a, b = edges[eid]['a'], edges[eid]['b']
            width = state['hi'][eid] - state['lo'][eid]
            slack_a = state['sum_hi'][a] - state['sum_lo'][a]
            slack_b = state['sum_hi'][b] - state['sum_lo'][b]
            cross_live = sum(1 for ce in edges[eid]['cross'] if state['hi'][ce] > 0)
            key = (width, slack_a + slack_b, -cross_live)
            if best is None or key < best_key:
                best = eid
                best_key = key
        return best

    def ordered_values(state, eid):
        # Try human-preferred impactful values first.
        vals = list(range(state['lo'][eid], state['hi'][eid] + 1))
        scores = []
        cross_live = sum(1 for ce in edges[eid]['cross'] if state['hi'][ce] > 0)
        for v in vals:
            impact = 0
            if v > 0:
                impact += 3 + cross_live
            if v == state['hi'][eid] or v == state['lo'][eid]:
                impact += 1
            scores.append((-impact, v))
        scores.sort()
        return [v for _, v in scores]

    def dfs(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        eid = choose_branch_edge(state)
        if eid is None:
            return None

        for val in ordered_values(state, eid):
            child = clone_state(state)
            q = deque()
            ok = force_edge_value(child, eid, val, q)
            if not ok:
                continue
            res = dfs(child)
            if res is not None:
                return res
        return None

    result = dfs(init_state())
    if result is None:
        return "No Solution"

    ans = {}
    for eid, e in enumerate(edges):
        v = result['lo'][eid]
        if v > 0:
            p1 = (islands[e['a']][0], islands[e['a']][1])
            p2 = (islands[e['b']][0], islands[e['b']][1])
            if p1 <= p2:
                ans[(p1, p2)] = v
            else:
                ans[(p2, p1)] = v
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, 'W', None, None, None, None], ['W', None, 'W', None, None, 'W', None, 'W', None, None], [None, 'B', None, None, None, None, None, 'W', None, 'W'], ['B', None, None, None, 'W', None, None, None, None, None], [None, None, None, None, None, None, None, None, None, 'W'], [None, None, 'W', 'W', None, None, None, None, None, None], ['W', None, None, None, 'B', None, None, None, None, None], ['W', 'B', None, None, None, None, 'W', 'B', None, None], [None, None, None, None, 'B', None, None, None, None, None], [None, 'B', None, 'W', None, None, 'W', 'B', None, None]]}

# Takuzu / Binairo solver with strong human-style propagation plus pruned search.
# Symbols are represented internally as:
#   1 -> 'B'
#   0 -> 'W'
#  -1 -> unknown

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or n % 2 != 0:
        return "No Solution"

    grid = []
    for r in data:
        row = []
        for v in r:
            if v == 'B':
                row.append(1)
            elif v == 'W':
                row.append(0)
            else:
                row.append(-1)
        grid.append(row)

    half = n // 2

    def val_to_char(v):
        return 'B' if v == 1 else 'W'

    def copy_grid(g):
        return [row[:] for row in g]

    def line_count_ok(line):
        b = sum(1 for x in line if x == 1)
        w = sum(1 for x in line if x == 0)
        u = line.count(-1)
        return b <= half and w <= half and b + u >= half and w + u >= half

    def no_three_possible(line):
        for i in range(n - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]
            if a != -1 and a == b == c:
                return False
        return True

    def line_complete_valid(line):
        if -1 in line:
            return False
        if sum(1 for x in line if x == 1) != half:
            return False
        for i in range(n - 2):
            if line[i] == line[i + 1] == line[i + 2]:
                return False
        return True

    def rows_cols_unique_possible(g):
        # completed rows must be pairwise different
        seen = set()
        for r in range(n):
            row = g[r]
            if -1 not in row:
                t = tuple(row)
                if t in seen:
                    return False
                seen.add(t)
        # completed cols must be pairwise different
        seen = set()
        for c in range(n):
            col = tuple(g[r][c] for r in range(n))
            if -1 not in col:
                if col in seen:
                    return False
                seen.add(col)
        return True

    def partial_compat(a, b):
        # True if two partial lines can still differ somewhere / are not already forced equal complete duplicates
        for x, y in zip(a, b):
            if x != -1 and y != -1 and x != y:
                return False
        return True

    def uniqueness_possible(g):
        # If a complete line equals a partial line on all known entries, the partial line's unknowns
        # cannot all be forced to that exact same pattern; stronger pruning is done in candidate generation.
        # Here we only reject actual duplicate completes.
        return rows_cols_unique_possible(g)

    def basic_line_deductions(line):
        # Returns (changed, contradiction)
        changed = False

        # Count rule
        b = sum(1 for x in line if x == 1)
        w = sum(1 for x in line if x == 0)
        if b > half or w > half:
            return changed, True
        if b == half:
            for i, x in enumerate(line):
                if x == -1:
                    line[i] = 0
                    changed = True
        elif w == half:
            for i, x in enumerate(line):
                if x == -1:
                    line[i] = 1
                    changed = True

        # Triple rule patterns:
        # XX? -> opposite
        # ?XX -> opposite
        # X?X -> opposite
        for i in range(n - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]
            if a != -1 and b != -1 and a == b:
                if c == a:
                    return changed, True
                if c == -1:
                    line[i + 2] = 1 - a
                    changed = True
            if b != -1 and c != -1 and b == c:
                if a == b:
                    return changed, True
                if a == -1:
                    line[i] = 1 - b
                    changed = True
            if a != -1 and c != -1 and a == c:
                if b == a:
                    return changed, True
                if b == -1:
                    line[i + 1] = 1 - a
                    changed = True

        if not line_count_ok(line):
            return changed, True
        if not no_three_possible(line):
            return changed, True

        return changed, False

    def propagate(g):
        while True:
            any_change = False

            # Row/column local deductions
            for r in range(n):
                changed, bad = basic_line_deductions(g[r])
                if bad:
                    return None
                any_change |= changed

            for c in range(n):
                col = [g[r][c] for r in range(n)]
                changed, bad = basic_line_deductions(col)
                if bad:
                    return None
                if changed:
                    any_change = True
                    for r in range(n):
                        g[r][c] = col[r]

            # Global consistency checks
            for r in range(n):
                if not line_count_ok(g[r]) or not no_three_possible(g[r]):
                    return None
            for c in range(n):
                col = [g[r][c] for r in range(n)]
                if not line_count_ok(col) or not no_three_possible(col):
                    return None
            if not uniqueness_possible(g):
                return None

            # Human-style uniqueness deductions:
            # If a partial row has exactly one completion and that completion would duplicate a complete row,
            # contradiction. If among possible completions only one survives uniqueness, fill it.
            row_poss = {}
            col_poss = {}

            for r in range(n):
                if -1 in g[r]:
                    poss = generate_line_candidates(g[r], completed_rows(g), is_row=True, index=r, grid=g)
                    if not poss:
                        return None
                    row_poss[r] = poss
                    if len(poss) == 1:
                        cand = poss[0]
                        for c in range(n):
                            if g[r][c] != cand[c]:
                                g[r][c] = cand[c]
                                any_change = True

            for c in range(n):
                col = [g[r][c] for r in range(n)]
                if -1 in col:
                    poss = generate_line_candidates(col, completed_cols(g), is_row=False, index=c, grid=g)
                    if not poss:
                        return None
                    col_poss[c] = poss
                    if len(poss) == 1:
                        cand = poss[0]
                        for r in range(n):
                            if g[r][c] != cand[r]:
                                g[r][c] = cand[r]
                                any_change = True

            if any_change:
                continue

            return g

    def completed_rows(g):
        return {tuple(g[r]) for r in range(n) if -1 not in g[r]}

    def completed_cols(g):
        out = set()
        for c in range(n):
            col = tuple(g[r][c] for r in range(n))
            if -1 not in col:
                out.add(col)
        return out

    def line_pattern_ok(line):
        if sum(1 for x in line if x == 1) != half:
            return False
        for i in range(n - 2):
            if line[i] == line[i + 1] == line[i + 2]:
                return False
        return True

    def generate_line_candidates(line, complete_set, is_row, index, grid):
        # Generate all valid completions of a line under local rules and uniqueness against completed peers.
        unknowns = [i for i, x in enumerate(line) if x == -1]
        if not unknowns:
            t = tuple(line)
            if not line_pattern_ok(line):
                return []
            if t in complete_set:
                return []
            return [line[:]]

        results = []
        work = line[:]

        def partial_ok_prefix(pos_changed=None):
            if not line_count_ok(work):
                return False
            for i in range(n - 2):
                a, b, c = work[i], work[i + 1], work[i + 2]
                if a != -1 and a == b == c:
                    return False
            return True

        def dfs(k):
            if k == len(unknowns):
                cand = work[:]
                t = tuple(cand)
                if not line_pattern_ok(cand):
                    return
                if t in complete_set:
                    return

                # Cross-check with current perpendicular lines for count/triple feasibility.
                if is_row:
                    r = index
                    for c in range(n):
                        col = [grid[i][c] for i in range(n)]
                        col[r] = cand[c]
                        if not line_count_ok(col) or not no_three_possible(col):
                            return
                else:
                    c = index
                    for r in range(n):
                        row = grid[r][:]
                        row[c] = cand[r]
                        if not line_count_ok(row) or not no_three_possible(row):
                            return
                results.append(cand)
                return

            idx = unknowns[k]
            # Try value order based on balancing counts
            b = sum(1 for x in work if x == 1)
            w = sum(1 for x in work if x == 0)
            order = (1, 0) if b < w else (0, 1)
            for v in order:
                work[idx] = v
                if partial_ok_prefix(idx):
                    dfs(k + 1)
                work[idx] = -1

        dfs(0)
        return results

    def choose_branch(g):
        best = None
        best_key = None

        row_complete = completed_rows(g)
        col_complete = completed_cols(g)

        for r in range(n):
            if -1 in g[r]:
                poss = generate_line_candidates(g[r], row_complete, True, r, g)
                if not poss:
                    return ('row', r, [])
                key = (len(poss), g[r].count(-1))
                if best is None or key < best_key:
                    best = ('row', r, poss)
                    best_key = key

        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if -1 in col:
                poss = generate_line_candidates(col, col_complete, False, c, g)
                if not poss:
                    return ('col', c, [])
                key = (len(poss), col.count(-1))
                if best is None or key < best_key:
                    best = ('col', c, poss)
                    best_key = key

        return best

    def is_solved(g):
        for r in range(n):
            if -1 in g[r]:
                return False
            if not line_complete_valid(g[r]):
                return False
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if not line_complete_valid(col):
                return False
        if len({tuple(g[r]) for r in range(n)}) != n:
            return False
        if len({tuple(g[r][c] for r in range(n)) for c in range(n)}) != n:
            return False
        return True

    def search(g):
        g = propagate(copy_grid(g))
        if g is None:
            return None
        if is_solved(g):
            return g

        branch = choose_branch(g)
        if branch is None:
            return None
        kind, idx, poss = branch
        if not poss:
            return None

        # Prefer candidates that maximize immediate forced assignments in perpendicular lines.
        scored = []
        for cand in poss:
            score = 0
            if kind == 'row':
                for c in range(n):
                    if g[idx][c] == -1:
                        score += 1
            else:
                for r in range(n):
                    if g[r][idx] == -1:
                        score += 1
            scored.append((score, cand))
        scored.sort(reverse=True)

        for _, cand in scored:
            ng = copy_grid(g)
            if kind == 'row':
                ng[idx] = cand[:]
            else:
                for r in range(n):
                    ng[r][idx] = cand[r]
            ans = search(ng)
            if ans is not None:
                return ans
        return None

    ans = search(grid)
    if ans is None:
        return "No Solution"
    return [[val_to_char(v) for v in row] for row in ans]


if __name__ == "__main__":
    print(solve(OBSERVATION))

