from collections import deque

# Human-style solver for Tapa-like "count black cells in 3x3 neighborhood" puzzle.
# Each cell is binary: black ('B') or white (None).
# Numbered cells constrain the sum of black cells in their 3x3 neighborhood, including themselves.
# We perform strong local propagation, subset-style reasoning via exact neighborhood accounting,
# and only then a highly constrained branch search.

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0]) if R else 0
    N = R * C

    def idx(r, c):
        return r * C + c

    def rc(i):
        return divmod(i, C)

    vars_of_constraint = []
    req = []
    constraints_of_var = [[] for _ in range(N)]

    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                cells = []
                for rr in range(max(0, r - 1), min(R, r + 2)):
                    for cc in range(max(0, c - 1), min(C, c + 2)):
                        cells.append(idx(rr, cc))
                k = len(vars_of_constraint)
                vars_of_constraint.append(tuple(cells))
                req.append(int(data[r][c]))
                for v in cells:
                    constraints_of_var[v].append(k)

    M = len(vars_of_constraint)

    # For each constraint keep dynamic black count and unknown count.
    black_count = [0] * M
    unknown_count = [len(vs) for vs in vars_of_constraint]

    # Assignment: -1 unknown, 0 white, 1 black
    assign = [-1] * N

    # Fast contradiction / propagation engine with trail for backtracking.
    trail = []

    def set_var(v, val, q):
        cur = assign[v]
        if cur == val:
            return True
        if cur != -1:
            return False
        assign[v] = val
        trail.append(('var', v))
        for ci in constraints_of_var[v]:
            trail.append(('cnt', ci, black_count[ci], unknown_count[ci]))
            unknown_count[ci] -= 1
            if val == 1:
                black_count[ci] += 1
            q.append(ci)
        return True

    def undo(mark):
        while len(trail) > mark:
            item = trail.pop()
            if item[0] == 'var':
                assign[item[1]] = -1
            else:
                _, ci, b, u = item
                black_count[ci] = b
                unknown_count[ci] = u

    # Precompute pairwise intersections for stronger local reasoning.
    inter = {}
    for a in range(M):
        sa = set(vars_of_constraint[a])
        for b in range(a + 1, M):
            sb = set(vars_of_constraint[b])
            common = sa & sb
            if common:
                only_a = tuple(x for x in vars_of_constraint[a] if x not in common)
                only_b = tuple(x for x in vars_of_constraint[b] if x not in common)
                inter[(a, b)] = (tuple(common), only_a, only_b)

    # Queue-based propagation:
    # 1) Standard exact-sum bounds:
    #    remaining = req - black_count among unknown_count unknowns.
    #    If remaining==0 => all unknown white
    #    If remaining==unknown_count => all unknown black
    # 2) Pairwise overlap bounds:
    #    For A,B with intersection I and disjoint tails XA,XB:
    #    Let remA, remB be black still needed among unknowns of A,B.
    #    Then blacks in I satisfy:
    #       remA - max_black(XA) <= black(I) <= remA - min_black(XA)
    #       remB - max_black(XB) <= black(I) <= remB - min_black(XB)
    #    giving consequences if some side saturates.
    def propagate(initial_constraints=None):
        q = deque()
        inq = [False] * M
        if initial_constraints is None:
            for ci in range(M):
                q.append(ci)
                inq[ci] = True
        else:
            for ci in initial_constraints:
                if not inq[ci]:
                    q.append(ci)
                    inq[ci] = True

        while q:
            ci = q.popleft()
            inq[ci] = False

            b = black_count[ci]
            u = unknown_count[ci]
            need = req[ci] - b

            if need < 0 or need > u:
                return False

            if u == 0:
                if need != 0:
                    return False
            else:
                if need == 0:
                    for v in vars_of_constraint[ci]:
                        if assign[v] == -1:
                            if not set_var(v, 0, q):
                                return False
                elif need == u:
                    for v in vars_of_constraint[ci]:
                        if assign[v] == -1:
                            if not set_var(v, 1, q):
                                return False

            # Pairwise local deductions with overlapping constraints.
            for cj in range(M):
                if cj == ci:
                    continue
                a, bidx = (ci, cj) if ci < cj else (cj, ci)
                info = inter.get((a, bidx))
                if not info:
                    continue
                common, only_a, only_b = info
                if ci < cj:
                    A, B = ci, cj
                    XA, XB = only_a, only_b
                else:
                    A, B = cj, ci
                    XA, XB = only_a, only_b

                remA = req[A] - black_count[A]
                remB = req[B] - black_count[B]

                min_xa = max_xa = 0
                unk_xa = []
                for v in XA:
                    av = assign[v]
                    if av == 1:
                        min_xa += 1
                        max_xa += 1
                    elif av == -1:
                        max_xa += 1
                        unk_xa.append(v)

                min_xb = max_xb = 0
                unk_xb = []
                for v in XB:
                    av = assign[v]
                    if av == 1:
                        min_xb += 1
                        max_xb += 1
                    elif av == -1:
                        max_xb += 1
                        unk_xb.append(v)

                # Bounds on black count in common unknown+fixed cells.
                lowA = remA - max_xa
                highA = remA - min_xa
                lowB = remB - max_xb
                highB = remB - min_xb

                # Compute current common fixed contribution and unknown list.
                fixed_common_black = 0
                unk_common = []
                for v in common:
                    av = assign[v]
                    if av == 1:
                        fixed_common_black += 1
                    elif av == -1:
                        unk_common.append(v)

                lo = max(lowA, lowB)
                hi = min(highA, highB)
                if fixed_common_black > hi or fixed_common_black + len(unk_common) < lo:
                    return False

                # If common black count forced exactly, use it to force all common vars.
                target_if_exact = None
                if lo == hi:
                    target_if_exact = lo

                if target_if_exact is not None:
                    need_common_unknown_black = target_if_exact - fixed_common_black
                    if need_common_unknown_black < 0 or need_common_unknown_black > len(unk_common):
                        return False
                    if need_common_unknown_black == 0:
                        for v in unk_common:
                            if not set_var(v, 0, q):
                                return False
                    elif need_common_unknown_black == len(unk_common):
                        for v in unk_common:
                            if not set_var(v, 1, q):
                                return False

                # Tail exactness induced by overlap saturation.
                # If common reaches A's minimal possible, XA must all be maxed; etc.
                if lo == highA:
                    # common forced at A's maximum allowed => XA at minimum
                    for v in unk_xa:
                        if not set_var(v, 0, q):
                            return False
                if hi == lowA:
                    # common forced at A's minimum allowed => XA at maximum
                    for v in unk_xa:
                        if not set_var(v, 1, q):
                            return False
                if lo == highB:
                    for v in unk_xb:
                        if not set_var(v, 0, q):
                            return False
                if hi == lowB:
                    for v in unk_xb:
                        if not set_var(v, 1, q):
                            return False

        return True

    def all_assigned():
        return all(v != -1 for v in assign)

    def choose_var():
        # Most constrained variable: prioritize those in many tight constraints.
        best_v = -1
        best_key = None
        for v in range(N):
            if assign[v] != -1:
                continue
            tight = 0
            degree = len(constraints_of_var[v])
            score_need = 0
            for ci in constraints_of_var[v]:
                need = req[ci] - black_count[ci]
                u = unknown_count[ci]
                if u <= 1:
                    tight += 100
                else:
                    tight += (10 - min(9, abs(2 * need - u)))
                score_need += min(need, u - need)
            key = (-tight, -degree, score_need)
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
        return best_v

    def value_order(v):
        # Try value that better fits local averages.
        s = 0.0
        cnt = 0
        for ci in constraints_of_var[v]:
            u = unknown_count[ci]
            if u > 0:
                s += (req[ci] - black_count[ci]) / u
                cnt += 1
        p_black = s / cnt if cnt else 0.5
        return (1, 0) if p_black >= 0.5 else (0, 1)

    def dfs():
        if all_assigned():
            return True

        v = choose_var()
        if v == -1:
            return True

        for val in value_order(v):
            mark = len(trail)
            q = deque()
            if set_var(v, val, q) and propagate(list(q)):
                if dfs():
                    return True
            undo(mark)
        return False

    if not propagate():
        return "No Solution"
    if not dfs():
        return "No Solution"

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if assign[idx(r, c)] == 1 else None)
        out.append(row)
    return str(out)

