# General nonogram solver using human-like line deduction plus constrained search.
# Output grid uses 'B' for black and None for white.

from functools import lru_cache

BLACK = "B"
WHITE = None
UNKNOWN = "?"

def solve(observation):
    row_clues = observation["row_black_runs"]
    col_clues = observation["col_black_runs"]
    h = len(row_clues)
    w = len(col_clues)

    row_domains = [generate_line_patterns(w, tuple(clue)) for clue in row_clues]
    col_domains = [generate_line_patterns(h, tuple(clue)) for clue in col_clues]

    if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
        return "No Solution"

    grid = [[UNKNOWN for _ in range(w)] for _ in range(h)]

    result = search(grid, row_domains, col_domains, row_clues, col_clues)
    if result is None:
        return "No Solution"
    return format_grid(result)

def format_grid(grid):
    return str([[cell if cell == BLACK else None for cell in row] for row in grid])

@lru_cache(maxsize=None)
def generate_line_patterns(length, clues):
    clues = tuple(clues)
    if not clues:
        return (tuple(WHITE for _ in range(length)),)

    total_blocks = sum(clues)
    min_required = total_blocks + (len(clues) - 1)
    if min_required > length:
        return ()

    out = []

    def place(idx, pos, line):
        if idx == len(clues):
            line2 = line + [WHITE] * (length - pos)
            out.append(tuple(line2))
            return

        remaining_blocks = sum(clues[idx:])
        remaining_separators = (len(clues) - idx - 1)
        latest_start = length - (remaining_blocks + remaining_separators)

        for start in range(pos, latest_start + 1):
            line2 = line + [WHITE] * (start - pos) + [BLACK] * clues[idx]
            next_pos = start + clues[idx]
            if idx < len(clues) - 1:
                line2.append(WHITE)
                next_pos += 1
            place(idx + 1, next_pos, line2)

    place(0, 0, [])
    return tuple(out)

def line_fits_pattern(pattern, known):
    for a, b in zip(pattern, known):
        if b is not UNKNOWN and a != b:
            return False
    return True

def deduce_from_domain(domain, length):
    if not domain:
        return None
    forced = []
    for i in range(length):
        v = domain[0][i]
        same = True
        for p in domain[1:]:
            if p[i] != v:
                same = False
                break
        forced.append(v if same else UNKNOWN)
    return forced

def propagate(grid, row_domains, col_domains):
    h = len(grid)
    w = len(grid[0])

    changed = True
    while changed:
        changed = False

        # Filter row domains from current grid
        for r in range(h):
            known = tuple(grid[r])
            nd = tuple(p for p in row_domains[r] if line_fits_pattern(p, known))
            if not nd:
                return None
            if len(nd) != len(row_domains[r]):
                row_domains[r] = nd
                changed = True

        # Filter col domains from current grid
        for c in range(w):
            known = tuple(grid[r][c] for r in range(h))
            nd = tuple(p for p in col_domains[c] if line_fits_pattern(p, known))
            if not nd:
                return None
            if len(nd) != len(col_domains[c]):
                col_domains[c] = nd
                changed = True

        # Deduce from rows
        for r in range(h):
            forced = deduce_from_domain(row_domains[r], w)
            if forced is None:
                return None
            for c in range(w):
                if grid[r][c] is UNKNOWN and forced[c] is not UNKNOWN:
                    grid[r][c] = forced[c]
                    changed = True
                elif grid[r][c] is not UNKNOWN and forced[c] is not UNKNOWN and grid[r][c] != forced[c]:
                    return None

        # Deduce from cols
        for c in range(w):
            forced = deduce_from_domain(col_domains[c], h)
            if forced is None:
                return None
            for r in range(h):
                if grid[r][c] is UNKNOWN and forced[r] is not UNKNOWN:
                    grid[r][c] = forced[r]
                    changed = True
                elif grid[r][c] is not UNKNOWN and forced[r] is not UNKNOWN and grid[r][c] != forced[r]:
                    return None

        # Cross-check each cell support in row/col domains
        for r in range(h):
            for c in range(w):
                if grid[r][c] is UNKNOWN:
                    row_vals = {p[c] for p in row_domains[r]}
                    col_vals = {p[r] for p in col_domains[c]}
                    inter = row_vals & col_vals
                    if not inter:
                        return None
                    if len(inter) == 1:
                        grid[r][c] = next(iter(inter))
                        changed = True

        # Refine again after cross-check assignments
        for r in range(h):
            known = tuple(grid[r])
            nd = tuple(p for p in row_domains[r] if line_fits_pattern(p, known))
            if not nd:
                return None
            if len(nd) != len(row_domains[r]):
                row_domains[r] = nd
                changed = True

        for c in range(w):
            known = tuple(grid[r][c] for r in range(h))
            nd = tuple(p for p in col_domains[c] if line_fits_pattern(p, known))
            if not nd:
                return None
            if len(nd) != len(col_domains[c]):
                col_domains[c] = nd
                changed = True

    return grid, row_domains, col_domains

def is_solved(grid):
    return all(cell is not UNKNOWN for row in grid for cell in row)

def clone_grid(grid):
    return [row[:] for row in grid]

def search(grid, row_domains, col_domains, row_clues, col_clues):
    state = propagate(clone_grid(grid), list(row_domains), list(col_domains))
    if state is None:
        return None
    grid, row_domains, col_domains = state

    if is_solved(grid):
        if validate_complete(grid, row_clues, col_clues):
            return grid
        return None

    choice = pick_best_branch(grid, row_domains, col_domains)
    if choice is None:
        return None

    kind, idx, domain = choice

    for pattern in domain:
        new_grid = clone_grid(grid)
        new_row_domains = list(row_domains)
        new_col_domains = list(col_domains)

        if kind == "row":
            for c, v in enumerate(pattern):
                if new_grid[idx][c] is not UNKNOWN and new_grid[idx][c] != v:
                    break
                new_grid[idx][c] = v
            else:
                new_row_domains[idx] = (pattern,)
                res = search(new_grid, new_row_domains, new_col_domains, row_clues, col_clues)
                if res is not None:
                    return res
        else:
            for r, v in enumerate(pattern):
                if new_grid[r][idx] is not UNKNOWN and new_grid[r][idx] != v:
                    break
                new_grid[r][idx] = v
            else:
                new_col_domains[idx] = (pattern,)
                res = search(new_grid, new_row_domains, new_col_domains, row_clues, col_clues)
                if res is not None:
                    return res

    return None

def pick_best_branch(grid, row_domains, col_domains):
    h = len(grid)
    w = len(grid[0])

    best = None
    best_score = None

    for r in range(h):
        d = row_domains[r]
        if 1 < len(d):
            unknowns = sum(1 for x in grid[r] if x is UNKNOWN)
            score = (len(d), unknowns, 0, r)
            if best_score is None or score < best_score:
                best_score = score
                best = ("row", r, d)

    for c in range(w):
        d = col_domains[c]
        if 1 < len(d):
            unknowns = sum(1 for r in range(h) if grid[r][c] is UNKNOWN)
            score = (len(d), unknowns, 1, c)
            if best_score is None or score < best_score:
                best_score = score
                best = ("col", c, d)

    return best

def runs_of_line(line):
    out = []
    cnt = 0
    for cell in line:
        if cell == BLACK:
            cnt += 1
        else:
            if cnt:
                out.append(cnt)
                cnt = 0
    if cnt:
        out.append(cnt)
    return out

def validate_complete(grid, row_clues, col_clues):
    h = len(grid)
    w = len(grid[0])
    for r in range(h):
        if runs_of_line(grid[r]) != row_clues[r]:
            return False
    for c in range(w):
        if runs_of_line([grid[r][c] for r in range(h)]) != col_clues[c]:
            return False
    return True

