# General solver for the 3x3-neighborhood black/white puzzle.
# Numbered cells constrain the count of black cells in their 3x3 neighborhood.

from copy import deepcopy

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return "[]"

    R, C = len(data), len(data[0])
    nvars = R * C

    def vid(r, c):
        return r * C + c

    def rc(v):
        return divmod(v, C)

    # Build constraints from numbered cells.
    constraints = []
    var_to_constraints = [[] for _ in range(nvars)]
    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(R, r + 2)):
                for cc in range(max(0, c - 1), min(C, c + 2)):
                    cells.append(vid(rr, cc))
            idx = len(constraints)
            constraints.append({
                'target': val,
                'vars': cells,
            })
            for v in cells:
                var_to_constraints[v].append(idx)

    # State
    assign = [UNKNOWN] * nvars
    unknown_count = [len(con['vars']) for con in constraints]
    black_count = [0] * len(constraints)

    # For faster contradiction checks / branching score
    active_unknowns = [set(con['vars']) for con in constraints]

    def assign_cell(v, color, queue):
        cur = assign[v]
        if cur != UNKNOWN:
            return cur == color
        assign[v] = color
        for ci in var_to_constraints[v]:
            if v in active_unknowns[ci]:
                active_unknowns[ci].remove(v)
            unknown_count[ci] -= 1
            if color == BLACK:
                black_count[ci] += 1
            queue.append(ci)
        return True

    def constraint_bounds_ok(ci):
        b = black_count[ci]
        u = unknown_count[ci]
        t = constraints[ci]['target']
        return b <= t <= b + u

    def deduce_from_constraint(ci, queue, forced):
        if not constraint_bounds_ok(ci):
            return False
        b = black_count[ci]
        u = unknown_count[ci]
        t = constraints[ci]['target']
        if u == 0:
            return b == t
        # Human-like local deduction:
        # If all remaining unknowns must be black -> force them black.
        # If none of the remaining unknowns can be black -> force them white.
        if t == b:
            for v in list(active_unknowns[ci]):
                forced.append((v, WHITE))
        elif t == b + u:
            for v in list(active_unknowns[ci]):
                forced.append((v, BLACK))
        return True

    def intersection_reasoning(forced):
        # Human-like subset / overlap deduction on pairs of constraints.
        # For A subset B:
        #   min blacks in B\A or max blacks in B\A can force values.
        m = len(constraints)
        for i in range(m):
            vars_i = active_unknowns[i]
            if not vars_i:
                continue
            bi = black_count[i]
            ui = unknown_count[i]
            ti = constraints[i]['target']
            need_i = ti - bi
            for j in range(m):
                if i == j:
                    continue
                vars_j = active_unknowns[j]
                if not vars_j:
                    continue
                if vars_i.issubset(vars_j):
                    bj = black_count[j]
                    uj = unknown_count[j]
                    tj = constraints[j]['target']
                    need_j = tj - bj

                    diff = vars_j - vars_i
                    diff_need = need_j - need_i

                    # Blacks in diff must be between these values:
                    # min = max(0, need_j - |i|)
                    # but since i subset j and all are unknown in sets, direct exact bounds:
                    # x(diff) = need_j - x(i), with x(i) in [0..|i|], but also x(i)=need_i? No:
                    # because need_i is exact over vars_i. Hence x(diff)=need_j-need_i exact.
                    # Therefore:
                    if diff_need < 0 or diff_need > len(diff):
                        return False
                    if diff_need == 0:
                        for v in diff:
                            forced.append((v, WHITE))
                    elif diff_need == len(diff):
                        for v in diff:
                            forced.append((v, BLACK))
        return True

    def propagate(initial_forced=None):
        queue = []
        forced = [] if initial_forced is None else list(initial_forced)

        # Seed all constraints once initially if needed.
        if initial_forced is None:
            queue.extend(range(len(constraints)))

        while True:
            while forced:
                v, color = forced.pop()
                if not assign_cell(v, color, queue):
                    return False

            if not queue:
                if not intersection_reasoning(forced):
                    return False
                if not forced:
                    break
                continue

            seen = set()
            while queue:
                ci = queue.pop()
                if ci in seen:
                    continue
                seen.add(ci)
                if not deduce_from_constraint(ci, queue, forced):
                    return False

        return True

    def snapshot():
        return (
            assign[:],
            unknown_count[:],
            black_count[:],
            [s.copy() for s in active_unknowns],
        )

    def restore(state):
        nonlocal assign, unknown_count, black_count, active_unknowns
        assign, unknown_count, black_count, active_unknowns = (
            state[0][:],
            state[1][:],
            state[2][:],
            [s.copy() for s in state[3]],
        )

    def solved():
        return all(v != UNKNOWN for v in assign) and all(
            black_count[i] == constraints[i]['target'] for i in range(len(constraints))
        )

    def choose_branch_var():
        # Human-like: choose the most constrained unknown cell.
        best_v = None
        best_key = None
        for v in range(nvars):
            if assign[v] != UNKNOWN:
                continue
            related = var_to_constraints[v]
            if not related:
                # Unconstrained cell can be white by default; branch only if necessary.
                key = (-1, -1, -1)
            else:
                tightness = 0
                degree = len(related)
                pressure = 0
                for ci in related:
                    t = constraints[ci]['target']
                    b = black_count[ci]
                    u = unknown_count[ci]
                    rem = t - b
                    # Smaller slack means more constrained.
                    tightness += min(rem, u - rem)
                    pressure += abs(u - 2 * rem)
                key = (degree, -tightness, pressure)
            if best_key is None or key > best_key:
                best_key = key
                best_v = v
        return best_v

    def branch_order(v):
        # Prefer values suggested by nearby constraints.
        score_black = 0
        score_white = 0
        for ci in var_to_constraints[v]:
            t = constraints[ci]['target']
            b = black_count[ci]
            u = unknown_count[ci]
            rem = t - b
            if u <= 0:
                continue
            if rem == 0:
                score_white += 4
            elif rem == u:
                score_black += 4
            else:
                if rem * 2 > u:
                    score_black += 1
                elif rem * 2 < u:
                    score_white += 1
        if score_black > score_white:
            return (BLACK, WHITE)
        return (WHITE, BLACK)

    def finalize_unconstrained():
        # Any cell not in any constraint can be white safely.
        changed = False
        for v in range(nvars):
            if assign[v] == UNKNOWN and not var_to_constraints[v]:
                assign[v] = WHITE
                changed = True
        return changed

    def dfs():
        if not propagate():
            return False

        finalize_unconstrained()

        if solved():
            return True

        v = choose_branch_var()
        if v is None:
            return False

        state = snapshot()
        for color in branch_order(v):
            restore(state)
            if assign_cell(v, color, []):
                if dfs():
                    return True
        restore(state)
        return False

    if not dfs():
        return "No Solution"

    result = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if assign[vid(r, c)] == BLACK else None)
        result.append(row)
    return str(result)


