from itertools import combinations

# Weighted binary grid puzzle solver.
# If rows are indexed 0..R-1 and cols 0..C-1, then:
# - each black cell in row r contributes (c+1) to row_sum[r]
# - each black cell in col c contributes (r+1) to col_sum[c]
#
# We solve by:
# 1) Generating all feasible row patterns from row targets.
# 2) Generating all feasible column patterns from column targets.
# 3) Repeatedly applying arc-consistency style filtering:
#    a row pattern is kept only if each of its cell values is supported by some
#    surviving column pattern in that column, and vice versa.
# 4) Applying deterministic deductions from forced cells.
# 5) Branching only on the most constrained row/column domain.
#
# This mirrors human solving:
# - enumerate legal possibilities for each line
# - cross-eliminate incompatible possibilities
# - mark forced black/white cells
# - only then guess minimally if needed

def subset_masks_with_weight(length, target, weights):
    masks = []
    for mask in range(1 << length):
        s = 0
        m = mask
        idx = 0
        while m:
            if m & 1:
                s += weights[idx]
                if s > target:
                    break
            idx += 1
            m >>= 1
        else:
            if s == target:
                masks.append(mask)
    return masks

def bit_at(mask, idx):
    return (mask >> idx) & 1

def common_bits(domains):
    if not domains:
        return 0, 0
    all1 = domains[0]
    all0 = (~domains[0])
    for m in domains[1:]:
        all1 &= m
        all0 &= ~m
    return all1, all0

def domain_cell_status_row(row_domains, r, c):
    vals = [bit_at(m, c) for m in row_domains[r]]
    if all(v == 1 for v in vals):
        return 1
    if all(v == 0 for v in vals):
        return 0
    return -1

def domain_cell_status_col(col_domains, c, r):
    vals = [bit_at(m, r) for m in col_domains[c]]
    if all(v == 1 for v in vals):
        return 1
    if all(v == 0 for v in vals):
        return 0
    return -1

def filter_domains(row_domains, col_domains, R, C):
    changed = True
    while changed:
        changed = False

        # Row -> Column support
        for r in range(R):
            new_dom = []
            for rm in row_domains[r]:
                ok = True
                for c in range(C):
                    v = bit_at(rm, c)
                    if not any(bit_at(cm, r) == v for cm in col_domains[c]):
                        ok = False
                        break
                if ok:
                    new_dom.append(rm)
            if not new_dom:
                return None, None
            if len(new_dom) != len(row_domains[r]):
                row_domains[r] = new_dom
                changed = True

        # Column -> Row support
        for c in range(C):
            new_dom = []
            for cm in col_domains[c]:
                ok = True
                for r in range(R):
                    v = bit_at(cm, r)
                    if not any(bit_at(rm, c) == v for rm in row_domains[r]):
                        ok = False
                        break
                if ok:
                    new_dom.append(cm)
            if not new_dom:
                return None, None
            if len(new_dom) != len(col_domains[c]):
                col_domains[c] = new_dom
                changed = True

        # Forced cell propagation
        for r in range(R):
            for c in range(C):
                rs = domain_cell_status_row(row_domains, r, c)
                cs = domain_cell_status_col(col_domains, c, r)

                if rs != -1 and cs != -1 and rs != cs:
                    return None, None

                forced = rs if rs != -1 else cs
                if forced == -1:
                    continue

                new_r = [rm for rm in row_domains[r] if bit_at(rm, c) == forced]
                new_c = [cm for cm in col_domains[c] if bit_at(cm, r) == forced]

                if not new_r or not new_c:
                    return None, None

                if len(new_r) != len(row_domains[r]):
                    row_domains[r] = new_r
                    changed = True
                if len(new_c) != len(col_domains[c]):
                    col_domains[c] = new_c
                    changed = True

    return row_domains, col_domains

def is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

def choose_branch(row_domains, col_domains):
    best = None

    for r, d in enumerate(row_domains):
        if 1 < len(d) and (best is None or len(d) < best[0]):
            best = (len(d), 'row', r)

    for c, d in enumerate(col_domains):
        if 1 < len(d) and (best is None or len(d) < best[0]):
            best = (len(d), 'col', c)

    return best

def deep_copy_domains(domains):
    return [list(d) for d in domains]

def search(row_domains, col_domains, R, C):
    row_domains, col_domains = filter_domains(row_domains, col_domains, R, C)
    if row_domains is None:
        return None

    if is_solved(row_domains, col_domains):
        return row_domains, col_domains

    branch = choose_branch(row_domains, col_domains)
    if branch is None:
        return row_domains, col_domains

    _, typ, idx = branch

    if typ == 'row':
        # Try patterns in a human-like helpful order: more balanced first is unnecessary;
        # keep original order for determinism.
        for m in row_domains[idx]:
            nr = deep_copy_domains(row_domains)
            nc = deep_copy_domains(col_domains)
            nr[idx] = [m]
            res = search(nr, nc, R, C)
            if res is not None:
                return res
    else:
        for m in col_domains[idx]:
            nr = deep_copy_domains(row_domains)
            nc = deep_copy_domains(col_domains)
            nc[idx] = [m]
            res = search(nr, nc, R, C)
            if res is not None:
                return res

    return None

def render_solution(row_domains, R, C):
    grid = []
    for r in range(R):
        mask = row_domains[r][0]
        row = []
        for c in range(C):
            row.append('B' if bit_at(mask, c) else None)
        grid.append(row)
    return grid

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)

    row_weights = [r + 1 for r in range(R)]
    col_weights = [c + 1 for c in range(C)]

    # Build row domains: subsets of columns summing to row target by column weights.
    row_domains = []
    for target in row_sum:
        dom = subset_masks_with_weight(C, target, col_weights)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    # Build column domains: subsets of rows summing to column target by row weights.
    col_domains = []
    for target in col_sum:
        dom = subset_masks_with_weight(R, target, row_weights)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    res = search(row_domains, col_domains, R, C)
    if res is None:
        return "No Solution"

    final_rows, _ = res
    return str(render_solution(final_rows, R, C))

