from collections import defaultdict, deque
import ast

def solve(observation):
    data = observation["data"]
    n = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, data[r][c]))
    m = len(islands)

    # Build candidate edges between visible orthogonal neighbors.
    edges = []
    edge_of = {}
    neighbors = [[] for _ in range(m)]

    def add_edge(i, j):
        a = islands[i][:2]
        b = islands[j][:2]
        if a > b:
            i, j = j, i
            a, b = b, a
        key = (a, b)
        idx = len(edges)
        ori = 'H' if a[0] == b[0] else 'V'
        rr1, cc1 = a
        rr2, cc2 = b
        if ori == 'H':
            cells = [(rr1, c) for c in range(cc1 + 1, cc2)]
        else:
            cells = [(r, cc1) for r in range(rr1 + 1, rr2)]
        edges.append({
            "ends": (i, j),
            "key": key,
            "ori": ori,
            "cells": cells,
            "cross": set(),
        })
        edge_of[key] = idx
        neighbors[i].append(idx)
        neighbors[j].append(idx)

    # Horizontal visibility
    for r in range(n):
        prev = None
        for c in range(len(data[r])):
            if data[r][c] is not None:
                if prev is not None:
                    add_edge(pos_to_idx[(r, prev)], pos_to_idx[(r, c)])
                prev = c

    # Vertical visibility
    width = max(len(row) for row in data)
    for c in range(width):
        prev = None
        for r in range(n):
            if c < len(data[r]) and data[r][c] is not None:
                if prev is not None:
                    add_edge(pos_to_idx[(prev, c)], pos_to_idx[(r, c)])
                prev = r

    # Crossing relations
    E = len(edges)
    for i in range(E):
        e1 = edges[i]
        if e1["ori"] != 'H':
            continue
        r = e1["key"][0][0]
        c1 = e1["key"][0][1]
        c2 = e1["key"][1][1]
        for j in range(E):
            e2 = edges[j]
            if e2["ori"] != 'V':
                continue
            c = e2["key"][0][1]
            r1 = e2["key"][0][0]
            r2 = e2["key"][1][0]
            if c1 < c < c2 and r1 < r < r2:
                edges[i]["cross"].add(j)
                edges[j]["cross"].add(i)

    req = [v for _, _, v in islands]

    # State arrays
    counts = [None] * E
    rem = req[:]
    incident_unassigned = [set(neighbors[i]) for i in range(m)]

    parent = list(range(m))
    rank = [0] * m
    active_edges = set()

    def dsu_find(par, x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    def dsu_union(par, rk, a, b):
        ra = dsu_find(par, a)
        rb = dsu_find(par, b)
        if ra == rb:
            return
        if rk[ra] < rk[rb]:
            par[ra] = rb
        elif rk[ra] > rk[rb]:
            par[rb] = ra
        else:
            par[rb] = ra
            rk[ra] += 1

    def rebuild_dsu(cur_counts):
        par = list(range(m))
        rk = [0] * m
        for ei, v in enumerate(cur_counts):
            if v and v > 0:
                a, b = edges[ei]["ends"]
                dsu_union(par, rk, a, b)
        return par, rk

    def clone_state():
        return (
            counts[:],
            rem[:],
            [set(s) for s in incident_unassigned],
            parent[:],
            rank[:],
            set(active_edges),
        )

    def restore_state(st):
        nonlocal counts, rem, incident_unassigned, parent, rank, active_edges
        counts, rem, incident_unassigned, parent, rank, active_edges = st

    def edge_bounds(ei):
        if counts[ei] is not None:
            v = counts[ei]
            return v, v
        a, b = edges[ei]["ends"]
        ub = min(2, rem[a], rem[b])
        if ub < 0:
            ub = -1
        return 0, ub

    def node_sum_bounds(i):
        lo = 0
        hi = 0
        for ei in neighbors[i]:
            l, u = edge_bounds(ei)
            if u < 0:
                return 1, 0
            lo += l
            hi += u
        return lo, hi

    def assign_edge(ei, val, queue):
        nonlocal parent, rank
        cur = counts[ei]
        if cur is not None:
            return cur == val
        a, b = edges[ei]["ends"]
        if val < 0 or val > 2:
            return False
        if val > rem[a] or val > rem[b]:
            return False

        # Crossing constraint
        if val > 0:
            for cj in edges[ei]["cross"]:
                cv = counts[cj]
                if cv is None:
                    pass
                elif cv > 0:
                    return False

        counts[ei] = val
        incident_unassigned[a].discard(ei)
        incident_unassigned[b].discard(ei)
        rem[a] -= val
        rem[b] -= val
        if rem[a] < 0 or rem[b] < 0:
            return False

        if val > 0:
            active_edges.add(ei)
            dsu_union(parent, rank, a, b)
            for cj in edges[ei]["cross"]:
                if counts[cj] is None:
                    queue.append(("edge", cj, 0))
        queue.append(("node", a))
        queue.append(("node", b))
        return True

    def connectivity_possible():
        # Components under currently positive edges.
        par = parent
        comps = defaultdict(list)
        for i in range(m):
            comps[dsu_find(par, i)].append(i)
        if len(comps) == 1:
            return True

        # Build graph of components connected by still-possible positive unassigned edges.
        comp_ids = {root: k for k, root in enumerate(comps)}
        g = [[] for _ in range(len(comps))]
        for ei in range(E):
            if counts[ei] is not None:
                continue
            a, b = edges[ei]["ends"]
            if min(2, rem[a], rem[b]) <= 0:
                continue
            ca = comp_ids[dsu_find(par, a)]
            cb = comp_ids[dsu_find(par, b)]
            if ca != cb:
                g[ca].append(cb)
                g[cb].append(ca)
        seen = {0}
        dq = deque([0])
        while dq:
            x = dq.popleft()
            for y in g[x]:
                if y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(g)

    def propagate():
        queue = deque()
        for i in range(m):
            queue.append(("node", i))

        while queue:
            item = queue.popleft()
            if item[0] == "edge":
                _, ei, val = item
                if not assign_edge(ei, val, queue):
                    return False
                continue

            _, i = item
            if rem[i] < 0:
                return False
            un = list(incident_unassigned[i])
            if not un:
                if rem[i] != 0:
                    return False
                continue

            # Feasibility bounds on node.
            max_sum = 0
            mins = []
            maxs = []
            for ei in un:
                l, u = edge_bounds(ei)
                if u < 0:
                    return False
                mins.append((ei, l))
                maxs.append((ei, u))
                max_sum += u
            if rem[i] > max_sum:
                return False
            if rem[i] == 0:
                for ei in un:
                    queue.append(("edge", ei, 0))
                continue
            if rem[i] == max_sum:
                for ei, u in maxs:
                    queue.append(("edge", ei, u))
                continue

            # Single-edge remainder.
            if len(un) == 1:
                ei = un[0]
                l, u = edge_bounds(ei)
                if l <= rem[i] <= u:
                    queue.append(("edge", ei, rem[i]))
                else:
                    return False
                continue

            # Human-like forcing:
            # If after giving all others max, an edge still needs at least X.
            total_max = max_sum
            for ei, u in maxs:
                need = rem[i] - (total_max - u)
                if need > 0:
                    if need > u:
                        return False
                    queue.append(("edge", ei, need))

            # If edge cannot be positive due to counterpart saturation/crossing, zero it.
            for ei in un:
                a, b = edges[ei]["ends"]
                other = b if a == i else a
                if rem[other] == 0:
                    queue.append(("edge", ei, 0))

        # Global node bounds
        for i in range(m):
            lo, hi = node_sum_bounds(i)
            if not (lo <= req[i] - (req[i] - rem[i]) <= hi):
                pass
            if rem[i] < 0 or rem[i] > hi:
                return False

        # Parity/leaf-like checks: if node requires >0, there must remain at least one possible positive edge.
        for i in range(m):
            if rem[i] > 0:
                ok = False
                for ei in neighbors[i]:
                    l, u = edge_bounds(ei)
                    if u > 0:
                        ok = True
                        break
                if not ok:
                    return False

        if not connectivity_possible():
            return False

        # Final all-zero on full nodes.
        for i in range(m):
            if rem[i] == 0:
                for ei in list(incident_unassigned[i]):
                    if counts[ei] is None:
                        st = deque([("edge", ei, 0)])
                        while st:
                            if not assign_edge(*st.popleft()[1:], st):
                                return False
        return True

    def is_solved():
        if any(v is None for v in counts):
            return False
        if any(r != 0 for r in rem):
            return False
        par, _ = rebuild_dsu(counts)
        root = dsu_find(par, 0)
        return all(dsu_find(par, i) == root for i in range(m))

    def choose_branch_edge():
        best = None
        best_key = None
        for ei in range(E):
            if counts[ei] is not None:
                continue
            l, u = edge_bounds(ei)
            vals = [v for v in (2, 1, 0) if l <= v <= u]
            if not vals:
                return ei, []
            a, b = edges[ei]["ends"]
            score = (
                len(vals),
                -(rem[a] + rem[b]),
                -len(edges[ei]["cross"]),
                -(req[a] + req[b]),
            )
            if best is None or score < best_key:
                best = (ei, vals)
                best_key = score
        return best

    def search():
        if not propagate():
            return None
        if is_solved():
            ans = {}
            for ei, v in enumerate(counts):
                if v:
                    ans[edges[ei]["key"]] = v
            return ans

        choice = choose_branch_edge()
        if choice is None:
            return None
        ei, vals = choice
        for v in vals:
            st = clone_state()
            q = deque([("edge", ei, v)])
            ok = True
            while q and ok:
                item = q.popleft()
                if item[0] == "edge":
                    ok = assign_edge(item[1], item[2], q)
                else:
                    q.appendleft(item)
                    ok = propagate()
                    break
            if ok:
                res = search()
                if res is not None:
                    return res
            restore_state(st)
        return None

    res = search()
    if res is None:
        return "No Solution"
    return str(res)

