from collections import defaultdict

# General solver for the stitch puzzle.
# Model:
# - For each border between orthogonally adjacent cells of different regions,
#   exactly one of the two endpoint hole-pairs on that border is chosen.
# - A chosen stitch uses two orthogonally adjacent holes.
# - Each hole can be used by at most one stitch.
# - Row/column clues count used holes in each hole row/column.

def solve(observation):
    region = observation['region']
    row_target = observation['row_stitch_counts']
    col_target = observation['col_stitch_counts']
    n = len(region)
    if n == 0 or len(row_target) != n or len(col_target) != n:
        return "No Solution"

    # Build border variables.
    # Each variable has exactly two possible stitch placements (two segments).
    # Segment is represented by endpoints ((r1,c1),(r2,c2)) with lexicographic order.
    variables = []
    hole_to_vars = defaultdict(list)
    row_to_vars = defaultdict(set)
    col_to_vars = defaultdict(set)

    def norm_seg(a, b):
        return (a, b) if a <= b else (b, a)

    # Vertical shared side between cells (r,c) and (r,c+1):
    # possible stitches are top and bottom horizontal segments.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                s1 = norm_seg((r, c), (r, c + 1))
                s2 = norm_seg((r + 1, c), (r + 1, c + 1))
                vid = len(variables)
                variables.append((s1, s2))
                for sid, seg in enumerate((s1, s2)):
                    (a, b) = seg
                    for h in seg:
                        hole_to_vars[h].append((vid, sid))
                        row_to_vars[h[0]].add(vid)
                        col_to_vars[h[1]].add(vid)

    # Horizontal shared side between cells (r,c) and (r+1,c):
    # possible stitches are left and right vertical segments.
    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                s1 = norm_seg((r, c), (r + 1, c))
                s2 = norm_seg((r, c + 1), (r + 1, c + 1))
                vid = len(variables)
                variables.append((s1, s2))
                for sid, seg in enumerate((s1, s2)):
                    for h in seg:
                        hole_to_vars[h].append((vid, sid))
                        row_to_vars[h[0]].add(vid)
                        col_to_vars[h[1]].add(vid)

    m = len(variables)
    if m == 0:
        if any(x != 0 for x in row_target) or any(x != 0 for x in col_target):
            return "No Solution"
        return "[]"

    # Precompute masks of rows/cols touched by each variable option.
    var_option_rows = []
    var_option_cols = []
    for s1, s2 in variables:
        rows = []
        cols = []
        for seg in (s1, s2):
            rs = set([seg[0][0], seg[1][0]])
            cs = set([seg[0][1], seg[1][1]])
            rows.append(rs)
            cols.append(cs)
        var_option_rows.append(rows)
        var_option_cols.append(cols)

    # State.
    # domain bitmask: 1 means option 0 available, 2 means option 1 available, 3 means both.
    domains = [3] * m
    assigned = [-1] * m

    row_used = [0] * n
    col_used = [0] * n
    row_unassigned = [len(row_to_vars[r]) for r in range(n)]
    col_unassigned = [len(col_to_vars[c]) for c in range(n)]

    # For each row/col, optimistic max additional used holes from remaining vars:
    # sum over unassigned vars touching line of whether any remaining option touches line (0,1,2 holes max from one var on one line).
    # Since a stitch can contribute:
    # - to a row: 2 if horizontal in that row, 1 if vertical crossing that row endpoint, 0 otherwise.
    # But due to puzzle geometry every chosen segment contributes exactly 0,1,or2 to a line.
    # We'll recompute bounds incrementally from domains when needed.

    # Hole occupancy:
    hole_owner = {}  # hole -> vid of chosen stitch using it

    # Adjacency for propagation:
    var_neighbors = [set() for _ in range(m)]
    for h, lst in hole_to_vars.items():
        vids = [vid for vid, _ in lst]
        for i in range(len(vids)):
            vi = vids[i]
            nei = var_neighbors[vi]
            for j in range(len(vids)):
                if i != j:
                    nei.add(vids[j])

    # Reversible trail.
    trail = []

    def push(kind, *data):
        trail.append((kind, data))

    def undo(mark):
        while len(trail) > mark:
            kind, data = trail.pop()
            if kind == 'domain':
                vid, old = data
                domains[vid] = old
            elif kind == 'assign':
                vid, old = data
                assigned[vid] = old
            elif kind == 'row_used':
                r, old = data
                row_used[r] = old
            elif kind == 'col_used':
                c, old = data
                col_used[c] = old
            elif kind == 'row_unassigned':
                r, old = data
                row_unassigned[r] = old
            elif kind == 'col_unassigned':
                c, old = data
                col_unassigned[c] = old
            elif kind == 'hole_owner':
                h, old_present, old_val = data
                if old_present:
                    hole_owner[h] = old_val
                else:
                    hole_owner.pop(h, None)

    def option_segments(vid, sid):
        return variables[vid][sid]

    def option_holes(vid, sid):
        seg = variables[vid][sid]
        return seg[0], seg[1]

    def line_bounds_row(r):
        lo = row_used[r]
        hi = row_used[r]
        for vid in row_to_vars[r]:
            if assigned[vid] != -1:
                continue
            mask = domains[vid]
            best = -1
            worst = 3
            if mask & 1:
                k = sum(1 for h in option_holes(vid, 0) if h[0] == r)
                if k > best:
                    best = k
                if k < worst:
                    worst = k
            if mask & 2:
                k = sum(1 for h in option_holes(vid, 1) if h[0] == r)
                if k > best:
                    best = k
                if k < worst:
                    worst = k
            hi += best
            lo += worst
        return lo, hi

    def line_bounds_col(c):
        lo = col_used[c]
        hi = col_used[c]
        for vid in col_to_vars[c]:
            if assigned[vid] != -1:
                continue
            mask = domains[vid]
            best = -1
            worst = 3
            if mask & 1:
                k = sum(1 for h in option_holes(vid, 0) if h[1] == c)
                if k > best:
                    best = k
                if k < worst:
                    worst = k
            if mask & 2:
                k = sum(1 for h in option_holes(vid, 1) if h[1] == c)
                if k > best:
                    best = k
                if k < worst:
                    worst = k
            hi += best
            lo += worst
        return lo, hi

    def remove_option(vid, sid, queue):
        mask = domains[vid]
        bit = 1 << sid
        if not (mask & bit):
            return True
        old = mask
        new = mask & ~bit
        if new == 0:
            return False
        push('domain', vid, old)
        domains[vid] = new
        queue.append(vid)
        return True

    def force_assign(vid, sid, queue):
        # Restrict domain then assign if singleton.
        other = sid ^ 1
        if not remove_option(vid, other, queue):
            return False
        return True

    def commit_assignment(vid, sid, queue):
        if assigned[vid] == sid:
            return True
        if assigned[vid] != -1 and assigned[vid] != sid:
            return False
        if domains[vid] != (1 << sid):
            old = domains[vid]
            push('domain', vid, old)
            domains[vid] = (1 << sid)
        push('assign', vid, assigned[vid])
        assigned[vid] = sid

        touched_rows = set()
        touched_cols = set()

        for r in row_to_vars:
            pass

        # update line unassigned counts for all rows/cols touched by this variable
        for rset in var_option_rows[vid]:
            touched_rows |= rset
        for cset in var_option_cols[vid]:
            touched_cols |= cset
        for r in touched_rows:
            old = row_unassigned[r]
            push('row_unassigned', r, old)
            row_unassigned[r] = old - 1
        for c in touched_cols:
            old = col_unassigned[c]
            push('col_unassigned', c, old)
            col_unassigned[c] = old - 1

        # mark holes used and update counts
        for h in option_holes(vid, sid):
            if h in hole_owner:
                return False
            push('hole_owner', h, False, None)
            hole_owner[h] = vid
            r, c = h
            oldr = row_used[r]
            push('row_used', r, oldr)
            row_used[r] = oldr + 1
            oldc = col_used[c]
            push('col_used', c, oldc)
            col_used[c] = oldc + 1

        # Immediate overflows
        for h in option_holes(vid, sid):
            r, c = h
            if row_used[r] > row_target[r] or col_used[c] > col_target[c]:
                return False

        # Hole exclusivity propagation
        for h in option_holes(vid, sid):
            for ov, osid in hole_to_vars[h]:
                if ov == vid or assigned[ov] != -1:
                    continue
                if not remove_option(ov, osid, queue):
                    return False
        return True

    def propagate():
        queue = list(range(m))
        in_queue = [True] * m

        def enqueue(v):
            if not in_queue[v]:
                in_queue[v] = True
                queue.append(v)

        while queue:
            vid = queue.pop()
            in_queue[vid] = False
            mask = domains[vid]
            if mask == 0:
                return False

            # If singleton, commit assignment.
            if assigned[vid] == -1 and mask in (1, 2):
                sid = 0 if mask == 1 else 1
                localq = []
                if not commit_assignment(vid, sid, localq):
                    return False
                for v in localq:
                    enqueue(v)

            # If unassigned, prune options conflicting with already used holes.
            if assigned[vid] == -1:
                for sid in (0, 1):
                    if domains[vid] & (1 << sid):
                        for h in option_holes(vid, sid):
                            owner = hole_owner.get(h)
                            if owner is not None and owner != vid:
                                if not remove_option(vid, sid, queue):
                                    return False
                                break

        # Global row/col bounds and line-forcing propagation loop
        changed = True
        while changed:
            changed = False

            # Check bounds.
            for r in range(n):
                lo, hi = line_bounds_row(r)
                if lo > row_target[r] or hi < row_target[r]:
                    return False
            for c in range(n):
                lo, hi = line_bounds_col(c)
                if lo > col_target[c] or hi < col_target[c]:
                    return False

            # Human-like line deductions:
            # If a row/col target equals current lower or upper bound, remove options that would exceed/fall short.
            for r in range(n):
                lo, hi = line_bounds_row(r)
                target = row_target[r]
                if target == lo:
                    for vid in list(row_to_vars[r]):
                        if assigned[vid] != -1:
                            continue
                        for sid in (0, 1):
                            if domains[vid] & (1 << sid):
                                contrib = sum(1 for h in option_holes(vid, sid) if h[0] == r)
                                alt = None
                                if domains[vid] & (1 << (sid ^ 1)):
                                    alt = sum(1 for h in option_holes(vid, sid ^ 1) if h[0] == r)
                                if contrib > (alt if alt is not None else contrib):
                                    mark = len(trail)
                                    q = []
                                    if not remove_option(vid, sid, q):
                                        undo(mark)
                                        return False
                                    if q:
                                        changed = True
                                        ok = propagate_local(q)
                                        if not ok:
                                            undo(mark)
                                            return False
                                    break
                elif target == hi:
                    for vid in list(row_to_vars[r]):
                        if assigned[vid] != -1:
                            continue
                        for sid in (0, 1):
                            if domains[vid] & (1 << sid):
                                contrib = sum(1 for h in option_holes(vid, sid) if h[0] == r)
                                alt = None
                                if domains[vid] & (1 << (sid ^ 1)):
                                    alt = sum(1 for h in option_holes(vid, sid ^ 1) if h[0] == r)
                                if alt is not None and contrib < alt:
                                    mark = len(trail)
                                    q = []
                                    if not remove_option(vid, sid, q):
                                        undo(mark)
                                        return False
                                    if q:
                                        changed = True
                                        ok = propagate_local(q)
                                        if not ok:
                                            undo(mark)
                                            return False
                                    break

            for c in range(n):
                lo, hi = line_bounds_col(c)
                target = col_target[c]
                if target == lo:
                    for vid in list(col_to_vars[c]):
                        if assigned[vid] != -1:
                            continue
                        for sid in (0, 1):
                            if domains[vid] & (1 << sid):
                                contrib = sum(1 for h in option_holes(vid, sid) if h[1] == c)
                                alt = None
                                if domains[vid] & (1 << (sid ^ 1)):
                                    alt = sum(1 for h in option_holes(vid, sid ^ 1) if h[1] == c)
                                if contrib > (alt if alt is not None else contrib):
                                    mark = len(trail)
                                    q = []
                                    if not remove_option(vid, sid, q):
                                        undo(mark)
                                        return False
                                    if q:
                                        changed = True
                                        ok = propagate_local(q)
                                        if not ok:
                                            undo(mark)
                                            return False
                                    break
                elif target == hi:
                    for vid in list(col_to_vars[c]):
                        if assigned[vid] != -1:
                            continue
                        for sid in (0, 1):
                            if domains[vid] & (1 << sid):
                                contrib = sum(1 for h in option_holes(vid, sid) if h[1] == c)
                                alt = None
                                if domains[vid] & (1 << (sid ^ 1)):
                                    alt = sum(1 for h in option_holes(vid, sid ^ 1) if h[1] == c)
                                if alt is not None and contrib < alt:
                                    mark = len(trail)
                                    q = []
                                    if not remove_option(vid, sid, q):
                                        undo(mark)
                                        return False
                                    if q:
                                        changed = True
                                        ok = propagate_local(q)
                                        if not ok:
                                            undo(mark)
                                            return False
                                    break

        return True

    def propagate_local(initial_queue):
        queue = list(initial_queue)
        seen = set(queue)
        while queue:
            vid = queue.pop()
            seen.discard(vid)
            mask = domains[vid]
            if mask == 0:
                return False
            if assigned[vid] == -1 and mask in (1, 2):
                sid = 0 if mask == 1 else 1
                q = []
                if not commit_assignment(vid, sid, q):
                    return False
                for v in q:
                    if v not in seen:
                        seen.add(v)
                        queue.append(v)
            if assigned[vid] == -1:
                for sid in (0, 1):
                    if domains[vid] & (1 << sid):
                        for h in option_holes(vid, sid):
                            owner = hole_owner.get(h)
                            if owner is not None and owner != vid:
                                q = []
                                if not remove_option(vid, sid, q):
                                    return False
                                for v in q:
                                    if v not in seen:
                                        seen.add(v)
                                        queue.append(v)
                                break
        for r in range(n):
            lo, hi = line_bounds_row(r)
            if lo > row_target[r] or hi < row_target[r]:
                return False
        for c in range(n):
            lo, hi = line_bounds_col(c)
            if lo > col_target[c] or hi < col_target[c]:
                return False
        return True

    def solved():
        return all(a != -1 for a in assigned) and row_used == row_target and col_used == col_target

    def choose_var():
        best = None
        best_score = None
        for vid in range(m):
            if assigned[vid] != -1:
                continue
            mask = domains[vid]
            if mask == 0:
                return None
            opts = [sid for sid in (0, 1) if mask & (1 << sid)]
            if len(opts) == 1:
                return vid
            # Heuristic: variable whose options differ most on constrained rows/cols and uses crowded holes.
            score = 0
            for sid in opts:
                for h in option_holes(vid, sid):
                    score += len(hole_to_vars[h])
                    r, c = h
                    score += abs(row_target[r] - row_used[r]) + abs(col_target[c] - col_used[c])
            # Prefer more constrained => higher score, but fewer options first.
            key = (len(opts), -score)
            if best is None or key < best_score:
                best = vid
                best_score = key
        return best

    def option_preference(vid):
        # Order options by estimated consistency with remaining row/col deficits.
        prefs = []
        for sid in (0, 1):
            if not (domains[vid] & (1 << sid)):
                continue
            value = 0
            for h in option_holes(vid, sid):
                r, c = h
                value += (row_target[r] - row_used[r]) + (col_target[c] - col_used[c])
            prefs.append((-value, sid))
        prefs.sort()
        return [sid for _, sid in prefs]

    def dfs():
        if solved():
            return True
        vid = choose_var()
        if vid is None:
            return False

        for sid in option_preference(vid):
            mark = len(trail)
            q = []
            if force_assign(vid, sid, q) and propagate_local(q) and propagate():
                if dfs():
                    return True
            undo(mark)
        return False

    if not propagate():
        return "No Solution"
    if not dfs():
        return "No Solution"

    result = []
    for vid, sid in enumerate(assigned):
        seg = variables[vid][sid]
        result.append([seg[0], seg[1]])
    result.sort()
    return str(result)


