from copy import deepcopy

def parse_unit(unit):
    if 'x' in unit:
        a, b = unit.split('x')
        return int(a), int(b)
    u = int(unit)
    return u, u

def bit_count(x):
    return x.bit_count()

def iter_bits(mask):
    while mask:
        b = mask & -mask
        yield b
        mask ^= b

def bit_to_value(bit):
    return bit.bit_length()

def solve(observation):
    grid = observation['data']
    br, bc = parse_unit(observation['unit'])
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    all_mask = (1 << n) - 1

    cell_to_box = [0] * (n * n)
    boxes = [[] for _ in range(n)]
    peers = [[] for _ in range(n * n)]
    units_of_cell = [[] for _ in range(n * n)]

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]

    box_index = 0
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            cells = []
            for r in range(r0, r0 + br):
                for c in range(c0, c0 + bc):
                    idx = r * n + c
                    cell_to_box[idx] = box_index
                    cells.append(idx)
            boxes[box_index] = cells
            box_index += 1

    for r in range(n):
        for c in range(n):
            idx = r * n + c
            b = cell_to_box[idx]
            units = [rows[r], cols[c], boxes[b]]
            units_of_cell[idx] = units
            p = set()
            for u in units:
                p.update(u)
            p.discard(idx)
            peers[idx] = list(p)

    values = [0] * (n * n)
    cand = [all_mask] * (n * n)

    def assign(idx, bit, queue):
        current = cand[idx]
        if current == bit:
            return True
        if not (current & bit):
            return False
        other = current & ~bit
        if other:
            for b in iter_bits(other):
                if not eliminate(idx, b, queue):
                    return False
        return True

    def eliminate(idx, bit, queue):
        current = cand[idx]
        if not (current & bit):
            return True
        new_mask = current & ~bit
        if new_mask == 0:
            return False
        cand[idx] = new_mask

        if bit_count(new_mask) == 1:
            only = new_mask
            if values[idx] == 0:
                values[idx] = bit_to_value(only)
                queue.append(idx)
            for p in peers[idx]:
                if not eliminate(p, only, queue):
                    return False

        for unit in units_of_cell[idx]:
            places = []
            for cidx in unit:
                if cand[cidx] & bit:
                    places.append(cidx)
            if not places:
                return False
            if len(places) == 1:
                if not assign(places[0], bit, queue):
                    return False
        return True

    initial_queue = []
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                idx = r * n + c
                if not assign(idx, 1 << (v - 1), initial_queue):
                    return "No Solution"

    def propagate():
        changed = True
        while changed:
            changed = False

            # Locked candidates / pointing / claiming
            for unit_type in (rows, cols, boxes):
                for unit in unit_type:
                    digit_places = [0] * n
                    for idx in unit:
                        m = cand[idx]
                        while m:
                            b = m & -m
                            digit_places[b.bit_length() - 1] |= (1 << (idx % (n * n)))
                            m ^= b

            for b_cells in boxes:
                row_buckets = {}
                col_buckets = {}
                for idx in b_cells:
                    r, c = divmod(idx, n)
                    m = cand[idx]
                    while m:
                        b = m & -m
                        d = b.bit_length() - 1
                        row_buckets.setdefault(d, set()).add(r)
                        col_buckets.setdefault(d, set()).add(c)
                        m ^= b
                for d, rs in row_buckets.items():
                    if len(rs) == 1:
                        r = next(iter(rs))
                        bit = 1 << d
                        for idx in rows[r]:
                            if idx not in b_cells and (cand[idx] & bit):
                                if not eliminate(idx, bit, []):
                                    return False
                                changed = True
                    # claim from row to box handled below
                for d, cs in col_buckets.items():
                    if len(cs) == 1:
                        c = next(iter(cs))
                        bit = 1 << d
                        for idx in cols[c]:
                            if idx not in b_cells and (cand[idx] & bit):
                                if not eliminate(idx, bit, []):
                                    return False
                                changed = True

            for r in range(n):
                unit = rows[r]
                box_buckets = {}
                for idx in unit:
                    b = cell_to_box[idx]
                    m = cand[idx]
                    while m:
                        bit = m & -m
                        d = bit.bit_length() - 1
                        box_buckets.setdefault(d, set()).add(b)
                        m ^= bit
                for d, bs in box_buckets.items():
                    if len(bs) == 1:
                        b = next(iter(bs))
                        bit = 1 << d
                        for idx in boxes[b]:
                            rr = idx // n
                            if rr != r and (cand[idx] & bit):
                                if not eliminate(idx, bit, []):
                                    return False
                                changed = True

            for c in range(n):
                unit = cols[c]
                box_buckets = {}
                for idx in unit:
                    b = cell_to_box[idx]
                    m = cand[idx]
                    while m:
                        bit = m & -m
                        d = bit.bit_length() - 1
                        box_buckets.setdefault(d, set()).add(b)
                        m ^= bit
                for d, bs in box_buckets.items():
                    if len(bs) == 1:
                        b = next(iter(bs))
                        bit = 1 << d
                        for idx in boxes[b]:
                            cc = idx % n
                            if cc != c and (cand[idx] & bit):
                                if not eliminate(idx, bit, []):
                                    return False
                                changed = True

            # Naked subsets
            for collection in (rows, cols, boxes):
                for unit in collection:
                    masks = {}
                    unsolved = [idx for idx in unit if bit_count(cand[idx]) > 1]
                    for idx in unsolved:
                        m = cand[idx]
                        k = bit_count(m)
                        if 2 <= k <= 4:
                            masks.setdefault(m, []).append(idx)
                    for m, cells in masks.items():
                        k = bit_count(m)
                        if len(cells) == k:
                            for idx in unit:
                                if idx not in cells:
                                    overlap = cand[idx] & m
                                    if overlap:
                                        nm = cand[idx] & ~m
                                        if nm == 0:
                                            return False
                                        if nm != cand[idx]:
                                            for b in iter_bits(overlap):
                                                if not eliminate(idx, b, []):
                                                    return False
                                            changed = True

            # Hidden subsets
            for collection in (rows, cols, boxes):
                for unit in collection:
                    digit_to_cells = {}
                    for d in range(n):
                        bit = 1 << d
                        cells = [idx for idx in unit if cand[idx] & bit]
                        if 1 <= len(cells) <= 4:
                            digit_to_cells[d] = tuple(cells)
                    inv = {}
                    for d, cells in digit_to_cells.items():
                        inv.setdefault(cells, []).append(d)
                    for cells, digits in inv.items():
                        k = len(cells)
                        if 2 <= k <= 4 and len(digits) == k:
                            keep = 0
                            for d in digits:
                                keep |= 1 << d
                            for idx in cells:
                                rem = cand[idx] & ~keep
                                if rem:
                                    for b in iter_bits(rem):
                                        if not eliminate(idx, b, []):
                                            return False
                                    changed = True

        return True

    if not propagate():
        return "No Solution"

    def solved():
        return all(bit_count(m) == 1 for m in cand)

    def snapshot():
        return cand[:], values[:]

    def restore(state):
        nonlocal cand, values
        cand, values = state[0][:], state[1][:]

    def search():
        if solved():
            return True

        # Choose cell with minimum remaining candidates, tie-break by peer pressure
        best = -1
        best_count = n + 1
        best_score = -1
        for idx in range(n * n):
            bc = bit_count(cand[idx])
            if 1 < bc < best_count:
                best = idx
                best_count = bc
                best_score = sum(1 for p in peers[idx] if bit_count(cand[p]) > 1)
            elif bc == best_count and bc > 1:
                score = sum(1 for p in peers[idx] if bit_count(cand[p]) > 1)
                if score > best_score:
                    best = idx
                    best_score = score

        if best == -1:
            return False

        # Least constraining value ordering
        options = []
        for bit in iter_bits(cand[best]):
            impact = 0
            for p in peers[best]:
                if cand[p] & bit:
                    impact += 1
            options.append((impact, bit))
        options.sort()

        state = snapshot()
        for _, bit in options:
            restore(state)
            if assign(best, bit, []):
                if propagate() and search():
                    return True
        restore(state)
        return False

    if not search():
        return "No Solution"

    result = []
    for r in range(n):
        row = []
        for c in range(n):
            m = cand[r * n + c]
            if bit_count(m) != 1:
                return "No Solution"
            row.append(bit_to_value(m))
        result.append(row)
    return str(result)

