from collections import defaultdict, deque
import ast

# Tetromino-region puzzle solver.
# Returns a Python-literal answer grid of same size using 'L'/'I'/'T'/'S' for shaded cells, None otherwise.

DIR4 = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))


def transform(cells, k):
    pts = list(cells)
    if k == 0:
        out = [(r, c) for r, c in pts]
    elif k == 1:
        out = [(r, -c) for r, c in pts]
    elif k == 2:
        out = [(-r, c) for r, c in pts]
    elif k == 3:
        out = [(-r, -c) for r, c in pts]
    elif k == 4:
        out = [(c, r) for r, c in pts]
    elif k == 5:
        out = [(c, -r) for r, c in pts]
    elif k == 6:
        out = [(-c, r) for r, c in pts]
    else:
        out = [(-c, -r) for r, c in pts]
    return normalize(out)


def unique_orientations(base):
    seen = set()
    out = []
    for k in range(8):
        n = transform(base, k)
        if n not in seen:
            seen.add(n)
            out.append(n)
    return out


BASES = {
    'I': normalize([(0, 0), (1, 0), (2, 0), (3, 0)]),
    'L': normalize([(0, 0), (1, 0), (2, 0), (2, 1)]),
    'T': normalize([(0, 0), (0, 1), (0, 2), (1, 1)]),
    'S': normalize([(0, 1), (0, 2), (1, 0), (1, 1)]),
}

TYPE_ORIENTS = {t: unique_orientations([p for p in cells]) for t, cells in BASES.items()}


def region_adjacency(region_grid):
    n = len(region_grid)
    m = len(region_grid[0])
    adj = defaultdict(set)
    for r in range(n):
        for c in range(m):
            a = region_grid[r][c]
            for dr, dc in ((1, 0), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    b = region_grid[nr][nc]
                    if a != b:
                        adj[a].add(b)
                        adj[b].add(a)
    return {k: set(v) for k, v in adj.items()}


def components(cells):
    cells = set(cells)
    comps = []
    while cells:
        start = next(iter(cells))
        q = [start]
        cells.remove(start)
        comp = {start}
        while q:
            r, c = q.pop()
            for dr, dc in DIR4:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells:
                    cells.remove((nr, nc))
                    comp.add((nr, nc))
                    q.append((nr, nc))
        comps.append(comp)
    return comps


def all_region_placements(region_cells):
    rcells = set(region_cells)
    by_type = defaultdict(list)
    # Enumerate connected 4-subsets inside region by anchored translations of canonical tetrominoes.
    for t, orients in TYPE_ORIENTS.items():
        seen = set()
        for orient in orients:
            for anchor in region_cells:
                ar, ac = anchor
                for br, bc in orient:
                    dr, dc = ar - br, ac - bc
                    placed = tuple(sorted((r + dr, c + dc) for r, c in orient))
                    pset = set(placed)
                    if pset <= rcells:
                        key = tuple(placed)
                        if key not in seen:
                            seen.add(key)
                            by_type[t].append(key)
    return dict(by_type)


def find_2x2_blocks(n, m):
    blocks = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks.append(((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
    return blocks


def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0])

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Each region must support at least one tetromino placement.
    placements_by_region = {}
    for rid in region_ids:
        placements_by_region[rid] = all_region_placements(regions[rid])
        if not placements_by_region[rid]:
            return "No Solution"

    adj = region_adjacency(grid)
    for rid in region_ids:
        adj.setdefault(rid, set())

    cell_to_regions = {}
    for rid, cells in regions.items():
        for cell in cells:
            cell_to_regions[cell] = rid

    all_cells = {(r, c) for r in range(n) for c in range(m)}
    blocks_2x2 = find_2x2_blocks(n, m)

    # Candidate object list per region.
    # Each candidate = {'type': t, 'cells': frozenset(...)}
    candidates = {}
    for rid in region_ids:
        lst = []
        for t, plist in placements_by_region[rid].items():
            for p in plist:
                lst.append({'type': t, 'cells': frozenset(p)})
        candidates[rid] = lst
        if not lst:
            return "No Solution"

    # Precompute region-local forced info for propagation speed.
    region_cell_set = {rid: set(cells) for rid, cells in regions.items()}

    # For quick 2x2 checking under partial assignment:
    cell_blocks = defaultdict(list)
    for idx, blk in enumerate(blocks_2x2):
        for cell in blk:
            cell_blocks[cell].append(idx)

    # Human-like propagation:
    # 1) Remove candidates violating already fixed neighboring region types.
    # 2) Region candidate domains shrink from 2x2 inevitability.
    # 3) Connectivity feasibility: shaded chosen cells plus potential future cells must still admit a single component.
    # 4) Components lower-bound pruning on already chosen cells.

    def domain_signature(domains):
        return tuple((rid, tuple(sorted((cand['type'], tuple(sorted(cand['cells']))) for cand in domains[rid]))) for rid in region_ids)

    def apply_type_adjacency(domains):
        changed = True
        while changed:
            changed = False
            fixed_types = {}
            for rid in region_ids:
                types = {c['type'] for c in domains[rid]}
                if not types:
                    return False
                if len(types) == 1:
                    fixed_types[rid] = next(iter(types))
            for rid in region_ids:
                forbidden = {fixed_types[nb] for nb in adj[rid] if nb in fixed_types}
                if not forbidden:
                    continue
                newdom = [c for c in domains[rid] if c['type'] not in forbidden or (len({x['type'] for x in domains[rid]}) == 1 and c['type'] in {x['type'] for x in domains[rid]})]
                # The "or" above avoids over-filtering when this region itself is fixed; actual contradiction will be handled below.
                if len(newdom) != len(domains[rid]):
                    domains[rid] = newdom
                    changed = True
                if not domains[rid]:
                    return False
            # Enforce direct contradiction for fixed-equal adjacent regions.
            fixed_types = {}
            for rid in region_ids:
                types = {c['type'] for c in domains[rid]}
                if len(types) == 1:
                    fixed_types[rid] = next(iter(types))
            for rid, t in fixed_types.items():
                for nb in adj[rid]:
                    if nb in fixed_types and fixed_types[nb] == t:
                        return False
        return True

    def apply_2x2_prune(domains):
        changed = True
        while changed:
            changed = False
            # For each 2x2 block, if all 4 cells would be forced shaded across region domains, contradiction.
            # Stronger: if in a block, for each cell's region every candidate shades that cell, then impossible.
            forced_shaded = {}
            possible_shaded = {}
            for rid in region_ids:
                dom = domains[rid]
                union = set()
                inter = set(dom[0]['cells'])
                for cand in dom:
                    union |= cand['cells']
                    inter &= cand['cells']
                possible_shaded[rid] = union
                forced_shaded[rid] = inter
            for blk in blocks_2x2:
                if all(cell in forced_shaded[cell_to_regions[cell]] for cell in blk):
                    return False

            # Candidate-level elimination:
            for rid in region_ids:
                newdom = []
                for cand in domains[rid]:
                    bad = False
                    # If choosing cand forces some 2x2 full because the other three cells are forced by their regions.
                    for cell in cand['cells']:
                        for bidx in cell_blocks[cell]:
                            blk = blocks_2x2[bidx]
                            if cell not in blk:
                                continue
                            all_full = True
                            for x in blk:
                                rr = cell_to_regions[x]
                                if rr == rid:
                                    if x not in cand['cells']:
                                        all_full = False
                                        break
                                else:
                                    if x not in forced_shaded[rr]:
                                        all_full = False
                                        break
                            if all_full:
                                bad = True
                                break
                        if bad:
                            break
                    if not bad:
                        newdom.append(cand)
                if not newdom:
                    return False
                if len(newdom) != len(domains[rid]):
                    domains[rid] = newdom
                    changed = True
        return True

    def connectivity_possible(domains):
        # Over-approximation: chosen cells = cells in singleton domains' sole candidate.
        # possible cells = union of all candidates.
        chosen = set()
        possible = set()
        for rid in region_ids:
            dom = domains[rid]
            u = set()
            for cand in dom:
                u |= cand['cells']
            possible |= u
            if len(dom) == 1:
                chosen |= set(dom[0]['cells'])
        if not possible:
            return False

        # All chosen cells must lie in one connected component of possible cells.
        if chosen:
            start = next(iter(chosen))
        else:
            start = next(iter(possible))
        seen = {start}
        dq = [start]
        while dq:
            r, c = dq.pop()
            for dr, dc in DIR4:
                nr, nc = r + dr, c + dc
                if (nr, nc) in possible and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    dq.append((nr, nc))
        if not chosen <= seen:
            return False

        # Every region must have at least one candidate touching the main possible component containing chosen/start.
        comp = seen
        for rid in region_ids:
            if not any(cand['cells'] & comp for cand in domains[rid]):
                return False

        # Lower-bound on current chosen disconnected singleton components:
        if chosen:
            comps = components(chosen)
            # Count regions not fixed yet that could bridge between components.
            unfixed = [rid for rid in region_ids if len(domains[rid]) > 1]
            if len(comps) > 1 and len(unfixed) == 0:
                return False
        return True

    def propagate(domains):
        prev = None
        while True:
            sig = domain_signature(domains)
            if sig == prev:
                return True
            prev = sig
            if not apply_type_adjacency(domains):
                return False
            if not apply_2x2_prune(domains):
                return False
            if not connectivity_possible(domains):
                return False

    def choose_region(domains):
        # Most constrained region, tie by type diversity then adjacency degree.
        best = None
        best_key = None
        for rid in region_ids:
            d = domains[rid]
            if len(d) <= 1:
                continue
            types = {c['type'] for c in d}
            key = (len(d), len(types), -len(adj[rid]))
            if best_key is None or key < best_key:
                best_key = key
                best = rid
        return best

    def final_check(assignments):
        # assignments: rid -> candidate
        # global connectivity
        shaded = set()
        type_of = {}
        for rid, cand in assignments.items():
            shaded |= set(cand['cells'])
            type_of[rid] = cand['type']
        if len(shaded) != 4 * len(region_ids):
            return False
        if shaded:
            comp = components(shaded)
            if len(comp) != 1:
                return False
        for blk in blocks_2x2:
            if all(cell in shaded for cell in blk):
                return False
        for rid in region_ids:
            for nb in adj[rid]:
                if rid < nb and type_of[rid] == type_of[nb]:
                    return False
        return True

    def search(domains):
        if not propagate(domains):
            return None
        if all(len(domains[rid]) == 1 for rid in region_ids):
            assignments = {rid: domains[rid][0] for rid in region_ids}
            if final_check(assignments):
                return assignments
            return None

        rid = choose_region(domains)
        # Value ordering: prefer candidates that increase connection to already forced/likely cells.
        chosen = set()
        possible_union = set()
        for rr in region_ids:
            if len(domains[rr]) == 1:
                chosen |= set(domains[rr][0]['cells'])
            for cand in domains[rr]:
                possible_union |= set(cand['cells'])

        def score(cand):
            cells = cand['cells']
            touch_chosen = 0
            frontier = 0
            for r, c in cells:
                for dr, dc in DIR4:
                    nb = (r + dr, c + dc)
                    if nb in chosen:
                        touch_chosen += 1
                    if nb in possible_union:
                        frontier += 1
            # prefer stronger connectivity and rarer type among neighbors
            neighbor_same_fixed = 0
            for nb_rid in adj[rid]:
                types = {x['type'] for x in domains[nb_rid]}
                if len(types) == 1 and cand['type'] in types:
                    neighbor_same_fixed += 1
            return (-neighbor_same_fixed, -touch_chosen, -frontier)

        for cand in sorted(domains[rid], key=score):
            new_domains = {rr: list(domains[rr]) for rr in region_ids}
            new_domains[rid] = [cand]
            res = search(new_domains)
            if res is not None:
                return res
        return None

    result = search({rid: list(candidates[rid]) for rid in region_ids})
    if result is None:
        return "No Solution"

    out = [[None for _ in range(m)] for _ in range(n)]
    for rid, cand in result.items():
        t = cand['type']
        for r, c in cand['cells']:
            out[r][c] = t
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[-1, None, None, None, None, 1, 1, None, None, -1], [None, 2, None, None, None, None, None, None, -1, None], [None, None, None, None, None, None, 0, None, None, None], [0, None, 1, None, None, None, None, None, None, None], [1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, 1], [None, None, None, None, None, None, None, 1, None, 2], [None, None, None, 1, None, None, None, None, None, None], [None, -1, None, None, None, None, None, None, 2, None], [-1, None, None, -1, -1, None, None, None, None, -1]]}

from collections import deque

BULB = 1
NOBULB = 0
UNKNOWN = -1


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = len(data[0]) if n else 0

    white_cells = []
    black_cells = set()
    numbered = {}

    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if v is None:
                white_cells.append((r, c))
            else:
                black_cells.add((r, c))
                if v >= 0:
                    numbered[(r, c)] = v

    white_index = {cell: i for i, cell in enumerate(white_cells)}
    W = len(white_cells)

    # Precompute line-of-sight groups split by black cells.
    row_segments = []
    row_seg_id = {}
    for r in range(n):
        c = 0
        while c < m:
            while c < m and data[r][c] is not None:
                c += 1
            if c >= m:
                break
            seg = []
            while c < m and data[r][c] is None:
                seg.append((r, c))
                c += 1
            sid = len(row_segments)
            row_segments.append(seg)
            for cell in seg:
                row_seg_id[cell] = sid

    col_segments = []
    col_seg_id = {}
    for c in range(m):
        r = 0
        while r < n:
            while r < n and data[r][c] is not None:
                r += 1
            if r >= n:
                break
            seg = []
            while r < n and data[r][c] is None:
                seg.append((r, c))
                r += 1
            sid = len(col_segments)
            col_segments.append(seg)
            for cell in seg:
                col_seg_id[cell] = sid

    # Visibility sets for each white cell.
    sees = [[] for _ in range(W)]
    for cell, i in white_index.items():
        rs = row_segments[row_seg_id[cell]]
        cs = col_segments[col_seg_id[cell]]
        vis = set(rs)
        vis.update(cs)
        vis.discard(cell)
        sees[i] = [white_index[x] for x in vis]

    # Numbered-black adjacency.
    num_adj = {}
    cell_to_num_constraints = [[] for _ in range(W)]
    for bc, val in numbered.items():
        r, c = bc
        adj = []
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < n and 0 <= nc < m and data[nr][nc] is None:
                idx = white_index[(nr, nc)]
                adj.append(idx)
                cell_to_num_constraints[idx].append(bc)
        num_adj[bc] = adj

    # Candidate bulbs capable of illuminating each white cell.
    # A cell can be illuminated by a bulb in its row segment or column segment.
    illuminators = [[] for _ in range(W)]
    for cell, i in white_index.items():
        rs = row_segments[row_seg_id[cell]]
        cs = col_segments[col_seg_id[cell]]
        cand = set(white_index[x] for x in rs)
        cand.update(white_index[x] for x in cs)
        illuminators[i] = list(cand)

    # For each segment, at most one bulb.
    segments = []
    seg_of_cell = [[] for _ in range(W)]
    for seg in row_segments:
        ids = [white_index[x] for x in seg]
        sid = len(segments)
        segments.append(ids)
        for i in ids:
            seg_of_cell[i].append(sid)
    for seg in col_segments:
        ids = [white_index[x] for x in seg]
        sid = len(segments)
        segments.append(ids)
        for i in ids:
            seg_of_cell[i].append(sid)

    # Mutable state.
    state = [UNKNOWN] * W
    lit_count = [0] * W
    remaining_illum = [len(illuminators[i]) for i in range(W)]

    seg_bulb_count = [0] * len(segments)
    seg_unknown_count = [len(seg) for seg in segments)

    num_bulb_count = {bc: 0 for bc in numbered}
    num_unknown_count = {bc: len(num_adj[bc]) for bc in numbered}

    trail = []

    def mark_lit_by(i, delta):
        # Update lit_count for cell itself and all visible cells.
        targets = [i]
        targets.extend(sees[i])
        for t in targets:
            old = lit_count[t]
            lit_count[t] = old + delta
            trail.append(("lit", t, old))

    def reduce_illum_option(i):
        old = remaining_illum[i]
        remaining_illum[i] = old - 1
        trail.append(("remill", i, old))

    def set_cell(i, val, queue):
        cur = state[i]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False

        trail.append(("state", i, cur))
        state[i] = val

        for sid in seg_of_cell[i]:
            oldu = seg_unknown_count[sid]
            seg_unknown_count[sid] = oldu - 1
            trail.append(("segunk", sid, oldu))

        for bc in cell_to_num_constraints[i]:
            oldu = num_unknown_count[bc]
            num_unknown_count[bc] = oldu - 1
            trail.append(("numunk", bc, oldu))

        if val == BULB:
            for sid in seg_of_cell[i]:
                oldb = seg_bulb_count[sid]
                seg_bulb_count[sid] = oldb + 1
                trail.append(("segb", sid, oldb))
                if seg_bulb_count[sid] > 1:
                    return False
            for bc in cell_to_num_constraints[i]:
                oldb = num_bulb_count[bc]
                num_bulb_count[bc] = oldb + 1
                trail.append(("numb", bc, oldb))
                if num_bulb_count[bc] > numbered[bc]:
                    return False

            mark_lit_by(i, 1)

            # A bulb forbids all visible cells from also being bulbs.
            for j in sees[i]:
                if state[j] == BULB:
                    return False
                if state[j] == UNKNOWN:
                    queue.append(("set", j, NOBULB))

            # Segment uniqueness also forces others in same row/col segments to NOBULB.
            for sid in seg_of_cell[i]:
                for j in segments[sid]:
                    if j != i and state[j] == UNKNOWN:
                        queue.append(("set", j, NOBULB))
        else:
            # Removing this cell as a possible illuminator for all it can light.
            targets = [i]
            targets.extend(sees[i])
            for t in targets:
                reduce_illum_option(t)

        return True

    def checkpoint():
        return len(trail)

    def undo(cp):
        while len(trail) > cp:
            item = trail.pop()
            tag = item[0]
            if tag == "state":
                _, i, old = item
                state[i] = old
            elif tag == "lit":
                _, i, old = item
                lit_count[i] = old
            elif tag == "remill":
                _, i, old = item
                remaining_illum[i] = old
            elif tag == "segb":
                _, sid, old = item
                seg_bulb_count[sid] = old
            elif tag == "segunk":
                _, sid, old = item
                seg_unknown_count[sid] = old
            elif tag == "numb":
                _, bc, old = item
                num_bulb_count[bc] = old
            elif tag == "numunk":
                _, bc, old = item
                num_unknown_count[bc] = old

    def enqueue_initial_rules():
        q = deque()
        for bc, req in numbered.items():
            adj = num_adj[bc]
            if req == 0:
                for i in adj:
                    if state[i] == UNKNOWN:
                        q.append(("set", i, NOBULB))
            elif req == len(adj):
                for i in adj:
                    if state[i] == UNKNOWN:
                        q.append(("set", i, BULB))
        return q

    def propagate(queue):
        q = deque(queue)

        while True:
            while q:
                typ, *rest = q.popleft()
                if typ == "set":
                    i, val = rest
                    if not set_cell(i, val, q):
                        return False

                # Immediate consistency checks around any changes.
                if remaining_illum[rest[0]] < 0 if typ == "set" and rest[1] == NOBULB else False:
                    return False

            progress = False

            # Global contradiction checks.
            for i in range(W):
                if state[i] == UNKNOWN and remaining_illum[i] == 0 and lit_count[i] == 0:
                    return False
                if state[i] != BULB and lit_count[i] == 0 and remaining_illum[i] == 0:
                    return False

            for bc, req in numbered.items():
                b = num_bulb_count[bc]
                u = num_unknown_count[bc]
                if b > req or b + u < req:
                    return False
                if u == 0:
                    continue
                adj = num_adj[bc]
                if b == req:
                    for i in adj:
                        if state[i] == UNKNOWN:
                            q.append(("set", i, NOBULB))
                            progress = True
                elif b + u == req:
                    for i in adj:
                        if state[i] == UNKNOWN:
                            q.append(("set", i, BULB))
                            progress = True

            # Segment rule: at most one bulb per segment.
            # If a segment already has one bulb, all others must be NOBULB.
            # If a white cell is currently unlit and only one possible illuminator remains, force it.
            for i in range(W):
                if lit_count[i] == 0:
                    if state[i] == UNKNOWN:
                        candidates = []
                        for j in illuminators[i]:
                            if state[j] == BULB:
                                candidates = [j]
                                break
                            if state[j] == UNKNOWN:
                                # j can still be bulb only if both segments have no bulb yet.
                                ok = True
                                for sid in seg_of_cell[j]:
                                    if seg_bulb_count[sid] >= 1:
                                        ok = False
                                        break
                                if ok:
                                    candidates.append(j)
                        if not candidates:
                            return False
                        if len(candidates) == 1 and state[candidates[0]] == UNKNOWN:
                            q.append(("set", candidates[0], BULB))
                            progress = True
                    else:
                        # Assigned NOBULB but still unlit: must have an external candidate.
                        candidates = []
                        for j in illuminators[i]:
                            if state[j] == BULB:
                                candidates = [j]
                                break
                            if state[j] == UNKNOWN:
                                ok = True
                                for sid in seg_of_cell[j]:
                                    if seg_bulb_count[sid] >= 1:
                                        ok = False
                                        break
                                if ok:
                                    candidates.append(j)
                        if not candidates:
                            return False
                        if len(candidates) == 1 and state[candidates[0]] == UNKNOWN:
                            q.append(("set", candidates[0], BULB))
                            progress = True

            # Segment exactness from illumination necessity:
            # if a whole segment has no possible bulb left and some cells there/linked remain unlit,
            # that will be detected by unique-candidate checks above, so no extra heavy rule needed.

            if not q:
                if not progress:
                    break

        # Final local consistency after fixpoint.
        for sid, seg in enumerate(segments):
            if seg_bulb_count[sid] > 1:
                return False

        for bc, req in numbered.items():
            b = num_bulb_count[bc]
            u = num_unknown_count[bc]
            if b > req or b + u < req:
                return False

        for i in range(W):
            if lit_count[i] == 0 and remaining_illum[i] == 0:
                return False

        return True

    def solved():
        for bc, req in numbered.items():
            if num_bulb_count[bc] != req:
                return False
        for sid in range(len(segments)):
            if seg_bulb_count[sid] > 1:
                return False
        for i in range(W):
            if lit_count[i] == 0:
                return False
        return True

    def choose_branch_cell():
        best = None
        best_score = None

        # Prefer forced-by-coverage ambiguous cells, then numbered adjacency, then illumination reach.
        for i in range(W):
            if state[i] != UNKNOWN:
                continue

            can_bulb = True
            for sid in seg_of_cell[i]:
                if seg_bulb_count[sid] >= 1:
                    can_bulb = False
                    break

            # Score lower is more constrained.
            num_pressure = 0
            for bc in cell_to_num_constraints[i]:
                req = numbered[bc]
                b = num_bulb_count[bc]
                u = num_unknown_count[bc]
                num_pressure += min(abs((b + u) - req), abs(req - b))

            cover_need = 0
            for t in [i] + sees[i]:
                if lit_count[t] == 0:
                    cover_need += 1

            score = (
                0 if can_bulb else 1,
                len(illuminators[i]),
                num_pressure,
                -cover_need,
                len(sees[i]),
            )
            if best_score is None or score < best_score:
                best_score = score
                best = i
        return best

    def dfs():
        if solved():
            return True

        i = choose_branch_cell()
        if i is None:
            return False

        # Branch ordering: prefer BULB if it covers more currently unlit cells or helps constraints.
        cover = sum(1 for t in ([i] + sees[i]) if lit_count[t] == 0)
        bulb_first = cover > 0

        for val in ((BULB, NOBULB) if bulb_first else (NOBULB, BULB)):
            # Fast skip impossible BULB
            if val == BULB:
                impossible = False
                for sid in seg_of_cell[i]:
                    if seg_bulb_count[sid] >= 1:
                        impossible = True
                        break
                if not impossible:
                    for bc in cell_to_num_constraints[i]:
                        if num_bulb_count[bc] + 1 > numbered[bc]:
                            impossible = True
                            break
                if impossible:
                    continue

            cp = checkpoint()
            if propagate([("set", i, val)]) and dfs():
                return True
            undo(cp)
        return False

    cp0 = checkpoint()
    if not propagate(enqueue_initial_rules()):
        undo(cp0)
        return "No Solution"

    if not dfs():
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for (r, c), i in white_index.items():
        if state[i] == BULB:
            ans[r][c] = 'B'
    return str(ans)


