from collections import defaultdict, deque
import ast

# General Tetromino-region puzzle solver.
# The solver is designed around region-local candidate generation plus strong propagation:
# - each region must choose exactly one 4-cell connected tetromino of allowed type
# - adjacent regions cannot choose same tetromino type
# - globally shaded cells must be connected
# - no fully shaded 2x2 block
#
# Output is a Python-literal grid of same size containing 'L'/'I'/'T'/'S' on shaded cells and None otherwise.


def normalize_shape(cells):
    mr = min(r for r, c in cells)
    mc = min(c for r, c in cells)
    return tuple(sorted((r - mr, c - mc) for r, c in cells))


def rotate(cells):
    return [(-c, r) for r, c in cells]


def reflect(cells):
    return [(r, -c) for r, c in cells]


def all_orientations(base):
    seen = set()
    cur = list(base)
    for _ in range(4):
        for variant in (cur, reflect(cur)):
            n = normalize_shape(variant)
            seen.add(n)
        cur = rotate(cur)
    return [list(x) for x in sorted(seen)]


BASE_SHAPES = {
    'I': [(0, 0), (1, 0), (2, 0), (3, 0)],
    'L': [(0, 0), (1, 0), (2, 0), (2, 1)],
    'T': [(0, 0), (0, 1), (0, 2), (1, 1)],
    'S': [(0, 1), (0, 2), (1, 0), (1, 1)],
}
ORIENTS = {k: all_orientations(v) for k, v in BASE_SHAPES.items()}


def neighbors4(cell, nrows, ncols):
    r, c = cell
    if r > 0:
        yield (r - 1, c)
    if r + 1 < nrows:
        yield (r + 1, c)
    if c > 0:
        yield (r, c - 1)
    if c + 1 < ncols:
        yield (r, c + 1)


def component_count(cells, nrows, ncols):
    if not cells:
        return 0
    cells = set(cells)
    start = next(iter(cells))
    q = [start]
    seen = {start}
    for x in q:
        for y in neighbors4(x, nrows, ncols):
            if y in cells and y not in seen:
                seen.add(y)
                q.append(y)
    return 1 if len(seen) == len(cells) else 2


def generate_region_candidates(region_cells):
    region_set = set(region_cells)
    candidates = []
    seen = set()
    for typ, orients in ORIENTS.items():
        for orient in orients:
            maxr = max(r for r, c in orient)
            maxc = max(c for r, c in orient)
            for ar, ac in region_cells:
                placed = tuple(sorted((ar + r, ac + c) for r, c in orient))
                if placed in seen:
                    continue
                ok = True
                for rr, cc in placed:
                    if (rr, cc) not in region_set:
                        ok = False
                        break
                if ok:
                    seen.add(placed)
                    candidates.append({'type': typ, 'cells': frozenset(placed)})
    return candidates


def solve(observation):
    grid = observation['data']
    nrows = len(grid)
    ncols = len(grid[0]) if nrows else 0

    regions = defaultdict(list)
    for r in range(nrows):
        for c in range(ncols):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Region adjacency graph.
    radj = {rid: set() for rid in region_ids}
    for r in range(nrows):
        for c in range(ncols):
            a = grid[r][c]
            if r + 1 < nrows:
                b = grid[r + 1][c]
                if a != b:
                    radj[a].add(b)
                    radj[b].add(a)
            if c + 1 < ncols:
                b = grid[r][c + 1]
                if a != b:
                    radj[a].add(b)
                    radj[b].add(a)

    # All 2x2 blocks.
    blocks2 = []
    cell_to_blocks = defaultdict(list)
    for r in range(nrows - 1):
        for c in range(ncols - 1):
            block = ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))
            idx = len(blocks2)
            blocks2.append(block)
            for cell in block:
                cell_to_blocks[cell].append(idx)

    # Generate candidates per region.
    domains = {}
    for rid in region_ids:
        cands = generate_region_candidates(regions[rid])
        if not cands:
            return "No Solution"
        domains[rid] = cands

    # Precompute region/cell membership and type partitions.
    region_cells_set = {rid: set(regions[rid]) for rid in region_ids}

    # Quick impossible: every region contributes 4 cells, global count must allow connectedness.
    total_shaded = 4 * len(region_ids)
    if total_shaded == 0:
        return repr([])

    def candidates_by_type(cands):
        out = defaultdict(list)
        for i, cand in enumerate(cands):
            out[cand['type']].append(i)
        return out

    # State represented as current candidate lists per region.
    def clone_domains(doms):
        return {rid: list(lst) for rid, lst in doms.items()}

    def region_forced_info(cands):
        # intersection/union of cells and possible types
        inter = set(cands[0]['cells'])
        union = set()
        types = set()
        for cand in cands:
            inter &= cand['cells']
            union |= cand['cells']
            types.add(cand['type'])
        return inter, union, types

    def global_forced_possible(doms):
        forced = set()
        possible = set()
        type_poss = {}
        for rid in region_ids:
            inter, union, types = region_forced_info(doms[rid])
            forced |= inter
            possible |= union
            type_poss[rid] = types
        return forced, possible, type_poss

    def check_connectivity_feasibility(doms):
        forced, possible, _ = global_forced_possible(doms)

        # Forced cells must not already split into disconnected islands that cannot be linked through possible cells.
        if not forced:
            return True

        # BFS in possible graph, starting from one forced cell, must reach all forced cells.
        start = next(iter(forced))
        q = deque([start])
        seen = {start}
        while q:
            cell = q.popleft()
            for nb in neighbors4(cell, nrows, ncols):
                if nb in possible and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return forced <= seen

    def check_2x2_feasibility(doms):
        # No block can be forced full.
        forced, possible, _ = global_forced_possible(doms)
        for block in blocks2:
            if all(cell in forced for cell in block):
                return False
            # if some region is fixed etc, further exact checks happen by candidate filtering
        return True

    def check_region_type_adjacency_feasibility(doms):
        # If two adjacent regions are both singleton-typed and equal, impossible.
        type_poss = {}
        for rid in region_ids:
            type_poss[rid] = {cand['type'] for cand in doms[rid]}
            if not type_poss[rid]:
                return False
        for a in region_ids:
            if len(type_poss[a]) == 1:
                ta = next(iter(type_poss[a]))
                for b in radj[a]:
                    if a < b and len(type_poss[b]) == 1 and ta == next(iter(type_poss[b])):
                        return False
        return True

    def filter_domain_by_constraints(rid, doms):
        cands = doms[rid]
        new_cands = []

        # Neighbor type singleton info.
        neighbor_single_types = {}
        for nb in radj[rid]:
            tset = {cand['type'] for cand in doms[nb]}
            if len(tset) == 1:
                neighbor_single_types[nb] = next(iter(tset))

        # Build global forced/possible excluding rid for stronger local checks.
        forced_other = set()
        possible_other = set()
        for x in region_ids:
            if x == rid:
                continue
            inter, union, _ = region_forced_info(doms[x])
            forced_other |= inter
            possible_other |= union

        for cand in cands:
            typ = cand['type']

            # Adjacent regions cannot use same tetromino type when neighbor fixed to type.
            bad = False
            for nb, t in neighbor_single_types.items():
                if typ == t:
                    bad = True
                    break
            if bad:
                continue

            # 2x2 exact local check with current candidate plus forced others.
            shaded_now = forced_other | set(cand['cells'])
            impossible = False
            for cell in cand['cells']:
                for bi in cell_to_blocks[cell]:
                    block = blocks2[bi]
                    if all(x in shaded_now for x in block):
                        impossible = True
                        break
                if impossible:
                    break
            if impossible:
                continue

            # Connectivity feasibility: all forced cells under this choice must be connectable through possible cells.
            forced = forced_other | set(cand['cells'])
            possible = possible_other | set(cand['cells'])
            if forced:
                start = next(iter(forced))
                q = deque([start])
                seen = {start}
                while q:
                    cell = q.popleft()
                    for nb in neighbors4(cell, nrows, ncols):
                        if nb in possible and nb not in seen:
                            seen.add(nb)
                            q.append(nb)
                if not (forced <= seen):
                    continue

            new_cands.append(cand)

        if len(new_cands) != len(cands):
            doms[rid] = new_cands
            return True
        return False

    def propagate(doms):
        changed = True
        while changed:
            changed = False

            for rid in region_ids:
                if not doms[rid]:
                    return False

            if not check_region_type_adjacency_feasibility(doms):
                return False
            if not check_2x2_feasibility(doms):
                return False
            if not check_connectivity_feasibility(doms):
                return False

            # Repeatedly filter each region using current global information.
            for rid in region_ids:
                if filter_domain_by_constraints(rid, doms):
                    changed = True
                    if not doms[rid]:
                        return False

            # Type elimination by adjacent singleton types.
            for a in region_ids:
                if len(doms[a]) == 1:
                    ta = doms[a][0]['type']
                    for b in radj[a]:
                        old = len(doms[b])
                        doms[b] = [cand for cand in doms[b] if cand['type'] != ta]
                        if len(doms[b]) != old:
                            changed = True
                            if not doms[b]:
                                return False

            # If a cell is forced in a region, fine; if a cell is impossible in all candidates, nothing to do.
            # More advanced human-like rule: if a possible global articulation is absent, prune.
            if not check_region_type_adjacency_feasibility(doms):
                return False
            if not check_2x2_feasibility(doms):
                return False
            if not check_connectivity_feasibility(doms):
                return False

        return True

    def is_solved(doms):
        return all(len(doms[rid]) == 1 for rid in region_ids)

    def build_answer(doms):
        ans = [[None for _ in range(ncols)] for _ in range(nrows)]
        shaded = set()
        for rid in region_ids:
            cand = doms[rid][0]
            typ = cand['type']
            for r, c in cand['cells']:
                ans[r][c] = typ
                shaded.add((r, c))

        # Final validation.
        for rid in region_ids:
            cells = {(r, c) for r in range(nrows) for c in range(ncols) if ans[r][c] is not None and grid[r][c] == rid}
            if len(cells) != 4:
                return None

        for a in region_ids:
            ta = doms[a][0]['type']
            for b in radj[a]:
                if a < b and ta == doms[b][0]['type']:
                    return None

        for block in blocks2:
            if all(ans[r][c] is not None for r, c in block):
                return None

        if shaded:
            start = next(iter(shaded))
            q = deque([start])
            seen = {start}
            while q:
                cell = q.popleft()
                for nb in neighbors4(cell, nrows, ncols):
                    if nb in shaded and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
            if seen != shaded:
                return None

        return repr(ans)

    def choose_branch_region(doms):
        # Human-like heuristic:
        # pick the region with smallest domain > 1,
        # tie-break by fewer type options, then larger adjacency degree.
        best = None
        best_key = None
        for rid in region_ids:
            m = len(doms[rid])
            if m <= 1:
                continue
            tcount = len({cand['type'] for cand in doms[rid]})
            key = (m, tcount, -len(radj[rid]))
            if best is None or key < best_key:
                best = rid
                best_key = key
        return best

    def order_candidates(rid, doms):
        # Prefer candidates whose type is rarer among neighbors' options and that add more forced connectivity.
        cands = doms[rid]
        neigh_types = defaultdict(int)
        for nb in radj[rid]:
            for cand in doms[nb]:
                neigh_types[cand['type']] += 1

        forced_other = set()
        for x in region_ids:
            if x == rid:
                continue
            inter, _, _ = region_forced_info(doms[x])
            forced_other |= inter

        def score(cand):
            touch = 0
            for cell in cand['cells']:
                for nb in neighbors4(cell, nrows, ncols):
                    if nb in forced_other:
                        touch += 1
            return (neigh_types[cand['type']], -touch)

        return sorted(cands, key=score)

    def search(doms):
        if not propagate(doms):
            return None
        if is_solved(doms):
            return build_answer(doms)

        rid = choose_branch_region(doms)
        if rid is None:
            return None

        for cand in order_candidates(rid, doms):
            nd = clone_domains(doms)
            nd[rid] = [cand]
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(clone_domains(domains))
    return result if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

