# Consecutive-dot Latin square solver.
# Generalized for any N x N grid with givens and explicit positive adjacency clues,
# where missing dots imply non-consecutive orthogonal neighbors.

ALL_MASK_CACHE = {}

def bit(v):
    return 1 << (v - 1)

def mask_all(n):
    if n not in ALL_MASK_CACHE:
        ALL_MASK_CACHE[n] = (1 << n) - 1
    return ALL_MASK_CACHE[n]

def popcount(x):
    return x.bit_count()

def iter_values(mask, n):
    while mask:
        b = mask & -mask
        yield b.bit_length()
        mask ^= b

def singleton_value(mask):
    return mask.bit_length() if mask and (mask & (mask - 1)) == 0 else None

def consecutive_mask(mask, n):
    # Values that can be consecutive to at least one value in mask
    res = 0
    m = mask
    while m:
        b = m & -m
        v = b.bit_length()
        if v > 1:
            res |= bit(v - 1)
        if v < n:
            res |= bit(v + 1)
        m ^= b
    return res

def nonconsecutive_mask(mask, n):
    return mask_all(n) & ~consecutive_mask(mask, n)

def build_neighbors(n, adjacent):
    dots = set()
    for a, b in adjacent:
        dots.add((a, b))
    nbrs = [[[] for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                mid = (float(r), c + 0.5)
                is_dot = mid in dots
                nbrs[r][c].append((r, c + 1, is_dot))
                nbrs[r][c + 1].append((r, c, is_dot))
            if r + 1 < n:
                mid = (r + 0.5, float(c))
                is_dot = mid in dots
                nbrs[r][c].append((r + 1, c, is_dot))
                nbrs[r + 1][c].append((r, c, is_dot))
    return nbrs

class Solver:
    def __init__(self, observation):
        self.grid = observation['data']
        self.n = len(self.grid)
        self.ALL = mask_all(self.n)
        self.neighbors = build_neighbors(self.n, observation['adjacent'])

        self.dom = [[self.ALL for _ in range(self.n)] for _ in range(self.n)]
        self.row_missing = [self.ALL for _ in range(self.n)]
        self.col_missing = [self.ALL for _ in range(self.n)]

        for r in range(self.n):
            used = 0
            for c in range(self.n):
                v = self.grid[r][c]
                if v is not None:
                    used |= bit(v)
            self.row_missing[r] = self.ALL & ~used

        for c in range(self.n):
            used = 0
            for r in range(self.n):
                v = self.grid[r][c]
                if v is not None:
                    used |= bit(v)
            self.col_missing[c] = self.ALL & ~used

        for r in range(self.n):
            for c in range(self.n):
                v = self.grid[r][c]
                if v is not None:
                    self.dom[r][c] = bit(v)
                else:
                    self.dom[r][c] = self.row_missing[r] & self.col_missing[c]

    def clone(self):
        other = Solver.__new__(Solver)
        other.grid = [row[:] for row in self.grid]
        other.n = self.n
        other.ALL = self.ALL
        other.neighbors = self.neighbors
        other.dom = [row[:] for row in self.dom]
        other.row_missing = self.row_missing[:]
        other.col_missing = self.col_missing[:]
        return other

    def assign(self, r, c, v, queue):
        m = bit(v)
        cur = self.dom[r][c]
        if cur == m:
            return True
        if not (cur & m):
            return False
        self.dom[r][c] = m
        self.grid[r][c] = v
        queue.append((r, c))
        return True

    def remove_mask(self, r, c, rem, queue):
        cur = self.dom[r][c]
        new = cur & ~rem
        if new == cur:
            return True
        if new == 0:
            return False
        self.dom[r][c] = new
        sv = singleton_value(new)
        if sv is not None and self.grid[r][c] != sv:
            self.grid[r][c] = sv
            queue.append((r, c))
        elif self.grid[r][c] is not None and new != bit(self.grid[r][c]):
            return False
        return True

    def restrict_mask(self, r, c, keep, queue):
        cur = self.dom[r][c]
        new = cur & keep
        if new == cur:
            return True
        if new == 0:
            return False
        self.dom[r][c] = new
        sv = singleton_value(new)
        if sv is not None and self.grid[r][c] != sv:
            self.grid[r][c] = sv
            queue.append((r, c))
        elif self.grid[r][c] is not None and new != bit(self.grid[r][c]):
            return False
        return True

    def propagate(self):
        queue = []
        processed_singletons = set()

        for r in range(self.n):
            for c in range(self.n):
                sv = singleton_value(self.dom[r][c])
                if sv is not None:
                    self.grid[r][c] = sv
                    queue.append((r, c))

        while True:
            while queue:
                r, c = queue.pop()
                m = self.dom[r][c]
                sv = singleton_value(m)
                if sv is None:
                    continue
                key = (r, c, sv)
                if key in processed_singletons:
                    continue
                processed_singletons.add(key)

                if not (self.row_missing[r] & bit(sv)) and self.grid[r][c] != sv:
                    return False
                if not (self.col_missing[c] & bit(sv)) and self.grid[r][c] != sv:
                    return False

                self.grid[r][c] = sv

                # Fix row/col bookkeeping only once logically
                if self.row_missing[r] & bit(sv):
                    self.row_missing[r] &= ~bit(sv)
                    for cc in range(self.n):
                        if cc != c:
                            if not self.remove_mask(r, cc, bit(sv), queue):
                                return False
                else:
                    for cc in range(self.n):
                        if cc != c and (self.dom[r][cc] & bit(sv)) and singleton_value(self.dom[r][cc]) == sv:
                            return False

                if self.col_missing[c] & bit(sv):
                    self.col_missing[c] &= ~bit(sv)
                    for rr in range(self.n):
                        if rr != r:
                            if not self.remove_mask(rr, c, bit(sv), queue):
                                return False
                else:
                    for rr in range(self.n):
                        if rr != r and (self.dom[rr][c] & bit(sv)) and singleton_value(self.dom[rr][c]) == sv:
                            return False

                # Adjacency propagation
                for nr, nc, is_dot in self.neighbors[r][c]:
                    if is_dot:
                        allowed = consecutive_mask(self.dom[r][c], self.n)
                    else:
                        allowed = nonconsecutive_mask(self.dom[r][c], self.n)
                    if not self.restrict_mask(nr, nc, allowed, queue):
                        return False

            changed = False

            # Recompute row/col missing from fixed cells and validate duplicates
            for r in range(self.n):
                used = 0
                for c in range(self.n):
                    sv = singleton_value(self.dom[r][c])
                    if sv is not None:
                        b = bit(sv)
                        if used & b:
                            return False
                        used |= b
                new_missing = self.ALL & ~used
                if new_missing != self.row_missing[r]:
                    self.row_missing[r] = new_missing
                    changed = True

            for c in range(self.n):
                used = 0
                for r in range(self.n):
                    sv = singleton_value(self.dom[r][c])
                    if sv is not None:
                        b = bit(sv)
                        if used & b:
                            return False
                        used |= b
                new_missing = self.ALL & ~used
                if new_missing != self.col_missing[c]:
                    self.col_missing[c] = new_missing
                    changed = True

            # Basic row/col domain filtering
            for r in range(self.n):
                allowed = self.row_missing[r]
                for c in range(self.n):
                    if singleton_value(self.dom[r][c]) is None:
                        if not self.restrict_mask(r, c, allowed, queue):
                            return False
            for c in range(self.n):
                allowed = self.col_missing[c]
                for r in range(self.n):
                    if singleton_value(self.dom[r][c]) is None:
                        if not self.restrict_mask(r, c, allowed, queue):
                            return False

            # Hidden singles in rows
            for r in range(self.n):
                for v in range(1, self.n + 1):
                    b = bit(v)
                    places = []
                    for c in range(self.n):
                        if self.dom[r][c] & b:
                            places.append(c)
                    if not places:
                        return False
                    if len(places) == 1:
                        if not self.assign(r, places[0], v, queue):
                            return False

            # Hidden singles in columns
            for c in range(self.n):
                for v in range(1, self.n + 1):
                    b = bit(v)
                    places = []
                    for r in range(self.n):
                        if self.dom[r][c] & b:
                            places.append(r)
                    if not places:
                        return False
                    if len(places) == 1:
                        if not self.assign(places[0], c, v, queue):
                            return False

            # Adjacency arc consistency for all edges
            for r in range(self.n):
                for c in range(self.n):
                    cur = self.dom[r][c]
                    supported = 0
                    for nr, nc, is_dot in self.neighbors[r][c]:
                        neigh = self.dom[nr][nc]
                        if is_dot:
                            supported |= consecutive_mask(neigh, self.n)
                        else:
                            supported |= nonconsecutive_mask(neigh, self.n)
                    new = cur & supported
                    if new != cur:
                        if not self.restrict_mask(r, c, new, queue):
                            return False
                        changed = True

            # Naked pairs in rows
            for r in range(self.n):
                pairs = {}
                for c in range(self.n):
                    m = self.dom[r][c]
                    if popcount(m) == 2:
                        pairs.setdefault(m, []).append(c)
                for m, cols in pairs.items():
                    if len(cols) == 2:
                        for c in range(self.n):
                            if c not in cols:
                                if not self.remove_mask(r, c, m, queue):
                                    return False

            # Naked pairs in columns
            for c in range(self.n):
                pairs = {}
                for r in range(self.n):
                    m = self.dom[r][c]
                    if popcount(m) == 2:
                        pairs.setdefault(m, []).append(r)
                for m, rows in pairs.items():
                    if len(rows) == 2:
                        for r in range(self.n):
                            if r not in rows:
                                if not self.remove_mask(r, c, m, queue):
                                    return False

            if queue:
                continue
            if not changed:
                break

        return True

    def solved(self):
        for r in range(self.n):
            for c in range(self.n):
                if singleton_value(self.dom[r][c]) is None:
                    return False
        return True

    def select_branch_cell(self):
        best = None
        best_score = None
        for r in range(self.n):
            for c in range(self.n):
                m = self.dom[r][c]
                pc = popcount(m)
                if pc <= 1:
                    continue
                degree = len(self.neighbors[r][c])
                score = (pc, -degree)
                if best_score is None or score < best_score:
                    best_score = score
                    best = (r, c)
        return best

    def ordered_values(self, r, c):
        vals = list(iter_values(self.dom[r][c], self.n))
        impacts = []
        for v in vals:
            score = 0
            for nr, nc, is_dot in self.neighbors[r][c]:
                nm = self.dom[nr][nc]
                if is_dot:
                    allowed = consecutive_mask(bit(v), self.n)
                else:
                    allowed = nonconsecutive_mask(bit(v), self.n)
                score += popcount(nm & allowed)
            impacts.append((score, v))
        impacts.sort()
        return [v for _, v in impacts]

    def search(self):
        if not self.propagate():
            return None
        if self.solved():
            return [[singleton_value(self.dom[r][c]) for c in range(self.n)] for r in range(self.n)]

        r, c = self.select_branch_cell()
        if r is None:
            return None

        for v in self.ordered_values(r, c):
            child = self.clone()
            q = []
            if child.assign(r, c, v, q):
                result = child.search()
                if result is not None:
                    return result
        return None

def solve(observation):
    solver = Solver(observation)
    ans = solver.search()
    if ans is None:
        return "No Solution"
    return str(ans)

