# General nonogram solver with strong line-domain propagation and bounded search.
# The logic mirrors human deduction:
# 1) enumerate all legal patterns for each row/column from clues
# 2) repeatedly filter patterns against current cell knowledge
# 3) infer forced cells from consensus across remaining patterns
# 4) when stuck, branch on the most constrained undecided cell / line

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    h = len(row_clues)
    w = len(col_clues)

    UNKNOWN = -1
    WHITE = 0
    BLACK = 1

    def generate_patterns(length, clues):
        if not clues:
            return [0]
        k = len(clues)
        suffix_need = [0] * (k + 1)
        for i in range(k - 1, -1, -1):
            suffix_need[i] = suffix_need[i + 1] + clues[i] + (1 if i < k - 1 else 0)

        out = []

        def rec(i, pos, mask):
            if i == k:
                out.append(mask)
                return
            run = clues[i]
            max_start = length - suffix_need[i]
            for start in range(pos, max_start + 1):
                m = mask
                for p in range(start, start + run):
                    m |= 1 << p
                next_pos = start + run + 1
                rec(i + 1, next_pos, m)

        rec(0, 0, 0)
        return out

    row_patterns = [generate_patterns(w, clues) for clues in row_clues]
    col_patterns = [generate_patterns(h, clues) for clues in col_clues]

    row_all_ones = [(1 << w) - 1 for _ in range(h)]
    col_all_ones = [(1 << h) - 1 for _ in range(w)]

    def line_forced(patterns, length):
        if not patterns:
            return None, None
        common_one = patterns[0]
        common_zero = (~patterns[0]) & ((1 << length) - 1)
        for p in patterns[1:]:
            common_one &= p
            common_zero &= (~p) & ((1 << length) - 1)
        return common_one, common_zero

    def propagate(row_domains, col_domains, grid):
        changed = True
        while changed:
            changed = False

            # Filter row domains and push row consensus to grid.
            for r in range(h):
                old = row_domains[r]
                new = []
                row_vals = grid[r]
                for p in old:
                    ok = True
                    x = p
                    for c in range(w):
                        bit = (x >> c) & 1
                        gv = row_vals[c]
                        if gv != UNKNOWN and gv != bit:
                            ok = False
                            break
                    if ok:
                        new.append(p)
                if not new:
                    return None
                if len(new) != len(old):
                    row_domains[r] = new
                    changed = True

                common_one, common_zero = line_forced(new, w)
                for c in range(w):
                    if (common_one >> c) & 1:
                        if grid[r][c] == WHITE:
                            return None
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = BLACK
                            changed = True
                    elif (common_zero >> c) & 1:
                        if grid[r][c] == BLACK:
                            return None
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = WHITE
                            changed = True

            # Filter column domains and push column consensus to grid.
            for c in range(w):
                old = col_domains[c]
                new = []
                for p in old:
                    ok = True
                    x = p
                    for r in range(h):
                        bit = (x >> r) & 1
                        gv = grid[r][c]
                        if gv != UNKNOWN and gv != bit:
                            ok = False
                            break
                    if ok:
                        new.append(p)
                if not new:
                    return None
                if len(new) != len(old):
                    col_domains[c] = new
                    changed = True

                common_one, common_zero = line_forced(new, h)
                for r in range(h):
                    if (common_one >> r) & 1:
                        if grid[r][c] == WHITE:
                            return None
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = BLACK
                            changed = True
                    elif (common_zero >> r) & 1:
                        if grid[r][c] == BLACK:
                            return None
                        if grid[r][c] == UNKNOWN:
                            grid[r][c] = WHITE
                            changed = True

        # Final consistency check.
        for r in range(h):
            if not row_domains[r]:
                return None
        for c in range(w):
            if not col_domains[c]:
                return None
        return row_domains, col_domains, grid

    def solved(grid):
        for r in range(h):
            for c in range(w):
                if grid[r][c] == UNKNOWN:
                    return False
        return True

    def clone_domains(domains):
        return [d[:] for d in domains]

    def clone_grid(grid):
        return [row[:] for row in grid]

    def choose_branch(row_domains, col_domains, grid):
        # Prefer smallest domain line > 1, then most constrained cell by support counts.
        best = None

        for r in range(h):
            ln = len(row_domains[r])
            if 1 < ln and (best is None or ln < best[0]):
                best = (ln, 'row', r)
        for c in range(w):
            ln = len(col_domains[c])
            if 1 < ln and (best is None or ln < best[0]):
                best = (ln, 'col', c)

        # Also inspect cells for balanced uncertainty to branch more effectively.
        cell_best = None
        for r in range(h):
            pats_r = row_domains[r]
            total_r = len(pats_r)
            if total_r == 0:
                return ('fail',)
            for c in range(w):
                if grid[r][c] != UNKNOWN:
                    continue
                black_count = 0
                bit = 1 << c
                for p in pats_r:
                    if p & bit:
                        black_count += 1
                if black_count == 0 or black_count == total_r:
                    continue
                score = abs(total_r - 2 * black_count)
                tie = total_r
                if cell_best is None or (score, tie) < (cell_best[0], cell_best[1]):
                    cell_best = (score, tie, r, c, black_count, total_r - black_count)

        if cell_best is not None:
            _, _, r, c, bc, wc = cell_best
            first = BLACK if bc <= wc else WHITE
            second = WHITE if first == BLACK else BLACK
            return ('cell', r, c, first, second)

        if best is not None:
            _, kind, idx = best
            return (kind, idx)

        return None

    def search(row_domains, col_domains, grid):
        state = propagate(row_domains, col_domains, grid)
        if state is None:
            return None
        row_domains, col_domains, grid = state

        if solved(grid):
            return grid

        choice = choose_branch(row_domains, col_domains, grid)
        if choice is None:
            return grid
        if choice[0] == 'fail':
            return None

        if choice[0] == 'cell':
            _, r, c, v1, v2 = choice
            for v in (v1, v2):
                rd = clone_domains(row_domains)
                cd = clone_domains(col_domains)
                g = clone_grid(grid)
                g[r][c] = v
                ans = search(rd, cd, g)
                if ans is not None:
                    return ans
            return None

        if choice[0] == 'row':
            _, r = choice
            # Branch using row patterns, trying patterns that maximize immediate information.
            patterns = row_domains[r]
            ordering = []
            for p in patterns:
                match_known = 0
                for c in range(w):
                    bit = (p >> c) & 1
                    if grid[r][c] != UNKNOWN and grid[r][c] == bit:
                        match_known += 1
                ordering.append((-match_known, p))
            ordering.sort()
            for _, p in ordering:
                rd = clone_domains(row_domains)
                cd = clone_domains(col_domains)
                g = clone_grid(grid)
                ok = True
                for c in range(w):
                    bit = (p >> c) & 1
                    if g[r][c] != UNKNOWN and g[r][c] != bit:
                        ok = False
                        break
                    g[r][c] = bit
                if not ok:
                    continue
                rd[r] = [p]
                ans = search(rd, cd, g)
                if ans is not None:
                    return ans
            return None

        if choice[0] == 'col':
            _, c = choice
            patterns = col_domains[c]
            ordering = []
            for p in patterns:
                match_known = 0
                for r in range(h):
                    bit = (p >> r) & 1
                    if grid[r][c] != UNKNOWN and grid[r][c] == bit:
                        match_known += 1
                ordering.append((-match_known, p))
            ordering.sort()
            for _, p in ordering:
                rd = clone_domains(row_domains)
                cd = clone_domains(col_domains)
                g = clone_grid(grid)
                ok = True
                for r in range(h):
                    bit = (p >> r) & 1
                    if g[r][c] != UNKNOWN and g[r][c] != bit:
                        ok = False
                        break
                    g[r][c] = bit
                if not ok:
                    continue
                cd[c] = [p]
                ans = search(rd, cd, g)
                if ans is not None:
                    return ans
            return None

        return None

    grid = [[UNKNOWN] * w for _ in range(h)]
    result = search([d[:] for d in row_patterns], [d[:] for d in col_patterns], grid)
    if result is None:
        return "No Solution"

    answer = [['B' if result[r][c] == BLACK else None for c in range(w)] for r in range(h)]
    return str(answer)


