# General solver for the weighted black-cell puzzle.
# Model:
# - Rows have implicit weights 1..R
# - Columns have implicit weights 1..C
# - If cell (r,c) is black:
#     row r contributes (c+1) to row_sum[r]
#     col c contributes (r+1) to col_sum[c]
#
# Human-like deduction structure implemented:
# 1) Enumerate all feasible patterns for each row from its target sum.
# 2) Enumerate all feasible patterns for each column from its target sum.
# 3) Cross-filter row/column domains by cell support.
# 4) Propagate forced cells from singleton domains.
# 5) Use subset-sum bounds on remaining unresolved rows/columns.
# 6) Branch only on the most constrained row/column domain.

from itertools import combinations

def bit_positions(mask, n):
    i = 0
    while i < n:
        if (mask >> i) & 1:
            yield i
        i += 1

def all_subset_masks_by_weighted_sum(weights, target):
    n = len(weights)
    out = []
    def rec(i, cur_sum, mask):
        if cur_sum > target:
            return
        if i == n:
            if cur_sum == target:
                out.append(mask)
            return
        rec(i + 1, cur_sum, mask)
        rec(i + 1, cur_sum + weights[i], mask | (1 << i))
    rec(0, 0, 0)
    return out

def possible_cell_values_from_masks(masks, width):
    any1 = 0
    any0 = (1 << width) - 1
    for m in masks:
        any1 |= m
        any0 &= m
    forced1 = any0
    forced0 = ((1 << width) - 1) ^ any1
    return forced1, forced0

def filter_row_masks_by_columns(row_masks, row_idx, col_domains):
    kept = []
    for m in row_masks:
        ok = True
        for c, cmasks in enumerate(col_domains):
            bit = (m >> c) & 1
            supported = False
            for col_mask in cmasks:
                if ((col_mask >> row_idx) & 1) == bit:
                    supported = True
                    break
            if not supported:
                ok = False
                break
        if ok:
            kept.append(m)
    return kept

def filter_col_masks_by_rows(col_masks, col_idx, row_domains):
    kept = []
    for m in col_masks:
        ok = True
        for r, rmasks in enumerate(row_domains):
            bit = (m >> r) & 1
            supported = False
            for row_mask in rmasks:
                if ((row_mask >> col_idx) & 1) == bit:
                    supported = True
                    break
            if not supported:
                ok = False
                break
        if ok:
            kept.append(m)
    return kept

def min_max_weight_sums_from_domain_row(masks, ncols):
    mins = [None] * ncols
    maxs = [None] * ncols
    for c in range(ncols):
        seen0 = False
        seen1 = False
        for m in masks:
            if (m >> c) & 1:
                seen1 = True
            else:
                seen0 = True
            if seen0 and seen1:
                break
        mins[c] = 0 if seen0 else 1
        maxs[c] = 1 if seen1 else 0
    return mins, maxs

def min_max_weight_sums_from_domain_col(masks, nrows):
    mins = [None] * nrows
    maxs = [None] * nrows
    for r in range(nrows):
        seen0 = False
        seen1 = False
        for m in masks:
            if (m >> r) & 1:
                seen1 = True
            else:
                seen0 = True
            if seen0 and seen1:
                break
        mins[r] = 0 if seen0 else 1
        maxs[r] = 1 if seen1 else 0
    return mins, maxs

def aggregate_column_bounds_from_rows(row_domains, nrows, ncols):
    min_sum = [0] * ncols
    max_sum = [0] * ncols
    for r in range(nrows):
        mins, maxs = min_max_weight_sums_from_domain_row(row_domains[r], ncols)
        rw = r + 1
        for c in range(ncols):
            min_sum[c] += rw * mins[c]
            max_sum[c] += rw * maxs[c]
    return min_sum, max_sum

def aggregate_row_bounds_from_cols(col_domains, nrows, ncols):
    min_sum = [0] * nrows
    max_sum = [0] * nrows
    for c in range(ncols):
        mins, maxs = min_max_weight_sums_from_domain_col(col_domains[c], nrows)
        cw = c + 1
        for r in range(nrows):
            min_sum[r] += cw * mins[r]
            max_sum[r] += cw * maxs[r]
    return min_sum, max_sum

def propagate(row_domains, col_domains, row_targets, col_targets):
    nrows = len(row_domains)
    ncols = len(col_domains)

    changed = True
    while changed:
        changed = False

        # Local row-to-column support filtering
        for r in range(nrows):
            new_masks = filter_row_masks_by_columns(row_domains[r], r, col_domains)
            if not new_masks:
                return None
            if len(new_masks) != len(row_domains[r]):
                row_domains[r] = new_masks
                changed = True

        # Local column-to-row support filtering
        for c in range(ncols):
            new_masks = filter_col_masks_by_rows(col_domains[c], c, row_domains)
            if not new_masks:
                return None
            if len(new_masks) != len(col_domains[c]):
                col_domains[c] = new_masks
                changed = True

        # Global weighted bounds from row domains onto columns
        cmin, cmax = aggregate_column_bounds_from_rows(row_domains, nrows, ncols)
        for c in range(ncols):
            if not (cmin[c] <= col_targets[c] <= cmax[c]):
                return None

        # Global weighted bounds from column domains onto rows
        rmin, rmax = aggregate_row_bounds_from_cols(col_domains, nrows, ncols)
        for r in range(nrows):
            if not (rmin[r] <= row_targets[r] <= rmax[r]):
                return None

        # Force by singleton row domains onto columns
        for r in range(nrows):
            if len(row_domains[r]) == 1:
                m = row_domains[r][0]
                for c in range(ncols):
                    bit = (m >> c) & 1
                    new_col = [cm for cm in col_domains[c] if ((cm >> r) & 1) == bit]
                    if not new_col:
                        return None
                    if len(new_col) != len(col_domains[c]):
                        col_domains[c] = new_col
                        changed = True

        # Force by singleton column domains onto rows
        for c in range(ncols):
            if len(col_domains[c]) == 1:
                m = col_domains[c][0]
                for r in range(nrows):
                    bit = (m >> r) & 1
                    new_row = [rm for rm in row_domains[r] if ((rm >> c) & 1) == bit]
                    if not new_row:
                        return None
                    if len(new_row) != len(row_domains[r]):
                        row_domains[r] = new_row
                        changed = True

    return row_domains, col_domains

def solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

def choose_branch(row_domains, col_domains):
    best = None

    for r, d in enumerate(row_domains):
        if 1 < len(d):
            key = (len(d), 0, r)  # prefer smaller domains, rows before cols
            if best is None or key < best[0]:
                best = (key, ('row', r))

    for c, d in enumerate(col_domains):
        if 1 < len(d):
            key = (len(d), 1, c)
            if best is None or key < best[0]:
                best = (key, ('col', c))

    return None if best is None else best[1]

def search(row_domains, col_domains, row_targets, col_targets):
    state = propagate(
        [d[:] for d in row_domains],
        [d[:] for d in col_domains],
        row_targets,
        col_targets,
    )
    if state is None:
        return None
    row_domains, col_domains = state

    if solved(row_domains, col_domains):
        return row_domains, col_domains

    kind, idx = choose_branch(row_domains, col_domains)
    if kind == 'row':
        domain = row_domains[idx]
        for m in domain:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] for d in col_domains]
            new_rows[idx] = [m]
            res = search(new_rows, new_cols, row_targets, col_targets)
            if res is not None:
                return res
    else:
        domain = col_domains[idx]
        for m in domain:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] for d in col_domains]
            new_cols[idx] = [m]
            res = search(new_rows, new_cols, row_targets, col_targets)
            if res is not None:
                return res

    return None

def format_answer_from_row_masks(row_masks, nrows, ncols):
    grid = []
    for r in range(nrows):
        m = row_masks[r][0]
        row = []
        for c in range(ncols):
            row.append('B' if ((m >> c) & 1) else None)
        grid.append(row)
    return str(grid)

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    nrows = len(row_targets)
    ncols = len(col_targets)

    col_weights = [c + 1 for c in range(ncols)]
    row_weights = [r + 1 for r in range(nrows)]

    row_domains = [all_subset_masks_by_weighted_sum(col_weights, t) for t in row_targets]
    col_domains = [all_subset_masks_by_weighted_sum(row_weights, t) for t in col_targets]

    if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
        return "No Solution"

    result = search(row_domains, col_domains, row_targets, col_targets)
    if result is None:
        return "No Solution"

    final_rows, final_cols = result
    return format_answer_from_row_masks(final_rows, nrows, ncols)

if __name__ == "__main__":
    print(solve(OBSERVATION))

