# Generalized Sudoku solver using human-like constraint propagation plus tightly pruned search.
# Supports N x N grids where N = box_rows * box_cols, e.g. 9x9, 12x12, 16x16.

def solve(observation):
    data = observation['data']
    unit = observation['unit']
    if 'x' in unit:
        br, bc = map(int, unit.split('x'))
    else:
        br = bc = int(unit)
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def lowbit_index(x):
        return (x & -x).bit_length() - 1

    def mask_to_values(mask):
        vals = []
        while mask:
            lb = mask & -mask
            vals.append(lb.bit_length())
            mask ^= lb
        return vals

    rows = list(range(n))
    cols = list(range(n))

    boxes = []
    cell_box = [[0] * n for _ in range(n)]
    b = 0
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            cells = []
            for r in range(r0, r0 + br):
                for c in range(c0, c0 + bc):
                    cells.append((r, c))
                    cell_box[r][c] = b
            boxes.append(cells)
            b += 1

    row_cells = [[(r, c) for c in cols] for r in rows]
    col_cells = [[(r, c) for r in rows] for c in cols]
    box_cells = boxes

    units_of_cell = [[None] * n for _ in range(n)]
    peers = [[None] * n for _ in range(n)]
    for r in rows:
        for c in cols:
            bidx = cell_box[r][c]
            units_of_cell[r][c] = (('row', r), ('col', c), ('box', bidx))
            s = set(row_cells[r]) | set(col_cells[c]) | set(box_cells[bidx])
            s.remove((r, c))
            peers[r][c] = tuple(s)

    board = [[0] * n for _ in range(n)]
    cand = [[full_mask] * n for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    box_used = [0] * n

    for r in rows:
        for c in cols:
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            m = bit(v)
            bidx = cell_box[r][c]
            if (row_used[r] & m) or (col_used[c] & m) or (box_used[bidx] & m):
                return "No Solution"
            board[r][c] = v
            row_used[r] |= m
            col_used[c] |= m
            box_used[bidx] |= m

    for r in rows:
        for c in cols:
            if board[r][c] == 0:
                bidx = cell_box[r][c]
                cand[r][c] = full_mask & ~(row_used[r] | col_used[c] | box_used[bidx])
                if cand[r][c] == 0:
                    return "No Solution"
            else:
                cand[r][c] = bit(board[r][c])

    trail = []

    def place(r, c, v):
        if board[r][c] == v:
            return True
        if board[r][c] != 0:
            return False

        m = bit(v)
        if not (cand[r][c] & m):
            return False

        trail.append(('cell', r, c, board[r][c], cand[r][c]))
        board[r][c] = v
        cand[r][c] = m

        bidx = cell_box[r][c]
        old_ru, old_cu, old_bu = row_used[r], col_used[c], box_used[bidx]
        if (old_ru & m) or (old_cu & m) or (old_bu & m):
            return False
        trail.append(('used', r, c, bidx, old_ru, old_cu, old_bu))
        row_used[r] |= m
        col_used[c] |= m
        box_used[bidx] |= m

        for rr, cc in peers[r][c]:
            if board[rr][cc] == 0 and (cand[rr][cc] & m):
                old = cand[rr][cc]
                new = old & ~m
                if new == 0:
                    return False
                if new != old:
                    trail.append(('cand', rr, cc, old))
                    cand[rr][cc] = new
        return True

    def undo(mark):
        while len(trail) > mark:
            item = trail.pop()
            tag = item[0]
            if tag == 'cand':
                _, r, c, old = item
                cand[r][c] = old
            elif tag == 'used':
                _, r, c, bidx, ru, cu, bu = item
                row_used[r] = ru
                col_used[c] = cu
                box_used[bidx] = bu
            else:
                _, r, c, old_board, old_cand = item
                board[r][c] = old_board
                cand[r][c] = old_cand

    def hidden_singles_in_unit(cells, used_mask):
        need = full_mask & ~used_mask
        while need:
            lb = need & -need
            need ^= lb
            found = None
            count = 0
            for r, c in cells:
                if board[r][c] == 0 and (cand[r][c] & lb):
                    count += 1
                    found = (r, c)
                    if count > 1:
                        break
            if count == 0:
                return False
            if count == 1:
                if not place(found[0], found[1], lb.bit_length()):
                    return False
        return True

    def naked_subsets_unit(cells):
        unsolved = [(r, c) for r, c in cells if board[r][c] == 0]
        groups = {}
        for r, c in unsolved:
            m = cand[r][c]
            k = popcount(m)
            if 2 <= k <= 4:
                groups.setdefault(m, []).append((r, c))
        for m, pos in groups.items():
            k = popcount(m)
            if len(pos) == k:
                for r, c in unsolved:
                    if (r, c) in pos:
                        continue
                    old = cand[r][c]
                    new = old & ~m
                    if new != old:
                        if new == 0:
                            return False
                        trail.append(('cand', r, c, old))
                        cand[r][c] = new
        return True

    def pointing_claiming():
        for bidx, cells in enumerate(box_cells):
            miss = full_mask & ~box_used[bidx]
            temp = miss
            while temp:
                lb = temp & -temp
                temp ^= lb
                pos = [(r, c) for r, c in cells if board[r][c] == 0 and (cand[r][c] & lb)]
                if not pos:
                    return False
                rows_set = {r for r, _ in pos}
                cols_set = {c for _, c in pos}
                if len(rows_set) == 1:
                    r = next(iter(rows_set))
                    for rr, cc in row_cells[r]:
                        if cell_box[rr][cc] != bidx and board[rr][cc] == 0 and (cand[rr][cc] & lb):
                            old = cand[rr][cc]
                            new = old & ~lb
                            if new == 0:
                                return False
                            trail.append(('cand', rr, cc, old))
                            cand[rr][cc] = new
                if len(cols_set) == 1:
                    c = next(iter(cols_set))
                    for rr, cc in col_cells[c]:
                        if cell_box[rr][cc] != bidx and board[rr][cc] == 0 and (cand[rr][cc] & lb):
                            old = cand[rr][cc]
                            new = old & ~lb
                            if new == 0:
                                return False
                            trail.append(('cand', rr, cc, old))
                            cand[rr][cc] = new
        for r in rows:
            miss = full_mask & ~row_used[r]
            temp = miss
            while temp:
                lb = temp & -temp
                temp ^= lb
                pos = [(rr, cc) for rr, cc in row_cells[r] if board[rr][cc] == 0 and (cand[rr][cc] & lb)]
                if not pos:
                    return False
                box_set = {cell_box[rr][cc] for rr, cc in pos}
                if len(box_set) == 1:
                    bidx = next(iter(box_set))
                    for rr, cc in box_cells[bidx]:
                        if rr != r and board[rr][cc] == 0 and (cand[rr][cc] & lb):
                            old = cand[rr][cc]
                            new = old & ~lb
                            if new == 0:
                                return False
                            trail.append(('cand', rr, cc, old))
                            cand[rr][cc] = new
        for c in cols:
            miss = full_mask & ~col_used[c]
            temp = miss
            while temp:
                lb = temp & -temp
                temp ^= lb
                pos = [(rr, cc) for rr, cc in col_cells[c] if board[rr][cc] == 0 and (cand[rr][cc] & lb)]
                if not pos:
                    return False
                box_set = {cell_box[rr][cc] for rr, cc in pos}
                if len(box_set) == 1:
                    bidx = next(iter(box_set))
                    for rr, cc in box_cells[bidx]:
                        if cc != c and board[rr][cc] == 0 and (cand[rr][cc] & lb):
                            old = cand[rr][cc]
                            new = old & ~lb
                            if new == 0:
                                return False
                            trail.append(('cand', rr, cc, old))
                            cand[rr][cc] = new
        return True

    def propagate():
        while True:
            changed = False
            before = len(trail)

            for r in rows:
                for c in cols:
                    if board[r][c] == 0:
                        m = cand[r][c]
                        if m == 0:
                            return False
                        if (m & (m - 1)) == 0:
                            if not place(r, c, m.bit_length()):
                                return False

            for r in rows:
                if not hidden_singles_in_unit(row_cells[r], row_used[r]):
                    return False
            for c in cols:
                if not hidden_singles_in_unit(col_cells[c], col_used[c]):
                    return False
            for bidx in range(n):
                if not hidden_singles_in_unit(box_cells[bidx], box_used[bidx]):
                    return False

            for r in rows:
                if not naked_subsets_unit(row_cells[r]):
                    return False
            for c in cols:
                if not naked_subsets_unit(col_cells[c]):
                    return False
            for bidx in range(n):
                if not naked_subsets_unit(box_cells[bidx]):
                    return False

            if not pointing_claiming():
                return False

            for r in rows:
                for c in cols:
                    if board[r][c] == 0 and cand[r][c] == 0:
                        return False

            if len(trail) != before:
                changed = True

            if not changed:
                break
        return True

    def solved():
        for r in rows:
            for c in cols:
                if board[r][c] == 0:
                    return False
        return True

    def select_branch_cell():
        best = None
        best_len = n + 1
        best_score = -1
        for r in rows:
            for c in cols:
                if board[r][c] == 0:
                    k = popcount(cand[r][c])
                    if k < best_len:
                        peer_pressure = 0
                        for rr, cc in peers[r][c]:
                            if board[rr][cc] == 0:
                                peer_pressure += 1
                        best = (r, c)
                        best_len = k
                        best_score = peer_pressure
                    elif k == best_len:
                        peer_pressure = 0
                        for rr, cc in peers[r][c]:
                            if board[rr][cc] == 0:
                                peer_pressure += 1
                        if peer_pressure > best_score:
                            best = (r, c)
                            best_score = peer_pressure
        return best

    def ordered_values(r, c):
        vals = mask_to_values(cand[r][c])
        if len(vals) <= 1:
            return vals
        impact = []
        for v in vals:
            m = bit(v)
            score = 0
            for rr, cc in peers[r][c]:
                if board[rr][cc] == 0 and (cand[rr][cc] & m):
                    score += 1
            impact.append((score, v))
        impact.sort(reverse=True)
        return [v for _, v in impact]

    def search():
        mark = len(trail)
        if not propagate():
            undo(mark)
            return False
        if solved():
            return True

        cell = select_branch_cell()
        if cell is None:
            undo(mark)
            return False
        r, c = cell

        for v in ordered_values(r, c):
            branch_mark = len(trail)
            if place(r, c, v) and search():
                return True
            undo(branch_mark)

        undo(mark)
        return False

    if not search():
        return "No Solution"
    return str(board)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 1, 1, 1, 1, 2], [0, 3, 4, 1, 2, 2], [0, 3, 4, 5, 5, 2], [0, 3, 6, 5, 5, 2], [3, 3, 6, 6, 7, 2], [3, 7, 7, 7, 7, 2]]}

# General solver for:
# - each region has exactly 2 shaded cells
# - shaded cells form dominoes (every shaded cell has exactly one orthogonally adjacent shaded cell)
# - different dominoes do not touch orthogonally
# Dominoes may cross region borders.
#
# The solver models candidate domino placements, then performs strong propagation on:
# - per-cell exact cover by at most one domino
# - per-region exact count of covered cells = 2
# - orthogonal non-touch between distinct dominoes
#
# Search is on domino candidates, with aggressive deductions before branching.

from collections import defaultdict, deque
import ast


def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n else 0

    cells = [(r, c) for r in range(n) for c in range(m)]
    cell_id = {cell: i for i, cell in enumerate(cells)}
    id_cell = cells[:]

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Orthogonal neighbors
    nbrs = {}
    for r in range(n):
        for c in range(m):
            arr = []
            if r > 0:
                arr.append((r - 1, c))
            if r + 1 < n:
                arr.append((r + 1, c))
            if c > 0:
                arr.append((r, c - 1))
            if c + 1 < m:
                arr.append((r, c + 1))
            nbrs[(r, c)] = arr

    # Enumerate all possible dominoes
    dominoes = []
    domino_index = {}
    for r in range(n):
        for c in range(m):
            if c + 1 < m:
                a, b = (r, c), (r, c + 1)
                idx = len(dominoes)
                domino_index[tuple(sorted((a, b)))] = idx
                dominoes.append((a, b))
            if r + 1 < n:
                a, b = (r, c), (r + 1, c)
                idx = len(dominoes)
                domino_index[tuple(sorted((a, b)))] = idx
                dominoes.append((a, b))

    D = len(dominoes)

    # For each cell, candidate dominoes using it
    cell_to_dominoes = [[] for _ in range(n * m)]
    for d, (a, b) in enumerate(dominoes):
        cell_to_dominoes[cell_id[a]].append(d)
        cell_to_dominoes[cell_id[b]].append(d)

    # Conflict graph:
    # Two dominoes conflict if:
    # - they share a cell
    # - any cell of one is orthogonally adjacent to any cell of the other, unless that adjacency is the shared internal edge of the same domino
    conflicts = [set() for _ in range(D)]
    dom_cells = []
    for a, b in dominoes:
        dom_cells.append({a, b})

    for i in range(D):
        a1, b1 = dominoes[i]
        s1 = dom_cells[i]
        for j in range(i + 1, D):
            a2, b2 = dominoes[j]
            s2 = dom_cells[j]
            bad = False
            if s1 & s2:
                bad = True
            else:
                for x in s1:
                    for y in s2:
                        if y in nbrs[x]:
                            bad = True
                            break
                    if bad:
                        break
            if bad:
                conflicts[i].add(j)
                conflicts[j].add(i)

    # For each region, candidate dominoes touching it
    region_to_dominoes = {rid: set() for rid in region_ids}
    for d, (a, b) in enumerate(dominoes):
        ra = grid[a[0]][a[1]]
        rb = grid[b[0]][b[1]]
        region_to_dominoes[ra].add(d)
        region_to_dominoes[rb].add(d)

    # For each region and candidate domino, contribution count (0/1/2)
    region_dom_contrib = {rid: {} for rid in region_ids}
    for rid in region_ids:
        for d, (a, b) in enumerate(dominoes):
            cnt = (1 if grid[a[0]][a[1]] == rid else 0) + (1 if grid[b[0]][b[1]] == rid else 0)
            if cnt:
                region_dom_contrib[rid][d] = cnt

    # State:
    # status[d] = -1 forbidden, 0 undecided, 1 chosen
    init_status = [0] * D
    init_region_count = {rid: 0 for rid in region_ids}
    init_cell_covered = [False] * (n * m)

    def region_bounds(status, rid):
        cur = 0
        possible_extra = 0
        contrib = region_dom_contrib[rid]
        for d, v in contrib.items():
            st = status[d]
            if st == 1:
                cur += v
            elif st == 0:
                possible_extra += v
        return cur, cur + possible_extra

    def choose_domino(d, status, region_count, cell_covered, queue):
        if status[d] == 1:
            return True
        if status[d] == -1:
            return False
        a, b = dominoes[d]
        ia, ib = cell_id[a], cell_id[b]
        if cell_covered[ia] or cell_covered[ib]:
            return False

        status[d] = 1
        cell_covered[ia] = True
        cell_covered[ib] = True

        ra = grid[a[0]][a[1]]
        rb = grid[b[0]][b[1]]
        region_count[ra] += 1
        region_count[rb] += 1

        if region_count[ra] > 2 or region_count[rb] > 2:
            return False

        # All other dominoes using these cells must be forbidden
        for dd in cell_to_dominoes[ia]:
            if dd != d:
                queue.append(('forbid', dd))
        for dd in cell_to_dominoes[ib]:
            if dd != d:
                queue.append(('forbid', dd))

        # Conflicting dominoes forbidden
        for dd in conflicts[d]:
            queue.append(('forbid', dd))

        # Regions reaching quota forbid further contributors
        for rid in {ra, rb}:
            if region_count[rid] == 2:
                for dd in region_to_dominoes[rid]:
                    if status[dd] == 0 and dd != d:
                        # Any undecided domino contributing to this region must be forbidden
                        if dd in region_dom_contrib[rid]:
                            queue.append(('forbid', dd))

        return True

    def forbid_domino(d, status, region_count, cell_covered, queue):
        if status[d] == -1:
            return True
        if status[d] == 1:
            return False
        status[d] = -1
        return True

    def cell_support(status, cid):
        return [d for d in cell_to_dominoes[cid] if status[d] != -1]

    def propagate(status, region_count, cell_covered):
        queue = deque()

        # Initial direct region overs/forced exact-2-domino-in-region cases
        changed = True
        while changed:
            changed = False

            # Basic region feasibility
            for rid in region_ids:
                low, high = region_bounds(status, rid)
                if low > 2 or high < 2:
                    return False
                # If exactly enough possible contribution remains, all contributors are forced
                need = 2 - low
                if need == 0:
                    for d, v in region_dom_contrib[rid].items():
                        if v > 0 and status[d] == 0:
                            queue.append(('forbid', d))
                else:
                    possible = [(d, v) for d, v in region_dom_contrib[rid].items() if status[d] == 0]
                    total_possible = sum(v for _, v in possible)
                    if total_possible == need:
                        for d, _ in possible:
                            queue.append(('choose', d))

            # Cell feasibility:
            # A covered cell is fine.
            # An uncovered cell can remain unshaded, but if a region still needs cells and only certain cells can supply them,
            # region-level logic will force dominoes. Here we only detect impossible already-covered contradictions by choice handling.
            while queue:
                op, d = queue.popleft()
                ok = choose_domino(d, status, region_count, cell_covered, queue) if op == 'choose' else forbid_domino(d, status, region_count, cell_covered, queue)
                if not ok:
                    return False
                changed = True

            # Additional region subset deductions by exact small combinatorics
            for rid in region_ids:
                low, high = region_bounds(status, rid)
                if low > 2 or high < 2:
                    return False
                need = 2 - low
                undec = [(d, region_dom_contrib[rid][d]) for d in region_dom_contrib[rid] if status[d] == 0]
                if need < 0:
                    return False
                if need == 0:
                    for d, _ in undec:
                        queue.append(('forbid', d))
                    continue
                if not undec:
                    if need != 0:
                        return False
                    continue

                # Compute if a domino is mandatory/impossible for satisfying exact region total.
                # Human-like "all ways to make remaining count".
                possible_sums = {0}
                for _, v in undec:
                    newset = set(possible_sums)
                    for s in possible_sums:
                        if s + v <= need:
                            newset.add(s + v)
                    possible_sums = newset
                if need not in possible_sums:
                    return False

                for d, v in undec:
                    # test exclude d
                    sums = {0}
                    for dd, vv in undec:
                        if dd == d:
                            continue
                        newset = set(sums)
                        for s in sums:
                            if s + vv <= need:
                                newset.add(s + vv)
                        sums = newset
                    if need not in sums:
                        queue.append(('choose', d))
                        changed = True
                        continue

                    # test include d
                    if v <= need:
                        sums = {v}
                        for dd, vv in undec:
                            if dd == d:
                                continue
                            newset = set(sums)
                            for s in sums:
                                if s + vv <= need:
                                    newset.add(s + vv)
                            sums = newset
                        if need not in sums:
                            queue.append(('forbid', d))
                            changed = True
                    else:
                        queue.append(('forbid', d))
                        changed = True

            while queue:
                op, d = queue.popleft()
                ok = choose_domino(d, status, region_count, cell_covered, queue) if op == 'choose' else forbid_domino(d, status, region_count, cell_covered, queue)
                if not ok:
                    return False

        # Final consistency
        for rid in region_ids:
            low, high = region_bounds(status, rid)
            if low > 2 or high < 2:
                return False

        return True

    def solved(status, region_count):
        for rid in region_ids:
            if region_count[rid] != 2:
                return False
        return True

    def score_domino(d, status, region_count):
        a, b = dominoes[d]
        ra = grid[a[0]][a[1]]
        rb = grid[b[0]][b[1]]
        s = 0
        s += len(conflicts[d]) * 3
        s += (2 - region_count[ra]) * 5
        s += (2 - region_count[rb]) * 5
        if ra == rb:
            s += 4
        return s

    def select_branch(status, region_count):
        # Prefer the most constrained region, then best contributing domino in it.
        best_region = None
        best_key = None
        for rid in region_ids:
            low, high = region_bounds(status, rid)
            need = 2 - low
            if need <= 0:
                continue
            undec = [d for d in region_dom_contrib[rid] if status[d] == 0]
            if not undec:
                continue
            key = (len(undec), high - low, need)
            if best_key is None or key < best_key:
                best_key = key
                best_region = rid

        if best_region is not None:
            cands = [d for d in region_dom_contrib[best_region] if status[d] == 0]
            cands.sort(key=lambda d: -score_domino(d, status, region_count))
            return cands[0]

        undec = [d for d in range(D) if status[d] == 0]
        if not undec:
            return None
        undec.sort(key=lambda d: -score_domino(d, status, region_count))
        return undec[0]

    def clone_state(status, region_count, cell_covered):
        return status[:], dict(region_count), cell_covered[:]

    def search(status, region_count, cell_covered):
        if not propagate(status, region_count, cell_covered):
            return None
        if solved(status, region_count):
            return status

        d = select_branch(status, region_count)
        if d is None:
            return None

        # Try choose first, then forbid.
        for first_choose in (True, False):
            st2, rc2, cc2 = clone_state(status, region_count, cell_covered)
            q = deque()
            q.append(('choose' if first_choose else 'forbid', d))
            ok = True
            while q and ok:
                op, dd = q.popleft()
                ok = choose_domino(dd, st2, rc2, cc2, q) if op == 'choose' else forbid_domino(dd, st2, rc2, cc2, q)
            if not ok:
                continue
            res = search(st2, rc2, cc2)
            if res is not None:
                return res
        return None

    result = search(init_status, init_region_count, init_cell_covered)
    if result is None:
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for d, st in enumerate(result):
        if st == 1:
            a, b = dominoes[d]
            ans[a[0]][a[1]] = 'S'
            ans[b[0]][b[1]] = 'S'
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

