from collections import defaultdict, deque

# Tetromino normalization and generation utilities.

def normalize(cells):
    mr = min(r for r, c in cells)
    mc = min(c for r, c in cells)
    return tuple(sorted((r - mr, c - mc) for r, c in cells))

def rot(cells):
    return [(-c, r) for r, c in cells]

def refl(cells):
    return [(r, -c) for r, c in cells]

def all_orients(base):
    seen = set()
    cur = list(base)
    for _ in range(4):
        for variant in (cur, refl(cur)):
            seen.add(normalize(variant))
        cur = rot(cur)
    return sorted(seen)

BASES = {
    'I': [(0, 0), (1, 0), (2, 0), (3, 0)],
    'L': [(0, 0), (1, 0), (2, 0), (2, 1)],
    'T': [(0, 0), (0, 1), (0, 2), (1, 1)],
    'S': [(0, 1), (0, 2), (1, 0), (1, 1)],
}

SHAPES = {k: all_orients(v) for k, v in BASES.items()}

def region_cells_from_grid(grid):
    regions = defaultdict(list)
    n = len(grid)
    m = len(grid[0])
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    return dict(regions)

def region_adjacency(grid):
    n = len(grid)
    m = len(grid[0])
    adj = defaultdict(set)
    for r in range(n):
        for c in range(m):
            a = grid[r][c]
            for dr, dc in ((1, 0), (0, 1)):
                rr, cc = r + dr, c + dc
                if rr < n and cc < m:
                    b = grid[rr][cc]
                    if a != b:
                        adj[a].add(b)
                        adj[b].add(a)
    return {k: set(v) for k, v in adj.items()}

def placements_for_region(cells):
    cellset = set(cells)
    placements = []
    seen = set()
    for t, orients in SHAPES.items():
        for orient in orients:
            for anchor in cells:
                ar, ac = anchor
                for br, bc in orient:
                    sr, sc = ar - br, ac - bc
                    placed = tuple(sorted((sr + r, sc + c) for r, c in orient))
                    if all(p in cellset for p in placed):
                        key = (t, placed)
                        if key not in seen:
                            seen.add(key)
                            placements.append({
                                'type': t,
                                'cells': placed,
                                'cellset': frozenset(placed),
                            })
    return placements

def build_problem(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0])
    regions = region_cells_from_grid(grid)
    adj = region_adjacency(grid)
    region_ids = sorted(regions)
    placements = {}
    type_masks = {}
    for rid in region_ids:
        pls = placements_for_region(regions[rid])
        placements[rid] = pls
        tm = defaultdict(list)
        for i, p in enumerate(pls):
            tm[p['type']].append(i)
        type_masks[rid] = dict(tm)
    return {
        'grid': grid,
        'n': n,
        'm': m,
        'regions': regions,
        'adj': adj,
        'region_ids': region_ids,
        'placements': placements,
        'type_masks': type_masks,
    }

def grid_neighbors(n, m):
    nbrs = {}
    for r in range(n):
        for c in range(m):
            out = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    out.append((rr, cc))
            nbrs[(r, c)] = out
    return nbrs

def all_2x2_blocks(n, m):
    blocks = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks.append(((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
    return blocks

def solve(observation):
    prob = build_problem(observation)
    grid = prob['grid']
    n = prob['n']
    m = prob['m']
    regions = prob['regions']
    adj = prob['adj']
    region_ids = prob['region_ids']
    placements = prob['placements']

    # Early feasibility per region.
    for rid in region_ids:
        if not placements[rid]:
            return "No Solution"

    neighbors = grid_neighbors(n, m)
    blocks2 = all_2x2_blocks(n, m)

    cell_to_regions = defaultdict(list)
    for rid in region_ids:
        for idx, p in enumerate(placements[rid]):
            for cell in p['cells']:
                cell_to_regions[cell].append((rid, idx))

    # Region domains as sets of placement indices.
    domains = {rid: set(range(len(placements[rid]))) for rid in region_ids}

    # Human-like propagation:
    # 1) region-type incompatibility between adjacent regions
    # 2) forced / impossible shaded cells and 2x2 forbiddance
    # 3) global connectivity bounds via "must shaded" and "can shaded"

    all_cells = {(r, c) for r in range(n) for c in range(m)}

    def region_type_set(rid, dom):
        return {placements[rid][i]['type'] for i in dom[rid]}

    def compute_cell_status(dom):
        forced_shaded = set()
        forced_unshaded = set()
        can_shaded = set()
        for rid in region_ids:
            region_dom = dom[rid]
            reg_cells = set(regions[rid])
            counts = defaultdict(int)
            total = len(region_dom)
            for i in region_dom:
                for cell in placements[rid][i]['cells']:
                    counts[cell] += 1
                    can_shaded.add(cell)
            for cell in reg_cells:
                cnt = counts.get(cell, 0)
                if cnt == total and total > 0:
                    forced_shaded.add(cell)
                if cnt == 0:
                    forced_unshaded.add(cell)
        return forced_shaded, forced_unshaded, can_shaded

    def connected_components(cells):
        cells = set(cells)
        if not cells:
            return []
        comps = []
        while cells:
            start = next(iter(cells))
            q = [start]
            cells.remove(start)
            comp = {start}
            while q:
                u = q.pop()
                for v in neighbors[u]:
                    if v in cells:
                        cells.remove(v)
                        comp.add(v)
                        q.append(v)
            comps.append(comp)
        return comps

    def connectivity_possible(forced_shaded, can_shaded):
        if not can_shaded:
            return False
        comps = connected_components(can_shaded)
        if len(comps) > 1:
            return False
        if forced_shaded:
            fcomps = connected_components(forced_shaded)
            if len(fcomps) == 1:
                return True
            # Every forced component must be connectable through can_shaded; since can_shaded connected, okay.
            return True
        return True

    def all_region_types_singleton(dom):
        out = {}
        for rid in region_ids:
            ts = region_type_set(rid, dom)
            if len(ts) == 1:
                out[rid] = next(iter(ts))
        return out

    def propagate(dom):
        dom = {rid: set(v) for rid, v in dom.items()}
        changed = True
        while changed:
            changed = False

            # Empty domain check.
            for rid in region_ids:
                if not dom[rid]:
                    return None

            # Adjacent regions cannot have same tetromino type.
            single_types = all_region_types_singleton(dom)
            for a in region_ids:
                ta = single_types.get(a)
                for b in adj.get(a, ()):
                    if a < b:
                        tb = single_types.get(b)
                        if ta is not None and tb is not None and ta == tb:
                            return None

            # Arc consistency on region type choices.
            for a in region_ids:
                possible_b_types = {}
                for b in adj.get(a, ()):
                    possible_b_types[b] = region_type_set(b, dom)
                remove = set()
                for i in dom[a]:
                    t = placements[a][i]['type']
                    bad = False
                    for b in adj.get(a, ()):
                        # Need some placement in b with different type.
                        if possible_b_types[b] <= {t}:
                            bad = True
                            break
                    if bad:
                        remove.add(i)
                if remove:
                    dom[a] -= remove
                    if not dom[a]:
                        return None
                    changed = True

            forced_shaded, forced_unshaded, can_shaded = compute_cell_status(dom)

            # 2x2 full shaded forbidden:
            # if a 2x2 block is already forced shaded => contradiction.
            # if in a 2x2, three are forced shaded and fourth can only be shaded by some placements, remove those.
            for block in blocks2:
                fs = sum(cell in forced_shaded for cell in block)
                if fs == 4:
                    return None
                if fs == 3:
                    for cell in block:
                        if cell not in forced_shaded:
                            # Cell must become unshaded: remove all placements shading it in its region.
                            rid = grid[cell[0]][cell[1]]
                            rem = {i for i in dom[rid] if cell in placements[rid][i]['cellset']}
                            if rem:
                                dom[rid] -= rem
                                if not dom[rid]:
                                    return None
                                changed = True

            # Connectivity feasibility.
            forced_shaded, forced_unshaded, can_shaded = compute_cell_status(dom)
            if not connectivity_possible(forced_shaded, can_shaded):
                return None

            # If some forced shaded component is isolated from possible future growth, contradiction.
            # More precise human-like cut check: every connected component of forced_shaded must touch
            # either another forced cell path via can_shaded or have frontier in can_shaded.
            if forced_shaded:
                comps = connected_components(forced_shaded)
                if len(comps) > 1:
                    for comp in comps:
                        frontier = False
                        for cell in comp:
                            for nb in neighbors[cell]:
                                if nb in can_shaded and nb not in comp:
                                    frontier = True
                                    break
                            if frontier:
                                break
                        if not frontier:
                            return None

            # Region internal mandatory cell deductions:
            # If a cell is the only way for a region to connect its tetromino shape placements,
            # equivalent to standard domain filtering by support already handled indirectly.
            # Here add a simple hidden-single by type: if only one type remains in a region,
            # remove same-type placements from neighbors.
            single_types = all_region_types_singleton(dom)
            for a, ta in single_types.items():
                for b in adj.get(a, ()):
                    rem = {i for i in dom[b] if placements[b][i]['type'] == ta}
                    if rem:
                        if rem != set():
                            newset = dom[b] - rem
                            if not newset:
                                return None
                            if newset != dom[b]:
                                dom[b] = newset
                                changed = True

        return dom

    def final_connected(choice):
        shaded = set()
        for rid, idx in choice.items():
            shaded.update(placements[rid][idx]['cells'])
        if not shaded:
            return False
        comps = connected_components(shaded)
        if len(comps) != 1:
            return False
        for block in blocks2:
            if all(cell in shaded for cell in block):
                return False
        return True

    def choose_region(dom):
        best = None
        best_key = None
        for rid in region_ids:
            d = dom[rid]
            if len(d) > 1:
                types = {placements[rid][i]['type'] for i in d}
                # Strong MRV + type diversity heuristic.
                key = (len(d), len(types), -len(adj.get(rid, ())))
                if best_key is None or key < best_key:
                    best_key = key
                    best = rid
        return best

    def order_values(rid, dom):
        vals = list(dom[rid])
        # Prefer placements that maximize overlap with currently forced frontier, and constrain neighbors.
        forced_shaded, _, _ = compute_cell_status(dom)
        neigh = adj.get(rid, ())
        scored = []
        for i in vals:
            p = placements[rid][i]
            t = p['type']
            frontier_touch = 0
            for cell in p['cells']:
                for nb in neighbors[cell]:
                    if nb in forced_shaded:
                        frontier_touch += 1
            impact = 0
            for b in neigh:
                impact += sum(1 for j in dom[b] if placements[b][j]['type'] == t)
            scored.append((-frontier_touch, impact, i))
        scored.sort()
        return [i for _, _, i in scored]

    def dfs(dom):
        dom = propagate(dom)
        if dom is None:
            return None
        if all(len(dom[rid]) == 1 for rid in region_ids):
            choice = {rid: next(iter(dom[rid])) for rid in region_ids}
            if final_connected(choice):
                return choice
            return None

        rid = choose_region(dom)
        if rid is None:
            return None

        for i in order_values(rid, dom):
            newdom = {r: set(v) for r, v in dom.items()}
            newdom[rid] = {i}
            res = dfs(newdom)
            if res is not None:
                return res
        return None

    sol = dfs(domains)
    if sol is None:
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for rid, idx in sol.items():
        p = placements[rid][idx]
        t = p['type']
        for r, c in p['cells']:
            ans[r][c] = t
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [['B3', None, None, 'B5', 'W2', None], [None, None, None, None, 'B3', None], ['B2', None, None, None, None, None], [None, None, None, None, None, None], [None, 'B2', None, 'B2', None, 'B2'], ['B3', None, None, None, None, None]]}

from collections import defaultdict, deque

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPPOSITE = [2, 3, 0, 1]


def solve(observation):
    data = observation['data']
    n1 = len(data)
    m1 = len(data[0])
    if n1 != m1:
        return "No Solution"
    N = n1 - 1

    # Edge indexing on dot grid
    h_edges = []  # ((r,c),(r,c+1))
    v_edges = []  # ((r,c),(r+1,c))
    edge_endpoints = []
    edge_orient = []  # 'H' or 'V'
    edge_pos = []     # (r,c) for top/left anchor

    h_id = {}
    v_id = {}
    eid = 0
    for r in range(N + 1):
        for c in range(N):
            h_id[(r, c)] = eid
            h_edges.append(eid)
            edge_endpoints.append(((r, c), (r, c + 1)))
            edge_orient.append('H')
            edge_pos.append((r, c))
            eid += 1
    for r in range(N):
        for c in range(N + 1):
            v_id[(r, c)] = eid
            v_edges.append(eid)
            edge_endpoints.append(((r, c), (r + 1, c)))
            edge_orient.append('V')
            edge_pos.append((r, c))
            eid += 1
    E = eid

    vertex_edges = defaultdict(list)
    for e, (a, b) in enumerate(edge_endpoints):
        vertex_edges[a].append(e)
        vertex_edges[b].append(e)

    cells = []
    clues = []
    for r in range(N + 1):
        for c in range(N + 1):
            tok = data[r][c]
            if tok is not None:
                color = tok[0]
                k = int(tok[1:])
                clues.append((r, c, color, k))

    # Rays from each clue in the 4 directions
    clue_rays = []
    clue_incident = []
    for (r, c, color, k) in clues:
        up = [v_id[(rr, c)] for rr in range(r - 1, -1, -1)]
        right = [h_id[(r, cc)] for cc in range(c, N)]
        down = [v_id[(rr, c)] for rr in range(r, N)]
        left = [h_id[(r, cc)] for cc in range(c - 1, -1, -1)]
        rays = [up, right, down, left]
        clue_rays.append(rays)
        inc = []
        if r > 0:
            inc.append(v_id[(r - 1, c)])
        if c < N:
            inc.append(h_id[(r, c)])
        if r < N:
            inc.append(v_id[(r, c)])
        if c > 0:
            inc.append(h_id[(r, c - 1)])
        clue_incident.append(set(inc))

    edge_to_clues = [[] for _ in range(E)]
    for ci, rays in enumerate(clue_rays):
        for d in range(4):
            for e in rays[d]:
                edge_to_clues[e].append((ci, d))

    # State: -1 unknown, 0 off, 1 on
    state = [-1] * E

    # For DSU on currently-on edges to prevent premature small loops
    parent = list(range((N + 1) * (N + 1))))
    rank = [0] * ((N + 1) * (N + 1))

    def vid(v):
        return v[0] * (N + 1) + v[1]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    # Clue pattern domains: possible direction-pairs
    # dir indices U,R,D,L = 0,1,2,3
    clue_domains = []
    for (r, c, color, k), rays in zip(clues, clue_rays):
        cand = []
        if color == 'W':
            pairs = [(0, 2), (1, 3)]
        else:
            pairs = [(0, 1), (1, 2), (2, 3), (3, 0)]
        for a, b in pairs:
            if len(rays[a]) + len(rays[b]) >= k:
                # minimum is 2 because if a direction chosen, first incident edge must be on
                # but if ray empty, pair impossible
                if len(rays[a]) == 0 or len(rays[b]) == 0:
                    continue
                # positive lengths on both chosen rays
                if k >= 2 and k <= len(rays[a]) + len(rays[b]):
                    # each chosen ray length in [1, len]
                    lo = max(1, k - len(rays[b]))
                    hi = min(len(rays[a]), k - 1)
                    if lo <= hi:
                        cand.append((a, b))
        clue_domains.append(cand)
        if not cand:
            return "No Solution"

    trail = []

    def snapshot():
        return (len(trail), parent[:], rank[:], clue_domains[:])

    def rollback(snap):
        tlen, p, rk, doms = snap
        while len(trail) > tlen:
            e, old = trail.pop()
            state[e] = old
        parent[:] = p
        rank[:] = rk
        clue_domains[:] = doms

    def set_edge(e, val):
        cur = state[e]
        if cur == val:
            return True
        if cur != -1:
            return False
        # Prevent degree >2 locally
        a, b = edge_endpoints[e]
        if val == 1:
            for v in (a, b):
                on = 0
                unk = 0
                for ee in vertex_edges[v]:
                    if ee == e:
                        on += 1
                    elif state[ee] == 1:
                        on += 1
                    elif state[ee] == -1:
                        unk += 1
                if on > 2:
                    return False
        trail.append((e, cur))
        state[e] = val
        if val == 1:
            va, vb = vid(a), vid(b)
            # Disallow forming a cycle before all used-degree vertices can belong to final single loop.
            # We permit cycle only if every on-edge is in this component and no vertex degree issue remains;
            # cheap approximation: forbid creating a cycle unless all nonzero degree vertices already degree 2 and no unknown on them.
            if find(va) == find(vb):
                if not would_be_final_cycle():
                    return False
            else:
                union(va, vb)
        return True

    def vertex_degree_info(v):
        on = off = unk = 0
        for e in vertex_edges[v]:
            s = state[e]
            if s == 1:
                on += 1
            elif s == 0:
                off += 1
            else:
                unk += 1
        return on, off, unk

    def would_be_final_cycle():
        used_vertices = []
        for r in range(N + 1):
            for c in range(N + 1):
                v = (r, c)
                on, off, unk = vertex_degree_info(v)
                if on > 0:
                    if on != 2:
                        return False
                    used_vertices.append(vid(v))
        if not used_vertices:
            return False
        root = find(used_vertices[0])
        for x in used_vertices:
            if find(x) != root:
                return False
        # all clues must be satisfiable with no required unknown incident edge
        return True

    def propagate_vertices():
        changed = True
        while changed:
            changed = False
            for r in range(N + 1):
                for c in range(N + 1):
                    v = (r, c)
                    on, off, unk = vertex_degree_info(v)
                    if on > 2:
                        return False
                    if on == 2:
                        for e in vertex_edges[v]:
                            if state[e] == -1:
                                if not set_edge(e, 0):
                                    return False
                                changed = True
                    elif on == 1 and unk == 0:
                        return False
                    elif on == 1 and unk == 1:
                        for e in vertex_edges[v]:
                            if state[e] == -1:
                                if not set_edge(e, 1):
                                    return False
                                changed = True
                    elif on == 0 and unk == 1:
                        # cannot have degree 1 in final loop
                        for e in vertex_edges[v]:
                            if state[e] == -1:
                                if not set_edge(e, 0):
                                    return False
                                changed = True
        return True

    def feasible_ray_count(ray):
        # contiguous on-prefix length constraints induced by straight segment
        # if an edge in ray is off, all beyond must be off for that direction.
        min_len = 0
        max_len = 0
        blocked = False
        for e in ray:
            s = state[e]
            if blocked:
                if s == 1:
                    return None
                continue
            if s == 1:
                min_len += 1
                max_len += 1
            elif s == -1:
                max_len += 1
            else:
                blocked = True
        return (min_len, max_len)

    def enforce_ray_prefix(ray, length):
        # first length on, rest off
        for i, e in enumerate(ray):
            v = 1 if i < length else 0
            if not set_edge(e, v):
                return False
        return True

    def propagate_clues():
        changed = True
        while changed:
            changed = False
            for ci, ((r, c, color, k), rays) in enumerate(zip(clues, clue_rays)):
                dom = clue_domains[ci]
                new_dom = []
                forced_pairs = []
                for a, b in dom:
                    fr_a = feasible_ray_count(rays[a])
                    fr_b = feasible_ray_count(rays[b])
                    if fr_a is None or fr_b is None:
                        continue
                    lo_a, hi_a = fr_a
                    lo_b, hi_b = fr_b
                    if max(lo_a, k - hi_b) <= min(hi_a, k - lo_b):
                        new_dom.append((a, b))
                if not new_dom:
                    return False
                if len(new_dom) != len(dom):
                    clue_domains[ci] = new_dom
                    dom = new_dom
                    changed = True

                # directions appearing in all remaining patterns must be used; absent in all must be unused.
                count_dir = [0] * 4
                for a, b in dom:
                    count_dir[a] += 1
                    count_dir[b] += 1
                used_forced = {d for d in range(4) if count_dir[d] == len(dom)}
                used_forbidden = {d for d in range(4) if count_dir[d] == 0}

                for d in used_forced:
                    if not rays[d]:
                        return False
                    if not set_edge(rays[d][0], 1):
                        return False
                    changed = True
                for d in used_forbidden:
                    if rays[d]:
                        if not set_edge(rays[d][0], 0):
                            return False
                        changed = True

                # For any direction, straight segment means prefix-on then off.
                # If first unknown after a forced off prefix impossible, handled by feasible_ray_count.
                # If first edge off, all beyond must off.
                for d in range(4):
                    ray = rays[d]
                    seen_off = False
                    for e in ray:
                        if seen_off:
                            if state[e] == 1:
                                return False
                            if state[e] == -1:
                                if not set_edge(e, 0):
                                    return False
                                changed = True
                        elif state[e] == 0:
                            seen_off = True

                # If single pattern remains, narrow lengths
                if len(dom) == 1:
                    a, b = dom[0]
                    fa = feasible_ray_count(rays[a])
                    fb = feasible_ray_count(rays[b])
                    lo = max(fa[0], k - fb[1])
                    hi = min(fa[1], k - fb[0])
                    if lo > hi:
                        return False
                    # forced common edges on/off from all feasible lengths
                    # on if index < lo, off if index >= hi on ray a
                    for i, e in enumerate(rays[a]):
                        if i < lo:
                            if not set_edge(e, 1):
                                return False
                            changed = True
                        elif i >= hi:
                            if not set_edge(e, 0):
                                return False
                            changed = True
                    lb = k - hi
                    hb = k - lo
                    for i, e in enumerate(rays[b]):
                        if i < lb:
                            if not set_edge(e, 1):
                                return False
                            changed = True
                        elif i >= hb:
                            if not set_edge(e, 0):
                                return False
                            changed = True

                    # non-used directions off entirely
                    for d in range(4):
                        if d != a and d != b:
                            for e in rays[d]:
                                if not set_edge(e, 0):
                                    return False
                                changed = True

        return True

    def connectivity_prune():
        # Build graph of vertices that could still be on-connected through on/unknown edges,
        # require all clue incident structure to be in one possible component.
        relevant = set()
        for ci, ((r, c, color, k), rays) in enumerate(zip(clues, clue_rays)):
            for e in clue_incident[ci]:
                if state[e] != 0:
                    a, b = edge_endpoints[e]
                    relevant.add(a)
                    relevant.add(b)
        if not relevant:
            return True
        start = next(iter(relevant))
        dq = deque([start])
        seen = {start}
        while dq:
            v = dq.popleft()
            for e in vertex_edges[v]:
                if state[e] == 0:
                    continue
                a, b = edge_endpoints[e]
                u = b if a == v else a
                if u not in seen:
                    seen.add(u)
                    dq.append(u)
        return relevant <= seen

    def propagate():
        while True:
            before = len(trail)
            if not propagate_vertices():
                return False
            if not propagate_clues():
                return False
            if not connectivity_prune():
                return False
            # Extra vertex impossibility: if a clue circle has wrong local shape already.
            for ci, (r, c, color, k) in enumerate(clues):
                inc = list(clue_incident[ci])
                on = sum(state[e] == 1 for e in inc)
                unk = sum(state[e] == -1 for e in inc)
                if color == 'W':
                    if on > 2 or on + unk < 2:
                        return False
                else:
                    if on > 2 or on + unk < 2:
                        return False
            if len(trail) == before:
                break
        return True

    def choose_branch():
        # Most constrained clue first
        best = None
        for ci, dom in enumerate(clue_domains):
            if len(dom) > 1:
                score = len(dom)
                if best is None or score < best[0]:
                    best = (score, 'clue', ci)
        if best is not None:
            return best[1], best[2]

        # Otherwise choose unknown edge near clues / high degree effect
        best_e = None
        best_s = -1
        for e in range(E):
            if state[e] != -1:
                continue
            s = len(edge_to_clues[e])
            a, b = edge_endpoints[e]
            for v in (a, b):
                on, off, unk = vertex_degree_info(v)
                if on == 1 and unk == 2:
                    s += 3
                elif on == 0 and unk == 2:
                    s += 2
            if s > best_s:
                best_s = s
                best_e = e
        if best_e is not None:
            return 'edge', best_e
        return None, None

    def all_assigned():
        return all(s != -1 for s in state)

    def extract_loop():
        deg2 = []
        used_vertices = []
        for r in range(N + 1):
            for c in range(N + 1):
                v = (r, c)
                on_edges = [e for e in vertex_edges[v] if state[e] == 1]
                if len(on_edges) not in (0, 2):
                    return None
                if len(on_edges) == 2:
                    used_vertices.append(v)
        if not used_vertices:
            return None
        # all clue circles must be on loop
        for (r, c, color, k) in clues:
            if sum(state[e] == 1 for e in vertex_edges[(r, c)]) != 2:
                return None
        # single component
        root = None
        for v in used_vertices:
            rv = find(vid(v))
            if root is None:
                root = rv
            elif root != rv:
                return None

        start = min(used_vertices)
        path = [start]
        prev = None
        cur = start
        while True:
            on_edges = [e for e in vertex_edges[cur] if state[e] == 1]
            nxt = None
            for e in on_edges:
                a, b = edge_endpoints[e]
                u = b if a == cur else a
                if u != prev:
                    nxt = u
                    break
            if nxt is None:
                return None
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > E + 2:
                return None
        if len(path) < 4:
            return None
        # verify every on edge used exactly once
        used = set()
        for i in range(len(path) - 1):
            a, b = path[i], path[i + 1]
            for e in vertex_edges[a]:
                x, y = edge_endpoints[e]
                if (x == a and y == b) or (x == b and y == a):
                    used.add(e)
                    break
        if any(state[e] == 1 and e not in used for e in range(E)):
            return None
        return path

    def search():
        if not propagate():
            return None
        if all_assigned():
            loop = extract_loop()
            return loop if loop is not None else None

        kind, idx = choose_branch()
        if kind is None:
            loop = extract_loop()
            return loop if loop is not None else None

        if kind == 'clue':
            ci = idx
            dom = clue_domains[ci]
            # branch on each pattern, most restrictive first by summed max lengths
            for pair in dom:
                snap = snapshot()
                clue_domains[ci] = [pair]
                if propagate():
                    res = search()
                    if res is not None:
                        return res
                rollback(snap)
            return None
        else:
            e = idx
            # value ordering: try on first if it touches clues
            vals = [1, 0] if edge_to_clues[e] else [0, 1]
            for v in vals:
                snap = snapshot()
                if set_edge(e, v):
                    res = search()
                    if res is not None:
                        return res
                rollback(snap)
            return None

    loop = search()
    if loop is None:
        return "No Solution"
    return str(loop)


