# General solver for the tetromino-region connectivity puzzle.
# Returns a string representation of the answer grid using 'L'/'I'/'T'/'S' for shaded cells and None otherwise.

from collections import defaultdict, deque

TYPES = ("L", "I", "T", "S")


def canonical(cells):
    return tuple(sorted(cells))


def normalize(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))


def transform(cells, k):
    pts = list(cells)
    if k == 0:
        out = [(r, c) for r, c in pts]
    elif k == 1:
        out = [(r, -c) for r, c in pts]
    elif k == 2:
        out = [(-r, c) for r, c in pts]
    elif k == 3:
        out = [(-r, -c) for r, c in pts]
    elif k == 4:
        out = [(c, r) for r, c in pts]
    elif k == 5:
        out = [(c, -r) for r, c in pts]
    elif k == 6:
        out = [(-c, r) for r, c in pts]
    else:
        out = [(-c, -r) for r, c in pts]
    return normalize(out)


def build_tetromino_catalog():
    base = {
        "I": [(0, 0), (1, 0), (2, 0), (3, 0)],
        "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
        "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
        "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
    }
    uniq = {}
    for t, cells in base.items():
        seen = set()
        shapes = []
        for k in range(8):
            shp = transform(cells, k)
            if shp not in seen:
                seen.add(shp)
                shapes.append(shp)
        uniq[t] = shapes
    return uniq


CATALOG = build_tetromino_catalog()


def region_cells_from_grid(grid):
    regions = defaultdict(list)
    for r, row in enumerate(grid):
        for c, x in enumerate(row):
            regions[x].append((r, c))
    return dict(regions)


def orth_neighbors(cell, nrows, ncols):
    r, c = cell
    if r > 0:
        yield (r - 1, c)
    if r + 1 < nrows:
        yield (r + 1, c)
    if c > 0:
        yield (r, c - 1)
    if c + 1 < ncols:
        yield (r, c + 1)


def shape_type(cells):
    norm = normalize(cells)
    for t, shapes in CATALOG.items():
        if norm in shapes:
            return t
    return None


def enumerate_region_placements(region_cells, nrows, ncols):
    region_set = set(region_cells)
    placements = []
    seen = set()
    for anchor in region_cells:
        ar, ac = anchor
        for t, shapes in CATALOG.items():
            for shp in shapes:
                for sr, sc in shp:
                    dr = ar - sr
                    dc = ac - sc
                    placed = tuple(sorted((dr + r, dc + c) for r, c in shp))
                    if all((r, c) in region_set for r, c in placed):
                        key = (t, placed)
                        if key not in seen:
                            seen.add(key)
                            placements.append(
                                {
                                    "type": t,
                                    "cells": placed,
                                    "cellset": set(placed),
                                }
                            )
    return placements


def region_adjacency(grid):
    nrows = len(grid)
    ncols = len(grid[0])
    adj = defaultdict(set)
    for r in range(nrows):
        for c in range(ncols):
            a = grid[r][c]
            if r + 1 < nrows:
                b = grid[r + 1][c]
                if a != b:
                    adj[a].add(b)
                    adj[b].add(a)
            if c + 1 < ncols:
                b = grid[r][c + 1]
                if a != b:
                    adj[a].add(b)
                    adj[b].add(a)
    return {k: set(v) for k, v in adj.items()}


def all_2x2_blocks(nrows, ncols):
    return [[(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)] for r in range(nrows - 1) for c in range(ncols - 1)]


def shaded_global_connectivity_possible(selected_cellsets, undecided_region_ids, domains):
    if not selected_cellsets and not undecided_region_ids:
        return True
    allowed = set()
    for cs in selected_cellsets:
        allowed |= cs
    for rid in undecided_region_ids:
        for p in domains[rid]:
            allowed |= p["cellset"]
    if not allowed:
        return False
    required = set()
    for cs in selected_cellsets:
        required |= cs
    start = next(iter(allowed))
    q = deque([start])
    seen = {start}
    while q:
        cur = q.popleft()
        r, c = cur
        for nb in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if nb in allowed and nb not in seen:
                seen.add(nb)
                q.append(nb)
    if required - seen:
        return False
    for rid in undecided_region_ids:
        possible = set()
        for p in domains[rid]:
            possible |= p["cellset"]
        if not (possible & seen):
            return False
    return True


def selected_cells_connected(assignments):
    cells = set()
    for p in assignments.values():
        cells |= p["cellset"]
    if not cells:
        return False
    start = next(iter(cells))
    q = deque([start])
    seen = {start}
    while q:
        r, c = q.popleft()
        for nb in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if nb in cells and nb not in seen:
                seen.add(nb)
                q.append(nb)
    return len(seen) == len(cells)


def solve(observation):
    grid = observation["data"]
    nrows = len(grid)
    ncols = len(grid[0])

    regions = region_cells_from_grid(grid)
    region_ids = sorted(regions)
    adj = region_adjacency(grid)
    blocks2 = all_2x2_blocks(nrows, ncols)

    domains = {}
    for rid in region_ids:
        placements = enumerate_region_placements(regions[rid], nrows, ncols)
        if not placements:
            return "No Solution"
        domains[rid] = placements

    region_of = {}
    for rid, cells in regions.items():
        for cell in cells:
            region_of[cell] = rid

    blocks_by_cell = defaultdict(list)
    for i, blk in enumerate(blocks2):
        for cell in blk:
            blocks_by_cell[cell].append(i)

    def check_no_full_2x2_partial(assignments):
        shaded = set()
        undecided = set(region_ids) - set(assignments)
        block_count = []
        for blk in blocks2:
            shaded_cnt = 0
            possible_extra = 0
            for cell in blk:
                rid = region_of[cell]
                if rid in assignments:
                    if cell in assignments[rid]["cellset"]:
                        shaded_cnt += 1
                else:
                    # Human-style pruning: can this undecided region ever shade this cell?
                    if any(cell in p["cellset"] for p in domains[rid]):
                        possible_extra += 1
            if shaded_cnt == 4:
                return False
            if shaded_cnt + possible_extra < 4:
                continue
            block_count.append((shaded_cnt, possible_extra))
        return True

    def propagate(domains, assignments):
        changed = True
        while changed:
            changed = False

            for rid in region_ids:
                if rid in assignments:
                    continue
                old = domains[rid]
                new = []
                for p in old:
                    ok = True

                    # Adjacent regions cannot use same tetromino type.
                    for nb in adj.get(rid, ()):
                        if nb in assignments and assignments[nb]["type"] == p["type"]:
                            ok = False
                            break
                    if not ok:
                        continue

                    # No 2x2 can be fully shaded.
                    for blk_idx in set(i for cell in p["cellset"] for i in blocks_by_cell[cell]):
                        blk = blocks2[blk_idx]
                        full = True
                        for cell in blk:
                            rr = region_of[cell]
                            if rr == rid:
                                if cell not in p["cellset"]:
                                    full = False
                                    break
                            elif rr in assignments:
                                if cell not in assignments[rr]["cellset"]:
                                    full = False
                                    break
                            else:
                                if not any(cell in q["cellset"] for q in domains[rr]):
                                    full = False
                                    break
                                full = False
                                break
                        if full:
                            ok = False
                            break
                    if not ok:
                        continue

                    new.append(p)

                if not new:
                    return None, None
                if len(new) != len(old):
                    domains[rid] = new
                    changed = True

            # Naked singletons
            for rid in region_ids:
                if rid not in assignments and len(domains[rid]) == 1:
                    assignments[rid] = domains[rid][0]
                    changed = True

            # Type elimination from assigned neighbors
            for rid in region_ids:
                if rid in assignments:
                    continue
                banned = {assignments[nb]["type"] for nb in adj.get(rid, ()) if nb in assignments}
                if banned:
                    old = domains[rid]
                    new = [p for p in old if p["type"] not in banned]
                    if not new:
                        return None, None
                    if len(new) != len(old):
                        domains[rid] = new
                        changed = True

            # Global connectivity feasibility
            selected = [assignments[r]["cellset"] for r in assignments]
            undecided = [r for r in region_ids if r not in assignments]
            if not shaded_global_connectivity_possible(selected, undecided, domains):
                return None, None

            # 2x2 hard contradiction
            if not check_no_full_2x2_partial(assignments):
                return None, None

        return domains, assignments

    def score_region(rid, domains, assignments):
        # Human-like choice: smallest domain first, then stronger interaction with neighbors.
        d = len(domains[rid])
        type_count = len({p["type"] for p in domains[rid]})
        undec_nb = sum(1 for nb in adj.get(rid, ()) if nb not in assignments)
        return (d, type_count, -undec_nb, -len(regions[rid]))

    def placement_key(p, rid, assignments):
        # Prefer placements touching existing shaded cells to preserve/connect the global shaded component.
        touched = 0
        occupied = set()
        for a in assignments.values():
            occupied |= a["cellset"]
        if occupied:
            for cell in p["cellset"]:
                r, c = cell
                for nb in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if nb in occupied:
                        touched += 1
                        break
        # Also prefer rarer types in region domain to force deductions.
        return (-touched, p["type"], p["cells"])

    def search(domains, assignments):
        domains = {k: list(v) for k, v in domains.items()}
        assignments = dict(assignments)

        domains, assignments = propagate(domains, assignments)
        if domains is None:
            return None

        if len(assignments) == len(region_ids):
            # Final checks
            for rid in region_ids:
                for nb in adj.get(rid, ()):
                    if rid < nb and assignments[rid]["type"] == assignments[nb]["type"]:
                        return None
            for blk in blocks2:
                if all(cell in assignments[region_of[cell]]["cellset"] for cell in blk):
                    return None
            if not selected_cells_connected(assignments):
                return None
            ans = [[None for _ in range(ncols)] for _ in range(nrows)]
            for rid, p in assignments.items():
                for r, c in p["cellset"]:
                    ans[r][c] = p["type"]
            return ans

        undecided = [rid for rid in region_ids if rid not in assignments]
        rid = min(undecided, key=lambda x: score_region(x, domains, assignments))

        options = sorted(domains[rid], key=lambda p: placement_key(p, rid, assignments))
        for p in options:
            new_domains = {k: list(v) for k, v in domains.items()}
            new_assignments = dict(assignments)
            new_assignments[rid] = p
            new_domains[rid] = [p]
            res = search(new_domains, new_assignments)
            if res is not None:
                return res
        return None

    res = search(domains, {})
    if res is None:
        return "No Solution"
    return str(res)


