from collections import defaultdict, deque

# Tetromino base definitions as sets of (r,c), normalized to include (0,0)-based positions.
BASES = {
    'I': {(0, 0), (0, 1), (0, 2), (0, 3)},
    'L': {(0, 0), (1, 0), (2, 0), (2, 1)},
    'T': {(0, 0), (0, 1), (0, 2), (1, 1)},
    'S': {(0, 1), (0, 2), (1, 0), (1, 1)},
}

def normalize(shape):
    mr = min(r for r, c in shape)
    mc = min(c for r, c in shape)
    return frozenset((r - mr, c - mc) for r, c in shape)

def transforms(shape):
    pts = list(shape)
    res = set()
    for rr in range(2):
        for k in range(4):
            cur = []
            for r, c in pts:
                x, y = r, c
                if rr:
                    y = -y
                for _ in range(k):
                    x, y = y, -x
                cur.append((x, y))
            res.add(normalize(cur))
    return res

ALL_SHAPES = {}
for t, s in BASES.items():
    ALL_SHAPES[t] = sorted(transforms(s), key=lambda z: sorted(z))

def region_cells_from_grid(grid):
    mp = defaultdict(list)
    for r, row in enumerate(grid):
        for c, x in enumerate(row):
            mp[x].append((r, c))
    return dict(mp)

def orth_neighbors(cell, R, C):
    r, c = cell
    if r > 0:
        yield (r - 1, c)
    if r + 1 < R:
        yield (r + 1, c)
    if c > 0:
        yield (r, c - 1)
    if c + 1 < C:
        yield (r, c + 1)

def shape_type_of_cells(cells):
    s = normalize(cells)
    for t, variants in ALL_SHAPES.items():
        if s in variants:
            return t
    return None

def enumerate_region_placements(region_cells):
    cells = set(region_cells)
    out = []
    seen = set()
    for comb in combinations4(region_cells):
        comb_set = frozenset(comb)
        if not connected_4(comb_set):
            continue
        t = shape_type_of_cells([(r, c) for r, c in relabel_normalized(comb_set)])
        if t is None:
            continue
        if comb_set in seen:
            continue
        seen.add(comb_set)
        out.append((t, comb_set))
    return out

def relabel_normalized(cells):
    mr = min(r for r, c in cells)
    mc = min(c for r, c in cells)
    return [(r - mr, c - mc) for r, c in cells]

def combinations4(lst):
    n = len(lst)
    for i in range(n - 3):
        a = lst[i]
        for j in range(i + 1, n - 2):
            b = lst[j]
            for k in range(j + 1, n - 1):
                c = lst[k]
                for l in range(k + 1, n):
                    yield (a, b, c, lst[l])

def connected_4(cells):
    cells = set(cells)
    q = deque([next(iter(cells))])
    seen = set(q)
    while q:
        u = q.popleft()
        r, c = u
        for v in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if v in cells and v not in seen:
                seen.add(v)
                q.append(v)
    return len(seen) == len(cells)

def pretty_answer(assignments, R, C):
    out = [[None for _ in range(C)] for _ in range(R)]
    for _, (typ, cells) in assignments.items():
        for r, c in cells:
            out[r][c] = typ
    return str(out)

def solve(observation):
    grid = observation['data']
    R, C = len(grid), len(grid[0])
    regions = region_cells_from_grid(grid)
    region_ids = sorted(regions)

    # Region adjacency graph.
    reg_adj = {rid: set() for rid in region_ids}
    for r in range(R):
        for c in range(C):
            a = grid[r][c]
            if r + 1 < R:
                b = grid[r + 1][c]
                if a != b:
                    reg_adj[a].add(b)
                    reg_adj[b].add(a)
            if c + 1 < C:
                b = grid[r][c + 1]
                if a != b:
                    reg_adj[a].add(b)
                    reg_adj[b].add(a)

    # Candidate placements per region.
    placements = {}
    for rid in region_ids:
        pls = enumerate_region_placements(regions[rid])
        if not pls:
            return "No Solution"
        placements[rid] = pls

    # Cell-to-candidate reverse map.
    cell_to_region = {}
    for rid, cells in regions.items():
        for cell in cells:
            cell_to_region[cell] = rid

    # For 2x2 pruning: precompute candidate participation.
    blocks = []
    cell_blocks = defaultdict(list)
    for r in range(R - 1):
        for c in range(C - 1):
            block = ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))
            idx = len(blocks)
            blocks.append(block)
            for cell in block:
                cell_blocks[cell].append(idx)

    candidate_cells = {}
    candidate_type = {}
    for rid in region_ids:
        candidate_cells[rid] = [set(cells) for _, cells in placements[rid]]
        candidate_type[rid] = [typ for typ, _ in placements[rid]]

    # Domains are sets of candidate indices.
    domains = {rid: set(range(len(placements[rid]))) for rid in region_ids}

    # Human-like deduction helpers.
    def enforce_arc_type(domains):
        changed = True
        while changed:
            changed = False
            for a in region_ids:
                if not domains[a]:
                    return None
                allowed_types_a = {candidate_type[a][i] for i in domains[a]}
                for b in reg_adj[a]:
                    if not domains[b]:
                        return None
                    allowed_types_b = {candidate_type[b][j] for j in domains[b]}
                    # Remove candidates in a whose type cannot be matched by some different type in b.
                    rem_a = set()
                    for i in domains[a]:
                        ta = candidate_type[a][i]
                        if all(candidate_type[b][j] == ta for j in domains[b]):
                            rem_a.add(i)
                    if rem_a:
                        domains[a] -= rem_a
                        if not domains[a]:
                            return None
                        changed = True
                    # Symmetric on b
                    rem_b = set()
                    for j in domains[b]:
                        tb = candidate_type[b][j]
                        if all(candidate_type[a][i] == tb for i in domains[a]):
                            rem_b.add(j)
                    if rem_b:
                        domains[b] -= rem_b
                        if not domains[b]:
                            return None
                        changed = True
        return domains

    def enforce_local_2x2(domains):
        # If any 2x2 block is forced fully shaded by currently possible candidates, fail.
        # If in a block, each of the 4 cells is guaranteed shaded by its region, contradiction.
        for block in blocks:
            forced = True
            for cell in block:
                rid = cell_to_region[cell]
                if not any(cell in candidate_cells[rid][i] for i in domains[rid]):
                    return None
                if not all(cell in candidate_cells[rid][i] for i in domains[rid]):
                    forced = False
            if forced:
                return None

        # Candidate-level elimination: if choosing a candidate would force a 2x2 full block regardless of others.
        changed = True
        while changed:
            changed = False
            for rid in region_ids:
                rem = set()
                for i in list(domains[rid]):
                    mycells = candidate_cells[rid][i]
                    bad = False
                    touched = set()
                    for cell in mycells:
                        touched.update(cell_blocks[cell])
                    for bi in touched:
                        block = blocks[bi]
                        if not all(cell in mycells or cell_to_region[cell] != rid for cell in block):
                            pass
                        forced_all = True
                        for cell in block:
                            rr = cell_to_region[cell]
                            if rr == rid:
                                if cell not in mycells:
                                    forced_all = False
                                    break
                            else:
                                if not all(cell in candidate_cells[rr][j] for j in domains[rr]):
                                    forced_all = False
                                    break
                        if forced_all:
                            bad = True
                            break
                    if bad:
                        rem.add(i)
                if rem:
                    domains[rid] -= rem
                    if not domains[rid]:
                        return None
                    changed = True
        return domains

    def connectivity_components_possible(domains):
        # Necessary connectivity check on region-candidate graph using possible touching.
        n = len(region_ids)
        possible_edges = {rid: set() for rid in region_ids}
        for idx_a, a in enumerate(region_ids):
            for b in region_ids[idx_a + 1:]:
                touch = False
                for i in domains[a]:
                    ca = candidate_cells[a][i]
                    for j in domains[b]:
                        cb = candidate_cells[b][j]
                        if any(((r - 1, c) in cb or (r + 1, c) in cb or (r, c - 1) in cb or (r, c + 1) in cb) for r, c in ca):
                            touch = True
                            break
                    if touch:
                        break
                if touch:
                    possible_edges[a].add(b)
                    possible_edges[b].add(a)
        start = region_ids[0]
        q = deque([start])
        seen = {start}
        while q:
            u = q.popleft()
            for v in possible_edges[u]:
                if v not in seen:
                    seen.add(v)
                    q.append(v)
        return len(seen) == n

    def propagate(domains):
        while True:
            snapshot = {k: frozenset(v) for k, v in domains.items()}
            domains = enforce_arc_type(domains)
            if domains is None:
                return None
            domains = enforce_local_2x2(domains)
            if domains is None:
                return None
            if not connectivity_components_possible(domains):
                return None
            # Single-type region forcing can prune neighboring same-types.
            changed = False
            fixed = [rid for rid in region_ids if len(domains[rid]) == 1]
            for rid in fixed:
                idx = next(iter(domains[rid]))
                t = candidate_type[rid][idx]
                for nb in reg_adj[rid]:
                    rem = {j for j in domains[nb] if candidate_type[nb][j] == t}
                    if rem:
                        domains[nb] -= rem
                        if not domains[nb]:
                            return None
                        changed = True
            if not changed and snapshot == {k: frozenset(v) for k, v in domains.items()}:
                break
        return domains

    def final_check(assign):
        # Adjacent regions different types.
        for a in region_ids:
            ta, ca = assign[a]
            for b in reg_adj[a]:
                if a < b and ta == assign[b][0]:
                    return False

        # No 2x2 all shaded.
        shaded = set()
        for _, cells in assign.values():
            shaded |= set(cells)
        for r in range(R - 1):
            for c in range(C - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= shaded:
                    return False

        # Global connectivity.
        if shaded:
            q = deque([next(iter(shaded))])
            seen = set(q)
            while q:
                u = q.popleft()
                r, c = u
                for v in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if v in shaded and v not in seen:
                        seen.add(v)
                        q.append(v)
            if len(seen) != len(shaded):
                return False
        return True

    def optimistic_connectivity_after_choice(domains, rid, choice):
        # Strong necessary check: all currently fixed/possible placements must be able to connect
        # to the chosen placement through possible-touch graph.
        temp = {k: set(v) for k, v in domains.items()}
        temp[rid] = {choice}
        if not connectivity_components_possible(temp):
            return False
        return True

    def select_region(domains):
        # Most constrained, then strongest interaction.
        best = None
        best_key = None
        for rid in region_ids:
            d = len(domains[rid])
            if d > 1:
                type_count = len({candidate_type[rid][i] for i in domains[rid]})
                key = (d, type_count, -len(reg_adj[rid]), -len(regions[rid]))
                if best_key is None or key < best_key:
                    best_key = key
                    best = rid
        return best

    def order_candidates(rid, domains):
        # Prefer candidates that touch many possible neighbors and avoid isolated islands.
        scored = []
        for i in domains[rid]:
            cells = candidate_cells[rid][i]
            t = candidate_type[rid][i]
            touch_score = 0
            same_type_conflict = 0
            for nb in reg_adj[rid]:
                can_touch = False
                diff_type_count = 0
                for j in domains[nb]:
                    if candidate_type[nb][j] != t:
                        diff_type_count += 1
                        cb = candidate_cells[nb][j]
                        if any(((r - 1, c) in cb or (r + 1, c) in cb or (r, c - 1) in cb or (r, c + 1) in cb) for r, c in cells):
                            can_touch = True
                if can_touch:
                    touch_score += 1
                same_type_conflict += len([j for j in domains[nb] if candidate_type[nb][j] == t])
            scored.append(( -touch_score, same_type_conflict, i))
        scored.sort()
        return [i for _, _, i in scored]

    def dfs(domains):
        domains = propagate({k: set(v) for k, v in domains.items()})
        if domains is None:
            return None
        if all(len(domains[rid]) == 1 for rid in region_ids):
            assign = {}
            for rid in region_ids:
                i = next(iter(domains[rid]))
                assign[rid] = (candidate_type[rid][i], frozenset(candidate_cells[rid][i]))
            if final_check(assign):
                return assign
            return None

        rid = select_region(domains)
        for i in order_candidates(rid, domains):
            if not optimistic_connectivity_after_choice(domains, rid, i):
                continue
            nd = {k: set(v) for k, v in domains.items()}
            nd[rid] = {i}
            res = dfs(nd)
            if res is not None:
                return res
        return None

    ans = dfs(domains)
    if ans is None:
        return "No Solution"
    return pretty_answer(ans, R, C)

