# Slitherlink solver with human-like deduction + constrained search.
# Returns ordered loop-dot coordinates, e.g. [(0,0), (0,1), ..., (0,0)] or "No Solution".

from collections import deque, defaultdict

UNKNOWN = -1
OFF = 0
ON = 1


class DSURollback:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.stack = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            self.stack.append((-1, -1, -1, -1))
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.stack.append((rb, self.parent[rb], ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

    def snapshot(self):
        return len(self.stack)

    def rollback(self, snap):
        while len(self.stack) > snap:
            rb, old_parent, ra, old_size = self.stack.pop()
            if rb == -1:
                continue
            self.parent[rb] = old_parent
            self.size[ra] = old_size


class SlitherlinkSolver:
    def __init__(self, data):
        self.data = data
        self.H = len(data)
        self.W = len(data[0]) if self.H else 0
        self.dot_rows = self.H + 1
        self.dot_cols = self.W + 1

        self.edges = []
        self.edge_index = {}
        self.edge_verts = []
        self.vert_edges = [[] for _ in range(self.dot_rows * self.dot_cols)]
        self.cell_edges = [[None] * self.W for _ in range(self.H)]
        self.edge_cells = []

        self._build_topology()

        self.E = len(self.edges)
        self.V = self.dot_rows * self.dot_cols

        self.state = [UNKNOWN] * self.E
        self.on_deg = [0] * self.V
        self.unk_deg = [len(self.vert_edges[v]) for v in range(self.V)]
        self.cell_on = [[0] * self.W for _ in range(self.H)]
        self.cell_unk = [[4] * self.W for _ in range(self.H)]

        self.dsu = DSURollback(self.V)
        self.on_edges_count = 0

        self.assign_stack = []
        self.reason_queue = deque()

        self._seed_basic_rules()

    def _vid(self, r, c):
        return r * self.dot_cols + c

    def _build_topology(self):
        # Horizontal edges
        idx = 0
        for r in range(self.dot_rows):
            for c in range(self.W):
                v1 = self._vid(r, c)
                v2 = self._vid(r, c + 1)
                self.edge_index[('H', r, c)] = idx
                self.edges.append(('H', r, c))
                self.edge_verts.append((v1, v2))
                self.vert_edges[v1].append(idx)
                self.vert_edges[v2].append(idx)
                cells = []
                if r > 0:
                    cells.append((r - 1, c))
                if r < self.H:
                    cells.append((r, c))
                self.edge_cells.append(cells)
                idx += 1

        # Vertical edges
        for r in range(self.H):
            for c in range(self.dot_cols):
                v1 = self._vid(r, c)
                v2 = self._vid(r + 1, c)
                self.edge_index[('V', r, c)] = idx
                self.edges.append(('V', r, c))
                self.edge_verts.append((v1, v2))
                self.vert_edges[v1].append(idx)
                self.vert_edges[v2].append(idx)
                cells = []
                if c > 0:
                    cells.append((r, c - 1))
                if c < self.W:
                    cells.append((r, c))
                self.edge_cells.append(cells)
                idx += 1

        for r in range(self.H):
            for c in range(self.W):
                top = self.edge_index[('H', r, c)]
                bottom = self.edge_index[('H', r + 1, c)]
                left = self.edge_index[('V', r, c)]
                right = self.edge_index[('V', r, c + 1)]
                self.cell_edges[r][c] = [top, right, bottom, left]

    def _seed_basic_rules(self):
        # Queue all constrained cells and vertices.
        for r in range(self.H):
            for c in range(self.W):
                if self.data[r][c] is not None:
                    self.reason_queue.append(('cell', r, c))
        for v in range(self.V):
            self.reason_queue.append(('vert', v))

        # Human-like immediate structural rules on clues.
        for r in range(self.H):
            for c in range(self.W):
                clue = self.data[r][c]
                if clue is None:
                    continue
                e = self.cell_edges[r][c]
                if clue == 0:
                    for x in e:
                        self.reason_queue.append(('force', x, OFF))
                elif clue == 3:
                    # Corner 3 rule: the two border edges around the corner cell must be ON.
                    if r == 0 and c == 0:
                        self.reason_queue.append(('force', e[0], ON))
                        self.reason_queue.append(('force', e[3], ON))
                    if r == 0 and c == self.W - 1:
                        self.reason_queue.append(('force', e[0], ON))
                        self.reason_queue.append(('force', e[1], ON))
                    if r == self.H - 1 and c == 0:
                        self.reason_queue.append(('force', e[2], ON))
                        self.reason_queue.append(('force', e[3], ON))
                    if r == self.H - 1 and c == self.W - 1:
                        self.reason_queue.append(('force', e[2], ON))
                        self.reason_queue.append(('force', e[1], ON))

    def snapshot(self):
        return (
            len(self.assign_stack),
            self.dsu.snapshot(),
            self.on_edges_count,
        )

    def rollback(self, snap):
        assign_len, dsu_snap, on_cnt = snap
        self.dsu.rollback(dsu_snap)
        self.on_edges_count = on_cnt
        while len(self.assign_stack) > assign_len:
            e, old = self.assign_stack.pop()
            val = self.state[e]
            if val == UNKNOWN:
                continue
            v1, v2 = self.edge_verts[e]
            for v in (v1, v2):
                if val == ON:
                    self.on_deg[v] -= 1
                self.unk_deg[v] += 1
            for r, c in self.edge_cells[e]:
                if val == ON:
                    self.cell_on[r][c] -= 1
                self.cell_unk[r][c] += 1
            self.state[e] = old

    def set_edge(self, e, val):
        cur = self.state[e]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False

        # Prevent premature subloops: if ON edge connects two vertices already in same ON-component,
        # it is only allowed if this is the final closing edge of the whole loop.
        if val == ON:
            v1, v2 = self.edge_verts[e]
            if self.on_deg[v1] >= 2 or self.on_deg[v2] >= 2:
                return False
            r1 = self.dsu.find(v1)
            r2 = self.dsu.find(v2)
            if r1 == r2:
                # Allow only if all remaining unknowns become OFF and all ON vertices degree 2.
                # In propagation phase, reject; full completion handled later.
                return False

        self.assign_stack.append((e, cur))
        self.state[e] = val
        v1, v2 = self.edge_verts[e]

        for v in (v1, v2):
            self.unk_deg[v] -= 1
            if val == ON:
                self.on_deg[v] += 1

        for r, c in self.edge_cells[e]:
            self.cell_unk[r][c] -= 1
            if val == ON:
                self.cell_on[r][c] += 1
            self.reason_queue.append(('cell', r, c))

        self.reason_queue.append(('vert', v1))
        self.reason_queue.append(('vert', v2))

        if val == ON:
            self.on_edges_count += 1
            self.dsu.union(v1, v2)

        return self._local_feasible(v1, v2, e)

    def _local_feasible(self, v1, v2, e):
        for v in (v1, v2):
            if self.on_deg[v] > 2:
                return False
            if self.on_deg[v] == 1 and self.unk_deg[v] == 0:
                return False

        for r, c in self.edge_cells[e]:
            clue = self.data[r][c]
            if clue is None:
                continue
            on = self.cell_on[r][c]
            unk = self.cell_unk[r][c]
            if on > clue or on + unk < clue:
                return False
        return True

    def propagate(self):
        while self.reason_queue:
            item = self.reason_queue.popleft()
            typ = item[0]

            if typ == 'force':
                _, e, val = item
                if not self.set_edge(e, val):
                    return False

            elif typ == 'cell':
                _, r, c = item
                clue = self.data[r][c]
                if clue is None:
                    continue
                on = self.cell_on[r][c]
                unk = self.cell_unk[r][c]
                edges = self.cell_edges[r][c]

                if on > clue or on + unk < clue:
                    return False
                if unk == 0:
                    continue
                if on == clue:
                    for e in edges:
                        if self.state[e] == UNKNOWN:
                            if not self.set_edge(e, OFF):
                                return False
                elif on + unk == clue:
                    for e in edges:
                        if self.state[e] == UNKNOWN:
                            if not self.set_edge(e, ON):
                                return False

                # Human-like diagonal / pattern rule around 3-0 adjacency and 3-3/1-3 consequences
                # via corner parity: for each corner of a cell, if two incident cell-edges statuses constrain a vertex.
                # This is kept lightweight and general through vertex propagation below.

            elif typ == 'vert':
                _, v = item
                on = self.on_deg[v]
                unk = self.unk_deg[v]
                if on > 2:
                    return False
                if on == 2:
                    for e in self.vert_edges[v]:
                        if self.state[e] == UNKNOWN:
                            if not self.set_edge(e, OFF):
                                return False
                elif on == 1 and unk == 0:
                    return False
                elif on == 1 and unk == 1:
                    for e in self.vert_edges[v]:
                        if self.state[e] == UNKNOWN:
                            if not self.set_edge(e, ON):
                                return False
                elif on == 0 and unk == 1:
                    for e in self.vert_edges[v]:
                        if self.state[e] == UNKNOWN:
                            if not self.set_edge(e, OFF):
                                return False

        return self._global_sanity()

    def _global_sanity(self):
        # Every clue must remain satisfiable.
        for r in range(self.H):
            for c in range(self.W):
                clue = self.data[r][c]
                if clue is None:
                    continue
                on = self.cell_on[r][c]
                unk = self.cell_unk[r][c]
                if on > clue or on + unk < clue:
                    return False

        # Connectivity lower-bound sanity:
        # any ON vertices must be potentially connectable into one loop through unknown/ON edges.
        on_vertices = [v for v in range(self.V) if self.on_deg[v] > 0]
        if on_vertices:
            seen = set()
            dq = deque([on_vertices[0]])
            seen.add(on_vertices[0])
            while dq:
                v = dq.popleft()
                for e in self.vert_edges[v]:
                    if self.state[e] != OFF:
                        a, b = self.edge_verts[e]
                        w = b if a == v else a
                        if w not in seen:
                            seen.add(w)
                            dq.append(w)
            for v in on_vertices:
                if v not in seen:
                    return False
        return True

    def is_complete(self):
        return all(s != UNKNOWN for s in self.state)

    def check_final(self):
        # Clues exact
        for r in range(self.H):
            for c in range(self.W):
                clue = self.data[r][c]
                if clue is not None and self.cell_on[r][c] != clue:
                    return False

        # Vertex degrees 0 or 2, and at least one edge
        on_vertices = [v for v in range(self.V) if self.on_deg[v] > 0]
        if not on_vertices:
            return False
        for v in range(self.V):
            if self.on_deg[v] not in (0, 2):
                return False

        # Single loop
        start = on_vertices[0]
        seen_v = set([start])
        seen_e = set()
        dq = deque([start])
        while dq:
            v = dq.popleft()
            for e in self.vert_edges[v]:
                if self.state[e] == ON:
                    seen_e.add(e)
                    a, b = self.edge_verts[e]
                    w = b if a == v else a
                    if w not in seen_v:
                        seen_v.add(w)
                        dq.append(w)
        return len(seen_e) == self.on_edges_count

    def choose_edge(self):
        # Most constrained unknown edge: prioritize those touching clue cells and high-degree vertices.
        best = None
        best_score = None
        for e in range(self.E):
            if self.state[e] != UNKNOWN:
                continue
            score = 0
            v1, v2 = self.edge_verts[e]
            score += 4 * (self.on_deg[v1] + self.on_deg[v2])
            score -= (self.unk_deg[v1] + self.unk_deg[v2])
            for r, c in self.edge_cells[e]:
                clue = self.data[r][c]
                if clue is not None:
                    need = clue - self.cell_on[r][c]
                    score += 6
                    score += 2 * abs(2 * need - self.cell_unk[r][c])
            if best is None or score > best_score:
                best = e
                best_score = score
        return best

    def branch_values(self, e):
        # Human-like preference:
        # If adjacent clues strongly need this edge, try ON first; otherwise OFF first.
        want_on = 0
        want_off = 0
        for r, c in self.edge_cells[e]:
            clue = self.data[r][c]
            if clue is None:
                continue
            on = self.cell_on[r][c]
            unk = self.cell_unk[r][c]
            need = clue - on
            if need == unk:
                want_on += 3
            if need == 0:
                want_off += 3
            if need > 0:
                want_on += 1
            else:
                want_off += 1
        v1, v2 = self.edge_verts[e]
        if self.on_deg[v1] == 1 or self.on_deg[v2] == 1:
            want_on += 1
        if self.on_deg[v1] == 2 or self.on_deg[v2] == 2:
            want_off += 4
        return [ON, OFF] if want_on >= want_off else [OFF, ON]

    def solve_search(self):
        if not self.propagate():
            return False
        if self.is_complete():
            return self.check_final()

        e = self.choose_edge()
        if e is None:
            return False

        for val in self.branch_values(e):
            snap = self.snapshot()
            self.reason_queue.append(('force', e, val))
            if self.solve_search():
                return True
            self.rollback(snap)
            self.reason_queue.clear()
        return False

    def extract_loop(self):
        adj = defaultdict(list)
        start = None
        for e, s in enumerate(self.state):
            if s == ON:
                v1, v2 = self.edge_verts[e]
                adj[v1].append(v2)
                adj[v2].append(v1)
                if start is None:
                    start = v1
        if start is None:
            return None

        path = []
        prev = None
        cur = start
        while True:
            r = cur // self.dot_cols
            c = cur % self.dot_cols
            path.append((r, c))
            nxts = adj[cur]
            if len(nxts) != 2:
                return None
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            prev, cur = cur, nxt
            if cur == start:
                path.append((start // self.dot_cols, start % self.dot_cols))
                break
        return path


def solve(observation):
    data = observation['data']
    solver = SlitherlinkSolver(data)
    ok = solver.solve_search()
    if not ok:
        return "No Solution"
    loop = solver.extract_loop()
    return str(loop) if loop is not None else "No Solution"


