from collections import deque

ALL_MASK_CACHE = {}

def bit(v):
    return 1 << (v - 1)

def mask_all(n):
    if n not in ALL_MASK_CACHE:
        ALL_MASK_CACHE[n] = (1 << n) - 1
    return ALL_MASK_CACHE[n]

def popcount(x):
    return x.bit_count()

def iter_values(mask, n):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length()
        mask ^= lsb

def mask_to_sorted_list(mask, n):
    return list(iter_values(mask, n))

def is_single(mask):
    return mask != 0 and (mask & (mask - 1)) == 0

def single_value(mask):
    return mask.bit_length()

def consecutive_mask_from(mask, n):
    # Values adjacent by +/-1 to any value in mask
    left = (mask << 1) & mask_all(n)
    right = mask >> 1
    return left | right

def nonconsecutive_mask_from(mask, n):
    return mask_all(n) & ~consecutive_mask_from(mask, n)

def build_edges(n, adjacent_coords):
    dotted = set()
    for a, b in adjacent_coords:
        if float(a).is_integer() and abs(b - int(b) - 0.5) < 1e-9:
            r = int(round(a))
            c = int(b - 0.5)
            if 0 <= r < n and 0 <= c < n - 1:
                x = (r, c)
                y = (r, c + 1)
                if x < y:
                    dotted.add((x, y))
                else:
                    dotted.add((y, x))
        elif float(b).is_integer() and abs(a - int(a) - 0.5) < 1e-9:
            r = int(a - 0.5)
            c = int(round(b))
            if 0 <= r < n - 1 and 0 <= c < n:
                x = (r, c)
                y = (r + 1, c)
                if x < y:
                    dotted.add((x, y))
                else:
                    dotted.add((y, x))
    neighbors = {}
    for r in range(n):
        for c in range(n):
            lst = []
            for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    a = (r, c)
                    b = (rr, cc)
                    key = (a, b) if a < b else (b, a)
                    lst.append((rr, cc, key in dotted))
            neighbors[(r, c)] = lst
    return dotted, neighbors

class Contradiction(Exception):
    pass

class State:
    __slots__ = ("n", "grid", "row_used", "col_used", "neighbors", "steps")
    def __init__(self, n, grid, row_used, col_used, neighbors):
        self.n = n
        self.grid = grid
        self.row_used = row_used
        self.col_used = col_used
        self.neighbors = neighbors
        self.steps = 0

    def clone(self):
        return State(
            self.n,
            [row[:] for row in self.grid],
            self.row_used[:],
            self.col_used[:],
            self.neighbors,
        )

def initialize(observation):
    data = observation["data"]
    n = len(data)
    _, neighbors = build_edges(n, observation["adjacent"])
    allm = mask_all(n)
    grid = [[allm for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    st = State(n, grid, row_used, col_used, neighbors)
    q = deque()

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    raise ValueError("Invalid clue value")
                q.append((r, c, bit(v)))

    propagate(st, q)
    return st

def assign(st, r, c, newmask, q):
    old = st.grid[r][c]
    if old == newmask:
        return
    if newmask == 0:
        raise Contradiction
    if old & newmask == 0:
        raise Contradiction
    if old != newmask:
        st.grid[r][c] = old & newmask
        q.append((r, c, st.grid[r][c]))

def remove_values(st, r, c, remmask, q):
    if remmask == 0:
        return
    old = st.grid[r][c]
    newmask = old & ~remmask
    if newmask != old:
        if newmask == 0:
            raise Contradiction
        st.grid[r][c] = newmask
        q.append((r, c, newmask))

def hidden_singles_unit(st, unit_cells, q):
    n = st.n
    counts = [0] * (n + 1)
    lastpos = [None] * (n + 1)
    for r, c in unit_cells:
        m = st.grid[r][c]
        for v in iter_values(m, n):
            counts[v] += 1
            lastpos[v] = (r, c)
    for v in range(1, n + 1):
        if counts[v] == 0:
            raise Contradiction
        if counts[v] == 1:
            r, c = lastpos[v]
            assign(st, r, c, bit(v), q)

def latin_line_bounds(st, idx, is_row, q):
    # Human-like interval pruning:
    # For each value v, track candidate positions where it can still appear in line.
    # Also if a cell sees row/col used values, its domain already excludes them.
    n = st.n
    positions = [[] for _ in range(n + 1)]
    cells = []
    if is_row:
        for c in range(n):
            cells.append((idx, c))
    else:
        for r in range(n):
            cells.append((r, idx))
    for pos, (r, c) in enumerate(cells):
        m = st.grid[r][c]
        for v in iter_values(m, n):
            positions[v].append(pos)
    for v in range(1, n + 1):
        if not positions[v]:
            raise Contradiction

def propagate(st, q=None):
    if q is None:
        q = deque((r, c, st.grid[r][c]) for r in range(st.n) for c in range(st.n))
    n = st.n
    allm = mask_all(n)
    in_queue_units = deque()
    touched_rows = set()
    touched_cols = set()

    while q or in_queue_units:
        while q:
            r, c, _ = q.popleft()
            st.steps += 1
            m = st.grid[r][c]
            if m == 0:
                raise Contradiction

            allowed = m & ~(st.row_used[r] | st.col_used[c])
            if allowed != m:
                if allowed == 0:
                    raise Contradiction
                st.grid[r][c] = allowed
                m = allowed

            if is_single(m):
                vbit = m
                if (st.row_used[r] & vbit) and data_value(st, r, c) != vbit:
                    pass
                if not (st.row_used[r] & vbit):
                    st.row_used[r] |= vbit
                    for cc in range(n):
                        if cc != c:
                            remove_values(st, r, cc, vbit, q)
                else:
                    for cc in range(n):
                        if cc != c and is_single(st.grid[r][cc]) and st.grid[r][cc] == vbit:
                            raise Contradiction
                if not (st.col_used[c] & vbit):
                    st.col_used[c] |= vbit
                    for rr in range(n):
                        if rr != r:
                            remove_values(st, rr, c, vbit, q)
                else:
                    for rr in range(n):
                        if rr != r and is_single(st.grid[rr][c]) and st.grid[rr][c] == vbit:
                            raise Contradiction

            # Kropki adjacency propagation
            m = st.grid[r][c]
            for rr, cc, dotted in st.neighbors[(r, c)]:
                nm = st.grid[rr][cc]
                if dotted:
                    allow_here = consecutive_mask_from(nm, n)
                    allow_there = consecutive_mask_from(m, n)
                else:
                    allow_here = nonconsecutive_mask_from(nm, n)
                    allow_there = nonconsecutive_mask_from(m, n)
                newm = m & allow_here
                if newm != m:
                    if newm == 0:
                        raise Contradiction
                    st.grid[r][c] = newm
                    m = newm
                newnm = nm & allow_there
                if newnm != nm:
                    if newnm == 0:
                        raise Contradiction
                    st.grid[rr][cc] = newnm
                    q.append((rr, cc, newnm))

            touched_rows.add(r)
            touched_cols.add(c)

        if touched_rows or touched_cols:
            rows = list(touched_rows)
            cols = list(touched_cols)
            touched_rows.clear()
            touched_cols.clear()

            for r in rows:
                unit = [(r, c) for c in range(n)]
                hidden_singles_unit(st, unit, q)
                latin_line_bounds(st, r, True, q)

            for c in cols:
                unit = [(r, c) for r in range(n)]
                hidden_singles_unit(st, unit, q)
                latin_line_bounds(st, c, False, q)

            # Dot-driven endpoint pruning:
            # 1 and N can only touch 2 / N-1 through dotted edges.
            edge_vals = bit(1) | bit(n)
            near_edge_vals = bit(2) | bit(n - 1) if n >= 2 else 0
            for r in rows:
                for c in range(n):
                    m = st.grid[r][c]
                    if m & edge_vals:
                        dotted_nbrs = [(rr, cc) for rr, cc, d in st.neighbors[(r, c)] if d]
                        if not dotted_nbrs:
                            remove_values(st, r, c, edge_vals, q)
                        else:
                            possible = 0
                            for rr, cc in dotted_nbrs:
                                possible |= st.grid[rr][cc]
                            if not (possible & near_edge_vals):
                                remove_values(st, r, c, edge_vals, q)
            for c in cols:
                for r in range(n):
                    m = st.grid[r][c]
                    if m & edge_vals:
                        dotted_nbrs = [(rr, cc) for rr, cc, d in st.neighbors[(r, c)] if d]
                        if not dotted_nbrs:
                            remove_values(st, r, c, edge_vals, q)
                        else:
                            possible = 0
                            for rr, cc in dotted_nbrs:
                                possible |= st.grid[rr][cc]
                            if not (possible & near_edge_vals):
                                remove_values(st, r, c, edge_vals, q)

    # Final consistency for solved duplicates
    for r in range(n):
        seen = 0
        for c in range(n):
            m = st.grid[r][c]
            if is_single(m):
                if seen & m:
                    raise Contradiction
                seen |= m
    for c in range(n):
        seen = 0
        for r in range(n):
            m = st.grid[r][c]
            if is_single(m):
                if seen & m:
                    raise Contradiction
                seen |= m

def data_value(st, r, c):
    return st.grid[r][c]

def solved(st):
    n = st.n
    full = mask_all(n)
    for r in range(n):
        acc = 0
        for c in range(n):
            m = st.grid[r][c]
            if not is_single(m):
                return False
            acc |= m
        if acc != full:
            return False
    for c in range(n):
        acc = 0
        for r in range(n):
            acc |= st.grid[r][c]
        if acc != full:
            return False
    return True

def choose_branch_cell(st):
    n = st.n
    best = None
    best_score = None
    for r in range(n):
        row_missing = n - popcount(st.row_used[r])
        for c in range(n):
            m = st.grid[r][c]
            pc = popcount(m)
            if pc <= 1:
                continue
            # Human-like heuristic:
            # prefer tightest domain, more constrained by neighbors and row/col occupancy
            dot_degree = sum(1 for _, _, d in st.neighbors[(r, c)] if d)
            score = (pc, -dot_degree, row_missing + (n - popcount(st.col_used[c])))
            if best_score is None or score < best_score:
                best_score = score
                best = (r, c)
    return best

def order_values(st, r, c):
    n = st.n
    m = st.grid[r][c]
    vals = []
    for v in iter_values(m, n):
        vb = bit(v)
        impact = 0
        # prefer values that constrain dotted/non-dotted neighbors strongly
        for rr, cc, dotted in st.neighbors[(r, c)]:
            nm = st.grid[rr][cc]
            if dotted:
                allowed = consecutive_mask_from(vb, n)
            else:
                allowed = nonconsecutive_mask_from(vb, n)
            impact += popcount(nm) - popcount(nm & allowed)
        vals.append((-impact, v))
    vals.sort()
    return [v for _, v in vals]

def search(st):
    if solved(st):
        return st
    cell = choose_branch_cell(st)
    if cell is None:
        return None
    r, c = cell
    for v in order_values(st, r, c):
        child = st.clone()
        q = deque()
        try:
            assign(child, r, c, bit(v), q)
            propagate(child, q)
            ans = search(child)
            if ans is not None:
                return ans
        except Contradiction:
            continue
    return None

def solve(observation):
    try:
        st = initialize(observation)
        res = search(st)
        if res is None:
            return "No Solution"
        out = []
        for r in range(res.n):
            out.append([single_value(res.grid[r][c]) for c in range(res.n)])
        return str(out)
    except Exception:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, 3, 6, 9, None], [None, None, None, None, None, 2, 4, None, 5], [None, None, 4, None, None, 9, None, 2, 1], [None, None, None, None, None, 7, 5, 6, 9], [None, None, None, None, 2, None, None, None, None], [9, 8, 5, 6, None, None, None, None, None], [2, 9, None, 3, None, None, 7, None, None], [6, None, 3, 5, None, None, None, None, None], [None, 4, 8, 2, None, None, None, None, None]], 'unit': '3x3'}

# Generalized Sudoku solver using human-like logical deduction first,
# then tightly-pruned search only when deduction stalls.

def solve(observation):
    data = observation['data']
    unit = observation['unit']
    if 'x' in unit:
        br, bc = map(int, unit.split('x'))
    else:
        br = bc = int(unit)
    n = len(data)
    if br * bc != n:
        return "No Solution"

    digits = tuple(range(1, n + 1))
    all_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        while mask:
            lsb = mask & -mask
            vals.append(lsb.bit_length())
            mask ^= lsb
        return vals

    def popcount(x):
        return x.bit_count()

    rows = [list(range(r * n, (r + 1) * n)) for r in range(n)]
    cols = [list(range(c, n * n, n)) for c in range(n)]
    boxes = []
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            box = []
            for r in range(r0, r0 + br):
                base = r * n
                for c in range(c0, c0 + bc):
                    box.append(base + c)
            boxes.append(box)

    cell_to_row = [0] * (n * n)
    cell_to_col = [0] * (n * n)
    cell_to_box = [0] * (n * n)

    for r in range(n):
        for c in range(n):
            idx = r * n + c
            cell_to_row[idx] = r
            cell_to_col[idx] = c
            cell_to_box[idx] = (r // br) * (n // bc) + (c // bc)

    units = [None] * (3 * n)
    for i in range(n):
        units[i] = rows[i]
        units[n + i] = cols[i]
        units[2 * n + i] = boxes[i]

    cell_units = [[] for _ in range(n * n)]
    for idx in range(n * n):
        cell_units[idx] = [cell_to_row[idx], n + cell_to_col[idx], 2 * n + cell_to_box[idx]]

    peers = [None] * (n * n)
    for idx in range(n * n):
        s = set()
        for u in cell_units[idx]:
            s.update(units[u])
        s.discard(idx)
        peers[idx] = tuple(s)

    values = [0] * (n * n)
    row_used = [0] * n
    col_used = [0] * n
    box_used = [0] * n

    for r in range(n):
        if len(data[r]) != n:
            return "No Solution"
        for c in range(n):
            v = data[r][c]
            idx = r * n + c
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            m = bit(v)
            b = cell_to_box[idx]
            if (row_used[r] & m) or (col_used[c] & m) or (box_used[b] & m):
                return "No Solution"
            values[idx] = v
            row_used[r] |= m
            col_used[c] |= m
            box_used[b] |= m

    candidates = [0] * (n * n)
    for idx in range(n * n):
        if values[idx]:
            candidates[idx] = bit(values[idx])
        else:
            r = cell_to_row[idx]
            c = cell_to_col[idx]
            b = cell_to_box[idx]
            mask = all_mask & ~(row_used[r] | col_used[c] | box_used[b])
            if mask == 0:
                return "No Solution"
            candidates[idx] = mask

    def assign(state, idx, v):
        values, candidates, row_used, col_used, box_used = state
        old = values[idx]
        if old == v:
            return True
        if old != 0:
            return False
        m = bit(v)
        if not (candidates[idx] & m):
            return False
        r = cell_to_row[idx]
        c = cell_to_col[idx]
        b = cell_to_box[idx]
        if (row_used[r] & m) or (col_used[c] & m) or (box_used[b] & m):
            return False
        values[idx] = v
        candidates[idx] = m
        row_used[r] |= m
        col_used[c] |= m
        box_used[b] |= m
        for p in peers[idx]:
            if values[p] == 0 and (candidates[p] & m):
                nm = candidates[p] & ~m
                if nm == 0:
                    return False
                candidates[p] = nm
        return True

    def eliminate_from_peers_singletons(state):
        values, candidates, row_used, col_used, box_used = state
        changed = False
        progress = True
        while progress:
            progress = False
            for idx in range(n * n):
                if values[idx] == 0:
                    mask = candidates[idx]
                    if mask == 0:
                        return None
                    if mask & (mask - 1) == 0:
                        v = mask.bit_length()
                        if not assign(state, idx, v):
                            return None
                        changed = True
                        progress = True
        return changed

    def hidden_singles(state):
        values, candidates, row_used, col_used, box_used = state
        changed = False
        for unit_cells in units:
            pos = [0] * n
            cnt = [0] * n
            for idx in unit_cells:
                if values[idx] == 0:
                    mask = candidates[idx]
                    mm = mask
                    while mm:
                        lsb = mm & -mm
                        d = lsb.bit_length() - 1
                        cnt[d] += 1
                        pos[d] = idx
                        mm ^= lsb
            for d in range(n):
                if cnt[d] == 1:
                    if not assign(state, pos[d], d + 1):
                        return None
                    changed = True
        return changed

    def naked_subsets(state, subset_size):
        values, candidates, row_used, col_used, box_used = state
        changed = False
        for unit_cells in units:
            groups = {}
            unsolved = []
            for idx in unit_cells:
                if values[idx] == 0:
                    mask = candidates[idx]
                    pc = popcount(mask)
                    if 2 <= pc <= subset_size:
                        groups.setdefault(mask, []).append(idx)
                    unsolved.append(idx)
            for mask, cells in groups.items():
                if popcount(mask) == subset_size and len(cells) == subset_size:
                    for idx in unsolved:
                        if idx not in cells:
                            nm = candidates[idx] & ~mask
                            if nm != candidates[idx]:
                                if nm == 0:
                                    return None
                                candidates[idx] = nm
                                changed = True
        return changed

    def hidden_subsets(state, subset_size):
        values, candidates, row_used, col_used, box_used = state
        changed = False
        from itertools import combinations
        for unit_cells in units:
            digit_cells = []
            active_digits = []
            for d in range(1, n + 1):
                m = bit(d)
                cells = [idx for idx in unit_cells if values[idx] == 0 and (candidates[idx] & m)]
                if 1 <= len(cells) <= subset_size:
                    active_digits.append(d)
                    digit_cells.append(set(cells))
            if len(active_digits) < subset_size:
                continue
            for comb in combinations(range(len(active_digits)), subset_size):
                union = set()
                for i in comb:
                    union |= digit_cells[i]
                if len(union) != subset_size:
                    continue
                dmask = 0
                for i in comb:
                    dmask |= bit(active_digits[i])
                for idx in union:
                    nm = candidates[idx] & dmask
                    if nm != candidates[idx]:
                        if nm == 0:
                            return None
                        candidates[idx] = nm
                        changed = True
        return changed

    def pointing_and_claiming(state):
        values, candidates, row_used, col_used, box_used = state
        changed = False

        # Pointing pairs/triples: within a box, a digit confined to one row/col.
        for b, box_cells in enumerate(boxes):
            for d in range(1, n + 1):
                m = bit(d)
                cells = [idx for idx in box_cells if values[idx] == 0 and (candidates[idx] & m)]
                if len(cells) <= 1:
                    continue
                rs = {cell_to_row[idx] for idx in cells}
                if len(rs) == 1:
                    r = next(iter(rs))
                    for idx in rows[r]:
                        if cell_to_box[idx] != b and values[idx] == 0 and (candidates[idx] & m):
                            nm = candidates[idx] & ~m
                            if nm == 0:
                                return None
                            if nm != candidates[idx]:
                                candidates[idx] = nm
                                changed = True
                cs = {cell_to_col[idx] for idx in cells}
                if len(cs) == 1:
                    c = next(iter(cs))
                    for idx in cols[c]:
                        if cell_to_box[idx] != b and values[idx] == 0 and (candidates[idx] & m):
                            nm = candidates[idx] & ~m
                            if nm == 0:
                                return None
                            if nm != candidates[idx]:
                                candidates[idx] = nm
                                changed = True

        # Claiming: within a row/col, a digit confined to one box.
        for r, row_cells in enumerate(rows):
            for d in range(1, n + 1):
                m = bit(d)
                cells = [idx for idx in row_cells if values[idx] == 0 and (candidates[idx] & m)]
                if len(cells) > 1:
                    bs = {cell_to_box[idx] for idx in cells}
                    if len(bs) == 1:
                        b = next(iter(bs))
                        for idx in boxes[b]:
                            if cell_to_row[idx] != r and values[idx] == 0 and (candidates[idx] & m):
                                nm = candidates[idx] & ~m
                                if nm == 0:
                                    return None
                                if nm != candidates[idx]:
                                    candidates[idx] = nm
                                    changed = True

        for c, col_cells in enumerate(cols):
            for d in range(1, n + 1):
                m = bit(d)
                cells = [idx for idx in col_cells if values[idx] == 0 and (candidates[idx] & m)]
                if len(cells) > 1:
                    bs = {cell_to_box[idx] for idx in cells}
                    if len(bs) == 1:
                        b = next(iter(bs))
                        for idx in boxes[b]:
                            if cell_to_col[idx] != c and values[idx] == 0 and (candidates[idx] & m):
                                nm = candidates[idx] & ~m
                                if nm == 0:
                                    return None
                                if nm != candidates[idx]:
                                    candidates[idx] = nm
                                    changed = True
        return changed

    def x_wing(state):
        values, candidates, row_used, col_used, box_used = state
        changed = False
        for d in range(1, n + 1):
            m = bit(d)

            row_patterns = {}
            for r in range(n):
                cols_with_d = [c for c in range(n) if values[r * n + c] == 0 and (candidates[r * n + c] & m)]
                if len(cols_with_d) == 2:
                    row_patterns.setdefault(tuple(cols_with_d), []).append(r)
            for cols_pair, rs in row_patterns.items():
                if len(rs) >= 2:
                    for i in range(len(rs)):
                        for j in range(i + 1, len(rs)):
                            r1, r2 = rs[i], rs[j]
                            c1, c2 = cols_pair
                            for r in range(n):
                                if r != r1 and r != r2:
                                    for c in (c1, c2):
                                        idx = r * n + c
                                        if values[idx] == 0 and (candidates[idx] & m):
                                            nm = candidates[idx] & ~m
                                            if nm == 0:
                                                return None
                                            if nm != candidates[idx]:
                                                candidates[idx] = nm
                                                changed = True

            col_patterns = {}
            for c in range(n):
                rows_with_d = [r for r in range(n) if values[r * n + c] == 0 and (candidates[r * n + c] & m)]
                if len(rows_with_d) == 2:
                    col_patterns.setdefault(tuple(rows_with_d), []).append(c)
            for rows_pair, cs in col_patterns.items():
                if len(cs) >= 2:
                    for i in range(len(cs)):
                        for j in range(i + 1, len(cs)):
                            c1, c2 = cs[i], cs[j]
                            r1, r2 = rows_pair
                            for c in range(n):
                                if c != c1 and c != c2:
                                    for r in (r1, r2):
                                        idx = r * n + c
                                        if values[idx] == 0 and (candidates[idx] & m):
                                            nm = candidates[idx] & ~m
                                            if nm == 0:
                                                return None
                                            if nm != candidates[idx]:
                                                candidates[idx] = nm
                                                changed = True
        return changed

    def validate(state):
        values, candidates, row_used, col_used, box_used = state
        for idx in range(n * n):
            if values[idx] == 0 and candidates[idx] == 0:
                return False
        for unit_cells in units:
            present = 0
            missing = all_mask
            for idx in unit_cells:
                if values[idx]:
                    present |= bit(values[idx])
            missing &= ~present
            mm = missing
            while mm:
                lsb = mm & -mm
                found = False
                for idx in unit_cells:
                    if values[idx] == 0 and (candidates[idx] & lsb):
                        found = True
                        break
                if not found:
                    return False
                mm ^= lsb
        return True

    def propagate(state):
        while True:
            any_change = False

            res = eliminate_from_peers_singletons(state)
            if res is None:
                return False
            any_change |= res

            res = hidden_singles(state)
            if res is None:
                return False
            any_change |= res

            res = pointing_and_claiming(state)
            if res is None:
                return False
            any_change |= res

            res = naked_subsets(state, 2)
            if res is None:
                return False
            any_change |= res

            res = naked_subsets(state, 3)
            if res is None:
                return False
            any_change |= res

            res = hidden_subsets(state, 2)
            if res is None:
                return False
            any_change |= res

            res = hidden_subsets(state, 3)
            if res is None:
                return False
            any_change |= res

            res = x_wing(state)
            if res is None:
                return False
            any_change |= res

            if not validate(state):
                return False

            if not any_change:
                return True

    def solved(state):
        values = state[0]
        return all(v != 0 for v in values)

    def clone_state(state):
        values, candidates, row_used, col_used, box_used = state
        return [values[:], candidates[:], row_used[:], col_used[:], box_used[:]]

    def choose_cell(state):
        values, candidates = state[0], state[1]
        best_idx = -1
        best_count = n + 1
        best_score = -1
        for idx in range(n * n):
            if values[idx] == 0:
                cnt = popcount(candidates[idx])
                if cnt < best_count:
                    best_count = cnt
                    best_idx = idx
                    best_score = sum(1 for p in peers[idx] if values[p] == 0)
                    if cnt == 2:
                        continue
                elif cnt == best_count:
                    score = sum(1 for p in peers[idx] if values[p] == 0)
                    if score > best_score:
                        best_idx = idx
                        best_score = score
        return best_idx

    def search(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        idx = choose_cell(state)
        if idx < 0:
            return None

        mask = state[1][idx]
        options = mask_to_values(mask)

        def impact(v):
            m = bit(v)
            score = 0
            for p in peers[idx]:
                if state[0][p] == 0 and (state[1][p] & m):
                    score += 1
            return -score

        options.sort(key=impact)

        for v in options:
            new_state = clone_state(state)
            if assign(new_state, idx, v):
                result = search(new_state)
                if result is not None:
                    return result
        return None

    state = [values[:], candidates[:], row_used[:], col_used[:], box_used[:]]
    result = search(state)
    if result is None:
        return "No Solution"

    out_values = result[0]
    grid = []
    for r in range(n):
        grid.append(out_values[r * n:(r + 1) * n])
    return str(grid)

