# Generalized Sudoku solver with human-like deduction first, then tightly pruned search.
# Supports NxN Sudoku where N = box_rows * box_cols, e.g. 9x9 (3x3), 12x12 (3x4), 16x16 (4x4).

def solve(observation):
    data = observation['data']
    unit = observation['unit']
    if 'x' in unit:
        br, bc = map(int, unit.split('x'))
    else:
        br = bc = int(unit)
    n = len(data)
    if br * bc != n:
        return "No Solution"

    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def box_index(r, c):
        return (r // br) * (n // bc) + (c // bc)

    rows = [0] * n
    cols = [0] * n
    boxes = [0] * n
    grid = [[0] * n for _ in range(n)]
    empties = []

    for r in range(n):
        if len(data[r]) != n:
            return "No Solution"
        for c in range(n):
            v = data[r][c]
            if v is None:
                empties.append((r, c))
            else:
                if not (1 <= v <= n):
                    return "No Solution"
                b = bit(v)
                bi = box_index(r, c)
                if (rows[r] & b) or (cols[c] & b) or (boxes[bi] & b):
                    return "No Solution"
                rows[r] |= b
                cols[c] |= b
                boxes[bi] |= b
                grid[r][c] = v

    peers = {}
    units_of_cell = {}
    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]
    box_cells = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            bi = box_index(r, c)
            box_cells[bi].append((r, c))
    for r in range(n):
        for c in range(n):
            bi = box_index(r, c)
            units = [row_cells[r], col_cells[c], box_cells[bi]]
            units_of_cell[(r, c)] = units
            s = set()
            for u in units:
                s.update(u)
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    cand = [[0] * n for _ in range(n)]

    def avail_mask(r, c):
        return full_mask & ~(rows[r] | cols[c] | boxes[box_index(r, c)])

    def popcount(x):
        return x.bit_count()

    def lowest_bit(x):
        return x & -x

    def bit_to_value(b):
        return b.bit_length()

    for r, c in empties:
        m = avail_mask(r, c)
        if m == 0:
            return "No Solution"
        cand[r][c] = m

    assigned_stack = []

    def assign(r, c, v):
        if grid[r][c] == v:
            return True
        if grid[r][c] != 0:
            return False
        b = bit(v)
        bi = box_index(r, c)
        if (rows[r] & b) or (cols[c] & b) or (boxes[bi] & b):
            return False

        assigned_stack.append((r, c, 0, cand[r][c]))
        grid[r][c] = v
        rows[r] |= b
        cols[c] |= b
        boxes[bi] |= b
        cand[r][c] = 0

        for pr, pc in peers[(r, c)]:
            if grid[pr][pc] == 0:
                old = cand[pr][pc]
                new = old & ~b
                if new != old:
                    assigned_stack.append((pr, pc, old, None))
                    cand[pr][pc] = new
                    if new == 0:
                        return False
        return True

    def mark():
        return len(assigned_stack), [row[:] for row in grid], rows[:], cols[:], boxes[:]

    def rollback(state):
        stack_len, g, rs, cs, bs = state
        while len(assigned_stack) > stack_len:
            assigned_stack.pop()
        for r in range(n):
            grid[r] = g[r][:]
        for i in range(n):
            rows[i] = rs[i]
            cols[i] = cs[i]
            boxes[i] = bs[i]
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    cand[r][c] = avail_mask(r, c)
                else:
                    cand[r][c] = 0

    def place_masked_values():
        progress = False
        changed = True
        while changed:
            changed = False

            # Naked singles
            singles = []
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == 0:
                        m = cand[r][c]
                        if m == 0:
                            return None
                        if m & (m - 1) == 0:
                            singles.append((r, c, bit_to_value(m)))
            if singles:
                changed = True
                progress = True
                for r, c, v in singles:
                    if grid[r][c] == 0 and not assign(r, c, v):
                        return None
                continue

            # Hidden singles in rows
            for r in range(n):
                need = full_mask & ~rows[r]
                x = need
                while x:
                    b = lowest_bit(x)
                    x ^= b
                    found = None
                    count = 0
                    for c in range(n):
                        if grid[r][c] == 0 and (cand[r][c] & b):
                            count += 1
                            found = c
                            if count > 1:
                                break
                    if count == 0:
                        return None
                    if count == 1:
                        changed = True
                        progress = True
                        if not assign(r, found, bit_to_value(b)):
                            return None

            # Hidden singles in columns
            for c in range(n):
                need = full_mask & ~cols[c]
                x = need
                while x:
                    b = lowest_bit(x)
                    x ^= b
                    found = None
                    count = 0
                    for r in range(n):
                        if grid[r][c] == 0 and (cand[r][c] & b):
                            count += 1
                            found = r
                            if count > 1:
                                break
                    if count == 0:
                        return None
                    if count == 1:
                        changed = True
                        progress = True
                        if not assign(found, c, bit_to_value(b)):
                            return None

            # Hidden singles in boxes
            for bi in range(n):
                need = full_mask & ~boxes[bi]
                x = need
                cells = box_cells[bi]
                while x:
                    b = lowest_bit(x)
                    x ^= b
                    found = None
                    count = 0
                    for r, c in cells:
                        if grid[r][c] == 0 and (cand[r][c] & b):
                            count += 1
                            found = (r, c)
                            if count > 1:
                                break
                    if count == 0:
                        return None
                    if count == 1:
                        changed = True
                        progress = True
                        if not assign(found[0], found[1], bit_to_value(b)):
                            return None

            # Locked candidates: box -> row/col
            for bi in range(n):
                rs = (bi // (n // bc)) * br
                cs = (bi % (n // bc)) * bc
                need = full_mask & ~boxes[bi]
                x = need
                while x:
                    b = lowest_bit(x)
                    x ^= b
                    positions = []
                    for r in range(rs, rs + br):
                        for c in range(cs, cs + bc):
                            if grid[r][c] == 0 and (cand[r][c] & b):
                                positions.append((r, c))
                    if not positions:
                        return None
                    same_row = all(r == positions[0][0] for r, _ in positions)
                    if same_row:
                        rr = positions[0][0]
                        for c in range(n):
                            if not (cs <= c < cs + bc) and grid[rr][c] == 0 and (cand[rr][c] & b):
                                old = cand[rr][c]
                                new = old & ~b
                                if new == 0:
                                    return None
                                if new != old:
                                    cand[rr][c] = new
                                    changed = True
                                    progress = True
                    same_col = all(c == positions[0][1] for _, c in positions)
                    if same_col:
                        cc = positions[0][1]
                        for r in range(n):
                            if not (rs <= r < rs + br) and grid[r][cc] == 0 and (cand[r][cc] & b):
                                old = cand[r][cc]
                                new = old & ~b
                                if new == 0:
                                    return None
                                if new != old:
                                    cand[r][cc] = new
                                    changed = True
                                    progress = True

            # Locked candidates: row/col -> box
            for r in range(n):
                need = full_mask & ~rows[r]
                x = need
                while x:
                    b = lowest_bit(x)
                    x ^= b
                    positions = [c for c in range(n) if grid[r][c] == 0 and (cand[r][c] & b)]
                    if not positions:
                        return None
                    first_bi = box_index(r, positions[0])
                    if all(box_index(r, c) == first_bi for c in positions):
                        rs = (first_bi // (n // bc)) * br
                        cs = (first_bi % (n // bc)) * bc
                        for rr in range(rs, rs + br):
                            for cc in range(cs, cs + bc):
                                if rr != r and grid[rr][cc] == 0 and (cand[rr][cc] & b):
                                    old = cand[rr][cc]
                                    new = old & ~b
                                    if new == 0:
                                        return None
                                    if new != old:
                                        cand[rr][cc] = new
                                        changed = True
                                        progress = True

            for c in range(n):
                need = full_mask & ~cols[c]
                x = need
                while x:
                    b = lowest_bit(x)
                    x ^= b
                    positions = [r for r in range(n) if grid[r][c] == 0 and (cand[r][c] & b)]
                    if not positions:
                        return None
                    first_bi = box_index(positions[0], c)
                    if all(box_index(r, c) == first_bi for r in positions):
                        rs = (first_bi // (n // bc)) * br
                        cs = (first_bi % (n // bc)) * bc
                        for rr in range(rs, rs + br):
                            for cc in range(cs, cs + bc):
                                if cc != c and grid[rr][cc] == 0 and (cand[rr][cc] & b):
                                    old = cand[rr][cc]
                                    new = old & ~b
                                    if new == 0:
                                        return None
                                    if new != old:
                                        cand[rr][cc] = new
                                        changed = True
                                        progress = True

            # Naked pairs/triples in units
            for unit_cells in row_cells + col_cells + box_cells:
                sig = {}
                for r, c in unit_cells:
                    if grid[r][c] == 0:
                        m = cand[r][c]
                        pc = popcount(m)
                        if 2 <= pc <= 3:
                            sig.setdefault(m, []).append((r, c))
                for m, cells in sig.items():
                    k = popcount(m)
                    if len(cells) == k:
                        for r, c in unit_cells:
                            if grid[r][c] == 0 and (r, c) not in cells:
                                old = cand[r][c]
                                new = old & ~m
                                if new == 0:
                                    return None
                                if new != old:
                                    cand[r][c] = new
                                    changed = True
                                    progress = True

            # Hidden pairs in units
            for unit_cells in row_cells + col_cells + box_cells:
                places = {}
                for d in range(1, n + 1):
                    b = bit(d)
                    positions = []
                    for r, c in unit_cells:
                        if grid[r][c] == 0 and (cand[r][c] & b):
                            positions.append((r, c))
                    if 1 <= len(positions) <= 2:
                        places[b] = tuple(positions)
                    elif len(positions) == 0:
                        used = False
                        for r, c in unit_cells:
                            if grid[r][c] == d:
                                used = True
                                break
                        if not used:
                            return None
                items = list(places.items())
                for i in range(len(items)):
                    b1, p1 = items[i]
                    if len(p1) != 2:
                        continue
                    for j in range(i + 1, len(items)):
                        b2, p2 = items[j]
                        if p1 == p2 and len(p2) == 2:
                            pair_mask = b1 | b2
                            for r, c in p1:
                                old = cand[r][c]
                                new = old & pair_mask
                                if new == 0:
                                    return None
                                if new != old:
                                    cand[r][c] = new
                                    changed = True
                                    progress = True

        return progress

    def solved():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    def choose_cell():
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    m = cand[r][c]
                    pc = popcount(m)
                    if pc == 0:
                        return None
                    peer_pressure = 0
                    for pr, pc2 in peers[(r, c)]:
                        if grid[pr][pc2] == 0:
                            peer_pressure += 1
                    score = (pc, -peer_pressure)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
                        if pc == 2:
                            return best
        return best

    def search():
        if place_masked_values() is None:
            return False
        if solved():
            return True

        cell = choose_cell()
        if cell is None:
            return False
        r, c = cell
        m = cand[r][c]

        # Least-constraining-value order
        options = []
        x = m
        while x:
            b = lowest_bit(x)
            x ^= b
            v = bit_to_value(b)
            impact = 0
            for pr, pc in peers[(r, c)]:
                if grid[pr][pc] == 0 and (cand[pr][pc] & b):
                    impact += 1
            options.append((impact, v))
        options.sort()

        state = mark()
        for _, v in options:
            rollback(state)
            if assign(r, c, v) and search():
                return True
        rollback(state)
        return False

    if search():
        return str(grid)
    return "No Solution"


