# General solver for the weighted black-cell puzzle.
# Interpretation used:
# - Grid size is R x C where R=len(row_sum), C=len(col_sum)
# - Row weights are 1..R from top to bottom
# - Column weights are 1..C from left to right
# - If cell (r,c) is black, it contributes (c+1) to row r target and (r+1) to column c target

from itertools import product

def bits_of(mask, n):
    i = 0
    while i < n:
        if (mask >> i) & 1:
            yield i
        i += 1

def mask_sum_by_weights(mask, weights):
    s = 0
    i = 0
    n = len(weights)
    while i < n:
        if (mask >> i) & 1:
            s += weights[i]
        i += 1
    return s

def possible_masks_for_sum(weights, target):
    n = len(weights)
    out = []
    for mask in range(1 << n):
        if mask_sum_by_weights(mask, weights) == target:
            out.append(mask)
    return out

def minmax_possible_sum_from_domains(col_domains, row_weights):
    c = len(col_domains)
    min_sum = 0
    max_sum = 0
    for j in range(c):
        w = row_weights
        d = col_domains[j]
        has0 = False
        has1 = False
        for v in d:
            if v == 0:
                has0 = True
            else:
                has1 = True
            if has0 and has1:
                break
        if has1 and not has0:
            min_sum += w
            max_sum += w
        elif has0 and has1:
            max_sum += w
    return min_sum, max_sum

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)

    row_weights = [r + 1 for r in range(R)]
    col_weights = [c + 1 for c in range(C)]

    # Human-like first step: generate all feasible row patterns by row target.
    row_candidates = []
    for r in range(R):
        cands = possible_masks_for_sum(col_weights, row_sum[r])
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    # Column domains are sets of possible values per cell before propagation.
    # domain[r][c] in {0,1}; represented column-wise for stronger weighted propagation.
    col_domains = [[0, 1] for _ in range(C * R)]

    def idx(r, c):
        return c * R + r

    # Maintain current row candidate lists and per-cell domains.
    row_cands = [list(cands) for cands in row_candidates]
    domains = [[0, 1] for _ in range(C * R)]

    def restrict_cell(r, c, allowed):
        d = domains[idx(r, c)]
        nd = []
        for v in d:
            if v in allowed:
                nd.append(v)
        if not nd:
            return False, False
        changed = len(nd) != len(d)
        if changed:
            domains[idx(r, c)] = nd
        return True, changed

    def propagate():
        # Repeatedly:
        # 1) prune row candidates by current cell domains
        # 2) infer fixed/impossible cells from row candidates
        # 3) prune via column weighted min/max and subset-achievability
        changed_any = True
        while changed_any:
            changed_any = False

            # Row candidate filtering
            for r in range(R):
                filtered = []
                for mask in row_cands[r]:
                    ok = True
                    for c in range(C):
                        bit = (mask >> c) & 1
                        if bit not in domains[idx(r, c)]:
                            ok = False
                            break
                    if ok:
                        filtered.append(mask)
                if not filtered:
                    return False
                if len(filtered) != len(row_cands[r]):
                    row_cands[r] = filtered
                    changed_any = True

                # Cell fixing from row candidates
                all1 = (1 << C) - 1
                and_mask = all1
                or_mask = 0
                for m in row_cands[r]:
                    and_mask &= m
                    or_mask |= m
                for c in range(C):
                    must1 = (and_mask >> c) & 1
                    can1 = (or_mask >> c) & 1
                    if must1:
                        ok, ch = restrict_cell(r, c, {1})
                        if not ok:
                            return False
                        changed_any |= ch
                    elif not can1:
                        ok, ch = restrict_cell(r, c, {0})
                        if not ok:
                            return False
                        changed_any |= ch

            # Column weighted feasibility
            for c in range(C):
                target = col_sum[c]
                min_s = 0
                max_s = 0
                unknown_rows = []
                forced1_rows = []
                for r in range(R):
                    d = domains[idx(r, c)]
                    w = row_weights[r]
                    has0 = 0 in d
                    has1 = 1 in d
                    if has1 and not has0:
                        min_s += w
                        max_s += w
                        forced1_rows.append(r)
                    elif has0 and has1:
                        max_s += w
                        unknown_rows.append(r)

                if target < min_s or target > max_s:
                    return False

                rem = target - min_s
                # Determine which unknown rows can be 1 in some subset summing to rem,
                # and which can be 0 in some subset summing to rem.
                # Since weights are small and structured, subset DP is fast.
                k = len(unknown_rows)
                reachable = {0}
                pref = [None] * (k + 1)
                pref[0] = {0}
                for i in range(k):
                    w = row_weights[unknown_rows[i]]
                    newset = set(pref[i])
                    for s in pref[i]:
                        ns = s + w
                        if ns <= rem:
                            newset.add(ns)
                    pref[i + 1] = newset
                if rem not in pref[k]:
                    return False

                suff = [None] * (k + 1)
                suff[k] = {0}
                i = k - 1
                while i >= 0:
                    w = row_weights[unknown_rows[i]]
                    newset = set(suff[i + 1])
                    for s in suff[i + 1]:
                        ns = s + w
                        if ns <= rem:
                            newset.add(ns)
                    suff[i] = newset
                    i -= 1

                for i in range(k):
                    r = unknown_rows[i]
                    w = row_weights[r]
                    can0 = False
                    can1 = False

                    # check if some sum x from prefix and y from suffix gives rem with this row 0
                    # and similarly rem-w with this row 1
                    left = pref[i]
                    right = suff[i + 1]

                    # can0
                    for x in left:
                        need = rem - x
                        if need in right:
                            can0 = True
                            break

                    # can1
                    if rem >= w:
                        for x in left:
                            need = rem - w - x
                            if need in right:
                                can1 = True
                                break

                    allowed = set()
                    if can0:
                        allowed.add(0)
                    if can1:
                        allowed.add(1)
                    if not allowed:
                        return False
                    ok, ch = restrict_cell(r, c, allowed)
                    if not ok:
                        return False
                    changed_any |= ch

        return True

    def choose_row():
        # Minimum remaining values heuristic on rows; this mirrors choosing the most constrained line.
        best_r = -1
        best_len = 10**9
        for r in range(R):
            n = len(row_cands[r])
            if n > 1 and n < best_len:
                best_len = n
                best_r = r
        return best_r

    def snapshot():
        return (
            [list(cands) for cands in row_cands],
            [list(d) for d in domains],
        )

    def restore(state):
        rc, dm = state
        for i in range(R):
            row_cands[i] = rc[i]
        for i in range(R * C):
            domains[i] = dm[i]

    def dfs():
        if not propagate():
            return None

        done = True
        for r in range(R):
            if len(row_cands[r]) != 1:
                done = False
                break
        if done:
            # Final verification
            grid = [[0] * C for _ in range(R)]
            for r in range(R):
                mask = row_cands[r][0]
                rs = 0
                for c in range(C):
                    v = (mask >> c) & 1
                    grid[r][c] = v
                    if v:
                        rs += c + 1
                if rs != row_sum[r]:
                    return None
            for c in range(C):
                cs = 0
                for r in range(R):
                    if grid[r][c]:
                        cs += r + 1
                if cs != col_sum[c]:
                    return None
            return grid

        r = choose_row()
        cands = row_cands[r]

        # Better branch ordering: prefer candidates that satisfy more currently-forced column cells.
        scored = []
        for m in cands:
            score = 0
            for c in range(C):
                d = domains[idx(r, c)]
                bit = (m >> c) & 1
                if len(d) == 1 and bit == d[0]:
                    score += 2
                elif bit in d:
                    score += 1
            scored.append((score, m))
        scored.sort(reverse=True)

        for _, m in scored:
            st = snapshot()
            row_cands[r] = [m]
            ok = True
            for c in range(C):
                bit = (m >> c) & 1
                ok2, _ = restrict_cell(r, c, {bit})
                if not ok2:
                    ok = False
                    break
            if ok:
                ans = dfs()
                if ans is not None:
                    return ans
            restore(st)
        return None

    ans = dfs()
    if ans is None:
        return "No Solution"

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if ans[r][c] else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [11, 1, 8, 4, 3, 1], 'col_sum': [8, 4, 5, 5, 1, 3]}

# Weighted binary grid solver.
# A black cell at (r, c) contributes:
# - column weight (c+1) to row r sum
# - row weight (r+1) to column c sum
#
# This means if x[r][c] in {0,1}, we need:
#   for each row r: sum((c+1) * x[r][c] for c) == row_sum[r]
#   for each col c: sum((r+1) * x[r][c] for r) == col_sum[c]
#
# The solver is generalized and uses:
# - exact per-line subset generation
# - line-domain filtering
# - bidirectional propagation between row and column domains
# - forced cell deduction
# - bounded feasibility checks
# - branch on most constrained unresolved line/cell
#
# It mirrors human deduction:
# - enumerate what each row/column can still be
# - eliminate impossible patterns when they conflict
# - mark cells forced black/white when every remaining pattern agrees
# - if stuck, choose the tightest uncertainty and split

from collections import deque

def solve(observation):
    row_targets = list(observation['row_sum'])
    col_targets = list(observation['col_sum'])
    R = len(row_targets)
    C = len(col_targets)

    row_weights = [r + 1 for r in range(R)]
    col_weights = [c + 1 for c in range(C)]

    # Precompute all subset masks by weighted sum for rows and columns.
    # Row patterns are masks over columns using column weights.
    # Column patterns are masks over rows using row weights.
    row_sum_to_masks = build_sum_to_masks(C, col_weights)
    col_sum_to_masks = build_sum_to_masks(R, row_weights)

    row_domains = []
    for r, target in enumerate(row_targets):
        masks = row_sum_to_masks.get(target, [])
        if not masks:
            return "No Solution"
        row_domains.append(set(masks))

    col_domains = []
    for c, target in enumerate(col_targets):
        masks = col_sum_to_masks.get(target, [])
        if not masks:
            return "No Solution"
        col_domains.append(set(masks))

    board = [[-1] * C for _ in range(R)]  # -1 unknown, 0 white, 1 black

    solved = search(board, row_domains, col_domains, R, C)
    if solved is None:
        return "No Solution"

    final_board = solved
    lines = []
    for r in range(R):
        row_repr = []
        for c in range(C):
            row_repr.append('B' if final_board[r][c] == 1 else 'None')
        lines.append('[' + ', '.join(row_repr) + ']')
    return '[\n ' + ',\n '.join(lines) + '\n]'


def build_sum_to_masks(n, weights):
    # Map weighted subset sum -> list of bitmasks.
    out = {}
    for mask in range(1 << n):
        s = 0
        m = mask
        i = 0
        while m:
            if m & 1:
                s += weights[i]
            i += 1
            m >>= 1
        # Remaining zero bits need no processing.
        out.setdefault(s, []).append(mask)
    return out


def search(board, row_domains, col_domains, R, C):
    state = propagate(board, row_domains, col_domains, R, C)
    if state is None:
        return None

    board, row_domains, col_domains = state

    if is_complete(board, R, C):
        if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
            return board

    branch = choose_branch(board, row_domains, col_domains, R, C)
    if branch is None:
        return board if verify(board, row_domains, col_domains, R, C) else None

    kind = branch[0]

    if kind == 'cell':
        _, r, c = branch
        # Try forced-by-smaller-support value first.
        support1 = count_cell_support_row(row_domains[r], c, 1)
        support0 = len(row_domains[r]) - support1
        values = [1, 0] if support1 <= support0 else [0, 1]
        for v in values:
            nb, nr, nc = clone_state(board, row_domains, col_domains)
            nb[r][c] = v
            result = search(nb, nr, nc, R, C)
            if result is not None:
                return result
        return None

    if kind == 'row':
        _, r = branch
        masks = sorted(row_domains[r], key=lambda m: pattern_score_row(m, r, col_domains, C))
        for mask in masks:
            nb, nr, nc = clone_state(board, row_domains, col_domains)
            nr[r] = {mask}
            result = search(nb, nr, nc, R, C)
            if result is not None:
                return result
        return None

    if kind == 'col':
        _, c = branch
        masks = sorted(col_domains[c], key=lambda m: pattern_score_col(m, c, row_domains, R))
        for mask in masks:
            nb, nr, nc = clone_state(board, row_domains, col_domains)
            nc[c] = {mask}
            result = search(nb, nr, nc, R, C)
            if result is not None:
                return result
        return None

    return None


def propagate(board, row_domains, col_domains, R, C):
    board, row_domains, col_domains = clone_state(board, row_domains, col_domains)

    queue = deque()
    for r in range(R):
        queue.append(('row', r))
    for c in range(C):
        queue.append(('col', c))

    while queue:
        typ, idx = queue.popleft()

        if typ == 'row':
            changed, ok, touched_cols = reduce_row(idx, board, row_domains, col_domains, R, C)
            if not ok:
                return None
            if changed:
                for c in touched_cols:
                    queue.append(('col', c))
                queue.append(('row', idx))
        else:
            changed, ok, touched_rows = reduce_col(idx, board, row_domains, col_domains, R, C)
            if not ok:
                return None
            if changed:
                for r in touched_rows:
                    queue.append(('row', r))
                queue.append(('col', idx))

    if not bounds_check(board, row_domains, col_domains, R, C):
        return None

    return board, row_domains, col_domains


def reduce_row(r, board, row_domains, col_domains, R, C):
    dom = row_domains[r]
    if not dom:
        return False, False, ()

    new_dom = set()
    for mask in dom:
        ok = True
        for c in range(C):
            bit = (mask >> c) & 1
            cell = board[r][c]
            if cell != -1 and cell != bit:
                ok = False
                break
            if not column_can_support(col_domains[c], r, bit):
                ok = False
                break
        if ok:
            new_dom.add(mask)

    if not new_dom:
        return False, False, ()

    changed = new_dom != dom
    row_domains[r] = new_dom

    touched_cols = set()
    forced = forced_bits_over_masks(new_dom, C)
    for c, val in forced.items():
        if board[r][c] == -1:
            board[r][c] = val
            changed = True
            touched_cols.add(c)
        elif board[r][c] != val:
            return False, False, ()

    # Additional per-cell support pruning from row -> columns.
    for c in range(C):
        if board[r][c] != -1:
            continue
        has0 = False
        has1 = False
        for mask in new_dom:
            bit = (mask >> c) & 1
            if bit == 0:
                has0 = True
            else:
                has1 = True
            if has0 and has1:
                break
        if not has0:
            board[r][c] = 1
            changed = True
            touched_cols.add(c)
        elif not has1:
            board[r][c] = 0
            changed = True
            touched_cols.add(c)

    return changed, True, tuple(touched_cols)


def reduce_col(c, board, row_domains, col_domains, R, C):
    dom = col_domains[c]
    if not dom:
        return False, False, ()

    new_dom = set()
    for mask in dom:
        ok = True
        for r in range(R):
            bit = (mask >> r) & 1
            cell = board[r][c]
            if cell != -1 and cell != bit:
                ok = False
                break
            if not row_can_support(row_domains[r], c, bit):
                ok = False
                break
        if ok:
            new_dom.add(mask)

    if not new_dom:
        return False, False, ()

    changed = new_dom != dom
    col_domains[c] = new_dom

    touched_rows = set()
    forced = forced_bits_over_masks(new_dom, R)
    for r, val in forced.items():
        if board[r][c] == -1:
            board[r][c] = val
            changed = True
            touched_rows.add(r)
        elif board[r][c] != val:
            return False, False, ()

    for r in range(R):
        if board[r][c] != -1:
            continue
        has0 = False
        has1 = False
        for mask in new_dom:
            bit = (mask >> r) & 1
            if bit == 0:
                has0 = True
            else:
                has1 = True
            if has0 and has1:
                break
        if not has0:
            board[r][c] = 1
            changed = True
            touched_rows.add(r)
        elif not has1:
            board[r][c] = 0
            changed = True
            touched_rows.add(r)

    return changed, True, tuple(touched_rows)


def forced_bits_over_masks(masks, width):
    it = iter(masks)
    first = next(it)
    all1 = first
    any1 = first
    for m in it:
        all1 &= m
        any1 |= m
    forced = {}
    full = (1 << width) - 1
    all0 = (~any1) & full
    for i in range(width):
        if (all1 >> i) & 1:
            forced[i] = 1
        elif (all0 >> i) & 1:
            forced[i] = 0
    return forced


def row_can_support(row_domain, c, bit):
    for mask in row_domain:
        if ((mask >> c) & 1) == bit:
            return True
    return False


def column_can_support(col_domain, r, bit):
    for mask in col_domain:
        if ((mask >> r) & 1) == bit:
            return True
    return False


def count_cell_support_row(row_domain, c, bit):
    cnt = 0
    for mask in row_domain:
        if ((mask >> c) & 1) == bit:
            cnt += 1
    return cnt


def bounds_check(board, row_domains, col_domains, R, C):
    # Domain non-emptiness.
    for d in row_domains:
        if not d:
            return False
    for d in col_domains:
        if not d:
            return False

    # Every cell must remain realizable from both perspectives.
    for r in range(R):
        for c in range(C):
            v = board[r][c]
            if v == -1:
                row_has0 = row_can_support(row_domains[r], c, 0)
                row_has1 = row_can_support(row_domains[r], c, 1)
                col_has0 = column_can_support(col_domains[c], r, 0)
                col_has1 = column_can_support(col_domains[c], r, 1)
                if not ((row_has0 and col_has0) or (row_has1 and col_has1)):
                    return False
            else:
                if not row_can_support(row_domains[r], c, v):
                    return False
                if not column_can_support(col_domains[c], r, v):
                    return False
    return True


def choose_branch(board, row_domains, col_domains, R, C):
    # Prefer smallest unresolved domain > 1.
    best = None
    best_size = 10**9

    for r in range(R):
        size = len(row_domains[r])
        if 1 < size < best_size:
            best_size = size
            best = ('row', r)

    for c in range(C):
        size = len(col_domains[c])
        if 1 < size < best_size:
            best_size = size
            best = ('col', c)

    # If a cell has exactly two jointly feasible values, branching on it can be superior.
    # Choose most constrained unknown cell by support product.
    best_cell = None
    best_score = 10**9
    for r in range(R):
        for c in range(C):
            if board[r][c] != -1:
                continue
            feas = []
            for v in (0, 1):
                if row_can_support(row_domains[r], c, v) and column_can_support(col_domains[c], r, v):
                    feas.append(v)
            if len(feas) == 0:
                return ('cell', r, c)
            if len(feas) == 1:
                return ('cell', r, c)
            sr = count_cell_support_row(row_domains[r], c, 1)
            zr = len(row_domains[r]) - sr
            sc = 0
            for mask in col_domains[c]:
                if ((mask >> r) & 1) == 1:
                    sc += 1
            zc = len(col_domains[c]) - sc
            score = min(sr, zr) * min(sc, zc)
            if score < best_score:
                best_score = score
                best_cell = ('cell', r, c)

    if best_cell is not None and (best is None or best_size > 2):
        return best_cell
    return best


def pattern_score_row(mask, r, col_domains, C):
    # Lower score = more restrictive / likely better first.
    score = 0
    for c in range(C):
        bit = (mask >> c) & 1
        support = 0
        for cm in col_domains[c]:
            if ((cm >> r) & 1) == bit:
                support += 1
        score += support
    return score


def pattern_score_col(mask, c, row_domains, R):
    score = 0
    for r in range(R):
        bit = (mask >> r) & 1
        support = 0
        for rm in row_domains[r]:
            if ((rm >> c) & 1) == bit:
                support += 1
        score += support
    return score


def verify(board, row_domains, col_domains, R, C):
    for r in range(R):
        if len(row_domains[r]) != 1:
            return False
    for c in range(C):
        if len(col_domains[c]) != 1:
            return False
    for r in range(R):
        for c in range(C):
            if board[r][c] == -1:
                return False
    return True


def is_complete(board, R, C):
    for r in range(R):
        for c in range(C):
            if board[r][c] == -1:
                return False
    return True


def clone_state(board, row_domains, col_domains):
    nb = [row[:] for row in board]
    nr = [set(d) for d in row_domains]
    nc = [set(d) for d in col_domains]
    return nb, nr, nc


