from collections import deque

def solve(observation):
    data = observation['data']
    unit = observation['unit']

    if 'x' in unit:
        br, bc = map(int, unit.split('x'))
    else:
        br = bc = int(unit)

    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    symbols = list(range(1, n + 1))
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        while mask:
            b = mask & -mask
            vals.append(b.bit_length())
            mask ^= b
        return vals

    def popcount(x):
        return x.bit_count()

    cells = [(r, c) for r in range(n) for c in range(n)]
    cell_index = {(r, c): r * n + c for r in range(n) for c in range(n)}

    box_count_row = n // br
    box_count_col = n // bc

    def box_id(r, c):
        return (r // br) * box_count_col + (c // bc)

    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]
    box_cells = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            box_cells[box_id(r, c)].append((r, c))

    units = []
    units.extend(row_cells)
    units.extend(col_cells)
    units.extend(box_cells)

    cell_units = {}
    for r in range(n):
        for c in range(n):
            cell_units[(r, c)] = [row_cells[r], col_cells[c], box_cells[box_id(r, c)]]

    peers = {}
    for r in range(n):
        for c in range(n):
            s = set(row_cells[r]) | set(col_cells[c]) | set(box_cells[box_id(r, c)])
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    grid = [[None] * n for _ in range(n)]
    cand = [[full_mask] * n for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    box_used = [0] * n

    def assign(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, v, queue):
        current = state_grid[r][c]
        if current == v:
            return True
        if current is not None and current != v:
            return False

        m = bit(v)
        b = box_id(r, c)
        if (state_row_used[r] & m) or (state_col_used[c] & m) or (state_box_used[b] & m):
            return False
        if not (state_cand[r][c] & m):
            return False

        state_grid[r][c] = v
        state_cand[r][c] = m
        state_row_used[r] |= m
        state_col_used[c] |= m
        state_box_used[b] |= m

        queue.append(('placed', r, c))
        return True

    def eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, rem_mask, queue):
        if state_grid[r][c] is not None:
            if state_cand[r][c] & rem_mask:
                if state_cand[r][c] & ~rem_mask == 0:
                    return False
            return True

        old = state_cand[r][c]
        new = old & ~rem_mask
        if new == old:
            return True
        if new == 0:
            return False
        state_cand[r][c] = new
        if popcount(new) == 1:
            v = new.bit_length()
            return assign(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, v, queue)
        queue.append(('reduced', r, c))
        return True

    def initialize():
        state_grid = [[None if data[r][c] is None else int(data[r][c]) for c in range(n)] for r in range(n)]
        state_cand = [[full_mask for _ in range(n)] for _ in range(n)]
        state_row_used = [0] * n
        state_col_used = [0] * n
        state_box_used = [0] * n
        queue = deque()

        for r in range(n):
            for c in range(n):
                v = state_grid[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    state_grid[r][c] = None

        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not assign(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, int(v), queue):
                        return None

        for r in range(n):
            for c in range(n):
                if state_grid[r][c] is None:
                    used = state_row_used[r] | state_col_used[c] | state_box_used[box_id(r, c)]
                    state_cand[r][c] = full_mask & ~used
                    if state_cand[r][c] == 0:
                        return None
                    if popcount(state_cand[r][c]) == 1:
                        v = state_cand[r][c].bit_length()
                        if not assign(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, v, queue):
                            return None

        return state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue

    def hidden_singles(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue):
        progress = False
        for unit_cells in units:
            present = 0
            for r, c in unit_cells:
                if state_grid[r][c] is not None:
                    present |= bit(state_grid[r][c])
            missing = full_mask & ~present
            mm = missing
            while mm:
                b = mm & -mm
                target = None
                count = 0
                for r, c in unit_cells:
                    if state_grid[r][c] is None and (state_cand[r][c] & b):
                        count += 1
                        target = (r, c)
                        if count > 1:
                            break
                if count == 0:
                    return None
                if count == 1:
                    if not assign(state_grid, state_cand, state_row_used, state_col_used, state_box_used, target[0], target[1], b.bit_length(), queue):
                        return None
                    progress = True
                mm ^= b
        return progress

    def locked_candidates(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue):
        progress = False

        for b_id, unit_cells in enumerate(box_cells):
            for v in symbols:
                m = bit(v)
                spots = [(r, c) for (r, c) in unit_cells if state_grid[r][c] is None and (state_cand[r][c] & m)]
                if not spots:
                    continue
                rows = {r for r, _ in spots}
                cols = {c for _, c in spots}
                if len(rows) == 1:
                    rr = next(iter(rows))
                    for r, c in row_cells[rr]:
                        if box_id(r, c) != b_id and state_grid[r][c] is None and (state_cand[r][c] & m):
                            if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, m, queue):
                                return None
                            progress = True
                if len(cols) == 1:
                    cc = next(iter(cols))
                    for r, c in col_cells[cc]:
                        if box_id(r, c) != b_id and state_grid[r][c] is None and (state_cand[r][c] & m):
                            if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, m, queue):
                                return None
                            progress = True

        for r in range(n):
            for v in symbols:
                m = bit(v)
                spots = [(rr, cc) for rr, cc in row_cells[r] if state_grid[rr][cc] is None and (state_cand[rr][cc] & m)]
                if spots:
                    boxes = {box_id(rr, cc) for rr, cc in spots}
                    if len(boxes) == 1:
                        b_id = next(iter(boxes))
                        for rr, cc in box_cells[b_id]:
                            if rr != r and state_grid[rr][cc] is None and (state_cand[rr][cc] & m):
                                if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, rr, cc, m, queue):
                                    return None
                                progress = True

        for c in range(n):
            for v in symbols:
                m = bit(v)
                spots = [(rr, cc) for rr, cc in col_cells[c] if state_grid[rr][cc] is None and (state_cand[rr][cc] & m)]
                if spots:
                    boxes = {box_id(rr, cc) for rr, cc in spots}
                    if len(boxes) == 1:
                        b_id = next(iter(boxes))
                        for rr, cc in box_cells[b_id]:
                            if cc != c and state_grid[rr][cc] is None and (state_cand[rr][cc] & m):
                                if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, rr, cc, m, queue):
                                    return None
                                progress = True

        return progress

    def naked_subsets(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue, max_k=4):
        progress = False
        for unit_cells in units:
            groups = {}
            unsolved = []
            for r, c in unit_cells:
                if state_grid[r][c] is None:
                    m = state_cand[r][c]
                    unsolved.append((r, c, m))
                    pc = popcount(m)
                    if 2 <= pc <= max_k:
                        groups.setdefault(m, []).append((r, c))
            for m, pos_list in groups.items():
                k = popcount(m)
                if len(pos_list) == k:
                    for r, c, other_m in unsolved:
                        if (r, c) not in pos_list and (other_m & m):
                            if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, m, queue):
                                return None
                            progress = True
        return progress

    def hidden_subsets(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue, max_k=4):
        progress = False
        for unit_cells in units:
            digit_spots = {}
            for v in symbols:
                m = bit(v)
                spots = []
                for r, c in unit_cells:
                    if state_grid[r][c] is None and (state_cand[r][c] & m):
                        spots.append((r, c))
                if 1 <= len(spots) <= max_k:
                    digit_spots.setdefault(tuple(spots), 0)
                    digit_spots[tuple(spots)] |= m
            for spots, m in digit_spots.items():
                k_cells = len(spots)
                k_digits = popcount(m)
                if 2 <= k_cells == k_digits <= max_k:
                    spot_set = set(spots)
                    for r, c in spots:
                        extra = state_cand[r][c] & ~m
                        if extra:
                            if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, extra, queue):
                                return None
                            progress = True
                    for r, c in unit_cells:
                        if (r, c) not in spot_set and state_grid[r][c] is None and (state_cand[r][c] & m):
                            if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, m, queue):
                                return None
                            progress = True
        return progress

    def propagate(state):
        state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue = state

        while True:
            while queue:
                kind, r, c = queue.popleft()
                if state_grid[r][c] is not None:
                    v = state_grid[r][c]
                    m = bit(v)
                    for rr, cc in peers[(r, c)]:
                        if state_grid[rr][cc] is None and (state_cand[rr][cc] & m):
                            if not eliminate_mask(state_grid, state_cand, state_row_used, state_col_used, state_box_used, rr, cc, m, queue):
                                return None
                else:
                    if state_cand[r][c] == 0:
                        return None
                    if popcount(state_cand[r][c]) == 1:
                        v = state_cand[r][c].bit_length()
                        if not assign(state_grid, state_cand, state_row_used, state_col_used, state_box_used, r, c, v, queue):
                            return None

            progress = False
            hs = hidden_singles(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue)
            if hs is None:
                return None
            progress |= hs
            if queue:
                continue

            lc = locked_candidates(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue)
            if lc is None:
                return None
            progress |= lc
            if queue:
                continue

            ns = naked_subsets(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue, 4)
            if ns is None:
                return None
            progress |= ns
            if queue:
                continue

            hsub = hidden_subsets(state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue, 4)
            if hsub is None:
                return None
            progress |= hsub
            if queue:
                continue

            for r in range(n):
                if state_row_used[r] != full_mask:
                    seen = 0
                    for c in range(n):
                        v = state_grid[r][c]
                        if v is not None:
                            m = bit(v)
                            if seen & m:
                                return None
                            seen |= m
            for c in range(n):
                if state_col_used[c] != full_mask:
                    seen = 0
                    for r in range(n):
                        v = state_grid[r][c]
                        if v is not None:
                            m = bit(v)
                            if seen & m:
                                return None
                            seen |= m
            for b_id in range(n):
                if state_box_used[b_id] != full_mask:
                    seen = 0
                    for r, c in box_cells[b_id]:
                        v = state_grid[r][c]
                        if v is not None:
                            m = bit(v)
                            if seen & m:
                                return None
                            seen |= m

            if not progress:
                break

        return state

    def is_solved(state_grid):
        for r in range(n):
            for c in range(n):
                if state_grid[r][c] is None:
                    return False
        return True

    def clone_state(state):
        state_grid, state_cand, state_row_used, state_col_used, state_box_used, _queue = state
        return (
            [row[:] for row in state_grid],
            [row[:] for row in state_cand],
            state_row_used[:],
            state_col_used[:],
            state_box_used[:],
            deque()
        )

    def choose_branch_cell(state_grid, state_cand):
        best = None
        best_score = None
        for r in range(n):
            row_missing = n - sum(1 for x in state_grid[r] if x is not None)
            for c in range(n):
                if state_grid[r][c] is None:
                    pc = popcount(state_cand[r][c])
                    peer_pressure = 0
                    for rr, cc in peers[(r, c)]:
                        if state_grid[rr][cc] is None:
                            peer_pressure += 1
                    score = (pc, -peer_pressure, -row_missing)
                    if best_score is None or score < best_score:
                        best_score = score
                        best = (r, c)
        return best

    def ordered_candidates(state_grid, state_cand, r, c):
        vals = mask_to_values(state_cand[r][c])
        impacts = []
        for v in vals:
            m = bit(v)
            impact = 0
            for rr, cc in peers[(r, c)]:
                if state_grid[rr][cc] is None and (state_cand[rr][cc] & m):
                    impact += 1
            impacts.append((impact, v))
        impacts.sort(reverse=True)
        return [v for _, v in impacts]

    def search(state):
        state = propagate(state)
        if state is None:
            return None

        state_grid, state_cand, state_row_used, state_col_used, state_box_used, queue = state
        if is_solved(state_grid):
            return state_grid

        choice = choose_branch_cell(state_grid, state_cand)
        if choice is None:
            return None
        r, c = choice

        for v in ordered_candidates(state_grid, state_cand, r, c):
            new_state = clone_state(state)
            ng, nc, nru, ncu, nbu, nq = new_state
            if assign(ng, nc, nru, ncu, nbu, r, c, v, nq):
                result = search(new_state)
                if result is not None:
                    return result
        return None

    initial = initialize()
    if initial is None:
        return "No Solution"

    solved = search(initial)
    return str(solved) if solved is not None else "No Solution"


