from collections import defaultdict, deque

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}

def addp(a, b):
    return (a[0] + b[0], a[1] + b[1])

def canon_edge(a, b):
    return (a, b) if a <= b else (b, a)

def edge_dir(a, b):
    if a[0] == b[0]:
        return 'R' if b[1] > a[1] else 'L'
    return 'D' if b[0] > a[0] else 'U'

def dir_vec(d):
    return DIRS[d]

def inside_cell(n, r, c):
    return 0 <= r < n and 0 <= c < n

def build_geometry(n):
    dots = [(r, c) for r in range(n + 1) for c in range(n + 1)]
    edges = []
    edge_index = {}
    dot_edges = defaultdict(list)
    for r in range(n + 1):
        for c in range(n):
            a, b = (r, c), (r, c + 1)
            e = canon_edge(a, b)
            edge_index[e] = len(edges)
            edges.append(e)
            dot_edges[a].append(e)
            dot_edges[b].append(e)
    for r in range(n):
        for c in range(n + 1):
            a, b = (r, c), (r + 1, c)
            e = canon_edge(a, b)
            edge_index[e] = len(edges)
            edges.append(e)
            dot_edges[a].append(e)
            dot_edges[b].append(e)
    edge_cells = defaultdict(list)
    cell_edges = {}
    for r in range(n):
        for c in range(n):
            e_top = canon_edge((r, c), (r, c + 1))
            e_bottom = canon_edge((r + 1, c), (r + 1, c + 1))
            e_left = canon_edge((r, c), (r + 1, c))
            e_right = canon_edge((r, c + 1), (r + 1, c + 1))
            cell_edges[(r, c)] = [e_top, e_right, e_bottom, e_left]
            for e in cell_edges[(r, c)]:
                edge_cells[e].append((r, c))
    return dots, edges, edge_index, dot_edges, edge_cells, cell_edges

def parse_clues(observation):
    data = observation['data']
    n = len(data)
    clues = {}
    for r in range(n):
        for c in range(n):
            tok = data[r][c]
            if tok is not None:
                clues[(r, c)] = (tok[0], int(tok[1:]))
    return n, clues

def clue_arms_for_cell(n, cell):
    r, c = cell
    arms = {
        'U': [],
        'D': [],
        'L': [],
        'R': [],
    }
    for k in range(1, r + 1):
        arms['U'].append(canon_edge((r - k, c), (r - k + 1, c)))
    for k in range(1, n - r):
        arms['D'].append(canon_edge((r + k - 1, c), (r + k, c)))
    for k in range(1, c + 1):
        arms['L'].append(canon_edge((r, c - k), (r, c - k + 1)))
    for k in range(1, n - c):
        arms['R'].append(canon_edge((r, c + k - 1), (r, c + k)))
    return arms

def generate_allowed_patterns(n, clue_type, k, cell):
    arms = clue_arms_for_cell(n, cell)
    allowed = []
    if clue_type == 'W':
        pairs = [('U', 'D'), ('L', 'R')]
    else:
        pairs = [('U', 'L'), ('U', 'R'), ('D', 'L'), ('D', 'R')]
    for d1, d2 in pairs:
        a1 = arms[d1]
        a2 = arms[d2]
        max1 = len(a1)
        max2 = len(a2)
        for l1 in range(1, max1 + 1):
            l2 = k - l1
            if 1 <= l2 <= max2:
                on = set(a1[:l1]) | set(a2[:l2])
                allowed.append((frozenset(on), (d1, l1, d2, l2)))
    return allowed

class DSU:
    def __init__(self, items):
        self.p = {x: x for x in items}
        self.sz = {x: 1 for x in items}

    def find(self, x):
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]
            x = self.p[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.sz[ra] < self.sz[rb]:
            ra, rb = rb, ra
        self.p[rb] = ra
        self.sz[ra] += self.sz[rb]
        return True

class Solver:
    def __init__(self, observation):
        self.n, self.clues = parse_clues(observation)
        self.dots, self.edges, self.edge_index, self.dot_edges, self.edge_cells, self.cell_edges = build_geometry(self.n)
        self.edge_state = {e: -1 for e in self.edges}  # -1 unknown, 0 off, 1 on
        self.dot_on_count = {d: 0 for d in self.dots}
        self.dot_unknown = {d: len(self.dot_edges[d]) for d in self.dots}
        self.clue_patterns = {}
        self.clue_possible = {}
        self.edge_to_clues = defaultdict(list)
        for cell, (t, k) in self.clues.items():
            pats = generate_allowed_patterns(self.n, t, k, cell)
            self.clue_patterns[cell] = pats
            self.clue_possible[cell] = set(range(len(pats)))
            used = set()
            for i, (onset, _) in enumerate(pats):
                for e in onset:
                    if e not in used:
                        self.edge_to_clues[e].append(cell)
                used |= onset
            all_edges = set()
            for arm in clue_arms_for_cell(self.n, cell).values():
                all_edges |= set(arm)
            for e in all_edges:
                if cell not in self.edge_to_clues[e]:
                    self.edge_to_clues[e].append(cell)

    def clone(self):
        other = Solver.__new__(Solver)
        other.n = self.n
        other.clues = self.clues
        other.dots = self.dots
        other.edges = self.edges
        other.edge_index = self.edge_index
        other.dot_edges = self.dot_edges
        other.edge_cells = self.edge_cells
        other.cell_edges = self.cell_edges
        other.clue_patterns = self.clue_patterns
        other.edge_to_clues = self.edge_to_clues
        other.edge_state = self.edge_state.copy()
        other.dot_on_count = self.dot_on_count.copy()
        other.dot_unknown = self.dot_unknown.copy()
        other.clue_possible = {k: v.copy() for k, v in self.clue_possible.items()}
        return other

    def set_edge(self, e, val, queue):
        cur = self.edge_state[e]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        self.edge_state[e] = val
        a, b = e
        self.dot_unknown[a] -= 1
        self.dot_unknown[b] -= 1
        if val == 1:
            self.dot_on_count[a] += 1
            self.dot_on_count[b] += 1
        queue.append(('dot', a))
        queue.append(('dot', b))
        for cell in self.edge_to_clues.get(e, []):
            queue.append(('clue', cell))
        for cell in self.edge_cells.get(e, []):
            queue.append(('cellpar', cell))
        return True

    def reduce_clue(self, cell, queue):
        poss = self.clue_possible[cell]
        pats = self.clue_patterns[cell]
        new_poss = set()
        for i in poss:
            onset, _ = pats[i]
            ok = True
            all_edges = set()
            for arm in clue_arms_for_cell(self.n, cell).values():
                all_edges |= set(arm)
            for e in all_edges:
                st = self.edge_state[e]
                want = 1 if e in onset else 0
                if st != -1 and st != want:
                    ok = False
                    break
            if ok:
                new_poss.add(i)
        if not new_poss:
            return False
        if new_poss != poss:
            self.clue_possible[cell] = new_poss
        all_edges = set()
        for arm in clue_arms_for_cell(self.n, cell).values():
            all_edges |= set(arm)
        for e in all_edges:
            vals = set(1 if e in pats[i][0] else 0 for i in new_poss)
            if len(vals) == 1:
                if not self.set_edge(e, next(iter(vals)), queue):
                    return False
        return True

    def reduce_dot(self, d, queue):
        on = self.dot_on_count[d]
        unk = self.dot_unknown[d]
        if on > 2:
            return False
        if on == 1 and unk == 0:
            return False
        if on == 0 and unk == 1:
            return False
        if on == 2:
            for e in self.dot_edges[d]:
                if self.edge_state[e] == -1:
                    if not self.set_edge(e, 0, queue):
                        return False
        elif on == 1 and unk == 1:
            for e in self.dot_edges[d]:
                if self.edge_state[e] == -1:
                    if not self.set_edge(e, 1, queue):
                        return False
        elif on == 0 and unk == 2:
            for e in self.dot_edges[d]:
                if self.edge_state[e] == -1:
                    if not self.set_edge(e, 1, queue):
                        return False
        elif on + unk < 2:
            return False
        return True

    def reduce_cell_parity(self, cell, queue):
        # Simple no-cross/planar loop parity aid:
        # In each cell, number of active boundary edges cannot be 1 or 3.
        cnt_on = 0
        unks = []
        for e in self.cell_edges[cell]:
            st = self.edge_state[e]
            if st == 1:
                cnt_on += 1
            elif st == -1:
                unks.append(e)
        if cnt_on > 4:
            return False
        if not unks:
            if cnt_on in (1, 3):
                return False
            return True
        if cnt_on == 1 and len(unks) == 1:
            return self.set_edge(unks[0], 1, queue)
        if cnt_on == 3 and len(unks) == 1:
            return self.set_edge(unks[0], 1, queue)
        if cnt_on == 0 and len(unks) == 1:
            return self.set_edge(unks[0], 0, queue)
        if cnt_on == 2 and len(unks) == 1:
            return self.set_edge(unks[0], 0, queue)
        if cnt_on == 4 and len(unks) == 0:
            return True
        return True

    def propagate(self):
        queue = deque()
        for cell in self.clues:
            queue.append(('clue', cell))
        for d in self.dots:
            queue.append(('dot', d))
        for cell in self.cell_edges:
            queue.append(('cellpar', cell))
        seen = 0
        while queue:
            typ, obj = queue.popleft()
            seen += 1
            if typ == 'clue':
                if not self.reduce_clue(obj, queue):
                    return False
            elif typ == 'dot':
                if not self.reduce_dot(obj, queue):
                    return False
            else:
                if not self.reduce_cell_parity(obj, queue):
                    return False
            if seen > 200000:
                break
        return self.global_checks()

    def global_checks(self):
        on_edges = [e for e, st in self.edge_state.items() if st == 1]
        if not on_edges:
            return True
        # No premature closed component unless complete.
        dsu = DSU(self.dots)
        for e in on_edges:
            dsu.union(e[0], e[1])
        comp_edges = defaultdict(int)
        comp_dots_deg1or2 = defaultdict(list)
        used_dots = set()
        for e in on_edges:
            used_dots.add(e[0]); used_dots.add(e[1])
        for d in used_dots:
            comp_dots_deg1or2[dsu.find(d)].append(d)
        for e in on_edges:
            comp_edges[dsu.find(e[0])] += 1
        total_on = len(on_edges)
        if len(comp_edges) > 1:
            # every separate component must have an open endpoint to extend
            for root, dots in comp_dots_deg1or2.items():
                closed = True
                for d in dots:
                    if self.dot_on_count[d] < 2 and self.dot_unknown[d] > 0:
                        closed = False
                        break
                if closed:
                    return False
        else:
            root = next(iter(comp_edges))
            all_used_closed = all(self.dot_on_count[d] == 2 for d in used_dots)
            any_unknown_on_used = any(self.dot_unknown[d] > 0 for d in used_dots)
            if all_used_closed and any(self.edge_state[e] == -1 for e in self.edges):
                return False
        return True

    def choose_branch(self):
        best = None
        # Prefer clue with fewest patterns >1
        for cell, poss in self.clue_possible.items():
            if 1 < len(poss) and (best is None or len(poss) < best[0]):
                best = (len(poss), ('clue', cell))
        if best is not None:
            return best[1]
        # Otherwise choose edge most constrained by clues
        score_best = -1
        edge_best = None
        for e, st in self.edge_state.items():
            if st == -1:
                score = len(self.edge_to_clues.get(e, []))
                a, b = e
                score += (2 - self.dot_unknown[a]) + (2 - self.dot_unknown[b])
                if score > score_best:
                    score_best = score
                    edge_best = e
        if edge_best is not None:
            return ('edge', edge_best)
        return None

    def is_complete(self):
        return all(st != -1 for st in self.edge_state.values())

    def extract_loop(self):
        on_edges = [e for e, st in self.edge_state.items() if st == 1]
        if not on_edges:
            return None
        adj = defaultdict(list)
        for a, b in on_edges:
            adj[a].append(b)
            adj[b].append(a)
        used = set()
        start = min(adj)
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            nxt = None
            if prev is None:
                nxt = nbrs[0]
            else:
                if len(nbrs) != 2:
                    return None
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
            e = canon_edge(cur, nxt)
            if e in used:
                break
            used.add(e)
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        if len(used) != len(on_edges):
            return None
        if path[-1] != start:
            path.append(start)
        return path

def solve(observation):
    solver = Solver(observation)
    if not solver.propagate():
        return "No Solution"

    def dfs(state, depth=0, limit=200):
        if depth > limit:
            return None
        if state.is_complete():
            if not state.global_checks():
                return None
            loop = state.extract_loop()
            return loop if loop is not None else None
        branch = state.choose_branch()
        if branch is None:
            return None
        typ, obj = branch
        if typ == 'clue':
            cell = obj
            poss = list(state.clue_possible[cell])
            # Human-like: try patterns that force more edges first
            pats = state.clue_patterns[cell]
            poss.sort(key=lambda i: -len(pats[i][0]))
            for i in poss:
                child = state.clone()
                q = deque()
                child.clue_possible[cell] = {i}
                q.append(('clue', cell))
                ok = True
                while q and ok:
                    typ2, obj2 = q.popleft()
                    if typ2 == 'clue':
                        ok = child.reduce_clue(obj2, q)
                    elif typ2 == 'dot':
                        ok = child.reduce_dot(obj2, q)
                    else:
                        ok = child.reduce_cell_parity(obj2, q)
                if ok and child.global_checks():
                    res = dfs(child, depth + 1, limit)
                    if res is not None:
                        return res
            return None
        else:
            e = obj
            # Branch order by local consistency impact
            for val in (1, 0):
                child = state.clone()
                q = deque()
                if child.set_edge(e, val, q):
                    ok = True
                    while q and ok:
                        typ2, obj2 = q.popleft()
                        if typ2 == 'clue':
                            ok = child.reduce_clue(obj2, q)
                        elif typ2 == 'dot':
                            ok = child.reduce_dot(obj2, q)
                        else:
                            ok = child.reduce_cell_parity(obj2, q)
                    if ok and child.global_checks():
                        res = dfs(child, depth + 1, limit)
                        if res is not None:
                            return res
            return None

    ans = dfs(solver)
    return str(ans) if ans is not None else "No Solution"

