# Weighted black-cell puzzle solver.
# A cell (r, c) is black iff variable x[r][c] = 1.
# Constraints:
#   For each row r: sum(col_weight[c] * x[r][c]) == row_sum[r]
#   For each col c: sum(row_weight[r] * x[r][c]) == col_sum[c]
# with row_weight[r] = r+1 and col_weight[c] = c+1 for the pictured format.
#
# The solver emphasizes human-like deduction:
# 1) Generate all feasible row patterns from row sums.
# 2) Generate all feasible column patterns from column sums.
# 3) Repeatedly intersect row/column possibilities to force cells.
# 4) Use tight min/max residual bounds on both dimensions.
# 5) Branch only on the most constrained undecided cell when needed.

from itertools import compress

def bits_of_mask(mask, n):
    return [(mask >> i) & 1 for i in range(n)]

def format_grid(grid):
    return str([['B' if v == 1 else None for v in row] for row in grid])

def subset_masks_by_weight(weights, target):
    n = len(weights)
    out = []
    for mask in range(1 << n):
        s = 0
        m = mask
        i = 0
        while m:
            if m & 1:
                s += weights[i]
            i += 1
            m >>= 1
        while i < n:
            i += 1
        if s == target:
            out.append(mask)
    return out

def pattern_cell_stats(patterns, length):
    if not patterns:
        return [set() for _ in range(length)]
    all1 = (1 << length) - 1
    and_mask = all1
    or_mask = 0
    for p in patterns:
        and_mask &= p
        or_mask |= p
    stats = []
    for i in range(length):
        can0 = ((or_mask >> i) & 1) == 0 or ((and_mask >> i) & 1) == 0
        can1 = ((or_mask >> i) & 1) == 1
        vals = set()
        if can0:
            vals.add(0)
        if can1 and ((or_mask >> i) & 1):
            vals.add(1)
        stats.append(vals)
    return stats

def min_max_possible_sum(weights, allowed):
    mn = 0
    mx = 0
    for w, vals in zip(weights, allowed):
        if 1 in vals and 0 not in vals:
            mn += w
            mx += w
        elif 1 in vals:
            mx += w
    return mn, mx

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)

    row_weights = [r + 1 for r in range(R)]
    col_weights = [c + 1 for c in range(C)]

    if sum(row_sum) != sum(col_sum):
        return "No Solution"

    # Initial candidate patterns per row/column.
    row_patterns = [subset_masks_by_weight(col_weights, row_sum[r]) for r in range(R)]
    col_patterns = [subset_masks_by_weight(row_weights, col_sum[c]) for c in range(C)]

    if any(len(pats) == 0 for pats in row_patterns) or any(len(pats) == 0 for pats in col_patterns):
        return "No Solution"

    # Domains per cell: {0}, {1}, or {0,1}
    allowed = [[{0, 1} for _ in range(C)] for _ in range(R)]

    def filter_row(r):
        pats = row_patterns[r]
        new = []
        for p in pats:
            ok = True
            for c in range(C):
                if ((p >> c) & 1) not in allowed[r][c]:
                    ok = False
                    break
            if ok:
                new.append(p)
        if not new:
            return False, False
        changed = len(new) != len(pats)
        row_patterns[r] = new
        return True, changed

    def filter_col(c):
        pats = col_patterns[c]
        new = []
        for p in pats:
            ok = True
            for r in range(R):
                if ((p >> r) & 1) not in allowed[r][c]:
                    ok = False
                    break
            if ok:
                new.append(p)
        if not new:
            return False, False
        changed = len(new) != len(pats)
        col_patterns[c] = new
        return True, changed

    def infer_from_rows():
        changed = False
        for r in range(R):
            stats = pattern_cell_stats(row_patterns[r], C)
            for c in range(C):
                newset = allowed[r][c] & stats[c]
                if not newset:
                    return False, False
                if newset != allowed[r][c]:
                    allowed[r][c] = newset
                    changed = True
        return True, changed

    def infer_from_cols():
        changed = False
        for c in range(C):
            stats = pattern_cell_stats(col_patterns[c], R)
            for r in range(R):
                newset = allowed[r][c] & stats[r]
                if not newset:
                    return False, False
                if newset != allowed[r][c]:
                    allowed[r][c] = newset
                    changed = True
        return True, changed

    def residual_bound_check():
        # Human-style sanity checking with min/max reachable weighted sums.
        for r in range(R):
            mn, mx = min_max_possible_sum(col_weights, allowed[r])
            if not (mn <= row_sum[r] <= mx):
                return False
        for c in range(C):
            col_allowed = [allowed[r][c] for r in range(R)]
            mn, mx = min_max_possible_sum(row_weights, col_allowed)
            if not (mn <= col_sum[c] <= mx):
                return False
        return True

    def propagate():
        while True:
            any_change = False

            for r in range(R):
                ok, ch = filter_row(r)
                if not ok:
                    return False
                any_change |= ch

            ok, ch = infer_from_rows()
            if not ok:
                return False
            any_change |= ch

            for c in range(C):
                ok, ch = filter_col(c)
                if not ok:
                    return False
                any_change |= ch

            ok, ch = infer_from_cols()
            if not ok:
                return False
            any_change |= ch

            if not residual_bound_check():
                return False

            if not any_change:
                return True

    def is_solved():
        return all(len(allowed[r][c]) == 1 for r in range(R) for c in range(C))

    def choose_branch_cell():
        # Most constrained cell with best impact estimate from row/col pattern counts.
        best = None
        best_key = None
        for r in range(R):
            for c in range(C):
                if len(allowed[r][c]) == 2:
                    key = (len(row_patterns[r]) * len(col_patterns[c]), len(row_patterns[r]) + len(col_patterns[c]), r, c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def snapshot():
        return (
            [rp[:] for rp in row_patterns],
            [cp[:] for cp in col_patterns],
            [[s.copy() for s in row] for row in allowed],
        )

    def restore(state):
        rp, cp, al = state
        for i in range(R):
            row_patterns[i] = rp[i]
        for j in range(C):
            col_patterns[j] = cp[j]
        for i in range(R):
            for j in range(C):
                allowed[i][j] = al[i][j]

    def build_grid():
        return [[next(iter(allowed[r][c])) for c in range(C)] for r in range(R)]

    def dfs():
        if not propagate():
            return None
        if is_solved():
            return build_grid()

        cell = choose_branch_cell()
        if cell is None:
            return None
        r, c = cell

        # Prefer value that appears less often among row/col patterns first; often causes faster contradictions.
        row_ones = sum((p >> c) & 1 for p in row_patterns[r])
        row_zeros = len(row_patterns[r]) - row_ones
        col_ones = sum((p >> r) & 1 for p in col_patterns[c])
        col_zeros = len(col_patterns[c]) - col_ones
        score0 = row_zeros + col_zeros
        score1 = row_ones + col_ones
        order = [0, 1] if score0 <= score1 else [1, 0]

        for v in order:
            if v not in allowed[r][c]:
                continue
            st = snapshot()
            allowed[r][c] = {v}
            res = dfs()
            if res is not None:
                return res
            restore(st)
        return None

    grid = dfs()
    if grid is None:
        return "No Solution"
    return format_grid(grid)

