# Slitherlink solver with strong deduction + constrained search.
# Returns an ordered list of loop dot coordinates, or "No Solution".

from collections import deque, defaultdict

UNKNOWN = -1
OFF = 0
ON = 1


def solve(observation):
    data = observation['data']
    n = len(data)
    solver = SlitherlinkSolver(data)
    ok = solver.solve()
    if not ok:
        return "No Solution"
    path = solver.extract_loop_path()
    return str(path) if path else "No Solution"


class RollbackDSU:
    # DSU used only on currently ON edges to forbid premature small cycles.
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def snapshot(self):
        return len(self.history)

    def rollback(self, snap):
        while len(self.history) > snap:
            item = self.history.pop()
            if item is None:
                continue
            rb, ra, size_ra, comps = item
            self.parent[rb] = rb
            self.size[ra] = size_ra
            self.components = comps

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            self.history.append(None)
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.history.append((rb, ra, self.size[ra], self.components))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True


class SlitherlinkSolver:
    def __init__(self, clues):
        self.clues = clues
        self.n = len(clues)
        self.dot_n = self.n + 1

        # Edge indexing
        # Horizontal edge h[r][c] : dot (r,c) -- (r,c+1), r in [0..n], c in [0..n-1]
        # Vertical   edge v[r][c] : dot (r,c) -- (r+1,c), r in [0..n-1], c in [0..n]
        self.h = [[None] * self.n for _ in range(self.n + 1)]
        self.v = [[None] * (self.n + 1) for _ in range(self.n)]
        self.edges = []  # (type, r, c, u, v)
        self.edge_state = []

        eid = 0
        for r in range(self.n + 1):
            for c in range(self.n):
                u = self.dot_id(r, c)
                v = self.dot_id(r, c + 1)
                self.h[r][c] = eid
                self.edges.append(('h', r, c, u, v))
                self.edge_state.append(UNKNOWN)
                eid += 1
        for r in range(self.n):
            for c in range(self.n + 1):
                u = self.dot_id(r, c)
                v = self.dot_id(r + 1, c)
                self.v[r][c] = eid
                self.edges.append(('v', r, c, u, v))
                self.edge_state.append(UNKNOWN)
                eid += 1

        self.E = eid
        self.V = self.dot_n * self.dot_n

        # Incident edges for each dot
        self.vertex_edges = [[] for _ in range(self.V)]
        for eid, (_, _, _, u, v) in enumerate(self.edges):
            self.vertex_edges[u].append(eid)
            self.vertex_edges[v].append(eid)

        # Cell edges
        self.cell_edges = [[None] * self.n for _ in range(self.n)]
        for r in range(self.n):
            for c in range(self.n):
                self.cell_edges[r][c] = (
                    self.h[r][c],
                    self.h[r + 1][c],
                    self.v[r][c],
                    self.v[r][c + 1],
                )

        # Edge -> adjacent cells
        self.edge_cells = [[] for _ in range(self.E)]
        for r in range(self.n):
            for c in range(self.n):
                for e in self.cell_edges[r][c]:
                    self.edge_cells[e].append((r, c))

        # DSU for ON edges; used with rollback
        self.dsu = RollbackDSU(self.V)

        # Vertex current ON count
        self.vertex_on = [0] * self.V

        # Assignment trail
        self.trail = []

        # Initial deductions
        self.initial_static_patterns()

    def dot_id(self, r, c):
        return r * self.dot_n + c

    def snapshot(self):
        return (len(self.trail), self.dsu.snapshot())

    def rollback(self, snap):
        trail_len, dsu_snap = snap
        while len(self.trail) > trail_len:
            kind, *rest = self.trail.pop()
            if kind == 'edge':
                eid, old = rest
                self.edge_state[eid] = old
            elif kind == 'vtx':
                vid, delta = rest
                self.vertex_on[vid] -= delta
        self.dsu.rollback(dsu_snap)

    def set_edge(self, eid, val, queue):
        cur = self.edge_state[eid]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False

        typ, r, c, u, v = self.edges[eid]

        # Vertex degree constraints
        if val == ON:
            if self.vertex_on[u] >= 2 or self.vertex_on[v] >= 2:
                return False
            # Forbid closing a smaller cycle before all ON vertices would form the single loop.
            # If endpoints are already connected, adding this edge makes a cycle.
            # Allow only if this would be the final completed loop (checked later by full consistency),
            # so reject for partial states.
            if self.dsu.find(u) == self.dsu.find(v):
                # Might be final edge, but unless all unknowns/off and all ON vertices degree 2, this is premature.
                if not self.can_close_final_cycle_by_adding(eid):
                    return False

        self.trail.append(('edge', eid, cur))
        self.edge_state[eid] = val

        if val == ON:
            self.trail.append(('vtx', u, 1))
            self.vertex_on[u] += 1
            self.trail.append(('vtx', v, 1))
            self.vertex_on[v] += 1
            self.dsu.union(u, v)

        # Affected local structures
        queue.append(('edge', eid))
        queue.append(('vertex', u))
        queue.append(('vertex', v))
        for cell in self.edge_cells[eid]:
            queue.append(('cell', cell[0], cell[1]))
        return True

    def can_close_final_cycle_by_adding(self, eid):
        # Conservative acceptance only if all other constraints imply final solution shape.
        # Since this function is called before assignment, simulate local degree feasibility lightly.
        # We reject almost always unless every currently ON vertex already has degree 2 except endpoints with 1,
        # and no unrelated unknown can be ON.
        typ, r, c, u, v = self.edges[eid]
        # endpoints must currently have degree 1 to become 2
        if self.vertex_on[u] != 1 or self.vertex_on[v] != 1:
            return False
        # all other vertices with ON edges must already be degree 2
        for vid, deg in enumerate(self.vertex_on):
            if vid == u or vid == v:
                continue
            if deg == 1:
                return False
            if deg > 2:
                return False
        # every unknown edge must be impossible to turn ON except maybe this one; too expensive to prove.
        # So use a strict condition: all other unknown edges touch only saturated or zero-usable contexts.
        for i, st in enumerate(self.edge_state):
            if i == eid:
                continue
            if st == UNKNOWN:
                return False
        return True

    def initial_static_patterns(self):
        # Human-style static patterns:
        # 0 => all four OFF
        # 3 on border => the three non-border cell edges ON, opposite interior edge OFF? Not universally forced.
        # Diagonal 3-0 corner between adjacent cells gives strong local deductions, but propagation will find them.
        q = deque()
        for r in range(self.n):
            for c in range(self.n):
                clue = self.clues[r][c]
                if clue == 0:
                    for e in self.cell_edges[r][c]:
                        self.set_edge(e, OFF, q)
        self.propagate(q)

    def propagate(self, queue=None):
        if queue is None:
            queue = deque()

        # Seed all structures if empty
        if not queue:
            for r in range(self.n):
                for c in range(self.n):
                    queue.append(('cell', r, c))
            for v in range(self.V):
                queue.append(('vertex', v))

        seen = 0
        while queue:
            item = queue.popleft()
            seen += 1

            if item[0] == 'cell':
                r, c = item[1], item[2]
                if not self.propagate_cell(r, c, queue):
                    return False
            elif item[0] == 'vertex':
                v = item[1]
                if not self.propagate_vertex(v, queue):
                    return False
            else:
                eid = item[1]
                if not self.propagate_edge_patterns(eid, queue):
                    return False

        return self.global_consistency()

    def propagate_cell(self, r, c, queue):
        clue = self.clues[r][c]
        if clue is None:
            return True
        edges = self.cell_edges[r][c]
        on = 0
        off = 0
        unknown = []
        for e in edges:
            st = self.edge_state[e]
            if st == ON:
                on += 1
            elif st == OFF:
                off += 1
            else:
                unknown.append(e)

        if on > clue:
            return False
        if on + len(unknown) < clue:
            return False

        if on == clue:
            for e in unknown:
                if not self.set_edge(e, OFF, queue):
                    return False
        elif on + len(unknown) == clue:
            for e in unknown:
                if not self.set_edge(e, ON, queue):
                    return False

        # Corner parity-style local rule:
        # In a cell, if at a corner one incident edge is forced ON and clue residual structure forces the other.
        # Rather than encode many cases, use subset reasoning by vertex saturation around the cell.
        return True

    def propagate_vertex(self, v, queue):
        inc = self.vertex_edges[v]
        on = self.vertex_on[v]
        unknown = [e for e in inc if self.edge_state[e] == UNKNOWN]

        if on > 2:
            return False
        if on == 2:
            for e in unknown:
                if not self.set_edge(e, OFF, queue):
                    return False
        elif on == 1:
            if len(unknown) == 0:
                return False
            if len(unknown) == 1:
                if not self.set_edge(unknown[0], ON, queue):
                    return False
        else:  # on == 0
            if len(unknown) == 0:
                return True
            if len(unknown) == 1:
                if not self.set_edge(unknown[0], OFF, queue):
                    return False

        # Connectivity feasibility:
        # If a vertex has degree 1 already, at least one unknown must remain for continuation.
        # If degree 0, either 0 or 2 final; with one unknown only, cannot become 2, so must be 0 -> OFF above handled.
        return True

    def propagate_edge_patterns(self, eid, queue):
        # Adjacent-cell pair patterns useful for human-like deduction:
        # 3 next to 0 => shared edge OFF, all other 3-edges ON already emerges from cell rules.
        # 3 next to 3 horizontally/vertically => their shared side must be ON? Not always alone.
        # We'll add a stronger generic residual pair check on each endpoint/cell context.
        for (r, c) in self.edge_cells[eid]:
            clue = self.clues[r][c]
            if clue is None:
                continue
            edges = self.cell_edges[r][c]
            # If a cell has exactly two unknown and needs one more, and those two unknown share a vertex
            # whose degree situation forbids one combination, local propagation elsewhere handles it.
            # Keep this lean.
        return True

    def global_consistency(self):
        # Cell bounds and vertex bounds are already enforced. Add loop-global feasibility checks.

        # No multiple closed components among ON edges.
        # Check if any connected ON component has all vertices degree 2 while some other ON edge exists/possible.
        comps = defaultdict(list)
        has_on = False
        for eid, st in enumerate(self.edge_state):
            if st == ON:
                has_on = True
                _, _, _, u, v = self.edges[eid]
                root = self.dsu.find(u)
                comps[root].append(eid)

        if has_on:
            closed_components = 0
            for root, eds in comps.items():
                verts = set()
                all_deg2 = True
                for eid in eds:
                    _, _, _, u, v = self.edges[eid]
                    verts.add(u)
                    verts.add(v)
                for v in verts:
                    if self.vertex_on[v] != 2:
                        all_deg2 = False
                        break
                if all_deg2:
                    closed_components += 1
            if closed_components >= 2:
                return False
            if closed_components == 1:
                # If one closed loop already exists, no other edge can still become ON.
                for eid, st in enumerate(self.edge_state):
                    if st == UNKNOWN and self.edge_can_be_on_quick(eid):
                        return False

        # Every degree-1 chain endpoint must have some possible expansion.
        for v in range(self.V):
            if self.vertex_on[v] == 1:
                if not any(self.edge_state[e] == UNKNOWN and self.edge_can_be_on_quick(e) for e in self.vertex_edges[v]):
                    return False

        # Cell exact completion feasibility already local, but add clue min/max after impossible unknown filtering.
        return True

    def edge_can_be_on_quick(self, eid):
        if self.edge_state[eid] != UNKNOWN:
            return self.edge_state[eid] == ON
        _, _, _, u, v = self.edges[eid]
        if self.vertex_on[u] >= 2 or self.vertex_on[v] >= 2:
            return False
        # Adjacent clue feasibility
        for r, c in self.edge_cells[eid]:
            clue = self.clues[r][c]
            if clue is None:
                continue
            on = 0
            unk = 0
            for e in self.cell_edges[r][c]:
                st = self.edge_state[e]
                if e == eid:
                    st = ON
                if st == ON:
                    on += 1
                elif st == UNKNOWN:
                    unk += 1
            if on > clue:
                return False
            if on + unk < clue:
                return False
        return True

    def is_solved(self):
        # All edges assigned
        if any(st == UNKNOWN for st in self.edge_state):
            return False

        # All clue cells exact
        for r in range(self.n):
            for c in range(self.n):
                clue = self.clues[r][c]
                if clue is None:
                    continue
                s = sum(1 for e in self.cell_edges[r][c] if self.edge_state[e] == ON)
                if s != clue:
                    return False

        # Vertex degrees 0 or 2, and at least one loop edge
        on_vertices = [v for v in range(self.V) if self.vertex_on[v] > 0]
        if not on_vertices:
            return False
        for v in on_vertices:
            if self.vertex_on[v] != 2:
                return False

        # Single connected loop
        root = None
        for eid, st in enumerate(self.edge_state):
            if st == ON:
                _, _, _, u, _ = self.edges[eid]
                root = self.dsu.find(u)
                break
        for eid, st in enumerate(self.edge_state):
            if st == ON:
                _, _, _, u, v = self.edges[eid]
                if self.dsu.find(u) != root or self.dsu.find(v) != root:
                    return False
        return True

    def choose_branch_edge(self):
        best = None
        best_score = None

        for eid, st in enumerate(self.edge_state):
            if st != UNKNOWN:
                continue
            score = 0
            # Prefer edges adjacent to clues and constrained vertices
            cells = self.edge_cells[eid]
            score += 3 * len(cells)
            for r, c in cells:
                clue = self.clues[r][c]
                if clue is not None:
                    edges = self.cell_edges[r][c]
                    on = sum(1 for e in edges if self.edge_state[e] == ON)
                    unk = sum(1 for e in edges if self.edge_state[e] == UNKNOWN)
                    score += 4 - unk
                    score += abs((clue - on) - (unk / 2.0))
            _, _, _, u, v = self.edges[eid]
            score += self.vertex_on[u] + self.vertex_on[v]
            # If one endpoint already degree 1, this is often decisive
            if self.vertex_on[u] == 1:
                score += 2
            if self.vertex_on[v] == 1:
                score += 2
            if best_score is None or score > best_score:
                best_score = score
                best = eid
        return best

    def branch_order(self, eid):
        # Try the more constrained-feasible value first.
        can_on = self.edge_can_be_on_quick(eid)
        can_off = self.edge_can_be_off_quick(eid)
        if can_on and not can_off:
            return [ON]
        if can_off and not can_on:
            return [OFF]
        # Heuristic: favor ON when it extends a path / satisfies high clues.
        _, _, _, u, v = self.edges[eid]
        score_on = self.vertex_on[u] + self.vertex_on[v]
        for r, c in self.edge_cells[eid]:
            clue = self.clues[r][c]
            if clue is not None:
                edges = self.cell_edges[r][c]
                on = sum(1 for e in edges if self.edge_state[e] == ON)
                score_on += max(0, clue - on)
        return [ON, OFF] if score_on >= 2 else [OFF, ON]

    def edge_can_be_off_quick(self, eid):
        if self.edge_state[eid] != UNKNOWN:
            return self.edge_state[eid] == OFF
        for r, c in self.edge_cells[eid]:
            clue = self.clues[r][c]
            if clue is None:
                continue
            on = 0
            unk = 0
            for e in self.cell_edges[r][c]:
                st = self.edge_state[e]
                if e == eid:
                    st = OFF
                if st == ON:
                    on += 1
                elif st == UNKNOWN:
                    unk += 1
            if on > clue:
                return False
            if on + unk < clue:
                return False
        # Vertex side: turning off can strand a degree-1 vertex if last continuation removed
        typ, r, c, u, v = self.edges[eid]
        for x in (u, v):
            if self.vertex_on[x] == 1:
                others = [e for e in self.vertex_edges[x] if e != eid and self.edge_state[e] == UNKNOWN]
                if not others:
                    return False
        return True

    def solve(self):
        if not self.propagate():
            return False
        return self.search()

    def search(self):
        if self.is_solved():
            return True

        eid = self.choose_branch_edge()
        if eid is None:
            return False

        for val in self.branch_order(eid):
            snap = self.snapshot()
            q = deque()
            if self.set_edge(eid, val, q) and self.propagate(q):
                if self.search():
                    return True
            self.rollback(snap)
        return False

    def extract_loop_path(self):
        if not self.is_solved():
            return None

        adj = defaultdict(list)
        for eid, st in enumerate(self.edge_state):
            if st == ON:
                _, _, _, u, v = self.edges[eid]
                adj[u].append(v)
                adj[v].append(u)

        start = None
        for v, nbrs in adj.items():
            if nbrs:
                start = v
                break
        if start is None:
            return None

        path_vids = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            if len(nbrs) != 2:
                return None
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            if nxt == start:
                path_vids.append(start)
                break
            path_vids.append(nxt)
            prev, cur = cur, nxt
            if len(path_vids) > sum(st == ON for st in self.edge_state) + 2:
                return None

        return [self.id_to_dot(v) for v in path_vids]

    def id_to_dot(self, vid):
        return (vid // self.dot_n, vid % self.dot_n)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 1, 2, 2, 2, 3], [0, 1, 2, 2, 2, 3], [0, 1, 4, 5, 3, 3], [0, 0, 4, 5, 6, 3], [0, 0, 5, 5, 6, 6], [7, 7, 7, 7, 6, 6]]}

# General solver for:
# - each region has exactly 2 shaded cells
# - shaded cells form dominoes (all shaded cells paired orthogonally)
# - different dominoes cannot touch orthogonally
# Dominoes may cross region borders.

from collections import defaultdict, deque
import ast

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): i for i, (r, c) in enumerate(cells)}

    def neigh4(r, c):
        if r > 0:
            yield (r - 1, c)
        if r + 1 < n:
            yield (r + 1, c)
        if c > 0:
            yield (r, c - 1)
        if c + 1 < m:
            yield (r, c + 1)

    neighbors = {cell: list(neigh4(*cell)) for cell in cells}

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Enumerate all possible domino placements.
    dominoes = []
    dom_id_of_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            if c + 1 < m:
                a, b = (r, c), (r, c + 1)
                did = len(dominoes)
                dominoes.append((a, b))
                dom_id_of_cells[a].append(did)
                dom_id_of_cells[b].append(did)
            if r + 1 < n:
                a, b = (r, c), (r + 1, c)
                did = len(dominoes)
                dominoes.append((a, b))
                dom_id_of_cells[a].append(did)
                dom_id_of_cells[b].append(did)

    # Domino conflict graph:
    # Two dominoes conflict if they share a cell or if any cell from one is orthogonally adjacent
    # to any cell from the other outside the domino itself, because distinct dominoes cannot touch.
    conflict = [set() for _ in range(len(dominoes))]
    for i, (a1, b1) in enumerate(dominoes):
        s1 = {a1, b1}
        ext1 = set()
        for x in s1:
            for y in neighbors[x]:
                if y not in s1:
                    ext1.add(y)
        for j in range(i + 1, len(dominoes)):
            a2, b2 = dominoes[j]
            s2 = {a2, b2}
            bad = False
            if s1 & s2:
                bad = True
            elif (a2 in ext1) or (b2 in ext1):
                bad = True
            else:
                ext2 = set()
                for x in s2:
                    for y in neighbors[x]:
                        if y not in s2:
                            ext2.add(y)
                if (a1 in ext2) or (b1 in ext2):
                    bad = True
            if bad:
                conflict[i].add(j)
                conflict[j].add(i)

    # For each region, precompute all ways it can obtain exactly 2 shaded cells by selected dominoes.
    # A pattern is a tuple of domino ids such that among cells of this region, exactly 2 are covered.
    region_patterns = {}
    region_pattern_covercount = {}
    region_pattern_domset = {}

    for rid in region_ids:
        rcells = regions[rid]
        candidate_dominoes = set()
        for cell in rcells:
            candidate_dominoes.update(dom_id_of_cells[cell])
        candidate_dominoes = sorted(candidate_dominoes)

        patterns = []
        covercounts = []
        domsets = []

        # Human-like bounded generation:
        # since region needs exactly 2 shaded cells, at most two dominoes can contribute
        # unless a single domino contributes 2 cells.
        # Generate all singleton and compatible pairs.
        for d in candidate_dominoes:
            cnt = 0
            for cell in dominoes[d]:
                if grid[cell[0]][cell[1]] == rid:
                    cnt += 1
            if cnt == 2:
                patterns.append((d,))
                covercounts.append({cell: (1 if cell in dominoes[d] else 0) for cell in rcells})
                domsets.append({d})

        L = candidate_dominoes
        for i in range(len(L)):
            d1 = L[i]
            c1 = 0
            cov1 = {}
            for cell in rcells:
                v = 1 if cell in dominoes[d1] else 0
                cov1[cell] = v
                c1 += v
            if c1 > 2:
                continue
            for j in range(i + 1, len(L)):
                d2 = L[j]
                if d2 in conflict[d1]:
                    continue
                total = 0
                cov = {}
                ok = True
                for cell in rcells:
                    v = (1 if cell in dominoes[d1] else 0) + (1 if cell in dominoes[d2] else 0)
                    if v > 1:
                        ok = False
                        break
                    cov[cell] = v
                    total += v
                if ok and total == 2:
                    patterns.append((d1, d2))
                    covercounts.append(cov)
                    domsets.append({d1, d2})

        # Deduplicate patterns by domino set.
        seen = set()
        up_patterns = []
        up_covercounts = []
        up_domsets = []
        for p, cov, ds in zip(patterns, covercounts, domsets):
            key = tuple(sorted(ds))
            if key not in seen:
                seen.add(key)
                up_patterns.append(p)
                up_covercounts.append(cov)
                up_domsets.append(ds)

        if not up_patterns:
            return "No Solution"

        region_patterns[rid] = up_patterns
        region_pattern_covercount[rid] = up_covercounts
        region_pattern_domset[rid] = up_domsets

    # Region adjacency by shared candidate domino, useful for propagation.
    domino_to_regions = defaultdict(set)
    for rid in region_ids:
        for ds in region_pattern_domset[rid]:
            for d in ds:
                domino_to_regions[d].add(rid)

    region_links = {rid: set() for rid in region_ids}
    for d, rs in domino_to_regions.items():
        rs = list(rs)
        for i in range(len(rs)):
            for j in range(i + 1, len(rs)):
                region_links[rs[i]].add(rs[j])
                region_links[rs[j]].add(rs[i])

    all_domino_ids = set(range(len(dominoes)))

    def propagate(domains):
        # domains: rid -> set(pattern_index)
        changed = True
        while changed:
            changed = False

            # Region domain nonempty and support-based filtering.
            for rid in region_ids:
                if not domains[rid]:
                    return None

            # Build forced/possible domino information.
            forced_dominoes = set()
            possible_dominoes = set()
            for rid in region_ids:
                pats = domains[rid]
                common = None
                union = set()
                for pi in pats:
                    ds = region_pattern_domset[rid][pi]
                    union |= ds
                    if common is None:
                        common = set(ds)
                    else:
                        common &= ds
                possible_dominoes |= union
                forced_dominoes |= common if common is not None else set()

            # Any forced domino excludes conflicting dominoes in every region.
            for d in list(forced_dominoes):
                bad = conflict[d]
                for rid in region_ids:
                    cur = domains[rid]
                    newset = set()
                    for pi in cur:
                        ds = region_pattern_domset[rid][pi]
                        if d in ds:
                            newset.add(pi)
                        else:
                            if ds.isdisjoint(bad):
                                newset.add(pi)
                    if newset != cur:
                        domains[rid] = newset
                        if not newset:
                            return None
                        changed = True

            # Region-local cell coverage deductions:
            # if a region cell can never be shaded among remaining patterns, fine;
            # if it must be shaded, then any pattern in linked regions using a conflicting domino is pruned
            # through domino forcing below. More direct and effective:
            # for each region, remove patterns using impossible dominoes due to lack of support elsewhere.
            for rid in region_ids:
                cur = domains[rid]
                supported = set()
                for pi in cur:
                    supported |= region_pattern_domset[rid][pi]
                newset = set()
                for pi in cur:
                    ds = region_pattern_domset[rid][pi]
                    if ds <= supported:
                        newset.add(pi)
                if newset != cur:
                    domains[rid] = newset
                    if not newset:
                        return None
                    changed = True

            # If a domino is forced in one region, no other region may use it.
            forced_owner = {}
            contradiction = False
            for rid in region_ids:
                cur = domains[rid]
                common = None
                for pi in cur:
                    ds = region_pattern_domset[rid][pi]
                    if common is None:
                        common = set(ds)
                    else:
                        common &= ds
                common = common or set()
                for d in common:
                    if d in forced_owner and forced_owner[d] != rid:
                        contradiction = True
                    forced_owner[d] = rid
            if contradiction:
                return None

            if forced_owner:
                for d, owner in forced_owner.items():
                    for rid in domino_to_regions.get(d, ()):
                        if rid == owner:
                            continue
                        cur = domains[rid]
                        newset = {pi for pi in cur if d not in region_pattern_domset[rid][pi]}
                        if newset != cur:
                            domains[rid] = newset
                            if not newset:
                                return None
                            changed = True

            # Arc-consistency on linked regions:
            # every pattern in a region must have at least one compatible pattern in each linked region.
            for rid in region_ids:
                for other in region_links[rid]:
                    cur1 = domains[rid]
                    cur2 = domains[other]
                    keep1 = set()
                    for p1 in cur1:
                        ds1 = region_pattern_domset[rid][p1]
                        ok = False
                        for p2 in cur2:
                            ds2 = region_pattern_domset[other][p2]
                            compatible = True
                            for d in ds1:
                                if d in ds2:
                                    compatible = False
                                    break
                                if conflict[d] & ds2:
                                    compatible = False
                                    break
                            if compatible:
                                ok = True
                                break
                        if ok:
                            keep1.add(p1)
                    if keep1 != cur1:
                        domains[rid] = keep1
                        if not keep1:
                            return None
                        changed = True

        return domains

    # Initial domains.
    domains = {rid: set(range(len(region_patterns[rid]))) for rid in region_ids}
    domains = propagate(domains)
    if domains is None:
        return "No Solution"

    def score_region(rid, domains):
        # Smallest domain first; tie-break by total distinct dominoes.
        pats = domains[rid]
        union = set()
        for pi in pats:
            union |= region_pattern_domset[rid][pi]
        return (len(pats), len(union), -len(region_links[rid]))

    def is_complete(domains):
        return all(len(domains[rid]) == 1 for rid in region_ids)

    def search(domains):
        domains = propagate({rid: set(v) for rid, v in domains.items()})
        if domains is None:
            return None
        if is_complete(domains):
            # Validate global uniqueness/conflicts.
            chosen = []
            for rid in region_ids:
                pi = next(iter(domains[rid]))
                chosen.append((rid, pi))
            used = set()
            for rid, pi in chosen:
                ds = region_pattern_domset[rid][pi]
                for d in ds:
                    if d in used:
                        return None
                    used.add(d)
            used_list = sorted(used)
            for i in range(len(used_list)):
                d1 = used_list[i]
                for j in range(i + 1, len(used_list)):
                    d2 = used_list[j]
                    if d2 in conflict[d1]:
                        return None
            return domains

        rid = min((r for r in region_ids if len(domains[r]) > 1), key=lambda r: score_region(r, domains))

        # Least-commitment branch order:
        # prefer patterns with more overlap with currently forced/likely dominoes.
        forced = set()
        possible_count = defaultdict(int)
        for rr in region_ids:
            common = None
            for pi in domains[rr]:
                ds = region_pattern_domset[rr][pi]
                if common is None:
                    common = set(ds)
                else:
                    common &= ds
                for d in ds:
                    possible_count[d] += 1
            forced |= (common or set())

        choices = list(domains[rid])
        def pattern_rank(pi):
            ds = region_pattern_domset[rid][pi]
            return (-sum(1 for d in ds if d in forced), sum(possible_count[d] for d in ds), len(ds))
        choices.sort(key=pattern_rank)

        for pi in choices:
            new_domains = {r: set(v) for r, v in domains.items()}
            new_domains[rid] = {pi}
            res = search(new_domains)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    shaded = [[None for _ in range(m)] for _ in range(n)]
    for rid in region_ids:
        pi = next(iter(result[rid]))
        ds = region_pattern_domset[rid][pi]
        for d in ds:
            a, b = dominoes[d]
            shaded[a[0]][a[1]] = 'S'
            shaded[b[0]][b[1]] = 'S'

    # Final validation.
    region_shaded = defaultdict(int)
    for r in range(n):
        for c in range(m):
            if shaded[r][c] == 'S':
                region_shaded[grid[r][c]] += 1
    for rid in region_ids:
        if region_shaded[rid] != 2:
            return "No Solution"

    for r in range(n):
        for c in range(m):
            if shaded[r][c] == 'S':
                cnt = 0
                for nr, nc in neighbors[(r, c)]:
                    if shaded[nr][nc] == 'S':
                        cnt += 1
                if cnt != 1:
                    return "No Solution"

    used_dominoes = []
    seen_cells = set()
    for r in range(n):
        for c in range(m):
            if shaded[r][c] == 'S' and (r, c) not in seen_cells:
                adj = [(nr, nc) for nr, nc in neighbors[(r, c)] if shaded[nr][nc] == 'S']
                if len(adj) != 1:
                    return "No Solution"
                other = adj[0]
                pair = tuple(sorted(((r, c), other)))
                used_dominoes.append(pair)
                seen_cells.add((r, c))
                seen_cells.add(other)

    for i in range(len(used_dominoes)):
        s1 = set(used_dominoes[i])
        for j in range(i + 1, len(used_dominoes)):
            s2 = set(used_dominoes[j])
            for a in s1:
                for b in s2:
                    if abs(a[0] - b[0]) + abs(a[1] - b[1]) == 1:
                        return "No Solution"

    return repr(shaded)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 2, None, 2, None], [None, None, 2, None, None], [1, 2, 1, 3, 2], [2, 3, None, None, None], [None, 2, 3, 3, None]]}

from collections import deque, defaultdict

# Slitherlink solver:
# - Edges are binary variables.
# - Human-like propagation:
#   * cell clue exact-count filtering
#   * dot degree filtering (0 or 2 only, never >2)
#   * no small closed loops before all used edges form a single loop
#   * line continuation at degree-1 dots
#   * forced completion/forbidden by local counts
# - Search:
#   * branch on most constrained unresolved edge
#   * maintain rollback by copying compact state
# This is a generalized solver for N x N clue grids.


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0:
        return "No Solution"

    # Horizontal edges: h[r][c] connects (r,c) - (r,c+1), r in [0..n], c in [0..n-1]
    # Vertical edges:   v[r][c] connects (r,c) - (r+1,c), r in [0..n-1], c in [0..n]
    # State values: -1 unknown, 0 empty, 1 line

    h_count = (n + 1) * n
    v_count = n * (n + 1)
    total_edges = h_count + v_count

    def h_id(r, c):
        return r * n + c

    def v_id(r, c):
        return h_count + r * (n + 1) + c

    def edge_endpoints(eid):
        if eid < h_count:
            r, c = divmod(eid, n)
            return (r, c), (r, c + 1)
        x = eid - h_count
        r, c = divmod(x, n + 1)
        return (r, c), (r + 1, c)

    def cell_edges(r, c):
        return (
            h_id(r, c),
            h_id(r + 1, c),
            v_id(r, c),
            v_id(r, c + 1),
        )

    def dot_edges(r, c):
        out = []
        if c > 0:
            out.append(h_id(r, c - 1))
        if c < n:
            out.append(h_id(r, c))
        if r > 0:
            out.append(v_id(r - 1, c))
        if r < n:
            out.append(v_id(r, c))
        return out

    # Precompute adjacency
    edge_to_cells = [[] for _ in range(total_edges)]
    clues = []
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                ce = cell_edges(r, c)
                for e in ce:
                    edge_to_cells[e].append((r, c))
                clues.append((r, c, data[r][c]))
            else:
                ce = cell_edges(r, c)
                for e in ce:
                    edge_to_cells[e].append((r, c))

    edge_to_dots = [edge_endpoints(e) for e in range(total_edges)]

    dot_list = [(r, c) for r in range(n + 1) for c in range(n + 1)]
    dot_to_edges = {}
    for d in dot_list:
        dot_to_edges[d] = dot_edges(*d)

    cell_to_edges = {}
    for r in range(n):
        for c in range(n):
            cell_to_edges[(r, c)] = cell_edges(r, c)

    # Neighbor edges that share a dot with this edge
    edge_neighbors = []
    for e in range(total_edges):
        a, b = edge_to_dots[e]
        s = set(dot_to_edges[a] + dot_to_edges[b])
        s.discard(e)
        edge_neighbors.append(tuple(s))

    class State:
        __slots__ = ("val", "line_deg", "unknown_deg", "cell_on", "cell_unknown")

        def __init__(self):
            self.val = [-1] * total_edges
            self.line_deg = {d: 0 for d in dot_list}
            self.unknown_deg = {d: len(dot_to_edges[d]) for d in dot_list}
            self.cell_on = {}
            self.cell_unknown = {}
            for r in range(n):
                for c in range(n):
                    self.cell_on[(r, c)] = 0
                    self.cell_unknown[(r, c)] = 4

        def copy(self):
            s = State.__new__(State)
            s.val = self.val[:]
            s.line_deg = self.line_deg.copy()
            s.unknown_deg = self.unknown_deg.copy()
            s.cell_on = self.cell_on.copy()
            s.cell_unknown = self.cell_unknown.copy()
            return s

    def assigned_line_edges(state):
        return [e for e, v in enumerate(state.val) if v == 1]

    def build_line_components(state):
        # Returns:
        #   components: list of (dots_set, edges_set)
        #   edge_to_comp
        used = [e for e, v in enumerate(state.val) if v == 1]
        if not used:
            return [], {}
        dot_adj = defaultdict(list)
        for e in used:
            a, b = edge_to_dots[e]
            dot_adj[a].append((b, e))
            dot_adj[b].append((a, e))
        seen_dots = set()
        comps = []
        edge_to_comp = {}
        for d in list(dot_adj.keys()):
            if d in seen_dots:
                continue
            q = [d]
            seen_dots.add(d)
            dots = set()
            edges = set()
            while q:
                x = q.pop()
                dots.add(x)
                for y, e in dot_adj[x]:
                    edges.add(e)
                    if y not in seen_dots:
                        seen_dots.add(y)
                        q.append(y)
            idx = len(comps)
            for e in edges:
                edge_to_comp[e] = idx
            comps.append((dots, edges))
        return comps, edge_to_comp

    def forms_small_loop_if_set(state, eid):
        # If setting eid=1 closes a cycle while there remain other line edges elsewhere,
        # reject unless the whole line set would become a single complete loop at the end.
        a, b = edge_to_dots[eid]
        used = [e for e, v in enumerate(state.val) if v == 1]
        if not used:
            return False

        # path existence between a and b in current used-edge graph
        dot_adj = defaultdict(list)
        for e in used:
            x, y = edge_to_dots[e]
            dot_adj[x].append(y)
            dot_adj[y].append(x)

        if a not in dot_adj or b not in dot_adj:
            return False

        q = deque([a])
        seen = {a}
        while q:
            x = q.popleft()
            if x == b:
                # Adding eid closes a cycle in an existing component.
                # If there are any other used edges outside this component, it's a forbidden small loop.
                comps, edge_to_comp = build_line_components(state)
                comp_idx = None
                for e in used:
                    x1, y1 = edge_to_dots[e]
                    if x1 in seen and y1 in seen:
                        comp_idx = edge_to_comp[e]
                        break
                if comp_idx is None:
                    return False
                comp_edges = comps[comp_idx][1]
                if len(comp_edges) != len(used):
                    return True
                # Even if all current used edges are in one component, closing now is only okay
                # if all dots in component will have degree 2 and no future line elsewhere possible.
                # Let general consistency checks handle completeness at terminal state.
                return False
            for y in dot_adj[x]:
                if y not in seen:
                    seen.add(y)
                    q.append(y)
        return False

    def set_edge(state, eid, value, queue):
        cur = state.val[eid]
        if cur == value:
            return True
        if cur != -1:
            return False

        if value == 1 and forms_small_loop_if_set(state, eid):
            return False

        state.val[eid] = value
        a, b = edge_to_dots[eid]

        for d in (a, b):
            state.unknown_deg[d] -= 1
            if value == 1:
                state.line_deg[d] += 1
            if state.line_deg[d] > 2:
                return False
            if state.line_deg[d] + state.unknown_deg[d] < 2 and state.line_deg[d] == 1:
                return False
            queue.append(("dot", d))

        for cell in edge_to_cells[eid]:
            state.cell_unknown[cell] -= 1
            if value == 1:
                state.cell_on[cell] += 1
            queue.append(("cell", cell))

        return True

    def process_cell(state, cell, queue):
        r, c = cell
        clue = data[r][c]
        if clue is None:
            return True
        on = state.cell_on[cell]
        unk = state.cell_unknown[cell]
        if on > clue:
            return False
        if on + unk < clue:
            return False

        edges = cell_to_edges[cell]
        if on == clue:
            for e in edges:
                if state.val[e] == -1:
                    if not set_edge(state, e, 0, queue):
                        return False
        elif on + unk == clue:
            for e in edges:
                if state.val[e] == -1:
                    if not set_edge(state, e, 1, queue):
                        return False

        return True

    def process_dot(state, dot, queue):
        ld = state.line_deg[dot]
        ud = state.unknown_deg[dot]
        if ld > 2:
            return False
        if ld == 1 and ud == 0:
            return False
        if ld == 0 and ud == 0:
            return True

        edges = dot_to_edges[dot]

        # Dot must have degree 0 or 2.
        if ld == 2:
            for e in edges:
                if state.val[e] == -1:
                    if not set_edge(state, e, 0, queue):
                        return False
        elif ld == 1 and ud == 1:
            for e in edges:
                if state.val[e] == -1:
                    if not set_edge(state, e, 1, queue):
                        return False
        elif ld == 0 and ud == 1:
            # Can't end with degree 1, so sole unknown must be 0
            for e in edges:
                if state.val[e] == -1:
                    if not set_edge(state, e, 0, queue):
                        return False

        # If ld + ud == 2, all remaining unknowns must be 1 to reach degree 2
        if ld < 2 and ld + ud == 2:
            for e in edges:
                if state.val[e] == -1:
                    if not set_edge(state, e, 1, queue):
                        return False

        return True

    def propagate(state):
        queue = deque()

        for r in range(n):
            for c in range(n):
                if data[r][c] is not None:
                    queue.append(("cell", (r, c)))
        for d in dot_list:
            queue.append(("dot", d))

        while queue:
            typ, obj = queue.popleft()
            if typ == "cell":
                if not process_cell(state, obj, queue):
                    return False
            else:
                if not process_dot(state, obj, queue):
                    return False

        # Global component consistency:
        comps, _ = build_line_components(state)
        if len(comps) > 1:
            # If there are multiple closed components already, impossible.
            closed = 0
            for dots, edges in comps:
                all_deg2 = True
                for d in dots:
                    if state.line_deg[d] != 2:
                        all_deg2 = False
                        break
                if all_deg2:
                    closed += 1
            if closed > 0:
                return False

        # Additional clue feasibility with dot constraints around undecided edges is already covered.
        return True

    def is_solved(state):
        if any(v == -1 for v in state.val):
            return False
        # clue exactness
        for r in range(n):
            for c in range(n):
                clue = data[r][c]
                if clue is not None and state.cell_on[(r, c)] != clue:
                    return False
        # dot degrees are 0 or 2, and at least one loop edge exists
        used = [e for e, v in enumerate(state.val) if v == 1]
        if not used:
            return False
        active_dots = set()
        for e in used:
            a, b = edge_to_dots[e]
            active_dots.add(a)
            active_dots.add(b)
        for d in active_dots:
            if state.line_deg[d] != 2:
                return False
        # single component
        comps, _ = build_line_components(state)
        return len(comps) == 1

    def edge_score(state, eid):
        # Lower score = stronger candidate for branching
        # Favor edges adjacent to constrained clues/dots.
        cells = edge_to_cells[eid]
        clue_tight = 0
        for cell in cells:
            clue = data[cell[0]][cell[1]]
            if clue is not None:
                on = state.cell_on[cell]
                unk = state.cell_unknown[cell]
                clue_tight += 4 - (unk + min(abs(clue - on), abs((on + unk) - clue)))
        a, b = edge_to_dots[eid]
        dot_tight = state.line_deg[a] + state.line_deg[b] + (4 - state.unknown_deg[a]) + (4 - state.unknown_deg[b])
        return -(clue_tight * 10 + dot_tight)

    def choose_edge(state):
        unknowns = [e for e, v in enumerate(state.val) if v == -1]
        if not unknowns:
            return None
        unknowns.sort(key=lambda e: edge_score(state, e))
        return unknowns[0]

    def search(state, depth=0):
        if not propagate(state):
            return None
        if is_solved(state):
            return state

        eid = choose_edge(state)
        if eid is None:
            return None

        # Value ordering:
        # Try line first when locally plausible near high clues / degree-1 dots.
        a, b = edge_to_dots[eid]
        prefer_one = False
        for d in (a, b):
            if state.line_deg[d] == 1:
                prefer_one = True
        for cell in edge_to_cells[eid]:
            clue = data[cell[0]][cell[1]]
            if clue is not None:
                on = state.cell_on[cell]
                unk = state.cell_unknown[cell]
                if clue - on > 0 and clue - on >= unk - 1:
                    prefer_one = True

        trial_values = (1, 0) if prefer_one else (0, 1)

        for val in trial_values:
            st2 = state.copy()
            q = deque()
            if set_edge(st2, eid, val, q):
                # finish immediate queued implications from this assignment first
                ok = True
                while q and ok:
                    typ, obj = q.popleft()
                    if typ == "cell":
                        ok = process_cell(st2, obj, q)
                    else:
                        ok = process_dot(st2, obj, q)
                if ok:
                    res = search(st2, depth + 1)
                    if res is not None:
                        return res
        return None

    def extract_loop(state):
        used = [e for e, v in enumerate(state.val) if v == 1]
        if not used:
            return None

        dot_adj = defaultdict(list)
        for e in used:
            a, b = edge_to_dots[e]
            dot_adj[a].append(b)
            dot_adj[b].append(a)

        start = min(dot_adj.keys())
        path = [start]
        prev = None
        cur = start

        while True:
            nbrs = dot_adj[cur]
            if len(nbrs) != 2:
                return None
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(used) + 2:
                return None
        return path

    initial = State()
    result = search(initial)
    if result is None:
        return "No Solution"
    loop = extract_loop(result)
    if loop is None:
        return "No Solution"
    return str(loop)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, None, None, 'B3', 'B3', 'B2'], [None, None, 'W2', None, None, None], [None, 'W2', None, None, None, None], [None, None, None, None, None, 'W2'], ['B7', None, None, None, 'B2', None]]}

from copy import deepcopy

# General Masyu-like straight-length loop solver:
# - vertices are dots on an (R x C) lattice where R=C=len(data)
# - clues live on cells addressed by same integer coordinates as dots in the prompt
# - loop runs along unit grid edges between adjacent dots
#
# This solver is designed around human-style deduction:
# 1) local degree rules at every dot
# 2) clue-shape feasibility filtering
# 3) straight-run length implications from numbered clues
# 4) aggressive propagation of forced edges
# 5) only then a tightly-pruned branch search
#
# Return format:
#   ordered closed loop path as a Python list of (row, col), or "No Solution"


def solve(observation):
    data = observation["data"]
    n = len(data)  # dots are 0..n-1 in both directions

    # Edge indexing
    # Horizontal edge H[r][c]: (r,c) -- (r,c+1), 0<=r<n, 0<=c<n-1
    # Vertical edge   V[r][c]: (r,c) -- (r+1,c), 0<=r<n-1, 0<=c<n
    edges = []
    edge_id = {}
    edge_ends = []

    def add_edge(a, b):
        i = len(edges)
        edges.append(i)
        edge_id[(a, b)] = i
        edge_id[(b, a)] = i
        edge_ends.append((a, b))

    for r in range(n):
        for c in range(n - 1):
            add_edge((r, c), (r, c + 1))
    for r in range(n - 1):
        for c in range(n):
            add_edge((r, c), (r + 1, c))

    m = len(edges)

    # Incidence per dot
    dot_edges = [[[] for _ in range(n)] for _ in range(n)]
    for eid, (a, b) in enumerate(edge_ends):
        ar, ac = a
        br, bc = b
        dot_edges[ar][ac].append(eid)
        dot_edges[br][bc].append(eid)

    # Directions around a cell/dot-coordinate clue position.
    # A clue at (r,c) refers to the loop passing through the dot-position coordinate.
    # The loop can use two incident edges there.
    # White: straight (UD or LR)
    # Black: turn (UL, UR, DL, DR)
    #
    # Number k = total lengths of the two straight segments extending from that circle.
    # For a straight clue, these are the two opposite directions of the line.
    # For a turn clue, these are the two outgoing legs after the turn.
    #
    # We precompute candidate local patterns and corresponding required total lengths.
    def get_dir_edge(r, c, d):
        if d == "U":
            if r == 0:
                return None
            return edge_id[((r, c), (r - 1, c))]
        if d == "D":
            if r == n - 1:
                return None
            return edge_id[((r, c), (r + 1, c))]
        if d == "L":
            if c == 0:
                return None
            return edge_id[((r, c), (r, c - 1))]
        if d == "R":
            if c == n - 1:
                return None
            return edge_id[((r, c), (r, c + 1))]
        return None

    opposite = {"U": "D", "D": "U", "L": "R", "R": "L"}
    drdc = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}

    clue_patterns = []
    clues = []
    for r in range(n):
        for c in range(n):
            tok = data[r][c]
            if tok is None:
                continue
            typ = tok[0]
            k = int(tok[1:])
            dirs = []
            if typ == "W":
                dirs = [("U", "D"), ("L", "R")]
            else:
                dirs = [("U", "L"), ("U", "R"), ("D", "L"), ("D", "R")]
            pats = []
            for d1, d2 in dirs:
                e1 = get_dir_edge(r, c, d1)
                e2 = get_dir_edge(r, c, d2)
                if e1 is None or e2 is None:
                    continue
                pats.append((d1, d2, e1, e2, k, typ))
            clues.append((r, c, typ, k))
            clue_patterns.append(pats)

    # For each clue direction, list of edges in the ray outward from clue.
    # The clue's own incident edge counts as the first unit if selected.
    def ray_edges(r, c, d):
        res = []
        cr, cc = r, c
        while True:
            e = get_dir_edge(cr, cc, d)
            if e is None:
                break
            res.append(e)
            rr, cc2 = drdc[d]
            cr += rr
            cc += cc2
        return res

    clue_rays = []
    for (r, c, typ, k), pats in zip(clues, clue_patterns):
        dmap = {}
        for d in "UDLR":
            dmap[d] = ray_edges(r, c, d)
        clue_rays.append(dmap)

    # State: -1 unknown, 0 off, 1 on
    init_state = [-1] * m

    # Union-find for currently ON edges to detect premature small loops
    class DSU:
        __slots__ = ("p", "r")
        def __init__(self, n_):
            self.p = list(range(n_))
            self.r = [0] * n_
        def find(self, x):
            p = self.p
            while p[x] != x:
                p[x] = p[p[x]]
                x = p[x]
            return x
        def union(self, a, b):
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.r[ra] < self.r[rb]:
                ra, rb = rb, ra
            self.p[rb] = ra
            if self.r[ra] == self.r[rb]:
                self.r[ra] += 1
            return True

    # Cache all dot coordinates
    dots = [(r, c) for r in range(n) for c in range(n)]

    def degree_info(state, r, c):
        on = off = unk = 0
        unk_edges = []
        for e in dot_edges[r][c]:
            v = state[e]
            if v == 1:
                on += 1
            elif v == 0:
                off += 1
            else:
                unk += 1
                unk_edges.append(e)
        return on, off, unk, unk_edges

    def set_edge(state, e, val, queue):
        cur = state[e]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[e] = val
        a, b = edge_ends[e]
        queue.append(("dot", a[0], a[1]))
        queue.append(("dot", b[0], b[1]))
        return True

    def force_dot_degree(state, r, c, queue):
        on, off, unk, unk_edges = degree_info(state, r, c)
        if on > 2:
            return False
        if on == 1 and unk == 0:
            return False
        if on == 0 and unk == 1:
            return False
        if on == 2:
            for e in unk_edges:
                if not set_edge(state, e, 0, queue):
                    return False
        elif on == 1 and unk == 1:
            if not set_edge(state, unk_edges[0], 1, queue):
                return False
        elif on == 0 and unk == 2:
            for e in unk_edges:
                if not set_edge(state, e, 1, queue):
                    return False
        return True

    def clue_pattern_feasible(state, clue_idx, pat):
        r, c, typ, k = clues[clue_idx]
        d1, d2, e1, e2, _, _ = pat

        # Local shape at clue
        if state[e1] == 0 or state[e2] == 0:
            return False
        # All other incident edges at clue must be off
        needed = {e1, e2}
        for e in dot_edges[r][c]:
            if e not in needed and state[e] == 1:
                return False

        # Length feasibility on each selected ray
        def ray_len_bounds(ray):
            # Segment must start from clue and continue contiguously until stop.
            # Since it's a straight segment extending from the clue,
            # chosen prefix length t>=1: first t edges ON, next edge if exists OFF.
            # Unknowns give interval.
            max_t = 0
            for e in ray:
                if state[e] == 0:
                    break
                max_t += 1
            min_t = 0
            for e in ray:
                if state[e] == 1:
                    min_t += 1
                else:
                    break
            if not ray or state[ray[0]] == 0:
                return None
            if state[ray[0]] == -1:
                min_t = 1
            else:
                min_t = max(1, min_t)
            return min_t, max_t

        b1 = ray_len_bounds(clue_rays[clue_idx][d1])
        b2 = ray_len_bounds(clue_rays[clue_idx][d2])
        if b1 is None or b2 is None:
            return False

        minsum = b1[0] + b2[0]
        maxsum = b1[1] + b2[1]
        if not (minsum <= k <= maxsum):
            return False

        # There must exist integer lengths l1,l2 in bounds summing to k.
        low = max(b1[0], k - b2[1])
        high = min(b1[1], k - b2[0])
        return low <= high

    def propagate_clue_from_patterns(state, clue_idx, queue):
        pats = clue_patterns[clue_idx]
        feas = [pat for pat in pats if clue_pattern_feasible(state, clue_idx, pat)]
        if not feas:
            return False

        r, c, typ, k = clues[clue_idx]

        # Force common incident edge decisions at clue center
        inc = dot_edges[r][c]
        common_on = set(inc)
        common_off = set(inc)
        for pat in feas:
            _, _, e1, e2, _, _ = pat
            need = {e1, e2}
            common_on &= need
            common_off &= (set(inc) - need)
        for e in common_on:
            if not set_edge(state, e, 1, queue):
                return False
        for e in common_off:
            if not set_edge(state, e, 0, queue):
                return False

        # Length-based forcing along rays
        dir_used = {}
        for d in "UDLR":
            dir_used[d] = all((d in (pat[0], pat[1])) for pat in feas)
        # If every feasible pattern uses a direction, its first edge must be on
        for d in "UDLR":
            ray = clue_rays[clue_idx][d]
            if not ray:
                continue
            if dir_used[d]:
                if not set_edge(state, ray[0], 1, queue):
                    return False

        # For each feasible orientation separately, derive possible lengths;
        # if all feasible patterns that use a direction require a common prefix/suffix relation, force it.
        for d in "UDLR":
            ray = clue_rays[clue_idx][d]
            if not ray:
                continue
            relevant = []
            for pat in feas:
                if d not in (pat[0], pat[1]):
                    continue
                other = pat[1] if pat[0] == d else pat[0]
                ray1 = clue_rays[clue_idx][d]
                ray2 = clue_rays[clue_idx][other]

                def bounds(ray_):
                    max_t = 0
                    for e in ray_:
                        if state[e] == 0:
                            break
                        max_t += 1
                    min_t = 0
                    for e in ray_:
                        if state[e] == 1:
                            min_t += 1
                        else:
                            break
                    if not ray_ or state[ray_[0]] == 0:
                        return None
                    if state[ray_[0]] == -1:
                        min_t = 1
                    else:
                        min_t = max(1, min_t)
                    return min_t, max_t

                b1 = bounds(ray1)
                b2 = bounds(ray2)
                if b1 is None or b2 is None:
                    continue
                lo = max(b1[0], k - b2[1])
                hi = min(b1[1], k - b2[0])
                if lo <= hi:
                    relevant.append((lo, hi))
            if not relevant:
                continue
            forced_min = max(lo for lo, hi in relevant)
            forced_max = min(hi for lo, hi in relevant)
            # Common guaranteed ON prefix = min of all lower bounds? To be safe:
            guaranteed_on = min(lo for lo, hi in relevant)
            # Any edge beyond max possible length is OFF.
            impossible_after = max(hi for lo, hi in relevant)

            for i, e in enumerate(ray):
                if i < guaranteed_on:
                    if not set_edge(state, e, 1, queue):
                        return False
                if i > impossible_after - 1:
                    if not set_edge(state, e, 0, queue):
                        return False

        return True

    def all_clues_propagate(state, queue):
        for i in range(len(clues)):
            if not propagate_clue_from_patterns(state, i, queue):
                return False
        return True

    def component_check(state):
        # Build DSU on dots through ON edges, count used vertices/edges, prevent closed subtour
        dsu = DSU(n * n)
        on_edges = []
        for e, v in enumerate(state):
            if v == 1:
                on_edges.append(e)
                (r1, c1), (r2, c2) = edge_ends[e]
                dsu.union(r1 * n + c1, r2 * n + c2)

        # If all decided later, exact single-loop checked elsewhere.
        # Here only prune: any connected component where every involved dot currently has degree 2
        # and component does not contain all on-structure + no unknown exits => premature cycle.
        comp_vertices = {}
        comp_edges = {}
        for e in on_edges:
            (r1, c1), (r2, c2) = edge_ends[e]
            root = dsu.find(r1 * n + c1)
            comp_vertices.setdefault(root, set()).add((r1, c1))
            comp_vertices[root].add((r2, c2))
            comp_edges[root] = comp_edges.get(root, 0) + 1

        if len(comp_vertices) <= 1:
            return True

        for root, verts in comp_vertices.items():
            all_deg2 = True
            has_unknown_exit = False
            for r, c in verts:
                on, off, unk, unk_edges = degree_info(state, r, c)
                if on != 2:
                    all_deg2 = False
                for e in unk_edges:
                    a, b = edge_ends[e]
                    other = b if a == (r, c) else a
                    if other not in verts:
                        has_unknown_exit = True
            if all_deg2 and not has_unknown_exit:
                return False
        return True

    def propagate(state):
        queue = []
        for r in range(n):
            for c in range(n):
                queue.append(("dot", r, c))
        for i in range(len(clues)):
            queue.append(("clue", i))

        seen = 0
        while queue:
            item = queue.pop()
            seen += 1
            if item[0] == "dot":
                _, r, c = item
                if not force_dot_degree(state, r, c, queue):
                    return False
            else:
                _, i = item
                if not propagate_clue_from_patterns(state, i, queue):
                    return False

            if not component_check(state):
                return False

        # Global sanity: each clue must still have a feasible pattern
        for i in range(len(clues)):
            ok = False
            for pat in clue_patterns[i]:
                if clue_pattern_feasible(state, i, pat):
                    ok = True
                    break
            if not ok:
                return False
        return True

    def final_check(state):
        # every dot degree 0 or 2, and clues passed, and exactly one cycle using all on edges
        for r in range(n):
            for c in range(n):
                on, off, unk, unk_edges = degree_info(state, r, c)
                if unk != 0:
                    return False
                if on not in (0, 2):
                    return False

        for i in range(len(clues)):
            feas = [pat for pat in clue_patterns[i] if clue_pattern_feasible(state, i, pat)]
            if not feas:
                return False
            # In final state at least one exact pattern
            exact = False
            r, c, typ, k = clues[i]
            for pat in feas:
                d1, d2, e1, e2, _, _ = pat
                if state[e1] != 1 or state[e2] != 1:
                    continue

                def exact_len(ray):
                    if not ray or state[ray[0]] != 1:
                        return None
                    cnt = 0
                    for e in ray:
                        if state[e] == 1:
                            cnt += 1
                        else:
                            break
                    if cnt < len(ray) and state[ray[cnt]] != 0:
                        return None
                    return cnt

                l1 = exact_len(clue_rays[i][d1])
                l2 = exact_len(clue_rays[i][d2])
                if l1 is not None and l2 is not None and l1 + l2 == k:
                    exact = True
                    break
            if not exact:
                return False

        on_edges = [e for e, v in enumerate(state) if v == 1]
        if not on_edges:
            return False

        # single cycle
        adj = {}
        for e in on_edges:
            a, b = edge_ends[e]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
        for v in adj:
            if len(adj[v]) != 2:
                return False
        start = next(iter(adj))
        seen = set()
        cur = start
        prev = None
        while True:
            seen.add(cur)
            nbrs = adj[cur]
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            prev, cur = cur, nxt
            if cur == start:
                break
            if cur in seen:
                return False
        if len(seen) != len(adj):
            return False
        return True

    def choose_branch_edge(state):
        # Human-like branching: pick most constrained clue first, then one of its key unknown edges.
        best = None
        for i, (r, c, typ, k) in enumerate(clues):
            feas = [pat for pat in clue_patterns[i] if clue_pattern_feasible(state, i, pat)]
            score = len(feas)
            unknown_local = [e for e in dot_edges[r][c] if state[e] == -1]
            if unknown_local:
                cand = (score, len(unknown_local), i, unknown_local[0])
                if best is None or cand < best:
                    best = cand
        if best is not None:
            return best[3]

        # Fallback: choose edge near high-degree uncertainty
        best_e = None
        best_sc = None
        for e, v in enumerate(state):
            if v != -1:
                continue
            (r1, c1), (r2, c2) = edge_ends[e]
            sc = 0
            for r, c in [(r1, c1), (r2, c2)]:
                on, off, unk, unk_edges = degree_info(state, r, c)
                sc += (4 - unk) + on * 2
            if best_sc is None or sc > best_sc:
                best_sc = sc
                best_e = e
        return best_e

    def search(state):
        if not propagate(state):
            return None
        if all(v != -1 for v in state):
            if final_check(state):
                return state
            return None

        e = choose_branch_edge(state)
        if e is None:
            return None

        # Value ordering: prefer ON if it fits local degree better.
        for val in (1, 0):
            st2 = state[:]
            q = []
            if set_edge(st2, e, val, q):
                res = search(st2)
                if res is not None:
                    return res
        return None

    def extract_loop(state):
        adj = {}
        for e, v in enumerate(state):
            if v == 1:
                a, b = edge_ends[e]
                adj.setdefault(a, []).append(b)
                adj.setdefault(b, []).append(a)
        if not adj:
            return None
        start = min(adj)
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        return path

    ans_state = search(init_state)
    if ans_state is None:
        return "No Solution"
    loop = extract_loop(ans_state)
    return str(loop)


