OBSERVATION = {'data': [[0, 0, 0, 0, 1, 1, 1, 1], [0, 2, 2, 0, 3, 3, 1, 1], [0, 4, 4, 0, 3, 1, 1, 5], [4, 4, 4, 6, 3, 3, 1, 5], [4, 4, 4, 6, 7, 7, 1, 5], [4, 8, 8, 7, 7, 7, 9, 10], [4, 11, 12, 12, 9, 9, 9, 10], [11, 11, 11, 12, 12, 12, 12, 10]]}

from collections import defaultdict, deque

# Solver for the puzzle:
# - each region contains exactly 2 shaded cells
# - shaded cells form dominoes (every shaded cell has exactly one orthogonally adjacent shaded cell)
# - different dominoes cannot touch orthogonally
# Dominoes may cross region boundaries.

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]

    def idx(r, c):
        return r * m + c

    def rc(i):
        return divmod(i, m)

    # Orthogonal adjacency
    neigh = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            if r > 0:
                neigh[i].append(idx(r - 1, c))
            if r + 1 < n:
                neigh[i].append(idx(r + 1, c))
            if c > 0:
                neigh[i].append(idx(r, c - 1))
            if c + 1 < m:
                neigh[i].append(idx(r, c + 1))

    # Regions
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[data[r][c]].append(idx(r, c))
    region_ids = sorted(region_cells)

    # All possible domino placements (edges)
    edge_list = []
    edge_of_pair = {}
    incident_edges = [[] for _ in range(n * m)]
    for i in range(n * m):
        for j in neigh[i]:
            if i < j:
                e = len(edge_list)
                edge_list.append((i, j))
                edge_of_pair[(i, j)] = e
                incident_edges[i].append(e)
                incident_edges[j].append(e)

    E = len(edge_list)

    # Conflict graph between dominoes:
    # two dominoes conflict if they share a cell OR if any cell of one is orthogonally adjacent
    # to any cell of the other (different dominoes cannot touch orthogonally).
    edge_conflicts = [set() for _ in range(E)]
    cell_to_incident = incident_edges

    for e, (a, b) in enumerate(edge_list):
        banned_edges = set()
        related_cells = {a, b}
        for x in (a, b):
            related_cells.update(neigh[x])
        for cell in related_cells:
            banned_edges.update(cell_to_incident[cell])
        banned_edges.discard(e)
        edge_conflicts[e] = banned_edges

    # Region-wise candidate dominoes contributing 0,1,2 cells to each region.
    # Human-like perspective: a region must collect exactly 2 shaded cells from selected dominoes.
    region_cover_edges = {}
    edge_region_count = [[0] * len(region_ids) for _ in range(E)]
    region_index = {rid: k for k, rid in enumerate(region_ids)}

    for rid in region_ids:
        region_set = set(region_cells[rid])
        cands = []
        for e, (a, b) in enumerate(edge_list):
            cnt = (1 if a in region_set else 0) + (1 if b in region_set else 0)
            if cnt:
                cands.append(e)
                edge_region_count[e][region_index[rid]] = cnt
        region_cover_edges[rid] = cands

    # Precompute per-cell region index
    cell_region_idx = [0] * (n * m)
    for rid in region_ids:
        k = region_index[rid]
        for i in region_cells[rid]:
            cell_region_idx[i] = k

    R = len(region_ids)

    # Fast structures for propagation
    all_edges_set = set(range(E))

    # For each region and each target remainder, useful quick tests
    region_cell_sets = {rid: set(region_cells[rid]) for rid in region_ids}

    def format_answer(selected_edges):
        shaded = [[None for _ in range(m)] for _ in range(n)]
        for e in selected_edges:
            a, b = edge_list[e]
            ra, ca = rc(a)
            rb, cb = rc(b)
            shaded[ra][ca] = 'S'
            shaded[rb][cb] = 'S'
        return str(shaded)

    # State:
    # status[e]: -1 unknown, 0 forbidden, 1 selected
    status = [-1] * E
    region_shaded = [0] * R
    cell_selected = [False] * (n * m)

    # Dynamic edge availability count by region contribution
    # unknown_cover[r] = edges still unknown that contribute to region r
    unknown_cover = [set() for _ in range(R)]
    for rid in region_ids:
        k = region_index[rid]
        unknown_cover[k] = set(region_cover_edges[rid])

    selected_edges = set()

    # Reversible trail
    trail = []

    def push_change(kind, *args):
        trail.append((kind, args))

    def snapshot():
        return len(trail)

    def rollback(snap):
        while len(trail) > snap:
            kind, args = trail.pop()
            if kind == 'status':
                e, old = args
                status[e] = old
            elif kind == 'region_shaded':
                k, old = args
                region_shaded[k] = old
            elif kind == 'cell_selected':
                i, old = args
                cell_selected[i] = old
            elif kind == 'unknown_add':
                k, e = args
                unknown_cover[k].add(e)
            elif kind == 'unknown_remove':
                k, e = args
                unknown_cover[k].remove(e)
            elif kind == 'selected_add':
                e = args[0]
                selected_edges.add(e)
            elif kind == 'selected_remove':
                e = args[0]
                selected_edges.remove(e)

    q = deque()

    def forbid_edge(e):
        st = status[e]
        if st == 0:
            return True
        if st == 1:
            return False
        push_change('status', e, st)
        status[e] = 0
        a, b = edge_list[e]
        for ridx in (cell_region_idx[a], cell_region_idx[b]):
            if edge_region_count[e][ridx]:
                if e in unknown_cover[ridx]:
                    push_change('unknown_add', ridx, e)
                    unknown_cover[ridx].remove(e)
        q.append(('check_edge_forbid', e))
        return True

    def select_edge(e):
        st = status[e]
        if st == 1:
            return True
        if st == 0:
            return False
        a, b = edge_list[e]

        # Cells cannot be reused
        if cell_selected[a] or cell_selected[b]:
            return False

        # Cannot touch another selected domino orthogonally or share cells
        for f in edge_conflicts[e]:
            if status[f] == 1:
                return False

        # Region counts
        ra = cell_region_idx[a]
        rb = cell_region_idx[b]
        add_a = edge_region_count[e][ra]
        add_b = edge_region_count[e][rb] if rb != ra else 0

        if region_shaded[ra] + add_a > 2:
            return False
        if rb != ra and region_shaded[rb] + add_b > 2:
            return False

        push_change('status', e, st)
        status[e] = 1

        if e in selected_edges:
            pass
        else:
            push_change('selected_remove', e)
            selected_edges.add(e)

        push_change('cell_selected', a, cell_selected[a])
        cell_selected[a] = True
        push_change('cell_selected', b, cell_selected[b])
        cell_selected[b] = True

        old = region_shaded[ra]
        push_change('region_shaded', ra, old)
        region_shaded[ra] = old + add_a
        if rb != ra:
            old = region_shaded[rb]
            push_change('region_shaded', rb, old)
            region_shaded[rb] = old + add_b

        for ridx in (ra, rb):
            if edge_region_count[e][ridx]:
                if e in unknown_cover[ridx]:
                    push_change('unknown_add', ridx, e)
                    unknown_cover[ridx].remove(e)

        # Selected edge forces conflicts and same-cell incident edges forbidden
        q.append(('after_select', e))
        return True

    def region_possible_sum(ridx):
        # Maximum additional cells that can still be supplied to region ridx.
        # Because each unknown edge contributes 1 or 2 cells.
        return sum(edge_region_count[e][ridx] for e in unknown_cover[ridx] if status[e] == -1)

    def region_candidate_patterns(rid):
        # Enumerate feasible local patterns of 1 or 2 dominoes that could finish this region
        # from current state. Used for strong human-like deductions.
        ridx = region_index[rid]
        need = 2 - region_shaded[ridx]
        if need < 0:
            return None
        if need == 0:
            return [tuple()]

        cands = [e for e in region_cover_edges[rid] if status[e] != 0]
        patterns = set()

        # One-edge pattern
        for e in cands:
            if edge_region_count[e][ridx] != need:
                continue
            if status[e] == 1:
                patterns.add((e,))
                continue
            a, b = edge_list[e]
            if cell_selected[a] or cell_selected[b]:
                continue
            bad = False
            for f in edge_conflicts[e]:
                if status[f] == 1:
                    bad = True
                    break
            if not bad:
                patterns.add((e,))

        # Two-edge pattern
        if need == 2:
            L = len(cands)
            for i in range(L):
                e1 = cands[i]
                c1 = edge_region_count[e1][ridx]
                if c1 <= 0 or c1 > 2:
                    continue
                for j in range(i + 1, L):
                    e2 = cands[j]
                    c2 = edge_region_count[e2][ridx]
                    if c1 + c2 != 2:
                        continue
                    if e2 in edge_conflicts[e1]:
                        continue
                    # Respect already-selected edges
                    if status[e1] == 1 and status[e2] == 0:
                        continue
                    if status[e2] == 1 and status[e1] == 0:
                        continue
                    if status[e1] == 0 or status[e2] == 0:
                        continue
                    ok = True
                    cells_used = set()
                    for e in (e1, e2):
                        a, b = edge_list[e]
                        if a in cells_used or b in cells_used:
                            ok = False
                            break
                        cells_used.add(a)
                        cells_used.add(b)
                        for x in (a, b):
                            if cell_selected[x] and status[e] != 1:
                                ok = False
                                break
                        if not ok:
                            break
                        for f in edge_conflicts[e]:
                            if status[f] == 1 and f not in (e1, e2):
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        patterns.add(tuple(sorted((e1, e2))))

        return sorted(patterns)

    def propagate():
        # Seed full checks
        for rid in region_ids:
            q.append(('check_region', rid))

        while q:
            typ, val = q.popleft()

            if typ == 'after_select':
                e = val
                a, b = edge_list[e]

                # Forbid all conflicting edges
                for f in edge_conflicts[e]:
                    if not forbid_edge(f):
                        return False

                # A selected cell cannot appear in any other domino
                for x in (a, b):
                    for f in incident_edges[x]:
                        if f != e:
                            if not forbid_edge(f):
                                return False

                # Recheck impacted regions
                impacted = {cell_region_idx[a], cell_region_idx[b]}
                for x in (a, b):
                    for y in neigh[x]:
                        impacted.add(cell_region_idx[y])
                for ridx in impacted:
                    q.append(('check_region', region_ids[ridx]))

            elif typ == 'check_edge_forbid':
                e = val
                a, b = edge_list[e]
                impacted = {cell_region_idx[a], cell_region_idx[b]}
                for ridx in impacted:
                    q.append(('check_region', region_ids[ridx]))

            elif typ == 'check_region':
                rid = val
                ridx = region_index[rid]
                need = 2 - region_shaded[ridx]
                if need < 0:
                    return False
                if need == 0:
                    # Any unknown edge touching this region must not contribute further.
                    for e in list(unknown_cover[ridx]):
                        if status[e] == -1 and edge_region_count[e][ridx] > 0:
                            if not forbid_edge(e):
                                return False
                    continue

                max_possible = region_possible_sum(ridx)
                if max_possible < need:
                    return False

                patterns = region_candidate_patterns(rid)
                if not patterns:
                    return False

                # If all patterns share some edge -> must select it.
                inter = set(patterns[0])
                union = set(patterns[0])
                for p in patterns[1:]:
                    sp = set(p)
                    inter &= sp
                    union |= sp

                for e in sorted(inter):
                    if status[e] == -1:
                        if not select_edge(e):
                            return False

                # Any candidate edge not in any pattern is impossible.
                for e in region_cover_edges[rid]:
                    if status[e] == -1 and edge_region_count[e][ridx] > 0 and e not in union:
                        if not forbid_edge(e):
                            return False

                # If exactly one pattern remains, force it.
                if len(patterns) == 1:
                    for e in patterns[0]:
                        if status[e] == -1:
                            if not select_edge(e):
                                return False

        return True

    def solved():
        return all(region_shaded[k] == 2 for k in range(R))

    def choose_branch():
        # Most constrained region: fewest patterns > 1
        best = None
        best_patterns = None
        for rid in region_ids:
            ridx = region_index[rid]
            if region_shaded[ridx] == 2:
                continue
            pats = region_candidate_patterns(rid)
            if not pats:
                return ('dead', rid, pats)
            if len(pats) > 1:
                score = (len(pats), len(set().union(*[set(p) for p in pats])) if pats else 0)
                if best is None or score < best:
                    best = score
                    best_patterns = (rid, pats)
        if best_patterns is None:
            return None
        rid, pats = best_patterns

        # Branch on a most frequent edge within patterns
        freq = defaultdict(int)
        for p in pats:
            for e in p:
                freq[e] += 1
        total = len(pats)
        branch_edge = None
        branch_score = None
        for e, f in freq.items():
            # prefer balanced split and higher frequency
            score = (abs(total - 2 * f), -f)
            if branch_score is None or score < branch_score:
                branch_score = score
                branch_edge = e
        return ('edge', branch_edge, pats)

    def dfs():
        if not propagate():
            return None
        if solved():
            return format_answer(selected_edges)

        choice = choose_branch()
        if choice is None:
            return format_answer(selected_edges)
        if choice[0] == 'dead':
            return None

        _, e, _ = choice

        # Try selecting first; puzzle structure often rewards positive commitments.
        snap = snapshot()
        if select_edge(e):
            ans = dfs()
            if ans is not None:
                return ans
        rollback(snap)

        snap = snapshot()
        if forbid_edge(e):
            ans = dfs()
            if ans is not None:
                return ans
        rollback(snap)

        return None

    ans = dfs()
    return ans if ans is not None else "No Solution"


