from collections import defaultdict, deque

# Tetromino canonical shape library.
# Types ignore rotation/reflection for region-adjacency rule, but placements enumerate all orientations.
BASE_SHAPES = {
    'I': {(0, 0), (1, 0), (2, 0), (3, 0)},
    'L': {(0, 0), (1, 0), (2, 0), (2, 1)},
    'T': {(0, 1), (1, 0), (1, 1), (1, 2)},
    'S': {(0, 1), (0, 2), (1, 0), (1, 1)},  # covers S/Z by reflections in normalization generation
}

def normalize(cells):
    cells = list(cells)
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

def transforms(cells):
    out = set()
    cells = list(cells)
    for rf in (1, -1):
        for cf in (1, -1):
            for swap in (0, 1):
                t = []
                for r, c in cells:
                    a, b = (c, r) if swap else (r, c)
                    t.append((a * rf, b * cf))
                out.add(normalize(t))
    return [set(x) for x in out]

ALL_ORIENTS = {k: transforms(v) for k, v in BASE_SHAPES.items()}

def format_answer(assign_grid):
    rows = []
    for row in assign_grid:
        rows.append(str(row))
    return "[" + ",\n ".join(rows) + "]"

def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0]) if R else 0

    # Region cells
    regions = defaultdict(list)
    for r in range(R):
        for c in range(C):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Region adjacency graph
    region_neighbors = {rid: set() for rid in region_ids}
    for r in range(R):
        for c in range(C):
            a = grid[r][c]
            if r + 1 < R:
                b = grid[r + 1][c]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)
            if c + 1 < C:
                b = grid[r][c + 1]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)

    # Cell adjacency
    nbrs = {}
    for r in range(R):
        for c in range(C):
            v = []
            if r > 0: v.append((r - 1, c))
            if r + 1 < R: v.append((r + 1, c))
            if c > 0: v.append((r, c - 1))
            if c + 1 < C: v.append((r, c + 1))
            nbrs[(r, c)] = v

    # Precompute all tetromino placements in each region.
    # A placement is a dict with:
    #   cells: frozenset of 4 cells
    #   type: 'L'/'I'/'T'/'S'
    region_placements = {}
    region_type_masks = {}
    cell_to_placements = {}
    for rid, cells in regions.items():
        cellset = set(cells)
        placements = []
        seen = set()
        for tname, orients in ALL_ORIENTS.items():
            for orient in orients:
                max_r = max(r for r, c in orient)
                max_c = max(c for r, c in orient)
                # Anchor every orientation on every possible cell of the region
                for ar, ac in cells:
                    # anchor normalized shape origin at (ar, ac)
                    placed = {(ar + r, ac + c) for r, c in orient}
                    if all(0 <= rr < R and 0 <= cc < C and (rr, cc) in cellset for rr, cc in placed):
                        key = (tname, tuple(sorted(placed)))
                        if key not in seen:
                            seen.add(key)
                            placements.append({'cells': frozenset(placed), 'type': tname})
        if not placements:
            return "No Solution"
        region_placements[rid] = placements
        mask = set(p['type'] for p in placements)
        region_type_masks[rid] = mask
        for cell in cells:
            cell_to_placements[(rid, cell)] = [i for i, p in enumerate(placements) if cell in p['cells']]

    # Global 2x2 windows and which cells belong to them.
    windows = []
    cell_windows = defaultdict(list)
    for r in range(R - 1):
        for c in range(C - 1):
            w = ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))
            idx = len(windows)
            windows.append(w)
            for cell in w:
                cell_windows[cell].append(idx)

    # Human-like deductive state:
    # domain[rid] = set of placement indices still possible
    domain = {rid: set(range(len(region_placements[rid]))) for rid in region_ids}
    fixed_type = {rid: None for rid in region_ids}

    # Fast global per-cell possible shading support count by regions not yet fixed
    def propagate(domain, fixed_type):
        changed = True
        while changed:
            changed = False

            # 1) Region domain nonempty and type filtering from neighboring fixed types.
            for rid in region_ids:
                if not domain[rid]:
                    return False
                banned = {fixed_type[n] for n in region_neighbors[rid] if fixed_type[n] is not None}
                if banned:
                    newd = {pi for pi in domain[rid] if region_placements[rid][pi]['type'] not in banned}
                    if not newd:
                        return False
                    if len(newd) != len(domain[rid]):
                        domain[rid] = newd
                        changed = True

            # 2) If a region's remaining placements all share one type, fix that type.
            for rid in region_ids:
                types = {region_placements[rid][pi]['type'] for pi in domain[rid]}
                if not types:
                    return False
                if len(types) == 1:
                    t = next(iter(types))
                    if fixed_type[rid] is None:
                        fixed_type[rid] = t
                        changed = True
                    elif fixed_type[rid] != t:
                        return False

            # 3) Adjacent regions cannot have same type:
            # If a region is fixed, neighbors cannot keep only that same type; handled above.
            # Additional singleton-type elimination:
            for rid in region_ids:
                if fixed_type[rid] is None:
                    continue
                t = fixed_type[rid]
                for nid in region_neighbors[rid]:
                    if fixed_type[nid] == t:
                        return False

            # 4) No 2x2 fully shaded:
            # For each window, every combination of one placement per covering region cannot fill all 4 cells.
            # Strong local support pruning: if all remaining support for some cell in a window forces all 4 cells shaded, prune.
            # Implemented as exact small-window consistency using participating regions only.
            for wi, w in enumerate(windows):
                regs = sorted({grid[r][c] for r, c in w})
                local_choices = []
                impossible = False
                for rid in regs:
                    pis = []
                    for pi in domain[rid]:
                        cov = tuple(1 if cell in region_placements[rid][pi]['cells'] else 0 for cell in w)
                        pis.append((pi, cov))
                    if not pis:
                        impossible = True
                        break
                    local_choices.append((rid, pis))
                if impossible:
                    return False

                # Determine if there exists at least one tuple not fully filling the window.
                # Also support prune individual placements that can only participate in full windows.
                supports = {rid: set() for rid in regs}

                # Efficient recursive join over very few regions (<=4)
                def rec(i, shaded_mask, chosen):
                    if i == len(local_choices):
                        if shaded_mask != 0b1111:
                            for rr, pp in chosen:
                                supports[rr].add(pp)
                            return True
                        return False
                    rid, pis = local_choices[i]
                    any_ok = False
                    for pi, cov in pis:
                        mask = shaded_mask
                        for k, v in enumerate(cov):
                            if v:
                                mask |= (1 << k)
                        if rec(i + 1, mask, chosen + [(rid, pi)]):
                            any_ok = True
                    return any_ok

                exists_nonfull = rec(0, 0, [])
                if not exists_nonfull:
                    return False

                for rid in regs:
                    nd = {pi for pi in domain[rid] if pi in supports[rid]}
                    if not nd:
                        return False
                    if len(nd) != len(domain[rid]):
                        domain[rid] = nd
                        changed = True

            # 5) Global connectivity feasibility:
            # Every region contributes exactly one placement. Already confirmed shaded cells are intersection of domain placements.
            # Possible shaded cells are union of domain placements.
            must_shade = set()
            can_shade = set()
            for rid in region_ids:
                plist = [region_placements[rid][pi]['cells'] for pi in domain[rid]]
                inter = set(plist[0])
                uni = set()
                for s in plist:
                    inter &= s
                    uni |= s
                must_shade |= inter
                can_shade |= uni

            if can_shade:
                # Necessary condition: all must_shade cells must lie in one connected component of can_shade.
                comp_rep = None
                seen = set()
                for cell in can_shade:
                    if cell in seen:
                        continue
                    q = deque([cell])
                    seen.add(cell)
                    comp = {cell}
                    while q:
                        u = q.popleft()
                        for v in nbrs[u]:
                            if v in can_shade and v not in seen:
                                seen.add(v)
                                comp.add(v)
                                q.append(v)
                    if must_shade & comp:
                        if comp_rep is None:
                            comp_rep = comp
                        else:
                            # must_shade appears in more than one can-shade component => impossible
                            if (must_shade & comp) and (must_shade & comp_rep):
                                return False
                    # If a component contains no must_shade cells, it might still be used later; keep.
                if must_shade:
                    # every region must have at least one placement touching the master can-shade component containing must_shade
                    master = None
                    seen = set()
                    for cell in can_shade:
                        if cell in seen:
                            continue
                        q = deque([cell])
                        seen.add(cell)
                        comp = {cell}
                        while q:
                            u = q.popleft()
                            for v in nbrs[u]:
                                if v in can_shade and v not in seen:
                                    seen.add(v)
                                    comp.add(v)
                                    q.append(v)
                        if must_shade & comp:
                            master = comp
                            break
                    if master is None:
                        return False
                    for rid in region_ids:
                        nd = {pi for pi in domain[rid] if region_placements[rid][pi]['cells'] <= master or region_placements[rid][pi]['cells'] & master}
                        # We only need some overlap path potential; disconnected internal cells don't matter here.
                        if not nd:
                            return False
                        if len(nd) != len(domain[rid]):
                            domain[rid] = nd
                            changed = True

            # 6) Cell-based support inside each region.
            # If a cell cannot be shaded by any remaining placement and all other cells exceed capacity? Keep lightweight:
            # For each region, every remaining placement must leave enough non-forced ambiguity to avoid future disconnect.
            # Skip expensive exact cardinality checks; exact size already fixed at 4 by placements.

        return True

    def choose_region(domain, fixed_type):
        best = None
        best_key = None
        for rid in region_ids:
            d = domain[rid]
            if len(d) == 1:
                continue
            types = {region_placements[rid][pi]['type'] for pi in d}
            # Human-like: prioritize constrained region with few placements, then few types, then high adjacency.
            key = (len(d), len(types), -len(region_neighbors[rid]))
            if best_key is None or key < best_key:
                best_key = key
                best = rid
        return best

    def final_check_and_build(domain):
        chosen = {}
        for rid in region_ids:
            if len(domain[rid]) != 1:
                return None
            pi = next(iter(domain[rid]))
            chosen[rid] = region_placements[rid][pi]

        shaded = set()
        answer = [[None for _ in range(C)] for _ in range(R)]
        for rid, p in chosen.items():
            t = p['type']
            for cell in p['cells']:
                if cell in shaded:
                    return None
                shaded.add(cell)
                r, c = cell
                answer[r][c] = t

        # Rule 3
        for rid in region_ids:
            for nid in region_neighbors[rid]:
                if rid < nid and chosen[rid]['type'] == chosen[nid]['type']:
                    return None

        # Rule 4: all shaded cells connected
        if shaded:
            start = next(iter(shaded))
            q = deque([start])
            seen = {start}
            while q:
                u = q.popleft()
                for v in nbrs[u]:
                    if v in shaded and v not in seen:
                        seen.add(v)
                        q.append(v)
            if len(seen) != len(shaded):
                return None

        # Rule 5: no 2x2 shaded
        for w in windows:
            if all(cell in shaded for cell in w):
                return None

        return answer

    def search(domain, fixed_type):
        if not propagate(domain, fixed_type):
            return None

        complete = all(len(domain[rid]) == 1 for rid in region_ids)
        if complete:
            return final_check_and_build(domain)

        rid = choose_region(domain, fixed_type)
        if rid is None:
            return None

        # Value ordering:
        # prefer placements that connect to many neighbor regions and avoid dense 2x2 patterns
        def placement_score(pi):
            p = region_placements[rid][pi]
            cells = p['cells']
            conn = 0
            for cell in cells:
                for v in nbrs[cell]:
                    if grid[v[0]][v[1]] != rid:
                        conn += 1
            bad2 = 0
            for cell in cells:
                for wi in cell_windows[cell]:
                    if sum(1 for x in windows[wi] if x in cells) >= 3:
                        bad2 += 1
            return (-conn, bad2, p['type'])

        for pi in sorted(domain[rid], key=placement_score):
            ndomain = {k: set(v) for k, v in domain.items()}
            nfixed = dict(fixed_type)
            ndomain[rid] = {pi}
            nfixed[rid] = region_placements[rid][pi]['type']
            ans = search(ndomain, nfixed)
            if ans is not None:
                return ans

        return None

    ans = search(domain, fixed_type)
    if ans is None:
        return "No Solution"
    return format_answer(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None, None, 3], [3, None, 2, 2, None, None, None, None, None, 1], [None, None, 2, 3, 2, 0, None, None, 3, 2], [None, None, 1, None, None, 1, None, None, 2, 3], [1, None, None, 3, 3, 3, None, 3, 2, None], [None, 3, None, 2, None, None, None, 2, 2, None], [None, 1, None, 2, None, None, None, 1, 1, 2], [3, None, 2, None, None, None, None, 2, None, None], [None, None, 2, 3, None, None, 2, 1, None, None], [3, None, 2, 3, None, 1, 2, None, 3, None]]}

from collections import deque, defaultdict

UNKNOWN = -1
OFF = 0
ON = 1


class Contradiction(Exception):
    pass


def solve(observation):
    data = observation["data"]
    n = len(data)
    solver = SlitherlinkSolver(data)
    ok = solver.run()
    if not ok:
        return "No Solution"
    path = solver.extract_loop()
    if path is None:
        return "No Solution"
    return str(path)


class SlitherlinkSolver:
    def __init__(self, clues):
        self.clues = clues
        self.n = len(clues)
        self.H = (self.n + 1) * self.n
        self.V = self.n * (self.n + 1)
        self.E = self.H + self.V
        self.edge_state = [UNKNOWN] * self.E
        self.edge_cells = [[] for _ in range(self.E)]
        self.edge_verts = [None] * self.E
        self.vert_edges = [[] for _ in range((self.n + 1) * (self.n + 1))]
        self.cell_edges = [[] for _ in range(self.n * self.n)]
        self.assign_stack = []
        self.build_topology()

    def h_id(self, r, c):
        return r * self.n + c

    def v_id(self, r, c):
        return self.H + r * (self.n + 1) + c

    def vid(self, r, c):
        return r * (self.n + 1) + c

    def cid(self, r, c):
        return r * self.n + c

    def build_topology(self):
        n = self.n

        for r in range(n + 1):
            for c in range(n):
                e = self.h_id(r, c)
                v1 = self.vid(r, c)
                v2 = self.vid(r, c + 1)
                self.edge_verts[e] = (v1, v2)
                self.vert_edges[v1].append(e)
                self.vert_edges[v2].append(e)
                if r > 0:
                    self.edge_cells[e].append(self.cid(r - 1, c))
                if r < n:
                    self.edge_cells[e].append(self.cid(r, c))

        for r in range(n):
            for c in range(n + 1):
                e = self.v_id(r, c)
                v1 = self.vid(r, c)
                v2 = self.vid(r + 1, c)
                self.edge_verts[e] = (v1, v2)
                self.vert_edges[v1].append(e)
                self.vert_edges[v2].append(e)
                if c > 0:
                    self.edge_cells[e].append(self.cid(r, c - 1))
                if c < n:
                    self.edge_cells[e].append(self.cid(r, c))

        for r in range(n):
            for c in range(n):
                cid = self.cid(r, c)
                self.cell_edges[cid] = [
                    self.h_id(r, c),
                    self.v_id(r, c + 1),
                    self.h_id(r + 1, c),
                    self.v_id(r, c),
                ]

    def run(self):
        try:
            self.initial_rules()
            self.propagate_full()
            if self.is_solved():
                return self.final_check()
            return self.search()
        except Contradiction:
            return False

    def initial_rules(self):
        n = self.n

        for r in range(n):
            for c in range(n):
                clue = self.clues[r][c]
                if clue == 0:
                    for e in self.cell_edges[self.cid(r, c)]:
                        self.set_edge(e, OFF)
                elif clue == 3:
                    if r > 0 and c > 0 and self.clues[r - 1][c - 1] == 3:
                        self.set_edge(self.h_id(r, c - 1), ON)
                        self.set_edge(self.v_id(r - 1, c), ON)
                    if r > 0 and c < n - 1 and self.clues[r - 1][c + 1] == 3:
                        self.set_edge(self.h_id(r, c), ON)
                        self.set_edge(self.v_id(r - 1, c + 1), ON)

        for r in range(n):
            for c in range(n - 1):
                a = self.clues[r][c]
                b = self.clues[r][c + 1]
                if a == 3 and b == 0:
                    self.set_edge(self.h_id(r, c), ON)
                    self.set_edge(self.h_id(r + 1, c), ON)
                    self.set_edge(self.v_id(r, c), ON)
                    self.set_edge(self.v_id(r, c + 1), ON)
                    self.set_edge(self.h_id(r, c + 1), OFF)
                    self.set_edge(self.h_id(r + 1, c + 1), OFF)
                    self.set_edge(self.v_id(r, c + 2), OFF)
                if a == 0 and b == 3:
                    self.set_edge(self.h_id(r, c + 1), ON)
                    self.set_edge(self.h_id(r + 1, c + 1), ON)
                    self.set_edge(self.v_id(r, c + 2), ON)
                    self.set_edge(self.v_id(r, c + 1), ON)
                    self.set_edge(self.h_id(r, c), OFF)
                    self.set_edge(self.h_id(r + 1, c), OFF)
                    self.set_edge(self.v_id(r, c), OFF)

        for r in range(n - 1):
            for c in range(n):
                a = self.clues[r][c]
                b = self.clues[r + 1][c]
                if a == 3 and b == 0:
                    self.set_edge(self.v_id(r, c), ON)
                    self.set_edge(self.v_id(r, c + 1), ON)
                    self.set_edge(self.h_id(r, c), ON)
                    self.set_edge(self.h_id(r + 1, c), ON)
                    self.set_edge(self.v_id(r + 1, c), OFF)
                    self.set_edge(self.v_id(r + 1, c + 1), OFF)
                    self.set_edge(self.h_id(r + 2, c), OFF)
                if a == 0 and b == 3:
                    self.set_edge(self.v_id(r + 1, c), ON)
                    self.set_edge(self.v_id(r + 1, c + 1), ON)
                    self.set_edge(self.h_id(r + 1, c), ON)
                    self.set_edge(self.h_id(r + 2, c), ON)
                    self.set_edge(self.v_id(r, c), OFF)
                    self.set_edge(self.v_id(r, c + 1), OFF)
                    self.set_edge(self.h_id(r, c), OFF)

    def set_edge(self, e, val):
        cur = self.edge_state[e]
        if cur == val:
            return False
        if cur != UNKNOWN and cur != val:
            raise Contradiction
        self.edge_state[e] = val
        self.assign_stack.append(e)
        return True

    def propagate_full(self):
        changed = True
        while changed:
            start = len(self.assign_stack)
            self.propagate_cells()
            self.propagate_vertices()
            self.propagate_patterns()
            self.prevent_small_loops()
            changed = len(self.assign_stack) > start

    def propagate_cells(self):
        for r in range(self.n):
            for c in range(self.n):
                clue = self.clues[r][c]
                if clue is None:
                    continue
                edges = self.cell_edges[self.cid(r, c)]
                on = 0
                off = 0
                unk = []
                for e in edges:
                    s = self.edge_state[e]
                    if s == ON:
                        on += 1
                    elif s == OFF:
                        off += 1
                    else:
                        unk.append(e)
                if on > clue or on + len(unk) < clue:
                    raise Contradiction
                if not unk:
                    continue
                if on == clue:
                    for e in unk:
                        self.set_edge(e, OFF)
                elif on + len(unk) == clue:
                    for e in unk:
                        self.set_edge(e, ON)

    def propagate_vertices(self):
        for v, edges in enumerate(self.vert_edges):
            on = 0
            off = 0
            unk = []
            for e in edges:
                s = self.edge_state[e]
                if s == ON:
                    on += 1
                elif s == OFF:
                    off += 1
                else:
                    unk.append(e)
            if on > 2:
                raise Contradiction
            if not unk:
                if on not in (0, 2):
                    raise Contradiction
                continue
            if on == 2:
                for e in unk:
                    self.set_edge(e, OFF)
            elif on == 1 and len(unk) == 1:
                self.set_edge(unk[0], ON)
            elif on == 0 and len(unk) == 1:
                self.set_edge(unk[0], OFF)

    def propagate_patterns(self):
        n = self.n

        for r in range(n):
            for c in range(n):
                clue = self.clues[r][c]
                if clue is None:
                    continue
                edges = self.cell_edges[self.cid(r, c)]
                top, right, bottom, left = edges
                states = [self.edge_state[e] for e in edges]

                if clue == 3:
                    if states[0] == OFF:
                        self.set_edge(right, ON)
                        self.set_edge(bottom, ON)
                        self.set_edge(left, ON)
                    if states[1] == OFF:
                        self.set_edge(top, ON)
                        self.set_edge(bottom, ON)
                        self.set_edge(left, ON)
                    if states[2] == OFF:
                        self.set_edge(top, ON)
                        self.set_edge(right, ON)
                        self.set_edge(left, ON)
                    if states[3] == OFF:
                        self.set_edge(top, ON)
                        self.set_edge(right, ON)
                        self.set_edge(bottom, ON)

                if clue == 1:
                    if states[0] == ON:
                        self.set_edge(right, OFF)
                        self.set_edge(bottom, OFF)
                        self.set_edge(left, OFF)
                    if states[1] == ON:
                        self.set_edge(top, OFF)
                        self.set_edge(bottom, OFF)
                        self.set_edge(left, OFF)
                    if states[2] == ON:
                        self.set_edge(top, OFF)
                        self.set_edge(right, OFF)
                        self.set_edge(left, OFF)
                    if states[3] == ON:
                        self.set_edge(top, OFF)
                        self.set_edge(right, OFF)
                        self.set_edge(bottom, OFF)

        for r in range(n - 1):
            for c in range(n - 1):
                a = self.clues[r][c]
                b = self.clues[r][c + 1]
                d = self.clues[r + 1][c]
                e = self.clues[r + 1][c + 1]
                vals = [a, b, d, e]
                if vals.count(3) == 3 and vals.count(0) == 1:
                    if a == 0:
                        self.set_edge(self.h_id(r, c), OFF)
                        self.set_edge(self.v_id(r, c), OFF)
                    if b == 0:
                        self.set_edge(self.h_id(r, c + 1), OFF)
                        self.set_edge(self.v_id(r, c + 2), OFF)
                    if d == 0:
                        self.set_edge(self.h_id(r + 2, c), OFF)
                        self.set_edge(self.v_id(r + 1, c), OFF)
                    if e == 0:
                        self.set_edge(self.h_id(r + 2, c + 1), OFF)
                        self.set_edge(self.v_id(r + 1, c + 2), OFF)

    def build_on_graph(self):
        g = defaultdict(list)
        on_edges = []
        for e, s in enumerate(self.edge_state):
            if s == ON:
                v1, v2 = self.edge_verts[e]
                g[v1].append((v2, e))
                g[v2].append((v1, e))
                on_edges.append(e)
        return g, on_edges

    def prevent_small_loops(self):
        g, on_edges = self.build_on_graph()
        if not on_edges:
            return
        seen = set()
        for e in on_edges:
            if e in seen:
                continue
            v1, v2 = self.edge_verts[e]
            comp_vs = set()
            comp_es = set()
            dq = deque([v1])
            comp_vs.add(v1)
            while dq:
                v = dq.popleft()
                for w, ee in g[v]:
                    comp_es.add(ee)
                    seen.add(ee)
                    if w not in comp_vs:
                        comp_vs.add(w)
                        dq.append(w)
            deg2_all = True
            for v in comp_vs:
                if len(g[v]) != 2:
                    deg2_all = False
                    break
            if deg2_all:
                if len(comp_es) != len(on_edges):
                    raise Contradiction
                for i, s in enumerate(self.edge_state):
                    if s == UNKNOWN:
                        raise Contradiction

    def is_solved(self):
        return all(s != UNKNOWN for s in self.edge_state)

    def final_check(self):
        for r in range(self.n):
            for c in range(self.n):
                clue = self.clues[r][c]
                if clue is None:
                    continue
                cnt = sum(self.edge_state[e] == ON for e in self.cell_edges[self.cid(r, c)])
                if cnt != clue:
                    return False

        for edges in self.vert_edges:
            cnt = sum(self.edge_state[e] == ON for e in edges)
            if cnt not in (0, 2):
                return False

        g, on_edges = self.build_on_graph()
        if not on_edges:
            return False
        start = self.edge_verts[on_edges[0]][0]
        seen_v = set([start])
        dq = deque([start])
        while dq:
            v = dq.popleft()
            for w, _ in g[v]:
                if w not in seen_v:
                    seen_v.add(w)
                    dq.append(w)
        used_vertices = set()
        for e in on_edges:
            used_vertices.update(self.edge_verts[e])
        return seen_v == used_vertices

    def snapshot(self):
        return len(self.assign_stack)

    def rollback(self, snap):
        while len(self.assign_stack) > snap:
            e = self.assign_stack.pop()
            self.edge_state[e] = UNKNOWN

    def search(self):
        if self.is_solved():
            return self.final_check()

        e = self.choose_branch_edge()
        if e is None:
            return False

        for val in (ON, OFF):
            snap = self.snapshot()
            try:
                self.set_edge(e, val)
                self.propagate_full()
                if self.is_solved():
                    if self.final_check():
                        return True
                else:
                    if self.search():
                        return True
            except Contradiction:
                pass
            self.rollback(snap)
        return False

    def choose_branch_edge(self):
        best_e = None
        best_score = -1

        for e, s in enumerate(self.edge_state):
            if s != UNKNOWN:
                continue
            score = 0
            for cid in self.edge_cells[e]:
                r, c = divmod(cid, self.n)
                clue = self.clues[r][c]
                if clue is not None:
                    score += 3
                    edges = self.cell_edges[cid]
                    on = sum(self.edge_state[x] == ON for x in edges)
                    unk = sum(self.edge_state[x] == UNKNOWN for x in edges)
                    if clue == on or clue == on + unk:
                        score += 2
            v1, v2 = self.edge_verts[e]
            for v in (v1, v2):
                edges = self.vert_edges[v]
                on = sum(self.edge_state[x] == ON for x in edges)
                unk = sum(self.edge_state[x] == UNKNOWN for x in edges)
                if on == 1:
                    score += 3
                if unk <= 2:
                    score += 1
            if score > best_score:
                best_score = score
                best_e = e
        return best_e

    def extract_loop(self):
        if not self.final_check():
            return None
        g, on_edges = self.build_on_graph()
        if not on_edges:
            return None
        start_edge = on_edges[0]
        a, b = self.edge_verts[start_edge]
        path = [self.vcoord(a), self.vcoord(b)]
        prev = a
        cur = b
        while True:
            nbrs = g[cur]
            nxt = None
            for w, _ in nbrs:
                if w != prev:
                    nxt = w
                    break
            if nxt is None:
                return None
            if nxt == path_vertex(path[0], self.n):
                path.append(self.vcoord(nxt))
                break
            path.append(self.vcoord(nxt))
            prev, cur = cur, nxt
            if len(path) > len(on_edges) + 2:
                return None
        return path

    def vcoord(self, vid):
        return (vid // (self.n + 1), vid % (self.n + 1))


def path_vertex(coord, n):
    return coord[0] * (n + 1) + coord[1]


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], ['W', None, None, 'W', None, None, 'B', 'W'], ['W', None, None, 'W', None, None, 'W', 'W'], [None, None, None, 'W', 'B', 'W', None, None], [None, None, 'W', None, 'W', None, 'W', None], [None, None, 'W', None, None, None, None, None], [None, None, 'W', None, 'W', None, 'W', None], ['B', 'W', None, None, None, 'W', None, None]]}

from collections import defaultdict, deque

# Masyu solver on an N x N lattice of clue points.
# A loop is built on edges between orthogonally adjacent dots (clue positions).
# Each clue position, if used by the loop, has degree 2; non-clue positions may be used or unused.
# Since every clue must be passed through, clue vertices must end with degree exactly 2.


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0:
        return "No Solution"

    # ---------- graph primitives ----------
    def vid(r, c):
        return r * n + c

    def rc(v):
        return divmod(v, n)

    vertices = list(range(n * n))
    clues = {}
    for r in range(n):
        for c in range(n):
            if data[r][c] in ("W", "B"):
                clues[vid(r, c)] = data[r][c]

    edges = []
    edge_index = {}
    incident = [[] for _ in vertices]
    edge_dir_at_v = {}

    for r in range(n):
        for c in range(n):
            v = vid(r, c)
            if c + 1 < n:
                u = vid(r, c + 1)
                eid = len(edges)
                edges.append((v, u))
                edge_index[(min(v, u), max(v, u))] = eid
                incident[v].append(eid)
                incident[u].append(eid)
                edge_dir_at_v[(eid, v)] = "H"
                edge_dir_at_v[(eid, u)] = "H"
            if r + 1 < n:
                u = vid(r + 1, c)
                eid = len(edges)
                edges.append((v, u))
                edge_index[(min(v, u), max(v, u))] = eid
                incident[v].append(eid)
                incident[u].append(eid)
                edge_dir_at_v[(eid, v)] = "V"
                edge_dir_at_v[(eid, u)] = "V"

    m = len(edges)

    def edge_between(a, b):
        return edge_index.get((min(a, b), max(a, b)))

    def neighbor(v, eid):
        a, b = edges[eid]
        return b if a == v else a

    # ---------- state ----------
    # -1 unknown, 0 forbidden, 1 selected
    state = [-1] * m
    deg_sel = [0] * (n * n)
    deg_unk = [len(incident[v]) for v in vertices]

    # rollback trail
    trail = []

    def push_assign(eid, val):
        cur = state[eid]
        if cur == val:
            return True
        if cur != -1:
            return False
        trail.append(("edge", eid, cur))
        state[eid] = val
        a, b = edges[eid]
        if val == 1:
            trail.append(("deg_sel", a, deg_sel[a]))
            deg_sel[a] += 1
            trail.append(("deg_sel", b, deg_sel[b]))
            deg_sel[b] += 1
        trail.append(("deg_unk", a, deg_unk[a]))
        deg_unk[a] -= 1
        trail.append(("deg_unk", b, deg_unk[b]))
        deg_unk[b] -= 1
        return True

    def checkpoint():
        return len(trail)

    def rollback(cp):
        while len(trail) > cp:
            typ, idx, old = trail.pop()
            if typ == "edge":
                state[idx] = old
            elif typ == "deg_sel":
                deg_sel[idx] = old
            elif typ == "deg_unk":
                deg_unk[idx] = old

    # ---------- DSU for selected-edge path components ----------
    # rebuilt on demand, enough for this puzzle size and simplifies rollback complexity.
    def build_selected_components():
        parent = list(range(n * n))
        rank = [0] * (n * n)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        sel_edges = [eid for eid, v in enumerate(state) if v == 1]
        for eid in sel_edges:
            a, b = edges[eid]
            union(a, b)

        comps = defaultdict(list)
        for v in vertices:
            if deg_sel[v] > 0:
                comps[find(v)].append(v)
        return find, comps, sel_edges

    # ---------- utility deductions ----------
    def enforce_vertex_degree(v, required=None):
        # required None means:
        #   clue -> 2
        #   non-clue -> 0 or 2, with local consistency only
        inc = incident[v]
        s = deg_sel[v]
        u = deg_unk[v]

        req = 2 if (required is None and v in clues) else required

        if req is not None:
            if s > req:
                return False
            if s + u < req:
                return False
            if s == req:
                for eid in inc:
                    if state[eid] == -1 and not push_assign(eid, 0):
                        return False
            elif s + u == req:
                for eid in inc:
                    if state[eid] == -1 and not push_assign(eid, 1):
                        return False
            return True

        # non-clue parity/branch constraints: degree can only be 0 or 2
        if s > 2:
            return False
        if s == 1 and u == 0:
            return False
        if s == 0 and u == 1:
            return False
        if s == 2:
            for eid in inc:
                if state[eid] == -1 and not push_assign(eid, 0):
                    return False
        elif s == 1 and u == 1:
            for eid in inc:
                if state[eid] == -1 and not push_assign(eid, 1):
                    return False
        elif s == 0 and u == 2:
            # If exactly two unknown remain, they must either both be 1 or both 0.
            # Defer explicit pair relation; local forcing not possible here.
            pass
        return True

    def clue_possible_patterns(v):
        r, c = rc(v)
        clue = clues[v]
        inc = incident[v]

        dirs = {"U": None, "D": None, "L": None, "R": None}
        for eid in inc:
            w = neighbor(v, eid)
            rr, cc = rc(w)
            if rr == r - 1:
                dirs["U"] = eid
            elif rr == r + 1:
                dirs["D"] = eid
            elif cc == c - 1:
                dirs["L"] = eid
            elif cc == c + 1:
                dirs["R"] = eid

        patterns = []

        def edge_status(eid):
            if eid is None:
                return 0
            return state[eid]

        def compatible(assigns):
            for eid, val in assigns.items():
                cur = state[eid]
                if cur != -1 and cur != val:
                    return False
            return True

        if clue == "W":
            # straight through: UD or LR
            for pair in (("U", "D"), ("L", "R")):
                e1, e2 = dirs[pair[0]], dirs[pair[1]]
                if e1 is None or e2 is None:
                    continue
                assigns = {e1: 1, e2: 1}
                for k in dirs:
                    eid = dirs[k]
                    if eid is not None and eid not in assigns:
                        assigns[eid] = 0
                # must turn at previous or next step:
                # if vertical at v, then at at least one of the adjacent vertices along U/D path, the loop turns.
                # if horizontal at v, similarly along L/R.
                if not compatible(assigns):
                    continue

                ok = True
                if pair == ("U", "D"):
                    vu = neighbor(v, e1)
                    vd = neighbor(v, e2)
                    if not white_side_can_turn(vu, e1) and not white_side_can_turn(vd, e2):
                        ok = False
                else:
                    vl = neighbor(v, e1)
                    vr = neighbor(v, e2)
                    if not white_side_can_turn(vl, e1) and not white_side_can_turn(vr, e2):
                        ok = False
                if ok:
                    patterns.append(assigns)

        else:  # B
            # turn: one vertical + one horizontal
            options = [("U", "L"), ("U", "R"), ("D", "L"), ("D", "R")]
            for a1, a2 in options:
                e1, e2 = dirs[a1], dirs[a2]
                if e1 is None or e2 is None:
                    continue
                assigns = {e1: 1, e2: 1}
                for k in dirs:
                    eid = dirs[k]
                    if eid is not None and eid not in assigns:
                        assigns[eid] = 0
                if not compatible(assigns):
                    continue

                # black: adjacent vertices on both used edges must go straight.
                v1 = neighbor(v, e1)
                v2 = neighbor(v, e2)
                if black_side_can_be_straight(v1, e1) and black_side_can_be_straight(v2, e2):
                    patterns.append(assigns)

        return patterns

    def white_side_can_turn(adj_v, incoming_eid):
        # At adjacent vertex, loop must be able to include incoming_eid and one perpendicular edge.
        if adj_v is None:
            return False
        inc = incident[adj_v]
        incoming_dir = edge_dir_at_v[(incoming_eid, adj_v)]
        candidates = []
        for eid in inc:
            if eid == incoming_eid:
                continue
            if edge_dir_at_v[(eid, adj_v)] != incoming_dir:
                candidates.append(eid)
        if not candidates:
            return False
        if state[incoming_eid] == 0:
            return False
        # there must exist at least one perpendicular edge not forbidden
        for eid in candidates:
            if state[eid] != 0:
                return True
        return False

    def black_side_can_be_straight(adj_v, incoming_eid):
        # At adjacent vertex, loop must be able to include incoming_eid and the opposite collinear edge.
        if adj_v is None:
            return False
        rr, cc = rc(adj_v)
        a, b = edges[incoming_eid]
        other = a if b == adj_v else b
        r0, c0 = rc(other)
        dr, dc = rr - r0, cc - c0
        r2, c2 = rr + dr, cc + dc
        if not (0 <= r2 < n and 0 <= c2 < n):
            return False
        out_v = vid(r2, c2)
        eid2 = edge_between(adj_v, out_v)
        if eid2 is None:
            return False
        if state[incoming_eid] == 0 or state[eid2] == 0:
            return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            # Degree constraints.
            cp0 = len(trail)
            for v in vertices:
                if v in clues:
                    if not enforce_vertex_degree(v, 2):
                        return False
                else:
                    if not enforce_vertex_degree(v, None):
                        return False
            if len(trail) != cp0:
                changed = True

            # Clue pattern filtering and common-edge forcing.
            cp1 = len(trail)
            for v in clues:
                pats = clue_possible_patterns(v)
                if not pats:
                    return False
                # any incident clue edge not present in any pattern => 0
                inc = incident[v]
                for eid in inc:
                    vals = {p.get(eid, state[eid]) for p in pats if eid in p}
                    if not vals:
                        continue
                    if vals == {1}:
                        if state[eid] == -1 and not push_assign(eid, 1):
                            return False
                    elif vals == {0}:
                        if state[eid] == -1 and not push_assign(eid, 0):
                            return False
            if len(trail) != cp1:
                changed = True

            # Prevent premature small cycles while there remain clues/components outside.
            cp2 = len(trail)
            if not prevent_subcycles():
                return False
            if len(trail) != cp2:
                changed = True

            # Connectivity sanity: every clue vertex must still be able to connect to selected structure.
            if not clue_reachability_ok():
                return False

        return True

    def prevent_subcycles():
        find, comps, sel_edges = build_selected_components()
        if not sel_edges:
            return True

        active_vertices = {v for v in vertices if deg_sel[v] > 0}
        clue_vertices = set(clues.keys())

        # If a component is already a cycle, it must be the final loop containing all clues and no undecided selected deficits.
        for root, vs in comps.items():
            cyc = all(deg_sel[v] == 2 for v in vs)
            if cyc:
                if any(v not in vs for v in clue_vertices):
                    return False
                if active_vertices != set(vs):
                    return False

        # For any unknown edge joining two degree-1 endpoints in same component, selecting it would close a subcycle unless final.
        for eid, st in enumerate(state):
            if st != -1:
                continue
            a, b = edges[eid]
            if deg_sel[a] == 1 and deg_sel[b] == 1 and find(a) == find(b):
                # Only allow if this would complete the final loop through all clues and all active endpoints are exactly these.
                comp_vs = set(comps[find(a)])
                if not (clue_vertices.issubset(comp_vs) and active_vertices.issubset(comp_vs)):
                    if not push_assign(eid, 0):
                        return False
        return True

    def clue_reachability_ok():
        # Build graph of edges not forbidden.
        g = [[] for _ in vertices]
        for eid, st in enumerate(state):
            if st != 0:
                a, b = edges[eid]
                g[a].append(b)
                g[b].append(a)

        # All clue vertices must lie in one connected component of the not-forbidden graph.
        clue_list = list(clues.keys())
        if not clue_list:
            return True
        start = clue_list[0]
        q = deque([start])
        seen = {start}
        while q:
            v = q.popleft()
            for w in g[v]:
                if w not in seen:
                    seen.add(w)
                    q.append(w)
        return all(v in seen for v in clue_list)

    # ---------- branching ----------
    def choose_branch():
        # Human-like: pick the most constrained clue first.
        best = None
        best_key = None

        for v in clues:
            pats = clue_possible_patterns(v)
            if len(pats) <= 1:
                continue
            unknown_inc = sum(1 for eid in incident[v] if state[eid] == -1)
            key = (len(pats), unknown_inc)
            if best is None or key < best_key:
                best = ("clue", v, pats)
                best_key = key

        if best is not None:
            return best

        # Fallback: choose unknown edge near constrained vertices.
        for eid, st in enumerate(state):
            if st == -1:
                a, b = edges[eid]
                score = (a in clues) + (b in clues), deg_unk[a] + deg_unk[b]
                return ("edge", eid, score)
        return None

    def apply_pattern(v, pat):
        for eid, val in pat.items():
            if not push_assign(eid, val):
                return False
        return True

    def all_assigned_consistent_final():
        # Degrees exact.
        for v in vertices:
            if v in clues:
                if deg_sel[v] != 2:
                    return False
            else:
                if deg_sel[v] not in (0, 2):
                    return False

        # Non-empty single cycle.
        sel = [eid for eid, st in enumerate(state) if st == 1]
        if not sel:
            return False

        used = {v for eid in sel for v in edges[eid]}
        # connectivity on selected graph
        start = next(iter(used))
        q = deque([start])
        seen = {start}
        adj = [[] for _ in vertices]
        for eid in sel:
            a, b = edges[eid]
            adj[a].append(b)
            adj[b].append(a)
        while q:
            v = q.popleft()
            for w in adj[v]:
                if w not in seen:
                    seen.add(w)
                    q.append(w)
        if seen != used:
            return False
        if any(deg_sel[v] != 2 for v in used):
            return False
        if not set(clues.keys()).issubset(used):
            return False
        return True

    def extract_loop():
        sel_adj = defaultdict(list)
        for eid, st in enumerate(state):
            if st == 1:
                a, b = edges[eid]
                sel_adj[a].append(b)
                sel_adj[b].append(a)

        if not sel_adj:
            return None
        start = min(sel_adj)
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = sel_adj[cur]
            if len(nbrs) != 2:
                return None
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(sel_adj) + 2:
                return None
        return [rc(v) for v in path]

    def search():
        if not propagate():
            return None

        if all(st != -1 for st in state):
            if all_assigned_consistent_final():
                return extract_loop()
            return None

        branch = choose_branch()
        if branch is None:
            if all_assigned_consistent_final():
                return extract_loop()
            return None

        if branch[0] == "clue":
            _, v, pats = branch
            # Try more restrictive patterns first: those assigning more currently unknown edges.
            pats = sorted(
                pats,
                key=lambda p: -sum(1 for eid in p if state[eid] == -1)
            )
            for pat in pats:
                cp = checkpoint()
                if apply_pattern(v, pat):
                    ans = search()
                    if ans is not None:
                        return ans
                rollback(cp)
        else:
            _, eid, _ = branch
            # Edge branching with 0 first often prunes more.
            for val in (0, 1):
                cp = checkpoint()
                if push_assign(eid, val):
                    ans = search()
                    if ans is not None:
                        return ans
                rollback(cp)
        return None

    ans = search()
    return str(ans) if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 8, None, None, None, None, None, None], [None, 3, None, None, None, None, 1, 7, None], [9, None, None, 4, 7, None, 5, None, 3], [None, 4, None, None, 1, None, None, None, None], [None, 1, None, 6, None, 8, None, 9, None], [None, None, None, None, 9, None, None, 2, None], [1, None, 6, None, 2, 7, None, None, 8], [None, 7, 3, None, None, None, None, 5, None], [None, None, None, None, None, None, 9, None, None]], 'unit': '3x3'}

from copy import deepcopy

def solve(observation):
    data = observation['data']
    unit = observation['unit']
    rbox, cbox = map(int, unit.split('x'))
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"
    if rbox * cbox != n:
        return "No Solution"

    digits = list(range(1, n + 1))
    all_mask = (1 << n) - 1

    def val_to_bit(v):
        return 1 << (v - 1)

    def bit_count(x):
        return x.bit_count()

    def bits_iter(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def bit_to_val(bit):
        return bit.bit_length()

    rows = [0] * n
    cols = [0] * n
    boxes = [0] * n
    board = [[0] * n for _ in range(n)]

    def box_index(r, c):
        return (r // rbox) * (n // cbox) + (c // cbox)

    empties = []
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                board[r][c] = 0
                empties.append((r, c))
            else:
                if not (1 <= v <= n):
                    return "No Solution"
                b = val_to_bit(v)
                bi = box_index(r, c)
                if (rows[r] & b) or (cols[c] & b) or (boxes[bi] & b):
                    return "No Solution"
                board[r][c] = v
                rows[r] |= b
                cols[c] |= b
                boxes[bi] |= b

    units = []
    cell_to_units = [[[] for _ in range(n)] for _ in range(n)]

    for r in range(n):
        cells = [(r, c) for c in range(n)]
        idx = len(units)
        units.append(cells)
        for cell in cells:
            cell_to_units[cell[0]][cell[1]].append(idx)

    for c in range(n):
        cells = [(r, c) for r in range(n)]
        idx = len(units)
        units.append(cells)
        for cell in cells:
            cell_to_units[cell[0]][cell[1]].append(idx)

    for br in range(0, n, rbox):
        for bc in range(0, n, cbox):
            cells = [(r, c) for r in range(br, br + rbox) for c in range(bc, bc + cbox)]
            idx = len(units)
            units.append(cells)
            for cell in cells:
                cell_to_units[cell[0]][cell[1]].append(idx)

    peers = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set()
            for ui in cell_to_units[r][c]:
                s.update(units[ui])
            s.discard((r, c))
            peers[r][c] = tuple(s)

    cand = [[0] * n for _ in range(n)]
    for r, c in empties:
        mask = all_mask & ~(rows[r] | cols[c] | boxes[box_index(r, c)])
        if mask == 0:
            return "No Solution"
        cand[r][c] = mask

    def assign(state_board, state_rows, state_cols, state_boxes, state_cand, r, c, v):
        if state_board[r][c] == v:
            return True
        if state_board[r][c] != 0:
            return False
        bit = val_to_bit(v)
        bi = box_index(r, c)
        if (state_rows[r] & bit) or (state_cols[c] & bit) or (state_boxes[bi] & bit):
            return False
        if not (state_cand[r][c] & bit):
            return False

        state_board[r][c] = v
        state_rows[r] |= bit
        state_cols[c] |= bit
        state_boxes[bi] |= bit
        state_cand[r][c] = 0

        for rr, cc in peers[r][c]:
            if state_board[rr][cc] == 0:
                if state_cand[rr][cc] & bit:
                    state_cand[rr][cc] &= ~bit
                    if state_cand[rr][cc] == 0:
                        return False
        return True

    def hidden_singles(state_board, state_rows, state_cols, state_boxes, state_cand):
        progress = False
        for cells in units:
            missing = all_mask
            places = {}
            for r, c in cells:
                v = state_board[r][c]
                if v:
                    missing &= ~val_to_bit(v)
            if missing == 0:
                continue
            for bit in bits_iter(missing):
                places[bit] = None
            for r, c in cells:
                if state_board[r][c] == 0:
                    m = state_cand[r][c] & missing
                    for bit in bits_iter(m):
                        prev = places[bit]
                        if prev is None:
                            places[bit] = (r, c)
                        elif prev != ():
                            places[bit] = ()
            for bit, pos in places.items():
                if pos is not None and pos != ():
                    if not assign(state_board, state_rows, state_cols, state_boxes, state_cand, pos[0], pos[1], bit_to_val(bit)):
                        return None
                    progress = True
        return progress

    def naked_subsets(state_board, state_cand):
        progress = False
        for cells in units:
            buckets = {}
            unsolved = []
            for r, c in cells:
                if state_board[r][c] == 0:
                    m = state_cand[r][c]
                    unsolved.append((r, c, m))
                    bc = bit_count(m)
                    if 2 <= bc <= 4:
                        buckets.setdefault(m, []).append((r, c))
            for m, poslist in buckets.items():
                k = bit_count(m)
                if len(poslist) == k:
                    posset = set(poslist)
                    for r, c, cm in unsolved:
                        if (r, c) not in posset and (cm & m):
                            state_cand[r][c] &= ~m
                            if state_cand[r][c] == 0:
                                return None
                            progress = True
        return progress

    def hidden_subsets(state_board, state_cand):
        progress = False
        for cells in units:
            digit_cells = {}
            for d in digits:
                digit_cells[d] = []
            for r, c in cells:
                if state_board[r][c] == 0:
                    m = state_cand[r][c]
                    for bit in bits_iter(m):
                        digit_cells[bit_to_val(bit)].append((r, c))

            items = [(d, tuple(sorted(v))) for d, v in digit_cells.items() if 2 <= len(v) <= 4]
            groups = {}
            for d, pos in items:
                groups.setdefault(pos, []).append(d)

            for pos, ds in groups.items():
                k = len(pos)
                if 2 <= k <= 4 and len(ds) == k:
                    allowed = 0
                    for d in ds:
                        allowed |= val_to_bit(d)
                    for r, c in pos:
                        newm = state_cand[r][c] & allowed
                        if newm == 0:
                            return None
                        if newm != state_cand[r][c]:
                            state_cand[r][c] = newm
                            progress = True
        return progress

    def pointing_and_claiming(state_board, state_cand):
        progress = False
        for br in range(0, n, rbox):
            for bc in range(0, n, cbox):
                cells = [(r, c) for r in range(br, br + rbox) for c in range(bc, bc + cbox) if state_board[r][c] == 0]
                if not cells:
                    continue
                for d in digits:
                    bit = val_to_bit(d)
                    poss = [(r, c) for r, c in cells if state_cand[r][c] & bit]
                    if len(poss) >= 2:
                        rows_set = {r for r, _ in poss}
                        cols_set = {c for _, c in poss}
                        if len(rows_set) == 1:
                            rr = next(iter(rows_set))
                            for cc in range(n):
                                if not (bc <= cc < bc + cbox) and state_board[rr][cc] == 0 and (state_cand[rr][cc] & bit):
                                    state_cand[rr][cc] &= ~bit
                                    if state_cand[rr][cc] == 0:
                                        return None
                                    progress = True
                        if len(cols_set) == 1:
                            cc = next(iter(cols_set))
                            for rr in range(n):
                                if not (br <= rr < br + rbox) and state_board[rr][cc] == 0 and (state_cand[rr][cc] & bit):
                                    state_cand[rr][cc] &= ~bit
                                    if state_cand[rr][cc] == 0:
                                        return None
                                    progress = True

        for r in range(n):
            for d in digits:
                bit = val_to_bit(d)
                poss = [(r, c) for c in range(n) if state_board[r][c] == 0 and (state_cand[r][c] & bit)]
                if len(poss) >= 2:
                    boxset = {box_index(rr, cc) for rr, cc in poss}
                    if len(boxset) == 1:
                        bi = next(iter(boxset))
                        br = (bi // (n // cbox)) * rbox
                        bc = (bi % (n // cbox)) * cbox
                        for rr in range(br, br + rbox):
                            for cc in range(bc, bc + cbox):
                                if rr != r and state_board[rr][cc] == 0 and (state_cand[rr][cc] & bit):
                                    state_cand[rr][cc] &= ~bit
                                    if state_cand[rr][cc] == 0:
                                        return None
                                    progress = True

        for c in range(n):
            for d in digits:
                bit = val_to_bit(d)
                poss = [(r, c) for r in range(n) if state_board[r][c] == 0 and (state_cand[r][c] & bit)]
                if len(poss) >= 2:
                    boxset = {box_index(rr, cc) for rr, cc in poss}
                    if len(boxset) == 1:
                        bi = next(iter(boxset))
                        br = (bi // (n // cbox)) * rbox
                        bc = (bi % (n // cbox)) * cbox
                        for rr in range(br, br + rbox):
                            for cc in range(bc, bc + cbox):
                                if cc != c and state_board[rr][cc] == 0 and (state_cand[rr][cc] & bit):
                                    state_cand[rr][cc] &= ~bit
                                    if state_cand[rr][cc] == 0:
                                        return None
                                    progress = True
        return progress

    def fill_naked_singles(state_board, state_rows, state_cols, state_boxes, state_cand):
        progress = False
        made = True
        while made:
            made = False
            for r in range(n):
                for c in range(n):
                    if state_board[r][c] == 0:
                        m = state_cand[r][c]
                        if m == 0:
                            return None
                        if m & (m - 1) == 0:
                            if not assign(state_board, state_rows, state_cols, state_boxes, state_cand, r, c, bit_to_val(m)):
                                return None
                            made = True
                            progress = True
        return progress

    def propagate(state_board, state_rows, state_cols, state_boxes, state_cand):
        while True:
            changed = False

            res = fill_naked_singles(state_board, state_rows, state_cols, state_boxes, state_cand)
            if res is None:
                return False
            changed |= res

            res = hidden_singles(state_board, state_rows, state_cols, state_boxes, state_cand)
            if res is None:
                return False
            changed |= res

            res = pointing_and_claiming(state_board, state_cand)
            if res is None:
                return False
            changed |= res

            res = naked_subsets(state_board, state_cand)
            if res is None:
                return False
            changed |= res

            res = hidden_subsets(state_board, state_cand)
            if res is None:
                return False
            changed |= res

            if not changed:
                break

        for r in range(n):
            for c in range(n):
                if state_board[r][c] == 0 and state_cand[r][c] == 0:
                    return False
        return True

    def solved(state_board):
        for r in range(n):
            for c in range(n):
                if state_board[r][c] == 0:
                    return False
        return True

    def select_branch_cell(state_board, state_cand):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if state_board[r][c] == 0:
                    m = state_cand[r][c]
                    cnt = bit_count(m)
                    peer_pressure = sum(1 for rr, cc in peers[r][c] if state_board[rr][cc] == 0)
                    score = (cnt, -peer_pressure)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
                        if cnt == 2 and peer_pressure > 10:
                            return best
        return best

    def search(state_board, state_rows, state_cols, state_boxes, state_cand):
        if not propagate(state_board, state_rows, state_cols, state_boxes, state_cand):
            return None
        if solved(state_board):
            return state_board

        r, c = select_branch_cell(state_board, state_cand)
        mask = state_cand[r][c]

        options = []
        for bit in bits_iter(mask):
            v = bit_to_val(bit)
            impact = 0
            for rr, cc in peers[r][c]:
                if state_board[rr][cc] == 0 and (state_cand[rr][cc] & bit):
                    impact += 1
            options.append((-impact, v))
        options.sort()

        for _, v in options:
            nb = [row[:] for row in state_board]
            nr = state_rows[:]
            nc = state_cols[:]
            nx = state_boxes[:]
            nd = [row[:] for row in state_cand]
            if assign(nb, nr, nc, nx, nd, r, c, v):
                ans = search(nb, nr, nc, nx, nd)
                if ans is not None:
                    return ans
        return None

    result = search(board, rows, cols, boxes, cand)
    if result is None:
        return "No Solution"
    return str(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 1, 1, 1, 2, 2, 3, 3], [0, 0, 4, 1, 5, 2, 2, 2], [0, 0, 4, 4, 5, 5, 5, 2], [0, 0, 4, 6, 6, 5, 7, 7], [0, 0, 5, 5, 5, 5, 5, 7], [8, 8, 9, 10, 5, 5, 11, 11], [8, 9, 9, 10, 5, 5, 5, 11], [9, 9, 9, 9, 5, 5, 12, 12]]}

from collections import defaultdict, deque
import ast

# Rules encoded:
# - Each region contains exactly 2 shaded cells.
# - Every shaded cell is part of a domino: shaded cells come in orthogonally adjacent pairs.
# - Different dominoes cannot touch orthogonally.
# - Dominoes may cross region borders.
#
# Modeling choice:
# A solution is a set of disjoint domino placements.
# A cell is shaded iff covered by exactly one chosen domino.
# Region constraint: total covered cells in each region = 2.
# Non-touching dominoes: if two dominoes are distinct, no cell of one may be orthogonally adjacent
# to any cell of the other unless that adjacency is the shared internal edge of the same domino.

def solve(observation):
    data = observation["data"]
    n = len(data)
    m = len(data[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]

    def inb(r, c):
        return 0 <= r < n and 0 <= c < m

    nbrs = {}
    for r, c in cells:
        arr = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if inb(rr, cc):
                arr.append((rr, cc))
        nbrs[(r, c)] = arr

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[data[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Enumerate all possible dominoes.
    dominoes = []
    dom_of_cell = defaultdict(list)
    cell_index = {cell: i for i, cell in enumerate(cells)}
    region_of = {(r, c): data[r][c] for r, c in cells}

    # Bitmask over cells for fast conflict checks.
    for r in range(n):
        for c in range(m):
            for dr, dc in ((1, 0), (0, 1)):
                rr, cc = r + dr, c + dc
                if not inb(rr, cc):
                    continue
                a = (r, c)
                b = (rr, cc)
                cover_mask = (1 << cell_index[a]) | (1 << cell_index[b])

                # Touch mask = all cells orthogonally adjacent to either endpoint, including endpoints.
                # If another selected domino has any covered cell in this mask, conflict,
                # except overlap already prohibited and same-domino case irrelevant.
                touch_cells = {a, b}
                touch_cells.update(nbrs[a])
                touch_cells.update(nbrs[b])
                touch_mask = 0
                for x in touch_cells:
                    touch_mask |= 1 << cell_index[x]

                idx = len(dominoes)
                dominoes.append({
                    "cells": (a, b),
                    "cover_mask": cover_mask,
                    "touch_mask": touch_mask,
                    "regions": (region_of[a], region_of[b]),
                })
                dom_of_cell[a].append(idx)
                dom_of_cell[b].append(idx)

    D = len(dominoes)

    # Conflicts between dominoes.
    conflicts = [0] * D
    for i in range(D):
        mi_cover = dominoes[i]["cover_mask"]
        mi_touch = dominoes[i]["touch_mask"]
        mask = 0
        for j in range(D):
            if i == j:
                continue
            mj_cover = dominoes[j]["cover_mask"]
            # Conflict if overlap or orthogonal touching between distinct dominoes.
            if (mi_cover & mj_cover) or (mi_touch & mj_cover):
                mask |= 1 << j
        conflicts[i] = mask

    # Region-to-domino incidence.
    region_dominoes = defaultdict(list)
    for d, dom in enumerate(dominoes):
        r1, r2 = dom["regions"]
        region_dominoes[r1].append(d)
        if r2 != r1:
            region_dominoes[r2].append(d)

    # Per domino, contribution to each region is 0/1/2.
    dom_region_contrib = []
    for dom in dominoes:
        r1, r2 = dom["regions"]
        contrib = {}
        contrib[r1] = contrib.get(r1, 0) + 1
        contrib[r2] = contrib.get(r2, 0) + 1
        dom_region_contrib.append(contrib)

    all_dom_mask = (1 << D) - 1

    # Availability masks by cell/region.
    cell_dom_mask = {}
    for cell in cells:
        mask = 0
        for d in dom_of_cell[cell]:
            mask |= 1 << d
        cell_dom_mask[cell] = mask

    region_dom_mask = {}
    for rid in region_ids:
        mask = 0
        for d in region_dominoes[rid]:
            mask |= 1 << d
        region_dom_mask[rid] = mask

    # Fast bit iteration.
    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    # Compute optimistic max additional shaded cells available to a region.
    # Since region target is only 2, enough to know whether 0/1/2 more is possible.
    def region_possible_additions(avail_mask, rid):
        if avail_mask == 0:
            return 0
        have1 = False
        have2 = False
        for d in iter_bits(avail_mask & region_dom_mask[rid]):
            c = dom_region_contrib[d].get(rid, 0)
            if c >= 1:
                have1 = True
            if c >= 2:
                have2 = True
                break
        if have2:
            return 2
        if not have1:
            return 0
        # Need to know if two distinct 1-contributors can co-exist.
        ones = [d for d in iter_bits(avail_mask & region_dom_mask[rid]) if dom_region_contrib[d].get(rid, 0) == 1]
        if len(ones) < 2:
            return 1
        first = ones[0]
        for d in ones[1:]:
            if not ((conflicts[first] >> d) & 1):
                return 2
        # Try broader check if first conflicts with all.
        for i in range(len(ones)):
            di = ones[i]
            for j in range(i + 1, len(ones)):
                dj = ones[j]
                if not ((conflicts[di] >> dj) & 1):
                    return 2
        return 1

    # Strong forced-cell logic:
    # A cell can only be shaded by choosing one of dominoes covering it.
    # If region still needs shade and all feasible completions require this cell shaded/unshaded,
    # branch-prefer/force by singleton available covering set and regional arithmetic.
    #
    # State:
    # chosen_mask: selected dominoes
    # forbidden_mask: dominoes impossible
    # region_count[rid]: shaded cells already contributed to region
    #
    # avail = all_dom_mask & ~forbidden_mask, but chosen must remain included.
    best_solution = None

    def propagate(chosen_mask, forbidden_mask, region_count):
        changed = True
        while changed:
            changed = False
            avail_mask = all_dom_mask & ~forbidden_mask

            # Any chosen domino forbids all conflicts.
            implied_forbidden = 0
            for d in iter_bits(chosen_mask):
                implied_forbidden |= conflicts[d]
            new_forbidden = forbidden_mask | implied_forbidden
            if new_forbidden != forbidden_mask:
                forbidden_mask = new_forbidden
                avail_mask = all_dom_mask & ~forbidden_mask
                if chosen_mask & forbidden_mask:
                    return None
                changed = True

            # Region bounds.
            for rid in region_ids:
                cnt = region_count[rid]
                if cnt > 2:
                    return None
                max_add = region_possible_additions(avail_mask & ~chosen_mask, rid)
                if cnt + max_add < 2:
                    return None
                if cnt == 2:
                    # Forbid any remaining domino touching this region.
                    mask = avail_mask & region_dom_mask[rid] & ~chosen_mask
                    if mask:
                        forbidden_mask |= mask
                        avail_mask = all_dom_mask & ~forbidden_mask
                        changed = True

            if chosen_mask & forbidden_mask:
                return None

            # Selected-domino exact region completion can force others.
            # If a region needs exactly 1 and only one available domino can provide it -> choose if contribution 1,
            # or reject if only 2-contribution overshoots.
            for rid in region_ids:
                need = 2 - region_count[rid]
                if need <= 0:
                    continue
                cand = []
                for d in iter_bits((avail_mask & region_dom_mask[rid])):
                    if (chosen_mask >> d) & 1:
                        continue
                    c = dom_region_contrib[d].get(rid, 0)
                    if c > 0:
                        cand.append((d, c))
                if not cand:
                    return None
                if need == 2:
                    # If a single 2-contributor exists and all 1-contributors mutually conflict/unusable with any partner,
                    # can sometimes force, but keep lightweight.
                    if len(cand) == 1:
                        d, c = cand[0]
                        if c != 2:
                            return None
                        chosen_mask |= 1 << d
                        for rr, add in dom_region_contrib[d].items():
                            region_count[rr] += add
                        changed = True
                        continue
                elif need == 1:
                    one_contrib = [d for d, c in cand if c == 1]
                    two_contrib = [d for d, c in cand if c == 2]
                    if not one_contrib and two_contrib:
                        return None
                    if len(one_contrib) == 1:
                        d = one_contrib[0]
                        # If this is the only way to supply the last cell to region, force it.
                        # Need check it won't immediately overshoot any other region.
                        ok = True
                        for rr, add in dom_region_contrib[d].items():
                            if region_count[rr] + add > 2:
                                ok = False
                                break
                        if not ok:
                            return None
                        chosen_mask |= 1 << d
                        for rr, add in dom_region_contrib[d].items():
                            region_count[rr] += add
                        changed = True
                        continue

            # Cell-level impossibility:
            # If a cell belongs to a region still needing all remaining cells and this cell has no available domino,
            # no direct forcing beyond region checks. But if any chosen shading would isolate a region target impossible,
            # covered by region_possible_additions.
            #
            # Additional exact-cover style check:
            # Any region with need=2 and exactly one available pair of cells achievable by one domino or compatible two dominoes.
            # We keep this implicit by branching heuristic to avoid expensive enumeration.

        return chosen_mask, forbidden_mask, region_count

    def select_branch_var(chosen_mask, forbidden_mask, region_count):
        avail_mask = all_dom_mask & ~forbidden_mask

        # Most constrained region first.
        best = None
        best_score = None

        for rid in region_ids:
            need = 2 - region_count[rid]
            if need <= 0:
                continue
            cands = []
            for d in iter_bits(avail_mask & region_dom_mask[rid]):
                if (chosen_mask >> d) & 1:
                    continue
                add = dom_region_contrib[d].get(rid, 0)
                if add > 0:
                    cands.append((d, add))
            if not cands:
                return ("dead", rid)

            # Count feasible ways roughly.
            single2 = [d for d, a in cands if a == 2]
            single1 = [d for d, a in cands if a == 1]
            ways = 0
            branch_items = []

            if need == 2:
                for d in single2:
                    ways += 1
                    branch_items.append((d,))
                L = single1
                for i in range(len(L)):
                    di = L[i]
                    for j in range(i + 1, len(L)):
                        dj = L[j]
                        if not ((conflicts[di] >> dj) & 1):
                            ways += 1
                            branch_items.append((di, dj))
            else:  # need == 1
                for d in single1:
                    ways += 1
                    branch_items.append((d,))

            if ways == 0:
                return ("dead", rid)

            score = (ways, len(cands))
            if best_score is None or score < best_score:
                best_score = score
                best = ("region", rid, branch_items)

        if best is not None:
            return best

        # Fallback: any undecided domino.
        undec = avail_mask & ~chosen_mask
        if undec:
            d = next(iter_bits(undec))
            return ("domino", d)
        return ("done",)

    def dfs(chosen_mask, forbidden_mask, region_count):
        nonlocal best_solution

        state = propagate(chosen_mask, forbidden_mask, region_count.copy())
        if state is None:
            return False
        chosen_mask, forbidden_mask, region_count = state

        # Check completion.
        if all(region_count[rid] == 2 for rid in region_ids):
            best_solution = chosen_mask
            return True

        branch = select_branch_var(chosen_mask, forbidden_mask, region_count)
        if branch[0] == "dead":
            return False
        if branch[0] == "done":
            best_solution = chosen_mask
            return True

        if branch[0] == "region":
            _, rid, options = branch
            # Human-like: try exact completion patterns for a constrained region.
            # Prefer single-domino completions first.
            options = sorted(options, key=lambda t: (len(t),))
            for opt in options:
                new_chosen = chosen_mask
                new_forbidden = forbidden_mask
                new_counts = region_count.copy()
                ok = True
                for d in opt:
                    if (new_forbidden >> d) & 1:
                        ok = False
                        break
                    if (new_chosen >> d) & 1:
                        continue
                    # Check immediate region overflow.
                    for rr, add in dom_region_contrib[d].items():
                        if new_counts[rr] + add > 2:
                            ok = False
                            break
                    if not ok:
                        break
                    new_chosen |= 1 << d
                    for rr, add in dom_region_contrib[d].items():
                        new_counts[rr] += add
                if ok and dfs(new_chosen, new_forbidden, new_counts):
                    return True
            # If no completion pattern worked, fail.
            return False

        if branch[0] == "domino":
            _, d = branch
            # Branch order: choose then forbid.
            new_counts = region_count.copy()
            ok = True
            for rr, add in dom_region_contrib[d].items():
                if new_counts[rr] + add > 2:
                    ok = False
                    break
            if ok:
                for rr, add in dom_region_contrib[d].items():
                    new_counts[rr] += add
                if dfs(chosen_mask | (1 << d), forbidden_mask, new_counts):
                    return True
            if dfs(chosen_mask, forbidden_mask | (1 << d), region_count.copy()):
                return True
            return False

        return False

    region_count0 = {rid: 0 for rid in region_ids}
    found = dfs(0, 0, region_count0)
    if not found or best_solution is None:
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for d in iter_bits(best_solution):
        for r, c in dominoes[d]["cells"]:
            ans[r][c] = "S"
    return str(ans)


