from collections import defaultdict

# States per cell:
#  1 = shaded
#  0 = unshaded
# -1 = undecided

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}

    nbrs = [[] for _ in range(n * m)]
    for r, c in cells:
        i = idx_of[(r, c)]
        if r > 0:
            nbrs[i].append(idx_of[(r - 1, c)])
        if r + 1 < n:
            nbrs[i].append(idx_of[(r + 1, c)])
        if c > 0:
            nbrs[i].append(idx_of[(r, c - 1)])
        if c + 1 < m:
            nbrs[i].append(idx_of[(r, c + 1)])

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append(idx_of[(r, c)])
    region_ids = sorted(regions)

    cell_region = [None] * (n * m)
    for rid in region_ids:
        for i in regions[rid]:
            cell_region[i] = rid

    # Candidate domino placements: each is an undirected edge between orthogonally adjacent cells.
    dominos = []
    domino_of_pair = {}
    incident_dominos = [[] for _ in range(n * m)]
    for i in range(n * m):
        for j in nbrs[i]:
            if i < j:
                d = len(dominos)
                dominos.append((i, j))
                domino_of_pair[(i, j)] = d
                incident_dominos[i].append(d)
                incident_dominos[j].append(d)

    # Domino conflict graph:
    # Two dominoes conflict if they share a cell, or if any shaded cell from one is orthogonally adjacent
    # to any shaded cell from the other (except the two cells inside the same domino).
    domino_conflicts = [set() for _ in range(len(dominos))]
    for a, (u1, v1) in enumerate(dominos):
        cells_a = (u1, v1)
        touch_a = set(cells_a)
        for x in cells_a:
            touch_a.update(nbrs[x])
        for b in range(a + 1, len(dominos)):
            u2, v2 = dominos[b]
            cells_b = (u2, v2)
            conflict = False
            # Share a cell
            if u1 == u2 or u1 == v2 or v1 == u2 or v1 == v2:
                conflict = True
            else:
                # Orthogonally adjacent shaded cells across distinct dominoes forbidden
                for x in cells_a:
                    if u2 in nbrs[x] or v2 in nbrs[x]:
                        conflict = True
                        break
            if conflict:
                domino_conflicts[a].add(b)
                domino_conflicts[b].add(a)

    # Region -> candidate dominos that contribute 0/1/2 cells in that region, but must be placeable globally.
    region_dominos = defaultdict(list)
    region_domino_contrib = defaultdict(dict)
    for rid in region_ids:
        regset = set(regions[rid])
        for d, (a, b) in enumerate(dominos):
            cnt = (1 if a in regset else 0) + (1 if b in regset else 0)
            if cnt:
                region_dominos[rid].append(d)
                region_domino_contrib[rid][d] = cnt

    # Region patterns: each region must receive exactly 2 shaded cells, from one inside-region domino
    # or from two crossing dominos each contributing one cell.
    region_patterns = {}
    for rid in region_ids:
        cand = region_dominos[rid]
        pats = []
        ln = len(cand)
        for x in range(ln):
            d1 = cand[x]
            c1 = region_domino_contrib[rid][d1]
            if c1 == 2:
                pats.append((d1,))
            for y in range(x + 1, ln):
                d2 = cand[y]
                c2 = region_domino_contrib[rid][d2]
                if c1 + c2 == 2:
                    # Must not conflict, or they'd produce adjacent/overlapping shaded cells.
                    if d2 not in domino_conflicts[d1]:
                        pats.append((d1, d2))
        # Remove duplicates if any
        pats = list(dict.fromkeys(tuple(sorted(p)) for p in pats))
        region_patterns[rid] = pats
        if not pats:
            return "No Solution"

    # State
    D = len(dominos)
    domino_state = [-1] * D   # 1 selected, 0 rejected, -1 undecided
    cell_state = [-1] * (n * m)

    # Region pattern status
    active_patterns = {rid: set(range(len(region_patterns[rid]))) for rid in region_ids}

    # Fast support maps
    pattern_contains = {}
    for rid in region_ids:
        pats = region_patterns[rid]
        contain = defaultdict(set)
        for pi, p in enumerate(pats):
            for d in p:
                contain[d].add(pi)
        pattern_contains[rid] = contain

    stack = []

    def assign_cell(i, val):
        cur = cell_state[i]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        stack.append(("cell", i, cur))
        cell_state[i] = val
        return True

    def assign_domino(d, val):
        cur = domino_state[d]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        stack.append(("domino", d, cur))
        domino_state[d] = val

        a, b = dominos[d]
        if val == 1:
            # Its cells are shaded
            if not assign_cell(a, 1):
                return False
            if not assign_cell(b, 1):
                return False
            # Conflicting dominos rejected
            for e in domino_conflicts[d]:
                if not assign_domino(e, 0):
                    return False
            # Any other domino using a shaded cell is already in conflict graph by shared cell;
            # adjacency restrictions also handled there.
        else:
            # If a cell can no longer belong to any selected/possible domino, it must be unshaded.
            pass
        return True

    def disable_pattern(rid, pi):
        if pi not in active_patterns[rid]:
            return True
        stack.append(("pattern", rid, pi))
        active_patterns[rid].remove(pi)
        return bool(active_patterns[rid])

    def savepoint():
        return len(stack)

    def rollback(sp):
        while len(stack) > sp:
            item = stack.pop()
            typ = item[0]
            if typ == "cell":
                _, i, old = item
                cell_state[i] = old
            elif typ == "domino":
                _, d, old = item
                domino_state[d] = old
            else:
                _, rid, pi = item
                active_patterns[rid].add(pi)

    def propagate():
        changed = True
        while changed:
            changed = False

            # Cell-based deductions:
            for i in range(n * m):
                if cell_state[i] == 1:
                    # Must belong to exactly one selected adjacent domino
                    poss = []
                    sel = 0
                    for d in incident_dominos[i]:
                        st = domino_state[d]
                        if st == 1:
                            sel += 1
                        elif st == -1:
                            poss.append(d)
                    if sel > 1:
                        return False
                    if sel == 0:
                        if not poss:
                            return False
                        if len(poss) == 1:
                            if not assign_domino(poss[0], 1):
                                return False
                            changed = True
                elif cell_state[i] == -1:
                    # If no incident domino can still be selected, cell must be unshaded.
                    ok = False
                    for d in incident_dominos[i]:
                        if domino_state[d] != 0:
                            ok = True
                            break
                    if not ok:
                        if not assign_cell(i, 0):
                            return False
                        changed = True

            # Selected / rejected domino imply cell facts
            for d, (a, b) in enumerate(dominos):
                st = domino_state[d]
                if st == 1:
                    if cell_state[a] == 0 or cell_state[b] == 0:
                        return False
                elif st == -1:
                    # If either endpoint unshaded, domino impossible.
                    if cell_state[a] == 0 or cell_state[b] == 0:
                        if not assign_domino(d, 0):
                            return False
                        changed = True
                    # If one endpoint shaded and all other incident dominos for that endpoint are rejected,
                    # this domino is forced.
                    elif cell_state[a] == 1:
                        others = [e for e in incident_dominos[a] if e != d and domino_state[e] != 0]
                        if not others:
                            if not assign_domino(d, 1):
                                return False
                            changed = True
                    elif cell_state[b] == 1:
                        others = [e for e in incident_dominos[b] if e != d and domino_state[e] != 0]
                        if not others:
                            if not assign_domino(d, 1):
                                return False
                            changed = True

            # Region pattern filtering
            for rid in region_ids:
                pats = region_patterns[rid]
                to_disable = []
                for pi in list(active_patterns[rid]):
                    p = pats[pi]
                    # Pattern invalid if any domino in it rejected, or any pair became conflicting (shouldn't happen),
                    # or if a selected domino contributing to region is omitted.
                    bad = False
                    for d in p:
                        if domino_state[d] == 0:
                            bad = True
                            break
                    if bad:
                        to_disable.append(pi)
                        continue

                    # Count selected contribution to region; pattern must include every selected contributing domino.
                    for d in region_dominos[rid]:
                        if domino_state[d] == 1 and d not in p:
                            to_disable.append(pi)
                            bad = True
                            break
                    if bad:
                        continue

                    # Also if any region cell is fixed shaded, pattern must cover it.
                    regcells = regions[rid]
                    cover = set()
                    for d in p:
                        a, b = dominos[d]
                        if cell_region[a] == rid:
                            cover.add(a)
                        if cell_region[b] == rid:
                            cover.add(b)
                    for i in regcells:
                        if cell_state[i] == 1 and i not in cover:
                            to_disable.append(pi)
                            bad = True
                            break
                    if bad:
                        continue

                    # If a region cell is fixed unshaded and pattern covers it, pattern impossible.
                    for i in cover:
                        if cell_state[i] == 0:
                            to_disable.append(pi)
                            break

                if to_disable:
                    for pi in to_disable:
                        if not disable_pattern(rid, pi):
                            return False
                    changed = True

                # No pattern means contradiction
                if not active_patterns[rid]:
                    return False

                # Common/union deductions from remaining patterns
                active = [pats[pi] for pi in active_patterns[rid]]
                # Dominos present in all patterns are forced selected
                common = set(active[0])
                union = set(active[0])
                for p in active[1:]:
                    ps = set(p)
                    common &= ps
                    union |= ps
                for d in common:
                    if not assign_domino(d, 1):
                        return False
                    changed = True
                # Candidate region dominos not appearing in any remaining pattern are rejected
                for d in region_dominos[rid]:
                    if d not in union and domino_state[d] == -1:
                        if not assign_domino(d, 0):
                            return False
                        changed = True

                # Cell coverage deductions within region
                regcells = regions[rid]
                cell_cover_count = defaultdict(int)
                for p in active:
                    covered = set()
                    for d in p:
                        a, b = dominos[d]
                        if cell_region[a] == rid:
                            covered.add(a)
                        if cell_region[b] == rid:
                            covered.add(b)
                    for i in covered:
                        cell_cover_count[i] += 1
                total_active = len(active)
                for i in regcells:
                    cnt = cell_cover_count.get(i, 0)
                    if cnt == 0:
                        if not assign_cell(i, 0):
                            return False
                        changed = True
                    elif cnt == total_active:
                        if not assign_cell(i, 1):
                            return False
                        changed = True

            # Global consistency: every shaded cell must have exactly one selected incident domino eventually possible
            for i in range(n * m):
                if cell_state[i] == 1:
                    sel = 0
                    poss = 0
                    for d in incident_dominos[i]:
                        if domino_state[d] == 1:
                            sel += 1
                        elif domino_state[d] == -1:
                            poss += 1
                    if sel > 1:
                        return False
                    if sel + poss < 1:
                        return False

            # Each region needs exactly 2 shaded cells still feasible
            for rid in region_ids:
                regcells = regions[rid]
                shaded = sum(1 for i in regcells if cell_state[i] == 1)
                undec = sum(1 for i in regcells if cell_state[i] == -1)
                if shaded > 2 or shaded + undec < 2:
                    return False

        return True

    def is_solved():
        # All regions resolved by one active pattern and all cells decided consistently
        for rid in region_ids:
            if len(active_patterns[rid]) != 1:
                return False
        # Force final selections from sole patterns
        return True

    def choose_branch():
        # Most constrained region first
        best_rid = None
        best_count = None
        for rid in region_ids:
            k = len(active_patterns[rid])
            if k > 1 and (best_count is None or k < best_count):
                best_count = k
                best_rid = rid
        if best_rid is not None:
            # Branch on one pattern for that region
            return ("region", best_rid)

        # Fallback: undecided domino with high conflict degree
        best_d = None
        best_score = -1
        for d in range(D):
            if domino_state[d] == -1:
                score = len(domino_conflicts[d])
                if score > best_score:
                    best_score = score
                    best_d = d
        if best_d is not None:
            return ("domino", best_d)
        return None

    def commit_region_pattern(rid, pi):
        pats = region_patterns[rid]
        target = set(pats[pi])
        # Disable all other patterns for region
        for pj in list(active_patterns[rid]):
            if pj != pi:
                if not disable_pattern(rid, pj):
                    return False
        # Force dominos in target selected; other region-contributing dominos rejected
        for d in region_dominos[rid]:
            if d in target:
                if not assign_domino(d, 1):
                    return False
            else:
                if domino_state[d] == -1:
                    if not assign_domino(d, 0):
                        return False
        return True

    def dfs():
        if not propagate():
            return False
        if is_solved():
            # Ensure all implied final selections are committed
            for rid in region_ids:
                pi = next(iter(active_patterns[rid]))
                if not commit_region_pattern(rid, pi):
                    return False
            if not propagate():
                return False
            # Validate complete assignment
            for rid in region_ids:
                regcells = regions[rid]
                if sum(1 for i in regcells if cell_state[i] == 1) != 2:
                    return False
            for i in range(n * m):
                if cell_state[i] == 1:
                    if sum(1 for d in incident_dominos[i] if domino_state[d] == 1) != 1:
                        return False
            return True

        branch = choose_branch()
        if branch is None:
            return False

        if branch[0] == "region":
            rid = branch[1]
            # Try patterns in heuristic order: fewer external side effects first
            opts = []
            for pi in active_patterns[rid]:
                p = region_patterns[rid][pi]
                score = sum(len(domino_conflicts[d]) for d in p)
                opts.append((score, pi))
            opts.sort()
            for _, pi in opts:
                sp = savepoint()
                if commit_region_pattern(rid, pi) and dfs():
                    return True
                rollback(sp)
            return False
        else:
            d = branch[1]
            # Try selected before rejected
            for val in (1, 0):
                sp = savepoint()
                if assign_domino(d, val) and dfs():
                    return True
                rollback(sp)
            return False

    if not dfs():
        return "No Solution"

    # Build answer grid
    ans = [[None for _ in range(m)] for _ in range(n)]
    for r in range(n):
        for c in range(m):
            i = idx_of[(r, c)]
            if cell_state[i] == 1:
                ans[r][c] = 'S'
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 'W', None, None], [None, 'B', None, None, 'W', None], [None, 'W', None, None, None, None], [None, None, None, None, 'W', 'B'], ['W', 'B', 'W', None, None, 'W'], [None, None, None, None, None, None]]}

# Masyu solver:
# - vertices are grid dots
# - edges connect orthogonally adjacent dots
# - loop is a single simple cycle
# - clue circles are placed on vertices in this task's encoding
#   W: degree 2 and straight-through at the vertex; at least one adjacent step before/after is a turn
#   B: degree 2 and turn at the vertex; both neighboring visited clue vertices (one step away along loop) are straight
#
# The implementation emphasizes human-like deduction:
# 1) local clue pattern pruning
# 2) degree propagation (0/2 at each vertex)
# 3) component/path feasibility checks
# 4) no small closed loop before all used vertices are in one cycle
# 5) branch on most constrained undecided edge

from collections import deque, defaultdict

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0:
        return "No Solution"

    # Vertex indexing
    def vid(r, c):
        return r * n + c

    def rc(v):
        return divmod(v, n)

    # Build graph edges
    edges = []
    edge_index = {}
    incident = [[] for _ in range(n * n)]

    for r in range(n):
        for c in range(n):
            v = vid(r, c)
            if c + 1 < n:
                u = vid(r, c + 1)
                idx = len(edges)
                edges.append((v, u))
                edge_index[(min(v, u), max(v, u))] = idx
                incident[v].append(idx)
                incident[u].append(idx)
            if r + 1 < n:
                u = vid(r + 1, c)
                idx = len(edges)
                edges.append((v, u))
                edge_index[(min(v, u), max(v, u))] = idx
                incident[v].append(idx)
                incident[u].append(idx)

    E = len(edges)
    V = n * n

    # Directions for each incident edge at a vertex
    # 0=U,1=R,2=D,3=L
    edge_dir_at_v = {}
    for i, (a, b) in enumerate(edges):
        ra, ca = rc(a)
        rb, cb = rc(b)
        if rb == ra + 1:
            edge_dir_at_v[(i, a)] = 2
            edge_dir_at_v[(i, b)] = 0
        else:
            edge_dir_at_v[(i, a)] = 1
            edge_dir_at_v[(i, b)] = 3

    def opposite_dir(d):
        return (d + 2) % 4

    clues = {}
    clue_vertices = set()
    for r in range(n):
        for c in range(n):
            if data[r][c] in ('W', 'B'):
                v = vid(r, c)
                clues[v] = data[r][c]
                clue_vertices.add(v)

    # State: -1 unknown, 0 forbidden, 1 chosen
    state = [-1] * E
    deg_on = [0] * V
    deg_off = [0] * V

    # Helper to copy state compactly
    def snapshot():
        return (state[:], deg_on[:], deg_off[:])

    def restore(ss):
        s, d1, d0 = ss
        state[:] = s
        deg_on[:] = d1
        deg_off[:] = d0

    # DSU on currently chosen edges, rebuilt when needed
    def build_on_components():
        parent = list(range(V))
        size = [1] * V

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        used_vertices = set()
        chosen_edges = 0
        for i, (a, b) in enumerate(edges):
            if state[i] == 1:
                union(a, b)
                used_vertices.add(a)
                used_vertices.add(b)
                chosen_edges += 1
        comps = defaultdict(list)
        for v in used_vertices:
            comps[find(v)].append(v)
        return parent, comps, chosen_edges, used_vertices

    # Local geometric tests for clue constraints under partial assignment
    def chosen_dirs(v):
        ds = []
        for e in incident[v]:
            if state[e] == 1:
                ds.append(edge_dir_at_v[(e, v)])
        return ds

    def unknown_dirs(v):
        ds = []
        for e in incident[v]:
            if state[e] == -1:
                ds.append(edge_dir_at_v[(e, v)])
        return ds

    def edge_from_dir(v, d):
        for e in incident[v]:
            if edge_dir_at_v[(e, v)] == d:
                return e
        return None

    def is_straight_pair(d1, d2):
        return opposite_dir(d1) == d2

    def is_turn_pair(d1, d2):
        return d1 != d2 and opposite_dir(d1) != d2

    queue = deque()

    def assign(e, val):
        cur = state[e]
        if cur == val:
            return True
        if cur != -1:
            return False
        state[e] = val
        a, b = edges[e]
        if val == 1:
            deg_on[a] += 1
            deg_on[b] += 1
        else:
            deg_off[a] += 1
            deg_off[b] += 1
        queue.append(a)
        queue.append(b)
        return True

    # Vertex generic degree logic
    def propagate_vertex_degree(v):
        # Every vertex on loop has degree 0 or 2; never 1 or >2
        if deg_on[v] > 2:
            return False
        rem = 4 if 0 < rc(v)[0] < n - 1 and 0 < rc(v)[1] < n - 1 else len(incident[v])
        # Generic using incident count:
        total_inc = len(incident[v])
        if deg_on[v] == 1 and deg_off[v] == total_inc - 1:
            return False
        if deg_on[v] == 2:
            for e in incident[v]:
                if state[e] == -1:
                    if not assign(e, 0):
                        return False
        if deg_off[v] == total_inc - 2:
            # Remaining unknowns, if any, must be ON to avoid degree 1.
            unknowns = [e for e in incident[v] if state[e] == -1]
            if deg_on[v] == 1:
                if len(unknowns) != 1:
                    return False
                if not assign(unknowns[0], 1):
                    return False
            elif deg_on[v] == 0 and len(unknowns) == 2:
                if not assign(unknowns[0], 1):
                    return False
                if not assign(unknowns[1], 1):
                    return False
        if deg_on[v] == 1 and deg_off[v] == total_inc:
            return False
        if deg_on[v] == 1 and not any(state[e] == -1 for e in incident[v]):
            return False
        return True

    def force_pattern(v, required_type):
        # required_type in {'straight','turn'}
        on_dirs = chosen_dirs(v)
        unk_dirs = unknown_dirs(v)

        if len(on_dirs) > 2:
            return False

        if len(on_dirs) == 2:
            ok = is_straight_pair(on_dirs[0], on_dirs[1]) if required_type == 'straight' else is_turn_pair(on_dirs[0], on_dirs[1])
            return ok

        if len(on_dirs) == 1:
            d = on_dirs[0]
            if required_type == 'straight':
                opp = opposite_dir(d)
                eopp = edge_from_dir(v, opp)
                if eopp is None:
                    return False
                for e in incident[v]:
                    if e != eopp and state[e] == -1:
                        if not assign(e, 0):
                            return False
                if state[eopp] == 0:
                    return False
                if state[eopp] == -1:
                    if not assign(eopp, 1):
                        return False
            else:
                # Need one perpendicular partner, opposite cannot be used
                eopp = edge_from_dir(v, opposite_dir(d))
                if eopp is not None and state[eopp] == -1:
                    if not assign(eopp, 0):
                        return False
                perp = []
                for dd in range(4):
                    if dd != d and dd != opposite_dir(d):
                        e = edge_from_dir(v, dd)
                        if e is not None:
                            perp.append(e)
                possible = [e for e in perp if state[e] != 0]
                if not possible:
                    return False
                if len(possible) == 1:
                    if not assign(possible[0], 1):
                        return False
                if all(state[e] == 0 for e in perp):
                    return False
            return True

        # len(on_dirs) == 0
        possible_pairs = []
        dirs_present = [edge_dir_at_v[(e, v)] for e in incident[v] if state[e] != 0]
        for i in range(len(dirs_present)):
            for j in range(i + 1, len(dirs_present)):
                d1, d2 = dirs_present[i], dirs_present[j]
                ok = is_straight_pair(d1, d2) if required_type == 'straight' else is_turn_pair(d1, d2)
                if ok:
                    possible_pairs.append((d1, d2))

        if not possible_pairs:
            return False

        # If all valid pairs require/forbid some edge, propagate
        for e in incident[v]:
            if state[e] != -1:
                continue
            d = edge_dir_at_v[(e, v)]
            in_all = all(d in pair for pair in possible_pairs)
            in_none = all(d not in pair for pair in possible_pairs)
            if in_all:
                if not assign(e, 1):
                    return False
            elif in_none:
                if not assign(e, 0):
                    return False
        return True

    def clue_neighbor_constraints(v):
        t = clues[v]
        if t == 'W':
            if not force_pattern(v, 'straight'):
                return False
        else:
            if not force_pattern(v, 'turn'):
                return False

        # Stronger clue propagation through adjacent chosen/forced directions.
        # For W at v with straight directions d and opp(d), at least one of the neighboring vertices
        # reached immediately before or after must be a turn.
        # For B at v with turn d1,d2, both adjacent vertices on those edges must be straight.
        on = chosen_dirs(v)
        if len(on) != 2:
            return True

        r, c = rc(v)
        nbrs = []
        for d in on:
            if d == 0:
                nbrs.append((vid(r - 1, c), d))
            elif d == 1:
                nbrs.append((vid(r, c + 1), d))
            elif d == 2:
                nbrs.append((vid(r + 1, c), d))
            else:
                nbrs.append((vid(r, c - 1), d))

        if t == 'B':
            # adjacent vertices must be straight relative to edge continuing through them
            for nv, incoming_from_v in nbrs:
                incoming = opposite_dir(incoming_from_v)
                e_in = edge_from_dir(nv, incoming)
                if e_in is None or state[e_in] != 1:
                    continue
                if not force_pattern(nv, 'straight'):
                    return False
        else:
            # White is straight here. If one side's neighboring vertex is already forced straight-through
            # with continuation pointing away from v, the other side must eventually be turn-capable.
            pass
        return True

    def no_dead_end_global():
        for v in range(V):
            total_inc = len(incident[v])
            if deg_on[v] == 1 and deg_off[v] == total_inc - 1:
                return False
            if deg_on[v] > 2:
                return False
        return True

    def partial_cycle_check():
        parent, comps, chosen_edges, used_vertices = build_on_components()
        if not used_vertices:
            return True
        # Any component where all vertices currently have degree 2 forms a closed cycle.
        # That's only allowed if it includes all chosen edges and no undecided edge can connect out,
        # and in final stage it must be the unique full solution cycle.
        for comp_vs in comps.values():
            all_deg2 = all(deg_on[v] == 2 for v in comp_vs)
            if all_deg2:
                if len(comp_vs) != len(used_vertices):
                    return False
                # full chosen structure is a cycle; if undecided edges still exist that must be off at all comp vertices,
                # accept only if every clue already satisfied and all vertices outside component have degree 0 and can remain 0.
        return True

    def connectivity_feasible():
        # Chosen-path endpoints/components must still be connectable through non-forbidden edges.
        parent, comps, chosen_edges, used_vertices = build_on_components()
        interesting = [set(vs) for vs in comps.values()]
        if len(interesting) <= 1:
            return True

        # Build graph on vertices using edges not forbidden.
        adj = [[] for _ in range(V)]
        for i, (a, b) in enumerate(edges):
            if state[i] != 0:
                adj[a].append(b)
                adj[b].append(a)

        # Component-reachability collapse
        comp_ids = {}
        comp_list = list(comps.values())
        for idx, vs in enumerate(comp_list):
            for v in vs:
                comp_ids[v] = idx

        seen_comp = set()
        q = deque(comp_list[0][:1])
        seen_v = {comp_list[0][0]}
        while q:
            v = q.popleft()
            if v in comp_ids:
                seen_comp.add(comp_ids[v])
            for u in adj[v]:
                if u not in seen_v:
                    seen_v.add(u)
                    q.append(u)
        return len(seen_comp) == len(comp_list)

    def propagate():
        while queue:
            v = queue.popleft()
            if not propagate_vertex_degree(v):
                return False
            if v in clue_vertices:
                if not clue_neighbor_constraints(v):
                    return False

        # Sweep because clue implications can unlock more degree implications.
        changed = True
        while changed:
            changed = False
            before = tuple(state)
            for v in range(V):
                if not propagate_vertex_degree(v):
                    return False
                if v in clue_vertices and not clue_neighbor_constraints(v):
                    return False
            if not no_dead_end_global():
                return False
            if not partial_cycle_check():
                return False
            if not connectivity_feasible():
                return False
            if tuple(state) != before:
                changed = True
        return True

    # Initial clue-based border impossibilities
    for v, t in clues.items():
        r, c = rc(v)
        dirs = {edge_dir_at_v[(e, v)] for e in incident[v]}
        if t == 'W':
            # White needs a straight pair, so on border/corner some directions impossible:
            has_ud = 0 in dirs and 2 in dirs
            has_lr = 1 in dirs and 3 in dirs
            if not (has_ud or has_lr):
                return "No Solution"
        else:
            # Black needs a turn, impossible only at isolated but never here if degree >=2
            if len(dirs) < 2:
                return "No Solution"
    for v in range(V):
        queue.append(v)
    if not propagate():
        return "No Solution"

    def all_clues_satisfied_exact():
        for v, t in clues.items():
            if deg_on[v] != 2:
                return False
            ds = chosen_dirs(v)
            if len(ds) != 2:
                return False
            if t == 'W':
                if not is_straight_pair(ds[0], ds[1]):
                    return False
                # At least one adjacent step before/after must be a turn.
                # Check neighboring vertices on both sides if determinable in final solution.
                ok_turn_neighbor = False
                r, c = rc(v)
                for d in ds:
                    if d == 0:
                        nv = vid(r - 1, c)
                    elif d == 1:
                        nv = vid(r, c + 1)
                    elif d == 2:
                        nv = vid(r + 1, c)
                    else:
                        nv = vid(r, c - 1)
                    nds = chosen_dirs(nv)
                    if len(nds) == 2 and is_turn_pair(nds[0], nds[1]):
                        ok_turn_neighbor = True
                if not ok_turn_neighbor:
                    return False
            else:
                if not is_turn_pair(ds[0], ds[1]):
                    return False
                # Both adjacent vertices must be straight in final loop.
                r, c = rc(v)
                for d in ds:
                    if d == 0:
                        nv = vid(r - 1, c)
                    elif d == 1:
                        nv = vid(r, c + 1)
                    elif d == 2:
                        nv = vid(r + 1, c)
                    else:
                        nv = vid(r, c - 1)
                    nds = chosen_dirs(nv)
                    if len(nds) != 2 or not is_straight_pair(nds[0], nds[1]):
                        return False
        return True

    def final_single_cycle():
        # every vertex degree 0 or 2, chosen edges form exactly one cycle, includes all clue vertices
        used = [v for v in range(V) if deg_on[v] > 0]
        if not used:
            return False
        for v in range(V):
            if deg_on[v] not in (0, 2):
                return False
        if any(deg_on[v] == 0 for v in clue_vertices):
            return False

        parent, comps, chosen_edges, used_vertices = build_on_components()
        if len(comps) != 1:
            return False
        if chosen_edges != len(used_vertices):
            return False
        return all_clues_satisfied_exact()

    def choose_branch_edge():
        # Most constrained undecided edge: prioritize around clues and near degree-1 vertices
        best = None
        best_score = -1
        for e in range(E):
            if state[e] != -1:
                continue
            a, b = edges[e]
            score = 0
            if a in clue_vertices:
                score += 5
            if b in clue_vertices:
                score += 5
            score += deg_on[a] + deg_on[b]
            score += 2 if deg_off[a] >= len(incident[a]) - 2 else 0
            score += 2 if deg_off[b] >= len(incident[b]) - 2 else 0
            if score > best_score:
                best_score = score
                best = e
        return best

    def dfs():
        if all(s != -1 for s in state):
            return final_single_cycle()

        e = choose_branch_edge()
        if e is None:
            return final_single_cycle()

        # Try ON first, usually stronger for loop construction
        for val in (1, 0):
            ss = snapshot()
            if assign(e, val) and propagate():
                if dfs():
                    return True
            restore(ss)
            queue.clear()
        return False

    if not dfs():
        return "No Solution"

    # Reconstruct ordered cycle
    chosen_adj = defaultdict(list)
    for i, (a, b) in enumerate(edges):
        if state[i] == 1:
            chosen_adj[a].append(b)
            chosen_adj[b].append(a)

    start = min(chosen_adj)
    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = chosen_adj[cur]
        nxt = nbrs[0] if nbrs[0] != prev else (nbrs[1] if len(nbrs) > 1 else None)
        if nxt is None:
            return "No Solution"
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > len(chosen_adj) + 2:
            return "No Solution"

    out = [rc(v) for v in path]
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B6', None, None, None, None, None, None], [None, None, None, None, 'B5', None, None, 'B8'], [None, None, None, None, None, None, None, None], ['W5', None, None, 'B3', None, 'W3', 'W5', None], [None, None, None, None, 'B4', None, None, None], [None, None, None, None, None, None, None, None], [None, 'B6', None, None, None, None, None, None], [None, None, None, None, None, None, None, None]]}

from collections import defaultdict, deque

# General solver for the loop puzzle described in the prompt.
# Model:
# - data is an (N+1)x(N+1) grid of dots/intersections.
# - Clues live on dots as well.
# - Selected unit edges between orthogonally adjacent dots form one single simple cycle.
# - Every clue dot must have degree 2 in the final loop.
# - White clue: loop goes straight through the clue.
# - Black clue: loop turns at the clue.
# - Number k equals the sum of the lengths of the two maximal straight rays of the loop
#   extending from that clue in the two loop directions.

# The implementation uses:
# 1) strong local degree propagation,
# 2) clue orientation filtering,
# 3) ray-length bound propagation for clues,
# 4) connectivity / premature-cycle pruning,
# 5) branch on most constrained undecided edge.
#
# The code is generalized and does not hardcode the pictured instance.

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]
VERT = {0, 2}
HORZ = {1, 3}


def solve(observation):
    data = observation['data']
    n1 = len(data)
    if n1 == 0 or any(len(row) != n1 for row in data):
        return "No Solution"
    n = n1 - 1

    # Edge indexing
    # Horizontal edge h[r][c]: between (r,c) and (r,c+1), 0<=r<=n, 0<=c<n
    # Vertical edge   v[r][c]: between (r,c) and (r+1,c), 0<=r<n, 0<=c<=n
    edges = []
    edge_id = {}
    incident = [[[] for _ in range(n1)] for _ in range(n1)]
    edge_info = {}

    def add_edge(a, b):
        eid = len(edges)
        edges.append((a, b))
        edge_id[(a, b)] = eid
        edge_id[(b, a)] = eid
        edge_info[eid] = (a, b)
        ar, ac = a
        br, bc = b
        incident[ar][ac].append(eid)
        incident[br][bc].append(eid)
        return eid

    for r in range(n1):
        for c in range(n):
            add_edge((r, c), (r, c + 1))
    for r in range(n):
        for c in range(n1):
            add_edge((r, c), (r + 1, c))

    m = len(edges)

    # For each dot and direction, which edge leaves in that direction.
    out_edge = [[{} for _ in range(n1)] for _ in range(n1)]
    for eid, (a, b) in enumerate(edges):
        ar, ac = a
        br, bc = b
        dr, dc = br - ar, bc - ac
        if (dr, dc) == (-1, 0):
            d1, d2 = 0, 2
        elif (dr, dc) == (0, 1):
            d1, d2 = 1, 3
        elif (dr, dc) == (1, 0):
            d1, d2 = 2, 0
        elif (dr, dc) == (0, -1):
            d1, d2 = 3, 1
        else:
            raise AssertionError("Bad edge")
        out_edge[ar][ac][d1] = eid
        out_edge[br][bc][d2] = eid

    clues = {}
    for r in range(n1):
        for c in range(n1):
            token = data[r][c]
            if token is None:
                continue
            t = token[0].upper()
            k = int(token[1:])
            if t not in ("W", "B"):
                return "No Solution"
            clues[(r, c)] = (t, k)

    # State: -1 unknown, 0 off, 1 on
    state = [-1] * m

    # Track clue orientation domain:
    # None => not fixed, else one of "V","H" for white; "UR","RD","DL","LU" for black
    orient_domain = {}
    for pos, (t, _) in clues.items():
        r, c = pos
        dirs = set(out_edge[r][c].keys())
        if t == 'W':
            dom = []
            if 0 in dirs and 2 in dirs:
                dom.append('V')
            if 1 in dirs and 3 in dirs:
                dom.append('H')
            orient_domain[pos] = set(dom)
        else:
            dom = []
            if 0 in dirs and 1 in dirs:
                dom.append('UR')
            if 1 in dirs and 2 in dirs:
                dom.append('RD')
            if 2 in dirs and 3 in dirs:
                dom.append('DL')
            if 3 in dirs and 0 in dirs:
                dom.append('LU')
            orient_domain[pos] = set(dom)
        if not orient_domain[pos]:
            return "No Solution"

    # Helpers
    def dir_between(a, b):
        ar, ac = a
        br, bc = b
        dr, dc = br - ar, bc - ac
        if (dr, dc) == (-1, 0):
            return 0
        if (dr, dc) == (0, 1):
            return 1
        if (dr, dc) == (1, 0):
            return 2
        if (dr, dc) == (0, -1):
            return 3
        raise AssertionError("Non-adjacent")

    def endpoint_of(eid, u):
        a, b = edges[eid]
        return b if a == u else a

    def edge_dir_from_dot(eid, u):
        v = endpoint_of(eid, u)
        return dir_between(u, v)

    def set_edge(eid, val, queue):
        cur = state[eid]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[eid] = val
        a, b = edges[eid]
        queue.append(('dot', a))
        queue.append(('dot', b))
        # clue rays touching either endpoint may be impacted
        if a in clues:
            queue.append(('clue', a))
        if b in clues:
            queue.append(('clue', b))
        return True

    def deg_counts(dot):
        on = off = unk = 0
        for eid in incident[dot[0]][dot[1]]:
            s = state[eid]
            if s == 1:
                on += 1
            elif s == 0:
                off += 1
            else:
                unk += 1
        return on, off, unk

    def allowed_pairs_for_clue(pos):
        t, _ = clues[pos]
        dom = orient_domain[pos]
        pairs = []
        if t == 'W':
            if 'V' in dom:
                pairs.append((0, 2))
            if 'H' in dom:
                pairs.append((1, 3))
        else:
            mapping = {
                'UR': (0, 1),
                'RD': (1, 2),
                'DL': (2, 3),
                'LU': (3, 0),
            }
            for x in dom:
                pairs.append(mapping[x])
        return pairs

    def restrict_clue_by_local_state(pos, queue):
        r, c = pos
        t, _ = clues[pos]
        dom = set()
        for ori in orient_domain[pos]:
            if t == 'W':
                pair = (0, 2) if ori == 'V' else (1, 3)
            else:
                pair = {'UR': (0, 1), 'RD': (1, 2), 'DL': (2, 3), 'LU': (3, 0)}[ori]
            ok = True
            used = set(pair)
            for d in pair:
                if d not in out_edge[r][c]:
                    ok = False
                    break
                eid = out_edge[r][c][d]
                if state[eid] == 0:
                    ok = False
                    break
            if not ok:
                continue
            for d, eid in out_edge[r][c].items():
                if d not in used and state[eid] == 1:
                    ok = False
                    break
            if ok:
                dom.add(ori)
        if not dom:
            return False
        if dom != orient_domain[pos]:
            orient_domain[pos] = dom
            queue.append(('dot', pos))
            queue.append(('clue', pos))
        return True

    def force_from_clue_local(pos, queue):
        if not restrict_clue_by_local_state(pos, queue):
            return False
        r, c = pos
        pairs = allowed_pairs_for_clue(pos)
        if not pairs:
            return False
        needed_dirs = set.intersection(*[set(p) for p in pairs]) if pairs else set()
        possible_dirs = set.union(*[set(p) for p in pairs]) if pairs else set()
        # Force always-used directions on, never-used directions off.
        for d, eid in out_edge[r][c].items():
            if d in needed_dirs:
                if not set_edge(eid, 1, queue):
                    return False
            elif d not in possible_dirs:
                if not set_edge(eid, 0, queue):
                    return False
        return True

    def propagate_dot(dot, queue):
        r, c = dot
        eids = incident[r][c]
        on = [eid for eid in eids if state[eid] == 1]
        off = [eid for eid in eids if state[eid] == 0]
        unk = [eid for eid in eids if state[eid] == -1]

        clue = clues.get(dot)

        if clue is None:
            # Degree must be 0 or 2
            if len(on) > 2:
                return False
            if len(on) == 1 and not unk:
                return False
            if len(on) == 3:
                return False
            if len(on) == 2:
                for eid in unk:
                    if not set_edge(eid, 0, queue):
                        return False
            elif len(on) == 1 and len(unk) == 1:
                if not set_edge(unk[0], 1, queue):
                    return False
            elif len(on) == 0 and len(unk) == 1:
                if not set_edge(unk[0], 0, queue):
                    return False
        else:
            # Clue dots must have degree exactly 2 and shape constrained
            if len(on) > 2:
                return False
            if len(on) + len(unk) < 2:
                return False
            if len(on) == 2:
                for eid in unk:
                    if not set_edge(eid, 0, queue):
                        return False
            elif len(on) + len(unk) == 2:
                for eid in unk:
                    if not set_edge(eid, 1, queue):
                        return False
            if not force_from_clue_local(dot, queue):
                return False

        return True

    def follow_straight_length_from_clue(pos, start_dir):
        # Returns (min_len, max_len) for the straight ray starting at clue in start_dir.
        # Exact when enough determined; max_len may be finite due to boundary/forced stop.
        # If impossible to start, returns None.
        r, c = pos
        if start_dir not in out_edge[r][c]:
            return None
        first_eid = out_edge[r][c][start_dir]
        if state[first_eid] == 0:
            return None

        cur = pos
        d = start_dir
        length = 0
        min_len = 0

        while True:
            if d not in out_edge[cur[0]][cur[1]]:
                break
            eid = out_edge[cur[0]][cur[1]][d]
            s = state[eid]
            if s == 0:
                break
            nxt = endpoint_of(eid, cur)
            if s == -1:
                # Can stop before taking unknown edge
                return (min_len, length + 1e9)
            length += 1
            min_len = length
            # At nxt, the straight segment continues iff opposite edge is on/possible and
            # no mandatory turn blocks it. A clue at nxt may force turn/straight.
            if d not in out_edge[nxt[0]][nxt[1]]:
                # impossible logically, but continue handling by stop
                return (min_len, min_len)
            oppd = d
            # Determine whether continuation in same geometric direction beyond nxt exists.
            if oppd not in out_edge[nxt[0]][nxt[1]]:
                return (min_len, min_len)

            # Need edge leaving nxt in same direction d.
            if d not in out_edge[nxt[0]][nxt[1]]:
                return (min_len, min_len)

            if nxt in clues:
                t, _ = clues[nxt]
                dom = orient_domain[nxt]
                possible_continue = False
                forced_stop = True
                for ori in dom:
                    if t == 'W':
                        pair = (0, 2) if ori == 'V' else (1, 3)
                    else:
                        pair = {'UR': (0, 1), 'RD': (1, 2), 'DL': (2, 3), 'LU': (3, 0)}[ori]
                    if OPP[d] in pair and d in pair:
                        possible_continue = True
                    if OPP[d] in pair and d not in pair:
                        pass
                    if OPP[d] in pair:
                        if d in pair:
                            forced_stop = False
                    else:
                        forced_stop = False
                if not possible_continue:
                    return (min_len, min_len)

            cont_eid = out_edge[nxt[0]][nxt[1]].get(d)
            if cont_eid is None:
                return (min_len, min_len)
            if state[cont_eid] == 0:
                return (min_len, min_len)
            if state[cont_eid] == -1:
                return (min_len, length + 1e9)
            cur = nxt

    def clue_length_bounds(pos):
        pairs = allowed_pairs_for_clue(pos)
        if not pairs:
            return None
        bounds = []
        for d1, d2 in pairs:
            b1 = follow_straight_length_from_clue(pos, d1)
            b2 = follow_straight_length_from_clue(pos, d2)
            if b1 is None or b2 is None:
                continue
            mn = b1[0] + b2[0]
            mx = b1[1] + b2[1]
            bounds.append(((d1, d2), mn, mx))
        if not bounds:
            return None
        return bounds

    def propagate_clue_length(pos, queue):
        info = clue_length_bounds(pos)
        if info is None:
            return False
        _, k = clues[pos]
        keep = []
        for pair, mn, mx in info:
            if mn <= k <= mx:
                keep.append(pair)
        if not keep:
            return False

        # Restrict orientation domain by feasible pairs
        t, _ = clues[pos]
        if t == 'W':
            new_dom = set()
            for p in keep:
                if set(p) == {0, 2}:
                    new_dom.add('V')
                elif set(p) == {1, 3}:
                    new_dom.add('H')
        else:
            inv = {(0, 1): 'UR', (1, 2): 'RD', (2, 3): 'DL', (0, 3): 'LU', (3, 0): 'LU'}
            new_dom = set()
            for p in keep:
                pp = tuple(sorted(p))
                if pp == (0, 1):
                    new_dom.add('UR')
                elif pp == (1, 2):
                    new_dom.add('RD')
                elif pp == (2, 3):
                    new_dom.add('DL')
                elif pp == (0, 3):
                    new_dom.add('LU')
        if not new_dom:
            return False
        if new_dom != orient_domain[pos]:
            orient_domain[pos] = new_dom
            queue.append(('dot', pos))
            queue.append(('clue', pos))

        # If only one pair remains and exact lower/upper force some first edges, local propagation handles it.
        return True

    def check_no_small_closed_component():
        # Build graph of on-edges. If any connected component is a cycle but does not contain all on-edges, reject.
        adj = defaultdict(list)
        on_edges = [eid for eid, s in enumerate(state) if s == 1]
        if not on_edges:
            return True
        for eid in on_edges:
            a, b = edges[eid]
            adj[a].append((b, eid))
            adj[b].append((a, eid))
        seen = set()
        total_on = len(on_edges)
        for v in list(adj):
            if v in seen:
                continue
            q = [v]
            seen.add(v)
            verts = []
            ecount2 = 0
            deg2 = True
            while q:
                x = q.pop()
                verts.append(x)
                if len(adj[x]) != 2:
                    deg2 = False
                ecount2 += len(adj[x])
                for y, _ in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        q.append(y)
            ecount = ecount2 // 2
            if deg2 and ecount < total_on:
                return False
        return True

    def check_global_feasibility():
        # Degree sanity
        for r in range(n1):
            for c in range(n1):
                dot = (r, c)
                on, off, unk = deg_counts(dot)
                if dot in clues:
                    if on > 2 or on + unk < 2:
                        return False
                else:
                    if on > 2:
                        return False
                    if on == 1 and unk == 0:
                        return False
        if not check_no_small_closed_component():
            return False
        return True

    def propagate():
        queue = deque()
        for r in range(n1):
            for c in range(n1):
                queue.append(('dot', (r, c)))
        for pos in clues:
            queue.append(('clue', pos))

        while queue:
            typ, obj = queue.popleft()
            if typ == 'dot':
                if not propagate_dot(obj, queue):
                    return False
            else:
                if not propagate_clue_length(obj, queue):
                    return False
            if not check_global_feasibility():
                return False
        return True

    def snapshot():
        return (state[:], {k: set(v) for k, v in orient_domain.items()})

    def restore(snap):
        s1, s2 = snap
        state[:] = s1
        orient_domain.clear()
        orient_domain.update({k: set(v) for k, v in s2.items()})

    def all_determined():
        return all(s != -1 for s in state)

    def extract_cycle():
        on_edges = [eid for eid, s in enumerate(state) if s == 1]
        if not on_edges:
            return None
        adj = defaultdict(list)
        for eid in on_edges:
            a, b = edges[eid]
            adj[a].append((b, eid))
            adj[b].append((a, eid))
        # Every used vertex must have degree 2, and there must be exactly one component.
        verts = list(adj.keys())
        if any(len(adj[v]) != 2 for v in verts):
            return None
        seen = set()
        q = [verts[0]]
        seen.add(verts[0])
        while q:
            x = q.pop()
            for y, _ in adj[x]:
                if y not in seen:
                    seen.add(y)
                    q.append(y)
        if len(seen) != len(verts):
            return None

        start = min(verts)
        n1a = adj[start][0][0]
        n1b = adj[start][1][0]
        prev = start
        cur = min(n1a, n1b)
        path = [start]
        while True:
            path.append(cur)
            nbrs = [y for y, _ in adj[cur]]
            nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
            prev, cur = cur, nxt
            if cur == start:
                path.append(start)
                break
        return path

    def validate_final(path):
        if path is None or len(path) < 4 or path[0] != path[-1]:
            return False
        used = set()
        for i in range(len(path) - 1):
            a, b = path[i], path[i + 1]
            if (a, b) not in edge_id:
                return False
            used.add(edge_id[(a, b)])
        if any((state[eid] == 1) != (eid in used) for eid in range(m)):
            return False

        # Check clue semantics exactly
        # Build successor structure from path
        prev_next = defaultdict(list)
        for i in range(len(path) - 1):
            a, b = path[i], path[i + 1]
            prev_next[a].append(b)
            prev_next[b].append(a)
        for pos, (t, k) in clues.items():
            if len(prev_next[pos]) != 2:
                return False
            nbs = prev_next[pos]
            d1 = dir_between(pos, nbs[0])
            d2 = dir_between(pos, nbs[1])
            if t == 'W':
                if {d1, d2} not in ({0, 2}, {1, 3}):
                    return False
            else:
                if {d1, d2} in ({0, 2}, {1, 3}):
                    return False

            # Compute exact straight lengths in both directions
            total = 0
            for nd in [d1, d2]:
                cur = pos
                d = nd
                cnt = 0
                while True:
                    eid = out_edge[cur[0]][cur[1]].get(d)
                    if eid is None or state[eid] != 1:
                        break
                    nxt = endpoint_of(eid, cur)
                    cnt += 1
                    if nxt not in prev_next:
                        break
                    n1_, n2_ = prev_next[nxt]
                    # continue along same direction if possible
                    dirs = [dir_between(nxt, n1_), dir_between(nxt, n2_)]
                    if OPP[d] not in dirs:
                        break
                    other = n1_ if dir_between(nxt, n1_) != OPP[d] else n2_
                    nd2 = dir_between(nxt, other)
                    if nd2 != d:
                        break
                    cur = nxt
                total += cnt
            if total != k:
                return False
        return True

    def choose_branch_edge():
        # Prefer edges adjacent to clues and most constrained endpoints.
        best = None
        best_score = None
        for eid, s in enumerate(state):
            if s != -1:
                continue
            a, b = edges[eid]
            score = 0
            if a in clues:
                score += 10
            if b in clues:
                score += 10
            ao, _, au = deg_counts(a)
            bo, _, bu = deg_counts(b)
            score += (4 - au) + (4 - bu) + ao + bo
            if best is None or score > best_score:
                best = eid
                best_score = score
        return best

    def search():
        if not propagate():
            return None
        if all_determined():
            path = extract_cycle()
            if validate_final(path):
                return path
            return None

        eid = choose_branch_edge()
        if eid is None:
            return None

        # Try promising value first:
        # Prefer on if either endpoint already has one on-edge or clue likely needs it.
        a, b = edges[eid]
        vals = [1, 0]
        if deg_counts(a)[0] == 0 and deg_counts(b)[0] == 0 and a not in clues and b not in clues:
            vals = [0, 1]

        for val in vals:
            snap = snapshot()
            q = deque()
            if set_edge(eid, val, q):
                # process immediate queue before recursive call
                ok = True
                while q and ok:
                    typ, obj = q.popleft()
                    if typ == 'dot':
                        ok = propagate_dot(obj, q)
                    else:
                        ok = propagate_clue_length(obj, q)
                    if ok and not check_global_feasibility():
                        ok = False
                if ok:
                    ans = search()
                    if ans is not None:
                        return ans
            restore(snap)
        return None

    ans = search()
    return str(ans) if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, None, None, None, None, 3], [1, 2, 1, None, 1, 2, None, None], [2, 3, None, 2, None, None, 2, None], [3, None, None, 2, None, None, None, None], [None, 2, None, None, 3, None, 2, None], [None, None, None, 3, None, None, 3, None], [None, 2, None, 3, 2, 2, None, None], [None, None, None, None, None, None, None, None]]}

# Slitherlink solver with strong propagation and limited search.
# Returns an ordered list of loop dot coordinates, or "No Solution".

from collections import deque, defaultdict

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0

    # Edge indexing
    # Horizontal edge h[r][c]: between dots (r,c) and (r,c+1), r in 0..n, c in 0..m-1
    # Vertical edge v[r][c]: between dots (r,c) and (r+1,c), r in 0..n-1, c in 0..m
    edges = []
    edge_of = {}

    def add_edge(kind, r, c, a, b):
        idx = len(edges)
        edges.append({
            'kind': kind, 'r': r, 'c': c,
            'a': a, 'b': b,
            'cells': []
        })
        edge_of[(kind, r, c)] = idx
        return idx

    for r in range(n + 1):
        for c in range(m):
            add_edge('h', r, c, (r, c), (r, c + 1))
    for r in range(n):
        for c in range(m + 1):
            add_edge('v', r, c, (r, c), (r + 1, c))

    # Cell -> incident edges in order [top, right, bottom, left]
    cell_edges = {}
    for r in range(n):
        for c in range(m):
            top = edge_of[('h', r, c)]
            right = edge_of[('v', r, c + 1)]
            bottom = edge_of[('h', r + 1, c)]
            left = edge_of[('v', r, c)]
            cell_edges[(r, c)] = [top, right, bottom, left]
            for e in (top, right, bottom, left):
                edges[e]['cells'].append((r, c))

    # Dot -> incident edges
    dot_edges = defaultdict(list)
    for i, e in enumerate(edges):
        dot_edges[e['a']].append(i)
        dot_edges[e['b']].append(i)

    dots = [(r, c) for r in range(n + 1) for c in range(m + 1)]
    clues = [(r, c, data[r][c]) for r in range(n) for c in range(m) if data[r][c] is not None]

    # State: -1 unknown, 0 off, 1 on
    state = [-1] * len(edges)

    # Counts
    cell_on = {}
    cell_off = {}
    cell_unknown = {}
    for r in range(n):
        for c in range(m):
            cell_on[(r, c)] = 0
            cell_off[(r, c)] = 0
            cell_unknown[(r, c)] = 4

    dot_on = {}
    dot_off = {}
    dot_unknown = {}
    for d in dots:
        deg = len(dot_edges[d])
        dot_on[d] = 0
        dot_off[d] = 0
        dot_unknown[d] = deg

    # DSU for currently-on edges to avoid small cycles before final completion
    parent = list(range((n + 1) * (m + 1)))
    rank = [0] * len(parent)

    def dot_id(d):
        return d[0] * (m + 1) + d[1]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    # Trail for backtracking
    trail = []
    queue = deque()
    queued_cells = set()
    queued_dots = set()

    def push_change(kind, key, old):
        trail.append((kind, key, old))

    def assign_edge(ei, val):
        cur = state[ei]
        if cur == val:
            return True
        if cur != -1:
            return False

        e = edges[ei]
        push_change('edge', ei, cur)
        state[ei] = val

        for cell in e['cells']:
            if val == 1:
                push_change('cell_on', cell, cell_on[cell]); cell_on[cell] += 1
            else:
                push_change('cell_off', cell, cell_off[cell]); cell_off[cell] += 1
            push_change('cell_unknown', cell, cell_unknown[cell]); cell_unknown[cell] -= 1
            if cell not in queued_cells:
                queued_cells.add(cell)
                queue.append(('cell', cell))

        for d in (e['a'], e['b']):
            if val == 1:
                push_change('dot_on', d, dot_on[d]); dot_on[d] += 1
            else:
                push_change('dot_off', d, dot_off[d]); dot_off[d] += 1
            push_change('dot_unknown', d, dot_unknown[d]); dot_unknown[d] -= 1
            if d not in queued_dots:
                queued_dots.add(d)
                queue.append(('dot', d))

        # small-cycle prevention for ON edge
        if val == 1:
            a = dot_id(e['a'])
            b = dot_id(e['b'])
            ra, rb = find(a), find(b)
            on_total = sum(1 for x in state if x == 1)
            unknown_total = sum(1 for x in state if x == -1)
            # If adding closes a cycle while there remain other edges potentially on elsewhere,
            # it would create a disconnected subloop.
            if ra == rb:
                if on_total < 4:
                    return False
                # closed a component; only okay if this is the final completed loop
                # which means all undecided edges must become off and all active dots degree 2.
                # We don't know yet, so reject premature cycle.
                if unknown_total > 0:
                    return False
            else:
                push_change('parent', None, parent[:])
                push_change('rank', None, rank[:])
                union(a, b)

        return True

    def rollback(mark):
        nonlocal queue, queued_cells, queued_dots
        while len(trail) > mark:
            kind, key, old = trail.pop()
            if kind == 'edge':
                state[key] = old
            elif kind == 'cell_on':
                cell_on[key] = old
            elif kind == 'cell_off':
                cell_off[key] = old
            elif kind == 'cell_unknown':
                cell_unknown[key] = old
            elif kind == 'dot_on':
                dot_on[key] = old
            elif kind == 'dot_off':
                dot_off[key] = old
            elif kind == 'dot_unknown':
                dot_unknown[key] = old
            elif kind == 'parent':
                parent[:] = old
            elif kind == 'rank':
                rank[:] = old
        queue = deque()
        queued_cells = set()
        queued_dots = set()

    def enqueue_all():
        for r in range(n):
            for c in range(m):
                if (r, c) not in queued_cells:
                    queued_cells.add((r, c))
                    queue.append(('cell', (r, c)))
        for d in dots:
            if d not in queued_dots:
                queued_dots.add(d)
                queue.append(('dot', d))

    def cell_rule(cell):
        r, c = cell
        clue = data[r][c]
        if clue is None:
            return True
        on = cell_on[cell]
        off = cell_off[cell]
        unk = cell_unknown[cell]
        if on > clue or on + unk < clue:
            return False
        if unk == 0:
            return on == clue
        es = cell_edges[cell]
        if on == clue:
            for e in es:
                if state[e] == -1 and not assign_edge(e, 0):
                    return False
        elif on + unk == clue:
            for e in es:
                if state[e] == -1 and not assign_edge(e, 1):
                    return False

        # Human-style pair rules for 3s and 0s emerge from count closure above.
        # Corner/adjacency pattern rules:
        # If clue is 3, opposite unknown possibilities can be restricted by neighboring dot degree.
        if clue == 3:
            # Any dot touching two edges of this cell cannot have both cell-incident edges off.
            top, right, bottom, left = es
            pairs = [
                ((r, c), [top, left]),
                ((r, c + 1), [top, right]),
                ((r + 1, c + 1), [bottom, right]),
                ((r + 1, c), [bottom, left]),
            ]
            for d, pair in pairs:
                vals = [state[pair[0]], state[pair[1]]]
                if vals.count(0) == 1 and vals.count(-1) == 1:
                    other = pair[vals.index(-1)]
                    if not assign_edge(other, 1):
                        return False
        return True

    def dot_rule(d):
        on = dot_on[d]
        unk = dot_unknown[d]
        if on > 2:
            return False
        if on == 1 and unk == 0:
            return False
        if on + unk < 2 and on != 0:
            return False

        es = dot_edges[d]
        if unk == 0:
            return on in (0, 2)

        # Degree completion
        if on == 2:
            for e in es:
                if state[e] == -1 and not assign_edge(e, 0):
                    return False
        elif on + unk == 2 and on < 2:
            for e in es:
                if state[e] == -1 and not assign_edge(e, 1):
                    return False
        elif on == 1 and unk == 1:
            for e in es:
                if state[e] == -1 and not assign_edge(e, 1):
                    return False

        return True

    def propagate():
        while queue:
            typ, item = queue.popleft()
            if typ == 'cell':
                queued_cells.discard(item)
                if not cell_rule(item):
                    return False
            else:
                queued_dots.discard(item)
                if not dot_rule(item):
                    return False
        return True

    # Initial direct clue rules
    enqueue_all()
    if not propagate():
        return "No Solution"

    def is_solved():
        if any(v == -1 for v in state):
            return False
        for r, c, clue in clues:
            if cell_on[(r, c)] != clue:
                return False
        active_dots = [d for d in dots if dot_on[d] == 2]
        if not active_dots:
            return False
        if any(dot_on[d] not in (0, 2) for d in dots):
            return False

        # Single loop check
        adj = defaultdict(list)
        on_edges = []
        for i, v in enumerate(state):
            if v == 1:
                a, b = edges[i]['a'], edges[i]['b']
                adj[a].append(b)
                adj[b].append(a)
                on_edges.append(i)
        start = active_dots[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    dq.append(y)
        return all(d in seen for d in active_dots)

    def component_would_close(ei):
        e = edges[ei]
        return find(dot_id(e['a'])) == find(dot_id(e['b']))

    def choose_edge():
        # Most constrained unknown edge: prioritize those in clue cells and near active dots.
        best = None
        best_score = None
        for i, v in enumerate(state):
            if v != -1:
                continue
            score = 0
            e = edges[i]
            for cell in e['cells']:
                clue = data[cell[0]][cell[1]]
                if clue is not None:
                    score += 10
                    need = clue - cell_on[cell]
                    score += 4 - abs(2 * need - cell_unknown[cell])
            for d in (e['a'], e['b']):
                score += 3 * dot_on[d] + (2 - dot_unknown[d])
            if component_would_close(i):
                score += 5
            if best is None or score > best_score:
                best = i
                best_score = score
        return best

    def search():
        if is_solved():
            return True

        ei = choose_edge()
        if ei is None:
            return False

        # Value ordering
        vals = [1, 0]
        if component_would_close(ei):
            vals = [0, 1]

        for val in vals:
            mark = len(trail)
            if assign_edge(ei, val) and propagate():
                # Global anti-subloop check on current forced graph:
                # if a connected component of on-edges is already a cycle and not final => reject.
                if not has_premature_cycle():
                    if search():
                        return True
            rollback(mark)
        return False

    def has_premature_cycle():
        adj = defaultdict(list)
        on_vertices = set()
        on_edges_cnt = 0
        for i, v in enumerate(state):
            if v == 1:
                a, b = edges[i]['a'], edges[i]['b']
                adj[a].append(b)
                adj[b].append(a)
                on_vertices.add(a)
                on_vertices.add(b)
                on_edges_cnt += 1
        seen = set()
        for s in list(on_vertices):
            if s in seen:
                continue
            comp_v = 0
            comp_e2 = 0
            dq = deque([s])
            seen.add(s)
            all_deg2 = True
            while dq:
                x = dq.popleft()
                comp_v += 1
                deg = len(adj[x])
                comp_e2 += deg
                if deg != 2:
                    all_deg2 = False
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        dq.append(y)
            comp_e = comp_e2 // 2
            if all_deg2 and comp_e == comp_v:
                if any(v == -1 for v in state):
                    return True
                if comp_e != on_edges_cnt:
                    return True
        return False

    if not search():
        return "No Solution"

    # Extract ordered loop coordinates
    adj = defaultdict(list)
    for i, v in enumerate(state):
        if v == 1:
            a, b = edges[i]['a'], edges[i]['b']
            adj[a].append(b)
            adj[b].append(a)

    start = None
    for d in sorted(adj):
        if len(adj[d]) == 2:
            start = d
            break
    if start is None:
        return "No Solution"

    path = [start]
    prev = None
    cur = start
    while True:
        ns = adj[cur]
        nxt = ns[0] if ns[0] != prev else ns[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break

    return str(path)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [1, 17, 9, 20, 23, 10, 11], 'col_sum': [15, 13, 9, 22, 27, 9, 7]}

# Weighted black-cell puzzle solver.
# General model:
# - Grid is RxC.
# - Row i has weight rw[i] and target row_sum[i]: sum of column-weights of black cells in row i.
# - Column j has weight cw[j] and target col_sum[j]: sum of row-weights of black cells in column j.
# In the pictured family, the visible side/top labels are the weights. For a plain NxN board they are 1..N.
#
# We solve generally with:
# 1) enumerate all feasible bitmasks for each row from row targets;
# 2) propagate by column residual feasibility;
# 3) branch on the most constrained row;
# 4) verify and return a grid of 'B'/None.

from bisect import bisect_left, bisect_right

def subset_sums_by_mask(weights):
    n = len(weights)
    sums = [0] * (1 << n)
    for m in range(1, 1 << n):
        lsb = m & -m
        k = lsb.bit_length() - 1
        sums[m] = sums[m ^ lsb] + weights[k]
    return sums

def masks_for_target(weights, target):
    sums = subset_sums_by_mask(weights)
    return [m for m, s in enumerate(sums) if s == target]

def build_col_subset_tables(row_weights):
    # For each column, possible sets of rows are subsets of row indices.
    # Precompute all subset sums of row_weights and bucket masks by sum.
    R = len(row_weights)
    sums = [0] * (1 << R)
    by_sum = {}
    by_sum[0] = [0]
    for m in range(1, 1 << R):
        lsb = m & -m
        k = lsb.bit_length() - 1
        s = sums[m ^ lsb] + row_weights[k]
        sums[m] = s
        by_sum.setdefault(s, []).append(m)
    return sums, by_sum

def allowed_masks_for_col_residual(total_rows_mask, assigned_black_mask, unassigned_rows_mask, target, col_sum_to_masks):
    # Need final column black-row mask M such that:
    # - assigned black rows are included
    # - assigned white rows (outside unassigned and not in assigned_black_mask) are excluded automatically
    # - among unassigned rows, any subset can be chosen
    # equivalently M = assigned_black_mask | X, where X subset of unassigned_rows_mask,
    # and sum(M) == target.
    rem = target
    # row weights handled by using actual subset masks from precomputed tables, so query all masks of exact target
    candidates = col_sum_to_masks.get(rem, [])
    out = []
    fixed_white_mask = total_rows_mask & ~(assigned_black_mask | unassigned_rows_mask)
    for m in candidates:
        if (m & assigned_black_mask) != assigned_black_mask:
            continue
        if m & fixed_white_mask:
            continue
        out.append(m)
    return out

def format_answer(chosen_masks, R, C):
    grid = []
    for i in range(R):
        row = []
        m = chosen_masks[i]
        for j in range(C):
            row.append('B' if (m >> j) & 1 else None)
        grid.append(row)
    return str(grid)

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    R = len(row_targets)
    C = len(col_targets)

    # In this puzzle family, side/top labels define weights; if not separately provided,
    # use 1..R and 1..C as shown in the image.
    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Enumerate feasible patterns for each row target.
    row_candidates = [masks_for_target(col_weights, t) for t in row_targets]
    if any(len(cands) == 0 for cands in row_candidates):
        return "No Solution"

    # Column helper tables over row weights.
    _, col_sum_to_masks = build_col_subset_tables(row_weights)
    total_rows_mask = (1 << R) - 1

    # Fast infeasibility checks for columns under partial assignment.
    # assigned_rows_mask: which rows already fixed
    # chosen_masks[i]: selected row bitmask if assigned, else -1
    def propagate_domains(domains, assigned_rows_mask, chosen_masks):
        # Repeatedly prune row domains using column residual feasibility.
        changed = True
        while changed:
            changed = False

            # Build per-column assigned black mask and unassigned row mask.
            assigned_black_per_col = [0] * C
            for i in range(R):
                if (assigned_rows_mask >> i) & 1:
                    m = chosen_masks[i]
                    for j in range(C):
                        if (m >> j) & 1:
                            assigned_black_per_col[j] |= (1 << i)
            unassigned_rows_mask = total_rows_mask & ~assigned_rows_mask

            # For each column, compute all allowed final black-row masks.
            allowed_col_masks = []
            possible_bits_by_col = []
            for j in range(C):
                allowed = allowed_masks_for_col_residual(
                    total_rows_mask,
                    assigned_black_per_col[j],
                    unassigned_rows_mask,
                    col_targets[j],
                    col_sum_to_masks
                )
                if not allowed:
                    return None
                allowed_col_masks.append(allowed)
                union_bits = 0
                inter_bits = total_rows_mask
                for m in allowed:
                    union_bits |= m
                    inter_bits &= m
                possible_bits_by_col.append((union_bits, inter_bits))

            # Prune each unassigned row domain against column possibilities.
            for i in range(R):
                if (assigned_rows_mask >> i) & 1:
                    continue
                new_dom = []
                bit = 1 << i
                for m in domains[i]:
                    ok = True
                    for j in range(C):
                        cell_black = (m >> j) & 1
                        union_bits, inter_bits = possible_bits_by_col[j]
                        if cell_black:
                            # row i must be black in some allowed mask
                            if not (union_bits & bit):
                                ok = False
                                break
                        else:
                            # row i must be white in some allowed mask
                            # i.e., not black in at least one allowed mask
                            if inter_bits & bit:
                                ok = False
                                break
                    if ok:
                        new_dom.append(m)
                if not new_dom:
                    return None
                if len(new_dom) != len(domains[i]):
                    domains[i] = new_dom
                    changed = True

            # If any unassigned row became singleton, assign it immediately.
            for i in range(R):
                if ((assigned_rows_mask >> i) & 1) == 0 and len(domains[i]) == 1:
                    chosen_masks[i] = domains[i][0]
                    assigned_rows_mask |= (1 << i)
                    changed = True

        return assigned_rows_mask

    def final_check(chosen):
        # Verify row sums and column sums exactly.
        for i in range(R):
            s = 0
            m = chosen[i]
            for j in range(C):
                if (m >> j) & 1:
                    s += col_weights[j]
            if s != row_targets[i]:
                return False
        for j in range(C):
            s = 0
            for i in range(R):
                if (chosen[i] >> j) & 1:
                    s += row_weights[i]
            if s != col_targets[j]:
                return False
        return True

    # Initial state.
    domains0 = [list(cands) for cands in row_candidates]
    chosen0 = [-1] * R
    assigned0 = 0
    for i in range(R):
        if len(domains0[i]) == 1:
            chosen0[i] = domains0[i][0]
            assigned0 |= (1 << i)

    assigned0 = propagate_domains(domains0, assigned0, chosen0)
    if assigned0 is None:
        return "No Solution"

    def score_row(i, domains, assigned_rows_mask, chosen_masks):
        # Most constrained row: smallest domain; tie-break by impact on columns.
        if (assigned_rows_mask >> i) & 1:
            return None
        impact = 0
        for j in range(C):
            vals = set((m >> j) & 1 for m in domains[i])
            if len(vals) > 1:
                impact += 1
        return (len(domains[i]), -impact, i)

    def dfs(domains, assigned_rows_mask, chosen_masks):
        assigned_rows_mask = propagate_domains(domains, assigned_rows_mask, chosen_masks)
        if assigned_rows_mask is None:
            return None
        if assigned_rows_mask == total_rows_mask:
            if final_check(chosen_masks):
                return chosen_masks[:]
            return None

        choices = [score_row(i, domains, assigned_rows_mask, chosen_masks) for i in range(R)]
        choices = [x for x in choices if x is not None]
        _, _, row = min(choices)

        # Value ordering: try masks that better satisfy tighter columns first.
        # Compute current assigned black masks per column.
        assigned_black_per_col = [0] * C
        for i in range(R):
            if (assigned_rows_mask >> i) & 1:
                m = chosen_masks[i]
                for j in range(C):
                    if (m >> j) & 1:
                        assigned_black_per_col[j] |= (1 << i)

        def mask_priority(m):
            # Prefer blacks in columns with larger remaining target pressure.
            p = 0
            for j in range(C):
                if (m >> j) & 1:
                    current = 0
                    abm = assigned_black_per_col[j]
                    x = abm
                    while x:
                        lsb = x & -x
                        idx = lsb.bit_length() - 1
                        current += row_weights[idx]
                        x ^= lsb
                    p -= (col_targets[j] - current)
            return p

        for m in sorted(domains[row], key=mask_priority):
            new_domains = [d[:] for d in domains]
            new_chosen = chosen_masks[:]
            new_chosen[row] = m
            new_domains[row] = [m]
            res = dfs(new_domains, assigned_rows_mask | (1 << row), new_chosen)
            if res is not None:
                return res
        return None

    solution = dfs(domains0, assigned0, chosen0)
    if solution is None:
        return "No Solution"
    return format_answer(solution, R, C)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [17, 24, 21, 19, 23, 24, 8], 'col_sum': [20, 24, 21, 12, 16, 27, 14]}

from itertools import combinations

# Puzzle model:
# - Grid is RxC.
# - Row i has weight (i+1); Column j has weight (j+1).
# - If cell (i,j) is black:
#     * row i contributes (j+1) to row_sum[i]
#     * col j contributes (i+1) to col_sum[j]
#
# We solve by:
# 1) Enumerating all feasible patterns for each row from its target sum.
# 2) Enumerating all feasible patterns for each column from its target sum.
# 3) Repeatedly applying arc-consistency style pruning between row/column domains.
# 4) Using strong subset-sum bounds on residuals.
# 5) Branching only on the most constrained row/column when needed.

def bit_positions(mask, n):
    i = 0
    while i < n:
        if (mask >> i) & 1:
            yield i
        i += 1

def format_grid(row_masks, r, c):
    grid = []
    for i in range(r):
        row = []
        mask = row_masks[i]
        for j in range(c):
            row.append('B' if ((mask >> j) & 1) else None)
        grid.append(row)
    return str(grid)

def subset_masks_by_sum(weights, target):
    n = len(weights)
    out = []
    # Efficient enough for typical puzzle sizes like 7x7.
    for mask in range(1 << n):
        s = 0
        m = mask
        idx = 0
        while m:
            if m & 1:
                s += weights[idx]
            idx += 1
            m >>= 1
        if s == target:
            out.append(mask)
    return out

def precompute_sum_bounds(weights):
    # For quick lower/upper achievable sum bounds on a subset of positions.
    # Indexed by bitmask over positions.
    n = len(weights)
    total = 1 << n
    min_sum = [0] * total
    max_sum = [0] * total
    # Here min over subset is always 0 because cells can be omitted,
    # and max is the sum of all available weights in subset.
    for mask in range(1, total):
        lsb = mask & -mask
        idx = lsb.bit_length() - 1
        prev = mask ^ lsb
        max_sum[mask] = max_sum[prev] + weights[idx]
    return min_sum, max_sum

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    R = len(row_targets)
    C = len(col_targets)

    row_weights = [i + 1 for i in range(R)]
    col_weights = [j + 1 for j in range(C)]

    # Row domains: masks over columns whose weighted sum equals row target.
    row_domains = []
    for i in range(R):
        dom = subset_masks_by_sum(col_weights, row_targets[i])
        if not dom:
            return "No Solution"
        row_domains.append(set(dom))

    # Column domains: masks over rows whose weighted sum equals col target.
    col_domains = []
    for j in range(C):
        dom = subset_masks_by_sum(row_weights, col_targets[j])
        if not dom:
            return "No Solution"
        col_domains.append(set(dom))

    full_row_mask = (1 << C) - 1
    full_col_mask = (1 << R) - 1

    col_min_unused, col_max_unused = precompute_sum_bounds(col_weights)
    row_min_unused, row_max_unused = precompute_sum_bounds(row_weights)

    def domain_forced_possible_bits_row(dom):
        it = iter(dom)
        first = next(it)
        forced1 = first
        possible1 = first
        for m in it:
            forced1 &= m
            possible1 |= m
        forced0 = (~possible1) & full_row_mask
        return forced1, forced0, possible1

    def domain_forced_possible_bits_col(dom):
        it = iter(dom)
        first = next(it)
        forced1 = first
        possible1 = first
        for m in it:
            forced1 &= m
            possible1 |= m
        forced0 = (~possible1) & full_col_mask
        return forced1, forced0, possible1

    def propagate(row_domains, col_domains):
        changed = True
        while changed:
            changed = False

            row_forced1 = [0] * R
            row_forced0 = [0] * R
            row_possible1 = [0] * R
            for i in range(R):
                if not row_domains[i]:
                    return False
                f1, f0, p1 = domain_forced_possible_bits_row(row_domains[i])
                row_forced1[i] = f1
                row_forced0[i] = f0
                row_possible1[i] = p1

            col_forced1 = [0] * C
            col_forced0 = [0] * C
            col_possible1 = [0] * C
            for j in range(C):
                if not col_domains[j]:
                    return False
                f1, f0, p1 = domain_forced_possible_bits_col(col_domains[j])
                col_forced1[j] = f1
                col_forced0[j] = f0
                col_possible1[j] = p1

            # Cell-wise consistency:
            # If one side forces a cell black/white, eliminate incompatible patterns on the other side.
            for i in range(R):
                new_dom = set()
                rf1 = row_forced1[i]
                rf0 = row_forced0[i]
                for mask in row_domains[i]:
                    ok = True
                    m = mask
                    # Check against column forced bits.
                    for j in range(C):
                        bit = (mask >> j) & 1
                        if bit:
                            if (col_forced0[j] >> i) & 1:
                                ok = False
                                break
                        else:
                            if (col_forced1[j] >> i) & 1:
                                ok = False
                                break
                    if ok:
                        new_dom.add(mask)
                if not new_dom:
                    return False
                if len(new_dom) != len(row_domains[i]):
                    row_domains[i] = new_dom
                    changed = True

            for j in range(C):
                new_dom = set()
                for mask in col_domains[j]:
                    ok = True
                    for i in range(R):
                        bit = (mask >> i) & 1
                        if bit:
                            if (row_forced0[i] >> j) & 1:
                                ok = False
                                break
                        else:
                            if (row_forced1[i] >> j) & 1:
                                ok = False
                                break
                    if ok:
                        new_dom.add(mask)
                if not new_dom:
                    return False
                if len(new_dom) != len(col_domains[j]):
                    col_domains[j] = new_dom
                    changed = True

            # Recompute after possible changes.
            row_forced1 = [0] * R
            row_forced0 = [0] * R
            row_possible1 = [0] * R
            for i in range(R):
                if not row_domains[i]:
                    return False
                f1, f0, p1 = domain_forced_possible_bits_row(row_domains[i])
                row_forced1[i] = f1
                row_forced0[i] = f0
                row_possible1[i] = p1

            col_forced1 = [0] * C
            col_forced0 = [0] * C
            col_possible1 = [0] * C
            for j in range(C):
                if not col_domains[j]:
                    return False
                f1, f0, p1 = domain_forced_possible_bits_col(col_domains[j])
                col_forced1[j] = f1
                col_forced0[j] = f0
                col_possible1[j] = p1

            # Residual sum feasibility for rows:
            # For row i, some cells are forced black by columns, some impossible by columns.
            # The row target must be achievable from remaining optional cells.
            for i in range(R):
                forced_sum = 0
                available_mask = 0
                for j in range(C):
                    if (col_forced1[j] >> i) & 1:
                        forced_sum += col_weights[j]
                    elif ((col_forced0[j] >> i) & 1) == 0:
                        available_mask |= (1 << j)
                if forced_sum > row_targets[i]:
                    return False
                rem = row_targets[i] - forced_sum
                if rem < 0 or rem > col_max_unused[available_mask]:
                    return False

                new_dom = set()
                for mask in row_domains[i]:
                    # Must include all column-forced black cells and exclude forced white.
                    if (mask & row_forced0[i]) != 0:
                        continue
                    if (mask & col_forced1_mask_for_row(i, col_forced1, C)) != col_forced1_mask_for_row(i, col_forced1, C):
                        continue
                    new_dom.add(mask)
                if not new_dom:
                    return False
                if len(new_dom) != len(row_domains[i]):
                    row_domains[i] = new_dom
                    changed = True

            # Residual sum feasibility for columns.
            for j in range(C):
                forced_sum = 0
                available_mask = 0
                for i in range(R):
                    if (row_forced1[i] >> j) & 1:
                        forced_sum += row_weights[i]
                    elif ((row_forced0[i] >> j) & 1) == 0:
                        available_mask |= (1 << i)
                if forced_sum > col_targets[j]:
                    return False
                rem = col_targets[j] - forced_sum
                if rem < 0 or rem > row_max_unused[available_mask]:
                    return False

                required_mask = row_forced1_mask_for_col(j, row_forced1, R)
                forbidden_mask = row_forced0_mask_for_col(j, row_forced0, R)
                new_dom = set()
                for mask in col_domains[j]:
                    if (mask & forbidden_mask) != 0:
                        continue
                    if (mask & required_mask) != required_mask:
                        continue
                    new_dom.add(mask)
                if not new_dom:
                    return False
                if len(new_dom) != len(col_domains[j]):
                    col_domains[j] = new_dom
                    changed = True

            # Pairwise support filtering:
            # Every cell value allowed by a row pattern must be supported by some column pattern and vice versa.
            for i in range(R):
                supported_masks = set()
                for rmask in row_domains[i]:
                    ok = True
                    for j in range(C):
                        bit = (rmask >> j) & 1
                        found = False
                        for cmask in col_domains[j]:
                            if ((cmask >> i) & 1) == bit:
                                found = True
                                break
                        if not found:
                            ok = False
                            break
                    if ok:
                        supported_masks.add(rmask)
                if not supported_masks:
                    return False
                if len(supported_masks) != len(row_domains[i]):
                    row_domains[i] = supported_masks
                    changed = True

            for j in range(C):
                supported_masks = set()
                for cmask in col_domains[j]:
                    ok = True
                    for i in range(R):
                        bit = (cmask >> i) & 1
                        found = False
                        for rmask in row_domains[i]:
                            if ((rmask >> j) & 1) == bit:
                                found = True
                                break
                        if not found:
                            ok = False
                            break
                    if ok:
                        supported_masks.add(cmask)
                if not supported_masks:
                    return False
                if len(supported_masks) != len(col_domains[j]):
                    col_domains[j] = supported_masks
                    changed = True

        return True

    def col_forced1_mask_for_row(i, col_forced1, C):
        mask = 0
        for j in range(C):
            if (col_forced1[j] >> i) & 1:
                mask |= (1 << j)
        return mask

    def row_forced1_mask_for_col(j, row_forced1, R):
        mask = 0
        for i in range(R):
            if (row_forced1[i] >> j) & 1:
                mask |= (1 << i)
        return mask

    def row_forced0_mask_for_col(j, row_forced0, R):
        mask = 0
        for i in range(R):
            if (row_forced0[i] >> j) & 1:
                mask |= (1 << i)
        return mask

    def is_solved(row_domains, col_domains):
        return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

    def choose_branch(row_domains, col_domains):
        # Most constrained variable, preferring smaller domain > 1.
        best_kind = None
        best_idx = -1
        best_size = 10**9

        for i, d in enumerate(row_domains):
            s = len(d)
            if 1 < s < best_size:
                best_size = s
                best_kind = 'row'
                best_idx = i

        for j, d in enumerate(col_domains):
            s = len(d)
            if 1 < s < best_size:
                best_size = s
                best_kind = 'col'
                best_idx = j

        return best_kind, best_idx

    def search(row_domains, col_domains):
        if not propagate(row_domains, col_domains):
            return None

        if is_solved(row_domains, col_domains):
            row_masks = [next(iter(d)) for d in row_domains]
            # Final consistency check against columns.
            for j in range(C):
                cmask = 0
                for i in range(R):
                    if (row_masks[i] >> j) & 1:
                        cmask |= (1 << i)
                if cmask not in col_domains[j]:
                    return None
            return row_masks

        kind, idx = choose_branch(row_domains, col_domains)
        if kind is None:
            return None

        if kind == 'row':
            # Heuristic: try patterns with higher support first.
            candidates = []
            for mask in row_domains[idx]:
                score = 0
                for j in range(C):
                    bit = (mask >> j) & 1
                    count = 0
                    for cmask in col_domains[j]:
                        if ((cmask >> idx) & 1) == bit:
                            count += 1
                    score += count
                candidates.append((score, mask))
            candidates.sort(reverse=True)

            for _, mask in candidates:
                new_rows = [set(d) for d in row_domains]
                new_cols = [set(d) for d in col_domains]
                new_rows[idx] = {mask}
                res = search(new_rows, new_cols)
                if res is not None:
                    return res
        else:
            candidates = []
            for mask in col_domains[idx]:
                score = 0
                for i in range(R):
                    bit = (mask >> i) & 1
                    count = 0
                    for rmask in row_domains[i]:
                        if ((rmask >> idx) & 1) == bit:
                            count += 1
                    score += count
                candidates.append((score, mask))
            candidates.sort(reverse=True)

            for _, mask in candidates:
                new_rows = [set(d) for d in row_domains]
                new_cols = [set(d) for d in col_domains]
                new_cols[idx] = {mask}
                res = search(new_rows, new_cols)
                if res is not None:
                    return res

        return None

    result = search([set(d) for d in row_domains], [set(d) for d in col_domains])
    if result is None:
        return "No Solution"
    return format_grid(result, R, C)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 1, 1, 1, 1], [0, 0, 1, 1, 1], [2, 2, 3, 1, 1], [2, 3, 3, 4, 4], [3, 3, 3, 3, 4]]}

# 1-star Star Battle solver with human-style deduction plus tightly-pruned search.
# The observation is an N x N region-id grid. We must place exactly one star in each
# row, column, and region, and stars may not touch orthogonally or diagonally.

from collections import defaultdict

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Normalize regions into contiguous ids if needed.
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            region_cells[data[r][c]].append((r, c))
    region_ids = list(region_cells.keys())
    ridx = {rid: i for i, rid in enumerate(region_ids)}
    m = len(region_ids)

    if m != n:
        # In a valid 1-star puzzle, number of regions must equal N.
        return "No Solution"

    full_mask = (1 << n) - 1

    # Cell indexing.
    cell_to_bit = {}
    bit_to_cell = {}
    row_cells = [0] * n
    col_cells = [0] * n
    reg_cells = [0] * n
    neighbors = {}

    bit = 1
    for r in range(n):
        for c in range(n):
            cell_to_bit[(r, c)] = bit
            bit_to_cell[bit] = (r, c)
            row_cells[r] |= bit
            col_cells[c] |= bit
            reg_cells[ridx[data[r][c]]] |= bit
            bit <<= 1

    # Adjacency mask for "cannot touch", including self for convenient banning.
    all_cells_mask = (1 << (n * n)) - 1
    for r in range(n):
        for c in range(n):
            b = cell_to_bit[(r, c)]
            mask = b
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        mask |= cell_to_bit[(nr, nc)]
            neighbors[b] = mask

    # Initial candidates: every cell allowed.
    row_avail = row_cells[:]
    col_avail = col_cells[:]
    reg_avail = reg_cells[:]

    # Fixed placements.
    row_star = [0] * n
    col_star = [0] * n
    reg_star = [0] * n

    def popcount(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    def cell_rc(bit_):
        return bit_to_cell[bit_]

    def legal_domain_for_row(r, row_av, col_av, reg_av):
        # Candidate cells for row r that are still available in row/col/region spaces.
        dom = row_av[r]
        if row_star[r]:
            return row_star[r]
        out = 0
        for b in iter_bits(dom):
            rr, cc = cell_rc(b)
            rg = ridx[data[rr][cc]]
            if col_star[cc] and col_star[cc] != b:
                continue
            if reg_star[rg] and reg_star[rg] != b:
                continue
            if (col_av[cc] & b) and (reg_av[rg] & b):
                out |= b
        return out

    def legal_domain_for_col(c, row_av, col_av, reg_av):
        dom = col_av[c]
        if col_star[c]:
            return col_star[c]
        out = 0
        for b in iter_bits(dom):
            rr, cc = cell_rc(b)
            rg = ridx[data[rr][cc]]
            if row_star[rr] and row_star[rr] != b:
                continue
            if reg_star[rg] and reg_star[rg] != b:
                continue
            if (row_av[rr] & b) and (reg_av[rg] & b):
                out |= b
        return out

    def legal_domain_for_reg(g, row_av, col_av, reg_av):
        dom = reg_av[g]
        if reg_star[g]:
            return reg_star[g]
        out = 0
        for b in iter_bits(dom):
            rr, cc = cell_rc(b)
            if row_star[rr] and row_star[rr] != b:
                continue
            if col_star[cc] and col_star[cc] != b:
                continue
            if (row_av[rr] & b) and (col_av[cc] & b):
                out |= b
        return out

    def place(bit_, row_av, col_av, reg_av, placements):
        r, c = cell_rc(bit_)
        g = ridx[data[r][c]]

        # Contradictions with existing fixed stars.
        if row_star[r] and row_star[r] != bit_:
            return False
        if col_star[c] and col_star[c] != bit_:
            return False
        if reg_star[g] and reg_star[g] != bit_:
            return False

        # Must still be available.
        if not (row_av[r] & bit_ and col_av[c] & bit_ and reg_av[g] & bit_):
            return False

        # Set fixed stars.
        row_star[r] = bit_
        col_star[c] = bit_
        reg_star[g] = bit_

        placements.append(bit_)

        # Ban all touching cells everywhere.
        ban = neighbors[bit_]

        # Row updates.
        for rr in range(n):
            before = row_av[rr]
            if rr == r:
                row_av[rr] = bit_
            else:
                row_av[rr] &= ~ban
            if row_av[rr] == 0:
                return False

        # Column updates.
        for cc in range(n):
            before = col_av[cc]
            if cc == c:
                col_av[cc] = bit_
            else:
                col_av[cc] &= ~ban
            if col_av[cc] == 0:
                return False

        # Region updates.
        for gg in range(n):
            if gg == g:
                reg_av[gg] = bit_
            else:
                reg_av[gg] &= ~ban
            if reg_av[gg] == 0:
                return False

        # Exactly one star per row/column/region:
        # remove any other cells in same row/col/region from other structures via intersection consistency.
        # This is naturally enforced through row_av[r]=bit_, etc., plus later consistency checks.
        return True

    def check_consistency(row_av, col_av, reg_av):
        # Every unit has at least one legal candidate.
        for r in range(n):
            if legal_domain_for_row(r, row_av, col_av, reg_av) == 0:
                return False
        for c in range(n):
            if legal_domain_for_col(c, row_av, col_av, reg_av) == 0:
                return False
        for g in range(n):
            if legal_domain_for_reg(g, row_av, col_av, reg_av) == 0:
                return False

        # Hall-like quick checks on consecutive rows/cols due to no-touching:
        # in k consecutive rows, at least k distinct columns are needed, but adjacency
        # forbids same/adjacent columns for neighboring chosen rows. A simple strong
        # necessary check uses union size >= k.
        for start in range(n):
            union = 0
            for end in range(start, n):
                union |= legal_domain_for_rows_block(start, end, row_av, col_av, reg_av)
                k = end - start + 1
                if popcount(columns_mask_from_cells(union)) < k:
                    return False
        for start in range(n):
            union = 0
            for end in range(start, n):
                union |= legal_domain_for_cols_block(start, end, row_av, col_av, reg_av)
                k = end - start + 1
                if popcount(rows_mask_from_cells(union)) < k:
                    return False
        return True

    def columns_mask_from_cells(mask):
        out = 0
        for b in iter_bits(mask):
            _, c = cell_rc(b)
            out |= 1 << c
        return out

    def rows_mask_from_cells(mask):
        out = 0
        for b in iter_bits(mask):
            r, _ = cell_rc(b)
            out |= 1 << r
        return out

    def legal_domain_for_rows_block(r0, r1, row_av, col_av, reg_av):
        out = 0
        for r in range(r0, r1 + 1):
            out |= legal_domain_for_row(r, row_av, col_av, reg_av)
        return out

    def legal_domain_for_cols_block(c0, c1, row_av, col_av, reg_av):
        out = 0
        for c in range(c0, c1 + 1):
            out |= legal_domain_for_col(c, row_av, col_av, reg_av)
        return out

    def force_hidden_singles(row_av, col_av, reg_av):
        changed = True
        placements = []
        while changed:
            changed = False

            # Naked singles in rows.
            for r in range(n):
                if not row_star[r]:
                    dom = legal_domain_for_row(r, row_av, col_av, reg_av)
                    if dom == 0:
                        return None
                    if dom & (dom - 1) == 0:
                        if not place(dom, row_av, col_av, reg_av, placements):
                            return None
                        changed = True

            # Naked singles in cols.
            for c in range(n):
                if not col_star[c]:
                    dom = legal_domain_for_col(c, row_av, col_av, reg_av)
                    if dom == 0:
                        return None
                    if dom & (dom - 1) == 0:
                        if not place(dom, row_av, col_av, reg_av, placements):
                            return None
                        changed = True

            # Naked singles in regions.
            for g in range(n):
                if not reg_star[g]:
                    dom = legal_domain_for_reg(g, row_av, col_av, reg_av)
                    if dom == 0:
                        return None
                    if dom & (dom - 1) == 0:
                        if not place(dom, row_av, col_av, reg_av, placements):
                            return None
                        changed = True

            # Hidden singles by cell ownership intersections:
            # if a row and a region intersect in exactly one legal cell, and either side
            # must use that intersection uniquely, place it. Likewise for row/col, col/region.
            for r in range(n):
                if row_star[r]:
                    continue
                row_dom = legal_domain_for_row(r, row_av, col_av, reg_av)
                # row-region intersections
                regs_seen = defaultdict(int)
                last = {}
                for b in iter_bits(row_dom):
                    rr, cc = cell_rc(b)
                    g = ridx[data[rr][cc]]
                    regs_seen[g] += 1
                    last[g] = b
                for g, cnt in regs_seen.items():
                    if not reg_star[g]:
                        reg_dom = legal_domain_for_reg(g, row_av, col_av, reg_av)
                        inter = row_dom & reg_dom
                        if inter and inter & (inter - 1) == 0:
                            if not place(inter, row_av, col_av, reg_av, placements):
                                return None
                            changed = True

            for c in range(n):
                if col_star[c]:
                    continue
                col_dom = legal_domain_for_col(c, row_av, col_av, reg_av)
                for g in range(n):
                    if reg_star[g]:
                        continue
                    inter = col_dom & legal_domain_for_reg(g, row_av, col_av, reg_av)
                    if inter and inter & (inter - 1) == 0:
                        if not place(inter, row_av, col_av, reg_av, placements):
                            return None
                        changed = True

            if not check_consistency(row_av, col_av, reg_av):
                return None

        return placements

    def solved():
        return all(row_star) and all(col_star) and all(reg_star)

    def choose_branch_unit(row_av, col_av, reg_av):
        # Human-style "most constrained unit" among rows, cols, regions.
        best = None

        for r in range(n):
            if not row_star[r]:
                dom = legal_domain_for_row(r, row_av, col_av, reg_av)
                cnt = popcount(dom)
                if cnt == 0:
                    return ("dead", r, 0)
                if best is None or cnt < best[2]:
                    best = ("row", r, cnt, dom)
        for c in range(n):
            if not col_star[c]:
                dom = legal_domain_for_col(c, row_av, col_av, reg_av)
                cnt = popcount(dom)
                if cnt == 0:
                    return ("dead", c, 0)
                if best is None or cnt < best[2]:
                    best = ("col", c, cnt, dom)
        for g in range(n):
            if not reg_star[g]:
                dom = legal_domain_for_reg(g, row_av, col_av, reg_av)
                cnt = popcount(dom)
                if cnt == 0:
                    return ("dead", g, 0)
                if best is None or cnt < best[2]:
                    best = ("reg", g, cnt, dom)

        return best

    def candidate_score(bit_, row_av, col_av, reg_av):
        # Lower score = more forcing / less disruptive ambiguity.
        r, c = cell_rc(bit_)
        g = ridx[data[r][c]]
        score = 0
        score += popcount(legal_domain_for_row(r, row_av, col_av, reg_av))
        score += popcount(legal_domain_for_col(c, row_av, col_av, reg_av))
        score += popcount(legal_domain_for_reg(g, row_av, col_av, reg_av))
        # Prefer candidates that ban many currently legal cells around them.
        impact = 0
        ban = neighbors[bit_]
        for rr in range(n):
            impact += popcount(row_av[rr] & ban)
        return (score, -impact)

    def search(row_av, col_av, reg_av):
        if force_hidden_singles(row_av, col_av, reg_av) is None:
            return None
        if solved():
            return True
        unit = choose_branch_unit(row_av, col_av, reg_av)
        if unit is None or unit[0] == "dead":
            return None

        kind, idx, _, dom = unit
        candidates = list(iter_bits(dom))
        candidates.sort(key=lambda b: candidate_score(b, row_av, col_av, reg_av))

        saved_row_star = row_star[:]
        saved_col_star = col_star[:]
        saved_reg_star = reg_star[:]

        for b in candidates:
            new_row_av = row_av[:]
            new_col_av = col_av[:]
            new_reg_av = reg_av[:]

            row_star[:] = saved_row_star
            col_star[:] = saved_col_star
            reg_star[:] = saved_reg_star

            placements = []
            if not place(b, new_row_av, new_col_av, new_reg_av, placements):
                continue
            if not check_consistency(new_row_av, new_col_av, new_reg_av):
                continue
            if search(new_row_av, new_col_av, new_reg_av):
                return True

        row_star[:] = saved_row_star
        col_star[:] = saved_col_star
        reg_star[:] = saved_reg_star
        return None

    if not check_consistency(row_avail, col_avail, reg_avail):
        return "No Solution"

    if not search(row_avail, col_avail, reg_avail):
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        b = row_star[r]
        if not b:
            return "No Solution"
        rr, cc = cell_rc(b)
        answer[rr][cc] = 'S'
    return str(answer)

