from functools import lru_cache

# This puzzle is equivalent to finding a 0/1 matrix X such that:
# - For each row i: sum_j X[i][j] * col_weight[j] = row_sum[i]
# - For each col j: sum_i X[i][j] * row_weight[i] = col_sum[j]
# Here the row weights are 1..R and column weights are 1..C, as shown on the image.


def solve(observation):
    row_sum = list(observation['row_sum'])
    col_sum = list(observation['col_sum'])
    R = len(row_sum)
    C = len(col_sum)

    row_weights = [i + 1 for i in range(R)]
    col_weights = [j + 1 for j in range(C)]

    if sum(row_sum) != sum(col_sum):
        return "No Solution"

    # Precompute subset masks grouped by weighted sum for rows and columns.
    # Row pattern: choose columns whose column-weights sum to row target.
    # Col pattern: choose rows whose row-weights sum to column target.
    row_masks_by_sum = subset_masks_by_weight_sum(col_weights)
    col_masks_by_sum = subset_masks_by_weight_sum(row_weights)

    row_domains = []
    for s in row_sum:
        dom = row_masks_by_sum.get(s, [])
        if not dom:
            return "No Solution"
        row_domains.append(dom[:])

    col_domains = []
    for s in col_sum:
        dom = col_masks_by_sum.get(s, [])
        if not dom:
            return "No Solution"
        col_domains.append(dom[:])

    # Initial propagation.
    row_domains, col_domains = propagate(row_domains, col_domains, R, C)
    if row_domains is None:
        return "No Solution"

    result = search(row_domains, col_domains, R, C)
    if result is None:
        return "No Solution"

    final_rows, _ = result
    grid = []
    for i in range(R):
        mask = final_rows[i][0]
        row = []
        for j in range(C):
            row.append('B' if (mask >> j) & 1 else None)
        grid.append(row)
    return str(grid)


def subset_masks_by_weight_sum(weights):
    n = len(weights)
    out = {}
    # Enumerate all subsets; feasible because puzzle sizes are typically small/moderate.
    for mask in range(1 << n):
        s = 0
        m = mask
        idx = 0
        while m:
            if m & 1:
                s += weights[idx]
            idx += 1
            m >>= 1
        # Remaining zero bits do not contribute.
        out.setdefault(s, []).append(mask)
    return out


def propagate(row_domains, col_domains, R, C):
    # Human-like iterative deduction:
    # 1. If a cell is always black/always white across a row's possibilities, enforce on columns.
    # 2. If a cell is always black/always white across a column's possibilities, enforce on rows.
    # 3. Repeat until stable.
    changed = True
    while changed:
        changed = False

        # Row-derived forced cells
        row_must1 = [0] * R
        row_must0 = [0] * R
        full_col_mask = (1 << C) - 1
        for i in range(R):
            dom = row_domains[i]
            if not dom:
                return None, None
            inter = full_col_mask
            union = 0
            for m in dom:
                inter &= m
                union |= m
            row_must1[i] = inter
            row_must0[i] = full_col_mask ^ union

        # Apply to columns
        for j in range(C):
            bit = 1 << j
            new_dom = []
            for cm in col_domains[j]:
                ok = True
                for i in range(R):
                    rb = 1 << i
                    cell_black_forced = (row_must1[i] & bit) != 0
                    cell_white_forced = (row_must0[i] & bit) != 0
                    has = (cm & rb) != 0
                    if cell_black_forced and not has:
                        ok = False
                        break
                    if cell_white_forced and has:
                        ok = False
                        break
                if ok:
                    new_dom.append(cm)
            if not new_dom:
                return None, None
            if len(new_dom) != len(col_domains[j]):
                col_domains[j] = new_dom
                changed = True

        # Column-derived forced cells
        col_must1 = [0] * C
        col_must0 = [0] * C
        full_row_mask = (1 << R) - 1
        for j in range(C):
            dom = col_domains[j]
            if not dom:
                return None, None
            inter = full_row_mask
            union = 0
            for m in dom:
                inter &= m
                union |= m
            col_must1[j] = inter
            col_must0[j] = full_row_mask ^ union

        # Apply to rows
        for i in range(R):
            bit = 1 << i
            new_dom = []
            for rm in row_domains[i]:
                ok = True
                for j in range(C):
                    cb = 1 << j
                    cell_black_forced = (col_must1[j] & bit) != 0
                    cell_white_forced = (col_must0[j] & bit) != 0
                    has = (rm & cb) != 0
                    if cell_black_forced and not has:
                        ok = False
                        break
                    if cell_white_forced and has:
                        ok = False
                        break
                if ok:
                    new_dom.append(rm)
            if not new_dom:
                return None, None
            if len(new_dom) != len(row_domains[i]):
                row_domains[i] = new_dom
                changed = True

        # Direct pairwise compatibility filtering for stronger pruning
        # A row pattern must be supported by at least one pattern in every intersecting column, and vice versa.
        for i in range(R):
            new_dom = []
            for rm in row_domains[i]:
                ok = True
                for j in range(C):
                    need = (rm >> j) & 1
                    supported = False
                    bit_i = 1 << i
                    for cm in col_domains[j]:
                        if (((cm & bit_i) != 0) == bool(need)):
                            supported = True
                            break
                    if not supported:
                        ok = False
                        break
                if ok:
                    new_dom.append(rm)
            if not new_dom:
                return None, None
            if len(new_dom) != len(row_domains[i]):
                row_domains[i] = new_dom
                changed = True

        for j in range(C):
            new_dom = []
            for cm in col_domains[j]:
                ok = True
                for i in range(R):
                    need = (cm >> i) & 1
                    supported = False
                    bit_j = 1 << j
                    for rm in row_domains[i]:
                        if (((rm & bit_j) != 0) == bool(need)):
                            supported = True
                            break
                    if not supported:
                        ok = False
                        break
                if ok:
                    new_dom.append(cm)
            if not new_dom:
                return None, None
            if len(new_dom) != len(col_domains[j]):
                col_domains[j] = new_dom
                changed = True

    return row_domains, col_domains


def search(row_domains, col_domains, R, C):
    # Solved when every row and column is singleton.
    if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
        # Sanity consistency check
        for i in range(R):
            rm = row_domains[i][0]
            for j in range(C):
                a = (rm >> j) & 1
                b = (col_domains[j][0] >> i) & 1
                if a != b:
                    return None
        return row_domains, col_domains

    # Choose the most constrained variable (row or column) with smallest domain > 1.
    best_is_row = True
    best_idx = -1
    best_len = 10**9

    for i, d in enumerate(row_domains):
        l = len(d)
        if 1 < l < best_len:
            best_len = l
            best_is_row = True
            best_idx = i

    for j, d in enumerate(col_domains):
        l = len(d)
        if 1 < l < best_len:
            best_len = l
            best_is_row = False
            best_idx = j

    if best_idx == -1:
        return None

    # Value ordering heuristic: try patterns that maximize agreement pressure first.
    if best_is_row:
        candidates = order_row_values(best_idx, row_domains, col_domains, R, C)
        for v in candidates:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] for d in col_domains]
            new_rows[best_idx] = [v]
            new_rows, new_cols = propagate(new_rows, new_cols, R, C)
            if new_rows is None:
                continue
            res = search(new_rows, new_cols, R, C)
            if res is not None:
                return res
    else:
        candidates = order_col_values(best_idx, row_domains, col_domains, R, C)
        for v in candidates:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] for d in col_domains]
            new_cols[best_idx] = [v]
            new_rows, new_cols = propagate(new_rows, new_cols, R, C)
            if new_rows is None:
                continue
            res = search(new_rows, new_cols, R, C)
            if res is not None:
                return res

    return None


def order_row_values(i, row_domains, col_domains, R, C):
    # Prefer row masks that fit rare column states.
    scored = []
    for rm in row_domains[i]:
        score = 0
        bit_i = 1 << i
        for j in range(C):
            need = (rm >> j) & 1
            cnt = 0
            for cm in col_domains[j]:
                if (((cm & bit_i) != 0) == bool(need)):
                    cnt += 1
            score += cnt
        scored.append((score, rm))
    scored.sort()
    return [rm for _, rm in scored]


def order_col_values(j, row_domains, col_domains, R, C):
    scored = []
    for cm in col_domains[j]:
        score = 0
        bit_j = 1 << j
        for i in range(R):
            need = (cm >> i) & 1
            cnt = 0
            for rm in row_domains[i]:
                if (((rm & bit_j) != 0) == bool(need)):
                    cnt += 1
            score += cnt
        scored.append((score, cm))
    scored.sort()
    return [cm for _, cm in scored]


