    print(solve(OBSERVATION))

OBSERVATION = {'data': [['B6', None, None, 'B7', None, None, None, None, 'B2', 'B2', None], [None, None, None, None, None, None, None, None, None, None, 'W2'], [None, None, None, None, 'W4', None, 'W3', None, 'B7', None, None], ['W5', 'W2', None, None, None, None, None, None, None, 'W2', None], [None, None, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, 'B2', None], [None, 'B2', None, None, 'B3', 'B3', None, 'B5', None, None, None], [None, None, None, None, None, None, None, None, None, None, None], [None, 'B2', 'B4', None, None, None, 'B3', None, 'B7', None, None], ['W2', None, None, 'B3', None, None, None, None, None, 'B2', 'W2'], [None, None, 'B2', None, None, None, 'B2', 'B2', None, None, None]]}

from collections import defaultdict, deque

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
AXIS = {'U': 'V', 'D': 'V', 'L': 'H', 'R': 'H'}


def solve(observation):
    data = observation['data']
    n = len(data) - 1  # clue grid is (n+1)x(n+1), loop lives on same lattice points

    vertices = [(r, c) for r in range(n + 1) for c in range(n + 1)]

    # Directed half-edges from each vertex.
    vdirs = {}
    for r, c in vertices:
        ds = []
        if r > 0:
            ds.append('U')
        if r < n:
            ds.append('D')
        if c > 0:
            ds.append('L')
        if c < n:
            ds.append('R')
        vdirs[(r, c)] = ds

    # Edge canonicalization.
    def move(v, d):
        dr, dc = DIRS[d]
        return (v[0] + dr, v[1] + dc)

    edge_index = {}
    edges = []
    for v in vertices:
        for d in vdirs[v]:
            u = move(v, d)
            if v < u:
                edge_index[(v, u)] = len(edges)
                edges.append((v, u))
    m = len(edges)

    def edge_id(v, d):
        u = move(v, d)
        a, b = (v, u) if v < u else (u, v)
        return edge_index[(a, b)]

    # Clues are on lattice points and must be degree 2.
    clues = {}
    for r in range(n + 1):
        for c in range(n + 1):
            tok = data[r][c]
            if tok is not None:
                clues[(r, c)] = (tok[0], int(tok[1:]))

    # Precompute ray edge lists for each clue and direction.
    rays = {}
    for v in clues:
        r, c = v
        rd = {}
        for d in vdirs[v]:
            lst = []
            cur = v
            while True:
                if d not in vdirs[cur]:
                    break
                eid = edge_id(cur, d)
                lst.append(eid)
                cur = move(cur, d)
            rd[d] = lst
        rays[v] = rd

    # Constraint groups: for each clue and each allowed shape pattern,
    # we will enforce local degree pattern and exact length sum using contiguous active prefixes.
    clue_patterns = {}
    for v, (kind, k) in clues.items():
        allowed = []
        ds = vdirs[v]
        if kind == 'W':
            # straight through: U+D or L+R
            if 'U' in ds and 'D' in ds:
                allowed.append(('UD', ('U', 'D')))
            if 'L' in ds and 'R' in ds:
                allowed.append(('LR', ('L', 'R')))
        else:
            # turn: any perpendicular pair
            for a in ds:
                for b in ds:
                    if a < b and AXIS[a] != AXIS[b]:
                        allowed.append((a + b, (a, b)))

        patt_infos = []
        for name, pair in allowed:
            d1, d2 = pair
            patt_infos.append({
                'name': name,
                'dirs': pair,
                'ray1': rays[v][d1],
                'ray2': rays[v][d2],
                'sum': k,
                'kind': kind,
            })
        clue_patterns[v] = patt_infos

    # State.
    edge_state = [-1] * m  # -1 unknown, 0 off, 1 on

    # For each vertex, incident eids by dir.
    inc = {}
    for v in vertices:
        dct = {}
        for d in vdirs[v]:
            dct[d] = edge_id(v, d)
        inc[v] = dct

    # DSU over active edges endpoints for anti-small-cycle pruning.
    parent = list(range(len(vertices)))
    rank = [0] * len(vertices)
    vid = {v: i for i, v in enumerate(vertices)}

    def dsu_find(par, x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    def dsu_union(par, rk, a, b):
        ra, rb = dsu_find(par, a), dsu_find(par, b)
        if ra == rb:
            return False
        if rk[ra] < rk[rb]:
            ra, rb = rb, ra
        par[rb] = ra
        if rk[ra] == rk[rb]:
            rk[ra] += 1
        return True

    trail = []

    def assign_edge(eid, val):
        cur = edge_state[eid]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        trail.append(('edge', eid, cur))
        edge_state[eid] = val
        return True

    # Human-like local degree propagation.
    def propagate_vertex(v):
        eids = [inc[v][d] for d in vdirs[v]]
        vals = [edge_state[e] for e in eids]
        on = sum(x == 1 for x in vals)
        unk = sum(x == -1 for x in vals)
        need_deg2 = v in clues
        maxdeg = 2
        target_set = {2} if need_deg2 else {0, 2}

        if on > 2:
            return False
        if on + unk < min(target_set):
            return False
        if need_deg2:
            if on > 2 or on + unk < 2:
                return False
            if on == 2:
                for e in eids:
                    if edge_state[e] == -1 and not assign_edge(e, 0):
                        return False
            elif on + unk == 2:
                for e in eids:
                    if edge_state[e] == -1 and not assign_edge(e, 1):
                        return False
        else:
            # non-clue can be degree 0 or 2; degree 1 or 3 impossible at completion
            if unk == 0 and on not in (0, 2):
                return False
            if on == 2:
                for e in eids:
                    if edge_state[e] == -1 and not assign_edge(e, 0):
                        return False
            # if on==1 and only one unknown remains, that unknown must be on
            if on == 1 and unk == 1:
                for e in eids:
                    if edge_state[e] == -1 and not assign_edge(e, 1):
                        return False
            # if on==0 and only one unknown remains among total degree 3? cannot end with 1, but no direct forced move.
            if on == 3:
                return False
        return True

    # Exact clue propagation by enumerating feasible (pattern, len1, len2) possibilities
    # and intersecting edge requirements.
    def clue_feasible_assignments(v):
        infos = clue_patterns[v]
        feas = []
        for info in infos:
            r1 = info['ray1']
            r2 = info['ray2']
            k = info['sum']
            # lengths are positive because loop passes through clue in those two directions
            max1 = len(r1)
            max2 = len(r2)
            for l1 in range(1, max1 + 1):
                l2 = k - l1
                if l2 < 1 or l2 > max2:
                    continue

                ok = True
                req = {}
                # selected rays: first l edges on, remainder off
                for i, e in enumerate(r1):
                    want = 1 if i < l1 else 0
                    cur = edge_state[e]
                    if cur != -1 and cur != want:
                        ok = False
                        break
                    req[e] = want
                if not ok:
                    continue
                for i, e in enumerate(r2):
                    want = 1 if i < l2 else 0
                    cur = edge_state[e]
                    if cur != -1 and cur != want:
                        ok = False
                        break
                    if e in req and req[e] != want:
                        ok = False
                        break
                    req[e] = want
                if not ok:
                    continue

                # all other incident dirs at clue are off
                sel = set(info['dirs'])
                for d, e in inc[v].items():
                    want = 1 if d in sel else 0
                    cur = edge_state[e]
                    if cur != -1 and cur != want:
                        ok = False
                        break
                    req[e] = want
                if ok:
                    feas.append(req)
        return feas

    def propagate_clue(v):
        feas = clue_feasible_assignments(v)
        if not feas:
            return False
        # force common literals
        keys = set()
        for f in feas:
            keys.update(f.keys())
        for e in keys:
            vals = {f[e] for f in feas if e in f}
            if len(vals) == 1:
                val = next(iter(vals))
                if not assign_edge(e, val):
                    return False
        return True

    def rebuild_dsu():
        par = list(range(len(vertices)))
        rk = [0] * len(vertices)
        active_edges = [eid for eid, s in enumerate(edge_state) if s == 1]
        for eid in active_edges:
            a, b = edges[eid]
            dsu_union(par, rk, vid[a], vid[b])
        return par, rk

    def component_cycle_prune():
        # Forbid forming a closed component before all clue vertices are included and all active degree constraints complete.
        par, rk = rebuild_dsu()

        # degree counts
        deg_on = {v: 0 for v in vertices}
        deg_unk = {v: 0 for v in vertices}
        for eid, st in enumerate(edge_state):
            a, b = edges[eid]
            if st == 1:
                deg_on[a] += 1
                deg_on[b] += 1
            elif st == -1:
                deg_unk[a] += 1
                deg_unk[b] += 1

        comp_vertices = defaultdict(list)
        comp_edges = defaultdict(int)
        for v in vertices:
            comp_vertices[dsu_find(par, vid[v])].append(v)
        for eid, st in enumerate(edge_state):
            if st == 1:
                a, _ = edges[eid]
                comp_edges[dsu_find(par, vid[a])] += 1

        active_clues = set()
        for v in clues:
            if deg_on[v] > 0:
                active_clues.add(v)

        all_clues = set(clues)

        for root, verts in comp_vertices.items():
            ecount = comp_edges[root]
            act = [v for v in verts if deg_on[v] > 0]
            if not act:
                continue
            # A closed active component has every active vertex degree 2 and no unknown exits from active vertices.
            closed = True
            for v in verts:
                if deg_on[v] not in (0, 2):
                    closed = False
                    break
                if deg_on[v] == 2 and deg_unk[v] != 0:
                    closed = False
                    break
            if closed:
                comp_clues = {v for v in verts if v in clues}
                # If this is a cycle and not all clues are in it, prune.
                if ecount == len(act) and comp_clues != all_clues:
                    return False
        return True

    def propagate():
        changed = True
        while changed:
            start_trail_len = len(trail)
            # vertex propagation
            for v in vertices:
                if not propagate_vertex(v):
                    return False
            # clue propagation
            for v in clues:
                if not propagate_clue(v):
                    return False
            # re-run vertices after clue forcing
            for v in vertices:
                if not propagate_vertex(v):
                    return False
            if not component_cycle_prune():
                return False
            changed = len(trail) != start_trail_len
        return True

    def snapshot():
        return len(trail)

    def rollback(snap):
        while len(trail) > snap:
            typ, eid, prev = trail.pop()
            if typ == 'edge':
                edge_state[eid] = prev

    def is_solved():
        if any(s == -1 for s in edge_state):
            return False
        deg = {v: 0 for v in vertices}
        for eid, st in enumerate(edge_state):
            if st == 1:
                a, b = edges[eid]
                deg[a] += 1
                deg[b] += 1
        # every clue degree 2, every non-clue 0 or 2
        for v in vertices:
            if v in clues:
                if deg[v] != 2:
                    return False
            else:
                if deg[v] not in (0, 2):
                    return False
        # single cycle containing all active edges and all clues
        active_vs = [v for v in vertices if deg[v] > 0]
        if not active_vs:
            return False
        seen = set()
        stack = [active_vs[0]]
        adj = defaultdict(list)
        for eid, st in enumerate(edge_state):
            if st == 1:
                a, b = edges[eid]
                adj[a].append(b)
                adj[b].append(a)
        while stack:
            v = stack.pop()
            if v in seen:
                continue
            seen.add(v)
            stack.extend(adj[v])
        if set(active_vs) != seen:
            return False
        if not set(clues).issubset(seen):
            return False
        return True

    def extract_loop():
        adj = defaultdict(list)
        for eid, st in enumerate(edge_state):
            if st == 1:
                a, b = edges[eid]
                adj[a].append(b)
                adj[b].append(a)
        start = min(adj)
        loop = [start]
        prev = None
        cur = start
        while True:
            nxts = adj[cur]
            if prev is None:
                nxt = min(nxts)
            else:
                nxt = nxts[0] if nxts[0] != prev else nxts[1]
            loop.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        return loop

    def score_edge(eid):
        a, b = edges[eid]
        score = 0
        if a in clues:
            score += 10
        if b in clues:
            score += 10
        # Prefer edges involved in clue rays
        for v in clues:
            for d in rays[v]:
                if eid in rays[v][d]:
                    score += 1
        return -score

    def choose_branch():
        # First branch on clue with minimum feasible assignments >1
        best = None
        best_feas = None
        for v in clues:
            feas = clue_feasible_assignments(v)
            if len(feas) > 1:
                if best is None or len(feas) < len(best_feas):
                    best = ('clue', v)
                    best_feas = feas
        if best is not None:
            # Convert each feasible assignment to delta decisions only
            options = []
            for f in best_feas:
                delta = [(e, val) for e, val in f.items() if edge_state[e] == -1]
                options.append(delta)
            options.sort(key=len)
            return best, options

        # Else branch on most constrained edge
        cands = [eid for eid, s in enumerate(edge_state) if s == -1]
        if not cands:
            return None, None
        cands.sort(key=score_edge)
        eid = cands[0]
        return ('edge', eid), [[(eid, 1)], [(eid, 0)]]

    def search():
        if not propagate():
            return None
        if is_solved():
            return extract_loop()
        choice, options = choose_branch()
        if choice is None:
            return None
        for delta in options:
            snap = snapshot()
            ok = True
            for e, val in delta:
                if not assign_edge(e, val):
                    ok = False
                    break
            if ok:
                res = search()
                if res is not None:
                    return res
            rollback(snap)
        return None

    res = search()
    if res is None:
        return "No Solution"
    return str(res)


