# Star Battle 1-star solver with strong propagation and limited search.
# The solver is generalized for NxN grids with exactly one star in every row,
# column, and region, and stars may not touch orthogonally/diagonally.

from collections import defaultdict, deque
import ast


def build_structures(region_grid):
    n = len(region_grid)
    cells = [(r, c) for r in range(n) for c in range(n)]

    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            region_cells[region_grid[r][c]].append((r, c))

    rows = {r: [(r, c) for c in range(n)] for r in range(n)}
    cols = {c: [(r, c) for r in range(n)] for c in range(n)}
    regions = dict(region_cells)

    groups = []
    group_names = []
    for r in range(n):
        groups.append(rows[r])
        group_names.append(("row", r))
    for c in range(n):
        groups.append(cols[c])
        group_names.append(("col", c))
    for rid in sorted(regions):
        groups.append(regions[rid])
        group_names.append(("region", rid))

    memberships = {cell: [] for cell in cells}
    for gi, group in enumerate(groups):
        for cell in group:
            memberships[cell].append(gi)

    neighbors = {}
    for r in range(n):
        for c in range(n):
            s = set()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        s.add((rr, cc))
            neighbors[(r, c)] = s

    return {
        "n": n,
        "cells": cells,
        "rows": rows,
        "cols": cols,
        "regions": regions,
        "groups": groups,
        "group_names": group_names,
        "memberships": memberships,
        "neighbors": neighbors,
    }


def initial_state(struct):
    domains = {cell: 1 for cell in struct["cells"]}  # bit 1 = can be empty, bit 2 = can be star; start as 3
    for cell in domains:
        domains[cell] = 3
    return domains


def has_star(bit):
    return (bit & 2) != 0


def has_empty(bit):
    return (bit & 1) != 0


def is_fixed_star(bit):
    return bit == 2


def is_fixed_empty(bit):
    return bit == 1


def set_star(domains, cell, queue):
    bit = domains[cell]
    if bit == 2:
        return True
    if bit == 1:
        return False
    domains[cell] = 2
    queue.append(cell)
    return True


def set_empty(domains, cell, queue):
    bit = domains[cell]
    if bit == 1:
        return True
    if bit == 2:
        return False
    domains[cell] = 1
    queue.append(cell)
    return True


def group_status(domains, group):
    star_fixed = 0
    can_star = []
    for cell in group:
        bit = domains[cell]
        if bit == 2:
            star_fixed += 1
        elif bit == 3:
            can_star.append(cell)
    return star_fixed, can_star


def propagate_basic(domains, struct):
    queue = deque(struct["cells"])

    while queue:
        changed_cell = queue.popleft()

        # If a cell is fixed star, all touching neighbors must be empty
        if domains[changed_cell] == 2:
            for nb in struct["neighbors"][changed_cell]:
                if not set_empty(domains, nb, queue):
                    return False

        # Every row/col/region has exactly one star
        for gi in struct["memberships"][changed_cell]:
            group = struct["groups"][gi]
            star_fixed, can_star = group_status(domains, group)

            if star_fixed > 1:
                return False
            if star_fixed == 0 and not can_star:
                return False

            if star_fixed == 1:
                # all other undecided cells in this group become empty
                for cell in can_star:
                    if not set_empty(domains, cell, queue):
                        return False
            else:
                # no fixed star yet; if only one candidate remains, it must be star
                if len(can_star) == 1:
                    if not set_star(domains, can_star[0], queue):
                        return False

    return True


def independent_subset_viability(cells, neighbors, domains):
    # Upper bound on how many non-touching stars can still be placed among candidate cells.
    # Greedy + forced isolation checks; cheap and effective.
    candidates = [c for c in cells if has_star(domains[c])]
    if not candidates:
        return 0

    candset = set(candidates)
    deg = {c: sum((nb in candset) for nb in neighbors[c]) for c in candidates}
    remaining = set(candidates)
    count = 0
    while remaining:
        c = min(remaining, key=lambda x: deg[x])
        count += 1
        removed = {c} | (neighbors[c] & remaining)
        for x in removed:
            remaining.discard(x)
    return count


def line_region_intersections(struct):
    # Precompute row/region and col/region intersections for human-style deductions.
    row_region = defaultdict(list)
    col_region = defaultdict(list)
    for rid, rcells in struct["regions"].items():
        for r in range(struct["n"]):
            inter = [cell for cell in rcells if cell[0] == r]
            if inter:
                row_region[(r, rid)] = inter
        for c in range(struct["n"]):
            inter = [cell for cell in rcells if cell[1] == c]
            if inter:
                col_region[(c, rid)] = inter
    return row_region, col_region


def propagate_human(domains, struct):
    row_region, col_region = line_region_intersections(struct)
    n = struct["n"]

    changed = True
    while changed:
        changed = False

        # First maintain core constraints.
        if not propagate_basic(domains, struct):
            return False

        # 1) If all star candidates of a region lie in a single row/column,
        # then that row/column cannot place its star outside that region cells.
        for rid, rcells in struct["regions"].items():
            cand = [cell for cell in rcells if has_star(domains[cell])]
            if not cand:
                return False
            rows = {r for r, _ in cand}
            cols = {c for _, c in cand}

            if len(rows) == 1:
                r = next(iter(rows))
                allowed = set(cand)
                for cell in struct["rows"][r]:
                    if struct["data"][cell[0]][cell[1]] != rid and has_star(domains[cell]):
                        if not set_empty(domains, cell, deque()):
                            return False
                        changed = True

            if len(cols) == 1:
                c = next(iter(cols))
                allowed = set(cand)
                for cell in struct["cols"][c]:
                    if struct["data"][cell[0]][cell[1]] != rid and has_star(domains[cell]):
                        if not set_empty(domains, cell, deque()):
                            return False
                        changed = True

        if not propagate_basic(domains, struct):
            return False

        # 2) Pairwise adjacency elimination within groups:
        # if a group's remaining candidates form touching conflicts,
        # and a cell is incompatible with all other candidates, force it when needed.
        for gi, group in enumerate(struct["groups"]):
            star_fixed, can_star = group_status(domains, group)
            if star_fixed == 1:
                continue
            if star_fixed > 1 or (star_fixed == 0 and not can_star):
                return False

            # Viability: there must exist at least one candidate not already forbidden by a fixed star adjacency.
            viable = []
            for cell in can_star:
                ok = True
                for nb in struct["neighbors"][cell]:
                    if domains[nb] == 2:
                        ok = False
                        break
                if ok:
                    viable.append(cell)
            if not viable:
                return False
            if len(viable) == 1:
                if not set_star(domains, viable[0], deque()):
                    return False
                changed = True

        if not propagate_basic(domains, struct):
            return False

        # 3) Hall-like check on subsets of rows against available columns/regions via candidates.
        # Lightweight contiguous-window style human deduction.
        # For each pair/triple of rows, available star cells must cover enough distinct columns and regions.
        row_candidates = {r: [cell for cell in struct["rows"][r] if has_star(domains[cell])] for r in range(n)}
        for start in range(n):
            cols_union = set()
            regs_union = set()
            max_pick = 0
            for end in range(start, n):
                r = end
                if not row_candidates[r]:
                    return False
                max_pick += 1
                for cell in row_candidates[r]:
                    cols_union.add(cell[1])
                    regs_union.add(struct["data"][cell[0]][cell[1]])
                if len(cols_union) < max_pick or len(regs_union) < max_pick:
                    return False

        # 4) Region capacity under non-touching restriction.
        # Even if a region has many candidates, if they mutually touch too much, ensure at least one star feasible.
        for rid, rcells in struct["regions"].items():
            fixed = sum(1 for cell in rcells if domains[cell] == 2)
            if fixed > 1:
                return False
            if fixed == 0:
                cap = independent_subset_viability(rcells, struct["neighbors"], domains)
                if cap < 1:
                    return False

        # 5) Column analog of Hall-like check.
        col_candidates = {c: [cell for cell in struct["cols"][c] if has_star(domains[cell])] for c in range(n)}
        for start in range(n):
            rows_union = set()
            regs_union = set()
            max_pick = 0
            for end in range(start, n):
                c = end
                if not col_candidates[c]:
                    return False
                max_pick += 1
                for cell in col_candidates[c]:
                    rows_union.add(cell[0])
                    regs_union.add(struct["data"][cell[0]][cell[1]])
                if len(rows_union) < max_pick or len(regs_union) < max_pick:
                    return False

    return True


def solved(domains, struct):
    for group in struct["groups"]:
        stars = sum(1 for cell in group if domains[cell] == 2)
        if stars != 1:
            return False
    return all(domains[cell] in (1, 2) for cell in struct["cells"])


def choose_branch_cell(domains, struct):
    # Human-like: branch on the most constrained row/col/region, then the most constrained cell.
    best_group = None
    best_candidates = None

    for gi, group in enumerate(struct["groups"]):
        star_fixed, can_star = group_status(domains, group)
        if star_fixed == 0 and 1 < len(can_star):
            if best_candidates is None or len(can_star) < len(best_candidates):
                best_group = gi
                best_candidates = can_star

    if best_candidates is None:
        # fallback
        undecided = [cell for cell in struct["cells"] if domains[cell] == 3]
        if not undecided:
            return None
        return min(
            undecided,
            key=lambda cell: (
                sum(1 for nb in struct["neighbors"][cell] if has_star(domains[nb])),
                sum(1 for gi in struct["memberships"][cell] if group_status(domains, struct["groups"][gi])[0] == 0),
            ),
        )

    # Within the chosen group, pick the cell with highest impact.
    return max(
        best_candidates,
        key=lambda cell: (
            len([nb for nb in struct["neighbors"][cell] if has_star(domains[nb])]),
            sum(1 for gi in struct["memberships"][cell] if group_status(domains, struct["groups"][gi])[0] == 0),
        ),
    )


def search(domains, struct, depth=0, depth_limit=200):
    if depth > depth_limit:
        return None

    if not propagate_human(domains, struct):
        return None

    if solved(domains, struct):
        return domains

    cell = choose_branch_cell(domains, struct)
    if cell is None:
        return domains if solved(domains, struct) else None

    # Try star first; strong propagation usually resolves quickly.
    for force_star in (True, False):
        new_domains = dict(domains)
        q = deque()
        ok = set_star(new_domains, cell, q) if force_star else set_empty(new_domains, cell, q)
        if not ok:
            continue
        result = search(new_domains, struct, depth + 1, depth_limit)
        if result is not None:
            return result

    return None


def format_answer(domains, n):
    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('S' if domains[(r, c)] == 2 else None)
        grid.append(row)
    return str(grid)


def solve(observation):
    region_grid = observation["data"]
    if not region_grid or any(len(row) != len(region_grid) for row in region_grid):
        return "No Solution"

    struct = build_structures(region_grid)
    struct["data"] = region_grid
    domains = initial_state(struct)
    result = search(domains, struct)
    if result is None:
        return "No Solution"
    return format_answer(result, struct["n"])


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'W3', None, None, None, None, None], [None, None, 'B3', None, None, None, None, None], [None, None, None, None, 'B2', None, 'W3', None], [None, 'W4', None, None, None, None, None, None], [None, None, None, None, 'W2', 'B3', None, 'W6'], [None, None, None, None, 'B5', None, 'W2', None], ['B7', None, 'B2', None, None, None, None, None], [None, None, None, None, None, None, None, None]]}

from collections import deque, defaultdict

# Slitherlink-like loop with numbered pearl constraints:
# - White clue: path goes straight through clue cell.
# - Black clue: path turns at clue cell.
# - Number k: sum of the maximal straight run lengths on both sides through that clue cell.
#
# We model cell-centers as graph vertices and potential loop segments between orthogonally adjacent
# clue cells / empty cells. Degree at every used cell is 2; unused cells degree 0. Every clue cell
# must be used. Final used edges form a single simple cycle.
#
# Human-like solving is implemented via:
# 1) local degree propagation
# 2) white/black turn/straight enforcement
# 3) numbered run-length feasibility pruning using directional ray bounds
# 4) component / premature small-loop prevention
# 5) branch on most-constrained edge or clue pattern only when deduction stalls

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0:
        return "No Solution"
    m = len(data[0])

    # Cells are (r,c). Potential edges between orthogonally adjacent cells.
    edge_list = []
    edge_index = {}
    nbr_edges = [[None] * 4 for _ in range(n * m)]
    clue_cells = []
    clue_info = {}

    def vid(r, c):
        return r * m + c

    def inside(r, c):
        return 0 <= r < n and 0 <= c < m

    for r in range(n):
        for c in range(m):
            tok = data[r][c]
            if tok is not None:
                clue_cells.append((r, c))
                clue_info[(r, c)] = (tok[0], int(tok[1:]))

    for r in range(n):
        for c in range(m):
            a = vid(r, c)
            for d, (dr, dc) in enumerate(DIRS):
                nr, nc = r + dr, c + dc
                if inside(nr, nc) and a < vid(nr, nc):
                    ei = len(edge_list)
                    edge_list.append((r, c, nr, nc))
                    edge_index[(a, vid(nr, nc))] = ei
                    edge_index[(vid(nr, nc), a)] = ei
    for ei, (r1, c1, r2, c2) in enumerate(edge_list):
        a = vid(r1, c1)
        b = vid(r2, c2)
        for d, (dr, dc) in enumerate(DIRS):
            if r1 + dr == r2 and c1 + dc == c2:
                nbr_edges[a][d] = ei
            if r2 + dr == r1 and c2 + dc == c1:
                nbr_edges[b][d] = ei

    E = len(edge_list)
    V = n * m

    # edge_state: -1 unknown, 0 absent, 1 present
    edge_state = [-1] * E
    deg_present = [0] * V
    deg_forbidden = [0] * V  # count of absent incident edges
    used_required = [False] * V
    for r, c in clue_cells:
        used_required[vid(r, c)] = True

    # DSU over present edges for loop detection / connectivity heuristics.
    parent = list(range(V))
    size = [1] * V

    # rollback stacks
    changes = []

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            changes.append(("noop_union",))
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        changes.append(("union", rb, parent[rb], ra, size[ra]))
        parent[rb] = ra
        size[ra] += size[rb]

    def rollback(mark):
        while len(changes) > mark:
            rec = changes.pop()
            t = rec[0]
            if t == "edge":
                ei, old = rec[1], rec[2]
                edge_state[ei] = old
            elif t == "deg":
                v, dp, df = rec[1], rec[2], rec[3]
                deg_present[v] = dp
                deg_forbidden[v] = df
            elif t == "union":
                rb, oldp, ra, oldsize = rec[1], rec[2], rec[3], rec[4]
                parent[rb] = oldp
                size[ra] = oldsize
            elif t == "noop_union":
                pass

    def incident_states(v):
        vals = []
        for ei in nbr_edges[v]:
            if ei is not None:
                vals.append((ei, edge_state[ei]))
        return vals

    def set_edge(ei, val, queue):
        cur = edge_state[ei]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        changes.append(("edge", ei, cur))
        edge_state[ei] = val
        r1, c1, r2, c2 = edge_list[ei]
        a = vid(r1, c1)
        b = vid(r2, c2)
        changes.append(("deg", a, deg_present[a], deg_forbidden[a]))
        changes.append(("deg", b, deg_present[b], deg_forbidden[b]))
        if val == 1:
            deg_present[a] += 1
            deg_present[b] += 1
            union(a, b)
        else:
            deg_forbidden[a] += 1
            deg_forbidden[b] += 1
        queue.append(a)
        queue.append(b)
        return True

    def force_vertex(v, queue):
        inc = incident_states(v)
        p = sum(1 for _, s in inc if s == 1)
        u = [ei for ei, s in inc if s == -1]
        total = len(inc)

        # Every used vertex must have degree 2; every unused has degree 0 or 2.
        if p > 2:
            return False
        if p == 2:
            for ei in u:
                if not set_edge(ei, 0, queue):
                    return False
        if used_required[v]:
            if p + len(u) < 2:
                return False
            if p == 1 and len(u) == 1:
                if not set_edge(u[0], 1, queue):
                    return False
            if p == 0 and len(u) == 2:
                for ei in u:
                    if not set_edge(ei, 1, queue):
                        return False
        else:
            if p == 1 and len(u) == 0:
                return False
            if p == 1 and len(u) == 1:
                if not set_edge(u[0], 1, queue):
                    return False
            if p == 0 and len(u) == 1:
                if not set_edge(u[0], 0, queue):
                    return False

        # If impossible to end at 0 or 2, fail.
        p = sum(1 for _, s in incident_states(v) if s == 1)
        ucnt = sum(1 for _, s in incident_states(v) if s == -1)
        possible = set()
        for final_deg in (0, 2):
            if used_required[v] and final_deg == 0:
                continue
            if p <= final_deg <= p + ucnt:
                possible.add(final_deg)
        if not possible:
            return False
        return True

    def dir_edge(v, d):
        return nbr_edges[v][d]

    def directional_run_bounds(r, c, orient):
        # orient 0 = vertical (up/down), 1 = horizontal (left/right)
        # returns per side: (min,max) where side lengths are maximal straight extensions from clue
        # assuming clue is used in this orientation. Human-style conservative feasibility:
        # min counts already-forced present edges in that direction chain before first undecided/blocked;
        # max counts extend through all cells that can still be straight-compatible.
        if orient == 0:
            sides = [0, 2]
        else:
            sides = [1, 3]

        mins = []
        maxs = []

        for d in sides:
            length_min = 0
            length_max = 0
            cr, cc = r, c
            while True:
                ei = nbr_edges[vid(cr, cc)][d]
                if ei is None:
                    break
                s = edge_state[ei]
                nr, nc = cr + DIRS[d][0], cc + DIRS[d][1]
                if s == 0:
                    break
                # For max, next cell must be able to continue straight (cannot be black forced turn in same orientation)
                length_max += 1
                if s == 1:
                    length_min += 1
                celltok = data[nr][nc]
                if celltok is not None:
                    t, k = clue_info[(nr, nc)]
                    # Entering neighboring clue while continuing straight through it requires:
                    # white -> same orientation okay
                    # black -> same orientation impossible
                    if t == 'B':
                        break
                    # white can continue straight, but if vertical orientation and white forced horizontal by local edge states,
                    # max feasibility may stop later by separate checks.
                cr, cc = nr, nc

                # If there is a present side edge forcing a turn here, straight cannot continue for sure.
                v2 = vid(cr, cc)
                if orient == 0:
                    perp = [1, 3]
                    straight_dirs = [0, 2]
                else:
                    perp = [0, 2]
                    straight_dirs = [1, 3]
                if any((nbr_edges[v2][pd] is not None and edge_state[nbr_edges[v2][pd]] == 1) for pd in perp):
                    break
                # If both straight continuations impossible at this cell, stop.
                if all((nbr_edges[v2][sd] is None or edge_state[nbr_edges[v2][sd]] == 0) for sd in straight_dirs):
                    break
            mins.append(length_min)
            maxs.append(length_max)
        return mins[0], maxs[0], mins[1], maxs[1]

    def enforce_clue(r, c, queue):
        v = vid(r, c)
        tok = data[r][c]
        t, k = tok[0], int(tok[1:])

        inc = [edge_state[ei] if ei is not None else 0 for ei in nbr_edges[v]]

        # Clue cell must be used.
        if not force_vertex(v, queue):
            return False

        # Possible local patterns.
        patterns = []
        # pattern represented as tuple of dirs used
        for d1, d2 in ((0, 2), (1, 3), (0, 1), (1, 2), (2, 3), (3, 0)):
            # valid geometry
            straight = (d1 + 2) % 4 == d2 or (d2 + 2) % 4 == d1
            if t == 'W' and not straight:
                continue
            if t == 'B' and straight:
                continue
            dirs = {d1, d2}
            ok = True
            for d in range(4):
                ei = nbr_edges[v][d]
                if ei is None:
                    if d in dirs:
                        ok = False
                    continue
                s = edge_state[ei]
                if d in dirs and s == 0:
                    ok = False
                if d not in dirs and s == 1:
                    ok = False
            if not ok:
                continue

            orient = 0 if dirs == {0, 2} else 1 if dirs == {1, 3} else None
            if t == 'W':
                a, A, b, B = directional_run_bounds(r, c, orient)
                if a + b <= k <= A + B:
                    patterns.append((dirs, orient))
            else:
                # black clue turns; lengths are measured along each incident arm.
                sides = list(dirs)
                mins = []
                maxs = []
                for d in sides:
                    length_min = 0
                    length_max = 0
                    cr, cc = r, c
                    while True:
                        ei = nbr_edges[vid(cr, cc)][d]
                        if ei is None:
                            break
                        s = edge_state[ei]
                        if s == 0:
                            break
                        nr, nc = cr + DIRS[d][0], cc + DIRS[d][1]
                        length_max += 1
                        if s == 1:
                            length_min += 1
                        celltok = data[nr][nc]
                        if celltok is not None:
                            tt, kk = clue_info[(nr, nc)]
                            # continuing in same direction through black impossible
                            if tt == 'B':
                                break
                        cr, cc = nr, nc
                        v2 = vid(cr, cc)
                        perp = [d]
                        if nbr_edges[v2][d] is None or edge_state[nbr_edges[v2][d]] == 0:
                            break
                    mins.append(length_min)
                    maxs.append(length_max)
                if mins[0] + mins[1] <= k <= maxs[0] + maxs[1]:
                    patterns.append((dirs, None))

        if not patterns:
            return False

        # Intersection/union reasoning over possible patterns.
        must_use = set.intersection(*(set(dirs) for dirs, _ in patterns))
        may_use = set.union(*(set(dirs) for dirs, _ in patterns))
        for d in range(4):
            ei = nbr_edges[v][d]
            if ei is None:
                continue
            if d in must_use:
                if not set_edge(ei, 1, queue):
                    return False
            if d not in may_use:
                if not set_edge(ei, 0, queue):
                    return False

        # Additional exact sum forcing for white clues when orientation unique.
        if t == 'W':
            orients = {orient for _, orient in patterns}
            if len(orients) == 1:
                orient = next(iter(orients))
                if orient == 0:
                    dirs = [0, 2]
                else:
                    dirs = [1, 3]
                min1, max1, min2, max2 = directional_run_bounds(r, c, orient)
                target = k
                # If one side max determines other side min, propagate nearest edge impossibilities weakly.
                # Stronger propagation is achieved by branch + local checking.
                if min1 + max2 == target:
                    pass
                if max1 + min2 == target:
                    pass
        return True

    def prevent_premature_cycle():
        # If there is a present-edge component where every currently used vertex has degree 2,
        # and not all required clue vertices are included, reject.
        comp_used = defaultdict(list)
        used_vertices = set()
        for ei, s in enumerate(edge_state):
            if s == 1:
                r1, c1, r2, c2 = edge_list[ei]
                a, b = vid(r1, c1), vid(r2, c2)
                used_vertices.add(a)
                used_vertices.add(b)
        for v in used_vertices:
            comp_used[find(v)].append(v)
        required_set = {vid(r, c) for r, c in clue_cells}
        for comp, verts in comp_used.items():
            if all(deg_present[v] == 2 for v in verts):
                comp_set = set(verts)
                if not required_set.issubset(comp_set):
                    return False
                # Also if there are any other used vertices outside, invalid multiple loops.
                if len(comp_set) != len(used_vertices):
                    return False
        return True

    def propagate():
        queue = deque()
        for v in range(V):
            queue.append(v)
        for r, c in clue_cells:
            queue.append(vid(r, c))

        inq = [False] * V
        while queue:
            v = queue.popleft()
            if inq[v]:
                inq[v] = False
            if not force_vertex(v, queue):
                return False
            r, c = divmod(v, m)
            if data[r][c] is not None:
                if not enforce_clue(r, c, queue):
                    return False
            if not prevent_premature_cycle():
                return False
        return True

    def final_check():
        # All edges decided enough and form one single cycle through all clues.
        # enforce all vertex degrees valid
        used_vertices = set()
        for v in range(V):
            p = deg_present[v]
            if used_required[v]:
                if p != 2:
                    return False
            else:
                if p not in (0, 2):
                    return False
            if p == 2:
                used_vertices.add(v)
        if not used_vertices:
            return False
        # all clues used
        for r, c in clue_cells:
            if vid(r, c) not in used_vertices:
                return False
        roots = {find(v) for v in used_vertices}
        if len(roots) != 1:
            return False

        # verify clue run-lengths exactly
        for r, c in clue_cells:
            v = vid(r, c)
            dirs = [d for d in range(4) if nbr_edges[v][d] is not None and edge_state[nbr_edges[v][d]] == 1]
            if len(dirs) != 2:
                return False
            tok = data[r][c]
            t, k = tok[0], int(tok[1:])
            straight = (dirs[0] + 2) % 4 == dirs[1]
            if t == 'W' and not straight:
                return False
            if t == 'B' and straight:
                return False
            total = 0
            for d in dirs:
                cr, cc = r, c
                while True:
                    ei = nbr_edges[vid(cr, cc)][d]
                    if ei is None or edge_state[ei] != 1:
                        break
                    total += 1
                    cr, cc = cr + DIRS[d][0], cc + DIRS[d][1]
                    nv = vid(cr, cc)
                    next_ei = nbr_edges[nv][d]
                    if next_ei is None or edge_state[next_ei] != 1:
                        break
            if total != k:
                return False
        return True

    def choose_branch():
        # Prefer clue with fewest feasible patterns > 1.
        best = None
        best_patterns = None
        for r, c in clue_cells:
            v = vid(r, c)
            if deg_present[v] == 2 and all(edge_state[ei] != -1 for ei in nbr_edges[v] if ei is not None):
                continue
            tok = data[r][c]
            t = tok[0]
            patterns = []
            for d1, d2 in ((0, 2), (1, 3), (0, 1), (1, 2), (2, 3), (3, 0)):
                straight = (d1 + 2) % 4 == d2 or (d2 + 2) % 4 == d1
                if t == 'W' and not straight:
                    continue
                if t == 'B' and straight:
                    continue
                dirs = {d1, d2}
                ok = True
                for d in range(4):
                    ei = nbr_edges[v][d]
                    if ei is None:
                        if d in dirs:
                            ok = False
                        continue
                    s = edge_state[ei]
                    if d in dirs and s == 0:
                        ok = False
                    if d not in dirs and s == 1:
                        ok = False
                if ok:
                    patterns.append(tuple(sorted(dirs)))
            if 1 < len(patterns) < (10 if best_patterns is None else len(best_patterns)):
                best = (r, c)
                best_patterns = patterns
        if best is not None:
            return ("clue", best, best_patterns)

        # Else choose edge adjacent to clues / constrained vertices.
        best_ei = None
        best_score = -1
        for ei, s in enumerate(edge_state):
            if s != -1:
                continue
            r1, c1, r2, c2 = edge_list[ei]
            a, b = vid(r1, c1), vid(r2, c2)
            score = 0
            if data[r1][c1] is not None:
                score += 3
            if data[r2][c2] is not None:
                score += 3
            score += deg_present[a] + deg_present[b]
            if score > best_score:
                best_score = score
                best_ei = ei
        if best_ei is not None:
            return ("edge", best_ei)
        return None

    def extract_cycle_path():
        # Convert used cell-edge cycle into dot-coordinate polygonal path around cells is not required here;
        # but problem expects ordered closed loop path as list of dot coordinates.
        # We interpret loop on dot grid lines surrounding traversed cells is not directly the same graph.
        # However the supplied clues are on dots in the image-aligned grid, so the intended model is
        # actually dot-to-dot path through clue positions. Our state graph already uses those positions.
        # Therefore return ordered vertex cycle through present edges.
        used = defaultdict(list)
        start = None
        for ei, s in enumerate(edge_state):
            if s == 1:
                r1, c1, r2, c2 = edge_list[ei]
                a = (r1, c1)
                b = (r2, c2)
                used[a].append(b)
                used[b].append(a)
                if start is None:
                    start = a
        if start is None:
            return []
        path = [start]
        prev = None
        cur = start
        while True:
            nxts = used[cur]
            if prev is None:
                nxt = nxts[0]
            else:
                nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > E + 5:
                break
        return path

    def search():
        if not propagate():
            return None
        if all(s != -1 for s in edge_state):
            if final_check():
                return extract_cycle_path()
            return None

        branch = choose_branch()
        if branch is None:
            return None

        if branch[0] == "clue":
            _, (r, c), patterns = branch
            v = vid(r, c)
            for pat in patterns:
                mark = len(changes)
                q = deque()
                dirs = set(pat)
                ok = True
                for d in range(4):
                    ei = nbr_edges[v][d]
                    if ei is None:
                        if d in dirs:
                            ok = False
                            break
                        continue
                    if not set_edge(ei, 1 if d in dirs else 0, q):
                        ok = False
                        break
                if ok:
                    ans = search()
                    if ans is not None:
                        return ans
                rollback(mark)
            return None
        else:
            _, ei = branch
            # Prefer present first if it connects clue structures, else absent first.
            for val in (1, 0):
                mark = len(changes)
                q = deque()
                if set_edge(ei, val, q):
                    ans = search()
                    if ans is not None:
                        return ans
                rollback(mark)
            return None

    ans = search()
    if ans is None:
        return "No Solution"
    return str(ans)


