# Solver for:
# - each region contains exactly 2 shaded cells
# - shaded cells form dominoes (every shaded cell has exactly one orthogonally adjacent shaded partner)
# - different dominoes cannot touch orthogonally
# Dominoes may cross region borders.
#
# Approach:
# Represent each possible domino placement as a variable.
# Selecting dominoes must satisfy:
# 1) every region is covered by exactly 2 selected cell-incidences
# 2) selected dominoes are pairwise non-touching orthogonally unless they are the same domino cells
#
# Human-like deduction is mirrored via repeated propagation:
# - region lower/upper bounds
# - forced/forbidden dominoes from exact-cover style counting
# - singleton support for cells/regions
# Then branch on the most constrained region/choice.

from collections import defaultdict
import ast

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0

    cells = [(r, c) for r in range(n) for c in range(m)]

    def inb(r, c):
        return 0 <= r < n and 0 <= c < m

    # Regions
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))
    regions = list(region_cells.keys())

    # Orthogonal adjacency
    orth = {}
    for r, c in cells:
        ns = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if inb(rr, cc):
                ns.append((rr, cc))
        orth[(r, c)] = ns

    # Enumerate all possible dominoes
    dominoes = []
    domino_index = {}
    cell_to_dominoes = defaultdict(list)

    for r in range(n):
        for c in range(m):
            if c + 1 < m:
                a = (r, c)
                b = (r, c + 1)
                idx = len(dominoes)
                dominoes.append((a, b))
                domino_index[(a, b)] = idx
                domino_index[(b, a)] = idx
                cell_to_dominoes[a].append(idx)
                cell_to_dominoes[b].append(idx)
            if r + 1 < n:
                a = (r, c)
                b = (r + 1, c)
                idx = len(dominoes)
                dominoes.append((a, b))
                domino_index[(a, b)] = idx
                domino_index[(b, a)] = idx
                cell_to_dominoes[a].append(idx)
                cell_to_dominoes[b].append(idx)

    D = len(dominoes)

    # For each domino, compute conflicting dominoes:
    # - overlapping in a cell
    # - any orthogonal touching between cells of distinct dominoes
    dom_cells = [set(d) for d in dominoes]
    conflicts = [set() for _ in range(D)]

    for i in range(D):
        ai, bi = dominoes[i]
        cells_i = dom_cells[i]
        near_i = set()
        for x in cells_i:
            near_i.add(x)
            near_i.update(orth[x])
        for j in range(i + 1, D):
            cells_j = dom_cells[j]
            if cells_i & cells_j:
                conflicts[i].add(j)
                conflicts[j].add(i)
                continue
            bad = False
            for x in cells_i:
                for y in cells_j:
                    if y in orth[x]:
                        bad = True
                        break
                if bad:
                    break
            if bad:
                conflicts[i].add(j)
                conflicts[j].add(i)

    # Region incidence counts of each domino
    # A domino can contribute 0,1,2 cells to a region.
    region_dominoes = defaultdict(list)
    dom_region_count = [defaultdict(int) for _ in range(D)]
    for d, (a, b) in enumerate(dominoes):
        ra = grid[a[0]][a[1]]
        rb = grid[b[0]][b[1]]
        dom_region_count[d][ra] += 1
        dom_region_count[d][rb] += 1
        region_dominoes[ra].append(d)
        if rb != ra:
            region_dominoes[rb].append(d)

    region_dominoes = {r: sorted(set(ds)) for r, ds in region_dominoes.items()}

    # Cell support map by region for stronger propagation
    region_cell_support = {}
    for reg, rcells in region_cells.items():
        support = {cell: [] for cell in rcells}
        for d in region_dominoes[reg]:
            a, b = dominoes[d]
            if a in support:
                support[a].append(d)
            if b in support:
                support[b].append(d)
        region_cell_support[reg] = support

    UNK, YES, NO = 0, 1, -1

    def serialize_answer(state):
        out = [[None for _ in range(m)] for _ in range(n)]
        for d, st in enumerate(state):
            if st == YES:
                a, b = dominoes[d]
                out[a[0]][a[1]] = 'S'
                out[b[0]][b[1]] = 'S'
        return str(out)

    def clone_state(state):
        return state[:]

    def assign(state, d, val, queue):
        cur = state[d]
        if cur == val:
            return True
        if cur == -val:
            return False
        state[d] = val
        queue.append(d)
        return True

    def region_bounds(state, reg):
        lo = 0
        hi = 0
        for d in region_dominoes[reg]:
            cnt = dom_region_count[d].get(reg, 0)
            if state[d] == YES:
                lo += cnt
                hi += cnt
            elif state[d] == UNK:
                hi += cnt
        return lo, hi

    def propagate(state):
        queue = []

        # Initial impossible self-check from chosen dominoes
        changed = True
        while changed:
            changed = False

            # Process direct consequences of explicit assignments
            while queue:
                d = queue.pop()
                if state[d] == YES:
                    for e in conflicts[d]:
                        if not assign(state, e, NO, queue):
                            return False
                # NO has no direct local consequence here

            # Region bounds and exactness
            for reg in regions:
                lo, hi = region_bounds(state, reg)
                if lo > 2 or hi < 2:
                    return False

                # Forced/forbidden by slack
                need = 2 - lo
                avail = hi - lo

                # If no more room, all unknown contributing dominoes forbidden
                if need == 0:
                    for d in region_dominoes[reg]:
                        if state[d] == UNK and dom_region_count[d].get(reg, 0) > 0:
                            if not assign(state, d, NO, queue):
                                return False
                            changed = True

                # If every remaining contribution is needed, force all unknown contributors
                elif need == avail:
                    for d in region_dominoes[reg]:
                        if state[d] == UNK and dom_region_count[d].get(reg, 0) > 0:
                            if not assign(state, d, YES, queue):
                                return False
                            changed = True

                # Cell-level support reasoning inside region
                support = region_cell_support[reg]
                cell_possible = []
                forced_cells = 0
                for cell, ds in support.items():
                    possible = []
                    chosen_here = False
                    for d in ds:
                        if state[d] == YES:
                            chosen_here = True
                            possible = [d]
                            break
                        elif state[d] == UNK:
                            possible.append(d)
                    if chosen_here:
                        forced_cells += 1
                    elif not possible:
                        pass
                    cell_possible.append((cell, possible, chosen_here))

                if forced_cells > 2:
                    return False

                # Count cells that can still be shaded in the region
                can_be_shaded = forced_cells + sum(1 for _, poss, ch in cell_possible if (not ch and poss))
                if can_be_shaded < 2:
                    return False

                # If exactly k more cells must be shaded and only k candidate cells remain, force them
                remain_cells_needed = 2 - forced_cells
                candidate_cells = [(cell, poss) for cell, poss, ch in cell_possible if (not ch and poss)]
                if remain_cells_needed < 0:
                    return False
                if remain_cells_needed == 0:
                    # Any domino shading an unforced region cell is impossible
                    candidate_dominoes = set()
                    for _, poss in candidate_cells:
                        candidate_dominoes.update(poss)
                    for d in candidate_dominoes:
                        if state[d] == UNK and dom_region_count[d].get(reg, 0) > 0:
                            if not assign(state, d, NO, queue):
                                return False
                            changed = True
                elif len(candidate_cells) == remain_cells_needed:
                    # Every remaining candidate cell must be shaded: if a cell has only one support domino, force it
                    for _, poss in candidate_cells:
                        if len(poss) == 1:
                            if not assign(state, poss[0], YES, queue):
                                return False
                            changed = True

                # Support uniqueness by contribution count:
                # if region still needs x cells and some cell can be covered only by one domino, sometimes force.
                if lo < 2:
                    # For each candidate cell with singleton support, force that domino if cell is unavoidable.
                    # A cell is unavoidable when excluding it leaves fewer than needed cells.
                    total_candidate = len(candidate_cells)
                    for cell, poss in candidate_cells:
                        if len(poss) == 1 and total_candidate - 1 < remain_cells_needed:
                            if not assign(state, poss[0], YES, queue):
                                return False
                            changed = True

            # Process consequences from queue caused by region deductions
            while queue:
                d = queue.pop()
                if state[d] == YES:
                    for e in conflicts[d]:
                        if not assign(state, e, NO, queue):
                            return False
                    changed = True

            # Cell domination:
            # if a cell has exactly one possible domino and that cell's region still needs it critically,
            # region logic above often catches it, but do a stronger global consistency pass:
            for cell in cells:
                yes_dom = None
                poss = []
                for d in cell_to_dominoes[cell]:
                    if state[d] == YES:
                        yes_dom = d
                        break
                    if state[d] == UNK:
                        poss.append(d)
                if yes_dom is not None:
                    continue

                reg = grid[cell[0]][cell[1]]
                lo, hi = region_bounds(state, reg)
                forced_in_reg = lo
                if forced_in_reg == 2:
                    continue
                # If this cell is the only remaining candidate in its region for one of the missing spots, force its unique domino.
                support = region_cell_support[reg]
                rem_cells = 0
                this_possible = False
                for c2, ds2 in support.items():
                    chosen = False
                    local_poss = False
                    for d2 in ds2:
                        if state[d2] == YES:
                            chosen = True
                            break
                        if state[d2] == UNK:
                            local_poss = True
                    if chosen:
                        continue
                    if local_poss:
                        rem_cells += 1
                        if c2 == cell:
                            this_possible = True
                need_cells = 2 - lo
                if this_possible and rem_cells == need_cells and len(poss) == 1:
                    if not assign(state, poss[0], YES, queue):
                        return False
                    changed = True

        # Final consistency for selected dominoes
        for d in range(D):
            if state[d] == YES:
                for e in conflicts[d]:
                    if state[e] == YES:
                        return False

        return True

    def solved(state):
        for reg in regions:
            lo, hi = region_bounds(state, reg)
            if lo != 2 or hi != 2:
                return False
        return True

    def choose_branch(state):
        # Human-like choice: most constrained region first.
        best = None
        best_key = None

        for reg in regions:
            lo, hi = region_bounds(state, reg)
            if lo == hi == 2:
                continue
            unknown_ds = [d for d in region_dominoes[reg] if state[d] == UNK and dom_region_count[d].get(reg, 0) > 0]
            if not unknown_ds:
                continue

            # Prefer small domain and high urgency
            # domain patterns by contribution to region
            ones = sum(1 for d in unknown_ds if dom_region_count[d].get(reg, 0) == 1)
            twos = sum(1 for d in unknown_ds if dom_region_count[d].get(reg, 0) == 2)
            need = 2 - lo
            key = (len(unknown_ds), need, ones + twos, -twos)
            if best_key is None or key < best_key:
                best_key = key
                best = ("region", reg, unknown_ds)

        if best is not None:
            reg = best[1]
            ds = best[2]
            # Prefer dominoes contributing 2 to that region, then with many conflicts.
            ds = sorted(ds, key=lambda d: (-dom_region_count[d].get(reg, 0), -len(conflicts[d])))
            return ds[0]

        # Fallback: most conflicting unknown domino
        cands = [d for d in range(D) if state[d] == UNK]
        if not cands:
            return None
        cands.sort(key=lambda d: -len(conflicts[d]))
        return cands[0]

    def dfs(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        d = choose_branch(state)
        if d is None:
            return None

        # Try YES first; puzzle usually sparse enough and propagation is strong.
        for val in (YES, NO):
            nxt = clone_state(state)
            q = []
            if assign(nxt, d, val, q):
                # seed queue effects
                while q:
                    x = q.pop()
                    if nxt[x] == YES:
                        for e in conflicts[x]:
                            if not assign(nxt, e, NO, q):
                                break
                        else:
                            continue
                        break
                else:
                    res = dfs(nxt)
                    if res is not None:
                        return res
        return None

    state = [UNK] * D
    res = dfs(state)
    if res is None:
        return "No Solution"
    return serialize_answer(res)

if __name__ == "__main__":
    print(solve(OBSERVATION))

