from itertools import combinations

# General solver for the weighted black-cell puzzle.
# Human-style model:
# - Each row chooses a subset of columns whose column-weights sum to the row target.
# - Each column then receives the sum of row-weights from rows choosing that column.
# - Deduction is performed by pruning impossible row patterns from column bounds,
#   then optional branching on the most constrained row.

def subset_masks_by_sum(weights, target):
    n = len(weights)
    out = []

    def dfs(i, s, mask):
        if s == target:
            out.append(mask)
            return
        if s > target or i == n:
            return
        rem = 0
        for k in range(i, n):
            rem += weights[k]
        if s + rem < target:
            return
        dfs(i + 1, s, mask)
        w = weights[i]
        if s + w <= target:
            dfs(i + 1, s + w, mask | (1 << i))

    dfs(0, 0, 0)
    return out


def solve(observation):
    row_weights = list(range(1, len(observation['row_sum']) + 1))
    col_weights = list(range(1, len(observation['col_sum']) + 1))
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']

    R = len(row_targets)
    C = len(col_targets)

    # All feasible row patterns by exact weighted row sum.
    row_domains = []
    for r in range(R):
        masks = subset_masks_by_sum(col_weights, row_targets[r])
        if not masks:
            return "No Solution"
        row_domains.append(masks)

    full_col_total = sum(row_weights)

    def domain_column_bounds(domains):
        # For each column, compute min/max achievable accumulated row-weight
        # from current row domains.
        minv = [0] * C
        maxv = [0] * C
        for r, dom in enumerate(domains):
            rw = row_weights[r]
            all1 = (1 << C) - 1
            any1 = 0
            for m in dom:
                any1 |= m
                all1 &= m
            for c in range(C):
                bit = 1 << c
                if all1 & bit:
                    minv[c] += rw
                    maxv[c] += rw
                elif any1 & bit:
                    maxv[c] += rw
        return minv, maxv

    def feasible_suffix(rows_remaining):
        # Bitset DP of possible sums using row_weights for remaining rows.
        # Used per column with forced included/excluded row weights removed.
        possible = 1
        for r in rows_remaining:
            possible |= (possible << row_weights[r])
        return possible

    def bit_has(bits, x):
        return x >= 0 and ((bits >> x) & 1) != 0

    def prune(domains):
        changed = True
        while changed:
            changed = False

            # Global column bounds pruning loop.
            minc, maxc = domain_column_bounds(domains)
            for c in range(C):
                if col_targets[c] < minc[c] or col_targets[c] > maxc[c]:
                    return None

            # Row-domain filtering using per-column exact residual feasibility.
            for r in range(R):
                old_dom = domains[r]
                if len(old_dom) == 1:
                    continue

                other_rows = [rr for rr in range(R) if rr != r]

                # For each column c:
                # mandatory_other[c] = sum of row weights from rows != r that must include c
                # possible_other[c]  = sum of row weights from rows != r that may include c
                mandatory_other = [0] * C
                possible_other = [0] * C
                for rr in other_rows:
                    rw = row_weights[rr]
                    all1 = (1 << C) - 1
                    any1 = 0
                    for m in domains[rr]:
                        any1 |= m
                        all1 &= m
                    for c in range(C):
                        bit = 1 << c
                        if all1 & bit:
                            mandatory_other[c] += rw
                            possible_other[c] += rw
                        elif any1 & bit:
                            possible_other[c] += rw

                # Build exact subset-sum bitsets for optional rows per column.
                # Optional rows are those that can vary on that column.
                col_possible_bits = [0] * C
                for c in range(C):
                    bits = 1
                    for rr in other_rows:
                        rw = row_weights[rr]
                        has0 = False
                        has1 = False
                        bit = 1 << c
                        for m in domains[rr]:
                            if m & bit:
                                has1 = True
                            else:
                                has0 = True
                            if has0 and has1:
                                bits |= (bits << rw)
                                break
                    col_possible_bits[c] = bits

                new_dom = []
                for m in old_dom:
                    ok = True
                    for c in range(C):
                        need = col_targets[c] - mandatory_other[c] - (row_weights[r] if (m >> c) & 1 else 0)
                        if need < 0 or need > possible_other[c]:
                            ok = False
                            break
                        if not bit_has(col_possible_bits[c], need):
                            ok = False
                            break
                    if ok:
                        new_dom.append(m)

                if not new_dom:
                    return None
                if len(new_dom) != len(old_dom):
                    domains[r] = new_dom
                    changed = True

            # If a row becomes fixed, immediately recheck rough consistency.
            minc, maxc = domain_column_bounds(domains)
            for c in range(C):
                if col_targets[c] < minc[c] or col_targets[c] > maxc[c]:
                    return None

        return domains

    def choose_row(domains):
        # Most constrained row; tie-break by rows whose patterns differ most in column coverage.
        best_r = None
        best_key = None
        for r, dom in enumerate(domains):
            if len(dom) <= 1:
                continue
            any1 = 0
            all1 = (1 << C) - 1
            for m in dom:
                any1 |= m
                all1 &= m
            flex = 0
            x = any1 ^ all1
            while x:
                x &= x - 1
                flex += 1
            key = (len(dom), flex)
            if best_key is None or key < best_key:
                best_key = key
                best_r = r
        return best_r

    def order_values(domains, r):
        # Least-conflicting first: prefer masks closer to satisfying columns.
        scores = []
        current_min, current_max = domain_column_bounds(domains)
        for m in domains[r]:
            score = 0
            rw = row_weights[r]
            for c in range(C):
                bit = 1 << c
                in_mask = 1 if (m & bit) else 0

                # Compare selecting/not selecting with target pressure.
                forced = 0
                possible = 0
                for rr, dom in enumerate(domains):
                    if rr == r:
                        continue
                    rrw = row_weights[rr]
                    all1 = (1 << C) - 1
                    any1 = 0
                    for mm in dom:
                        any1 |= mm
                        all1 &= mm
                    if all1 & bit:
                        forced += rrw
                        possible += rrw
                    elif any1 & bit:
                        possible += rrw

                lo = forced + in_mask * rw
                hi = possible + in_mask * rw
                if lo <= col_targets[c] <= hi:
                    score += 0
                else:
                    score += abs(col_targets[c] - lo) + abs(col_targets[c] - hi)
            scores.append((score, m))
        scores.sort()
        return [m for _, m in scores]

    def final_check(domains):
        if any(len(dom) != 1 for dom in domains):
            return False
        col_acc = [0] * C
        for r in range(R):
            m = domains[r][0]
            rw = row_weights[r]
            for c in range(C):
                if (m >> c) & 1:
                    col_acc[c] += rw
        return col_acc == col_targets

    def search(domains):
        domains = [list(d) for d in domains]
        domains = prune(domains)
        if domains is None:
            return None
        if all(len(d) == 1 for d in domains):
            if final_check(domains):
                return domains
            return None

        r = choose_row(domains)
        if r is None:
            return None

        for m in order_values(domains, r):
            nxt = [list(d) for d in domains]
            nxt[r] = [m]
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    result = search(row_domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(R):
        m = result[r][0]
        row = []
        for c in range(C):
            row.append('B' if ((m >> c) & 1) else None)
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

