from collections import defaultdict, deque

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
DIR_LIST = ['U', 'D', 'L', 'R']


def addp(a, b):
    return (a[0] + b[0], a[1] + b[1])


def solve(observation):
    data = observation['data']
    n = len(data) - 1
    if n < 1:
        return "No Solution"

    clues = {}
    for r in range(n + 1):
        for c in range(n + 1):
            tok = data[r][c]
            if tok is not None:
                kind = tok[0]
                val = int(tok[1:])
                clues[(r, c)] = (kind, val)

    vertices = [(r, c) for r in range(n + 1) for c in range(n + 1)]
    edge_id = {}
    edge_ends = []
    incident = {v: [] for v in vertices}

    def add_edge(a, b):
        eid = len(edge_ends)
        edge_id[(a, b)] = eid
        edge_id[(b, a)] = eid
        edge_ends.append((a, b))
        incident[a].append(eid)
        incident[b].append(eid)

    for r in range(n + 1):
        for c in range(n):
            add_edge((r, c), (r, c + 1))
    for r in range(n):
        for c in range(n + 1):
            add_edge((r, c), (r + 1, c))

    m = len(edge_ends)
    UNKNOWN, OFF, ON = -1, 0, 1

    edge_dir_at_vertex = {}
    for eid, (a, b) in enumerate(edge_ends):
        dr = b[0] - a[0]
        dc = b[1] - a[1]
        if dr == 0 and dc == 1:
            edge_dir_at_vertex[(eid, a)] = 'R'
            edge_dir_at_vertex[(eid, b)] = 'L'
        elif dr == 1 and dc == 0:
            edge_dir_at_vertex[(eid, a)] = 'D'
            edge_dir_at_vertex[(eid, b)] = 'U'
        else:
            return "No Solution"

    ray_edges = {}
    for v in clues:
        dmap = {}
        r, c = v
        for d, (dr, dc) in DIRS.items():
            lst = []
            cr, cc = r, c
            while True:
                nr, nc = cr + dr, cc + dc
                if not (0 <= nr <= n and 0 <= nc <= n):
                    break
                eid = edge_id[((cr, cc), (nr, nc))]
                lst.append(eid)
                cr, cc = nr, nc
            dmap[d] = lst
        ray_edges[v] = dmap

    clue_patterns = {}
    for v, (kind, k) in clues.items():
        pats = []
        if kind == 'W':
            pairs = [('U', 'D'), ('L', 'R')]
        else:
            pairs = [('U', 'L'), ('U', 'R'), ('D', 'L'), ('D', 'R')]
        for d1, d2 in pairs:
            max1 = len(ray_edges[v][d1])
            max2 = len(ray_edges[v][d2])
            lo1 = max(1, k - max2)
            hi1 = min(max1, k - 1)
            for l1 in range(lo1, hi1 + 1):
                l2 = k - l1
                if 1 <= l2 <= max2:
                    pats.append((d1, l1, d2, l2))
        if not pats:
            return "No Solution"
        clue_patterns[v] = pats

    edge_clue_requirements = defaultdict(list)
    for v, pats in clue_patterns.items():
        for pi, (d1, l1, d2, l2) in enumerate(pats):
            for i, eid in enumerate(ray_edges[v][d1]):
                edge_clue_requirements[eid].append((v, pi, 1 if i < l1 else 0))
            for i, eid in enumerate(ray_edges[v][d2]):
                edge_clue_requirements[eid].append((v, pi, 1 if i < l2 else 0))
            used_dirs = {d1, d2}
            for d in DIR_LIST:
                if d not in used_dirs:
                    for eid in ray_edges[v][d]:
                        edge_clue_requirements[eid].append((v, pi, 0))

    patterns_possible = {v: set(range(len(clue_patterns[v]))) for v in clues}
    edge_state = [UNKNOWN] * m
    deg_on = {v: 0 for v in vertices}
    deg_unknown = {v: len(incident[v]) for v in vertices}

    parent = list(range(len(vertices)))
    rank = [0] * len(vertices)
    vertex_index = {v: i for i, v in enumerate(vertices)}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1

    changes = []

    def snapshot():
        return len(changes)

    def rollback(snap):
        nonlocal parent, rank
        while len(changes) > snap:
            typ, data = changes.pop()
            if typ == 'edge':
                eid, prev = data
                edge_state[eid] = prev
            elif typ == 'deg':
                v, pon, punk = data
                deg_on[v] = pon
                deg_unknown[v] = punk
            elif typ == 'pat':
                v, oldset = data
                patterns_possible[v] = oldset
            elif typ == 'uf':
                parent, rank = data

    queue_vertices = deque()
    queue_clues = deque()
    queue_edges = deque()

    in_qv = set()
    in_qc = set()
    in_qe = set()

    def push_vertex(v):
        if v not in in_qv:
            in_qv.add(v)
            queue_vertices.append(v)

    def push_clue(v):
        if v not in in_qc:
            in_qc.add(v)
            queue_clues.append(v)

    def push_edge(eid):
        if eid not in in_qe:
            in_qe.add(eid)
            queue_edges.append(eid)

    def set_edge(eid, val):
        cur = edge_state[eid]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        changes.append(('edge', (eid, cur)))
        edge_state[eid] = val
        a, b = edge_ends[eid]
        changes.append(('deg', (a, deg_on[a], deg_unknown[a])))
        changes.append(('deg', (b, deg_on[b], deg_unknown[b])))
        deg_unknown[a] -= 1
        deg_unknown[b] -= 1
        if val == ON:
            deg_on[a] += 1
            deg_on[b] += 1
            changes.append(('uf', (parent[:], rank[:])))
            union(vertex_index[a], vertex_index[b])
        push_vertex(a)
        push_vertex(b)
        push_edge(eid)
        for clue, _, _ in edge_clue_requirements[eid]:
            push_clue(clue)
        return True

    def prune_clue(v):
        old = patterns_possible[v]
        new = set()
        pats = clue_patterns[v]
        for pi in old:
            d1, l1, d2, l2 = pats[pi]
            ok = True
            req = {}
            for i, eid in enumerate(ray_edges[v][d1]):
                req[eid] = ON if i < l1 else OFF
            for i, eid in enumerate(ray_edges[v][d2]):
                req[eid] = ON if i < l2 else OFF
            used_dirs = {d1, d2}
            for d in DIR_LIST:
                if d not in used_dirs:
                    for eid in ray_edges[v][d]:
                        req[eid] = OFF
            for eid, need in req.items():
                st = edge_state[eid]
                if st != UNKNOWN and st != need:
                    ok = False
                    break
            if ok:
                new.add(pi)
        if not new:
            return False
        if new != old:
            changes.append(('pat', (v, old)))
            patterns_possible[v] = new
            forced = {}
            first = True
            for pi in new:
                d1, l1, d2, l2 = clue_patterns[v][pi]
                req = {}
                for i, eid in enumerate(ray_edges[v][d1]):
                    req[eid] = ON if i < l1 else OFF
                for i, eid in enumerate(ray_edges[v][d2]):
                    req[eid] = ON if i < l2 else OFF
                used_dirs = {d1, d2}
                for d in DIR_LIST:
                    if d not in used_dirs:
                        for eid in ray_edges[v][d]:
                            req[eid] = OFF
                if first:
                    forced = req
                    first = False
                else:
                    for eid in list(forced.keys()):
                        if forced[eid] != req[eid]:
                            del forced[eid]
            for eid, val in forced.items():
                if not set_edge(eid, val):
                    return False
        return True

    def enforce_vertex(v):
        on = deg_on[v]
        unk = deg_unknown[v]
        if on > 2:
            return False
        if on + unk < 2:
            return False
        if on == 2:
            for eid in incident[v]:
                if edge_state[eid] == UNKNOWN:
                    if not set_edge(eid, OFF):
                        return False
        elif on + unk == 2:
            for eid in incident[v]:
                if edge_state[eid] == UNKNOWN:
                    if not set_edge(eid, ON):
                        return False
        return True

    def check_no_small_cycle():
        on_edges = [eid for eid, st in enumerate(edge_state) if st == ON]
        if not on_edges:
            return True
        adj = defaultdict(list)
        for eid in on_edges:
            a, b = edge_ends[eid]
            adj[a].append((b, eid))
            adj[b].append((a, eid))
        visited_v = set()
        total_on = len(on_edges)
        for v in adj:
            if v in visited_v:
                continue
            comp_v = []
            comp_e = set()
            dq = [v]
            visited_v.add(v)
            while dq:
                x = dq.pop()
                comp_v.append(x)
                for y, eid in adj[x]:
                    comp_e.add(eid)
                    if y not in visited_v:
                        visited_v.add(y)
                        dq.append(y)
            closed = all(deg_on[x] == 2 for x in comp_v)
            if closed and len(comp_e) < total_on:
                return False
        return True

    def propagate():
        while queue_vertices or queue_clues or queue_edges:
            while queue_clues:
                v = queue_clues.popleft()
                in_qc.discard(v)
                if not prune_clue(v):
                    return False
            while queue_vertices:
                v = queue_vertices.popleft()
                in_qv.discard(v)
                if not enforce_vertex(v):
                    return False
            while queue_edges:
                eid = queue_edges.popleft()
                in_qe.discard(eid)
                pass
            if not check_no_small_cycle():
                return False
        return True

    for v in vertices:
        push_vertex(v)
    for v in clues:
        push_clue(v)

    if not propagate():
        return "No Solution"

    def all_assigned():
        return all(st != UNKNOWN for st in edge_state)

    def final_check():
        if any(len(patterns_possible[v]) != 1 for v in clues):
            return False
        if any(deg_on[v] not in (0, 2) for v in vertices):
            return False
        on_edges = [eid for eid, st in enumerate(edge_state) if st == ON]
        if not on_edges:
            return False
        adj = defaultdict(list)
        used_vertices = set()
        for eid in on_edges:
            a, b = edge_ends[eid]
            adj[a].append(b)
            adj[b].append(a)
            used_vertices.add(a)
            used_vertices.add(b)
        start = next(iter(used_vertices))
        seen = set([start])
        dq = [start]
        while dq:
            x = dq.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    dq.append(y)
        if seen != used_vertices:
            return False
        for v in clues:
            if deg_on[v] != 2:
                return False
        return True

    def choose_branch():
        best = None
        best_score = None

        for v in clues:
            if len(patterns_possible[v]) > 1:
                score = (len(patterns_possible[v]), -sum(edge_state[eid] == UNKNOWN for d in DIR_LIST for eid in ray_edges[v][d]))
                if best is None or score < best_score:
                    best = ('clue', v)
                    best_score = score

        if best is not None:
            return best

        for eid, st in enumerate(edge_state):
            if st == UNKNOWN:
                a, b = edge_ends[eid]
                score = -(deg_unknown[a] + deg_unknown[b])
                if best is None or score < best_score:
                    best = ('edge', eid)
                    best_score = score
        return best

    def build_path():
        on_edges = [eid for eid, st in enumerate(edge_state) if st == ON]
        adj = defaultdict(list)
        for eid in on_edges:
            a, b = edge_ends[eid]
            adj[a].append(b)
            adj[b].append(a)
        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            if prev is None:
                nxt = min(nbrs)
            else:
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        return path

    def search():
        if all_assigned():
            return final_check()

        choice = choose_branch()
        if choice is None:
            return final_check()

        kind, obj = choice

        if kind == 'clue':
            v = obj
            options = []
            for pi in patterns_possible[v]:
                req = {}
                d1, l1, d2, l2 = clue_patterns[v][pi]
                for i, eid in enumerate(ray_edges[v][d1]):
                    req[eid] = ON if i < l1 else OFF
                for i, eid in enumerate(ray_edges[v][d2]):
                    req[eid] = ON if i < l2 else OFF
                used_dirs = {d1, d2}
                for d in DIR_LIST:
                    if d not in used_dirs:
                        for eid in ray_edges[v][d]:
                            req[eid] = OFF
                impact = sum(1 for eid, val in req.items() if edge_state[eid] == UNKNOWN)
                options.append((-impact, pi, req))
            options.sort()
            for _, pi, req in options:
                snap = snapshot()
                old = patterns_possible[v]
                changes.append(('pat', (v, old)))
                patterns_possible[v] = {pi}
                ok = True
                for eid, val in req.items():
                    if not set_edge(eid, val):
                        ok = False
                        break
                if ok:
                    push_clue(v)
                    ok = propagate()
                if ok and search():
                    return True
                rollback(snap)
            return False

        eid = obj
        a, b = edge_ends[eid]
        values = [ON, OFF]
        if deg_on[a] == 1 and deg_unknown[a] == 1:
            values = [ON, OFF]
        elif deg_on[a] == 2 or deg_on[b] == 2:
            values = [OFF, ON]

        for val in values:
            snap = snapshot()
            ok = set_edge(eid, val)
            if ok:
                ok = propagate()
            if ok and search():
                return True
            rollback(snap)
        return False

    if not search():
        return "No Solution"
    return str(build_path())


