# General solver for the "water level by region" puzzle.
# Each region chooses a single water level: either empty, or all cells with row >= level in that region are water.
# This induces one candidate pattern per possible cutoff in each region.
# We solve by strong propagation on row/column exact counts plus region-choice consistency.

from collections import defaultdict

def solve(observation):
    region_grid = observation['region']
    row_target = observation['row_water_counts']
    col_target = observation['col_water_counts']

    R = len(region_grid)
    if R == 0:
        return "[]"
    C = len(region_grid[0])

    # Build regions and their row-structure.
    region_cells = defaultdict(list)
    for r in range(R):
        for c in range(C):
            region_cells[region_grid[r][c]].append((r, c))

    region_ids = sorted(region_cells)
    region_index = {rid: i for i, rid in enumerate(region_ids)}
    K = len(region_ids)

    # For each region, create all feasible "water level" options.
    # Option represented as bitmask of water cells over all cells in that region.
    region_rows = {}
    region_cols_in_row = {}
    for rid in region_ids:
        rows = defaultdict(list)
        for r, c in region_cells[rid]:
            rows[r].append(c)
        region_rows[rid] = sorted(rows)
        region_cols_in_row[rid] = {r: tuple(sorted(cols)) for r, cols in rows.items()}

    # Global cell indexing for compact masks if needed later.
    cell_to_bit = {(r, c): r * C + c for r in range(R) for c in range(C)}

    # Each option stores:
    # - row_add[r]: number of water cells contributed to row r
    # - col_add[c]: number of water cells contributed to col c
    # - cells_mask: bitmask over full board
    options = []
    region_options = []

    for rid in region_ids:
        rows_sorted = region_rows[rid]
        row_to_cols = region_cols_in_row[rid]
        opts = []

        # Empty option.
        row_add = [0] * R
        col_add = [0] * C
        cells_mask = 0
        opts.append((row_add, col_add, cells_mask))

        # Water up to consistent level: choose a topmost water row among existing region rows.
        # Then every region cell in rows >= that row becomes water.
        for cutoff_row in rows_sorted:
            row_add = [0] * R
            col_add = [0] * C
            cells_mask = 0
            for rr in rows_sorted:
                if rr >= cutoff_row:
                    cols = row_to_cols[rr]
                    row_add[rr] += len(cols)
                    for cc in cols:
                        col_add[cc] += 1
                        cells_mask |= 1 << cell_to_bit[(rr, cc)]
            opts.append((row_add, col_add, cells_mask))

        region_options.append(opts)

    # Precompute quick min/max contributions to each row/col from each region domain subset.
    def domain_bounds(domains):
        row_min = [0] * R
        row_max = [0] * R
        col_min = [0] * C
        col_max = [0] * C
        for k in range(K):
            opts = region_options[k]
            dom = domains[k]
            for r in range(R):
                vals = [opts[i][0][r] for i in dom]
                row_min[r] += min(vals)
                row_max[r] += max(vals)
            for c in range(C):
                vals = [opts[i][1][c] for i in dom]
                col_min[c] += min(vals)
                col_max[c] += max(vals)
        return row_min, row_max, col_min, col_max

    # Cell-level forcedness from current domains.
    # If every remaining option of a region agrees a cell is water, it is forced water.
    # If every remaining option agrees non-water, forced non-water.
    # Use row/col residuals to prune impossible region options.
    region_cell_option_water = []
    for k, rid in enumerate(region_ids):
        cells = region_cells[rid]
        per_opt = []
        for opt in region_options[k]:
            mask = opt[2]
            d = {}
            for cell in cells:
                d[cell] = 1 if (mask >> cell_to_bit[cell]) & 1 else 0
            per_opt.append(d)
        region_cell_option_water.append(per_opt)

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # Global row/col feasibility.
            row_min, row_max, col_min, col_max = domain_bounds(domains)
            for r in range(R):
                if row_target[r] < row_min[r] or row_target[r] > row_max[r]:
                    return None
            for c in range(C):
                if col_target[c] < col_min[c] or col_target[c] > col_max[c]:
                    return None

            # Region-option pruning by checking whether choosing it can still satisfy all line totals.
            for k in range(K):
                opts = region_options[k]
                other_domains = domains[:k] + domains[k+1:]

                # Bounds from other regions only.
                other_row_min = [0] * R
                other_row_max = [0] * R
                other_col_min = [0] * C
                other_col_max = [0] * C
                for kk, dom in enumerate(other_domains):
                    real_k = kk if kk < k else kk + 1
                    o_opts = region_options[real_k]
                    for r in range(R):
                        vals = [o_opts[i][0][r] for i in dom]
                        other_row_min[r] += min(vals)
                        other_row_max[r] += max(vals)
                    for c in range(C):
                        vals = [o_opts[i][1][c] for i in dom]
                        other_col_min[c] += min(vals)
                        other_col_max[c] += max(vals)

                new_dom = set()
                for i in domains[k]:
                    row_add, col_add, _ = opts[i]
                    ok = True
                    for r in range(R):
                        need = row_target[r] - row_add[r]
                        if need < other_row_min[r] or need > other_row_max[r]:
                            ok = False
                            break
                    if ok:
                        for c in range(C):
                            need = col_target[c] - col_add[c]
                            if need < other_col_min[c] or need > other_col_max[c]:
                                ok = False
                                break
                    if ok:
                        new_dom.add(i)
                if not new_dom:
                    return None
                if new_dom != domains[k]:
                    domains[k] = new_dom
                    changed = True

            # Human-like cell forcing from line exactness.
            # Determine globally forced water/non-water cells from region domains.
            forced_water = set()
            forced_land = set()
            for k, rid in enumerate(region_ids):
                cells = region_cells[rid]
                dom = domains[k]
                per_opt = region_cell_option_water[k]
                for cell in cells:
                    vals = {per_opt[i][cell] for i in dom}
                    if len(vals) == 1:
                        if 1 in vals:
                            forced_water.add(cell)
                        else:
                            forced_land.add(cell)

            # Row exact-count forcing.
            for r in range(R):
                row_cells = [(r, c) for c in range(C)]
                fw = sum(1 for cell in row_cells if cell in forced_water)
                unknown = [cell for cell in row_cells if cell not in forced_water and cell not in forced_land]
                need = row_target[r] - fw
                if need < 0 or need > len(unknown):
                    return None
                if need == 0 or need == len(unknown):
                    want = 1 if need == len(unknown) else 0
                    for cell in unknown:
                        rr, cc = cell
                        rid = region_grid[rr][cc]
                        k = region_index[rid]
                        new_dom = set()
                        for i in domains[k]:
                            if region_cell_option_water[k][i][cell] == want:
                                new_dom.add(i)
                        if not new_dom:
                            return None
                        if new_dom != domains[k]:
                            domains[k] = new_dom
                            changed = True

            # Column exact-count forcing.
            for c in range(C):
                col_cells = [(r, c) for r in range(R)]
                fw = sum(1 for cell in col_cells if cell in forced_water)
                unknown = [cell for cell in col_cells if cell not in forced_water and cell not in forced_land]
                need = col_target[c] - fw
                if need < 0 or need > len(unknown):
                    return None
                if need == 0 or need == len(unknown):
                    want = 1 if need == len(unknown) else 0
                    for cell in unknown:
                        rr, cc = cell
                        rid = region_grid[rr][cc]
                        k = region_index[rid]
                        new_dom = set()
                        for i in domains[k]:
                            if region_cell_option_water[k][i][cell] == want:
                                new_dom.add(i)
                        if not new_dom:
                            return None
                        if new_dom != domains[k]:
                            domains[k] = new_dom
                            changed = True

        return domains

    def is_solved(domains):
        return all(len(d) == 1 for d in domains)

    def build_answer(domains):
        grid = [[None for _ in range(C)] for _ in range(R)]
        for k, rid in enumerate(region_ids):
            i = next(iter(domains[k]))
            mask = region_options[k][i][2]
            for r, c in region_cells[rid]:
                if (mask >> cell_to_bit[(r, c)]) & 1:
                    grid[r][c] = 'W'
        return str(grid)

    def choose_branch_region(domains):
        # Most constrained region first; tie-break by largest effect variability.
        best_k = None
        best_key = None
        for k in range(K):
            if len(domains[k]) <= 1:
                continue
            row_spread = 0
            col_spread = 0
            opts = region_options[k]
            dom = domains[k]
            for r in range(R):
                vals = [opts[i][0][r] for i in dom]
                row_spread += max(vals) - min(vals)
            for c in range(C):
                vals = [opts[i][1][c] for i in dom]
                col_spread += max(vals) - min(vals)
            key = (len(domains[k]), -(row_spread + col_spread))
            if best_key is None or key < best_key:
                best_key = key
                best_k = k
        return best_k

    def ordered_values(k, domains):
        # Try options that are most constrained by current residual bounds.
        opts = region_options[k]
        scored = []
        row_min, row_max, col_min, col_max = domain_bounds(domains)
        for i in domains[k]:
            row_add, col_add, _ = opts[i]
            score = 0
            for r in range(R):
                slack = (row_target[r] - row_min[r]) + (row_max[r] - row_target[r])
                score += abs(row_add[r] * 2 - (row_min[r] + row_max[r])) + slack
            for c in range(C):
                slack = (col_target[c] - col_min[c]) + (col_max[c] - col_target[c])
                score += abs(col_add[c] * 2 - (col_min[c] + col_max[c])) + slack
            scored.append((score, i))
        scored.sort()
        return [i for _, i in scored]

    def dfs(domains):
        domains = [set(d) for d in domains]
        domains = propagate(domains)
        if domains is None:
            return None
        if is_solved(domains):
            # Final exact verification.
            ans = [[None for _ in range(C)] for _ in range(R)]
            row_count = [0] * R
            col_count = [0] * C
            for k, rid in enumerate(region_ids):
                i = next(iter(domains[k]))
                mask = region_options[k][i][2]
                for r, c in region_cells[rid]:
                    if (mask >> cell_to_bit[(r, c)]) & 1:
                        ans[r][c] = 'W'
                        row_count[r] += 1
                        col_count[c] += 1
            if row_count == row_target and col_count == col_target:
                return str(ans)
            return None

        k = choose_branch_region(domains)
        if k is None:
            return None

        for i in ordered_values(k, domains):
            new_domains = [set(d) for d in domains]
            new_domains[k] = {i}
            res = dfs(new_domains)
            if res is not None:
                return res
        return None

    initial_domains = [set(range(len(region_options[k]))) for k in range(K)]
    result = dfs(initial_domains)
    return result if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, 'B', None, None], [None, 'W', None, None, None, None, 'B', None, None, 'W'], [None, None, None, None, None, None, None, None, None, None], ['W', None, None, 'B', None, None, 'W', None, 'W', None], [None, 'B', None, 'W', None, 'W', None, None, None, None], [None, None, 'B', None, None, None, 'W', 'W', None, 'W'], [None, 'W', None, None, None, 'W', None, 'W', None, None], [None, None, None, None, None, None, 'W', None, 'W', None], [None, None, None, None, 'B', None, 'W', 'W', None, None], ['B', None, None, None, None, None, None, None, None, None]]}

from collections import deque, defaultdict

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Edge indexing on an n x n dot grid.
    # Horizontal: between (r,c) and (r,c+1), r in [0..n-1], c in [0..n-2]
    # Vertical:   between (r,c) and (r+1,c), r in [0..n-2], c in [0..n-1]
    h_count = n * (n - 1)
    v_count = (n - 1) * n
    m = h_count + v_count

    def h_id(r, c):
        return r * (n - 1) + c

    def v_id(r, c):
        return h_count + r * n + c

    def edge_endpoints(eid):
        if eid < h_count:
            r, c = divmod(eid, n - 1)
            return (r, c), (r, c + 1)
        x = eid - h_count
        r, c = divmod(x, n)
        return (r, c), (r + 1, c)

    # For each cell/dot, map local direction -> edge id or None if out of bounds
    dot_edges = [[[-1] * 4 for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r > 0:
                dot_edges[r][c][0] = v_id(r - 1, c)
            if c < n - 1:
                dot_edges[r][c][1] = h_id(r, c)
            if r < n - 1:
                dot_edges[r][c][2] = v_id(r, c)
            if c > 0:
                dot_edges[r][c][3] = h_id(r, c - 1)

    # Candidate local patterns for each clue / empty dot.
    # Each pattern is a bitmask on directions U,R,D,L with exactly deg 0 or 2.
    all_masks = [0, 3, 5, 6, 9, 10, 12]  # 0 plus all 2-edge combos

    def is_straight(mask):
        return mask in (5, 10)  # U+D or R+L

    def is_turn(mask):
        return mask in (3, 6, 9, 12)

    allowed_masks = [[[] for _ in range(n)] for _ in range(n)]
    clues = []
    for r in range(n):
        for c in range(n):
            clue = data[r][c]
            if clue is None:
                allowed_masks[r][c] = [0, 3, 5, 6, 9, 10, 12]
            elif clue == 'W':
                allowed_masks[r][c] = [5, 10]
                clues.append((r, c))
            elif clue == 'B':
                allowed_masks[r][c] = [3, 6, 9, 12]
                clues.append((r, c))
            else:
                return "No Solution"

            # Filter masks by border feasibility
            filt = []
            for mask in allowed_masks[r][c]:
                ok = True
                for d in range(4):
                    if (mask >> d) & 1:
                        if dot_edges[r][c][d] == -1:
                            ok = False
                            break
                if ok:
                    filt.append(mask)
            allowed_masks[r][c] = filt
            if not filt:
                return "No Solution"

    # Human-like look-ahead around clue circles:
    # White: straight at circle, and at least one adjacent clue-neighbor step (prev or next) must be a turn.
    # Black: turn at circle, and both adjacent clue-neighbor steps must be straight.
    #
    # We encode directional compatibility constraints between consecutive visited clue dots along used edges.
    # Since every clue dot is on loop, each clue contributes conditional requirements on neighboring dots.
    #
    # For a clue at (r,c) and a chosen mask:
    # - white straight vertical uses U and D. Then the previous and next visited dots are (r-1,c),(r+1,c).
    #   At least one of those dots must be a turn in its chosen mask.
    # - white straight horizontal analogously.
    # - black turn with directions d1,d2. Then neighbors in those directions must be straight.

    # Reverse incidence: edge -> [(r,c,direction)]
    edge_to_local = [[] for _ in range(m)]
    for r in range(n):
        for c in range(n):
            for d in range(4):
                eid = dot_edges[r][c][d]
                if eid != -1:
                    edge_to_local[eid].append((r, c, d))

    # State
    edge_state = [-1] * m  # -1 unknown, 0 off, 1 on

    # Domain masks as mutable sets encoded by sorted lists + alive flags
    domains = [[set(allowed_masks[r][c]) for c in range(n)] for r in range(n)]

    # Queue-driven propagation
    q = deque()
    inq = set()

    def enqueue_dot(r, c):
        key = ('d', r, c)
        if key not in inq:
            inq.add(key)
            q.append(key)

    def enqueue_edge(eid):
        key = ('e', eid)
        if key not in inq:
            inq.add(key)
            q.append(key)

    for r in range(n):
        for c in range(n):
            enqueue_dot(r, c)

    trail = []

    def assign_edge(eid, val):
        cur = edge_state[eid]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        trail.append(('edge', eid, cur))
        edge_state[eid] = val
        enqueue_edge(eid)
        a, b = edge_endpoints(eid)
        enqueue_dot(*a)
        enqueue_dot(*b)
        return True

    def remove_mask(r, c, mask):
        if mask not in domains[r][c]:
            return True
        trail.append(('mask', r, c, mask))
        domains[r][c].remove(mask)
        if not domains[r][c]:
            return False
        enqueue_dot(r, c)
        return True

    def force_domain_singletons(r, c):
        # If all remaining masks agree on an edge state, propagate it.
        dom = domains[r][c]
        for d in range(4):
            eid = dot_edges[r][c][d]
            if eid == -1:
                continue
            vals = set((mask >> d) & 1 for mask in dom)
            if len(vals) == 1:
                v = next(iter(vals))
                if not assign_edge(eid, v):
                    return False
        return True

    def dot_type_from_mask(mask):
        if mask == 0:
            return 'Z'
        return 'S' if is_straight(mask) else 'T'

    def process_dot(r, c):
        dom = domains[r][c]
        # Filter by incident edge states and degree 0/2 nature already encoded in masks
        rem = []
        for mask in list(dom):
            ok = True
            for d in range(4):
                bit = (mask >> d) & 1
                eid = dot_edges[r][c][d]
                if eid == -1:
                    if bit:
                        ok = False
                        break
                    continue
                st = edge_state[eid]
                if st != -1 and st != bit:
                    ok = False
                    break
            if ok:
                rem.append(mask)
        if len(rem) != len(dom):
            keep = set(rem)
            for mask in list(dom):
                if mask not in keep:
                    if not remove_mask(r, c, mask):
                        return False
            dom = domains[r][c]

        clue = data[r][c]
        if clue is not None:
            # Additional clue-neighbor logic
            valid = []
            for mask in list(dom):
                if clue == 'W':
                    # Must be straight. At least one neighbor in used directions can be a turn.
                    if mask == 5:
                        nbrs = []
                        for nr, nc in [(r - 1, c), (r + 1, c)]:
                            if 0 <= nr < n and 0 <= nc < n:
                                nbrs.append((nr, nc))
                        possible_turn = False
                        for nr, nc in nbrs:
                            for m2 in domains[nr][nc]:
                                if is_turn(m2):
                                    possible_turn = True
                                    break
                            if possible_turn:
                                break
                        if possible_turn:
                            valid.append(mask)
                    elif mask == 10:
                        nbrs = []
                        for nr, nc in [(r, c - 1), (r, c + 1)]:
                            if 0 <= nr < n and 0 <= nc < n:
                                nbrs.append((nr, nc))
                        possible_turn = False
                        for nr, nc in nbrs:
                            for m2 in domains[nr][nc]:
                                if is_turn(m2):
                                    possible_turn = True
                                    break
                            if possible_turn:
                                break
                        if possible_turn:
                            valid.append(mask)
                else:  # 'B'
                    # Must turn. Both neighboring dots in used directions must be straight-capable.
                    ds = [d for d in range(4) if (mask >> d) & 1]
                    good = True
                    for d in ds:
                        nr, nc = r + DIRS[d][0], c + DIRS[d][1]
                        if not (0 <= nr < n and 0 <= nc < n):
                            good = False
                            break
                        if not any(is_straight(m2) for m2 in domains[nr][nc]):
                            good = False
                            break
                    if good:
                        valid.append(mask)
            if len(valid) != len(dom):
                keep = set(valid)
                for mask in list(dom):
                    if mask not in keep:
                        if not remove_mask(r, c, mask):
                            return False
                dom = domains[r][c]

        if not force_domain_singletons(r, c):
            return False

        # If edge states force exactly one mask, keep it.
        if len(dom) == 1:
            mask = next(iter(dom))
            for d in range(4):
                eid = dot_edges[r][c][d]
                if eid != -1:
                    if not assign_edge(eid, (mask >> d) & 1):
                        return False
        return True

    def process_edge(eid):
        st = edge_state[eid]
        if st == -1:
            return True
        for r, c, d in edge_to_local[eid]:
            for mask in list(domains[r][c]):
                if ((mask >> d) & 1) != st:
                    if not remove_mask(r, c, mask):
                        return False
        return True

    def rollback(mark):
        while len(trail) > mark:
            item = trail.pop()
            if item[0] == 'edge':
                _, eid, prev = item
                edge_state[eid] = prev
            else:
                _, r, c, mask = item
                domains[r][c].add(mask)

    def propagate():
        while q:
            key = q.popleft()
            inq.discard(key)
            if key[0] == 'd':
                if not process_dot(key[1], key[2]):
                    return False
            else:
                if not process_edge(key[1]):
                    return False
        # Global graph checks
        return global_checks()

    def active_neighbors_of_dot(r, c):
        res = []
        for d in range(4):
            eid = dot_edges[r][c][d]
            if eid != -1 and edge_state[eid] == 1:
                nr, nc = r + DIRS[d][0], c + DIRS[d][1]
                res.append((nr, nc, d, eid))
        return res

    def possible_on_count(r, c):
        cnt = 0
        for d in range(4):
            eid = dot_edges[r][c][d]
            if eid != -1 and edge_state[eid] != 0:
                cnt += 1
        return cnt

    def global_checks():
        # Degree feasibility at every dot
        active_dots = []
        for r in range(n):
            for c in range(n):
                on = 0
                unk = 0
                for d in range(4):
                    eid = dot_edges[r][c][d]
                    if eid == -1:
                        continue
                    st = edge_state[eid]
                    if st == 1:
                        on += 1
                    elif st == -1:
                        unk += 1
                if on > 2:
                    return False
                if on == 1 and unk == 0:
                    return False
                if on == 0 and data[r][c] is not None and unk == 0:
                    return False
                if on > 0:
                    active_dots.append((r, c))

        # Avoid completed small loops before all clue dots are included / full solution.
        # Build components on current ON edges.
        seen = set()
        total_clues = set(clues)
        for r, c in active_dots:
            if (r, c) in seen:
                continue
            comp_nodes = []
            comp_edges = 0
            dq = deque([(r, c)])
            seen.add((r, c))
            while dq:
                x, y = dq.popleft()
                comp_nodes.append((x, y))
                for nx, ny, d, eid in active_neighbors_of_dot(x, y):
                    comp_edges += 1
                    if (nx, ny) not in seen:
                        seen.add((nx, ny))
                        dq.append((nx, ny))
            comp_edges //= 2
            deg2 = all(len(active_neighbors_of_dot(x, y)) == 2 for x, y in comp_nodes)
            if deg2:
                comp_set = set(comp_nodes)
                # If any dot outside component could still join? For a closed component, impossible.
                # So allow only if all clues are inside and all decided edges form final solution.
                if not total_clues.issubset(comp_set):
                    return False
                # If there are unknown edges touching component nodes, component would already branch if used.
                # A final loop requires every used dot degree 2; other outside used dots impossible to connect.
                any_other_possible = False
                for rr in range(n):
                    for cc in range(n):
                        if (rr, cc) not in comp_set and any(edge_state[e] != 0 for e in dot_edges[rr][cc] if e != -1):
                            # Outside still has possible participation
                            any_other_possible = True
                            break
                    if any_other_possible:
                        break
                if any_other_possible:
                    return False
        return True

    def choose_branch():
        # Prefer clue dots, smallest domain >1
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                sz = len(domains[r][c])
                if sz <= 1:
                    continue
                clue_bias = 0 if data[r][c] is not None else 1
                key = (clue_bias, sz)
                if best is None or key < best_key:
                    best = ('dot', r, c)
                    best_key = key
        if best is not None:
            return best
        for eid in range(m):
            if edge_state[eid] == -1:
                return ('edge', eid)
        return None

    def all_decided():
        return all(len(domains[r][c]) == 1 for r in range(n) for c in range(n)) and all(st != -1 for st in edge_state)

    def extract_loop():
        # Build loop from ON edges
        on_edges = [eid for eid, st in enumerate(edge_state) if st == 1]
        if not on_edges:
            return None
        adj = defaultdict(list)
        for eid in on_edges:
            a, b = edge_endpoints(eid)
            adj[a].append(b)
            adj[b].append(a)
        used_dots = list(adj.keys())
        if any(len(adj[p]) != 2 for p in used_dots):
            return None
        clue_set = set(clues)
        if not clue_set.issubset(set(used_dots)):
            return None
        start = min(used_dots)
        path = [start]
        prev = None
        cur = start
        while True:
            nxts = adj[cur]
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(on_edges) + 2:
                return None
        if len(path) != len(on_edges) + 1:
            return None
        return path

    def dfs():
        if not propagate():
            return None
        if all_decided():
            loop = extract_loop()
            return loop if loop is not None else None

        branch = choose_branch()
        if branch is None:
            return None

        mark = len(trail)
        if branch[0] == 'dot':
            _, r, c = branch
            # Human-style branching: prefer masks consistent with clue semantics strongest.
            masks = sorted(domains[r][c], key=lambda m: (m == 0, m))
            for keep in masks:
                curdom = list(domains[r][c])
                ok = True
                for msk in curdom:
                    if msk != keep:
                        if not remove_mask(r, c, msk):
                            ok = False
                            break
                if ok:
                    res = dfs()
                    if res is not None:
                        return res
                rollback(mark)
                q.clear()
                inq.clear()
                enqueue_dot(r, c)
        else:
            _, eid = branch
            # Try ON before OFF to form loop through clues.
            for val in (1, 0):
                if assign_edge(eid, val):
                    res = dfs()
                    if res is not None:
                        return res
                rollback(mark)
                q.clear()
                inq.clear()
                enqueue_edge(eid)
        return None

    loop = dfs()
    if loop is None:
        return "No Solution"
    return str(loop)


