from itertools import combinations

# Weighted binary grid puzzle solver.
# A black cell at (r, c) contributes:
# - column weight (c+1) to row r target
# - row weight (r+1) to column c target
#
# Human-like logic encoded:
# 1) For each row, enumerate all subsets of columns whose column-weights sum to the row target.
# 2) For each column, track feasible accumulated row-weight based on remaining undecided rows.
# 3) Repeatedly force cell values by checking support across row patterns and column feasibility.
# 4) Branch only on the most constrained row/cell when propagation stalls.

def subset_masks_for_target(n, target, weights):
    masks = []
    def rec(i, rem, mask):
        if rem == 0:
            masks.append(mask)
            return
        if i == n or rem < 0:
            return
        max_possible = sum(weights[j] for j in range(i, n))
        if rem > max_possible:
            return
        rec(i + 1, rem, mask)
        w = weights[i]
        if w <= rem:
            rec(i + 1, rem - w, mask | (1 << i))
    rec(0, target, 0)
    return masks

def format_grid(mask_rows, n_rows, n_cols):
    grid = []
    for r in range(n_rows):
        row = []
        mask = mask_rows[r]
        for c in range(n_cols):
            row.append('B' if (mask >> c) & 1 else None)
        grid.append(row)
    return str(grid)

def solve(observation):
    row_targets = list(observation['row_sum'])
    col_targets = list(observation['col_sum'])
    n_rows = len(row_targets)
    n_cols = len(col_targets)

    row_weights = [r + 1 for r in range(n_rows)]
    col_weights = [c + 1 for c in range(n_cols)]

    # All feasible patterns per row.
    row_domains = []
    for r in range(n_rows):
        pats = subset_masks_for_target(n_cols, row_targets[r], col_weights)
        if not pats:
            return "No Solution"
        row_domains.append(pats)

    full_col_mask = (1 << n_cols) - 1

    # Precompute suffix sums of remaining row weights for fast column feasibility.
    # rem_weight_from[i] = sum of row weights from rows i..end in original order,
    # but dynamic search uses assigned/unassigned status explicitly too.
    def propagate(domains):
        domains = [list(d) for d in domains]

        while True:
            changed = False

            # Column current min/max contributions from row domains.
            col_min = [0] * n_cols
            col_max = [0] * n_cols

            row_must1 = [0] * n_rows
            row_may1 = [0] * n_rows

            for r, pats in enumerate(domains):
                if not pats:
                    return None
                inter = full_col_mask
                union = 0
                for m in pats:
                    inter &= m
                    union |= m
                row_must1[r] = inter
                row_may1[r] = union
                rw = row_weights[r]
                bits = union
                c = 0
                while bits:
                    if bits & 1:
                        col_max[c] += rw
                    bits >>= 1
                    c += 1
                bits = inter
                c = 0
                while bits:
                    if bits & 1:
                        col_min[c] += rw
                    bits >>= 1
                    c += 1

            for c in range(n_cols):
                if not (col_min[c] <= col_targets[c] <= col_max[c]):
                    return None

            # Filter row patterns by column range support.
            for r in range(n_rows):
                rw = row_weights[r]
                new_pats = []
                for m in domains[r]:
                    ok = True
                    for c in range(n_cols):
                        bit = (m >> c) & 1
                        contrib = rw if bit else 0
                        other_min = col_min[c] - (rw if ((row_must1[r] >> c) & 1) else 0)
                        other_max = col_max[c] - (rw if ((row_may1[r] >> c) & 1) else 0)
                        t = col_targets[c]
                        if not (other_min + contrib <= t <= other_max + contrib):
                            ok = False
                            break
                    if ok:
                        new_pats.append(m)
                if not new_pats:
                    return None
                if len(new_pats) != len(domains[r]):
                    domains[r] = new_pats
                    changed = True

            # Recompute after filtering for support-based forcing.
            col_min = [0] * n_cols
            col_max = [0] * n_cols
            row_must1 = [0] * n_rows
            row_may1 = [0] * n_rows
            for r, pats in enumerate(domains):
                inter = full_col_mask
                union = 0
                for m in pats:
                    inter &= m
                    union |= m
                row_must1[r] = inter
                row_may1[r] = union
                rw = row_weights[r]
                for c in range(n_cols):
                    if (union >> c) & 1:
                        col_max[c] += rw
                    if (inter >> c) & 1:
                        col_min[c] += rw

            # Cell forcing from exact column requirements.
            for r in range(n_rows):
                rw = row_weights[r]
                force1 = 0
                force0 = 0
                for c in range(n_cols):
                    other_min = col_min[c] - (rw if ((row_must1[r] >> c) & 1) else 0)
                    other_max = col_max[c] - (rw if ((row_may1[r] >> c) & 1) else 0)
                    t = col_targets[c]
                    can0 = other_min <= t <= other_max
                    can1 = other_min + rw <= t <= other_max + rw
                    if not can0 and not can1:
                        return None
                    if can1 and not can0:
                        force1 |= (1 << c)
                    elif can0 and not can1:
                        force0 |= (1 << c)

                if force1 or force0:
                    new_pats = []
                    for m in domains[r]:
                        if (m & force1) != force1:
                            continue
                        if (m & force0) != 0:
                            continue
                        new_pats.append(m)
                    if not new_pats:
                        return None
                    if len(new_pats) != len(domains[r]):
                        domains[r] = new_pats
                        changed = True

            # If all rows fixed, verify exact columns.
            all_single = all(len(d) == 1 for d in domains)
            if all_single:
                col_acc = [0] * n_cols
                for r in range(n_rows):
                    m = domains[r][0]
                    rw = row_weights[r]
                    for c in range(n_cols):
                        if (m >> c) & 1:
                            col_acc[c] += rw
                if col_acc != col_targets:
                    return None
                return domains

            if not changed:
                return domains

    def choose_branch(domains):
        # Prefer row with smallest domain > 1.
        best_r = None
        best_key = None
        for r, d in enumerate(domains):
            if len(d) > 1:
                inter = full_col_mask
                union = 0
                for m in d:
                    inter &= m
                    union |= m
                uncertainty = (union ^ inter).bit_count()
                key = (len(d), uncertainty)
                if best_key is None or key < best_key:
                    best_key = key
                    best_r = r
        return best_r

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if all(len(d) == 1 for d in domains):
            return [d[0] for d in domains]

        r = choose_branch(domains)
        pats = domains[r]

        # Order by impact: patterns that bring columns closer to targets first.
        def score(mask):
            s = 0
            rw = row_weights[r]
            for c in range(n_cols):
                if (mask >> c) & 1:
                    s -= abs(col_targets[c] - rw)
                else:
                    s -= abs(col_targets[c])
            return s

        for m in sorted(pats, key=score, reverse=True):
            new_domains = [list(d) for d in domains]
            new_domains[r] = [m]
            ans = search(new_domains)
            if ans is not None:
                return ans
        return None

    result = search(row_domains)
    if result is None:
        return "No Solution"
    return format_grid(result, n_rows, n_cols)

if __name__ == "__main__":
    print(solve(OBSERVATION))

