# Star Battle 1-star solver with strong propagation and lightweight search.
# The observation is parsed from the image into a region-id grid.

from collections import defaultdict
import ast

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Build region -> cells mapping and validate exactly n regions for 1-star NxN.
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            region_cells[data[r][c]].append((r, c))
    region_ids = sorted(region_cells)
    if len(region_ids) != n:
        # Generalized expectation for 1-star puzzle: exactly N regions.
        return "No Solution"

    region_index = {rid: i for i, rid in enumerate(region_ids)}

    # Index each cell.
    cell_index = {}
    index_cell = []
    for r in range(n):
        for c in range(n):
            idx = len(index_cell)
            cell_index[(r, c)] = idx
            index_cell.append((r, c))
    m = n * n

    # Bit utilities.
    ALL = (1 << m) - 1
    row_masks = [0] * n
    col_masks = [0] * n
    reg_masks = [0] * n
    neighbor_masks = [0] * m

    for r in range(n):
        for c in range(n):
            idx = cell_index[(r, c)]
            bit = 1 << idx
            row_masks[r] |= bit
            col_masks[c] |= bit
            reg_masks[region_index[data[r][c]]] |= bit

    for r in range(n):
        for c in range(n):
            idx = cell_index[(r, c)]
            mask = 0
            for dr in (-1, 0, 1):
                rr = r + dr
                if 0 <= rr < n:
                    for dc in (-1, 0, 1):
                        cc = c + dc
                        if 0 <= cc < n and not (dr == 0 and dc == 0):
                            mask |= 1 << cell_index[(rr, cc)]
            neighbor_masks[idx] = mask

    constraints = []
    for r in range(n):
        constraints.append(("row", r, row_masks[r]))
    for c in range(n):
        constraints.append(("col", c, col_masks[c]))
    for k in range(n):
        constraints.append(("reg", k, reg_masks[k]))

    # Precompute cell -> involved constraints.
    cell_constraints = [[] for _ in range(m)]
    for ci, (_, _, cmask) in enumerate(constraints):
        x = cmask
        while x:
            b = x & -x
            idx = b.bit_length() - 1
            cell_constraints[idx].append(ci)
            x ^= b

    full_constraint_count = len(constraints)

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def popcount(x):
        return x.bit_count()

    # Propagation state:
    # avail_mask: cells still allowed to be stars
    # star_mask: cells fixed as stars
    # sat_mask: bit i means constraint i already has its unique star placed
    #
    # Human-like deductions encoded:
    # 1) If a row/col/region has one possible place left -> place star there.
    # 2) If a row/col/region already has a star -> all others in it removed.
    # 3) If a cell is impossible due to star adjacency or line/region completion -> remove.
    # 4) Hall-like subset rule among rows/cols/regions:
    #    if k unsatisfied constraints of same type share exactly k candidate cells, those cells
    #    are reserved for them and can be removed from other same-type constraints.
    # 5) Cross-constraint forcing:
    #    if all candidates of a constraint lie in one other unsatisfied constraint, that other
    #    must take its star inside that set too; if set size 1 then immediate placement.
    #
    # Search uses MRV on unsatisfied constraint with smallest candidate count.

    def choose_single_bit(mask):
        if mask and (mask & (mask - 1)) == 0:
            return mask.bit_length() - 1
        return None

    def place_star(idx, avail_mask, star_mask, sat_mask):
        bit = 1 << idx
        if not (avail_mask & bit):
            return None
        if star_mask & neighbor_masks[idx]:
            return None

        # Any involved constraint already satisfied by a different star => impossible.
        for ci in cell_constraints[idx]:
            if (sat_mask >> ci) & 1:
                cmask = constraints[ci][2]
                if not (star_mask & cmask & bit):
                    return None

        new_star_mask = star_mask | bit
        forbidden = neighbor_masks[idx] | bit

        # Satisfy row/col/region containing this cell, removing all other cells in those constraints.
        new_sat_mask = sat_mask
        for ci in cell_constraints[idx]:
            new_sat_mask |= (1 << ci)
            forbidden |= constraints[ci][2] & ~bit

        new_avail_mask = avail_mask & ~forbidden

        # Verify no existing star got accidentally removed conceptually.
        if new_star_mask & ~ (new_avail_mask | new_star_mask):
            return None
        return new_avail_mask, new_star_mask, new_sat_mask

    def remove_cell(idx, avail_mask, star_mask, sat_mask):
        bit = 1 << idx
        if not (avail_mask & bit):
            return avail_mask, star_mask, sat_mask
        if star_mask & bit:
            return None
        new_avail = avail_mask & ~bit
        return new_avail, star_mask, sat_mask

    def candidate_mask_for_constraint(ci, avail_mask, star_mask, sat_mask):
        typ, ident, cmask = constraints[ci]
        if (sat_mask >> ci) & 1:
            return star_mask & cmask
        return avail_mask & cmask

    def propagate(avail_mask, star_mask, sat_mask):
        changed = True
        while changed:
            changed = False

            # Basic feasibility / singles.
            for ci in range(full_constraint_count):
                cand = candidate_mask_for_constraint(ci, avail_mask, star_mask, sat_mask)
                cnt = popcount(cand)
                if cnt == 0:
                    return None
                if not ((sat_mask >> ci) & 1):
                    if cnt == 1:
                        idx = cand.bit_length() - 1
                        res = place_star(idx, avail_mask, star_mask, sat_mask)
                        if res is None:
                            return None
                        na, ns, nm = res
                        if na != avail_mask or ns != star_mask or nm != sat_mask:
                            avail_mask, star_mask, sat_mask = na, ns, nm
                            changed = True

            # Adjacency consistency and duplicate stars in same row/col/region.
            for ci, (_, _, cmask) in enumerate(constraints):
                stars_here = popcount(star_mask & cmask)
                if stars_here > 1:
                    return None
                if stars_here == 1 and not ((sat_mask >> ci) & 1):
                    sat_mask |= (1 << ci)
                    changed = True

            # Hall-like subset elimination within same-type unsatisfied constraints.
            for base in ("row", "col", "reg"):
                groups = []
                for ci, (typ, ident, cmask) in enumerate(constraints):
                    if typ != base or ((sat_mask >> ci) & 1):
                        continue
                    cand = avail_mask & cmask
                    groups.append((ci, cand))
                    if cand == 0:
                        return None

                # Map candidate set -> constraints sharing it.
                by_mask = defaultdict(list)
                for ci, cand in groups:
                    by_mask[cand].append(ci)

                # Exact Hall equality for identical masks.
                for mask, cis in by_mask.items():
                    k = len(cis)
                    if k > 0 and popcount(mask) == k:
                        # These cells are reserved for these k constraints:
                        # remove them from all other unsatisfied constraints of same type.
                        for ci, cand in groups:
                            if ci in cis:
                                continue
                            rem = cand & mask
                            if rem:
                                x = rem
                                while x:
                                    b = x & -x
                                    idx = b.bit_length() - 1
                                    res = remove_cell(idx, avail_mask, star_mask, sat_mask)
                                    if res is None:
                                        return None
                                    na, ns, nm = res
                                    x ^= b
                                    if na != avail_mask or ns != star_mask or nm != sat_mask:
                                        avail_mask, star_mask, sat_mask = na, ns, nm
                                        changed = True

                # Small subset Hall rule on merged masks (pairs/triples only for speed).
                g_len = len(groups)
                # Pairs
                for i in range(g_len):
                    ci1, m1 = groups[i]
                    for j in range(i + 1, g_len):
                        ci2, m2 = groups[j]
                        u = m1 | m2
                        if popcount(u) == 2:
                            for ci, cand in groups:
                                if ci == ci1 or ci == ci2:
                                    continue
                                rem = cand & u
                                if rem:
                                    x = rem
                                    while x:
                                        b = x & -x
                                        idx = b.bit_length() - 1
                                        res = remove_cell(idx, avail_mask, star_mask, sat_mask)
                                        if res is None:
                                            return None
                                        na, ns, nm = res
                                        x ^= b
                                        if na != avail_mask or ns != star_mask or nm != sat_mask:
                                            avail_mask, star_mask, sat_mask = na, ns, nm
                                            changed = True
                # Triples
                for i in range(g_len):
                    ci1, m1 = groups[i]
                    for j in range(i + 1, g_len):
                        ci2, m2 = groups[j]
                        u12 = m1 | m2
                        if popcount(u12) > 3:
                            continue
                        for k in range(j + 1, g_len):
                            ci3, m3 = groups[k]
                            u = u12 | m3
                            if popcount(u) == 3:
                                for ci, cand in groups:
                                    if ci == ci1 or ci == ci2 or ci == ci3:
                                        continue
                                    rem = cand & u
                                    if rem:
                                        x = rem
                                        while x:
                                            b = x & -x
                                            idx = b.bit_length() - 1
                                            res = remove_cell(idx, avail_mask, star_mask, sat_mask)
                                            if res is None:
                                                return None
                                            na, ns, nm = res
                                            x ^= b
                                            if na != avail_mask or ns != star_mask or nm != sat_mask:
                                                avail_mask, star_mask, sat_mask = na, ns, nm
                                                changed = True

            # Cross forcing: if candidates of one constraint all lie inside exactly one other
            # unsatisfied constraint's candidate set relationship, exploit immediate implications.
            unsat = [ci for ci in range(full_constraint_count) if not ((sat_mask >> ci) & 1)]
            cands = {ci: avail_mask & constraints[ci][2] for ci in unsat}
            for ci in unsat:
                mi = cands[ci]
                if mi == 0:
                    return None
                typ_i, id_i, _ = constraints[ci]
                for cj in unsat:
                    if ci == cj:
                        continue
                    typ_j, id_j, _ = constraints[cj]
                    if typ_i == typ_j:
                        continue
                    mj = cands[cj]
                    inter = mi & mj
                    if inter == mi:
                        # ci's star must be in inter. Therefore cells of cj outside inter
                        # can be removed if cj can only be satisfied simultaneously there? No.
                        # Safe stronger rule: if inter is singleton, place it.
                        sb = choose_single_bit(inter)
                        if sb is not None:
                            res = place_star(sb, avail_mask, star_mask, sat_mask)
                            if res is None:
                                return None
                            na, ns, nm = res
                            if na != avail_mask or ns != star_mask or nm != sat_mask:
                                avail_mask, star_mask, sat_mask = na, ns, nm
                                changed = True

        # Final consistency.
        if popcount(star_mask) > n:
            return None
        return avail_mask, star_mask, sat_mask

    def solved(star_mask, sat_mask):
        return popcount(star_mask) == n and sat_mask == (1 << full_constraint_count) - 1

    def select_branch_constraint(avail_mask, sat_mask):
        best_ci = None
        best_mask = None
        best_count = 10**9
        # Prefer unsatisfied constraint with minimum candidates.
        for ci in range(full_constraint_count):
            if (sat_mask >> ci) & 1:
                continue
            cand = avail_mask & constraints[ci][2]
            cnt = popcount(cand)
            if cnt < best_count:
                best_count = cnt
                best_ci = ci
                best_mask = cand
                if cnt <= 2:
                    break
        return best_ci, best_mask

    def order_candidates(mask):
        # Human-style: prefer cells that constrain the most neighboring/line possibilities.
        scored = []
        for idx in bit_iter(mask):
            r, c = index_cell[idx]
            score = popcount(neighbor_masks[idx]) + popcount(row_masks[r]) + popcount(col_masks[c]) + popcount(reg_masks[region_index[data[r][c]]])
            scored.append((-score, idx))
        scored.sort()
        return [idx for _, idx in scored]

    def dfs(avail_mask, star_mask, sat_mask, depth=0):
        state = propagate(avail_mask, star_mask, sat_mask)
        if state is None:
            return None
        avail_mask, star_mask, sat_mask = state

        if solved(star_mask, sat_mask):
            return star_mask

        ci, cand = select_branch_constraint(avail_mask, sat_mask)
        if ci is None or cand == 0:
            return None

        # Try placing star in candidate cells; no blind "not this cell" branching.
        # Strong propagation after each forced placement handles eliminations.
        for idx in order_candidates(cand):
            res = place_star(idx, avail_mask, star_mask, sat_mask)
            if res is None:
                continue
            ans = dfs(*res, depth + 1)
            if ans is not None:
                return ans
        return None

    ans_mask = dfs(ALL, 0, 0)
    if ans_mask is None:
        return "No Solution"

    out = [[None for _ in range(n)] for _ in range(n)]
    for idx in bit_iter(ans_mask):
        r, c = index_cell[idx]
        out[r][c] = 'S'
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, 'W', None, None, 'W', None, 'W', None], ['B', None, None, None, None, 'W', 'W', None], [None, None, 'W', None, None, None, 'W', None], [None, None, None, None, None, 'B', None, 'W'], [None, None, 'W', 'W', None, None, None, None], [None, 'W', None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B']]}

# General Masyu solver on an N x N dot grid.
# Clues are placed on dots.
# We choose undirected edges between orthogonally adjacent dots so that:
# - every used dot has degree 2
# - clue dots are used
# - non-clue dots may be unused or degree 2
# - all used edges form a single simple cycle
# - white clue: path goes straight through the clue, and turns immediately before or after
# - black clue: path turns at the clue, and goes straight immediately before and after

from collections import deque, defaultdict

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0:
        return "No Solution"

    cells = [(r, c) for r in range(n) for c in range(n)]
    clues = {(r, c): data[r][c] for r in range(n) for c in range(n) if data[r][c] in ("W", "B")}

    neighbors = {}
    for r, c in cells:
        nbrs = []
        for d, (dr, dc) in enumerate(DIRS):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n:
                nbrs.append((d, (rr, cc)))
        neighbors[(r, c)] = nbrs

    edge_id = {}
    edges = []
    inc_edges = {p: [] for p in cells}
    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                a, b = (r, c), (r, c + 1)
                i = len(edges)
                edges.append((a, b))
                edge_id[tuple(sorted((a, b)))] = i
                inc_edges[a].append(i)
                inc_edges[b].append(i)
            if r + 1 < n:
                a, b = (r, c), (r + 1, c)
                i = len(edges)
                edges.append((a, b))
                edge_id[tuple(sorted((a, b)))] = i
                inc_edges[a].append(i)
                inc_edges[b].append(i)

    # Directional edge lookup
    edge_from_dir = {}
    for p in cells:
        mp = {}
        r, c = p
        for d, q in neighbors[p]:
            mp[d] = edge_id[tuple(sorted((p, q)))]
        edge_from_dir[p] = mp

    # Domain of local patterns for each dot:
    # each pattern is a tuple of two directions used at the dot (sorted), or empty tuple for unused.
    # Clues must be used, non-clues can be unused.
    domains = {}
    for p in cells:
        avail_dirs = sorted(edge_from_dir[p].keys())
        pats = []
        if p not in clues:
            pats.append(())
        for i in range(len(avail_dirs)):
            for j in range(i + 1, len(avail_dirs)):
                pats.append((avail_dirs[i], avail_dirs[j]))
        domains[p] = set(pats)

    # Initial clue filtering from local geometry
    for p, t in clues.items():
        domains[p] = {pat for pat in domains[p] if pat}
        domains[p] = {pat for pat in domains[p] if clue_pattern_possible(p, pat, t, n)}
        if not domains[p]:
            return "No Solution"

    # State
    # edge_state[e] in {-1 unknown, 0 off, 1 on}
    edge_state = [-1] * len(edges)

    # Precompute which patterns imply edge on/off
    pattern_edges = {}
    for p in cells:
        pedges = {}
        for pat in domains[p]:
            used = set(edge_from_dir[p][d] for d in pat) if pat else set()
            pedges[pat] = used
        pattern_edges[p] = pedges

    # Queue-based propagation
    state = {
        "domains": {p: set(v) for p, v in domains.items()},
        "edge_state": edge_state[:],
    }

    if not propagate_all(state, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
        return "No Solution"

    sol = search(state, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n)
    if sol is None:
        return "No Solution"

    path = extract_cycle_path(sol["edge_state"], edges, inc_edges, clues)
    if path is None:
        return "No Solution"
    return str(path)


def clue_pattern_possible(p, pat, clue_type, n):
    r, c = p
    if len(pat) != 2:
        return False
    a, b = pat
    straight = (a + 2) % 4 == b
    if clue_type == "W":
        return straight
    if clue_type == "B":
        return not straight
    return True


def is_straight_pat(pat):
    if len(pat) != 2:
        return False
    a, b = pat
    return (a + 2) % 4 == b


def step_pos(p, d):
    return (p[0] + DIRS[d][0], p[1] + DIRS[d][1])


def propagate_all(state, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
    q_cells = deque(cells)
    q_edges = deque(range(len(edges)))
    in_qc = {p: True for p in cells}
    in_qe = {e: True for e in range(len(edges))}

    while q_cells or q_edges:
        while q_cells:
            p = q_cells.popleft()
            in_qc[p] = False
            if not revise_cell_domain(state, p, clues, edge_from_dir, pattern_edges, n):
                return False
            # If edge implications changed, we need to queue incident edges and neighboring cells
            for e in inc_edges[p]:
                if not in_qe.get(e, False):
                    q_edges.append(e)
                    in_qe[e] = True
            for _, q in neighbor_dirs_of_cell(p, edge_from_dir):
                if not in_qc.get(q, False):
                    q_cells.append(q)
                    in_qc[q] = True

        while q_edges:
            e = q_edges.popleft()
            in_qe[e] = False
            a, b = edges[e]
            if not enforce_edge_consistency(state, e, a, b, pattern_edges):
                return False
            for p in (a, b):
                if not in_qc.get(p, False):
                    q_cells.append(p)
                    in_qc[p] = True

        # stronger global deductions
        changed = True
        while changed:
            changed = False
            if not apply_degree_forcing(state, cells, inc_edges):
                return False
            if not apply_clue_chain_rules(state, clues, edge_from_dir, pattern_edges, n):
                return False
            if not prevent_small_closed_components(state, cells, edges, inc_edges, clues):
                return False

            # Requeue everything touched conservatively
            for p in cells:
                if not in_qc.get(p, False):
                    q_cells.append(p)
                    in_qc[p] = True
            for e in range(len(edges)):
                if not in_qe.get(e, False):
                    q_edges.append(e)
                    in_qe[e] = True
            changed = False
            # Single pass per outer iteration is enough because queues handle cascading.
            break
    return final_feasibility_check(state, cells, clues, inc_edges, edges)


def neighbor_dirs_of_cell(p, edge_from_dir):
    for d in edge_from_dir[p]:
        yield d, step_pos(p, d)


def revise_cell_domain(state, p, clues, edge_from_dir, pattern_edges, n):
    dom = state["domains"][p]
    es = state["edge_state"]
    new_dom = set()

    for pat in dom:
        used = pattern_edges[p][pat]
        ok = True
        for d, e in edge_from_dir[p].items():
            st = es[e]
            want = 1 if e in used else 0
            if st != -1 and st != want:
                ok = False
                break
        if not ok:
            continue

        if p in clues:
            t = clues[p]
            if not clue_future_feasible(p, pat, t, state, edge_from_dir, n):
                continue

        new_dom.add(pat)

    if not new_dom:
        return False

    if new_dom != dom:
        state["domains"][p] = new_dom

    # If all remaining patterns agree on some edge, assign it
    forced = edge_forcing_from_domain(p, state["domains"][p], edge_from_dir, pattern_edges)
    for e, val in forced.items():
        if not assign_edge(state, e, val):
            return False
    return True


def edge_forcing_from_domain(p, dom, edge_from_dir, pattern_edges):
    res = {}
    all_edges = set(edge_from_dir[p].values())
    for e in all_edges:
        vals = set()
        for pat in dom:
            vals.add(1 if e in pattern_edges[p][pat] else 0)
        if len(vals) == 1:
            res[e] = next(iter(vals))
    return res


def enforce_edge_consistency(state, e, a, b, pattern_edges):
    st = state["edge_state"][e]
    if st == -1:
        # If one endpoint cannot support on/off, force.
        poss = []
        for val in (0, 1):
            ok = True
            for p in (a, b):
                found = False
                for pat in state["domains"][p]:
                    used = pattern_edges[p][pat]
                    if (e in used) == (val == 1):
                        found = True
                        break
                if not found:
                    ok = False
                    break
            poss.append(ok)
        if poss == [False, False]:
            return False
        if poss == [True, False]:
            return assign_edge(state, e, 0)
        if poss == [False, True]:
            return assign_edge(state, e, 1)
        return True

    for p in (a, b):
        nd = set()
        for pat in state["domains"][p]:
            used = pattern_edges[p][pat]
            if (e in used) == (st == 1):
                nd.add(pat)
        if not nd:
            return False
        state["domains"][p] = nd
    return True


def assign_edge(state, e, val):
    cur = state["edge_state"][e]
    if cur == val:
        return True
    if cur != -1 and cur != val:
        return False
    state["edge_state"][e] = val
    return True


def clue_future_feasible(p, pat, clue_type, state, edge_from_dir, n):
    # Human-like local look-ahead:
    # White: straight here, and at least one adjacent dot along the path must be able to turn.
    # Black: turn here, and each adjacent dot along the path must be able to continue straight.
    dirs = list(pat)
    if clue_type == "W":
        if not is_straight_pat(pat):
            return False
        can_turn_prev = False
        can_turn_next = False
        for d in dirs:
            q = step_pos(p, d)
            if not (0 <= q[0] < n and 0 <= q[1] < n):
                return False
            if neighbor_can_be_turn(q, OPP[d], state, edge_from_dir):
                if d == dirs[0]:
                    can_turn_prev = True
                else:
                    can_turn_next = True
        return can_turn_prev or can_turn_next

    if clue_type == "B":
        if is_straight_pat(pat):
            return False
        for d in dirs:
            q = step_pos(p, d)
            if not (0 <= q[0] < n and 0 <= q[1] < n):
                return False
            if not neighbor_can_be_straight(q, OPP[d], state, edge_from_dir):
                return False
        return True
    return True


def neighbor_can_be_turn(q, incoming_dir, state, edge_from_dir):
    # At q, a turning pattern using edge incoming_dir
    for pat in state["domains"][q]:
        if len(pat) != 2:
            continue
        if incoming_dir not in pat:
            continue
        if not is_straight_pat(pat):
            return True
    return False


def neighbor_can_be_straight(q, incoming_dir, state, edge_from_dir):
    # At q, a straight pattern using edge incoming_dir
    for pat in state["domains"][q]:
        if len(pat) != 2:
            continue
        if incoming_dir not in pat:
            continue
        if is_straight_pat(pat):
            return True
    return False


def apply_degree_forcing(state, cells, inc_edges):
    # Dot degree must be either 0 or 2; clues exactly 2 because no empty pattern remains there.
    for p in cells:
        vals = [state["edge_state"][e] for e in inc_edges[p]]
        on = sum(1 for v in vals if v == 1)
        unk = sum(1 for v in vals if v == -1)
        if on > 2:
            return False
        if on == 1 and unk == 0:
            return False
        if on + unk < 2 and any(len(pat) == 2 for pat in state["domains"][p]):
            # no way to realize used dot
            if () not in state["domains"][p]:
                return False
        # If already 2 on, rest must be off
        if on == 2:
            for e in inc_edges[p]:
                if state["edge_state"][e] == -1:
                    if not assign_edge(state, e, 0):
                        return False
        # If on==1 and only one unknown, that unknown must be on
        if on == 1 and unk == 1:
            for e in inc_edges[p]:
                if state["edge_state"][e] == -1:
                    if not assign_edge(state, e, 1):
                        return False
        # If on==0 and unk==2 and empty pattern impossible, both must be on
        if on == 0 and unk == 2 and () not in state["domains"][p]:
            for e in inc_edges[p]:
                if state["edge_state"][e] == -1:
                    if not assign_edge(state, e, 1):
                        return False
    return True


def apply_clue_chain_rules(state, clues, edge_from_dir, pattern_edges, n):
    # Stronger direct implications from clue domains.
    for p, t in clues.items():
        dom = state["domains"][p]
        if len(dom) == 1:
            pat = next(iter(dom))
            dirs = list(pat)
            if t == "W":
                # neighbors on the line: at least one must turn; sometimes one side impossible => other forced
                possible = []
                for d in dirs:
                    q = step_pos(p, d)
                    possible.append(neighbor_can_be_turn(q, OPP[d], state, edge_from_dir))
                if not any(possible):
                    return False
            elif t == "B":
                # both sides must be straight-capable
                for d in dirs:
                    q = step_pos(p, d)
                    if not neighbor_can_be_straight(q, OPP[d], state, edge_from_dir):
                        return False
    return True


def prevent_small_closed_components(state, cells, edges, inc_edges, clues):
    # On-edges cannot already form a closed component unless it includes all used cells
    # and all clues are satisfied. During search, forbid premature isolated cycles.
    adj_on = defaultdict(list)
    used_vertices = set()
    for i, (a, b) in enumerate(edges):
        if state["edge_state"][i] == 1:
            adj_on[a].append(b)
            adj_on[b].append(a)
            used_vertices.add(a)
            used_vertices.add(b)

    seen = set()
    comps = []
    for v in used_vertices:
        if v in seen:
            continue
        stack = [v]
        seen.add(v)
        comp = set([v])
        edge_count_twice = 0
        while stack:
            x = stack.pop()
            edge_count_twice += len(adj_on[x])
            for y in adj_on[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
                    comp.add(y)
        comps.append((comp, edge_count_twice // 2))

    if len(comps) <= 1:
        return True

    # If any component is already a full cycle separated from others, impossible.
    for comp, ecount in comps:
        deg2 = all(len(adj_on[v]) == 2 for v in comp)
        if deg2 and ecount == len(comp):
            return False
    return True


def final_feasibility_check(state, cells, clues, inc_edges, edges):
    for p in cells:
        if not state["domains"][p]:
            return False
    for e, st in enumerate(state["edge_state"]):
        if st not in (-1, 0, 1):
            return False
    return True


def search(state, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
    if all(state["edge_state"][e] != -1 for e in range(len(edges))) and all(len(state["domains"][p]) == 1 for p in cells):
        if is_complete_valid(state, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
            return state
        return None

    # Branch on most constrained cell domain >1, otherwise edge.
    p = select_branch_cell(state, cells)
    if p is not None:
        options = sorted(state["domains"][p], key=pattern_rank)
        for pat in options:
            ns = clone_state(state)
            ns["domains"][p] = {pat}
            if propagate_all(ns, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
                ans = search(ns, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n)
                if ans is not None:
                    return ans
        return None

    e = select_branch_edge(state, edges)
    if e is None:
        return None
    for val in (1, 0):
        ns = clone_state(state)
        if assign_edge(ns, e, val) and propagate_all(ns, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
            ans = search(ns, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n)
            if ans is not None:
                return ans
    return None


def clone_state(state):
    return {
        "domains": {p: set(v) for p, v in state["domains"].items()},
        "edge_state": state["edge_state"][:],
    }


def pattern_rank(pat):
    if pat == ():
        return 2
    return 0 if len(pat) == 2 else 1


def select_branch_cell(state, cells):
    best = None
    best_size = 10**9
    for p in cells:
        k = len(state["domains"][p])
        if 1 < k < best_size:
            best = p
            best_size = k
    return best


def select_branch_edge(state, edges):
    for i in range(len(edges)):
        if state["edge_state"][i] == -1:
            return i
    return None


def is_complete_valid(state, cells, clues, edge_from_dir, inc_edges, edges, pattern_edges, n):
    # Every cell must realize exactly one pattern
    chosen = {}
    for p in cells:
        if len(state["domains"][p]) != 1:
            return False
        chosen[p] = next(iter(state["domains"][p]))

    # Edge agreement
    for i, (a, b) in enumerate(edges):
        sa = i in pattern_edges[a][chosen[a]]
        sb = i in pattern_edges[b][chosen[b]]
        if sa != sb:
            return False
        if state["edge_state"][i] != (1 if sa else 0):
            return False

    # Degrees 0/2 and clues used
    for p in cells:
        deg = sum(1 for e in inc_edges[p] if state["edge_state"][e] == 1)
        if chosen[p] == ():
            if deg != 0:
                return False
        else:
            if deg != 2:
                return False

    for p, t in clues.items():
        pat = chosen[p]
        if t == "W":
            if not is_straight_pat(pat):
                return False
            dirs = list(pat)
            turns = []
            for d in dirs:
                q = step_pos(p, d)
                qpat = chosen[q]
                if qpat == ():
                    return False
                turns.append(not is_straight_pat(qpat))
            if not any(turns):
                return False
        elif t == "B":
            if is_straight_pat(pat):
                return False
            for d in pat:
                q = step_pos(p, d)
                qpat = chosen[q]
                if qpat == () or not is_straight_pat(qpat):
                    return False

    # Single cycle
    adj = defaultdict(list)
    used = set()
    for i, (a, b) in enumerate(edges):
        if state["edge_state"][i] == 1:
            adj[a].append(b)
            adj[b].append(a)
            used.add(a)
            used.add(b)
    if not used:
        return False
    if any(len(adj[v]) != 2 for v in used):
        return False
    start = next(iter(used))
    seen = set()
    stack = [start]
    while stack:
        x = stack.pop()
        if x in seen:
            continue
        seen.add(x)
        for y in adj[x]:
            if y not in seen:
                stack.append(y)
    if seen != used:
        return False
    for p in clues:
        if p not in used:
            return False
    return True


def extract_cycle_path(edge_state, edges, inc_edges, clues):
    adj = defaultdict(list)
    used = set()
    for i, (a, b) in enumerate(edges):
        if edge_state[i] == 1:
            adj[a].append(b)
            adj[b].append(a)
            used.add(a)
            used.add(b)
    if not used:
        return None
    for v in used:
        if len(adj[v]) != 2:
            return None

    # Prefer starting from a clue if possible
    start = None
    for p in clues:
        if p in used:
            start = p
            break
    if start is None:
        start = min(used)

    path = [start]
    prev = None
    cur = start
    while True:
        nxts = adj[cur]
        if prev is None:
            nxt = min(nxts)
        else:
            nxt = nxts[0] if nxts[1] == prev else nxts[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break

    # Verify simple cycle uses all used vertices
    if len(set(path[:-1])) != len(used):
        return None
    return path


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [9, 8, 18, 5, 5, 10, 15, 5, 25], 'col_sum': [13, 18, 8, 19, 20, 16, 1, 14, 10]}

from functools import lru_cache

# This puzzle is a weighted 0/1 matrix problem:
# - If cell (r, c) is black, row r contributes column-weight (c+1) to row target,
#   and column c contributes row-weight (r+1) to column target.
# Hence:
#   sum_{c black in row r} (c+1) == row_sum[r]
#   sum_{r black in col c} (r+1) == col_sum[c]
#
# Human-like deduction strategy encoded here:
# 1) For each row, enumerate only subsets of columns whose column-weights sum to the row target.
# 2) Maintain remaining column targets while assigning rows.
# 3) Repeatedly filter row candidates by column feasibility:
#    - a candidate is impossible if it overfills any column
#    - for each column, the remaining rows must still be able to achieve exactly the residual target
# 4) Branch on the most constrained row.
#
# Key optimization:
# For each column independently, precompute subset-sum bitsets over suffixes of rows using each row's weight.
# This allows fast "can remaining unassigned rows realize residual target in this column?" checks.

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n = len(row_sum)
    m = len(col_sum)

    row_weights = [r + 1 for r in range(n)]
    col_weights = [c + 1 for c in range(m)]

    # Enumerate all subsets of columns for each row target.
    row_candidates = []
    for target in row_sum:
        cands = []
        for mask in range(1 << m):
            s = 0
            mm = mask
            idx = 0
            while mm:
                if mm & 1:
                    s += col_weights[idx]
                    if s > target:
                        break
                idx += 1
                mm >>= 1
            else:
                if s == target:
                    cands.append(mask)
                continue
            # if broken, still need to consider exact sum impossible
            # no action needed
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    # Column totals are sums of selected row weights.
    max_col_target = max(col_sum) if col_sum else 0
    total_row_weight = sum(row_weights)

    # Precompute suffix subset-sum bitsets per column under row availability only.
    # Since any future row may choose to include/exclude the column independently,
    # the possible added amount to a fixed column from rows i..n-1 is any subset sum
    # of row_weights[i:].
    suffix_bits = [0] * (n + 1)
    suffix_bits[n] = 1  # only sum 0 possible
    for i in range(n - 1, -1, -1):
        w = row_weights[i]
        suffix_bits[i] = suffix_bits[i + 1] | (suffix_bits[i + 1] << w)

    # Quick global consistency: each column target must be achievable as subset sum of row weights.
    full_bits = suffix_bits[0]
    for t in col_sum:
        if t < 0 or ((full_bits >> t) & 1) == 0:
            return "No Solution"

    # Candidate masks as tuples for immutability/cache friendliness.
    row_candidates = [tuple(cands) for cands in row_candidates]

    # Initial filtering by simple per-column overfill and future-achievability.
    def filter_all(remaining, domains, assigned):
        changed = True
        domains = list(domains)
        while changed:
            changed = False

            # Remove candidates that immediately overfill columns.
            for r in range(n):
                if assigned[r]:
                    continue
                new_dom = []
                for mask in domains[r]:
                    ok = True
                    for c in range(m):
                        if (mask >> c) & 1 and remaining[c] < row_weights[r]:
                            ok = False
                            break
                    if ok:
                        new_dom.append(mask)
                if not new_dom:
                    return None
                if len(new_dom) != len(domains[r]):
                    domains[r] = tuple(new_dom)
                    changed = True

            # Strong per-column feasibility:
            # Let mandatory contribution from undecided rows to column c be min_possible,
            # and optional max_possible be max_possible. Residual after assignments
            # must lie within [min_possible, max_possible], and exactness is checked by
            # recursive search later. Here we derive min/max from row domains.
            min_add = [0] * m
            max_add = [0] * m
            for r in range(n):
                if assigned[r]:
                    continue
                dom = domains[r]
                if len(dom) == 1:
                    mask0 = dom[0]
                    for c in range(m):
                        if (mask0 >> c) & 1:
                            min_add[c] += row_weights[r]
                            max_add[c] += row_weights[r]
                else:
                    any1 = [False] * m
                    all1 = [True] * m
                    for mask in dom:
                        for c in range(m):
                            bit = (mask >> c) & 1
                            any1[c] = any1[c] or bool(bit)
                            all1[c] = all1[c] and bool(bit)
                    for c in range(m):
                        if all1[c]:
                            min_add[c] += row_weights[r]
                        if any1[c]:
                            max_add[c] += row_weights[r]

            for c in range(m):
                if remaining[c] < min_add[c] or remaining[c] > max_add[c]:
                    return None

            # Candidate-level lookahead:
            # For each row candidate, after fixing it, each column residual must remain
            # subset-sum achievable by suffix rows, but we tighten using actual domains:
            # if a future row can never place black in column c, its weight is unavailable there.
            future_possible_bits = [1] * m
            for c in range(m):
                bits = 1
                for r in range(n - 1, -1, -1):
                    if assigned[r]:
                        continue
                    can_use = False
                    if len(domains[r]) == 1:
                        can_use = ((domains[r][0] >> c) & 1) == 1
                    else:
                        for mask in domains[r]:
                            if (mask >> c) & 1:
                                can_use = True
                                break
                    if can_use:
                        bits = bits | (bits << row_weights[r])
                future_possible_bits[c] = bits

            for r in range(n):
                if assigned[r]:
                    continue
                new_dom = []
                for mask in domains[r]:
                    ok = True
                    for c in range(m):
                        rem = remaining[c] - (row_weights[r] if ((mask >> c) & 1) else 0)
                        if rem < 0:
                            ok = False
                            break
                        # Necessary condition: rem achievable by some subset of other unassigned rows
                        # that can still place in this column.
                        bits = 1
                        for rr in range(n):
                            if rr == r or assigned[rr]:
                                continue
                            can_use = False
                            if len(domains[rr]) == 1:
                                can_use = ((domains[rr][0] >> c) & 1) == 1
                            else:
                                for mm in domains[rr]:
                                    if (mm >> c) & 1:
                                        can_use = True
                                        break
                            if can_use:
                                bits = bits | (bits << row_weights[rr])
                        if ((bits >> rem) & 1) == 0:
                            ok = False
                            break
                    if ok:
                        new_dom.append(mask)
                if not new_dom:
                    return None
                if len(new_dom) != len(domains[r]):
                    domains[r] = tuple(new_dom)
                    changed = True

        return tuple(domains)

    init_domains = tuple(row_candidates)
    assigned0 = tuple(False for _ in range(n))
    filtered = filter_all(tuple(col_sum), init_domains, assigned0)
    if filtered is None:
        return "No Solution"

    @lru_cache(maxsize=None)
    def dfs(remaining, domains, assigned):
        remaining = list(remaining)
        assigned = list(assigned)
        domains = list(domains)

        # Finished?
        done = True
        for a in assigned:
            if not a:
                done = False
                break
        if done:
            if all(x == 0 for x in remaining):
                return ()
            return None

        # Choose most constrained unassigned row.
        best_r = -1
        best_score = None
        for r in range(n):
            if not assigned[r]:
                score = len(domains[r])
                if best_score is None or score < best_score:
                    best_score = score
                    best_r = r
                if score == 1:
                    break

        r = best_r
        # Heuristic: try candidates that consume larger scarce column residuals first.
        def cand_key(mask):
            score = 0
            for c in range(m):
                if (mask >> c) & 1:
                    score -= remaining[c]
            return score

        for mask in sorted(domains[r], key=cand_key):
            new_remaining = remaining[:]
            ok = True
            w = row_weights[r]
            for c in range(m):
                if (mask >> c) & 1:
                    new_remaining[c] -= w
                    if new_remaining[c] < 0:
                        ok = False
                        break
            if not ok:
                continue

            new_domains = domains[:]
            new_domains[r] = (mask,)
            new_assigned = assigned[:]
            new_assigned[r] = True

            pruned = filter_all(tuple(new_remaining), tuple(new_domains), tuple(new_assigned))
            if pruned is None:
                continue

            res = dfs(tuple(new_remaining), pruned, tuple(new_assigned))
            if res is not None:
                return ((r, mask),) + res

        return None

    result = dfs(tuple(col_sum), filtered, assigned0)
    if result is None:
        return "No Solution"

    row_to_mask = [0] * n
    for r, mask in result:
        row_to_mask[r] = mask

    grid = []
    for r in range(n):
        row = []
        mask = row_to_mask[r]
        for c in range(m):
            row.append('B' if ((mask >> c) & 1) else None)
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, 2, None, None, None, 2, None], [2, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, 6], [None, 1, None, None, None, 3, None], [None, None, None, None, None, None, None]]}

from collections import deque, defaultdict

# General Nurikabe solver with strong propagation and bounded search.
# Output format: stringified Python list-of-lists using 'B' for black and None for white.

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    grid = observation["data"]
    solver = NurikabeSolver(grid)
    ans = solver.run()
    if ans is None:
        return "No Solution"
    out = []
    for r in range(solver.R):
        row = []
        for c in range(solver.C):
            row.append('B' if ans[r][c] == BLACK else None)
        out.append(row)
    return repr(out)


class NurikabeSolver:
    def __init__(self, clues):
        self.clues = clues
        self.R = len(clues)
        self.C = len(clues[0]) if self.R else 0
        self.cells = [(r, c) for r in range(self.R) for c in range(self.C)]
        self.idx = {(r, c): r * self.C + c for r, c in self.cells}
        self.nbrs = {}
        for r, c in self.cells:
            ns = []
            if r > 0:
                ns.append((r - 1, c))
            if r + 1 < self.R:
                ns.append((r + 1, c))
            if c > 0:
                ns.append((r, c - 1))
            if c + 1 < self.C:
                ns.append((r, c + 1))
            self.nbrs[(r, c)] = ns

        self.clue_cells = []
        self.clue_id_of = {}
        self.clue_size = {}
        k = 0
        for r in range(self.R):
            for c in range(self.C):
                if clues[r][c] is not None:
                    self.clue_cells.append((r, c))
                    self.clue_id_of[(r, c)] = k
                    self.clue_size[k] = clues[r][c]
                    k += 1
        self.K = k

        self.reach_masks = {}
        self.dist_to_clue = {}
        self.owner_bits = {}
        all_mask = 0
        for cid, root in enumerate(self.clue_cells):
            mask, dist = self._bfs_all(root)
            self.reach_masks[cid] = mask
            self.dist_to_clue[cid] = dist
            all_mask |= mask
        for cell in self.cells:
            bits = 0
            for cid in range(self.K):
                if self._bit(cell) & self.reach_masks[cid]:
                    bits |= 1 << cid
            self.owner_bits[cell] = bits

        self.initial = [[UNKNOWN] * self.C for _ in range(self.R)]
        self.owner = [[-1] * self.C for _ in range(self.R)]
        for cid, (r, c) in enumerate(self.clue_cells):
            self.initial[r][c] = WHITE
            self.owner[r][c] = cid

    def _bit(self, cell):
        return 1 << self.idx[cell]

    def _bfs_all(self, start):
        q = deque([start])
        seen = {start}
        dist = {start: 0}
        mask = self._bit(start)
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                if v not in seen:
                    seen.add(v)
                    dist[v] = dist[u] + 1
                    mask |= self._bit(v)
                    q.append(v)
        return mask, dist

    def run(self):
        state = State(self)
        if not self.propagate(state):
            return None
        return self.search(state)

    def clone_state(self, st):
        ns = State(self, copy_from=st)
        return ns

    def search(self, state):
        if state.solved():
            if self.final_check(state):
                return state.grid
            return None

        branch = self.choose_branch(state)
        if branch is None:
            return None

        kind = branch[0]
        if kind == "cell":
            _, cell, vals = branch
            for color, owner in vals:
                ns = self.clone_state(state)
                if self.assign(ns, cell, color, owner):
                    if self.propagate(ns):
                        ans = self.search(ns)
                        if ans is not None:
                            return ans
            return None

        if kind == "island_expand":
            _, cid, candidates = branch
            # Try white expansion candidates first, then black rejections.
            for cell in candidates:
                ns = self.clone_state(state)
                if self.assign(ns, cell, WHITE, cid):
                    if self.propagate(ns):
                        ans = self.search(ns)
                        if ans is not None:
                            return ans
            for cell in candidates:
                ns = self.clone_state(state)
                if self.assign(ns, cell, BLACK, -1):
                    if self.propagate(ns):
                        ans = self.search(ns)
                        if ans is not None:
                            return ans
            return None

        return None

    def choose_branch(self, state):
        # Prefer an island with the tightest growth frontier.
        best = None
        for cid in range(self.K):
            if state.island_size(cid) >= self.clue_size[cid]:
                continue
            cand = self.expandable_cells(state, cid)
            if not cand:
                continue
            score = (len(cand), self.clue_size[cid] - state.island_size(cid))
            if best is None or score < best[0]:
                best = (score, ("island_expand", cid, cand))
        if best is not None:
            return best[1]

        # Then branch on most constrained unknown cell.
        best = None
        for cell in self.cells:
            r, c = cell
            if state.grid[r][c] != UNKNOWN:
                continue
            options = []
            if self.can_be_black(state, cell):
                options.append((BLACK, -1))
            owners = self.possible_white_owners(state, cell)
            for cid in owners:
                options.append((WHITE, cid))
            if not options:
                return ("cell", cell, [])
            score = len(options)
            if best is None or score < best[0]:
                best = (score, ("cell", cell, options))
        return best[1] if best else None

    def solved_black_connected(self, state):
        blacks = [(r, c) for r, c in self.cells if state.grid[r][c] == BLACK]
        if not blacks:
            return True
        seen = set([blacks[0]])
        q = deque([blacks[0]])
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                if v not in seen and state.grid[v[0]][v[1]] == BLACK:
                    seen.add(v)
                    q.append(v)
        return len(seen) == len(blacks)

    def final_check(self, state):
        # No unknowns
        for r, c in self.cells:
            if state.grid[r][c] == UNKNOWN:
                return False

        # Black connected
        if not self.solved_black_connected(state):
            return False

        # No 2x2 black
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cnt = 0
                for dr in (0, 1):
                    for dc in (0, 1):
                        if state.grid[r + dr][c + dc] == BLACK:
                            cnt += 1
                if cnt == 4:
                    return False

        # White islands exactly match clue ownership and sizes
        for cid, root in enumerate(self.clue_cells):
            comp = self.island_cells(state, cid)
            if len(comp) != self.clue_size[cid]:
                return False
        for r, c in self.cells:
            if state.grid[r][c] == WHITE and state.owner[r][c] < 0:
                return False
        return True

    def island_cells(self, state, cid):
        root = self.clue_cells[cid]
        if state.owner[root[0]][root[1]] != cid:
            return set()
        q = deque([root])
        seen = {root}
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                vr, vc = v
                if v not in seen and state.grid[vr][vc] == WHITE and state.owner[vr][vc] == cid:
                    seen.add(v)
                    q.append(v)
        return seen

    def island_frontier(self, state, cid):
        front = set()
        for cell in state.islands[cid]:
            for nb in self.nbrs[cell]:
                r, c = nb
                if state.grid[r][c] == UNKNOWN:
                    front.add(nb)
        return front

    def expandable_cells(self, state, cid):
        target = self.clue_size[cid]
        current = state.island_size(cid)
        if current >= target:
            return []

        root = self.clue_cells[cid]
        allowed = []
        # Reachable unknown cells that can still be connected to island through unknown/owned path.
        # Human-like: only consider frontier-connected growth, not arbitrary remote cells.
        q = deque(state.islands[cid])
        seen = set(state.islands[cid])
        found = set()
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                vr, vc = v
                if v in seen:
                    continue
                seen.add(v)
                if state.grid[vr][vc] == BLACK:
                    continue
                if state.grid[vr][vc] == WHITE:
                    if state.owner[vr][vc] == cid:
                        q.append(v)
                    continue
                # unknown
                if cid in self.possible_white_owners(state, v):
                    found.add(v)
                    q.append(v)
        for cell in found:
            if self.can_assign_white_owner(state, cell, cid):
                allowed.append(cell)
        return allowed

    def possible_white_owners(self, state, cell):
        r, c = cell
        if state.grid[r][c] == WHITE:
            return [state.owner[r][c]] if state.owner[r][c] >= 0 else []
        if state.grid[r][c] == BLACK:
            return []
        bits = self.owner_bits[cell]
        owners = []
        for cid in range(self.K):
            if not ((bits >> cid) & 1):
                continue
            if self.can_assign_white_owner(state, cell, cid):
                owners.append(cid)
        return owners

    def can_assign_white_owner(self, state, cell, cid):
        r, c = cell
        if state.grid[r][c] == BLACK:
            return False
        if state.grid[r][c] == WHITE:
            return state.owner[r][c] == cid
        if state.island_size(cid) >= self.clue_size[cid]:
            return False
        # Cannot join two islands / be adjacent to different fixed owner white.
        for nb in self.nbrs[cell]:
            nr, nc = nb
            if state.grid[nr][nc] == WHITE:
                oid = state.owner[nr][nc]
                if oid >= 0 and oid != cid:
                    return False
        # Must be connectable to cid via non-black cells without passing through other owned white islands.
        if not self.has_path_to_island(state, cell, cid):
            return False
        # Distance lower bound to leave enough room.
        root = self.clue_cells[cid]
        d = self.dist_to_clue[cid].get(cell)
        if d is None:
            return False
        if d + 1 > self.clue_size[cid]:
            return False
        return True

    def has_path_to_island(self, state, cell, cid):
        target = state.islands[cid]
        q = deque([cell])
        seen = {cell}
        while q:
            u = q.popleft()
            if u in target:
                return True
            for v in self.nbrs[u]:
                if v in seen:
                    continue
                vr, vc = v
                if state.grid[vr][vc] == BLACK:
                    continue
                if state.grid[vr][vc] == WHITE and state.owner[vr][vc] != cid:
                    continue
                seen.add(v)
                q.append(v)
        return False

    def can_be_black(self, state, cell):
        r, c = cell
        if state.grid[r][c] == WHITE:
            return False
        # Numbered cells cannot be black.
        if self.clues[r][c] is not None:
            return False
        # 2x2 forbidden.
        if self.creates_2x2_black(state, cell):
            return False
        # Must not eliminate all possible growth for any unfinished island.
        for cid in range(self.K):
            if state.island_size(cid) < self.clue_size[cid]:
                if not self.island_can_still_finish_with_black(state, cid, cell):
                    return False
        # White unknown cell with no possible owner often forced black; converse not required.
        return True

    def island_can_still_finish_with_black(self, state, cid, black_cell):
        need = self.clue_size[cid] - state.island_size(cid)
        if need <= 0:
            return True
        q = deque(state.islands[cid])
        seen = set(state.islands[cid])
        avail = set()
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                if v in seen:
                    continue
                seen.add(v)
                if v == black_cell:
                    continue
                vr, vc = v
                if state.grid[vr][vc] == BLACK:
                    continue
                if state.grid[vr][vc] == WHITE:
                    if state.owner[vr][vc] == cid:
                        q.append(v)
                    continue
                if cid in self.possible_white_owners_except_black(state, v, black_cell):
                    avail.add(v)
                    q.append(v)
        return len(avail) >= need

    def possible_white_owners_except_black(self, state, cell, black_cell):
        if cell == black_cell:
            return []
        return self.possible_white_owners(state, cell)

    def creates_2x2_black(self, state, cell):
        r, c = cell
        for dr in (-1, 0):
            for dc in (-1, 0):
                rr, cc = r + dr, c + dc
                if 0 <= rr < self.R - 1 and 0 <= cc < self.C - 1:
                    cnt = 0
                    unknowns = []
                    for a in (0, 1):
                        for b in (0, 1):
                            x, y = rr + a, cc + b
                            if (x, y) == cell:
                                cnt += 1
                            else:
                                v = state.grid[x][y]
                                if v == BLACK:
                                    cnt += 1
                                elif v == UNKNOWN:
                                    unknowns.append((x, y))
                    if cnt == 4:
                        return True
        return False

    def assign(self, state, cell, color, owner):
        r, c = cell
        cur = state.grid[r][c]
        if cur != UNKNOWN:
            if cur != color:
                return False
            if color == WHITE and owner >= 0 and state.owner[r][c] != owner:
                return False
            return True

        if color == WHITE:
            if not self.can_assign_white_owner(state, cell, owner):
                return False
            state.grid[r][c] = WHITE
            state.owner[r][c] = owner
            state.islands[owner].add(cell)
            return True

        if color == BLACK:
            if not self.can_be_black(state, cell):
                return False
            state.grid[r][c] = BLACK
            state.owner[r][c] = -1
            return True

        return False

    def propagate(self, state):
        changed = True
        while changed:
            changed = False

            # Basic contradiction checks.
            if not self.check_no_2x2_partial(state):
                return False
            if not self.check_white_ownership_consistency(state):
                return False
            if not self.check_island_bounds(state):
                return False
            if not self.check_black_connectivity_feasible(state):
                return False

            # 1. Adjacent clues cannot connect => separating cell black.
            if self.rule_separate_clues(state):
                changed = True
                continue

            # 2. Completed islands force adjacent unknowns black.
            if self.rule_completed_islands_surround_black(state):
                changed = True
                continue

            # 3. 2x2 prevention: if three black in a 2x2, fourth white.
            if self.rule_no_2x2_force_white(state):
                changed = True
                continue

            # 4. Any unknown with no possible white owner must be black.
            if self.rule_no_owner_means_black(state):
                changed = True
                continue

            # 5. Any unknown that cannot be black must be white with sole owner if unique.
            if self.rule_cannot_be_black(state):
                changed = True
                continue

            # 6. Single-cell island of size 1: orthogonal neighbors black.
            if self.rule_size_one_clues(state):
                changed = True
                continue

            # 7. Island exact-fill rules from reachable area.
            if self.rule_island_capacity_forcing(state):
                changed = True
                continue

            # 8. Black articulation / unreachable unknowns to keep black connected.
            if self.rule_black_connectivity_forcing(state):
                changed = True
                continue

            # 9. If a white cell location has exactly one owner, assign it white.
            if self.rule_unique_owner_white(state):
                changed = True
                continue

        return self.final_feasibility(state)

    def final_feasibility(self, state):
        return (
            self.check_no_2x2_partial(state)
            and self.check_white_ownership_consistency(state)
            and self.check_island_bounds(state)
            and self.check_black_connectivity_feasible(state)
        )

    def check_no_2x2_partial(self, state):
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cntb = 0
                for dr in (0, 1):
                    for dc in (0, 1):
                        if state.grid[r + dr][c + dc] == BLACK:
                            cntb += 1
                if cntb == 4:
                    return False
        return True

    def check_white_ownership_consistency(self, state):
        for r, c in self.cells:
            if state.grid[r][c] == WHITE:
                oid = state.owner[r][c]
                if oid < 0:
                    return False
                if (r, c) in self.clue_id_of and self.clue_id_of[(r, c)] != oid:
                    return False
                for nb in self.nbrs[(r, c)]:
                    nr, nc = nb
                    if state.grid[nr][nc] == WHITE and state.owner[nr][nc] >= 0 and state.owner[nr][nc] != oid:
                        return False
        return True

    def check_island_bounds(self, state):
        for cid in range(self.K):
            sz = state.island_size(cid)
            target = self.clue_size[cid]
            if sz > target:
                return False

            # Upper bound on still reachable cells for this island.
            q = deque(state.islands[cid])
            seen = set(state.islands[cid])
            reach = set(state.islands[cid])
            while q:
                u = q.popleft()
                for v in self.nbrs[u]:
                    if v in seen:
                        continue
                    seen.add(v)
                    vr, vc = v
                    if state.grid[vr][vc] == BLACK:
                        continue
                    if state.grid[vr][vc] == WHITE:
                        if state.owner[vr][vc] == cid:
                            reach.add(v)
                            q.append(v)
                        continue
                    if cid in self.possible_white_owners(state, v):
                        reach.add(v)
                        q.append(v)
            if len(reach) < target:
                return False
        return True

    def check_black_connectivity_feasible(self, state):
        blacks = [(r, c) for r, c in self.cells if state.grid[r][c] == BLACK]
        if not blacks:
            return True
        allowed = {cell for cell in self.cells if state.grid[cell[0]][cell[1]] != WHITE}
        seen = {blacks[0]}
        q = deque([blacks[0]])
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                if v in allowed and v not in seen:
                    seen.add(v)
                    q.append(v)
        for b in blacks:
            if b not in seen:
                return False
        return True

    def rule_separate_clues(self, state):
        for cid, root in enumerate(self.clue_cells):
            for nb in self.nbrs[root]:
                if nb in self.clue_id_of and self.clue_id_of[nb] != cid:
                    # already both white clues; nothing between orthogonally adjacent clues
                    return False
            r, c = root
            for dr, dc in ((1, 0), (0, 1)):
                r2, c2 = r + 2 * dr, c + 2 * dc
                if 0 <= r2 < self.R and 0 <= c2 < self.C and self.clues[r2][c2] is not None:
                    mid = (r + dr, c + dc)
                    if state.grid[mid[0]][mid[1]] == UNKNOWN:
                        if not self.assign(state, mid, BLACK, -1):
                            return False
                        return True
                    if state.grid[mid[0]][mid[1]] != BLACK:
                        return False
        return False

    def rule_completed_islands_surround_black(self, state):
        for cid in range(self.K):
            if state.island_size(cid) == self.clue_size[cid]:
                for cell in list(state.islands[cid]):
                    for nb in self.nbrs[cell]:
                        nr, nc = nb
                        if state.grid[nr][nc] == UNKNOWN:
                            if not self.assign(state, nb, BLACK, -1):
                                return False
                            return True
                        if state.grid[nr][nc] == WHITE and state.owner[nr][nc] != cid:
                            return False
        return False

    def rule_no_2x2_force_white(self, state):
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                blacks = [p for p in cells if state.grid[p[0]][p[1]] == BLACK]
                unknowns = [p for p in cells if state.grid[p[0]][p[1]] == UNKNOWN]
                if len(blacks) == 3:
                    if not unknowns:
                        return False
                    x = unknowns[0]
                    owners = self.possible_white_owners(state, x)
                    if len(owners) == 1:
                        if not self.assign(state, x, WHITE, owners[0]):
                            return False
                        return True
                    if len(owners) == 0:
                        return False
        return False

    def rule_no_owner_means_black(self, state):
        for cell in self.cells:
            r, c = cell
            if state.grid[r][c] != UNKNOWN:
                continue
            owners = self.possible_white_owners(state, cell)
            if not owners:
                if not self.assign(state, cell, BLACK, -1):
                    return False
                return True
        return False

    def rule_cannot_be_black(self, state):
        for cell in self.cells:
            r, c = cell
            if state.grid[r][c] != UNKNOWN:
                continue
            cb = self.can_be_black(state, cell)
            owners = self.possible_white_owners(state, cell)
            if not cb:
                if len(owners) == 1:
                    if not self.assign(state, cell, WHITE, owners[0]):
                        return False
                    return True
                if len(owners) == 0:
                    return False
        return False

    def rule_size_one_clues(self, state):
        for cid, root in enumerate(self.clue_cells):
            if self.clue_size[cid] == 1:
                for nb in self.nbrs[root]:
                    nr, nc = nb
                    if state.grid[nr][nc] == UNKNOWN:
                        if not self.assign(state, nb, BLACK, -1):
                            return False
                        return True
                    if state.grid[nr][nc] == WHITE and state.owner[nr][nc] != cid:
                        return False
        return False

    def rule_island_capacity_forcing(self, state):
        for cid in range(self.K):
            target = self.clue_size[cid]
            current = state.island_size(cid)
            if current >= target:
                continue
            cand = self.expandable_cells(state, cid)
            need = target - current
            if len(cand) < need:
                return False
            if len(cand) == need:
                for cell in cand:
                    if state.grid[cell[0]][cell[1]] == UNKNOWN:
                        if not self.assign(state, cell, WHITE, cid):
                            return False
                        return True
        return False

    def rule_black_connectivity_forcing(self, state):
        blacks = [(r, c) for r, c in self.cells if state.grid[r][c] == BLACK]
        if not blacks:
            return False
        allowed = {cell for cell in self.cells if state.grid[cell[0]][cell[1]] != WHITE}
        seen = {blacks[0]}
        q = deque([blacks[0]])
        while q:
            u = q.popleft()
            for v in self.nbrs[u]:
                if v in allowed and v not in seen:
                    seen.add(v)
                    q.append(v)
        for cell in self.cells:
            r, c = cell
            if state.grid[r][c] == UNKNOWN and cell not in seen:
                if not self.assign(state, cell, WHITE, self._sole_owner_if_any(state, cell)):
                    # If not forceable white by sole owner, leave it. Contradiction only if black needed unreachable.
                    pass
                else:
                    return True
        return False

    def _sole_owner_if_any(self, state, cell):
        owners = self.possible_white_owners(state, cell)
        return owners[0] if len(owners) == 1 else -999

    def rule_unique_owner_white(self, state):
        for cell in self.cells:
            r, c = cell
            if state.grid[r][c] != UNKNOWN:
                continue
            owners = self.possible_white_owners(state, cell)
            if len(owners) == 1 and not self.can_be_black(state, cell):
                if not self.assign(state, cell, WHITE, owners[0]):
                    return False
                return True
        return False


class State:
    def __init__(self, solver, copy_from=None):
        self.solver = solver
        R, C = solver.R, solver.C
        if copy_from is None:
            self.grid = [row[:] for row in solver.initial]
            self.owner = [row[:] for row in solver.owner]
            self.islands = [set() for _ in range(solver.K)]
            for cid, root in enumerate(solver.clue_cells):
                self.islands[cid].add(root)
        else:
            self.grid = [row[:] for row in copy_from.grid]
            self.owner = [row[:] for row in copy_from.owner]
            self.islands = [s.copy() for s in copy_from.islands]

    def island_size(self, cid):
        return len(self.islands[cid])

    def solved(self):
        for row in self.grid:
            for v in row:
                if v == UNKNOWN:
                    return False
        return True


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 0, 1], [2, 2, 2, 0, 3, 1], [2, 4, 4, 3, 3, 1], [2, 4, 5, 3, 1, 1], [2, 5, 5, 3, 3, 1], [2, 2, 3, 3, 1, 1]]}

# General 1-star Star Battle solver with human-like propagation plus tightly pruned search.
# Input:
#   observation = {'data': region_id_grid}
# Output:
#   string representation of grid as list of lists containing 'S' or None, or "No Solution"

from copy import deepcopy


def solve(observation):
    regions = observation['data']
    n = len(regions)
    if n == 0 or any(len(row) != n for row in regions):
        return "No Solution"

    # Build region -> cells map
    region_cells = {}
    for r in range(n):
        for c in range(n):
            region_cells.setdefault(regions[r][c], []).append((r, c))

    if len(region_cells) != n:
        # For a valid 1-star puzzle on NxN, there should be exactly N regions
        return "No Solution"

    cells = [(r, c) for r in range(n) for c in range(n)]
    cell_index = {cell: i for i, cell in enumerate(cells)}

    row_of = [r for r, c in cells]
    col_of = [c for r, c in cells]
    reg_of = [regions[r][c] for r, c in cells]

    # Neighbor cells that cannot also contain a star (touching incl. diagonal)
    touch = []
    for r, c in cells:
        nb = set()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    nb.add(cell_index[(rr, cc)])
        touch.append(nb)

    # Units
    row_cells = [[cell_index[(r, c)] for c in range(n)] for r in range(n)]
    col_cells = [[cell_index[(r, c)] for r in range(n)] for c in range(n)]
    reg_ids = sorted(region_cells)
    reg_id_to_pos = {rid: i for i, rid in enumerate(reg_ids)}
    reg_cells = [[] for _ in range(n)]
    for rid, lst in region_cells.items():
        reg_cells[reg_id_to_pos[rid]] = [cell_index[cell] for cell in lst]

    # For each cell, unit membership indices
    cell_row = row_of
    cell_col = col_of
    cell_reg = [reg_id_to_pos[reg_of[i]] for i in range(n * n)]

    ALL = (1 << (n * n)) - 1

    def list_to_mask(lst):
        m = 0
        for x in lst:
            m |= 1 << x
        return m

    row_masks = [list_to_mask(lst) for lst in row_cells]
    col_masks = [list_to_mask(lst) for lst in col_cells]
    reg_masks = [list_to_mask(lst) for lst in reg_cells]
    touch_masks = []
    for i in range(n * n):
        m = 0
        for j in touch[i]:
            m |= 1 << j
        touch_masks.append(m)

    unit_defs = []
    for r in range(n):
        unit_defs.append(("row", r, row_masks[r], row_cells[r]))
    for c in range(n):
        unit_defs.append(("col", c, col_masks[c], col_cells[c]))
    for g in range(n):
        unit_defs.append(("reg", g, reg_masks[g], reg_cells[g]))

    class State:
        __slots__ = (
            'allowed',
            'star_mask',
            'row_need',
            'col_need',
            'reg_need',
            'row_avail',
            'col_avail',
            'reg_avail',
        )

        def __init__(self):
            self.allowed = ALL
            self.star_mask = 0
            self.row_need = [1] * n
            self.col_need = [1] * n
            self.reg_need = [1] * n
            self.row_avail = row_masks[:]
            self.col_avail = col_masks[:]
            self.reg_avail = reg_masks[:]

        def clone(self):
            s = State()
            s.allowed = self.allowed
            s.star_mask = self.star_mask
            s.row_need = self.row_need[:]
            s.col_need = self.col_need[:]
            s.reg_need = self.reg_need[:]
            s.row_avail = self.row_avail[:]
            s.col_avail = self.col_avail[:]
            s.reg_avail = self.reg_avail[:]
            return s

    def bit_count(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def remove_cell(state, i):
        bit = 1 << i
        if not (state.allowed & bit):
            return True
        if state.star_mask & bit:
            return False
        state.allowed ^= bit
        r = cell_row[i]
        c = cell_col[i]
        g = cell_reg[i]
        state.row_avail[r] &= ~bit
        state.col_avail[c] &= ~bit
        state.reg_avail[g] &= ~bit
        if bit_count(state.row_avail[r]) < state.row_need[r]:
            return False
        if bit_count(state.col_avail[c]) < state.col_need[c]:
            return False
        if bit_count(state.reg_avail[g]) < state.reg_need[g]:
            return False
        return True

    def place_star(state, i):
        bit = 1 << i
        if not (state.allowed & bit):
            return False
        r = cell_row[i]
        c = cell_col[i]
        g = cell_reg[i]
        if state.row_need[r] == 0 or state.col_need[c] == 0 or state.reg_need[g] == 0:
            return False

        # Mark star
        state.star_mask |= bit
        state.row_need[r] -= 1
        state.col_need[c] -= 1
        state.reg_need[g] -= 1

        # Everything else in same row/col/region must be removed, and all touching cells removed.
        forbid = ((row_masks[r] | col_masks[c] | reg_masks[g] | touch_masks[i]) & state.allowed) & ~bit
        for j in list(iter_bits(forbid)):
            if not remove_cell(state, j):
                return False

        # The chosen cell must stay allowed until final consistency, but no duplicate star anyway.
        # If unit is now satisfied, all remaining cells in that unit must be removed.
        if state.row_need[r] == 0:
            rem = state.row_avail[r] & ~bit
            for j in list(iter_bits(rem)):
                if not remove_cell(state, j):
                    return False
        if state.col_need[c] == 0:
            rem = state.col_avail[c] & ~bit
            for j in list(iter_bits(rem)):
                if not remove_cell(state, j):
                    return False
        if state.reg_need[g] == 0:
            rem = state.reg_avail[g] & ~bit
            for j in list(iter_bits(rem)):
                if not remove_cell(state, j):
                    return False

        # Availability consistency after placement
        if bit_count(state.row_avail[r]) < state.row_need[r]:
            return False
        if bit_count(state.col_avail[c]) < state.col_need[c]:
            return False
        if bit_count(state.reg_avail[g]) < state.reg_need[g]:
            return False
        return True

    def unit_hidden_single(state):
        changed = False
        # If a unit needs 1 and has exactly 1 available cell, force it.
        for r in range(n):
            if state.row_need[r] == 1 and bit_count(state.row_avail[r]) == 1:
                i = next(iter_bits(state.row_avail[r]))
                before = state.star_mask
                if not place_star(state, i):
                    return None
                changed |= (state.star_mask != before)
        for c in range(n):
            if state.col_need[c] == 1 and bit_count(state.col_avail[c]) == 1:
                i = next(iter_bits(state.col_avail[c]))
                before = state.star_mask
                if not place_star(state, i):
                    return None
                changed |= (state.star_mask != before)
        for g in range(n):
            if state.reg_need[g] == 1 and bit_count(state.reg_avail[g]) == 1:
                i = next(iter_bits(state.reg_avail[g]))
                before = state.star_mask
                if not place_star(state, i):
                    return None
                changed |= (state.star_mask != before)
        return changed

    def contradiction(state):
        # Needs must be satisfiable
        for r in range(n):
            if state.row_need[r] < 0 or bit_count(state.row_avail[r]) < state.row_need[r]:
                return True
        for c in range(n):
            if state.col_need[c] < 0 or bit_count(state.col_avail[c]) < state.col_need[c]:
                return True
        for g in range(n):
            if state.reg_need[g] < 0 or bit_count(state.reg_avail[g]) < state.reg_need[g]:
                return True
        # Count consistency: total remaining needs must agree
        if sum(state.row_need) != sum(state.col_need) or sum(state.row_need) != sum(state.reg_need):
            return True
        return False

    def line_intersection_for_region(state):
        # Human-style rule:
        # If all possible cells for a region lie in one row/col, then since exactly one star must be in that row/col,
        # other cells touching every one of those possibilities in adjacent rows/cols can often be eliminated indirectly.
        # More directly useful in 1-star: if region candidates in a row occupy consecutive columns,
        # touching cells in neighboring rows can be removed if they would conflict with all placements.
        changed = False

        for g in range(n):
            if state.reg_need[g] != 1:
                continue
            mask = state.reg_avail[g]
            if mask == 0:
                return None

            rows_present = {}
            cols_present = {}
            for i in iter_bits(mask):
                rows_present.setdefault(cell_row[i], []).append(i)
                cols_present.setdefault(cell_col[i], []).append(i)

            # Region confined to single row -> all neighboring row cells in adjacent columns become impossible
            if len(rows_present) == 1:
                r = next(iter(rows_present))
                cols = [cell_col[i] for i in rows_present[r]]
                for rr in (r - 1, r + 1):
                    if 0 <= rr < n:
                        for cc in cols:
                            j = cell_index[(rr, cc)]
                            if state.allowed & (1 << j):
                                if not remove_cell(state, j):
                                    return None
                                changed = True

            # Region confined to single column -> symmetric
            if len(cols_present) == 1:
                c = next(iter(cols_present))
                rows = [cell_row[i] for i in cols_present[c]]
                for cc in (c - 1, c + 1):
                    if 0 <= cc < n:
                        for rr in rows:
                            j = cell_index[(rr, cc)]
                            if state.allowed & (1 << j):
                                if not remove_cell(state, j):
                                    return None
                                changed = True

        return changed

    def hall_like_unit_check(state):
        # Human-like subset deduction:
        # For each pair of unit types, if k rows together can place stars only in k columns, exclude those columns elsewhere.
        # Same for rows<->regions and cols<->regions.
        changed = False

        # rows -> cols
        active_rows = [r for r in range(n) if state.row_need[r] == 1]
        row_to_cols = {r: {cell_col[i] for i in iter_bits(state.row_avail[r])} for r in active_rows}
        for size in range(1, min(4, len(active_rows)) + 1):
            arr = active_rows
            m = len(arr)
            idxs = list(range(m))
            # small combinations only; enough for practical deduction without brute force
            def comb(start, left, chosen):
                nonlocal changed
                if left == 0:
                    rows_sel = chosen[:]
                    cols_union = set()
                    for r in rows_sel:
                        cols_union |= row_to_cols[r]
                    if len(cols_union) == len(rows_sel):
                        row_set = set(rows_sel)
                        for c in cols_union:
                            for i in list(iter_bits(state.col_avail[c])):
                                if cell_row[i] not in row_set:
                                    if not remove_cell(state, i):
                                        return False
                                    changed = True
                    return True
                for k in range(start, m - left + 1):
                    chosen.append(arr[k])
                    ok = comb(k + 1, left - 1, chosen)
                    chosen.pop()
                    if not ok:
                        return False
                return True
            if not comb(0, size, []):
                return None

        # cols -> rows
        active_cols = [c for c in range(n) if state.col_need[c] == 1]
        col_to_rows = {c: {cell_row[i] for i in iter_bits(state.col_avail[c])} for c in active_cols}
        for size in range(1, min(4, len(active_cols)) + 1):
            arr = active_cols
            m = len(arr)
            def comb(start, left, chosen):
                nonlocal changed
                if left == 0:
                    cols_sel = chosen[:]
                    rows_union = set()
                    for c in cols_sel:
                        rows_union |= col_to_rows[c]
                    if len(rows_union) == len(cols_sel):
                        col_set = set(cols_sel)
                        for r in rows_union:
                            for i in list(iter_bits(state.row_avail[r])):
                                if cell_col[i] not in col_set:
                                    if not remove_cell(state, i):
                                        return False
                                    changed = True
                    return True
                for k in range(start, len(arr) - left + 1):
                    chosen.append(arr[k])
                    ok = comb(k + 1, left - 1, chosen)
                    chosen.pop()
                    if not ok:
                        return False
                return True
            if not comb(0, size, []):
                return None

        return changed

    def propagate(state):
        while True:
            if contradiction(state):
                return False
            progress = False

            res = unit_hidden_single(state)
            if res is None:
                return False
            progress |= res

            res = line_intersection_for_region(state)
            if res is None:
                return False
            progress |= res

            res = hall_like_unit_check(state)
            if res is None:
                return False
            progress |= res

            if contradiction(state):
                return False
            if not progress:
                break
        return True

    def solved(state):
        return (
            sum(state.row_need) == 0 and
            sum(state.col_need) == 0 and
            sum(state.reg_need) == 0
        )

    def choose_branch_cell(state):
        # Strong heuristic: pick most constrained unsatisfied unit, then best candidate within it.
        best_cells = None
        best_len = 10**9

        for r in range(n):
            if state.row_need[r] == 1:
                cnt = bit_count(state.row_avail[r])
                if cnt < best_len and cnt > 1:
                    best_len = cnt
                    best_cells = list(iter_bits(state.row_avail[r]))
        for c in range(n):
            if state.col_need[c] == 1:
                cnt = bit_count(state.col_avail[c])
                if cnt < best_len and cnt > 1:
                    best_len = cnt
                    best_cells = list(iter_bits(state.col_avail[c]))
        for g in range(n):
            if state.reg_need[g] == 1:
                cnt = bit_count(state.reg_avail[g])
                if cnt < best_len and cnt > 1:
                    best_len = cnt
                    best_cells = list(iter_bits(state.reg_avail[g]))

        if not best_cells:
            return None

        # Prefer candidates that constrain the most neighbors and lie in constrained cross-units
        def score(i):
            return (
                bit_count(touch_masks[i]) +
                (n - bit_count(state.row_avail[cell_row[i]])) +
                (n - bit_count(state.col_avail[cell_col[i]])) +
                (n - bit_count(state.reg_avail[cell_reg[i]]))
            )

        best_cells.sort(key=score, reverse=True)
        return best_cells

    def dfs(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        branch = choose_branch_cell(state)
        if branch is None:
            return None

        # Try star placement first, then exclusion.
        for i in branch:
            s1 = state.clone()
            if place_star(s1, i):
                ans = dfs(s1)
                if ans is not None:
                    return ans

            s2 = state.clone()
            if remove_cell(s2, i):
                ans = dfs(s2)
                if ans is not None:
                    return ans

            # Since branch list is from same unit, trying all candidates is enough
            # but exclusion on one candidate may still be needed before others.
            # Continue through candidates.
        return None

    init = State()
    result = dfs(init)
    if result is None:
        return "No Solution"

    grid = [[None for _ in range(n)] for _ in range(n)]
    for i in iter_bits(result.star_mask):
        r, c = row_of[i], col_of[i]
        grid[r][c] = 'S'
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[2, None, 2, 2, None], [None, 3, None, None, None], [3, None, None, 3, None], [None, None, None, 1, None], [3, None, None, 1, 1]]}

# Generalized Minesweeper-clue solver for partially revealed boards.
# Returns a same-sized grid with 'F' for mines and None for safe cells, or "No Solution".

from collections import deque

def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return str([])

    R, C = len(data), len(data[0])

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if nr < 0 or nr >= R:
                continue
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nc = c + dc
                if 0 <= nc < C:
                    yield nr, nc

    numbered = []
    num_set = set()
    unknown_cells = []
    unknown_set = set()
    for r in range(R):
        for c in range(C):
            if data[r][c] is None:
                unknown_cells.append((r, c))
                unknown_set.add((r, c))
            else:
                numbered.append((r, c))
                num_set.add((r, c))

    # Variables are only cells that are unknown and adjacent to at least one clue.
    var_index = {}
    vars_list = []
    clue_to_vars = {}
    clue_require = {}

    for rc in numbered:
        r, c = rc
        adj_vars = []
        for nr, nc in neighbors(r, c):
            if (nr, nc) in unknown_set:
                if (nr, nc) not in var_index:
                    var_index[(nr, nc)] = len(vars_list)
                    vars_list.append((nr, nc))
                adj_vars.append(var_index[(nr, nc)])
        clue_to_vars[rc] = adj_vars
        clue_require[rc] = data[r][c]
        if data[r][c] < 0 or data[r][c] > len(adj_vars):
            return "No Solution"

    nvars = len(vars_list)

    # Cells not touching any clue can never be deduced by clues alone; in standard formulation
    # any assignment is allowed there. We choose them as safe to provide a canonical answer.
    unconstrained_unknowns = [cell for cell in unknown_cells if cell not in var_index]

    # Build variable -> clues adjacency.
    var_to_clues = [[] for _ in range(nvars)]
    for clue, vs in clue_to_vars.items():
        for v in vs:
            var_to_clues[v].append(clue)

    # Precompute clue subset relations for human-like deductions:
    # If A vars subset B vars, then:
    #   req(B)-req(A) mines in B\A
    # Which can force all safe or all mines in difference.
    clue_list = [cl for cl in numbered if clue_to_vars[cl]]
    clue_var_sets = {cl: set(clue_to_vars[cl]) for cl in clue_list}

    assign = [-1] * nvars  # -1 unknown, 0 safe, 1 mine
    rem_mines = {cl: clue_require[cl] for cl in clue_to_vars}
    rem_unknown = {cl: len(clue_to_vars[cl]) for cl in clue_to_vars}

    def set_var(v, val, queue):
        cur = assign[v]
        if cur != -1:
            return cur == val
        assign[v] = val
        for cl in var_to_clues[v]:
            rem_unknown[cl] -= 1
            if val == 1:
                rem_mines[cl] -= 1
            if rem_mines[cl] < 0 or rem_mines[cl] > rem_unknown[cl]:
                return False
            queue.append(cl)
        return True

    def propagate(initial_clues=None):
        queue = deque()
        inq = set()

        if initial_clues is None:
            for cl in clue_to_vars:
                queue.append(cl)
                inq.add(cl)
        else:
            for cl in initial_clues:
                if cl not in inq:
                    queue.append(cl)
                    inq.add(cl)

        while queue:
            cl = queue.popleft()
            inq.discard(cl)

            req = rem_mines[cl]
            unk = rem_unknown[cl]

            if req < 0 or req > unk:
                return False

            # Direct human rule:
            # if remaining mines == 0 => all remaining adjacent unknown are safe
            # if remaining mines == remaining unknowns => all are mines
            if unk:
                if req == 0 or req == unk:
                    forced_val = 1 if req == unk else 0
                    for v in clue_to_vars[cl]:
                        if assign[v] == -1:
                            if not set_var(v, forced_val, queue):
                                return False

            # Subset/difference reasoning against neighboring clues.
            # Restrict to clues sharing some variable neighborhood for efficiency.
            related = set()
            for v in clue_to_vars[cl]:
                for other in var_to_clues[v]:
                    if other != cl:
                        related.add(other)

            A = clue_var_sets.get(cl)
            if A is None:
                continue

            A_unknown = {v for v in A if assign[v] == -1}
            A_req = rem_mines[cl]

            for other in related:
                B = clue_var_sets[other]
                B_unknown = {v for v in B if assign[v] == -1}
                B_req = rem_mines[other]

                if not A_unknown or not B_unknown:
                    continue

                if A_unknown <= B_unknown:
                    diff = B_unknown - A_unknown
                    dreq = B_req - A_req
                    if dreq < 0 or dreq > len(diff):
                        return False
                    if diff:
                        if dreq == 0:
                            for v in diff:
                                if assign[v] == -1 and not set_var(v, 0, queue):
                                    return False
                        elif dreq == len(diff):
                            for v in diff:
                                if assign[v] == -1 and not set_var(v, 1, queue):
                                    return False
                if B_unknown <= A_unknown:
                    diff = A_unknown - B_unknown
                    dreq = A_req - B_req
                    if dreq < 0 or dreq > len(diff):
                        return False
                    if diff:
                        if dreq == 0:
                            for v in diff:
                                if assign[v] == -1 and not set_var(v, 0, queue):
                                    return False
                        elif dreq == len(diff):
                            for v in diff:
                                if assign[v] == -1 and not set_var(v, 1, queue):
                                    return False

        return True

    if not propagate():
        return "No Solution"

    # Split remaining variables into independent connected components by clue coupling.
    unassigned = [v for v in range(nvars) if assign[v] == -1]
    if unassigned:
        seen = set()
        components = []
        for v in unassigned:
            if v in seen:
                continue
            q = [v]
            seen.add(v)
            comp_vars = []
            comp_clues = set()
            while q:
                x = q.pop()
                comp_vars.append(x)
                for cl in var_to_clues[x]:
                    comp_clues.add(cl)
                    for y in clue_to_vars[cl]:
                        if assign[y] == -1 and y not in seen:
                            seen.add(y)
                            q.append(y)
            components.append((comp_vars, list(comp_clues)))
    else:
        components = []

    # Enumerate each component with strong pruning.
    for comp_vars, comp_clues in components:
        local_pos = {v: i for i, v in enumerate(comp_vars)}
        local_clues = comp_clues

        clue_locals = []
        for cl in local_clues:
            lst = [local_pos[v] for v in clue_to_vars[cl] if assign[v] == -1]
            fixed_mines = sum(1 for v in clue_to_vars[cl] if assign[v] == 1)
            fixed_unknown_assigned = sum(1 for v in clue_to_vars[cl] if assign[v] != -1)
            req = clue_require[cl] - fixed_mines
            total_unknown_here = len(lst)
            if req < 0 or req > total_unknown_here:
                return "No Solution"
            clue_locals.append((lst, req))

        v_to_localclues = [[] for _ in comp_vars]
        for ci, (lst, req) in enumerate(clue_locals):
            for lv in lst:
                v_to_localclues[lv].append(ci)

        order = sorted(range(len(comp_vars)), key=lambda lv: -len(v_to_localclues[lv]))

        rem_req = [req for _, req in clue_locals]
        rem_unk = [len(lst) for lst, _ in clue_locals]
        local_assign = [-1] * len(comp_vars)
        solution = None

        def choose_branch_var():
            best = None
            best_score = -1
            for lv in order:
                if local_assign[lv] != -1:
                    continue
                score = 0
                for ci in v_to_localclues[lv]:
                    score += 1 + len(clue_locals[ci][0])
                if score > best_score:
                    best_score = score
                    best = lv
            return best

        def local_set(lv, val, touched_clues, forced_vars):
            if local_assign[lv] != -1:
                return local_assign[lv] == val
            local_assign[lv] = val
            forced_vars.append(lv)
            for ci in v_to_localclues[lv]:
                rem_unk[ci] -= 1
                if val == 1:
                    rem_req[ci] -= 1
                touched_clues.add(ci)
                if rem_req[ci] < 0 or rem_req[ci] > rem_unk[ci]:
                    return False
            return True

        def local_propagate(seed_clues, touched_clues, forced_vars):
            dq = deque(seed_clues)
            inq = set(seed_clues)
            while dq:
                ci = dq.popleft()
                inq.discard(ci)
                req = rem_req[ci]
                unk = rem_unk[ci]
                if req < 0 or req > unk:
                    return False
                if unk == 0:
                    continue
                if req == 0 or req == unk:
                    forced_val = 1 if req == unk else 0
                    for lv in clue_locals[ci][0]:
                        if local_assign[lv] == -1:
                            if not local_set(lv, forced_val, touched_clues, forced_vars):
                                return False
                            for cj in v_to_localclues[lv]:
                                if cj not in inq:
                                    dq.append(cj)
                                    inq.add(cj)
            return True

        def undo(touched_clues, forced_vars):
            for lv in reversed(forced_vars):
                val = local_assign[lv]
                for ci in v_to_localclues[lv]:
                    if val == 1:
                        rem_req[ci] += 1
                    rem_unk[ci] += 1
                local_assign[lv] = -1

        def dfs():
            nonlocal solution
            lv = choose_branch_var()
            if lv is None:
                if all(req == 0 for req in rem_req):
                    solution = local_assign[:]
                    return True
                return False

            # Value ordering: test the more constrained possibility first.
            # Estimate pressure from adjacent clues.
            mine_pressure = 0
            safe_pressure = 0
            for ci in v_to_localclues[lv]:
                req = rem_req[ci]
                unk = rem_unk[ci]
                mine_pressure += req / unk
                safe_pressure += (unk - req) / unk
            branch_vals = [1, 0] if mine_pressure >= safe_pressure else [0, 1]

            for val in branch_vals:
                touched_clues = set()
                forced_vars = []
                if local_set(lv, val, touched_clues, forced_vars):
                    seed = list(touched_clues)
                    if local_propagate(seed, touched_clues, forced_vars):
                        if dfs():
                            return True
                undo(touched_clues, forced_vars)
            return False

        if not dfs():
            return "No Solution"

        for lv, gval in enumerate(solution):
            assign[comp_vars[lv]] = gval

    # Final verification on all clues.
    for r, c in numbered:
        s = 0
        for nr, nc in neighbors(r, c):
            if (nr, nc) in var_index and assign[var_index[(nr, nc)]] == 1:
                s += 1
        if s != data[r][c]:
            return "No Solution"

    answer = [[None for _ in range(C)] for _ in range(R)]
    for cell, idx in var_index.items():
        if assign[idx] == 1:
            r, c = cell
            answer[r][c] = 'F'
    # Unconstrained unknown cells kept as None by canonical choice.
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'W4', None, None, None, None, None, None, None, 'B12'], [None, None, None, 'B5', None, 'B2', 'B4', 'B2', None, None, None], [None, None, None, None, None, 'B3', None, None, None, None, None], [None, 'B2', None, 'B3', None, None, None, None, None, None, None], ['W3', None, None, 'B3', None, None, None, None, 'W2', None, None], [None, 'B2', 'B5', 'B3', None, None, 'B7', None, None, 'W5', None], [None, None, None, None, None, 'B3', None, None, 'W2', None, None], [None, None, None, None, None, 'B3', None, None, None, None, None], [None, None, None, None, None, 'B3', None, None, None, 'W2', 'B3'], [None, 'B2', None, None, None, None, None, 'B4', None, None, None], [None, 'W4', None, None, None, None, None, None, None, None, None]]}

from collections import defaultdict, deque

# General Masyu-like loop solver with numbered white/black circles:
# - White: loop goes straight through clue cell.
# - Black: loop turns at clue cell.
# - Number k: sum of lengths of the two maximal straight arms extending from that clue.
#
# Representation:
# A clue at cell (r,c) lies between 4 surrounding dots:
#   NW=(r,c), NE=(r,c+1), SW=(r+1,c), SE=(r+1,c+1)
# The loop uses cell-local patterns over those 4 boundary edges:
#   N: (r,c)-(r,c+1)
#   S: (r+1,c)-(r+1,c+1)
#   W: (r,c)-(r+1,c)
#   E: (r,c+1)-(r+1,c+1)
#
# Valid per-cell occupancy patterns are:
#   empty
#   horizontal (N+S)
#   vertical   (W+E)
#   turn_NE (N+E), turn_NW (N+W), turn_SE (S+E), turn_SW (S+W)
#
# We solve by:
# 1. Enumerating clue-compatible local patterns with exact numbered-arm feasibility.
# 2. Enforcing edge agreement between neighboring cells.
# 3. Enforcing dot degree constraints (0 or 2, no branches).
# 4. Strong propagation from clue lengths, parity, and connectivity.
# 5. Limited search on most constrained cells.
#
# This is not a naive path DFS; it is a domain-filtering CSP with loop-specific deductions.

DIRS = ('N', 'E', 'S', 'W')
DRDC = {'N': (-1, 0), 'E': (0, 1), 'S': (1, 0), 'W': (0, -1)}
OPP = {'N': 'S', 'S': 'N', 'E': 'W', 'W': 'E'}

PATTERNS = {
    'empty': frozenset(),
    'hor': frozenset(('N', 'S')),
    'ver': frozenset(('W', 'E')),
    'NE': frozenset(('N', 'E')),
    'NW': frozenset(('N', 'W')),
    'SE': frozenset(('S', 'E')),
    'SW': frozenset(('S', 'W')),
}

TURN_PATTERNS = [PATTERNS[k] for k in ('NE', 'NW', 'SE', 'SW')]
STRAIGHT_PATTERNS = [PATTERNS['hor'], PATTERNS['ver']]


def solve(observation):
    data = observation['data']
    H = len(data)
    W = len(data[0]) if H else 0

    clues = {}
    for r in range(H):
        for c in range(W):
            tok = data[r][c]
            if tok is not None:
                clues[(r, c)] = (tok[0], int(tok[1:]))

    solver = Solver(H, W, clues)
    if not solver.initialise():
        return "No Solution"
    if not solver.search():
        return "No Solution"
    path = solver.extract_loop_path()
    return str(path) if path else "No Solution"


class Solver:
    def __init__(self, H, W, clues):
        self.H = H
        self.W = W
        self.clues = clues

        # Cell domains: set of local patterns (frozenset of boundary labels)
        self.dom = {}
        # Dot incident edge states: edge -> -1 unknown, 0 absent, 1 present
        self.edge_state = {}
        # For reversible search
        self.trail = []
        self.level_marks = []

        # Precompute cell-edge IDs
        self.cell_edges = {}
        self.cells_of_edge = defaultdict(list)
        self.dot_edges = defaultdict(list)

        for r in range(H):
            for c in range(W):
                mapping = {
                    'N': ('H', r, c),
                    'S': ('H', r + 1, c),
                    'W': ('V', r, c),
                    'E': ('V', r, c + 1),
                }
                self.cell_edges[(r, c)] = mapping
                for d, e in mapping.items():
                    self.cells_of_edge[e].append((r, c, d))

        for r in range(H + 1):
            for c in range(W):
                e = ('H', r, c)
                self.edge_state[e] = -1
                self.dot_edges[(r, c)].append(e)
                self.dot_edges[(r, c + 1)].append(e)

        for r in range(H):
            for c in range(W + 1):
                e = ('V', r, c)
                self.edge_state[e] = -1
                self.dot_edges[(r, c)].append(e)
                self.dot_edges[(r + 1, c)].append(e)

        # Precompute clue pattern candidates with exact-arm feasibility
        self.base_domains = {}
        for r in range(H):
            for c in range(W):
                self.base_domains[(r, c)] = self.compute_base_domain(r, c)

    def initialise(self):
        for cell, domain in self.base_domains.items():
            if not domain:
                return False
            self.dom[cell] = set(domain)

        return self.propagate()

    def compute_base_domain(self, r, c):
        clue = self.clues.get((r, c))
        if clue is None:
            return list(PATTERNS.values())

        color, k = clue
        allowed = TURN_PATTERNS if color == 'B' else STRAIGHT_PATTERNS
        out = []
        for pat in allowed:
            if self.pattern_can_meet_number(r, c, pat, k):
                out.append(pat)
        return out

    def pattern_can_meet_number(self, r, c, pat, k):
        dirs = list(pat)
        d1, d2 = dirs[0], dirs[1]
        lengths1 = self.possible_arm_lengths(r, c, d1, pat)
        lengths2 = self.possible_arm_lengths(r, c, d2, pat)
        # Human-like arithmetic feasibility: exact sum of two arm lengths.
        need = k
        s2 = set(lengths2)
        for a in lengths1:
            if need - a in s2:
                return True
        return False

    def possible_arm_lengths(self, r, c, d, pat):
        # Arm length counts consecutive cells including current clue cell,
        # along the geometric direction of the segment through the clue.
        # At current clue cell, chosen pattern already uses direction d.
        # Then following cells must maintain same edge occupancy to continue straight.
        dr, dc = DRDC[d]
        rr, cc = r, c
        length = 1
        possible = {1}
        while True:
            nr, nc = rr + dr, cc + dc
            if not (0 <= nr < self.H and 0 <= nc < self.W):
                break

            # Crossing cell boundary means the shared edge between (rr,cc) and (nr,nc)
            # must be occupied. Local continuation in next cell must also include the
            # opposite side and same side pair to continue straight in that direction.
            needed = self.continuation_patterns(nr, nc, OPP[d], d)
            if not needed:
                break
            length += 1
            possible.add(length)
            rr, cc = nr, nc
        return possible

    def continuation_patterns(self, r, c, enter_side, travel_dir):
        # If we enter cell through side enter_side and continue straight along travel_dir,
        # then the cell must use both enter_side and its opposite-facing exit side.
        # Because our label set is sides occupied on cell border:
        # horizontal travel uses N+S; vertical uses W+E.
        clue = self.clues.get((r, c))
        cands = self.base_domain_local_only(r, c)
        out = []
        for pat in cands:
            if enter_side not in pat:
                continue
            # Continue straight in same geometric direction:
            # moving N/S requires vertical pattern W+E? No:
            # With this cell formalism, N/S are horizontal top/bottom edges.
            # A path segment moving vertically through a cell occupies W+E? Actually no.
            # The defined local patterns correspond whether path uses top+bottom (vertical pass)
            # or left+right (horizontal pass) in the dual-cell view:
            # N+S means entering from top and leaving bottom => vertical movement.
            # W+E means entering left and leaving right => horizontal movement.
            if travel_dir in ('N', 'S'):
                if pat == PATTERNS['hor']:
                    out.append(pat)
            else:
                if pat == PATTERNS['ver']:
                    out.append(pat)
        return out

    def base_domain_local_only(self, r, c):
        clue = self.clues.get((r, c))
        if clue is None:
            return list(PATTERNS.values())
        color, _ = clue
        return TURN_PATTERNS if color == 'B' else STRAIGHT_PATTERNS

    def push_level(self):
        self.level_marks.append(len(self.trail))

    def pop_level(self):
        mark = self.level_marks.pop()
        while len(self.trail) > mark:
            typ, key, old = self.trail.pop()
            if typ == 'dom':
                self.dom[key] = old
            else:
                self.edge_state[key] = old

    def set_dom(self, cell, newdom):
        old = self.dom[cell]
        if newdom == old:
            return True
        if not newdom:
            return False
        self.trail.append(('dom', cell, old))
        self.dom[cell] = newdom
        return True

    def set_edge(self, e, val):
        old = self.edge_state[e]
        if old == val:
            return True
        if old != -1 and old != val:
            return False
        self.trail.append(('edge', e, old))
        self.edge_state[e] = val
        return True

    def propagate(self):
        q_cells = deque((r, c) for r in range(self.H) for c in range(self.W))
        q_edges = deque(self.edge_state.keys())
        q_dots = deque(self.dot_edges.keys())

        in_q_cells = set(q_cells)
        in_q_edges = set(q_edges)
        in_q_dots = set(q_dots)

        while q_cells or q_edges or q_dots:
            if q_cells:
                cell = q_cells.popleft()
                in_q_cells.discard(cell)
                if not self.reduce_cell(cell, q_edges, in_q_edges, q_dots, in_q_dots):
                    return False
            elif q_edges:
                e = q_edges.popleft()
                in_q_edges.discard(e)
                if not self.reduce_edge(e, q_cells, in_q_cells):
                    return False
            else:
                dot = q_dots.popleft()
                in_q_dots.discard(dot)
                if not self.reduce_dot(dot, q_edges, in_q_edges, q_cells, in_q_cells, q_dots, in_q_dots):
                    return False

        # Global loop pruning: avoid completed smaller loops before all used clues are connected.
        if not self.check_no_premature_cycle():
            return False
        return True

    def enqueue_cell_neighbors(self, cell, q_cells, in_q_cells, q_edges, in_q_edges, q_dots, in_q_dots):
        r, c = cell
        if cell not in in_q_cells:
            q_cells.append(cell)
            in_q_cells.add(cell)
        for e in self.cell_edges[cell].values():
            if e not in in_q_edges:
                q_edges.append(e)
                in_q_edges.add(e)
            typ, er, ec = e
            if typ == 'H':
                dots = [(er, ec), (er, ec + 1)]
            else:
                dots = [(er, ec), (er + 1, ec)]
            for d in dots:
                if d not in in_q_dots:
                    q_dots.append(d)
                    in_q_dots.add(d)

    def reduce_cell(self, cell, q_edges, in_q_edges, q_dots, in_q_dots):
        r, c = cell
        domain = self.dom[cell]
        mapping = self.cell_edges[cell]
        newdom = set()
        for pat in domain:
            ok = True
            for side, e in mapping.items():
                st = self.edge_state[e]
                if st == -1:
                    continue
                want = 1 if side in pat else 0
                if st != want:
                    ok = False
                    break
            if ok and self.pattern_number_still_feasible(r, c, pat):
                newdom.add(pat)

        if not newdom:
            return False
        if newdom != domain:
            if not self.set_dom(cell, newdom):
                return False

        # Forced edges from all remaining patterns.
        for side, e in mapping.items():
            vals = {1 if side in pat else 0 for pat in self.dom[cell]}
            if len(vals) == 1:
                v = next(iter(vals))
                if not self.set_edge(e, v):
                    return False
                if e not in in_q_edges:
                    q_edges.append(e)
                    in_q_edges.add(e)
                typ, er, ec = e
                dots = [(er, ec), (er, ec + 1)] if typ == 'H' else [(er, ec), (er + 1, ec)]
                for dot in dots:
                    if dot not in in_q_dots:
                        q_dots.append(dot)
                        in_q_dots.add(dot)
        return True

    def pattern_number_still_feasible(self, r, c, pat):
        clue = self.clues.get((r, c))
        if clue is None:
            return True
        _, k = clue
        ds = list(pat)
        a_range = self.arm_length_bounds(r, c, ds[0], pat)
        b_range = self.arm_length_bounds(r, c, ds[1], pat)
        min_sum = a_range[0] + b_range[0]
        max_sum = a_range[1] + b_range[1]
        if not (min_sum <= k <= max_sum):
            return False

        # Parity-aware exact feasibility using interval sets from both arms.
        A = self.arm_length_possible_set_bounded(r, c, ds[0], pat)
        B = self.arm_length_possible_set_bounded(r, c, ds[1], pat)
        SB = set(B)
        for x in A:
            if k - x in SB:
                return True
        return False

    def arm_length_bounds(self, r, c, d, pat):
        vals = self.arm_length_possible_set_bounded(r, c, d, pat)
        return (min(vals), max(vals))

    def arm_length_possible_set_bounded(self, r, c, d, pat):
        # Exact possible lengths under current domains/edges by walking until blocked,
        # requiring every traversed future cell to admit a straight continuation.
        dr, dc = DRDC[d]
        vals = {1}
        rr, cc = r, c
        cur_len = 1
        while True:
            nr, nc = rr + dr, cc + dc
            if not (0 <= nr < self.H and 0 <= nc < self.W):
                break

            # Shared boundary edge must be potentially present.
            shared = self.shared_boundary_edge(rr, cc, nr, nc)
            st = self.edge_state[shared]
            if st == 0:
                break

            req_pat = PATTERNS['hor'] if d in ('N', 'S') else PATTERNS['ver']
            domn = self.dom[(nr, nc)]
            if req_pat not in domn:
                break

            cur_len += 1
            vals.add(cur_len)
            rr, cc = nr, nc
        return vals

    def shared_boundary_edge(self, r1, c1, r2, c2):
        if r2 == r1 - 1:
            return ('H', r1, c1)
        if r2 == r1 + 1:
            return ('H', r1 + 1, c1)
        if c2 == c1 - 1:
            return ('V', r1, c1)
        return ('V', r1, c1 + 1)

    def reduce_edge(self, e, q_cells, in_q_cells):
        cells = self.cells_of_edge[e]
        st = self.edge_state[e]

        if st == -1:
            # If no incident cell can use it -> 0 ; if all must use -> 1
            possible = []
            for r, c, side in cells:
                vals = {1 if side in pat else 0 for pat in self.dom[(r, c)]}
                possible.append(vals)
            if possible:
                can1 = all(1 in vals for vals in possible)
                can0 = all(0 in vals for vals in possible)
                if not can1 and not can0:
                    return False
                if can1 and not can0:
                    if not self.set_edge(e, 1):
                        return False
                elif can0 and not can1:
                    if not self.set_edge(e, 0):
                        return False
                if self.edge_state[e] != -1:
                    st = self.edge_state[e]

        if st != -1:
            for r, c, _ in cells:
                if (r, c) not in in_q_cells:
                    q_cells.append((r, c))
                    in_q_cells.add((r, c))
        return True

    def reduce_dot(self, dot, q_edges, in_q_edges, q_cells, in_q_cells, q_dots, in_q_dots):
        edges = self.dot_edges[dot]
        vals = [self.edge_state[e] for e in edges]
        on = sum(v == 1 for v in vals)
        unk = sum(v == -1 for v in vals)

        # Degree must be 0 or 2.
        if on > 2:
            return False
        if on == 1 and unk == 0:
            return False
        if on == 3:
            return False
        if on == 1 and unk == 1:
            # Last unknown must be on.
            for e in edges:
                if self.edge_state[e] == -1:
                    if not self.set_edge(e, 1):
                        return False
                    if e not in in_q_edges:
                        q_edges.append(e)
                        in_q_edges.add(e)
        if on == 2:
            for e in edges:
                if self.edge_state[e] == -1:
                    if not self.set_edge(e, 0):
                        return False
                    if e not in in_q_edges:
                        q_edges.append(e)
                        in_q_edges.add(e)
        if on == 0 and unk == 1:
            if not self.set_edge(next(e for e in edges if self.edge_state[e] == -1), 0):
                return False
            e = next(e for e in edges if self.edge_state[e] != -1 and self.edge_state[e] == 0)
            if e not in in_q_edges:
                q_edges.append(e)
                in_q_edges.add(e)

        # Human-like local clue pressure:
        # Any cell touching this dot cannot have incompatible degree contribution.
        r, c = dot
        for cr in (r - 1, r):
            for cc in (c - 1, c):
                if 0 <= cr < self.H and 0 <= cc < self.W and (cr, cc) not in in_q_cells:
                    q_cells.append((cr, cc))
                    in_q_cells.add((cr, cc))
        return True

    def check_no_premature_cycle(self):
        # Build graph of confirmed present edges.
        adj = defaultdict(list)
        present_edges = [e for e, v in self.edge_state.items() if v == 1]
        if not present_edges:
            return True
        for e in present_edges:
            a, b = self.edge_endpoints(e)
            adj[a].append(b)
            adj[b].append(a)

        # Components among degree>0 dots.
        seen = set()
        comps = []
        for v in adj:
            if v in seen:
                continue
            stack = [v]
            seen.add(v)
            comp = []
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in adj[x]:
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            comps.append(comp)

        # If a component is already a closed cycle, it must be the unique final loop,
        # so all present edges must belong to it and no undecided clue demand outside.
        total_present_vertices = sum(len(c) for c in comps)
        for comp in comps:
            if all(len(adj[v]) == 2 for v in comp):
                if len(comp) != total_present_vertices:
                    return False
                # If it's a complete cycle, then every clue cell used must be fixed and all others empty;
                # but clues cannot be empty, so require every clue cell to already have a non-empty forced pattern.
                for cell, clue in self.clues.items():
                    if all(len(p) == 0 for p in self.dom[cell]):
                        return False
                # Also reject if there remains any unknown edge adjacent to current cycle that could extend;
                # a final full cycle should occur only at completion, checked later in solved().
                if any(v == -1 for v in self.edge_state.values()):
                    return False
        return True

    def edge_endpoints(self, e):
        typ, r, c = e
        if typ == 'H':
            return (r, c), (r, c + 1)
        return (r, c), (r + 1, c)

    def solved(self):
        if any(len(self.dom[cell]) != 1 for cell in self.dom):
            return False
        if any(v == -1 for v in self.edge_state.values()):
            return False

        # Every clue cell must be used correctly.
        for cell, (color, k) in self.clues.items():
            pat = next(iter(self.dom[cell]))
            if color == 'W' and pat not in STRAIGHT_PATTERNS:
                return False
            if color == 'B' and pat not in TURN_PATTERNS:
                return False
            if not self.pattern_exact_number(cell[0], cell[1], pat, k):
                return False

        # Dot degrees and single loop.
        adj = defaultdict(list)
        used_vertices = set()
        for e, v in self.edge_state.items():
            if v == 1:
                a, b = self.edge_endpoints(e)
                adj[a].append(b)
                adj[b].append(a)
                used_vertices.add(a)
                used_vertices.add(b)
        if not used_vertices:
            return False
        if any(len(adj[v]) != 2 for v in used_vertices):
            return False

        start = next(iter(used_vertices))
        seen = {start}
        stack = [start]
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return seen == used_vertices

    def pattern_exact_number(self, r, c, pat, k):
        ds = list(pat)
        return self.exact_arm_length(r, c, ds[0], pat) + self.exact_arm_length(r, c, ds[1], pat) == k

    def exact_arm_length(self, r, c, d, pat):
        dr, dc = DRDC[d]
        rr, cc = r, c
        length = 1
        while True:
            nr, nc = rr + dr, cc + dc
            if not (0 <= nr < self.H and 0 <= nc < self.W):
                break
            req = PATTERNS['hor'] if d in ('N', 'S') else PATTERNS['ver']
            if next(iter(self.dom[(nr, nc)])) != req:
                break
            shared = self.shared_boundary_edge(rr, cc, nr, nc)
            if self.edge_state[shared] != 1:
                break
            length += 1
            rr, cc = nr, nc
        return length

    def choose_branch(self):
        # Most constrained unresolved clue cell first, then any unresolved cell.
        best = None
        best_score = None
        for cell, domain in self.dom.items():
            if len(domain) <= 1:
                continue
            clue = self.clues.get(cell)
            score = (0 if clue else 1, len(domain))
            if best is None or score < best_score:
                best = cell
                best_score = score
        return best

    def search(self):
        if self.solved():
            return True

        cell = self.choose_branch()
        if cell is None:
            return False

        # Least-ambiguity heuristic: patterns forcing more currently unknown edges first.
        pats = list(self.dom[cell])
        mapping = self.cell_edges[cell]
        def pat_score(pat):
            force = 0
            for side, e in mapping.items():
                if self.edge_state[e] == -1:
                    force += 1
            clue_bonus = 0
            if cell in self.clues:
                color, k = self.clues[cell]
                clue_bonus = -k
                if color == 'B' and pat in TURN_PATTERNS:
                    clue_bonus -= 2
            return (-force, clue_bonus)
        pats.sort(key=pat_score)

        old_domain = self.dom[cell]
        for pat in pats:
            self.push_level()
            if self.set_dom(cell, {pat}) and self.propagate() and self.search():
                return True
            self.pop_level()

        # Optional domain wipe to signal failure at this level omitted; caller handles backtracking.
        self.dom[cell] = old_domain
        return False

    def extract_loop_path(self):
        if not self.solved():
            return None
        adj = defaultdict(list)
        for e, v in self.edge_state.items():
            if v == 1:
                a, b = self.edge_endpoints(e)
                adj[a].append(b)
                adj[b].append(a)

        start = min(adj)
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        return path


