    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, 3, None], [None, None, 1, None, None], [None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None]]}

from collections import deque, defaultdict
import ast

# Nurikabe solver with strong propagation and bounded search.
# Output is a Python-literal grid using 'B' for black and None for white.

UNKNOWN = -1
WHITE = 0
BLACK = 1

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    solver = NurikabeSolver(data)
    ans = solver.run()
    if ans is None:
        return "No Solution"
    return repr(ans)


class NurikabeSolver:
    def __init__(self, data):
        self.data = data
        self.R = len(data)
        self.C = len(data[0]) if self.R else 0
        self.N = self.R * self.C
        self.idx_of = lambda r, c: r * self.C + c
        self.rc_of = lambda i: divmod(i, self.C)

        self.neigh = [[] for _ in range(self.N)]
        for r in range(self.R):
            for c in range(self.C):
                i = self.idx_of(r, c)
                for dr, dc in DIRS:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < self.R and 0 <= nc < self.C:
                        self.neigh[i].append(self.idx_of(nr, nc))

        self.numbered = []
        self.required = []
        self.root_index = {}
        for r in range(self.R):
            for c in range(self.C):
                if data[r][c] is not None:
                    self.root_index[(r, c)] = len(self.numbered)
                    self.numbered.append(self.idx_of(r, c))
                    self.required.append(int(data[r][c]))

        self.K = len(self.numbered)
        self.all_mask = (1 << self.K) - 1

        self.initial_color = [UNKNOWN] * self.N
        self.initial_owner = [self.all_mask] * self.N

        for k, root in enumerate(self.numbered):
            self.initial_color[root] = WHITE
            self.initial_owner[root] = 1 << k

        # A numbered cell of size 1 forces all orthogonal neighbors black.
        for k, root in enumerate(self.numbered):
            if self.required[k] == 1:
                for nb in self.neigh[root]:
                    if self.initial_color[nb] == UNKNOWN:
                        self.initial_color[nb] = BLACK
                        self.initial_owner[nb] = 0

        # Numbered cells cannot touch orthogonally as same island would contain >1 number.
        root_set = set(self.numbered)
        for a in self.numbered:
            for b in self.neigh[a]:
                if b in root_set:
                    return

        self.valid = True

    def run(self):
        if not self.valid:
            return None
        state = State(self.initial_color[:], self.initial_owner[:], self)
        if not self.propagate(state):
            return None
        solved = self.search(state)
        if solved is None:
            return None
        return self.to_answer(solved)

    def to_answer(self, state):
        out = []
        for r in range(self.R):
            row = []
            for c in range(self.C):
                i = self.idx_of(r, c)
                row.append('B' if state.color[i] == BLACK else None)
            out.append(row)
        return out

    def search(self, state):
        if self.is_complete(state):
            return state

        move = self.choose_branch(state)
        if move is None:
            return None

        kind = move[0]
        if kind == "cell_color":
            _, cell, options = move
            # Prefer white before black if ownership is narrow; otherwise black first often constrains more.
            ordered = options[:]
            for col in ordered:
                ns = state.copy()
                if not self.assign_color(ns, cell, col):
                    continue
                if not self.propagate(ns):
                    continue
                res = self.search(ns)
                if res is not None:
                    return res
            return None

        if kind == "cell_owner":
            _, cell, owners = move
            for k in owners:
                ns = state.copy()
                if not self.assign_owner(ns, cell, 1 << k):
                    continue
                if not self.propagate(ns):
                    continue
                res = self.search(ns)
                if res is not None:
                    return res
            return None

        return None

    def choose_branch(self, state):
        # Human-like branching:
        # 1) unresolved white ownership with smallest candidate set
        # 2) unresolved color at cells with strongest local effect
        best = None
        best_score = None

        for i in range(self.N):
            if state.color[i] == WHITE:
                m = state.owner[i]
                if m and (m & (m - 1)):
                    cnt = bitcount(m)
                    score = (0, cnt, -self.local_pressure(state, i))
                    if best_score is None or score < best_score:
                        best_score = score
                        best = ("cell_owner", i, bits_list(m))
            elif state.color[i] == UNKNOWN:
                opts = self.color_options(state, i)
                if len(opts) == 0:
                    return None
                if len(opts) == 1:
                    score = (-1, 1, -self.local_pressure(state, i))
                    if best_score is None or score < best_score:
                        best_score = score
                        best = ("cell_color", i, opts)
                else:
                    score = (1, len(opts), -self.local_pressure(state, i))
                    if best_score is None or score < best_score:
                        best_score = score
                        best = ("cell_color", i, opts)

        return best

    def local_pressure(self, state, i):
        # Higher means more constrained / informative.
        s = 0
        for nb in self.neigh[i]:
            if state.color[nb] != UNKNOWN:
                s += 1
            if state.color[nb] == WHITE and single_bit(state.owner[nb]):
                s += 1
        r, c = self.rc_of(i)
        if 0 < r < self.R - 1:
            s += 1
        if 0 < c < self.C - 1:
            s += 1
        return s

    def is_complete(self, state):
        if any(v == UNKNOWN for v in state.color):
            return False
        if not self.final_check(state):
            return False
        return True

    def final_check(self, state):
        # All white cells must have single owner, island sizes exact, one black component.
        for i in range(self.N):
            if state.color[i] == WHITE:
                if not single_bit(state.owner[i]):
                    return False
            elif state.color[i] != BLACK:
                return False

        sizes = [0] * self.K
        for i in range(self.N):
            if state.color[i] == WHITE:
                k = lowbit_index(state.owner[i])
                sizes[k] += 1
        if sizes != self.required:
            return False

        # No 2x2 all black.
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [self.idx_of(r, c), self.idx_of(r + 1, c), self.idx_of(r, c + 1), self.idx_of(r + 1, c + 1)]
                if all(state.color[x] == BLACK for x in cells):
                    return False

        # One black connected group.
        blacks = [i for i, v in enumerate(state.color) if v == BLACK]
        if blacks:
            seen = {blacks[0]}
            dq = deque([blacks[0]])
            while dq:
                x = dq.popleft()
                for nb in self.neigh[x]:
                    if state.color[nb] == BLACK and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(blacks):
                return False

        # Distinct islands not orthogonally merged.
        for i in range(self.N):
            if state.color[i] == WHITE:
                oi = lowbit_index(state.owner[i])
                for nb in self.neigh[i]:
                    if state.color[nb] == WHITE:
                        oj = lowbit_index(state.owner[nb])
                        if oi != oj:
                            return False
        return True

    def propagate(self, state):
        changed = True
        while changed:
            changed = False

            # Recompute owner possibilities from current colors and roots.
            if not self.recompute_owner_domains(state):
                return False

            # Immediate forced assignments from color options.
            for i in range(self.N):
                if state.color[i] == UNKNOWN:
                    opts = self.color_options(state, i)
                    if not opts:
                        return False
                    if len(opts) == 1:
                        if not self.assign_color(state, i, opts[0]):
                            return False
                        changed = True

            # White cells with singleton owner mask.
            for i in range(self.N):
                if state.color[i] == WHITE and state.owner[i] != 0 and not single_bit(state.owner[i]):
                    # If all adjacent white singleton owners same, may collapse later by recompute.
                    pass

            # Island region deductions.
            if not self.propagate_islands(state):
                return False

            # Black 2x2 prevention and black connectivity support.
            if not self.propagate_black_rules(state):
                return False

            # Global viability checks.
            if not self.global_checks(state):
                return False

            # If any assignment occurred in subroutines, detect by re-running domain normalization.
            # We rely on subroutines directly mutating state; so compare option simplifications by another pass.
            before_sig = state.signature_cache
            sig = self.state_signature(state)
            if sig != before_sig:
                state.signature_cache = sig
                changed = True

        return self.final_feasibility(state)

    def state_signature(self, state):
        return (tuple(state.color), tuple(state.owner))

    def assign_color(self, state, cell, color):
        cur = state.color[cell]
        if cur == color:
            return True
        if cur != UNKNOWN and cur != color:
            return False
        state.color[cell] = color
        if color == BLACK:
            state.owner[cell] = 0
        else:
            if state.owner[cell] == 0:
                state.owner[cell] = self.all_mask
        state.signature_cache = None
        return True

    def assign_owner(self, state, cell, mask):
        if state.color[cell] == BLACK:
            return False
        if state.color[cell] == UNKNOWN:
            state.color[cell] = WHITE
        newmask = state.owner[cell] & mask
        if newmask == 0:
            return False
        if newmask != state.owner[cell]:
            state.owner[cell] = newmask
            state.signature_cache = None
        return True

    def color_options(self, state, cell):
        if state.color[cell] == WHITE:
            return [WHITE]
        if state.color[cell] == BLACK:
            return [BLACK]

        opts = []

        # White possible iff some owner can reach cell and local adjacency to known singleton white owners is consistent.
        if state.owner[cell] != 0:
            white_mask = state.owner[cell]
            for nb in self.neigh[cell]:
                if state.color[nb] == WHITE and single_bit(state.owner[nb]):
                    white_mask &= state.owner[nb]
            if white_mask != 0:
                opts.append(WHITE)

        # Black possible iff doesn't immediately make 2x2 and not conflict with numbered/root status.
        black_ok = True
        for r0 in (self.rc_of(cell)[0] - 1, self.rc_of(cell)[0]):
            for c0 in (self.rc_of(cell)[1] - 1, self.rc_of(cell)[1]):
                if 0 <= r0 < self.R - 1 and 0 <= c0 < self.C - 1:
                    cells = [self.idx_of(r0, c0), self.idx_of(r0 + 1, c0), self.idx_of(r0, c0 + 1), self.idx_of(r0 + 1, c0 + 1)]
                    blacks = 0
                    unknowns = 0
                    for x in cells:
                        if x == cell:
                            blacks += 1
                        elif state.color[x] == BLACK:
                            blacks += 1
                        elif state.color[x] == UNKNOWN:
                            unknowns += 1
                    if blacks == 4:
                        black_ok = False
                        break
                if not black_ok:
                    break
            if not black_ok:
                break
        if black_ok:
            opts.append(BLACK)

        return opts

    def recompute_owner_domains(self, state):
        # Owner domains are based on current non-black graph and exclusion from touching fixed foreign singleton islands.
        masks = [0] * self.N

        for k, root in enumerate(self.numbered):
            bit = 1 << k
            seen = {root}
            dq = deque([root])
            while dq:
                x = dq.popleft()
                if state.color[x] == BLACK:
                    continue
                masks[x] |= bit
                for nb in self.neigh[x]:
                    if nb in seen or state.color[nb] == BLACK:
                        continue
                    # Cannot pass through a white cell fixed to a different owner.
                    if state.color[nb] == WHITE and single_bit(state.owner[nb]) and state.owner[nb] != bit:
                        continue
                    # Cannot step onto a white singleton foreign owner.
                    seen.add(nb)
                    dq.append(nb)

        for i in range(self.N):
            if state.color[i] == BLACK:
                state.owner[i] = 0
                continue
            newmask = masks[i]
            if i in self.numbered:
                k = self.numbered.index(i)
                newmask &= (1 << k)
            # White cells adjacent to singleton-owned whites of different owners impossible;
            # if multiple distinct singleton owners adjacent, contradiction.
            singleton_adj = 0
            for nb in self.neigh[i]:
                if state.color[nb] == WHITE and single_bit(state.owner[nb]):
                    singleton_adj |= state.owner[nb]
            if singleton_adj and single_bit(singleton_adj):
                newmask &= singleton_adj
            elif singleton_adj and not single_bit(singleton_adj):
                # If this cell is white or must connect multiple fixed different islands, impossible.
                if state.color[i] == WHITE:
                    return False
                # As unknown, it simply cannot be white.
                pass

            if state.color[i] == WHITE:
                newmask &= state.owner[i]

            if newmask == 0:
                if state.color[i] == WHITE:
                    return False
            state.owner[i] = newmask

        return True

    def propagate_islands(self, state):
        # Analyze each island's current component, capacity, and mandatory expansions.
        components = self.island_components(state)
        if components is None:
            return False

        for k in range(self.K):
            comp = components[k]
            size_now = len(comp)
            req = self.required[k]
            if size_now > req:
                return False

            candidates = self.expandable_cells_for_owner(state, k, comp)
            if size_now + len(candidates) < req:
                return False

            # Exact fit: all candidate cells for this island must be white and owned by k.
            if size_now + len(candidates) == req:
                for cell in candidates:
                    if not self.assign_owner(state, cell, 1 << k):
                        return False

            # If island already full, all orthogonal unknown neighbors must be black.
            if size_now == req:
                border = set()
                for x in comp:
                    for nb in self.neigh[x]:
                        if state.color[nb] == UNKNOWN:
                            border.add(nb)
                        elif state.color[nb] == WHITE and not (state.owner[nb] & (1 << k)):
                            return False
                for cell in border:
                    if not self.assign_color(state, cell, BLACK):
                        return False

            # Single-route growth: if island needs more and a candidate is articulation-needed.
            need = req - size_now
            if need > 0:
                frontier = self.frontier_of_owner(state, k, comp)
                if len(frontier) == 0:
                    return False
                if len(frontier) == 1:
                    only = next(iter(frontier))
                    if not self.assign_owner(state, only, 1 << k):
                        return False

                # Common cell in all possible shortest root-to-candidate expansions:
                # simpler human rule substitute: if a white candidate is the only way to connect
                # an already white ambiguous cell owned by k, force it.
                forced = self.owner_connection_forced_cells(state, k, comp)
                for cell in forced:
                    if not self.assign_owner(state, cell, 1 << k):
                        return False

        # Unknown cell adjacent to two different fixed islands cannot be white => black.
        for i in range(self.N):
            if state.color[i] == UNKNOWN:
                m = 0
                for nb in self.neigh[i]:
                    if state.color[nb] == WHITE and single_bit(state.owner[nb]):
                        m |= state.owner[nb]
                if m and not single_bit(m):
                    if not self.assign_color(state, i, BLACK):
                        return False

        return True

    def island_components(self, state):
        comps = [set() for _ in range(self.K)]
        for k, root in enumerate(self.numbered):
            bit = 1 << k
            if state.color[root] != WHITE or state.owner[root] != bit:
                return None
            seen = {root}
            dq = deque([root])
            while dq:
                x = dq.popleft()
                comps[k].add(x)
                for nb in self.neigh[x]:
                    if nb in seen:
                        continue
                    if state.color[nb] == WHITE and (state.owner[nb] & bit):
                        # If fixed singleton foreign owner, disallow.
                        if single_bit(state.owner[nb]) and state.owner[nb] != bit:
                            continue
                        seen.add(nb)
                        dq.append(nb)
            # If a white cell fixed to k is disconnected from root through white-k cells => contradiction.
        for i in range(self.N):
            if state.color[i] == WHITE and single_bit(state.owner[i]):
                k = lowbit_index(state.owner[i])
                if i not in comps[k]:
                    return None
        return comps

    def expandable_cells_for_owner(self, state, k, comp):
        bit = 1 << k
        vis = set(comp)
        dq = deque(comp)
        cand = set()
        while dq:
            x = dq.popleft()
            for nb in self.neigh[x]:
                if nb in vis or state.color[nb] == BLACK:
                    continue
                if not (state.owner[nb] & bit):
                    continue
                if state.color[nb] == WHITE:
                    vis.add(nb)
                    dq.append(nb)
                    cand.add(nb)
                else:
                    vis.add(nb)
                    cand.add(nb)
                    dq.append(nb)
        return cand - comp

    def frontier_of_owner(self, state, k, comp):
        bit = 1 << k
        frontier = set()
        for x in comp:
            for nb in self.neigh[x]:
                if state.color[nb] != BLACK and (state.owner[nb] & bit) and nb not in comp:
                    frontier.add(nb)
        return frontier

    def owner_connection_forced_cells(self, state, k, comp):
        bit = 1 << k
        forced = set()
        # For each white cell that can belong only to k but is not yet connected in comp, force the only bridge if unique.
        targets = [i for i in range(self.N) if state.color[i] == WHITE and state.owner[i] == bit and i not in comp]
        # Usually unreachable after island_components catches contradictions; but for unknown bottlenecks, inspect near frontier.
        for t in targets:
            paths_first = set()
            q = deque()
            seen = {t}
            q.append((t, None))
            found_dist = None
            dist = {t: 0}
            while q:
                x, first = q.popleft()
                d = dist[x]
                if found_dist is not None and d > found_dist:
                    break
                if x in comp:
                    found_dist = d
                    if first is not None:
                        paths_first.add(first)
                    continue
                for nb in self.neigh[x]:
                    if state.color[nb] == BLACK or not (state.owner[nb] & bit):
                        continue
                    nf = first if first is not None else nb
                    if nb not in dist:
                        dist[nb] = d + 1
                        q.append((nb, nf))
            if len(paths_first) == 1:
                x = next(iter(paths_first))
                if state.color[x] == UNKNOWN:
                    forced.add(x)
        return forced

    def propagate_black_rules(self, state):
        # 2x2 rule: if 3 blacks + 1 unknown, unknown must be white.
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [self.idx_of(r, c), self.idx_of(r + 1, c), self.idx_of(r, c + 1), self.idx_of(r + 1, c + 1)]
                blacks = [x for x in cells if state.color[x] == BLACK]
                unknowns = [x for x in cells if state.color[x] == UNKNOWN]
                if len(blacks) == 4:
                    return False
                if len(blacks) == 3 and len(unknowns) == 1:
                    if not self.assign_color(state, unknowns[0], WHITE):
                        return False

        # Black connectivity necessary condition:
        # all current black components must be connectable through unknown cells.
        if not self.black_connectivity_possible(state):
            return False

        # Unknown cells that are cut-vertices for black connectivity may be forced black.
        forced = self.forced_black_connectors(state)
        for cell in forced:
            if not self.assign_color(state, cell, BLACK):
                return False

        return True

    def black_connectivity_possible(self, state):
        blacks = [i for i, v in enumerate(state.color) if v == BLACK]
        if not blacks:
            return True
        allowed = {i for i, v in enumerate(state.color) if v != WHITE}
        seen = {blacks[0]}
        dq = deque([blacks[0]])
        while dq:
            x = dq.popleft()
            for nb in self.neigh[x]:
                if nb in allowed and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        for b in blacks:
            if b not in seen:
                return False
        return True

    def forced_black_connectors(self, state):
        blacks = [i for i, v in enumerate(state.color) if v == BLACK]
        if len(blacks) <= 1:
            return set()
        # If an unknown cell is the sole bridge in the graph induced by non-white cells between black regions, force it black.
        allowed = [i for i, v in enumerate(state.color) if v != WHITE]
        allowed_set = set(allowed)

        # Build components of current black cells under black-only graph.
        comp_id = {}
        cid = 0
        for b in blacks:
            if b in comp_id:
                continue
            dq = deque([b])
            comp_id[b] = cid
            while dq:
                x = dq.popleft()
                for nb in self.neigh[x]:
                    if state.color[nb] == BLACK and nb not in comp_id:
                        comp_id[nb] = cid
                        dq.append(nb)
            cid += 1
        if cid <= 1:
            return set()

        forced = set()
        for u in range(self.N):
            if state.color[u] != UNKNOWN:
                continue
            seen_black_comp = set()
            for nb in self.neigh[u]:
                if state.color[nb] == BLACK:
                    seen_black_comp.add(comp_id[nb])
            if len(seen_black_comp) >= 2:
                forced.add(u)
        return forced

    def global_checks(self, state):
        # White cells cannot contain two roots in one connected white region possibility.
        if not self.white_region_root_consistency(state):
            return False

        # Capacity checks via maximum possible cells per island and minimum obligatory white counts.
        comps = self.island_components(state)
        if comps is None:
            return False

        total_req = sum(self.required)
        fixed_white = sum(1 for v in state.color if v == WHITE)
        if fixed_white > total_req:
            return False
        possible_white = sum(1 for i in range(self.N) if state.color[i] == WHITE or (state.color[i] == UNKNOWN and state.owner[i] != 0))
        if possible_white < total_req:
            return False

        return True

    def white_region_root_consistency(self, state):
        # Any connected component of cells that are not black and can be white must not contain two fixed roots
        # with no possible black separator due to already white path.
        seen = set()
        roots = set(self.numbered)
        for i in range(self.N):
            if i in seen or state.color[i] == BLACK:
                continue
            dq = deque([i])
            seen.add(i)
            comp = []
            while dq:
                x = dq.popleft()
                comp.append(x)
                for nb in self.neigh[x]:
                    if nb not in seen and state.color[nb] != BLACK:
                        seen.add(nb)
                        dq.append(nb)
            fixed_roots = [x for x in comp if x in roots]
            if len(fixed_roots) <= 1:
                continue
            # If there is a white path component already containing multiple roots, impossible.
            white_part = [x for x in comp if state.color[x] == WHITE]
            if not white_part:
                continue
            wseen = set()
            for x in white_part:
                if x in wseen:
                    continue
                dq = deque([x])
                wseen.add(x)
                touched_roots = set([x]) if x in roots else set()
                while dq:
                    y = dq.popleft()
                    if y in roots:
                        touched_roots.add(y)
                    for nb in self.neigh[y]:
                        if state.color[nb] == WHITE and nb not in wseen:
                            wseen.add(nb)
                            dq.append(nb)
                if len(touched_roots) > 1:
                    return False
        return True

    def final_feasibility(self, state):
        # Every island can still reach required size through some connected non-black cells.
        comps = self.island_components(state)
        if comps is None:
            return False
        for k in range(self.K):
            bit = 1 << k
            comp = comps[k]
            req = self.required[k]
            if len(comp) > req:
                return False
            # BFS through non-black cells that can belong to k
            vis = set(comp)
            dq = deque(comp)
            while dq:
                x = dq.popleft()
                for nb in self.neigh[x]:
                    if nb in vis or state.color[nb] == BLACK or not (state.owner[nb] & bit):
                        continue
                    vis.add(nb)
                    dq.append(nb)
            if len(vis) < req:
                return False
        return True


class State:
    __slots__ = ("color", "owner", "solver", "signature_cache")

    def __init__(self, color, owner, solver):
        self.color = color
        self.owner = owner
        self.solver = solver
        self.signature_cache = None

    def copy(self):
        s = State(self.color[:], self.owner[:], self.solver)
        s.signature_cache = self.signature_cache
        return s


def bitcount(x):
    return x.bit_count()


def single_bit(x):
    return x != 0 and (x & (x - 1)) == 0


def lowbit_index(x):
    return (x.bit_length() - 1)


def bits_list(mask):
    out = []
    while mask:
        b = mask & -mask
        out.append(lowbit_index(b))
        mask ^= b
    return out


