OBSERVATION = {'data': [[1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, 6, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, 1, None, None, 2, None, None, None, 3, None], [2, None, None, None, None, None, None, 3, None, None], [None, None, 2, None, None, None, None, None, None, 2], [None, 3, None, None, None, 3, None, None, 6, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, 2, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None]]}

from collections import deque, defaultdict

UNKNOWN = -1
WHITE = 0
BLACK = 1

DIRS = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def solve(observation):
    data = observation['data']
    solver = NurikabeSolver(data)
    ans = solver.run()
    if ans is None:
        return "No Solution"
    return repr(ans)


class NurikabeSolver:
    def __init__(self, data):
        self.data = data
        self.R = len(data)
        self.C = len(data[0]) if self.R else 0
        self.N = self.R * self.C

        self.idx = lambda r, c: r * self.C + c
        self.rc = lambda i: divmod(i, self.C)

        self.neigh = [[] for _ in range(self.N)]
        for r in range(self.R):
            for c in range(self.C):
                i = self.idx(r, c)
                for dr, dc in DIRS:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < self.R and 0 <= cc < self.C:
                        self.neigh[i].append(self.idx(rr, cc))

        self.numbers = []
        self.clue_of = {}
        for r in range(self.R):
            for c in range(self.C):
                if data[r][c] is not None:
                    i = self.idx(r, c)
                    self.clue_of[i] = len(self.numbers)
                    self.numbers.append((i, data[r][c]))

        self.k = len(self.numbers)
        self.num_pos = [p for p, s in self.numbers]
        self.num_size = [s for p, s in self.numbers]

        self.owner0 = [-1] * self.N
        self.state0 = [UNKNOWN] * self.N
        for j, (p, s) in enumerate(self.numbers):
            self.owner0[p] = j
            self.state0[p] = WHITE

        # Cells orthogonally adjacent to different clues cannot be white.
        for a in range(self.k):
            pa = self.num_pos[a]
            for b in range(a + 1, self.k):
                pb = self.num_pos[b]
                if self.manhattan(pa, pb) == 1:
                    return

        self.initial_valid = True
        self.apply_static_separations(self.state0)

    def manhattan(self, a, b):
        ra, ca = self.rc(a)
        rb, cb = self.rc(b)
        return abs(ra - rb) + abs(ca - cb)

    def apply_static_separations(self, state):
        # Human rule: cells between two clues that would connect islands are black.
        changed = True
        while changed:
            changed = False
            for a in range(self.k):
                pa, sa = self.numbers[a]
                ra, ca = self.rc(pa)
                for b in range(a + 1, self.k):
                    pb, sb = self.numbers[b]
                    rb, cb = self.rc(pb)
                    d = abs(ra - rb) + abs(ca - cb)
                    if d == 2:
                        mids = []
                        if ra == rb:
                            mids.append(self.idx(ra, (ca + cb) // 2))
                        elif ca == cb:
                            mids.append(self.idx((ra + rb) // 2, ca))
                        else:
                            mids.append(self.idx(ra, cb))
                            mids.append(self.idx(rb, ca))
                        for m in mids:
                            if state[m] == UNKNOWN:
                                state[m] = BLACK
                                changed = True

    def run(self):
        if not self.initial_valid:
            return None

        state = self.state0[:]
        owner = self.owner0[:]
        sizes = [1] * self.k

        if not self.propagate(state, owner, sizes):
            return None

        res = self.search(state, owner, sizes)
        if res is None:
            return None
        out = []
        for r in range(self.R):
            row = []
            for c in range(self.C):
                i = self.idx(r, c)
                row.append('B' if res[i] == BLACK else None)
            out.append(row)
        return out

    def copy_state(self, state, owner, sizes):
        return state[:], owner[:], sizes[:]

    def search(self, state, owner, sizes):
        if all(v != UNKNOWN for v in state):
            if self.final_check(state, owner, sizes):
                return state
            return None

        move = self.choose_branch(state, owner, sizes)
        if move is None:
            return None

        cell, options = move
        for kind, val in options:
            ns, no, nz = self.copy_state(state, owner, sizes)
            if kind == 'black':
                if not self.assign_black(cell, ns, no, nz):
                    continue
            elif kind == 'white':
                if not self.assign_white(cell, val, ns, no, nz):
                    continue
            else:
                continue

            if not self.propagate(ns, no, nz):
                continue
            res = self.search(ns, no, nz)
            if res is not None:
                return res
        return None

    def choose_branch(self, state, owner, sizes):
        best = None
        best_score = None

        # Prefer highly constrained unknowns adjacent to determined structure.
        for i in range(self.N):
            if state[i] != UNKNOWN:
                continue

            white_owners = set()
            black_adj = 0
            unk_adj = 0
            for nb in self.neigh[i]:
                if state[nb] == WHITE and owner[nb] != -1:
                    white_owners.add(owner[nb])
                elif state[nb] == BLACK:
                    black_adj += 1
                elif state[nb] == UNKNOWN:
                    unk_adj += 1

            options = []
            if self.can_be_black(i, state):
                options.append(('black', None))
            for j in white_owners:
                if sizes[j] < self.num_size[j]:
                    options.append(('white', j))

            # If no adjacent island owner, try candidates from reachability.
            if not options or (len(options) == 1 and options[0][0] == 'black'):
                cands = self.white_candidate_owners(i, state, owner, sizes)
                for j in cands:
                    pair = ('white', j)
                    if pair not in options:
                        options.append(pair)

            if not options:
                return None

            score = (len(options), -len(white_owners), -black_adj, unk_adj)
            if best is None or score < best_score:
                best = (i, options)
                best_score = score
                if len(options) == 1:
                    break
        return best

    def propagate(self, state, owner, sizes):
        while True:
            progress = False

            if not self.check_basic_consistency(state, owner, sizes):
                return False

            # Completed islands force all frontier cells black.
            for j in range(self.k):
                if sizes[j] == self.num_size[j]:
                    for i in range(self.N):
                        if state[i] == UNKNOWN:
                            for nb in self.neigh[i]:
                                if state[nb] == WHITE and owner[nb] == j:
                                    if not self.assign_black(i, state, owner, sizes):
                                        return False
                                    progress = True
                                    break

            # Unknown cell with no possible white owner must be black.
            # Unknown cell that cannot be black and has a single white owner is forced white.
            for i in range(self.N):
                if state[i] != UNKNOWN:
                    continue
                can_black = self.can_be_black(i, state)
                cands = self.white_candidate_owners(i, state, owner, sizes)
                if not can_black and not cands:
                    return False
                if not cands:
                    if not self.assign_black(i, state, owner, sizes):
                        return False
                    progress = True
                    continue
                if not can_black and len(cands) == 1:
                    if not self.assign_white(i, cands[0], state, owner, sizes):
                        return False
                    progress = True
                    continue

            # Island reachability and capacity checks.
            for j in range(self.k):
                if not self.island_capacity_feasible(j, state, owner, sizes):
                    return False
                forced = self.forced_cells_for_island(j, state, owner, sizes)
                if forced is None:
                    return False
                for i in forced:
                    if state[i] == UNKNOWN:
                        if not self.assign_white(i, j, state, owner, sizes):
                            return False
                        progress = True

            # White connected component with exactly one reachable owner and no black option -> force.
            for comp in self.unknown_components(state):
                owner_set = set()
                for i in comp:
                    for j in self.white_candidate_owners(i, state, owner, sizes):
                        owner_set.add(j)
                if not owner_set:
                    # All must be black, but component may violate black rules if assigned later.
                    for i in comp:
                        if not self.assign_black(i, state, owner, sizes):
                            return False
                        progress = True
                elif len(owner_set) == 1:
                    j = next(iter(owner_set))
                    need = self.num_size[j] - sizes[j]
                    # If component size equals exactly remaining need and every cell can belong only here, force all white.
                    valid_all = True
                    possible_cells = []
                    for i in comp:
                        cands = self.white_candidate_owners(i, state, owner, sizes)
                        if j not in cands:
                            valid_all = False
                            break
                        possible_cells.append(i)
                    if valid_all and len(possible_cells) == need:
                        for i in possible_cells:
                            if state[i] == UNKNOWN:
                                if not self.assign_white(i, j, state, owner, sizes):
                                    return False
                                progress = True

            # Prevent black disconnection early.
            if not self.black_connectivity_feasible(state):
                return False

            if not progress:
                break

        return self.check_basic_consistency(state, owner, sizes) and self.black_connectivity_feasible(state)

    def check_basic_consistency(self, state, owner, sizes):
        # No 2x2 all black.
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [self.idx(r, c), self.idx(r + 1, c), self.idx(r, c + 1), self.idx(r + 1, c + 1)]
                if all(state[x] == BLACK for x in cells):
                    return False

        # White cells must belong to exactly one island and island size can't exceed clue.
        for j in range(self.k):
            if sizes[j] > self.num_size[j]:
                return False

        # Adjacent whites from different owners impossible.
        for i in range(self.N):
            if state[i] == WHITE:
                oi = owner[i]
                if oi == -1:
                    return False
                for nb in self.neigh[i]:
                    if state[nb] == WHITE and owner[nb] != oi:
                        return False

        # Every non-number white cell must connect to its clue through same-owner whites.
        for j in range(self.k):
            cells = [i for i in range(self.N) if state[i] == WHITE and owner[i] == j]
            if len(cells) != sizes[j]:
                return False
            if cells:
                seen = set()
                dq = deque([self.num_pos[j]])
                seen.add(self.num_pos[j])
                while dq:
                    x = dq.popleft()
                    for nb in self.neigh[x]:
                        if state[nb] == WHITE and owner[nb] == j and nb not in seen:
                            seen.add(nb)
                            dq.append(nb)
                if len(seen) != len(cells):
                    return False

        # Unnumbered white components forbidden by owner tracking.
        return True

    def assign_black(self, i, state, owner, sizes):
        if state[i] == BLACK:
            return True
        if state[i] == WHITE:
            return False
        state[i] = BLACK

        r, c = self.rc(i)
        for dr in (-1, 0):
            for dc in (-1, 0):
                rr, cc = r + dr, c + dc
                if 0 <= rr < self.R - 1 and 0 <= cc < self.C - 1:
                    cells = [self.idx(rr, cc), self.idx(rr + 1, cc), self.idx(rr, cc + 1), self.idx(rr + 1, cc + 1)]
                    if all(state[x] == BLACK for x in cells):
                        return False
                    if sum(state[x] == BLACK for x in cells) == 3:
                        for x in cells:
                            if state[x] == UNKNOWN:
                                if not self.assign_nonblack_by_logic(x, state, owner, sizes):
                                    return False
        return True

    def assign_nonblack_by_logic(self, i, state, owner, sizes):
        cands = self.white_candidate_owners(i, state, owner, sizes)
        if len(cands) != 1:
            return False
        return self.assign_white(i, cands[0], state, owner, sizes)

    def assign_white(self, i, j, state, owner, sizes):
        if state[i] == BLACK:
            return False
        if state[i] == WHITE:
            return owner[i] == j

        # Must connect to existing island j by adjacency, unless it's the clue itself.
        if i != self.num_pos[j]:
            ok = False
            for nb in self.neigh[i]:
                if state[nb] == WHITE and owner[nb] == j:
                    ok = True
                    break
            if not ok:
                return False

        # Cannot touch another white island.
        for nb in self.neigh[i]:
            if state[nb] == WHITE and owner[nb] != j:
                return False

        state[i] = WHITE
        owner[i] = j
        sizes[j] += 1 if i != self.num_pos[j] else 0
        if sizes[j] > self.num_size[j]:
            return False

        # Completed island blocks frontier.
        if sizes[j] == self.num_size[j]:
            for x in self.neigh[i]:
                if state[x] == UNKNOWN:
                    if not self.assign_black(x, state, owner, sizes):
                        return False
        return True

    def can_be_black(self, i, state):
        if state[i] == WHITE:
            return False
        r, c = self.rc(i)
        for dr in (-1, 0):
            for dc in (-1, 0):
                rr, cc = r + dr, c + dc
                if 0 <= rr < self.R - 1 and 0 <= cc < self.C - 1:
                    cells = [self.idx(rr, cc), self.idx(rr + 1, cc), self.idx(rr, cc + 1), self.idx(rr + 1, cc + 1)]
                    cnt_black = sum(state[x] == BLACK for x in cells)
                    if i in cells and cnt_black == 3:
                        return False
        return True

    def white_candidate_owners(self, i, state, owner, sizes):
        if state[i] == WHITE:
            return [owner[i]]
        if state[i] == BLACK:
            return []

        adj_owners = set()
        for nb in self.neigh[i]:
            if state[nb] == WHITE:
                adj_owners.add(owner[nb])

        if adj_owners:
            out = []
            for j in adj_owners:
                if sizes[j] < self.num_size[j]:
                    bad = False
                    for nb in self.neigh[i]:
                        if state[nb] == WHITE and owner[nb] != j:
                            bad = True
                            break
                    if not bad:
                        out.append(j)
            return out

        out = []
        for j in range(self.k):
            if sizes[j] >= self.num_size[j]:
                continue
            if self.reachable_from_island(j, i, state, owner, sizes):
                bad = False
                for nb in self.neigh[i]:
                    if state[nb] == WHITE and owner[nb] != j:
                        bad = True
                        break
                if not bad:
                    out.append(j)
        return out

    def reachable_from_island(self, j, target, state, owner, sizes):
        if state[target] == BLACK:
            return False
        limit = self.num_size[j] - sizes[j]
        if limit <= 0:
            return False

        start_cells = [i for i in range(self.N) if state[i] == WHITE and owner[i] == j]
        seen = set(start_cells)
        dq = deque((x, 0) for x in start_cells)
        while dq:
            x, d = dq.popleft()
            if x == target:
                return True
            if d == limit:
                continue
            for nb in self.neigh[x]:
                if nb in seen:
                    continue
                if state[nb] == BLACK:
                    continue
                if state[nb] == WHITE and owner[nb] != j:
                    continue
                seen.add(nb)
                dq.append((nb, d + 1))
        return False

    def island_capacity_feasible(self, j, state, owner, sizes):
        need = self.num_size[j] - sizes[j]
        if need < 0:
            return False
        if need == 0:
            return True

        start = [i for i in range(self.N) if state[i] == WHITE and owner[i] == j]
        seen = set(start)
        dq = deque(start)
        candidates = set()
        while dq:
            x = dq.popleft()
            for nb in self.neigh[x]:
                if nb in seen:
                    continue
                if state[nb] == BLACK:
                    continue
                if state[nb] == WHITE and owner[nb] != j:
                    continue
                seen.add(nb)
                dq.append(nb)
                if state[nb] == UNKNOWN:
                    candidates.add(nb)
        return len(candidates) >= need

    def forced_cells_for_island(self, j, state, owner, sizes):
        need = self.num_size[j] - sizes[j]
        if need <= 0:
            return set()

        reach = self.reachable_unknowns_of_island(j, state, owner)
        if len(reach) < need:
            return None
        if len(reach) == need:
            return set(reach)

        # Articulation-like human rule via indispensability:
        # if excluding a candidate leaves insufficient connected expansion, candidate is forced.
        forced = set()
        for cell in list(reach):
            if not self.island_can_fill_without(j, cell, state, owner, sizes):
                forced.add(cell)
        return forced

    def reachable_unknowns_of_island(self, j, state, owner):
        start = [i for i in range(self.N) if state[i] == WHITE and owner[i] == j]
        seen = set(start)
        dq = deque(start)
        reach = set()
        while dq:
            x = dq.popleft()
            for nb in self.neigh[x]:
                if nb in seen:
                    continue
                if state[nb] == BLACK:
                    continue
                if state[nb] == WHITE and owner[nb] != j:
                    continue
                seen.add(nb)
                dq.append(nb)
                if state[nb] == UNKNOWN:
                    reach.add(nb)
        return reach

    def island_can_fill_without(self, j, forbidden, state, owner, sizes):
        need = self.num_size[j] - sizes[j]
        start = [i for i in range(self.N) if state[i] == WHITE and owner[i] == j]
        seen = set(start)
        dq = deque(start)
        cnt = 0
        while dq:
            x = dq.popleft()
            for nb in self.neigh[x]:
                if nb == forbidden or nb in seen:
                    continue
                if state[nb] == BLACK:
                    continue
                if state[nb] == WHITE and owner[nb] != j:
                    continue
                seen.add(nb)
                dq.append(nb)
                if state[nb] == UNKNOWN:
                    cnt += 1
        return cnt >= need

    def unknown_components(self, state):
        seen = set()
        comps = []
        for i in range(self.N):
            if state[i] != UNKNOWN or i in seen:
                continue
            comp = []
            dq = deque([i])
            seen.add(i)
            while dq:
                x = dq.popleft()
                comp.append(x)
                for nb in self.neigh[x]:
                    if state[nb] == UNKNOWN and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            comps.append(comp)
        return comps

    def black_connectivity_feasible(self, state):
        blacks = [i for i in range(self.N) if state[i] == BLACK]
        if not blacks:
            return True

        allowed = set(i for i in range(self.N) if state[i] != WHITE)
        start = blacks[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for nb in self.neigh[x]:
                if nb in allowed and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)

        for b in blacks:
            if b not in seen:
                return False
        return True

    def final_check(self, state, owner, sizes):
        if not self.check_basic_consistency(state, owner, sizes):
            return False

        for j in range(self.k):
            if sizes[j] != self.num_size[j]:
                return False

        blacks = [i for i in range(self.N) if state[i] == BLACK]
        if blacks:
            seen = {blacks[0]}
            dq = deque([blacks[0]])
            while dq:
                x = dq.popleft()
                for nb in self.neigh[x]:
                    if state[nb] == BLACK and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(blacks):
                return False

        for i in range(self.N):
            if state[i] == WHITE and owner[i] == -1:
                return False

        return True


