from collections import deque

B = 1
W = 0
U = -1

def solve(observation):
    data = observation['data']
    n = len(data)
    grid = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] == 'B':
                grid[r][c] = B
            elif data[r][c] == 'W':
                grid[r][c] = W

    neighbors = [[[] for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r > 0:
                neighbors[r][c].append((r - 1, c))
            if r + 1 < n:
                neighbors[r][c].append((r + 1, c))
            if c > 0:
                neighbors[r][c].append((r, c - 1))
            if c + 1 < n:
                neighbors[r][c].append((r, c + 1))

    def clone(g):
        return [row[:] for row in g]

    def set_cell(g, r, c, val, q):
        cur = g[r][c]
        if cur != U:
            return cur == val
        g[r][c] = val
        q.append((r, c))
        return True

    def apply_local_rules(g):
        q = deque()
        for r in range(n):
            for c in range(n):
                if g[r][c] != U:
                    q.append((r, c))

        while q:
            r, c = q.popleft()

            # Rule 1: 2x2 cannot be monochrome; if 3 fixed same, 4th forced opposite
            for rr in (r - 1, r):
                for cc in (c - 1, c):
                    if 0 <= rr < n - 1 and 0 <= cc < n - 1:
                        cells = [(rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)]
                        vals = [g[x][y] for x, y in cells]
                        if U not in vals:
                            if vals[0] == vals[1] == vals[2] == vals[3]:
                                return False
                        else:
                            cntB = vals.count(B)
                            cntW = vals.count(W)
                            cntU = vals.count(U)
                            if cntU == 1 and (cntB == 3 or cntW == 3):
                                idx = vals.index(U)
                                x, y = cells[idx]
                                forced = W if cntB == 3 else B
                                if not set_cell(g, x, y, forced, q):
                                    return False

            # Rule 2: Avoid disconnecting a color by making a degree-1 corridor impossible.
            # If an assigned cell of color v has two opposite neighbors of other color,
            # side-adjacent unknowns may be forced to preserve non-monochrome 2x2 and path continuity.
            v = g[r][c]
            if v != U:
                # Horizontal sandwich of opposite color forces this color in middle-adjacent extension
                if c - 1 >= 0 and c + 1 < n:
                    lv, rv = g[r][c - 1], g[r][c + 1]
                    if lv == rv != U and lv != v:
                        for nr, nc in ((r - 1, c), (r + 1, c)):
                            if 0 <= nr < n:
                                # no immediate force generally; handled by 2x2 and connectivity checks
                                pass
                # Vertical sandwich
                if r - 1 >= 0 and r + 1 < n:
                    uv, dv = g[r - 1][c], g[r + 1][c]
                    if uv == dv != U and uv != v:
                        for nr, nc in ((r, c - 1), (r, c + 1)):
                            if 0 <= nc < n:
                                pass

        return True

    def components_info(g, color):
        seen = [[False] * n for _ in range(n)]
        comps = []
        unassigned_adj = []
        for r in range(n):
            for c in range(n):
                if g[r][c] == color and not seen[r][c]:
                    dq = deque([(r, c)])
                    seen[r][c] = True
                    comp = []
                    frontier = set()
                    while dq:
                        x, y = dq.popleft()
                        comp.append((x, y))
                        for nx, ny in neighbors[x][y]:
                            if g[nx][ny] == color and not seen[nx][ny]:
                                seen[nx][ny] = True
                                dq.append((nx, ny))
                            elif g[nx][ny] == U:
                                frontier.add((nx, ny))
                    comps.append(comp)
                    unassigned_adj.append(frontier)
        return comps, unassigned_adj

    def unassigned_regions(g):
        seen = [[False] * n for _ in range(n)]
        regs = []
        for r in range(n):
            for c in range(n):
                if g[r][c] == U and not seen[r][c]:
                    dq = deque([(r, c)])
                    seen[r][c] = True
                    reg = []
                    while dq:
                        x, y = dq.popleft()
                        reg.append((x, y))
                        for nx, ny in neighbors[x][y]:
                            if g[nx][ny] == U and not seen[nx][ny]:
                                seen[nx][ny] = True
                                dq.append((nx, ny))
                    regs.append(reg)
        return regs

    def connectivity_possible(g, color):
        comps, frontiers = components_info(g, color)
        if len(comps) <= 1:
            return True
        regs = unassigned_regions(g)
        if not regs:
            return False
        # Build component graph via unknown regions touching them.
        k = len(comps)
        comp_graph = [set() for _ in range(k)]
        cell_to_comp = {}
        for i, comp in enumerate(comps):
            for cell in comp:
                cell_to_comp[cell] = i
        for reg in regs:
            touch = set()
            for x, y in reg:
                for nx, ny in neighbors[x][y]:
                    if g[nx][ny] == color:
                        touch.add(cell_to_comp[(nx, ny)])
            touch = list(touch)
            for i in range(len(touch)):
                for j in range(i + 1, len(touch)):
                    a, b = touch[i], touch[j]
                    comp_graph[a].add(b)
                    comp_graph[b].add(a)
        seen = {0}
        dq = deque([0])
        while dq:
            u = dq.popleft()
            for v in comp_graph[u]:
                if v not in seen:
                    seen.add(v)
                    dq.append(v)
        return len(seen) == k

    def no_closed_island(g, color):
        # If a component of color has no adjacent unknown and there are other cells
        comps, frontiers = components_info(g, color)
        if len(comps) <= 1:
            return True
        for fr in frontiers:
            if not fr:
                return False
        return True

    def check_no_monochrome_2x2(g):
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [g[r][c], g[r + 1][c], g[r][c + 1], g[r + 1][c + 1]]
                if U not in vals and vals[0] == vals[1] == vals[2] == vals[3]:
                    return False
        return True

    def final_connected(g, color):
        cells = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
        if not cells:
            return False
        start = cells[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x, y = dq.popleft()
            for nx, ny in neighbors[x][y]:
                if g[nx][ny] == color and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    dq.append((nx, ny))
        return len(seen) == len(cells)

    def consistent(g):
        if not check_no_monochrome_2x2(g):
            return False
        if not no_closed_island(g, B):
            return False
        if not no_closed_island(g, W):
            return False
        if not connectivity_possible(g, B):
            return False
        if not connectivity_possible(g, W):
            return False
        return True

    def propagate(g):
        changed = True
        while changed:
            changed = False
            before = tuple(tuple(row) for row in g)
            if not apply_local_rules(g):
                return False
            if not consistent(g):
                return False

            # Region-based human rule:
            # An unknown region that can touch only one color must become that color
            regs = unassigned_regions(g)
            for reg in regs:
                touches = set()
                for x, y in reg:
                    for nx, ny in neighbors[x][y]:
                        if g[nx][ny] == B:
                            touches.add(B)
                        elif g[nx][ny] == W:
                            touches.add(W)
                if len(touches) == 1:
                    forced = next(iter(touches))
                    q = deque()
                    for x, y in reg:
                        if not set_cell(g, x, y, forced, q):
                            return False
                    if not apply_local_rules(g):
                        return False
                    if not consistent(g):
                        return False

            after = tuple(tuple(row) for row in g)
            changed = before != after
        return True

    def is_complete(g):
        return all(g[r][c] != U for r in range(n) for c in range(n))

    def final_check(g):
        return check_no_monochrome_2x2(g) and final_connected(g, B) and final_connected(g, W)

    def score_cell(g, r, c):
        score = 0
        for rr in (r - 1, r):
            for cc in (c - 1, c):
                if 0 <= rr < n - 1 and 0 <= cc < n - 1:
                    vals = [g[rr][cc], g[rr + 1][cc], g[rr][cc + 1], g[rr + 1][cc + 1]]
                    if U in vals:
                        score += 3
                        if vals.count(U) == 1:
                            score += 10
        for nx, ny in neighbors[r][c]:
            if g[nx][ny] != U:
                score += 2
        return score

    def choose_cell(g):
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if g[r][c] == U:
                    s = score_cell(g, r, c)
                    if s > best_score:
                        best_score = s
                        best = (r, c)
        return best

    def branch_order(g, r, c):
        cnt = {B: 0, W: 0}
        for nx, ny in neighbors[r][c]:
            if g[nx][ny] == B:
                cnt[B] += 1
            elif g[nx][ny] == W:
                cnt[W] += 1
        if cnt[B] > cnt[W]:
            return [B, W]
        if cnt[W] > cnt[B]:
            return [W, B]
        return [B, W]

    def dfs(g):
        if not propagate(g):
            return None
        if is_complete(g):
            return g if final_check(g) else None
        r, c = choose_cell(g)
        for val in branch_order(g, r, c):
            ng = clone(g)
            q = deque()
            if set_cell(ng, r, c, val, q):
                res = dfs(ng)
                if res is not None:
                    return res
        return None

    ans = dfs(grid)
    if ans is None:
        return "No Solution"
    out = [['B' if ans[r][c] == B else 'W' for c in range(n)] for r in range(n)]
    return str(out)

