from collections import deque
import ast

# General Nurikabe solver with strong propagation and bounded search.
# Output format: Python literal list of lists using 'B' for black and None for white.

UNKNOWN = -1
WHITE = 0
BLACK = 1

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0
    n = h * w

    def idx(r, c):
        return r * w + c

    def rc(i):
        return divmod(i, w)

    neighbors = [[] for _ in range(n)]
    for r in range(h):
        for c in range(w):
            i = idx(r, c)
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    neighbors[i].append(idx(rr, cc))

    numbered = []
    number_at = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                i = idx(r, c)
                numbered.append(i)
                number_at[i] = data[r][c]

    k = len(numbered)
    island_index = {root: t for t, root in enumerate(numbered)}
    island_sizes = [number_at[root] for root in numbered]

    # Precompute all connected candidate shapes for each island root.
    # Each shape is a frozenset of cell indices, connected, contains root, and size == target.
    def enumerate_shapes(root, target):
        shapes = set()
        start = frozenset([root])

        def rec(shape, frontier):
            if len(shape) == target:
                shapes.add(shape)
                return
            need = target - len(shape)
            if len(shape) + len(frontier) < target:
                return
            # Symmetry reduction by deterministic ordering
            for cell in sorted(frontier):
                new_shape = shape | {cell}
                new_frontier = set(frontier)
                new_frontier.discard(cell)
                for nb in neighbors[cell]:
                    if nb not in new_shape:
                        new_frontier.add(nb)
                # Simple connected reachability bound
                if len(new_shape) + len(new_frontier) < target:
                    continue
                rec(new_shape, frozenset(new_frontier))

        init_frontier = frozenset(nb for nb in neighbors[root] if nb != root)
        rec(start, init_frontier)
        return [set(s) for s in shapes]

    all_shapes = []
    cell_to_shapes = [dict() for _ in range(k)]
    for t, root in enumerate(numbered):
        shapes = enumerate_shapes(root, island_sizes[t])
        # Filter any shape containing another numbered cell
        valid = []
        for s in shapes:
            bad = False
            for j in numbered:
                if j != root and j in s:
                    bad = True
                    break
            if not bad:
                valid.append(s)
        all_shapes.append(valid)
        m = {}
        for si, s in enumerate(valid):
            for cell in s:
                m.setdefault(cell, []).append(si)
        cell_to_shapes[t] = m

    # If any island has no possible shape, impossible.
    if any(len(v) == 0 for v in all_shapes):
        return "No Solution"

    all_cells = set(range(n))
    numbered_set = set(numbered)

    # State
    colors = [UNKNOWN] * n
    owner = [None] * n  # if WHITE and assigned to a specific island, stores island index
    domains = [set(range(len(all_shapes[t]))) for t in range(k)]

    for t, root in enumerate(numbered):
        colors[root] = WHITE
        owner[root] = t

    # Utility functions
    def clone_state(colors, owner, domains):
        return colors[:], owner[:], [d.copy() for d in domains]

    def compatible_shape(t, shape, colors, owner):
        # Shape cells must be non-black and not claimed by another island.
        for cell in shape:
            if colors[cell] == BLACK:
                return False
            if owner[cell] is not None and owner[cell] != t:
                return False
            if cell in numbered_set:
                if cell != numbered[t]:
                    return False
        # Cells outside shape cannot be root-assigned to this island only if already owner t? that's allowed;
        # domain logic will handle exactness.
        return True

    def set_color(cell, col, colors, owner, domains, queue):
        cur = colors[cell]
        if cur == col:
            return True
        if cur != UNKNOWN and cur != col:
            return False
        colors[cell] = col
        queue.append(("cell", cell))
        return True

    def assign_owner(cell, t, colors, owner, domains, queue):
        if owner[cell] == t:
            return True
        if owner[cell] is not None and owner[cell] != t:
            return False
        owner[cell] = t
        if not set_color(cell, WHITE, colors, owner, domains, queue):
            return False
        queue.append(("own", cell))
        return True

    def prune_domains(colors, owner, domains, queue):
        changed = True
        while changed:
            changed = False
            for t in range(k):
                dom = domains[t]
                bad = []
                root = numbered[t]
                for si in dom:
                    s = all_shapes[t][si]
                    if not compatible_shape(t, s, colors, owner):
                        bad.append(si)
                        continue
                    # Any numbered cell from another island cannot be in shape
                    # already handled by compatible_shape.
                    # If a cell is already white and assigned to t but not in shape, impossible for this shape.
                    impossible = False
                    for cell in range(n):
                        if owner[cell] == t and cell not in s:
                            impossible = True
                            break
                    if impossible:
                        bad.append(si)
                if bad:
                    dom.difference_update(bad)
                    changed = True
                    queue.append(("dom", t))
                if not dom:
                    return False

                # Forced membership / forced exclusion from island shapes
                union_cells = set()
                inter_cells = None
                for si in dom:
                    s = all_shapes[t][si]
                    union_cells |= s
                    inter_cells = set(s) if inter_cells is None else inter_cells & s

                # Cells in all shapes are white and owned by t
                for cell in inter_cells:
                    if not assign_owner(cell, t, colors, owner, domains, queue):
                        return False

                # Any currently owned-by-t cell must remain in every shape; checked above.
                # Cells not in union cannot belong to t; if they are white unowned no direct action.

                # If domain singleton, assign exact island footprint and blacklist adjacent numbered ownership conflicts via exactness.
                if len(dom) == 1:
                    si = next(iter(dom))
                    s = all_shapes[t][si]
                    for cell in s:
                        if not assign_owner(cell, t, colors, owner, domains, queue):
                            return False

            # Any white unowned cell that can belong to no island -> contradiction.
            for cell in range(n):
                if colors[cell] == WHITE and owner[cell] is None:
                    poss = []
                    for t in range(k):
                        if cell in cell_to_shapes[t]:
                            for si in domains[t]:
                                if si in cell_to_shapes[t][cell]:
                                    poss.append(t)
                                    break
                    if not poss:
                        return False
                    if len(poss) == 1:
                        if not assign_owner(cell, poss[0], colors, owner, domains, queue):
                            return False

            # Any unknown cell that belongs to no remaining island shape must be black.
            for cell in range(n):
                if colors[cell] == UNKNOWN:
                    possible_white = False
                    for t in range(k):
                        lst = cell_to_shapes[t].get(cell)
                        if lst:
                            for si in lst:
                                if si in domains[t]:
                                    possible_white = True
                                    break
                        if possible_white:
                            break
                    if not possible_white:
                        if not set_color(cell, BLACK, colors, owner, domains, queue):
                            return False
        return True

    def no_2x2_rule(colors, owner, domains, queue):
        for r in range(h - 1):
            for c in range(w - 1):
                block = [idx(r, c), idx(r + 1, c), idx(r, c + 1), idx(r + 1, c + 1)]
                blacks = sum(colors[x] == BLACK for x in block)
                unknowns = [x for x in block if colors[x] == UNKNOWN]
                if blacks == 4:
                    return False
                if blacks == 3 and len(unknowns) == 1:
                    if not set_color(unknowns[0], WHITE, colors, owner, domains, queue):
                        return False
        return True

    def adjacent_number_separation(colors, owner, domains, queue):
        # Cells orthogonally between distinct numbered roots cannot merge islands;
        # if two numbered cells are adjacent, impossible unless same number root impossible in Nurikabe.
        for a in range(k):
            for b in range(a + 1, k):
                ra = numbered[a]
                rb = numbered[b]
                if rb in neighbors[ra]:
                    return False
        # Any cell adjacent to forced owners of different islands cannot be white if it would connect both?
        # Simpler robust rule: if unknown cell has white neighbors from different owners, it must be black.
        for cell in range(n):
            if colors[cell] == UNKNOWN:
                owns = {owner[nb] for nb in neighbors[cell] if colors[nb] == WHITE and owner[nb] is not None}
                if len(owns) >= 2:
                    if not set_color(cell, BLACK, colors, owner, domains, queue):
                        return False
        return True

    def white_connectivity_owner_rule(colors, owner, domains, queue):
        # If a white component contains two different numbered roots/owners, impossible.
        seen = [False] * n
        for i in range(n):
            if colors[i] == WHITE and not seen[i]:
                comp = []
                dq = [i]
                seen[i] = True
                roots = set()
                ownerset = set()
                while dq:
                    x = dq.pop()
                    comp.append(x)
                    if x in island_index:
                        roots.add(island_index[x])
                    if owner[x] is not None:
                        ownerset.add(owner[x])
                    for nb in neighbors[x]:
                        if colors[nb] == WHITE and not seen[nb]:
                            seen[nb] = True
                            dq.append(nb)
                if len(roots) >= 2:
                    return False
                if len(ownerset) >= 2:
                    return False
                if len(roots) == 1:
                    t = next(iter(roots))
                    for cell in comp:
                        if not assign_owner(cell, t, colors, owner, domains, queue):
                            return False
                elif len(ownerset) == 1:
                    t = next(iter(ownerset))
                    for cell in comp:
                        if not assign_owner(cell, t, colors, owner, domains, queue):
                            return False
        return True

    def black_connectivity_prune(colors, owner, domains, queue):
        # Black cells must be able to form a single connected component through non-white cells.
        blacks = [i for i, c in enumerate(colors) if c == BLACK]
        if not blacks:
            return True
        allowed = {i for i, c in enumerate(colors) if c != WHITE}
        start = blacks[0]
        seen = {start}
        dq = [start]
        while dq:
            x = dq.pop()
            for nb in neighbors[x]:
                if nb in allowed and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        for b in blacks:
            if b not in seen:
                return False
        # If an unknown cell cannot connect any black regions and turning white is impossible maybe leave it.
        return True

    def final_black_connected(colors):
        blacks = [i for i, c in enumerate(colors) if c == BLACK]
        if not blacks:
            return False
        seen = {blacks[0]}
        dq = [blacks[0]]
        while dq:
            x = dq.pop()
            for nb in neighbors[x]:
                if colors[nb] == BLACK and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(blacks)

    def finalize_check(colors, owner, domains):
        # All cells decided
        if any(c == UNKNOWN for c in colors):
            return False
        # White islands exact and unique
        seen = [False] * n
        found_roots = set()
        for i in range(n):
            if colors[i] == WHITE and not seen[i]:
                comp = []
                dq = [i]
                seen[i] = True
                roots = []
                while dq:
                    x = dq.pop()
                    comp.append(x)
                    if x in island_index:
                        roots.append(x)
                    for nb in neighbors[x]:
                        if colors[nb] == WHITE and not seen[nb]:
                            seen[nb] = True
                            dq.append(nb)
                if len(roots) != 1:
                    return False
                root = roots[0]
                if len(comp) != number_at[root]:
                    return False
                found_roots.add(root)
        if found_roots != numbered_set:
            return False
        # No 2x2 black
        for r in range(h - 1):
            for c in range(w - 1):
                block = [idx(r, c), idx(r + 1, c), idx(r, c + 1), idx(r + 1, c + 1)]
                if all(colors[x] == BLACK for x in block):
                    return False
        # Connected black
        return final_black_connected(colors)

    def propagate(colors, owner, domains):
        queue = deque([("init", None)])
        while queue:
            queue.popleft()
            if not prune_domains(colors, owner, domains, queue):
                return False
            if not no_2x2_rule(colors, owner, domains, queue):
                return False
            if not adjacent_number_separation(colors, owner, domains, queue):
                return False
            if not white_connectivity_owner_rule(colors, owner, domains, queue):
                return False
            if not black_connectivity_prune(colors, owner, domains, queue):
                return False

            # If a cell is black, neighbors that are numbered remain white already.
            # If a cell is white and assigned to t, incompatible domains removed by prune_domains.

            # If unknown cell has black on three corners of any 2x2 handled already.

            # If unknown cell adjacent to a completed island and cannot belong to any other island, make black.
            for t in range(k):
                if len(domains[t]) == 1:
                    s = all_shapes[t][next(iter(domains[t]))]
                    border = set()
                    for cell in s:
                        for nb in neighbors[cell]:
                            if nb not in s:
                                border.add(nb)
                    for cell in border:
                        if colors[cell] == UNKNOWN:
                            possible_white_elsewhere = False
                            for u in range(k):
                                if u == t:
                                    continue
                                lst = cell_to_shapes[u].get(cell)
                                if lst:
                                    for si in lst:
                                        if si in domains[u]:
                                            possible_white_elsewhere = True
                                            break
                                if possible_white_elsewhere:
                                    break
                            if not possible_white_elsewhere:
                                if not set_color(cell, BLACK, colors, owner, domains, queue):
                                    return False

        return True

    def choose_branch(colors, owner, domains):
        # Prefer island with smallest domain > 1
        best = None
        best_score = None
        for t in range(k):
            d = len(domains[t])
            if d > 1:
                # smaller domain, larger shape size, more constrained
                score = (d, -island_sizes[t])
                if best_score is None or score < best_score:
                    best_score = score
                    best = ("domain", t)
        if best is not None:
            return best

        # Otherwise choose unknown cell with constrained white possibilities
        best_cell = None
        best_tuple = None
        for cell in range(n):
            if colors[cell] == UNKNOWN:
                poss = 0
                for t in range(k):
                    lst = cell_to_shapes[t].get(cell)
                    if lst:
                        for si in lst:
                            if si in domains[t]:
                                poss += 1
                                break
                score = (poss, -sum(colors[nb] != UNKNOWN for nb in neighbors[cell]))
                if best_tuple is None or score < best_tuple:
                    best_tuple = score
                    best_cell = cell
        if best_cell is not None:
            return ("cell", best_cell)
        return None

    def search(colors, owner, domains):
        if not propagate(colors, owner, domains):
            return None
        if finalize_check(colors, owner, domains):
            return colors

        branch = choose_branch(colors, owner, domains)
        if branch is None:
            return None

        kind, val = branch
        if kind == "domain":
            t = val
            # Try shapes in heuristic order: more overlap with current white assignments first
            choices = list(domains[t])
            choices.sort(key=lambda si: (
                -sum(owner[cell] == t for cell in all_shapes[t][si]),
                -sum(colors[cell] == WHITE for cell in all_shapes[t][si]),
                len(all_shapes[t][si])
            ))
            for si in choices:
                c2, o2, d2 = clone_state(colors, owner, domains)
                d2[t] = {si}
                res = search(c2, o2, d2)
                if res is not None:
                    return res
            return None
        else:
            cell = val
            # Branch smarter: if cell has no white possibility, only black.
            white_possible = []
            for t in range(k):
                lst = cell_to_shapes[t].get(cell)
                if lst:
                    for si in lst:
                        if si in domains[t]:
                            white_possible.append(t)
                            break
            # Order by stronger likely deduction.
            options = []
            if white_possible:
                options.append(WHITE)
            options.append(BLACK)

            for col in options:
                c2, o2, d2 = clone_state(colors, owner, domains)
                q = deque()
                if not set_color(cell, col, c2, o2, d2, q):
                    continue
                if col == WHITE and len(white_possible) == 1:
                    if not assign_owner(cell, white_possible[0], c2, o2, d2, q):
                        continue
                res = search(c2, o2, d2)
                if res is not None:
                    return res
            return None

    result = search(colors, owner, domains)
    if result is None:
        return "No Solution"

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if result[idx(r, c)] == BLACK else None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [['B', None, None, None, None, 'B', None, None, None, None], [None, None, 'B', 'W', None, None, None, None, 'W', 'W'], [None, None, None, None, 'W', None, None, 'W', 'W', None], [None, None, 'W', 'W', None, None, None, None, None, None], ['W', None, None, 'W', 'B', 'W', None, 'W', None, None], ['W', None, 'W', 'B', None, 'B', None, 'W', None, 'W'], [None, 'W', None, None, 'W', 'W', None, None, None, None], [None, None, None, 'W', None, 'B', 'W', None, None, None], ['W', None, 'W', None, None, None, 'W', None, None, 'W'], ['B', None, None, None, None, None, None, None, None, None]]}

from collections import deque

# Masyu solver using human-like deduction plus strongly-pruned search.
# Grid interpretation:
# - observation['data'] is an N x N array of clues at lattice points (dots).
# - Candidate loop edges lie between orthogonally adjacent dots.
# - Solution is a single simple cycle through all clue vertices.

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    vid = lambda r, c: r * n + c
    rc = lambda v: divmod(v, n)

    clue = {}
    for r in range(n):
        for c in range(n):
            if data[r][c] in ("W", "B"):
                clue[vid(r, c)] = data[r][c]

    # Edge indexing
    edge_u = []
    edge_v = []
    edge_index = {}
    incident = [[] for _ in range(n * n)]
    dir_edge = [[-1] * 4 for _ in range(n * n)]

    def add_edge(a, b, da):
        i = len(edge_u)
        edge_u.append(a)
        edge_v.append(b)
        edge_index[(min(a, b), max(a, b))] = i
        incident[a].append(i)
        incident[b].append(i)
        dir_edge[a][da] = i
        dir_edge[b][OPP[da]] = i

    for r in range(n):
        for c in range(n):
            a = vid(r, c)
            if c + 1 < n:
                add_edge(a, vid(r, c + 1), 1)
            if r + 1 < n:
                add_edge(a, vid(r + 1, c), 2)

    m = len(edge_u)

    # Edge state: -1 unknown, 0 forbidden, 1 used
    state = [-1] * m

    # Vertex counts
    deg_on = [0] * (n * n)
    deg_off = [0] * (n * n)
    deg_unk = [len(incident[v]) for v in range(n * n)]

    # For clue reasoning, maintain used directions mask
    used_dirs = [0] * (n * n)
    off_dirs = [0] * (n * n)

    # Union-find over currently used edges to detect premature small cycles
    parent = list(range(n * n))
    size = [1] * (n * n)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    # trail for backtracking
    trail = []
    queue = deque()

    def push_trail(kind, *vals):
        trail.append((kind, vals))

    def snapshot():
        return len(trail)

    def rollback(snap):
        nonlocal queue
        while len(trail) > snap:
            kind, vals = trail.pop()
            if kind == "edge":
                e, old = vals
                state[e] = old
            elif kind == "deg":
                arr_name, idx, old = vals
                if arr_name == "deg_on":
                    deg_on[idx] = old
                elif arr_name == "deg_off":
                    deg_off[idx] = old
                elif arr_name == "deg_unk":
                    deg_unk[idx] = old
                elif arr_name == "used_dirs":
                    used_dirs[idx] = old
                elif arr_name == "off_dirs":
                    off_dirs[idx] = old
            elif kind == "uf_parent":
                idx, old = vals
                parent[idx] = old
            elif kind == "uf_size":
                idx, old = vals
                size[idx] = old
        queue = deque()

    def edge_dir_from(v, e):
        a, b = edge_u[e], edge_v[e]
        other = b if a == v else a
        vr, vc = rc(v)
        orr, occ = rc(other)
        dr, dc = orr - vr, occ - vc
        for d, (x, y) in enumerate(DIRS):
            if (dr, dc) == (x, y):
                return d
        return -1

    def set_edge(e, val):
        if state[e] == val:
            return True
        if state[e] != -1:
            return False
        push_trail("edge", e, state[e])
        state[e] = val
        a, b = edge_u[e], edge_v[e]

        for v in (a, b):
            d = edge_dir_from(v, e)
            if val == 1:
                push_trail("deg", "deg_on", v, deg_on[v])
                deg_on[v] += 1
                push_trail("deg", "used_dirs", v, used_dirs[v])
                used_dirs[v] |= (1 << d)
            else:
                push_trail("deg", "deg_off", v, deg_off[v])
                deg_off[v] += 1
                push_trail("deg", "off_dirs", v, off_dirs[v])
                off_dirs[v] |= (1 << d)
            push_trail("deg", "deg_unk", v, deg_unk[v])
            deg_unk[v] -= 1
            queue.append(v)

        if val == 1:
            ra, rb = find(a), find(b)
            if ra == rb:
                # A cycle closed. Only allowed if all used-degree vertices are exactly degree 2 and no unknown used extension exists.
                # Defer exact check via propagation/global validation, but reject if there exists any vertex with degree 1 already in this component.
                comp = ra
                cyc_vertices = []
                for v in range(n * n):
                    if deg_on[v] > 0 and find(v) == comp:
                        cyc_vertices.append(v)
                all_closed = all(deg_on[v] == 2 for v in cyc_vertices)
                # If all closed but there are other used vertices elsewhere or possible required clues omitted, handled later.
                if not all_closed:
                    return False
            else:
                push_trail("uf_parent", rb, parent[rb])
                push_trail("uf_size", ra, size[ra])
                union(a, b)
        return True

    def force_vertex_degree(v):
        # Any loop vertex degree must be 0 or 2.
        if deg_on[v] > 2:
            return False
        if deg_on[v] == 1 and deg_unk[v] == 0:
            return False
        if deg_on[v] == 0 and deg_unk[v] == 1:
            return False
        if deg_on[v] + deg_unk[v] < 2 and deg_on[v] != 0:
            return False
        if deg_on[v] == 2:
            for e in incident[v]:
                if state[e] == -1 and not set_edge(e, 0):
                    return False
        elif deg_on[v] == 1 and deg_unk[v] == 1:
            for e in incident[v]:
                if state[e] == -1 and not set_edge(e, 1):
                    return False
        elif deg_on[v] == 0 and deg_unk[v] == 2:
            for e in incident[v]:
                if state[e] == -1 and not set_edge(e, 1):
                    return False
        elif deg_on[v] == 0 and deg_unk[v] < 2:
            return False
        return True

    def clue_local(v):
        typ = clue.get(v)
        if not typ:
            return True

        dirs_used = [d for d in range(4) if (used_dirs[v] >> d) & 1]
        dirs_off = [d for d in range(4) if (off_dirs[v] >> d) & 1]
        unknown = [d for d in range(4) if not ((used_dirs[v] | off_dirs[v]) >> d) & 1]

        r, c = rc(v)

        if typ == "W":
            # White: if degree 2, it must be straight; if one used edge exists, opposite edge must be used.
            if deg_on[v] == 2:
                if len(dirs_used) != 2:
                    return False
                if dirs_used[1] != OPP[dirs_used[0]]:
                    return False
                # At least one adjacent vertex (previous or next along straight line) must turn.
                d1 = dirs_used[0]
                d2 = dirs_used[1]
                ok1 = white_neighbor_can_or_must_turn(v, d1)
                ok2 = white_neighbor_can_or_must_turn(v, d2)
                if ok1 is False and ok2 is False:
                    return False
            elif deg_on[v] == 1:
                d = dirs_used[0]
                opp = OPP[d]
                eopp = dir_edge[v][opp]
                if eopp == -1:
                    return False
                if not set_edge(eopp, 1):
                    return False
                # Orthogonal edges must be off once degree fixed to 2.
                for od in range(4):
                    if od != d and od != opp:
                        e = dir_edge[v][od]
                        if e != -1 and not set_edge(e, 0):
                            return False
            else:
                # On borders/corners impossible orientations may constrain.
                # White needs a straight pair available.
                possible_straight = False
                for d in (0, 1):
                    d2 = OPP[d]
                    e1 = dir_edge[v][d]
                    e2 = dir_edge[v][d2]
                    if e1 != -1 and e2 != -1 and state[e1] != 0 and state[e2] != 0:
                        possible_straight = True
                if not possible_straight:
                    return False

        elif typ == "B":
            # Black: if degree 2, must be a turn.
            if deg_on[v] == 2:
                if len(dirs_used) != 2:
                    return False
                if dirs_used[1] == OPP[dirs_used[0]]:
                    return False
                # Both adjacent continuation vertices must go straight.
                for d in dirs_used:
                    if not black_neighbor_must_straight(v, d):
                        return False
            elif deg_on[v] == 1:
                d = dirs_used[0]
                # second edge must be orthogonal, not opposite
                opp = OPP[d]
                candidates = []
                for od in range(4):
                    if od != d and od != opp:
                        e = dir_edge[v][od]
                        if e != -1 and state[e] != 0:
                            candidates.append(e)
                if not candidates:
                    return False
                eopp = dir_edge[v][opp]
                if eopp != -1 and not set_edge(eopp, 0):
                    return False
                if len(candidates) == 1 and not set_edge(candidates[0], 1):
                    return False
            else:
                # Need a turn pair available
                possible_turn = False
                for d in range(4):
                    for od in range(d + 1, 4):
                        if od == OPP[d]:
                            continue
                        e1 = dir_edge[v][d]
                        e2 = dir_edge[v][od]
                        if e1 != -1 and e2 != -1 and state[e1] != 0 and state[e2] != 0:
                            possible_turn = True
                if not possible_turn:
                    return False

        return True

    def white_neighbor_can_or_must_turn(v, d):
        e = dir_edge[v][d]
        if e == -1 or state[e] != 1:
            return None
        u = edge_v[e] if edge_u[e] == v else edge_u[e]
        # At neighbor, since edge from v to u is used, if neighbor degree becomes 2, can it turn?
        in_dir = OPP[d]
        typ = clue.get(u)
        if typ == "W":
            # White cannot turn.
            if deg_on[u] == 2:
                return False
            # If one used edge and it is this incoming, white forces straight later, so cannot turn.
            if deg_on[u] == 1 and ((used_dirs[u] >> in_dir) & 1):
                return False
            # Could still be unused from another path impossible because this edge is used.
            return False
        if typ == "B":
            # Black turns always.
            return True
        # Unclued: can turn if an orthogonal edge is available.
        for od in range(4):
            if od == in_dir or od == OPP[in_dir]:
                continue
            e2 = dir_edge[u][od]
            if e2 != -1 and state[e2] != 0:
                return True
        # If degree already 2 and used straight, impossible.
        if deg_on[u] == 2:
            dirs = [x for x in range(4) if (used_dirs[u] >> x) & 1]
            if len(dirs) == 2 and dirs[1] == OPP[dirs[0]]:
                return False
        return None

    def black_neighbor_must_straight(v, d):
        e = dir_edge[v][d]
        if e == -1 or state[e] != 1:
            return False
        u = edge_v[e] if edge_u[e] == v else edge_u[e]
        in_dir = OPP[d]
        typ = clue.get(u)

        if typ == "B":
            return False
        if typ == "W":
            # White with incoming edge must continue straight
            e2 = dir_edge[u][OPP[in_dir]]
            if e2 == -1:
                return False
            if not set_edge(e2, 1):
                return False
            for od in range(4):
                if od != in_dir and od != OPP[in_dir]:
                    ex = dir_edge[u][od]
                    if ex != -1 and not set_edge(ex, 0):
                        return False
            return True

        # Unclued neighbor must be straight relative to this black clue segment:
        e2 = dir_edge[u][OPP[in_dir]]
        if e2 == -1:
            return False
        if not set_edge(e2, 1):
            return False
        for od in range(4):
            if od != in_dir and od != OPP[in_dir]:
                ex = dir_edge[u][od]
                if ex != -1 and not set_edge(ex, 0):
                    return False
        return True

    def apply_static_border_rules():
        # Human-style immediate clue deductions near borders/corners.
        for v, typ in clue.items():
            r, c = rc(v)
            if typ == "W":
                # White on border cannot be straight perpendicular to border; must be parallel to border.
                if r == 0 or r == n - 1:
                    # horizontal
                    for d in (0, 2):
                        e = dir_edge[v][d]
                        if e != -1 and not set_edge(e, 0):
                            return False
                if c == 0 or c == n - 1:
                    # vertical
                    for d in (1, 3):
                        e = dir_edge[v][d]
                        if e != -1 and not set_edge(e, 0):
                            return False
            elif typ == "B":
                # Black on border cannot turn outward; thus the two usable directions are the border-inward turn pair.
                possible = []
                for d in range(4):
                    e = dir_edge[v][d]
                    if e != -1:
                        possible.append(d)
                # If exactly 2 incident already, both must be used and form a turn.
                if len(possible) == 2:
                    for d in possible:
                        e = dir_edge[v][d]
                        if not set_edge(e, 1):
                            return False
        return True

    def propagate():
        while queue:
            v = queue.popleft()
            if not force_vertex_degree(v):
                return False
            if not clue_local(v):
                return False
        # Global connectivity sanity
        return global_checks()

    def global_checks():
        # Every clue must remain potentially degree 2.
        for v in clue:
            if deg_on[v] > 2 or deg_on[v] + deg_unk[v] < 2:
                return False

        # If any closed used component exists, it must be the final single cycle.
        used_vertices = [v for v in range(n * n) if deg_on[v] > 0]
        if used_vertices:
            comps = {}
            for v in used_vertices:
                comps.setdefault(find(v), []).append(v)
            closed_comps = []
            for root, vs in comps.items():
                if all(deg_on[v] == 2 for v in vs):
                    closed_comps.append(vs)
            if closed_comps:
                if len(comps) > 1:
                    return False
                # If one closed component exists, then no unknown edge can be used and all clue vertices must be on it.
                vs = closed_comps[0]
                if any(deg_on[v] == 0 for v in clue):
                    return False
                for e in range(m):
                    if state[e] == -1:
                        a, b = edge_u[e], edge_v[e]
                        if deg_on[a] < 2 and deg_on[b] < 2:
                            return False
        return True

    def initialize():
        for v in range(n * n):
            queue.append(v)
        if not apply_static_border_rules():
            return False
        return propagate()

    def candidate_patterns(v):
        # Return feasible degree-2 patterns for this vertex given current state.
        patterns = []
        inc = incident[v]
        avail = [e for e in inc if state[e] != 0]
        used = [e for e in inc if state[e] == 1]
        if len(used) > 2:
            return patterns
        if len(used) == 2:
            pairs = [tuple(sorted(used))]
        else:
            pairs = set()
            if len(used) == 1:
                e0 = used[0]
                for e in avail:
                    if e != e0:
                        pairs.add(tuple(sorted((e0, e))))
            elif len(used) == 0:
                for i in range(len(avail)):
                    for j in range(i + 1, len(avail)):
                        pairs.add(tuple(sorted((avail[i], avail[j]))))
            pairs = list(pairs)

        typ = clue.get(v)
        for p in pairs:
            ds = sorted(edge_dir_from(v, e) for e in p)
            if typ == "W":
                if ds[1] != OPP[ds[0]]:
                    continue
            elif typ == "B":
                if ds[1] == OPP[ds[0]]:
                    continue
            patterns.append(p)
        return patterns

    def choose_branch_vertex():
        # Prefer constrained clue vertices, then general frontier vertices.
        best = None
        best_score = None
        for v in range(n * n):
            if deg_on[v] == 2 or deg_on[v] + deg_unk[v] < 2:
                continue
            pats = candidate_patterns(v)
            if not pats:
                continue
            score = (len(pats), -1 if v in clue else 0, len(incident[v]))
            if best_score is None or score < best_score:
                best_score = score
                best = (v, pats)
        return best

    def apply_pattern(v, pair):
        chosen = set(pair)
        for e in incident[v]:
            target = 1 if e in chosen else 0
            if state[e] == -1:
                if not set_edge(e, target):
                    return False
            elif state[e] != target and e in chosen:
                return False
        return True

    def solved():
        # All vertices degree 0 or 2; clues degree 2; exactly one cycle.
        for v in range(n * n):
            if deg_on[v] not in (0, 2):
                return False
        for v in clue:
            if deg_on[v] != 2:
                return False

        used_edges = [e for e in range(m) if state[e] == 1]
        if not used_edges:
            return False

        used_vertices = [v for v in range(n * n) if deg_on[v] == 2]
        roots = {find(v) for v in used_vertices}
        if len(roots) != 1:
            return False

        # Ensure every unknown is actually off by necessity; accept complete cycle if no contradictions.
        return True

    def build_path():
        # Traverse the unique cycle and output coordinates, closed.
        used_inc = [[] for _ in range(n * n)]
        for e in range(m):
            if state[e] == 1:
                a, b = edge_u[e], edge_v[e]
                used_inc[a].append(b)
                used_inc[b].append(a)

        start = None
        for v in clue:
            if used_inc[v]:
                start = v
                break
        if start is None:
            for v in range(n * n):
                if used_inc[v]:
                    start = v
                    break
        if start is None:
            return "No Solution"

        path = [start]
        prev = -1
        cur = start
        while True:
            nxts = used_inc[cur]
            if len(nxts) != 2:
                return "No Solution"
            nxt = nxts[0] if nxts[0] != prev else nxts[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(used_inc) + len(edge_u) + 5:
                return "No Solution"

        return str([rc(v) for v in path])

    def dfs():
        if solved():
            return build_path()

        choice = choose_branch_vertex()
        if choice is None:
            return "No Solution"
        v, pats = choice

        # Heuristic ordering: for clue vertices, patterns that immediately fix more forced neighbors first.
        def pat_score(pair):
            s = 0
            for e in pair:
                a, b = edge_u[e], edge_v[e]
                u = b if a == v else a
                if u in clue:
                    s -= 1
            return s

        pats = sorted(pats, key=pat_score)

        for pair in pats:
            snap = snapshot()
            if apply_pattern(v, pair) and propagate():
                ans = dfs()
                if ans != "No Solution":
                    return ans
            rollback(snap)
        return "No Solution"

    if not initialize():
        return "No Solution"
    return dfs()


