OBSERVATION = {'data': [[None, 'B', None, None, None, None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None], [None, None, 'B', 'B', None, None], [None, None, None, None, 'B', None], [None, 'B', None, None, None, None]]}

from collections import deque

B = 1
W = 0

def solve(observation):
    data = observation['data']
    n = len(data)
    grid = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                grid[r][c] = B
            elif v == 'W':
                grid[r][c] = W

    if not initial_consistent(grid):
        return "No Solution"

    state = Solver(grid)
    ans = state.run()
    if ans is None:
        return "No Solution"
    return repr([[('B' if ans[r][c] == B else 'W') for c in range(n)] for r in range(n)])


def initial_consistent(grid):
    n = len(grid)
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                continue
            for dr, dc in ((1, 0), (0, 1), (1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n and grid[rr][cc] is not None:
                    pass
    return True


class Solver:
    def __init__(self, grid):
        self.n = len(grid)
        self.grid = [row[:] for row in grid]
        self.nei = {}
        for r in range(self.n):
            for c in range(self.n):
                arr = []
                if r > 0:
                    arr.append((r - 1, c))
                if r + 1 < self.n:
                    arr.append((r + 1, c))
                if c > 0:
                    arr.append((r, c - 1))
                if c + 1 < self.n:
                    arr.append((r, c + 1))
                self.nei[(r, c)] = arr

    def run(self):
        grid = [row[:] for row in self.grid]
        res = self._search(grid)
        return res

    def _search(self, grid):
        ok, changed = self._propagate(grid)
        if not ok:
            return None

        if self._is_complete(grid):
            if self._final_check(grid):
                return [row[:] for row in grid]
            return None

        r, c, order = self._choose_cell(grid)
        for v in order:
            ng = [row[:] for row in grid]
            ng[r][c] = v
            res = self._search(ng)
            if res is not None:
                return res
        return None

    def _is_complete(self, grid):
        for row in grid:
            for v in row:
                if v is None:
                    return False
        return True

    def _choose_cell(self, grid):
        n = self.n
        best = None
        best_score = None
        best_order = (B, W)

        for r in range(n):
            for c in range(n):
                if grid[r][c] is not None:
                    continue
                allowed = self._allowed_values(grid, r, c)
                if not allowed:
                    return r, c, ()
                if len(allowed) == 1:
                    return r, c, tuple(allowed)
                score = self._cell_score(grid, r, c)
                if best is None or score > best_score:
                    best = (r, c)
                    best_score = score
                    # heuristic: prefer color matching more assigned neighbors to help connectivity
                    bcnt = 0
                    wcnt = 0
                    for rr, cc in self.nei[(r, c)]:
                        if grid[rr][cc] == B:
                            bcnt += 1
                        elif grid[rr][cc] == W:
                            wcnt += 1
                    if bcnt >= wcnt:
                        best_order = tuple(sorted(allowed, reverse=True))
                    else:
                        best_order = tuple(sorted(allowed))
        return best[0], best[1], best_order

    def _cell_score(self, grid, r, c):
        score = 0
        for rr, cc in self.nei[(r, c)]:
            if grid[rr][cc] is not None:
                score += 3
        for br in (r - 1, r):
            for bc in (c - 1, c):
                if 0 <= br < self.n - 1 and 0 <= bc < self.n - 1:
                    known = 0
                    for dr in (0, 1):
                        for dc in (0, 1):
                            if grid[br + dr][bc + dc] is not None:
                                known += 1
                    score += known
        return score

    def _propagate(self, grid):
        n = self.n
        changed = True
        while changed:
            changed = False

            # local 2x2 deductions
            progress = True
            while progress:
                progress = False
                for r in range(n - 1):
                    for c in range(n - 1):
                        cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                        vals = [grid[x][y] for x, y in cells]
                        if vals.count(None) == 0:
                            if vals.count(B) == 4 or vals.count(W) == 4:
                                return False, changed
                        elif vals.count(None) == 1:
                            idx = vals.index(None)
                            known = [v for v in vals if v is not None]
                            if known.count(B) == 3:
                                x, y = cells[idx]
                                if not self._assign(grid, x, y, W):
                                    return False, changed
                                progress = changed = True
                            elif known.count(W) == 3:
                                x, y = cells[idx]
                                if not self._assign(grid, x, y, B):
                                    return False, changed
                                progress = changed = True

            # connectivity impossibility checks on partial grid
            if not self._partial_connectivity_possible(grid, B):
                return False, changed
            if not self._partial_connectivity_possible(grid, W):
                return False, changed

            # forced articulation-style deductions:
            # if an assigned cell of color X is the only possible bridge between two X-regions,
            # neighboring undecided cells that must keep possibility open are forced.
            forced = self._connectivity_forcing(grid)
            if forced is None:
                return False, changed
            if forced:
                changed = True
                continue

            # domain wipeout check
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is None and not self._allowed_values(grid, r, c):
                        return False, changed

        return True, changed

    def _assign(self, grid, r, c, v):
        cur = grid[r][c]
        if cur is not None:
            return cur == v
        grid[r][c] = v
        return True

    def _allowed_values(self, grid, r, c):
        if grid[r][c] is not None:
            return {grid[r][c]}
        allowed = {B, W}
        for v in (B, W):
            if not self._locally_valid_if(grid, r, c, v):
                allowed.discard(v)
        return allowed

    def _locally_valid_if(self, grid, r, c, v):
        n = self.n
        for br in (r - 1, r):
            for bc in (c - 1, c):
                if 0 <= br < n - 1 and 0 <= bc < n - 1:
                    vals = []
                    for dr in (0, 1):
                        for dc in (0, 1):
                            rr, cc = br + dr, bc + dc
                            if rr == r and cc == c:
                                vals.append(v)
                            else:
                                vals.append(grid[rr][cc])
                    if vals.count(None) == 0:
                        if vals.count(B) == 4 or vals.count(W) == 4:
                            return False
        return True

    def _partial_connectivity_possible(self, grid, color):
        n = self.n
        fixed = []
        allowed = []
        for r in range(n):
            for c in range(n):
                if grid[r][c] == color:
                    fixed.append((r, c))
                    allowed.append((r, c))
                elif grid[r][c] is None:
                    allowed.append((r, c))

        if not fixed:
            return True

        allowed_set = set(allowed)
        start = fixed[0]
        q = deque([start])
        seen = {start}
        while q:
            x, y = q.popleft()
            for nx, ny in self.nei[(x, y)]:
                if (nx, ny) in allowed_set and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    q.append((nx, ny))
        for cell in fixed:
            if cell not in seen:
                return False
        return True

    def _connectivity_forcing(self, grid):
        n = self.n
        any_change = False
        for color in (B, W):
            fixed = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
            if len(fixed) <= 1:
                continue

            comps = self._components_of_fixed(grid, color)
            if len(comps) <= 1:
                continue

            # For each undecided cell, test whether forbidding this color disconnects the color's fixed cells.
            for r in range(n):
                for c in range(n):
                    if grid[r][c] is not None:
                        continue
                    if not self._locally_valid_if(grid, r, c, color):
                        continue
                    grid[r][c] = 1 - color
                    possible = self._partial_connectivity_possible(grid, color)
                    grid[r][c] = None
                    if not possible:
                        if not self._assign(grid, r, c, color):
                            return None
                        any_change = True
        return any_change

    def _components_of_fixed(self, grid, color):
        n = self.n
        cells = {(r, c) for r in range(n) for c in range(n) if grid[r][c] == color}
        comps = []
        seen = set()
        for cell in cells:
            if cell in seen:
                continue
            q = deque([cell])
            seen.add(cell)
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in self.nei[(x, y)]:
                    if (nx, ny) in cells and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append(comp)
        return comps

    def _final_check(self, grid):
        n = self.n

        # no 2x2 monochromatic
        for r in range(n - 1):
            for c in range(n - 1):
                s = {grid[r][c], grid[r + 1][c], grid[r][c + 1], grid[r + 1][c + 1]}
                if len(s) == 1:
                    return False

        # each color connected
        for color in (B, W):
            cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
            if not cells:
                return False
            q = deque([cells[0]])
            seen = {cells[0]}
            target = set(cells)
            while q:
                x, y = q.popleft()
                for nx, ny in self.nei[(x, y)]:
                    if grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            if seen != target:
                return False

        return True


