from collections import deque

B = 'B'
W = 'W'
U = None


def solve(observation):
    data = observation['data']
    n = len(data)
    grid = [row[:] for row in data]

    neighbors = {}
    for r in range(n):
        for c in range(n):
            adj = []
            if r > 0:
                adj.append((r - 1, c))
            if r + 1 < n:
                adj.append((r + 1, c))
            if c > 0:
                adj.append((r, c - 1))
            if c + 1 < n:
                adj.append((r, c + 1))
            neighbors[(r, c)] = adj

    all_cells = [(r, c) for r in range(n) for c in range(n)]

    def copy_grid(g):
        return [row[:] for row in g]

    def opposite(v):
        return B if v == W else W

    def set_cell(g, r, c, v, queue):
        cur = g[r][c]
        if cur is None:
            g[r][c] = v
            queue.append((r, c))
            return True
        return cur == v

    def apply_2x2_forced(g, queue):
        changed = False
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                vals = [g[x][y] for x, y in cells]
                if None not in vals:
                    if vals.count(vals[0]) == 4:
                        return None
                    continue
                bcnt = vals.count(B)
                wcnt = vals.count(W)
                uidx = [i for i, v in enumerate(vals) if v is None]
                if bcnt == 3 and len(uidx) == 1:
                    x, y = cells[uidx[0]]
                    if not set_cell(g, x, y, W, queue):
                        return None
                    changed = True
                if wcnt == 3 and len(uidx) == 1:
                    x, y = cells[uidx[0]]
                    if not set_cell(g, x, y, B, queue):
                        return None
                    changed = True
        return changed

    def articulation_required_color(g, color):
        fixed = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
        if len(fixed) <= 1:
            return True
        fixed_set = set(fixed)

        allowed = {(r, c) for r in range(n) for c in range(n) if g[r][c] != opposite(color)}
        if not fixed_set.issubset(allowed):
            return False

        start = fixed[0]
        seen = {start}
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if v in allowed and v not in seen:
                    seen.add(v)
                    dq.append(v)
        if not fixed_set.issubset(seen):
            return False

        if len(fixed) <= 2:
            return True

        root = fixed[0]
        disc = {}
        low = {}
        parent = {}
        timer = [0]
        articulation = set()

        def dfs(u):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            child_count = 0
            is_fixed_u = u in fixed_set
            subtree_has_fixed = is_fixed_u

            for v in neighbors[u]:
                if v not in allowed:
                    continue
                if v not in disc:
                    parent[v] = u
                    child_count += 1
                    child_has_fixed = dfs(v)
                    subtree_has_fixed = subtree_has_fixed or child_has_fixed
                    low[u] = min(low[u], low[v])

                    if u == root:
                        if child_has_fixed:
                            root.fixed_child_components += 1
                    else:
                        if child_has_fixed and low[v] >= disc[u] and u in fixed_set:
                            articulation.add(u)
                elif parent.get(u) != v:
                    low[u] = min(low[u], disc[v])

            return subtree_has_fixed

        root.fixed_child_components = 0
        dfs(root)
        if root in fixed_set and root.fixed_child_components >= 2:
            articulation.add(root)

        return len(articulation) == 0

    def component_analysis(g, color):
        opp = opposite(color)
        allowed = {(r, c) for r in range(n) for c in range(n) if g[r][c] != opp}
        fixed = {(r, c) for r in range(n) for c in range(n) if g[r][c] == color}

        seen = set()
        comps = []
        for cell in allowed:
            if cell in seen:
                continue
            dq = deque([cell])
            seen.add(cell)
            comp = []
            fixed_count = 0
            unknowns = []
            while dq:
                u = dq.popleft()
                comp.append(u)
                if u in fixed:
                    fixed_count += 1
                elif g[u[0]][u[1]] is None:
                    unknowns.append(u)
                for v in neighbors[u]:
                    if v in allowed and v not in seen:
                        seen.add(v)
                        dq.append(v)
            comps.append((comp, fixed_count, unknowns))
        return comps

    def propagate_connectivity_obligations(g, queue):
        for color in (B, W):
            comps = component_analysis(g, color)
            fixed_comps = [item for item in comps if item[1] > 0]
            if len(fixed_comps) > 1:
                return None
            if len(fixed_comps) == 1:
                for comp, fixed_count, unknowns in comps:
                    if fixed_count == 0:
                        for r, c in unknowns:
                            if not set_cell(g, r, c, opposite(color), queue):
                                return None
        return True

    def no_isolated_fixed_region_possible(g, color):
        fixed = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
        if not fixed:
            return True
        allowed = {(r, c) for r in range(n) for c in range(n) if g[r][c] != opposite(color)}
        start = fixed[0]
        seen = {start}
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if v in allowed and v not in seen:
                    seen.add(v)
                    dq.append(v)
        return all(cell in seen for cell in fixed)

    def local_patterns(g, queue):
        changed = False
        for r in range(n):
            for c in range(n):
                v = g[r][c]
                if v is None:
                    continue
                opp = opposite(v)
                if c + 2 < n and g[r][c + 2] == v and g[r][c + 1] is None:
                    if not set_cell(g, r, c + 1, opp, queue):
                        return None
                    changed = True
                if r + 2 < n and g[r + 2][c] == v and g[r + 1][c] is None:
                    if not set_cell(g, r + 1, c, opp, queue):
                        return None
                    changed = True
                if c + 1 < n and g[r][c + 1] == v:
                    if c - 1 >= 0 and g[r][c - 1] is None:
                        if not set_cell(g, r, c - 1, opp, queue):
                            return None
                        changed = True
                    if c + 2 < n and g[r][c + 2] is None:
                        if not set_cell(g, r, c + 2, opp, queue):
                            return None
                        changed = True
                if r + 1 < n and g[r + 1][c] == v:
                    if r - 1 >= 0 and g[r - 1][c] is None:
                        if not set_cell(g, r - 1, c, opp, queue):
                            return None
                        changed = True
                    if r + 2 < n and g[r + 2][c] is None:
                        if not set_cell(g, r + 2, c, opp, queue):
                            return None
                        changed = True
        return changed

    def check_no_mono_2x2(g):
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [g[r][c], g[r + 1][c], g[r][c + 1], g[r + 1][c + 1]]
                if None not in vals and vals.count(vals[0]) == 4:
                    return False
        return True

    def connectivity_final(g):
        for color in (B, W):
            cells = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
            if not cells:
                return False
            seen = {cells[0]}
            dq = deque([cells[0]])
            target = set(cells)
            while dq:
                u = dq.popleft()
                for v in neighbors[u]:
                    if v in target and v not in seen:
                        seen.add(v)
                        dq.append(v)
            if len(seen) != len(cells):
                return False
        return True

    def partial_feasible(g):
        if not check_no_mono_2x2(g):
            return False
        for color in (B, W):
            if not no_isolated_fixed_region_possible(g, color):
                return False
            if not articulation_required_color(g, color):
                return False
        return True

    def propagate(g):
        queue = deque((r, c) for r in range(n) for c in range(n) if g[r][c] is not None)
        while True:
            progressed = False

            res = apply_2x2_forced(g, queue)
            if res is None:
                return None
            progressed |= res

            res = local_patterns(g, queue)
            if res is None:
                return None
            progressed |= res

            res = propagate_connectivity_obligations(g, queue)
            if res is None:
                return None
            progressed |= True

            if not partial_feasible(g):
                return None

            if not progressed:
                break
        return g

    def completion_status(g):
        for r in range(n):
            for c in range(n):
                if g[r][c] is None:
                    return False
        return True

    def choose_cell(g):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if g[r][c] is not None:
                    continue
                score = 0
                for nr, nc in neighbors[(r, c)]:
                    if g[nr][nc] is not None:
                        score += 2
                for rr in range(max(0, r - 1), min(n - 1, r) + 1):
                    for cc in range(max(0, c - 1), min(n - 1, c) + 1):
                        vals = [g[rr][cc], g[rr + 1][cc], g[rr][cc + 1], g[rr + 1][cc + 1]]
                        score += 4 - vals.count(None)
                if best is None or score > best_score:
                    best = (r, c)
                    best_score = score
        return best

    def candidate_order(g, r, c):
        cnt = {B: 0, W: 0}
        for nr, nc in neighbors[(r, c)]:
            if g[nr][nc] in cnt:
                cnt[g[nr][nc]] += 1
        if cnt[B] > cnt[W]:
            return [B, W]
        if cnt[W] > cnt[B]:
            return [W, B]
        btotal = sum(row.count(B) for row in g)
        wtotal = sum(row.count(W) for row in g)
        return [B, W] if btotal <= wtotal else [W, B]

    def search(g):
        g = propagate(copy_grid(g))
        if g is None:
            return None
        if completion_status(g):
            if connectivity_final(g) and check_no_mono_2x2(g):
                return g
            return None

        r, c = choose_cell(g)
        for v in candidate_order(g, r, c):
            ng = copy_grid(g)
            ng[r][c] = v
            res = search(ng)
            if res is not None:
                return res
        return None

    ans = search(grid)
    if ans is None:
        return "No Solution"
    return str(ans)


