# Generalized Minesweeper solver using human-style deduction first,
# then tightly-pruned component search over only unresolved frontier cells.

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def neighbors(r, c):
        out = []
        for dr in (-1, 0, 1):
            nr = r + dr
            if 0 <= nr < rows:
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nc = c + dc
                    if 0 <= nc < cols:
                        out.append((nr, nc))
        return out

    clue_cells = []
    hidden_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                hidden_cells.append((r, c))
            else:
                clue_cells.append((r, c))

    hidden_set = set(hidden_cells)
    neigh_cache = {(r, c): neighbors(r, c) for r in range(rows) for c in range(cols)}

    # State: -1 unknown, 0 safe, 1 mine on hidden cells only
    state = {cell: -1 for cell in hidden_cells}

    clue_to_hidden = {}
    for rc in clue_cells:
        hs = [n for n in neigh_cache[rc] if n in hidden_set]
        clue_to_hidden[rc] = hs

    changed = True

    def assign(cell, val):
        cur = state[cell]
        if cur != -1:
            return cur == val
        state[cell] = val
        return True

    def clue_bounds(rc):
        need = grid[rc[0]][rc[1]]
        mines = 0
        unknown = 0
        for h in clue_to_hidden[rc]:
            if state[h] == 1:
                mines += 1
            elif state[h] == -1:
                unknown += 1
        return mines, unknown, need

    def local_consistent(rc):
        mines, unknown, need = clue_bounds(rc)
        return mines <= need <= mines + unknown

    def global_consistent():
        for rc in clue_cells:
            if not local_consistent(rc):
                return False
        return True

    def propagate_basic():
        # Repeatedly apply:
        # 1) if need == flagged => all unknown neighbors safe
        # 2) if need == flagged + unknown => all unknown neighbors mines
        progress = True
        while progress:
            progress = False
            for rc in clue_cells:
                mines, unknown, need = clue_bounds(rc)
                if mines > need or mines + unknown < need:
                    return False
                if unknown == 0:
                    continue
                if mines == need:
                    for h in clue_to_hidden[rc]:
                        if state[h] == -1:
                            if not assign(h, 0):
                                return False
                            progress = True
                elif mines + unknown == need:
                    for h in clue_to_hidden[rc]:
                        if state[h] == -1:
                            if not assign(h, 1):
                                return False
                            progress = True
        return True

    def propagate_subset():
        # Human-style subset rule:
        # If unknown set A subset B, then residual(B\A) must account for need diff.
        progress = True
        while progress:
            progress = False
            clue_list = clue_cells
            for i in range(len(clue_list)):
                a = clue_list[i]
                am, au, an = clue_bounds(a)
                Au = {h for h in clue_to_hidden[a] if state[h] == -1}
                if not Au:
                    continue
                ra = an - am
                for j in range(len(clue_list)):
                    if i == j:
                        continue
                    b = clue_list[j]
                    bm, bu, bn = clue_bounds(b)
                    Bu = {h for h in clue_to_hidden[b] if state[h] == -1}
                    if not Bu:
                        continue
                    rb = bn - bm
                    if Au.issubset(Bu):
                        diff = Bu - Au
                        dneed = rb - ra
                        if dneed < 0 or dneed > len(diff):
                            return False
                        if diff:
                            if dneed == 0:
                                for h in diff:
                                    if state[h] == -1:
                                        if not assign(h, 0):
                                            return False
                                        progress = True
                            elif dneed == len(diff):
                                for h in diff:
                                    if state[h] == -1:
                                        if not assign(h, 1):
                                            return False
                                        progress = True
            if progress:
                if not propagate_basic():
                    return False
        return True

    if not propagate_basic():
        return "No Solution"
    if not propagate_subset():
        return "No Solution"

    # Frontier cells: unknown hidden cells adjacent to at least one clue.
    frontier = [h for h in hidden_cells if state[h] == -1 and any(n in clue_to_hidden for n in neigh_cache[h] if grid[n[0]][n[1]] is not None)]
    frontier_set = set(frontier)

    # Unknown hidden cells not touching any clue can be arbitrary in unconstrained puzzles.
    # To satisfy a concrete single answer, choose them as safe unless forced otherwise.
    isolated = [h for h in hidden_cells if state[h] == -1 and h not in frontier_set]

    # Build clue-frontier adjacency
    clue_front = {}
    for rc in clue_cells:
        lst = [h for h in clue_to_hidden[rc] if h in frontier_set]
        if lst:
            clue_front[rc] = lst

    # Connected components on frontier using clue-sharing graph
    frontier_adj = {h: set() for h in frontier}
    for rc, lst in clue_front.items():
        for i in range(len(lst)):
            hi = lst[i]
            for j in range(i + 1, len(lst)):
                hj = lst[j]
                frontier_adj[hi].add(hj)
                frontier_adj[hj].add(hi)

    components = []
    seen = set()
    for h in frontier:
        if h in seen:
            continue
        stack = [h]
        seen.add(h)
        comp = []
        while stack:
            x = stack.pop()
            comp.append(x)
            for y in frontier_adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        components.append(comp)

    # For each component, enumerate all satisfying assignments with strong pruning.
    comp_solutions = []

    # Precompute clue data dynamic references
    hidden_to_clues = {h: [] for h in hidden_cells}
    for rc in clue_cells:
        for h in clue_to_hidden[rc]:
            hidden_to_clues[h].append(rc)

    for comp in components:
        comp_set = set(comp)
        rel_clues = []
        for rc in clue_cells:
            if any(h in comp_set for h in clue_to_hidden[rc]):
                rel_clues.append(rc)

        # residual needs after current global deductions, considering only comp vars as unknowns here
        clue_info = {}
        for rc in rel_clues:
            flagged = sum(1 for h in clue_to_hidden[rc] if state[h] == 1)
            outside_unknown = sum(1 for h in clue_to_hidden[rc] if state[h] == -1 and h not in comp_set)
            inside_vars = [h for h in clue_to_hidden[rc] if h in comp_set]
            need = grid[rc[0]][rc[1]] - flagged
            clue_info[rc] = {
                'need': need,
                'vars': inside_vars,
                'outside_unknown': outside_unknown,
            }

        # Order variables by constraint degree for faster search.
        comp_order = sorted(comp, key=lambda h: (-len([rc for rc in hidden_to_clues[h] if rc in clue_info]), h))
        idx_of = {h: i for i, h in enumerate(comp_order)}

        # For pruning, track assigned mines and assigned counts per clue.
        clue_var_count = {rc: len(clue_info[rc]['vars']) for rc in rel_clues}
        involved_clues = {h: [rc for rc in hidden_to_clues[h] if rc in clue_info] for h in comp_order}

        solutions = []

        assigned = {}
        assigned_mines = {rc: 0 for rc in rel_clues}
        assigned_vars = {rc: 0 for rc in rel_clues}

        def dfs(k):
            if k == len(comp_order):
                for rc in rel_clues:
                    need = clue_info[rc]['need']
                    if assigned_mines[rc] > need:
                        return
                    rem_inside = clue_var_count[rc] - assigned_vars[rc]
                    # outside_unknown remain globally free; but since they are not in frontier components, they are either already fixed or not adjacent.
                    # Here all clue-related unknowns are within some component/frontier, so outside_unknown should be 0 for rel_clues crossing this comp
                    # unless clue touches another component, which cannot happen by component construction.
                    if assigned_mines[rc] + rem_inside < need:
                        return
                    if assigned_mines[rc] != need:
                        return
                solutions.append({h: assigned[h] for h in comp_order})
                return

            h = comp_order[k]

            # Try safe then mine; a human solver often prefers non-mine assumption first.
            for val in (0, 1):
                assigned[h] = val
                bad = False
                touched = involved_clues[h]
                for rc in touched:
                    assigned_vars[rc] += 1
                    assigned_mines[rc] += val
                    need = clue_info[rc]['need']
                    rem_inside = clue_var_count[rc] - assigned_vars[rc]
                    if assigned_mines[rc] > need or assigned_mines[rc] + rem_inside < need:
                        bad = True
                if not bad:
                    dfs(k + 1)
                for rc in touched:
                    assigned_vars[rc] -= 1
                    assigned_mines[rc] -= val
                del assigned[h]

        dfs(0)
        if not solutions:
            return "No Solution"
        comp_solutions.append((comp_order, solutions))

    # Merge component solutions; since components are clue-independent, any combination works.
    # To get a deterministic single answer, choose lexicographically smallest mine pattern.
    final_state = dict(state)

    for comp_order, solutions in comp_solutions:
        best = None
        for sol in solutions:
            key = tuple(sol[h] for h in sorted(sol))
            if best is None or key < best[0]:
                best = (key, sol)
        chosen = best[1]
        for h, v in chosen.items():
            final_state[h] = v

    for h in isolated:
        final_state[h] = 0

    # Final verification
    for rc in clue_cells:
        total = 0
        for h in clue_to_hidden[rc]:
            total += 1 if final_state[h] == 1 else 0
        if total != grid[rc[0]][rc[1]]:
            return "No Solution"

    answer = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if grid[r][c] is None and final_state[(r, c)] == 1:
                row.append('F')
            else:
                row.append(None)
        answer.append(row)
    return str(answer)


