from itertools import combinations
import ast

# Human-style Star Battle solver:
# - represent each region by all legal 2-cell placements inside that region
# - placements already respect non-touching within region
# - propagate exact row/col capacities
# - propagate incompatibilities between placements of different regions
# - use row/col support checks and forced assignments
# - branch only on most constrained region/cell when deduction stalls

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"

    stars_per_unit = 2
    cells = [(r, c) for r in range(n) for c in range(n)]
    cell_id = {(r, c): r * n + c for r, c in cells}

    # Build regions
    region_cells = {}
    for r in range(n):
        for c in range(n):
            region_cells.setdefault(grid[r][c], []).append((r, c))
    region_ids = sorted(region_cells)
    m = len(region_ids)
    rid_to_idx = {rid: i for i, rid in enumerate(region_ids)}

    # Adjacency masks
    adj_mask = [0] * (n * n)
    for r in range(n):
        for c in range(n):
            mask = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        mask |= 1 << cell_id[(rr, cc)]
            adj_mask[cell_id[(r, c)]] = mask

    row_mask = [0] * n
    col_mask = [0] * n
    for r in range(n):
        mask = 0
        for c in range(n):
            mask |= 1 << cell_id[(r, c)]
        row_mask[r] = mask
    for c in range(n):
        mask = 0
        for r in range(n):
            mask |= 1 << cell_id[(r, c)]
        col_mask[c] = mask

    # All legal 2-star placements per region
    placements = []
    placement_cells = []
    placement_row_counts = []
    placement_col_counts = []
    placement_cover_by_region_cell = []
    placement_regions = []

    region_options = []
    for rid in region_ids:
        rcells = region_cells[rid]
        opts = []
        cover = {cell: [] for cell in rcells}
        for a, b in combinations(rcells, 2):
            ia = cell_id[a]
            ib = cell_id[b]
            if adj_mask[ia] & (1 << ib):
                continue
            mask = (1 << ia) | (1 << ib)
            rows = [0] * n
            cols = [0] * n
            rows[a[0]] += 1
            rows[b[0]] += 1
            cols[a[1]] += 1
            cols[b[1]] += 1
            pidx = len(placements)
            placements.append(mask)
            placement_cells.append((a, b))
            placement_row_counts.append(tuple(rows))
            placement_col_counts.append(tuple(cols))
            placement_regions.append(rid_to_idx[rid])
            cover[a].append(pidx)
            cover[b].append(pidx)
            opts.append(pidx)
        if not opts:
            return "No Solution"
        placement_cover_by_region_cell.append(cover)
        region_options.append(opts)

    total_placements = len(placements)

    # Incompatibility masks between placements
    incompatible = [0] * total_placements
    for i in range(total_placements):
        mi = placements[i]
        # same region incompatible unless identical single choice
        for j in range(i + 1, total_placements):
            bad = False
            if placement_regions[i] == placement_regions[j]:
                bad = True
            else:
                mj = placements[j]
                # two placements conflict if any star touches any star
                x = mi
                while x:
                    lsb = x & -x
                    bit_index = lsb.bit_length() - 1
                    if adj_mask[bit_index] & mj:
                        bad = True
                        break
                    x ^= lsb
            if bad:
                incompatible[i] |= 1 << j
                incompatible[j] |= 1 << i

    all_placement_mask = (1 << total_placements) - 1

    region_allowed_masks = []
    for opts in region_options:
        mask = 0
        for p in opts:
            mask |= 1 << p
        region_allowed_masks.append(mask)

    # cell -> placements containing it
    cell_to_placements = [0] * (n * n)
    for pidx, mask in enumerate(placements):
        x = mask
        while x:
            lsb = x & -x
            cid = lsb.bit_length() - 1
            cell_to_placements[cid] |= 1 << pidx
            x ^= lsb

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def count_bits(x):
        return x.bit_count()

    def format_answer(star_mask):
        ans = [[None for _ in range(n)] for _ in range(n)]
        for cid in iter_bits(star_mask):
            r, c = divmod(cid, n)
            ans[r][c] = 'S'
        return str(ans)

    def propagate(region_masks, row_need, col_need, star_mask, ban_mask):
        changed = True
        while changed:
            changed = False

            # Remove options using banned cells or exceeding row/col needs
            for ri in range(m):
                old = region_masks[ri]
                nm = 0
                for p in iter_bits(old):
                    pmask = placements[p]
                    if pmask & ban_mask:
                        continue
                    rows = placement_row_counts[p]
                    cols = placement_col_counts[p]
                    ok = True
                    for i in range(n):
                        if rows[i] > row_need[i] or cols[i] > col_need[i]:
                            ok = False
                            break
                    if ok:
                        nm |= 1 << p
                if nm == 0:
                    return None
                if nm != old:
                    region_masks[ri] = nm
                    changed = True

            # Capacity lower/upper bounds from region options
            min_row = [0] * n
            max_row = [0] * n
            min_col = [0] * n
            max_col = [0] * n
            for i in range(n):
                row_contribs = []
                col_contribs = []
                for ri in range(m):
                    vals_r = set()
                    vals_c = set()
                    for p in iter_bits(region_masks[ri]):
                        vals_r.add(placement_row_counts[p][i])
                        vals_c.add(placement_col_counts[p][i])
                    min_row[i] += min(vals_r)
                    max_row[i] += max(vals_r)
                    min_col[i] += min(vals_c)
                    max_col[i] += max(vals_c)
                if not (min_row[i] <= row_need[i] <= max_row[i]):
                    return None
                if not (min_col[i] <= col_need[i] <= max_col[i]):
                    return None

            # Single-option region => commit placement
            for ri in range(m):
                mask = region_masks[ri]
                if mask & (mask - 1) == 0:
                    p = mask.bit_length() - 1
                    pmask = placements[p]
                    new_stars = pmask & ~star_mask
                    if new_stars:
                        # place stars
                        for cid in iter_bits(new_stars):
                            r, c = divmod(cid, n)
                            row_need[r] -= 1
                            col_need[c] -= 1
                            if row_need[r] < 0 or col_need[c] < 0:
                                return None
                        star_mask |= new_stars
                        # ban touching cells
                        b = 0
                        for cid in iter_bits(new_stars):
                            b |= adj_mask[cid]
                        if b & star_mask != star_mask:
                            return None
                        ban_mask |= b
                        # keep actual stars unbanned logically irrelevant, but safe
                        changed = True

                        # remove incompatible placements globally
                        bad = incompatible[p]
                        for rj in range(m):
                            old = region_masks[rj]
                            nm = old & ~bad
                            if rj == ri:
                                nm = old
                            if nm == 0:
                                return None
                            if nm != old:
                                region_masks[rj] = nm
                                changed = True

            # If row/col need is 0, ban remaining cells in that row/col
            for i in range(n):
                if row_need[i] == 0:
                    nb = row_mask[i] & ~ban_mask
                    if nb:
                        ban_mask |= nb
                        changed = True
                if col_need[i] == 0:
                    nb = col_mask[i] & ~ban_mask
                    if nb:
                        ban_mask |= nb
                        changed = True

            # Cell support checks and forced stars
            for cid in range(n * n):
                bit = 1 << cid
                if star_mask & bit:
                    continue
                if ban_mask & bit:
                    # ensure no remaining placement requires impossible cell exclusively in a unit later by bounds
                    continue

                supporting_regions = []
                for ri in range(m):
                    if region_masks[ri] & cell_to_placements[cid]:
                        supporting_regions.append(ri)
                # no direct action here unless by row/col exactness below

            # Exact support in rows
            for r in range(n):
                if row_need[r] == 0:
                    continue
                support_cells = []
                mandatory_cells = []
                for c in range(n):
                    cid = r * n + c
                    bit = 1 << cid
                    if ban_mask & bit:
                        continue
                    supported = False
                    for ri in range(m):
                        if region_masks[ri] & cell_to_placements[cid]:
                            supported = True
                            break
                    if supported:
                        support_cells.append(cid)
                        # mandatory if every supporting placement of some region uses this cell and row still needs it
                    # no-op placeholder
                if len(support_cells) < row_need[r]:
                    return None
                if len(support_cells) == row_need[r]:
                    for cid in support_cells:
                        if not (star_mask & (1 << cid)):
                            # force star by restricting its region(s) to placements containing cid
                            hit = False
                            for ri in range(m):
                                nm = region_masks[ri] & cell_to_placements[cid]
                                if nm:
                                    # only force when this cell belongs to that region
                                    reg_has_cell = False
                                    for p in iter_bits(region_masks[ri]):
                                        if placements[p] & (1 << cid):
                                            reg_has_cell = True
                                            break
                                    if reg_has_cell:
                                        if region_masks[ri] != nm:
                                            region_masks[ri] = nm
                                            changed = True
                                        hit = True
                                        break
                            if not hit:
                                return None

            # Exact support in cols
            for c in range(n):
                if col_need[c] == 0:
                    continue
                support_cells = []
                for r in range(n):
                    cid = r * n + c
                    bit = 1 << cid
                    if ban_mask & bit:
                        continue
                    supported = False
                    for ri in range(m):
                        if region_masks[ri] & cell_to_placements[cid]:
                            supported = True
                            break
                    if supported:
                        support_cells.append(cid)
                if len(support_cells) < col_need[c]:
                    return None
                if len(support_cells) == col_need[c]:
                    for cid in support_cells:
                        if not (star_mask & (1 << cid)):
                            hit = False
                            for ri in range(m):
                                nm = region_masks[ri] & cell_to_placements[cid]
                                if nm:
                                    reg_has_cell = False
                                    for p in iter_bits(region_masks[ri]):
                                        if placements[p] & (1 << cid):
                                            reg_has_cell = True
                                            break
                                    if reg_has_cell:
                                        if region_masks[ri] != nm:
                                            region_masks[ri] = nm
                                            changed = True
                                        hit = True
                                        break
                            if not hit:
                                return None

            # Region-cell impossibility: if a region still needs 2 stars but some cell appears in all options and row/col impossible, prune happened above.
            # Hall-like pair rule on rows and cols: if exactly k regions can contribute to a subset with total max==need, omitted for simplicity.

        return region_masks, row_need, col_need, star_mask, ban_mask

    def solved(region_masks, row_need, col_need):
        return all(x == 0 for x in row_need) and all(x == 0 for x in col_need) and all(mask & (mask - 1) == 0 for mask in region_masks)

    def choose_branch(region_masks, row_need, col_need, star_mask, ban_mask):
        # Most constrained region first
        best_ri = None
        best_count = 10**9
        for ri in range(m):
            cnt = count_bits(region_masks[ri])
            if 1 < cnt < best_count:
                best_count = cnt
                best_ri = ri
        if best_ri is not None:
            # order placements by least conflict and better fit to unmet row/col needs
            opts = list(iter_bits(region_masks[best_ri]))
            def score(p):
                rows = placement_row_counts[p]
                cols = placement_col_counts[p]
                fit = 0
                for i in range(n):
                    if rows[i]:
                        fit += row_need[i]
                    if cols[i]:
                        fit += col_need[i]
                return (count_bits(incompatible[p]), -fit)
            opts.sort(key=score)
            return ("region", best_ri, opts)
        return None

    def dfs(region_masks, row_need, col_need, star_mask, ban_mask):
        state = propagate(region_masks[:], row_need[:], col_need[:], star_mask, ban_mask)
        if state is None:
            return None
        region_masks, row_need, col_need, star_mask, ban_mask = state

        if solved(region_masks, row_need, col_need):
            return star_mask

        branch = choose_branch(region_masks, row_need, col_need, star_mask, ban_mask)
        if branch is None:
            return None

        _, ri, opts = branch
        for p in opts:
            new_region_masks = region_masks[:]
            new_region_masks[ri] = 1 << p
            res = dfs(new_region_masks, row_need[:], col_need[:], star_mask, ban_mask)
            if res is not None:
                return res

        return None

    row_need = [stars_per_unit] * n
    col_need = [stars_per_unit] * n
    star_mask = 0
    ban_mask = 0

    result = dfs(region_allowed_masks[:], row_need, col_need, star_mask, ban_mask)
    if result is None:
        return "No Solution"
    return format_answer(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

