from collections import deque, defaultdict

# General Masyu solver on an N x N dot grid.
# A loop is formed by using edges between orthogonally adjacent dots.
# Each cell clue applies to the dot at the same (row, col).

DIRS = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0:
        return "No Solution"

    idx = lambda r, c: r * n + c
    rc = lambda v: divmod(v, n)

    nbr = [[-1] * 4 for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            v = idx(r, c)
            for d, (dr, dc) in enumerate(DIRS):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    nbr[v][d] = idx(rr, cc)

    # Edge state: 1 unknown, 2 on, 0 off
    edges = {}
    incident = [[] for _ in range(n * n)]
    edge_dirs = {}
    for r in range(n):
        for c in range(n):
            v = idx(r, c)
            if c + 1 < n:
                u = idx(r, c + 1)
                e = (v, u)
                edges[e] = 1
                incident[v].append(e)
                incident[u].append(e)
                edge_dirs[(v, e)] = 1
                edge_dirs[(u, e)] = 3
            if r + 1 < n:
                u = idx(r + 1, c)
                e = (v, u)
                edges[e] = 1
                incident[v].append(e)
                incident[u].append(e)
                edge_dirs[(v, e)] = 2
                edge_dirs[(u, e)] = 0

    clues = {}
    for r in range(n):
        for c in range(n):
            if data[r][c] in ('W', 'B'):
                clues[idx(r, c)] = data[r][c]

    # Track "must turn before/after" for white circles.
    # For each white vertex v and each straight orientation:
    # if horizontal, at least one of left/right neighboring vertices (if along used path) must be turn.
    # if vertical, at least one of up/down neighboring vertices must be turn.
    #
    # We'll enforce by local deductions and by final consistency checks during propagation.

    def edge_key(a, b):
        return (a, b) if a < b else (b, a)

    def get_edge(v, d):
        u = nbr[v][d]
        if u == -1:
            return None
        return edge_key(v, u)

    def vertex_on_dirs(state, v):
        ds = []
        for e in incident[v]:
            if state[e] == 2:
                ds.append(edge_dirs[(v, e)])
        return ds

    def vertex_unknown_dirs(state, v):
        ds = []
        for e in incident[v]:
            if state[e] == 1:
                ds.append(edge_dirs[(v, e)])
        return ds

    def set_edge(state, e, val, queue):
        cur = state[e]
        if cur == val:
            return True
        if cur != 1 and cur != val:
            return False
        state[e] = val
        a, b = e
        queue.append(a)
        queue.append(b)
        return True

    def degree_counts(state, v):
        on = off = unk = 0
        for e in incident[v]:
            s = state[e]
            if s == 2:
                on += 1
            elif s == 0:
                off += 1
            else:
                unk += 1
        return on, off, unk

    def force_vertex_degree_0_or_2(state, v, queue):
        on, off, unk = degree_counts(state, v)
        if on > 2:
            return False
        if on == 2:
            for e in incident[v]:
                if state[e] == 1:
                    if not set_edge(state, e, 0, queue):
                        return False
        elif on == 1 and unk == 0:
            return False
        elif on == 1 and unk == 1:
            for e in incident[v]:
                if state[e] == 1:
                    if not set_edge(state, e, 2, queue):
                        return False
        elif on == 0 and unk == 1:
            # Can't finish degree 0 or 2 with only one unknown left.
            if not set_edge(state, next(e for e in incident[v] if state[e] == 1), 0, queue):
                return False
        return True

    def allowed_patterns_for_vertex(state, v):
        # Return possible sets of directions among incident dirs that can be ON at v,
        # respecting degree 0/2 and clue local shape.
        present_dirs = [edge_dirs[(v, e)] for e in incident[v]]
        on_dirs = set(vertex_on_dirs(state, v))
        unk_dirs = set(vertex_unknown_dirs(state, v))

        all_dirs = set(present_dirs)
        poss = []

        # degree 0
        if not on_dirs:
            poss.append(frozenset())

        # degree 2
        dirs_list = sorted(all_dirs)
        for i in range(len(dirs_list)):
            for j in range(i + 1, len(dirs_list)):
                s = frozenset((dirs_list[i], dirs_list[j]))
                if not on_dirs.issubset(s):
                    continue
                if any(d not in s for d in on_dirs):
                    continue
                if not s.issubset(on_dirs | unk_dirs):
                    continue
                if v in clues:
                    clue = clues[v]
                    a, b = sorted(s)
                    is_straight = (a == 0 and b == 2) or (a == 1 and b == 3)
                    if clue == 'W':
                        if not is_straight:
                            continue
                    elif clue == 'B':
                        if is_straight:
                            continue
                poss.append(s)
        return poss

    def turn_possible(state, v):
        if v not in clues and True:
            pass
        poss = allowed_patterns_for_vertex(state, v)
        for s in poss:
            if len(s) == 2:
                a, b = sorted(s)
                is_straight = (a == 0 and b == 2) or (a == 1 and b == 3)
                if not is_straight:
                    return True
        return False

    def straight_possible(state, v):
        poss = allowed_patterns_for_vertex(state, v)
        for s in poss:
            if len(s) == 2:
                a, b = sorted(s)
                is_straight = (a == 0 and b == 2) or (a == 1 and b == 3)
                if is_straight:
                    return True
        return False

    def apply_vertex_pattern_forcing(state, v, queue):
        poss = allowed_patterns_for_vertex(state, v)
        if not poss:
            return False

        dirs_present = {edge_dirs[(v, e)] for e in incident[v]}
        must_on = set(dirs_present)
        must_off = set(dirs_present)
        for s in poss:
            must_on &= set(s)
            must_off &= (dirs_present - set(s))

        for d in dirs_present:
            e = get_edge(v, d)
            if d in must_on:
                if not set_edge(state, e, 2, queue):
                    return False
            if d in must_off:
                if not set_edge(state, e, 0, queue):
                    return False
        return True

    def apply_black_rule(state, v, queue):
        # Black: turn here, straight before and after.
        poss = allowed_patterns_for_vertex(state, v)
        turn_poss = [s for s in poss if len(s) == 2 and not (((min(s), max(s)) == (0, 2)) or ((min(s), max(s)) == (1, 3)))]
        if not turn_poss:
            return False

        # If one arm is forced on, continue straight in the adjacent vertex.
        on_dirs = vertex_on_dirs(state, v)
        if len(on_dirs) == 2:
            # exact turn known
            ds = sorted(on_dirs)
            for d in ds:
                u = nbr[v][d]
                if u == -1:
                    return False
                # At u, edge entering from opp(d) is on; black rule says u must also continue straight through.
                od = OPP[d]
                e2 = get_edge(u, od)
                if e2 is None or state[e2] != 2:
                    return False
                # Need opposite edge at u to be on.
                if od in (0, 2):
                    od2 = 2 if od == 0 else 0
                else:
                    od2 = 3 if od == 1 else 1
                e3 = get_edge(u, od2)
                if e3 is None:
                    return False
                if not set_edge(state, e3, 2, queue):
                    return False
                # Perpendiculars off.
                for pd in ({0, 2} if od in (1, 3) else {1, 3}):
                    ee = get_edge(u, pd)
                    if ee is not None:
                        if not set_edge(state, ee, 0, queue):
                            return False
        return True

    def apply_white_rule(state, v, queue):
        poss = allowed_patterns_for_vertex(state, v)
        straight_poss = [s for s in poss if len(s) == 2 and (((min(s), max(s)) == (0, 2)) or ((min(s), max(s)) == (1, 3)))]
        if not straight_poss:
            return False

        on_dirs = vertex_on_dirs(state, v)
        if len(on_dirs) == 2:
            ds = sorted(on_dirs)
            # Must be straight already by local rule.
            # Need at least one adjacent continuation endpoint to turn.
            if ds == [0, 2]:
                neighbors = []
                for d in ds:
                    u = nbr[v][d]
                    if u == -1:
                        return False
                    neighbors.append((u, OPP[d]))
                # If one neighbor cannot turn, the other must.
                can = []
                for u, incoming in neighbors:
                    can.append(neighbor_can_turn_given_incoming(state, u, incoming))
                if not any(can):
                    return False
                if can[0] and not can[1]:
                    if not force_turn_with_incoming(state, neighbors[0][0], neighbors[0][1], queue):
                        return False
                if can[1] and not can[0]:
                    if not force_turn_with_incoming(state, neighbors[1][0], neighbors[1][1], queue):
                        return False
            elif ds == [1, 3]:
                neighbors = []
                for d in ds:
                    u = nbr[v][d]
                    if u == -1:
                        return False
                    neighbors.append((u, OPP[d]))
                can = []
                for u, incoming in neighbors:
                    can.append(neighbor_can_turn_given_incoming(state, u, incoming))
                if not any(can):
                    return False
                if can[0] and not can[1]:
                    if not force_turn_with_incoming(state, neighbors[0][0], neighbors[0][1], queue):
                        return False
                if can[1] and not can[0]:
                    if not force_turn_with_incoming(state, neighbors[1][0], neighbors[1][1], queue):
                        return False
        return True

    def neighbor_can_turn_given_incoming(state, u, incoming_dir):
        # incoming_dir at u is already on; can u be a turn vertex in some valid local pattern?
        e_in = get_edge(u, incoming_dir)
        if e_in is None:
            return False
        if state[e_in] == 0:
            return False
        poss = allowed_patterns_for_vertex(state, u)
        for s in poss:
            if incoming_dir in s and len(s) == 2:
                a, b = sorted(s)
                is_straight = (a, b) in ((0, 2), (1, 3))
                if not is_straight:
                    return True
        return False

    def force_turn_with_incoming(state, u, incoming_dir, queue):
        # Force u to use incoming_dir and one perpendicular dir.
        e_in = get_edge(u, incoming_dir)
        if e_in is None:
            return False
        if not set_edge(state, e_in, 2, queue):
            return False
        candidates = []
        for d in range(4):
            if d == incoming_dir or d == OPP[incoming_dir]:
                continue
            e = get_edge(u, d)
            if e is not None and state[e] != 0:
                # must be compatible with clue at u
                poss = allowed_patterns_for_vertex(state, u)
                ok = False
                for s in poss:
                    if s == frozenset((incoming_dir, d)):
                        ok = True
                        break
                if ok:
                    candidates.append(d)
        if not candidates:
            return False
        if len(candidates) == 1:
            d = candidates[0]
            if not set_edge(state, get_edge(u, d), 2, queue):
                return False
            od = OPP[incoming_dir]
            e = get_edge(u, od)
            if e is not None:
                if not set_edge(state, e, 0, queue):
                    return False
            for d2 in range(4):
                if d2 not in (incoming_dir, d):
                    e = get_edge(u, d2)
                    if e is not None:
                        if not set_edge(state, e, 0, queue):
                            return False
        return True

    def partial_subcycle_exists(state):
        # Detect any closed component among ON edges that doesn't include all currently nonzero-degree used vertices.
        parent = {}
        rank = {}

        used_vertices = set()
        on_edges = []
        for e, s in state.items():
            if s == 2:
                a, b = e
                used_vertices.add(a)
                used_vertices.add(b)
                on_edges.append(e)

        if not on_edges:
            return False

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return False
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1
            return True

        for v in used_vertices:
            parent[v] = v
            rank[v] = 0

        cycles = 0
        for a, b in on_edges:
            if not union(a, b):
                cycles += 1

        # In a graph with max degree 2, any cycle before completion is bad unless all used vertices form the final loop and no clue/unknown obligations remain.
        if cycles:
            # Check if every used vertex has degree 2 and there are no possible future attachments from used component to unused.
            all_deg2 = True
            for v in used_vertices:
                on, off, unk = degree_counts(state, v)
                if on != 2:
                    all_deg2 = False
                    break
            if all_deg2:
                # If any clue vertex unused or any unused vertex can connect to loop later, then this is premature.
                for v in clues:
                    if v not in used_vertices:
                        return True
                if len(used_vertices) != n * n:
                    for v in used_vertices:
                        for e in incident[v]:
                            if state[e] == 1:
                                return True
            return True
        return False

    def propagate(state):
        queue = deque(range(n * n))
        inq = [True] * (n * n)

        while queue:
            v = queue.popleft()
            inq[v] = False

            if not force_vertex_degree_0_or_2(state, v, queue):
                return False
            if not apply_vertex_pattern_forcing(state, v, queue):
                return False

            if v in clues:
                if clues[v] == 'B':
                    if not apply_black_rule(state, v, queue):
                        return False
                else:
                    if not apply_white_rule(state, v, queue):
                        return False

            # Re-enqueue neighbors when local state matters.
            for e in incident[v]:
                a, b = e
                u = b if a == v else a
                if not inq[u]:
                    queue.append(u)
                    inq[u] = True

            if partial_subcycle_exists(state):
                return False

        # Global parity/shape checks for clue consistency.
        for v, clue in clues.items():
            poss = allowed_patterns_for_vertex(state, v)
            if not poss:
                return False

            on = vertex_on_dirs(state, v)
            if clue == 'W' and len(on) == 2:
                ds = sorted(on)
                if ds not in ([0, 2], [1, 3]):
                    return False
                neighbors = [(nbr[v][d], OPP[d]) for d in ds]
                feasible = False
                for i in range(2):
                    u, incoming = neighbors[i]
                    if u != -1 and neighbor_can_turn_given_incoming(state, u, incoming):
                        feasible = True
                        break
                if not feasible:
                    return False
            if clue == 'B' and len(on) == 2:
                ds = sorted(on)
                if ds in ([0, 2], [1, 3]):
                    return False
                for d in ds:
                    u = nbr[v][d]
                    if u == -1:
                        return False
                    incoming = OPP[d]
                    # Neighbor must be able to be straight with incoming edge.
                    if not neighbor_can_straight_given_incoming(state, u, incoming):
                        return False

        return True

    def neighbor_can_straight_given_incoming(state, u, incoming_dir):
        e_in = get_edge(u, incoming_dir)
        if e_in is None or state[e_in] == 0:
            return False
        poss = allowed_patterns_for_vertex(state, u)
        for s in poss:
            if incoming_dir in s and len(s) == 2:
                a, b = sorted(s)
                if (a, b) in ((0, 2), (1, 3)):
                    return True
        return False

    def all_assigned(state):
        return all(s != 1 for s in state.values())

    def final_check(state):
        # All clue vertices must be used, all used vertices degree 2, and exactly one cycle.
        for v in clues:
            on, off, unk = degree_counts(state, v)
            if on != 2:
                return False

        used = [v for v in range(n * n) if degree_counts(state, v)[0] > 0]
        if not used:
            return False
        for v in used:
            if degree_counts(state, v)[0] != 2:
                return False

        # single cycle connectivity
        start = used[0]
        seen = {start}
        dq = deque([start])
        while dq:
            v = dq.popleft()
            for e in incident[v]:
                if state[e] == 2:
                    a, b = e
                    u = b if a == v else a
                    if u not in seen:
                        seen.add(u)
                        dq.append(u)
        if len(seen) != len(used):
            return False

        # Need all clues on cycle, already ensured.
        return True

    def choose_branch_edge(state):
        # Human-like branching: prefer edges near clues and in constrained vertices.
        best = None
        best_score = -1
        for e, s in state.items():
            if s != 1:
                continue
            a, b = e
            score = 0
            if a in clues:
                score += 5
            if b in clues:
                score += 5
            score += 4 - degree_counts(state, a)[2]
            score += 4 - degree_counts(state, b)[2]
            if score > best_score:
                best_score = score
                best = e
        return best

    def search(state, depth=0):
        if not propagate(state):
            return None
        if all_assigned(state):
            if final_check(state):
                return state
            return None

        e = choose_branch_edge(state)
        if e is None:
            return None

        # Try ON first, usually stronger in loop puzzles.
        for val in (2, 0):
            st2 = state.copy()
            q = deque()
            if set_edge(st2, e, val, q):
                res = search(st2, depth + 1)
                if res is not None:
                    return res
        return None

    def extract_loop(state):
        # Build ordered closed loop as list of (row, col)
        used = [v for v in range(n * n) if degree_counts(state, v)[0] == 2]
        if not used:
            return None
        start = min(used)
        path = [start]
        prev = None
        cur = start
        while True:
            nxts = []
            for e in incident[cur]:
                if state[e] == 2:
                    a, b = e
                    u = b if a == cur else a
                    if u != prev:
                        nxts.append(u)
            if prev is None:
                if not nxts:
                    return None
                nxt = min(nxts)
            else:
                if len(nxts) != 1:
                    return None
                nxt = nxts[0]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(used) + 1:
                return None
        return [rc(v) for v in path]

    state = dict(edges)
    res = search(state)
    if res is None:
        return "No Solution"
    loop = extract_loop(res)
    return str(loop) if loop is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1, 1, 2], [0, 0, 3, 3, 3, 1, 1, 2], [0, 3, 3, 4, 3, 3, 2, 2], [0, 3, 5, 4, 3, 2, 2, 6], [0, 0, 5, 4, 3, 3, 3, 6], [0, 7, 5, 4, 6, 6, 6, 6], [0, 7, 7, 7, 8, 8, 6, 9], [0, 0, 0, 0, 0, 0, 9, 9]]}

# Generalized 1-star Star Battle solver for region-partitioned NxN grids.
# The solver emphasizes human-like deduction:
# - candidate generation from row/column/region constraints
# - adjacency elimination
# - hidden singles in row/column/region
# - subset/Hall-style feasibility checks on grouped units
# - forced placements by contradiction
# - only then a tightly-pruned search

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    regions = {}
    for r in range(n):
        for c in range(n):
            regions.setdefault(data[r][c], []).append((r, c))
    region_ids = list(regions.keys())

    # Each cell gets a stable bit index.
    cell_index = {}
    index_cell = []
    k = 0
    for r in range(n):
        for c in range(n):
            cell_index[(r, c)] = k
            index_cell.append((r, c))
            k += 1
    all_cells_mask = (1 << (n * n)) - 1

    row_cells = []
    col_cells = []
    region_cells = {}

    for r in range(n):
        m = 0
        for c in range(n):
            m |= 1 << cell_index[(r, c)]
        row_cells.append(m)

    for c in range(n):
        m = 0
        for r in range(n):
            m |= 1 << cell_index[(r, c)]
        col_cells.append(m)

    for rid, cells in regions.items():
        m = 0
        for rc in cells:
            m |= 1 << cell_index[rc]
        region_cells[rid] = m

    # Neighbor mask includes touching orthogonally or diagonally, excluding self.
    neighbor_masks = [0] * (n * n)
    for r in range(n):
        for c in range(n):
            i = cell_index[(r, c)]
            m = 0
            for dr in (-1, 0, 1):
                rr = r + dr
                if 0 <= rr < n:
                    for dc in (-1, 0, 1):
                        cc = c + dc
                        if 0 <= cc < n and not (dr == 0 and dc == 0):
                            m |= 1 << cell_index[(rr, cc)]
            neighbor_masks[i] = m

    # Precompute unit list for generalized deductions.
    units = []
    for r in range(n):
        units.append(("row", r, row_cells[r]))
    for c in range(n):
        units.append(("col", c, col_cells[c]))
    for rid in region_ids:
        units.append(("reg", rid, region_cells[rid]))

    unit_to_cells = {}
    for typ, uid, mask in units:
        cells = []
        mm = mask
        while mm:
            b = mm & -mm
            i = b.bit_length() - 1
            cells.append(i)
            mm ^= b
        unit_to_cells[(typ, uid)] = cells

    row_of = [0] * (n * n)
    col_of = [0] * (n * n)
    reg_of = [None] * (n * n)
    for i, (r, c) in enumerate(index_cell):
        row_of[i] = r
        col_of[i] = c
        reg_of[i] = data[r][c]

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def popcount(x):
        return x.bit_count()

    def unit_masks(possible_mask):
        rows = [possible_mask & row_cells[r] for r in range(n)]
        cols = [possible_mask & col_cells[c] for c in range(n)]
        regs = {rid: possible_mask & region_cells[rid] for rid in region_ids}
        return rows, cols, regs

    def contradiction(placed_mask, forbidden_mask):
        if placed_mask & forbidden_mask:
            return True

        # No touching and no duplicate row/col/region among placed.
        seen_rows = 0
        seen_cols = 0
        seen_regs = set()
        pm = placed_mask
        touched = 0
        while pm:
            b = pm & -pm
            i = b.bit_length() - 1
            r = row_of[i]
            c = col_of[i]
            rid = reg_of[i]
            if (seen_rows >> r) & 1:
                return True
            if (seen_cols >> c) & 1:
                return True
            if rid in seen_regs:
                return True
            if touched & b:
                return True
            seen_rows |= 1 << r
            seen_cols |= 1 << c
            seen_regs.add(rid)
            touched |= neighbor_masks[i]
            pm ^= b

        possible = all_cells_mask & ~forbidden_mask

        # Every unfilled row/col/region must retain at least one candidate.
        rows, cols, regs = unit_masks(possible)
        for r in range(n):
            if not ((seen_rows >> r) & 1) and rows[r] == 0:
                return True
        for c in range(n):
            if not ((seen_cols >> c) & 1) and cols[c] == 0:
                return True
        for rid in region_ids:
            if rid not in seen_regs and regs[rid] == 0:
                return True

        # Simple count feasibility.
        stars_placed = popcount(placed_mask)
        if stars_placed > n:
            return True
        if stars_placed + popcount(possible & ~placed_mask) < n:
            return True

        # Hall-style feasibility on rows, cols, regions:
        # for any subset of unresolved units of same type, union of candidates must be >= number of units.
        # Limited to small subsets to stay fast, but effective.
        def hall_check(unit_candidate_masks):
            unresolved = [m for m in unit_candidate_masks if m]
            mlen = len(unresolved)
            if mlen <= 1:
                return False
            # Sort small candidate sets first.
            unresolved.sort(key=popcount)
            # Check subsets up to size 4 aggressively.
            limit = min(4, mlen)
            def rec(start, depth, target, union_mask):
                if depth == target:
                    return popcount(union_mask) < target
                prev = None
                for idx in range(start, mlen - (target - depth) + 1):
                    m = unresolved[idx]
                    if m == prev:
                        continue
                    prev = m
                    if rec(idx + 1, depth + 1, target, union_mask | m):
                        return True
                return False
            for s in range(2, limit + 1):
                if rec(0, 0, s, 0):
                    return True
            return False

        unresolved_rows = []
        unresolved_cols = []
        unresolved_regs = []
        for r in range(n):
            if not ((seen_rows >> r) & 1):
                unresolved_rows.append(rows[r])
        for c in range(n):
            if not ((seen_cols >> c) & 1):
                unresolved_cols.append(cols[c])
        for rid in region_ids:
            if rid not in seen_regs:
                unresolved_regs.append(regs[rid])

        if hall_check(unresolved_rows) or hall_check(unresolved_cols) or hall_check(unresolved_regs):
            return True

        return False

    def propagate(placed_mask, forbidden_mask):
        if contradiction(placed_mask, forbidden_mask):
            return None

        changed = True
        while changed:
            changed = False

            possible = all_cells_mask & ~forbidden_mask
            rows, cols, regs = unit_masks(possible)

            # Track which units are already satisfied by placed stars.
            filled_rows = [False] * n
            filled_cols = [False] * n
            filled_regs = {rid: False for rid in region_ids}
            pm = placed_mask
            while pm:
                b = pm & -pm
                i = b.bit_length() - 1
                filled_rows[row_of[i]] = True
                filled_cols[col_of[i]] = True
                filled_regs[reg_of[i]] = True
                pm ^= b

            # If a row/col/region is filled, all other cells in it are forbidden.
            extra_forbid = 0
            for r in range(n):
                if filled_rows[r]:
                    extra_forbid |= row_cells[r] & ~placed_mask
            for c in range(n):
                if filled_cols[c]:
                    extra_forbid |= col_cells[c] & ~placed_mask
            for rid in region_ids:
                if filled_regs[rid]:
                    extra_forbid |= region_cells[rid] & ~placed_mask
            if extra_forbid & ~forbidden_mask:
                forbidden_mask |= extra_forbid
                if contradiction(placed_mask, forbidden_mask):
                    return None
                changed = True
                continue

            possible = all_cells_mask & ~forbidden_mask
            rows, cols, regs = unit_masks(possible)

            # Naked singles: unresolved unit with exactly one candidate.
            forced = 0
            for r in range(n):
                if not filled_rows[r] and rows[r] and (rows[r] & (rows[r] - 1) == 0):
                    forced |= rows[r]
            for c in range(n):
                if not filled_cols[c] and cols[c] and (cols[c] & (cols[c] - 1) == 0):
                    forced |= cols[c]
            for rid in region_ids:
                m = regs[rid]
                if not filled_regs[rid] and m and (m & (m - 1) == 0):
                    forced |= m

            # Hidden singles: a candidate cell that is the only one in intersection patterns.
            # Implemented by counting appearances of candidates across unresolved units.
            row_need = [r for r in range(n) if not filled_rows[r]]
            col_need = [c for c in range(n) if not filled_cols[c]]
            reg_need = [rid for rid in region_ids if not filled_regs[rid]]

            # Candidate uniquely serving a row among a region, etc. Human-style spotting.
            # For each unresolved region, if among its candidates only one lies in any unresolved row/col support.
            for rid in reg_need:
                m = regs[rid]
                if m == 0:
                    return None
                # Unique row position inside region after propagation from columns/neighbors can force.
                row_hits = {}
                col_hits = {}
                for i in iter_bits(m):
                    row_hits.setdefault(row_of[i], 0)
                    row_hits[row_of[i]] |= 1 << i
                    col_hits.setdefault(col_of[i], 0)
                    col_hits[col_of[i]] |= 1 << i
                for rr, mm in row_hits.items():
                    if mm and (mm & (mm - 1) == 0):
                        # If this row still unresolved and this cell is only region candidate in that row,
                        # and row candidates compatible, it often forces.
                        forced |= mm
                for cc, mm in col_hits.items():
                    if mm and (mm & (mm - 1) == 0):
                        forced |= mm

            if forced:
                # Place all forced cells, checking consistency.
                fm = forced & ~placed_mask
                if fm:
                    for i in iter_bits(fm):
                        b = 1 << i
                        # If this cell is forbidden by previous placements, contradiction.
                        if forbidden_mask & b:
                            return None
                        placed_mask |= b
                        forbidden_mask |= b
                        forbidden_mask |= neighbor_masks[i]
                    if contradiction(placed_mask, forbidden_mask):
                        return None
                    changed = True
                    continue

            # Hall subset reduction within each unit type:
            # if k unresolved rows have union of exactly k cells, these cells cannot serve other rows/cols/regions
            # We materialize only eliminations that are globally safe by unit type.
            def apply_exact_union(unit_masks_list, unit_cell_masks, filled_flags):
                nonlocal forbidden_mask, changed
                unresolved = []
                for idx, m in enumerate(unit_masks_list):
                    if not filled_flags(idx) and m:
                        unresolved.append((idx, m))
                unresolved.sort(key=lambda t: popcount(t[1]))
                mlen = len(unresolved)
                limit = min(4, mlen)
                any_change = False

                def rec(start, depth, target, chosen_idxs, union_mask):
                    nonlocal any_change, forbidden_mask, changed
                    if any_change:
                        return
                    if depth == target:
                        if popcount(union_mask) == target:
                            # Cells in this exact union cannot appear in other unresolved units of same type.
                            other = 0
                            chosen = set(chosen_idxs)
                            for j, m in unresolved:
                                if j not in chosen:
                                    other |= (m & union_mask)
                            if other:
                                forbidden_mask |= other
                                any_change = True
                                changed = True
                        return
                    prev = None
                    for pos in range(start, mlen - (target - depth) + 1):
                        idx, m = unresolved[pos]
                        if m == prev:
                            continue
                        prev = m
                        new_union = union_mask | m
                        if popcount(new_union) > target:
                            continue
                        rec(pos + 1, depth + 1, target, chosen_idxs + [idx], new_union)
                        if any_change:
                            return

                for s in range(2, limit + 1):
                    rec(0, 0, s, [], 0)
                    if any_change:
                        return

            apply_exact_union(rows, row_cells, lambda idx: filled_rows[idx])
            if contradiction(placed_mask, forbidden_mask):
                return None
            if changed:
                continue

            apply_exact_union(cols, col_cells, lambda idx: filled_cols[idx])
            if contradiction(placed_mask, forbidden_mask):
                return None
            if changed:
                continue

            reg_index = {rid: t for t, rid in enumerate(region_ids)}
            filled_reg_list = [filled_regs[rid] for rid in region_ids]
            reg_masks_list = [regs[rid] for rid in region_ids]
            apply_exact_union(reg_masks_list, region_cells, lambda idx: filled_reg_list[idx])
            if contradiction(placed_mask, forbidden_mask):
                return None
            if changed:
                continue

            # Contradiction-based forcing:
            # if a candidate is the only plausible "front-runner" for a constrained unit, test both branches.
            # We do this conservatively on the smallest unresolved unit.
            possible = all_cells_mask & ~forbidden_mask
            rows, cols, regs = unit_masks(possible)

            best_mask = None
            best_size = 10**9
            best_kind = None
            for r in range(n):
                if not filled_rows[r]:
                    cnt = popcount(rows[r])
                    if 1 < cnt < best_size:
                        best_size = cnt
                        best_mask = rows[r]
                        best_kind = ("row", r)
            for c in range(n):
                if not filled_cols[c]:
                    cnt = popcount(cols[c])
                    if 1 < cnt < best_size:
                        best_size = cnt
                        best_mask = cols[c]
                        best_kind = ("col", c)
            for rid in region_ids:
                if not filled_regs[rid]:
                    cnt = popcount(regs[rid])
                    if 1 < cnt < best_size:
                        best_size = cnt
                        best_mask = regs[rid]
                        best_kind = ("reg", rid)

            if best_mask is not None and best_size <= 3:
                test_forced = 0
                for i in iter_bits(best_mask):
                    b = 1 << i
                    res = propagate(placed_mask, forbidden_mask | b)
                    if res is None:
                        test_forced |= b
                if test_forced:
                    for i in iter_bits(test_forced):
                        b = 1 << i
                        placed_mask |= b
                        forbidden_mask |= b
                        forbidden_mask |= neighbor_masks[i]
                    if contradiction(placed_mask, forbidden_mask):
                        return None
                    changed = True
                    continue

        return placed_mask, forbidden_mask

    def score_state(placed_mask, forbidden_mask):
        possible = all_cells_mask & ~forbidden_mask
        rows, cols, regs = unit_masks(possible)

        filled_rows = set()
        filled_cols = set()
        filled_regs = set()
        for i in iter_bits(placed_mask):
            filled_rows.add(row_of[i])
            filled_cols.add(col_of[i])
            filled_regs.add(reg_of[i])

        best = None
        # Choose the most constrained unresolved unit.
        for r in range(n):
            if r not in filled_rows:
                cnt = popcount(rows[r])
                if cnt == 0:
                    return None
                cand = (cnt, 0, r, rows[r])
                if best is None or cand < best:
                    best = cand
        for c in range(n):
            if c not in filled_cols:
                cnt = popcount(cols[c])
                if cnt == 0:
                    return None
                cand = (cnt, 1, c, cols[c])
                if best is None or cand < best:
                    best = cand
        for rid in region_ids:
            if rid not in filled_regs:
                cnt = popcount(regs[rid])
                if cnt == 0:
                    return None
                cand = (cnt, 2, rid, regs[rid])
                if best is None or cand < best:
                    best = cand
        return best

    def is_complete(placed_mask):
        return popcount(placed_mask) == n

    def search(placed_mask, forbidden_mask):
        state = propagate(placed_mask, forbidden_mask)
        if state is None:
            return None
        placed_mask, forbidden_mask = state

        if is_complete(placed_mask):
            # Final validation.
            if contradiction(placed_mask, forbidden_mask):
                return None
            return placed_mask

        pick = score_state(placed_mask, forbidden_mask)
        if pick is None:
            return None
        _, kind, uid, mask = pick

        # Try candidates in most constraining order:
        # cells that eliminate the largest number of remaining possibilities first.
        options = []
        possible = all_cells_mask & ~forbidden_mask
        for i in iter_bits(mask):
            b = 1 << i
            impact = popcount((neighbor_masks[i] | row_cells[row_of[i]] | col_cells[col_of[i]] | region_cells[reg_of[i]]) & possible)
            options.append((-impact, i))
        options.sort()

        for _, i in options:
            b = 1 << i
            res = search(placed_mask | b, forbidden_mask | b | neighbor_masks[i])
            if res is not None:
                return res

        return None

    result_mask = search(0, 0)
    if result_mask is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for i in iter_bits(result_mask):
        r, c = index_cell[i]
        answer[r][c] = 'S'
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, 'W'], [None, None, 'B', 'W', None, None], [None, None, None, 'W', 'B', None], [None, None, 'W', None, 'W', None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None]]}

from collections import deque

B, W, U = 1, 0, -1


def solve(observation):
    data = observation["data"]
    n = len(data)
    grid = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                grid[r][c] = B
            elif v == 'W':
                grid[r][c] = W

    state = Solver(grid)
    ok = state.propagate_all()
    if not ok:
        return "No Solution"
    ans = state.search()
    if ans is None:
        return "No Solution"
    return repr([[('B' if ans[r][c] == B else 'W') for c in range(n)] for r in range(n)])


class Solver:
    def __init__(self, grid):
        self.n = len(grid)
        self.g = [row[:] for row in grid]

    def clone(self):
        return Solver(self.g)

    def neighbors(self, r, c):
        n = self.n
        if r > 0:
            yield r - 1, c
        if r + 1 < n:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < n:
            yield r, c + 1

    def set_cell(self, r, c, color):
        cur = self.g[r][c]
        if cur == color:
            return True
        if cur != U and cur != color:
            return False
        self.g[r][c] = color
        return True

    def propagate_all(self):
        changed = True
        while changed:
            changed = False
            progress = self.local_deductions()
            if progress is None:
                return False
            if progress:
                changed = True
            progress = self.connectivity_forced_moves()
            if progress is None:
                return False
            if progress:
                changed = True
            if not self.quick_feasibility():
                return False
        return True

    def local_deductions(self):
        n = self.n
        changed = False

        # 2x2 anti-monochrome deductions
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                vals = [self.g[x][y] for x, y in cells]
                for color in (B, W):
                    cnt_color = sum(v == color for v in vals)
                    cnt_unknown = sum(v == U for v in vals)
                    if cnt_color == 4:
                        return None
                    if cnt_color == 3 and cnt_unknown == 1:
                        idx = vals.index(U)
                        x, y = cells[idx]
                        if not self.set_cell(x, y, 1 - color):
                            return None
                        changed = True

        # No same-color separator around opposite color center in lines of 3
        # Pattern X ? X => middle must be opposite of X
        for r in range(n):
            for c in range(n - 2):
                a, b, d = self.g[r][c], self.g[r][c + 1], self.g[r][c + 2]
                if a != U and a == d:
                    if b == a:
                        return None
                    if b == U:
                        if not self.set_cell(r, c + 1, 1 - a):
                            return None
                        changed = True
        for c in range(n):
            for r in range(n - 2):
                a, b, d = self.g[r][c], self.g[r + 1][c], self.g[r + 2][c]
                if a != U and a == d:
                    if b == a:
                        return None
                    if b == U:
                        if not self.set_cell(r + 1, c, 1 - a):
                            return None
                        changed = True

        # Degree-0 contradiction and degree-1 forcing for each color:
        # if an assigned cell has no possible same-color orthogonal neighbor, impossible.
        # if exactly one possible same-color neighbor remains, force it.
        for color in (B, W):
            for r in range(n):
                for c in range(n):
                    if self.g[r][c] != color:
                        continue
                    possibles = []
                    same_fixed = 0
                    for nr, nc in self.neighbors(r, c):
                        v = self.g[nr][nc]
                        if v == color:
                            same_fixed += 1
                        elif v == U:
                            possibles.append((nr, nc))
                    if same_fixed == 0 and not possibles and self.count_color(color) > 1:
                        return None
                    if same_fixed == 0 and len(possibles) == 1 and self.count_color(color) > 1:
                        nr, nc = possibles[0]
                        if not self.set_cell(nr, nc, color):
                            return None
                        changed = True

        return changed

    def count_color(self, color):
        return sum(v == color for row in self.g for v in row)

    def components_info(self, color):
        n = self.n
        vis = [[False] * n for _ in range(n)]
        comps = []
        fixed = 0
        unknown_exists = False
        for r in range(n):
            for c in range(n):
                if self.g[r][c] == color:
                    fixed += 1
                elif self.g[r][c] == U:
                    unknown_exists = True
        for r in range(n):
            for c in range(n):
                if self.g[r][c] == color and not vis[r][c]:
                    q = deque([(r, c)])
                    vis[r][c] = True
                    comp = []
                    boundary_unknown = set()
                    while q:
                        x, y = q.popleft()
                        comp.append((x, y))
                        for nx, ny in self.neighbors(x, y):
                            v = self.g[nx][ny]
                            if v == color and not vis[nx][ny]:
                                vis[nx][ny] = True
                                q.append((nx, ny))
                            elif v == U:
                                boundary_unknown.add((nx, ny))
                    comps.append((comp, boundary_unknown))
        return comps, fixed, unknown_exists

    def connectivity_forced_moves(self):
        changed = False
        for color in (B, W):
            info = self._connectivity_forced_color(color)
            if info is None:
                return None
            if info:
                changed = True
        return changed

    def _connectivity_forced_color(self, color):
        comps, fixed, unknown_exists = self.components_info(color)
        if fixed == 0:
            return False
        if len(comps) == 1:
            return False

        # If there are multiple components, every component must have at least one frontier unknown.
        # If exactly one frontier cell can connect a component outward, force it.
        changed = False
        for comp, frontier in comps:
            if not frontier:
                return None
            if len(frontier) == 1:
                (r, c) = next(iter(frontier))
                if not self.set_cell(r, c, color):
                    return None
                changed = True

        # Articulation-like forcing in unknown graph:
        # Build unknown cells that touch at least one color component.
        # If a particular unknown is the only cell adjacent to 2+ different components, it must be color.
        comp_index = {}
        for i, (comp, _) in enumerate(comps):
            for cell in comp:
                comp_index[cell] = i
        touch_map = {}
        for i, (comp, frontier) in enumerate(comps):
            for u in frontier:
                touch_map.setdefault(u, set()).add(i)
        for u, touched in touch_map.items():
            if len(touched) >= 2:
                r, c = u
                if self.g[r][c] == U:
                    if not self.set_cell(r, c, color):
                        return None
                    changed = True
        return changed

    def quick_feasibility(self):
        return self._color_feasible(B) and self._color_feasible(W) and self._no_forced_monochrome_2x2_dead()

    def _color_feasible(self, color):
        n = self.n
        fixed_cells = [(r, c) for r in range(n) for c in range(n) if self.g[r][c] == color]
        if not fixed_cells:
            return True

        allowed = [[self.g[r][c] != 1 - color for c in range(n)] for r in range(n)]
        start = fixed_cells[0]
        q = deque([start])
        vis = {start}
        while q:
            x, y = q.popleft()
            for nx, ny in self.neighbors(x, y):
                if allowed[nx][ny] and (nx, ny) not in vis:
                    vis.add((nx, ny))
                    q.append((nx, ny))
        for cell in fixed_cells:
            if cell not in vis:
                return False
        return True

    def _no_forced_monochrome_2x2_dead(self):
        n = self.n
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [self.g[r][c], self.g[r + 1][c], self.g[r][c + 1], self.g[r + 1][c + 1]]
                if all(v == B for v in vals) or all(v == W for v in vals):
                    return False
        return True

    def solved(self):
        if any(U in row for row in self.g):
            return False
        if not self._single_component(B):
            return False
        if not self._single_component(W):
            return False
        return self._no_forced_monochrome_2x2_dead()

    def _single_component(self, color):
        n = self.n
        cells = [(r, c) for r in range(n) for c in range(n) if self.g[r][c] == color]
        if not cells:
            return False
        start = cells[0]
        q = deque([start])
        vis = {start}
        while q:
            x, y = q.popleft()
            for nx, ny in self.neighbors(x, y):
                if self.g[nx][ny] == color and (nx, ny) not in vis:
                    vis.add((nx, ny))
                    q.append((nx, ny))
        return len(vis) == len(cells)

    def choose_branch_cell(self):
        n = self.n
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if self.g[r][c] != U:
                    continue
                score = 0
                for nr, nc in self.neighbors(r, c):
                    if self.g[nr][nc] != U:
                        score += 3
                for rr in (r - 1, r):
                    for cc in (c - 1, c):
                        if 0 <= rr < n - 1 and 0 <= cc < n - 1:
                            vals = [self.g[rr][cc], self.g[rr + 1][cc], self.g[rr][cc + 1], self.g[rr + 1][cc + 1]]
                            known = sum(v != U for v in vals)
                            score += known
                if score > best_score:
                    best_score = score
                    best = (r, c)
        return best

    def branch_order(self, r, c):
        # Prefer color that better connects neighboring same-color regions.
        scores = []
        for color in (B, W):
            same = 0
            opp = 0
            for nr, nc in self.neighbors(r, c):
                if self.g[nr][nc] == color:
                    same += 1
                elif self.g[nr][nc] == 1 - color:
                    opp += 1
            scores.append((opp - same, color))
        scores.sort()
        return [color for _, color in scores]

    def search(self):
        if not self.propagate_all():
            return None
        if self.solved():
            return self.g

        cell = self.choose_branch_cell()
        if cell is None:
            return None
        r, c = cell
        for color in self.branch_order(r, c):
            nxt = self.clone()
            if not nxt.set_cell(r, c, color):
                continue
            ans = nxt.search()
            if ans is not None:
                return ans
        return None


