    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, None, None, 3, None, 3, None], [None, None, 2, 3, None, None, None], [None, None, None, None, 1, None, 1], [1, None, None, 1, None, 2, None], [1, None, None, None, 1, None, 2], [None, None, None, 2, None, None, None], [None, 1, 0, None, None, None, 1]]}

from itertools import combinations
from collections import deque
import ast

# Generalized Minesweeper solver with strong logical propagation and small, pruned search.
# It mirrors human deduction:
# - local saturation rules (all remaining neighbors are mines / all safe)
# - subset-difference rules between clue neighborhoods
# - component decomposition on frontier unknowns
# - exact enumeration only inside independent constrained components
# - global consistency merge of component solutions


def neighbors(r, c, rows, cols):
    for dr in (-1, 0, 1):
        nr = r + dr
        if nr < 0 or nr >= rows:
            continue
        for dc in (-1, 0, 1):
            nc = c + dc
            if dc == 0 and dr == 0:
                continue
            if 0 <= nc < cols:
                yield nr, nc


def build_problem(data):
    rows = len(data)
    cols = len(data[0]) if rows else 0

    clues = {}
    unknowns = set()
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is None:
                unknowns.add((r, c))
            else:
                clues[(r, c)] = int(data[r][c])

    clue_to_unknowns = {}
    unknown_to_clues = {u: [] for u in unknowns}
    for pos, val in clues.items():
        us = set()
        r, c = pos
        for nb in neighbors(r, c, rows, cols):
            if nb in unknowns:
                us.add(nb)
                unknown_to_clues[nb].append(pos)
        clue_to_unknowns[pos] = us

    return rows, cols, clues, unknowns, clue_to_unknowns, unknown_to_clues


def propagate(clues, clue_to_unknowns, flagged, safe):
    changed = True
    contradiction = False

    # Repeatedly apply direct human-style deductions + subset rules.
    while changed and not contradiction:
        changed = False

        # Direct saturation rules.
        for clue_pos, target in clues.items():
            uset = clue_to_unknowns[clue_pos]
            rem = []
            flagged_count = 0
            for u in uset:
                if u in flagged:
                    flagged_count += 1
                elif u not in safe:
                    rem.append(u)
            need = target - flagged_count
            if need < 0 or need > len(rem):
                contradiction = True
                break
            if need == 0 and rem:
                for u in rem:
                    if u in flagged:
                        contradiction = True
                        break
                    if u not in safe:
                        safe.add(u)
                        changed = True
                if contradiction:
                    break
            elif need == len(rem) and rem:
                for u in rem:
                    if u in safe:
                        contradiction = True
                        break
                    if u not in flagged:
                        flagged.add(u)
                        changed = True
                if contradiction:
                    break
        if contradiction:
            break

        # Build active equations for subset reasoning.
        eqs = []
        for clue_pos, target in clues.items():
            uset = clue_to_unknowns[clue_pos]
            undec = set()
            flagged_count = 0
            for u in uset:
                if u in flagged:
                    flagged_count += 1
                elif u not in safe:
                    undec.add(u)
            need = target - flagged_count
            if need < 0 or need > len(undec):
                contradiction = True
                break
            if undec:
                eqs.append((frozenset(undec), need))
        if contradiction:
            break

        # Subset-difference rules:
        # If A subset B, then mines(B\A) = needB - needA.
        n = len(eqs)
        for i in range(n):
            set_a, need_a = eqs[i]
            for j in range(n):
                if i == j:
                    continue
                set_b, need_b = eqs[j]
                if len(set_a) > len(set_b):
                    continue
                if set_a.issubset(set_b):
                    diff = set_b - set_a
                    need_diff = need_b - need_a
                    if need_diff < 0 or need_diff > len(diff):
                        contradiction = True
                        break
                    if not diff:
                        continue
                    if need_diff == 0:
                        for u in diff:
                            if u in flagged:
                                contradiction = True
                                break
                            if u not in safe:
                                safe.add(u)
                                changed = True
                        if contradiction:
                            break
                    elif need_diff == len(diff):
                        for u in diff:
                            if u in safe:
                                contradiction = True
                                break
                            if u not in flagged:
                                flagged.add(u)
                                changed = True
                        if contradiction:
                            break
            if contradiction:
                break

    return not contradiction


def frontier_components(frontier, unknown_to_clues):
    # Components among frontier unknowns via shared clues.
    frontier = set(frontier)
    seen = set()
    comps = []
    clue_buckets = {}
    for u in frontier:
        clue_buckets[u] = tuple(unknown_to_clues[u])

    for start in frontier:
        if start in seen:
            continue
        q = deque([start])
        seen.add(start)
        comp = []
        comp_clues = set()
        while q:
            u = q.popleft()
            comp.append(u)
            for cp in clue_buckets[u]:
                comp_clues.add(cp)
            for cp in clue_buckets[u]:
                # traverse through clue to other frontier cells
                pass
        # Expand by clue adjacency
        q2 = deque(comp)
        comp_set = set(comp)
        while q2:
            u = q2.popleft()
            for cp in clue_buckets[u]:
                for v in frontier:
                    if v not in comp_set and cp in clue_buckets[v]:
                        comp_set.add(v)
                        q2.append(v)
        # rebuild clue set
        comp = list(comp_set)
        comp_clues = set()
        for u in comp:
            for cp in clue_buckets[u]:
                comp_clues.add(cp)
        seen.update(comp_set)
        comps.append((comp, list(comp_clues)))
    return comps


def build_component_constraints(comp_vars, comp_clues, clues, clue_to_unknowns, flagged, safe):
    var_index = {u: i for i, u in enumerate(comp_vars)}
    constraints = []

    for cp in comp_clues:
        target = clues[cp]
        flagged_count = 0
        vars_in = []
        for u in clue_to_unknowns[cp]:
            if u in flagged:
                flagged_count += 1
            elif u not in safe and u in var_index:
                vars_in.append(var_index[u])
        need = target - flagged_count

        # Because the component decomposition is over frontier connectivity,
        # any undecided neighbor of this clue must be within the same component.
        # Thus vars_in covers all unresolved cells affecting this clue.
        if need < 0 or need > len(vars_in):
            return None
        constraints.append((tuple(vars_in), need))
    return constraints, var_index


def enumerate_component(comp_vars, constraints):
    n = len(comp_vars)
    if n == 0:
        return [()]

    cons_for_var = [[] for _ in range(n)]
    for ci, (vars_in, need) in enumerate(constraints):
        for v in vars_in:
            cons_for_var[v].append(ci)

    assigned = [-1] * n
    current_sum = [0] * len(constraints)
    current_unassigned = [len(vars_in) for vars_in, _ in constraints]
    solutions = []

    # Variable ordering: most constrained first.
    order = sorted(range(n), key=lambda v: -len(cons_for_var[v]))

    def dfs(k):
        if k == n:
            for ci, (_, need) in enumerate(constraints):
                if current_sum[ci] != need:
                    return
            solutions.append(tuple(assigned))
            return

        v = order[k]

        # Try 0 then 1; later global deductions can use unanimity across solutions.
        for val in (0, 1):
            ok = True
            assigned[v] = val
            touched = []
            for ci in cons_for_var[v]:
                current_unassigned[ci] -= 1
                current_sum[ci] += val
                touched.append(ci)
                _, need = constraints[ci]
                s = current_sum[ci]
                rem = current_unassigned[ci]
                if s > need or s + rem < need:
                    ok = False
                    break
            if ok:
                dfs(k + 1)
            for ci in touched:
                current_sum[ci] -= val
                current_unassigned[ci] += 1
            assigned[v] = -1

    dfs(0)
    return solutions


def solve_with_logic(data):
    rows, cols, clues, unknowns, clue_to_unknowns, unknown_to_clues = build_problem(data)

    flagged = set()
    safe = set()

    if not propagate(clues, clue_to_unknowns, flagged, safe):
        return None

    frontier = {u for u in unknowns if u not in flagged and u not in safe and unknown_to_clues[u]}
    isolated = unknowns - frontier - flagged - safe

    if not frontier:
        # Unconstrained isolated cells must be safe for a valid deterministic completion.
        safe |= isolated
        return flagged, safe

    comps = frontier_components(frontier, unknown_to_clues)

    comp_solutions = []
    for comp_vars, comp_clues in comps:
        built = build_component_constraints(comp_vars, comp_clues, clues, clue_to_unknowns, flagged, safe)
        if built is None:
            return None
        constraints, var_index = built
        sols = enumerate_component(comp_vars, constraints)
        if not sols:
            return None
        comp_solutions.append((comp_vars, sols))

    # Deduce unanimity inside each component, then propagate again.
    changed = True
    while changed:
        changed = False

        for comp_vars, sols in comp_solutions:
            if not sols:
                return None
            m = len(comp_vars)
            for i in range(m):
                vals = {sol[i] for sol in sols}
                u = comp_vars[i]
                if vals == {1}:
                    if u in safe:
                        return None
                    if u not in flagged:
                        flagged.add(u)
                        changed = True
                elif vals == {0}:
                    if u in flagged:
                        return None
                    if u not in safe:
                        safe.add(u)
                        changed = True

        if changed:
            if not propagate(clues, clue_to_unknowns, flagged, safe):
                return None
            frontier = {u for u in unknowns if u not in flagged and u not in safe and unknown_to_clues[u]}
            isolated = unknowns - frontier - flagged - safe
            if not frontier:
                safe |= isolated
                return flagged, safe

            comps = frontier_components(frontier, unknown_to_clues)
            comp_solutions = []
            for comp_vars, comp_clues in comps:
                built = build_component_constraints(comp_vars, comp_clues, clues, clue_to_unknowns, flagged, safe)
                if built is None:
                    return None
                constraints, var_index = built
                sols = enumerate_component(comp_vars, constraints)
                if not sols:
                    return None
                comp_solutions.append((comp_vars, sols))

    # If unresolved but multiple consistent frontier assignments remain, use limited product merge.
    # Components are independent, so pick any solution per component; isolated cells are safe.
    # We only need one valid final completion.
    for comp_vars, sols in comp_solutions:
        chosen = sols[0]
        for i, bit in enumerate(chosen):
            if bit:
                flagged.add(comp_vars[i])
            else:
                safe.add(comp_vars[i])

    safe |= isolated

    # Final verification.
    for cp, target in clues.items():
        cnt = 0
        r, c = cp
        for nb in neighbors(r, c, rows, cols):
            if nb in flagged:
                cnt += 1
        if cnt != target:
            return None

    return flagged, safe


def format_answer(rows, cols, flagged):
    grid = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('F' if (r, c) in flagged else None)
        grid.append(row)
    return str(grid)


def solve(observation):
    data = observation['data']
    rows = len(data)
    cols = len(data[0]) if rows else 0
    result = solve_with_logic(data)
    if result is None:
        return "No Solution"
    flagged, safe = result
    return format_answer(rows, cols, flagged)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, 2, None], [None, None, 4, None, None, None, None], [None, 1, None, None, None, 4, None], [None, None, None, None, 4, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, None, None, None]]}

from collections import deque
from copy import deepcopy


# Nurikabe solver with strong propagation plus bounded search.
# Output format: string representation of a grid using 'B' for black and None for white.


def solve(observation):
    data = observation['data']
    solver = NurikabeSolver(data)
    ans = solver.run()
    if ans is None:
        return "No Solution"
    return repr(ans)


class NurikabeSolver:
    UNKNOWN = -1
    WHITE = 0
    BLACK = 1

    def __init__(self, data):
        self.data = data
        self.R = len(data)
        self.C = len(data[0]) if self.R else 0
        self.N = self.R * self.C
        self.idx_of = lambda r, c: r * self.C + c
        self.rc_of = lambda i: divmod(i, self.C)
        self.neis = [[] for _ in range(self.N)]
        for r in range(self.R):
            for c in range(self.C):
                i = self.idx_of(r, c)
                if r > 0:
                    self.neis[i].append(self.idx_of(r - 1, c))
                if r + 1 < self.R:
                    self.neis[i].append(self.idx_of(r + 1, c))
                if c > 0:
                    self.neis[i].append(self.idx_of(r, c - 1))
                if c + 1 < self.C:
                    self.neis[i].append(self.idx_of(r, c + 1))

        self.clues = []
        self.clue_at = {}
        for r in range(self.R):
            for c in range(self.C):
                v = data[r][c]
                if v is not None:
                    i = self.idx_of(r, c)
                    self.clue_at[i] = len(self.clues)
                    self.clues.append((i, v))

        self.all_cells = list(range(self.N))

        self.initial_state = self.make_initial_state()

    def make_initial_state(self):
        state = {
            'color': [self.UNKNOWN] * self.N,
            'owner_mask': [0] * self.N,   # bitset of clues that may own this white cell
        }
        k = len(self.clues)
        allmask = (1 << k) - 1

        for i in self.all_cells:
            state['owner_mask'][i] = allmask

        for clue_id, (cell, size) in enumerate(self.clues):
            state['color'][cell] = self.WHITE
            state['owner_mask'][cell] = 1 << clue_id

        # Precompute reachability masks from clue size limits.
        clue_reach = [set() for _ in range(k)]
        for clue_id, (root, size) in enumerate(self.clues):
            dist = self.dist_from(root)
            for i, d in enumerate(dist):
                if d != -1 and d < size:
                    clue_reach[clue_id].add(i)

        for i in self.all_cells:
            mask = 0
            for clue_id in range(k):
                if i in clue_reach[clue_id]:
                    mask |= 1 << clue_id
            state['owner_mask'][i] &= mask

        # Cells unreachable from every clue must be black.
        for i in self.all_cells:
            if state['color'][i] == self.UNKNOWN and state['owner_mask'][i] == 0:
                state['color'][i] = self.BLACK

        # Distinct clues cannot share white island:
        # Any cell adjacent to two different clue cells is impossible for both if it would connect clue islands directly?
        # Stronger rule handled by ownership and component checks later.

        return state

    def dist_from(self, src):
        dist = [-1] * self.N
        q = deque([src])
        dist[src] = 0
        while q:
            x = q.popleft()
            for y in self.neis[x]:
                if dist[y] == -1:
                    dist[y] = dist[x] + 1
                    q.append(y)
        return dist

    def clone_state(self, state):
        return {
            'color': state['color'][:],
            'owner_mask': state['owner_mask'][:],
        }

    def run(self):
        state = self.clone_state(self.initial_state)
        state = self.propagate(state)
        if state is None:
            return None
        solved = self.search(state)
        if solved is None:
            return None
        return self.format_answer(solved)

    def format_answer(self, state):
        out = []
        for r in range(self.R):
            row = []
            for c in range(self.C):
                i = self.idx_of(r, c)
                row.append('B' if state['color'][i] == self.BLACK else None)
            out.append(row)
        return out

    def search(self, state):
        if self.is_complete(state):
            if self.final_check(state):
                return state
            return None

        choice = self.choose_branch(state)
        if choice is None:
            return None

        kind = choice[0]
        if kind == 'color':
            i = choice[1]
            for val in choice[2]:
                ns = self.clone_state(state)
                if not self.assign_color(ns, i, val):
                    continue
                ns = self.propagate(ns)
                if ns is None:
                    continue
                ans = self.search(ns)
                if ans is not None:
                    return ans
            return None
        elif kind == 'owner':
            i = choice[1]
            options = choice[2]
            for clue_id in options:
                ns = self.clone_state(state)
                if not self.assign_owner_single(ns, i, clue_id):
                    continue
                ns = self.propagate(ns)
                if ns is None:
                    continue
                ans = self.search(ns)
                if ans is not None:
                    return ans
            return None
        return None

    def is_complete(self, state):
        return all(v != self.UNKNOWN for v in state['color'])

    def popcount(self, x):
        return x.bit_count()

    def iter_bits(self, mask):
        while mask:
            b = mask & -mask
            yield (b.bit_length() - 1)
            mask ^= b

    def assign_color(self, state, i, val):
        cur = state['color'][i]
        if cur == val:
            return True
        if cur != self.UNKNOWN:
            return False
        state['color'][i] = val
        if val == self.BLACK:
            state['owner_mask'][i] = 0
        else:
            if state['owner_mask'][i] == 0:
                return False
        return True

    def forbid_owner(self, state, i, clue_id):
        if state['color'][i] == self.BLACK:
            return True
        bit = 1 << clue_id
        if not (state['owner_mask'][i] & bit):
            return True
        state['owner_mask'][i] &= ~bit
        if state['color'][i] == self.WHITE and state['owner_mask'][i] == 0:
            return False
        if state['color'][i] == self.UNKNOWN and state['owner_mask'][i] == 0:
            state['color'][i] = self.BLACK
        return True

    def assign_owner_single(self, state, i, clue_id):
        if not self.assign_color(state, i, self.WHITE):
            return False
        mask = 1 << clue_id
        if not (state['owner_mask'][i] & mask):
            return False
        state['owner_mask'][i] = mask
        return True

    def propagate(self, state):
        changed = True
        while changed:
            changed = False

            if not self.rule_numbered_white(state):
                return None
            if not self.rule_island_ownership_connectivity(state):
                return None
            if not self.rule_no_adjacent_clue_islands(state):
                return None
            if not self.rule_single_cell_islands(state):
                return None
            if not self.rule_expand_and_cap_islands(state):
                return None
            if not self.rule_black_2x2(state):
                return None
            if not self.rule_black_connectivity(state):
                return None
            if not self.rule_white_reachability(state):
                return None

            sig = (tuple(state['color']), tuple(state['owner_mask']))
            if getattr(self, '_last_sig', None) != sig:
                changed = True
                self._last_sig = sig

        self._last_sig = None
        return state if self.global_consistency(state) else None

    def rule_numbered_white(self, state):
        for clue_id, (cell, size) in enumerate(self.clues):
            if not self.assign_color(state, cell, self.WHITE):
                return False
            if state['owner_mask'][cell] != (1 << clue_id):
                state['owner_mask'][cell] = 1 << clue_id
        return True

    def rule_single_cell_islands(self, state):
        for clue_id, (cell, size) in enumerate(self.clues):
            if size == 1:
                for nb in self.neis[cell]:
                    if not self.assign_color(state, nb, self.BLACK):
                        return False
        return True

    def white_components(self, state):
        comp_id = [-1] * self.N
        comps = []
        cid = 0
        for i in self.all_cells:
            if state['color'][i] == self.WHITE and comp_id[i] == -1:
                q = deque([i])
                comp_id[i] = cid
                cells = []
                while q:
                    x = q.popleft()
                    cells.append(x)
                    for y in self.neis[x]:
                        if state['color'][y] == self.WHITE and comp_id[y] == -1:
                            comp_id[y] = cid
                            q.append(y)
                comps.append(cells)
                cid += 1
        return comp_id, comps

    def rule_island_ownership_connectivity(self, state):
        # White connected components must be compatible with exactly one clue owner.
        comp_id, comps = self.white_components(state)
        for cells in comps:
            owner_inter = None
            clue_cells = []
            for i in cells:
                if owner_inter is None:
                    owner_inter = state['owner_mask'][i]
                else:
                    owner_inter &= state['owner_mask'][i]
                if i in self.clue_at:
                    clue_cells.append(self.clue_at[i])
            if owner_inter == 0:
                return False
            if len(set(clue_cells)) > 1:
                return False
            if clue_cells:
                fixed = clue_cells[0]
                if not (owner_inter & (1 << fixed)):
                    return False
                owner_inter = 1 << fixed
            for i in cells:
                newmask = state['owner_mask'][i] & owner_inter
                if newmask == 0:
                    return False
                state['owner_mask'][i] = newmask

        # Unknown cells adjacent to white cells may need owner restriction.
        for i in self.all_cells:
            if state['color'][i] == self.UNKNOWN:
                adj_white_comps = set()
                adj_owner = 0
                for nb in self.neis[i]:
                    if state['color'][nb] == self.WHITE:
                        adj_white_comps.add(comp_id[nb])
                        adj_owner |= state['owner_mask'][nb]
                if len(adj_white_comps) >= 2:
                    # If touching multiple white components, becoming white could merge them.
                    # Allowed only if all those components can belong to same owner.
                    common = None
                    for cid in adj_white_comps:
                        cells = comps[cid]
                        cm = 0
                        for x in cells:
                            cm |= state['owner_mask'][x]
                        if common is None:
                            common = cm
                        else:
                            common &= cm
                    if common is None or common == 0:
                        if not self.assign_color(state, i, self.BLACK):
                            return False
                if adj_owner:
                    newmask = state['owner_mask'][i] & adj_owner
                    if newmask != state['owner_mask'][i]:
                        state['owner_mask'][i] = newmask
                        if state['owner_mask'][i] == 0:
                            if not self.assign_color(state, i, self.BLACK):
                                return False
        return True

    def rule_no_adjacent_clue_islands(self, state):
        # Any path of white connecting distinct clues is forbidden.
        for clue_id, (cell, _) in enumerate(self.clues):
            for nb in self.neis[cell]:
                if state['color'][nb] != self.BLACK:
                    m = state['owner_mask'][nb]
                    if m & ~(1 << clue_id):
                        state['owner_mask'][nb] &= (1 << clue_id)
                        if state['owner_mask'][nb] == 0:
                            return False
        # Cell adjacent to different clue-anchored white components cannot be white.
        for i in self.all_cells:
            if state['color'][i] == self.UNKNOWN:
                seen = set()
                for nb in self.neis[i]:
                    if state['color'][nb] == self.WHITE:
                        m = state['owner_mask'][nb]
                        if self.popcount(m) == 1:
                            seen.add((m.bit_length() - 1))
                if len(seen) >= 2:
                    if not self.assign_color(state, i, self.BLACK):
                        return False
        return True

    def owned_region_stats(self, state, clue_id):
        root, target = self.clues[clue_id]
        allowed = [False] * self.N
        bit = 1 << clue_id
        for i in self.all_cells:
            if state['color'][i] != self.BLACK and (state['owner_mask'][i] & bit):
                allowed[i] = True

        # Connected allowed region from root
        if not allowed[root]:
            return None
        q = deque([root])
        seen = {root}
        while q:
            x = q.popleft()
            for y in self.neis[x]:
                if allowed[y] and y not in seen:
                    seen.add(y)
                    q.append(y)

        mandatory_white = set()
        maybe = set()
        for i in seen:
            if state['color'][i] == self.WHITE:
                mandatory_white.add(i)
            else:
                maybe.add(i)

        return {
            'root': root,
            'target': target,
            'reachable': seen,
            'mandatory': mandatory_white,
            'maybe': maybe,
        }

    def rule_expand_and_cap_islands(self, state):
        for clue_id, (root, target) in enumerate(self.clues):
            info = self.owned_region_stats(state, clue_id)
            if info is None:
                return False
            mandatory = info['mandatory']
            reachable = info['reachable']
            maybe = info['maybe']

            if len(mandatory) > target:
                return False
            if len(reachable) < target:
                return False

            # If island already full, all other reachable cells for that owner must be black/forbidden.
            if len(mandatory) == target:
                for i in reachable:
                    if i not in mandatory:
                        if not self.forbid_owner(state, i, clue_id):
                            return False

            # If exactly enough reachable cells remain, all must be white and belong here.
            if len(reachable) == target:
                for i in reachable:
                    if not self.assign_owner_single(state, i, clue_id):
                        return False

            # Articulation-like human rule:
            # If a mandatory component would become disconnected from root without an unknown bridge,
            # force the only bridge.
            allowed = set(reachable)
            forced = self.compute_forced_connectors(state, clue_id, allowed)
            if forced is None:
                return False
            for i in forced:
                if not self.assign_owner_single(state, i, clue_id):
                    return False

        return True

    def compute_forced_connectors(self, state, clue_id, allowed):
        root, target = self.clues[clue_id]
        bit = 1 << clue_id
        forced = set()
        mandatory = [i for i in allowed if state['color'][i] == self.WHITE and (state['owner_mask'][i] & bit)]
        for m in mandatory:
            if m == root:
                continue
            paths = self.count_short_paths_within_allowed(root, m, allowed, limit=2)
            if paths == 0:
                return None
            if len(paths) == 1:
                for x in next(iter(paths)):
                    if state['color'][x] == self.UNKNOWN:
                        forced.add(x)
        return forced

    def count_short_paths_within_allowed(self, src, dst, allowed, limit=2):
        # Enumerate up to limit simple shortest paths by BFS parents.
        dist = {src: 0}
        q = deque([src])
        while q:
            x = q.popleft()
            if x == dst:
                break
            for y in self.neis[x]:
                if y in allowed and y not in dist:
                    dist[y] = dist[x] + 1
                    q.append(y)
        if dst not in dist:
            return 0
        d = dist[dst]
        parents = {}
        for x in allowed:
            if x in dist:
                parents[x] = [y for y in self.neis[x] if y in dist and dist[y] == dist[x] - 1]

        res = set()

        def bt(x, path):
            if len(res) >= limit:
                return
            if x == src:
                res.add(tuple(sorted(path)))
                return
            for p in parents.get(x, []):
                bt(p, path + [p])

        bt(dst, [dst])
        return res

    def rule_black_2x2(self, state):
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [
                    self.idx_of(r, c),
                    self.idx_of(r + 1, c),
                    self.idx_of(r, c + 1),
                    self.idx_of(r + 1, c + 1),
                ]
                vals = [state['color'][i] for i in cells]
                bc = vals.count(self.BLACK)
                uc = vals.count(self.UNKNOWN)
                if bc == 4:
                    return False
                if bc == 3 and uc == 1:
                    i = cells[vals.index(self.UNKNOWN)]
                    if not self.assign_color(state, i, self.WHITE):
                        return False
        return True

    def blackish_cells(self, state):
        return [i for i in self.all_cells if state['color'][i] != self.WHITE]

    def rule_black_connectivity(self, state):
        black = [i for i in self.all_cells if state['color'][i] == self.BLACK]
        if not black:
            return True

        nonwhite = set(self.blackish_cells(state))
        start = black[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in self.neis[x]:
                if y in nonwhite and y not in seen:
                    seen.add(y)
                    q.append(y)

        for b in black:
            if b not in seen:
                return False

        # Any unknown cell not connected through non-white graph to existing black must be white.
        for i in self.all_cells:
            if state['color'][i] == self.UNKNOWN and i not in seen:
                if not self.assign_color(state, i, self.WHITE):
                    return False

        # If an unknown cell is articulation in the non-white graph connecting black zones, force black.
        # Approximation: if removing an unknown splits current black reachability to some black, make it black.
        unknowns = [i for i in self.all_cells if state['color'][i] == self.UNKNOWN]
        if len(black) >= 2:
            for u in unknowns:
                if self.unknown_required_for_black_connection(state, u, black):
                    if not self.assign_color(state, u, self.BLACK):
                        return False
        return True

    def unknown_required_for_black_connection(self, state, u, black_cells):
        nonwhite = set(self.blackish_cells(state))
        if u not in nonwhite:
            return False
        start = black_cells[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in self.neis[x]:
                if y in nonwhite and y != u and y not in seen:
                    seen.add(y)
                    q.append(y)
        for b in black_cells:
            if b not in seen:
                return True
        return False

    def rule_white_reachability(self, state):
        # Unknown cell with owners all eliminated becomes black already.
        # White cells/components must still be expandable to target sizes.
        for clue_id, (root, target) in enumerate(self.clues):
            info = self.owned_region_stats(state, clue_id)
            if info is None:
                return False
            if len(info['mandatory']) > target or len(info['reachable']) < target:
                return False

        # Any unknown white candidate that would immediately violate island size if white for all owners -> black.
        for i in self.all_cells:
            if state['color'][i] == self.UNKNOWN:
                ok_owner = []
                for clue_id in self.iter_bits(state['owner_mask'][i]):
                    ns = {
                        'color': state['color'][:],
                        'owner_mask': state['owner_mask'][:],
                    }
                    if self.assign_owner_single(ns, i, clue_id):
                        if self.quick_local_consistent(ns, i, clue_id):
                            ok_owner.append(clue_id)
                if not ok_owner:
                    if not self.assign_color(state, i, self.BLACK):
                        return False
                else:
                    mask = 0
                    for clue_id in ok_owner:
                        mask |= (1 << clue_id)
                    state['owner_mask'][i] = mask
        return True

    def quick_local_consistent(self, state, touched_cell, clue_id):
        info = self.owned_region_stats(state, clue_id)
        if info is None:
            return False
        if len(info['mandatory']) > info['target'] or len(info['reachable']) < info['target']:
            return False
        if not self.local_no_2x2_around(state, touched_cell):
            return False
        return True

    def local_no_2x2_around(self, state, i):
        r, c = self.rc_of(i)
        for rr in range(max(0, r - 1), min(self.R - 1, r) + 1):
            for cc in range(max(0, c - 1), min(self.C - 1, c) + 1):
                cells = [
                    self.idx_of(rr, cc),
                    self.idx_of(rr + 1, cc),
                    self.idx_of(rr, cc + 1),
                    self.idx_of(rr + 1, cc + 1),
                ]
                if all(state['color'][x] == self.BLACK for x in cells):
                    return False
        return True

    def global_consistency(self, state):
        # White component clue compatibility
        comp_id, comps = self.white_components(state)
        for cells in comps:
            clues = set()
            common = (1 << len(self.clues)) - 1
            for i in cells:
                common &= state['owner_mask'][i]
                if i in self.clue_at:
                    clues.add(self.clue_at[i])
            if common == 0:
                return False
            if len(clues) > 1:
                return False
            if len(clues) == 1:
                clue_id = next(iter(clues))
                if not (common & (1 << clue_id)):
                    return False
                target = self.clues[clue_id][1]
                if len(cells) > target:
                    return False
        # 2x2 black
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [
                    self.idx_of(r, c),
                    self.idx_of(r + 1, c),
                    self.idx_of(r, c + 1),
                    self.idx_of(r + 1, c + 1),
                ]
                if all(state['color'][x] == self.BLACK for x in cells):
                    return False
        return True

    def final_check(self, state):
        # All cells decided.
        if any(v == self.UNKNOWN for v in state['color']):
            return False

        # Black connected.
        black = [i for i in self.all_cells if state['color'][i] == self.BLACK]
        if black:
            q = deque([black[0]])
            seen = {black[0]}
            while q:
                x = q.popleft()
                for y in self.neis[x]:
                    if state['color'][y] == self.BLACK and y not in seen:
                        seen.add(y)
                        q.append(y)
            if len(seen) != len(black):
                return False

        # No 2x2 black.
        for r in range(self.R - 1):
            for c in range(self.C - 1):
                cells = [
                    self.idx_of(r, c),
                    self.idx_of(r + 1, c),
                    self.idx_of(r, c + 1),
                    self.idx_of(r + 1, c + 1),
                ]
                if all(state['color'][x] == self.BLACK for x in cells):
                    return False

        # White islands exact.
        visited = set()
        for i in self.all_cells:
            if state['color'][i] == self.WHITE and i not in visited:
                q = deque([i])
                visited.add(i)
                cells = []
                clues = []
                while q:
                    x = q.popleft()
                    cells.append(x)
                    if x in self.clue_at:
                        clues.append(self.clue_at[x])
                    for y in self.neis[x]:
                        if state['color'][y] == self.WHITE and y not in visited:
                            visited.add(y)
                            q.append(y)
                if len(clues) != 1:
                    return False
                clue_id = clues[0]
                if len(cells) != self.clues[clue_id][1]:
                    return False
        return True

    def choose_branch(self, state):
        # Prefer unresolved white ownership on white cells, then highly constrained unknown cells.
        best = None
        best_score = None

        for i in self.all_cells:
            if state['color'][i] == self.WHITE:
                pc = self.popcount(state['owner_mask'][i])
                if pc > 1:
                    score = (0, pc)
                    if best_score is None or score < best_score:
                        best_score = score
                        best = ('owner', i, list(self.iter_bits(state['owner_mask'][i])))
        if best is not None:
            return best

        for i in self.all_cells:
            if state['color'][i] == self.UNKNOWN:
                color_options = []
                # Try more constrained order.
                if self.can_be_black(state, i):
                    color_options.append(self.BLACK)
                if self.can_be_white(state, i):
                    color_options.append(self.WHITE)
                if not color_options:
                    return ('color', i, [])
                deg = sum(1 for nb in self.neis[i] if state['color'][nb] == self.UNKNOWN)
                own = self.popcount(state['owner_mask'][i])
                score = (1, len(color_options), own, deg)
                if best_score is None or score < best_score:
                    # heuristic: if cell touches white, test white first; if 2x2 risk/connectivity risk, black first.
                    order = self.branch_order_for_cell(state, i, color_options)
                    best_score = score
                    best = ('color', i, order)
        return best

    def can_be_black(self, state, i):
        ns = self.clone_state(state)
        if not self.assign_color(ns, i, self.BLACK):
            return False
        return self.global_consistency(ns)

    def can_be_white(self, state, i):
        if state['owner_mask'][i] == 0:
            return False
        for clue_id in self.iter_bits(state['owner_mask'][i]):
            ns = self.clone_state(state)
            if self.assign_owner_single(ns, i, clue_id) and self.quick_local_consistent(ns, i, clue_id):
                return True
        return False

    def branch_order_for_cell(self, state, i, options):
        if len(options) <= 1:
            return options
        white_touch = any(state['color'][nb] == self.WHITE for nb in self.neis[i])
        black_touch = any(state['color'][nb] == self.BLACK for nb in self.neis[i])
        if white_touch and not black_touch:
            return [self.WHITE, self.BLACK] if self.WHITE in options and self.BLACK in options else options
        return [self.BLACK, self.WHITE] if self.BLACK in options and self.WHITE in options else options


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 1, None, None, None, None, None, None, None], [None, None, None, 5, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, 1, None, None, None, None, None], [None, None, None, None, None, 9, None, None, None, 5], [6, None, None, 3, None, None, None, 8, None, None], [None, None, None, None, None, None, None, None, 3, None], [None, None, None, None, None, None, None, None, None, None], [1, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, 1, None, None]]}

from collections import deque
import ast

UNKNOWN = -1
WHITE = 0
BLACK = 1

def solve(observation):
    data = observation['data']
    h = len(data)
    w = len(data[0]) if h else 0
    cells = [(r, c) for r in range(h) for c in range(w)]
    idx_of = {(r, c): r * w + c for r, c in cells}
    pos_of = {idx_of[p]: p for p in cells}

    def neighbors(rc):
        r, c = rc
        if r > 0:
            yield (r - 1, c)
        if r + 1 < h:
            yield (r + 1, c)
        if c > 0:
            yield (r, c - 1)
        if c + 1 < w:
            yield (r, c + 1)

    clues = []
    clue_id_of_cell = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                clue_id_of_cell[(r, c)] = len(clues)
                clues.append(((r, c), data[r][c]))

    # Precompute all connected placements for each island, then derive per-cell support.
    placements = []
    cell_to_placements = []
    for cid, (root, size) in enumerate(clues):
        if size == 1:
            plist = [frozenset([root])]
        else:
            plist = []
            seen = set()
            stack = [(frozenset([root]), set(neighbors(root)))]
            while stack:
                comp, frontier = stack.pop()
                if len(comp) == size:
                    key = tuple(sorted(comp))
                    if key not in seen:
                        seen.add(key)
                        plist.append(frozenset(comp))
                    continue
                # Heuristic: expand in deterministic order
                for cell in sorted(frontier):
                    if cell in comp:
                        continue
                    new_comp = set(comp)
                    new_comp.add(cell)
                    new_frontier = set(frontier)
                    new_frontier.discard(cell)
                    for nb in neighbors(cell):
                        if nb not in new_comp:
                            new_frontier.add(nb)
                    stack.append((frozenset(new_comp), new_frontier))
        placements.append(plist)
        cmap = {}
        for pidx, pl in enumerate(plist):
            for cell in pl:
                cmap.setdefault(cell, []).append(pidx)
        cell_to_placements.append(cmap)

    # If a cell is reachable by multiple clues, it cannot be white in two islands simultaneously.
    clue_reach = {}
    for cid, cmap in enumerate(cell_to_placements):
        for cell in cmap:
            clue_reach.setdefault(cell, []).append(cid)

    state = [UNKNOWN] * (h * w)
    for cid, (root, size) in enumerate(clues):
        state[idx_of[root]] = WHITE

    possible = [set(range(len(placements[cid]))) for cid in range(len(clues))]

    def clone_state(st, poss):
        return st[:], [set(s) for s in poss]

    def set_cell(st, rc, color):
        i = idx_of[rc]
        cur = st[i]
        if cur != UNKNOWN and cur != color:
            return False
        st[i] = color
        return True

    def get_cell(st, rc):
        return st[idx_of[rc]]

    def all_2x2_blocks():
        for r in range(h - 1):
            for c in range(w - 1):
                yield [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]

    blocks2 = list(all_2x2_blocks())
    cell_to_blocks = {p: [] for p in cells}
    for b in blocks2:
        for p in b:
            cell_to_blocks[p].append(b)

    def filter_placements_by_state(st, poss):
        changed = True
        while changed:
            changed = False

            # Remove placements conflicting with fixed cells and with other clue numbers.
            for cid, plist in enumerate(placements):
                rem = set()
                root, size = clues[cid]
                for pidx in poss[cid]:
                    pl = plist[pidx]
                    bad = False
                    for cell in pl:
                        if get_cell(st, cell) == BLACK:
                            bad = True
                            break
                        if cell in clue_id_of_cell and clue_id_of_cell[cell] != cid:
                            bad = True
                            break
                    if bad:
                        rem.add(pidx)
                        continue
                    for r, c in cells:
                        if (r, c) not in pl and get_cell(st, (r, c)) == WHITE:
                            # White cells must belong to exactly one island; if this cell can only belong to cid later, handled elsewhere.
                            pass
                if rem:
                    poss[cid] -= rem
                    changed = True
                if not poss[cid]:
                    return False, True

            # Overlap elimination between different clues.
            for cell, cids in clue_reach.items():
                supporting = []
                for cid in cids:
                    sup = [pidx for pidx in poss[cid] if cell in placements[cid][pidx]]
                    if sup:
                        supporting.append((cid, sup))
                if len(supporting) >= 2:
                    # If cell fixed white, only one clue may support it.
                    if get_cell(st, cell) == WHITE:
                        owners = [cid for cid, sup in supporting]
                        determined = []
                        for cid, sup in supporting:
                            if all(cell in placements[cid][p] for p in poss[cid]):
                                determined.append(cid)
                        if len(determined) > 1:
                            return False, True
                    # If any clue must include this cell, all others must exclude it.
                    must_include = []
                    for cid, sup in supporting:
                        if len(sup) == len(poss[cid]):
                            must_include.append(cid)
                    if len(must_include) > 1:
                        return False, True
                    if len(must_include) == 1:
                        owner = must_include[0]
                        for cid, sup in supporting:
                            if cid != owner:
                                newset = {p for p in poss[cid] if cell not in placements[cid][p]}
                                if newset != poss[cid]:
                                    poss[cid] = newset
                                    changed = True
                                if not poss[cid]:
                                    return False, True

            # Forced cell colors from placement intersections/unions.
            for cid, plist in enumerate(placements):
                if not poss[cid]:
                    return False, True
                union = set()
                inter = None
                for pidx in poss[cid]:
                    pl = plist[pidx]
                    union |= pl
                    inter = set(pl) if inter is None else inter & set(pl)

                for cell in inter:
                    if not set_cell(st, cell, WHITE):
                        return False, True
                # Cells that are in reach map for only this clue but not in union cannot be white for this clue.
                # More generally, if a white cell cannot belong to any clue placement, contradiction handled later.

            # Any cell not supportable by any clue and not forced black? If white impossible -> black.
            for cell in cells:
                if cell in clue_id_of_cell:
                    if not set_cell(st, cell, WHITE):
                        return False, True
                    continue
                supporters = []
                for cid, cmap in enumerate(cell_to_placements):
                    if cell in cmap:
                        ok = False
                        for pidx in cmap[cell]:
                            if pidx in poss[cid]:
                                ok = True
                                break
                        if ok:
                            supporters.append(cid)
                cur = get_cell(st, cell)
                if cur == WHITE and not supporters:
                    return False, True
                if cur == UNKNOWN and not supporters:
                    if not set_cell(st, cell, BLACK):
                        return False, True
                    changed = True

            # White uniqueness for non-numbered cells:
            for cell in cells:
                if cell in clue_id_of_cell:
                    continue
                if get_cell(st, cell) == WHITE:
                    owners = []
                    for cid, cmap in enumerate(cell_to_placements):
                        if cell in cmap and any(pidx in poss[cid] for pidx in cmap[cell]):
                            owners.append(cid)
                    if len(owners) == 0:
                        return False, True
                    if len(owners) == 1:
                        cid = owners[0]
                        newset = {p for p in poss[cid] if cell in placements[cid][p]}
                        if newset != poss[cid]:
                            poss[cid] = newset
                            changed = True
                        if not poss[cid]:
                            return False, True

            # If a cell can belong to only one clue and all placements of that clue include it? handled by previous loops

            # No adjacent different islands through orth adjacency:
            # If two clues could claim orthogonally adjacent whites, both cells cannot be white under different clues.
            for r, c in cells:
                for nb in neighbors((r, c)):
                    if idx_of[(r, c)] < idx_of[nb]:
                        a = (r, c)
                        b = nb
                        if get_cell(st, a) == WHITE and get_cell(st, b) == WHITE:
                            owners_a = []
                            owners_b = []
                            for cid, cmap in enumerate(cell_to_placements):
                                if a in cmap and any(p in poss[cid] for p in cmap[a]):
                                    owners_a.append(cid)
                                if b in cmap and any(p in poss[cid] for p in cmap[b]):
                                    owners_b.append(cid)
                            common = set(owners_a) & set(owners_b)
                            if not common:
                                return False, True
                            if len(common) == 1:
                                cid = next(iter(common))
                                newset = {p for p in poss[cid] if a in placements[cid][p] and b in placements[cid][p]}
                                if newset != poss[cid]:
                                    poss[cid] = newset
                                    changed = True
                                if not poss[cid]:
                                    return False, True

            # 2x2 black rule.
            for block in blocks2:
                vals = [get_cell(st, p) for p in block]
                bc = sum(v == BLACK for v in vals)
                uc = sum(v == UNKNOWN for v in vals)
                if bc == 4:
                    return False, True
                if bc == 3 and uc == 1:
                    p = block[vals.index(UNKNOWN)]
                    if not set_cell(st, p, WHITE):
                        return False, True
                    changed = True

            # White connected component around each clue cannot exceed target; if a white region with one clue reaches exact size, frontier blacks.
            if not local_white_region_checks(st, poss, clues, clue_id_of_cell, neighbors, cells, get_cell, set_cell):
                return False, True

            # Black connectivity feasibility.
            if not black_connectivity_feasible(st, cells, neighbors, get_cell):
                return False, True

        return True, False

    def local_white_region_checks(st, poss, clues, clue_id_of_cell, neighbors, cells, get_cell, set_cell):
        seen = set()
        for cell in cells:
            if get_cell(st, cell) != WHITE or cell in seen:
                continue
            comp = []
            q = [cell]
            seen.add(cell)
            clues_in = []
            frontier = set()
            while q:
                cur = q.pop()
                comp.append(cur)
                if cur in clue_id_of_cell:
                    clues_in.append(clue_id_of_cell[cur])
                for nb in neighbors(cur):
                    v = get_cell(st, nb)
                    if v == WHITE and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
                    elif v == UNKNOWN:
                        frontier.add(nb)
            if len(clues_in) == 0:
                return False
            if len(set(clues_in)) > 1:
                return False
            cid = clues_in[0]
            target = clues[cid][1]
            if len(comp) > target:
                return False
            if len(comp) == target:
                for nb in frontier:
                    if not set_cell(st, nb, BLACK):
                        return False
            else:
                # Need enough room to expand.
                reach = set(comp)
                qq = deque(comp)
                while qq:
                    cur = qq.popleft()
                    for nb in neighbors(cur):
                        if nb in reach:
                            continue
                        if get_cell(st, nb) != BLACK:
                            # Cannot pass through numbered cells of other clues.
                            if nb in clue_id_of_cell and clue_id_of_cell[nb] != cid:
                                continue
                            reach.add(nb)
                            qq.append(nb)
                if len(reach) < target:
                    return False
        return True

    def black_connectivity_feasible(st, cells, neighbors, get_cell):
        blacks = [c for c in cells if get_cell(st, c) == BLACK]
        nonwhite = [c for c in cells if get_cell(st, c) != WHITE]
        if not blacks:
            return True
        seen = set([blacks[0]])
        q = deque([blacks[0]])
        while q:
            cur = q.popleft()
            for nb in neighbors(cur):
                if nb not in seen and get_cell(st, nb) != WHITE:
                    seen.add(nb)
                    q.append(nb)
        for b in blacks:
            if b not in seen:
                return False
        return True

    ok, _ = filter_placements_by_state(state, possible)
    if not ok:
        return "No Solution"

    def finalized(st, poss):
        if any(v == UNKNOWN for v in st):
            return False
        # Each clue exactly one placement must match whites.
        for cid, plist in enumerate(placements):
            good = []
            for pidx, pl in enumerate(plist):
                fits = True
                for cell in cells:
                    v = get_cell(st, cell)
                    if cell in pl:
                        if v != WHITE:
                            fits = False
                            break
                    else:
                        if cell == clues[cid][0]:
                            fits = False
                            break
                if fits:
                    good.append(pidx)
            if len(good) != 1:
                return False
        # Black connected
        blacks = [c for c in cells if get_cell(st, c) == BLACK]
        if blacks:
            seen = set([blacks[0]])
            q = deque([blacks[0]])
            while q:
                cur = q.popleft()
                for nb in neighbors(cur):
                    if nb not in seen and get_cell(st, nb) == BLACK:
                        seen.add(nb)
                        q.append(nb)
            if len(seen) != len(blacks):
                return False
        # No 2x2 black
        for block in blocks2:
            if all(get_cell(st, p) == BLACK for p in block):
                return False
        return True

    def choose_branch(st, poss):
        best = None
        # First branch on clue with fewest placements > 1.
        for cid in range(len(clues)):
            n = len(poss[cid])
            if 1 < n and (best is None or n < best[0]):
                best = (n, 'clue', cid)
        # Also branch on ambiguous cell with strong split.
        for cell in cells:
            if get_cell(st, cell) != UNKNOWN:
                continue
            supporters = 0
            for cid, cmap in enumerate(cell_to_placements):
                if cell in cmap and any(p in poss[cid] for p in cmap[cell]):
                    supporters += 1
            if supporters == 0:
                return ('cell', cell)
        if best is not None:
            return best[1], best[2]
        for cell in cells:
            if get_cell(st, cell) == UNKNOWN:
                return ('cell', cell)
        return None

    def search(st, poss):
        ok, _ = filter_placements_by_state(st, poss)
        if not ok:
            return None
        if finalized(st, poss):
            return st
        choice = choose_branch(st, poss)
        if choice is None:
            return None

        if choice[0] == 'clue':
            cid = choice[1]
            # Human-like: try placements that force most cells first.
            scored = []
            for pidx in poss[cid]:
                pl = placements[cid][pidx]
                score = 0
                for cell in cells:
                    cur = get_cell(st, cell)
                    if cur == UNKNOWN:
                        if cell in pl:
                            score += 2
                        elif cell in cell_to_placements[cid]:
                            score += 1
                scored.append((-score, pidx))
            for _, pidx in sorted(scored):
                nst, nposs = clone_state(st, poss)
                nposs[cid] = {pidx}
                res = search(nst, nposs)
                if res is not None:
                    return res
            return None
        else:
            cell = choice[1]
            # Prefer black first unless cell is strongly island-supported.
            supporters = []
            for cid, cmap in enumerate(cell_to_placements):
                if cell in cmap:
                    sup = [p for p in cmap[cell] if p in poss[cid]]
                    if sup:
                        supporters.append((cid, sup))
            order = [BLACK, WHITE]
            if len(supporters) == 1:
                order = [WHITE, BLACK]
            for color in order:
                nst, nposs = clone_state(st, poss)
                if not set_cell(nst, cell, color):
                    continue
                if color == WHITE and len(supporters) == 1:
                    cid = supporters[0][0]
                    nposs[cid] = {p for p in nposs[cid] if cell in placements[cid][p]}
                    if not nposs[cid]:
                        continue
                res = search(nst, nposs)
                if res is not None:
                    return res
            return None

    result = search(state, possible)
    if result is None:
        return "No Solution"

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if result[idx_of[(r, c)]] == BLACK else None)
        out.append(row)
    return str(out)

