# Star Battle solver for 2-star puzzles.
# The code emphasizes strong logical propagation before branching:
# - row/col/region exact counts
# - no-touch adjacency elimination
# - hidden singles
# - subset/capacity reasoning on row/col-region intersections
# - forced stars from lower-bound packing in independent path/cycle components
# - branch on the most constrained undecided cell only when logic stalls

from collections import defaultdict, deque

STAR = 1
EMPTY = 0
UNKNOWN = -1


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    stars_per_unit = 2
    cell_count = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    regions = defaultdict(list)
    cell_region = [None] * cell_count
    for r in range(n):
        for c in range(n):
            rid = data[r][c]
            i = idx(r, c)
            regions[rid].append(i)
            cell_region[i] = rid
    region_ids = sorted(regions)

    if len(region_ids) != n:
        # Standard Star Battle has N regions on NxN board.
        # Still solve generally if possible, but counts must remain 2 per region.
        pass

    row_cells = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c) for r in range(n)] for c in range(n)]
    reg_cells = [regions[rid] for rid in region_ids]
    region_index_of_id = {rid: k for k, rid in enumerate(region_ids)}
    cell_reg_index = [region_index_of_id[cell_region[i]] for i in range(cell_count)]

    neighbors = [[] for _ in range(cell_count)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            adj = []
            for dr in (-1, 0, 1):
                rr = r + dr
                if 0 <= rr < n:
                    for dc in (-1, 0, 1):
                        cc = c + dc
                        if 0 <= cc < n and not (dr == 0 and dc == 0):
                            adj.append(idx(rr, cc))
            neighbors[i] = adj

    row_of = [i // n for i in range(cell_count)]
    col_of = [i % n for i in range(cell_count)]

    # Precompute row/col intersection masks with regions as exact cell lists
    row_region_cells = [[[] for _ in range(len(region_ids))] for _ in range(n)]
    col_region_cells = [[[] for _ in range(len(region_ids))] for _ in range(n)]
    for i in range(cell_count):
        r = row_of[i]
        c = col_of[i]
        g = cell_reg_index[i]
        row_region_cells[r][g].append(i)
        col_region_cells[c][g].append(i)

    # Pairwise non-touch among same line gives stronger "placement pairs" reasoning.
    line_non_touch_ok = {}
    for kind, lines in (("row", row_cells), ("col", col_cells), ("reg", reg_cells)):
        for li, cells in enumerate(lines):
            pairs = []
            m = len(cells)
            for a in range(m):
                i = cells[a]
                for b in range(a + 1, m):
                    j = cells[b]
                    if j not in neighbors[i]:
                        pairs.append((i, j))
            line_non_touch_ok[(kind, li)] = pairs

    units = []
    unit_cells = []
    # rows
    for r in range(n):
        units.append(("row", r))
        unit_cells.append(row_cells[r])
    # cols
    for c in range(n):
        units.append(("col", c))
        unit_cells.append(col_cells[c])
    # regions
    for g in range(len(region_ids)):
        units.append(("reg", g))
        unit_cells.append(reg_cells[g])

    cell_units = [[] for _ in range(cell_count)]
    for ui, cells in enumerate(unit_cells):
        for i in cells:
            cell_units[i].append(ui)

    class State:
        __slots__ = (
            "val",
            "row_star", "col_star", "reg_star",
            "row_unk", "col_unk", "reg_unk",
            "changed",
        )

        def __init__(self):
            self.val = [UNKNOWN] * cell_count
            self.row_star = [0] * n
            self.col_star = [0] * n
            self.reg_star = [0] * len(region_ids)
            self.row_unk = [n] * n
            self.col_unk = [n] * n
            self.reg_unk = [len(reg_cells[g]) for g in range(len(region_ids))]
            self.changed = True

        def clone(self):
            s = State.__new__(State)
            s.val = self.val[:]
            s.row_star = self.row_star[:]
            s.col_star = self.col_star[:]
            s.reg_star = self.reg_star[:]
            s.row_unk = self.row_unk[:]
            s.col_unk = self.col_unk[:]
            s.reg_unk = self.reg_unk[:]
            s.changed = self.changed
            return s

    def set_cell(state, i, v):
        cur = state.val[i]
        if cur == v:
            return True
        if cur != UNKNOWN:
            return False

        r = row_of[i]
        c = col_of[i]
        g = cell_reg_index[i]

        state.val[i] = v
        state.changed = True

        state.row_unk[r] -= 1
        state.col_unk[c] -= 1
        state.reg_unk[g] -= 1

        if v == STAR:
            state.row_star[r] += 1
            state.col_star[c] += 1
            state.reg_star[g] += 1

            if state.row_star[r] > stars_per_unit or state.col_star[c] > stars_per_unit or state.reg_star[g] > stars_per_unit:
                return False

            for j in neighbors[i]:
                if state.val[j] == STAR:
                    return False
            for j in neighbors[i]:
                if state.val[j] == UNKNOWN:
                    if not set_cell(state, j, EMPTY):
                        return False

        # capacity checks
        if state.row_star[r] + state.row_unk[r] < stars_per_unit:
            return False
        if state.col_star[c] + state.col_unk[c] < stars_per_unit:
            return False
        if state.reg_star[g] + state.reg_unk[g] < stars_per_unit:
            return False

        return True

    def unit_status(state, kind, k):
        if kind == "row":
            return state.row_star[k], state.row_unk[k], row_cells[k]
        if kind == "col":
            return state.col_star[k], state.col_unk[k], col_cells[k]
        return state.reg_star[k], state.reg_unk[k], reg_cells[k]

    def basic_count_propagation(state):
        progress = False
        for kind, k in units:
            s, u, cells = unit_status(state, kind, k)
            need = stars_per_unit - s
            if need < 0 or need > u:
                return None
            if need == 0:
                for i in cells:
                    if state.val[i] == UNKNOWN:
                        if not set_cell(state, i, EMPTY):
                            return None
                        progress = True
            elif need == u:
                for i in cells:
                    if state.val[i] == UNKNOWN:
                        if not set_cell(state, i, STAR):
                            return None
                        progress = True
        return progress

    def hidden_single_propagation(state):
        progress = False
        for kind, k in units:
            s, u, cells = unit_status(state, kind, k)
            need = stars_per_unit - s
            if need <= 0:
                continue
            cand = [i for i in cells if state.val[i] == UNKNOWN]
            if len(cand) < need:
                return None
            if need == 1:
                viable = []
                for i in cand:
                    ok = True
                    for j in neighbors[i]:
                        if state.val[j] == STAR:
                            ok = False
                            break
                    if ok:
                        viable.append(i)
                if len(viable) < 1:
                    return None
                if len(viable) == 1:
                    if not set_cell(state, viable[0], STAR):
                        return None
                    progress = True
        return progress

    def subset_intersection_propagation(state):
        progress = False

        # For each row/column and each region intersection:
        # If a unit still needs k stars and all its candidates lie inside a small set A,
        # then other units interacting with A can be constrained.
        # Implement the strongest cheap rule:
        # If row r needs t stars and exactly t candidate cells in region g are the only row candidates,
        # then all other cells of region g become empty if region also needs exactly t there.
        # Also symmetric for columns.
        for r in range(n):
            row_need = stars_per_unit - state.row_star[r]
            if row_need <= 0:
                continue
            row_cands = [i for i in row_cells[r] if state.val[i] == UNKNOWN]
            if len(row_cands) == row_need and row_cands:
                regs = {cell_reg_index[i] for i in row_cands}
                for g in regs:
                    other = [i for i in reg_cells[g] if state.val[i] == UNKNOWN and row_of[i] != r]
                    reg_need = stars_per_unit - state.reg_star[g]
                    in_row = [i for i in row_cands if cell_reg_index[i] == g]
                    if len(in_row) == reg_need:
                        for i in other:
                            if not set_cell(state, i, EMPTY):
                                return None
                            progress = True

        for c in range(n):
            col_need = stars_per_unit - state.col_star[c]
            if col_need <= 0:
                continue
            col_cands = [i for i in col_cells[c] if state.val[i] == UNKNOWN]
            if len(col_cands) == col_need and col_cands:
                regs = {cell_reg_index[i] for i in col_cands}
                for g in regs:
                    other = [i for i in reg_cells[g] if state.val[i] == UNKNOWN and col_of[i] != c]
                    reg_need = stars_per_unit - state.reg_star[g]
                    in_col = [i for i in col_cands if cell_reg_index[i] == g]
                    if len(in_col) == reg_need:
                        for i in other:
                            if not set_cell(state, i, EMPTY):
                                return None
                            progress = True

        # Region confined to exact rows/cols:
        for g in range(len(region_ids)):
            reg_need = stars_per_unit - state.reg_star[g]
            if reg_need <= 0:
                continue
            cands = [i for i in reg_cells[g] if state.val[i] == UNKNOWN]
            if len(cands) < reg_need:
                return None
            rows_used = defaultdict(list)
            cols_used = defaultdict(list)
            for i in cands:
                rows_used[row_of[i]].append(i)
                cols_used[col_of[i]].append(i)
            if len(rows_used) == reg_need:
                rows_set = set(rows_used)
                for r in rows_set:
                    for i in row_cells[r]:
                        if state.val[i] == UNKNOWN and cell_reg_index[i] != g:
                            if not set_cell(state, i, EMPTY):
                                return None
                            progress = True
            if len(cols_used) == reg_need:
                cols_set = set(cols_used)
                for c in cols_set:
                    for i in col_cells[c]:
                        if state.val[i] == UNKNOWN and cell_reg_index[i] != g:
                            if not set_cell(state, i, EMPTY):
                                return None
                            progress = True

        return progress

    def feasible_pairs_for_unit(state, kind, k):
        pairs = []
        s, u, cells = unit_status(state, kind, k)
        need = stars_per_unit - s
        if need < 0 or need > u:
            return None
        if need == 0:
            return [()]
        if need == 1:
            for i in cells:
                if state.val[i] != UNKNOWN:
                    continue
                bad = False
                for j in neighbors[i]:
                    if state.val[j] == STAR:
                        bad = True
                        break
                if bad:
                    continue
                pairs.append((i,))
            return pairs
        # need == 2 in practice from zero progress states
        all_pairs = line_non_touch_ok[(kind, k)]
        for a, b in all_pairs:
            if state.val[a] == EMPTY or state.val[b] == EMPTY:
                continue
            if state.val[a] == STAR and state.val[b] == STAR:
                pairs.append((a, b))
                continue
            if state.val[a] == STAR:
                # b must be compatible with all existing stars; adjacency to a already okay
                bad = False
                for j in neighbors[b]:
                    if state.val[j] == STAR and j != a:
                        bad = True
                        break
                if not bad:
                    pairs.append((a, b))
                continue
            if state.val[b] == STAR:
                bad = False
                for j in neighbors[a]:
                    if state.val[j] == STAR and j != b:
                        bad = True
                        break
                if not bad:
                    pairs.append((a, b))
                continue
            bad = False
            for j in neighbors[a]:
                if state.val[j] == STAR:
                    bad = True
                    break
            if not bad:
                for j in neighbors[b]:
                    if state.val[j] == STAR:
                        bad = True
                        break
            if not bad:
                pairs.append((a, b))
        return pairs

    def pair_cover_propagation(state):
        progress = False
        for kind, k in units:
            poss = feasible_pairs_for_unit(state, kind, k)
            if poss is None or len(poss) == 0:
                return None

            flat = set()
            for p in poss:
                for i in p:
                    flat.add(i)

            s, u, cells = unit_status(state, kind, k)
            need = stars_per_unit - s

            # Cells not appearing in any feasible completion cannot be stars.
            if need > 0:
                for i in cells:
                    if state.val[i] == UNKNOWN and i not in flat:
                        if not set_cell(state, i, EMPTY):
                            return None
                        progress = True

            # Cells appearing in every feasible completion must be stars.
            if poss:
                inter = set(poss[0])
                for p in poss[1:]:
                    inter &= set(p)
                for i in inter:
                    if state.val[i] == UNKNOWN:
                        if not set_cell(state, i, STAR):
                            return None
                        progress = True
        return progress

    def component_packing_propagation(state):
        progress = False

        # Build graph of remaining candidate cells where edges mean "cannot both be star"
        # only between king-neighbors. In a row/column/region, stars count = 2.
        # For each connected component under adjacency, compute a maximum independent-set size
        # if the component is a path/cycle after row/col restriction induced candidates.
        # Use this only when cheap and exact:
        # If a unit needs k stars and the sum of MIS upper bounds of its components is exactly k,
        # all component-forced stars can be derived.
        candidates = [i for i in range(cell_count) if state.val[i] == UNKNOWN]
        cand_set = set(candidates)
        graph = {}
        for i in candidates:
            graph[i] = [j for j in neighbors[i] if j in cand_set]

        visited = set()
        comps = []
        for i in candidates:
            if i in visited:
                continue
            dq = [i]
            visited.add(i)
            comp = []
            while dq:
                x = dq.pop()
                comp.append(x)
                for y in graph[x]:
                    if y not in visited:
                        visited.add(y)
                        dq.append(y)
            comps.append(comp)

        # Only use exact reasoning on components with max degree <= 2 and small size.
        comp_info = {}
        for comp in comps:
            ok = True
            degs = []
            for x in comp:
                d = sum(1 for y in graph[x] if y in comp)
                degs.append(d)
                if d > 2:
                    ok = False
                    break
            if not ok or len(comp) > 14:
                continue

            # Enumerate exact independent sets for this small/path-like component.
            comp_list = comp[:]
            pos = {x: t for t, x in enumerate(comp_list)}
            adjmask = [0] * len(comp_list)
            for t, x in enumerate(comp_list):
                m = 0
                for y in graph[x]:
                    if y in pos:
                        m |= 1 << pos[y]
                adjmask[t] = m

            indep_masks = []
            best = 0

            def rec(p, used_mask, chosen_mask, cnt):
                nonlocal best
                if p == len(comp_list):
                    indep_masks.append((chosen_mask, cnt))
                    if cnt > best:
                        best = cnt
                    return
                rec(p + 1, used_mask, chosen_mask, cnt)
                if not (used_mask >> p) & 1:
                    rec(p + 1, used_mask | (1 << p) | adjmask[p], chosen_mask | (1 << p), cnt + 1)

            rec(0, 0, 0, 0)
            max_masks = [m for m, cnt in indep_masks if cnt == best]
            forced_bits = None
            union_bits = 0
            for m in max_masks:
                union_bits |= m
                forced_bits = m if forced_bits is None else (forced_bits & m)
            comp_info[frozenset(comp)] = (comp_list, best, forced_bits, union_bits)

        if not comp_info:
            return False

        # Apply to each unit.
        for kind, k in units:
            s, u, cells = unit_status(state, kind, k)
            need = stars_per_unit - s
            if need <= 0:
                continue
            ucands = [i for i in cells if state.val[i] == UNKNOWN]
            if not ucands:
                continue

            parts = []
            seen = set()
            for i in ucands:
                if i in seen:
                    continue
                stack = [i]
                seen.add(i)
                part = []
                while stack:
                    x = stack.pop()
                    part.append(x)
                    for y in graph.get(x, []):
                        if y in ucands and y not in seen:
                            seen.add(y)
                            stack.append(y)
                parts.append(part)

            total_upper = 0
            exact_parts = []
            for part in parts:
                key = frozenset(part)
                if key in comp_info:
                    comp_list, best, forced_bits, union_bits = comp_info[key]
                    total_upper += best
                    exact_parts.append((part, comp_list, best, forced_bits, union_bits))
                else:
                    # crude upper bound by size
                    total_upper += len(part)
            if total_upper < need:
                return None

            if total_upper == need:
                # Every exact component must realize its maximum; cells not in union of max sets are empty,
                # cells in intersection of all max sets are stars.
                for part, comp_list, best, forced_bits, union_bits in exact_parts:
                    for t, i in enumerate(comp_list):
                        bit = 1 << t
                        if state.val[i] != UNKNOWN:
                            continue
                        if not (union_bits & bit):
                            if not set_cell(state, i, EMPTY):
                                return None
                            progress = True
                        elif forced_bits & bit:
                            if not set_cell(state, i, STAR):
                                return None
                            progress = True

        return progress

    def propagate(state):
        while True:
            state.changed = False

            for fn in (
                basic_count_propagation,
                hidden_single_propagation,
                pair_cover_propagation,
                subset_intersection_propagation,
                component_packing_propagation,
                basic_count_propagation,
            ):
                res = fn(state)
                if res is None:
                    return False
                if state.changed:
                    break

            if not state.changed:
                break

        # Final consistency
        for r in range(n):
            if state.row_star[r] > stars_per_unit or state.row_star[r] + state.row_unk[r] < stars_per_unit:
                return False
        for c in range(n):
            if state.col_star[c] > stars_per_unit or state.col_star[c] + state.col_unk[c] < stars_per_unit:
                return False
        for g in range(len(region_ids)):
            if state.reg_star[g] > stars_per_unit or state.reg_star[g] + state.reg_unk[g] < stars_per_unit:
                return False

        for i in range(cell_count):
            if state.val[i] == STAR:
                for j in neighbors[i]:
                    if state.val[j] == STAR:
                        return False
        return True

    def solved(state):
        return (
            all(x == stars_per_unit for x in state.row_star) and
            all(x == stars_per_unit for x in state.col_star) and
            all(x == stars_per_unit for x in state.reg_star)
        )

    def choose_branch_cell(state):
        # Most constrained candidate: minimize product of residual capacities around the cell,
        # favor cells in units with fewer feasible completions.
        best = None
        best_key = None

        row_poss_cache = {}
        col_poss_cache = {}
        reg_poss_cache = {}

        for i in range(cell_count):
            if state.val[i] != UNKNOWN:
                continue

            r = row_of[i]
            c = col_of[i]
            g = cell_reg_index[i]

            if r not in row_poss_cache:
                p = feasible_pairs_for_unit(state, "row", r)
                row_poss_cache[r] = 0 if p is None else len(p)
            if c not in col_poss_cache:
                p = feasible_pairs_for_unit(state, "col", c)
                col_poss_cache[c] = 0 if p is None else len(p)
            if g not in reg_poss_cache:
                p = feasible_pairs_for_unit(state, "reg", g)
                reg_poss_cache[g] = 0 if p is None else len(p)

            star_block = sum(1 for j in neighbors[i] if state.val[j] == UNKNOWN)
            key = (
                row_poss_cache[r] + col_poss_cache[c] + reg_poss_cache[g],
                (stars_per_unit - state.row_star[r]) + (stars_per_unit - state.col_star[c]) + (stars_per_unit - state.reg_star[g]),
                -star_block,
                len([j for j in neighbors[i] if state.val[j] == UNKNOWN]),
            )
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def search(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        i = choose_branch_cell(state)
        if i is None:
            return None

        # Try STAR first if plausible; otherwise EMPTY.
        for v in (STAR, EMPTY):
            s2 = state.clone()
            if set_cell(s2, i, v):
                ans = search(s2)
                if ans is not None:
                    return ans
        return None

    init = State()
    ans = search(init)
    if ans is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            v = ans.val[idx(r, c)]
            row.append('S' if v == STAR else None)
        out.append(row)
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [0, 0, 0, 0], 'D': [3, 2, 0, 0], 'L': [0, 0, 0, 0], 'R': [3, 3, 0, 2]}

from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)
    nums = tuple(range(1, n + 1))

    all_perms = list(permutations(nums))

    row_candidates = []
    for r in range(n):
        lc = L[r]
        rc = R[r]
        cands = []
        for p in all_perms:
            if lc and visible_count(p) != lc:
                continue
            if rc and visible_count(p[::-1]) != rc:
                continue
            cands.append(p)
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    col_allowed = []
    for c in range(n):
        uc = U[c]
        dc = D[c]
        allowed = []
        for p in all_perms:
            if uc and visible_count(p) != uc:
                continue
            if dc and visible_count(p[::-1]) != dc:
                continue
            allowed.append(p)
        if not allowed:
            return "No Solution"
        col_allowed.append(allowed)

    col_prefix_sets = []
    for c in range(n):
        prefix_map = {}
        for p in col_allowed[c]:
            for k in range(n + 1):
                pref = p[:k]
                prefix_map.setdefault(k, set()).add(pref)
        col_prefix_sets.append(prefix_map)

    row_index_order = sorted(range(n), key=lambda r: len(row_candidates[r]))

    def propagate(cands_by_row):
        changed = True
        while changed:
            changed = False

            allowed_vals = [[set() for _ in range(n)] for _ in range(n)]
            for r in range(n):
                for p in cands_by_row[r]:
                    for c, v in enumerate(p):
                        allowed_vals[r][c].add(v)

            for r in range(n):
                new_list = []
                for p in cands_by_row[r]:
                    ok = True
                    for c, v in enumerate(p):
                        for rr in range(n):
                            if rr != r and v not in allowed_vals[rr][c]:
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        new_list.append(p)
                if not new_list:
                    return None
                if len(new_list) != len(cands_by_row[r]):
                    cands_by_row[r] = new_list
                    changed = True

            cell_domains = [[set() for _ in range(n)] for _ in range(n)]
            for r in range(n):
                for p in cands_by_row[r]:
                    for c, v in enumerate(p):
                        cell_domains[r][c].add(v)

            for c in range(n):
                union_vals = [cell_domains[r][c] for r in range(n)]
                for r in range(n):
                    forced_elsewhere = set()
                    for rr in range(n):
                        if rr != r and len(union_vals[rr]) == 1:
                            forced_elsewhere |= union_vals[rr]
                    new_domain = union_vals[r] - forced_elsewhere
                    if not new_domain:
                        if len(union_vals[r]) == 1:
                            new_domain = union_vals[r]
                        else:
                            return None
                    if new_domain != union_vals[r]:
                        new_list = [p for p in cands_by_row[r] if p[c] in new_domain]
                        if not new_list:
                            return None
                        if len(new_list) != len(cands_by_row[r]):
                            cands_by_row[r] = new_list
                            changed = True

            prefixes = [tuple(next(iter({p[c] for p in cands_by_row[r] if True})) for r in range(0)) for c in range(0)]
            for c in range(n):
                possible_prefixes = set()
                rows_done = []
                fixed = True
                for r in range(n):
                    vals = {p[c] for p in cands_by_row[r]}
                    if len(vals) == 1:
                        rows_done.append(next(iter(vals)))
                    else:
                        fixed = False
                        break
                if fixed:
                    pref = tuple(rows_done)
                    if pref not in col_prefix_sets[c][n]:
                        return None

        return cands_by_row

    def check_partial_prefixes(assignments):
        for c in range(n):
            pref = []
            for r in range(n):
                if assignments[r] is None:
                    break
                pref.append(assignments[r][c])
            pref = tuple(pref)
            if pref not in col_prefix_sets[c][len(pref)]:
                return False
        return True

    def final_grid_ok(grid):
        for c in range(n):
            col = tuple(grid[r][c] for r in range(n))
            if len(set(col)) != n:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(col[::-1]) != D[c]:
                return False
        return True

    initial = [list(rc) for rc in row_candidates]
    initial = propagate(initial)
    if initial is None:
        return "No Solution"

    assignments = [None] * n

    def choose_row(cands_by_row):
        best_r = None
        best_len = 10**9
        for r in row_index_order:
            if assignments[r] is None:
                ln = len(cands_by_row[r])
                if ln < best_len:
                    best_len = ln
                    best_r = r
        return best_r

    def search(cands_by_row):
        done = True
        for r in range(n):
            if assignments[r] is None:
                done = False
                break
        if done:
            grid = [list(assignments[r]) for r in range(n)]
            return grid if final_grid_ok(grid) else None

        r = choose_row(cands_by_row)
        cands = cands_by_row[r]

        def score_row(p):
            s = 0
            for c in range(n):
                used = set()
                for rr in range(n):
                    if assignments[rr] is not None:
                        used.add(assignments[rr][c])
                if p[c] not in used:
                    s += 1
            return s

        for p in sorted(cands, key=score_row):
            conflict = False
            for c in range(n):
                for rr in range(n):
                    if rr != r and assignments[rr] is not None and assignments[rr][c] == p[c]:
                        conflict = True
                        break
                if conflict:
                    break
            if conflict:
                continue

            assignments[r] = p
            if not check_partial_prefixes(assignments):
                assignments[r] = None
                continue

            new_cands = [lst[:] for lst in cands_by_row]
            new_cands[r] = [p]

            ok = True
            for rr in range(n):
                if rr == r or assignments[rr] is not None:
                    continue
                filtered = []
                for q in new_cands[rr]:
                    good = True
                    for c in range(n):
                        if q[c] == p[c]:
                            good = False
                            break
                    if good:
                        filtered.append(q)
                if not filtered:
                    ok = False
                    break
                new_cands[rr] = filtered
            if ok:
                new_cands = propagate(new_cands)
                if new_cands is not None:
                    res = search(new_cands)
                    if res is not None:
                        return res

            assignments[r] = None

        return None

    result = search(initial)
    return str(result) if result is not None else "No Solution"


