OBSERVATION = {'U': [0, 5, 0, 0, 3], 'D': [2, 0, 4, 0, 0], 'L': [0, 4, 0, 0, 0], 'R': [3, 0, 0, 0, 3]}

from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def clue_ok(seq, left_clue, right_clue):
    if left_clue and visible_count(seq) != left_clue:
        return False
    if right_clue and visible_count(seq[::-1]) != right_clue:
        return False
    return True


def partial_visible_possible(prefix, clue, n):
    if clue == 0:
        return True
    seen = 0
    mx = 0
    for x in prefix:
        if x > mx:
            mx = x
            seen += 1
    if seen > clue:
        return False
    remaining = n - len(prefix)
    max_additional = 0
    cur = mx
    for v in range(cur + 1, n + 1):
        max_additional += 1
    return seen <= clue <= seen + min(remaining, max_additional)


def suffix_visibility_bounds(prefix, n):
    seen = 0
    mx = 0
    for x in prefix:
        if x > mx:
            mx = x
            seen += 1
    remaining = n - len(prefix)
    max_additional = 0
    for v in range(mx + 1, n + 1):
        max_additional += 1
    return seen, seen + min(remaining, max_additional)


def row_candidates_for_clues(n, left_clue, right_clue):
    nums = tuple(range(1, n + 1))
    out = []
    for p in permutations(nums):
        if clue_ok(p, left_clue, right_clue):
            out.append(p)
    return out


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    # Precompute all row permutations satisfying row-side clues.
    row_domains = [row_candidates_for_clues(n, L[r], R[r]) for r in range(n)]
    if any(not dom for dom in row_domains):
        return "No Solution"

    # Human-like direct deductions from extreme clues:
    # clue 1 => first building is tallest; clue n => row/col strictly ascending from that side.
    forced = [[0] * n for _ in range(n)]

    for r in range(n):
        if L[r] == 1:
            forced[r][0] = n
        if R[r] == 1:
            forced[r][n - 1] = n
        if L[r] == n:
            for c in range(n):
                forced[r][c] = c + 1
        if R[r] == n:
            for c in range(n):
                forced[r][c] = n - c

    for c in range(n):
        if U[c] == 1:
            if forced[0][c] not in (0, n):
                return "No Solution"
            forced[0][c] = n
        if D[c] == 1:
            if forced[n - 1][c] not in (0, n):
                return "No Solution"
            forced[n - 1][c] = n
        if U[c] == n:
            for r in range(n):
                v = r + 1
                if forced[r][c] not in (0, v):
                    return "No Solution"
                forced[r][c] = v
        if D[c] == n:
            for r in range(n):
                v = n - r
                if forced[r][c] not in (0, v):
                    return "No Solution"
                forced[r][c] = v

    # Filter row domains by forced cells and simple column clue implications.
    for r in range(n):
        nd = []
        for row in row_domains[r]:
            ok = True
            for c in range(n):
                if forced[r][c] and row[c] != forced[r][c]:
                    ok = False
                    break
            if ok:
                nd.append(row)
        row_domains[r] = nd
        if not nd:
            return "No Solution"

    # Column-wise support filtering loop.
    changed = True
    while changed:
        changed = False

        # Cell supports from row domains.
        cell_vals = [[set() for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for row in row_domains[r]:
                for c, v in enumerate(row):
                    cell_vals[r][c].add(v)

        # Enforce Latin uniqueness support per column and clue-feasible prefixes/suffixes.
        for r in range(n):
            nd = []
            for row in row_domains[r]:
                good = True
                for c, v in enumerate(row):
                    # value v at (r,c) must remain possible in column c
                    if v not in cell_vals[r][c]:
                        good = False
                        break
                if good:
                    nd.append(row)
            if len(nd) != len(row_domains[r]):
                row_domains[r] = nd
                changed = True
                if not nd:
                    return "No Solution"

        # Stronger per-column support based on row domains and clue bounds.
        col_possible = [None] * n
        for c in range(n):
            poss = [set() for _ in range(n)]
            for r in range(n):
                for row in row_domains[r]:
                    poss[r].add(row[c])
            col_possible[c] = poss

        # Remove row candidates that make any column impossible.
        for r in range(n):
            nd = []
            for row in row_domains[r]:
                good = True
                for c in range(n):
                    # Candidate prefix in column c through row r
                    prefix = []
                    for rr in range(r):
                        vals = {cand[c] for cand in row_domains[rr]}
                        if len(vals) == 1:
                            prefix.append(next(iter(vals)))
                        else:
                            break
                    # If all earlier rows fixed in this column, append current value and test top clue feasibility.
                    if len(prefix) == r:
                        pref = prefix + [row[c]]
                        if not partial_visible_possible(pref, U[c], n):
                            good = False
                            break
                    # Symmetric from bottom where later rows are fixed.
                    suffix = []
                    for rr in range(n - 1, r, -1):
                        vals = {cand[c] for cand in row_domains[rr]}
                        if len(vals) == 1:
                            suffix.append(next(iter(vals)))
                        else:
                            break
                    if len(suffix) == (n - 1 - r):
                        pref_rev = suffix + [row[c]]
                        if not partial_visible_possible(pref_rev, D[c], n):
                            good = False
                            break
                if good:
                    nd.append(row)
            if len(nd) != len(row_domains[r]):
                row_domains[r] = nd
                changed = True
                if not nd:
                    return "No Solution"

    # Backtracking with aggressive propagation; choose most constrained row.
    assigned = [None] * n
    used_in_col = [set() for _ in range(n)]

    def column_prefix_ok(c, upto_r, val):
        seq = []
        for r in range(upto_r):
            seq.append(assigned[r][c])
        seq.append(val)
        return partial_visible_possible(seq, U[c], n)

    def column_suffix_final_ok(c):
        col = [assigned[r][c] for r in range(n)]
        if len(set(col)) != n:
            return False
        if U[c] and visible_count(col) != U[c]:
            return False
        if D[c] and visible_count(col[::-1]) != D[c]:
            return False
        return True

    def feasible_row_values(r, row):
        for c, v in enumerate(row):
            if v in used_in_col[c]:
                return False
            if not column_prefix_ok(c, r, v):
                return False
        return True

    def select_row():
        best_r = None
        best_list = None
        best_len = None
        for r in range(n):
            if assigned[r] is not None:
                continue
            cand = [row for row in row_domains[r] if feasible_row_values(r, row)]
            if not cand:
                return r, []
            if best_len is None or len(cand) < best_len:
                best_len = len(cand)
                best_r = r
                best_list = cand
        return best_r, best_list

    def recurse(done):
        if done == n:
            for c in range(n):
                if not column_suffix_final_ok(c):
                    return None
            return [list(assigned[r]) for r in range(n)]

        r, cand_rows = select_row()
        if not cand_rows:
            return None

        # Heuristic ordering: rows that constrain columns more first.
        def score(row):
            s = 0
            for c, v in enumerate(row):
                s += len(row_domains[r])
                if U[c]:
                    pref = [assigned[rr][c] for rr in range(r) if assigned[rr] is not None]
                    s -= visible_count(pref + [v])
            return s

        cand_rows.sort(key=score)

        for row in cand_rows:
            assigned[r] = row
            for c, v in enumerate(row):
                used_in_col[c].add(v)

            # Fast forward-check on remaining rows.
            fail = False
            for rr in range(n):
                if assigned[rr] is not None:
                    continue
                any_ok = False
                for prow in row_domains[rr]:
                    ok = True
                    for c, v in enumerate(prow):
                        if v in used_in_col[c]:
                            ok = False
                            break
                    if ok:
                        any_ok = True
                        break
                if not any_ok:
                    fail = True
                    break

            # If this assignment completes a top prefix or bottom suffix in some columns, check clue feasibility tighter.
            if not fail:
                for c in range(n):
                    prefix = []
                    k = 0
                    while k < n and assigned[k] is not None:
                        prefix.append(assigned[k][c])
                        k += 1
                    if prefix and not partial_visible_possible(prefix, U[c], n):
                        fail = True
                        break

            if not fail:
                res = recurse(done + 1)
                if res is not None:
                    return res

            for c, v in enumerate(row):
                used_in_col[c].remove(v)
            assigned[r] = None

        return None

    ans = recurse(0)
    return ans if ans is not None else "No Solution"


