OBSERVATION = {'U': [3, 3, 0, 0, 0], 'D': [0, 0, 0, 0, 0], 'L': [2, 0, 1, 0, 0], 'R': [0, 0, 2, 2, 0]}

from itertools import permutations

# General Skyscrapers solver with strong logical filtering plus targeted backtracking.
# Clue value 0 means "no clue"/unknown.


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def bit_count(x):
    return x.bit_count()


def values_from_mask(mask, n):
    return [v for v in range(1, n + 1) if mask & (1 << (v - 1))]


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)
    full_mask = (1 << n) - 1

    # Precompute all row permutations grouped by side-clue pair.
    perms = list(permutations(range(1, n + 1)))
    row_candidates_by_clue = {}
    for left in range(n + 1):
        for right in range(n + 1):
            row_candidates_by_clue[(left, right)] = []

    for p in perms:
        lv = visible_count(p)
        rv = visible_count(reversed(p))
        for left in (0, lv):
            for right in (0, rv):
                row_candidates_by_clue[(left, right)].append(p)

    # Initial row domains from row clues.
    row_domains = [list(row_candidates_by_clue[(L[r], R[r])]) for r in range(n)]
    if any(not d for d in row_domains):
        return "No Solution"

    # Cell masks inferred from row domains.
    cell_masks = [[full_mask for _ in range(n)] for _ in range(n)]

    # Column used-values exact assignments tracker via masks.
    # Deductions are performed through row domains and cell masks jointly.

    def recompute_cell_masks(row_domains):
        masks = [[0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                m = 0
                for p in row_domains[r]:
                    m |= 1 << (p[c] - 1)
                masks[r][c] = m
                if m == 0:
                    return None
        return masks

    def filter_rows_by_cell_masks(row_domains, cell_masks):
        changed = False
        for r in range(n):
            old = row_domains[r]
            new = []
            for p in old:
                ok = True
                for c, v in enumerate(p):
                    if not (cell_masks[r][c] & (1 << (v - 1))):
                        ok = False
                        break
                if ok:
                    new.append(p)
            if not new:
                return None, None
            if len(new) != len(old):
                row_domains[r] = new
                changed = True
        return row_domains, changed

    def clue_prefix_bounds(seq, clue_front):
        # For a partial sequence with zeros as unknowns, return min/max possible visible
        # from the front, using only safe bounds based on current maximum.
        if clue_front == 0:
            return 0, n
        seen = 0
        curmax = 0
        unknown = 0
        for x in seq:
            if x == 0:
                unknown += 1
            elif x > curmax:
                curmax = x
                seen += 1
        # Minimum: current seen (unknowns can be hidden if possible)
        mn = seen
        # Maximum: each unknown could potentially exceed current max at most once each
        mx = seen + unknown
        return mn, mx

    def column_feasible_by_clues_and_uniqueness(col_vals, top_clue, bot_clue):
        # col_vals contains 0 for unknowns.
        assigned = [v for v in col_vals if v != 0]
        if len(set(assigned)) != len(assigned):
            return False

        if top_clue:
            mn, mx = clue_prefix_bounds(col_vals, top_clue)
            if not (mn <= top_clue <= mx):
                return False

        if bot_clue:
            mn, mx = clue_prefix_bounds(list(reversed(col_vals)), bot_clue)
            if not (mn <= bot_clue <= mx):
                return False

        # If complete, exact clue check.
        if 0 not in col_vals:
            if top_clue and visible_count(col_vals) != top_clue:
                return False
            if bot_clue and visible_count(reversed(col_vals)) != bot_clue:
                return False
        return True

    def filter_rows_by_column_constraints(row_domains):
        changed = False
        # For each row, each candidate must have support against all column constraints.
        for r in range(n):
            old = row_domains[r]
            new = []
            for p in old:
                ok = True
                for c in range(n):
                    test_col = []
                    for rr in range(n):
                        if rr == r:
                            test_col.append(p[c])
                        else:
                            vals = {q[c] for q in row_domains[rr]}
                            if len(vals) == 1:
                                test_col.append(next(iter(vals)))
                            else:
                                test_col.append(0)
                    if not column_feasible_by_clues_and_uniqueness(test_col, U[c], D[c]):
                        ok = False
                        break
                if ok:
                    new.append(p)
            if not new:
                return None, None
            if len(new) != len(old):
                row_domains[r] = new
                changed = True
        return row_domains, changed

    def enforce_column_value_support(row_domains):
        # For each cell, remove row candidates whose value has no support in column due to
        # Latin uniqueness and column clue-compatible completions.
        changed = False
        cell_masks = recompute_cell_masks(row_domains)
        if cell_masks is None:
            return None, None

        for c in range(n):
            col_domains = [set() for _ in range(n)]
            for r in range(n):
                col_domains[r] = {p[c] for p in row_domains[r]}

            # Hall-style singleton propagation within a column.
            progress = True
            while progress:
                progress = False
                fixed = {next(iter(s)) for s in col_domains if len(s) == 1}
                for r in range(n):
                    if len(col_domains[r]) > 1:
                        ns = col_domains[r] - fixed
                        if not ns:
                            return None, None
                        if ns != col_domains[r]:
                            col_domains[r] = ns
                            progress = True

            # Remove unsupported row candidates.
            for r in range(n):
                allowed = col_domains[r]
                old = row_domains[r]
                new = [p for p in old if p[c] in allowed]
                if not new:
                    return None, None
                if len(new) != len(old):
                    row_domains[r] = new
                    changed = True

        return row_domains, changed

    def propagate(row_domains):
        while True:
            any_change = False

            cell_masks = recompute_cell_masks(row_domains)
            if cell_masks is None:
                return None

            # Column uniqueness: if a value can appear in only one place in a column, force it there.
            for c in range(n):
                for v in range(1, n + 1):
                    bit = 1 << (v - 1)
                    rows_possible = [r for r in range(n) if cell_masks[r][c] & bit]
                    if not rows_possible:
                        return None
                    if len(rows_possible) == 1:
                        r = rows_possible[0]
                        if cell_masks[r][c] != bit:
                            cell_masks[r][c] = bit
                            any_change = True

            # Row filtering by updated cell masks.
            out = filter_rows_by_cell_masks(row_domains, cell_masks)
            if out[0] is None:
                return None
            row_domains, changed = out
            any_change |= changed

            # Enforce column support / uniqueness.
            out = enforce_column_value_support(row_domains)
            if out[0] is None:
                return None
            row_domains, changed = out
            any_change |= changed

            # Lightweight clue-based filtering.
            out = filter_rows_by_column_constraints(row_domains)
            if out[0] is None:
                return None
            row_domains, changed = out
            any_change |= changed

            # Validate exact-complete columns where possible.
            cell_masks = recompute_cell_masks(row_domains)
            if cell_masks is None:
                return None
            for c in range(n):
                col_vals = []
                for r in range(n):
                    vals = values_from_mask(cell_masks[r][c], n)
                    if len(vals) == 1:
                        col_vals.append(vals[0])
                    else:
                        col_vals.append(0)
                if not column_feasible_by_clues_and_uniqueness(col_vals, U[c], D[c]):
                    return None

            if not any_change:
                return row_domains

    def is_solved(row_domains):
        return all(len(d) == 1 for d in row_domains)

    def extract_grid(row_domains):
        return [list(d[0]) for d in row_domains]

    def final_check(grid):
        nums = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != nums:
                return False
            if L[r] and visible_count(grid[r]) != L[r]:
                return False
            if R[r] and visible_count(reversed(grid[r])) != R[r]:
                return False
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != nums:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(reversed(col)) != D[c]:
                return False
        return True

    def choose_branch_row(row_domains):
        best_r = None
        best_score = None
        for r, d in enumerate(row_domains):
            if 1 < len(d):
                # Prefer smallest domain; tie-break by positional diversity.
                diversity = sum(len({p[c] for p in d}) for c in range(n))
                score = (len(d), diversity)
                if best_score is None or score < best_score:
                    best_score = score
                    best_r = r
        return best_r

    def order_candidates(row_domains, r):
        # Least-conflicting candidate first using column frequencies.
        freqs = [{ } for _ in range(n)]
        for c in range(n):
            f = {}
            for rr in range(n):
                if rr == r:
                    continue
                for p in row_domains[rr]:
                    f[p[c]] = f.get(p[c], 0) + 1
            freqs[c] = f

        scored = []
        for p in row_domains[r]:
            score = 0
            for c, v in enumerate(p):
                score += freqs[c].get(v, 0)
            scored.append((score, p))
        scored.sort()
        return [p for _, p in scored]

    def search(row_domains):
        row_domains = [list(d) for d in row_domains]
        row_domains = propagate(row_domains)
        if row_domains is None:
            return None
        if is_solved(row_domains):
            grid = extract_grid(row_domains)
            return grid if final_check(grid) else None

        r = choose_branch_row(row_domains)
        for cand in order_candidates(row_domains, r):
            new_domains = [list(d) for d in row_domains]
            new_domains[r] = [cand]
            ans = search(new_domains)
            if ans is not None:
                return ans
        return None

    grid = search(row_domains)
    return str(grid) if grid is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [2, None, 4, None, None, 2], 'D': [None, 4, 3, None, 1, None], 'L': [None, None, 4, None, 2, 3], 'R': [3, 4, None, 3, None, None]}

from itertools import permutations

# General Skyscrapers solver with strong propagation plus bounded backtracking.
# The image was parsed into OBSERVATION above. Missing clues are represented by None.

def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c

def clue_ok_prefix(prefix, clue, n):
    if clue is None:
        return True
    seen = visible_count(prefix)
    if seen > clue:
        return False
    # Even with all remaining cells, visibility cannot exceed this upper bound.
    rem = n - len(prefix)
    if seen + rem < clue:
        return False
    return True

def line_satisfies_clues(line, left, right):
    if left is not None and visible_count(line) != left:
        return False
    if right is not None and visible_count(line[::-1]) != right:
        return False
    return True

def line_possible_with_prefix_and_mask(prefix, used_mask, n, left, right):
    rem_vals = [v for v in range(1, n + 1) if not (used_mask >> (v - 1)) & 1]
    if len(rem_vals) != n - len(prefix):
        return False
    if not clue_ok_prefix(prefix, left, n):
        return False
    # Small residual permutation check; acceptable because used only for pruning.
    for tail in permutations(rem_vals):
        line = prefix + list(tail)
        if line_satisfies_clues(line, left, right):
            return True
    return False

def generate_line_candidates(n, left, right):
    vals = list(range(1, n + 1))
    out = []
    for p in permutations(vals):
        if line_satisfies_clues(p, left, right):
            out.append(tuple(p))
    return out

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    # Candidate rows filtered by row clues.
    row_cands = [generate_line_candidates(n, L[r], R[r]) for r in range(n)]
    if any(not c for c in row_cands):
        return "No Solution"

    all_mask = (1 << n) - 1

    # Column domains as bitmasks per cell.
    cell_masks = [[all_mask for _ in range(n)] for _ in range(n)]

    def recompute_cell_masks_from_rows():
        changed = False
        for r in range(n):
            cands = row_cands[r]
            for c in range(n):
                mask = 0
                for row in cands:
                    mask |= 1 << (row[c] - 1)
                if mask != cell_masks[r][c]:
                    cell_masks[r][c] = mask
                    changed = True
                if mask == 0:
                    return None
        return changed

    def filter_rows_by_cells():
        changed = False
        for r in range(n):
            new = []
            for row in row_cands[r]:
                ok = True
                for c, v in enumerate(row):
                    if not (cell_masks[r][c] >> (v - 1)) & 1:
                        ok = False
                        break
                if ok:
                    new.append(row)
            if not new:
                return None
            if len(new) != len(row_cands[r]):
                row_cands[r] = new
                changed = True
        return changed

    def filter_by_column_uniqueness():
        changed = False
        # Hall-like support checks from row candidates per column.
        for c in range(n):
            # For each value, determine which rows can place it at column c.
            supports = {v: [] for v in range(1, n + 1)}
            for r in range(n):
                vals_here = set(row[c] for row in row_cands[r])
                for v in vals_here:
                    supports[v].append(r)
            for v in range(1, n + 1):
                rows = supports[v]
                if not rows:
                    return None
                if len(rows) == 1:
                    rr = rows[0]
                    m = 1 << (v - 1)
                    if cell_masks[rr][c] != m:
                        cell_masks[rr][c] &= m
                        if cell_masks[rr][c] == 0:
                            return None
                        changed = True

            # If a row has only one possible value in this column, remove that value from others.
            singles = []
            for r in range(n):
                m = cell_masks[r][c]
                if m and (m & (m - 1)) == 0:
                    singles.append((r, m))
            for r_single, m in singles:
                for r in range(n):
                    if r != r_single and (cell_masks[r][c] & m):
                        cell_masks[r][c] &= ~m
                        if cell_masks[r][c] == 0:
                            return None
                        changed = True
        return changed

    def filter_by_column_clues():
        changed = False
        for c in range(n):
            top = U[c]
            bot = D[c]
            # Candidate values per row for this column.
            col_sets = [set() for _ in range(n)]
            for r in range(n):
                for row in row_cands[r]:
                    col_sets[r].add(row[c])

            # Build all feasible column tuples consistent with current row-candidates and clue.
            feasible_tuples = []
            def bt(r, used_mask, prefix):
                if r == n:
                    if line_satisfies_clues(prefix, top, bot):
                        feasible_tuples.append(tuple(prefix))
                    return
                # Prefix pruning for top clue
                if not clue_ok_prefix(prefix, top, n):
                    return
                for v in sorted(col_sets[r]):
                    bit = 1 << (v - 1)
                    if used_mask & bit:
                        continue
                    prefix.append(v)
                    # Remaining feasibility by clues.
                    if line_possible_with_prefix_and_mask(prefix, used_mask | bit, n, top, bot):
                        bt(r + 1, used_mask | bit, prefix)
                    prefix.pop()

            bt(0, 0, [])
            if not feasible_tuples:
                return None

            allowed_per_row = [0] * n
            for tup in feasible_tuples:
                for r, v in enumerate(tup):
                    allowed_per_row[r] |= 1 << (v - 1)

            for r in range(n):
                new_mask = cell_masks[r][c] & allowed_per_row[r]
                if new_mask == 0:
                    return None
                if new_mask != cell_masks[r][c]:
                    cell_masks[r][c] = new_mask
                    changed = True

            # Also prune row candidates with the refined column allowance.
            for r in range(n):
                before = len(row_cands[r])
                row_cands[r] = [row for row in row_cands[r] if (cell_masks[r][c] >> (row[c] - 1)) & 1]
                if not row_cands[r]:
                    return None
                if len(row_cands[r]) != before:
                    changed = True
        return changed

    def propagate():
        # Repeatedly tighten row candidates, cell masks, and column clue consistency.
        while True:
            any_change = False

            res = recompute_cell_masks_from_rows()
            if res is None:
                return False
            any_change |= res

            res = filter_by_column_uniqueness()
            if res is None:
                return False
            any_change |= res

            res = filter_rows_by_cells()
            if res is None:
                return False
            any_change |= res

            res = filter_by_column_clues()
            if res is None:
                return False
            any_change |= res

            res = recompute_cell_masks_from_rows()
            if res is None:
                return False
            any_change |= res

            res = filter_rows_by_cells()
            if res is None:
                return False
            any_change |= res

            if not any_change:
                return True

    def is_solved():
        return all(len(cands) == 1 for cands in row_cands)

    def final_grid_if_valid():
        grid = [list(row_cands[r][0]) for r in range(n)]
        want = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != want:
                return None
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != want:
                return None
            if not line_satisfies_clues(col, U[c], D[c]):
                return None
        for r in range(n):
            if not line_satisfies_clues(grid[r], L[r], R[r]):
                return None
        return grid

    def snapshot():
        return (
            [list(c) for c in row_cands],
            [row[:] for row in cell_masks],
        )

    def restore(state):
        rc, cm = state
        for i in range(n):
            row_cands[i] = rc[i]
            cell_masks[i] = cm[i]

    def choose_branch():
        # Human-like choice: the most constrained row first.
        best = None
        for r in range(n):
            k = len(row_cands[r])
            if k > 1 and (best is None or k < best[0]):
                best = (k, r)
        return None if best is None else best[1]

    def dfs():
        if not propagate():
            return None
        if is_solved():
            return final_grid_if_valid()

        r = choose_branch()
        if r is None:
            return final_grid_if_valid()

        # Prefer candidates that are rarer in columns to maximize pruning.
        scored = []
        for row in row_cands[r]:
            score = 0
            for c, v in enumerate(row):
                freq = 0
                for rr in range(n):
                    for cand in row_cands[rr]:
                        if cand[c] == v:
                            freq += 1
                score += freq
            scored.append((score, row))
        scored.sort()

        saved = snapshot()
        original = row_cands[r]
        for _, guess in scored:
            restore(saved)
            row_cands[r] = [guess]
            ans = dfs()
            if ans is not None:
                return ans
        restore(saved)
        row_cands[r] = original
        return None

    ans = dfs()
    return str(ans) if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, 6, None], [None, None, None, None, 5], [None, 7, None, None, None]]}

from collections import deque
from copy import deepcopy

WHITE = 1
BLACK = 0
UNKNOWN = -1


def solve(observation):
    data = observation['data']
    n = len(data)
    clues = {}
    clue_cells = set()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                clue_cells.add((r, c))

    lines = {}
    cell_to_lines = {}
    for (r, c), val in clues.items():
        arms = []
        left = [(r, x) for x in range(c - 1, -1, -1)]
        right = [(r, x) for x in range(c + 1, n)]
        up = [(x, c) for x in range(r - 1, -1, -1)]
        down = [(x, c) for x in range(r + 1, n)]
        arms = [left, right, up, down]
        lines[(r, c)] = arms
        for arm_idx, arm in enumerate(arms):
            for pos_idx, cell in enumerate(arm):
                cell_to_lines.setdefault(cell, []).append(((r, c), arm_idx, pos_idx))

    neighbors = {}
    for r in range(n):
        for c in range(n):
            adj = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    adj.append((rr, cc))
            neighbors[(r, c)] = adj

    all_cells = [(r, c) for r in range(n) for c in range(n)]

    def new_state():
        grid = [[UNKNOWN] * n for _ in range(n)]
        for r, c in clue_cells:
            grid[r][c] = WHITE
        return grid

    def get_cell(grid, cell):
        return grid[cell[0]][cell[1]]

    def set_cell(grid, cell, value, queue):
        r, c = cell
        cur = grid[r][c]
        if cur == value:
            return True
        if cur != UNKNOWN and cur != value:
            return False
        if value == BLACK and cell in clue_cells:
            return False
        grid[r][c] = value
        queue.append(cell)
        return True

    def clue_line_bounds(grid, clue):
        r, c = clue
        total_min = 1
        total_max = 1
        arm_info = []
        for arm in lines[clue]:
            minv = 0
            maxv = 0
            blocked = False
            unknown_prefix = 0
            first_black_idx = None
            for i, cell in enumerate(arm):
                v = get_cell(grid, cell)
                if blocked:
                    break
                if v == BLACK:
                    blocked = True
                    first_black_idx = i
                    break
                elif v == WHITE:
                    minv += 1
                    maxv += 1
                else:
                    unknown_prefix += 1
                    maxv += 1
            total_min += minv
            total_max += maxv
            arm_info.append((minv, maxv, unknown_prefix, first_black_idx))
        return total_min, total_max, arm_info

    def forced_by_clue(grid, clue, queue):
        target = clues[clue]
        lo, hi, _ = clue_line_bounds(grid, clue)
        if target < lo or target > hi:
            return False
        if lo == hi:
            return True

        arms = lines[clue]
        for arm in arms:
            # If current maximum already equals target, every visible unknown prefix must be white? no.
            pass

        total_min, total_max, arm_info = clue_line_bounds(grid, clue)

        for arm_idx, arm in enumerate(arms):
            others_min = total_min - 1 - arm_info[arm_idx][0]
            others_max = total_max - 1 - arm_info[arm_idx][1]
            needed_here_min = target - 1 - others_max
            allowed_here_max = target - 1 - others_min

            prefix = []
            for cell in arm:
                v = get_cell(grid, cell)
                if v == BLACK:
                    break
                prefix.append((cell, v))

            if needed_here_min > len(prefix) or allowed_here_max < 0:
                return False

            needed_here_min = max(0, needed_here_min)
            allowed_here_max = min(len(prefix), allowed_here_max)
            if needed_here_min > allowed_here_max:
                return False

            # First needed_here_min cells must be white
            for i in range(needed_here_min):
                cell, _ = prefix[i]
                if not set_cell(grid, cell, WHITE, queue):
                    return False

            # Cell right after allowed_here_max visible whites must be black if exists and not already stopped
            if allowed_here_max < len(arm):
                # To limit visible cells to at most allowed_here_max, the next cell after that many visibles
                # must be black if all prior are not black.
                all_prev_nonblack = True
                for i in range(allowed_here_max):
                    if get_cell(grid, arm[i]) == BLACK:
                        all_prev_nonblack = False
                        break
                if all_prev_nonblack:
                    next_cell = arm[allowed_here_max]
                    if get_cell(grid, next_cell) != BLACK:
                        if not set_cell(grid, next_cell, BLACK, queue):
                            return False

            # If exactly allowed_here_max == needed_here_min, stronger closure
            if needed_here_min == allowed_here_max:
                for i in range(needed_here_min):
                    cell = arm[i]
                    if not set_cell(grid, cell, WHITE, queue):
                        return False
                if needed_here_min < len(arm):
                    # If all prior visible cells are white, next is black
                    ok_prefix = True
                    for i in range(needed_here_min):
                        if get_cell(grid, arm[i]) == BLACK:
                            ok_prefix = False
                            break
                    if ok_prefix:
                        if not set_cell(grid, arm[needed_here_min], BLACK, queue):
                            return False

        return True

    def enforce_black_adjacency(grid, changed_cell, queue):
        if get_cell(grid, changed_cell) == BLACK:
            for nb in neighbors[changed_cell]:
                if not set_cell(grid, nb, WHITE, queue):
                    return False
        elif get_cell(grid, changed_cell) == UNKNOWN:
            return True
        else:
            # If a cell has black neighbors on two sides not relevant; no direct rule.
            pass
        return True

    def enforce_local_black_forcing(grid, changed_cell, queue):
        # If an unknown cell has a black neighbor, that's already white by adjacency.
        # If white cell would disconnect clue visibility impossible, handled elsewhere.
        return True

    def connectivity_checks(grid):
        white_cells = []
        unknown_cells = []
        for cell in all_cells:
            v = get_cell(grid, cell)
            if v == WHITE:
                white_cells.append(cell)
            elif v == UNKNOWN:
                unknown_cells.append(cell)

        if not white_cells:
            return True

        # Necessary condition: all known whites must be connected through white/unknown cells.
        allowed = set(white_cells) | set(unknown_cells)
        start = white_cells[0]
        q = deque([start])
        seen = {start}
        while q:
            cur = q.popleft()
            for nb in neighbors[cur]:
                if nb in allowed and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        for w in white_cells:
            if w not in seen:
                return False

        # If all decided, whites must be connected directly.
        if not unknown_cells:
            q = deque([start])
            seen = {start}
            white_set = set(white_cells)
            while q:
                cur = q.popleft()
                for nb in neighbors[cur]:
                    if nb in white_set and nb not in seen:
                        seen.add(nb)
                        q.append(nb)
            return len(seen) == len(white_cells)
        return True

    def propagate(grid):
        queue = deque(clue_cells)
        for cell in all_cells:
            if get_cell(grid, cell) != UNKNOWN:
                queue.append(cell)

        in_queue = set(queue)

        while queue:
            cell = queue.popleft()
            in_queue.discard(cell)

            if not enforce_black_adjacency(grid, cell, queue):
                return False
            if not enforce_local_black_forcing(grid, cell, queue):
                return False

            # clue checks impacted by this cell
            impacted = set()
            if cell in clues:
                impacted.add(cell)
            for item in cell_to_lines.get(cell, []):
                impacted.add(item[0])

            # also neighboring clue rows/cols may be affected by forced adjacency
            for clue in impacted:
                if not forced_by_clue(grid, clue, queue):
                    return False

            if not connectivity_checks(grid):
                return False

            # Keep queue unique-ish
            if queue:
                seen_local = set()
                newq = deque()
                while queue:
                    x = queue.popleft()
                    if x not in seen_local:
                        seen_local.add(x)
                        newq.append(x)
                queue = newq

        # Global clue consistency
        for clue in clues:
            lo, hi, _ = clue_line_bounds(grid, clue)
            target = clues[clue]
            if target < lo or target > hi:
                return False

        if not connectivity_checks(grid):
            return False

        return True

    def is_solved(grid):
        for cell in all_cells:
            if get_cell(grid, cell) == UNKNOWN:
                return False
        if not connectivity_checks(grid):
            return False
        for clue, target in clues.items():
            cnt = 1
            r, c = clue
            for arm in lines[clue]:
                for cell in arm:
                    v = get_cell(grid, cell)
                    if v == BLACK:
                        break
                    if v != WHITE:
                        return False
                    cnt += 1
            if cnt != target:
                return False
        for cell in all_cells:
            if get_cell(grid, cell) == BLACK:
                for nb in neighbors[cell]:
                    if get_cell(grid, nb) == BLACK:
                        return False
        return True

    def score_cell(grid, cell):
        # Human-like choice: pick a cell participating in many clues / near constraints
        score = 0
        if cell in clue_cells:
            return -1
        score += 5 * len(cell_to_lines.get(cell, []))
        for nb in neighbors[cell]:
            if get_cell(grid, nb) == BLACK:
                score += 10
            elif get_cell(grid, nb) == WHITE:
                score += 1
            if nb in clue_cells:
                score += 4
        return score

    def choose_branch_cell(grid):
        best = None
        best_score = -1
        for cell in all_cells:
            if get_cell(grid, cell) == UNKNOWN:
                s = score_cell(grid, cell)
                if s > best_score:
                    best_score = s
                    best = cell
        return best

    def branch_order(grid, cell):
        # Prefer white first for connectivity, unless black is strongly suggested
        black_pressure = 0
        white_pressure = 0
        for nb in neighbors[cell]:
            v = get_cell(grid, nb)
            if v == BLACK:
                white_pressure += 5
            if v == WHITE:
                white_pressure += 1
            if nb in clue_cells:
                white_pressure += 2
        for clue, arm_idx, pos_idx in cell_to_lines.get(cell, []):
            target = clues[clue]
            lo, hi, _ = clue_line_bounds(grid, clue)
            if hi > target:
                black_pressure += 1
            if lo < target:
                white_pressure += 1
        if black_pressure > white_pressure:
            return [BLACK, WHITE]
        return [WHITE, BLACK]

    def search(grid):
        if not propagate(grid):
            return None
        if is_solved(grid):
            return grid

        cell = choose_branch_cell(grid)
        if cell is None:
            return None

        for value in branch_order(grid, cell):
            new_grid = deepcopy(grid)
            q = deque()
            if not set_cell(new_grid, cell, value, q):
                continue
            result = search(new_grid)
            if result is not None:
                return result
        return None

    grid = new_state()
    result = search(grid)
    if result is None:
        return "No Solution"

    answer = []
    for r in range(n):
        row = []
        for c in range(n):
            if (r, c) in clues:
                row.append(clues[(r, c)])
            else:
                row.append('B' if result[r][c] == BLACK else None)
        answer.append(row)
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 2, 4, 2, 3], 'D': [2, 2, 1, 4, 3], 'L': [1, 3, 3, 2, 2], 'R': [4, 2, 1, 3, 2]}

from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    all_vals_mask = (1 << n) - 1
    full_set = tuple(range(1, n + 1))

    # Precompute all row permutations compatible with left/right clues.
    perms = list(permutations(full_set))
    row_candidates = []
    for r in range(n):
        lc = L[r]
        rc = R[r]
        cand = []
        for p in perms:
            if lc and visible_count(p) != lc:
                continue
            if rc and visible_count(p[::-1]) != rc:
                continue
            cand.append(p)
        if not cand:
            return "No Solution"
        row_candidates.append(cand)

    # Initial cell domains from row candidates.
    domains = [[all_vals_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            mask = 0
            for p in row_candidates[r]:
                mask |= 1 << (p[c] - 1)
            domains[r][c] = mask

    def bit_count(x):
        return x.bit_count()

    def iter_mask(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def mask_to_values(mask):
        return [v for v in iter_mask(mask)]

    def singleton_value(mask):
        return mask.bit_length()

    def filter_row_candidates_by_domains(row_cands, row_domains):
        out = []
        for p in row_cands:
            ok = True
            for c, v in enumerate(p):
                if not (row_domains[c] >> (v - 1)) & 1:
                    ok = False
                    break
            if ok:
                out.append(p)
        return out

    def column_top_prefix_possible(seq, clue):
        if clue == 0:
            return True
        vis = 0
        m = 0
        for x in seq:
            if x > m:
                m = x
                vis += 1
        remaining = n - len(seq)
        # At most one new visible per remaining position.
        if vis > clue:
            return False
        if vis + remaining < clue:
            return False
        return True

    def column_bottom_prefix_possible(seq, clue):
        if clue == 0:
            return True
        return column_top_prefix_possible(seq[::-1], clue)

    def exact_column_clue_ok(col_vals, top_clue, bottom_clue):
        if top_clue and visible_count(col_vals) != top_clue:
            return False
        if bottom_clue and visible_count(col_vals[::-1]) != bottom_clue:
            return False
        return True

    def refine(domains, row_candidates):
        changed = True
        while changed:
            changed = False

            # Filter row candidates against current domains.
            for r in range(n):
                new_cands = filter_row_candidates_by_domains(row_candidates[r], domains[r])
                if not new_cands:
                    return False
                if len(new_cands) != len(row_candidates[r]):
                    row_candidates[r] = new_cands
                    changed = True

                for c in range(n):
                    mask = 0
                    for p in row_candidates[r]:
                        mask |= 1 << (p[c] - 1)
                    new_mask = domains[r][c] & mask
                    if new_mask == 0:
                        return False
                    if new_mask != domains[r][c]:
                        domains[r][c] = new_mask
                        changed = True

            # Latin constraints on rows: every value must appear somewhere in the row.
            for r in range(n):
                for v in range(1, n + 1):
                    positions = []
                    bit = 1 << (v - 1)
                    for c in range(n):
                        if domains[r][c] & bit:
                            positions.append(c)
                    if not positions:
                        return False
                    if len(positions) == 1:
                        c = positions[0]
                        if domains[r][c] != bit:
                            domains[r][c] = bit
                            changed = True

            # Latin constraints on columns.
            for c in range(n):
                for v in range(1, n + 1):
                    positions = []
                    bit = 1 << (v - 1)
                    for r in range(n):
                        if domains[r][c] & bit:
                            positions.append(r)
                    if not positions:
                        return False
                    if len(positions) == 1:
                        r = positions[0]
                        if domains[r][c] != bit:
                            domains[r][c] = bit
                            changed = True

            # If a row cell is fixed to v, remove v from other cells in row.
            for r in range(n):
                fixed_bits = []
                for c in range(n):
                    if bit_count(domains[r][c]) == 1:
                        fixed_bits.append((c, domains[r][c]))
                for c0, bit in fixed_bits:
                    for c in range(n):
                        if c != c0 and (domains[r][c] & bit):
                            new_mask = domains[r][c] & ~bit
                            if new_mask == 0:
                                return False
                            if new_mask != domains[r][c]:
                                domains[r][c] = new_mask
                                changed = True

            # If a column cell is fixed to v, remove v from other cells in column.
            for c in range(n):
                fixed_bits = []
                for r in range(n):
                    if bit_count(domains[r][c]) == 1:
                        fixed_bits.append((r, domains[r][c]))
                for r0, bit in fixed_bits:
                    for r in range(n):
                        if r != r0 and (domains[r][c] & bit):
                            new_mask = domains[r][c] & ~bit
                            if new_mask == 0:
                                return False
                            if new_mask != domains[r][c]:
                                domains[r][c] = new_mask
                                changed = True

            # Column clue propagation using current domains.
            for c in range(n):
                top_clue = U[c]
                bottom_clue = D[c]

                # Build quick sets for each row in this column.
                col_masks = [domains[r][c] for r in range(n)]

                # Forward/backward feasibility checks for each candidate value per cell via small DFS.
                memo = {}

                def col_feasible(pos, used_mask, prefix_vals):
                    key = (pos, used_mask, prefix_vals)
                    if key in memo:
                        return memo[key]
                    if not column_top_prefix_possible(prefix_vals, top_clue):
                        memo[key] = False
                        return False
                    if pos == n:
                        ok = exact_column_clue_ok(prefix_vals, top_clue, bottom_clue)
                        memo[key] = ok
                        return ok
                    avail = col_masks[pos] & ~used_mask
                    while avail:
                        b = avail & -avail
                        v = b.bit_length()
                        if col_feasible(pos + 1, used_mask | b, prefix_vals + (v,)):
                            memo[key] = True
                            return True
                        avail ^= b
                    memo[key] = False
                    return False

                if not col_feasible(0, 0, ()):
                    return False

                for r in range(n):
                    keep = 0
                    mask = domains[r][c]
                    for v in mask_to_values(mask):
                        b = 1 << (v - 1)

                        memo2 = {}

                        def col_feasible_forced(pos, used_mask, prefix_vals):
                            key = (pos, used_mask, prefix_vals)
                            if key in memo2:
                                return memo2[key]
                            if not column_top_prefix_possible(prefix_vals, top_clue):
                                memo2[key] = False
                                return False
                            if pos == n:
                                ok = exact_column_clue_ok(prefix_vals, top_clue, bottom_clue)
                                memo2[key] = ok
                                return ok
                            avail = col_masks[pos] & ~used_mask
                            if pos == r:
                                avail &= b
                            while avail:
                                bb = avail & -avail
                                vv = bb.bit_length()
                                if col_feasible_forced(pos + 1, used_mask | bb, prefix_vals + (vv,)):
                                    memo2[key] = True
                                    return True
                                avail ^= bb
                            memo2[key] = False
                            return False

                        if col_feasible_forced(0, 0, ()):
                            keep |= b

                    if keep == 0:
                        return False
                    if keep != domains[r][c]:
                        domains[r][c] = keep
                        changed = True

        return True

    def is_solved(domains):
        for r in range(n):
            for c in range(n):
                if bit_count(domains[r][c]) != 1:
                    return False
        return True

    def build_grid(domains):
        return [[singleton_value(domains[r][c]) for c in range(n)] for r in range(n)]

    def validate_grid(grid):
        target = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != target:
                return False
            if L[r] and visible_count(grid[r]) != L[r]:
                return False
            if R[r] and visible_count(grid[r][::-1]) != R[r]:
                return False
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != target:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(col[::-1]) != D[c]:
                return False
        return True

    def search(domains, row_candidates):
        if not refine(domains, row_candidates):
            return None

        if is_solved(domains):
            grid = build_grid(domains)
            return grid if validate_grid(grid) else None

        # Human-like branching: choose the most constrained unresolved row first,
        # preferring rows with few candidate permutations.
        best_row = None
        best_len = 10**9
        for r in range(n):
            if any(bit_count(domains[r][c]) != 1 for c in range(n)):
                rc = filter_row_candidates_by_domains(row_candidates[r], domains[r])
                m = len(rc)
                if m < best_len:
                    best_len = m
                    best_row = r

        if best_row is not None and best_len <= 6:
            rcands = filter_row_candidates_by_domains(row_candidates[best_row], domains[best_row])
            # Try most restrictive rows by full row placement.
            for p in rcands:
                new_domains = [row[:] for row in domains]
                new_row_candidates = [lst[:] for lst in row_candidates]
                ok = True
                for c, v in enumerate(p):
                    b = 1 << (v - 1)
                    if not (new_domains[best_row][c] & b):
                        ok = False
                        break
                    new_domains[best_row][c] = b
                if ok:
                    new_row_candidates[best_row] = [p]
                    ans = search(new_domains, new_row_candidates)
                    if ans is not None:
                        return ans

        # Otherwise branch on most constrained cell.
        br = bc = None
        best_count = 10**9
        for r in range(n):
            for c in range(n):
                cnt = bit_count(domains[r][c])
                if 1 < cnt < best_count:
                    best_count = cnt
                    br, bc = r, c

        if br is None:
            return None

        for v in mask_to_values(domains[br][bc]):
            new_domains = [row[:] for row in domains]
            new_row_candidates = [lst[:] for lst in row_candidates]
            new_domains[br][bc] = 1 << (v - 1)
            ans = search(new_domains, new_row_candidates)
            if ans is not None:
                return ans

        return None

    result = search(domains, [lst[:] for lst in row_candidates])
    return str(result) if result is not None else "No Solution"


