    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 4, 3, 1, 5], [4, 3, 5, 3, 1], [5, 2, 5, 4, 3], [3, 3, 4, 1, 2], [4, 5, 2, 3, 4]]}

# Hitori solver with strong propagation:
# - duplicate reasoning on rows/cols
# - black adjacency forcing neighbors white
# - connectivity/articulation style forcing to avoid white disconnection
# - branch on most constrained duplicate cell only when logic stalls

from collections import defaultdict, deque
import ast

BLACK = 1
WHITE = 0
UNKNOWN = -1


def solve(observation):
    board = observation["data"]
    n = len(board)
    solver = HitoriSolver(board)
    res = solver.run()
    if res is None:
        return "No Solution"
    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if res[r][c] == BLACK else None)
        out.append(row)
    return str(out)


class HitoriSolver:
    def __init__(self, board):
        self.board = board
        self.n = len(board)
        self.N = self.n * self.n
        self.state = [UNKNOWN] * self.N
        self.nei = [[] for _ in range(self.N)]
        self.row_groups = []
        self.col_groups = []
        self.groups_of_cell = [[] for _ in range(self.N)]
        self.dup_cells = set()

        for r in range(self.n):
            for c in range(self.n):
                i = self.idx(r, c)
                if r > 0:
                    self.nei[i].append(self.idx(r - 1, c))
                if r + 1 < self.n:
                    self.nei[i].append(self.idx(r + 1, c))
                if c > 0:
                    self.nei[i].append(self.idx(r, c - 1))
                if c + 1 < self.n:
                    self.nei[i].append(self.idx(r, c + 1))

        self._build_groups()

    def idx(self, r, c):
        return r * self.n + c

    def rc(self, i):
        return divmod(i, self.n)

    def _build_groups(self):
        gid = 0
        for r in range(self.n):
            mp = defaultdict(list)
            for c in range(self.n):
                mp[self.board[r][c]].append(self.idx(r, c))
            for cells in mp.values():
                if len(cells) >= 2:
                    self.row_groups.append((gid, tuple(cells)))
                    for i in cells:
                        self.groups_of_cell[i].append(("row", gid, tuple(cells)))
                        self.dup_cells.add(i)
                    gid += 1

        gid = 0
        for c in range(self.n):
            mp = defaultdict(list)
            for r in range(self.n):
                mp[self.board[r][c]].append(self.idx(r, c))
            for cells in mp.values():
                if len(cells) >= 2:
                    self.col_groups.append((gid, tuple(cells)))
                    for i in cells:
                        self.groups_of_cell[i].append(("col", gid, tuple(cells)))
                        self.dup_cells.add(i)
                    gid += 1

    def clone_state(self, state):
        return state[:]

    def assign(self, state, i, val, queue):
        cur = state[i]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        state[i] = val
        queue.append(i)
        return True

    def run(self):
        state = self.clone_state(self.state)
        if not self.propagate(state):
            return None
        return self.search(state)

    def propagate(self, state):
        queue = deque([i for i, v in enumerate(state) if v != UNKNOWN])

        # Initial duplicate-based deductions
        if not self.apply_duplicate_rules(state, queue):
            return False

        changed = True
        while changed:
            changed = False

            while queue:
                i = queue.popleft()
                v = state[i]

                if v == BLACK:
                    # black cells cannot touch orthogonally
                    for j in self.nei[i]:
                        if state[j] == BLACK:
                            return False
                        if state[j] == UNKNOWN:
                            state[j] = WHITE
                            queue.append(j)
                            changed = True

                # local duplicate consistency after any assignment
                if not self.apply_local_group_rules(state, i, queue):
                    return False

            # global duplicate rules
            before = tuple(state)
            if not self.apply_duplicate_rules(state, queue):
                return False
            if tuple(state) != before:
                changed = True
                continue

            # connectivity checks and forced whites/blacks from articulation logic
            before = tuple(state)
            if not self.connectivity_prune(state, queue):
                return False
            if tuple(state) != before:
                changed = True
                continue

            # final contradiction scan
            if not self.quick_consistency(state):
                return False

        return True

    def apply_local_group_rules(self, state, i, queue):
        for _, _, cells in self.groups_of_cell[i]:
            if not self.enforce_group(state, cells, queue):
                return False
        return True

    def apply_duplicate_rules(self, state, queue):
        for _, cells in self.row_groups:
            if not self.enforce_group(state, cells, queue):
                return False
            if not self.enforce_line_consecutive(state, cells, queue, line_type="row"):
                return False
        for _, cells in self.col_groups:
            if not self.enforce_group(state, cells, queue):
                return False
            if not self.enforce_line_consecutive(state, cells, queue, line_type="col"):
                return False
        return True

    def enforce_group(self, state, cells, queue):
        white_count = 0
        unknowns = []
        for i in cells:
            if state[i] == WHITE:
                white_count += 1
            elif state[i] == UNKNOWN:
                unknowns.append(i)

        # At most one white in duplicate group
        if white_count > 1:
            return False

        # If one is already white, all others black
        if white_count == 1:
            for i in unknowns:
                if not self.assign(state, i, BLACK, queue):
                    return False
            return True

        # If all but one are black, last one must be white
        black_count = sum(1 for i in cells if state[i] == BLACK)
        if black_count == len(cells):
            return False
        if len(cells) - black_count == 1:
            for i in cells:
                if state[i] != BLACK:
                    if not self.assign(state, i, WHITE, queue):
                        return False
        return True

    def enforce_line_consecutive(self, state, cells, queue, line_type):
        # Human rule: equal numbers adjacent in same row/col cannot both remain white,
        # and black cells cannot touch, so for consecutive duplicates one side often forced.
        if line_type == "row":
            ordered = sorted(cells, key=lambda x: self.rc(x)[1])
        else:
            ordered = sorted(cells, key=lambda x: self.rc(x)[0])

        for a, b in zip(ordered, ordered[1:]):
            ra, ca = self.rc(a)
            rb, cb = self.rc(b)
            if abs(ra - rb) + abs(ca - cb) == 1:
                # adjacent equal cells: at least one black, but not both black
                sa, sb = state[a], state[b]
                if sa == WHITE and sb == WHITE:
                    return False
                if sa == BLACK and sb == BLACK:
                    return False
                if sa == WHITE and sb == UNKNOWN:
                    if not self.assign(state, b, BLACK, queue):
                        return False
                elif sb == WHITE and sa == UNKNOWN:
                    if not self.assign(state, a, BLACK, queue):
                        return False
                elif sa == BLACK and sb == UNKNOWN:
                    if not self.assign(state, b, WHITE, queue):
                        return False
                elif sb == BLACK and sa == UNKNOWN:
                    if not self.assign(state, a, WHITE, queue):
                        return False
        return True

    def quick_consistency(self, state):
        # no adjacent black
        for i, v in enumerate(state):
            if v == BLACK:
                for j in self.nei[i]:
                    if j > i and state[j] == BLACK:
                        return False

        # no duplicate whites in row/col
        n = self.n
        for r in range(n):
            seen = {}
            for c in range(n):
                i = self.idx(r, c)
                if state[i] == WHITE:
                    val = self.board[r][c]
                    if val in seen:
                        return False
                    seen[val] = 1
        for c in range(n):
            seen = {}
            for r in range(n):
                i = self.idx(r, c)
                if state[i] == WHITE:
                    val = self.board[r][c]
                    if val in seen:
                        return False
                    seen[val] = 1

        # white-connectivity possibility: all current whites + unknowns must be connected enough
        if not self.white_possible_connected(state):
            return False
        return True

    def white_possible_connected(self, state):
        allowed = [i for i, v in enumerate(state) if v != BLACK]
        if not allowed:
            return False
        start = None
        for i, v in enumerate(state):
            if v == WHITE:
                start = i
                break
        if start is None:
            start = allowed[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in self.nei[x]:
                if state[y] != BLACK and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(allowed)

    def connectivity_prune(self, state, queue):
        # If fixed whites exist, every non-black cell must be reachable from white region through non-black cells.
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if whites:
            seen = set([whites[0]])
            dq = deque([whites[0]])
            while dq:
                x = dq.popleft()
                for y in self.nei[x]:
                    if state[y] != BLACK and y not in seen:
                        seen.add(y)
                        dq.append(y)
            for i, v in enumerate(state):
                if v != BLACK and i not in seen:
                    return False

        # Unknown articulation forcing:
        # if removing an unknown cell from the graph of non-black cells disconnects fixed white cells/components,
        # that cell must be white.
        candidates = [i for i, v in enumerate(state) if v == UNKNOWN]
        white_set = [i for i, v in enumerate(state) if v == WHITE]

        if white_set:
            for x in candidates:
                if self.is_required_connector(state, x):
                    if not self.assign(state, x, WHITE, queue):
                        return False

        # Unknown that cannot be white due to immediate row/col duplicate with fixed whites or connectivity can be black
        for i in candidates:
            if state[i] != UNKNOWN:
                continue
            if not self.can_be_white(state, i):
                if not self.assign(state, i, BLACK, queue):
                    return False
            elif not self.can_be_black(state, i):
                if not self.assign(state, i, WHITE, queue):
                    return False

        return True

    def is_required_connector(self, state, x):
        # Consider graph of cells not black and not x. If there are at least two white cells/components separated, x must be white.
        whites = [i for i, v in enumerate(state) if v == WHITE and i != x]
        if len(whites) <= 1:
            return False
        start = whites[0]
        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            for nb in self.nei[cur]:
                if nb == x or state[nb] == BLACK or nb in seen:
                    continue
                seen.add(nb)
                dq.append(nb)
        for w in whites[1:]:
            if w not in seen:
                return True
        return False

    def can_be_white(self, state, i):
        # local duplicate conflict with existing whites
        r, c = self.rc(i)
        val = self.board[r][c]
        for cc in range(self.n):
            j = self.idx(r, cc)
            if j != i and state[j] == WHITE and self.board[j // self.n][j % self.n] == val:
                return False
        for rr in range(self.n):
            j = self.idx(rr, c)
            if j != i and state[j] == WHITE and self.board[j // self.n][j % self.n] == val:
                return False

        tmp = state[:]
        tmp[i] = WHITE
        if not self.quick_consistency(tmp):
            return False
        return True

    def can_be_black(self, state, i):
        for j in self.nei[i]:
            if state[j] == BLACK:
                return False
        tmp = state[:]
        tmp[i] = BLACK
        if not self.quick_consistency(tmp):
            return False
        return True

    def search(self, state):
        if all(v != UNKNOWN for v in state):
            if self.quick_consistency(state):
                return state
            return None

        choice = self.choose_branch_cell(state)
        if choice is None:
            return None

        # value ordering: prefer the value with stronger local support / fewer consequences first
        options = []
        wb = self.can_be_white(state, choice)
        bb = self.can_be_black(state, choice)
        if wb:
            options.append(WHITE)
        if bb:
            options.append(BLACK)
        if not options:
            return None

        # Heuristic: if duplicate pressure high, try black first; if connectivity-critical, white first
        if self.is_required_connector(state, choice):
            options.sort(key=lambda x: 0 if x == WHITE else 1)
        else:
            options.sort(key=lambda x: 0 if x == BLACK else 1)

        for val in options:
            new_state = state[:]
            q = deque()
            if not self.assign(new_state, choice, val, q):
                continue
            if self.propagate(new_state):
                res = self.search(new_state)
                if res is not None:
                    return res
        return None

    def choose_branch_cell(self, state):
        # branch on most constrained duplicate cell first
        best = None
        best_score = None
        for i, v in enumerate(state):
            if v != UNKNOWN:
                continue
            score = 0

            # duplicate pressure
            for _, _, cells in self.groups_of_cell[i]:
                white_count = sum(1 for x in cells if state[x] == WHITE)
                black_count = sum(1 for x in cells if state[x] == BLACK)
                unknown_count = sum(1 for x in cells if state[x] == UNKNOWN)
                score += 10
                score += 4 * white_count
                score += 3 * black_count
                score += max(0, 4 - unknown_count)

            # adjacent to black/white
            adj_black = sum(1 for j in self.nei[i] if state[j] == BLACK)
            adj_white = sum(1 for j in self.nei[i] if state[j] == WHITE)
            score += 5 * adj_black + 2 * adj_white

            # connectivity critical
            if self.is_required_connector(state, i):
                score += 50

            # centrality
            r, c = self.rc(i)
            score += min(r, self.n - 1 - r) + min(c, self.n - 1 - c)

            if best_score is None or score > best_score:
                best_score = score
                best = i
        return best


