OBSERVATION = {'data': [[1, 5, 3, 4, 1], [5, 3, 5, 3, 1], [3, 5, 4, 1, 5], [5, 1, 2, 3, 4], [2, 1, 1, 1, 3]]}

from collections import defaultdict, deque

# Hitori solver with human-like deduction plus tightly pruned search.
# Output is an NxN mask using 'B' for black and None for white.

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    board = observation["data"]
    n = len(board)
    m = len(board[0]) if n else 0

    row_groups, col_groups = build_duplicate_groups(board)
    neighbors = build_neighbors(n, m)
    pair_edges, triads, duplicate_cells = build_local_duplicate_structures(board, row_groups, col_groups)

    state = [UNKNOWN] * (n * m)
    res = search(
        board, n, m, state,
        row_groups, col_groups,
        neighbors, pair_edges, triads, duplicate_cells
    )
    if res is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if res[idx(r, c, m)] == BLACK else None)
        out.append(row)
    return str(out)


def idx(r, c, m):
    return r * m + c


def rc(i, m):
    return divmod(i, m)


def build_neighbors(n, m):
    neighbors = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c, m)
            if r > 0:
                neighbors[i].append(idx(r - 1, c, m))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c, m))
            if c > 0:
                neighbors[i].append(idx(r, c - 1, m))
            if c + 1 < m:
                neighbors[i].append(idx(r, c + 1, m))
    return neighbors


def build_duplicate_groups(board):
    n = len(board)
    m = len(board[0])
    row_groups = []
    col_groups = []

    for r in range(n):
        mp = defaultdict(list)
        for c in range(m):
            mp[board[r][c]].append(idx(r, c, m))
        row_groups.append([cells for cells in mp.values() if len(cells) >= 2])

    for c in range(m):
        mp = defaultdict(list)
        for r in range(n):
            mp[board[r][c]].append(idx(r, c, m))
        col_groups.append([cells for cells in mp.values() if len(cells) >= 2])

    return row_groups, col_groups


def build_local_duplicate_structures(board, row_groups, col_groups):
    n = len(board)
    m = len(board[0])
    pair_edges = set()
    triads = []
    duplicate_cells = set()

    # Adjacent equal numbers in row/column: at least one must be black.
    for r in range(n):
        for c in range(m - 1):
            if board[r][c] == board[r][c + 1]:
                a = idx(r, c, m)
                b = idx(r, c + 1, m)
                pair_edges.add((min(a, b), max(a, b)))
                duplicate_cells.add(a)
                duplicate_cells.add(b)

    for c in range(m):
        for r in range(n - 1):
            if board[r][c] == board[r + 1][c]:
                a = idx(r, c, m)
                b = idx(r + 1, c, m)
                pair_edges.add((min(a, b), max(a, b)))
                duplicate_cells.add(a)
                duplicate_cells.add(b)

    # Three consecutive equal numbers in row/column: middle must be white, ends black.
    for r in range(n):
        for c in range(m - 2):
            if board[r][c] == board[r][c + 1] == board[r][c + 2]:
                triads.append((idx(r, c, m), idx(r, c + 1, m), idx(r, c + 2, m)))
                duplicate_cells.update([idx(r, c, m), idx(r, c + 1, m), idx(r, c + 2, m)])

    for c in range(m):
        for r in range(n - 2):
            if board[r][c] == board[r + 1][c] == board[r + 2][c]:
                triads.append((idx(r, c, m), idx(r + 1, c, m), idx(r + 2, c, m)))
                duplicate_cells.update([idx(r, c, m), idx(r + 1, c, m), idx(r + 2, c, m)])

    for groups in row_groups:
        for cells in groups:
            duplicate_cells.update(cells)
    for groups in col_groups:
        for cells in groups:
            duplicate_cells.update(cells)

    return list(pair_edges), triads, duplicate_cells


def assign(state, i, val, queue):
    cur = state[i]
    if cur == val:
        return True
    if cur != UNKNOWN:
        return False
    state[i] = val
    queue.append(i)
    return True


def propagate(board, n, m, state, row_groups, col_groups, neighbors, pair_edges, triads):
    queue = deque()

    for i, v in enumerate(state):
        if v != UNKNOWN:
            queue.append(i)

    changed_global = True
    while changed_global:
        changed_global = False

        # Re-process queue-driven implications until exhausted.
        while queue:
            i = queue.popleft()
            v = state[i]

            if v == BLACK:
                # Black cells cannot touch orthogonally.
                for nb in neighbors[i]:
                    if state[nb] == BLACK:
                        return False
                    if state[nb] == UNKNOWN:
                        if not assign(state, nb, WHITE, queue):
                            return False
                        changed_global = True

            elif v == WHITE:
                # In every duplicate group containing this white cell, all peers must be black.
                r, c = rc(i, m)
                val = board[r][c]

                for group in row_groups[r]:
                    if i in group:
                        for j in group:
                            if j != i:
                                if state[j] == WHITE:
                                    return False
                                if state[j] == UNKNOWN:
                                    if not assign(state, j, BLACK, queue):
                                        return False
                                    changed_global = True

                for group in col_groups[c]:
                    if i in group:
                        for j in group:
                            if j != i:
                                if state[j] == WHITE:
                                    return False
                                if state[j] == UNKNOWN:
                                    if not assign(state[j:j+1] and state, j, BLACK, queue):
                                        return False
                                    changed_global = True

        # Static pattern deductions, applied repeatedly.
        local_change = True
        while local_change:
            local_change = False

            # Adjacent equal pair => at least one black.
            for a, b in pair_edges:
                sa, sb = state[a], state[b]
                if sa == WHITE and sb == WHITE:
                    return False
                if sa == WHITE and sb == UNKNOWN:
                    if not assign(state, b, BLACK, queue):
                        return False
                    local_change = True
                    changed_global = True
                elif sb == WHITE and sa == UNKNOWN:
                    if not assign(state, a, BLACK, queue):
                        return False
                    local_change = True
                    changed_global = True

            # Triple equal in line => B W B.
            for a, b, c in triads:
                if state[b] == BLACK:
                    return False
                if state[b] == UNKNOWN:
                    if not assign(state, b, WHITE, queue):
                        return False
                    local_change = True
                    changed_global = True
                for x in (a, c):
                    if state[x] == WHITE:
                        return False
                    if state[x] == UNKNOWN:
                        if not assign(state, x, BLACK, queue):
                            return False
                        local_change = True
                        changed_global = True

            # Group counting rule:
            # In each duplicate set, if exactly one cell can still be white, force it white.
            for groups in row_groups:
                for group in groups:
                    white_count = 0
                    undec = []
                    for i in group:
                        if state[i] == WHITE:
                            white_count += 1
                        elif state[i] == UNKNOWN:
                            undec.append(i)
                    if white_count >= 2:
                        return False
                    if white_count == 0 and len(undec) == 1:
                        if not assign(state, undec[0], WHITE, queue):
                            return False
                        local_change = True
                        changed_global = True

            for groups in col_groups:
                for group in groups:
                    white_count = 0
                    undec = []
                    for i in group:
                        if state[i] == WHITE:
                            white_count += 1
                        elif state[i] == UNKNOWN:
                            undec.append(i)
                    if white_count >= 2:
                        return False
                    if white_count == 0 and len(undec) == 1:
                        if not assign(state, undec[0], WHITE, queue):
                            return False
                        local_change = True
                        changed_global = True

            # If an unknown cell is adjacent to a black, it tends to be white if black would
            # isolate patterns badly only when all other neighbors black. Strong local no-island:
            for i, s in enumerate(state):
                if s == UNKNOWN:
                    black_adj = 0
                    unk_adj = 0
                    for nb in neighbors[i]:
                        if state[nb] == BLACK:
                            black_adj += 1
                        elif state[nb] == UNKNOWN:
                            unk_adj += 1
                    if black_adj >= 2:
                        if not assign(state, i, WHITE, queue):
                            return False
                        local_change = True
                        changed_global = True

        # Fast consistency checks.
        if not check_group_consistency(state, row_groups, col_groups):
            return False
        if not check_no_adjacent_black(state, neighbors):
            return False
        if not connectivity_possible(state, neighbors):
            return False

    return True


def check_group_consistency(state, row_groups, col_groups):
    for groups in row_groups:
        for group in groups:
            white_count = 0
            unknown_count = 0
            for i in group:
                if state[i] == WHITE:
                    white_count += 1
                elif state[i] == UNKNOWN:
                    unknown_count += 1
            if white_count > 1:
                return False
            if white_count == 0 and unknown_count == 0:
                return False

    for groups in col_groups:
        for group in groups:
            white_count = 0
            unknown_count = 0
            for i in group:
                if state[i] == WHITE:
                    white_count += 1
                elif state[i] == UNKNOWN:
                    unknown_count += 1
            if white_count > 1:
                return False
            if white_count == 0 and unknown_count == 0:
                return False
    return True


def check_no_adjacent_black(state, neighbors):
    for i, s in enumerate(state):
        if s == BLACK:
            for nb in neighbors[i]:
                if nb > i and state[nb] == BLACK:
                    return False
    return True


def connectivity_possible(state, neighbors):
    # All cells not fixed black (white + unknown) must be connected, otherwise impossible.
    nodes = [i for i, s in enumerate(state) if s != BLACK]
    if not nodes:
        return False

    start = None
    for i, s in enumerate(state):
        if s == WHITE:
            start = i
            break
    if start is None:
        start = nodes[0]

    allowed = set(nodes)
    seen = {start}
    dq = deque([start])
    while dq:
        x = dq.popleft()
        for nb in neighbors[x]:
            if nb in allowed and nb not in seen:
                seen.add(nb)
                dq.append(nb)
    return len(seen) == len(allowed)


def final_connected_whites(state, neighbors):
    whites = [i for i, s in enumerate(state) if s == WHITE]
    if not whites:
        return False
    start = whites[0]
    seen = {start}
    dq = deque([start])
    white_set = set(whites)
    while dq:
        x = dq.popleft()
        for nb in neighbors[x]:
            if nb in white_set and nb not in seen:
                seen.add(nb)
                dq.append(nb)
    return len(seen) == len(whites)


def choose_branch_cell(board, n, m, state, row_groups, col_groups, neighbors, duplicate_cells):
    # Human-like heuristic:
    # prioritize cells involved in duplicates, especially those with many duplicate constraints
    # and centrality / adjacency effects.
    best = None
    best_score = -1

    dup_membership = [0] * (n * m)
    for groups in row_groups:
        for g in groups:
            for i in g:
                dup_membership[i] += len(g) - 1
    for groups in col_groups:
        for g in groups:
            for i in g:
                dup_membership[i] += len(g) - 1

    for i, s in enumerate(state):
        if s != UNKNOWN:
            continue
        score = 0
        if i in duplicate_cells:
            score += 100
        score += dup_membership[i] * 10
        black_adj = sum(1 for nb in neighbors[i] if state[nb] == BLACK)
        unk_adj = sum(1 for nb in neighbors[i] if state[nb] == UNKNOWN)
        score += black_adj * 6 + unk_adj
        r, c = rc(i, m)
        score -= abs(r - n // 2) + abs(c - m // 2)
        if score > best_score:
            best_score = score
            best = i
    return best


def branch_order(board, n, m, state, cell, row_groups, col_groups, neighbors):
    # Estimate whether WHITE or BLACK is more constrained first.
    # White is strong in duplicate groups; Black is strong near existing blacks due adjacency.
    white_pressure = 0
    black_pressure = 0
    r, c = rc(cell, m)

    for group in row_groups[r]:
        if cell in group:
            white_pressure += len(group) - 1
    for group in col_groups[c]:
        if cell in group:
            white_pressure += len(group) - 1

    black_pressure += sum(1 for nb in neighbors[cell] if state[nb] != BLACK)

    # Try the more constraining branch first.
    if white_pressure >= black_pressure:
        return (WHITE, BLACK)
    return (BLACK, WHITE)


def search(board, n, m, state, row_groups, col_groups, neighbors, pair_edges, triads, duplicate_cells):
    state = state[:]
    if not propagate(board, n, m, state, row_groups, col_groups, neighbors, pair_edges, triads):
        return None

    if all(s != UNKNOWN for s in state):
        if check_group_consistency(state, row_groups, col_groups) and check_no_adjacent_black(state, neighbors) and final_connected_whites(state, neighbors):
            return state
        return None

    cell = choose_branch_cell(board, n, m, state, row_groups, col_groups, neighbors, duplicate_cells)
    if cell is None:
        return None

    for val in branch_order(board, n, m, state, cell, row_groups, col_groups, neighbors):
        new_state = state[:]
        q = deque()
        if assign(new_state, cell, val, q):
            res = search(board, n, m, new_state, row_groups, col_groups, neighbors, pair_edges, triads, duplicate_cells)
            if res is not None:
                return res
    return None


