# General solver for Heyawake-like puzzle with:
# 1) numbered regions contain exactly that many black cells
# 2) black cells not orthogonally adjacent
# 3) any uninterrupted white segment in a row/column crosses at most 2 regions
# 4) all white cells are orthogonally connected
#
# Returns a Python-literal grid using 'B' for black and None for white, or "No Solution".

from collections import deque, defaultdict
import ast

UNKNOWN = -1
WHITE = 0
BLACK = 1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0]) if n else 0

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}
    rc_of = {i: (i // m, i % m) for i in range(n * m)}

    # Region metadata
    region_cells = defaultdict(list)
    region_clue = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            region_cells[rid].append(idx_of[(r, c)])
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]
    all_regions = sorted(region_cells)

    # Adjacency
    orth = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            i = idx_of[(r, c)]
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    orth[i].append(idx_of[(rr, cc)])

    # White-run constraints: maximal row/column stretches without crossing black.
    # In final state, every contiguous white segment may cross at most 2 regions.
    # We precompute all windows of 3 distinct region blocks in each row/col.
    # If a segment spanning these 3 blocks becomes all white, that's forbidden:
    # thus each such window must contain at least one black.
    run_windows = []

    def add_line_windows(line):
        blocks = []
        start = 0
        while start < len(line):
            rid = region[line[start][0]][line[start][1]]
            end = start + 1
            while end < len(line) and region[line[end][0]][line[end][1]] == rid:
                end += 1
            blocks.append((rid, [idx_of[p] for p in line[start:end]]))
            start = end
        # Consecutive 3 blocks with distinct region ids in order; if all white => bad
        for i in range(len(blocks) - 2):
            a, b, c = blocks[i], blocks[i + 1], blocks[i + 2]
            # Adjacent blocks on a line are always different regions by maximality
            cells_window = a[1] + b[1] + c[1]
            run_windows.append(tuple(cells_window))

    for r in range(n):
        add_line_windows([(r, c) for c in range(m)])
    for c in range(m):
        add_line_windows([(r, c) for r in range(n)])

    # Remove duplicates
    run_windows = list(dict.fromkeys(run_windows))

    class State:
        __slots__ = ("assign", "reg_black", "reg_unknown", "white_count", "black_count")
        def __init__(self):
            self.assign = [UNKNOWN] * (n * m)
            self.reg_black = {rid: 0 for rid in all_regions}
            self.reg_unknown = {rid: len(region_cells[rid]) for rid in all_regions}
            self.white_count = 0
            self.black_count = 0

        def clone(self):
            s = State()
            s.assign = self.assign[:]
            s.reg_black = self.reg_black.copy()
            s.reg_unknown = self.reg_unknown.copy()
            s.white_count = self.white_count
            s.black_count = self.black_count
            return s

    def set_cell(st, i, val, queue):
        cur = st.assign[i]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        st.assign[i] = val
        r, c = rc_of[i]
        rid = region[r][c]
        st.reg_unknown[rid] -= 1
        if val == BLACK:
            st.reg_black[rid] += 1
            st.black_count += 1
        else:
            st.white_count += 1
        queue.append(i)
        return True

    def region_bounds_ok(st, rid):
        clue = region_clue.get(rid)
        if clue is None:
            return True
        b = st.reg_black[rid]
        u = st.reg_unknown[rid]
        if b > clue:
            return False
        if b + u < clue:
            return False
        return True

    def propagate(st):
        queue = deque()

        # Seed with immediate deductions from clues 0 / full region
        changed = True
        while changed:
            changed = False
            for rid in all_regions:
                if not region_bounds_ok(st, rid):
                    return False
                clue = region_clue.get(rid)
                if clue is None:
                    continue
                b = st.reg_black[rid]
                u = st.reg_unknown[rid]
                if u == 0:
                    if b != clue:
                        return False
                    continue
                cells_u = [i for i in region_cells[rid] if st.assign[i] == UNKNOWN]
                if b == clue:
                    for i in cells_u:
                        if not set_cell(st, i, WHITE, queue):
                            return False
                        changed = True
                elif b + u == clue:
                    for i in cells_u:
                        if not set_cell(st, i, BLACK, queue):
                            return False
                        changed = True

        # Process queue and iterative deductions
        while True:
            while queue:
                i = queue.popleft()
                val = st.assign[i]
                rid = region[rc_of[i][0]][rc_of[i][1]]

                # Rule 2: black cells cannot touch orthogonally
                if val == BLACK:
                    for j in orth[i]:
                        if not set_cell(st, j, WHITE, queue):
                            return False

                # Region consistency + completion
                if not region_bounds_ok(st, rid):
                    return False
                clue = region_clue.get(rid)
                if clue is not None:
                    b = st.reg_black[rid]
                    u = st.reg_unknown[rid]
                    if u == 0:
                        if b != clue:
                            return False
                    else:
                        cells_u = [x for x in region_cells[rid] if st.assign[x] == UNKNOWN]
                        if b == clue:
                            for x in cells_u:
                                if not set_cell(st, x, WHITE, queue):
                                    return False
                        elif b + u == clue:
                            for x in cells_u:
                                if not set_cell(st, x, BLACK, queue):
                                    return False

            progress = False

            # White-run window rule: every 3-region window must have at least one black
            for win in run_windows:
                blacks = 0
                unknowns = []
                for i in win:
                    a = st.assign[i]
                    if a == BLACK:
                        blacks += 1
                        break
                    if a == UNKNOWN:
                        unknowns.append(i)
                if blacks:
                    continue
                if not unknowns:
                    return False
                if len(unknowns) == 1:
                    if not set_cell(st, unknowns[0], BLACK, queue):
                        return False
                    progress = True

            # Additional local no-adjacent-black forcing:
            # if unknown has a black neighbor => white
            for i in range(n * m):
                if st.assign[i] == UNKNOWN:
                    if any(st.assign[j] == BLACK for j in orth[i]):
                        if not set_cell(st, i, WHITE, queue):
                            return False
                        progress = True

            # Connectivity pruning for white cells:
            # All non-black cells (white + unknown) must remain in one connected component;
            # every current white cell must be able to reach every other through non-black cells.
            if not nonblack_connectivity_possible(st):
                return False

            # No enclosed mandatory-white separation:
            # every connected component of current white cells must be connectable to others through unknowns.
            if not white_components_can_merge(st):
                return False

            if queue:
                continue
            if not progress:
                break

        return True

    def nonblack_connectivity_possible(st):
        nodes = [i for i in range(n * m) if st.assign[i] != BLACK]
        if not nodes:
            return True
        start = nodes[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in orth[x]:
                if st.assign[y] != BLACK and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(nodes)

    def white_components_can_merge(st):
        white_nodes = [i for i in range(n * m) if st.assign[i] == WHITE]
        if len(white_nodes) <= 1:
            return True

        comp_id = {}
        comps = []
        for s in white_nodes:
            if s in comp_id:
                continue
            cid = len(comps)
            comps.append([])
            dq = deque([s])
            comp_id[s] = cid
            while dq:
                x = dq.popleft()
                comps[cid].append(x)
                for y in orth[x]:
                    if st.assign[y] == WHITE and y not in comp_id:
                        comp_id[y] = cid
                        dq.append(y)

        if len(comps) == 1:
            return True

        # Build reachability over non-black cells from first white component.
        start = comps[0][0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in orth[x]:
                if st.assign[y] != BLACK and y not in seen:
                    seen.add(y)
                    dq.append(y)

        for cid in range(1, len(comps)):
            if not any(x in seen for x in comps[cid]):
                return False
        return True

    def is_complete(st):
        if any(v == UNKNOWN for v in st.assign):
            return False
        for rid in all_regions:
            clue = region_clue.get(rid)
            if clue is not None and st.reg_black[rid] != clue:
                return False
        if not nonblack_connectivity_possible(st):
            return False
        # Since complete, nonblack connectivity is exactly white connectivity.
        # White-run windows already enforced by propagation.
        return True

    def choose_branch_cell(st):
        # Human-like heuristic:
        # 1) cells in numbered regions with tight residual clue
        # 2) cells in many active 3-region windows
        # 3) cells adjacent to decided black/white structure
        score_best = None
        best = None

        active_window_count = [0] * (n * m)
        for win in run_windows:
            if any(st.assign[i] == BLACK for i in win):
                continue
            for i in win:
                if st.assign[i] == UNKNOWN:
                    active_window_count[i] += 1

        for i in range(n * m):
            if st.assign[i] != UNKNOWN:
                continue
            r, c = rc_of[i]
            rid = region[r][c]
            clue = region_clue.get(rid)
            reg_score = 0
            if clue is not None:
                b = st.reg_black[rid]
                u = st.reg_unknown[rid]
                need = clue - b
                reg_score = 20 - abs(u - 2 * need)
            neigh_score = sum(3 for j in orth[i] if st.assign[j] != UNKNOWN)
            score = (reg_score + 2 * active_window_count[i] + neigh_score, active_window_count[i], neigh_score)
            if score_best is None or score > score_best:
                score_best = score
                best = i
        return best

    def value_order(st, i):
        r, c = rc_of[i]
        rid = region[r][c]
        clue = region_clue.get(rid)

        # Try forced-looking value first.
        prefs = []

        # If region needs many blacks among few unknowns, prefer black.
        if clue is not None:
            b = st.reg_black[rid]
            u = st.reg_unknown[rid]
            need = clue - b
            if need == 0:
                return [WHITE]
            if need == u:
                return [BLACK]
            if need * 2 > u:
                prefs = [BLACK, WHITE]
            else:
                prefs = [WHITE, BLACK]
        else:
            prefs = [WHITE, BLACK]

        # If any black neighbor, black impossible; white first.
        if any(st.assign[j] == BLACK for j in orth[i]):
            return [WHITE]

        return prefs

    def dfs(st):
        if not propagate(st):
            return None
        if is_complete(st):
            return st

        i = choose_branch_cell(st)
        if i is None:
            return None

        for val in value_order(st, i):
            ns = st.clone()
            q = deque()
            if not set_cell(ns, i, val, q):
                continue
            res = dfs(ns)
            if res is not None:
                return res
        return None

    st0 = State()
    result = dfs(st0)
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            v = result.assign[idx_of[(r, c)]]
            row.append('B' if v == BLACK else None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 9, None, None, None], [None, 5, None, None, None, None, 8], [None, None, None, 8, None, None, 10], [None, None, None, 9, None, None, None], [7, None, None, 9, None, None, None], [3, None, None, None, None, 3, None], [None, None, None, 4, None, None, None]]}

from collections import deque

# General solver for Kuromasu / Kurodoko-like puzzles.
# State encoding:
#   -1 = unknown
#    0 = white
#    1 = black
# Clue cells are fixed white.
#
# The solver is designed around aggressive propagation:
# 1) clue visibility min/max bounds
# 2) candidate line-pattern filtering per clue
# 3) no-adjacent-black rule
# 4) impossible-white / impossible-black tests by local consistency
# 5) global white-connectivity pruning using optimistic reachability
# Search remains, but only after heavy deduction and with a strong branching heuristic.

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    data = observation["data"]
    n = len(data)
    clues = {}
    clue_cells = set()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                clue_cells.add((r, c))

    idx = {(r, c): r * n + c for r in range(n) for c in range(n)}

    neighbors = {}
    for r in range(n):
        for c in range(n):
            arr = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    arr.append((rr, cc))
            neighbors[(r, c)] = arr

    # Rays from each clue in 4 directions, excluding the clue cell itself.
    clue_rays = {}
    clue_cross = {}
    for (r, c), val in clues.items():
        rays = []
        cross = [(r, c)]
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            ray = []
            rr, cc = r + dr, c + dc
            while 0 <= rr < n and 0 <= cc < n:
                ray.append((rr, cc))
                cross.append((rr, cc))
                rr += dr
                cc += dc
            rays.append(ray)
        clue_rays[(r, c)] = rays
        clue_cross[(r, c)] = cross

    # Which clues see a given cell on same row/col.
    cell_to_clues = {pos: [] for pos in idx}
    for clue, cells in clue_cross.items():
        for cell in cells:
            cell_to_clues[cell].append(clue)

    # Initial state.
    state = [UNKNOWN] * (n * n)
    for (r, c) in clue_cells:
        state[idx[(r, c)]] = WHITE

    # Precompute all feasible directional length tuples for each clue.
    # Tuple is (u,d,l,r) visible lengths excluding clue cell.
    clue_patterns = {}
    for (r, c), val in clues.items():
        maxlens = tuple(len(ray) for ray in clue_rays[(r, c)])
        pats = []
        for u in range(maxlens[0] + 1):
            for d in range(maxlens[1] + 1):
                for l in range(maxlens[2] + 1):
                    rem = val - 1 - u - d - l
                    if 0 <= rem <= maxlens[3]:
                        pats.append((u, d, l, rem))
        clue_patterns[(r, c)] = pats

    def get_cell(st, cell):
        return st[idx[cell]]

    def set_cell(st, cell, value):
        i = idx[cell]
        cur = st[i]
        if cur == value:
            return True
        if cur != UNKNOWN and cur != value:
            return False
        st[i] = value
        return True

    def visible_bounds_for_clue(st, clue):
        rays = clue_rays[clue]
        min_total = 1
        max_total = 1
        for ray in rays:
            # Minimum visible: consecutive forced whites before first unknown/black.
            mn = 0
            for cell in ray:
                v = get_cell(st, cell)
                if v == WHITE:
                    mn += 1
                else:
                    break
            # Maximum visible: until first forced black.
            mx = 0
            for cell in ray:
                v = get_cell(st, cell)
                if v == BLACK:
                    break
                mx += 1
            min_total += mn
            max_total += mx
        return min_total, max_total

    def clue_pattern_fits(st, clue, pat):
        rays = clue_rays[clue]
        for ray, k in zip(rays, pat):
            # First k cells must be white, next cell if exists must be black.
            for i, cell in enumerate(ray):
                v = get_cell(st, cell)
                if i < k:
                    if v == BLACK:
                        return False
                elif i == k:
                    if v == WHITE:
                        return False
                    break
        return True

    def feasible_patterns(st, clue):
        pats = []
        for pat in clue_patterns[clue]:
            if clue_pattern_fits(st, clue, pat):
                pats.append(pat)
        return pats

    def apply_clue_patterns(st, clue, pats):
        rays = clue_rays[clue]
        changed = False

        # If no pattern exists => contradiction.
        if not pats:
            return None

        # For each ray position, infer if always white / always not-white-visible.
        for ray_idx, ray in enumerate(rays):
            for pos, cell in enumerate(ray):
                all_white = True
                all_black_boundary_or_beyond = True
                for pat in pats:
                    k = pat[ray_idx]
                    if pos < k:
                        all_black_boundary_or_beyond = False
                    else:
                        all_white = False
                if all_white:
                    i = idx[cell]
                    if st[i] == BLACK:
                        return None
                    if st[i] == UNKNOWN:
                        st[i] = WHITE
                        changed = True
                if all_black_boundary_or_beyond:
                    # This cell can never be visible from this clue.
                    # If all previous cells in the ray are guaranteed white in every pattern and this cell is at boundary k, it must be black.
                    boundary_all = True
                    for pat in pats:
                        if pat[ray_idx] != pos:
                            boundary_all = False
                            break
                    if boundary_all:
                        i = idx[cell]
                        if cell in clue_cells:
                            return None
                        if st[i] == WHITE:
                            return None
                        if st[i] == UNKNOWN:
                            st[i] = BLACK
                            changed = True
        return changed

    def no_adjacent_black_propagation(st):
        changed = False
        for r in range(n):
            for c in range(n):
                if get_cell(st, (r, c)) == BLACK:
                    for nb in neighbors[(r, c)]:
                        i = idx[nb]
                        if st[i] == BLACK:
                            return None
                        if st[i] == UNKNOWN:
                            st[i] = WHITE
                            changed = True
        return changed

    def simple_clue_bound_propagation(st):
        changed = False
        for clue, val in clues.items():
            mn, mx = visible_bounds_for_clue(st, clue)
            if not (mn <= val <= mx):
                return None

            # Per-ray pressure by min/max lengths.
            rays = clue_rays[clue]
            ray_mins = []
            ray_maxs = []
            for ray in rays:
                mnr = 0
                for cell in ray:
                    v = get_cell(st, cell)
                    if v == WHITE:
                        mnr += 1
                    else:
                        break
                mxr = 0
                for cell in ray:
                    v = get_cell(st, cell)
                    if v == BLACK:
                        break
                    mxr += 1
                ray_mins.append(mnr)
                ray_maxs.append(mxr)

            total_min_excl = sum(ray_mins)
            total_max_excl = sum(ray_maxs)
            target = val - 1

            for d in range(4):
                other_min = total_min_excl - ray_mins[d]
                other_max = total_max_excl - ray_maxs[d]
                need_low = target - other_max
                need_high = target - other_min
                need_low = max(need_low, ray_mins[d], 0)
                need_high = min(need_high, ray_maxs[d])

                if need_low > need_high:
                    return None

                ray = rays[d]

                # First need_low cells must be white.
                for i2 in range(need_low):
                    cell = ray[i2]
                    j = idx[cell]
                    if st[j] == BLACK:
                        return None
                    if st[j] == UNKNOWN:
                        st[j] = WHITE
                        changed = True

                # Cell after need_high must be black if exists.
                if need_high < len(ray):
                    cell = ray[need_high]
                    if cell not in clue_cells:
                        j = idx[cell]
                        if st[j] == WHITE:
                            return None
                        if st[j] == UNKNOWN:
                            st[j] = BLACK
                            changed = True
                    else:
                        # A clue cell cannot be black, so this upper bound can only be valid if crossing never requires blacking the clue.
                        # Since rays do not include clue cells, this path should never occur; still safe.
                        pass
        return changed

    def optimistic_white_reachability(st):
        # Cells that can possibly be white are all non-forced-black cells.
        possible = [i for i, v in enumerate(st) if v != BLACK]
        if not possible:
            return False
        forced_white = [i for i, v in enumerate(st) if v == WHITE]
        if not forced_white:
            return True

        start = forced_white[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            r, c = divmod(x, n)
            for rr, cc in neighbors[(r, c)]:
                y = idx[(rr, cc)]
                if y not in seen and st[y] != BLACK:
                    seen.add(y)
                    dq.append(y)
        for i in forced_white:
            if i not in seen:
                return False
        return True

    def final_white_connected(st):
        white = [i for i, v in enumerate(st) if v == WHITE]
        if not white:
            return False
        start = white[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            r, c = divmod(x, n)
            for rr, cc in neighbors[(r, c)]:
                y = idx[(rr, cc)]
                if y not in seen and st[y] == WHITE:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(white)

    def all_clues_exact(st):
        for clue, val in clues.items():
            rays = clue_rays[clue]
            total = 1
            for ray in rays:
                for cell in ray:
                    v = get_cell(st, cell)
                    if v == WHITE:
                        total += 1
                    else:
                        break
            if total != val:
                return False
        return True

    def local_cell_feasible(st, cell, value):
        # Test assignment by checking impacted clues and adjacency.
        tmp = st[:]
        if not set_cell(tmp, cell, value):
            return False

        # Clue cells can never be black.
        if cell in clue_cells and value == BLACK:
            return False

        # Adjacency around assigned black.
        if value == BLACK:
            for nb in neighbors[cell]:
                if get_cell(tmp, nb) == BLACK:
                    return False

        # Impacted clues only.
        for clue in cell_to_clues[cell]:
            mn, mx = visible_bounds_for_clue(tmp, clue)
            valc = clues[clue]
            if not (mn <= valc <= mx):
                return False
            if not feasible_patterns(tmp, clue):
                return False

        if not optimistic_white_reachability(tmp):
            return False

        return True

    def propagate(st):
        while True:
            any_change = False

            res = no_adjacent_black_propagation(st)
            if res is None:
                return None
            any_change |= res

            res = simple_clue_bound_propagation(st)
            if res is None:
                return None
            any_change |= res

            # Pattern filtering per clue.
            for clue in clues:
                pats = feasible_patterns(st, clue)
                if not pats:
                    return None
                res = apply_clue_patterns(st, clue, pats)
                if res is None:
                    return None
                any_change |= res

            # Cell-wise contradiction forcing.
            # If one color impossible, assign the other.
            for r in range(n):
                for c in range(n):
                    cell = (r, c)
                    i = idx[cell]
                    if st[i] != UNKNOWN:
                        continue
                    if cell in clue_cells:
                        st[i] = WHITE
                        any_change = True
                        continue
                    can_w = local_cell_feasible(st, cell, WHITE)
                    can_b = local_cell_feasible(st, cell, BLACK)
                    if not can_w and not can_b:
                        return None
                    if can_w and not can_b:
                        st[i] = WHITE
                        any_change = True
                    elif can_b and not can_w:
                        st[i] = BLACK
                        any_change = True

            if not optimistic_white_reachability(st):
                return None

            if not any_change:
                break
        return st

    def choose_branch_cell(st):
        # Strong heuristic:
        # pick unknown cell with highest pressure from clue-pattern ambiguity and local constraints.
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                cell = (r, c)
                i = idx[cell]
                if st[i] != UNKNOWN:
                    continue
                if cell in clue_cells:
                    return cell

                score = 0

                # Adjacent black pressure
                for nb in neighbors[cell]:
                    if get_cell(st, nb) == BLACK:
                        score += 50

                # Clue involvement pressure
                involved = cell_to_clues[cell]
                score += 10 * len(involved)
                for clue in involved:
                    pats = feasible_patterns(st, clue)
                    score += max(0, 20 - len(pats))

                    # Whether many patterns disagree on this cell.
                    rayinfo = None
                    cr, cc = clue
                    if r == cr and c == cc:
                        continue
                    rays = clue_rays[clue]
                    for ridx, ray in enumerate(rays):
                        if cell in ray:
                            pos = ray.index(cell)
                            rayinfo = (ridx, pos)
                            break
                    if rayinfo is not None:
                        ridx, pos = rayinfo
                        white_count = 0
                        blackish_count = 0
                        boundary_count = 0
                        for pat in pats:
                            k = pat[ridx]
                            if pos < k:
                                white_count += 1
                            else:
                                blackish_count += 1
                            if pos == k:
                                boundary_count += 1
                        score += min(white_count, blackish_count)
                        score += boundary_count

                # Fewer feasible colors should branch sooner.
                can_w = local_cell_feasible(st, cell, WHITE)
                can_b = local_cell_feasible(st, cell, BLACK)
                if can_w != can_b:
                    score += 100

                key = (-score, r, c)
                if best_score is None or key < best_score:
                    best_score = key
                    best = cell
        return best

    def search(st):
        st = propagate(st[:])
        if st is None:
            return None

        if all(v != UNKNOWN for v in st):
            if final_white_connected(st) and all_clues_exact(st):
                return st
            return None

        cell = choose_branch_cell(st)
        if cell is None:
            return None

        # Prefer value that is locally more constrained first.
        options = []
        for val in (WHITE, BLACK):
            if local_cell_feasible(st, cell, val):
                # Scoring for branch order: try more forced-looking choice first.
                score = 0
                if val == BLACK:
                    score += sum(1 for nb in neighbors[cell] if get_cell(st, nb) == UNKNOWN)
                else:
                    score += len(cell_to_clues[cell])
                options.append((-score, val))
        options.sort()

        for _, val in options:
            nxt = st[:]
            if not set_cell(nxt, cell, val):
                continue
            res = search(nxt)
            if res is not None:
                return res
        return None

    res = search(state)
    if res is None:
        return "No Solution"

    answer = []
    for r in range(n):
        row = []
        for c in range(n):
            if data[r][c] is not None:
                row.append(data[r][c])
            else:
                row.append('B' if res[idx[(r, c)]] == BLACK else None)
        answer.append(row)
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 1, None, None, None, None, None, None, None, None, None], [None, None, 3, 1, None, 1, 2, 3, None, 1, None], [1, 2, 3, None, None, None, 1, None, None, None, 1], [None, 1, 1, None, None, 1, 1, None, 1, 2, 1], [None, None, 1, None, 2, 2, None, None, 2, 1, None], [None, 1, None, None, None, None, 3, None, 2, None, None], [None, 3, 1, None, 3, None, None, 1, 2, None, 1], [1, 1, 2, 3, 1, 2, None, 1, None, 2, None], [1, None, 2, None, 3, None, None, None, 1, None, 1], [1, 2, None, 2, 1, 2, None, 2, 2, 2, 1], [None, 1, 1, None, None, None, None, None, 1, None, None]]}

# Slant puzzle solver:
# - one slash per cell
# - each numbered dot must have exactly that many incident diagonals
# - diagonals must form no cycle
#
# The solver is generalized and uses:
# 1) degree bound propagation on dots
# 2) union-find with rollback to forbid loops incrementally
# 3) cell forcing when one orientation becomes impossible
# 4) branching on the most constrained undecided cell

from copy import deepcopy

SLASH = 0      # '/'
BACKSLASH = 1  # '\\'


class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def snapshot(self):
        return len(self.history)

    def rollback(self, snap):
        while len(self.history) > snap:
            entry = self.history.pop()
            if entry is None:
                continue
            rb, ra, size_ra = entry
            self.parent[rb] = rb
            self.size[ra] = size_ra
            self.components += 1

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.history.append((rb, ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True


class Solver:
    def __init__(self, observation):
        self.data = observation['data']
        self.Hp = len(self.data)
        self.Wp = len(self.data[0])
        if self.Hp != self.Wp:
            raise ValueError("Expected square point grid")
        self.N = self.Hp - 1

        # cell state: -1 undecided, 0 '/', 1 '\'
        self.assign = [[-1] * self.N for _ in range(self.N)]

        # point indexing
        self.P = self.Hp * self.Wp

        # incident cells and local endpoint mapping
        # For a cell (r,c):
        # '/' uses (r, c+1) and (r+1, c)
        # '\' uses (r, c) and (r+1, c+1)
        self.point_incident = [[[] for _ in range(self.Wp)] for _ in range(self.Hp)]
        self.numbered_points = []
        self.point_req = {}
        self.point_deg = {}
        self.point_undec = {}

        for r in range(self.N):
            for c in range(self.N):
                # For each incident point, store (cell_r, cell_c, ori_if_incident)
                self.point_incident[r][c].append((r, c, BACKSLASH))
                self.point_incident[r][c + 1].append((r, c, SLASH))
                self.point_incident[r + 1][c].append((r, c, SLASH))
                self.point_incident[r + 1][c + 1].append((r, c, BACKSLASH))

        for pr in range(self.Hp):
            for pc in range(self.Wp):
                clue = self.data[pr][pc]
                if clue is not None:
                    self.numbered_points.append((pr, pc))
                    self.point_req[(pr, pc)] = clue
                    self.point_deg[(pr, pc)] = 0
                    self.point_undec[(pr, pc)] = len(self.point_incident[pr][pc])

        self.dsu = RollbackDSU(self.P)
        self.trail = []
        self.queue = []

        # Precompute endpoints for both orientations
        self.cell_endpoints = {}
        for r in range(self.N):
            for c in range(self.N):
                self.cell_endpoints[(r, c, SLASH)] = ((r, c + 1), (r + 1, c))
                self.cell_endpoints[(r, c, BACKSLASH)] = ((r, c), (r + 1, c + 1))

    def point_id(self, pr, pc):
        return pr * self.Wp + pc

    def cell_possible(self, r, c, ori):
        cur = self.assign[r][c]
        if cur != -1:
            return cur == ori

        # Check numbered point feasibility if this orientation is chosen
        if not self._check_point_effect(r, c, ori):
            return False

        # Loop prevention: if endpoints already connected, choosing this creates a cycle
        (a, b) = self.cell_endpoints[(r, c, ori)]
        ia = self.point_id(*a)
        ib = self.point_id(*b)
        if self.dsu.find(ia) == self.dsu.find(ib):
            return False

        return True

    def _check_point_effect(self, r, c, ori):
        # For every numbered point incident to cell, simulate degree and undecided changes.
        touched = []
        for pr, pc, needed_ori in (
            (r, c, BACKSLASH),
            (r, c + 1, SLASH),
            (r + 1, c, SLASH),
            (r + 1, c + 1, BACKSLASH),
        ):
            if self.data[pr][pc] is not None:
                touched.append((pr, pc, needed_ori))

        seen = set()
        for pr, pc, needed_ori in touched:
            if (pr, pc) in seen:
                continue
            seen.add((pr, pc))
            req = self.point_req[(pr, pc)]
            deg = self.point_deg[(pr, pc)]
            undec = self.point_undec[(pr, pc)]
            undec2 = undec - 1
            deg2 = deg + (1 if ori == needed_ori else 0)
            if deg2 > req:
                return False
            if deg2 + undec2 < req:
                return False
        return True

    def _record_point_change(self, pr, pc, old_deg, old_undec):
        self.trail.append(("pt", pr, pc, old_deg, old_undec))

    def _record_cell(self, r, c, old):
        self.trail.append(("cell", r, c, old))

    def _record_queue_mark(self):
        self.trail.append(("qmark",))

    def snapshot(self):
        return (len(self.trail), self.dsu.snapshot())

    def rollback(self, snap):
        trail_len, dsu_snap = snap
        self.dsu.rollback(dsu_snap)
        while len(self.trail) > trail_len:
            item = self.trail.pop()
            typ = item[0]
            if typ == "cell":
                _, r, c, old = item
                self.assign[r][c] = old
            elif typ == "pt":
                _, pr, pc, old_deg, old_undec = item
                self.point_deg[(pr, pc)] = old_deg
                self.point_undec[(pr, pc)] = old_undec
            elif typ == "qmark":
                self.queue.pop()

    def enqueue(self, r, c):
        self._record_queue_mark()
        self.queue.append((r, c))

    def assign_cell(self, r, c, ori):
        cur = self.assign[r][c]
        if cur != -1:
            return cur == ori
        if not self.cell_possible(r, c, ori):
            return False

        self._record_cell(r, c, cur)
        self.assign[r][c] = ori

        # Update numbered points
        updates = [
            (r, c, BACKSLASH),
            (r, c + 1, SLASH),
            (r + 1, c, SLASH),
            (r + 1, c + 1, BACKSLASH),
        ]
        seen = set()
        for pr, pc, needed_ori in updates:
            if self.data[pr][pc] is None or (pr, pc) in seen:
                continue
            seen.add((pr, pc))
            old_deg = self.point_deg[(pr, pc)]
            old_undec = self.point_undec[(pr, pc)]
            self._record_point_change(pr, pc, old_deg, old_undec)
            self.point_undec[(pr, pc)] = old_undec - 1
            if ori == needed_ori:
                self.point_deg[(pr, pc)] = old_deg + 1

            req = self.point_req[(pr, pc)]
            deg = self.point_deg[(pr, pc)]
            undec = self.point_undec[(pr, pc)]
            if deg > req or deg + undec < req:
                return False

        # Union chosen endpoints
        a, b = self.cell_endpoints[(r, c, ori)]
        if not self.dsu.union(self.point_id(*a), self.point_id(*b)):
            return False

        return True

    def propagate(self):
        changed = True
        while changed:
            changed = False

            # Dot-based deductions
            for pr, pc in self.numbered_points:
                req = self.point_req[(pr, pc)]
                deg = self.point_deg[(pr, pc)]
                undec = self.point_undec[(pr, pc)]
                if deg > req or deg + undec < req:
                    return False
                if undec == 0:
                    if deg != req:
                        return False
                    continue

                need = req - deg
                # Among undecided incident cells, classify which orientation contributes to this point.
                undec_cells = []
                must_incident = []
                must_not_incident = []
                for r, c, ori_hit in self.point_incident[pr][pc]:
                    if self.assign[r][c] == -1:
                        undec_cells.append((r, c, ori_hit))

                if not undec_cells:
                    continue

                if need == 0:
                    # All undecided incident cells must avoid this point
                    for r, c, ori_hit in undec_cells:
                        forced = 1 - ori_hit
                        if not self.assign_cell(r, c, forced):
                            return False
                        changed = True
                elif need == len(undec_cells):
                    # All undecided incident cells must hit this point
                    for r, c, ori_hit in undec_cells:
                        if not self.assign_cell(r, c, ori_hit):
                            return False
                        changed = True

            # Cell-based feasibility deductions
            for r in range(self.N):
                for c in range(self.N):
                    if self.assign[r][c] != -1:
                        continue
                    p0 = self.cell_possible(r, c, SLASH)
                    p1 = self.cell_possible(r, c, BACKSLASH)
                    if not p0 and not p1:
                        return False
                    if p0 ^ p1:
                        if not self.assign_cell(r, c, SLASH if p0 else BACKSLASH):
                            return False
                        changed = True

        return True

    def is_solved(self):
        for r in range(self.N):
            for c in range(self.N):
                if self.assign[r][c] == -1:
                    return False
        for pr, pc in self.numbered_points:
            if self.point_deg[(pr, pc)] != self.point_req[(pr, pc)]:
                return False
        return True

    def choose_branch_cell(self):
        best = None
        best_score = None
        for r in range(self.N):
            for c in range(self.N):
                if self.assign[r][c] != -1:
                    continue
                p0 = self.cell_possible(r, c, SLASH)
                p1 = self.cell_possible(r, c, BACKSLASH)
                if not p0 and not p1:
                    return None
                score = 0
                # Prefer cells touching more constrained numbered points
                pts = [
                    (r, c),
                    (r, c + 1),
                    (r + 1, c),
                    (r + 1, c + 1),
                ]
                seen = set()
                for pr, pc in pts:
                    if (pr, pc) in seen:
                        continue
                    seen.add((pr, pc))
                    if self.data[pr][pc] is not None:
                        req = self.point_req[(pr, pc)]
                        deg = self.point_deg[(pr, pc)]
                        undec = self.point_undec[(pr, pc)]
                        score += 10 - max(0, undec - abs(req - deg))
                if best is None or score > best_score:
                    best = (r, c, p0, p1)
                    best_score = score
        return best

    def search(self):
        if not self.propagate():
            return False
        if self.is_solved():
            return True

        choice = self.choose_branch_cell()
        if choice is None:
            return False
        r, c, p0, p1 = choice

        # Try more constrained-looking orientation first:
        # estimate by resulting point hits near numbered clues
        order = []
        if p0:
            order.append(SLASH)
        if p1:
            order.append(BACKSLASH)

        def local_score(ori):
            score = 0
            for pr, pc, need_ori in (
                (r, c, BACKSLASH),
                (r, c + 1, SLASH),
                (r + 1, c, SLASH),
                (r + 1, c + 1, BACKSLASH),
            ):
                if self.data[pr][pc] is not None:
                    req = self.point_req[(pr, pc)]
                    deg = self.point_deg[(pr, pc)]
                    if ori == need_ori:
                        score += abs(req - (deg + 1))
                    else:
                        score += abs(req - deg)
            return score

        order.sort(key=local_score)

        for ori in order:
            snap = self.snapshot()
            if self.assign_cell(r, c, ori) and self.search():
                return True
            self.rollback(snap)
        return False

    def result_grid(self):
        return [[('/' if self.assign[r][c] == SLASH else '\\') for c in range(self.N)] for r in range(self.N)]


def solve(observation):
    solver = Solver(observation)
    ok = solver.search()
    if not ok:
        return "No Solution"
    return str(solver.result_grid())


if __name__ == "__main__":
    print(solve(OBSERVATION))

