from collections import deque

WHITE = 1
BLACK = 0
UNKNOWN = -1

def solve(observation):
    data = observation['data']
    n = len(data)
    clues = {}
    clue_cells = set()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                clue_cells.add((r, c))

    idx = lambda r, c: r * n + c
    rc = lambda i: divmod(i, n)

    # Precompute line segments for each clue (excluding clue cell itself), split by direction.
    clue_info = {}
    for (r, c), val in clues.items():
        dirs = []
        up = [idx(rr, c) for rr in range(r - 1, -1, -1)]
        down = [idx(rr, c) for rr in range(r + 1, n)]
        left = [idx(r, cc) for cc in range(c - 1, -1, -1)]
        right = [idx(r, cc) for cc in range(c + 1, n)]
        dirs = [up, down, left, right]
        all_cells = []
        for arr in dirs:
            all_cells.extend(arr)
        clue_info[(r, c)] = {
            'value': val,
            'dirs': dirs,
            'all': all_cells,
            'index': idx(r, c),
        }

    # Neighborhoods
    orth = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    orth[i].append(idx(rr, cc))

    # For each cell, list clues that see it on their row/col.
    seen_by = [[] for _ in range(n * n)]
    for clue, info in clue_info.items():
        ci = info['index']
        seen_by[ci].append(clue)
        for j in info['all']:
            seen_by[j].append(clue)

    # State arrays
    state = [UNKNOWN] * (n * n)
    for r, c in clue_cells:
        state[idx(r, c)] = WHITE

    # Forced due to clue cells: clue cells are white and their orth-neighbors can't be black touching clue if clue black? No, clue is white, black can touch white.
    # But clue cells themselves cannot be black.

    def assign(st, i, val, queue):
        cur = st[i]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        st[i] = val
        queue.append(i)
        return True

    def visible_bounds_on_dir(st, arr):
        # Human-like: visible cells form a prefix of whites then optionally a black blocker.
        minw = 0
        maxw = 0
        open_unknown = False
        for j in arr:
            if st[j] == WHITE:
                minw += 1
                maxw += 1
            elif st[j] == BLACK:
                break
            else:
                maxw += 1
                open_unknown = True
        return minw, maxw, open_unknown

    def clue_total_bounds(st, clue):
        info = clue_info[clue]
        mn = 1
        mx = 1
        dir_bounds = []
        for arr in info['dirs']:
            a, b, _ = visible_bounds_on_dir(st, arr)
            mn += a
            mx += b
            dir_bounds.append((a, b))
        return mn, mx, dir_bounds

    def force_prefix_logic(st, clue, queue):
        # For each clue, use exact count with directional prefix logic.
        info = clue_info[clue]
        target = info['value']
        mins = [0] * 4
        maxs = [0] * 4
        for d, arr in enumerate(info['dirs']):
            a, b, _ = visible_bounds_on_dir(st, arr)
            mins[d] = a
            maxs[d] = b
        total_min = 1 + sum(mins)
        total_max = 1 + sum(maxs)
        if target < total_min or target > total_max:
            return False
        # If a direction must contribute at least k, first k cells are white.
        for d, arr in enumerate(info['dirs']):
            other_max = total_max - maxs[d]
            need = target - other_max - 1
            if need < 0:
                need = 0
            if need > maxs[d]:
                return False
            # Need first `need` visible cells in this direction to be white.
            for t in range(need):
                if t >= len(arr):
                    return False
                j = arr[t]
                if st[j] == BLACK:
                    return False
                if st[j] == UNKNOWN:
                    if not assign(st, j, WHITE, queue):
                        return False
            # If direction cannot exceed lim, then cell after lim whites must be black (if exists and previous lim all non-black-capable)
            lim = target - (1 + sum(mins[k] for k in range(4) if k != d))
            if lim < mins[d] or lim > maxs[d]:
                pass
            # Stronger local prefix rule:
            # Count guaranteed non-black prefix length p (existing whites plus forced by impossibility of earlier black).
            # If max contribution exactly x, then (x+1)-th cell must be black if present and all first x are white.
            if lim == mins[d] == maxs[d]:
                # exact contribution from this direction fixed
                x = lim
                if x < len(arr):
                    ok_prefix = True
                    for t in range(x):
                        if st[arr[t]] == BLACK:
                            ok_prefix = False
                            break
                    if ok_prefix:
                        j = arr[x]
                        if st[j] == WHITE:
                            return False
                        if st[j] == UNKNOWN:
                            if not assign(st, j, BLACK, queue):
                                return False

        # Enumerate directional contributions only (small) and derive per-cell consequences.
        choices = []
        for d, arr in enumerate(info['dirs']):
            poss = []
            # contribution x means first x cells white, next cell black or border, and no earlier black among first x.
            for x in range(maxs[d] + 1):
                if x < mins[d]:
                    continue
                feasible = True
                for t in range(x):
                    if st[arr[t]] == BLACK:
                        feasible = False
                        break
                if not feasible:
                    continue
                if x < len(arr) and x < maxs[d]:
                    if st[arr[x]] == WHITE:
                        feasible = False
                if feasible:
                    poss.append(x)
            if not poss:
                return False
            choices.append(poss)

        valid = []
        for a in choices[0]:
            s1 = a
            if s1 > target - 1:
                continue
            for b in choices[1]:
                s2 = s1 + b
                if s2 > target - 1:
                    continue
                for c in choices[2]:
                    s3 = s2 + c
                    if s3 > target - 1:
                        continue
                    d = target - 1 - s3
                    if d in choices[3]:
                        valid.append((a, b, c, d))
        if not valid:
            return False

        # For each direction/cell position, if all valid tuples require position < x white, force white;
        # if all valid tuples require position == x stop, force black on x-th cell.
        for d, arr in enumerate(info['dirs']):
            if not arr:
                continue
            max_len = len(arr)
            vals = [tpl[d] for tpl in valid]
            minx = min(vals)
            maxx = max(vals)
            for t in range(minx):
                j = arr[t]
                if st[j] == UNKNOWN:
                    if not assign(st, j, WHITE, queue):
                        return False
                elif st[j] == BLACK:
                    return False
            # If all contributions equal x and there is a next cell, it must be black.
            if minx == maxx and minx < max_len:
                j = arr[minx]
                if st[j] == UNKNOWN:
                    if not assign(st, j, BLACK, queue):
                        return False
                elif st[j] == WHITE:
                    return False
        return True

    def connectivity_checks(st):
        # White cells (assigned white and unknowns potentially white) must allow clue whites to be in one component.
        white_like = [i for i, v in enumerate(st) if v != BLACK]
        if not white_like:
            return False
        start = white_like[0]
        vis = set([start])
        dq = deque([start])
        while dq:
            i = dq.popleft()
            for j in orth[i]:
                if st[j] != BLACK and j not in vis:
                    vis.add(j)
                    dq.append(j)
        for i, v in enumerate(st):
            if v != BLACK and i not in vis:
                return False
        # Assigned white cells must themselves be connected through non-black cells possibility.
        whites = [i for i, v in enumerate(st) if v == WHITE]
        if whites:
            start = whites[0]
            vis = set([start])
            dq = deque([start])
            while dq:
                i = dq.popleft()
                for j in orth[i]:
                    if st[j] != BLACK and j not in vis:
                        vis.add(j)
                        dq.append(j)
            for i in whites:
                if i not in vis:
                    return False
        return True

    def articulation_forced_white(st, queue):
        # If setting an unknown to black disconnects current white region possibility, force it white.
        # Cheap test only around narrow candidates.
        nonblack = [i for i, v in enumerate(st) if v != BLACK]
        if not nonblack:
            return True
        for i, v in enumerate(st):
            if v != UNKNOWN:
                continue
            st[i] = BLACK
            ok = connectivity_checks(st)
            st[i] = UNKNOWN
            if not ok:
                if not assign(st, i, WHITE, queue):
                    return False
        return True

    def local_black_adjacency(st, i, queue):
        if st[i] == BLACK:
            for j in orth[i]:
                if st[j] == BLACK:
                    return False
                if st[j] == UNKNOWN:
                    if not assign(st, j, WHITE, queue):
                        return False
        return True

    def clue_cell_cannot_be_blocked_wrong(st, i):
        # Fast consistency for clues seeing this cell.
        for clue in seen_by[i]:
            mn, mx, _ = clue_total_bounds(st, clue)
            target = clue_info[clue]['value']
            if target < mn or target > mx:
                return False
        return True

    def propagate(st):
        queue = deque()

        # Initial queue all decided cells and all clue lines
        for i, v in enumerate(st):
            if v != UNKNOWN:
                queue.append(i)

        touched_clues = deque(clues.keys())
        in_touched = set(clues.keys())

        while queue or touched_clues:
            while queue:
                i = queue.popleft()
                if not local_black_adjacency(st, i, queue):
                    return False
                if not clue_cell_cannot_be_blocked_wrong(st, i):
                    return False
                for clue in seen_by[i]:
                    if clue not in in_touched:
                        in_touched.add(clue)
                        touched_clues.append(clue)

            if touched_clues:
                clue = touched_clues.popleft()
                in_touched.discard(clue)
                before = tuple(st)
                if not force_prefix_logic(st, clue, queue):
                    return False
                if tuple(st) != before:
                    # Any changed cell already in queue
                    pass

        # Global passes until stable
        changed = True
        while changed:
            changed = False
            before = tuple(st)
            if not articulation_forced_white(st, deque_holder := deque()):
                return False
            while deque_holder:
                i = deque_holder.popleft()
                if not local_black_adjacency(st, i, deque_holder):
                    return False
                if not clue_cell_cannot_be_blocked_wrong(st, i):
                    return False
                for clue in seen_by[i]:
                    if not force_prefix_logic(st, clue, deque_holder):
                        return False
            if not connectivity_checks(st):
                return False
            if tuple(st) != before:
                changed = True
        return True

    def solved(st):
        if any(v == UNKNOWN for v in st):
            return False
        if not connectivity_checks(st):
            return False
        for clue in clues:
            mn, mx, _ = clue_total_bounds(st, clue)
            target = clue_info[clue]['value']
            if not (mn == mx == target):
                return False
        for i, v in enumerate(st):
            if v == BLACK:
                for j in orth[i]:
                    if st[j] == BLACK:
                        return False
        return True

    def choose_cell(st):
        # Most constrained unknown: participates in many clue lines and near blacks/clues.
        best = None
        best_score = -1
        for i, v in enumerate(st):
            if v != UNKNOWN:
                continue
            score = len(seen_by[i]) * 5
            score += sum(1 for j in orth[i] if st[j] != UNKNOWN)
            if score > best_score:
                best_score = score
                best = i
        return best

    def search(st):
        if not propagate(st):
            return None
        if solved(st):
            return st
        i = choose_cell(st)
        if i is None:
            return None

        # Value ordering: try value that appears more constrained by clues.
        orders = [WHITE, BLACK]
        r, c = rc(i)
        if (r, c) in clue_cells:
            orders = [WHITE]
        elif any(st[j] == BLACK for j in orth[i]):
            orders = [WHITE, BLACK]
        for val in orders:
            nxt = st[:]
            q = deque()
            if not assign(nxt, i, val, q):
                continue
            res = search(nxt)
            if res is not None:
                return res
        return None

    res = search(state[:])
    if res is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            if data[r][c] is not None:
                row.append(data[r][c])
            else:
                row.append('B' if res[idx(r, c)] == BLACK else None)
        out.append(row)
    return str(out)

