# Hitori solver with strong propagation and pruned search.
# Returns a solved mask as an N x N list using 'B' for black and None for white.

from collections import deque

UNKNOWN = 0
WHITE = 1
BLACK = 2

def solve(observation):
    grid = observation['data']
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"

    idx = lambda r, c: r * n + c
    rc = lambda i: divmod(i, n)
    N2 = n * n

    neighbors = [[] for _ in range(N2)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    # Duplicate groups in rows and columns.
    row_groups = []
    col_groups = []
    cell_to_groups = [[] for _ in range(N2)]

    for r in range(n):
        mp = {}
        for c in range(n):
            mp.setdefault(grid[r][c], []).append(idx(r, c))
        for cells in mp.values():
            if len(cells) >= 2:
                gid = len(row_groups)
                row_groups.append(tuple(cells))
                for i in cells:
                    cell_to_groups[i].append(('r', gid))

    for c in range(n):
        mp = {}
        for r in range(n):
            mp.setdefault(grid[r][c], []).append(idx(r, c))
        for cells in mp.values():
            if len(cells) >= 2:
                gid = len(col_groups)
                col_groups.append(tuple(cells))
                for i in cells:
                    cell_to_groups[i].append(('c', gid))

    # Cells not in any duplicate group can never be black.
    initial_forced_white = [i for i in range(N2) if not cell_to_groups[i]]

    # Consecutive duplicate rule in row/column:
    # If two same numbers are adjacent in row/column, at least one black.
    # Since adjacent blacks forbidden, the other orthogonal neighbors forcing white
    # is naturally handled after one side is black.
    consecutive_pairs = []
    for r in range(n):
        for c in range(n - 1):
            if grid[r][c] == grid[r][c + 1]:
                consecutive_pairs.append((idx(r, c), idx(r, c + 1)))
    for c in range(n):
        for r in range(n - 1):
            if grid[r][c] == grid[r + 1][c]:
                consecutive_pairs.append((idx(r, c), idx(r + 1, c)))

    # Triple rule in row/column: a a a => middle must be black, ends white.
    triple_constraints = []
    for r in range(n):
        for c in range(n - 2):
            if grid[r][c] == grid[r][c + 1] == grid[r][c + 2]:
                triple_constraints.append((idx(r, c), idx(r, c + 1), idx(r, c + 2)))
    for c in range(n):
        for r in range(n - 2):
            if grid[r][c] == grid[r + 1][c] == grid[r + 2][c]:
                triple_constraints.append((idx(r, c), idx(r + 1, c), idx(r + 2, c)))

    # Pairwise conflict edges: same value in same row/column => not both white.
    conflict_edges = [[] for _ in range(N2)]
    for groups in (row_groups, col_groups):
        for cells in groups:
            m = len(cells)
            for a in range(m):
                ia = cells[a]
                for b in range(a + 1, m):
                    ib = cells[b]
                    conflict_edges[ia].append(ib)
                    conflict_edges[ib].append(ia)

    class State:
        __slots__ = ('color', 'queue')
        def __init__(self):
            self.color = [UNKNOWN] * N2
            self.queue = deque()

        def clone(self):
            s = State()
            s.color = self.color[:]
            return s

    def assign(state, i, val):
        cur = state.color[i]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        state.color[i] = val
        state.queue.append(i)
        return True

    def rowcol_group_check(state, cells):
        white_count = 0
        unknowns = []
        for i in cells:
            col = state.color[i]
            if col == WHITE:
                white_count += 1
                if white_count >= 2:
                    return False
            elif col == UNKNOWN:
                unknowns.append(i)
        if white_count == 1:
            for i in unknowns:
                if not assign(state, i, BLACK):
                    return False
        elif white_count == 0 and len(unknowns) == 1:
            if not assign(state, unknowns[0], WHITE):
                return False
        return True

    def connectivity_possible(state):
        # Necessary condition:
        # Unknown+white cells must be connected in possibility graph.
        possibles = [i for i, c in enumerate(state.color) if c != BLACK]
        if not possibles:
            return False
        seen = {possibles[0]}
        dq = deque([possibles[0]])
        while dq:
            x = dq.popleft()
            for y in neighbors[x]:
                if state.color[y] != BLACK and y not in seen:
                    seen.add(y)
                    dq.append(y)
        if len(seen) != len(possibles):
            return False

        # All fixed white cells must be connected through possible cells.
        whites = [i for i, c in enumerate(state.color) if c == WHITE]
        if whites:
            seen = {whites[0]}
            dq = deque([whites[0]])
            while dq:
                x = dq.popleft()
                for y in neighbors[x]:
                    if state.color[y] != BLACK and y not in seen:
                        seen.add(y)
                        dq.append(y)
            for w in whites:
                if w not in seen:
                    return False

        # Articulation-style forced white:
        # If removing an unknown cell disconnects existing white region / possible region components
        # that cannot otherwise reconnect, that cell must be white.
        # We apply a local but effective global test selectively.
        changed = True
        while changed:
            changed = False
            possibles = [i for i, c in enumerate(state.color) if c != BLACK]
            if not possibles:
                return False
            base = possibles[0]
            if state.color[base] == BLACK:
                return False
            for cut in list(possibles):
                if state.color[cut] != UNKNOWN:
                    continue
                start = None
                for p in possibles:
                    if p != cut:
                        start = p
                        break
                if start is None:
                    continue
                seen2 = {start}
                dq = deque([start])
                while dq:
                    x = dq.popleft()
                    for y in neighbors[x]:
                        if y == cut or state.color[y] == BLACK or y in seen2:
                            continue
                        seen2.add(y)
                        dq.append(y)
                bad = False
                for p in possibles:
                    if p == cut:
                        continue
                    if p not in seen2:
                        bad = True
                        break
                if bad:
                    if not assign(state, cut, WHITE):
                        return False
                    while state.queue:
                        if not propagate_queue(state):
                            return False
                    changed = True
                    break
        return True

    def propagate_queue(state):
        while state.queue:
            i = state.queue.popleft()
            col = state.color[i]

            if col == BLACK:
                # Adjacent blacks forbidden; neighbors forced white.
                for j in neighbors[i]:
                    if not assign(state, j, WHITE):
                        return False
            elif col == WHITE:
                # Any same-value conflicting white-pair impossible; neighbors in same duplicate group may need black.
                for j in conflict_edges[i]:
                    if state.color[j] == WHITE:
                        return False

            # Update row/col duplicate groups containing this cell.
            for kind, gid in cell_to_groups[i]:
                cells = row_groups[gid] if kind == 'r' else col_groups[gid]
                if not rowcol_group_check(state, cells):
                    return False

            # Consecutive pair rule.
            for a, b in consecutive_pairs:
                ca = state.color[a]
                cb = state.color[b]
                if ca == WHITE and cb == WHITE:
                    return False
                if ca == BLACK:
                    if not assign(state, b, WHITE):
                        return False
                elif cb == BLACK:
                    if not assign(state, a, WHITE):
                        return False
                elif ca == UNKNOWN and cb == UNKNOWN:
                    pass

            # Triple rule.
            for a, b, c in triple_constraints:
                if not assign(state, b, BLACK):
                    return False
                if not assign(state, a, WHITE):
                    return False
                if not assign(state, c, WHITE):
                    return False

        return True

    def full_propagate(state):
        for i in initial_forced_white:
            if not assign(state, i, WHITE):
                return False

        # Seed local deductions from triple patterns.
        for a, b, c in triple_constraints:
            if not assign(state, b, BLACK):
                return False
            if not assign(state, a, WHITE):
                return False
            if not assign(state, c, WHITE):
                return False

        # Initial group checks.
        for cells in row_groups:
            if not rowcol_group_check(state, cells):
                return False
        for cells in col_groups:
            if not rowcol_group_check(state, cells):
                return False

        if not propagate_queue(state):
            return False

        # Iterative higher-level deductions.
        progress = True
        while progress:
            snapshot = tuple(state.color)
            if not apply_line_pattern_rules(state):
                return False
            if not propagate_queue(state):
                return False
            if not connectivity_possible(state):
                return False
            if not propagate_queue(state):
                return False
            progress = tuple(state.color) != snapshot

        return True

    def apply_line_pattern_rules(state):
        # Human-like line scanning:
        # For each duplicate group in row/col, if choosing white for one candidate would force contradiction
        # among the remaining candidates due to adjacency/group constraints, prune.
        for groups in (row_groups, col_groups):
            for cells in groups:
                unknowns = [i for i in cells if state.color[i] == UNKNOWN]
                whites = [i for i in cells if state.color[i] == WHITE]
                if len(whites) >= 2:
                    return False
                if len(whites) == 1:
                    for i in unknowns:
                        if not assign(state, i, BLACK):
                            return False
                    continue
                if len(unknowns) <= 1:
                    continue

                feasible_white = []
                for cand in unknowns:
                    t = state.clone()
                    if not assign(t, cand, WHITE):
                        continue
                    if not propagate_queue(t):
                        continue
                    # Only need lightweight local consistency + possibility connectivity.
                    ok = True
                    for kind2, gid2 in cell_to_groups[cand]:
                        grp = row_groups[gid2] if kind2 == 'r' else col_groups[gid2]
                        if not rowcol_group_check(t, grp):
                            ok = False
                            break
                    if ok and connectivity_possible(t):
                        feasible_white.append(cand)

                if not feasible_white:
                    return False
                if len(feasible_white) == 1:
                    if not assign(state, feasible_white[0], WHITE):
                        return False
                    for i in unknowns:
                        if i != feasible_white[0]:
                            if not assign(state, i, BLACK):
                                return False
                else:
                    white_set = set(feasible_white)
                    for i in unknowns:
                        if i not in white_set:
                            if not assign(state, i, BLACK):
                                return False
        return True

    def is_solved(state):
        if any(c == UNKNOWN for c in state.color):
            return False
        # White uniqueness.
        for cells in row_groups:
            if sum(state.color[i] == WHITE for i in cells) != 1:
                return False
        for cells in col_groups:
            if sum(state.color[i] == WHITE for i in cells) != 1:
                return False
        # No adjacent blacks.
        for i in range(N2):
            if state.color[i] == BLACK:
                for j in neighbors[i]:
                    if state.color[j] == BLACK:
                        return False
        # White connectivity.
        whites = [i for i in range(N2) if state.color[i] == WHITE]
        if not whites:
            return False
        seen = {whites[0]}
        dq = deque([whites[0]])
        while dq:
            x = dq.popleft()
            for y in neighbors[x]:
                if state.color[y] == WHITE and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(whites)

    def choose_branch_cell(state):
        # Prefer cells in many duplicate constraints, especially with black possibility.
        best = None
        best_score = -1
        for i, col in enumerate(state.color):
            if col != UNKNOWN:
                continue
            deg_dup = len(cell_to_groups[i]) * 10 + len(conflict_edges[i])
            deg_adj = len(neighbors[i])
            score = deg_dup + deg_adj
            if score > best_score:
                best_score = score
                best = i
        return best

    def branch_order(state, i):
        # Prefer black first for duplicate-heavy cells, unless impossible by local context.
        can_black = True
        for j in neighbors[i]:
            if state.color[j] == BLACK:
                can_black = False
                break
        in_dups = bool(cell_to_groups[i])
        if in_dups and can_black:
            return (BLACK, WHITE)
        return (WHITE, BLACK) if not can_black else (BLACK, WHITE)

    def dfs(state, depth=0):
        if not full_propagate(state):
            return None
        if is_solved(state):
            return state

        i = choose_branch_cell(state)
        if i is None:
            return None

        for val in branch_order(state, i):
            t = state.clone()
            if not assign(t, i, val):
                continue
            if not propagate_queue(t):
                continue
            if not connectivity_possible(t):
                continue
            res = dfs(t, depth + 1)
            if res is not None:
                return res
        return None

    state = State()
    res = dfs(state)
    if res is None:
        return "No Solution"

    ans = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if res.color[idx(r, c)] == BLACK else None)
        ans.append(row)
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 2, 2], [0, 0, 3, 3, 3, 4, 5, 6], [7, 8, 3, 3, 3, 9, 9, 6], [7, 8, 3, 3, 3, 9, 9, 6], [7, 10, 10, 11, 12, 9, 9, 6], [7, 10, 10, 11, 12, 9, 9, 6], [13, 13, 13, 11, 12, 14, 14, 6], [13, 13, 13, 15, 15, 16, 16, 16]], 'data': [[2, None, None, None, 0, None, None, None], [None, None, None, None, None, None, 1, None], [None, 0, None, None, None, 2, None, None], [None, None, None, None, None, None, None, None], [None, 1, None, 2, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, None, None, 0, None, None]]}

from collections import defaultdict, deque
from itertools import combinations

B = 1
W = 0
U = -1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    cells = [(r, c) for r in range(n) for c in range(n)]

    reg_cells = defaultdict(list)
    reg_clue = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            reg_cells[rid].append((r, c))
            if data[r][c] is not None:
                reg_clue[rid] = data[r][c]

    if any(rid not in reg_clue for rid in reg_cells):
        # General solver expects every region to carry exactly one clue somewhere.
        return "No Solution"

    reg_ids = sorted(reg_cells)
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}

    orth = {}
    diag = {}
    for r in range(n):
        for c in range(n):
            o = []
            d = []
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                rr, cc = r+dr, c+dc
                if 0 <= rr < n and 0 <= cc < n:
                    o.append((rr, cc))
            for dr, dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                rr, cc = r+dr, c+dc
                if 0 <= rr < n and 0 <= cc < n:
                    d.append((rr, cc))
            orth[(r,c)] = o
            diag[(r,c)] = d

    # Precompute maximal straight segments for rule 3.
    segments = []
    cell_to_segments = defaultdict(list)

    # Horizontal segments bounded by region changes / borders, but "uninterrupted straight white segment"
    # means contiguous white run in a row. We enforce every possible contiguous run among cells with no black inside
    # by using automaton-style local propagation on whole rows/cols. For pruning, we also keep maximal border-to-border line.
    # The exact region-count condition on every white run is handled dynamically in validation/propagation.
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    lines = rows + cols

    # Candidate black patterns for each region from clue + non-touch orthogonally.
    region_patterns = {}
    cell_to_region_patterns = defaultdict(list)

    for rid in reg_ids:
        rcells = reg_cells[rid]
        k = reg_clue[rid]
        m = len(rcells)
        pats = []
        if k < 0 or k > m:
            return "No Solution"
        for comb in combinations(range(m), k):
            blackset = set(rcells[i] for i in comb)
            ok = True
            for cell in blackset:
                for nb in orth[cell]:
                    if nb in blackset:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                bits = [W] * m
                for i in comb:
                    bits[i] = B
                pats.append(tuple(bits))
        if not pats:
            return "No Solution"
        region_patterns[rid] = pats
        for pi, pat in enumerate(pats):
            for i, cell in enumerate(rcells):
                if pat[i] == B:
                    cell_to_region_patterns[cell].append((rid, pi))

    # State
    assignment = {cell: U for cell in cells}
    active_patterns = {rid: set(range(len(region_patterns[rid]))) for rid in reg_ids}

    def set_cell(cell, val, queue):
        cur = assignment[cell]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        assignment[cell] = val
        queue.append(('cell', cell))
        return True

    def recompute_region_allowed(rid):
        rcells = reg_cells[rid]
        pats = region_patterns[rid]
        alive = active_patterns[rid]
        new_alive = set()
        for pi in alive:
            pat = pats[pi]
            ok = True
            for i, cell in enumerate(rcells):
                a = assignment[cell]
                if a != U and a != pat[i]:
                    ok = False
                    break
            if ok:
                new_alive.add(pi)
        return new_alive

    def line_run_valid_partial(line):
        # Any fully determined white run may span at most 2 distinct regions.
        # If a run includes unknowns, we only reject when impossible already:
        # for any subsegment with no black and all determined white except unknowns, if determined distinct regions > 2
        # and unknowns cannot break because none are forced black yet; however unknowns may become black, so weak pruning only.
        i = 0
        L = len(line)
        while i < L:
            if assignment[line[i]] == B:
                i += 1
                continue
            j = i
            regions_seen = set()
            all_known = True
            while j < L and assignment[line[j]] != B:
                if assignment[line[j]] == U:
                    all_known = False
                elif assignment[line[j]] == W:
                    regions_seen.add(region[line[j][0]][line[j][1]])
                j += 1
            if all_known and len(regions_seen) > 2:
                return False
            i = j
        return True

    def line_deduce(line, queue):
        # Human-style row/col deduction for rule 3.
        # If in a black-free interval there are already white cells from >=3 regions, contradiction.
        # If there are white cells from exactly 2 regions and an unknown in a third region connected between no black barrier,
        # that unknown cannot be white unless a black occurs before it splits the run. We implement a safe local version:
        # in any maximal interval between known blacks, if whites from 2 regions exist, then any unknown belonging to a third
        # region and lying between existing whites in same interval must be black.
        L = len(line)
        black_pos = [-1] + [i for i, cell in enumerate(line) if assignment[cell] == B] + [L]
        for bi in range(len(black_pos)-1):
            a, b = black_pos[bi] + 1, black_pos[bi+1] - 1
            if a > b:
                continue
            regs_white = set()
            unknowns = []
            for i in range(a, b+1):
                cell = line[i]
                av = assignment[cell]
                if av == W:
                    regs_white.add(region[cell[0]][cell[1]])
                elif av == U:
                    unknowns.append((i, cell))
            if len(regs_white) > 2:
                return False
            if len(regs_white) == 2:
                for i, cell in unknowns:
                    if region[cell[0]][cell[1]] not in regs_white:
                        if not set_cell(cell, B, queue):
                            return False
        return True

    def white_connectivity_possible():
        white_cells = [cell for cell in cells if assignment[cell] != B]
        if not white_cells:
            return False
        start = None
        for cell in white_cells:
            if assignment[cell] == W:
                start = cell
                break
        if start is None:
            start = white_cells[0]
        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            for nb in orth[cur]:
                if assignment[nb] != B and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(white_cells)

    def white_connected_final():
        white_cells = [cell for cell in cells if assignment[cell] == W]
        if not white_cells:
            return False
        seen = {white_cells[0]}
        dq = deque([white_cells[0]])
        while dq:
            cur = dq.popleft()
            for nb in orth[cur]:
                if assignment[nb] == W and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(white_cells)

    def no_black_touch_ok():
        for cell, val in assignment.items():
            if val == B:
                for nb in orth[cell]:
                    if assignment[nb] == B:
                        return False
        return True

    def propagate():
        queue = deque(('region', rid) for rid in reg_ids)
        while queue:
            typ, obj = queue.popleft()
            if typ == 'cell':
                cell = obj
                # Black orthogonal exclusion.
                if assignment[cell] == B:
                    for nb in orth[cell]:
                        if not set_cell(nb, W, queue):
                            return False
                # Update region of this cell.
                queue.append(('region', region[cell[0]][cell[1]]))
                # Update lines containing this cell.
                queue.append(('line_row', cell[0]))
                queue.append(('line_col', cell[1]))
            elif typ == 'region':
                rid = obj
                new_alive = recompute_region_allowed(rid)
                if not new_alive:
                    return False
                if new_alive != active_patterns[rid]:
                    active_patterns[rid] = new_alive
                rcells = reg_cells[rid]
                pats = region_patterns[rid]
                for i, cell in enumerate(rcells):
                    vals = {pats[pi][i] for pi in active_patterns[rid]}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        if not set_cell(cell, v, queue):
                            return False
            elif typ == 'line_row':
                if not line_deduce(rows[obj], queue):
                    return False
                if not line_run_valid_partial(rows[obj]):
                    return False
            elif typ == 'line_col':
                if not line_deduce(cols[obj], queue):
                    return False
                if not line_run_valid_partial(cols[obj]):
                    return False

            if not no_black_touch_ok():
                return False
            if not white_connectivity_possible():
                return False

        # Additional articulation-style forced white:
        # any unknown cell whose turning black disconnects possible white graph must be white.
        changed = True
        while changed:
            changed = False
            unknowns = [cell for cell in cells if assignment[cell] == U]
            for cell in unknowns:
                assignment[cell] = B
                possible = no_black_touch_ok() and white_connectivity_possible()
                assignment[cell] = U
                if not possible:
                    if not set_cell(cell, W, queue):
                        return False
                    changed = True
            while queue:
                typ, obj = queue.popleft()
                if typ == 'cell':
                    cell = obj
                    if assignment[cell] == B:
                        for nb in orth[cell]:
                            if not set_cell(nb, W, queue):
                                return False
                    queue.append(('region', region[cell[0]][cell[1]]))
                    queue.append(('line_row', cell[0]))
                    queue.append(('line_col', cell[1]))
                elif typ == 'region':
                    rid = obj
                    new_alive = recompute_region_allowed(rid)
                    if not new_alive:
                        return False
                    if new_alive != active_patterns[rid]:
                        active_patterns[rid] = new_alive
                    rcells = reg_cells[rid]
                    pats = region_patterns[rid]
                    for i, c in enumerate(rcells):
                        vals = {pats[pi][i] for pi in active_patterns[rid]}
                        if len(vals) == 1:
                            v = next(iter(vals))
                            if not set_cell(c, v, queue):
                                return False
                elif typ == 'line_row':
                    if not line_deduce(rows[obj], queue):
                        return False
                    if not line_run_valid_partial(rows[obj]):
                        return False
                elif typ == 'line_col':
                    if not line_deduce(cols[obj], queue):
                        return False
                    if not line_run_valid_partial(cols[obj]):
                        return False
                if not no_black_touch_ok():
                    return False
                if not white_connectivity_possible():
                    return False

        return True

    def final_check():
        for rid in reg_ids:
            cnt = sum(assignment[cell] == B for cell in reg_cells[rid])
            if cnt != reg_clue[rid]:
                return False
        if any(assignment[cell] == U for cell in cells):
            return False
        if not no_black_touch_ok():
            return False
        for line in lines:
            i = 0
            L = len(line)
            while i < L:
                if assignment[line[i]] == B:
                    i += 1
                    continue
                regs = set()
                has_white = False
                j = i
                while j < L and assignment[line[j]] != B:
                    if assignment[line[j]] == W:
                        has_white = True
                        regs.add(region[line[j][0]][line[j][1]])
                    j += 1
                if has_white and len(regs) > 2:
                    return False
                i = j
        if not white_connected_final():
            return False
        return True

    def snapshot():
        return (
            assignment.copy(),
            {rid: s.copy() for rid, s in active_patterns.items()}
        )

    def restore(snap):
        a, ap = snap
        assignment.clear()
        assignment.update(a)
        active_patterns.clear()
        active_patterns.update({rid: s.copy() for rid, s in ap.items()})

    def choose_branch():
        # Best-first: smallest region pattern set >1, else most constrained unknown cell.
        best_rid = None
        best_size = 10**9
        for rid in reg_ids:
            sz = len(active_patterns[rid])
            if 1 < sz < best_size:
                best_size = sz
                best_rid = rid
        if best_rid is not None:
            return ('region', best_rid)

        best_cell = None
        best_score = -1
        for cell in cells:
            if assignment[cell] == U:
                score = 0
                rid = region[cell[0]][cell[1]]
                pats = region_patterns[rid]
                alive = active_patterns[rid]
                vals = {pats[pi][reg_cells[rid].index(cell)] for pi in alive}
                if len(vals) == 2:
                    score += 3
                score += sum(assignment[nb] != U for nb in orth[cell]) * 2
                score += sum(assignment[nb] == W for nb in orth[cell])
                if score > best_score:
                    best_score = score
                    best_cell = cell
        if best_cell is not None:
            return ('cell', best_cell)
        return None

    def search():
        if not propagate():
            return False
        if all(assignment[cell] != U for cell in cells):
            return final_check()

        choice = choose_branch()
        if choice is None:
            return final_check()

        kind, obj = choice
        snap = snapshot()

        if kind == 'region':
            rid = obj
            pats = list(active_patterns[rid])

            # Order patterns by compatibility with neighbors and connectivity.
            def pat_score(pi):
                pat = region_patterns[rid][pi]
                score = 0
                for i, cell in enumerate(reg_cells[rid]):
                    if pat[i] == W:
                        score += 1
                        score += sum(assignment[nb] != B for nb in orth[cell])
                return -score

            for pi in sorted(pats, key=pat_score):
                restore(snap)
                q = deque()
                active_patterns[rid] = {pi}
                q.append(('region', rid))
                ok = True
                while q and ok:
                    typ, obj2 = q.popleft()
                    if typ == 'region':
                        new_alive = recompute_region_allowed(obj2)
                        if not new_alive:
                            ok = False
                            break
                        active_patterns[obj2] = new_alive
                        rcells = reg_cells[obj2]
                        pats2 = region_patterns[obj2]
                        for i, cell in enumerate(rcells):
                            vals = {pats2[pj][i] for pj in active_patterns[obj2]}
                            if len(vals) == 1:
                                if not set_cell(cell, next(iter(vals)), q):
                                    ok = False
                                    break
                    elif typ == 'cell':
                        cell = obj2
                        if assignment[cell] == B:
                            for nb in orth[cell]:
                                if not set_cell(nb, W, q):
                                    ok = False
                                    break
                        if ok:
                            q.append(('region', region[cell[0]][cell[1]]))
                            q.append(('line_row', cell[0]))
                            q.append(('line_col', cell[1]))
                    elif typ == 'line_row':
                        if not line_deduce(rows[obj2], q) or not line_run_valid_partial(rows[obj2]):
                            ok = False
                    elif typ == 'line_col':
                        if not line_deduce(cols[obj2], q) or not line_run_valid_partial(cols[obj2]):
                            ok = False
                    if ok and (not no_black_touch_ok() or not white_connectivity_possible()):
                        ok = False
                if ok and search():
                    return True
            restore(snap)
            return False

        else:
            cell = obj
            # Prefer black first if still allowed, because it tends to trigger more propagation.
            for val in (B, W):
                restore(snap)
                q = deque()
                if not set_cell(cell, val, q):
                    continue
                ok = True
                while q and ok:
                    typ, obj2 = q.popleft()
                    if typ == 'cell':
                        c = obj2
                        if assignment[c] == B:
                            for nb in orth[c]:
                                if not set_cell(nb, W, q):
                                    ok = False
                                    break
                        if ok:
                            q.append(('region', region[c[0]][c[1]]))
                            q.append(('line_row', c[0]))
                            q.append(('line_col', c[1]))
                    elif typ == 'region':
                        rid = obj2
                        new_alive = recompute_region_allowed(rid)
                        if not new_alive:
                            ok = False
                            break
                        active_patterns[rid] = new_alive
                        rcells = reg_cells[rid]
                        pats = region_patterns[rid]
                        for i, c in enumerate(rcells):
                            vals = {pats[pi][i] for pi in active_patterns[rid]}
                            if len(vals) == 1:
                                if not set_cell(c, next(iter(vals)), q):
                                    ok = False
                                    break
                    elif typ == 'line_row':
                        if not line_deduce(rows[obj2], q) or not line_run_valid_partial(rows[obj2]):
                            ok = False
                    elif typ == 'line_col':
                        if not line_deduce(cols[obj2], q) or not line_run_valid_partial(cols[obj2]):
                            ok = False
                    if ok and (not no_black_touch_ok() or not white_connectivity_possible()):
                        ok = False
                if ok and search():
                    return True
            restore(snap)
            return False

    if not search():
        return "No Solution"

    ans = [[None if assignment[(r, c)] == W else 'B' for c in range(n)] for r in range(n)]
    return str(ans)

