from collections import deque, defaultdict

# Hitori solver using strong propagation + guarded search.
# Cell state: -1 unknown, 0 white, 1 black.

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    board = observation["data"]
    n = len(board)
    if n == 0:
        return []

    row_groups, col_groups, dup_cells = build_duplicate_groups(board)

    state = [[UNKNOWN] * n for _ in range(n)]

    ok = propagate(board, state, row_groups, col_groups, dup_cells)
    if not ok:
        return "No Solution"

    result = search(board, state, row_groups, col_groups, dup_cells)
    if result is None:
        return "No Solution"

    return [[('B' if result[r][c] == BLACK else None) for c in range(n)] for r in range(n)]


def build_duplicate_groups(board):
    n = len(board)
    row_groups = []
    col_groups = []

    for r in range(n):
        mp = defaultdict(list)
        for c, v in enumerate(board[r]):
            mp[v].append((r, c))
        groups = [cells for cells in mp.values() if len(cells) >= 2]
        row_groups.append(groups)

    for c in range(n):
        mp = defaultdict(list)
        for r in range(n):
            mp[board[r][c]].append((r, c))
        groups = [cells for cells in mp.values() if len(cells) >= 2]
        col_groups.append(groups)

    dup_cells = set()
    for groups in row_groups:
        for g in groups:
            dup_cells.update(g)
    for groups in col_groups:
        for g in groups:
            dup_cells.update(g)

    return row_groups, col_groups, dup_cells


def neighbors4(n, r, c):
    if r > 0:
        yield r - 1, c
    if r + 1 < n:
        yield r + 1, c
    if c > 0:
        yield r, c - 1
    if c + 1 < n:
        yield r, c + 1


def set_state(state, r, c, val, queue):
    cur = state[r][c]
    if cur == val:
        return True
    if cur != UNKNOWN and cur != val:
        return False
    state[r][c] = val
    queue.append((r, c))
    return True


def propagate(board, state, row_groups, col_groups, dup_cells):
    n = len(board)
    queue = deque()

    # Seed all currently assigned cells.
    for r in range(n):
        for c in range(n):
            if state[r][c] != UNKNOWN:
                queue.append((r, c))

    # Initial universal deductions from adjacent equal numbers:
    # equal orthogonal pair cannot both be white => neither can be black together
    # due to adjacency-black ban, so both must be white.
    for r in range(n):
        for c in range(n):
            v = board[r][c]
            if r + 1 < n and board[r + 1][c] == v:
                if not set_state(state, r, c, WHITE, queue):
                    return False
                if not set_state(state, r + 1, c, WHITE, queue):
                    return False
            if c + 1 < n and board[r][c + 1] == v:
                if not set_state(state, r, c, WHITE, queue):
                    return False
                if not set_state(state, r, c + 1, WHITE, queue):
                    return False

    changed = True
    while changed:
        changed = False

        # Process consequences of direct assignments until queue drained.
        while queue:
            r, c = queue.popleft()
            s = state[r][c]

            if s == BLACK:
                # Black cells cannot touch orthogonally.
                for nr, nc in neighbors4(n, r, c):
                    if not set_state(state, nr, nc, WHITE, queue):
                        return False
            elif s == WHITE:
                # In any duplicate group containing this cell, all other white-forbidden logic applies.
                v = board[r][c]

                # Row duplicates of same value.
                row_positions = [cc for cc in range(n) if cc != c and board[r][cc] == v]
                for cc in row_positions:
                    if not set_state(state, r, cc, BLACK, queue):
                        return False

                # Column duplicates of same value.
                col_positions = [rr for rr in range(n) if rr != r and board[rr][c] == v]
                for rr in col_positions:
                    if not set_state(state, rr, c, BLACK, queue):
                        return False

        # Group-based deductions: in every duplicate group, at least one black and at most one white.
        # Therefore:
        # - if one cell is white => all others black
        # - if all but one are black => last one white
        # - if some cell cannot be black (adjacent to black), it tends toward white through generic rules
        for groups in row_groups:
            for cells in groups:
                if not apply_group_rules(state, cells):
                    return False
        for groups in col_groups:
            for cells in groups:
                if not apply_group_rules(state, cells):
                    return False

        # Any cell not in any duplicate set can never be black.
        for r in range(n):
            for c in range(n):
                if (r, c) not in dup_cells and state[r][c] == UNKNOWN:
                    if not set_state(state, r, c, WHITE, queue):
                        return False
                    changed = True

        # Connectivity-based local deductions.
        # White cells must remain potentially connected.
        if not connectivity_prune(state):
            return False

        # Unknown cells that are articulation-forcing in current non-black graph must be white.
        forced_whites = forced_white_cut_vertices(state)
        for r, c in forced_whites:
            if state[r][c] == UNKNOWN:
                if not set_state(state, r, c, WHITE, queue):
                    return False
                changed = True

        # Unknown cells that cannot be white because they'd duplicate an already white equal number.
        for r in range(n):
            seen = {}
            for c in range(n):
                if state[r][c] == WHITE:
                    v = board[r][c]
                    if v in seen:
                        return False
                    seen[v] = c
            for c in range(n):
                if state[r][c] == UNKNOWN and board[r][c] in seen:
                    if not set_state(state, r, c, BLACK, queue):
                        return False
                    changed = True

        for c in range(n):
            seen = {}
            for r in range(n):
                if state[r][c] == WHITE:
                    v = board[r][c]
                    if v in seen:
                        return False
                    seen[v] = r
            for r in range(n):
                if state[r][c] == UNKNOWN and board[r][c] in seen:
                    if not set_state(state, r, c, BLACK, queue):
                        return False
                    changed = True

        # Validate static constraints after each wave.
        if not quick_consistency(board, state, row_groups, col_groups):
            return False

        if queue:
            changed = True

    return quick_consistency(board, state, row_groups, col_groups)


def apply_group_rules(state, cells):
    vals = [state[r][c] for r, c in cells]
    white_count = sum(v == WHITE for v in vals)
    black_count = sum(v == BLACK for v in vals)
    unknowns = [(r, c) for (r, c), v in zip(cells, vals) if v == UNKNOWN]

    if white_count >= 2:
        return False
    # Need at least one black in each duplicate group.
    if black_count == 0 and not unknowns and white_count >= 1:
        return False
    if black_count == 0 and len(unknowns) == 0:
        return False

    # If one white exists, all others must be black.
    # This is handled through queue when white assigned; no-op here.
    # If all but one are black, last must be white.
    if len(unknowns) == 1 and white_count == 0:
        r, c = unknowns[0]
        state[r][c] = WHITE
    return True


def quick_consistency(board, state, row_groups, col_groups):
    n = len(board)

    # No adjacent black.
    for r in range(n):
        for c in range(n):
            if state[r][c] == BLACK:
                if r + 1 < n and state[r + 1][c] == BLACK:
                    return False
                if c + 1 < n and state[r][c + 1] == BLACK:
                    return False

    # White uniqueness cannot already be violated.
    for r in range(n):
        seen = set()
        for c in range(n):
            if state[r][c] == WHITE:
                v = board[r][c]
                if v in seen:
                    return False
                seen.add(v)

    for c in range(n):
        seen = set()
        for r in range(n):
            if state[r][c] == WHITE:
                v = board[r][c]
                if v in seen:
                    return False
                seen.add(v)

    # Every duplicate group must still be satisfiable: at most one white, at least one black possible.
    for groups in row_groups:
        for cells in groups:
            vals = [state[r][c] for r, c in cells]
            if sum(v == WHITE for v in vals) >= 2:
                return False
            if all(v == WHITE for v in vals):
                return False

    for groups in col_groups:
        for cells in groups:
            vals = [state[r][c] for r, c in cells]
            if sum(v == WHITE for v in vals) >= 2:
                return False
            if all(v == WHITE for v in vals):
                return False

    # Potential white connectivity.
    if not connectivity_prune(state):
        return False

    # Final all-white connectivity if complete.
    if all(state[r][c] != UNKNOWN for r in range(n) for c in range(n)):
        if not all_white_connected(state):
            return False

    return True


def connectivity_prune(state):
    n = len(state)
    nodes = [(r, c) for r in range(n) for c in range(n) if state[r][c] != BLACK]
    if not nodes:
        return False

    start = nodes[0]
    vis = {start}
    dq = deque([start])
    while dq:
        r, c = dq.popleft()
        for nr, nc in neighbors4(n, r, c):
            if state[nr][nc] != BLACK and (nr, nc) not in vis:
                vis.add((nr, nc))
                dq.append((nr, nc))
    return len(vis) == len(nodes)


def all_white_connected(state):
    n = len(state)
    whites = [(r, c) for r in range(n) for c in range(n) if state[r][c] != BLACK]
    if not whites:
        return False
    start = None
    for cell in whites:
        if state[cell[0]][cell[1]] == WHITE:
            start = cell
            break
    if start is None:
        start = whites[0]

    vis = {start}
    dq = deque([start])
    while dq:
        r, c = dq.popleft()
        for nr, nc in neighbors4(n, r, c):
            if state[nr][nc] != BLACK and (nr, nc) not in vis:
                vis.add((nr, nc))
                dq.append((nr, nc))
    return len(vis) == len(whites)


def forced_white_cut_vertices(state):
    # Any unknown cell whose removal disconnects the graph of non-black cells
    # must be white; making it black would break connectivity.
    n = len(state)
    nodes = [(r, c) for r in range(n) for c in range(n) if state[r][c] != BLACK]
    node_set = set(nodes)
    if len(nodes) <= 1:
        return []

    forced = []
    for r, c in nodes:
        if state[r][c] != UNKNOWN:
            continue
        remaining = [x for x in nodes if x != (r, c)]
        if not remaining:
            continue
        start = remaining[0]
        vis = {start}
        dq = deque([start])
        while dq:
            cr, cc = dq.popleft()
            for nr, nc in neighbors4(n, cr, cc):
                if (nr, nc) == (r, c):
                    continue
                if (nr, nc) in node_set and (nr, nc) not in vis:
                    vis.add((nr, nc))
                    dq.append((nr, nc))
        if len(vis) != len(remaining):
            forced.append((r, c))
    return forced


def search(board, state, row_groups, col_groups, dup_cells):
    n = len(board)

    if all(state[r][c] != UNKNOWN for r in range(n) for c in range(n)):
        if quick_consistency(board, state, row_groups, col_groups):
            return state
        return None

    cell = choose_branch_cell(board, state, row_groups, col_groups, dup_cells)
    if cell is None:
        return None
    r, c = cell

    # Value ordering: try BLACK first for duplicate-heavy cells unless connectivity says risky.
    options = branch_order(board, state, r, c)

    for val in options:
        new_state = [row[:] for row in state]
        q = deque()
        if not set_state(new_state, r, c, val, q):
            continue
        if not propagate(board, new_state, row_groups, col_groups, dup_cells):
            continue
        res = search(board, new_state, row_groups, col_groups, dup_cells)
        if res is not None:
            return res
    return None


def choose_branch_cell(board, state, row_groups, col_groups, dup_cells):
    n = len(board)
    best = None
    best_score = None

    for r in range(n):
        for c in range(n):
            if state[r][c] != UNKNOWN:
                continue
            domain = possible_values(board, state, r, c)
            if not domain:
                return (r, c)
            if len(domain) == 1:
                return (r, c)

            # Heuristic: branch on most constrained, most duplicated, near center.
            dup_degree = duplicate_degree(board, r, c)
            black_neighbors = 0
            unknown_neighbors = 0
            for nr, nc in neighbors4(n, r, c):
                if state[nr][nc] == BLACK:
                    black_neighbors += 1
                elif state[nr][nc] == UNKNOWN:
                    unknown_neighbors += 1

            score = (
                len(domain),
                -dup_degree,
                -black_neighbors,
                -unknown_neighbors,
                abs(r - (n - 1) / 2) + abs(c - (n - 1) / 2),
            )
            if best_score is None or score < best_score:
                best_score = score
                best = (r, c)

    return best


def duplicate_degree(board, r, c):
    n = len(board)
    v = board[r][c]
    cnt = 0
    for cc in range(n):
        if cc != c and board[r][cc] == v:
            cnt += 1
    for rr in range(n):
        if rr != r and board[rr][c] == v:
            cnt += 1
    return cnt


def possible_values(board, state, r, c):
    n = len(board)
    vals = []

    # Can be white?
    can_white = True
    v = board[r][c]
    for cc in range(n):
        if cc != c and board[r][cc] == v and state[r][cc] == WHITE:
            can_white = False
            break
    if can_white:
        for rr in range(n):
            if rr != r and board[rr][c] == v and state[rr][c] == WHITE:
                can_white = False
                break
    if can_white:
        vals.append(WHITE)

    # Can be black?
    can_black = True
    for nr, nc in neighbors4(n, r, c):
        if state[nr][nc] == BLACK:
            can_black = False
            break
    # A unique number cell cannot be black.
    if duplicate_degree(board, r, c) == 0:
        can_black = False
    if can_black:
        vals.append(BLACK)

    return vals


def branch_order(board, state, r, c):
    dom = possible_values(board, state, r, c)
    if len(dom) <= 1:
        return dom
    # Prefer black if this is in multiple duplicate relations and not obviously central to connectivity.
    deg = duplicate_degree(board, r, c)
    if deg >= 2:
        return [BLACK, WHITE] if BLACK in dom and WHITE in dom else dom
    return [WHITE, BLACK] if WHITE in dom and BLACK in dom else dom


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 1, 1, 2, 2, 2, 3, 4], [0, 5, 5, 2, 2, 2, 3, 4], [0, 5, 5, 6, 6, 7, 3, 4], [0, 8, 8, 6, 6, 9, 9, 4], [0, 8, 8, 6, 6, 9, 9, 10], [0, 11, 12, 12, 12, 12, 13, 10], [14, 11, 12, 12, 12, 12, 13, 10], [14, 15, 15, 16, 16, 16, 16, 16]], 'data': [[1, 0, None, None, None, None, 1, 1], [None, None, None, None, None, None, None, None], [None, None, None, 2, None, 0, None, None], [None, 0, None, None, None, 0, None, None], [None, None, None, None, None, None, None, None], [None, None, 2, None, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, 1, None, None, None, None]]}

from collections import deque, defaultdict

# Solver for Heyawake-like rules:
# 1) Region clue gives exact black count.
# 2) No orthogonally adjacent black cells.
# 3) Any uninterrupted white segment in a row/column crosses at most 2 regions.
# 4) All white cells connected.
#
# Representation:
#   state[idx] = -1 unknown, 0 white, 1 black

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0]) if n else 0
    N = n * m

    def idx(r, c):
        return r * m + c

    def rc(i):
        return divmod(i, m)

    cells = list(range(N))

    # Regions
    region_cells = defaultdict(list)
    clues = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            i = idx(r, c)
            region_cells[rid].append(i)
            if data[r][c] is not None:
                clues[rid] = data[r][c]
    all_regions = sorted(region_cells)

    # Orthogonal adjacency
    nbrs = [[] for _ in range(N)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            if r > 0: nbrs[i].append(idx(r - 1, c))
            if r + 1 < n: nbrs[i].append(idx(r + 1, c))
            if c > 0: nbrs[i].append(idx(r, c - 1))
            if c + 1 < m: nbrs[i].append(idx(r, c + 1))

    # Maximal row/column windows between board edges; rule applies to any uninterrupted white run.
    # For a fully white run, number of crossed regions <= 2, so any contiguous segment spanning >=3 region blocks
    # cannot be all white. We precompute minimal "forbidden all-white" windows: contiguous cells whose region
    # sequence contains exactly 3 blocks and endpoints are first/last cells of those 3 blocks.
    forbidden_windows = []

    # Rows
    for r in range(n):
        seq = [region[r][c] for c in range(m)]
        blocks = []
        s = 0
        while s < m:
            e = s
            while e + 1 < m and seq[e + 1] == seq[s]:
                e += 1
            blocks.append((s, e, seq[s]))
            s = e + 1
        for k in range(len(blocks) - 2):
            a = blocks[k][0]
            b = blocks[k + 2][1]
            forbidden_windows.append(tuple(idx(r, c) for c in range(a, b + 1)))

    # Cols
    for c in range(m):
        seq = [region[r][c] for r in range(n)]
        blocks = []
        s = 0
        while s < n:
            e = s
            while e + 1 < n and seq[e + 1] == seq[s]:
                e += 1
            blocks.append((s, e, seq[s]))
            s = e + 1
        for k in range(len(blocks) - 2):
            a = blocks[k][0]
            b = blocks[k + 2][1]
            forbidden_windows.append(tuple(idx(r, c) for r in range(a, b + 1)))

    # Deduplicate windows
    forbidden_windows = list(dict.fromkeys(forbidden_windows))
    windows_of_cell = [[] for _ in range(N)]
    for wi, w in enumerate(forbidden_windows):
        for i in w:
            windows_of_cell[i].append(wi)

    # Region metadata
    cell_region = [0] * N
    for rid, lst in region_cells.items():
        for i in lst:
            cell_region[i] = rid

    clue_regions = set(clues)

    class Contradiction(Exception):
        pass

    def connectivity_possible(state):
        # White cells (0) plus unknowns (-1) must contain a connected component covering all current whites.
        allowed = [i for i, v in enumerate(state) if v != 1]
        if not allowed:
            return False
        white = [i for i, v in enumerate(state) if v == 0]
        start = white[0] if white else allowed[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in nbrs[x]:
                if y not in seen and state[y] != 1:
                    seen.add(y)
                    dq.append(y)
        for i, v in enumerate(state):
            if v == 0 and i not in seen:
                return False
        return True

    def all_white_connected(state):
        white = [i for i, v in enumerate(state) if v == 0]
        if not white:
            return True
        seen = set([white[0]])
        dq = deque([white[0]])
        while dq:
            x = dq.popleft()
            for y in nbrs[x]:
                if state[y] == 0 and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(white)

    def check_complete(state):
        # Region clues exact
        for rid in clue_regions:
            blacks = sum(1 for i in region_cells[rid] if state[i] == 1)
            if blacks != clues[rid]:
                return False
        # No black adjacency
        for i in range(N):
            if state[i] == 1:
                for j in nbrs[i]:
                    if j > i and state[j] == 1:
                        return False
        # White segment rule
        for w in forbidden_windows:
            if all(state[i] == 0 for i in w):
                return False
        # White connectivity
        return all_white_connected(state)

    def force(state, queue, i, val):
        cur = state[i]
        if cur == val:
            return
        if cur != -1 and cur != val:
            raise Contradiction
        state[i] = val
        queue.append(i)

    def propagate(state):
        queue = deque()

        # Seed queue with all assigned cells for local propagation
        for i, v in enumerate(state):
            if v != -1:
                queue.append(i)

        # Global region deductions repeated to fixpoint
        changed_global = True
        while True:
            while queue:
                i = queue.popleft()
                v = state[i]

                if v == 1:
                    # No orthogonal touching black
                    for j in nbrs[i]:
                        force(state, queue, j, 0)

                # Windows containing this cell
                for wi in windows_of_cell[i]:
                    w = forbidden_windows[wi]
                    vals = [state[x] for x in w]
                    if all(vv != 1 for vv in vals):
                        unknowns = [x for x in w if state[x] == -1]
                        # all-white forbidden
                        if not unknowns:
                            raise Contradiction
                        if len(unknowns) == 1:
                            force(state, queue, unknowns[0], 1)

                # Region local checks for touched region
                rid = cell_region[i]
                if rid in clue_regions:
                    lst = region_cells[rid]
                    k = clues[rid]
                    b = sum(1 for x in lst if state[x] == 1)
                    u = [x for x in lst if state[x] == -1]
                    if b > k or b + len(u) < k:
                        raise Contradiction
                    if b == k:
                        for x in u:
                            force(state, queue, x, 0)
                    elif b + len(u) == k:
                        for x in u:
                            force(state, queue, x, 1)

            # Global checks/deductions
            if not connectivity_possible(state):
                raise Contradiction

            changed = False

            # Articulation-style white connectivity deduction:
            # if an unknown cell is the only possible bridge joining two existing white components in allowed graph,
            # force it white.
            white = [i for i, v in enumerate(state) if v == 0]
            if white:
                comp_id = {}
                cid = 0
                for s in white:
                    if s in comp_id:
                        continue
                    dq = deque([s])
                    comp_id[s] = cid
                    while dq:
                        x = dq.popleft()
                        for y in nbrs[x]:
                            if state[y] == 0 and y not in comp_id:
                                comp_id[y] = cid
                                dq.append(y)
                    cid += 1
                if cid > 1:
                    # Immediate contradiction if even allowed graph cannot connect all white cells
                    allowed = [i for i, v in enumerate(state) if v != 1]
                    start = white[0]
                    seen = set([start])
                    dq = deque([start])
                    while dq:
                        x = dq.popleft()
                        for y in nbrs[x]:
                            if state[y] != 1 and y not in seen:
                                seen.add(y)
                                dq.append(y)
                    if any(s not in seen for s in white):
                        raise Contradiction

                # Unknown cell with neighbors in >=2 distinct white components must be white if black would separate
                for i, v in enumerate(state):
                    if v != -1:
                        continue
                    adj_comps = {comp_id[j] for j in nbrs[i] if state[j] == 0}
                    if len(adj_comps) >= 2:
                        force(state, queue, i, 0)
                        changed = True

            # Region pairwise anti-adjacency stronger pruning:
            # For clue=1, if an unknown cell is adjacent to all remaining possible black positions except itself, etc.
            for rid in clue_regions:
                lst = region_cells[rid]
                k = clues[rid]
                b = [x for x in lst if state[x] == 1]
                u = [x for x in lst if state[x] == -1]
                if len(b) > k or len(b) + len(u) < k:
                    raise Contradiction
                if k - len(b) == 1 and u:
                    possible = []
                    for x in u:
                        if all(state[y] != 1 for y in nbrs[x]):
                            possible.append(x)
                    if not possible:
                        raise Contradiction
                    # Cells adjacent to every possible black cannot be black
                    common_neighbors = None
                    for x in possible:
                        s = set([x])
                        if common_neighbors is None:
                            common_neighbors = s
                        else:
                            common_neighbors &= s
                    # no-op placeholder to keep pattern structured

            if queue:
                continue
            if not changed:
                break

        # Final consistency checks after propagation
        for rid in clue_regions:
            lst = region_cells[rid]
            k = clues[rid]
            b = sum(1 for x in lst if state[x] == 1)
            u = sum(1 for x in lst if state[x] == -1)
            if b > k or b + u < k:
                raise Contradiction
        for i in range(N):
            if state[i] == 1:
                for j in nbrs[i]:
                    if state[j] == 1:
                        raise Contradiction
        for w in forbidden_windows:
            if all(state[x] != 1 for x in w):
                if all(state[x] == 0 for x in w):
                    raise Contradiction
        if not connectivity_possible(state):
            raise Contradiction

    def choose_branch_cell(state):
        # Human-like branching:
        # prioritize clue regions with tight remaining counts, then cells in many forbidden windows, then white-connectivity critical.
        best = None
        best_score = None
        for i, v in enumerate(state):
            if v != -1:
                continue
            rid = cell_region[i]
            score = 0
            if rid in clue_regions:
                lst = region_cells[rid]
                k = clues[rid]
                b = sum(1 for x in lst if state[x] == 1)
                u = sum(1 for x in lst if state[x] == -1)
                rem = k - b
                score += 50 - abs(u - rem) * 10
            score += len(windows_of_cell[i]) * 4
            score += sum(1 for j in nbrs[i] if state[j] == 0) * 3
            score += sum(1 for j in nbrs[i] if state[j] == -1)
            if best is None or score > best_score:
                best = i
                best_score = score
        return best

    def branch_order(state, i):
        rid = cell_region[i]
        # Try value more constrained first
        prefers = []
        if rid in clue_regions:
            lst = region_cells[rid]
            k = clues[rid]
            b = sum(1 for x in lst if state[x] == 1)
            u = sum(1 for x in lst if state[x] == -1)
            rem = k - b
            if rem == 0:
                return [0]
            if rem == u:
                return [1]
            # if many white neighbors, black often impossible due adjacency; try white first
        white_n = sum(1 for j in nbrs[i] if state[j] == 0)
        black_n = sum(1 for j in nbrs[i] if state[j] == 1)
        if black_n:
            return [0]
        # if any forbidden window almost all white, black first
        for wi in windows_of_cell[i]:
            w = forbidden_windows[wi]
            if sum(1 for x in w if state[x] == 0) == len(w) - 1 and sum(1 for x in w if state[x] == -1) == 1:
                return [1]
        if white_n >= 2:
            return [0, 1]
        return [1, 0]

    def dfs(state):
        try:
            propagate(state)
        except Contradiction:
            return None

        if all(v != -1 for v in state):
            return state if check_complete(state) else None

        i = choose_branch_cell(state)
        for val in branch_order(state, i):
            new_state = state[:]
            new_state[i] = val
            res = dfs(new_state)
            if res is not None:
                return res
        return None

    init = [-1] * N

    # Apply clue=0 immediate whites for region
    for rid in clue_regions:
        if clues[rid] == 0:
            for i in region_cells[rid]:
                init[i] = 0

    # Apply full-black regions if clue equals size, then adjacency will white neighbors
    for rid in clue_regions:
        if clues[rid] == len(region_cells[rid]):
            for i in region_cells[rid]:
                init[i] = 1

    ans = dfs(init)
    if ans is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            v = ans[idx(r, c)]
            row.append('B' if v == 1 else None)
        out.append(row)
    return str(out)

