from collections import defaultdict, deque

# States:
# -1 unknown
#  0 white
#  1 black

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    idx = lambda r, c: r * n + c
    rc = lambda i: divmod(i, n)

    N = n * n
    values = [data[r][c] for r in range(n) for c in range(n)]

    neighbors = [[] for _ in range(N)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    row_groups = []
    col_groups = []

    for r in range(n):
        mp = defaultdict(list)
        for c in range(n):
            mp[data[r][c]].append(idx(r, c))
        for cells in mp.values():
            if len(cells) > 1:
                row_groups.append(tuple(cells))

    for c in range(n):
        mp = defaultdict(list)
        for r in range(n):
            mp[data[r][c]].append(idx(r, c))
        for cells in mp.values():
            if len(cells) > 1:
                col_groups.append(tuple(cells))

    groups_by_cell = [[] for _ in range(N)]
    all_groups = []
    for g in row_groups + col_groups:
        gi = len(all_groups)
        all_groups.append(g)
        for i in g:
            groups_by_cell[i].append(gi)

    def clone_state(state):
        return {
            'cell': state['cell'][:],
            'row_white': [d.copy() for d in state['row_white']],
            'col_white': [d.copy() for d in state['col_white']],
            'unknown_count': state['unknown_count'],
            'white_count': state['white_count'],
            'black_count': state['black_count'],
        }

    def initial_state():
        return {
            'cell': [-1] * N,
            'row_white': [defaultdict(int) for _ in range(n)],
            'col_white': [defaultdict(int) for _ in range(n)],
            'unknown_count': N,
            'white_count': 0,
            'black_count': 0,
        }

    def assign(state, i, color, queue):
        cur = state['cell'][i]
        if cur == color:
            return True
        if cur != -1:
            return False

        r, c = rc(i)
        v = values[i]

        state['cell'][i] = color
        state['unknown_count'] -= 1
        if color == 0:
            state['white_count'] += 1
            state['row_white'][r][v] += 1
            if state['row_white'][r][v] > 1:
                return False
            state['col_white'][c][v] += 1
            if state['col_white'][c][v] > 1:
                return False
        else:
            state['black_count'] += 1
            for nb in neighbors[i]:
                if state['cell'][nb] == 1:
                    return False

        queue.append(i)
        return True

    def component_info_on_nonblack(state):
        # Connectivity over cells that are not black: white + unknown.
        # If split into multiple components already, impossible.
        # Also compute articulation-like necessity for unknowns:
        # if an unknown is the only bridge among nonblack cells, it cannot be black.
        cell = state['cell']
        nonblack = [i for i in range(N) if cell[i] != 1]
        if not nonblack:
            return False, None, None

        seen = set()
        comps = []
        for s in nonblack:
            if s in seen:
                continue
            q = [s]
            seen.add(s)
            comp = []
            while q:
                x = q.pop()
                comp.append(x)
                for y in neighbors[x]:
                    if cell[y] != 1 and y not in seen:
                        seen.add(y)
                        q.append(y)
            comps.append(comp)

        if len(comps) > 1:
            return False, None, None

        # Tarjan articulation on the single nonblack graph.
        comp = comps[0]
        in_comp = set(comp)
        disc = {}
        low = {}
        parent = {}
        art = set()
        t = [0]

        def dfs(u):
            disc[u] = low[u] = t[0]
            t[0] += 1
            child = 0
            for v in neighbors[u]:
                if v not in in_comp:
                    continue
                if v not in disc:
                    parent[v] = u
                    child += 1
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if u not in parent and child > 1:
                        art.add(u)
                    if u in parent and low[v] >= disc[u]:
                        art.add(u)
                elif parent.get(u) != v:
                    low[u] = min(low[u], disc[v])

        dfs(comp[0])
        return True, in_comp, art

    def check_group_coverage(state, group):
        # In each duplicate-group, at most one white can survive.
        # Human-like deduction:
        # if one already white -> all others black
        # if all but one black -> last one white
        cell = state['cell']
        white = [i for i in group if cell[i] == 0]
        unknown = [i for i in group if cell[i] == -1]
        if len(white) > 1:
            return False, []
        implied = []
        if len(white) == 1:
            for i in unknown:
                implied.append((i, 1))
        else:
            # no white currently, must leave at least one nonblack:
            # if all but one black, last must be white
            black_count = len(group) - len(unknown)
            if black_count == len(group):
                return False, []
            if len(unknown) == 1:
                implied.append((unknown[0], 0))
        return True, implied

    def local_rules(state):
        queue = deque(i for i in range(N) if state['cell'][i] != -1)
        touched_groups = set()

        while True:
            while queue:
                i = queue.popleft()
                r, c = rc(i)
                cur = state['cell'][i]

                # Rule 1: black cells force orthogonal neighbors white.
                if cur == 1:
                    for nb in neighbors[i]:
                        if not assign(state, nb, 0, queue):
                            return False

                # Rule 2: any white duplicate forces peers in row/col duplicate groups black.
                for gi in groups_by_cell[i]:
                    if gi in touched_groups:
                        continue
                    ok, implied = check_group_coverage(state, all_groups[gi])
                    if not ok:
                        return False
                    for j, col in implied:
                        if not assign(state, j, col, queue):
                            return False
                    touched_groups.add(gi)

            # Rule 3: sweep all groups until stable.
            changed = False
            touched_groups.clear()
            for gi, g in enumerate(all_groups):
                ok, implied = check_group_coverage(state, g)
                if not ok:
                    return False
                for j, col in implied:
                    if state['cell'][j] == -1:
                        if not assign(state, j, col, queue):
                            return False
                        changed = True

            while queue:
                i = queue.popleft()
                cur = state['cell'][i]
                if cur == 1:
                    for nb in neighbors[i]:
                        if not assign(state, nb, 0, queue):
                            return False

            # Rule 4: connectivity of nonblack cells cannot already be broken.
            ok_conn, in_comp, arts = component_info_on_nonblack(state)
            if not ok_conn:
                return False

            # Rule 5: unknown articulation cells in current nonblack graph cannot be black.
            for a in arts:
                if state['cell'][a] == -1:
                    if not assign(state, a, 0, queue):
                        return False
                    changed = True

            while queue:
                i = queue.popleft()
                cur = state['cell'][i]
                if cur == 1:
                    for nb in neighbors[i]:
                        if not assign(state, nb, 0, queue):
                            return False

            # Rule 6: if a cell cannot be black due to immediate local contradiction, make it white.
            # Similarly if cannot be white due to duplicate counts, make it black.
            progress = False
            for i in range(N):
                if state['cell'][i] != -1:
                    continue
                r, c = rc(i)
                v = values[i]

                can_white = state['row_white'][r].get(v, 0) == 0 and state['col_white'][c].get(v, 0) == 0
                can_black = True
                for nb in neighbors[i]:
                    if state['cell'][nb] == 1:
                        can_black = False
                        break

                # stronger quick black test: if blacking this cell disconnects nonblack graph, cannot black
                if can_black:
                    tmp = clone_state(state)
                    q2 = deque()
                    if not assign(tmp, i, 1, q2):
                        can_black = False
                    else:
                        if not local_rules_shallow(tmp):
                            can_black = False

                if not can_white and not can_black:
                    return False
                if can_white and not can_black:
                    if not assign(state, i, 0, queue):
                        return False
                    progress = True
                elif can_black and not can_white:
                    if not assign(state, i, 1, queue):
                        return False
                    progress = True

            while queue:
                i = queue.popleft()
                cur = state['cell'][i]
                if cur == 1:
                    for nb in neighbors[i]:
                        if not assign(state, nb, 0, queue):
                            return False

            if not changed and not progress:
                break

        return final_consistency(state)

    def local_rules_shallow(state):
        # Lightweight propagation for hypothetical checks.
        queue = deque(i for i in range(N) if state['cell'][i] != -1)
        seen_groups = set()
        while queue:
            i = queue.popleft()
            if state['cell'][i] == 1:
                for nb in neighbors[i]:
                    if not assign(state, nb, 0, queue):
                        return False
            for gi in groups_by_cell[i]:
                if gi in seen_groups:
                    continue
                seen_groups.add(gi)
                ok, implied = check_group_coverage(state, all_groups[gi])
                if not ok:
                    return False
                for j, col in implied:
                    if not assign(state, j, col, queue):
                        return False
        ok_conn, _, _ = component_info_on_nonblack(state)
        if not ok_conn:
            return False
        return True

    def final_consistency(state):
        # Full consistency checks; final connectivity of whites if complete.
        cell = state['cell']
        for g in all_groups:
            whites = sum(1 for i in g if cell[i] == 0)
            if whites > 1:
                return False
            if all(cell[i] == 1 for i in g):
                return False

        for i in range(N):
            if cell[i] == 1:
                for nb in neighbors[i]:
                    if cell[nb] == 1:
                        return False

        ok_conn, _, _ = component_info_on_nonblack(state)
        if not ok_conn:
            return False

        if state['unknown_count'] == 0:
            whites = [i for i in range(N) if cell[i] == 0]
            if not whites:
                return False
            seen = {whites[0]}
            dq = deque([whites[0]])
            while dq:
                x = dq.popleft()
                for y in neighbors[x]:
                    if cell[y] == 0 and y not in seen:
                        seen.add(y)
                        dq.append(y)
            if len(seen) != len(whites):
                return False

        return True

    def choose_branch_cell(state):
        # Human-like heuristic:
        # pick the most constrained unresolved cell:
        # high duplicate pressure, adjacency to black, articulation tendency.
        cell = state['cell']
        best = None
        best_score = None

        ok_conn, _, arts = component_info_on_nonblack(state)
        if not ok_conn:
            return None

        for i in range(N):
            if cell[i] != -1:
                continue
            r, c = rc(i)
            v = values[i]

            dup_pressure = 0
            for gi in groups_by_cell[i]:
                g = all_groups[gi]
                unknown = sum(1 for x in g if cell[x] == -1)
                white = sum(1 for x in g if cell[x] == 0)
                dup_pressure += (10 if white else 0) + (5 - min(4, unknown))

            black_adj = sum(1 for nb in neighbors[i] if cell[nb] == 1)
            unk_adj = sum(1 for nb in neighbors[i] if cell[nb] == -1)
            art_bonus = 20 if i in arts else 0
            row_block = 8 if state['row_white'][r].get(v, 0) else 0
            col_block = 8 if state['col_white'][c].get(v, 0) else 0

            score = art_bonus + dup_pressure + black_adj * 6 + row_block + col_block - unk_adj
            if best is None or score > best_score:
                best = i
                best_score = score
        return best

    def branch_order(state, i):
        # Try the more forced-looking color first.
        r, c = rc(i)
        v = values[i]
        white_possible = state['row_white'][r].get(v, 0) == 0 and state['col_white'][c].get(v, 0) == 0
        black_possible = all(state['cell'][nb] != 1 for nb in neighbors[i])

        # Estimate.
        white_score = 0
        black_score = 0

        for gi in groups_by_cell[i]:
            g = all_groups[gi]
            white_count = sum(1 for x in g if state['cell'][x] == 0)
            unk = sum(1 for x in g if state['cell'][x] == -1)
            if white_count == 0 and unk == 1:
                white_score += 50
            if white_count == 1:
                black_score += 30

        black_score += sum(1 for nb in neighbors[i] if state['cell'][nb] == -1)
        if i in component_info_on_nonblack(state)[2]:
            white_score += 100

        opts = []
        if white_possible:
            opts.append((white_score, 0))
        if black_possible:
            opts.append((black_score, 1))
        opts.sort(reverse=True)
        return [color for _, color in opts]

    def search(state):
        if not local_rules(state):
            return None
        if state['unknown_count'] == 0:
            return state

        i = choose_branch_cell(state)
        if i is None:
            return None

        for color in branch_order(state, i):
            st2 = clone_state(state)
            q = deque()
            if assign(st2, i, color, q):
                res = search(st2)
                if res is not None:
                    return res
        return None

    state = initial_state()
    res = search(state)
    if res is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if res['cell'][idx(r, c)] == 1 else None)
        out.append(row)
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

