# Slant / Diagonal puzzle solver.
# Each cell chooses exactly one of:
#   '\' connecting (r,c) <-> (r+1,c+1)
#   '/' connecting (r,c+1) <-> (r+1,c)
#
# Constraints:
# 1) Numbered dots require exact incident diagonal count.
# 2) Chosen segments must form no cycle.
#
# The solver below is generalized and uses:
# - incremental clue propagation,
# - local forced deductions,
# - union-find rollback for loop prevention,
# - branch selection by strongest local pressure.
#
# It avoids external solvers and keeps search tightly pruned.

from copy import deepcopy

SLASH = 1
BACKSLASH = 2

def solve(observation):
    data = observation['data']
    m = len(data)          # dot rows = N+1
    n = len(data[0])       # dot cols = N+1
    if m != n:
        return "No Solution"
    N = m - 1

    # Cell endpoints for the two orientations
    # dot id = r*(N+1)+c
    def dot_id(r, c):
        return r * (N + 1) + c

    cell_ends = []
    dot_to_cells = [[] for _ in range((N + 1) * (N + 1))]
    for r in range(N):
        row = []
        for c in range(N):
            bs = (dot_id(r, c), dot_id(r + 1, c + 1))      # '\'
            sl = (dot_id(r, c + 1), dot_id(r + 1, c))      # '/'
            row.append((sl, bs))
            dot_to_cells[bs[0]].append((r, c, BACKSLASH))
            dot_to_cells[bs[1]].append((r, c, BACKSLASH))
            dot_to_cells[sl[0]].append((r, c, SLASH))
            dot_to_cells[sl[1]].append((r, c, SLASH))
        cell_ends.append(row)

    # For each dot, list adjacent cells and whether each orientation contributes to that dot.
    dot_adj = [[] for _ in range((N + 1) * (N + 1))]
    for r in range(N):
        for c in range(N):
            sl, bs = cell_ends[r][c]
            a, b = sl
            dot_adj[a].append((r, c, SLASH))
            dot_adj[b].append((r, c, SLASH))
            a, b = bs
            dot_adj[a].append((r, c, BACKSLASH))
            dot_adj[b].append((r, c, BACKSLASH))

    clues = [None] * ((N + 1) * (N + 1))
    for r in range(N + 1):
        for c in range(N + 1):
            clues[dot_id(r, c)] = data[r][c]

    class RollbackDSU:
        def __init__(self, size):
            self.parent = list(range(size))
            self.rank = [0] * size
            self.history = []

        def find(self, x):
            while self.parent[x] != x:
                x = self.parent[x]
            return x

        def snapshot(self):
            return len(self.history)

        def rollback(self, snap):
            while len(self.history) > snap:
                item = self.history.pop()
                if item is None:
                    continue
                rb, ra, rank_inc = item
                self.parent[rb] = rb
                if rank_inc:
                    self.rank[ra] -= 1

        def union(self, a, b):
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            rank_inc = 1 if self.rank[ra] == self.rank[rb] else 0
            self.history.append((rb, ra, rank_inc))
            self.parent[rb] = ra
            if rank_inc:
                self.rank[ra] += 1
            return True

        def same(self, a, b):
            return self.find(a) == self.find(b)

    class State:
        __slots__ = (
            'assign', 'unknown_count',
            'req', 'sat', 'undec',
            'dsu', 'trail',
        )
        def __init__(self):
            self.assign = [[0] * N for _ in range(N)]   # 0 unknown, 1 slash, 2 backslash
            self.unknown_count = N * N

            # Per dot:
            # req = clue or -1
            # sat = number already incident from assigned cells
            # undec = number of adjacent unknown cells that could still contribute
            self.req = [-1 if clues[i] is None else clues[i] for i in range((N + 1) * (N + 1))]
            self.sat = [0] * ((N + 1) * (N + 1))
            self.undec = [0] * ((N + 1) * (N + 1))
            for d in range((N + 1) * (N + 1)):
                if self.req[d] != -1:
                    self.undec[d] = len(dot_adj[d])

            self.dsu = RollbackDSU((N + 1) * (N + 1))
            self.trail = []

        def snapshot(self):
            return (len(self.trail), self.dsu.snapshot(), self.unknown_count)

        def rollback(self, snap):
            trail_len, dsu_snap, unk = snap
            self.dsu.rollback(dsu_snap)
            while len(self.trail) > trail_len:
                kind, payload = self.trail.pop()
                if kind == 'cell':
                    r, c, old = payload
                    self.assign[r][c] = old
                elif kind == 'dot':
                    d, old_sat, old_undec = payload
                    self.sat[d] = old_sat
                    self.undec[d] = old_undec
            self.unknown_count = unk

        def cell_endpoints(self, r, c, val):
            sl, bs = cell_ends[r][c]
            return sl if val == SLASH else bs

        def contributes(self, r, c, val, d):
            a, b = self.cell_endpoints(r, c, val)
            return d == a or d == b

        def can_place(self, r, c, val):
            if self.assign[r][c] not in (0, val):
                return False
            a, b = self.cell_endpoints(r, c, val)

            # Loop prevention: if endpoints already connected, adding this edge creates cycle.
            if self.dsu.same(a, b):
                return False

            # Check clue feasibility around all affected dots globally for this cell.
            # For each adjacent dot of this cell, assignment either contributes or not.
            touched = set()
            sl, bs = cell_ends[r][c]
            for d in (sl[0], sl[1], bs[0], bs[1]):
                touched.add(d)

            for d in touched:
                req = self.req[d]
                if req == -1:
                    continue
                sat = self.sat[d]
                undec = self.undec[d]
                contrib = 1 if self.contributes(r, c, val, d) else 0
                # one unknown adjacent cell is being resolved
                nsat = sat + contrib
                nundec = undec - 1
                if nsat > req:
                    return False
                if nsat + nundec < req:
                    return False
            return True

        def place(self, r, c, val):
            if not self.can_place(r, c, val):
                return False
            old = self.assign[r][c]
            self.trail.append(('cell', (r, c, old)))
            self.assign[r][c] = val
            self.unknown_count -= 1

            sl, bs = cell_ends[r][c]
            touched = set((sl[0], sl[1], bs[0], bs[1]))
            for d in touched:
                if self.req[d] == -1:
                    continue
                old_sat = self.sat[d]
                old_undec = self.undec[d]
                self.trail.append(('dot', (d, old_sat, old_undec)))
                if self.contributes(r, c, val, d):
                    self.sat[d] += 1
                self.undec[d] -= 1

            a, b = self.cell_endpoints(r, c, val)
            ok = self.dsu.union(a, b)
            if not ok:
                return False
            return True

        def dot_status_ok(self, d):
            req = self.req[d]
            if req == -1:
                return True
            sat = self.sat[d]
            undec = self.undec[d]
            return sat <= req and sat + undec >= req

        def all_clues_satisfied(self):
            for d, req in enumerate(self.req):
                if req != -1 and self.sat[d] != req:
                    return False
            return True

    state = State()

    # Initial static contradiction checks.
    for d in range((N + 1) * (N + 1)):
        req = state.req[d]
        if req != -1 and req > len(dot_adj[d]):
            return "No Solution"

    def forced_for_dot(st, d):
        req = st.req[d]
        if req == -1:
            return []
        sat = st.sat[d]
        undec = st.undec[d]
        rem = req - sat
        if rem < 0 or rem > undec:
            return None

        unknown_entries = []
        for r, c, ori in dot_adj[d]:
            if st.assign[r][c] == 0:
                unknown_entries.append((r, c, ori))

        if not unknown_entries:
            return []

        actions = []
        if rem == 0:
            # All unknown adjacent cells must avoid touching this dot.
            cells = {}
            for r, c, ori in unknown_entries:
                cells.setdefault((r, c), []).append(ori)
            for (r, c), oris in cells.items():
                # exactly one orientation contributes to a given dot for a cell
                if len(oris) != 1:
                    continue
                contrib_ori = oris[0]
                forced = BACKSLASH if contrib_ori == SLASH else SLASH
                actions.append((r, c, forced))
        elif rem == undec:
            # Every remaining unknown adjacent cell must touch this dot.
            cells = {}
            for r, c, ori in unknown_entries:
                cells.setdefault((r, c), []).append(ori)
            for (r, c), oris in cells.items():
                if len(oris) != 1:
                    continue
                forced = oris[0]
                actions.append((r, c, forced))
        return actions

    def propagate(st):
        changed = True
        while changed:
            changed = False

            # First, direct clue bounds and local human-style forcing.
            for d in range((N + 1) * (N + 1)):
                if not st.dot_status_ok(d):
                    return False
                acts = forced_for_dot(st, d)
                if acts is None:
                    return False
                for r, c, val in acts:
                    cur = st.assign[r][c]
                    if cur == 0:
                        if not st.place(r, c, val):
                            return False
                        changed = True
                    elif cur != val:
                        return False

            # Second, cell-level orientation filtering:
            # if only one orientation remains feasible, force it.
            for r in range(N):
                for c in range(N):
                    if st.assign[r][c] != 0:
                        continue
                    ok1 = st.can_place(r, c, SLASH)
                    ok2 = st.can_place(r, c, BACKSLASH)
                    if not ok1 and not ok2:
                        return False
                    if ok1 ^ ok2:
                        val = SLASH if ok1 else BACKSLASH
                        if not st.place(r, c, val):
                            return False
                        changed = True

        return True

    def score_cell(st, r, c):
        # Strong branching heuristic: prioritize cells touching clues with tight slack
        # and cells where one orientation is risky/impossible.
        score = 0
        sl, bs = cell_ends[r][c]
        touched = set((sl[0], sl[1], bs[0], bs[1]))
        for d in touched:
            req = st.req[d]
            if req == -1:
                continue
            sat = st.sat[d]
            undec = st.undec[d]
            rem = req - sat
            score += 10
            score += max(0, 4 - undec) * 5
            if rem == 0 or rem == undec:
                score += 30
            score += abs(rem - undec / 2)
        ok1 = st.can_place(r, c, SLASH)
        ok2 = st.can_place(r, c, BACKSLASH)
        if ok1 ^ ok2:
            score += 1000
        return score, ok1, ok2

    def choose_cell(st):
        best = None
        best_info = None
        for r in range(N):
            for c in range(N):
                if st.assign[r][c] != 0:
                    continue
                info = score_cell(st, r, c)
                if best is None or info[0] > best:
                    best = info[0]
                    best_info = (r, c, info[1], info[2])
        return best_info

    def search(st):
        if not propagate(st):
            return None
        if st.unknown_count == 0:
            if st.all_clues_satisfied():
                return st
            return None

        pick = choose_cell(st)
        if pick is None:
            return st if st.all_clues_satisfied() else None
        r, c, ok1, ok2 = pick

        # Value ordering: test orientation with greater immediate clue pressure first.
        vals = []
        if ok1:
            vals.append(SLASH)
        if ok2:
            vals.append(BACKSLASH)

        def impact(val):
            score = 0
            sl, bs = cell_ends[r][c]
            touched = set((sl[0], sl[1], bs[0], bs[1]))
            for d in touched:
                req = st.req[d]
                if req == -1:
                    continue
                contrib = 1 if st.contributes(r, c, val, d) else 0
                rem = req - st.sat[d]
                if contrib and rem == 1:
                    score += 8
                if (not contrib) and rem == st.undec[d]:
                    score += 8
            return -score

        vals.sort(key=impact)

        for val in vals:
            snap = st.snapshot()
            if st.place(r, c, val):
                res = search(st)
                if res is not None:
                    return res
            st.rollback(snap)
        return None

    res = search(state)
    if res is None:
        return "No Solution"

    out = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append('/' if res.assign[r][c] == SLASH else '\\')
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 0, None, 0, None], [2, None, None, None, None, None], [None, None, 2, None, None, 2], [2, 2, None, 2, 1, None], [0, None, None, None, None, 0], [None, None, 0, None, 1, None]]}

# Slitherlink-like "diagonal puzzle" (aka no-loop diagonal placement) solver.
# One diagonal per cell, either '/' or '\'.
# Numbered dots constrain the count of incident diagonal segments.
# Additionally, all chosen segments together must contain no cycle.
#
# The solver is generalized:
# - parses clues from OBSERVATION['data']
# - performs aggressive propagation from dot-degree constraints
# - maintains acyclicity incrementally via rollbackable DSU
# - uses human-like deductions:
#   * local min/max feasibility at each clue
#   * singleton forcing when required count reaches lower/upper bounds
#   * immediate contradiction if a choice would close a loop
#   * branch on the most constrained cell when logic stalls
#
# Returned answer is an N x N list of lists of '/' or '\' or "No Solution".

from collections import deque

UNKNOWN = -1
SLASH = 0      # '/'
BACKSLASH = 1  # '\\'


class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def snapshot(self):
        return len(self.history)

    def rollback(self, snap):
        while len(self.history) > snap:
            rec = self.history.pop()
            if rec is None:
                continue
            rb, ra, sa, comp = rec
            self.parent[rb] = rb
            self.size[ra] = sa
            self.components = comp

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            self.history.append(None)
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.history.append((rb, ra, self.size[ra], self.components))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True

    def connected(self, a, b):
        return self.find(a) == self.find(b)


def solve(observation):
    data = observation['data']
    m = len(data)
    if m == 0:
        return []
    n = m - 1
    if any(len(row) != n + 1 for row in data):
        return "No Solution"

    # Dot indexing
    def dot_id(r, c):
        return r * (n + 1) + c

    # Cell endpoints for each orientation
    # slash '/' uses (r,c+1) -- (r+1,c)
    # backslash '\' uses (r,c) -- (r+1,c+1)
    cell_endpoints = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append((
                (dot_id(r, c + 1), dot_id(r + 1, c)),      # SLASH
                (dot_id(r, c), dot_id(r + 1, c + 1)),      # BACKSLASH
            ))
        cell_endpoints.append(row)

    # For each dot, list incident cells and orientation that contributes.
    # entry: (cell_r, cell_c, orient)
    incident = [[[] for _ in range(n + 1)] for _ in range(n + 1)]
    for r in range(n):
        for c in range(n):
            (a1, b1), (a2, b2) = cell_endpoints[r][c]
            # SLASH endpoints
            rr1, cc1 = divmod(a1, n + 1)
            rr2, cc2 = divmod(b1, n + 1)
            incident[rr1][cc1].append((r, c, SLASH))
            incident[rr2][cc2].append((r, c, SLASH))
            # BACKSLASH endpoints
            rr1, cc1 = divmod(a2, n + 1)
            rr2, cc2 = divmod(b2, n + 1)
            incident[rr1][cc1].append((r, c, BACKSLASH))
            incident[rr2][cc2].append((r, c, BACKSLASH))

    # State
    assign = [[UNKNOWN] * n for _ in range(n)]

    # For each clue dot: required, current satisfied assigned incidences, unknown incidences count
    req = [[data[r][c] for c in range(n + 1)] for r in range(n + 1)]
    sat = [[0] * (n + 1) for _ in range(n + 1)]
    unk = [[0] * (n + 1) for _ in range(n + 1)]

    clue_dots = []
    for r in range(n + 1):
        for c in range(n + 1):
            if req[r][c] is not None:
                unk[r][c] = len(incident[r][c])
                clue_dots.append((r, c))

    dsu = RollbackDSU((n + 1) * (n + 1))

    # Queue for clue propagation
    q = deque()
    inq = [[False] * (n + 1) for _ in range(n + 1)]
    for r, c in clue_dots:
        q.append((r, c))
        inq[r][c] = True

    # Rollback log for non-DSU state
    ops = []

    def snapshot():
        return len(ops), dsu.snapshot()

    def rollback(snap):
        op_snap, dsu_snap = snap
        dsu.rollback(dsu_snap)
        while len(ops) > op_snap:
            typ, payload = ops.pop()
            if typ == 'assign':
                r, c, oldv = payload
                assign[r][c] = oldv
            elif typ == 'sat':
                r, c, delta = payload
                sat[r][c] -= delta
            elif typ == 'unk':
                r, c, delta = payload
                unk[r][c] += delta
            elif typ == 'inq':
                r, c = payload
                inq[r][c] = False
                # queue contents are ignored on rollback; caller rebuilds via forced pushes if needed
        # Queue may contain stale items from deeper calls; we rebuild externally by validating when popped.

    def push_clue(r, c):
        if req[r][c] is not None and not inq[r][c]:
            inq[r][c] = True
            ops.append(('inq', (r, c)))
            q.append((r, c))

    def cell_choice_contributes_to_dot(cell_r, cell_c, orient, dot_r, dot_c):
        for d in cell_endpoints[cell_r][cell_c][orient]:
            rr, cc = divmod(d, n + 1)
            if rr == dot_r and cc == dot_c:
                return True
        return False

    def choice_creates_cycle(r, c, orient):
        a, b = cell_endpoints[r][c][orient]
        return dsu.connected(a, b)

    def apply_assignment(r, c, orient):
        old = assign[r][c]
        if old == orient:
            return True
        if old != UNKNOWN:
            return False

        # No-loop rule: chosen diagonal cannot connect two already connected dots.
        if choice_creates_cycle(r, c, orient):
            return False

        ops.append(('assign', (r, c, old)))
        assign[r][c] = orient

        # This cell becomes known for all clue dots touching it.
        # For each of its four corner dots, if numbered, unknown count decreases by 1.
        corners = ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1))
        chosen_end_ids = set(cell_endpoints[r][c][orient])

        seen = set()
        for dr, dc in corners:
            if not (0 <= dr <= n and 0 <= dc <= n):
                continue
            if req[dr][dc] is None:
                continue
            if (dr, dc) in seen:
                continue
            seen.add((dr, dc))
            ops.append(('unk', (dr, dc, 1)))
            unk[dr][dc] -= 1
            if dot_id(dr, dc) in chosen_end_ids:
                ops.append(('sat', (dr, dc, 1)))
                sat[dr][dc] += 1
            push_clue(dr, dc)

        a, b = cell_endpoints[r][c][orient]
        dsu.union(a, b)
        return True

    def force_cell(r, c, orient):
        return apply_assignment(r, c, orient)

    def clue_feasible(r, c):
        return sat[r][c] <= req[r][c] <= sat[r][c] + unk[r][c]

    def propagate():
        while q:
            r, c = q.popleft()
            inq[r][c] = False
            if req[r][c] is None:
                continue
            if not clue_feasible(r, c):
                return False

            need = req[r][c] - sat[r][c]
            if need == 0:
                # Every still-unknown incident cell must choose the orientation that does NOT touch this dot.
                for cr, cc, orient_touch in incident[r][c]:
                    if assign[cr][cc] != UNKNOWN:
                        continue
                    other = 1 - orient_touch
                    if not force_cell(cr, cc, other):
                        return False
            elif need == unk[r][c]:
                # Every still-unknown incident cell must choose the orientation that DOES touch this dot.
                for cr, cc, orient_touch in incident[r][c]:
                    if assign[cr][cc] != UNKNOWN:
                        continue
                    if not force_cell(cr, cc, orient_touch):
                        return False

        # Additional pass: if a cell has one orientation making immediate contradiction, force the other.
        changed = True
        while changed:
            changed = False
            for r in range(n):
                for c in range(n):
                    if assign[r][c] != UNKNOWN:
                        continue
                    viable = []
                    for orient in (SLASH, BACKSLASH):
                        snap = snapshot()
                        ok = apply_assignment(r, c, orient)
                        if ok:
                            ok = propagate()
                        rollback(snap)
                        if ok:
                            viable.append(orient)
                    if not viable:
                        return False
                    if len(viable) == 1:
                        if not apply_assignment(r, c, viable[0]):
                            return False
                        if not propagate():
                            return False
                        changed = True
        return True

    def all_assigned():
        for r in range(n):
            for c in range(n):
                if assign[r][c] == UNKNOWN:
                    return False
        return True

    def final_check():
        # clues exact
        for r, c in clue_dots:
            if sat[r][c] != req[r][c]:
                return False
        # no loops already enforced incrementally
        return True

    def select_branch_cell():
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if assign[r][c] != UNKNOWN:
                    continue
                # Score by neighboring clue tightness and local impact.
                score = 0
                corners = ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1))
                for dr, dc in corners:
                    if req[dr][dc] is None:
                        continue
                    need = req[dr][dc] - sat[dr][dc]
                    rem = unk[dr][dc]
                    score += 10
                    score += max(0, 4 - rem)
                    score += max(0, abs(2 * need - rem))
                # prefer more constrained
                if best is None or score > best_score:
                    best = (r, c)
                    best_score = score
        return best

    def orient_order(r, c):
        # Try orientation with stronger local support first.
        scores = []
        for orient in (SLASH, BACKSLASH):
            s = 0
            chosen = set(cell_endpoints[r][c][orient])
            corners = ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1))
            for dr, dc in corners:
                if req[dr][dc] is None:
                    continue
                touch = dot_id(dr, dc) in chosen
                need = req[dr][dc] - sat[dr][dc]
                rem = unk[dr][dc]
                # If touching a dot that still needs many among few rem cells, prefer it.
                if touch:
                    s += 2 * need - rem
                else:
                    s += rem - 2 * need
            # avoid cycle-closing choice if detectable
            if choice_creates_cycle(r, c, orient):
                s -= 1000
            scores.append((s, orient))
        scores.sort(reverse=True)
        return [o for _, o in scores]

    def dfs():
        if not propagate():
            return False
        if all_assigned():
            return final_check()

        r, c = select_branch_cell()
        if r is None:
            return False

        for orient in orient_order(r, c):
            snap = snapshot()
            if apply_assignment(r, c, orient) and dfs():
                return True
            rollback(snap)
        return False

    if not dfs():
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('/' if assign[r][c] == SLASH else '\\')
        out.append(row)
    return out


if __name__ == "__main__":
    print(solve(OBSERVATION))

