from collections import deque, defaultdict

B = 1
W = 0
U = -1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0])

    regions = defaultdict(list)
    clue = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            regions[rid].append((r, c))
            if data[r][c] is not None:
                clue[rid] = data[r][c]

    region_ids = sorted(regions)
    if set(clue) != set(region_ids):
        # If some regions have no clue, unsupported by puzzle rules; still reject cleanly.
        return "No Solution"

    cell_index = {}
    cells = []
    for r in range(n):
        for c in range(m):
            idx = len(cells)
            cell_index[(r, c)] = idx
            cells.append((r, c))

    region_of_idx = [region[r][c] for r, c in cells]
    neighbors = [[] for _ in cells]
    for idx, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                neighbors[idx].append(cell_index[(rr, cc)])

    region_cells_idx = {}
    for rid, rcells in regions.items():
        region_cells_idx[rid] = [cell_index[p] for p in rcells]

    # Maximal row/col straight segments inside same row/col between borders.
    row_segments = []
    row_seg_of = {}
    for r in range(n):
        start = 0
        while start < m:
            cur_regs = [region[r][start]]
            end = start
            while end + 1 < m:
                end += 1
                cur_regs.append(region[r][end])
            seg = [cell_index[(r, c)] for c in range(start, end + 1)]
            sid = len(row_segments)
            row_segments.append(seg)
            for idx in seg:
                row_seg_of[idx] = sid
            start = end + 1

    col_segments = []
    col_seg_of = {}
    for c in range(m):
        start = 0
        while start < n:
            end = start
            while end + 1 < n:
                end += 1
            seg = [cell_index[(r, c)] for r in range(start, end + 1)]
            sid = len(col_segments)
            col_segments.append(seg)
            for idx in seg:
                col_seg_of[idx] = sid
            start = end + 1

    # For rule 3 we only need each contiguous white run in a row/col to use <= 2 regions.
    rows = [[cell_index[(r, c)] for c in range(m)] for r in range(n)]
    cols = [[cell_index[(r, c)] for r in range(n)] for c in range(m)]

    region_need = {rid: clue[rid] for rid in region_ids}

    all_region_patterns = {}
    for rid in region_ids:
        idxs = region_cells_idx[rid]
        k = len(idxs)
        need = region_need[rid]
        pats = []
        # Enumerate all subsets of region cells with exactly need blacks and no orth-adjacent blacks.
        # Region sizes are tiny in these puzzles; this powers strong deduction.
        def rec(pos, left, chosen_mask):
            if left < 0:
                return
            if pos == k:
                if left == 0:
                    pats.append(chosen_mask)
                return
            if k - pos < left:
                return
            # white
            rec(pos + 1, left, chosen_mask)
            # black if no adjacent black among already chosen region cells and globally same region pattern local validity
            idx = idxs[pos]
            ok = True
            for nb in neighbors[idx]:
                # Only need check neighbors already chosen among region cells to enforce non-touch;
                # cross-region adjacency handled during propagation.
                if nb in idxs:
                    j = idxs.index(nb)
                    if j < pos and ((chosen_mask >> j) & 1):
                        ok = False
                        break
            if ok:
                rec(pos + 1, left - 1, chosen_mask | (1 << pos))
        rec(0, need, 0)
        all_region_patterns[rid] = pats
        if not pats:
            return "No Solution"

    idx_pos_in_region = {}
    for rid, idxs in region_cells_idx.items():
        for j, idx in enumerate(idxs):
            idx_pos_in_region[idx] = (rid, j)

    class State:
        __slots__ = ("assign", "reg_pats")
        def __init__(self, assign, reg_pats):
            self.assign = assign
            self.reg_pats = reg_pats

        def clone(self):
            return State(self.assign[:], {rid: pats[:] for rid, pats in self.reg_pats.items()})

    def force_cell(st, idx, val):
        cur = st.assign[idx]
        if cur == val:
            return True
        if cur != U:
            return False
        st.assign[idx] = val
        return True

    def check_line_rule_partial(line, assign):
        # Every completed white segment must span <=2 regions.
        # Partial check:
        # scan segments separated by forced black; within each open segment,
        # count distinct regions among forced/possible whites. If forced whites already >2 => fail.
        # If all unknowns removed later cannot reduce distinct forced-white regions.
        i = 0
        L = len(line)
        while i < L:
            while i < L and assign[line[i]] == B:
                i += 1
            if i >= L:
                break
            regs_forced_white = set()
            regs_possible = set()
            j = i
            while j < L and assign[line[j]] != B:
                rid = region_of_idx[line[j]]
                if assign[line[j]] == W:
                    regs_forced_white.add(rid)
                else:
                    regs_possible.add(rid)
                j += 1
            if len(regs_forced_white) > 2:
                return False
            if len(regs_forced_white | regs_possible) <= 2:
                i = j
                continue
            # If >2 possible regions but only <=2 forced, still maybe split by future blacks. Allowed.
            i = j
        return True

    def connectivity_possible(assign):
        whiteish = [i for i, v in enumerate(assign) if v != B]
        if not whiteish:
            return False
        start = next((i for i, v in enumerate(assign) if v == W), whiteish[0])
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for nb in neighbors[x]:
                if assign[nb] != B and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(whiteish)

    def connectivity_final(assign):
        whites = [i for i, v in enumerate(assign) if v == W]
        if not whites:
            return False
        seen = {whites[0]}
        dq = deque([whites[0]])
        while dq:
            x = dq.popleft()
            for nb in neighbors[x]:
                if assign[nb] == W and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(whites)

    def propagate(st):
        changed = True
        while changed:
            changed = False

            # Filter region patterns by current assignments and cross-region adjacency implications.
            for rid in region_ids:
                idxs = region_cells_idx[rid]
                newp = []
                for mask in st.reg_pats[rid]:
                    ok = True
                    for j, idx in enumerate(idxs):
                        bit_black = (mask >> j) & 1
                        av = st.assign[idx]
                        if av != U and av != bit_black:
                            ok = False
                            break
                        if bit_black:
                            for nb in neighbors[idx]:
                                avn = st.assign[nb]
                                if avn == B:
                                    ok = False
                                    break
                            if not ok:
                                break
                    if ok:
                        newp.append(mask)
                if not newp:
                    return False
                if len(newp) != len(st.reg_pats[rid]):
                    st.reg_pats[rid] = newp
                    changed = True

                # Region consensus
                for j, idx in enumerate(idxs):
                    all_black = all((mask >> j) & 1 for mask in st.reg_pats[rid])
                    all_white = all(((mask >> j) & 1) == 0 for mask in st.reg_pats[rid])
                    if all_black:
                        if not force_cell(st, idx, B):
                            return False
                        changed = True
                    elif all_white:
                        if not force_cell(st, idx, W):
                            return False
                        changed = True

            # Black cells force orthogonal neighbors white
            for idx, v in enumerate(st.assign):
                if v == B:
                    for nb in neighbors[idx]:
                        if not force_cell(st, nb, W):
                            return False

            # Any region with exact quota matched in assignment via patterns already handled.
            # Line rule local checks
            for line in rows:
                if not check_line_rule_partial(line, st.assign):
                    return False
            for line in cols:
                if not check_line_rule_partial(line, st.assign):
                    return False

            # Strong line rule deductions:
            # If a current no-black interval has forced whites from exactly 2 regions,
            # then any unknown cell of a third region inside that interval must be black.
            for line in rows + cols:
                i = 0
                L = len(line)
                while i < L:
                    while i < L and st.assign[line[i]] == B:
                        i += 1
                    if i >= L:
                        break
                    j = i
                    forced_regs = set()
                    unknown_positions = []
                    while j < L and st.assign[line[j]] != B:
                        idx = line[j]
                        if st.assign[idx] == W:
                            forced_regs.add(region_of_idx[idx])
                        elif st.assign[idx] == U:
                            unknown_positions.append(idx)
                        j += 1
                    if len(forced_regs) == 2:
                        for idx in unknown_positions:
                            if region_of_idx[idx] not in forced_regs:
                                if not force_cell(st, idx, B):
                                    return False
                                changed = True
                    elif len(forced_regs) > 2:
                        return False
                    i = j

            # Connectivity possibility
            if not connectivity_possible(st.assign):
                return False

        # Final consistency checks if complete
        if all(v != U for v in st.assign):
            for rid in region_ids:
                idxs = region_cells_idx[rid]
                if sum(1 for idx in idxs if st.assign[idx] == B) != region_need[rid]:
                    return False
            for idx, v in enumerate(st.assign):
                if v == B:
                    for nb in neighbors[idx]:
                        if st.assign[nb] == B:
                            return False
            for line in rows + cols:
                i = 0
                L = len(line)
                while i < L:
                    while i < L and st.assign[line[i]] == B:
                        i += 1
                    if i >= L:
                        break
                    regs = set()
                    while i < L and st.assign[line[i]] != B:
                        regs.add(region_of_idx[line[i]])
                        i += 1
                    if len(regs) > 2:
                        return False
            if not connectivity_final(st.assign):
                return False

        return True

    def choose_branch(st):
        # Choose region with fewest patterns >1
        best = None
        for rid in region_ids:
            lp = len(st.reg_pats[rid])
            if lp > 1 and (best is None or lp < best[0]):
                best = (lp, rid)
        if best is not None:
            rid = best[1]
            idxs = region_cells_idx[rid]
            pats = st.reg_pats[rid]
            # pick cell with best split across patterns
            best_cell = None
            best_score = None
            for j, idx in enumerate(idxs):
                cntb = sum((p >> j) & 1 for p in pats)
                cntw = len(pats) - cntb
                if cntb and cntw:
                    score = abs(cntb - cntw)
                    if best_score is None or score < best_score:
                        best_score = score
                        best_cell = idx
            if best_cell is not None:
                return best_cell
        # fallback any unknown cell
        for idx, v in enumerate(st.assign):
            if v == U:
                return idx
        return None

    def dfs(st):
        if not propagate(st):
            return None
        if all(v != U for v in st.assign):
            return st
        idx = choose_branch(st)
        if idx is None:
            return None

        # Value ordering: use region pattern frequency
        rid, j = idx_pos_in_region[idx]
        pats = st.reg_pats[rid]
        cntb = sum((p >> j) & 1 for p in pats)
        cntw = len(pats) - cntb
        order = [B, W] if cntb <= cntw else [W, B]

        for val in order:
            ns = st.clone()
            if force_cell(ns, idx, val):
                ans = dfs(ns)
                if ans is not None:
                    return ans
        return None

    initial = State([U] * (n * m), {rid: all_region_patterns[rid][:] for rid in region_ids})
    result = dfs(initial)
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            idx = cell_index[(r, c)]
            row.append('B' if result.assign[idx] == B else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 5, 4, 3, 2, 2], 'D': [3, 1, 2, 3, 2, 4], 'L': [1, 3, 4, 2, 3, 2], 'R': [3, 1, 2, 3, 2, 4]}

from itertools import permutations


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    def visible_count(seq):
        m = 0
        c = 0
        for x in seq:
            if x > m:
                m = x
                c += 1
        return c

    # Human-like line reasoning:
    # A row/column must be one of the Latin permutations compatible with its two side clues.
    # We precompute all such candidates once.
    pair_to_perms = {}
    for lc in range(0, n + 1):
        for rc in range(0, n + 1):
            pair_to_perms[(lc, rc)] = []

    for p in all_perms:
        lv = visible_count(p)
        rv = visible_count(p[::-1])
        for lc in (0, lv):
            for rc in (0, rv):
                pair_to_perms[(lc, rc)].append(p)

    row_cands = [list(pair_to_perms[(L[r], R[r])]) for r in range(n)]
    col_cands = [list(pair_to_perms[(U[c], D[c])]) for c in range(n)]

    if any(not x for x in row_cands) or any(not x for x in col_cands):
        return "No Solution"

    # Domains as bitmasks for fast propagation.
    full_mask = (1 << n) - 1
    cell_masks = [[full_mask for _ in range(n)] for _ in range(n)]

    def bit(v):
        return 1 << (v - 1)

    def values_from_mask(mask):
        v = 1
        while mask:
            lsb = mask & -mask
            idx = lsb.bit_length() - 1
            yield idx + 1
            mask ^= lsb
            v += 1

    def filter_line_candidates_by_masks(cands, masks):
        out = []
        for p in cands:
            ok = True
            for i, v in enumerate(p):
                if not (masks[i] & bit(v)):
                    ok = False
                    break
            if ok:
                out.append(p)
        return out

    def union_masks_from_candidates(cands, nlen):
        unions = [0] * nlen
        for p in cands:
            for i, v in enumerate(p):
                unions[i] |= bit(v)
        return unions

    def propagate(row_cands, col_cands, cell_masks):
        changed = True
        while changed:
            changed = False

            # Filter row candidates by current cell masks.
            for r in range(n):
                newc = filter_line_candidates_by_masks(row_cands[r], cell_masks[r])
                if not newc:
                    return False
                if len(newc) != len(row_cands[r]):
                    row_cands[r] = newc
                    changed = True

                unions = union_masks_from_candidates(row_cands[r], n)
                for c in range(n):
                    nm = cell_masks[r][c] & unions[c]
                    if nm == 0:
                        return False
                    if nm != cell_masks[r][c]:
                        cell_masks[r][c] = nm
                        changed = True

            # Filter column candidates by current cell masks.
            for c in range(n):
                col_masks = [cell_masks[r][c] for r in range(n)]
                newc = filter_line_candidates_by_masks(col_cands[c], col_masks)
                if not newc:
                    return False
                if len(newc) != len(col_cands[c]):
                    col_cands[c] = newc
                    changed = True

                unions = union_masks_from_candidates(col_cands[c], n)
                for r in range(n):
                    nm = cell_masks[r][c] & unions[r]
                    if nm == 0:
                        return False
                    if nm != cell_masks[r][c]:
                        cell_masks[r][c] = nm
                        changed = True

            # Hidden singles in rows.
            for r in range(n):
                counts = [0] * (n + 1)
                lastc = [-1] * (n + 1)
                for c in range(n):
                    m = cell_masks[r][c]
                    for v in values_from_mask(m):
                        counts[v] += 1
                        lastc[v] = c
                for v in range(1, n + 1):
                    if counts[v] == 0:
                        return False
                    if counts[v] == 1:
                        c = lastc[v]
                        nm = bit(v)
                        if cell_masks[r][c] != nm:
                            if not (cell_masks[r][c] & nm):
                                return False
                            cell_masks[r][c] = nm
                            changed = True

            # Hidden singles in columns.
            for c in range(n):
                counts = [0] * (n + 1)
                lastr = [-1] * (n + 1)
                for r in range(n):
                    m = cell_masks[r][c]
                    for v in values_from_mask(m):
                        counts[v] += 1
                        lastr[v] = r
                for v in range(1, n + 1):
                    if counts[v] == 0:
                        return False
                    if counts[v] == 1:
                        r = lastr[v]
                        nm = bit(v)
                        if cell_masks[r][c] != nm:
                            if not (cell_masks[r][c] & nm):
                                return False
                            cell_masks[r][c] = nm
                            changed = True

            # If a row/column is fixed to one permutation, force its cells.
            for r in range(n):
                if len(row_cands[r]) == 1:
                    p = row_cands[r][0]
                    for c, v in enumerate(p):
                        nm = bit(v)
                        if cell_masks[r][c] != nm:
                            if not (cell_masks[r][c] & nm):
                                return False
                            cell_masks[r][c] = nm
                            changed = True

            for c in range(n):
                if len(col_cands[c]) == 1:
                    p = col_cands[c][0]
                    for r, v in enumerate(p):
                        nm = bit(v)
                        if cell_masks[r][c] != nm:
                            if not (cell_masks[r][c] & nm):
                                return False
                            cell_masks[r][c] = nm
                            changed = True

        return True

    def solved(row_cands, col_cands, cell_masks):
        return all(len(rc) == 1 for rc in row_cands) and all(len(cc) == 1 for cc in col_cands)

    def copy_state(row_cands, col_cands, cell_masks):
        return [list(x) for x in row_cands], [list(x) for x in col_cands], [list(row) for row in cell_masks]

    def choose_branch(row_cands, col_cands, cell_masks):
        # Prefer the most constrained line, mirroring human "focus where information is tightest".
        best = None

        for r in range(n):
            k = len(row_cands[r])
            if 1 < k and (best is None or k < best[0]):
                best = (k, 'row', r)

        for c in range(n):
            k = len(col_cands[c])
            if 1 < k and (best is None or k < best[0]):
                best = (k, 'col', c)

        if best is not None:
            return best[1], best[2]

        # Fallback to a cell with smallest domain > 1.
        best_cell = None
        for r in range(n):
            for c in range(n):
                m = cell_masks[r][c]
                bc = m.bit_count()
                if 1 < bc and (best_cell is None or bc < best_cell[0]):
                    best_cell = (bc, r, c)
        if best_cell is not None:
            return 'cell', (best_cell[1], best_cell[2])

        return None, None

    def dfs(row_cands, col_cands, cell_masks):
        if not propagate(row_cands, col_cands, cell_masks):
            return None

        if solved(row_cands, col_cands, cell_masks):
            grid = [list(row_cands[r][0]) for r in range(n)]
            return grid

        kind, idx = choose_branch(row_cands, col_cands, cell_masks)
        if kind is None:
            return None

        if kind == 'row':
            r = idx
            # Try candidates in current constrained row.
            for p in row_cands[r]:
                rr, cc, mm = copy_state(row_cands, col_cands, cell_masks)
                rr[r] = [p]
                for c, v in enumerate(p):
                    mm[r][c] = bit(v)
                ans = dfs(rr, cc, mm)
                if ans is not None:
                    return ans
            return None

        if kind == 'col':
            c = idx
            for p in col_cands[c]:
                rr, cc, mm = copy_state(row_cands, col_cands, cell_masks)
                cc[c] = [p]
                for r, v in enumerate(p):
                    mm[r][c] = bit(v)
                ans = dfs(rr, cc, mm)
                if ans is not None:
                    return ans
            return None

        r, c = idx
        mask = cell_masks[r][c]
        for v in values_from_mask(mask):
            rr, cc, mm = copy_state(row_cands, col_cands, cell_masks)
            mm[r][c] = bit(v)
            ans = dfs(rr, cc, mm)
            if ans is not None:
                return ans
        return None

    result = dfs(row_cands, col_cands, cell_masks)
    return str(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 3, 2, 2, 1, None], [None, None, 3, None, 3, None], [1, 2, None, 2, None, 1], [1, None, 3, 2, None, 1], [None, None, 1, None, 1, None]]}

# General Slant solver:
# - One diagonal per cell: '/' or '\'
# - Numbered dots require exact incident count
# - No closed loop allowed among chosen diagonal segments
#
# The implementation is human-style in structure:
# 1) Convert each cell into a binary choice with explicit endpoint effects on nearby dots.
# 2) Repeatedly apply local clue propagation:
#    - exact saturation / exhaustion
#    - forced value from dot lower/upper bounds
# 3) Maintain global no-loop condition incrementally with rollback DSU:
#    - assigning a diagonal whose endpoints are already connected forms a cycle => forbidden
# 4) Branch only on the most constrained cell, trying values consistent with strongest local pressure.

from copy import deepcopy

SLASH = 0      # '/'
BACKSLASH = 1  # '\\'

def solve(observation):
    data = observation['data']
    m = len(data)
    if m == 0 or any(len(row) != m for row in data):
        return "No Solution"
    n = m - 1
    if n <= 0:
        return []

    # Dot indexing
    def dot_id(r, c):
        return r * (n + 1) + c

    num_dots = (n + 1) * (n + 1)
    num_cells = n * n

    # Cell metadata
    cell_rc = []
    cell_endpoints = []  # [('/', (a,b)), ('\\', (c,d))]
    cell_dots = []       # for each cell, the four corner dots [(r,c),...]
    cells_of_dot = [[] for _ in range(num_dots)]

    for r in range(n):
        for c in range(n):
            idx = r * n + c
            cell_rc.append((r, c))
            a = dot_id(r, c + 1)     # '/' endpoints
            b = dot_id(r + 1, c)
            c1 = dot_id(r, c)        # '\' endpoints
            d = dot_id(r + 1, c + 1)
            cell_endpoints.append(((a, b), (c1, d)))
            corners = [dot_id(r, c), dot_id(r, c + 1), dot_id(r + 1, c), dot_id(r + 1, c + 1)]
            cell_dots.append(corners)
            for dd in corners:
                cells_of_dot[dd].append(idx)

    # For each dot and each incident cell, determine whether '/' or '\' contributes to that dot
    # effect[(dot, cell)] = mask of values that contribute to that dot
    # Actually exactly one of the two values contributes if the cell touches the dot.
    effect = {}
    for idx, (r, c) in enumerate(cell_rc):
        # '/' uses (r,c+1) and (r+1,c)
        effect[(dot_id(r, c + 1), idx)] = SLASH
        effect[(dot_id(r + 1, c), idx)] = SLASH
        # '\' uses (r,c) and (r+1,c+1)
        effect[(dot_id(r, c), idx)] = BACKSLASH
        effect[(dot_id(r + 1, c + 1), idx)] = BACKSLASH

    clues = [None] * num_dots
    constrained_dots = []
    for r in range(n + 1):
        for c in range(n + 1):
            v = data[r][c]
            did = dot_id(r, c)
            clues[did] = v
            if v is not None:
                constrained_dots.append(did)

    # Precompute incident constrained dots per cell for branching score
    constrained_count_per_cell = [0] * num_cells
    for idx in range(num_cells):
        cnt = 0
        seen = set()
        for d in cell_dots[idx]:
            if clues[d] is not None and d not in seen:
                cnt += 1
                seen.add(d)
        constrained_count_per_cell[idx] = cnt

    class RollbackDSU:
        __slots__ = ('parent', 'size', 'history')
        def __init__(self, n_):
            self.parent = list(range(n_))
            self.size = [1] * n_
            self.history = []

        def find(self, x):
            while self.parent[x] != x:
                x = self.parent[x]
            return x

        def snapshot(self):
            return len(self.history)

        def rollback(self, snap):
            while len(self.history) > snap:
                item = self.history.pop()
                if item is None:
                    continue
                rb, ra, sa = item
                self.parent[rb] = rb
                self.size[ra] = sa

        def union(self, a, b):
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                self.history.append(None)
                return False
            if self.size[ra] < self.size[rb]:
                ra, rb = rb, ra
            self.history.append((rb, ra, self.size[ra]))
            self.parent[rb] = ra
            self.size[ra] += self.size[rb]
            return True

        def connected(self, a, b):
            return self.find(a) == self.find(b)

    # State
    assignment = [-1] * num_cells
    assigned_count = 0

    # For each dot:
    # req = clue
    # cnt = assigned contributing diagonals
    # undec = number of incident unassigned cells
    # poss = among unassigned incident cells, how many can still contribute
    dot_cnt = [0] * num_dots
    dot_undec = [len(cells_of_dot[d]) for d in range(num_dots)]
    dot_poss = [0] * num_dots

    # Initial possible contributor counts
    for d in range(num_dots):
        if clues[d] is None:
            continue
        p = 0
        for cell in cells_of_dot[d]:
            p += 1  # every incident unassigned cell can contribute in exactly one of its two states
        dot_poss[d] = p

    dsu = RollbackDSU(num_dots)

    # Queue-driven propagation
    queue = []
    in_queue = [False] * num_dots

    def push_dot(d):
        if clues[d] is not None and not in_queue[d]:
            in_queue[d] = True
            queue.append(d)

    for d in constrained_dots:
        push_dot(d)

    def cell_value_contributes_to_dot(cell, value, d):
        return effect.get((d, cell), -1) == value

    def dot_bounds_ok(d):
        req = clues[d]
        if req is None:
            return True
        cnt = dot_cnt[d]
        if cnt > req:
            return False
        # Maximum reachable = cnt + possible contributors among unassigned
        if cnt + dot_poss[d] < req:
            return False
        return True

    def assign(cell, value):
        nonlocal assigned_count
        cur = assignment[cell]
        if cur == value:
            return True
        if cur != -1:
            return False

        (s_a, s_b), (b_a, b_b) = cell_endpoints[cell]
        ea, eb = ((s_a, s_b) if value == SLASH else (b_a, b_b))

        # No-loop check: adding an edge inside same component would create a cycle.
        if dsu.connected(ea, eb):
            return False

        assignment[cell] = value
        assigned_count += 1

        # Update dots around this cell
        for d in cell_dots[cell]:
            if clues[d] is None:
                continue
            dot_undec[d] -= 1
            # This cell was one possible contributor before assignment
            dot_poss[d] -= 1
            if cell_value_contributes_to_dot(cell, value, d):
                dot_cnt[d] += 1
            push_dot(d)

        # Commit edge
        dsu.union(ea, eb)

        # Immediate bound checks
        for d in cell_dots[cell]:
            if clues[d] is not None and not dot_bounds_ok(d):
                return False
        return True

    def propagate():
        # Repeatedly force cells from clue saturation/exhaustion and cycle prevention.
        head = 0
        while head < len(queue):
            d = queue[head]
            head += 1
            in_queue[d] = False
            req = clues[d]
            if req is None:
                continue

            cnt = dot_cnt[d]
            poss = dot_poss[d]
            if cnt > req or cnt + poss < req:
                return False

            need = req - cnt

            # Examine incident unassigned cells and classify contributing/noncontributing value.
            unassigned_cells = []
            for cell in cells_of_dot[d]:
                if assignment[cell] == -1:
                    contrib_val = effect[(d, cell)]
                    other_val = 1 - contrib_val
                    unassigned_cells.append((cell, contrib_val, other_val))

            if need == 0:
                # All remaining incident cells must avoid contributing to d.
                for cell, contrib_val, other_val in unassigned_cells:
                    if not assign(cell, other_val):
                        return False
            elif need == len(unassigned_cells):
                # Every remaining incident cell must contribute to d.
                for cell, contrib_val, other_val in unassigned_cells:
                    if not assign(cell, contrib_val):
                        return False
            else:
                # Human-like local contradiction lookahead:
                # if one of the two values for an unassigned cell would instantly violate
                # either this clue or cycle rule, force the other.
                for cell, contrib_val, other_val in unassigned_cells:
                    possible_contrib = True
                    possible_other = True

                    # Check clue d only
                    # If choose contrib_val: d count becomes cnt+1, remaining possible after assignment = poss-1
                    if cnt + 1 > req:
                        possible_contrib = False
                    # If choose other_val: remaining possible for d becomes poss-1
                    if cnt + (poss - 1) < req:
                        possible_other = False

                    # Check cycle rule
                    (s_a, s_b), (b_a, b_b) = cell_endpoints[cell]
                    if possible_contrib:
                        ea, eb = ((s_a, s_b) if contrib_val == SLASH else (b_a, b_b))
                        if dsu.connected(ea, eb):
                            possible_contrib = False
                    if possible_other:
                        ea, eb = ((s_a, s_b) if other_val == SLASH else (b_a, b_b))
                        if dsu.connected(ea, eb):
                            possible_other = False

                    if not possible_contrib and not possible_other:
                        return False
                    if possible_contrib and not possible_other:
                        if not assign(cell, contrib_val):
                            return False
                    elif possible_other and not possible_contrib:
                        if not assign(cell, other_val):
                            return False

        # Global pass: if a cell has one orientation making a cycle, force the other.
        changed = True
        while changed:
            changed = False
            for cell in range(num_cells):
                if assignment[cell] != -1:
                    continue
                (s_a, s_b), (b_a, b_b) = cell_endpoints[cell]
                bad_slash = dsu.connected(s_a, s_b)
                bad_back = dsu.connected(b_a, b_b)
                if bad_slash and bad_back:
                    return False
                if bad_slash:
                    if not assign(cell, BACKSLASH):
                        return False
                    changed = True
                elif bad_back:
                    if not assign(cell, SLASH):
                        return False
                    changed = True
            if changed:
                while head < len(queue):
                    d = queue[head]
                    head += 1
                    in_queue[d] = False
                    req = clues[d]
                    cnt = dot_cnt[d]
                    poss = dot_poss[d]
                    if cnt > req or cnt + poss < req:
                        return False
                    need = req - cnt
                    unassigned_cells = []
                    for cell in cells_of_dot[d]:
                        if assignment[cell] == -1:
                            contrib_val = effect[(d, cell)]
                            other_val = 1 - contrib_val
                            unassigned_cells.append((cell, contrib_val, other_val))
                    if need == 0:
                        for cell, contrib_val, other_val in unassigned_cells:
                            if not assign(cell, other_val):
                                return False
                    elif need == len(unassigned_cells):
                        for cell, contrib_val, other_val in unassigned_cells:
                            if not assign(cell, contrib_val):
                                return False

        return True

    # Initial contradiction checks from obvious impossible clues
    for d in constrained_dots:
        deg = len(cells_of_dot[d])
        if clues[d] < 0 or clues[d] > deg:
            return "No Solution"

    if not propagate():
        return "No Solution"

    def choose_cell():
        # Most constrained first:
        # - smallest domain under current clue/cycle restrictions
        # - highest number of adjacent clues
        # - strongest clue pressure
        best = None
        best_key = None
        for cell in range(num_cells):
            if assignment[cell] != -1:
                continue
            allowed = []
            for value in (SLASH, BACKSLASH):
                (s_a, s_b), (b_a, b_b) = cell_endpoints[cell]
                ea, eb = ((s_a, s_b) if value == SLASH else (b_a, b_b))
                if dsu.connected(ea, eb):
                    continue
                ok = True
                # quick clue feasibility around adjacent dots
                for d in cell_dots[cell]:
                    req = clues[d]
                    if req is None:
                        continue
                    contributes = cell_value_contributes_to_dot(cell, value, d)
                    cnt = dot_cnt[d] + (1 if contributes else 0)
                    poss = dot_poss[d] - 1
                    if cnt > req or cnt + poss < req:
                        ok = False
                        break
                if ok:
                    allowed.append(value)
            if not allowed:
                return cell, []
            pressure = 0
            for d in cell_dots[cell]:
                req = clues[d]
                if req is None:
                    continue
                need = req - dot_cnt[d]
                rem = dot_poss[d]
                pressure += abs(2 * need - rem)
            key = (len(allowed), -constrained_count_per_cell[cell], -pressure, cell)
            if best_key is None or key < best_key:
                best_key = key
                best = (cell, allowed)
                if len(allowed) == 1:
                    break
        return best

    def value_order(cell, allowed):
        # Prefer value satisfying more urgent neighboring clues.
        scores = []
        for value in allowed:
            score = 0
            for d in cell_dots[cell]:
                req = clues[d]
                if req is None:
                    continue
                contributes = cell_value_contributes_to_dot(cell, value, d)
                need = req - dot_cnt[d]
                rem = dot_poss[d]
                # Reward exact-fit style moves
                if contributes:
                    if need == rem:
                        score += 6
                    if need > 0:
                        score += 2
                else:
                    if need == 0:
                        score += 6
                score += constrained_count_per_cell[cell]
            scores.append((-score, value))
        scores.sort()
        return [v for _, v in scores]

    def dfs():
        nonlocal assigned_count
        if assigned_count == num_cells:
            # All clues must be exactly satisfied; cycle-free maintained incrementally.
            for d in constrained_dots:
                if dot_cnt[d] != clues[d]:
                    return False
            return True

        choice = choose_cell()
        if choice is None:
            return False
        cell, allowed = choice
        if not allowed:
            return False

        for value in value_order(cell, allowed):
            snap_dsu = dsu.snapshot()
            snap_assignment = assignment[cell]
            snap_assigned_count = assigned_count
            touched = []
            old_queue_len = len(queue)

            # Snapshot local dot arrays only for dots around all future assignments is hard;
            # simplest reliable rollback is full copies of lightweight state arrays.
            # Grid sizes here are moderate; propagation sharply reduces branching.
            dot_cnt_bak = dot_cnt[:]
            dot_undec_bak = dot_undec[:]
            dot_poss_bak = dot_poss[:]
            in_queue_bak = in_queue[:]
            queue_bak = queue[:]

            if assign(cell, value) and propagate() and dfs():
                return True

            # rollback
            assignment[cell] = snap_assignment
            assigned_count = snap_assigned_count
            dot_cnt[:] = dot_cnt_bak
            dot_undec[:] = dot_undec_bak
            dot_poss[:] = dot_poss_bak
            in_queue[:] = in_queue_bak
            queue[:] = queue_bak
            dsu.rollback(snap_dsu)

        return False

    if not dfs():
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            v = assignment[r * n + c]
            row.append('/' if v == SLASH else '\\')
        out.append(row)
    return out

