OBSERVATION = {'U': [2, 1, 2, 2], 'D': [3, 4, 1, 2], 'L': [2, 1, 2, 2], 'R': [3, 4, 1, 2]}

from itertools import permutations


def solve(observation):
    n = len(observation['U'])
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    def visible_count(seq):
        m = 0
        c = 0
        for x in seq:
            if x > m:
                m = x
                c += 1
        return c

    def clue_ok(clue, seq):
        return clue == 0 or clue == visible_count(seq)

    def row_candidates(left_clue, right_clue):
        out = []
        for p in all_perms:
            if clue_ok(left_clue, p) and clue_ok(right_clue, p[::-1]):
                out.append(p)
        return out

    row_cands = [row_candidates(L[r], R[r]) for r in range(n)]
    if any(not c for c in row_cands):
        return "No Solution"

    # Human-like propagation:
    # 1) row clue filtering
    # 2) Latin uniqueness propagation by column
    # 3) prefix feasibility against top/bottom clues
    # 4) recursive branching on the most constrained row

    def compute_domains(cands):
        domains = [[set() for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for p in cands[r]:
                for c, v in enumerate(p):
                    domains[r][c].add(v)
        return domains

    def filter_by_cell_domains(cands, domains):
        changed = False
        for r in range(n):
            new_list = []
            for p in cands[r]:
                ok = True
                for c, v in enumerate(p):
                    if v not in domains[r][c]:
                        ok = False
                        break
                if ok:
                    new_list.append(p)
            if len(new_list) != len(cands[r]):
                cands[r] = new_list
                changed = True
            if not cands[r]:
                return None, True
        return cands, changed

    def latin_propagate(cands):
        changed_any = False
        while True:
            changed = False
            domains = compute_domains(cands)

            for r in range(n):
                for c in range(n):
                    if not domains[r][c]:
                        return None

            # Column-based Hall-like simple deductions:
            # each value must appear somewhere in each column
            for c in range(n):
                pos_by_val = {v: [] for v in nums}
                for r in range(n):
                    for v in domains[r][c]:
                        pos_by_val[v].append(r)

                for v in nums:
                    rows = pos_by_val[v]
                    if not rows:
                        return None
                    if len(rows) == 1:
                        rr = rows[0]
                        if domains[rr][c] != {v}:
                            domains[rr][c].intersection_update({v})
                            changed = True
                            if not domains[rr][c]:
                                return None

                # If a row in a column is fixed to v, remove v from others.
                fixed = {}
                for r in range(n):
                    if len(domains[r][c]) == 1:
                        vv = next(iter(domains[r][c]))
                        if vv in fixed:
                            if fixed[vv] != r:
                                return None
                        fixed[vv] = r
                for v, rr in fixed.items():
                    for r in range(n):
                        if r != rr and v in domains[r][c]:
                            domains[r][c].remove(v)
                            changed = True
                            if not domains[r][c]:
                                return None

            cands2, ch2 = filter_by_cell_domains(cands, domains)
            if cands2 is None:
                return None
            cands = cands2
            changed = changed or ch2

            if any(not cands[r] for r in range(n)):
                return None

            changed_any = changed_any or changed
            if not changed:
                return cands

    def prefix_visibility_info(prefix):
        m = 0
        vis = 0
        for x in prefix:
            if x > m:
                m = x
                vis += 1
        return vis, m

    def feasible_column_prefix(col_vals, top_clue, bottom_clue):
        used = set(col_vals)
        if len(used) != len(col_vals):
            return False

        remaining = [v for v in nums if v not in used]

        vis_so_far, max_so_far = prefix_visibility_info(col_vals)

        # Top clue feasibility bounds
        if top_clue:
            min_top = vis_so_far
            extra_top = sum(1 for v in remaining if v > max_so_far)
            max_top = vis_so_far + extra_top
            if not (min_top <= top_clue <= max_top):
                return False

        # Bottom clue feasibility via all completions of remaining values.
        # n is small in skyscrapers; this remains efficient with strong pruning.
        if bottom_clue:
            if not remaining:
                if visible_count(col_vals[::-1]) != bottom_clue:
                    return False
            else:
                found = False
                for tail in permutations(remaining):
                    full = col_vals + list(tail)
                    if clue_ok(top_clue, full) and clue_ok(bottom_clue, full[::-1]):
                        found = True
                        break
                if not found:
                    return False

        return True

    def clue_propagate(cands):
        # Filter row candidates by column prefix/suffix clue feasibility.
        progress = True
        while progress:
            progress = False
            order = sorted(range(n), key=lambda r: len(cands[r]))
            for r in order:
                new_list = []
                for p in cands[r]:
                    ok = True
                    for c in range(n):
                        # Build partial column using fixed rows only if singleton candidate,
                        # plus current hypothetical row p.
                        prefix = []
                        for rr in range(n):
                            if rr < r and len(cands[rr]) == 1:
                                prefix.append(cands[rr][0][c])
                            elif rr == r:
                                prefix.append(p[c])
                            elif rr < r:
                                break
                            else:
                                break
                        if not feasible_column_prefix(prefix, U[c], D[c]):
                            ok = False
                            break
                    if ok:
                        new_list.append(p)
                if not new_list:
                    return None
                if len(new_list) != len(cands[r]):
                    cands[r] = new_list
                    progress = True
            cands = latin_propagate(cands)
            if cands is None:
                return None
        return cands

    def final_grid_valid(grid):
        for r in range(n):
            row = grid[r]
            if set(row) != set(nums):
                return False
            if not clue_ok(L[r], row):
                return False
            if not clue_ok(R[r], row[::-1]):
                return False

        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != set(nums):
                return False
            if not clue_ok(U[c], col):
                return False
            if not clue_ok(D[c], col[::-1]):
                return False

        return True

    def search(cands):
        cands = [list(x) for x in cands]
        cands = latin_propagate(cands)
        if cands is None:
            return None
        cands = clue_propagate(cands)
        if cands is None:
            return None

        if all(len(cands[r]) == 1 for r in range(n)):
            grid = [list(cands[r][0]) for r in range(n)]
            return grid if final_grid_valid(grid) else None

        # Branch on most constrained row.
        r = min((i for i in range(n) if len(cands[i]) > 1), key=lambda i: len(cands[i]))

        # Better ordering: try rows that satisfy more column clue pressure first.
        def row_score(p):
            score = 0
            for c in range(n):
                if U[c]:
                    score += (p[c] == n)
                if D[c]:
                    score += (p[c] == 1)
            return -score

        for p in sorted(cands[r], key=row_score):
            new_cands = [list(x) for x in cands]
            new_cands[r] = [p]
            ans = search(new_cands)
            if ans is not None:
                return ans
        return None

    grid = search(row_cands)
    return str(grid) if grid is not None else "No Solution"


