from collections import deque, defaultdict
import copy

B = 1
W = 0
U = -1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx = {(r, c): r * m + c for r, c in cells}

    regions = defaultdict(list)
    clues = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            regions[rid].append((r, c))
            if data[r][c] is not None:
                clues[rid] = data[r][c]
    all_region_ids = sorted(regions.keys())

    for rid in all_region_ids:
        if rid not in clues:
            clues[rid] = None

    orth = {}
    diag = {}
    for r, c in cells:
        o = []
        d = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                o.append((rr, cc))
        for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                d.append((rr, cc))
        orth[(r, c)] = o
        diag[(r, c)] = d

    # Maximal row/column segments inside a single region.
    # Rule: any uninterrupted straight white segment cannot pass through >2 regions.
    # For a cell to be white, extending in its row and column through contiguous whites may cross region boundaries,
    # but each maximal uninterrupted segment can involve at most 2 distinct regions.
    # We enforce this incrementally by checking the current determined white-run implications.
    row_cells = [[(r, c) for c in range(m)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(m)]

    region_of = {(r, c): region[r][c] for r, c in cells}

    state = {cell: U for cell in cells}

    # Region bookkeeping
    reg_black = {rid: 0 for rid in all_region_ids}
    reg_unknown = {rid: len(regions[rid]) for rid in all_region_ids}

    # Initial forced by clue 0
    queue = deque()
    for rid in all_region_ids:
        clue = clues[rid]
        if clue == 0:
            for cell in regions[rid]:
                queue.append((cell, W, f"region {rid} clue 0"))
        elif clue is not None and clue == len(regions[rid]):
            # Impossible under no-adjacent-black if any region has touching cells, but keep generic
            for cell in regions[rid]:
                queue.append((cell, B, f"region {rid} full black"))

    def assign(st, cell, val):
        cur = st[cell]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        st[cell] = val
        rid = region_of[cell]
        reg_unknown[rid] -= 1
        if val == B:
            reg_black[rid] += 1
        return True

    def unassign(st, cell, old):
        rid = region_of[cell]
        cur = st[cell]
        if cur == U:
            return
        if cur == B:
            reg_black[rid] -= 1
        reg_unknown[rid] += 1
        st[cell] = old

    def region_bounds_ok(rid):
        clue = clues[rid]
        if clue is None:
            return True
        b = reg_black[rid]
        u = reg_unknown[rid]
        return b <= clue <= b + u

    def check_black_adjacency_local(st, cell):
        if st[cell] != B:
            return True
        for nb in orth[cell]:
            if st[nb] == B:
                return False
        return True

    def propagate_forced(st):
        changed = True
        while changed:
            changed = False

            # Region count propagation
            for rid in all_region_ids:
                clue = clues[rid]
                if clue is None:
                    continue
                b = reg_black[rid]
                u = reg_unknown[rid]
                if b > clue or b + u < clue:
                    return False
                if u == 0:
                    continue
                if b == clue:
                    for cell in regions[rid]:
                        if st[cell] == U:
                            if not assign(st, cell, W):
                                return False
                            changed = True
                elif b + u == clue:
                    for cell in regions[rid]:
                        if st[cell] == U:
                            if not assign(st, cell, B):
                                return False
                            changed = True

            # Black non-touching propagation
            for cell in cells:
                if st[cell] == B:
                    for nb in orth[cell]:
                        if st[nb] == B:
                            return False
                        if st[nb] == U:
                            if not assign(st, nb, W):
                                return False
                            changed = True

            # Row/column >2 region white-segment restriction:
            # For any determined contiguous run of cells that are not black, if all cells between two white/unknown ends
            # are forced to remain uninterrupted and already span >2 regions with no possible black splitter, contradiction.
            # Also if an unknown turned white would instantly create a >2-region segment, force black where allowed.
            if not apply_line_rule(st):
                return False

            # White connectivity viability
            if not white_connectivity_possible(st):
                return False

            # Single-cell impossibility checks
            for cell in cells:
                if st[cell] == U:
                    ok_w = test_tentative(st, cell, W)
                    ok_b = test_tentative(st, cell, B)
                    if not ok_w and not ok_b:
                        return False
                    if ok_w and not ok_b:
                        if not assign(st, cell, W):
                            return False
                        changed = True
                    elif ok_b and not ok_w:
                        if not assign(st, cell, B):
                            return False
                        changed = True

        return final_consistency(st)

    def final_consistency(st):
        for rid in all_region_ids:
            if not region_bounds_ok(rid):
                return False
        for cell in cells:
            if st[cell] == B and not check_black_adjacency_local(st, cell):
                return False
        if not line_rule_global_ok(st):
            return False
        if not white_connectivity_possible(st):
            return False
        if all(st[cell] != U for cell in cells):
            for rid in all_region_ids:
                clue = clues[rid]
                if clue is not None and reg_black[rid] != clue:
                    return False
            if not white_connected_final(st):
                return False
        return True

    def line_rule_global_ok(st):
        for r in range(n):
            if not check_line_ok([st[(r, c)] for c in range(m)], [region[r][c] for c in range(m)]):
                return False
        for c in range(m):
            if not check_line_ok([st[(r, c)] for r in range(n)], [region[r][c] for r in range(n)]):
                return False
        return True

    def check_line_ok(vals, regs):
        L = len(vals)
        i = 0
        while i < L:
            if vals[i] == B:
                i += 1
                continue
            j = i
            region_set = set()
            has_unknown = False
            while j < L and vals[j] != B:
                region_set.add(regs[j])
                if vals[j] == U:
                    has_unknown = True
                j += 1
            if len(region_set) > 2:
                return False
            i = j
        return True

    def apply_line_rule(st):
        # For each line, if assigning an unknown to white would create >2-region uninterrupted segment, force black.
        # If assigning black impossible due to region, then contradiction.
        progress = True
        while progress:
            progress = False
            for r in range(n):
                line = [(r, c) for c in range(m)]
                if not force_line_cells(st, line):
                    return False
                    # no progress after contradiction
            for c in range(m):
                line = [(r, c) for r in range(n)]
                if not force_line_cells(st, line):
                    return False
            # rely on outer changed loop for repeated effects
            break
        return True

    def force_line_cells(st, line):
        vals = [st[cell] for cell in line]
        regs = [region_of[cell] for cell in line]
        L = len(line)
        for i in range(L):
            if vals[i] != U:
                continue
            vals[i] = W
            if not check_line_ok(vals, regs):
                vals[i] = U
                # must be black
                old = st[line[i]]
                if not assign(st, line[i], B):
                    return False
                if not check_black_adjacency_local(st, line[i]):
                    return False
                rid = region_of[line[i]]
                if not region_bounds_ok(rid):
                    return False
            else:
                vals[i] = U
        return True

    def white_nodes_possible(st):
        return [cell for cell in cells if st[cell] != B]

    def white_connected_final(st):
        whites = [cell for cell in cells if st[cell] == W]
        if not whites:
            return True
        seen = set([whites[0]])
        dq = deque([whites[0]])
        while dq:
            cur = dq.popleft()
            for nb in orth[cur]:
                if st[nb] == W and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(whites)

    def white_connectivity_possible(st):
        possible = [cell for cell in cells if st[cell] != B]
        if not possible:
            return True
        start = possible[0]
        seen = {start}
        dq = deque([start])
        while dq:
            cur = dq.popleft()
            for nb in orth[cur]:
                if st[nb] != B and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(possible)

    def test_tentative(st, cell, val):
        old = st[cell]
        rid = region_of[cell]
        if not assign(st, cell, val):
            return False
        ok = True
        if val == B and not check_black_adjacency_local(st, cell):
            ok = False
        if ok and not region_bounds_ok(rid):
            ok = False
        if ok:
            for nb in orth[cell]:
                rr = region_of[nb]
                if not region_bounds_ok(rr):
                    ok = False
                    break
        if ok and not line_rule_global_ok(st):
            ok = False
        if ok and not white_connectivity_possible(st):
            ok = False
        unassign(st, cell, old)
        return ok

    def choose_branch_cell(st):
        best = None
        best_score = None
        for cell in cells:
            if st[cell] != U:
                continue
            rid = region_of[cell]
            clue = clues[rid]
            score = 0
            if clue is not None:
                need = clue - reg_black[rid]
                unk = reg_unknown[rid]
                score += 20 - abs(2 * need - unk)
                score += 10
            score += len(orth[cell])
            score += len({region_of[nb] for nb in orth[cell]})
            # cells on line boundaries are impactful for line-rule
            r, c = cell
            if (c > 0 and region[r][c - 1] != rid) or (c + 1 < m and region[r][c + 1] != rid):
                score += 3
            if (r > 0 and region[r - 1][c] != rid) or (r + 1 < n and region[r + 1][c] != rid):
                score += 3
            if best is None or score > best_score:
                best = cell
                best_score = score
        return best

    def search(st):
        if not propagate_forced(st):
            return None
        if all(st[cell] != U for cell in cells):
            if final_consistency(st):
                return st
            return None

        cell = choose_branch_cell(st)
        if cell is None:
            return None

        # Branch ordering guided by region demand and line pressure
        rid = region_of[cell]
        opts = [W, B]
        clue = clues[rid]
        if clue is not None:
            need = clue - reg_black[rid]
            unk = reg_unknown[rid]
            if need == 0:
                opts = [W, B]
            elif need == unk:
                opts = [B, W]
            elif need * 2 >= unk:
                opts = [B, W]

        for val in opts:
            if not test_tentative(st, cell, val):
                continue
            st2 = st.copy()
            # copy bookkeeping
            saved_reg_black = reg_black.copy()
            saved_reg_unknown = reg_unknown.copy()
            if not assign(st2, cell, val):
                continue
            # patch globals for recursive call
            old_rb = reg_black.copy()
            old_ru = reg_unknown.copy()
            reg_black.clear()
            reg_black.update(saved_reg_black)
            reg_unknown.clear()
            reg_unknown.update(saved_reg_unknown)
            # replay st2 difference from st for bookkeeping
            for cc in cells:
                if st[cc] == U and st2[cc] != U:
                    rr = region_of[cc]
                    reg_unknown[rr] -= 1
                    if st2[cc] == B:
                        reg_black[rr] += 1
            res = search(st2)
            if res is not None:
                return res
            reg_black.clear()
            reg_black.update(old_rb)
            reg_unknown.clear()
            reg_unknown.update(old_ru)
        return None

    # initialize bookkeeping from queued assignments
    while queue:
        cell, val, _reason = queue.popleft()
        if not assign(state, cell, val):
            return "No Solution"

    if not final_consistency(state):
        return "No Solution"

    result = search(state.copy())
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if result[(r, c)] == B else None)
        out.append(row)
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 3, 4, 4, 5], [0, 0, 1, 1, 2, 2, 3, 4, 4, 5], [0, 0, 6, 6, 7, 7, 7, 4, 4, 5], [0, 0, 6, 6, 7, 7, 7, 4, 4, 5], [0, 0, 8, 8, 9, 9, 9, 4, 4, 10], [11, 12, 12, 13, 13, 13, 14, 14, 14, 10], [11, 12, 12, 13, 13, 13, 14, 14, 14, 15], [16, 16, 16, 13, 13, 13, 17, 17, 18, 15], [19, 19, 20, 21, 21, 22, 23, 24, 18, 15], [19, 19, 20, 20, 20, 22, 23, 25, 25, 15]], 'data': [[None, None, None, None, 2, None, None, 3, None, 1], [None, None, None, None, None, None, None, None, None, None], [None, None, 2, None, 1, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, 1, None, None, None, None, None], [None, 2, None, 2, None, None, 1, None, None, None], [None, None, None, None, None, None, None, None, None, 0], [None, None, None, None, None, None, None, None, None, None], [None, None, None, 1, None, None, None, 0, None, None], [None, None, None, None, None, None, None, 1, None, None]]}

from collections import deque, defaultdict

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}

    regions = defaultdict(list)
    clue_by_region = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            regions[rid].append((r, c))
            if data[r][c] is not None:
                clue_by_region[rid] = data[r][c]

    region_ids = sorted(regions.keys())
    for rid in region_ids:
        if rid not in clue_by_region:
            return "No Solution"

    region_of = {}
    for rid, clist in regions.items():
        for cell in clist:
            region_of[cell] = rid

    orth = {}
    for r, c in cells:
        ns = []
        if r > 0:
            ns.append((r - 1, c))
        if r + 1 < n:
            ns.append((r + 1, c))
        if c > 0:
            ns.append((r, c - 1))
        if c + 1 < m:
            ns.append((r, c + 1))
        orth[(r, c)] = ns

    # Straight maximal row/column segments inside same row/column bounded by grid edges only.
    # Rule 3 means: along any contiguous white run in a row or column, the set of regions crossed
    # has size <= 2. Equivalently, no fully white 3-region witness subsegment may exist.
    row_triples = []
    for r in range(n):
        c0 = 0
        while c0 < m:
            c1 = c0
            seq = []
            while c1 < m:
                seq.append((r, c1))
                c1 += 1
            regs = [region_of[x] for x in seq]
            for a in range(len(seq)):
                regset = []
                seen = []
                for b in range(a, len(seq)):
                    rr = regs[b]
                    if not seen or seen[-1] != rr:
                        seen.append(rr)
                    if len(seen) >= 3:
                        if len(seen) == 3:
                            # minimal witness from first appearance of third distinct block
                            row_triples.append(tuple(seq[a:b + 1]))
                        break
            c0 = c1

    col_triples = []
    for c in range(m):
        r0 = 0
        while r0 < n:
            r1 = r0
            seq = []
            while r1 < n:
                seq.append((r1, c))
                r1 += 1
            regs = [region_of[x] for x in seq]
            for a in range(len(seq)):
                seen = []
                for b in range(a, len(seq)):
                    rr = regs[b]
                    if not seen or seen[-1] != rr:
                        seen.append(rr)
                    if len(seen) >= 3:
                        if len(seen) == 3:
                            col_triples.append(tuple(seq[a:b + 1]))
                        break
            r0 = r1

    # Deduplicate witnesses
    triple_witnesses = []
    seen_tw = set()
    for seg in row_triples + col_triples:
        if seg not in seen_tw:
            seen_tw.add(seg)
            triple_witnesses.append(seg)

    # Precompute region candidate masks under non-touching within region and immediate clue count.
    region_candidates = {}
    candidate_cells_cover = {}
    for rid in region_ids:
        clist = regions[rid]
        k = clue_by_region[rid]
        L = len(clist)
        local_idx = {clist[i]: i for i in range(L)}
        # conflict among cells that cannot both be black due to orth adjacency
        conf = [0] * L
        for i, cell in enumerate(clist):
            mask = 0
            for nb in orth[cell]:
                if nb in local_idx:
                    mask |= 1 << local_idx[nb]
            conf[i] = mask

        masks = []

        def gen(i, chosen_mask, chosen_cnt, forbidden_mask):
            if chosen_cnt > k:
                return
            if chosen_cnt + (L - i) < k:
                return
            if i == L:
                if chosen_cnt == k:
                    masks.append(chosen_mask)
                return
            # white
            gen(i + 1, chosen_mask, chosen_cnt, forbidden_mask)
            # black
            bit = 1 << i
            if not (forbidden_mask & bit):
                gen(i + 1, chosen_mask | bit, chosen_cnt + 1, forbidden_mask | bit | conf[i])

        gen(0, 0, 0, 0)
        if not masks:
            return "No Solution"
        region_candidates[rid] = masks
        cover = defaultdict(list)
        for mask in masks:
            for i, cell in enumerate(clist):
                if mask >> i & 1:
                    cover[cell].append(mask)
        candidate_cells_cover[rid] = cover

    # Global cross-region orth adjacency incompatibility
    cross_bad = defaultdict(set)
    for r, c in cells:
        for nb in orth[(r, c)]:
            if idx_of[(r, c)] < idx_of[nb]:
                if region_of[(r, c)] != region_of[nb]:
                    cross_bad[(r, c)].add(nb)
                    cross_bad[nb].add((r, c))

    state = {cell: UNKNOWN for cell in cells}
    active_candidates = {rid: list(masks) for rid, masks in region_candidates.items()}

    region_loc_index = {rid: {cell: i for i, cell in enumerate(regions[rid])} for rid in region_ids}

    def assign(cell, val, queue):
        cur = state[cell]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        state[cell] = val
        queue.append(cell)
        return True

    def filter_region_by_state(rid):
        clist = regions[rid]
        loc = region_loc_index[rid]
        newm = []
        for mask in active_candidates[rid]:
            ok = True
            for cell in clist:
                s = state[cell]
                if s == UNKNOWN:
                    continue
                bit = (mask >> loc[cell]) & 1
                if s == BLACK and bit == 0:
                    ok = False
                    break
                if s == WHITE and bit == 1:
                    ok = False
                    break
            if ok:
                # cross-region orth black conflicts with already black neighbors
                for cell in clist:
                    if (mask >> loc[cell]) & 1:
                        for nb in cross_bad.get(cell, ()):
                            if state[nb] == BLACK:
                                ok = False
                                break
                        if not ok:
                            break
            if ok:
                newm.append(mask)
        if not newm:
            return False
        active_candidates[rid] = newm
        return True

    def region_forced_assignments(rid, queue):
        clist = regions[rid]
        loc = region_loc_index[rid]
        masks = active_candidates[rid]
        for cell in clist:
            i = loc[cell]
            all_black = True
            any_black = False
            for mask in masks:
                if (mask >> i) & 1:
                    any_black = True
                else:
                    all_black = False
                if any_black and not all_black:
                    break
            if all_black:
                if not assign(cell, BLACK, queue):
                    return False
            elif not any_black:
                if not assign(cell, WHITE, queue):
                    return False
        return True

    def apply_non_touch(queue):
        while queue:
            cell = queue.popleft()
            if state[cell] == BLACK:
                for nb in orth[cell]:
                    if not assign(nb, WHITE, queue):
                        return False
                rid = region_of[cell]
                if not filter_region_by_state(rid):
                    return False
                if not region_forced_assignments(rid, queue):
                    return False
                for nb in cross_bad.get(cell, ()):
                    nr = region_of[nb]
                    if not filter_region_by_state(nr):
                        return False
                    if not region_forced_assignments(nr, queue):
                        return False
            else:
                rid = region_of[cell]
                if not filter_region_by_state(rid):
                    return False
                if not region_forced_assignments(rid, queue):
                    return False
        return True

    def apply_witness_rule(queue):
        changed = True
        while changed:
            changed = False
            for seg in triple_witnesses:
                vals = [state[x] for x in seg]
                if any(v == BLACK for v in vals):
                    continue
                unknowns = [seg[i] for i, v in enumerate(vals) if v == UNKNOWN]
                if not unknowns:
                    # all white => check regions crossed
                    regs = []
                    for x in seg:
                        rr = region_of[x]
                        if not regs or regs[-1] != rr:
                            regs.append(rr)
                    if len(regs) >= 3:
                        return False
                elif len(unknowns) == 1:
                    # this last unknown must be black to interrupt the 3-region white line
                    if not assign(unknowns[0], BLACK, queue):
                        return False
                    changed = True
            if changed:
                if not apply_non_touch(queue):
                    return False
        return True

    def white_connectivity_check():
        # White cells plus unknown cells must be able to connect all confirmed whites.
        passable = [cell for cell in cells if state[cell] != BLACK]
        if not passable:
            return False
        confirmed_white = [cell for cell in cells if state[cell] == WHITE]
        if not confirmed_white:
            return True
        start = confirmed_white[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for nb in orth[x]:
                if state[nb] != BLACK and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        for w in confirmed_white:
            if w not in seen:
                return False
        return True

    def force_articulations(queue):
        # Human-like: if a non-black candidate cell is the only bridge between two white components
        # in the current graph of possible white cells, it must be white.
        confirmed_white = [cell for cell in cells if state[cell] == WHITE]
        if len(confirmed_white) <= 1:
            return True

        passable = [cell for cell in cells if state[cell] != BLACK]
        passable_set = set(passable)

        # Build components of confirmed whites under passable graph.
        start = confirmed_white[0]
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for nb in orth[x]:
                if nb in passable_set and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        if all(w in seen for w in confirmed_white):
            return True

        # For each unknown passable cell, test whether removing it destroys ability to connect whites.
        # Only do this for unknown cells near frontier for efficiency.
        frontier = set()
        for w in confirmed_white:
            frontier.add(w)
            frontier.update(nb for nb in orth[w] if state[nb] == UNKNOWN)
        candidates = [x for x in frontier if state[x] == UNKNOWN]
        for cut in candidates:
            rem_start = None
            for w in confirmed_white:
                if w != cut:
                    rem_start = w
                    break
            if rem_start is None:
                continue
            seen2 = {rem_start}
            dq = deque([rem_start])
            while dq:
                x = dq.popleft()
                for nb in orth[x]:
                    if nb == cut or state[nb] == BLACK or nb in seen2:
                        continue
                    seen2.add(nb)
                    dq.append(nb)
            if any(w not in seen2 for w in confirmed_white if w != cut):
                if not assign(cut, WHITE, queue):
                    return False
        return True

    def propagate():
        queue = deque()
        # Initialize by filtering all regions and applying region-level forced cells.
        for rid in region_ids:
            if not filter_region_by_state(rid):
                return False
        for rid in region_ids:
            if not region_forced_assignments(rid, queue):
                return False
        if not apply_non_touch(queue):
            return False

        progress = True
        while progress:
            snapshot = tuple(state[cell] for cell in cells), tuple((rid, tuple(active_candidates[rid])) for rid in region_ids)
            if not apply_witness_rule(queue):
                return False
            if not force_articulations(queue):
                return False
            if not apply_non_touch(queue):
                return False
            if not white_connectivity_check():
                return False
            for rid in region_ids:
                if not filter_region_by_state(rid):
                    return False
            for rid in region_ids:
                if not region_forced_assignments(rid, queue):
                    return False
            if not apply_non_touch(queue):
                return False
            newsnapshot = tuple(state[cell] for cell in cells), tuple((rid, tuple(active_candidates[rid])) for rid in region_ids)
            progress = newsnapshot != snapshot
        return True

    def solved():
        if any(state[cell] == UNKNOWN for cell in cells):
            return False
        for rid in region_ids:
            cnt = sum(1 for cell in regions[rid] if state[cell] == BLACK)
            if cnt != clue_by_region[rid]:
                return False
        for cell in cells:
            if state[cell] == BLACK:
                for nb in orth[cell]:
                    if state[nb] == BLACK:
                        return False
        for seg in triple_witnesses:
            if all(state[x] == WHITE for x in seg):
                regs = []
                for x in seg:
                    rr = region_of[x]
                    if not regs or regs[-1] != rr:
                        regs.append(rr)
                if len(regs) >= 3:
                    return False
        whites = [cell for cell in cells if state[cell] == WHITE]
        if whites:
            seen = {whites[0]}
            dq = deque([whites[0]])
            while dq:
                x = dq.popleft()
                for nb in orth[x]:
                    if state[nb] == WHITE and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if len(seen) != len(whites):
                return False
        return True

    def choose_branch():
        # Prefer region with fewest candidate masks > 1; then pick a highly constrained cell.
        best_rid = None
        best_len = 10**9
        for rid in region_ids:
            l = len(active_candidates[rid])
            if 1 < l < best_len:
                best_len = l
                best_rid = rid
        if best_rid is not None:
            clist = regions[best_rid]
            loc = region_loc_index[best_rid]
            masks = active_candidates[best_rid]
            best_cell = None
            best_score = None
            for cell in clist:
                if state[cell] != UNKNOWN:
                    continue
                blacks = sum((mask >> loc[cell]) & 1 for mask in masks)
                whites = len(masks) - blacks
                score = abs(blacks - whites)
                deg = len(orth[cell])
                key = (score, -deg)
                if best_score is None or key < best_score:
                    best_score = key
                    best_cell = cell
            if best_cell is not None:
                blacks = sum((mask >> region_loc_index[best_rid][best_cell]) & 1 for mask in active_candidates[best_rid])
                whites = len(active_candidates[best_rid]) - blacks
                return best_cell, [BLACK, WHITE] if blacks <= whites else [WHITE, BLACK]

        # Fallback unknown cell with most constraints
        best = None
        best_metric = None
        for cell in cells:
            if state[cell] != UNKNOWN:
                continue
            rid = region_of[cell]
            masks = active_candidates[rid]
            i = region_loc_index[rid][cell]
            blacks = sum((mask >> i) & 1 for mask in masks)
            metric = (min(blacks, len(masks) - blacks), -len(orth[cell]))
            if best_metric is None or metric < best_metric:
                best_metric = metric
                best = cell
        if best is None:
            return None, None
        rid = region_of[best]
        i = region_loc_index[rid][best]
        masks = active_candidates[rid]
        blacks = sum((mask >> i) & 1 for mask in masks)
        whites = len(masks) - blacks
        return best, [BLACK, WHITE] if blacks <= whites else [WHITE, BLACK]

    def snapshot():
        return (
            dict(state),
            {rid: list(active_candidates[rid]) for rid in region_ids},
        )

    def restore(snap):
        nonlocal state, active_candidates
        state, active_candidates = snap[0], snap[1]

    def dfs():
        if not propagate():
            return False
        if solved():
            return True
        cell, order = choose_branch()
        if cell is None:
            return False
        snap = snapshot()
        for val in order:
            restore(snap)
            q = deque()
            if assign(cell, val, q) and apply_non_touch(q):
                if dfs():
                    return True
        restore(snap)
        return False

    if not dfs():
        return "No Solution"

    ans = [['B' if state[(r, c)] == BLACK else None for c in range(m)] for r in range(n)]
    return str(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 0, 1, 1], [2, 3, 3, 3, 1, 1], [2, 4, 5, 5, 1, 1], [2, 4, 5, 5, 6, 6], [7, 7, 8, 8, 8, 9], [7, 7, 10, 10, 11, 9]], 'data': [[1, None, None, None, 2, None], [None, None, None, None, None, None], [None, 0, None, None, None, None], [None, None, None, None, 0, None], [1, None, 1, None, None, 1], [None, None, None, None, None, None]]}

# Heyawake-like solver:
# 1. Region black-count clues.
# 2. Black cells non-orthogonally-adjacent.
# 3. Any maximal horizontal/vertical white run may intersect at most 2 regions.
# 4. White cells must be connected.
#
# The solver combines:
# - region candidate generation
# - human-like propagation:
#   * forced black/white from region clue saturation
#   * adjacency consequences
#   * line-run / "3-region crossing" deductions
#   * connectivity checks for white cells and black separators
# - depth-first search with strong branching on constrained regions/cells

from collections import deque, defaultdict

B = 1
W = 0
U = -1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx = {(r, c): r * m + c for r, c in cells}

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    neighbors = [[] for _ in range(n * m)]
    for r, c in cells:
        i = idx[(r, c)]
        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                neighbors[i].append(idx[(rr, cc)])

    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[region[r][c]].append(idx[(r, c)])
    region_ids = sorted(region_cells)

    region_clue = {}
    for rid in region_ids:
        clue = None
        for i in region_cells[rid]:
            r, c = divmod(i, m)
            if data[r][c] is not None:
                clue = data[r][c]
                break
        region_clue[rid] = clue

    # Region adjacency graph by border sharing
    region_adj = {rid: set() for rid in region_ids}
    border_right = [[False] * (m - 1) for _ in range(n)]
    border_down = [[False] * m for _ in range(n - 1)]
    for r in range(n):
        for c in range(m - 1):
            a, b = region[r][c], region[r][c + 1]
            if a != b:
                border_right[r][c] = True
                region_adj[a].add(b)
                region_adj[b].add(a)
    for r in range(n - 1):
        for c in range(m):
            a, b = region[r][c], region[r + 1][c]
            if a != b:
                border_down[r][c] = True
                region_adj[a].add(b)
                region_adj[b].add(a)

    # Precompute maximal row/col segments constrained by 3-region rule.
    # For every possible contiguous row segment [c1..c2] in a row, if there is no horizontal black
    # break inside it, then if all cells become white, segment may not span >2 regions.
    # Same for columns. We use this for contradiction and forcing.
    bad_row_segments = []
    for r in range(n):
        for c1 in range(m):
            regs = []
            last = None
            for c2 in range(c1, m):
                rg = region[r][c2]
                if rg != last:
                    regs.append(rg)
                    last = rg
                if len(regs) >= 3:
                    bad_row_segments.append(tuple(idx[(r, c)] for c in range(c1, c2 + 1)))
                    # Longer supersets also bad, keep all for stronger local forcing
    bad_col_segments = []
    for c in range(m):
        for r1 in range(n):
            regs = []
            last = None
            for r2 in range(r1, n):
                rg = region[r2][c]
                if rg != last:
                    regs.append(rg)
                    last = rg
                if len(regs) >= 3:
                    bad_col_segments.append(tuple(idx[(r, c)] for r in range(r1, r2 + 1)))

    bad_segments = bad_row_segments + bad_col_segments

    # For each cell, track bad segments containing it
    segs_of_cell = [[] for _ in range(n * m)]
    for si, seg in enumerate(bad_segments):
        for i in seg:
            segs_of_cell[i].append(si)

    # For each region with clue, generate valid internal black subsets respecting no-adjacent black.
    region_patterns = {}
    for rid in region_ids:
        clue = region_clue[rid]
        rcells = region_cells[rid]
        if clue is None:
            # no direct clue; any count allowed, but still no internal orth-adjacent blacks.
            # We do not enumerate all subsets for unclued regions.
            region_patterns[rid] = None
            continue
        if clue < 0 or clue > len(rcells):
            return "No Solution"

        # internal adjacency among region cells
        rcset = set(rcells)
        internal_neighbors = {i: [j for j in neighbors[i] if j in rcset] for i in rcells}

        ordered = sorted(rcells, key=lambda x: len(internal_neighbors[x]), reverse=True)
        pats = []

        def bt(k, chosen, blocked):
            if len(chosen) > clue:
                return
            rem = len(ordered) - k
            need = clue - len(chosen)
            if need < 0 or need > rem:
                return
            if k == len(ordered):
                if len(chosen) == clue:
                    pats.append(frozenset(chosen))
                return
            cell = ordered[k]
            # choose black
            if cell not in blocked and need > 0:
                nb = set(blocked)
                nb.add(cell)
                for j in internal_neighbors[cell]:
                    nb.add(j)
                chosen.append(cell)
                bt(k + 1, chosen, nb)
                chosen.pop()
            # choose white
            bt(k + 1, chosen, blocked)

        bt(0, [], set())
        region_patterns[rid] = pats
        if not pats:
            return "No Solution"

    region_of = [0] * (n * m)
    for rid, lst in region_cells.items():
        for i in lst:
            region_of[i] = rid

    def clone_state(state):
        return {
            'cell': state['cell'][:],
            'black_count': state['black_count'].copy(),
            'unknown_count': state['unknown_count'].copy(),
            'possible': {rid: (None if state['possible'][rid] is None else state['possible'][rid][:]) for rid in region_ids},
        }

    state = {
        'cell': [U] * (n * m),
        'black_count': {rid: 0 for rid in region_ids},
        'unknown_count': {rid: len(region_cells[rid]) for rid in region_ids},
        'possible': {rid: (None if region_patterns[rid] is None else region_patterns[rid][:]) for rid in region_ids},
    }

    def assign(state, i, val, queue):
        cur = state['cell'][i]
        if cur == val:
            return True
        if cur != U:
            return False
        state['cell'][i] = val
        rid = region_of[i]
        state['unknown_count'][rid] -= 1
        if val == B:
            state['black_count'][rid] += 1
        queue.append(i)
        return True

    def filter_region_patterns(state, rid, queue):
        pats = state['possible'][rid]
        clue = region_clue[rid]
        if pats is None:
            # Clued absent: only count lower/upper impossible checks from adjacency/known cells.
            return unclued_region_basic_checks(state, rid, queue)

        newp = []
        rcells = region_cells[rid]
        for p in pats:
            ok = True
            for i in rcells:
                v = state['cell'][i]
                if v == B and i not in p:
                    ok = False
                    break
                if v == W and i in p:
                    ok = False
                    break
            if ok:
                # external adjacency to black neighbors
                for i in p:
                    bad = False
                    for j in neighbors[i]:
                        if region_of[j] != rid and state['cell'][j] == B:
                            bad = True
                            break
                    if bad:
                        ok = False
                        break
            if ok:
                newp.append(p)

        if not newp:
            return False
        if len(newp) != len(pats):
            state['possible'][rid] = newp

        # common membership forcing
        common_black = set(newp[0])
        union_black = set(newp[0])
        for p in newp[1:]:
            common_black &= p
            union_black |= p

        for i in rcells:
            if i in common_black:
                if not assign(state, i, B, queue):
                    return False
            elif i not in union_black:
                if not assign(state, i, W, queue):
                    return False

        # exact count saturation
        if state['black_count'][rid] > clue:
            return False
        if state['black_count'][rid] + state['unknown_count'][rid] < clue:
            return False
        if state['black_count'][rid] == clue:
            for i in rcells:
                if state['cell'][i] == U:
                    if not assign(state, i, W, queue):
                        return False
        elif state['black_count'][rid] + state['unknown_count'][rid] == clue:
            for i in rcells:
                if state['cell'][i] == U:
                    if not assign(state, i, B, queue):
                        return False
        return True

    def unclued_region_basic_checks(state, rid, queue):
        # Only internal no-adj-black and no fixed count.
        rcells = region_cells[rid]
        for i in rcells:
            if state['cell'][i] == B:
                for j in neighbors[i]:
                    if j in rcells and state['cell'][j] == B:
                        return False
        return True

    def check_bad_segment_now(state, seg):
        vals = [state['cell'][i] for i in seg]
        # segment is invalid if no black present and all assigned white/unknown could form all-white
        # contradiction only when all are forced white.
        if all(v == W for v in vals):
            return False
        return True

    def propagate_bad_segments(state, queue):
        # Human-like rule:
        # For any segment that would cross 3+ regions:
        # - if all but one cells are already white, the last undecided must be black
        # - if all cells white => contradiction
        for seg in bad_segments:
            vals = [state['cell'][i] for i in seg]
            if any(v == B for v in vals):
                continue
            undec = [seg[k] for k, v in enumerate(vals) if v == U]
            if not undec:
                return False
            if len(undec) == 1:
                if not assign(state, undec[0], B, queue):
                    return False
        return True

    def white_connectivity_possible(state):
        # All confirmed white plus unknown cells are traversable for potential white connectivity.
        # If confirmed white cells are split by confirmed black barriers even through unknowns unavailable? Here unknowns are allowed.
        traversable = [state['cell'][i] != B for i in range(n * m)]
        white_nodes = [i for i in range(n * m) if state['cell'][i] == W]
        if not white_nodes:
            return True
        start = white_nodes[0]
        seen = {start}
        dq = deque([start])
        while dq:
            i = dq.popleft()
            for j in neighbors[i]:
                if traversable[j] and j not in seen:
                    seen.add(j)
                    dq.append(j)
        return all(i in seen for i in white_nodes)

    def no_isolated_unknown_white_requirement(state, queue):
        # If an unknown cell cannot be black (due adjacency/count/patterns) then force white? handled elsewhere.
        # Here detect confirmed non-black components impossible to connect all whites.
        return white_connectivity_possible(state)

    def final_white_connected(state):
        white_nodes = [i for i in range(n * m) if state['cell'][i] == W]
        if not white_nodes:
            return False
        start = white_nodes[0]
        seen = {start}
        dq = deque([start])
        while dq:
            i = dq.popleft()
            for j in neighbors[i]:
                if state['cell'][j] == W and j not in seen:
                    seen.add(j)
                    dq.append(j)
        return len(seen) == len(white_nodes)

    def propagate(state):
        queue = deque()

        # Seed all assigned cells already present
        for i in range(n * m):
            if state['cell'][i] != U:
                queue.append(i)

        # Initial region filtering
        for rid in region_ids:
            if not filter_region_patterns(state, rid, queue):
                return False

        if not propagate_bad_segments(state, queue):
            return False

        while queue:
            i = queue.popleft()
            v = state['cell'][i]

            if v == B:
                # black cells force orthogonal neighbors white
                for j in neighbors[i]:
                    if not assign(state, j, W, queue):
                        return False

            rid = region_of[i]
            if not filter_region_patterns(state, rid, queue):
                return False

            # Neighboring regions with patterns may be affected by external black adjacency
            for j in neighbors[i]:
                rj = region_of[j]
                if rj != rid:
                    if not filter_region_patterns(state, rj, queue):
                        return False

            # Local bad segments touching this cell
            touched = set(segs_of_cell[i])
            for si in touched:
                seg = bad_segments[si]
                vals = [state['cell'][x] for x in seg]
                if any(vv == B for vv in vals):
                    continue
                undec = [x for x in seg if state['cell'][x] == U]
                if not undec:
                    return False
                if len(undec) == 1:
                    if not assign(state, undec[0], B, queue):
                        return False

            if not no_isolated_unknown_white_requirement(state, queue):
                return False

        # Global post checks
        for seg in bad_segments:
            if not check_bad_segment_now(state, seg):
                return False

        for rid in region_ids:
            clue = region_clue[rid]
            bc = state['black_count'][rid]
            uc = state['unknown_count'][rid]
            if clue is not None:
                if bc > clue or bc + uc < clue:
                    return False

        if not white_connectivity_possible(state):
            return False

        return True

    def is_complete(state):
        return all(v != U for v in state['cell'])

    def valid_complete(state):
        # region counts
        for rid in region_ids:
            clue = region_clue[rid]
            if clue is not None and state['black_count'][rid] != clue:
                return False

        # no adj black
        for i in range(n * m):
            if state['cell'][i] == B:
                for j in neighbors[i]:
                    if state['cell'][j] == B:
                        return False

        # 3-region line rule on maximal white runs:
        # Since all cells decided, check actual maximal runs.
        for r in range(n):
            c = 0
            while c < m:
                if state['cell'][idx[(r, c)]] == B:
                    c += 1
                    continue
                c2 = c
                regs = []
                last = None
                while c2 < m and state['cell'][idx[(r, c2)]] != B:
                    rg = region[r][c2]
                    if rg != last:
                        regs.append(rg)
                        last = rg
                    c2 += 1
                if len(regs) > 2:
                    return False
                c = c2
        for c in range(m):
            r = 0
            while r < n:
                if state['cell'][idx[(r, c)]] == B:
                    r += 1
                    continue
                r2 = r
                regs = []
                last = None
                while r2 < n and state['cell'][idx[(r2, c)]] != B:
                    rg = region[r2][c]
                    if rg != last:
                        regs.append(rg)
                        last = rg
                    r2 += 1
                if len(regs) > 2:
                    return False
                r = r2

        if not final_white_connected(state):
            return False
        return True

    def candidate_values_for_cell(state, i):
        if state['cell'][i] != U:
            return [state['cell'][i]]
        rid = region_of[i]
        vals = []

        # quick feasibility of black
        black_ok = True
        for j in neighbors[i]:
            if state['cell'][j] == B:
                black_ok = False
                break
        clue = region_clue[rid]
        if clue is not None and state['black_count'][rid] >= clue:
            black_ok = False
        pats = state['possible'][rid]
        if pats is not None and not any(i in p for p in pats):
            black_ok = False

        white_ok = True
        if clue is not None and state['black_count'][rid] + state['unknown_count'][rid] - 1 < clue:
            white_ok = False
        if pats is not None and not any(i not in p for p in pats):
            white_ok = False

        # segment pressure: if some bad segment has all others white, black is forced
        force_black = False
        for si in segs_of_cell[i]:
            seg = bad_segments[si]
            if any(state['cell'][x] == B for x in seg if x != i):
                continue
            others = [x for x in seg if x != i]
            if all(state['cell'][x] == W for x in others):
                force_black = True
                break
        if force_black:
            white_ok = False

        if black_ok:
            vals.append(B)
        if white_ok:
            vals.append(W)
        return vals

    def choose_branch_cell(state):
        # Prefer cells in clued regions with smallest remaining pattern count.
        best = None
        best_score = None

        for rid in region_ids:
            pats = state['possible'][rid]
            if pats is not None:
                unknowns = [i for i in region_cells[rid] if state['cell'][i] == U]
                if not unknowns:
                    continue
                score = (0, len(pats), len(unknowns))
                if best_score is None or score < best_score:
                    # choose most informative cell in region: membership frequency near half
                    total = len(pats)
                    pick = None
                    pick_metric = None
                    for i in unknowns:
                        cnt = sum(1 for p in pats if i in p)
                        metric = abs(total - 2 * cnt)
                        vals = candidate_values_for_cell(state, i)
                        if len(vals) < 2:
                            continue
                        if pick_metric is None or metric < pick_metric:
                            pick_metric = metric
                            pick = i
                    if pick is None:
                        pick = unknowns[0]
                    best = pick
                    best_score = score

        if best is not None:
            return best

        # fallback: choose unknown cell with smallest domain, then most constrained by segments/neighbors
        for i in range(n * m):
            if state['cell'][i] == U:
                vals = candidate_values_for_cell(state, i)
                score = (len(vals), -len(segs_of_cell[i]), -len(neighbors[i]))
                if best_score is None or score < best_score:
                    best_score = score
                    best = i
        return best

    def search(state):
        if not propagate(state):
            return None
        if is_complete(state):
            if valid_complete(state):
                return state
            return None

        i = choose_branch_cell(state)
        if i is None:
            return None

        vals = candidate_values_for_cell(state, i)
        if not vals:
            return None

        # Value ordering: often black gives stronger propagation; if both possible, prefer forced-ish black.
        vals = sorted(vals, reverse=True)

        for val in vals:
            st2 = clone_state(state)
            q = deque()
            if not assign(st2, i, val, q):
                continue
            # include immediate queue entries from this assignment
            while q:
                st2_i = q.popleft()
                # emulate propagate's queue seed by marking already assigned; easier: just call search->propagate
                pass
            res = search(st2)
            if res is not None:
                return res
        return None

    result = search(state)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if result['cell'][idx[(r, c)]] == B else None)
        grid.append(row)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 4, 3, 2, 3], [4, 3, 2, 3, 5], [1, 2, 3, 1, 4], [5, 3, 1, 4, 2], [2, 4, 4, 3, 3]]}

from collections import deque

# Hitori solver:
# - State per cell: 1 = white, -1 = black, 0 = undecided
# - Human-like deductions:
#   1) Duplicates in a row/column imply at least one of each duplicate group must be black.
#   2) Adjacent equal cells in row/column cannot both be white, so all cells between them in that line
#      forced black by line uniqueness if endpoints stayed white; we encode simpler local implications:
#      if a cell is black, orthogonal neighbors must be white.
#   3) If in a duplicate group all but one candidate are black, remaining must be white; if one is white,
#      all other duplicates in that group must be black.
#   4) Connectivity pruning on white cells and potential white cells.
#   5) No isolated white possibility: any undecided/white cell that can no longer connect to white region
#      is pruned.
# Search only after fixpoint propagation, with branching on most constrained duplicate-related cell.

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    N = n * n

    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    values = [grid[r][c] for r in range(n) for c in range(n)]

    neighbors = [[] for _ in range(N)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < n:
                neighbors[i].append(idx(r, c + 1))

    row_groups = []
    col_groups = []
    cell_to_groups = [[] for _ in range(N)]

    for r in range(n):
        by_val = {}
        for c in range(n):
            i = idx(r, c)
            by_val.setdefault(grid[r][c], []).append(i)
        groups = [tuple(v) for v in by_val.values() if len(v) > 1]
        row_groups.extend(groups)

    for c in range(n):
        by_val = {}
        for r in range(n):
            i = idx(r, c)
            by_val.setdefault(grid[r][c], []).append(i)
        groups = [tuple(v) for v in by_val.values() if len(v) > 1]
        col_groups.extend(groups)

    all_groups = row_groups + col_groups
    for gi, g in enumerate(all_groups):
        for i in g:
            cell_to_groups[i].append(gi)

    duplicate_cells = {i for g in all_groups for i in g}

    # Conflict pairs: same row same value OR same col same value
    conflict = [set() for _ in range(N)]
    for g in all_groups:
        for i in g:
            for j in g:
                if i != j:
                    conflict[i].add(j)

    def assign(state, i, val, queue):
        cur = state[i]
        if cur == val:
            return True
        if cur == -val:
            return False
        state[i] = val
        queue.append(i)
        return True

    def check_connectivity_feasible(state):
        # White cells must be connectable through non-black cells.
        white = [i for i, s in enumerate(state) if s == 1]
        allowed = [i for i, s in enumerate(state) if s != -1]
        if not allowed:
            return False
        if white:
            start = white[0]
        else:
            start = allowed[0]
        seen = {start}
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if state[v] != -1 and v not in seen:
                    seen.add(v)
                    dq.append(v)
        for i in white:
            if i not in seen:
                return False
        # Also every allowed cell that is undecided/white should be in same possible component as whites if whites exist,
        # otherwise still okay if all allowed connected.
        if white:
            for i in allowed:
                # If a non-black cell is outside white-reachable component, it would become disconnected if white there.
                if i not in seen:
                    return False
        return True

    def check_no_black_adjacency(state):
        for i, s in enumerate(state):
            if s == -1:
                for j in neighbors[i]:
                    if state[j] == -1:
                        return False
        return True

    def check_uniqueness_consistency(state):
        # No two white-conflicting cells
        for i in range(N):
            if state[i] == 1:
                for j in conflict[i]:
                    if j > i and state[j] == 1:
                        return False
        # In every duplicate group, not all black
        for g in all_groups:
            if all(state[i] == -1 for i in g):
                return False
        return True

    def articulation_forced_whites(state, queue):
        # If blacking an undecided cell would disconnect current/potential white region, force it white.
        allowed = [i for i, s in enumerate(state) if s != -1]
        if len(allowed) <= 1:
            return True
        start = allowed[0]
        disc = {}
        low = {}
        parent = {}
        time = 0
        arts = set()

        def dfs(u):
            nonlocal time
            time += 1
            disc[u] = low[u] = time
            child = 0
            for v in neighbors[u]:
                if state[v] == -1:
                    continue
                if v not in disc:
                    parent[v] = u
                    child += 1
                    dfs(v)
                    low[u] = min(low[u], low[v])
                    if u not in parent and child > 1:
                        arts.add(u)
                    if u in parent and low[v] >= disc[u]:
                        arts.add(u)
                elif parent.get(u) != v:
                    low[u] = min(low[u], disc[v])

        dfs(start)
        if len(disc) != len(allowed):
            return False
        for u in arts:
            if state[u] == 0:
                if not assign(state, u, 1, queue):
                    return False
        return True

    def propagate(state):
        queue = deque(i for i, s in enumerate(state) if s != 0)

        # Initial deterministic deductions:
        # Orthogonally adjacent equal numbers cannot both be white due to row/col uniqueness,
        # but no direct forcing unless one decided.
        changed = True
        while changed:
            changed = False

            # Process explicit assignments implications
            while queue:
                i = queue.popleft()
                s = state[i]
                if s == -1:
                    for j in neighbors[i]:
                        if not assign(state, j, 1, queue):
                            return None
                    changed = True
                elif s == 1:
                    for j in conflict[i]:
                        if not assign(state, j, -1, queue):
                            return None
                    changed = True

            # Group deductions
            for g in all_groups:
                whites = [i for i in g if state[i] == 1]
                undec = [i for i in g if state[i] == 0]
                if len(whites) > 1:
                    return None
                if not whites and not undec:
                    return None
                if len(whites) == 1:
                    for i in undec:
                        if not assign(state, i, -1, queue):
                            return None
                        changed = True
                elif len(undec) == 1:
                    # all others black -> last one must be white
                    if not assign(state, undec[0], 1, queue):
                        return None
                    changed = True

            # Local adjacency/uniqueness forcing:
            # If a cell has a black neighbor pattern making it impossible to be black (adj black) and conflicts unresolved, force white.
            for i in range(N):
                if state[i] != 0:
                    continue
                if any(state[j] == -1 for j in neighbors[i]):
                    if not assign(state, i, 1, queue):
                        return None
                    changed = True

            # Connectivity articulation forcing
            if not articulation_forced_whites(state, queue):
                return None

            if queue:
                continue

            # Global consistency checks
            if not check_no_black_adjacency(state):
                return None
            if not check_uniqueness_consistency(state):
                return None
            if not check_connectivity_feasible(state):
                return None

        return state

    def choose_branch_cell(state):
        best = None
        best_score = None
        for i in range(N):
            if state[i] != 0:
                continue
            score = 0
            if i in duplicate_cells:
                score += 10
                score += len([j for j in conflict[i] if state[j] == 0]) * 3
                score += len([j for j in conflict[i] if state[j] == 1]) * 5
            score += len([j for j in neighbors[i] if state[j] == -1]) * 4
            score += len([j for j in neighbors[i] if state[j] == 0])
            if best is None or score > best_score:
                best = i
                best_score = score
        return best

    def branch_order(state, i):
        # Prefer black for duplicate-involved cells unless adjacent black prevents it.
        can_black = all(state[j] != -1 for j in neighbors[i])
        in_dup = i in duplicate_cells
        if in_dup and can_black:
            return (-1, 1)
        return (1, -1) if not can_black else (1, -1)

    def is_solved(state):
        return all(s != 0 for s in state)

    def finalize(state):
        if not check_no_black_adjacency(state):
            return None
        if not check_uniqueness_consistency(state):
            return None
        white_cells = [i for i, s in enumerate(state) if s == 1]
        if not white_cells:
            return None
        seen = {white_cells[0]}
        dq = deque([white_cells[0]])
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if state[v] == 1 and v not in seen:
                    seen.add(v)
                    dq.append(v)
        if len(seen) != len(white_cells):
            return None
        out = []
        for r in range(n):
            row = []
            for c in range(n):
                row.append('B' if state[idx(r, c)] == -1 else None)
            out.append(row)
        return out

    def dfs(state):
        state = state[:]
        state = propagate(state)
        if state is None:
            return None
        if is_solved(state):
            return finalize(state)

        i = choose_branch_cell(state)
        if i is None:
            return finalize(state)

        for val in branch_order(state, i):
            child = state[:]
            q = deque()
            if assign(child, i, val, q):
                result = dfs(child)
                if result is not None:
                    return result
        return None

    initial = [0] * N
    result = dfs(initial)
    return str(result) if result is not None else "No Solution"


