from itertools import permutations

# General Skyscrapers solver using human-like deduction:
# - Generate row candidates satisfying row-side clues.
# - Propagate column feasibility using Latin constraints + clue-compatible prefixes.
# - Apply forced placements and MRV branching only when deduction stalls.
# - Avoid naive cell-by-cell brute force.


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def clue_ok(seq, left_clue, right_clue):
    if left_clue and visible_count(seq) != left_clue:
        return False
    if right_clue and visible_count(seq[::-1]) != right_clue:
        return False
    return True


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    # Precompute row candidates by left/right clues.
    row_candidates = []
    for r in range(n):
        cands = [p for p in all_perms if clue_ok(p, L[r], R[r])]
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    # Precompute all column permutations by top/bottom clues.
    col_valid_full = []
    for c in range(n):
        cands = [p for p in all_perms if clue_ok(p, U[c], D[c])]
        if not cands:
            return "No Solution"
        col_valid_full.append(cands)

    # Prefix feasibility tables for each column:
    # prefix_sets[c][k] = set of prefixes of length k that can extend to some valid full column.
    prefix_sets = []
    for c in range(n):
        ps = [set() for _ in range(n + 1)]
        ps[0].add(())
        for perm in col_valid_full[c]:
            for k in range(1, n + 1):
                ps[k].add(perm[:k])
        prefix_sets.append(ps)

    # Domain as list of candidate row permutations.
    domains = [list(cands) for cands in row_candidates]

    def filter_domains(domains):
        # Repeated deduction until stable.
        changed = True
        while changed:
            changed = False

            # Cell-wise allowed values from row domains.
            row_pos_vals = []
            for r in range(n):
                pos = [set() for _ in range(n)]
                for cand in domains[r]:
                    for c, v in enumerate(cand):
                        pos[c].add(v)
                row_pos_vals.append(pos)

            # Filter rows by column prefix feasibility and column duplicate impossibility.
            for r in range(n):
                new_cands = []
                for cand in domains[r]:
                    ok = True
                    for c in range(n):
                        # Build possible prefix values in column c up to row r.
                        # Earlier rows may vary among their domains, but if a value is already impossible
                        # because no earlier row can realize needed entries jointly with current cand prefix,
                        # we conservatively use prefix feasibility on actual chosen values only at assigned rows
                        # via singleton rows. For unassigned rows, stronger checks below handle feasibility.
                        pass
                    if ok:
                        new_cands.append(cand)
                if not new_cands:
                    return None
                if len(new_cands) != len(domains[r]):
                    domains[r] = new_cands
                    changed = True

            # Forced cells from row domains.
            fixed_rows = [None] * n
            for r in range(n):
                if len(domains[r]) == 1:
                    fixed_rows[r] = domains[r][0]

            # Column-based filtering against fixed prefixes/suffixes and duplicate values in fixed rows.
            for r in range(n):
                new_cands = []
                for cand in domains[r]:
                    ok = True
                    for c in range(n):
                        # Duplicate against fixed rows in same column.
                        for rr in range(n):
                            if rr != r and fixed_rows[rr] is not None and fixed_rows[rr][c] == cand[c]:
                                ok = False
                                break
                        if not ok:
                            break

                        # Prefix feasibility using fixed rows up to each depth.
                        prefix = []
                        feasible = True
                        for rr in range(n):
                            if rr == r:
                                prefix.append(cand[c])
                            elif fixed_rows[rr] is not None:
                                prefix.append(fixed_rows[rr][c])
                            else:
                                break
                        k = len(prefix)
                        if tuple(prefix) not in prefix_sets[c][k]:
                            feasible = False
                        if not feasible:
                            ok = False
                            break

                        # Also check suffix feasibility from bottom using fixed trailing rows.
                        suffix = []
                        for rr in range(n - 1, -1, -1):
                            if rr == r:
                                suffix.append(cand[c])
                            elif fixed_rows[rr] is not None:
                                suffix.append(fixed_rows[rr][c])
                            else:
                                break
                        if suffix:
                            rev_prefix = tuple(reversed(suffix))
                            valid = False
                            # Reuse full valid columns reversed for bottom-side prefix check.
                            for perm in col_valid_full[c]:
                                if perm[n - len(rev_prefix):] == rev_prefix:
                                    valid = True
                                    break
                            if not valid:
                                ok = False
                                break

                    if ok:
                        new_cands.append(cand)
                if not new_cands:
                    return None
                if len(new_cands) != len(domains[r]):
                    domains[r] = new_cands
                    changed = True

            # Column value coverage and Hall-like singleton forcing light version.
            row_pos_vals = []
            for r in range(n):
                pos = [set() for _ in range(n)]
                for cand in domains[r]:
                    for c, v in enumerate(cand):
                        pos[c].add(v)
                row_pos_vals.append(pos)

            # For each column and value, it must appear in at least one row position candidate.
            for c in range(n):
                for v in nums:
                    possible_rows = [r for r in range(n) if v in row_pos_vals[r][c]]
                    if not possible_rows:
                        return None
                    if len(possible_rows) == 1:
                        rr = possible_rows[0]
                        new_cands = [cand for cand in domains[rr] if cand[c] == v]
                        if not new_cands:
                            return None
                        if len(new_cands) != len(domains[rr]):
                            domains[rr] = new_cands
                            changed = True

            # If a row is fixed, remove identical column values from same column in other rows.
            fixed_rows = [domains[r][0] if len(domains[r]) == 1 else None for r in range(n)]
            for rr in range(n):
                if fixed_rows[rr] is None:
                    continue
                row = fixed_rows[rr]
                for r in range(n):
                    if r == rr or len(domains[r]) == 1:
                        continue
                    new_cands = []
                    for cand in domains[r]:
                        good = True
                        for c in range(n):
                            if cand[c] == row[c]:
                                good = False
                                break
                        if good:
                            new_cands.append(cand)
                    if not new_cands:
                        return None
                    if len(new_cands) != len(domains[r]):
                        domains[r] = new_cands
                        changed = True

        return domains

    def complete_and_valid(domains):
        if any(len(d) != 1 for d in domains):
            return False
        grid = [list(d[0]) for d in domains]

        # Latin columns.
        target = set(nums)
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != target:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(col[::-1]) != D[c]:
                return False
        return True

    def optimistic_column_check(domains):
        # Strong feasibility check by exact matching each column against valid full columns,
        # considering row domains as allowed values at positions.
        allowed = []
        for r in range(n):
            pos = [set() for _ in range(n)]
            for cand in domains[r]:
                for c, v in enumerate(cand):
                    pos[c].add(v)
            allowed.append(pos)

        for c in range(n):
            found = False
            for perm in col_valid_full[c]:
                ok = True
                for r in range(n):
                    if perm[r] not in allowed[r][c]:
                        ok = False
                        break
                if ok:
                    found = True
                    break
            if not found:
                return False
        return True

    def search(domains):
        domains = [list(d) for d in domains]
        domains = filter_domains(domains)
        if domains is None:
            return None
        if not optimistic_column_check(domains):
            return None
        if complete_and_valid(domains):
            return [list(d[0]) for d in domains]

        # MRV row branching.
        r = min((i for i in range(n) if len(domains[i]) > 1), key=lambda i: len(domains[i]))

        # Least-constraining ordering: prefer candidates compatible with many column valid permutations.
        scored = []
        for cand in domains[r]:
            score = 0
            for c in range(n):
                cnt = 0
                for perm in col_valid_full[c]:
                    if perm[r] == cand[c]:
                        cnt += 1
                score += cnt
            scored.append((score, cand))
        scored.sort(reverse=True)

        for _, cand in scored:
            new_domains = [list(d) for d in domains]
            new_domains[r] = [cand]
            ans = search(new_domains)
            if ans is not None:
                return ans
        return None

    ans = search(domains)
    if ans is None:
        return "No Solution"
    return str(ans)


