def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    n = len(U)

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    # Precompute row candidates by side clues.
    row_candidates = []
    for r in range(n):
        lc = L[r]
        rc = R[r]
        cands = []
        for p in all_perms:
            if lc and visible_count(p) != lc:
                continue
            if rc and visible_count(p[::-1]) != rc:
                continue
            cands.append(p)
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    # Cell domains from row candidates.
    cell_domains = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            vals = set(p[c] for p in row_candidates[r])
            if not vals:
                return "No Solution"
            cell_domains[r][c] = vals

    # Column clue-aware feasibility check for partial columns.
    def col_prefix_bounds(prefix, top_clue, bottom_clue):
        k = len(prefix)
        used = set(prefix)
        rem = [x for x in nums if x not in used]

        # Current top visibility on prefix.
        top_seen = 0
        mx = 0
        for x in prefix:
            if x > mx:
                mx = x
                top_seen += 1

        # Min additional top-visible: append remaining in descending order.
        add_min = 0
        cur = mx
        for x in sorted(rem, reverse=True):
            if x > cur:
                cur = x
                add_min += 1

        # Max additional top-visible: append all remaining > mx in ascending order.
        add_max = sum(1 for x in rem if x > mx)

        top_min = top_seen + add_min
        top_max = top_seen + add_max

        if top_clue:
            if not (top_min <= top_clue <= top_max):
                return False

        # Bottom clue bounds using reversed full column:
        # reversed(full) starts with unknown suffix reversed, then reversed(prefix).
        rev_prefix = list(reversed(prefix))
        bottom_seen_known_tail = 0
        cur_tail = 0
        for x in rev_prefix:
            if x > cur_tail:
                cur_tail = x
                bottom_seen_known_tail += 1

        # For unknown suffix, choose order to minimize/maximize visibility before hitting known tail.
        # Min visibility from unknown suffix: descending order.
        unk_desc = sorted(rem, reverse=True)
        b_min_unk = 0
        cur = 0
        for x in unk_desc:
            if x > cur:
                cur = x
                b_min_unk += 1
        b_min = b_min_unk
        cur_after = cur
        b_min_tail = 0
        for x in rev_prefix:
            if x > cur_after:
                cur_after = x
                b_min_tail += 1
        bottom_min = b_min + b_min_tail

        # Max visibility from unknown suffix: ascending order.
        unk_asc = sorted(rem)
        b_max_unk = 0
        cur = 0
        for x in unk_asc:
            if x > cur:
                cur = x
                b_max_unk += 1
        b_max = b_max_unk
        cur_after = cur
        b_max_tail = 0
        for x in rev_prefix:
            if x > cur_after:
                cur_after = x
                b_max_tail += 1
        bottom_max = b_max + b_max_tail

        if bottom_clue:
            if not (bottom_min <= bottom_clue <= bottom_max):
                return False

        return True

    # Full column exact clue check.
    def col_ok(col_vals, top_clue, bottom_clue):
        if len(set(col_vals)) != n:
            return False
        if top_clue and visible_count(col_vals) != top_clue:
            return False
        if bottom_clue and visible_count(col_vals[::-1]) != bottom_clue:
            return False
        return True

    # Filter rows by current cell domains.
    def filter_row_candidates(row_cands, domains):
        changed = True
        while changed:
            changed = False
            for r in range(n):
                new = [p for p in row_cands[r] if all(p[c] in domains[r][c] for c in range(n))]
                if not new:
                    return None, None
                if len(new) != len(row_cands[r]):
                    row_cands[r] = new
                    changed = True

                for c in range(n):
                    vals = set(p[c] for p in row_cands[r])
                    if not vals:
                        return None, None
                    if vals != domains[r][c]:
                        domains[r][c] &= vals
                        if not domains[r][c]:
                            return None, None
                        changed = True

            # Column uniqueness propagation.
            for c in range(n):
                union = set()
                for r in range(n):
                    union |= domains[r][c]
                if union != set(nums):
                    # A missing number in a column means impossible.
                    return None, None

                for v in nums:
                    spots = [r for r in range(n) if v in domains[r][c]]
                    if not spots:
                        return None, None
                    if len(spots) == 1:
                        r = spots[0]
                        if domains[r][c] != {v}:
                            domains[r][c] = {v}
                            changed = True

                # If a row is fixed at a column, remove value from other rows in same column.
                fixed = {}
                for r in range(n):
                    if len(domains[r][c]) == 1:
                        v = next(iter(domains[r][c]))
                        if v in fixed:
                            return None, None
                        fixed[v] = r
                for v, rr in fixed.items():
                    for r in range(n):
                        if r != rr and v in domains[r][c]:
                            domains[r][c].remove(v)
                            if not domains[r][c]:
                                return None, None
                            changed = True

        return row_cands, domains

    # Order rows by constraint tightness.
    row_order = sorted(range(n), key=lambda r: len(row_candidates[r]))

    def search(assigned_rows, row_cands, domains):
        row_cands, domains = filter_row_candidates(
            [list(x) for x in row_cands],
            [[set(s) for s in row] for row in domains],
        )
        if row_cands is None:
            return None

        # Check partial column clue feasibility against fixed prefixes in actual row order.
        for c in range(n):
            prefix = []
            for r in range(n):
                if r in assigned_rows:
                    prefix.append(assigned_rows[r][c])
                else:
                    break
            # Only valid as prefix when assigned rows form initial segment; otherwise skip this lightweight check.
            if len(prefix) > 0 and all(rr in assigned_rows for rr in range(len(prefix))):
                if not col_prefix_bounds(prefix, U[c], D[c]):
                    return None

        if len(assigned_rows) == n:
            grid = [assigned_rows[r] for r in range(n)]
            for c in range(n):
                col = [grid[r][c] for r in range(n)]
                if not col_ok(col, U[c], D[c]):
                    return None
            return grid

        # Choose next row: minimum remaining candidates among unassigned rows.
        unassigned = [r for r in range(n) if r not in assigned_rows]
        r = min(unassigned, key=lambda x: len(row_cands[x]))

        # Candidate ordering: prefer rows that fit current column domains most tightly.
        def score(p):
            s = 0
            for c, v in enumerate(p):
                s += len(domains[r][c])
                col_used = {assigned_rows[rr][c] for rr in assigned_rows}
                if v in col_used:
                    s += 1000
            return s

        for p in sorted(row_cands[r], key=score):
            # Column uniqueness against assigned rows.
            bad = False
            for c, v in enumerate(p):
                for rr in assigned_rows:
                    if assigned_rows[rr][c] == v:
                        bad = True
                        break
                if bad:
                    break
            if bad:
                continue

            # Build next domains with row fixed.
            next_domains = [[set(s) for s in row] for row in domains]
            for c, v in enumerate(p):
                next_domains[r][c] = {v}

            # Remove fixed row values from other rows in same columns.
            for c, v in enumerate(p):
                for rr in range(n):
                    if rr != r and v in next_domains[rr][c]:
                        next_domains[rr][c].remove(v)
                        if not next_domains[rr][c]:
                            bad = True
                            break
                if bad:
                    break
            if bad:
                continue

            next_assigned = dict(assigned_rows)
            next_assigned[r] = p

            # Exact clue checks for any completed column.
            for c in range(n):
                if all(rr in next_assigned for rr in range(n)):
                    col = [next_assigned[rr][c] for rr in range(n)]
                    if not col_ok(col, U[c], D[c]):
                        bad = True
                        break
                else:
                    # Partial feasibility by domains: each value must still have at least one place.
                    possible = [next_domains[rr][c] for rr in range(n)]
                    if set().union(*possible) != set(nums):
                        bad = True
                        break
            if bad:
                continue

            res = search(next_assigned, row_cands, next_domains)
            if res is not None:
                return res

        return None

    result = search({}, row_candidates, cell_domains)
    return str([list(row) for row in result]) if result is not None else "No Solution"


