from collections import deque, defaultdict
from copy import deepcopy

# State encoding:
# -1 unknown
#  0 white
#  1 black

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]
    idx = {(r, c): r * m + c for r, c in cells}

    # Build regions and clues
    region_cells = defaultdict(list)
    region_clue = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            region_cells[rid].append((r, c))
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]
    for rid in region_cells:
        if rid not in region_clue:
            raise ValueError(f"Region {rid} has no clue")
    region_ids = sorted(region_cells.keys())

    # Orthogonal and diagonal-near adjacency for black prohibition
    orth = {}
    king = {}
    for r, c in cells:
        o = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                o.append((rr, cc))
        orth[(r, c)] = o
        k = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    k.append((rr, cc))
        king[(r, c)] = k

    # Precompute maximal straight segments for rule 3
    row_segments = []
    for r in range(n):
        start = 0
        while start < m:
            rid = region[r][start]
            end = start
            while end + 1 < m and region[r][end + 1] == rid:
                end += 1
            # expand contiguous cells until blocked by grid edge only; segment as maximal row run candidate
            # Rule applies to any uninterrupted white segment, so we use every maximal contiguous run of non-black cells.
            # During propagation we analyze dynamic runs on full row, but segment crossing count can be updated locally.
            row_segments.append([(r, c) for c in range(start, end + 1)])
            start = end + 1

    col_segments = []
    for c in range(m):
        start = 0
        while start < n:
            rid = region[start][c]
            end = start
            while end + 1 < n and region[end + 1][c] == rid:
                end += 1
            col_segments.append([(r, c) for r in range(start, end + 1)])
            start = end + 1

    # More useful: for each row/col, region sequence along that line
    row_rids = [[region[r][c] for c in range(m)] for r in range(n)]
    col_rids = [[region[r][c] for r in range(n)] for c in range(m)]

    def dynamic_line_runs(states, is_row, fixed):
        # returns list of runs (list of coordinates) of cells that are not black
        runs = []
        cur = []
        if is_row:
            for c in range(m):
                cell = (fixed, c)
                if states[cell] != 1:
                    cur.append(cell)
                else:
                    if cur:
                        runs.append(cur)
                        cur = []
        else:
            for r in range(n):
                cell = (r, fixed)
                if states[cell] != 1:
                    cur.append(cell)
                else:
                    if cur:
                        runs.append(cur)
                        cur = []
        if cur:
            runs.append(cur)
        return runs

    def run_region_count(run):
        seen = 0
        prev = None
        for r, c in run:
            rid = region[r][c]
            if rid != prev:
                seen += 1
                prev = rid
        return seen

    # Candidate combinations per region from black non-touching inside region and clue count
    region_patterns = {}
    for rid in region_ids:
        rcells = region_cells[rid]
        clue = region_clue[rid]
        # enumerate subsets with size clue and respecting orthogonal non-touch globally inside region
        # region sizes are small; this is efficient and human-like region candidate listing
        pat = []

        def rec(i, chosen, chosen_set):
            if len(chosen) > clue:
                return
            if i == len(rcells):
                if len(chosen) == clue:
                    pat.append(tuple(sorted(chosen)))
                return
            remaining = len(rcells) - i
            need = clue - len(chosen)
            if need < 0 or need > remaining:
                return
            cell = rcells[i]
            # choose black if compatible with chosen
            ok = True
            for nb in orth[cell]:
                if nb in chosen_set:
                    ok = False
                    break
            if ok and need > 0:
                chosen.append(cell)
                chosen_set.add(cell)
                rec(i + 1, chosen, chosen_set)
                chosen_set.remove(cell)
                chosen.pop()
            # choose white
            rec(i + 1, chosen, chosen_set)

        rec(0, [], set())
        if not pat:
            return "No Solution"
        region_patterns[rid] = pat

    class Contradiction(Exception):
        pass

    def make_state():
        return {
            'cell': {cell: -1 for cell in cells},
            'reg_possible': {rid: set(range(len(region_patterns[rid]))) for rid in region_ids},
        }

    def clone_state(st):
        return {
            'cell': st['cell'].copy(),
            'reg_possible': {rid: s.copy() for rid, s in st['reg_possible'].items()},
        }

    def assign(st, cell, value, queue):
        cur = st['cell'][cell]
        if cur == value:
            return
        if cur != -1 and cur != value:
            raise Contradiction
        st['cell'][cell] = value
        queue.append(('cell', cell))

    def filter_region_patterns(st, rid, queue):
        poss = st['reg_possible'][rid]
        new_poss = set()
        rcells = region_cells[rid]
        for pi in poss:
            blacks = set(region_patterns[rid][pi])
            ok = True
            for cell in rcells:
                v = st['cell'][cell]
                if v == 1 and cell not in blacks:
                    ok = False
                    break
                if v == 0 and cell in blacks:
                    ok = False
                    break
            if not ok:
                continue
            # black cells cannot touch orthogonally outside region
            for b in blacks:
                for nb in orth[b]:
                    if st['cell'][nb] == 1 and nb not in blacks:
                        ok = False
                        break
                if not ok:
                    break
            # row/col >2 region rule local feasibility check with fixed blacks
            if ok:
                for b in blacks:
                    # tentative blacks already in pattern; enough to check current dynamic runs after assigning pattern cells?
                    # Use lightweight necessary check by forbidding impossible already-existing pure-white runs >2 due to fixed blacks.
                    pass
            if ok:
                new_poss.add(pi)
        if not new_poss:
            raise Contradiction
        if new_poss != poss:
            st['reg_possible'][rid] = new_poss
            queue.append(('region', rid))

    def enforce_region_from_patterns(st, rid, queue):
        poss = st['reg_possible'][rid]
        rcells = region_cells[rid]
        if len(poss) == 1:
            blacks = set(region_patterns[rid][next(iter(poss))])
            for cell in rcells:
                assign(st, cell, 1 if cell in blacks else 0, queue)
            return
        # intersection reasoning
        always_black = set(rcells)
        always_white = set(rcells)
        for pi in poss:
            blacks = set(region_patterns[rid][pi])
            always_black &= blacks
            always_white &= (set(rcells) - blacks)
        for cell in always_black:
            assign(st, cell, 1, queue)
        for cell in always_white:
            assign(st, cell, 0, queue)

    def enforce_black_adjacency(st, cell, queue):
        if st['cell'][cell] != 1:
            return
        for nb in orth[cell]:
            assign(st, nb, 0, queue)

    def check_line_rule_complete(st):
        for r in range(n):
            for run in dynamic_line_runs(st['cell'], True, r):
                if run_region_count(run) > 2:
                    return False
        for c in range(m):
            for run in dynamic_line_runs(st['cell'], False, c):
                if run_region_count(run) > 2:
                    return False
        return True

    def line_rule_propagate(st, queue):
        # Human-like deduction:
        # If a current not-black run already spans >2 regions => contradiction.
        # If an unknown cell is the only possible blocker preventing a >2-region run, force it black.
        changed = True
        while changed:
            changed = False
            for r in range(n):
                vals = [st['cell'][(r, c)] for c in range(m)]
                for c in range(m):
                    if vals[c] != -1:
                        continue
                    st['cell'][(r, c)] = 0
                    bad_white = False
                    for run in dynamic_line_runs(st['cell'], True, r):
                        if run_region_count(run) > 2:
                            bad_white = True
                            break
                    st['cell'][(r, c)] = -1
                    if bad_white:
                        assign(st, (r, c), 1, queue)
                        changed = True
            for c in range(m):
                vals = [st['cell'][(r, c)] for r in range(n)]
                for r in range(n):
                    if vals[r] != -1:
                        continue
                    st['cell'][(r, c)] = 0
                    bad_white = False
                    for run in dynamic_line_runs(st['cell'], False, c):
                        if run_region_count(run) > 2:
                            bad_white = True
                            break
                    st['cell'][(r, c)] = -1
                    if bad_white:
                        assign(st, (r, c), 1, queue)
                        changed = True
        if not check_line_rule_complete(st):
            raise Contradiction

    def connectivity_possible(st):
        whites = [cell for cell in cells if st['cell'][cell] == 0]
        unknowns = {cell for cell in cells if st['cell'][cell] == -1}
        if not whites:
            return True
        allowed = set(whites) | unknowns
        q = deque([whites[0]])
        vis = {whites[0]}
        while q:
            u = q.popleft()
            for v in orth[u]:
                if v in allowed and v not in vis:
                    vis.add(v)
                    q.append(v)
        return all(w in vis for w in whites)

    def connectivity_forced_white(st, queue):
        # Articulation-style simple test: if setting unknown to black disconnects existing white cells, force white.
        if not connectivity_possible(st):
            raise Contradiction
        white_count = sum(1 for cell in cells if st['cell'][cell] == 0)
        if white_count == 0:
            return
        for cell in cells:
            if st['cell'][cell] != -1:
                continue
            st['cell'][cell] = 1
            ok = connectivity_possible(st)
            # also all unknown/white should still be able to cover unresolved region needs
            st['cell'][cell] = -1
            if not ok:
                assign(st, cell, 0, queue)

    def final_connectivity(st):
        whites = [cell for cell in cells if st['cell'][cell] == 0]
        if not whites:
            return False
        q = deque([whites[0]])
        vis = {whites[0]}
        while q:
            u = q.popleft()
            for v in orth[u]:
                if st['cell'][v] == 0 and v not in vis:
                    vis.add(v)
                    q.append(v)
        return len(vis) == len(whites)

    def propagate(st):
        queue = deque()
        for rid in region_ids:
            queue.append(('region', rid))
        for cell in cells:
            if st['cell'][cell] != -1:
                queue.append(('cell', cell))
        while queue:
            typ, obj = queue.popleft()
            if typ == 'cell':
                cell = obj
                if st['cell'][cell] == 1:
                    enforce_black_adjacency(st, cell, queue)
                rid = region[cell[0]][cell[1]]
                filter_region_patterns(st, rid, queue)
                # neighboring regions may be affected by black adjacency
                for nb in orth[cell]:
                    nrid = region[nb[0]][nb[1]]
                    if nrid != rid:
                        filter_region_patterns(st, nrid, queue)
            else:
                rid = obj
                filter_region_patterns(st, rid, queue)
                enforce_region_from_patterns(st, rid, queue)
        line_rule_propagate(st, queue)
        while queue:
            typ, obj = queue.popleft()
            if typ == 'cell':
                cell = obj
                if st['cell'][cell] == 1:
                    enforce_black_adjacency(st, cell, queue)
                rid = region[cell[0]][cell[1]]
                filter_region_patterns(st, rid, queue)
                for nb in orth[cell]:
                    nrid = region[nb[0]][nb[1]]
                    if nrid != rid:
                        filter_region_patterns(st, nrid, queue)
            else:
                rid = obj
                filter_region_patterns(st, rid, queue)
                enforce_region_from_patterns(st, rid, queue)
        connectivity_forced_white(st, queue)
        while queue:
            typ, obj = queue.popleft()
            if typ == 'cell':
                cell = obj
                if st['cell'][cell] == 1:
                    enforce_black_adjacency(st, cell, queue)
                rid = region[cell[0]][cell[1]]
                filter_region_patterns(st, rid, queue)
                for nb in orth[cell]:
                    nrid = region[nb[0]][nb[1]]
                    if nrid != rid:
                        filter_region_patterns(st, nrid, queue)
            else:
                rid = obj
                filter_region_patterns(st, rid, queue)
                enforce_region_from_patterns(st, rid, queue)
        if not check_line_rule_complete(st):
            raise Contradiction
        if not connectivity_possible(st):
            raise Contradiction

    def is_solved(st):
        return all(st['cell'][cell] != -1 for cell in cells)

    def validate_complete(st):
        for rid in region_ids:
            cnt = sum(1 for cell in region_cells[rid] if st['cell'][cell] == 1)
            if cnt != region_clue[rid]:
                return False
        for cell in cells:
            if st['cell'][cell] == 1:
                for nb in orth[cell]:
                    if st['cell'][nb] == 1:
                        return False
        if not check_line_rule_complete(st):
            return False
        if not final_connectivity(st):
            return False
        return True

    def choose_branch(st):
        # Prefer most constrained region, then cell with strongest implication
        best = None
        for rid in region_ids:
            k = len(st['reg_possible'][rid])
            if k > 1:
                score = (k, len(region_cells[rid]))
                if best is None or score < best[0]:
                    best = (score, ('region', rid))
        if best is not None:
            return best[1]
        # fallback cell
        best_cell = None
        best_score = None
        for cell in cells:
            if st['cell'][cell] == -1:
                rid = region[cell[0]][cell[1]]
                black_support = 0
                white_support = 0
                for pi in st['reg_possible'][rid]:
                    blacks = set(region_patterns[rid][pi])
                    if cell in blacks:
                        black_support += 1
                    else:
                        white_support += 1
                score = min(black_support, white_support)
                if best_score is None or score < best_score:
                    best_score = score
                    best_cell = cell
        return ('cell', best_cell)

    def search(st):
        try:
            propagate(st)
        except Contradiction:
            return None
        if is_solved(st):
            return st if validate_complete(st) else None

        kind, obj = choose_branch(st)
        if kind == 'region':
            rid = obj
            # Branch on region pattern candidates
            order = sorted(st['reg_possible'][rid], key=lambda pi: sum(
                1 for b in region_patterns[rid][pi] for nb in orth[b] if st['cell'][nb] == -1
            ))
            for pi in order:
                ns = clone_state(st)
                ns['reg_possible'][rid] = {pi}
                res = search(ns)
                if res is not None:
                    return res
        else:
            cell = obj
            rid = region[cell[0]][cell[1]]
            black_support = any(cell in set(region_patterns[rid][pi]) for pi in st['reg_possible'][rid])
            white_support = any(cell not in set(region_patterns[rid][pi]) for pi in st['reg_possible'][rid])
            # Try more constrained value first
            vals = []
            if black_support and white_support:
                can_black = True
                for nb in orth[cell]:
                    if st['cell'][nb] == 1:
                        can_black = False
                        break
                # Heuristic: prefer forced-looking choice by testing contradictions cheaply
                prefs = [1, 0] if can_black else [0]
                if 0 not in prefs:
                    prefs.append(0)
                vals = prefs
            elif black_support:
                vals = [1]
            else:
                vals = [0]
            used = set()
            for v in vals:
                if v in used:
                    continue
                used.add(v)
                ns = clone_state(st)
                try:
                    q = deque()
                    assign(ns, cell, v, q)
                except Contradiction:
                    continue
                res = search(ns)
                if res is not None:
                    return res
        return None

    st = make_state()
    result = search(st)
    if result is None:
        return "No Solution"
    ans = [['B' if result['cell'][(r, c)] == 1 else None for c in range(m)] for r in range(n)]
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 0, 0, 0], [1, 1, 2, 3, 3, 4], [1, 1, 5, 5, 6, 4], [1, 1, 7, 7, 7, 7], [8, 9, 9, 9, 9, 10], [11, 9, 9, 9, 9, 10]], 'data': [[2, None, None, None, None, None], [None, None, 0, None, None, None], [None, None, 1, None, None, None], [None, None, 2, None, None, None], [1, 2, None, None, None, None], [None, None, None, None, None, None]]}

from collections import deque, defaultdict
from copy import deepcopy

BLACK = 1
WHITE = 0
UNKNOWN = -1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}
    rc_of = {idx_of[(r, c)]: (r, c) for r, c in cells}

    regions = defaultdict(list)
    clue_by_region = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            regions[rid].append((r, c))
            if data[r][c] is not None:
                clue_by_region[rid] = data[r][c]

    region_ids = sorted(regions.keys())
    if set(region_ids) != set(clue_by_region.keys()):
        return "No Solution"

    orth = {}
    diag = {}
    for r, c in cells:
        o = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                o.append((rr, cc))
        orth[(r, c)] = o
        d = []
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    d.append((rr, cc))
        diag[(r, c)] = d

    row_segments = []
    for r in range(n):
        start = 0
        while start < m:
            rid = region[r][start]
            end = start + 1
            while end < m and region[r][end] == rid:
                end += 1
            seg = [(r, c) for c in range(start, end)]
            row_segments.append(seg)
            start = end

    col_segments = []
    for c in range(m):
        start = 0
        while start < n:
            rid = region[start][c]
            end = start + 1
            while end < n and region[end][c] == rid:
                end += 1
            seg = [(r, c) for r in range(start, end)]
            col_segments.append(seg)
            start = end

    lines = []
    for r in range(n):
        lines.append([(r, c) for c in range(m)])
    for c in range(m):
        lines.append([(r, c) for r in range(n)])

    # For each line, every maximal white run may intersect at most 2 distinct regions.
    # Precompute all contiguous windows of 3 cells whose regions are pairwise from 3 distinct region ids.
    # In such a triple, not all 3 can be white simultaneously.
    triple_constraints = []
    for line in lines:
        for i in range(len(line) - 2):
            triple = line[i:i + 3]
            rset = {region[r][c] for r, c in triple}
            if len(rset) == 3:
                triple_constraints.append(tuple(triple))

    region_cell_list = {rid: list(lst) for rid, lst in regions.items()}
    region_sizes = {rid: len(lst) for rid, lst in region_cell_list.items()}
    cell_region = {(r, c): region[r][c] for r, c in cells}

    # State
    state = {cell: UNKNOWN for cell in cells}

    def clone_state(st):
        return dict(st)

    def region_counts(st, rid):
        b = 0
        w = 0
        u = 0
        for cell in region_cell_list[rid]:
            v = st[cell]
            if v == BLACK:
                b += 1
            elif v == WHITE:
                w += 1
            else:
                u += 1
        return b, w, u

    def assign(st, cell, val, queue):
        cur = st[cell]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        st[cell] = val
        queue.append(cell)
        return True

    def check_region_feasible(st, rid):
        clue = clue_by_region[rid]
        b, w, u = region_counts(st, rid)
        if b > clue:
            return False
        if b + u < clue:
            return False
        return True

    def line_region_violation(st, line):
        seen_regions = set()
        in_run = False
        run_regions = set()
        for cell in line:
            if st[cell] == WHITE:
                if not in_run:
                    in_run = True
                    run_regions = {cell_region[cell]}
                else:
                    run_regions.add(cell_region[cell])
                    if len(run_regions) > 2:
                        return True
            else:
                in_run = False
                run_regions = set()
        return False

    def any_line_violation(st):
        for line in lines:
            if line_region_violation(st, line):
                return True
        return False

    def white_connectivity_possible(st):
        white_cells = [c for c in cells if st[c] == WHITE]
        non_black = [c for c in cells if st[c] != BLACK]
        if not non_black:
            return False
        start = white_cells[0] if white_cells else non_black[0]
        dq = deque([start])
        seen = {start}
        while dq:
            cell = dq.popleft()
            for nb in orth[cell]:
                if nb not in seen and st[nb] != BLACK:
                    seen.add(nb)
                    dq.append(nb)
        for c in white_cells:
            if c not in seen:
                return False
        return True

    def white_connectivity_final(st):
        white_cells = [c for c in cells if st[c] == WHITE]
        if not white_cells:
            return False
        dq = deque([white_cells[0]])
        seen = {white_cells[0]}
        while dq:
            cell = dq.popleft()
            for nb in orth[cell]:
                if nb not in seen and st[nb] == WHITE:
                    seen.add(nb)
                    dq.append(nb)
        return len(seen) == len(white_cells)

    def apply_local_deductions(st):
        queue = deque(cells)
        inq = set(cells)

        while queue:
            cell = queue.popleft()
            inq.discard(cell)

            # Orthogonal black adjacency
            if st[cell] == BLACK:
                for nb in orth[cell]:
                    if not assign(st, nb, WHITE, queue):
                        return False

            # Triple constraints on lines: in any 3 consecutive cells from 3 distinct regions, not all can be white
            # if two white then third black; if all white contradiction
            for triple in triple_constraints:
                if cell not in triple:
                    continue
                vals = [st[x] for x in triple]
                wc = vals.count(WHITE)
                uc = vals.count(UNKNOWN)
                if wc == 3:
                    return False
                if wc == 2 and uc == 1:
                    x = triple[vals.index(UNKNOWN)]
                    if not assign(st, x, BLACK, queue):
                        return False

            rid = cell_region[cell]
            clue = clue_by_region[rid]
            b, w, u = region_counts(st, rid)
            if b > clue or b + u < clue:
                return False
            if b == clue:
                for x in region_cell_list[rid]:
                    if st[x] == UNKNOWN:
                        if not assign(st, x, WHITE, queue):
                            return False
            if b + u == clue:
                for x in region_cell_list[rid]:
                    if st[x] == UNKNOWN:
                        if not assign(st, x, BLACK, queue):
                            return False

            # If a cell cannot be black due to touching an existing black orthogonally, force white
            if st[cell] == UNKNOWN:
                if any(st[nb] == BLACK for nb in orth[cell]):
                    if not assign(st, cell, WHITE, queue):
                        return False

            # If setting a cell white would instantly make a 3-region white triple impossible, sometimes force black.
            if st[cell] == UNKNOWN:
                force_black = False
                for triple in triple_constraints:
                    if cell not in triple:
                        continue
                    others = [x for x in triple if x != cell]
                    if all(st[x] == WHITE for x in others):
                        force_black = True
                        break
                if force_black:
                    if not assign(st, cell, BLACK, queue):
                        return False

            # If a region still needs k blacks and exactly k cells remain non-forced-by-adj? handled by b+u==clue
            # Additional human-like: cells diagonally irrelevant; only orth adjacency matters.

            # Early line contradiction check on affected row/col
            r, c = cell
            if line_region_violation(st, [(r, cc) for cc in range(m)]):
                return False
            if line_region_violation(st, [(rr, c) for rr in range(n)]):
                return False

            if not check_region_feasible(st, rid):
                return False

        if any_line_violation(st):
            return False
        if not white_connectivity_possible(st):
            return False
        return True

    def candidate_black_possible(st, cell):
        if st[cell] == WHITE:
            return False
        if any(st[nb] == BLACK for nb in orth[cell]):
            return False
        rid = cell_region[cell]
        b, w, u = region_counts(st, rid)
        return b < clue_by_region[rid]

    def candidate_white_possible(st, cell):
        if st[cell] == BLACK:
            return False
        tmp = clone_state(st)
        tmp[cell] = WHITE
        # Fast local line checks
        r, c = cell
        if line_region_violation(tmp, [(r, cc) for cc in range(m)]):
            return False
        if line_region_violation(tmp, [(rr, c) for rr in range(n)]):
            return False
        return True

    def speculative_propagation(st):
        changed = True
        while changed:
            changed = False
            for cell in cells:
                if st[cell] != UNKNOWN:
                    continue
                can_b = candidate_black_possible(st, cell)
                can_w = candidate_white_possible(st, cell)
                if not can_b and not can_w:
                    return False
                if can_b and not can_w:
                    st[cell] = BLACK
                    changed = True
                    if not apply_local_deductions(st):
                        return False
                elif can_w and not can_b:
                    st[cell] = WHITE
                    changed = True
                    if not apply_local_deductions(st):
                        return False
        return True

    def is_solved(st):
        if any(st[c] == UNKNOWN for c in cells):
            return False
        for rid in region_ids:
            b, w, u = region_counts(st, rid)
            if b != clue_by_region[rid]:
                return False
        for cell in cells:
            if st[cell] == BLACK:
                if any(st[nb] == BLACK for nb in orth[cell]):
                    return False
        if any_line_violation(st):
            return False
        if not white_connectivity_final(st):
            return False
        return True

    def choose_branch_cell(st):
        best = None
        best_score = None
        for cell in cells:
            if st[cell] != UNKNOWN:
                continue
            rid = cell_region[cell]
            clue = clue_by_region[rid]
            b, w, u = region_counts(st, rid)
            need = clue - b
            score = (
                0 if need > 0 else 1,
                u,
                -sum(1 for nb in orth[cell] if st[nb] == UNKNOWN),
                cell[0], cell[1]
            )
            if best_score is None or score < best_score:
                best_score = score
                best = cell
        return best

    def search(st):
        if not apply_local_deductions(st):
            return None
        if not speculative_propagation(st):
            return None
        if is_solved(st):
            return st

        cell = choose_branch_cell(st)
        if cell is None:
            return None

        # Try the more constrained value first.
        options = []
        if candidate_black_possible(st, cell):
            options.append(BLACK)
        if candidate_white_possible(st, cell):
            options.append(WHITE)

        # Prefer black first when region still needs blacks; otherwise white first.
        rid = cell_region[cell]
        b, w, u = region_counts(st, rid)
        if clue_by_region[rid] - b <= 0:
            options.sort(key=lambda v: 0 if v == WHITE else 1)
        else:
            options.sort(key=lambda v: 0 if v == BLACK else 1)

        for val in options:
            st2 = clone_state(st)
            st2[cell] = val
            res = search(st2)
            if res is not None:
                return res
        return None

    result = search(state)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(m)] for _ in range(n)]
    for r in range(n):
        for c in range(m):
            answer[r][c] = 'B' if result[(r, c)] == BLACK else None
    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

