# General Slant solver with:
# - exact local clue propagation
# - no-loop enforcement via rollback DSU on grid dots
# - human-like deductions (forced by clue bounds, singleton cell effects, corner/near-complete clue reasoning)
# - MRV branching only when propagation stalls

from copy import deepcopy

SLASH = 1      # '/'
BACKSLASH = 2  # '\'


class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def snapshot(self):
        return len(self.history)

    def rollback(self, snap):
        while len(self.history) > snap:
            item = self.history.pop()
            if item is None:
                continue
            rb, ra, size_ra, comps = item
            self.parent[rb] = rb
            self.size[ra] = size_ra
            self.components = comps

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            self.history.append(None)
            return False, True  # no structural change, cycle edge if used in forest context
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.history.append((rb, ra, self.size[ra], self.components))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True, False


class Solver:
    def __init__(self, observation):
        self.data = observation['data']
        self.n = len(self.data) - 1
        self.cells = [[0] * self.n for _ in range(self.n)]  # 0 unknown, 1 '/', 2 '\'
        self.dot_req = self.data

        # For each dot: incident cells and which orientation contributes.
        self.dot_inc = [[[] for _ in range(self.n + 1)] for _ in range(self.n + 1)]
        for r in range(self.n):
            for c in range(self.n):
                # slash connects (r, c+1) and (r+1, c)
                self.dot_inc[r][c + 1].append((r, c, SLASH))
                self.dot_inc[r + 1][c].append((r, c, SLASH))
                # backslash connects (r, c) and (r+1, c+1)
                self.dot_inc[r][c].append((r, c, BACKSLASH))
                self.dot_inc[r + 1][c + 1].append((r, c, BACKSLASH))

        # Dot accounting.
        self.dot_on = [[0] * (self.n + 1) for _ in range(self.n + 1)]
        self.dot_unknown = [[len(self.dot_inc[r][c]) for c in range(self.n + 1)] for r in range(self.n + 1)]

        # DSU over dots to forbid loops.
        self.dsu = RollbackDSU((self.n + 1) * (self.n + 1))

        # Assignment stack for rollback.
        self.assign_history = []
        self.contradiction = False

        # Queue of dirty dots/cells.
        self.dot_queue = []
        self.dot_in_queue = [[False] * (self.n + 1) for _ in range(self.n + 1)]
        self.cell_queue = []
        self.cell_in_queue = [[False] * self.n for _ in range(self.n)]

        for r in range(self.n + 1):
            for c in range(self.n + 1):
                if self.dot_req[r][c] is not None:
                    self.push_dot(r, c)
        for r in range(self.n):
            for c in range(self.n):
                self.push_cell(r, c)

    def dot_id(self, r, c):
        return r * (self.n + 1) + c

    def endpoints(self, r, c, val):
        if val == SLASH:
            return (r, c + 1), (r + 1, c)
        return (r, c), (r + 1, c + 1)

    def cell_touches(self, r, c):
        return [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]

    def push_dot(self, r, c):
        if not self.dot_in_queue[r][c]:
            self.dot_in_queue[r][c] = True
            self.dot_queue.append((r, c))

    def push_cell(self, r, c):
        if 0 <= r < self.n and 0 <= c < self.n and not self.cell_in_queue[r][c]:
            self.cell_in_queue[r][c] = True
            self.cell_queue.append((r, c))

    def snapshot(self):
        return (len(self.assign_history), self.dsu.snapshot(), self.contradiction)

    def rollback(self, snap):
        assign_len, dsu_snap, old_contra = snap
        while len(self.assign_history) > assign_len:
            r, c, prev, touched = self.assign_history.pop()
            cur = self.cells[r][c]
            if cur != 0:
                for dr, dc in touched:
                    if self.dot_req[dr][dc] is not None:
                        if cur == self.required_orientation_for_dot(r, c, dr, dc):
                            self.dot_on[dr][dc] -= 1
                        self.dot_unknown[dr][dc] += 1
                        self.push_dot(dr, dc)
                self.cells[r][c] = prev
                self.push_cell(r, c)
                for dr, dc in touched:
                    for rr, cc, _ in self.dot_inc[dr][dc]:
                        self.push_cell(rr, cc)
        self.dsu.rollback(dsu_snap)
        self.contradiction = old_contra
        # Keep queues as-is; reprocessing is harmless and simpler.

    def required_orientation_for_dot(self, cell_r, cell_c, dot_r, dot_c):
        # returns orientation of this cell that contributes to this dot
        if (dot_r, dot_c) == (cell_r, cell_c):
            return BACKSLASH
        if (dot_r, dot_c) == (cell_r, cell_c + 1):
            return SLASH
        if (dot_r, dot_c) == (cell_r + 1, cell_c):
            return SLASH
        if (dot_r, dot_c) == (cell_r + 1, cell_c + 1):
            return BACKSLASH
        return None

    def assign(self, r, c, val):
        if self.contradiction:
            return False
        cur = self.cells[r][c]
        if cur == val:
            return True
        if cur != 0 and cur != val:
            self.contradiction = True
            return False

        # Check loop immediately.
        a, b = self.endpoints(r, c, val)
        ai = self.dot_id(*a)
        bi = self.dot_id(*b)
        ra = self.dsu.find(ai)
        rb = self.dsu.find(bi)
        if ra == rb:
            self.contradiction = True
            return False

        touched = self.cell_touches(r, c)
        self.assign_history.append((r, c, cur, touched))
        self.cells[r][c] = val
        self.dsu.union(ai, bi)

        for dr, dc in touched:
            if self.dot_req[dr][dc] is not None:
                req_or = self.required_orientation_for_dot(r, c, dr, dc)
                if val == req_or:
                    self.dot_on[dr][dc] += 1
                self.dot_unknown[dr][dc] -= 1
                if self.dot_on[dr][dc] > self.dot_req[dr][dc]:
                    self.contradiction = True
                if self.dot_on[dr][dc] + self.dot_unknown[dr][dc] < self.dot_req[dr][dc]:
                    self.contradiction = True
                self.push_dot(dr, dc)

        self.push_cell(r, c)
        for dr, dc in touched:
            for rr, cc, _ in self.dot_inc[dr][dc]:
                self.push_cell(rr, cc)
        return not self.contradiction

    def possible_values(self, r, c):
        if self.cells[r][c]:
            return [self.cells[r][c]]

        vals = []
        for val in (SLASH, BACKSLASH):
            a, b = self.endpoints(r, c, val)
            if self.dsu.find(self.dot_id(*a)) == self.dsu.find(self.dot_id(*b)):
                continue

            ok = True
            for dr, dc in self.cell_touches(r, c):
                clue = self.dot_req[dr][dc]
                if clue is None:
                    continue
                req_or = self.required_orientation_for_dot(r, c, dr, dc)
                on2 = self.dot_on[dr][dc] + (1 if val == req_or else 0)
                unk2 = self.dot_unknown[dr][dc] - 1
                if on2 > clue or on2 + unk2 < clue:
                    ok = False
                    break
            if ok:
                vals.append(val)
        return vals

    def propagate_dot(self, r, c):
        clue = self.dot_req[r][c]
        if clue is None or self.contradiction:
            return
        on = self.dot_on[r][c]
        unk = self.dot_unknown[r][c]
        if on > clue or on + unk < clue:
            self.contradiction = True
            return
        if unk == 0:
            return

        need = clue - on
        if need == 0:
            # All unknown incident cells must avoid this dot.
            for rr, cc, orient in self.dot_inc[r][c]:
                if self.cells[rr][cc] == 0:
                    other = BACKSLASH if orient == SLASH else SLASH
                    if not self.assign(rr, cc, other):
                        return
        elif need == unk:
            # All unknown incident cells must hit this dot.
            for rr, cc, orient in self.dot_inc[r][c]:
                if self.cells[rr][cc] == 0:
                    if not self.assign(rr, cc, orient):
                        return

    def propagate_cell(self, r, c):
        if self.contradiction or self.cells[r][c] != 0:
            return
        vals = self.possible_values(r, c)
        if not vals:
            self.contradiction = True
            return
        if len(vals) == 1:
            self.assign(r, c, vals[0])
            return

        # Human-like local pattern:
        # If one orientation would satisfy/exceed certain adjacent clue bounds while the other cannot, force.
        # This is already captured by possible_values, but we add a tiny lookahead:
        forced = []
        for val in vals:
            viable = True
            for dr, dc in self.cell_touches(r, c):
                clue = self.dot_req[dr][dc]
                if clue is None:
                    continue
                req_or = self.required_orientation_for_dot(r, c, dr, dc)
                on2 = self.dot_on[dr][dc] + (1 if val == req_or else 0)
                unk2 = self.dot_unknown[dr][dc] - 1
                if unk2 == 0 and on2 != clue:
                    viable = False
                    break
            if viable:
                forced.append(val)
        if len(forced) == 1:
            self.assign(r, c, forced[0])

    def propagate(self):
        while not self.contradiction:
            progressed = False

            while self.dot_queue and not self.contradiction:
                r, c = self.dot_queue.pop()
                self.dot_in_queue[r][c] = False
                before = len(self.assign_history)
                self.propagate_dot(r, c)
                if len(self.assign_history) != before:
                    progressed = True

            while self.cell_queue and not self.contradiction:
                r, c = self.cell_queue.pop()
                self.cell_in_queue[r][c] = False
                before = len(self.assign_history)
                self.propagate_cell(r, c)
                if len(self.assign_history) != before:
                    progressed = True

            if not progressed:
                break

        return not self.contradiction

    def is_solved(self):
        if self.contradiction:
            return False
        for r in range(self.n):
            for c in range(self.n):
                if self.cells[r][c] == 0:
                    return False
        for r in range(self.n + 1):
            for c in range(self.n + 1):
                clue = self.dot_req[r][c]
                if clue is not None and self.dot_on[r][c] != clue:
                    return False
        return True

    def choose_branch_cell(self):
        best = None
        best_key = None
        for r in range(self.n):
            for c in range(self.n):
                if self.cells[r][c] != 0:
                    continue
                vals = self.possible_values(r, c)
                if not vals:
                    return (r, c, [])
                # score by MRV, then clue pressure around the cell
                pressure = 0
                for dr, dc in self.cell_touches(r, c):
                    clue = self.dot_req[dr][dc]
                    if clue is not None:
                        pressure += 1 + self.dot_unknown[dr][dc]
                key = (len(vals), pressure)
                if best is None or key < best_key:
                    best = (r, c, vals)
                    best_key = key
                    if len(vals) == 1:
                        return best
        return best

    def search(self):
        if not self.propagate():
            return False
        if self.is_solved():
            return True

        choice = self.choose_branch_cell()
        if choice is None:
            return False
        r, c, vals = choice
        if not vals:
            return False

        # Try value that better satisfies nearby unmet clues first.
        scored = []
        for val in vals:
            gain = 0
            for dr, dc in self.cell_touches(r, c):
                clue = self.dot_req[dr][dc]
                if clue is None:
                    continue
                req_or = self.required_orientation_for_dot(r, c, dr, dc)
                if val == req_or and self.dot_on[dr][dc] < clue:
                    gain += 1
            scored.append((-gain, val))
        vals = [v for _, v in sorted(scored)]

        for val in vals:
            snap = self.snapshot()
            if self.assign(r, c, val) and self.search():
                return True
            self.rollback(snap)
        return False

    def format_answer(self):
        out = []
        for r in range(self.n):
            row = []
            for c in range(self.n):
                row.append('/' if self.cells[r][c] == SLASH else '\\')
            out.append(row)
        return out


def solve(observation):
    solver = Solver(observation)
    ok = solver.search()
    if not ok:
        return "No Solution"
    return str(solver.format_answer())


