    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 1], [0, 1, 1, 2, 2], [0, 3, 3, 3, 4], [0, 4, 4, 4, 4], [5, 5, 5, 5, 5]], 'data': [[None, None, None, 2, None], [None, None, None, None, None], [None, 5, None, 1, None], [None, None, None, None, None], [None, 4, None, None, None]]}

# Jigsaw Latin square / irregular Sudoku solver.
# The solver is generalized for NxN grids with row/column/region all requiring 1..N exactly once.
# It emphasizes human-like deduction:
# - naked singles
# - hidden singles in row/column/region
# - locked-set style subset elimination in any house
# - contradiction checks
# Only when deduction stalls does it branch, choosing the most constrained cell.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    if n == 0 or any(len(row) != n for row in region) or any(len(row) != n for row in data):
        return "No Solution"

    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        v = 1
        while mask:
            if mask & 1:
                vals.append(v)
            mask >>= 1
            v += 1
        return vals

    def popcount(x):
        return x.bit_count()

    def single_value(mask):
        return mask.bit_length() if mask and (mask & (mask - 1)) == 0 else None

    # Normalize region ids to compact 0..n-1 if needed.
    ids = sorted({region[r][c] for r in range(n) for c in range(n)})
    rid_map = {rid: i for i, rid in enumerate(ids)}
    reg = [[rid_map[region[r][c]] for c in range(n)] for r in range(n)]
    region_count = len(ids)
    if region_count != n:
        return "No Solution"

    # Build houses.
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regions = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            regions[reg[r][c]].append((r, c))
    if any(len(cells) != n for cells in regions):
        return "No Solution"

    houses = rows + cols + regions

    # Membership map for quick related-cell traversal.
    cell_houses = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            cell_houses[r][c] = (r, n + c, 2 * n + reg[r][c])

    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set()
            for hid in cell_houses[r][c]:
                s.update(houses[hid])
            s.discard((r, c))
            peers[r][c] = tuple(s)

    # Initial candidate masks.
    cand = [[full_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                cand[r][c] = bit(v)

    def clone_state(state):
        return [row[:] for row in state]

    def assign(state, r, c, value_mask):
        # Assign a single value mask to cell and propagate elimination to peers.
        cur = state[r][c]
        if cur == value_mask:
            return True
        if not (cur & value_mask):
            return False
        state[r][c] = value_mask
        for rr, cc in peers[r][c]:
            m = state[rr][cc]
            if m & value_mask:
                nm = m & ~value_mask
                if nm == 0:
                    return False
                state[rr][cc] = nm
        return True

    def basic_propagate(state):
        # Repeatedly apply:
        # 1) contradiction detection
        # 2) naked singles
        # 3) hidden singles in every house
        # 4) subset elimination in every house
        changed = True
        while changed:
            changed = False

            # Contradiction: fixed duplicates in any house; and empty candidates.
            for r in range(n):
                for c in range(n):
                    if state[r][c] == 0:
                        return False

            for house in houses:
                seen = 0
                for r, c in house:
                    m = state[r][c]
                    if m & (m - 1) == 0:
                        if seen & m:
                            return False
                        seen |= m

            # Naked singles assignment propagation.
            singles = []
            for r in range(n):
                for c in range(n):
                    m = state[r][c]
                    if m & (m - 1) == 0:
                        singles.append((r, c, m))
            for r, c, m in singles:
                for rr, cc in peers[r][c]:
                    om = state[rr][cc]
                    if om & m:
                        nm = om & ~m
                        if nm == 0:
                            return False
                        if nm != om:
                            state[rr][cc] = nm
                            changed = True

            # Hidden singles.
            for house in houses:
                pos = [0] * n  # bit i -> candidate cells mask over house positions packed in Python int
                for idx, (r, c) in enumerate(house):
                    m = state[r][c]
                    mm = m
                    while mm:
                        lb = mm & -mm
                        d = lb.bit_length() - 1
                        pos[d] |= (1 << idx)
                        mm ^= lb
                for d in range(n):
                    p = pos[d]
                    if p == 0:
                        return False
                    if p & (p - 1) == 0:
                        idx = p.bit_length() - 1
                        r, c = house[idx]
                        need = 1 << d
                        if state[r][c] != need:
                            if not assign(state, r, c, need):
                                return False
                            changed = True

            # Naked/hidden subset elimination within each house.
            # For compactness and efficiency on small N, enumerate signatures actually present.
            for house in houses:
                sig_count = {}
                sig_cells = {}
                for idx, (r, c) in enumerate(house):
                    m = state[r][c]
                    pc = popcount(m)
                    if 2 <= pc <= n - 1:
                        sig_count[m] = sig_count.get(m, 0) + 1
                        sig_cells.setdefault(m, []).append(idx)

                # Naked subsets: if exactly k cells share same k-sized mask, remove from others.
                for m, cnt in tuple(sig_count.items()):
                    k = popcount(m)
                    if cnt == k:
                        for idx, (r, c) in enumerate(house):
                            if idx not in sig_cells[m]:
                                om = state[r][c]
                                if om & m:
                                    nm = om & ~m
                                    if nm == 0:
                                        return False
                                    if nm != om:
                                        state[r][c] = nm
                                        changed = True

                # Hidden subsets:
                # Build digit->positions mapping, then group equal position patterns.
                pat_to_digits = {}
                for d in range(n):
                    p = 0
                    for idx, (r, c) in enumerate(house):
                        if state[r][c] & (1 << d):
                            p |= 1 << idx
                    if p == 0:
                        return False
                    pat_to_digits.setdefault(p, 0)
                    pat_to_digits[p] |= 1 << d

                for p, dmask in tuple(pat_to_digits.items()):
                    cell_count = popcount(p)
                    digit_count = popcount(dmask)
                    if 2 <= cell_count == digit_count <= n - 1:
                        # Those cells can only contain those digits.
                        idxs = []
                        pp = p
                        while pp:
                            lb = pp & -pp
                            idxs.append(lb.bit_length() - 1)
                            pp ^= lb
                        for idx in idxs:
                            r, c = house[idx]
                            om = state[r][c]
                            nm = om & dmask
                            if nm == 0:
                                return False
                            if nm != om:
                                state[r][c] = nm
                                changed = True

        return True

    def solved(state):
        return all(state[r][c] & (state[r][c] - 1) == 0 for r in range(n) for c in range(n))

    def choose_branch_cell(state):
        # Minimum remaining values; tie-break by strongest peer pressure.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = state[r][c]
                pc = popcount(m)
                if pc > 1:
                    peer_fixed = 0
                    for rr, cc in peers[r][c]:
                        pm = state[rr][cc]
                        if pm & (pm - 1) == 0:
                            peer_fixed += 1
                    key = (pc, -peer_fixed)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def order_values(state, r, c):
        # Least-constraining value: try value eliminating fewest total peer candidates first.
        vals = []
        m = state[r][c]
        mm = m
        while mm:
            lb = mm & -mm
            impact = 0
            for rr, cc in peers[r][c]:
                if state[rr][cc] & lb:
                    impact += 1
            vals.append((impact, lb))
            mm ^= lb
        vals.sort()
        return [lb for _, lb in vals]

    def search(state):
        if not basic_propagate(state):
            return None
        if solved(state):
            return state

        cell = choose_branch_cell(state)
        if cell is None:
            return state
        r, c = cell

        for vm in order_values(state, r, c):
            nxt = clone_state(state)
            if assign(nxt, r, c, vm):
                res = search(nxt)
                if res is not None:
                    return res
        return None

    initial = clone_state(cand)
    result = search(initial)
    if result is None:
        return "No Solution"

    solved_grid = [[single_value(result[r][c]) for c in range(n)] for r in range(n)]
    if any(v is None for row in solved_grid for v in row):
        return "No Solution"
    return str(solved_grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 3], [0, 0, 1, 1, 2, 2, 3], [0, 1, 1, 2, 2, 4, 3], [0, 0, 1, 2, 4, 4, 3], [5, 5, 5, 5, 4, 4, 3], [5, 6, 6, 5, 6, 4, 3], [5, 6, 6, 6, 6, 4, 3]], 'data': [[None, None, None, None, None, None, None], [1, 7, None, 2, None, None, 6], [2, None, None, 7, 6, None, None], [None, None, 5, None, 2, None, None], [None, None, 2, 3, None, None, 4], [5, None, None, 4, None, 3, 7], [None, None, None, None, None, None, None]]}

# Generalized Latin + irregular-region solver with strong propagation.
# It models candidates as bitmasks and applies human-like deduction:
# - naked singles
# - hidden singles in row/column/region
# - locked-set style subset eliminations in each unit
# Search is used only after propagation stalls, branching on the most constrained cell.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    full = (1 << n) - 1

    # Validate region ids and build region cells
    region_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells.setdefault(rid, []).append((r, c))

    # Each region must contain exactly n cells
    if len(region_cells) != n:
        return "No Solution"
    for rid, cells in region_cells.items():
        if len(cells) != n:
            return "No Solution"

    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regs = [region_cells[rid] for rid in sorted(region_cells)]

    cell_reg_index = [[None] * n for _ in range(n)]
    rid_to_index = {rid: i for i, rid in enumerate(sorted(region_cells))}
    for rid, cells in region_cells.items():
        idx = rid_to_index[rid]
        for r, c in cells:
            cell_reg_index[r][c] = idx

    units = []
    units.extend(rows)
    units.extend(cols)
    units.extend(regs)

    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set(rows[r]) | set(cols[c]) | set(regs[cell_reg_index[r][c]])
            s.discard((r, c))
            peers[r][c] = tuple(s)

    # Bit helpers
    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def single_value(mask):
        return mask.bit_length()

    # Initialize candidate masks
    cand = [[full for _ in range(n)] for _ in range(n)]

    # Initial givens validation by unit duplicate check
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            b = bit(v)
            ri = cell_reg_index[r][c]
            if (row_used[r] & b) or (col_used[c] & b) or (reg_used[ri] & b):
                return "No Solution"
            row_used[r] |= b
            col_used[c] |= b
            reg_used[ri] |= b

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                cand[r][c] = bit(v)
            else:
                allowed = full & ~row_used[r] & ~col_used[c] & ~reg_used[cell_reg_index[r][c]]
                if allowed == 0:
                    return "No Solution"
                cand[r][c] = allowed

    # Assignment with propagation queue
    def assign(cand_grid, r, c, mask):
        cur = cand_grid[r][c]
        if cur == mask:
            return True
        if (cur & mask) == 0:
            return False
        cand_grid[r][c] = mask
        stack = [(r, c)]
        while stack:
            rr, cc = stack.pop()
            m = cand_grid[rr][cc]
            if m == 0:
                return False
            if popcount(m) != 1:
                continue
            for pr, pc in peers[rr][cc]:
                pm = cand_grid[pr][pc]
                nm = pm & ~m
                if nm != pm:
                    if nm == 0:
                        return False
                    cand_grid[pr][pc] = nm
                    if popcount(nm) == 1:
                        stack.append((pr, pc))
        return True

    def unit_hidden_singles(cand_grid, unit):
        changed = False
        pos = [None] * n
        cnt = [0] * n
        for r, c in unit:
            m = cand_grid[r][c]
            x = m
            while x:
                lb = x & -x
                d = lb.bit_length() - 1
                cnt[d] += 1
                pos[d] = (r, c)
                x -= lb
        for d in range(n):
            if cnt[d] == 0:
                return None
            if cnt[d] == 1:
                r, c = pos[d]
                m = 1 << d
                if cand_grid[r][c] != m:
                    if not assign(cand_grid, r, c, m):
                        return None
                    changed = True
        return changed

    def unit_naked_subsets(cand_grid, unit):
        # If k cells share a candidate set of size k, remove those digits from other cells.
        changed = False
        groups = {}
        for r, c in unit:
            m = cand_grid[r][c]
            pc = popcount(m)
            if 2 <= pc <= 4:
                groups.setdefault(m, []).append((r, c))
        for m, cells in list(groups.items()):
            k = popcount(m)
            if len(cells) == k:
                for r, c in unit:
                    if (r, c) in cells:
                        continue
                    old = cand_grid[r][c]
                    new = old & ~m
                    if new != old:
                        if new == 0:
                            return None
                        cand_grid[r][c] = new
                        changed = True
        return changed

    def unit_hidden_subsets(cand_grid, unit):
        # For subsets of digits of size 2..4 whose candidate positions are exactly k cells,
        # restrict those cells to the subset.
        changed = False
        digit_cells = []
        for d in range(n):
            b = 1 << d
            cells = []
            for r, c in unit:
                if cand_grid[r][c] & b:
                    cells.append((r, c))
            if not cells:
                return None
            digit_cells.append(cells)

        from itertools import combinations
        digits = [d for d in range(n) if 2 <= len(digit_cells[d]) <= 4]
        for k in (2, 3, 4):
            if len(digits) < k:
                continue
            for ds in combinations(digits, k):
                union_cells = set()
                for d in ds:
                    union_cells.update(digit_cells[d])
                if len(union_cells) != k:
                    continue
                subset_mask = 0
                for d in ds:
                    subset_mask |= 1 << d
                valid = True
                for d in range(n):
                    if d in ds:
                        continue
                    # no extra digit should be confined entirely inside same k cells in a way that breaks hidden subset?
                    # not required for correctness.
                    pass
                for r, c in union_cells:
                    old = cand_grid[r][c]
                    new = old & subset_mask
                    if new == 0:
                        return None
                    if new != old:
                        cand_grid[r][c] = new
                        changed = True
        return changed

    def propagate(cand_grid):
        while True:
            changed = False

            # Detect contradictions in units and queue singles consistency
            for unit in units:
                seen = 0
                for r, c in unit:
                    m = cand_grid[r][c]
                    if m == 0:
                        return False
                    if popcount(m) == 1:
                        if seen & m:
                            return False
                        seen |= m

            # Hidden singles
            for unit in units:
                res = unit_hidden_singles(cand_grid, unit)
                if res is None:
                    return False
                changed |= res

            # Naked subsets and hidden subsets
            for unit in units:
                res = unit_naked_subsets(cand_grid, unit)
                if res is None:
                    return False
                changed |= res

            for unit in units:
                res = unit_hidden_subsets(cand_grid, unit)
                if res is None:
                    return False
                changed |= res

            # Re-propagate any newly formed singles by assigning them to trigger peer elimination
            singles = []
            for r in range(n):
                for c in range(n):
                    m = cand_grid[r][c]
                    if m == 0:
                        return False
                    if popcount(m) == 1:
                        singles.append((r, c, m))
            for r, c, m in singles:
                # assign is idempotent and ensures peer elimination from this single
                before = [row[:] for row in cand_grid]
                if not assign(cand_grid, r, c, m):
                    return False
                if cand_grid != before:
                    changed = True

            if not changed:
                break
        return True

    # Seed givens through assign to propagate immediately
    for r in range(n):
        for c in range(n):
            if popcount(cand[r][c]) == 1:
                if not assign(cand, r, c, cand[r][c]):
                    return "No Solution"

    if not propagate(cand):
        return "No Solution"

    def solved(cand_grid):
        for r in range(n):
            for c in range(n):
                if popcount(cand_grid[r][c]) != 1:
                    return False
        return True

    def choose_branch_cell(cand_grid):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                m = cand_grid[r][c]
                pc = popcount(m)
                if pc <= 1:
                    continue
                # Most constrained cell, tie-break by peer pressure
                score = (pc, -len(peers[r][c]))
                if best is None or score < best_score:
                    best = (r, c)
                    best_score = score
        return best

    def search(cand_grid):
        if solved(cand_grid):
            return cand_grid
        cell = choose_branch_cell(cand_grid)
        if cell is None:
            return None
        r, c = cell
        m = cand_grid[r][c]

        # Value ordering: least frequent in related units first
        vals = []
        x = m
        while x:
            lb = x & -x
            dmask = lb
            freq = 0
            for rr, cc in rows[r]:
                if cand_grid[rr][cc] & dmask:
                    freq += 1
            for rr, cc in cols[c]:
                if cand_grid[rr][cc] & dmask:
                    freq += 1
            for rr, cc in regs[cell_reg_index[r][c]]:
                if cand_grid[rr][cc] & dmask:
                    freq += 1
            vals.append((freq, dmask))
            x -= lb
        vals.sort()

        for _, dmask in vals:
            new_grid = [row[:] for row in cand_grid]
            if assign(new_grid, r, c, dmask) and propagate(new_grid):
                res = search(new_grid)
                if res is not None:
                    return res
        return None

    res = search(cand)
    if res is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            m = res[r][c]
            if popcount(m) != 1:
                return "No Solution"
            row.append(single_value(m))
        out.append(row)
    return str(out)

