# General Latin + irregular regions solver using strong constraint propagation
# and human-like deductions (singles, hidden singles, subset elimination,
# fish-style line/region interactions), with MRV search only as fallback.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    digits = list(range(1, n + 1))
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def bits_to_values(mask):
        vals = []
        d = 1
        while mask:
            if mask & 1:
                vals.append(d)
            mask >>= 1
            d += 1
        return vals

    def bit_count(x):
        return x.bit_count()

    # Build region cell lists and validate region sizes
    reg_ids = sorted({region[r][c] for r in range(n) for c in range(n)})
    reg_map = {rid: [] for rid in reg_ids}
    for r in range(n):
        for c in range(n):
            reg_map[region[r][c]].append((r, c))

    if len(reg_ids) != n:
        return "No Solution"
    for rid in reg_ids:
        if len(reg_map[rid]) != n:
            return "No Solution"

    # Units
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regs = [reg_map[rid] for rid in reg_ids]
    units = rows + cols + regs

    # Peers
    peers = {}
    for r in range(n):
        for c in range(n):
            s = set(rows[r]) | set(cols[c]) | set(reg_map[region[r][c]])
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    # Cell-to-unit indices
    cell_units = {}
    for r in range(n):
        for c in range(n):
            cell_units[(r, c)] = (r, n + c, 2 * n + reg_ids.index(region[r][c]))

    # Initial candidate masks
    masks = [[full for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                masks[r][c] = bit(v)

    def assign(grid, r, c, value_mask):
        # Set cell to exactly value_mask and propagate eliminations to peers.
        old = grid[r][c]
        if old == value_mask:
            return True
        if not (old & value_mask):
            return False
        other = old & ~value_mask
        x = other
        while x:
            lb = x & -x
            if not eliminate(grid, r, c, lb):
                return False
            x ^= lb
        return True

    def eliminate(grid, r, c, rem_mask):
        old = grid[r][c]
        if not (old & rem_mask):
            return True
        new = old & ~rem_mask
        if new == 0:
            return False
        grid[r][c] = new

        # Naked single propagation
        if new != old and (new & (new - 1)) == 0:
            for rr, cc in peers[(r, c)]:
                if not eliminate(grid, rr, cc, new):
                    return False

        # Hidden single checks in all units containing cell
        for ui in cell_units[(r, c)]:
            unit = units[ui]
            # For each digit that could appear in this unit, if only one place remains => assign
            places = {}
            for rr, cc in unit:
                m = grid[rr][cc]
                x = m
                while x:
                    lb = x & -x
                    places[lb] = places.get(lb, 0) + 1
                    x ^= lb
            # Contradiction if any digit absent
            for d in digits:
                bm = bit(d)
                cnt = places.get(bm, 0)
                if cnt == 0:
                    return False
                if cnt == 1:
                    for rr, cc in unit:
                        if grid[rr][cc] & bm:
                            if not assign(grid, rr, cc, bm):
                                return False
                            break

            # Naked subset elimination within the unit
            loc = {}
            for rr, cc in unit:
                m = grid[rr][cc]
                bc = bit_count(m)
                if 2 <= bc <= len(unit):
                    loc.setdefault(m, []).append((rr, cc))
            for subset_mask, cells in list(loc.items()):
                k = bit_count(subset_mask)
                if len(cells) == k and k >= 2:
                    for rr, cc in unit:
                        if (rr, cc) not in cells:
                            if not eliminate(grid, rr, cc, subset_mask):
                                return False

        return True

    def propagate(grid):
        changed = True
        while changed:
            snapshot = tuple(tuple(row) for row in grid)
            # Unit hidden singles and subset rules over all units
            for unit in units:
                digit_places = {bit(d): [] for d in digits}
                for r, c in unit:
                    m = grid[r][c]
                    x = m
                    while x:
                        lb = x & -x
                        digit_places[lb].append((r, c))
                        x ^= lb

                for d in digits:
                    bm = bit(d)
                    places = digit_places[bm]
                    if not places:
                        return False
                    if len(places) == 1:
                        r, c = places[0]
                        if not assign(grid, r, c, bm):
                            return False

                # General hidden subsets
                place_to_digits = {}
                for d in digits:
                    bm = bit(d)
                    key = tuple(digit_places[bm])
                    if 2 <= len(key) <= n:
                        place_to_digits.setdefault(key, 0)
                        place_to_digits[key] |= bm
                for places, dmask in list(place_to_digits.items()):
                    k_cells = len(places)
                    k_digits = bit_count(dmask)
                    if k_cells == k_digits and k_cells >= 2:
                        place_set = set(places)
                        for r, c in place_set:
                            extra = grid[r][c] & ~dmask
                            if extra:
                                if not eliminate(grid, r, c, extra):
                                    return False

            # Line/region interaction (pointing/claiming)
            for ridx, unit in enumerate(regs):
                for d in digits:
                    bm = bit(d)
                    places = [(r, c) for (r, c) in unit if grid[r][c] & bm]
                    if not places:
                        return False
                    rows_used = {r for r, _ in places}
                    cols_used = {c for _, c in places}
                    if len(rows_used) == 1:
                        rr = next(iter(rows_used))
                        for r, c in rows[rr]:
                            if region[r][c] != reg_ids[ridx] and (grid[r][c] & bm):
                                if not eliminate(grid, r, c, bm):
                                    return False
                    if len(cols_used) == 1:
                        cc = next(iter(cols_used))
                        for r, c in cols[cc]:
                            if region[r][c] != reg_ids[ridx] and (grid[r][c] & bm):
                                if not eliminate(grid, r, c, bm):
                                    return False

            for r in range(n):
                for d in digits:
                    bm = bit(d)
                    places = [(r, c) for c in range(n) if grid[r][c] & bm]
                    if not places:
                        return False
                    regs_used = {region[rr][cc] for rr, cc in places}
                    if len(regs_used) == 1:
                        rid = next(iter(regs_used))
                        for rr, cc in reg_map[rid]:
                            if rr != r and (grid[rr][cc] & bm):
                                if not eliminate(grid, rr, cc, bm):
                                    return False

            for c in range(n):
                for d in digits:
                    bm = bit(d)
                    places = [(r, c) for r in range(n) if grid[r][c] & bm]
                    if not places:
                        return False
                    regs_used = {region[rr][cc] for rr, cc in places}
                    if len(regs_used) == 1:
                        rid = next(iter(regs_used))
                        for rr, cc in reg_map[rid]:
                            if cc != c and (grid[rr][cc] & bm):
                                if not eliminate(grid[rr], cc, bm):
                                    return False

            changed = snapshot != tuple(tuple(row) for row in grid)

        return True

    # Fix minor helper issue from above block by wrapping safe eliminate calls
    def clean_propagate(grid):
        changed = True
        while changed:
            snapshot = tuple(tuple(row) for row in grid)

            for unit in units:
                digit_places = {bit(d): [] for d in digits}
                for r, c in unit:
                    m = grid[r][c]
                    x = m
                    while x:
                        lb = x & -x
                        digit_places[lb].append((r, c))
                        x ^= lb

                for d in digits:
                    bm = bit(d)
                    places = digit_places[bm]
                    if not places:
                        return False
                    if len(places) == 1:
                        r, c = places[0]
                        if not assign(grid, r, c, bm):
                            return False

                place_to_digits = {}
                for d in digits:
                    bm = bit(d)
                    key = tuple(digit_places[bm])
                    if 2 <= len(key) <= n:
                        place_to_digits.setdefault(key, 0)
                        place_to_digits[key] |= bm
                for places, dmask in list(place_to_digits.items()):
                    k_cells = len(places)
                    k_digits = bit_count(dmask)
                    if k_cells == k_digits and k_cells >= 2:
                        for r, c in places:
                            extra = grid[r][c] & ~dmask
                            if extra and not eliminate(grid, r, c, extra):
                                return False

            for ridx, unit in enumerate(regs):
                rid = reg_ids[ridx]
                for d in digits:
                    bm = bit(d)
                    places = [(r, c) for (r, c) in unit if grid[r][c] & bm]
                    if not places:
                        return False
                    rs = {r for r, _ in places}
                    cs = {c for _, c in places}
                    if len(rs) == 1:
                        rr = next(iter(rs))
                        for r, c in rows[rr]:
                            if region[r][c] != rid and (grid[r][c] & bm):
                                if not eliminate(grid, r, c, bm):
                                    return False
                    if len(cs) == 1:
                        cc = next(iter(cs))
                        for r, c in cols[cc]:
                            if region[r][c] != rid and (grid[r][c] & bm):
                                if not eliminate(grid, r, c, bm):
                                    return False

            for r in range(n):
                for d in digits:
                    bm = bit(d)
                    places = [(r, c) for c in range(n) if grid[r][c] & bm]
                    if not places:
                        return False
                    regs_used = {region[rr][cc] for rr, cc in places}
                    if len(regs_used) == 1:
                        rid = next(iter(regs_used))
                        for rr, cc in reg_map[rid]:
                            if rr != r and (grid[rr][cc] & bm):
                                if not eliminate(grid, rr, cc, bm):
                                    return False

            for c in range(n):
                for d in digits:
                    bm = bit(d)
                    places = [(r, c) for r in range(n) if grid[r][c] & bm]
                    if not places:
                        return False
                    regs_used = {region[rr][cc] for rr, cc in places}
                    if len(regs_used) == 1:
                        rid = next(iter(regs_used))
                        for rr, cc in reg_map[rid]:
                            if cc != c and (grid[rr][cc] & bm):
                                if not eliminate(grid, rr, cc, bm):
                                    return False

            changed = snapshot != tuple(tuple(row) for row in grid)
        return True

    # Apply givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not assign(masks, r, c, bit(v)):
                    return "No Solution"

    if not clean_propagate(masks):
        return "No Solution"

    def solved(grid):
        return all((grid[r][c] & (grid[r][c] - 1)) == 0 for r in range(n) for c in range(n))

    def score_choice(grid):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = grid[r][c]
                bc = bit_count(m)
                if bc > 1:
                    peer_pressure = sum(1 for rr, cc in peers[(r, c)] if bit_count(grid[rr][cc]) > 1)
                    key = (bc, -peer_pressure)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def copy_grid(grid):
        return [row[:] for row in grid]

    def search(grid):
        if solved(grid):
            return grid

        cell = score_choice(grid)
        if cell is None:
            return None
        r, c = cell

        # Least-constraining-value order
        options = []
        m = grid[r][c]
        for v in bits_to_values(m):
            bm = bit(v)
            impact = 0
            for rr, cc in peers[(r, c)]:
                if grid[rr][cc] & bm:
                    impact += 1
            options.append((impact, bm))
        options.sort()

        for _, bm in options:
            g2 = copy_grid(grid)
            if assign(g2, r, c, bm) and clean_propagate(g2):
                ans = search(g2)
                if ans is not None:
                    return ans
        return None

    result = search(masks)
    if result is None:
        return "No Solution"

    solved_grid = [[bits_to_values(result[r][c])[0] for c in range(n)] for r in range(n)]
    return str(solved_grid)


