# Generalized irregular Latin / jigsaw sudoku solver.
# Uses human-like propagation:
# - basic elimination from row/col/region
# - hidden singles in row/col/region
# - locked candidates between region and row/col
# - naked subsets in row/col/region
# Then falls back to tightly constrained branching.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    digits = list(range(1, n + 1))
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(m):
        vals = []
        x = m
        d = 1
        while x:
            if x & 1:
                vals.append(d)
            x >>= 1
            d += 1
        return vals

    def popcount(x):
        return x.bit_count()

    # Normalize region ids to 0..k-1 preserving shape.
    id_map = {}
    next_id = 0
    reg = [[0] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            if rid not in id_map:
                id_map[rid] = next_id
                next_id += 1
            reg[r][c] = id_map[rid]

    k = next_id
    region_cells = [[] for _ in range(k)]
    for r in range(n):
        for c in range(n):
            region_cells[reg[r][c]].append((r, c))

    # Validate region sizes for Latin 1..N constraints.
    if any(len(cells) != n for cells in region_cells):
        return "No Solution"

    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]

    units = []
    unit_kinds = []
    unit_index = {}
    for r in range(n):
        unit_index[('row', r)] = len(units)
        units.append(row_cells[r])
        unit_kinds.append(('row', r))
    for c in range(n):
        unit_index[('col', c)] = len(units)
        units.append(col_cells[c])
        unit_kinds.append(('col', c))
    for rid in range(k):
        unit_index[('reg', rid)] = len(units)
        units.append(region_cells[rid])
        unit_kinds.append(('reg', rid))

    cell_units = [[None] * n for _ in range(n)]
    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            u = [
                unit_index[('row', r)],
                unit_index[('col', c)],
                unit_index[('reg', reg[r][c])]
            ]
            cell_units[r][c] = u
            p = set()
            for ui in u:
                p.update(units[ui])
            p.discard((r, c))
            peers[r][c] = tuple(p)

    board = [[0] * n for _ in range(n)]
    cand = [[full_mask for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * k

    def assign(board, cand, row_used, col_used, reg_used, r, c, v):
        b = bit(v)
        cur = board[r][c]
        if cur == v:
            return True
        if cur != 0 and cur != v:
            return False
        if (row_used[r] & b) or (col_used[c] & b) or (reg_used[reg[r][c]] & b):
            return False
        if not (cand[r][c] & b):
            return False
        board[r][c] = v
        cand[r][c] = b
        row_used[r] |= b
        col_used[c] |= b
        reg_used[reg[r][c]] |= b

        for rr, cc in peers[r][c]:
            if board[rr][cc] == 0 and (cand[rr][cc] & b):
                nc = cand[rr][cc] & ~b
                if nc == 0:
                    return False
                cand[rr][cc] = nc
        return True

    # Initialize givens.
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            if not assign(board, cand, row_used, col_used, reg_used, r, c, v):
                return "No Solution"

    # Initial candidate restriction from current used masks.
    for r in range(n):
        for c in range(n):
            if board[r][c] == 0:
                allowed = full_mask & ~(row_used[r] | col_used[c] | reg_used[reg[r][c]])
                cand[r][c] &= allowed
                if cand[r][c] == 0:
                    return "No Solution"

    def propagate(board, cand, row_used, col_used, reg_used):
        while True:
            changed = False

            # Basic singles
            progress = True
            while progress:
                progress = False
                for r in range(n):
                    for c in range(n):
                        if board[r][c] == 0:
                            m = cand[r][c]
                            if m == 0:
                                return False
                            if m & (m - 1) == 0:
                                v = (m.bit_length() - 1) + 1
                                if not assign(board, cand, row_used, col_used, reg_used, r, c, v):
                                    return False
                                changed = True
                                progress = True

            # Hidden singles
            for ui, cells in enumerate(units):
                missing_mask = full_mask
                kind, idx = unit_kinds[ui]
                if kind == 'row':
                    missing_mask &= ~row_used[idx]
                elif kind == 'col':
                    missing_mask &= ~col_used[idx]
                else:
                    missing_mask &= ~reg_used[idx]

                mm = missing_mask
                while mm:
                    b = mm & -mm
                    places = []
                    for r, c in cells:
                        if board[r][c] == 0 and (cand[r][c] & b):
                            places.append((r, c))
                            if len(places) > 1:
                                break
                    if len(places) == 0:
                        return False
                    if len(places) == 1:
                        r, c = places[0]
                        v = b.bit_length()
                        if not assign(board, cand, row_used, col_used, reg_used, r, c, v):
                            return False
                        changed = True
                    mm -= b

            if changed:
                continue

            # Locked candidates: region -> row/col and row/col -> region
            for rid, cells in enumerate(region_cells):
                missing = full_mask & ~reg_used[rid]
                mm = missing
                while mm:
                    b = mm & -mm
                    pos = [(r, c) for (r, c) in cells if board[r][c] == 0 and (cand[r][c] & b)]
                    if not pos:
                        return False
                    rows = {r for r, _ in pos}
                    cols = {c for _, c in pos}
                    if len(rows) == 1:
                        rr = next(iter(rows))
                        for r, c in row_cells[rr]:
                            if reg[r][c] != rid and board[r][c] == 0 and (cand[r][c] & b):
                                nc = cand[r][c] & ~b
                                if nc == 0:
                                    return False
                                if nc != cand[r][c]:
                                    cand[r][c] = nc
                                    changed = True
                    if len(cols) == 1:
                        cc = next(iter(cols))
                        for r, c in col_cells[cc]:
                            if reg[r][c] != rid and board[r][c] == 0 and (cand[r][c] & b):
                                nc = cand[r][c] & ~b
                                if nc == 0:
                                    return False
                                if nc != cand[r][c]:
                                    cand[r][c] = nc
                                    changed = True
                    mm -= b

            # row -> region
            for r in range(n):
                missing = full_mask & ~row_used[r]
                mm = missing
                while mm:
                    b = mm & -mm
                    pos = [(r, c) for c in range(n) if board[r][c] == 0 and (cand[r][c] & b)]
                    if not pos:
                        return False
                    regs = {reg[rr][cc] for rr, cc in pos}
                    if len(regs) == 1:
                        rid = next(iter(regs))
                        for rr, cc in region_cells[rid]:
                            if rr != r and board[rr][cc] == 0 and (cand[rr][cc] & b):
                                nc = cand[rr][cc] & ~b
                                if nc == 0:
                                    return False
                                if nc != cand[rr][cc]:
                                    cand[rr][cc] = nc
                                    changed = True
                    mm -= b

            # col -> region
            for c in range(n):
                missing = full_mask & ~col_used[c]
                mm = missing
                while mm:
                    b = mm & -mm
                    pos = [(r, c) for r in range(n) if board[r][c] == 0 and (cand[r][c] & b)]
                    if not pos:
                        return False
                    regs = {reg[rr][cc] for rr, cc in pos}
                    if len(regs) == 1:
                        rid = next(iter(regs))
                        for rr, cc in region_cells[rid]:
                            if cc != c and board[rr][cc] == 0 and (cand[rr][cc] & b):
                                nc = cand[rr][cc] & ~b
                                if nc == 0:
                                    return False
                                if nc != cand[rr][cc]:
                                    cand[rr][cc] = nc
                                    changed = True
                    mm -= b

            if changed:
                continue

            # Naked subsets in each unit
            for cells in units:
                unsolved = [(r, c, cand[r][c]) for (r, c) in cells if board[r][c] == 0]
                mlen = len(unsolved)
                if mlen >= 2:
                    groups = {}
                    for r, c, m in unsolved:
                        pc = popcount(m)
                        if 2 <= pc <= min(4, mlen - 1):
                            groups.setdefault(m, []).append((r, c))
                    for m, plist in groups.items():
                        sz = popcount(m)
                        if len(plist) == sz:
                            for r, c, cm in unsolved:
                                if (r, c) not in plist and (cm & m):
                                    nc = cm & ~m
                                    if nc == 0:
                                        return False
                                    if nc != cm:
                                        cand[r][c] = nc
                                        changed = True

            if changed:
                continue

            # Final consistency checks
            for r in range(n):
                needed = full_mask & ~row_used[r]
                mm = needed
                while mm:
                    b = mm & -mm
                    if not any(board[r][c] == 0 and (cand[r][c] & b) for c in range(n)):
                        return False
                    mm -= b
            for c in range(n):
                needed = full_mask & ~col_used[c]
                mm = needed
                while mm:
                    b = mm & -mm
                    if not any(board[r][c] == 0 and (cand[r][c] & b) for r in range(n)):
                        return False
                    mm -= b
            for rid, cells in enumerate(region_cells):
                needed = full_mask & ~reg_used[rid]
                mm = needed
                while mm:
                    b = mm & -mm
                    if not any(board[r][c] == 0 and (cand[r][c] & b) for r, c in cells):
                        return False
                    mm -= b

            return True

    def solved(board):
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    return False
        return True

    def clone_state(board, cand, row_used, col_used, reg_used):
        return (
            [row[:] for row in board],
            [row[:] for row in cand],
            row_used[:],
            col_used[:],
            reg_used[:],
        )

    def choose_branch_cell(board, cand):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    m = cand[r][c]
                    pc = popcount(m)
                    # Tie-breaker: higher peer pressure (fewer total candidate support around)
                    support = 0
                    for rr, cc in peers[r][c]:
                        if board[rr][cc] == 0:
                            support += popcount(cand[rr][cc])
                    key = (pc, support)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def search(board, cand, row_used, col_used, reg_used):
        if not propagate(board, cand, row_used, col_used, reg_used):
            return None
        if solved(board):
            return board

        r, c = choose_branch_cell(board, cand)
        if r is None:
            return board

        values = mask_to_values(cand[r][c])

        # Least-constraining value order.
        scored = []
        for v in values:
            b = bit(v)
            impact = 0
            for rr, cc in peers[r][c]:
                if board[rr][cc] == 0 and (cand[rr][cc] & b):
                    impact += 1
            scored.append((impact, v))
        scored.sort()

        for _, v in scored:
            nb, nc, nru, ncu, ngu = clone_state(board, cand, row_used, col_used, reg_used)
            if assign(nb, nc, nru, ncu, ngu, r, c, v):
                res = search(nb, nc, nru, ncu, ngu)
                if res is not None:
                    return res
        return None

    result = search(board, cand, row_used, col_used, reg_used)
    return str(result) if result is not None else "No Solution"


