# General irregular Latin/Sudoku solver with strong propagation and lightweight search.
# Returns the solved grid as a Python literal string, or "No Solution".

from collections import deque

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    digits = list(range(1, n + 1))
    all_mask = (1 << n) - 1

    # Validate regions: exactly n regions, each of size n.
    reg_cells = {}
    for r in range(n):
        for c in range(n):
            reg_cells.setdefault(region[r][c], []).append((r, c))
    if len(reg_cells) != n:
        return "No Solution"
    if any(len(cells) != n for cells in reg_cells.values()):
        return "No Solution"

    reg_ids = sorted(reg_cells)
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    cell_region = [[reg_index[region[r][c]] for c in range(n)] for r in range(n)]
    regions = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            regions[cell_region[r][c]].append((r, c))

    # Units and peers
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    units = rows + cols + regions

    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set(rows[r] + cols[c] + regions[cell_region[r][c]])
            s.discard((r, c))
            peers[r][c] = tuple(s)

    # Bit helpers
    bit_to_val = {1 << i: i + 1 for i in range(n)}

    def popcount(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b
            mask ^= b

    # Initialize candidate masks
    cand = [[all_mask for _ in range(n)] for _ in range(n)]
    queue = deque()

    # Eliminate based on givens and validate duplicates
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            bit = 1 << (v - 1)
            rg = cell_region[r][c]
            if (row_used[r] & bit) or (col_used[c] & bit) or (reg_used[rg] & bit):
                return "No Solution"
            row_used[r] |= bit
            col_used[c] |= bit
            reg_used[rg] |= bit
            cand[r][c] = bit

    # Initial pruning from existing placements
    for r in range(n):
        for c in range(n):
            if popcount(cand[r][c]) == 1:
                queue.append((r, c))

    def assign(cand, r, c, bit, queue):
        m = cand[r][c]
        if m == bit:
            return True
        if not (m & bit):
            return False
        cand[r][c] = bit
        queue.append((r, c))
        return True

    def eliminate(cand, r, c, bit, queue):
        m = cand[r][c]
        if not (m & bit):
            return True
        nm = m & ~bit
        if nm == 0:
            return False
        if nm == m:
            return True
        cand[r][c] = nm
        if popcount(nm) == 1:
            queue.append((r, c))
        return True

    def hidden_singles(cand, queue):
        changed = True
        while changed:
            changed = False
            for unit in units:
                # For each digit, collect locations in unit where digit can go.
                pos = [None] * n
                count = [0] * n
                for r, c in unit:
                    m = cand[r][c]
                    for b in iter_bits(m):
                        i = b.bit_length() - 1
                        count[i] += 1
                        pos[i] = (r, c)
                for i in range(n):
                    if count[i] == 0:
                        return False
                    if count[i] == 1:
                        r, c = pos[i]
                        bit = 1 << i
                        if cand[r][c] != bit:
                            if not assign(cand, r, c, bit, queue):
                                return False
                            changed = True
        return True

    def naked_subsets(cand):
        # Human-like rule: if k cells in a unit share exactly k candidates, remove them from others.
        changed_any = False
        for unit in units:
            groups = {}
            unsolved = []
            for r, c in unit:
                m = cand[r][c]
                pc = popcount(m)
                if 2 <= pc <= 4:
                    groups.setdefault(m, []).append((r, c))
                if pc > 1:
                    unsolved.append((r, c))
            for m, cells in groups.items():
                k = popcount(m)
                if len(cells) == k:
                    for r, c in unsolved:
                        if (r, c) in cells:
                            continue
                        nm = cand[r][c] & ~m
                        if nm != cand[r][c]:
                            if nm == 0:
                                return None
                            cand[r][c] = nm
                            changed_any = True
        return changed_any

    def intersection_removal(cand):
        # Box/line style interaction generalized to irregular regions.
        changed_any = False
        # Region -> row/col
        for rg in range(n):
            cells = regions[rg]
            for d in range(n):
                bit = 1 << d
                poss = [(r, c) for (r, c) in cells if cand[r][c] & bit]
                if not poss:
                    return None
                rows_set = {r for r, _ in poss}
                cols_set = {c for _, c in poss}
                if len(rows_set) == 1:
                    rr = next(iter(rows_set))
                    for c in range(n):
                        if cell_region[rr][c] != rg and (cand[rr][c] & bit):
                            nm = cand[rr][c] & ~bit
                            if nm == 0:
                                return None
                            if nm != cand[rr][c]:
                                cand[rr][c] = nm
                                changed_any = True
                if len(cols_set) == 1:
                    cc = next(iter(cols_set))
                    for r in range(n):
                        if cell_region[r][cc] != rg and (cand[r][cc] & bit):
                            nm = cand[r][cc] & ~bit
                            if nm == 0:
                                return None
                            if nm != cand[r][cc]:
                                cand[r][cc] = nm
                                changed_any = True

        # Row/col -> region
        for r in range(n):
            for d in range(n):
                bit = 1 << d
                poss = [(r, c) for c in range(n) if cand[r][c] & bit]
                if not poss:
                    return None
                regs = {cell_region[r][c] for _, c in poss}
                if len(regs) == 1:
                    rg = next(iter(regs))
                    for rr, cc in regions[rg]:
                        if rr != r and (cand[rr][cc] & bit):
                            nm = cand[rr][cc] & ~bit
                            if nm == 0:
                                return None
                            if nm != cand[rr][cc]:
                                cand[rr][cc] = nm
                                changed_any = True
        for c in range(n):
            for d in range(n):
                bit = 1 << d
                poss = [(r, c) for r in range(n) if cand[r][c] & bit]
                if not poss:
                    return None
                regs = {cell_region[r][c] for r, _ in poss}
                if len(regs) == 1:
                    rg = next(iter(regs))
                    for rr, cc in regions[rg]:
                        if cc != c and (cand[rr][cc] & bit):
                            nm = cand[rr][cc] & ~bit
                            if nm == 0:
                                return None
                            if nm != cand[rr][cc]:
                                cand[rr][cc] = nm
                                changed_any = True
        return changed_any

    def propagate(cand):
        queue = deque((r, c) for r in range(n) for c in range(n) if popcount(cand[r][c]) == 1)

        while True:
            while queue:
                r, c = queue.popleft()
                m = cand[r][c]
                if popcount(m) != 1:
                    continue
                for pr, pc in peers[r][c]:
                    if not eliminate(cand, pr, pc, m, queue):
                        return False

            # Unit consistency check + hidden singles
            if not hidden_singles(cand, queue):
                return False
            if queue:
                continue

            progress = False

            ns = naked_subsets(cand)
            if ns is None:
                return False
            if ns:
                progress = True

            ir = intersection_removal(cand)
            if ir is None:
                return False
            if ir:
                progress = True

            if progress:
                for r in range(n):
                    for c in range(n):
                        if popcount(cand[r][c]) == 1:
                            queue.append((r, c))
                continue

            # Final zero-position validation for every digit in every unit
            for unit in units:
                seen = 0
                for r, c in unit:
                    seen |= cand[r][c]
                if seen != all_mask:
                    return False

            return True

    def solved(cand):
        return all(popcount(cand[r][c]) == 1 for r in range(n) for c in range(n))

    def choose_branch_cell(cand):
        # MRV + degree heuristic + least-constraining value ordering support.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = cand[r][c]
                pc = popcount(m)
                if pc <= 1:
                    continue
                degree = sum(1 for pr, pc2 in peers[r][c] if popcount(cand[pr][pc2]) > 1)
                key = (pc, -degree)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def value_order(cand, r, c):
        # Least constraining value: prefer digit that removes fewer options from peers.
        vals = []
        for bit in iter_bits(cand[r][c]):
            impact = 0
            for pr, pc in peers[r][c]:
                if cand[pr][pc] & bit:
                    impact += 1
            vals.append((impact, bit))
        vals.sort()
        return [bit for _, bit in vals]

    def clone_cand(cand):
        return [row[:] for row in cand]

    def search(cand):
        if not propagate(cand):
            return None
        if solved(cand):
            return cand

        r, c = choose_branch_cell(cand)
        if r is None:
            return None

        for bit in value_order(cand, r, c):
            nc = clone_cand(cand)
            q = deque()
            if not assign(nc, r, c, bit, q):
                continue
            result = search(nc)
            if result is not None:
                return result
        return None

    result = search(cand)
    if result is None:
        return "No Solution"

    grid = [[bit_to_val[result[r][c]] for c in range(n)] for r in range(n)]
    return str(grid)

