# Generalized solver for Latin-square-with-irregular-regions puzzles (Jigsaw Sudoku of order N).
# Uses aggressive constraint propagation and human-like deductions before limited search.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    if n == 0 or any(len(row) != n for row in region) or any(len(row) != n for row in data):
