    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def lowbit_index(x):
        return (x & -x).bit_length() - 1

    # Validate and build regions
    reg_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            reg_cells.setdefault(rid, []).append((r, c))

    if len(reg_cells) != n:
        return "No Solution"
    for rid, cells in reg_cells.items():
        if len(cells) != n:
            return "No Solution"

    reg_ids = sorted(reg_cells)
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    cell_reg = [[reg_index[region[r][c]] for c in range(n)] for r in range(n)]
    reg_cells_idx = [[] for _ in range(n)]
    for rid, cells in reg_cells.items():
        reg_cells_idx[reg_index[rid]] = cells

    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regs = reg_cells_idx

    units = []
    unit_kinds = []
    unit_ids = []
    for i in range(n):
        units.append(rows[i]); unit_kinds.append('row'); unit_ids.append(i)
    for i in range(n):
        units.append(cols[i]); unit_kinds.append('col'); unit_ids.append(i)
    for i in range(n):
        units.append(regs[i]); unit_kinds.append('reg'); unit_ids.append(i)

    cell_units = [[[] for _ in range(n)] for _ in range(n)]
    for ui, cells in enumerate(units):
        for r, c in cells:
            cell_units[r][c].append(ui)

    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n
    grid = [[0] * n for _ in range(n)]
    cand = [[full_mask for _ in range(n)] for _ in range(n)]

    def assign_initial(r, c, v):
        if not (1 <= v <= n):
            return False
        m = bit(v)
        rg = cell_reg[r][c]
        if (row_used[r] & m) or (col_used[c] & m) or (reg_used[rg] & m):
            return False
        grid[r][c] = v
        row_used[r] |= m
        col_used[c] |= m
        reg_used[rg] |= m
        cand[r][c] = m
        return True

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not assign_initial(r, c, v):
                    return "No Solution"

    def recompute_candidates():
        for r in range(n):
            for c in range(n):
                if grid[r][c]:
                    cand[r][c] = bit(grid[r][c])
                else:
                    m = full_mask & ~(row_used[r] | col_used[c] | reg_used[cell_reg[r][c]])
                    if m == 0:
                        return False
                    cand[r][c] = m
        return True

    if not recompute_candidates():
        return "No Solution"

