        if grid[r][c] == v:
            return True
        if grid[r][c] != 0:
            return False
        m = bit(v)
        rg = cell_reg[r][c]
        if (row_used[r] & m) or (col_used[c] & m) or (reg_used[rg] & m):
            return False
        if not (cand[r][c] & m):
            return False
        grid[r][c] = v
        row_used[r] |= m
        col_used[c] |= m
        reg_used[rg] |= m
        cand[r][c] = m
        return True

    def eliminate_peers_after_assignments(assignments):
        # Recompute all candidates after a batch; for small N this is fast and robust.
        return recompute_candidates()

    def naked_singles(assignments):
        changed = False
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    m = cand[r][c]
                    if m == 0:
                        return None
                    if m & (m - 1) == 0:
                        v = lowbit_index(m) + 1
                        if not place(r, c, v):
                            return None
                        assignments.append((r, c, v))
                        changed = True
        return changed

    def hidden_singles(assignments):
        changed = False
        for cells in units:
            pos = [0] * n
            cnt = [0] * n
            for r, c in cells:
                if grid[r][c] == 0:
                    m = cand[r][c]
                    while m:
                        lb = m & -m
                        d = lb.bit_length() - 1
                        cnt[d] += 1
                        pos[d] = (r, c)
                        m ^= lb
            for d in range(n):
                if cnt[d] == 1:
                    r, c = pos[d]
                    v = d + 1
                    if grid[r][c] == 0:
                        if not place(r, c, v):
                            return None
                        assignments.append((r, c, v))
                        changed = True
        return changed

    def locked_sets_in_unit(cells):
        # Naked pairs/triples/etc. generalized:
        # if k cells share exactly k candidates among them, remove those from other cells in unit.
        unsolved = [(r, c, cand[r][c]) for r, c in cells if grid[r][c] == 0]
        mlen = len(unsolved)
        if mlen < 2:
            return False
        groups = {}
        for r, c, m in unsolved:
            pc = popcount(m)
            if 2 <= pc <= min(4, mlen):
                groups.setdefault(m, []).append((r, c))
        changed = False
        for m, ps in groups.items():
            k = popcount(m)
            if len(ps) == k:
                protected = set(ps)
                for r, c, cm in unsolved:
                    if (r, c) not in protected and (cm & m):
                        nm = cm & ~m
                        if nm == 0:
                            return None
                        if nm != cm:
                            cand[r][c] = nm
                            changed = True
        return changed

    def hidden_sets_in_unit(cells):
        # Hidden pairs/triples/quads: if a set of k digits appears only in same k cells, strip others there.
        unsolved = [(r, c, cand[r][c]) for r, c in cells if grid[r][c] == 0]
        if len(unsolved) < 2:
            return False
        digit_cells = []
        for d in range(n):
            positions = []
            m = 1 << d
            for r, c, cm in unsolved:
                if cm & m:
                    positions.append((r, c))
            digit_cells.append(positions)

        bucket = {}
        for d in range(n):
            l = len(digit_cells[d])
            if 2 <= l <= 4:
                key = tuple(digit_cells[d])
                bucket.setdefault(key, []).append(d)

        changed = False
        for positions, digits in bucket.items():
            k = len(positions)
            if len(digits) == k and 2 <= k <= 4:
                mask = 0
                for d in digits:
                    mask |= 1 << d
                for r, c in positions:
                    cm = cand[r][c]
                    nm = cm & mask
                    if nm == 0:
                        return None
                    if nm != cm:
                        cand[r][c] = nm
                        changed = True
        return changed

    def fish_like_intersections():
        # Pointing/claiming analogue across row/col with regions:
        # If all candidates of digit in a row lie in one region, remove digit from other cells of that region.
        # If all candidates of digit in a region lie in one row/col, remove from rest of that row/col.
        changed = False

        for r in range(n):
            for d in range(1, n + 1):
                m = bit(d)
                cells = [(r, c) for c in range(n) if grid[r][c] == 0 and (cand[r][c] & m)]
                if len(cells) >= 2:
                    regs_here = {cell_reg[r][c] for _, c in cells}
                    if len(regs_here) == 1:
                        rg = next(iter(regs_here))
                        for rr, cc in regs[rg]:
                            if rr != r and grid[rr][cc] == 0 and (cand[rr][cc] & m):
                                nm = cand[rr][cc] & ~m
                                if nm == 0:
                                    return None
                                cand[rr][cc] = nm
                                changed = True

        for c in range(n):
            for d in range(1, n + 1):
                m = bit(d)
                cells = [(r, c) for r in range(n) if grid[r][c] == 0 and (cand[r][c] & m)]
                if len(cells) >= 2:
                    regs_here = {cell_reg[r][c] for r, _ in cells}
                    if len(regs_here) == 1:
                        rg = next(iter(regs_here))
                        for rr, cc in regs[rg]:
                            if cc != c and grid[rr][cc] == 0 and (cand[rr][cc] & m):
                                nm = cand[rr][cc] & ~m
                                if nm == 0:
                                    return None
                                cand[rr][cc] = nm
                                changed = True

        for rg in range(n):
            cells = regs[rg]
            for d in range(1, n + 1):
                m = bit(d)
                poss = [(r, c) for r, c in cells if grid[r][c] == 0 and (cand[r][c] & m)]
                if len(poss) >= 2:
                    rows_here = {r for r, _ in poss}
                    cols_here = {c for _, c in poss}
                    if len(rows_here) == 1:
                        r = next(iter(rows_here))
                        for cc in range(n):
                            if cell_reg[r][cc] != rg and grid[r][cc] == 0 and (cand[r][cc] & m):
                                nm = cand[r][cc] & ~m
                                if nm == 0:
                                    return None
                                cand[r][cc] = nm
                                changed = True
                    if len(cols_here) == 1:
                        c = next(iter(cols_here))
                        for rr in range(n):
                            if cell_reg[rr][c] != rg and grid[rr][c] == 0 and (cand[rr][c] & m):
                                nm = cand[rr][c] & ~m
                                if nm == 0:
                                    return None
                                cand[rr][c] = nm
                                changed = True
        return changed

    def validate_state():
        for r in range(n):
            seen = 0
            for c in range(n):
                v = grid[r][c]
                if v:
                    m = bit(v)
                    if seen & m:
                        return False
                    seen |= m
                elif cand[r][c] == 0:
                    return False
            needed = full_mask & ~seen
            m = needed
            while m:
                lb = m & -m
                found = False
                for c in range(n):
                    if grid[r][c] == 0 and (cand[r][c] & lb):
                        found = True
                        break
                if not found:
                    return False
                m ^= lb

        for c in range(n):
            seen = 0
            for r in range(n):
                v = grid[r][c]
                if v:
                    m = bit(v)
                    if seen & m:
                        return False
                    seen |= m
            needed = full_mask & ~seen
            m = needed
            while m:
                lb = m & -m
                found = False
                for r in range(n):
                    if grid[r][c] == 0 and (cand[r][c] & lb):
                        found = True
                        break
                if not found:
                    return False
                m ^= lb

        for rg in range(n):
            seen = 0
            for r, c in regs[rg]:
                v = grid[r][c]
                if v:
                    m = bit(v)
                    if seen & m:
                        return False
                    seen |= m
            needed = full_mask & ~seen
            m = needed
            while m:
                lb = m & -m
                found = False
                for r, c in regs[rg]:
                    if grid[r][c] == 0 and (cand[r][c] & lb):
                        found = True
                        break
                if not found:
                    return False
                m ^= lb
        return True

    def propagate():
        if not recompute_candidates():
            return False
        while True:
            progress = False
            assignments = []

            res = naked_singles(assignments)
            if res is None:
                return False
            progress |= res
            if assignments:
                if not eliminate_peers_after_assignments(assignments):
                    return False

            assignments = []
            res = hidden_singles(assignments)
            if res is None:
                return False
            progress |= res
            if assignments:
                if not eliminate_peers_after_assignments(assignments):
                    return False

            local_change = False
            for cells in units:
                res = locked_sets_in_unit(cells)
                if res is None:
                    return False
                local_change |= res
                res = hidden_sets_in_unit(cells)
                if res is None:
                    return False
                local_change |= res

            res = fish_like_intersections()
            if res is None:
                return False
            local_change |= res

            if local_change:
                progress = True
                if not recompute_candidates():
                    return False

            if not validate_state():
                return False

            if not progress:
                break
        return True

    def solved():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    def snapshot():
        return (
            [row[:] for row in grid],
            row_used[:],
            col_used[:],
            reg_used[:],
            [row[:] for row in cand],
        )

    def restore(state):
        g, ru, cu, gu, ca = state
        for r in range(n):
            grid[r] = g[r][:]
            cand[r] = ca[r][:]
        for i in range(n):
            row_used[i] = ru[i]
            col_used[i] = cu[i]
            reg_used[i] = gu[i]

    def select_branch_cell():
        # Minimum remaining values, then highest peer pressure.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    m = cand[r][c]
                    pc = popcount(m)
                    rg = cell_reg[r][c]
                    pressure = (
                        sum(1 for cc in range(n) if grid[r][cc] == 0 and cc != c) +
                        sum(1 for rr in range(n) if grid[rr][c] == 0 and rr != r) +
                        sum(1 for rr, cc in regs[rg] if grid[rr][cc] == 0 and (rr != r or cc != c))
                    )
                    key = (pc, -pressure)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def ordered_values(r, c):
        # Least-constraining value ordering.
        vals = []
        m = cand[r][c]
        rg = cell_reg[r][c]
        while m:
            lb = m & -m
            d = lb.bit_length() - 1
            v = d + 1
            impact = 0
            for cc in range(n):
                if cc != c and grid[r][cc] == 0 and (cand[r][cc] & lb):
                    impact += 1
            for rr in range(n):
                if rr != r and grid[rr][c] == 0 and (cand[rr][c] & lb):
                    impact += 1
            for rr, cc in regs[rg]:
                if (rr != r or cc != c) and grid[rr][cc] == 0 and (cand[rr][cc] & lb):
                    impact += 1
            vals.append((impact, v))
            m ^= lb
        vals.sort()
        return [v for _, v in vals]

    def dfs():
        if not propagate():
            return False
        if solved():
            return True

        r, c = select_branch_cell()
        state = snapshot()
        for v in ordered_values(r, c):
            restore(state)
            if place(r, c, v) and dfs():
                return True
        restore(state)
        return False

    if not dfs():
        return "No Solution"
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 1, 2, 2, 2, 3, 3], [0, 0, 0, 1, 1, 2, 2, 3, 3], [4, 0, 0, 1, 1, 2, 2, 2, 3], [4, 0, 1, 1, 5, 5, 2, 3, 3], [4, 1, 1, 6, 5, 5, 5, 3, 7], [4, 4, 4, 6, 6, 5, 5, 3, 7], [8, 8, 8, 8, 9, 5, 5, 7, 7], [8, 8, 8, 8, 9, 9, 9, 9, 10], [8, 10, 10, 10, 10, 10, 10, 10, 10]], 'data': [[None, None, None, None, 3, None, None, None, None], [8, None, 6, None, None, None, None, 1, 4], [None, None, 5, None, None, None, 8, 4, None], [None, None, 1, None, None, None, 2, None, None], [None, None, None, None, None, None, None, None, None], [None, None, 2, None, None, None, 3, None, None], [None, 7, 4, None, None, None, 1, None, None], [6, 2, None, None, None, None, 4, None, 5], [None, None, None, None, 1, None, None, None, None]]}

# Generalized irregular Latin Sudoku solver with strong propagation.
# Returns the solved grid as a Python 2D-list string, or "No Solution".

ALL_MASK_CACHE = {}

def bit_count(x):
    return x.bit_count()

def lowbit(x):
    return x & -x

def mask_to_values(mask, n):
    out = []
    while mask:
        b = lowbit(mask)
        out.append(b.bit_length())
        mask ^= b
    return out

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    all_mask = ALL_MASK_CACHE.get(n)
    if all_mask is None:
        all_mask = (1 << n) - 1
        ALL_MASK_CACHE[n] = all_mask

    # Normalize region ids and validate region sizes.
    reg_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            reg_cells.setdefault(rid, []).append(r * n + c)
    if any(len(cells) != n for cells in reg_cells.values()) or len(reg_cells) != n:
        return "No Solution"

    reg_ids = sorted(reg_cells)
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    cell_region = [0] * (n * n)
    regions = [[] for _ in range(n)]
    for rid, cells in reg_cells.items():
        idx = reg_index[rid]
        regions[idx] = cells
        for p in cells:
            cell_region[p] = idx

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]

    # Units per cell: row, col, region.
    cell_units = []
    for r in range(n):
        for c in range(n):
            p = r * n + c
            cell_units.append((rows[r], cols[c], regions[cell_region[p]]))

    # Peer lists.
    peers = []
    for p in range(n * n):
        s = set()
        for unit in cell_units[p]:
            s.update(unit)
        s.remove(p)
        peers.append(tuple(s))

    values = [0] * (n * n)
    cand = [all_mask] * (n * n)
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    def assign_initial(p, v):
        bit = 1 << (v - 1)
        r, c = divmod(p, n)
        g = cell_region[p]
        if (row_used[r] | col_used[c] | reg_used[g]) & bit:
            return False
        values[p] = v
        cand[p] = bit
        row_used[r] |= bit
        col_used[c] |= bit
        reg_used[g] |= bit
        return True

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                if not assign_initial(r * n + c, v):
                    return "No Solution"

    def refresh_candidates():
        for p in range(n * n):
            if values[p]:
                cand[p] = 1 << (values[p] - 1)
            else:
                r, c = divmod(p, n)
                g = cell_region[p]
                m = all_mask & ~(row_used[r] | col_used[c] | reg_used[g])
                if m == 0:
                    return False
                cand[p] = m
        return True

    if not refresh_candidates():
        return "No Solution"

    def place(p, bit, trail):
        v = bit.bit_length()
        r, c = divmod(p, n)
        g = cell_region[p]
        if values[p]:
            return cand[p] == bit
        if (row_used[r] | col_used[c] | reg_used[g]) & bit:
            return False
        trail.append((p, values[p], cand[p], row_used[r], col_used[c], reg_used[g]))
        values[p] = v
        cand[p] = bit
        row_used[r] |= bit
        col_used[c] |= bit
        reg_used[g] |= bit
        return True

    def eliminate(p, rem_mask, trail):
        if values[p]:
            return (cand[p] & rem_mask) == 0
        old = cand[p]
        new = old & ~rem_mask
        if new == old:
            return True
        if new == 0:
            return False
        r, c = divmod(p, n)
        g = cell_region[p]
        trail.append((p, values[p], old, row_used[r], col_used[c], reg_used[g]))
        cand[p] = new
        return True

    def undo(trail):
        for p, old_val, old_cand, old_ru, old_cu, old_gu in reversed(trail):
            r, c = divmod(p, n)
            g = cell_region[p]
            values[p] = old_val
            cand[p] = old_cand
            row_used[r] = old_ru
            col_used[c] = old_cu
            reg_used[g] = old_gu

    units = rows + cols + regions

    # Intersections for locked candidates between every row/col and region.
    intersections = []
    for u_idx, unit in enumerate(rows + cols):
        u_set = set(unit)
        for g_idx, reg in enumerate(regions):
            inter = [p for p in reg if p in u_set]
            if 1 <= len(inter) < n:
                other_u = [p for p in unit if p not in inter]
                other_g = [p for p in reg if p not in inter]
                intersections.append((inter, other_u, other_g))

    def propagate(trail):
        changed = True
        while changed:
            changed = False

            # 1) Any assigned value removes itself from peers; any naked single is placed.
            for p in range(n * n):
                if values[p] == 0:
                    m = cand[p]
                    if m == 0:
                        return False
                    if m & (m - 1) == 0:
                        if not place(p, m, trail):
                            return False
                        changed = True

            # 2) Recompute unsolved candidate consistency against used masks.
            for p in range(n * n):
                if values[p] == 0:
                    r, c = divmod(p, n)
                    g = cell_region[p]
                    allowed = all_mask & ~(row_used[r] | col_used[c] | reg_used[g])
                    nm = cand[p] & allowed
                    if nm == 0:
                        return False
                    if nm != cand[p]:
                        if not eliminate(p, cand[p] ^ nm, trail):
                            return False
                        changed = True

            # 3) Hidden singles in each unit.
            for unit in units:
                occ = [0] * n
                lastp = [-1] * n
                for p in unit:
                    m = cand[p]
                    mm = m
                    while mm:
                        b = lowbit(mm)
                        d = b.bit_length() - 1
                        occ[d] += 1
                        lastp[d] = p
                        mm ^= b
                for d in range(n):
                    if occ[d] == 0:
                        return False
                    if occ[d] == 1:
                        p = lastp[d]
                        bit = 1 << d
                        if values[p] == 0:
                            if not place(p, bit, trail):
                                return False
                            changed = True
                        elif cand[p] != bit:
                            return False

            # 4) Naked pairs/triples in units.
            for unit in units:
                buckets = {}
                unsolved = 0
                for p in unit:
                    if values[p] == 0:
                        unsolved += 1
                        bc = bit_count(cand[p])
                        if 2 <= bc <= 3:
                            buckets.setdefault(cand[p], []).append(p)
                for m, ps in buckets.items():
                    k = bit_count(m)
                    if len(ps) == k and unsolved > k:
                        for p in unit:
                            if p not in ps and values[p] == 0 and (cand[p] & m):
                                if not eliminate(p, m, trail):
                                    return False
                                changed = True

            # 5) Locked candidates (pointing/claiming) using row/col-region intersections.
            for inter, other_u, other_g in intersections:
                union_mask = 0
                for p in inter:
                    if values[p] == 0:
                        union_mask |= cand[p]
                    else:
                        union_mask |= cand[p]
                if union_mask == 0:
                    continue

                # If a digit in region appears only in the intersection, remove from rest of row/col.
                m = union_mask
                while m:
                    b = lowbit(m)
                    m ^= b
                    in_inter = False
                    in_other_g = False
                    for p in inter:
                        if cand[p] & b:
                            in_inter = True
                            break
                    if not in_inter:
                        continue
                    for p in other_g:
                        if cand[p] & b:
                            in_other_g = True
                            break
                    if not in_other_g:
                        for p in other_u:
                            if values[p] == 0 and (cand[p] & b):
                                if not eliminate(p, b, trail):
                                    return False
                                changed = True

                # If a digit in row/col appears only in the intersection, remove from rest of region.
                m = union_mask
                while m:
                    b = lowbit(m)
                    m ^= b
                    in_inter = False
                    in_other_u = False
                    for p in inter:
                        if cand[p] & b:
                            in_inter = True
                            break
                    if not in_inter:
                        continue
                    for p in other_u:
                        if cand[p] & b:
                            in_other_u = True
                            break
                    if not in_other_u:
                        for p in other_g:
                            if values[p] == 0 and (cand[p] & b):
                                if not eliminate(p, b, trail):
                                    return False
                                changed = True

            # 6) Fish-lite subset check for unit-digit exact cover by small cell set.
            # For each unit and digit, if candidate cells all share same k digits and count==k, remove those digits elsewhere.
            for unit in units:
                digit_cells = {}
                for d in range(n):
                    bit = 1 << d
                    ps = [p for p in unit if cand[p] & bit]
                    if 2 <= len(ps) <= 3:
                        digit_cells.setdefault(tuple(ps), 0)
                        digit_cells[tuple(ps)] |= bit
                for ps_t, m in digit_cells.items():
                    k = len(ps_t)
                    if bit_count(m) == k:
                        ps_set = set(ps_t)
                        for p in unit:
                            if p not in ps_set and values[p] == 0 and (cand[p] & m):
                                if not eliminate(p, m, trail):
                                    return False
                                changed = True

        return True

    def solved():
        return all(values)

    def choose_branch_cell():
        best_p = -1
        best_count = n + 1
        best_score = -1
        for p in range(n * n):
            if values[p] == 0:
                cnt = bit_count(cand[p])
                if cnt < best_count:
                    # Higher peer pressure score preferred.
                    score = 0
                    for q in peers[p]:
                        if values[q] == 0:
                            score += 10 - bit_count(cand[q])
                    best_p = p
                    best_count = cnt
                    best_score = score
                elif cnt == best_count:
                    score = 0
                    for q in peers[p]:
                        if values[q] == 0:
                            score += 10 - bit_count(cand[q])
                    if score > best_score:
                        best_p = p
                        best_score = score
        return best_p

    def order_bits_for_cell(p):
        # Least constraining value ordering based on peer eliminations.
        opts = []
        m = cand[p]
        while m:
            b = lowbit(m)
            m ^= b
            impact = 0
            for q in peers[p]:
                if values[q] == 0 and (cand[q] & b):
                    impact += 1
            opts.append((impact, b))
        opts.sort()
        return [b for _, b in opts]

    def dfs():
        trail = []
        if not propagate(trail):
            undo(trail)
            return False
        if solved():
            return True

        p = choose_branch_cell()
        bits = order_bits_for_cell(p)
        snapshot_len = len(trail)
        undo(trail)

        for b in bits:
            local = []
            if place(p, b, local) and dfs():
                return True
            undo(local)
        return False

    if not dfs():
        return "No Solution"

    ans = []
    for r in range(n):
        ans.append(values[r * n:(r + 1) * n])
    return str(ans)

