# Generalized irregular Latin Sudoku solver with strong human-like propagation:
# - naked singles
# - hidden singles in row/column/region
# - locked candidates (region-row / region-column interactions)
# - naked pairs/triples in every unit
# - hidden pairs in every unit
# - contradiction-driven propagation
# Search is only used after exhausting deductions, with MRV + candidate impact ordering.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    digits = list(range(1, n + 1))
    full_mask = (1 << n) - 1

    def bit(d):
        return 1 << (d - 1)

    def bits_to_list(mask):
        out = []
        d = 1
        while mask:
            if mask & 1:
                out.append(d)
            mask >>= 1
            d += 1
        return out

    def popcount(x):
        return x.bit_count()

    # Build regions and validate
    region_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells.setdefault(rid, []).append((r, c))
    if len(region_cells) != n:
        return "No Solution"
    for rid, cells in region_cells.items():
        if len(cells) != n:
            return "No Solution"

    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regs = [None] * n
    rid_to_idx = {}
    for idx, rid in enumerate(sorted(region_cells)):
        rid_to_idx[rid] = idx
        regs[idx] = region_cells[rid]

    cell_region = [[rid_to_idx[region[r][c]] for c in range(n)] for r in range(n)]

    units = []
    units.extend(rows)
    units.extend(cols)
    units.extend(regs)

    # Peers
    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            pr = set(rows[r])
            pr.update(cols[c])
            pr.update(regs[cell_region[r][c]])
            pr.discard((r, c))
            peers[r][c] = tuple(pr)

    # Candidate grid
    cand = [[full_mask for _ in range(n)] for _ in range(n)]

    # Occupancy masks
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    # Initialize givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            b = bit(v)
            g = cell_region[r][c]
            if (row_used[r] & b) or (col_used[c] & b) or (reg_used[g] & b):
                return "No Solution"
            row_used[r] |= b
            col_used[c] |= b
            reg_used[g] |= b
            cand[r][c] = b

    # Initial free candidates for empty cells
    for r in range(n):
        for c in range(n):
            if data[r][c] is None:
                mask = full_mask & ~(row_used[r] | col_used[c] | reg_used[cell_region[r][c]])
                if mask == 0:
                    return "No Solution"
                cand[r][c] = mask

    solved_count = sum(1 for r in range(n) for c in range(n) if popcount(cand[r][c]) == 1)

    def assign(r, c, value_mask, queue):
        nonlocal solved_count
        cur = cand[r][c]
        if cur == value_mask:
            return True
        if not (cur & value_mask):
            return False
        if popcount(value_mask) != 1:
            return False

        # Remove all other candidates first
        other = cur & ~value_mask
        m = other
        while m:
            low = m & -m
            if not eliminate(r, c, low, queue):
                return False
            m -= low
        return True

    def eliminate(r, c, rem_mask, queue):
        nonlocal solved_count
        cur = cand[r][c]
        if not (cur & rem_mask):
            return True
        new = cur & ~rem_mask
        if new == 0:
            return False
        if new == cur:
            return True

        was_single = (cur & (cur - 1)) == 0
        now_single = (new & (new - 1)) == 0
        cand[r][c] = new

        if was_single and not now_single:
            return False

        if now_single and not was_single:
            solved_count += 1
            vmask = new
            rr = r
            cc = c
            rg = cell_region[r][c]
            if row_used[rr] & vmask or col_used[cc] & vmask or reg_used[rg] & vmask:
                return False
            row_used[rr] |= vmask
            col_used[cc] |= vmask
            reg_used[rg] |= vmask
            queue.append((r, c))
        elif not now_single:
            queue.append((r, c))
        return True

    # Seed queue with all singles
    queue = []
    for r in range(n):
        for c in range(n):
            if popcount(cand[r][c]) == 1:
                queue.append((r, c))

    processed_single = set()
    while queue:
        r, c = queue.pop()
        if popcount(cand[r][c]) != 1:
            continue
        if (r, c) in processed_single:
            continue
        processed_single.add((r, c))
        vmask = cand[r][c]
        for rr, cc in peers[r][c]:
            if not eliminate(rr, cc, vmask, queue):
                return "No Solution"

    def unit_hidden_singles(unit, queue):
        changed = False
        pos = [None] * n
        count = [0] * n
        for r, c in unit:
            mask = cand[r][c]
            m = mask
            while m:
                low = m & -m
                d = low.bit_length() - 1
                count[d] += 1
                pos[d] = (r, c)
                m -= low
        for d in range(n):
            if count[d] == 0:
                return None
            if count[d] == 1:
                r, c = pos[d]
                if cand[r][c] != (1 << d):
                    if not assign(r, c, 1 << d, queue):
                        return None
                    changed = True
        return changed

    def locked_candidates_regions(queue):
        changed = False
        for g in range(n):
            cells = regs[g]
            digit_places = [[] for _ in range(n)]
            for r, c in cells:
                mask = cand[r][c]
                m = mask
                while m:
                    low = m & -m
                    d = low.bit_length() - 1
                    digit_places[d].append((r, c))
                    m -= low
            for d in range(n):
                places = digit_places[d]
                if not places:
                    return None
                if len(places) <= 1:
                    continue
                rows_set = {r for r, _ in places}
                cols_set = {c for _, c in places}
                b = 1 << d
                if len(rows_set) == 1:
                    r = next(iter(rows_set))
                    for rr, cc in rows[r]:
                        if cell_region[rr][cc] != g and (cand[rr][cc] & b):
                            if not eliminate(rr, cc, b, queue):
                                return None
                            changed = True
                if len(cols_set) == 1:
                    c = next(iter(cols_set))
                    for rr, cc in cols[c]:
                        if cell_region[rr][cc] != g and (cand[rr][cc] & b):
                            if not eliminate(rr, cc, b, queue):
                                return None
                            changed = True
        return changed

    def naked_subsets(unit, queue, max_size=3):
        changed = False
        buckets = {}
        for r, c in unit:
            m = cand[r][c]
            pc = popcount(m)
            if 2 <= pc <= max_size:
                buckets.setdefault(m, []).append((r, c))
        for mask, cells in list(buckets.items()):
            k = popcount(mask)
            if len(cells) == k and k >= 2:
                for r, c in unit:
                    if (r, c) not in cells:
                        if cand[r][c] & mask:
                            if not eliminate(r, c, mask, queue):
                                return None
                            changed = True
        return changed

    def hidden_pairs(unit, queue):
        changed = False
        digit_cells = {}
        for d in range(1, n + 1):
            b = bit(d)
            cells = []
            for r, c in unit:
                if cand[r][c] & b:
                    cells.append((r, c))
            if len(cells) == 0:
                return None
            if 2 <= len(cells) <= 2:
                digit_cells[d] = tuple(cells)
        inv = {}
        for d, cells in digit_cells.items():
            inv.setdefault(cells, []).append(d)
        for cells, ds in inv.items():
            if len(cells) == 2 and len(ds) == 2:
                mask = bit(ds[0]) | bit(ds[1])
                for r, c in cells:
                    extra = cand[r][c] & ~mask
                    if extra:
                        if not eliminate(r, c, extra, queue):
                            return None
                        changed = True
        return changed

    def propagate():
        local_queue = []
        for r in range(n):
            for c in range(n):
                if popcount(cand[r][c]) == 1:
                    local_queue.append((r, c))

        processed = set()
        while True:
            progress = False

            while local_queue:
                r, c = local_queue.pop()
                if popcount(cand[r][c]) != 1:
                    continue
                if (r, c) in processed:
                    continue
                processed.add((r, c))
                vmask = cand[r][c]
                for rr, cc in peers[r][c]:
                    if not eliminate(rr, cc, vmask, local_queue):
                        return False
                progress = True

            for unit in units:
                res = unit_hidden_singles(unit, local_queue)
                if res is None:
                    return False
                progress |= res

            res = locked_candidates_regions(local_queue)
            if res is None:
                return False
            progress |= res

            for unit in units:
                res = naked_subsets(unit, local_queue, 3)
                if res is None:
                    return False
                progress |= res

            for unit in units:
                res = hidden_pairs(unit, local_queue)
                if res is None:
                    return False
                progress |= res

            # Validity scan
            for r in range(n):
                seen = 0
                unsolved = False
                for c in range(n):
                    m = cand[r][c]
                    if m == 0:
                        return False
                    if popcount(m) == 1:
                        if seen & m:
                            return False
                        seen |= m
                    else:
                        unsolved = True
                if unsolved:
                    union = 0
                    for c in range(n):
                        union |= cand[r][c]
                    if union != full_mask:
                        return False

            for c in range(n):
                seen = 0
                unsolved = False
                for r in range(n):
                    m = cand[r][c]
                    if m == 0:
                        return False
                    if popcount(m) == 1:
                        if seen & m:
                            return False
                        seen |= m
                    else:
                        unsolved = True
                if unsolved:
                    union = 0
                    for r in range(n):
                        union |= cand[r][c]
                    if union != full_mask:
                        return False

            for g in range(n):
                seen = 0
                unsolved = False
                for r, c in regs[g]:
                    m = cand[r][c]
                    if m == 0:
                        return False
                    if popcount(m) == 1:
                        if seen & m:
                            return False
                        seen |= m
                    else:
                        unsolved = True
                if unsolved:
                    union = 0
                    for r, c in regs[g]:
                        union |= cand[r][c]
                    if union != full_mask:
                        return False

            if not progress:
                break
        return True

    if not propagate():
        return "No Solution"

    def is_solved():
        for r in range(n):
            for c in range(n):
                if popcount(cand[r][c]) != 1:
                    return False
        return True

    def snapshot():
        return [row[:] for row in cand], solved_count, row_used[:], col_used[:], reg_used[:]

    def restore(state):
        nonlocal cand, solved_count, row_used, col_used, reg_used
        cand, solved_count, row_used, col_used, reg_used = state

    def select_cell():
        best = None
        best_len = n + 1
        best_score = -1
        for r in range(n):
            for c in range(n):
                m = cand[r][c]
                pc = popcount(m)
                if pc > 1:
                    score = 0
                    for rr, cc in peers[r][c]:
                        score += popcount(cand[rr][cc])
                    if pc < best_len or (pc == best_len and score > best_score):
                        best_len = pc
                        best_score = score
                        best = (r, c)
        return best

    def ordered_values(r, c):
        vals = bits_to_list(cand[r][c])
        impacts = []
        for v in vals:
            b = bit(v)
            impact = 0
            for rr, cc in peers[r][c]:
                if cand[rr][cc] & b:
                    impact += 1
            impacts.append((impact, v))
        impacts.sort(reverse=True)
        return [v for _, v in impacts]

    def dfs():
        if is_solved():
            return True
        cell = select_cell()
        if cell is None:
            return False
        r, c = cell
        for v in ordered_values(r, c):
            state = snapshot()
            q = []
            if assign(r, c, bit(v), q):
                processed = set()
                ok = True
                while q:
                    rr, cc = q.pop()
                    if popcount(cand[rr][cc]) != 1:
                        continue
                    if (rr, cc) in processed:
                        continue
                    processed.add((rr, cc))
                    vmask = cand[rr][cc]
                    for rrr, ccc in peers[rr][cc]:
                        if not eliminate(rrr, ccc, vmask, q):
                            ok = False
                            break
                    if not ok:
                        break
                if ok and propagate() and dfs():
                    return True
            restore(state)
        return False

    if not dfs():
        return "No Solution"

    solved = [[bits_to_list(cand[r][c])[0] for c in range(n)] for r in range(n)]
    return str(solved)

