    region_ids = sorted({region[r][c] for r in range(n) for c in range(n)})
    if len(region_ids) != n:
        return "No Solution"
    id_to_idx = {rid: i for i, rid in enumerate(region_ids)}

    region_cells = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            idx = id_to_idx[region[r][c]]
            region_cells[idx].append((r, c))
    if any(len(cells) != n for cells in region_cells):
        return "No Solution"

    cell_region = [[id_to_idx[region[r][c]] for c in range(n)] for r in range(n)]
    ALLVALS = tuple(range(1, n + 1))

    # Units
    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]

    # Peers
    peers = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set(row_cells[r]) | set(col_cells[c]) | set(region_cells[cell_region[r][c]])
            s.discard((r, c))
            peers[r][c] = tuple(s)

    # Masks
    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(m):
        vals = []
        while m:
            lsb = m & -m
            vals.append(lsb.bit_length())
            m ^= lsb
        return vals

    def popcount(x):
        return x.bit_count()

    # State
    cand = [[full for _ in range(n)] for _ in range(n)]
    grid = [[None for _ in range(n)] for _ in range(n)]

    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    # Initialize givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"

    # Initial candidate restrictions from givens and unit occupancy
    for r in range(n):
        seen = 0
        for c in range(n):
            v = data[r][c]
            if v is not None:
                b = bit(v)
                if seen & b:
