                    if len(cells_same) == k:
                        for r, c in unit_cells:
                            if (r, c) not in cells_same and state_grid[r][c] is None:
                                before = state_cand[r][c]
                                if before & m:
                                    if not eliminate_mask(state_cand, state_grid, r, c, m, q):
                                        return False
                                    if state_cand[r][c] != before:
                                        progress = True
                                        if popcount(state_cand[r][c]) == 1:
                                            vv = state_cand[r][c].bit_length()
                                            if not assign(state_cand, state_grid, state_row_used, state_col_used, state_reg_used, r, c, vv, q):
                                                return False
                return True

            for unit in row_cells:
                if not naked_subsets(unit):
                    return False
            for unit in col_cells:
                if not naked_subsets(unit):
                    return False
            for unit in region_cells:
                if not naked_subsets(unit):
                    return False

            # Hidden subsets (pairs/triples) in each unit
            def hidden_subsets(unit_cells):
                nonlocal progress
                missing_vals = []
                present = 0
                for r, c in unit_cells:
                    if state_grid[r][c] is not None:
                        present |= bit(state_grid[r][c])
                missing = full & ~present
                vals = mask_to_values(missing)
                positions = {v: [] for v in vals}
                for v in vals:
                    b = bit(v)
                    for r, c in unit_cells:
                        if state_grid[r][c] is None and (state_cand[r][c] & b):
                            positions[v].append((r, c))
                    if not positions[v]:
                        return False
                # small unit sizes; enumerate pairs/triples only
                L = vals
                ln = len(L)
                for size in (2, 3):
                    if ln < size:
                        continue
                    def combs(arr, k, start=0, cur=None):
                        if cur is None:
                            cur = []
                        if len(cur) == k:
                            yield tuple(cur)
                            return
                        for i in range(start, len(arr)):
                            cur.append(arr[i])
                            yield from combs(arr, k, i + 1, cur)
                            cur.pop()
                    for combo in combs(L, size):
                        cellset = set()
                        for v in combo:
                            cellset.update(positions[v])
                        if len(cellset) == size:
                            keep = 0
                            for v in combo:
                                keep |= bit(v)
                            for r, c in cellset:
                                before = state_cand[r][c]
                                nm = before & keep
                                if nm == 0:
                                    return False
                                if nm != before:
                                    if state_grid[r][c] is not None and nm != before:
                                        return False
                                    state_cand[r][c] = nm
                                    progress = True
                                    q.append(("reduced", r, c))
                                    if popcount(nm) == 1:
                                        vv = nm.bit_length()
                                        if not assign(state_cand, state_grid, state_row_used, state_col_used, state_reg_used, r, c, vv, q):
                                            return False
                return True

            for unit in row_cells:
                if not hidden_subsets(unit):
                    return False
            for unit in col_cells:
                if not hidden_subsets(unit):
                    return False
            for unit in region_cells:
                if not hidden_subsets(unit):
                    return False

            # Box-line style interactions generalized between region and row/column:
            # if all candidates of value v inside a region lie on one row/col, eliminate v from the rest of that row/col.
            for rg in range(n):
                missing = full & ~state_reg_used[rg]
                for v in mask_to_values(missing):
                    b = bit(v)
                    places = [(r, c) for (r, c) in region_cells[rg] if state_grid[r][c] is None and (state_cand[r][c] & b)]
                    if not places:
                        return False
                    rows = {r for r, _ in places}
                    cols = {c for _, c in places}
                    if len(rows) == 1:
                        rr = next(iter(rows))
                        for cc in range(n):
                            if cell_region[rr][cc] != rg and state_grid[rr][cc] is None and (state_cand[rr][cc] & b):
                                if not eliminate_mask(state_cand, state_grid, rr, cc, b, q):
                                    return False
                                progress = True
                                if popcount(state_cand[rr][cc]) == 1:
                                    vv = state_cand[rr][cc].bit_length()
                                    if not assign(state_cand, state_grid, state_row_used, state_col_used, state_reg_used, rr, cc, vv, q):
                                        return False
                    if len(cols) == 1:
                        cc = next(iter(cols))
                        for rr in range(n):
                            if cell_region[rr][cc] != rg and state_grid[rr][cc] is None and (state_cand[rr][cc] & b):
                                if not eliminate_mask(state_cand, state_grid, rr, cc, b, q):
                                    return False
                                progress = True
                                if popcount(state_cand[rr][cc]) == 1:
                                    vv = state_cand[rr][cc].bit_length()
                                    if not assign(state_cand, state_grid, state_row_used, state_col_used, state_reg_used, rr, cc, vv, q):
                                        return False

            # Reverse interaction: in a row/column if all candidates for a value lie within one region, eliminate elsewhere in that region.
            for r in range(n):
                missing = full & ~state_row_used[r]
                for v in mask_to_values(missing):
                    b = bit(v)
                    places = [(r, c) for c in range(n) if state_grid[r][c] is None and (state_cand[r][c] & b)]
                    if not places:
                        return False
                    regs = {cell_region[rr][cc] for rr, cc in places}
                    if len(regs) == 1:
                        rg = next(iter(regs))
                        for rr, cc in region_cells[rg]:
                            if rr != r and state_grid[rr][cc] is None and (state_cand[rr][cc] & b):
                                if not eliminate_mask(state_cand, state_grid, rr, cc, b, q):
                                    return False
                                progress = True
                                if popcount(state_cand[rr][cc]) == 1:
                                    vv = state_cand[rr][cc].bit_length()
                                    if not assign(state_cand, state_grid, state_row_used, state_col_used, state_reg_used, rr, cc, vv, q):
                                        return False
            for c in range(n):
                missing = full & ~state_col_used[c]
                for v in mask_to_values(missing):
                    b = bit(v)
                    places = [(r, c) for r in range(n) if state_grid[r][c] is None and (state_cand[r][c] & b)]
                    if not places:
                        return False
                    regs = {cell_region[rr][cc] for rr, cc in places}
                    if len(regs) == 1:
                        rg = next(iter(regs))
                        for rr, cc in region_cells[rg]:
                            if cc != c and state_grid[rr][cc] is None and (state_cand[rr][cc] & b):
                                if not eliminate_mask(state_cand, state_grid, rr, cc, b, q):
                                    return False
                                progress = True
                                if popcount(state_cand[rr][cc]) == 1:
                                    vv = state_cand[rr][cc].bit_length()
                                    if not assign(state_cand, state_grid, state_row_used, state_col_used, state_reg_used, rr, cc, vv, q):
                                        return False

            if q:
                continue
            if not progress:
                break

        # Final validation
        for r in range(n):
            for c in range(n):
                if state_grid[r][c] is None and state_cand[r][c] == 0:
                    return False
        return True

    def is_solved(state_grid):
        for r in range(n):
            for c in range(n):
                if state_grid[r][c] is None:
                    return False
        return True

    def clone_state(state_cand, state_grid, state_row_used, state_col_used, state_reg_used):
        return (
            [row[:] for row in state_cand],
            [row[:] for row in state_grid],
            state_row_used[:],
            state_col_used[:],
            state_reg_used[:],
        )

    # Apply givens as assignments for uniform propagation.
    init_cand, init_grid, init_row_used, init_col_used, init_reg_used = clone_state(cand, grid, row_used, col_used, reg_used)
    # Reset occupancy and rebuild through assign to maintain coherence.
    init_row_used = [0] * n
    init_col_used = [0] * n
    init_reg_used = [0] * n
    for r in range(n):
        for c in range(n):
            if data[r][c] is None:
                init_grid[r][c] = None
                init_cand[r][c] = full
            else:
                init_grid[r][c] = None
                init_cand[r][c] = full

    q0 = deque()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                if not assign(init_cand, init_grid, init_row_used, init_col_used, init_reg_used, r, c, data[r][c], q0):
                    return "No Solution"

    # Restrict non-given candidates by current occupancy before propagation.
    while q0:
        _, r, c = q0.popleft()
        v = init_grid[r][c]
        b = bit(v)
        for rr, cc in peers[r][c]:
            if init_grid[rr][cc] is None:
                init_cand[rr][cc] &= ~b
                if init_cand[rr][cc] == 0:
                    return "No Solution"

    if not propagate(init_cand, init_grid, init_row_used, init_col_used, init_reg_used):
        return "No Solution"

    # Search with MRV + degree tie-break + least-constraining value order.
    def search(state_cand, state_grid, state_row_used, state_col_used, state_reg_used):
        if is_solved(state_grid):
            return state_grid

        # Choose cell with minimum remaining values; tie-break by most peers unfilled.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if state_grid[r][c] is None:
                    m = state_cand[r][c]
                    pc = popcount(m)
                    if pc == 0:
                        return None
                    degree = sum(1 for rr, cc in peers[r][c] if state_grid[rr][cc] is None)
                    key = (pc, -degree)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        if best is None:
            return state_grid

        r, c = best
        vals = mask_to_values(state_cand[r][c])

        # Least-constraining value ordering.
        scored = []
        for v in vals:
            b = bit(v)
            impact = 0
            for rr, cc in peers[r][c]:
                if state_grid[rr][cc] is None and (state_cand[rr][cc] & b):
                    impact += 1
            scored.append((impact, v))
        scored.sort()

        for _, v in scored:
            nc, ng, nru, ncu, ngu = clone_state(state_cand, state_grid, state_row_used, state_col_used, state_reg_used)
            q = deque()
            if not assign(nc, ng, nru, ncu, ngu, r, c, v, q):
                continue
            # Process immediate peer elimination quickly before full propagation.
            ok = True
            while q and ok:
                _, ar, ac = q.popleft()
                av = ng[ar][ac]
                b = bit(av)
                for rr, cc in peers[ar][ac]:
                    if ng[rr][cc] is None and (nc[rr][cc] & b):
                        nc[rr][cc] &= ~b
                        if nc[rr][cc] == 0:
                            ok = False
                            break
            if not ok:
                continue
            if not propagate(nc, ng, nru, ncu, ngu):
                continue
            res = search(nc, ng, nru, ncu, ngu)
            if res is not None:
                return res
        return None

    solved = search(init_cand, init_grid, init_row_used, init_col_used, init_reg_used)
    if solved is None:
        return "No Solution"
    return str(solved)


