    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 1, 5], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None]], 'horizontal': {'(0,0.5)': '>', '(0,1.5)': '>', '(1,0.5)': '<', '(2,1.5)': '<', '(2,3.5)': '<', '(3,0.5)': '<'}, 'vertical': {'(2.5,3)': 'v', '(3.5,4)': 'v'}}

# Futoshiki solver with strong human-like propagation:
# - row/column Latin constraints
# - inequality arc-consistency
# - hidden singles in rows/columns
# - bound tightening from inequalities
# - search only after propagation stalls, choosing the most constrained cell

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        v = 1
        while mask:
            if mask & 1:
                vals.append(v)
            mask >>= 1
            v += 1
        return vals

    def popcount(x):
        return x.bit_count()

    def min_value(mask):
        return (mask & -mask).bit_length()

    def max_value(mask):
        return mask.bit_length()

    # Build inequality edges as (r1,c1,op,r2,c2) meaning cell1 op cell2
    edges = []
    neighbors = [[[] for _ in range(n)] for _ in range(n)]

    for k, sym in observation.get('horizontal', {}).items():
        row, colh = eval(k)
        c = int(colh - 0.5)
        r = int(row)
        # symbol drawn between left and right cells, interpreted as left sym right
        edges.append((r, c, sym, r, c + 1))

    for k, sym in observation.get('vertical', {}).items():
        rowh, col = eval(k)
        r = int(rowh - 0.5)
        c = int(col)
        # convention used here:
        # 'v' means upper cell < lower cell
        # '^' means upper cell > lower cell
        op = '<' if sym == 'v' else '>'
        edges.append((r, c, op, r + 1, c))

    for idx, (r1, c1, op, r2, c2) in enumerate(edges):
        neighbors[r1][c1].append((idx, True))
        neighbors[r2][c2].append((idx, False))

    masks = [[full_mask for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                m = bit(v)
                if row_used[r] & m or col_used[c] & m:
                    return "No Solution"
                masks[r][c] = m
                row_used[r] |= m
                col_used[c] |= m

    def relate_ok(a, op, b):
        return a < b if op == '<' else a > b

    def revise_pair(m1, op, m2):
        vals1 = mask_to_values(m1)
        vals2 = mask_to_values(m2)
        good1 = 0
        good2 = 0
        for a in vals1:
            ok = False
            for b in vals2:
                if relate_ok(a, op, b):
                    ok = True
                    good2 |= bit(b)
            if ok:
                good1 |= bit(a)
        return good1, good2

    def assign(state_masks, state_row_used, state_col_used, r, c, value_mask):
        old = state_masks[r][c]
        if old == value_mask:
            return True
        if (old & value_mask) == 0:
            return False
        if popcount(value_mask) != 1:
            state_masks[r][c] &= value_mask
            return state_masks[r][c] != 0

        # enforce single value
        vmask = value_mask
        if popcount(old) == 1:
            return old == vmask

        state_masks[r][c] = vmask
        state_row_used[r] |= vmask
        state_col_used[c] |= vmask

        # remove from peers
        for cc in range(n):
            if cc != c and (state_masks[r][cc] & vmask):
                nm = state_masks[r][cc] & ~vmask
                if nm == 0:
                    return False
                state_masks[r][cc] = nm
        for rr in range(n):
            if rr != r and (state_masks[rr][c] & vmask):
                nm = state_masks[rr][c] & ~vmask
                if nm == 0:
                    return False
                state_masks[rr][c] = nm
        return True

    def eliminate_used(state_masks, state_row_used, state_col_used):
        changed = False
        for r in range(n):
            used = 0
            for c in range(n):
                if popcount(state_masks[r][c]) == 1:
                    used |= state_masks[r][c]
            state_row_used[r] = used
        for c in range(n):
            used = 0
            for r in range(n):
                if popcount(state_masks[r][c]) == 1:
                    used |= state_masks[r][c]
            state_col_used[c] = used

        for r in range(n):
            forbidden = state_row_used[r]
            for c in range(n):
                if popcount(state_masks[r][c]) > 1:
                    nm = state_masks[r][c] & ~forbidden
                    if nm == 0:
                        return False, changed
                    if nm != state_masks[r][c]:
                        state_masks[r][c] = nm
                        changed = True
        for c in range(n):
            forbidden = state_col_used[c]
            for r in range(n):
                if popcount(state_masks[r][c]) > 1:
                    nm = state_masks[r][c] & ~forbidden
                    if nm == 0:
                        return False, changed
                    if nm != state_masks[r][c]:
                        state_masks[r][c] = nm
                        changed = True
        return True, changed

    def hidden_singles_units(state_masks):
        changed = False
        # rows
        for r in range(n):
            pos = [0] * (n + 1)
            cnt = [0] * (n + 1)
            for c in range(n):
                m = state_masks[r][c]
                for v in mask_to_values(m):
                    cnt[v] += 1
                    pos[v] = c
            for v in range(1, n + 1):
                if cnt[v] == 0:
                    return False, changed
                if cnt[v] == 1:
                    c = pos[v]
                    vm = bit(v)
                    if state_masks[r][c] != vm:
                        state_masks[r][c] = vm
                        changed = True
        # cols
        for c in range(n):
            pos = [0] * (n + 1)
            cnt = [0] * (n + 1)
            for r in range(n):
                m = state_masks[r][c]
                for v in mask_to_values(m):
                    cnt[v] += 1
                    pos[v] = r
            for v in range(1, n + 1):
                if cnt[v] == 0:
                    return False, changed
                if cnt[v] == 1:
                    r = pos[v]
                    vm = bit(v)
                    if state_masks[r][c] != vm:
                        state_masks[r][c] = vm
                        changed = True
        return True, changed

    def inequality_propagate(state_masks):
        changed = False
        for r1, c1, op, r2, c2 in edges:
            m1 = state_masks[r1][c1]
            m2 = state_masks[r2][c2]
            nm1, nm2 = revise_pair(m1, op, m2)
            if nm1 == 0 or nm2 == 0:
                return False, changed
            if nm1 != m1:
                state_masks[r1][c1] = nm1
                changed = True
            if nm2 != m2:
                state_masks[r2][c2] = nm2
                changed = True
        return True, changed

    def validate_complete(state_masks):
        target = set(range(1, n + 1))
        grid = [[min_value(state_masks[r][c]) for c in range(n)] for r in range(n)]
        for r in range(n):
            if set(grid[r]) != target:
                return False
        for c in range(n):
            if set(grid[r][c] for r in range(n)) != target:
                return False
        for r1, c1, op, r2, c2 in edges:
            if not relate_ok(grid[r1][c1], op, grid[r2][c2]):
                return False
        return True

    def propagate(state_masks, state_row_used, state_col_used):
        while True:
            any_change = False

            ok, changed = eliminate_used(state_masks, state_row_used, state_col_used)
            if not ok:
                return False
            any_change |= changed

            # assign any naked singles explicitly so row/col used gets refreshed on next pass
            for r in range(n):
                for c in range(n):
                    m = state_masks[r][c]
                    if m == 0:
                        return False
                    if popcount(m) == 1:
                        if not assign(state_masks, state_row_used, state_col_used, r, c, m):
                            return False

            ok, changed = inequality_propagate(state_masks)
            if not ok:
                return False
            any_change |= changed

            ok, changed = hidden_singles_units(state_masks)
            if not ok:
                return False
            any_change |= changed

            # quick feasibility checks
            for r in range(n):
                union = 0
                for c in range(n):
                    if state_masks[r][c] == 0:
                        return False
                    union |= state_masks[r][c]
                if union != full_mask:
                    return False
            for c in range(n):
                union = 0
                for r in range(n):
                    if state_masks[r][c] == 0:
                        return False
                    union |= state_masks[r][c]
                if union != full_mask:
                    return False

            if not any_change:
                return True

    def is_solved(state_masks):
        for r in range(n):
            for c in range(n):
                if popcount(state_masks[r][c]) != 1:
                    return False
        return validate_complete(state_masks)

    def choose_cell(state_masks):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                m = state_masks[r][c]
                pc = popcount(m)
                if pc > 1:
                    degree = len(neighbors[r][c])
                    score = (pc, -degree)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
        return best

    def search(state_masks, state_row_used, state_col_used):
        if not propagate(state_masks, state_row_used, state_col_used):
            return None
        if is_solved(state_masks):
            return state_masks

        cell = choose_cell(state_masks)
        if cell is None:
            return None
        r, c = cell

        # Value ordering: try values that satisfy more immediate inequalities first
        vals = mask_to_values(state_masks[r][c])

        def value_score(v):
            score = 0
            for idx, is_left in neighbors[r][c]:
                r1, c1, op, r2, c2 = edges[idx]
                if is_left:
                    other = state_masks[r2][c2]
                    if op == '<':
                        for b in mask_to_values(other):
                            if v < b:
                                score += 1
                    else:
                        for b in mask_to_values(other):
                            if v > b:
                                score += 1
                else:
                    other = state_masks[r1][c1]
                    if op == '<':
                        for a in mask_to_values(other):
                            if a < v:
                                score += 1
                    else:
                        for a in mask_to_values(other):
                            if a > v:
                                score += 1
            return -score, v

        vals.sort(key=value_score)

        for v in vals:
            new_masks = [row[:] for row in state_masks]
            new_row_used = state_row_used[:]
            new_col_used = state_col_used[:]
            if assign(new_masks, new_row_used, new_col_used, r, c, bit(v)):
                res = search(new_masks, new_row_used, new_col_used)
                if res is not None:
                    return res
        return None

    result_masks = search([row[:] for row in masks], row_used[:], col_used[:])
    if result_masks is None:
        return "No Solution"
    result = [[min_value(result_masks[r][c]) for c in range(n)] for r in range(n)]
    return str(result)

