# General Futoshiki solver with strong propagation and limited search.
# Symbols are interpreted as:
# Horizontal at (r, c+0.5):
#   '>' means grid[r][c] > grid[r][c+1]
#   '<' means grid[r][c] < grid[r][c+1]
# Vertical at (r+0.5, c):
#   'v' means grid[r][c] < grid[r+1][c]
#   '^' means grid[r][c] > grid[r+1][c]

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def mask_to_list(mask):
        out = []
        while mask:
            b = mask & -mask
            out.append(b.bit_length())
            mask ^= b
        return out

    # Parse inequalities as directed "less-than" edges: a < b
    lt_edges = []
    gt_edges = []

    for k, sym in observation['horizontal'].items():
        r, cp = k.strip('()').split(',')
        r = int(float(r))
        cp = float(cp)
        c = int(cp - 0.5)
        a = r * n + c
        b = r * n + (c + 1)
        if sym == '<':
            lt_edges.append((a, b))
        else:
            lt_edges.append((b, a))

    for k, sym in observation['vertical'].items():
        rp, c = k.strip('()').split(',')
        rp = float(rp)
        c = int(float(c))
        r = int(rp - 0.5)
        a = r * n + c
        b = (r + 1) * n + c
        if sym == 'v':
            lt_edges.append((a, b))
        else:
            lt_edges.append((b, a))

    less_to_more = [[] for _ in range(n * n)]
    more_to_less = [[] for _ in range(n * n)]
    for a, b in lt_edges:
        less_to_more[a].append(b)
        more_to_less[b].append(a)

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    units_of = [[] for _ in range(n * n)]
    peers = [set() for _ in range(n * n)]
    for r in range(n):
        unit = rows[r]
        for i in unit:
            units_of[i].append(unit)
            peers[i].update(unit)
    for c in range(n):
        unit = cols[c]
        for i in unit:
            units_of[i].append(unit)
            peers[i].update(unit)
    for i in range(n * n):
        peers[i].discard(i)

    domains = [full_mask] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            idx = r * n + c
            if v is not None:
                domains[idx] = bit(v)

    # Precompute inequality longest-chain lower/upper bounds.
    indeg = [0] * (n * n)
    for a, b in lt_edges:
        indeg[b] += 1
    dq = deque([i for i in range(n * n) if indeg[i] == 0])
    topo = []
    while dq:
        x = dq.popleft()
        topo.append(x)
        for y in less_to_more[x]:
            indeg[y] -= 1
            if indeg[y] == 0:
                dq.append(y)

    if len(topo) != n * n:
        return "No Solution"

    low_rank = [1] * (n * n)
    for x in topo:
        for y in less_to_more[x]:
            if low_rank[y] < low_rank[x] + 1:
                low_rank[y] = low_rank[x] + 1

    high_rank = [n] * (n * n)
    for x in reversed(topo):
        for y in less_to_more[x]:
            if high_rank[x] > high_rank[y] - 1:
                high_rank[x] = high_rank[y] - 1

    for i in range(n * n):
        lo = low_rank[i]
        hi = high_rank[i]
        if lo > hi:
            return "No Solution"
        mask = 0
        for v in range(lo, hi + 1):
            mask |= bit(v)
        domains[i] &= mask
        if domains[i] == 0:
            return "No Solution"

    def assign(dom, idx, value_mask, queue):
        old = dom[idx]
        new = old & value_mask
        if new == 0:
            return False
        if new == old:
            return True
        dom[idx] = new
        queue.append(idx)
        return True

    def inequality_prune_pair(dom, a, b, queue):
        ma = dom[a]
        mb = dom[b]
        mina = min_val(ma)
        maxa = max_val(ma)
        minb = min_val(mb)
        maxb = max_val(mb)

        # a < b
        allowed_a = 0
        for va in mask_to_list(ma):
            if va < maxb:
                allowed_a |= bit(va)
        allowed_b = 0
        for vb in mask_to_list(mb):
            if vb > mina:
                allowed_b |= bit(vb)

        if allowed_a == 0 or allowed_b == 0:
            return False
        if allowed_a != ma:
            dom[a] = allowed_a
            queue.append(a)
        if allowed_b != mb:
            dom[b] = allowed_b
            queue.append(b)
        return True

    def unit_hidden_singles(dom, unit, queue):
        support = [0] * (n + 1)
        where = [-1] * (n + 1)
        for idx in unit:
            m = dom[idx]
            for v in mask_to_list(m):
                support[v] += 1
                where[v] = idx
        for v in range(1, n + 1):
            if support[v] == 0:
                return False
            if support[v] == 1:
                idx = where[v]
                if dom[idx] != bit(v):
                    dom[idx] = bit(v)
                    queue.append(idx)
        return True

    def unit_naked_subsets(dom, unit, queue):
        buckets = {}
        for idx in unit:
            m = dom[idx]
            pc = popcount(m)
            if 2 <= pc <= n - 1:
                buckets.setdefault(m, []).append(idx)
        for m, cells in buckets.items():
            k = popcount(m)
            if len(cells) == k:
                for idx in unit:
                    if idx not in cells:
                        nm = dom[idx] & ~m
                        if nm == 0:
                            return False
                        if nm != dom[idx]:
                            dom[idx] = nm
                            queue.append(idx)
        return True

    def interval_hall_prune(dom, unit, queue):
        # Human-like interval reasoning for Latin constraints:
        # if exactly k cells' domains lie within an interval of size k,
        # those values are locked to those cells.
        mins = []
        maxs = []
        cell_data = []
        for idx in unit:
            m = dom[idx]
            mins.append(min_val(m))
            maxs.append(max_val(m))
            cell_data.append((idx, min_val(m), max_val(m)))
        for a in range(1, n + 1):
            for b in range(a, n + 1):
                width = b - a + 1
                inside = [idx for idx, lo, hi in cell_data if lo >= a and hi <= b]
                if len(inside) > width:
                    return False
                if len(inside) == width and width < n:
                    rem_mask = 0
                    for v in range(a, b + 1):
                        rem_mask |= bit(v)
                    for idx, lo, hi in cell_data:
                        if idx not in inside:
                            nm = dom[idx] & ~rem_mask
                            if nm == 0:
                                return False
                            if nm != dom[idx]:
                                dom[idx] = nm
                                queue.append(idx)
        return True

    def propagate(dom):
        queue = deque(i for i in range(n * n))
        in_queue = [True] * (n * n)

        while queue:
            idx = queue.popleft()
            in_queue[idx] = False
            m = dom[idx]
            if m == 0:
                return False

            if popcount(m) == 1:
                # Remove fixed value from row/col peers
                for p in peers[idx]:
                    nm = dom[p] & ~m
                    if nm == 0:
                        return False
                    if nm != dom[p]:
                        dom[p] = nm
                        if not in_queue[p]:
                            queue.append(p)
                            in_queue[p] = True

            # Inequality propagation
            for y in less_to_more[idx]:
                if not inequality_prune_pair(dom, idx, y, queue):
                    return False
                in_queue[idx] = True
                in_queue[y] = True
            for x in more_to_less[idx]:
                if not inequality_prune_pair(dom, x, idx, queue):
                    return False
                in_queue[x] = True
                in_queue[idx] = True

            # Unit reasoning on row and column
            r = idx // n
            c = idx % n
            for unit in (rows[r], cols[c]):
                if not unit_hidden_singles(dom, unit, queue):
                    return False
                if not unit_naked_subsets(dom, unit, queue):
                    return False
                if not interval_hall_prune(dom, unit, queue):
                    return False
                for uidx in unit:
                    if not in_queue[uidx]:
                        queue.append(uidx)
                        in_queue[uidx] = True

        return True

    def solved(dom):
        return all(popcount(m) == 1 for m in dom)

    def choose_cell(dom):
        best = None
        best_key = None
        for i, m in enumerate(dom):
            pc = popcount(m)
            if pc > 1:
                degree = len(peers[i]) + len(less_to_more[i]) + len(more_to_less[i])
                key = (pc, -degree)
                if best_key is None or key < best_key:
                    best_key = key
                    best = i
        return best

    def ordered_values(dom, idx):
        vals = mask_to_list(dom[idx])
        scored = []
        for v in vals:
            score = 0
            for p in peers[idx]:
                if dom[p] & bit(v):
                    score += 1
            for y in less_to_more[idx]:
                score += sum(1 for w in mask_to_list(dom[y]) if w <= v)
            for x in more_to_less[idx]:
                score += sum(1 for w in mask_to_list(dom[x]) if w >= v)
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def search(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        idx = choose_cell(dom)
        if idx is None:
            return None

        for v in ordered_values(dom, idx):
            nd = dom[:]
            nd[idx] = bit(v)
            res = search(nd)
            if res is not None:
                return res
        return None

    res = search(domains)
    if res is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(min_val(res[r * n + c]))
        grid.append(row)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

