# General Takuzu/Binox with adjacency relation solver.
# Uses human-like propagation first, then tightly-pruned search.

from copy import deepcopy

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    if n == 0:
        return "No Solution"
    m = len(grid[0])
    if n != m or n % 2 != 0:
        return "No Solution"

    half = n // 2

    def parse_key(s):
        s = s.strip()[1:-1]
        a, b = s.split(',')
        a = a.strip()
        b = b.strip()
        return float(a), float(b)

    hcons = {}
    for k, v in observation.get('horizontal', {}).items():
        r, c = parse_key(k)
        r = int(r)
        c_left = int(c - 0.5)
        if 0 <= r < n and 0 <= c_left < m - 1:
            hcons[(r, c_left)] = v

    vcons = {}
    for k, v in observation.get('vertical', {}).items():
        r, c = parse_key(k)
        r_up = int(r - 0.5)
        c = int(c)
        if 0 <= r_up < n - 1 and 0 <= c < m:
            vcons[(r_up, c)] = v

    def opp(val):
        return 'B' if val == 'W' else 'W'

    def related_neighbors(r, c):
        out = []
        if c - 1 >= 0 and (r, c - 1) in hcons:
            out.append((r, c - 1, hcons[(r, c - 1)], 'h_left'))
        if c < m - 1 and (r, c) in hcons:
            out.append((r, c + 1, hcons[(r, c)], 'h_right'))
        if r - 1 >= 0 and (r - 1, c) in vcons:
            out.append((r - 1, c, vcons[(r - 1, c)], 'v_up'))
        if r < n - 1 and (r, c) in vcons:
            out.append((r + 1, c, vcons[(r, c)], 'v_down'))
        return out

    def assignment_from_relation(val, rel):
        return val if rel == '=' else opp(val)

    def set_cell(g, r, c, val):
        cur = g[r][c]
        if cur is None:
            g[r][c] = val
            return True
        return cur == val

    def row_counts_ok(line):
        b = line.count('B')
        w = line.count('W')
        u = line.count(None)
        return b <= half and w <= half and b + u >= half and w + u >= half

    def no_triplets_possible(line):
        for i in range(len(line) - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]
            if a is not None and a == b == c:
                return False
        return True

    def row_unique_ok(g, idx, is_row=True):
        line = g[idx] if is_row else [g[r][idx] for r in range(n)]
        if any(x is None for x in line):
            return True
        for j in range(n):
            if j == idx:
                continue
            other = g[j] if is_row else [g[r][j] for r in range(n)]
            if None not in other and other == line:
                return False
        return True

    def partial_unique_ok(g, idx, is_row=True):
        line = g[idx] if is_row else [g[r][idx] for r in range(n)]
        known_positions = [i for i, v in enumerate(line) if v is not None]
        if not known_positions:
            return True
        for j in range(n):
            if j == idx:
                continue
            other = g[j] if is_row else [g[r][j] for r in range(n)]
            if None in other:
                continue
            same = True
            for p in known_positions:
                if other[p] != line[p]:
                    same = False
                    break
            if same and all(v is not None for v in line):
                return False
        return True

    def line_force_triplets(g):
        changed = False
        # Rows
        for r in range(n):
            line = g[r]
            for i in range(n - 2):
                a, b, c = line[i], line[i + 1], line[i + 2]
                if a is not None and a == b and c is None:
                    if not set_cell(g, r, i + 2, opp(a)):
                        return None
                    changed = True
                if a is not None and c is not None and a == c and b is None:
                    if not set_cell(g, r, i + 1, opp(a)):
                        return None
                    changed = True
                if b is not None and c is not None and b == c and a is None:
                    if not set_cell(g, r, i, opp(b)):
                        return None
                    changed = True
        # Cols
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            for i in range(n - 2):
                a, b, d = col[i], col[i + 1], col[i + 2]
                if a is not None and a == b and d is None:
                    if not set_cell(g, i + 2, c, opp(a)):
                        return None
                    changed = True
                if a is not None and d is not None and a == d and b is None:
                    if not set_cell(g, i + 1, c, opp(a)):
                        return None
                    changed = True
                if b is not None and d is not None and b == d and a is None:
                    if not set_cell(g, i, c, opp(b)):
                        return None
                    changed = True
        return changed

    def line_force_counts(g):
        changed = False
        for r in range(n):
            row = g[r]
            b = row.count('B')
            w = row.count('W')
            if b > half or w > half:
                return None
            if b == half:
                for c in range(n):
                    if g[r][c] is None:
                        if not set_cell(g, r, c, 'W'):
                            return None
                        changed = True
            elif w == half:
                for c in range(n):
                    if g[r][c] is None:
                        if not set_cell(g, r, c, 'B'):
                            return None
                        changed = True
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            b = col.count('B')
            w = col.count('W')
            if b > half or w > half:
                return None
            if b == half:
                for r in range(n):
                    if g[r][c] is None:
                        if not set_cell(g, r, c, 'W'):
                            return None
                        changed = True
            elif w == half:
                for r in range(n):
                    if g[r][c] is None:
                        if not set_cell(g, r, c, 'B'):
                            return None
                        changed = True
        return changed

    def propagate_relations(g):
        changed = False
        progress = True
        while progress:
            progress = False
            for r in range(n):
                for c in range(m):
                    if g[r][c] is None:
                        continue
                    val = g[r][c]
                    for nr, nc, rel, _ in related_neighbors(r, c):
                        needed = assignment_from_relation(val, rel)
                        cur = g[nr][nc]
                        if cur is None:
                            g[nr][nc] = needed
                            changed = True
                            progress = True
                        elif cur != needed:
                            return None
            # Also infer reverse consistency where both filled.
            for (r, c), rel in hcons.items():
                a, b = g[r][c], g[r][c + 1]
                if a is not None and b is not None:
                    if (a == b) != (rel == '='):
                        return None
            for (r, c), rel in vcons.items():
                a, b = g[r][c], g[r + 1][c]
                if a is not None and b is not None:
                    if (a == b) != (rel == '='):
                        return None
        return changed

    def advanced_uniqueness(g):
        changed = False
        # If a row is one cell away from matching a completed row, force opposite in that spot.
        complete_rows = [(i, g[i]) for i in range(n) if None not in g[i]]
        for r in range(n):
            row = g[r]
            if row.count(None) == 1:
                c = row.index(None)
                for _, full in complete_rows:
                    same = True
                    for j in range(n):
                        if j == c:
                            continue
                        if row[j] != full[j]:
                            same = False
                            break
                    if same:
                        if not set_cell(g, r, c, opp(full[c])):
                            return None
                        changed = True
        complete_cols = []
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if None not in col:
                complete_cols.append((c, col))
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if col.count(None) == 1:
                r0 = col.index(None)
                for _, full in complete_cols:
                    same = True
                    for i in range(n):
                        if i == r0:
                            continue
                        if col[i] != full[i]:
                            same = False
                            break
                    if same:
                        if not set_cell(g, r0, c, opp(full[r0])):
                            return None
                        changed = True
        return changed

    def valid(g):
        for r in range(n):
            row = g[r]
            if not row_counts_ok(row) or not no_triplets_possible(row) or not partial_unique_ok(g, r, True):
                return False
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if not row_counts_ok(col) or not no_triplets_possible(col) or not partial_unique_ok(g, c, False):
                return False
        for (r, c), rel in hcons.items():
            a, b = g[r][c], g[r][c + 1]
            if a is not None and b is not None and ((a == b) != (rel == '=')):
                return False
        for (r, c), rel in vcons.items():
            a, b = g[r][c], g[r + 1][c]
            if a is not None and b is not None and ((a == b) != (rel == '=')):
                return False
        for r in range(n):
            if not row_unique_ok(g, r, True):
                return False
        for c in range(n):
            if not row_unique_ok(g, c, False):
                return False
        return True

    def propagate(g):
        while True:
            any_change = False
            res = propagate_relations(g)
            if res is None:
                return None
            any_change |= res

            res = line_force_triplets(g)
            if res is None:
                return None
            any_change |= res

            res = line_force_counts(g)
            if res is None:
                return None
            any_change |= res

            res = advanced_uniqueness(g)
            if res is None:
                return None
            any_change |= res

            if not valid(g):
                return None

            if not any_change:
                break
        return g

    def candidates_for_cell(g, r, c):
        vals = []
        for v in ('B', 'W'):
            gg = [row[:] for row in g]
            if not set_cell(gg, r, c, v):
                continue
            if propagate(gg) is not None:
                vals.append(v)
        return vals

    def select_cell(g):
        best = None
        best_cands = None
        for r in range(n):
            for c in range(n):
                if g[r][c] is None:
                    cands = candidates_for_cell(g, r, c)
                    if not cands:
                        return (r, c, [])
                    if best is None or len(cands) < len(best_cands):
                        best = (r, c)
                        best_cands = cands
                        if len(cands) == 1:
                            return (r, c, cands)
        if best is None:
            return None
        return (best[0], best[1], best_cands)

    def is_complete(g):
        return all(all(v is not None for v in row) for row in g)

    def dfs(g):
        g = propagate([row[:] for row in g])
        if g is None:
            return None
        if is_complete(g):
            return g
        choice = select_cell(g)
        if choice is None:
            return g
        r, c, cands = choice
        for v in cands:
            gg = [row[:] for row in g]
            if not set_cell(gg, r, c, v):
                continue
            ans = dfs(gg)
            if ans is not None:
                return ans
        return None

    ans = dfs(grid)
    if ans is None:
        return "No Solution"
    return str(ans)

