# Futoshiki solver with strong human-like deduction:
# - row/column Latin constraints
# - direct inequality filtering
# - inequality bound propagation
# - hidden singles in rows/columns
# - subset elimination (naked subsets)
# - branch on most constrained cell only after propagation stalls

from copy import deepcopy

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    def val_to_bit(v):
        return 1 << (v - 1)

    def bit_count(x):
        return x.bit_count()

    def bits_to_values(mask):
        vals = []
        v = 1
        while mask:
            b = mask & -mask
            vals.append((b.bit_length()))
            mask ^= b
            v += 1
        return vals

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def mask_le(k):
        if k <= 0:
            return 0
        if k >= n:
            return full_mask
        return (1 << k) - 1

    def mask_ge(k):
        if k <= 1:
            return full_mask
        if k > n:
            return 0
        return full_mask ^ ((1 << (k - 1)) - 1)

    # Parse inequalities into directed comparisons a < b
    less_than = []
    for key, sym in observation.get('horizontal', {}).items():
        row, c05 = key.strip('()').split(',')
        r = int(float(row))
        c = int(float(c05) - 0.5)
        if sym == '<':
            less_than.append(((r, c), (r, c + 1)))
        elif sym == '>':
            less_than.append(((r, c + 1), (r, c)))
    for key, sym in observation.get('vertical', {}).items():
        r05, col = key.strip('()').split(',')
        r = int(float(r05) - 0.5)
        c = int(float(col))
        # Based on the image convention used here:
        # '^' means upper cell > lower cell, so lower < upper
        # 'v' means upper cell < lower cell
        if sym == '^':
            less_than.append(((r + 1, c), (r, c)))
        elif sym == 'v':
            less_than.append(((r, c), (r + 1, c)))

    # Neighbors for quick propagation
    lt_out = {}
    lt_in = {}
    for a, b in less_than:
        lt_out.setdefault(a, []).append(b)
        lt_in.setdefault(b, []).append(a)

    # Initial domains
    domains = [[full_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = val_to_bit(data[r][c])

    def is_single(mask):
        return mask and (mask & (mask - 1) == 0)

    def assign(dom, r, c, value):
        m = val_to_bit(value)
        if dom[r][c] & m == 0:
            return False
        if dom[r][c] == m:
            return True
        dom[r][c] = m
        return True

    def eliminate(dom, r, c, remove_mask):
        new_mask = dom[r][c] & ~remove_mask
        if new_mask == 0:
            return False
        dom[r][c] = new_mask
        return True

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Row/column solved-value elimination
            for r in range(n):
                fixed = 0
                for c in range(n):
                    m = dom[r][c]
                    if is_single(m):
                        fixed |= m
                for c in range(n):
                    if not is_single(dom[r][c]):
                        nm = dom[r][c] & ~fixed
                        if nm == 0:
                            return False
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True

            for c in range(n):
                fixed = 0
                for r in range(n):
                    m = dom[r][c]
                    if is_single(m):
                        fixed |= m
                for r in range(n):
                    if not is_single(dom[r][c]):
                        nm = dom[r][c] & ~fixed
                        if nm == 0:
                            return False
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True

            # All-different contradiction checks + hidden singles
            for r in range(n):
                seen = 0
                for c in range(n):
                    m = dom[r][c]
                    if is_single(m):
                        if seen & m:
                            return False
                        seen |= m
                for v in range(1, n + 1):
                    bit = val_to_bit(v)
                    places = [c for c in range(n) if dom[r][c] & bit]
                    if not places:
                        return False
                    if len(places) == 1 and dom[r][places[0]] != bit:
                        dom[r][places[0]] = bit
                        changed = True

            for c in range(n):
                seen = 0
                for r in range(n):
                    m = dom[r][c]
                    if is_single(m):
                        if seen & m:
                            return False
                        seen |= m
                for v in range(1, n + 1):
                    bit = val_to_bit(v)
                    places = [r for r in range(n) if dom[r][c] & bit]
                    if not places:
                        return False
                    if len(places) == 1 and dom[places[0]][c] != bit:
                        dom[places[0]][c] = bit
                        changed = True

            # Naked subsets in rows
            for r in range(n):
                groups = {}
                for c in range(n):
                    m = dom[r][c]
                    bc = bit_count(m)
                    if 2 <= bc <= n - 1:
                        groups.setdefault(m, []).append(c)
                for m, cells in groups.items():
                    k = bit_count(m)
                    if len(cells) == k:
                        for c2 in range(n):
                            if c2 not in cells:
                                nm = dom[r][c2] & ~m
                                if nm == 0:
                                    return False
                                if nm != dom[r][c2]:
                                    dom[r][c2] = nm
                                    changed = True

            # Naked subsets in columns
            for c in range(n):
                groups = {}
                for r in range(n):
                    m = dom[r][c]
                    bc = bit_count(m)
                    if 2 <= bc <= n - 1:
                        groups.setdefault(m, []).append(r)
                for m, cells in groups.items():
                    k = bit_count(m)
                    if len(cells) == k:
                        for r2 in range(n):
                            if r2 not in cells:
                                nm = dom[r2][c] & ~m
                                if nm == 0:
                                    return False
                                if nm != dom[r2][c]:
                                    dom[r2][c] = nm
                                    changed = True

            # Inequality propagation a < b
            for a, b in less_than:
                ar, ac = a
                br, bc = b
                ma = dom[ar][ac]
                mb = dom[br][bc]
                mina, maxa = min_val(ma), max_val(ma)
                minb, maxb = min_val(mb), max_val(mb)

                # a must be <= maxb-1 ; b must be >= mina+1
                new_ma = ma & mask_le(maxb - 1)
                new_mb = mb & mask_ge(mina + 1)

                if new_ma == 0 or new_mb == 0:
                    return False

                # stronger support filtering
                minb2 = min_val(new_mb)
                maxa2 = max_val(new_ma)
                new_ma2 = new_ma & mask_le(maxa2)
                new_mb2 = new_mb & mask_ge(minb2)

                # exact support prune
                supported_a = 0
                temp = new_ma
                while temp:
                    ba = temp & -temp
                    va = ba.bit_length()
                    if new_mb & mask_ge(va + 1):
                        supported_a |= ba
                    temp ^= ba

                supported_b = 0
                temp = new_mb
                while temp:
                    bb = temp & -temp
                    vb = bb.bit_length()
                    if new_ma & mask_le(vb - 1):
                        supported_b |= bb
                    temp ^= bb

                if supported_a == 0 or supported_b == 0:
                    return False

                if supported_a != dom[ar][ac]:
                    dom[ar][ac] = supported_a
                    changed = True
                if supported_b != dom[br][bc]:
                    dom[br][bc] = supported_b
                    changed = True

            # Final contradiction checks
            for r in range(n):
                for c in range(n):
                    if dom[r][c] == 0:
                        return False

        return True

    def solved(dom):
        return all(is_single(dom[r][c]) for r in range(n) for c in range(n))

    def choose_cell(dom):
        best = None
        best_key = None
        for r in range(n):
            row_fixed = sum(1 for c in range(n) if is_single(dom[r][c]))
            for c in range(n):
                m = dom[r][c]
                bc = bit_count(m)
                if bc > 1:
                    deg = len(lt_out.get((r, c), ())) + len(lt_in.get((r, c), ()))
                    col_fixed = sum(1 for rr in range(n) if is_single(dom[rr][c]))
                    key = (bc, -(row_fixed + col_fixed + deg), r, c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def ordered_values(dom, r, c):
        m = dom[r][c]
        vals = []
        temp = m
        while temp:
            b = temp & -temp
            v = b.bit_length()
            score = 0

            # Prefer values that satisfy inequalities tightly and reduce peers.
            for rr in range(n):
                if rr != r and (dom[rr][c] & b):
                    score += 1
            for cc in range(n):
                if cc != c and (dom[r][cc] & b):
                    score += 1

            for nb in lt_out.get((r, c), ()):
                mb = dom[nb[0]][nb[1]]
                # (r,c) < nb, so higher values are worse
                if mb & mask_ge(v + 1):
                    score -= 1
                else:
                    score += 5
            for nb in lt_in.get((r, c), ()):
                mb = dom[nb[0]][nb[1]]
                # nb < (r,c), so lower values are worse
                if mb & mask_le(v - 1):
                    score -= 1
                else:
                    score += 5

            vals.append((score, v))
            temp ^= b
        vals.sort()
        return [v for _, v in vals]

    def search(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        r, c = choose_cell(dom)
        for v in ordered_values(dom, r, c):
            new_dom = [row[:] for row in dom]
            if assign(new_dom, r, c, v):
                res = search(new_dom)
                if res is not None:
                    return res
        return None

    result = search([row[:] for row in domains])
    if result is None:
        return "No Solution"

    grid = [[min_val(result[r][c]) for c in range(n)] for r in range(n)]
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

