# General Futoshiki solver using aggressive propagation plus limited search.
# Symbols interpretation used here:
# Horizontal at (r, c+0.5):
#   '<' means cell(r,c) < cell(r,c+1)
#   '>' means cell(r,c) > cell(r,c+1)
# Vertical at (r+0.5, c):
#   '^' means cell(r,c) < cell(r+1,c)
#   'v' means cell(r,c) > cell(r+1,c)

def solve(observation):
    N = len(observation['data'])
    full_mask = (1 << N) - 1

    def bit(v):
        return 1 << (v - 1)

    def values_from_mask(mask):
        v = 1
        while mask:
            b = mask & -mask
            yield (b.bit_length())
            mask ^= b
            v += 1

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def popcount(x):
        return x.bit_count()

    # Build inequality edge list: (a_index, b_index, rel) with rel = -1 meaning a < b, +1 meaning a > b
    edges = []
    h = observation.get('horizontal', {})
    v = observation.get('vertical', {})

    for k, sym in h.items():
        r, c = k.strip('()').split(',')
        r = int(float(r))
        c = float(c)
        left = int(c - 0.5)
        right = left + 1
        a = r * N + left
        b = r * N + right
        if sym == '<':
            edges.append((a, b, -1))
        elif sym == '>':
            edges.append((a, b, +1))

    for k, sym in v.items():
        r, c = k.strip('()').split(',')
        r = float(r)
        c = int(float(c))
        top = int(r - 0.5)
        bottom = top + 1
        a = top * N + c
        b = bottom * N + c
        if sym == '^':
            edges.append((a, b, -1))
        elif sym == 'v':
            edges.append((a, b, +1))

    # Neighbors for fast propagation
    ineq_adj = [[] for _ in range(N * N)]
    for a, b, rel in edges:
        ineq_adj[a].append((b, rel))
        ineq_adj[b].append((a, -rel))

    row_cells = [[r * N + c for c in range(N)] for r in range(N)]
    col_cells = [[r * N + c for r in range(N)] for c in range(N)]

    domains = [full_mask] * (N * N)

    # Initialize givens
    for r in range(N):
        for c in range(N):
            val = observation['data'][r][c]
            if val is not None:
                domains[r * N + c] = bit(val)

    def assign(dom, idx, mask):
        old = dom[idx]
        new = old & mask
        if new == 0:
            return False, None
        if new == old:
            return True, False
        dom[idx] = new
        return True, popcount(new) == 1

    def inequality_reduce_pair(ma, mb, rel):
        # rel=-1 => a < b, rel=+1 => a > b
        if rel == -1:
            mina, maxa = min_val(ma), max_val(ma)
            minb, maxb = min_val(mb), max_val(mb)
            na = ma & ((1 << (maxb - 1)) - 1) if maxb > 1 else 0
            nb = mb & ~((1 << mina) - 1)
            return na, nb
        else:
            nb, na = inequality_reduce_pair(mb, ma, -1)
            return na, nb

    def hidden_singles(dom, units):
        changed = False
        for unit in units:
            places = [0] * (N + 1)
            counts = [0] * (N + 1)
            for idx in unit:
                m = dom[idx]
                mm = m
                while mm:
                    b = mm & -mm
                    val = b.bit_length()
                    counts[val] += 1
                    places[val] = idx
                    mm ^= b
            for val in range(1, N + 1):
                if counts[val] == 0:
                    return None
                if counts[val] == 1:
                    idx = places[val]
                    ok, became_single = assign(dom, idx, bit(val))
                    if not ok:
                        return None
                    if became_single is not False:
                        changed = True
        return changed

    def naked_subsets_unit(dom, unit):
        changed = False
        buckets = {}
        unsolved = []
        for idx in unit:
            m = dom[idx]
            pc = popcount(m)
            if 2 <= pc <= 4:
                buckets.setdefault(m, []).append(idx)
                unsolved.append(idx)
        for m, cells in buckets.items():
            k = popcount(m)
            if len(cells) == k:
                for idx in unit:
                    if idx not in cells:
                        old = dom[idx]
                        new = old & ~m
                        if new == 0:
                            return None
                        if new != old:
                            dom[idx] = new
                            changed = True
        return changed

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Row/column solved-value elimination and contradiction checks
            for units in (row_cells, col_cells):
                for unit in units:
                    solved_mask = 0
                    seen = 0
                    for idx in unit:
                        m = dom[idx]
                        if m == 0:
                            return False
                        if popcount(m) == 1:
                            if solved_mask & m:
                                return False
                            solved_mask |= m
                    if solved_mask:
                        for idx in unit:
                            m = dom[idx]
                            if popcount(m) > 1:
                                new = m & ~solved_mask
                                if new == 0:
                                    return False
                                if new != m:
                                    dom[idx] = new
                                    changed = True

            # Inequality local reduction
            for a, b, rel in edges:
                ma, mb = dom[a], dom[b]
                na, nb = inequality_reduce_pair(ma, mb, rel)
                if na == 0 or nb == 0:
                    return False
                if na != ma:
                    dom[a] = na
                    changed = True
                if nb != mb:
                    dom[b] = nb
                    changed = True

            # Hidden singles
            hs = hidden_singles(dom, row_cells)
            if hs is None:
                return False
            changed |= hs
            hs = hidden_singles(dom, col_cells)
            if hs is None:
                return False
            changed |= hs

            # Naked subsets
            for units in (row_cells, col_cells):
                for unit in units:
                    ns = naked_subsets_unit(dom, unit)
                    if ns is None:
                        return False
                    changed |= ns

            # Stronger inequality chain bounds using rank feasibility in units
            # For each unit, if k cells are already forced below/above by inequalities, prune impossible extremes.
            for idx in range(N * N):
                m = dom[idx]
                if m == 0:
                    return False
                if popcount(m) == 1:
                    continue

                # Count strict lower/upper chain lengths by DFS on inequalities only
                lower_seen = set()
                stack = [idx]
                while stack:
                    x = stack.pop()
                    for y, rel in ineq_adj[x]:
                        # x < y if rel == -1, x > y if rel == +1
                        if rel == +1 and y not in lower_seen:
                            lower_seen.add(y)
                            stack.append(y)
                upper_seen = set()
                stack = [idx]
                while stack:
                    x = stack.pop()
                    for y, rel in ineq_adj[x]:
                        if rel == -1 and y not in upper_seen:
                            upper_seen.add(y)
                            stack.append(y)

                low_rank = len(lower_seen) + 1
                high_rank = N - len(upper_seen)
                new = m & (((1 << high_rank) - 1) if high_rank < N else full_mask) & ~((1 << (low_rank - 1)) - 1)
                if new == 0:
                    return False
                if new != m:
                    dom[idx] = new
                    changed = True

        return True

    def solved(dom):
        return all(popcount(m) == 1 for m in dom)

    def select_cell(dom):
        best = None
        best_score = None
        for idx, m in enumerate(dom):
            pc = popcount(m)
            if pc > 1:
                degree = len(ineq_adj[idx]) + 2 * N
                score = (pc, -degree)
                if best_score is None or score < best_score:
                    best_score = score
                    best = idx
        return best

    def order_values(dom, idx):
        m = dom[idx]
        vals = []
        mm = m
        while mm:
            b = mm & -mm
            val = b.bit_length()
            impact = 0
            r, c = divmod(idx, N)

            # Least-constraining heuristic
            for j in row_cells[r]:
                if j != idx and (dom[j] & b):
                    impact += 1
            for j in col_cells[c]:
                if j != idx and (dom[j] & b):
                    impact += 1
            for j, rel in ineq_adj[idx]:
                mj = dom[j]
                if rel == -1:
                    # idx < j
                    if max_val(mj) <= val:
                        impact += 100
                    else:
                        # larger impact if many options removed from neighbor
                        impact += popcount(mj & ((1 << val) - 1))
                else:
                    # idx > j
                    if min_val(mj) >= val:
                        impact += 100
                    else:
                        impact += popcount(mj & ~((1 << (val - 1)) - 1))
            vals.append((impact, val))
            mm ^= b
        vals.sort()
        return [v for _, v in vals]

    def search(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        idx = select_cell(dom)
        for val in order_values(dom, idx):
            nd = dom[:]
            nd[idx] = bit(val)
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(domains[:])
    if result is None:
        return "No Solution"

    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(result[r * N + c].bit_length())
        grid.append(row)
    return str(grid)

