# Generalized Futoshiki solver with strong logical propagation and bounded search.
# Symbols are interpreted exactly as drawn between adjacent cells:
# Horizontal at (r, c+0.5): '<' means cell(r,c) < cell(r,c+1), '>' means cell(r,c) > cell(r,c+1)
# Vertical at (r+0.5, c): '^' means cell(r,c) < cell(r+1,c), 'v' means cell(r,c) > cell(r+1,c)

from copy import deepcopy

def parse_coord_key(key):
    s = key.strip()
    if s[0] == '(' and s[-1] == ')':
        s = s[1:-1]
    a, b = s.split(',')
    x = float(a.strip())
    y = float(b.strip())
    return x, y

def build_relations(observation):
    n = len(observation['data'])
    less_edges = []
    greater_edges = []

    for k, sym in observation.get('horizontal', {}).items():
        r, c_half = parse_coord_key(k)
        r = int(round(r))
        c = int(round(c_half - 0.5))
        a = (r, c)
        b = (r, c + 1)
        if sym == '<':
            less_edges.append((a, b))
            greater_edges.append((b, a))
        elif sym == '>':
            less_edges.append((b, a))
            greater_edges.append((a, b))

    for k, sym in observation.get('vertical', {}).items():
        r_half, c = parse_coord_key(k)
        r = int(round(r_half - 0.5))
        c = int(round(c))
        a = (r, c)
        b = (r + 1, c)
        if sym == '^':
            less_edges.append((a, b))
            greater_edges.append((b, a))
        elif sym == 'v':
            less_edges.append((b, a))
            greater_edges.append((a, b))

    less_from = {(r, c): [] for r in range(n) for c in range(n)}
    greater_from = {(r, c): [] for r in range(n) for c in range(n)}
    for u, v in less_edges:
        less_from[u].append(v)
    for u, v in greater_edges:
        greater_from[u].append(v)
    return less_from, greater_from

def bit_count(x):
    return x.bit_count()

def lowbit_index(x):
    return (x & -x).bit_length() - 1

def mask_to_values(mask, n):
    vals = []
    while mask:
        b = x = mask & -mask
        vals.append(lowbit_index(b) + 1)
        mask ^= b
    return vals

def single_value(mask):
    return lowbit_index(mask) + 1

def min_value(mask):
    return lowbit_index(mask) + 1

def max_value(mask):
    return mask.bit_length()

def remove_leq(mask, k):
    if k <= 0:
        return mask
    return mask & ~((1 << k) - 1)

def remove_geq(mask, k, n):
    if k > n:
        return mask
    return mask & ((1 << (k - 1)) - 1)

def enforce_ineq_pair(mask_a, mask_b, relation, n):
    # relation: '<' means a < b ; '>' means a > b
    changed = False
    if relation == '<':
        if mask_a == 0 or mask_b == 0:
            return 0, 0, True
        max_b = max_value(mask_b)
        min_a = min_value(mask_a)
        new_a = remove_geq(mask_a, max_b, n)      # a < max_b
        new_b = remove_leq(mask_b, min_a)         # b > min_a
        if new_a != mask_a:
            mask_a = new_a
            changed = True
        if new_b != mask_b:
            mask_b = new_b
            changed = True
    else:
        if mask_a == 0 or mask_b == 0:
            return 0, 0, True
        min_b = min_value(mask_b)
        max_a = max_value(mask_a)
        new_a = remove_leq(mask_a, min_b)         # a > min_b
        new_b = remove_geq(mask_b, max_a, n)      # b < max_a
        if new_a != mask_a:
            mask_a = new_a
            changed = True
        if new_b != mask_b:
            mask_b = new_b
            changed = True
    return mask_a, mask_b, changed

def solve(observation):
    n = len(observation['data'])
    full = (1 << n) - 1
    less_from, greater_from = build_relations(observation)

    domains = [[full for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n

    for r in range(n):
        for c in range(n):
            v = observation['data'][r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                bit = 1 << (v - 1)
                if (row_used[r] & bit) or (col_used[c] & bit):
                    return "No Solution"
                domains[r][c] = bit
                row_used[r] |= bit
                col_used[c] |= bit

    # Initial Latin filtering from givens.
    for r in range(n):
        used = row_used[r]
        for c in range(n):
            if bit_count(domains[r][c]) > 1:
                domains[r][c] &= ~used
                if domains[r][c] == 0:
                    return "No Solution"
    for c in range(n):
        used = col_used[c]
        for r in range(n):
            if bit_count(domains[r][c]) > 1:
                domains[r][c] &= ~used
                if domains[r][c] == 0:
                    return "No Solution"

    all_cells = [(r, c) for r in range(n) for c in range(n)]

    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # 1) Assigned values eliminate from row/col peers.
            row_fixed = [0] * n
            col_fixed = [0] * n
            for r in range(n):
                for c in range(n):
                    m = domains[r][c]
                    if m == 0:
                        return None
                    if bit_count(m) == 1:
                        row_fixed[r] |= m
                        col_fixed[c] |= m

            for r in range(n):
                fixed = row_fixed[r]
                for c in range(n):
                    m = domains[r][c]
                    if bit_count(m) > 1:
                        nm = m & ~fixed
                        if nm != m:
                            domains[r][c] = nm
                            if nm == 0:
                                return None
                            changed = True

            for c in range(n):
                fixed = col_fixed[c]
                for r in range(n):
                    m = domains[r][c]
                    if bit_count(m) > 1:
                        nm = m & ~fixed
                        if nm != m:
                            domains[r][c] = nm
                            if nm == 0:
                                return None
                            changed = True

            # 2) Hidden singles in rows and columns.
            for r in range(n):
                pos = [0] * n
                for c in range(n):
                    m = domains[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        pos[lowbit_index(b)] += 1
                        mm ^= b
                for v_idx in range(n):
                    if pos[v_idx] == 0:
                        return None
                    if pos[v_idx] == 1:
                        bit = 1 << v_idx
                        target = None
                        for c in range(n):
                            if domains[r][c] & bit:
                                target = c
                                break
                        if domains[r][target] != bit:
                            domains[r][target] = bit
                            changed = True

            for c in range(n):
                pos = [0] * n
                for r in range(n):
                    m = domains[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        pos[lowbit_index(b)] += 1
                        mm ^= b
                for v_idx in range(n):
                    if pos[v_idx] == 0:
                        return None
                    if pos[v_idx] == 1:
                        bit = 1 << v_idx
                        target = None
                        for r in range(n):
                            if domains[r][c] & bit:
                                target = r
                                break
                        if domains[target][c] != bit:
                            domains[target][c] = bit
                            changed = True

            # 3) Inequality propagation.
            for r in range(n):
                for c in range(n):
                    a = domains[r][c]
                    for rr, cc in less_from[(r, c)]:
                        b = domains[rr][cc]
                        na, nb, ch = enforce_ineq_pair(a, b, '<', n)
                        if na == 0 or nb == 0:
                            return None
                        if ch:
                            domains[r][c] = na
                            domains[rr][cc] = nb
                            a = na
                            changed = True
                    a = domains[r][c]
                    for rr, cc in greater_from[(r, c)]:
                        b = domains[rr][cc]
                        na, nb, ch = enforce_ineq_pair(a, b, '>', n)
                        if na == 0 or nb == 0:
                            return None
                        if ch:
                            domains[r][c] = na
                            domains[rr][cc] = nb
                            a = na
                            changed = True

            # 4) Human-style Hall subset filtering in rows/cols.
            # If k cells' candidates union to k values, remove those values from other cells.
            for r in range(n):
                groups = {}
                for c in range(n):
                    m = domains[r][c]
                    bc = bit_count(m)
                    if 1 < bc < n:
                        groups.setdefault(m, []).append(c)
                masks = list(groups.keys())
                # identical-mask naked subsets
                for m in masks:
                    k = bit_count(m)
                    if len(groups[m]) == k:
                        for c in range(n):
                            if c not in groups[m]:
                                nm = domains[r][c] & ~m
                                if nm != domains[r][c]:
                                    domains[r][c] = nm
                                    if nm == 0:
                                        return None
                                    changed = True

            for c in range(n):
                groups = {}
                for r in range(n):
                    m = domains[r][c]
                    bc = bit_count(m)
                    if 1 < bc < n:
                        groups.setdefault(m, []).append(r)
                masks = list(groups.keys())
                for m in masks:
                    k = bit_count(m)
                    if len(groups[m]) == k:
                        for r in range(n):
                            if r not in groups[m]:
                                nm = domains[r][c] & ~m
                                if nm != domains[r][c]:
                                    domains[r][c] = nm
                                    if nm == 0:
                                        return None
                                    changed = True

            # 5) Quick contradiction checks for duplicate fixed values in row/col.
            for r in range(n):
                seen = 0
                for c in range(n):
                    m = domains[r][c]
                    if bit_count(m) == 1:
                        if seen & m:
                            return None
                        seen |= m
            for c in range(n):
                seen = 0
                for r in range(n):
                    m = domains[r][c]
                    if bit_count(m) == 1:
                        if seen & m:
                            return None
                        seen |= m

        return domains

    def solved(domains):
        for r in range(n):
            rowmask = 0
            for c in range(n):
                m = domains[r][c]
                if bit_count(m) != 1:
                    return False
                rowmask |= m
            if rowmask != full:
                return False
        for c in range(n):
            colmask = 0
            for r in range(n):
                m = domains[r][c]
                colmask |= m
            if colmask != full:
                return False
        return True

    def pick_branch_cell(domains):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                m = domains[r][c]
                bc = bit_count(m)
                if bc > 1:
                    deg = len(less_from[(r, c)]) + len(greater_from[(r, c)])
                    score = (bc, -deg)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
        return best

    def value_order(domains, r, c):
        vals = mask_to_values(domains[r][c], n)
        # Least-constraining-ish with inequality bias.
        scored = []
        for v in vals:
            score = 0
            for rr, cc in less_from[(r, c)]:
                m = domains[rr][cc]
                cnt = 0
                mm = m
                while mm:
                    b = mm & -mm
                    if lowbit_index(b) + 1 > v:
                        cnt += 1
                    mm ^= b
                score += cnt
            for rr, cc in greater_from[(r, c)]:
                m = domains[rr][cc]
                cnt = 0
                mm = m
                while mm:
                    b = mm & -mm
                    if lowbit_index(b) + 1 < v:
                        cnt += 1
                    mm ^= b
                score += cnt
            scored.append((-score, v))
        scored.sort()
        return [v for _, v in scored]

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if solved(domains):
            return domains

        r, c = pick_branch_cell(domains)
        for v in value_order(domains, r, c):
            nd = [row[:] for row in domains]
            nd[r][c] = 1 << (v - 1)
            res = dfs(nd)
            if res is not None:
                return res
        return None

    result = dfs(domains)
    if result is None:
        return "No Solution"

    grid = [[single_value(result[r][c]) for c in range(n)] for r in range(n)]
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, 7, None, None, None], [None, None, 4, None, None, None, 7]], 'horizontal': {'(0,1.5)': '<', '(0,3.5)': '>', '(1,3.5)': '>', '(4,0.5)': '>', '(4,5.5)': '>', '(6,2.5)': '<', '(6,3.5)': '>', '(6,4.5)': '>'}, 'vertical': {'(0.5,1)': 'v', '(0.5,2)': '^', '(0.5,5)': '^', '(1.5,6)': '^', '(2.5,2)': '^', '(2.5,6)': '^', '(4.5,1)': 'v', '(4.5,2)': 'v', '(4.5,5)': '^', '(4.5,6)': 'v', '(5.5,0)': '^', '(5.5,2)': 'v'}}

# General Futoshiki solver using human-like propagation plus tightly pruned search.
# Symbols interpretation used here:
# Horizontal at (r, c+0.5):
#   '<' means cell(r,c) < cell(r,c+1)
#   '>' means cell(r,c) > cell(r,c+1)
# Vertical at (r+0.5, c):
#   '^' means cell(r,c) < cell(r+1,c)
#   'v' means cell(r,c) > cell(r+1,c)

def solve(observation):
    N = len(observation['data'])
    full_mask = (1 << N) - 1

    def bit(v):
        return 1 << (v - 1)

    def bits_to_list(mask):
        out = []
        v = 1
        while mask:
            if mask & 1:
                out.append(v)
            mask >>= 1
            v += 1
        return out

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    # Build inequality arcs as directed "a < b"
    less_edges = []
    for k, sym in observation.get('horizontal', {}).items():
        s = k.strip()[1:-1]
        r_str, c_str = s.split(',')
        r = int(float(r_str))
        c_half = float(c_str)
        c = int(c_half - 0.5)
        a = (r, c)
        b = (r, c + 1)
        if sym == '<':
            less_edges.append((a, b))
        elif sym == '>':
            less_edges.append((b, a))
        else:
            return "No Solution"

    for k, sym in observation.get('vertical', {}).items():
        s = k.strip()[1:-1]
        r_str, c_str = s.split(',')
        r_half = float(r_str)
        c = int(float(c_str))
        r = int(r_half - 0.5)
        a = (r, c)
        b = (r + 1, c)
        if sym == '^':
            less_edges.append((a, b))
        elif sym == 'v':
            less_edges.append((b, a))
        else:
            return "No Solution"

    # Adjacency for quick propagation
    less_out = [[[] for _ in range(N)] for _ in range(N)]
    less_in = [[[] for _ in range(N)] for _ in range(N)]
    for (r1, c1), (r2, c2) in less_edges:
        less_out[r1][c1].append((r2, c2))
        less_in[r2][c2].append((r1, c1))

    # Transitive closure on inequality DAG/graph for bounds reasoning
    idx = lambda r, c: r * N + c
    reach = [[False] * (N * N) for _ in range(N * N)]
    for i in range(N * N):
        reach[i][i] = True
    for (r1, c1), (r2, c2) in less_edges:
        reach[idx(r1, c1)][idx(r2, c2)] = True
    for k in range(N * N):
        rk = reach[k]
        for i in range(N * N):
            if reach[i][k]:
                ri = reach[i]
                for j in range(N * N):
                    if rk[j]:
                        ri[j] = True

    lower_chain = [[0] * N for _ in range(N)]  # count of strict predecessors reachable
    upper_chain = [[0] * N for _ in range(N)]  # count of strict successors reachable
    for r in range(N):
        for c in range(N):
            me = idx(r, c)
            pred = 0
            succ = 0
            for rr in range(N):
                for cc in range(N):
                    other = idx(rr, cc)
                    if other != me:
                        if reach[other][me]:
                            pred += 1
                        if reach[me][other]:
                            succ += 1
            lower_chain[r][c] = pred
            upper_chain[r][c] = succ

    # Domain masks
    dom = [[full_mask for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            # chain-derived static bounds
            lo = 1 + lower_chain[r][c]
            hi = N - upper_chain[r][c]
            if lo > hi:
                return "No Solution"
            mask = ((1 << hi) - 1) ^ ((1 << (lo - 1)) - 1)
            dom[r][c] &= mask

    for r in range(N):
        for c in range(N):
            v = observation['data'][r][c]
            if v is not None:
                if not (1 <= v <= N):
                    return "No Solution"
                dom[r][c] &= bit(v)
                if dom[r][c] == 0:
                    return "No Solution"

    def is_single(mask):
        return mask != 0 and (mask & (mask - 1)) == 0

    def assign(dom, r, c, v):
        m = bit(v)
        if dom[r][c] == m:
            return True
        if not (dom[r][c] & m):
            return False
        dom[r][c] = m
        return True

    def remove_mask(dom, r, c, rem):
        newm = dom[r][c] & ~rem
        if newm == dom[r][c]:
            return True
        if newm == 0:
            return False
        dom[r][c] = newm
        return True

    def enforce_binary_ineq(dom, a, b):
        r1, c1 = a
        r2, c2 = b
        m1 = dom[r1][c1]
        m2 = dom[r2][c2]
        if m1 == 0 or m2 == 0:
            return False
        hi2 = max_val(m2)
        lo1 = min_val(m1)
        # a < b => a <= hi(b)-1 and b >= lo(a)+1
        nm1 = m1 & ((1 << (hi2 - 1)) - 1 if hi2 > 1 else 0)
        if lo1 < N:
            nm2 = m2 & ~((1 << lo1) - 1)
        else:
            nm2 = 0
        if nm1 == 0 or nm2 == 0:
            return False
        dom[r1][c1] = nm1
        dom[r2][c2] = nm2
        # exact arc consistency for small domains
        vals1 = bits_to_list(dom[r1][c1])
        vals2 = bits_to_list(dom[r2][c2])
        sup1 = 0
        sup2 = 0
        j = 0
        vals2_sorted = vals2
        for x in vals1:
            while j < len(vals2_sorted) and vals2_sorted[j] <= x:
                j += 1
            if j < len(vals2_sorted):
                sup1 |= bit(x)
        i = 0
        vals1_sorted = vals1
        for y in vals2:
            while i < len(vals1_sorted) and vals1_sorted[i] < y:
                i += 1
            if i > 0:
                sup2 |= bit(y)
        if sup1 == 0 or sup2 == 0:
            return False
        dom[r1][c1] = sup1
        dom[r2][c2] = sup2
        return True

    def all_diff_line_propagate(dom, cells):
        changed = False
        # Singles eliminate from peers
        fixed_mask = 0
        fixed_vals = []
        for r, c in cells:
            m = dom[r][c]
            if is_single(m):
                if fixed_mask & m:
                    return False, changed
                fixed_mask |= m
                fixed_vals.append(m)
        if fixed_mask:
            for r, c in cells:
                if not is_single(dom[r][c]):
                    nm = dom[r][c] & ~fixed_mask
                    if nm == 0:
                        return False, changed
                    if nm != dom[r][c]:
                        dom[r][c] = nm
                        changed = True

        # Hidden singles
        positions = [0] * (N + 1)
        counts = [0] * (N + 1)
        for idx_cell, (r, c) in enumerate(cells):
            m = dom[r][c]
            v = 1
            mm = m
            while mm:
                if mm & 1:
                    positions[v] = idx_cell
                    counts[v] += 1
                mm >>= 1
                v += 1
        for v in range(1, N + 1):
            if counts[v] == 0:
                return False, changed
            if counts[v] == 1:
                rr, cc = cells[positions[v]]
                m = bit(v)
                if dom[rr][cc] != m:
                    dom[rr][cc] = m
                    changed = True

        # Naked subsets / hidden subsets via Hall on masks present in line
        bucket = {}
        for i, (r, c) in enumerate(cells):
            m = dom[r][c]
            cnt = m.bit_count()
            if 2 <= cnt <= N - 1:
                bucket.setdefault(m, []).append(i)
        for m, idxs in bucket.items():
            k = m.bit_count()
            if len(idxs) == k:
                for j, (r, c) in enumerate(cells):
                    if j not in idxs:
                        nm = dom[r][c] & ~m
                        if nm == 0:
                            return False, changed
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True

        # Interval pruning from inequality order within a line is already partly static.
        return True, changed

    def line_feasible(dom, cells):
        # Bipartite feasibility for all-different on a line
        value_cells = [[] for _ in range(N + 1)]
        for i, (r, c) in enumerate(cells):
            vals = bits_to_list(dom[r][c])
            if not vals:
                return False
            for v in vals:
                value_cells[v].append(i)

        match_to_cell = [-1] * (N + 1)

        def dfs(cell_i, seen_vals):
            r, c = cells[cell_i]
            for v in bits_to_list(dom[r][c]):
                if seen_vals[v]:
                    continue
                seen_vals[v] = True
                if match_to_cell[v] == -1 or dfs(match_to_cell[v], seen_vals):
                    match_to_cell[v] = cell_i
                    return True
            return False

        for i in range(N):
            seen = [False] * (N + 1)
            if not dfs(i, seen):
                return False
        return True

    def propagate(dom):
        while True:
            snapshot = tuple(tuple(row) for row in dom)

            # Row/column direct all-different reasoning
            for r in range(N):
                ok, _ = all_diff_line_propagate(dom, [(r, c) for c in range(N)])
                if not ok:
                    return False
            for c in range(N):
                ok, _ = all_diff_line_propagate(dom, [(r, c) for r in range(N)])
                if not ok:
                    return False

            # Inequalities
            for a, b in less_edges:
                if not enforce_binary_ineq(dom, a, b):
                    return False

            # Re-apply all-different after inequalities
            for r in range(N):
                if not line_feasible(dom, [(r, c) for c in range(N)]):
                    return False
                ok, _ = all_diff_line_propagate(dom, [(r, c) for c in range(N)])
                if not ok:
                    return False
            for c in range(N):
                if not line_feasible(dom, [(r, c) for r in range(N)]):
                    return False
                ok, _ = all_diff_line_propagate(dom, [(r, c) for r in range(N)])
                if not ok:
                    return False

            # Global contradiction checks for inequalities
            for (r1, c1), (r2, c2) in less_edges:
                if max_val(dom[r1][c1]) >= min_val(dom[r2][c2]):
                    # This condition alone is not contradiction; exact support handles it.
                    pass
                if not enforce_binary_ineq(dom, (r1, c1), (r2, c2)):
                    return False

            if snapshot == tuple(tuple(row) for row in dom):
                return True

    def solved(dom):
        for r in range(N):
            for c in range(N):
                if not is_single(dom[r][c]):
                    return False
        return True

    def choose_cell(dom):
        best = None
        best_score = None
        for r in range(N):
            for c in range(N):
                m = dom[r][c]
                bc = m.bit_count()
                if bc > 1:
                    deg = (N - 1) * 2 + len(less_in[r][c]) + len(less_out[r][c])
                    score = (bc, -deg)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
        return best

    def value_order(dom, r, c):
        vals = bits_to_list(dom[r][c])
        # Prefer values that best satisfy nearby inequalities and row/col scarcity.
        scored = []
        row_used = 0
        col_used = 0
        for j in range(N):
            if is_single(dom[r][j]):
                row_used |= dom[r][j]
        for i in range(N):
            if is_single(dom[i][c]):
                col_used |= dom[i][c]
        used = row_used | col_used

        for v in vals:
            score = 0
            if used & bit(v):
                score += 5
            for rr, cc in less_out[r][c]:
                # current < neighbor, smaller is easier
                if dom[rr][cc] & ~((1 << v) - 1):
                    score += 0
                else:
                    score += 10
            for rr, cc in less_in[r][c]:
                # neighbor < current, larger is easier
                if v > 1 and (dom[rr][cc] & ((1 << (v - 1)) - 1)):
                    score += 0
                else:
                    score += 10
            score += abs(v - (N + 1) / 2) * 0.01
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def clone_dom(dom):
        return [row[:] for row in dom]

    def search(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        r, c = choose_cell(dom)
        for v in value_order(dom, r, c):
            nd = clone_dom(dom)
            if not assign(nd, r, c, v):
                continue
            res = search(nd)
            if res is not None:
                return res

        # Optional contradiction-driven elimination at this node:
        # if all assignments fail, caller handles backtracking.
        return None

    result = search(dom)
    if result is None:
        return "No Solution"

    grid = [[min_val(result[r][c]) for c in range(N)] for r in range(N)]
    return str(grid)


