    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None]], 'horizontal': {'(0,0.5)': '>', '(0,3.5)': '<', '(1,0.5)': '<', '(1,2.5)': '<', '(3,1.5)': '<', '(3,2.5)': '>', '(4,1.5)': '<'}, 'vertical': {'(1.5,0)': 'v', '(2.5,2)': 'v'}}

# General Futoshiki solver with strong propagation and MRV-guided search.
# Symbols are interpreted exactly as requested:
# horizontal at (r, c+0.5): '<' or '>'
#   '<' means cell(r,c) < cell(r,c+1)
#   '>' means cell(r,c) > cell(r,c+1)
# vertical at (r+0.5, c): '^' or 'v'
#   '^' means cell(r,c) < cell(r+1,c)
#   'v' means cell(r,c) > cell(r+1,c)

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    def val_to_mask(v):
        return 1 << (v - 1)

    def mask_to_vals(mask):
        vals = []
        v = 1
        while mask:
            if mask & 1:
                vals.append(v)
            mask >>= 1
            v += 1
        return vals

    def bit_count(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def single_value(mask):
        return mask.bit_length()

    # Parse inequalities into directed comparisons a < b
    less_edges = []
    for k, sym in observation['horizontal'].items():
        r, c = ast_tuple(k)
        r = int(r)
        c = float(c)
        left_c = int(c - 0.5)
        a = idx(r, left_c, n)
        b = idx(r, left_c + 1, n)
        if sym == '<':
            less_edges.append((a, b))
        elif sym == '>':
            less_edges.append((b, a))
        else:
            return "No Solution"

    for k, sym in observation['vertical'].items():
        r, c = ast_tuple(k)
        r = float(r)
        c = int(c)
        top_r = int(r - 0.5)
        a = idx(top_r, c, n)
        b = idx(top_r + 1, c, n)
        if sym == '^':
            less_edges.append((a, b))
        elif sym == 'v':
            less_edges.append((b, a))
        else:
            return "No Solution"

    # Neighbor structures
    row_cells = [[idx(r, c, n) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c, n) for r in range(n)] for c in range(n)]
    units_of = [[] for _ in range(n * n)]
    peers = [set() for _ in range(n * n)]

    for r in range(n):
        unit = row_cells[r]
        for cell in unit:
            units_of[cell].append(unit)
            peers[cell].update(x for x in unit if x != cell)

    for c in range(n):
        unit = col_cells[c]
        for cell in unit:
            units_of[cell].append(unit)
            peers[cell].update(x for x in unit if x != cell)

    less_from = [[] for _ in range(n * n)]
    greater_from = [[] for _ in range(n * n)]
    for a, b in less_edges:
        less_from[a].append(b)
        greater_from[b].append(a)

    # Initial domains
    domains = [full_mask] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[idx(r, c, n)] = val_to_mask(v)

    # Topological-like depth bounds from inequalities only
    # If x has k strict predecessors in a chain, x >= 1+k
    # If x has k strict successors in a chain, x <= n-k
    lower_rank = longest_path_predecessors(n, less_edges)
    upper_rank = longest_path_successors(n, less_edges)
    if lower_rank is None or upper_rank is None:
        return "No Solution"

    for i in range(n * n):
        lo = 1 + lower_rank[i]
        hi = n - upper_rank[i]
        if lo > hi:
            return "No Solution"
        allowed = range_mask(lo, hi)
        domains[i] &= allowed
        if domains[i] == 0:
            return "No Solution"

    # Main propagation
    if not propagate(domains, n, peers, row_cells, col_cells, less_from, greater_from):
        return "No Solution"

    solved = search(domains, n, peers, row_cells, col_cells, less_from, greater_from)
    if solved is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(solved[idx(r, c, n)]))
        grid.append(row)
    return str(grid)

def idx(r, c, n):
    return r * n + c

def ast_tuple(s):
    s = s.strip()
    if not (s.startswith('(') and s.endswith(')')):
        raise ValueError("Bad coordinate")
    a, b = s[1:-1].split(',')
    return float(a.strip()), float(b.strip())

def range_mask(lo, hi):
    if lo > hi:
        return 0
    return ((1 << hi) - 1) ^ ((1 << (lo - 1)) - 1)

def longest_path_predecessors(n, less_edges):
    m = n * n
    incoming = [[] for _ in range(m)]
    outgoing = [[] for _ in range(m)]
    indeg = [0] * m
    for a, b in less_edges:
        outgoing[a].append(b)
        incoming[b].append(a)
        indeg[b] += 1
    q = deque([i for i in range(m) if indeg[i] == 0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in outgoing[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    if len(topo) != m:
        return None
    dist = [0] * m
    for u in topo:
        best = 0
        for p in incoming[u]:
            cand = dist[p] + 1
            if cand > best:
                best = cand
        dist[u] = best
    return dist

def longest_path_successors(n, less_edges):
    m = n * n
    outgoing = [[] for _ in range(m)]
    indeg = [0] * m
    rev_incoming = [[] for _ in range(m)]
    for a, b in less_edges:
        outgoing[a].append(b)
        rev_incoming[a].append(b)
        indeg[b] += 1
    q = deque([i for i in range(m) if indeg[i] == 0])
    topo = []
    indeg2 = indeg[:]
    while q:
        u = q.popleft()
        topo.append(u)
        for v in outgoing[u]:
            indeg2[v] -= 1
            if indeg2[v] == 0:
                q.append(v)
    if len(topo) != m:
        return None
    dist = [0] * m
    for u in reversed(topo):
        best = 0
        for v in outgoing[u]:
            cand = dist[v] + 1
            if cand > best:
                best = cand
        dist[u] = best
    return dist

def propagate(domains, n, peers, row_cells, col_cells, less_from, greater_from):
    q = deque(range(n * n))
    in_q = [True] * (n * n)

    while q:
        cell = q.popleft()
        in_q[cell] = False
        old = domains[cell]
        new = old

        # Inequality filtering using current neighbor min/max
        for b in less_from[cell]:
            mb = domains[b]
            if mb == 0:
                return False
            max_b = mb.bit_length()
            new &= ((1 << (max_b - 1)) - 1) if max_b > 1 else 0
        for a in greater_from[cell]:
            ma = domains[a]
            if ma == 0:
                return False
            min_a = (ma & -ma).bit_length()
            new &= ~((1 << min_a) - 1)

        if new == 0:
            return False
        if new != old:
            domains[cell] = new
            for p in peers[cell]:
                if not in_q[p]:
                    q.append(p)
                    in_q[p] = True
            for p in less_from[cell]:
                if not in_q[p]:
                    q.append(p)
                    in_q[p] = True
            for p in greater_from[cell]:
                if not in_q[p]:
                    q.append(p)
                    in_q[p] = True

        # If singleton, remove from row/col peers
        m = domains[cell]
        if m and (m & (m - 1)) == 0:
            for p in peers[cell]:
                pm = domains[p]
                nm = pm & ~m
                if nm != pm:
                    if nm == 0:
                        return False
                    domains[p] = nm
                    if not in_q[p]:
                        q.append(p)
                        in_q[p] = True

        # Hidden singles and Hall-like subset checks on impacted units are cheap for small n
        r = cell // n
        c = cell % n
        if not process_unit(row_cells[r], domains, q, in_q):
            return False
        if not process_unit(col_cells[c], domains, q, in_q):
            return False

    # Final all-different sanity
    for unit in row_cells + col_cells:
        seen = 0
        for c in unit:
            m = domains[c]
            if m == 0:
                return False
            if (m & (m - 1)) == 0:
                if seen & m:
                    return False
                seen |= m
        union = 0
        for c in unit:
            union |= domains[c]
        if union != (1 << n) - 1:
            return False

    # Final inequality sanity
    for a in range(n * n):
        ma = domains[a]
        if ma == 0:
            return False
        min_a = (ma & -ma).bit_length()
        max_a = ma.bit_length()
        for b in less_from[a]:
            mb = domains[b]
            if mb == 0:
                return False
            min_b = (mb & -mb).bit_length()
            max_b = mb.bit_length()
            if not (min_a < max_b and max_a > min_b or max_a < min_b or min_a < max_b):
                pass
            if max_a >= min_b and not exists_less_pair(ma, mb):
                return False
    return True

def process_unit(unit, domains, q, in_q):
    n = len(unit)
    # Hidden single
    for v in range(1, n + 1):
        bit = 1 << (v - 1)
        spots = []
        for c in unit:
            if domains[c] & bit:
                spots.append(c)
        if not spots:
            return False
        if len(spots) == 1:
            c = spots[0]
            if domains[c] != bit:
                domains[c] = bit
                if not in_q[c]:
                    q.append(c)
                    in_q[c] = True

    # Naked subsets via exact repeated masks
    counts = {}
    for c in unit:
        m = domains[c]
        bc = m.bit_count()
        if 1 < bc <= n - 1:
            counts[m] = counts.get(m, 0) + 1
    for m, k in counts.items():
        if m.bit_count() == k:
            for c in unit:
                if domains[c] != m:
                    nm = domains[c] & ~m
                    if nm != domains[c]:
                        if nm == 0:
                            return False
                        domains[c] = nm
                        if not in_q[c]:
                            q.append(c)
                            in_q[c] = True

    # Hall subset check over value subsets for small n
    # For n=5 this is very effective and still tiny.
    value_masks = []
    for c in unit:
        value_masks.append(domains[c])
    all_values = (1 << n) - 1
    sub = all_values
    while sub:
        k = sub.bit_count()
        if 2 <= k <= n - 1:
            cells = [c for c in unit if domains[c] & sub]
            forced = [c for c in cells if domains[c] & ~sub == 0]
            if len(cells) < k:
                return False
            if len(forced) == k:
                for c in unit:
                    if c not in forced:
                        nm = domains[c] & ~sub
                        if nm != domains[c]:
                            if nm == 0:
                                return False
                            domains[c] = nm
                            if not in_q[c]:
                                q.append(c)
                                in_q[c] = True
        sub = (sub - 1) & all_values
    return True

def exists_less_pair(ma, mb):
    # Whether there exists a in A and b in B with a < b
    if ma == 0 or mb == 0:
        return False
    max_b = mb.bit_length()
    if max_b <= 1:
        return False
    return (ma & ((1 << (max_b - 1)) - 1)) != 0

def search(domains, n, peers, row_cells, col_cells, less_from, greater_from):
    # Solved?
    unsolved = [i for i, m in enumerate(domains) if m & (m - 1)]
    if not unsolved:
        return domains

    # MRV + degree heuristic
    best = None
    best_key = None
    for i in unsolved:
        m = domains[i]
        key = (m.bit_count(), -(len(peers[i]) + len(less_from[i]) + len(greater_from[i])))
        if best_key is None or key < best_key:
            best_key = key
            best = i

    # Least-constraining value ordering
    vals = values_lcv(best, domains, peers, less_from, greater_from)
    for v in vals:
        new_domains = domains[:]
        new_domains[best] = 1 << (v - 1)
        if propagate(new_domains, n, peers, row_cells, col_cells, less_from, greater_from):
            ans = search(new_domains, n, peers, row_cells, col_cells, less_from, greater_from)
            if ans is not None:
                return ans
    return None

def values_lcv(cell, domains, peers, less_from, greater_from):
    m = domains[cell]
    vals = []
    bits = m
    while bits:
        b = bits & -bits
        v = b.bit_length()
        score = 0
        for p in peers[cell]:
            if domains[p] & b:
                score += 1
        for nb in less_from[cell]:
            # cell < nb, assigning larger v constrains nb more
            score += count_leq(domains[nb], v)
        for na in greater_from[cell]:
            # na < cell, assigning smaller v constrains na more
            score += count_geq(domains[na], v)
        vals.append((score, v))
        bits ^= b
    vals.sort()
    return [v for _, v in vals]

def count_leq(mask, v):
    return (mask & ((1 << v) - 1)).bit_count()

def count_geq(mask, v):
    return (mask & ~((1 << (v - 1)) - 1)).bit_count()

