# General Binairo/Takuzu-style solver with adjacent equality/inequality constraints.
# Returns solved grid as list of lists using 'B'/'W', or "No Solution".

from copy import deepcopy

B, W = 1, 0
CH = {B: 'B', W: 'W'}

def parse_coord_key(key):
    a, b = key.strip()[1:-1].split(',')
    a = a.strip()
    b = b.strip()
    return float(a) if '.' in a else int(a), float(b) if '.' in b else int(b)

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0])
    if n != m or n % 2 != 0:
        return "No Solution"

    target = n // 2
    board = [[None] * n for _ in range(n)]

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                board[r][c] = B
            elif v == 'W':
                board[r][c] = W

    h_cons = {}
    for k, v in observation.get('horizontal', {}).items():
        r, x = parse_coord_key(k)
        r = int(r)
        c = int(x - 0.5)
        if 0 <= r < n and 0 <= c < n - 1:
            h_cons[(r, c, r, c + 1)] = (v == '=')

    v_cons = {}
    for k, v in observation.get('vertical', {}).items():
        x, c = parse_coord_key(k)
        r = int(x - 0.5)
        c = int(c)
        if 0 <= r < n - 1 and 0 <= c < n:
            v_cons[(r, c, r + 1, c)] = (v == '=')

    neighbors = {}
    for (r1, c1, r2, c2), same in list(h_cons.items()) + list(v_cons.items()):
        neighbors.setdefault((r1, c1), []).append((r2, c2, same))
        neighbors.setdefault((r2, c2), []).append((r1, c1, same))

    all_patterns = generate_valid_patterns(n, target)

    row_allowed = [filter_patterns_by_fixed(all_patterns, board[r]) for r in range(n)]
    col_allowed = [filter_patterns_by_fixed(all_patterns, [board[r][c] for r in range(n)]) for c in range(n)]

    if any(not s for s in row_allowed) or any(not s for s in col_allowed):
        return "No Solution"

    state = {
        'board': board,
        'row_allowed': row_allowed,
        'col_allowed': col_allowed,
    }

    state = propagate(state, neighbors)
    if state is None:
        return "No Solution"

    if is_solved(state['board']):
        return [[CH[state['board'][r][c]] for c in range(n)] for r in range(n)]

    result = search(state, neighbors)
    if result is None:
        return "No Solution"
    return [[CH[result['board'][r][c]] for c in range(n)] for r in range(n)]

def generate_valid_patterns(n, target):
    res = []
    def rec(pos, arr, count1):
        if count1 > target:
            return
        if pos - count1 > target:
            return
        if pos >= 2 and arr[pos - 1] == arr[pos - 2]:
            for v in (0, 1):
                if v == arr[pos - 1]:
                    continue
        if pos == n:
            if count1 == target:
                res.append(tuple(arr))
            return
        for v in (W, B):
            if pos >= 2 and arr[pos - 1] == arr[pos - 2] == v:
                continue
            arr.append(v)
            rec(pos + 1, arr, count1 + (1 if v == B else 0))
            arr.pop()
    rec(0, [], 0)
    return res

def filter_patterns_by_fixed(patterns, fixed_line):
    out = set()
    for p in patterns:
        ok = True
        for i, v in enumerate(fixed_line):
            if v is not None and p[i] != v:
                ok = False
                break
        if ok:
            out.add(p)
    return out

def is_solved(board):
    for row in board:
        for v in row:
            if v is None:
                return False
    return True

def propagate(state, neighbors):
    n = len(state['board'])
    changed = True
    while changed:
        changed = False

        # Enforce row/col pattern sets against current board.
        for r in range(n):
            newset = {p for p in state['row_allowed'][r] if line_matches_board_row(state['board'], r, p)}
            if not newset:
                return None
            if newset != state['row_allowed'][r]:
                state['row_allowed'][r] = newset
                changed = True

        for c in range(n):
            newset = {p for p in state['col_allowed'][c] if line_matches_board_col(state['board'], c, p)}
            if not newset:
                return None
            if newset != state['col_allowed'][c]:
                state['col_allowed'][c] = newset
                changed = True

        # Derive forced cell values from row/col domains intersection.
        for r in range(n):
            forced = common_values(state['row_allowed'][r])
            if forced:
                for c, v in forced.items():
                    if not assign_cell(state, r, c, v):
                        return None
                    changed = True

        for c in range(n):
            forced = common_values(state['col_allowed'][c])
            if forced:
                for r, v in forced.items():
                    if not assign_cell(state, r, c, v):
                        return None
                    changed = True

        # Human-like local deductions: adjacency constraints, no-three, counts.
        for r in range(n):
            for c in range(n):
                v = state['board'][r][c]
                if v is None:
                    poss = possible_values_from_domains(state, r, c)
                    if not poss:
                        return None
                    # Neighbor relation propagation
                    if (r, c) in neighbors:
                        poss2 = set(poss)
                        for nr, nc, same in neighbors[(r, c)]:
                            nv = state['board'][nr][nc]
                            if nv is not None:
                                needed = nv if same else 1 - nv
                                if needed in poss2:
                                    poss2 = {needed}
                                else:
                                    return None
                        poss = poss2
                    # No-three pattern local restriction
                    poss = poss & local_possible_no_three(state['board'], r, c)
                    if not poss:
                        return None
                    # Count restriction local
                    poss = poss & local_possible_counts(state['board'], r, c)
                    if not poss:
                        return None
                    if len(poss) == 1:
                        if not assign_cell(state, r, c, next(iter(poss))):
                            return None
                        changed = True
                else:
                    # Verify neighbor constraints immediately
                    if (r, c) in neighbors:
                        for nr, nc, same in neighbors[(r, c)]:
                            nv = state['board'][nr][nc]
                            if nv is not None:
                                if same and nv != v:
                                    return None
                                if (not same) and nv == v:
                                    return None

        # Uniqueness pruning for completed rows/cols and domain-level duplicate prevention.
        if not enforce_uniqueness(state):
            return None

    return state

def line_matches_board_row(board, r, p):
    for c, v in enumerate(board[r]):
        if v is not None and p[c] != v:
            return False
    return True

def line_matches_board_col(board, c, p):
    for r in range(len(board)):
        v = board[r][c]
        if v is not None and p[r] != v:
            return False
    return True

def common_values(patterns):
    if not patterns:
        return {}
    patterns = list(patterns)
    n = len(patterns[0])
    out = {}
    for i in range(n):
        v = patterns[0][i]
        same = True
        for p in patterns[1:]:
            if p[i] != v:
                same = False
                break
        if same:
            out[i] = v
    return out

def possible_values_from_domains(state, r, c):
    rp = {p[c] for p in state['row_allowed'][r]}
    cp = {p[r] for p in state['col_allowed'][c]}
    return rp & cp

def local_possible_no_three(board, r, c):
    n = len(board)
    poss = {W, B}
    for v in (W, B):
        # horizontal windows
        for a, b in ((c - 2, c - 1), (c - 1, c + 1), (c + 1, c + 2)):
            if 0 <= a < n and 0 <= b < n:
                va = board[r][a]
                vb = board[r][b]
                if va is not None and vb is not None and va == vb == v:
                    poss.discard(v)
        # vertical windows
        for a, b in ((r - 2, r - 1), (r - 1, r + 1), (r + 1, r + 2)):
            if 0 <= a < n and 0 <= b < n:
                va = board[a][c]
                vb = board[b][c]
                if va is not None and vb is not None and va == vb == v:
                    poss.discard(v)
    return poss

def local_possible_counts(board, r, c):
    n = len(board)
    target = n // 2
    poss = {W, B}
    row = board[r]
    col = [board[i][c] for i in range(n)]

    bcount = sum(v == B for v in row if v is not None)
    wcount = sum(v == W for v in row if v is not None)
    if bcount >= target:
        poss.discard(B)
    if wcount >= target:
        poss.discard(W)

    bcount = sum(v == B for v in col if v is not None)
    wcount = sum(v == W for v in col if v is not None)
    if bcount >= target:
        poss.discard(B)
    if wcount >= target:
        poss.discard(W)
    return poss

def assign_cell(state, r, c, v):
    cur = state['board'][r][c]
    if cur is not None:
        return cur == v
    state['board'][r][c] = v
    rowset = {p for p in state['row_allowed'][r] if p[c] == v}
    if not rowset:
        return False
    colset = {p for p in state['col_allowed'][c] if p[r] == v}
    if not colset:
        return False
    state['row_allowed'][r] = rowset
    state['col_allowed'][c] = colset
    return True

def enforce_uniqueness(state):
    n = len(state['board'])

    # Completed rows/cols must be unique.
    seen_rows = {}
    for r in range(n):
        if None not in state['board'][r]:
            t = tuple(state['board'][r])
            if t in seen_rows:
                return False
            seen_rows[t] = r

    seen_cols = {}
    for c in range(n):
        col = tuple(state['board'][r][c] for r in range(n))
        if None not in col:
            if col in seen_cols:
                return False
            seen_cols[col] = c

    # If a row is completed, no other row domain may equal exactly that pattern as sole option causing duplicate.
    completed_rows = {tuple(state['board'][r]): r for r in range(n) if None not in state['board'][r]}
    for pat, rr in completed_rows.items():
        for r in range(n):
            if r != rr and pat in state['row_allowed'][r] and len(state['row_allowed'][r]) == 1:
                return False
            if r != rr and pat in state['row_allowed'][r] and None in state['board'][r]:
                state['row_allowed'][r].discard(pat)
                if not state['row_allowed'][r]:
                    return False

    completed_cols = {}
    for c in range(n):
        col = tuple(state['board'][r][c] for r in range(n))
        if None not in col:
            completed_cols[col] = c
    for pat, cc in completed_cols.items():
        for c in range(n):
            if c != cc and pat in state['col_allowed'][c] and len(state['col_allowed'][c]) == 1:
                return False
            if c != cc and pat in state['col_allowed'][c] and any(state['board'][r][c] is None for r in range(n)):
                state['col_allowed'][c].discard(pat)
                if not state['col_allowed'][c]:
                    return False
    return True

def search(state, neighbors):
    if is_solved(state['board']):
        return state if enforce_uniqueness(state) else None

    n = len(state['board'])
    best = None

    # Choose most constrained unresolved cell.
    for r in range(n):
        for c in range(n):
            if state['board'][r][c] is None:
                poss = possible_values_from_domains(state, r, c)
                if (r, c) in neighbors:
                    for nr, nc, same in neighbors[(r, c)]:
                        nv = state['board'][nr][nc]
                        if nv is not None:
                            need = nv if same else 1 - nv
                            poss &= {need}
                poss &= local_possible_no_three(state['board'], r, c)
                poss &= local_possible_counts(state['board'], r, c)
                if not poss:
                    return None
                score = len(poss)
                score2 = len(state['row_allowed'][r]) + len(state['col_allowed'][c])
                item = (score, score2, r, c, tuple(sorted(poss)))
                if best is None or item < best:
                    best = item

    if best is None:
        return state if is_solved(state['board']) else None

    _, _, r, c, poss = best
    for v in poss:
        nxt = {
            'board': [row[:] for row in state['board']],
            'row_allowed': [set(s) for s in state['row_allowed']],
            'col_allowed': [set(s) for s in state['col_allowed']],
        }
        if not assign_cell(nxt, r, c, v):
            continue
        nxt = propagate(nxt, neighbors)
        if nxt is None:
            continue
        res = search(nxt, neighbors)
        if res is not None:
            return res
    return None

if __name__ == "__main__":
    print(solve(OBSERVATION))

