# General Futoshiki solver using bitset domains, human-like propagation, and tightly pruned search.
# It accepts the observation format specified in the prompt and returns the solved grid as a 2D list
# or "No Solution".

ALL_MASK_CACHE = {}


def bit_count(x):
    return x.bit_count()


def lowbit_index(x):
    return (x & -x).bit_length() - 1


def mask_to_values(mask, n):
    vals = []
    while mask:
        b = mask & -mask
        vals.append(b.bit_length())
        mask ^= b
    return vals


def get_all_mask(n):
    m = ALL_MASK_CACHE.get(n)
    if m is None:
        m = (1 << n) - 1
        ALL_MASK_CACHE[n] = m
    return m


def parse_constraints(observation):
    n = len(observation['data'])
    horiz = {}
    vert = {}

    for k, sym in observation.get('horizontal', {}).items():
        r, c = eval(k, {"__builtins__": None}, {})
        left = (int(r), int(c - 0.5))
        right = (int(r), int(c + 0.5))
        horiz[(left[0], left[1])] = (right[0], right[1], sym)

    for k, sym in observation.get('vertical', {}).items():
        r, c = eval(k, {"__builtins__": None}, {})
        top = (int(r - 0.5), int(c))
        bottom = (int(r + 0.5), int(c))
        vert[(top[0], top[1])] = (bottom[0], bottom[1], sym)

    # Build directed less-than edges a < b
    less_edges = {}
    greater_edges = {}
    for r in range(n):
        for c in range(n):
            less_edges[(r, c)] = []
            greater_edges[(r, c)] = []

    for (r, c), (rr, cc, sym) in horiz.items():
        a = (r, c)
        b = (rr, cc)
        if sym == '<':
            less_edges[a].append(b)
            greater_edges[b].append(a)
        else:
            less_edges[b].append(a)
            greater_edges[a].append(b)

    for (r, c), (rr, cc, sym) in vert.items():
        a = (r, c)   # top
        b = (rr, cc) # bottom
        if sym == '^':
            # top > bottom
            less_edges[b].append(a)
            greater_edges[a].append(b)
        else:
            # top < bottom
            less_edges[a].append(b)
            greater_edges[b].append(a)

    return less_edges, greater_edges


def build_peers(n):
    peers = {}
    row_cells = []
    col_cells = []

    for r in range(n):
        row = [(r, c) for c in range(n)]
        row_cells.append(row)
    for c in range(n):
        col = [(r, c) for r in range(n)]
        col_cells.append(col)

    for r in range(n):
        for c in range(n):
            s = set(row_cells[r] + col_cells[c])
            s.remove((r, c))
            peers[(r, c)] = tuple(s)
    return peers, row_cells, col_cells


def min_value(mask):
    return lowbit_index(mask) + 1


def max_value(mask):
    return mask.bit_length()


def remove_values_lt(mask, k):
    if k <= 1:
        return mask
    return mask & ~((1 << (k - 1)) - 1)


def remove_values_gt(mask, k, n):
    if k >= n:
        return mask
    return mask & ((1 << k) - 1)


def enforce_ineq_pair(mask_a, mask_b, relation, n):
    # relation: '<' means A < B, '>' means A > B
    if relation == '<':
        # A <= max(B)-1, B >= min(A)+1
        new_a = remove_values_gt(mask_a, max_value(mask_b) - 1, n) if mask_b else 0
        new_b = remove_values_lt(mask_b, min_value(new_a) + 1 if new_a else n + 1)
    else:
        # A > B  <=> B < A
        new_b = remove_values_gt(mask_b, max_value(mask_a) - 1, n) if mask_a else 0
        new_a = remove_values_lt(mask_a, min_value(new_b) + 1 if new_b else n + 1)
    return new_a, new_b


def assign(domains, cell, value_mask, queue):
    old = domains[cell]
    new = old & value_mask
    if new == 0:
        return False
    if new != old:
        domains[cell] = new
        queue.append(cell)
    return True


def propagate(domains, n, peers, row_cells, col_cells, less_edges, greater_edges):
    queue = [cell for cell, mask in domains.items() if bit_count(mask) == 1]

    # Include all cells initially for stronger first-pass propagation.
    queue.extend(cell for cell in domains if bit_count(domains[cell]) > 1)

    in_queue = set(queue)
    all_mask = get_all_mask(n)

    while queue:
        cell = queue.pop()
        in_queue.discard(cell)
        mask = domains[cell]
        if mask == 0:
            return False

        r, c = cell

        # If singleton, remove from row/column peers.
        if bit_count(mask) == 1:
            inv = all_mask ^ mask
            for p in peers[cell]:
                pm = domains[p]
                nm = pm & inv
                if nm == 0:
                    return False
                if nm != pm:
                    domains[p] = nm
                    if p not in in_queue:
                        queue.append(p)
                        in_queue.add(p)

        # Inequality propagation: cell < neighbor
        a_mask = domains[cell]
        for nb in less_edges[cell]:
            b_mask = domains[nb]
            # cell < nb
            new_a = remove_values_gt(a_mask, max_value(b_mask) - 1, n) if b_mask else 0
            if new_a == 0:
                return False
            new_b = remove_values_lt(b_mask, min_value(new_a) + 1)
            if new_b == 0:
                return False
            if new_a != a_mask:
                domains[cell] = new_a
                a_mask = new_a
                if cell not in in_queue:
                    queue.append(cell)
                    in_queue.add(cell)
            if new_b != b_mask:
                domains[nb] = new_b
                if nb not in in_queue:
                    queue.append(nb)
                    in_queue.add(nb)

        # Inequality propagation: greater neighbors g with g < cell
        a_mask = domains[cell]
        for g in greater_edges[cell]:
            g_mask = domains[g]
            # g < cell
            new_g = remove_values_gt(g_mask, max_value(a_mask) - 1, n) if a_mask else 0
            if new_g == 0:
                return False
            new_a = remove_values_lt(a_mask, min_value(new_g) + 1)
            if new_a == 0:
                return False
            if new_g != g_mask:
                domains[g] = new_g
                if g not in in_queue:
                    queue.append(g)
                    in_queue.add(g)
            if new_a != a_mask:
                domains[cell] = new_a
                a_mask = new_a
                if cell not in in_queue:
                    queue.append(cell)
                    in_queue.add(cell)

        # Hidden singles in row and column.
        for unit in (row_cells[r], col_cells[c]):
            counts = [0] * n
            last_cell = [None] * n
            union = 0
            for u in unit:
                um = domains[u]
                if um == 0:
                    return False
                union |= um
                x = um
                while x:
                    b = x & -x
                    idx = b.bit_length() - 1
                    counts[idx] += 1
                    last_cell[idx] = u
                    x ^= b
            if union != all_mask:
                return False
            for idx in range(n):
                if counts[idx] == 0:
                    return False
                if counts[idx] == 1:
                    target = last_cell[idx]
                    val_mask = 1 << idx
                    tm = domains[target]
                    if tm != val_mask:
                        domains[target] = val_mask
                        if target not in in_queue:
                            queue.append(target)
                            in_queue.add(target)

            # Naked subsets by identical masks.
            mask_buckets = {}
            for u in unit:
                um = domains[u]
                bc = bit_count(um)
                if 2 <= bc <= n - 1:
                    mask_buckets.setdefault(um, []).append(u)
            for m, cells in mask_buckets.items():
                bc = bit_count(m)
                if len(cells) == bc:
                    for u in unit:
                        if u not in cells:
                            um = domains[u]
                            nm = um & ~m
                            if nm == 0:
                                return False
                            if nm != um:
                                domains[u] = nm
                                if u not in in_queue:
                                    queue.append(u)
                                    in_queue.add(u)

    return True


def is_solved(domains):
    return all(bit_count(m) == 1 for m in domains.values())


def domains_to_grid(domains, n):
    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(lowbit_index(domains[(r, c)]) + 1)
        grid.append(row)
    return grid


def choose_branch_cell(domains, n, less_edges, greater_edges):
    # MRV + degree + inequality pressure
    best = None
    best_key = None
    for cell, mask in domains.items():
        bc = bit_count(mask)
        if bc <= 1:
            continue
        deg = len(less_edges[cell]) + len(greater_edges[cell])
        spread = max_value(mask) - min_value(mask)
        key = (bc, -deg, spread)
        if best_key is None or key < best_key:
            best_key = key
            best = cell
    return best


def ordered_values(mask, cell, domains, peers, less_edges, greater_edges, n):
    vals = mask_to_values(mask, n)

    # Least-constraining-value style ordering, but computed cheaply.
    scored = []
    for v in vals:
        score = 0

        for p in peers[cell]:
            pm = domains[p]
            if pm & (1 << (v - 1)):
                score += 1

        for nb in less_edges[cell]:
            # cell < nb, larger v is more constraining
            nbm = domains[nb]
            score += bit_count(remove_values_lt(nbm, v + 1))
        for g in greater_edges[cell]:
            # g < cell, smaller v is more constraining
            gm = domains[g]
            score += bit_count(remove_values_gt(gm, v - 1, n)) if v > 1 else bit_count(gm)

        scored.append((score, v))

    scored.sort()
    return [v for _, v in scored]


def search(domains, n, peers, row_cells, col_cells, less_edges, greater_edges):
    if not propagate(domains, n, peers, row_cells, col_cells, less_edges, greater_edges):
        return None
    if is_solved(domains):
        return domains

    cell = choose_branch_cell(domains, n, less_edges, greater_edges)
    mask = domains[cell]

    for v in ordered_values(mask, cell, domains, peers, less_edges, greater_edges, n):
        new_domains = domains.copy()
        new_domains[cell] = 1 << (v - 1)
        result = search(new_domains, n, peers, row_cells, col_cells, less_edges, greater_edges)
        if result is not None:
            return result
    return None


def solve(observation):
    data = observation['data']
    n = len(data)
    all_mask = get_all_mask(n)

    peers, row_cells, col_cells = build_peers(n)
    less_edges, greater_edges = parse_constraints(observation)

    domains = {}
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                domains[(r, c)] = all_mask
            else:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[(r, c)] = 1 << (v - 1)

    result = search(domains, n, peers, row_cells, col_cells, less_edges, greater_edges)
    if result is None:
        return "No Solution"
    return domains_to_grid(result, n)


if __name__ == "__main__":
    print(solve(OBSERVATION))

