# Generalized Futoshiki solver using strong constraint propagation plus guided search.
# Symbols are interpreted as:
# Horizontal at (r, c+0.5): '<' means cell(r,c) < cell(r,c+1), '>' means cell(r,c) > cell(r,c+1)
# Vertical at (r+0.5, c): '^' means cell(r,c) < cell(r+1,c), 'v' means cell(r,c) > cell(r+1,c)

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    # Precompute value-bit helpers for 1..n
    VAL_TO_BIT = [0] + [1 << (v - 1) for v in range(1, n + 1)]
    BIT_TO_VAL = {1 << (v - 1): v for v in range(1, n + 1)}

    def bit_count(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    # Build inequality graph as directed edges smaller -> larger
    less_than = []
    greater_than = []

    for r in range(n):
        for c in range(n):
            less_than.append([])
            greater_than.append([])

    def idx(r, c):
        return r * n + c

    def add_lt(a_r, a_c, b_r, b_c):
        a = idx(a_r, a_c)
        b = idx(b_r, b_c)
        less_than[a].append(b)
        greater_than[b].append(a)

    for k, sym in observation.get('horizontal', {}).items():
        r_str, chalf_str = k.strip('()').split(',')
        r = int(float(r_str))
        chalf = float(chalf_str)
        c = int(chalf - 0.5)
        if sym == '<':
            add_lt(r, c, r, c + 1)
        else:
            add_lt(r, c + 1, r, c)

    for k, sym in observation.get('vertical', {}).items():
        rhalf_str, c_str = k.strip('()').split(',')
        rhalf = float(rhalf_str)
        c = int(float(c_str))
        r = int(rhalf - 0.5)
        if sym == '^':
            add_lt(r, c, r + 1, c)
        else:
            add_lt(r + 1, c, r, c)

    # Domains as bitmasks
    domains = [full_mask] * (n * n)
    row_used = [0] * n
    col_used = [0] * n

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                b = VAL_TO_BIT[v]
                if row_used[r] & b or col_used[c] & b:
                    return "No Solution"
                row_used[r] |= b
                col_used[c] |= b
                domains[idx(r, c)] = b

    row_cells = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c) for r in range(n)] for c in range(n)]

    # Topological longest-chain bounds from inequalities:
    # if x has k predecessors in a chain, x >= 1+k ; if x has k successors, x <= n-k
    def topo_bounds():
        indeg = [len(greater_than[i]) for i in range(n * n)]
        q = deque(i for i in range(n * n) if indeg[i] == 0)
        low_rank = [1] * (n * n)
        seen = 0
        while q:
            u = q.popleft()
            seen += 1
            base = low_rank[u] + 1
            for v in less_than[u]:
                if low_rank[v] < base:
                    low_rank[v] = base
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        if seen != n * n:
            return None, None

        outdeg = [len(less_than[i]) for i in range(n * n)]
        q = deque(i for i in range(n * n) if outdeg[i] == 0)
        high_rank = [n] * (n * n)
        seen = 0
        while q:
            u = q.popleft()
            seen += 1
            base = high_rank[u] - 1
            for v in greater_than[u]:
                if high_rank[v] > base:
                    high_rank[v] = base
                outdeg[v] -= 1
                if outdeg[v] == 0:
                    q.append(v)
        if seen != n * n:
            return None, None

        return low_rank, high_rank

    low_rank, high_rank = topo_bounds()
    if low_rank is None:
        return "No Solution"

    for i in range(n * n):
        lo = low_rank[i]
        hi = high_rank[i]
        mask = 0
        for v in range(lo, hi + 1):
            mask |= VAL_TO_BIT[v]
        domains[i] &= mask
        if domains[i] == 0:
            return "No Solution"

    def assign(domains, row_used, col_used, i, bit, queue):
        r, c = divmod(i, n)
        cur = domains[i]
        if cur == bit:
            return True
        if not (cur & bit):
            return False
        if (row_used[r] & bit and cur != bit) or (col_used[c] & bit and cur != bit):
            return False
        domains[i] = bit
        row_used[r] |= bit
        col_used[c] |= bit
        queue.append(i)
        return True

    def remove_bits(domains, row_used, col_used, i, rem, queue):
        cur = domains[i]
        new = cur & ~rem
        if new == cur:
            return True
        if new == 0:
            return False
        if cur != new:
            domains[i] = new
            queue.append(i)
        return True

    def propagate(domains, row_used, col_used):
        queue = deque(i for i in range(n * n) if bit_count(domains[i]) == 1)

        # Initial row/col used elimination
        for r in range(n):
            used = row_used[r]
            if used:
                for c in range(n):
                    i = idx(r, c)
                    if bit_count(domains[i]) > 1:
                        new = domains[i] & ~used
                        if new != domains[i]:
                            if new == 0:
                                return False
                            domains[i] = new
                            queue.append(i)
        for c in range(n):
            used = col_used[c]
            if used:
                for r in range(n):
                    i = idx(r, c)
                    if bit_count(domains[i]) > 1:
                        new = domains[i] & ~used
                        if new != domains[i]:
                            if new == 0:
                                return False
                            domains[i] = new
                            queue.append(i)

        changed = True
        while changed:
            changed = False

            while queue:
                i = queue.popleft()
                mask = domains[i]
                if mask == 0:
                    return False
                if bit_count(mask) == 1:
                    bit = mask
                    r, c = divmod(i, n)
                    if not (row_used[r] & bit):
                        row_used[r] |= bit
                    if not (col_used[c] & bit):
                        col_used[c] |= bit

                    # Eliminate from peers
                    for cc in range(n):
                        j = idx(r, cc)
                        if j != i and (domains[j] & bit):
                            if not remove_bits(domains, row_used, col_used, j, bit, queue):
                                return False
                    for rr in range(n):
                        j = idx(rr, c)
                        if j != i and (domains[j] & bit):
                            if not remove_bits(domains, row_used, col_used, j, bit, queue):
                                return False

                # Inequality propagation
                # i < j for all j in less_than[i]
                ai = domains[i]
                amin = min_val(ai)
                amax = max_val(ai)
                for j in less_than[i]:
                    bj = domains[j]
                    bmin = min_val(bj)
                    bmax = max_val(bj)

                    # a < b => a <= bmax-1, b >= amin+1
                    rem_a = 0
                    limit_a = bmax - 1
                    if amax > limit_a:
                        for v in range(limit_a + 1, amax + 1):
                            if ai & VAL_TO_BIT[v]:
                                rem_a |= VAL_TO_BIT[v]
                    if rem_a:
                        if not remove_bits(domains, row_used, col_used, i, rem_a, queue):
                            return False
                        ai = domains[i]
                        amin = min_val(ai)
                        amax = max_val(ai)

                    rem_b = 0
                    limit_b = amin + 1
                    if bmin < limit_b:
                        for v in range(bmin, limit_b):
                            if bj & VAL_TO_BIT[v]:
                                rem_b |= VAL_TO_BIT[v]
                    if rem_b:
                        if not remove_bits(domains, row_used, col_used, j, rem_b, queue):
                            return False

                # i > j for all j in greater_than[i], equivalent j < i
                ai = domains[i]
                amin = min_val(ai)
                amax = max_val(ai)
                for j in greater_than[i]:
                    bj = domains[j]
                    bmin = min_val(bj)
                    bmax = max_val(bj)

                    # j < i => i >= bmin+1, j <= amax-1
                    rem_a = 0
                    limit_a = bmin + 1
                    if amin < limit_a:
                        for v in range(amin, limit_a):
                            if ai & VAL_TO_BIT[v]:
                                rem_a |= VAL_TO_BIT[v]
                    if rem_a:
                        if not remove_bits(domains, row_used, col_used, i, rem_a, queue):
                            return False
                        ai = domains[i]
                        amin = min_val(ai)
                        amax = max_val(ai)

                    rem_b = 0
                    limit_b = amax - 1
                    if bmax > limit_b:
                        for v in range(limit_b + 1, bmax + 1):
                            if bj & VAL_TO_BIT[v]:
                                rem_b |= VAL_TO_BIT[v]
                    if rem_b:
                        if not remove_bits(domains, row_used, col_used, j, rem_b, queue):
                            return False

            # Hidden singles in rows/cols
            for groups in (row_cells, col_cells):
                for cells in groups:
                    pos = [0] * (n + 1)
                    cnt = [0] * (n + 1)
                    for i in cells:
                        m = domains[i]
                        x = m
                        while x:
                            b = x & -x
                            v = BIT_TO_VAL[b]
                            cnt[v] += 1
                            pos[v] = i
                            x -= b
                    for v in range(1, n + 1):
                        if cnt[v] == 0:
                            return False
                        if cnt[v] == 1:
                            i = pos[v]
                            if domains[i] != VAL_TO_BIT[v]:
                                q = deque()
                                if not assign(domains, row_used, col_used, i, VAL_TO_BIT[v], q):
                                    return False
                                queue.extend(q)
                                changed = True

            # Hall-like subset elimination on rows/cols, but only for small subsets generated from cell domains
            for groups in (row_cells, col_cells):
                for cells in groups:
                    bucket = {}
                    unresolved = []
                    for i in cells:
                        m = domains[i]
                        if bit_count(m) > 1:
                            unresolved.append(i)
                            bc = bit_count(m)
                            if bc <= 4:
                                bucket.setdefault(m, []).append(i)
                    # Naked subsets from repeated or unioned small masks
                    masks = list(bucket.keys())
                    for m in masks:
                        k = bit_count(m)
                        holders = [i for i in unresolved if domains[i] & ~m == 0]
                        if len(holders) == k and k >= 2:
                            for i in cells:
                                if i not in holders and (domains[i] & m):
                                    if not remove_bits(domains, row_used, col_used, i, m, queue):
                                        return False
                                    changed = True

            # Recompute row/col used consistency
            for r in range(n):
                seen = 0
                for c in range(n):
                    i = idx(r, c)
                    if bit_count(domains[i]) == 1:
                        b = domains[i]
                        if seen & b:
                            return False
                        seen |= b
                row_used[r] = seen
            for c in range(n):
                seen = 0
                for r in range(n):
                    i = idx(r, c)
                    if bit_count(domains[i]) == 1:
                        b = domains[i]
                        if seen & b:
                            return False
                        seen |= b
                col_used[c] = seen

        return True

    def solved(domains):
        return all(bit_count(m) == 1 for m in domains)

    def select_branch_cell(domains):
        best = None
        best_key = None
        for i, m in enumerate(domains):
            bc = bit_count(m)
            if bc <= 1:
                continue
            r, c = divmod(i, n)
            degree = len(less_than[i]) + len(greater_than[i])
            peer_pressure = 0
            for cc in range(n):
                if cc != c and bit_count(domains[idx(r, cc)]) > 1:
                    peer_pressure += 1
            for rr in range(n):
                if rr != r and bit_count(domains[idx(rr, c)]) > 1:
                    peer_pressure += 1
            key = (bc, -degree, -peer_pressure)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def ordered_values(i, domains):
        # Least-constraining-ish ordering with inequality awareness.
        m = domains[i]
        vals = []
        x = m
        while x:
            b = x & -x
            v = BIT_TO_VAL[b]
            score = 0
            for j in less_than[i]:
                dj = domains[j]
                # prefer values that leave many larger options in successor
                cnt = 0
                y = dj
                while y:
                    bb = y & -y
                    if BIT_TO_VAL[bb] > v:
                        cnt += 1
                    y -= bb
                score += cnt
            for j in greater_than[i]:
                dj = domains[j]
                cnt = 0
                y = dj
                while y:
                    bb = y & -y
                    if BIT_TO_VAL[bb] < v:
                        cnt += 1
                    y -= bb
                score += cnt
            vals.append((-score, v, b))
            x -= b
        vals.sort()
        return [b for _, _, b in vals]

    def dfs(domains, row_used, col_used):
        if not propagate(domains, row_used, col_used):
            return None
        if solved(domains):
            return domains

        i = select_branch_cell(domains)
        if i is None:
            return None

        for bit in ordered_values(i, domains):
            nd = domains[:]
            nru = row_used[:]
            ncu = col_used[:]
            q = deque()
            if not assign(nd, nru, ncu, i, bit, q):
                continue
            # seed assignment queue into propagation by directly setting singleton; propagate will handle it
            res = dfs(nd, nru, ncu)
            if res is not None:
                return res

        return None

    result = dfs(domains[:], row_used[:], col_used[:])
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(BIT_TO_VAL[result[idx(r, c)]])
        grid.append(row)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'B', None, None, None, None, None, None, None], ['B', None, None, None, None, None, 'B', None, None, None], ['W', None, None, None, None, 'B', 'W', None, None, 'W'], ['W', None, None, None, None, None, None, None, None, 'B'], [None, None, None, None, 'B', None, None, None, None, None], [None, None, None, None, None, 'B', None, None, None, None], ['W', None, None, None, None, None, None, None, None, 'B'], ['B', None, None, 'B', 'W', None, None, None, None, 'W'], [None, None, None, 'B', None, None, None, None, None, 'W'], [None, None, None, None, None, None, None, 'B', None, None]], 'horizontal': {}, 'vertical': {'(2.5,0.0)': '=', '(0.5,3.0)': 'x', '(0.5,5.0)': 'x', '(1.5,7.0)': 'x', '(3.5,3.0)': 'x', '(4.5,7.0)': '=', '(6.5,8.0)': 'x'}}

# Generalized Binairo/Takuzu solver with extra adjacency constraints.
# The solver emphasizes human-like propagation:
# - fixed clues
# - equality/inequality constraints
# - no three consecutive equal cells
# - equal black/white counts in each row/column
# - unique completed rows/columns
# It combines aggressive deduction with a small, highly-pruned backtracking layer.

from copy import deepcopy

B, W = 'B', 'W'
VALS = (B, W)

def opp(v):
    return W if v == B else B

def parse_coord_key(s):
    s = s.strip()
    if s[0] == '(' and s[-1] == ')':
        s = s[1:-1]
    a, b = s.split(',')
    return float(a.strip()), float(b.strip())

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    horiz = {}
    vert = {}

    for k, v in observation.get('horizontal', {}).items():
        r, c = parse_coord_key(k)
        rr = int(round(r))
        cc = c
        left = int(round(cc - 0.5))
        right = left + 1
        if not (0 <= rr < n and 0 <= left < n and 0 <= right < n):
            return "No Solution"
        horiz[(rr, left)] = v

    for k, v in observation.get('vertical', {}).items():
        r, c = parse_coord_key(k)
        rr = r
        cc = int(round(c))
        up = int(round(rr - 0.5))
        down = up + 1
        if not (0 <= cc < n and 0 <= up < n and 0 <= down < n):
            return "No Solution"
        vert[(up, cc)] = v

    half = n // 2

    def all_edges_for_cell(r, c):
        out = []
        if c - 1 >= 0 and (r, c - 1) in horiz:
            out.append(((r, c - 1), (r, c), horiz[(r, c - 1)]))
        if c < n - 1 and (r, c) in horiz:
            out.append(((r, c), (r, c + 1), horiz[(r, c)]))
        if r - 1 >= 0 and (r - 1, c) in vert:
            out.append(((r - 1, c), (r, c), vert[(r - 1, c)]))
        if r < n - 1 and (r, c) in vert:
            out.append(((r, c), (r + 1, c), vert[(r, c)]))
        return out

    def initial_domains(g):
        d = [[set(VALS) for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for c in range(n):
                if g[r][c] in VALS:
                    d[r][c] = {g[r][c]}
        return d

    def assign(g, d, r, c, v, queue):
        if v not in d[r][c]:
            return False
        if g[r][c] == v:
            return True
        if g[r][c] in VALS and g[r][c] != v:
            return False
        g[r][c] = v
        if d[r][c] != {v}:
            d[r][c] = {v}
        queue.append((r, c))
        return True

    def remove_value(g, d, r, c, v, queue):
        if v not in d[r][c]:
            return True
        if len(d[r][c]) == 1:
            return False
        d[r][c].remove(v)
        if not d[r][c]:
            return False
        if len(d[r][c]) == 1:
            only = next(iter(d[r][c]))
            if g[r][c] is None:
                g[r][c] = only
                queue.append((r, c))
            elif g[r][c] != only:
                return False
        return True

    def line_count_rule(g, d, is_row, idx, queue):
        cells = g[idx] if is_row else [g[r][idx] for r in range(n)]
        b = sum(v == B for v in cells)
        w = sum(v == W for v in cells)
        unknown = [j for j, v in enumerate(cells) if v is None]
        if b > half or w > half:
            return False
        if not unknown:
            return b == half and w == half
        if b == half:
            for j in unknown:
                r, c = (idx, j) if is_row else (j, idx)
                if not assign(g, d, r, c, W, queue):
                    return False
        if w == half:
            for j in unknown:
                r, c = (idx, j) if is_row else (j, idx)
                if not assign(g, d, r, c, B, queue):
                    return False
        remaining = len(unknown)
        if b + remaining < half or w + remaining < half:
            return False
        return True

    def line_no_three_rule(g, d, is_row, idx, queue):
        line = g[idx] if is_row else [g[r][idx] for r in range(n)]
        for i in range(n - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]
            # XX?
            if a in VALS and b == a and c is None:
                r, cc = (idx, i + 2) if is_row else (i + 2, idx)
                if not assign(g, d, r, cc, opp(a), queue):
                    return False
            # ?XX
            if b in VALS and c == b and a is None:
                r, cc = (idx, i) if is_row else (i, idx)
                if not assign(g, d, r, cc, opp(b), queue):
                    return False
            # X?X
            if a in VALS and c == a and b is None:
                r, cc = (idx, i + 1) if is_row else (i + 1, idx)
                if not assign(g, d, r, cc, opp(a), queue):
                    return False
            if a in VALS and b == a and c == a:
                return False
        return True

    def uniqueness_rule(g, d, is_row, idx, queue):
        line = g[idx] if is_row else [g[r][idx] for r in range(n)]
        unknown_pos = [i for i, v in enumerate(line) if v is None]

        if not unknown_pos:
            for j in range(n):
                if j == idx:
                    continue
                other = g[j] if is_row else [g[r][j] for r in range(n)]
                if None not in other and other == line:
                    return False
            return True

        if len(unknown_pos) == 2:
            for j in range(n):
                if j == idx:
                    continue
                other = g[j] if is_row else [g[r][j] for r in range(n)]
                if None in other:
                    continue
                mismatch_known = False
                for k in range(n):
                    if k in unknown_pos:
                        continue
                    if line[k] != other[k]:
                        mismatch_known = True
                        break
                if mismatch_known:
                    continue
                p, q = unknown_pos
                need_p = opp(other[p])
                need_q = opp(other[q])
                # If matching the completed line would require both unknowns equal to other,
                # at least one must differ. With count parity and no-three, stronger propagation often follows.
                # Here, if one unknown already forced to equal other, force the other to differ.
                if line[p] is None and line[q] is None:
                    dp = d[idx][p] if is_row else d[p][idx]
                    dq = d[idx][q] if is_row else d[q][idx]
                    if other[p] not in dp:
                        if not assign(g, d, *( (idx, q, need_q) if is_row else (q, idx, need_q) ), queue):
                            return False
                    if other[q] not in dq:
                        if not assign(g, d, *( (idx, p, need_p) if is_row else (p, idx, need_p) ), queue):
                            return False
        return True

    def adjacency_rule(g, d, r1, c1, r2, c2, rel, queue):
        v1, v2 = g[r1][c1], g[r2][c2]
        if v1 in VALS and v2 in VALS:
            if rel == '=':
                return v1 == v2
            return v1 != v2
        if v1 in VALS and v2 is None:
            need = v1 if rel == '=' else opp(v1)
            return assign(g, d, r2, c2, need, queue)
        if v2 in VALS and v1 is None:
            need = v2 if rel == '=' else opp(v2)
            return assign(g, d, r1, c1, need, queue)

        # domain filtering for both unknown
        if rel == '=':
            common = d[r1][c1] & d[r2][c2]
            if not common:
                return False
            for val in tuple(d[r1][c1] - common):
                if not remove_value(g, d, r1, c1, val, queue):
                    return False
            for val in tuple(d[r2][c2] - common):
                if not remove_value(g, d, r2, c2, val, queue):
                    return False
        else:
            if len(d[r1][c1]) == 1:
                only = next(iter(d[r1][c1]))
                if not remove_value(g, d, r2, c2, only, queue):
                    return False
            if len(d[r2][c2]) == 1:
                only = next(iter(d[r2][c2]))
                if not remove_value(g, d, r1, c1, only, queue):
                    return False
            if len(d[r1][c1]) == 1 and len(d[r2][c2]) == 1:
                return next(iter(d[r1][c1])) != next(iter(d[r2][c2]))
        return True

    def validate_partial(g):
        # counts + no-three + complete uniqueness
        for r in range(n):
            row = g[r]
            if sum(v == B for v in row) > half or sum(v == W for v in row) > half:
                return False
            for i in range(n - 2):
                if row[i] in VALS and row[i] == row[i + 1] == row[i + 2]:
                    return False
        for c in range(n):
            col = [g[r][c] for r in range(n)]
            if sum(v == B for v in col) > half or sum(v == W for v in col) > half:
                return False
            for i in range(n - 2):
                if col[i] in VALS and col[i] == col[i + 1] == col[i + 2]:
                    return False

        for (r, c), rel in horiz.items():
            a, b = g[r][c], g[r][c + 1]
            if a in VALS and b in VALS:
                if rel == '=' and a != b:
                    return False
                if rel == 'x' and a == b:
                    return False
        for (r, c), rel in vert.items():
            a, b = g[r][c], g[r + 1][c]
            if a in VALS and b in VALS:
                if rel == '=' and a != b:
                    return False
                if rel == 'x' and a == b:
                    return False

        complete_rows = {}
        for r in range(n):
            if None not in g[r]:
                t = tuple(g[r])
                if t in complete_rows:
                    return False
                complete_rows[t] = r

        complete_cols = {}
        for c in range(n):
            col = tuple(g[r][c] for r in range(n))
            if None not in col:
                if col in complete_cols:
                    return False
                complete_cols[col] = c

        return True

    def propagate(g, d):
        queue = []
        for r in range(n):
            for c in range(n):
                if g[r][c] in VALS:
                    queue.append((r, c))

        # Also perform full sweep until stable.
        changed = True
        while changed:
            changed = False
            before_state = tuple(tuple(row) for row in g)

            while queue:
                r, c = queue.pop()

                for (a1, b1), (a2, b2), rel in all_edges_for_cell(r, c):
                    if not adjacency_rule(g, d, a1, b1, a2, b2, rel, queue):
                        return False

                if not line_count_rule(g, d, True, r, queue):
                    return False
                if not line_count_rule(g, d, False, c, queue):
                    return False
                if not line_no_three_rule(g, d, True, r, queue):
                    return False
                if not line_no_three_rule(g, d, False, c, queue):
                    return False
                if not uniqueness_rule(g, d, True, r, queue):
                    return False
                if not uniqueness_rule(g, d, False, c, queue):
                    return False

            # global sweeps for lines not touched enough
            for r in range(n):
                if not line_count_rule(g, d, True, r, queue):
                    return False
                if not line_no_three_rule(g, d, True, r, queue):
                    return False
                if not uniqueness_rule(g, d, True, r, queue):
                    return False
            for c in range(n):
                if not line_count_rule(g, d, False, c, queue):
                    return False
                if not line_no_three_rule(g, d, False, c, queue):
                    return False
                if not uniqueness_rule(g, d, False, c, queue):
                    return False
            for (r, c), rel in horiz.items():
                if not adjacency_rule(g, d, r, c, r, c + 1, rel, queue):
                    return False
            for (r, c), rel in vert.items():
                if not adjacency_rule(g, d, r, c, r + 1, c, rel, queue):
                    return False

            if queue:
                changed = True
            else:
                after_state = tuple(tuple(row) for row in g)
                if after_state != before_state:
                    changed = True

            if not validate_partial(g):
                return False

        return True

    def score_cell(g, d, r, c):
        score = 0
        # Prefer highly constrained cells.
        score += 10 * (2 - len(d[r][c]))
        score += 3 * len(all_edges_for_cell(r, c))
        row = g[r]
        col = [g[i][c] for i in range(n)]
        score += abs(sum(v == B for v in row) - half)
        score += abs(sum(v == W for v in row) - half)
        score += abs(sum(v == B for v in col) - half)
        score += abs(sum(v == W for v in col) - half)
        return score

    def choose_cell(g, d):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if g[r][c] is None:
                    key = (len(d[r][c]), -score_cell(g, d, r, c), r, c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def branch_values(g, d, r, c):
        vals = list(d[r][c])
        def local_impact(v):
            impact = 0
            for (_, _), (_, _), rel in all_edges_for_cell(r, c):
                impact += 1
            row = g[r]
            col = [g[i][c] for i in range(n)]
            impact += 2 if sum(x == v for x in row) >= sum(x == opp(v) for x in row) else 0
            impact += 2 if sum(x == v for x in col) >= sum(x == opp(v) for x in col) else 0
            return -impact
        vals.sort(key=local_impact)
        return vals

    def search(g, d):
        if not propagate(g, d):
            return None
        if all(g[r][c] in VALS for r in range(n) for c in range(n)):
            return g if validate_partial(g) else None

        cell = choose_cell(g, d)
        if cell is None:
            return g if validate_partial(g) else None
        r, c = cell

        for v in branch_values(g, d, r, c):
            g2 = [row[:] for row in g]
            d2 = [[set(d[i][j]) for j in range(n)] for i in range(n)]
            q = []
            if assign(g2, d2, r, c, v, q):
                res = search(g2, d2)
                if res is not None:
                    return res
        return None

    domains = initial_domains(grid)
    result = search(grid, domains)
    if result is None:
        return "No Solution"
    return result

