    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'W', None, None, None, None], ['W', None, None, None, None, 'B'], [None, 'B', None, None, 'W', None], [None, 'W', None, None, 'W', None], [None, None, None, None, None, None], ['W', None, None, None, None, 'W']], 'horizontal': {'(0,0.5)': 'x', '(2,0.5)': '=', '(4,2.5)': '='}, 'vertical': {'(2.5,2)': 'x', '(0.5,5)': '=', '(2.5,5)': 'x'}}

# Generalized Binairo/Takuzu solver with adjacent equality/inequality constraints.
# The implementation emphasizes human-like deductions first, then a tightly-pruned search.

from copy import deepcopy

B, W, U = 'B', 'W', None


def opposite(v):
    return W if v == B else B if v == W else None


def parse_point_key(s):
    s = s.strip()
    if s[0] == '(' and s[-1] == ')':
        s = s[1:-1]
    a, b = s.split(',')
    a = a.strip()
    b = b.strip()
    x = float(a) if '.' in a else int(a)
    y = float(b) if '.' in b else int(b)
    return x, y


def build_edges(observation):
    n = len(observation['data'])
    horiz = {}
    vert = {}
    neighbors = {}
    for r in range(n):
        for c in range(n):
            neighbors[(r, c)] = []

    for k, rel in observation.get('horizontal', {}).items():
        r, c05 = parse_point_key(k)
        r = int(r)
        c = int(c05 - 0.5)
        a = (r, c)
        b = (r, c + 1)
        horiz[a, b] = rel
        neighbors[a].append((b, rel))
        neighbors[b].append((a, rel))

    for k, rel in observation.get('vertical', {}).items():
        r05, c = parse_point_key(k)
        r = int(r05 - 0.5)
        c = int(c)
        a = (r, c)
        b = (r + 1, c)
        vert[a, b] = rel
        neighbors[a].append((b, rel))
        neighbors[b].append((a, rel))

    return neighbors, horiz, vert


def related_value(v, rel):
    return v if rel == '=' else opposite(v)


def count_vals(seq):
    b = sum(1 for x in seq if x == B)
    w = sum(1 for x in seq if x == W)
    u = sum(1 for x in seq if x is None)
    return b, w, u


def line_no_three_possible(seq):
    for i in range(len(seq) - 2):
        a, b, c = seq[i], seq[i + 1], seq[i + 2]
        if a is not None and b is not None and c is not None and a == b == c:
            return False
    return True


def line_counts_possible(seq, half):
    b, w, u = count_vals(seq)
    return b <= half and w <= half and b + u >= half and w + u >= half


def line_complete_valid(seq, half):
    if any(x is None for x in seq):
        return False
    b, w, _ = count_vals(seq)
    return b == half and w == half and line_no_three_possible(seq)


def compatible_line(partial, candidate):
    for a, b in zip(partial, candidate):
        if a is not None and a != b:
            return False
    return True


def build_line_patterns(n, fixed_relations):
    half = n // 2
    patterns = []

    def rec(i, cur, bcnt, wcnt):
        if bcnt > half or wcnt > half:
            return
        if i >= 3 and cur[i - 1] == cur[i - 2] == cur[i - 3]:
            return
        if i == n:
            if bcnt == half and wcnt == half:
                ok = True
                for a, b, rel in fixed_relations:
                    va = cur[a]
                    vb = cur[b]
                    if (rel == '=' and va != vb) or (rel == 'x' and va == vb):
                        ok = False
                        break
                if ok:
                    patterns.append(tuple(cur))
            return

        remain = n - i
        if bcnt + remain < half or wcnt + remain < half:
            return

        cur.append(B)
        rec(i + 1, cur, bcnt + 1, wcnt)
        cur.pop()

        cur.append(W)
        rec(i + 1, cur, bcnt, wcnt + 1)
        cur.pop()

    rec(0, [], 0, 0)
    return patterns


def prepare_patterns(observation):
    grid = observation['data']
    n = len(grid)
    row_rels = {r: [] for r in range(n)}
    col_rels = {c: [] for c in range(n)}

    for k, rel in observation.get('horizontal', {}).items():
        r, c05 = parse_point_key(k)
        r = int(r)
        c = int(c05 - 0.5)
        row_rels[r].append((c, c + 1, rel))

    for k, rel in observation.get('vertical', {}).items():
        r05, c = parse_point_key(k)
        r = int(r05 - 0.5)
        c = int(c)
        col_rels[c].append((r, r + 1, rel))

    row_patterns = [build_line_patterns(n, row_rels[r]) for r in range(n)]
    col_patterns = [build_line_patterns(n, col_rels[c]) for c in range(n)]
    return row_patterns, col_patterns


def row_seq(grid, r):
    return list(grid[r])


def col_seq(grid, c):
    return [grid[r][c] for r in range(len(grid))]


def set_cell(grid, r, c, v, queue):
    cur = grid[r][c]
    if cur is not None:
        return cur == v
    grid[r][c] = v
    queue.append((r, c))
    return True


def deduce_from_triplets_line(seq):
    changes = []
    n = len(seq)
    for i in range(n - 2):
        a, b, c = seq[i], seq[i + 1], seq[i + 2]
        if a is not None and a == b and c is None:
            changes.append((i + 2, opposite(a)))
        if b is not None and b == c and a is None:
            changes.append((i, opposite(b)))
        if a is not None and c is not None and a == c and b is None:
            changes.append((i + 1, opposite(a)))
    return changes


def deduce_from_counts_line(seq):
    n = len(seq)
    half = n // 2
    b, w, u = count_vals(seq)
    changes = []
    if u == 0:
        return changes
    if b == half:
        for i, v in enumerate(seq):
            if v is None:
                changes.append((i, W))
    if w == half:
        for i, v in enumerate(seq):
            if v is None:
                changes.append((i, B))
    return changes


def candidate_patterns_for_row(grid, r, row_patterns, used_rows=None):
    seq = row_seq(grid, r)
    cand = [p for p in row_patterns[r] if compatible_line(seq, p)]
    if used_rows is not None and all(x is not None for x in seq):
        pass
    return cand


def candidate_patterns_for_col(grid, c, col_patterns):
    seq = col_seq(grid, c)
    return [p for p in col_patterns[c] if compatible_line(seq, p)]


def pattern_intersection_assignments(partials, indices=None):
    if not partials:
        return None
    n = len(partials[0])
    if indices is None:
        indices = range(n)
    res = {}
    for i in indices:
        first = partials[0][i]
        same = True
        for p in partials[1:]:
            if p[i] != first:
                same = False
                break
        if same:
            res[i] = first
    return res


def propagate(grid, neighbors, row_patterns, col_patterns):
    n = len(grid)
    half = n // 2
    queue = [(r, c) for r in range(n) for c in range(n) if grid[r][c] is not None]

    # Also process all lines at least once even if empty queue becomes insufficient.
    pending_rows = set(range(n))
    pending_cols = set(range(n))

    while queue or pending_rows or pending_cols:
        while queue:
            r, c = queue.pop()

            # Constraint propagation through = / x edges
            v = grid[r][c]
            for (nr, nc), rel in neighbors[(r, c)]:
                req = related_value(v, rel)
                cur = grid[nr][nc]
                if cur is None:
                    if not set_cell(grid, nr, nc, req, queue):
                        return False
                elif cur != req:
                    return False
                pending_rows.add(nr)
                pending_cols.add(nc)

            pending_rows.add(r)
            pending_cols.add(c)

        # Process rows
        while pending_rows:
            r = pending_rows.pop()
            seq = row_seq(grid, r)

            if not line_no_three_possible(seq) or not line_counts_possible(seq, half):
                return False

            for idx, val in deduce_from_triplets_line(seq):
                if seq[idx] is None:
                    if not set_cell(grid, r, idx, val, queue):
                        return False
                elif seq[idx] != val:
                    return False

            seq = row_seq(grid, r)
            for idx, val in deduce_from_counts_line(seq):
                if seq[idx] is None:
                    if not set_cell(grid, r, idx, val, queue):
                        return False
                elif seq[idx] != val:
                    return False

            cands = candidate_patterns_for_row(grid, r, row_patterns)
            if not cands:
                return False
            forced = pattern_intersection_assignments(cands)
            for c, val in forced.items():
                if grid[r][c] is None:
                    if not set_cell(grid, r, c, val, queue):
                        return False
                elif grid[r][c] != val:
                    return False

            # No duplicate completed rows
            if all(x is not None for x in grid[r]):
                for rr in range(n):
                    if rr != r and all(x is not None for x in grid[rr]) and grid[rr] == grid[r]:
                        return False

        # Process columns
        while pending_cols:
            c = pending_cols.pop()
            seq = col_seq(grid, c)

            if not line_no_three_possible(seq) or not line_counts_possible(seq, half):
                return False

            for idx, val in deduce_from_triplets_line(seq):
                if seq[idx] is None:
                    if not set_cell(grid, idx, c, val, queue):
                        return False
                elif seq[idx] != val:
                    return False

            seq = col_seq(grid, c)
            for idx, val in deduce_from_counts_line(seq):
                if seq[idx] is None:
                    if not set_cell(grid, idx, c, val, queue):
                        return False
                elif seq[idx] != val:
                    return False

            cands = candidate_patterns_for_col(grid, c, col_patterns)
            if not cands:
                return False
            forced = pattern_intersection_assignments(cands)
            for r, val in forced.items():
                if grid[r][c] is None:
                    if not set_cell(grid, r, c, val, queue):
                        return False
                elif grid[r][c] != val:
                    return False

            # No duplicate completed columns
            colc = col_seq(grid, c)
            if all(x is not None for x in colc):
                for cc in range(n):
                    if cc == c:
                        continue
                    other = col_seq(grid, cc)
                    if all(x is not None for x in other) and other == colc:
                        return False

    # Final validation of partial uniqueness feasibility using candidate sets
    row_cands = []
    for r in range(n):
        cands = candidate_patterns_for_row(grid, r, row_patterns)
        if not cands:
            return False
        row_cands.append(cands)

    for i in range(n):
        if all(x is not None for x in grid[i]):
            for j in range(i + 1, n):
                if all(x is not None for x in grid[j]) and grid[i] == grid[j]:
                    return False

    for c in range(n):
        cands = candidate_patterns_for_col(grid, c, col_patterns)
        if not cands:
            return False

    return True


def is_solved(grid):
    return all(all(v is not None for v in row) for row in grid)


def choose_branch(grid, row_patterns, col_patterns):
    n = len(grid)
    best = None

    # Prefer most constrained line-pattern branching
    for r in range(n):
        if any(v is None for v in grid[r]):
            cands = candidate_patterns_for_row(grid, r, row_patterns)
            k = len(cands)
            if k > 1:
                score = (k, 'row', r, cands)
                if best is None or score[0] < best[0]:
                    best = score

    for c in range(n):
        seq = col_seq(grid, c)
        if any(v is None for v in seq):
            cands = candidate_patterns_for_col(grid, c, col_patterns)
            k = len(cands)
            if k > 1:
                score = (k, 'col', c, cands)
                if best is None or score[0] < best[0]:
                    best = score

    if best is not None:
        return best[1], best[2], best[3]

    # Fallback cell branching with local support counts
    best_cell = None
    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                row_cands = candidate_patterns_for_row(grid, r, row_patterns)
                col_cands = candidate_patterns_for_col(grid, c, col_patterns)
                supp_b = sum(1 for p in row_cands if p[c] == B) * sum(1 for p in col_cands if p[r] == B)
                supp_w = sum(1 for p in row_cands if p[c] == W) * sum(1 for p in col_cands if p[r] == W)
                options = (1 if supp_b else 0) + (1 if supp_w else 0)
                metric = (options, supp_b + supp_w, r, c)
                if best_cell is None or metric < best_cell:
                    best_cell = metric
    if best_cell is None:
        return None, None, None
    _, _, r, c = best_cell
    vals = []
    row_cands = candidate_patterns_for_row(grid, r, row_patterns)
    col_cands = candidate_patterns_for_col(grid, c, col_patterns)
    if any(p[c] == B for p in row_cands) and any(p[r] == B for p in col_cands):
        vals.append(B)
    if any(p[c] == W for p in row_cands) and any(p[r] == W for p in col_cands):
        vals.append(W)
    return 'cell', (r, c), vals


def dfs(grid, neighbors, row_patterns, col_patterns):
    if not propagate(grid, neighbors, row_patterns, col_patterns):
        return None
    if is_solved(grid):
        return grid

    kind, idx, choices = choose_branch(grid, row_patterns, col_patterns)
    if kind is None:
        return None

    if kind == 'row':
        r = idx
        current = grid[r]
        # Prefer candidates that maximize immediate fills in intersecting columns
        ordered = sorted(
            choices,
            key=lambda p: sum(1 for i, v in enumerate(current) if v is None),
        )
        for p in ordered:
            ng = deepcopy(grid)
            ok = True
            for c, v in enumerate(p):
                if ng[r][c] is None:
                    ng[r][c] = v
                elif ng[r][c] != v:
                    ok = False
                    break
            if not ok:
                continue
            ans = dfs(ng, neighbors, row_patterns, col_patterns)
            if ans is not None:
                return ans
        return None

    if kind == 'col':
        c = idx
        ordered = sorted(
            choices,
            key=lambda p: sum(1 for i in range(len(grid)) if grid[i][c] is None),
        )
        for p in ordered:
            ng = deepcopy(grid)
            ok = True
            for r, v in enumerate(p):
                if ng[r][c] is None:
                    ng[r][c] = v
                elif ng[r][c] != v:
                    ok = False
                    break
            if not ok:
                continue
            ans = dfs(ng, neighbors, row_patterns, col_patterns)
            if ans is not None:
                return ans
        return None

    if kind == 'cell':
        r, c = idx
        for v in choices:
            ng = deepcopy(grid)
            ng[r][c] = v
            ans = dfs(ng, neighbors, row_patterns, col_patterns)
            if ans is not None:
                return ans
        return None

    return None


def solve(observation):
    grid = deepcopy(observation['data'])
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid) or n % 2 != 0:
        return "No Solution"

    neighbors, _, _ = build_edges(observation)
    row_patterns, col_patterns = prepare_patterns(observation)

    ans = dfs(grid, neighbors, row_patterns, col_patterns)
    if ans is None:
        return "No Solution"
    return ans


if __name__ == "__main__":
    print(solve(OBSERVATION))

