# Futoshiki solver with strong propagation and limited search.
# Conventions used for inequalities:
# Horizontal at (r, c+0.5):
#   '<' means cell(r,c) < cell(r,c+1)
#   '>' means cell(r,c) > cell(r,c+1)
# Vertical at (r+0.5, c):
#   '^' means cell(r,c) < cell(r+1,c)
#   'v' means cell(r,c) > cell(r+1,c)

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_list(m):
        out = []
        while m:
            lsb = m & -m
            out.append(lsb.bit_length())
            m ^= lsb
        return out

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    # Build domains
    domains = [[full_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = bit(data[r][c])

    # Build inequality edges as directed a < b
    less_pairs = []
    for k, sym in observation['horizontal'].items():
        r, cp = eval(k)
        r = int(r)
        c = int(cp - 0.5)
        if sym == '<':
            less_pairs.append((r, c, r, c + 1))
        else:
            less_pairs.append((r, c + 1, r, c))
    for k, sym in observation['vertical'].items():
        rp, c = eval(k)
        r = int(rp - 0.5)
        c = int(c)
        if sym == '^':
            less_pairs.append((r, c, r + 1, c))
        else:
            less_pairs.append((r + 1, c, r, c))

    neighbors_lt = [[[] for _ in range(n)] for _ in range(n)]
    neighbors_gt = [[[] for _ in range(n)] for _ in range(n)]
    for r1, c1, r2, c2 in less_pairs:
        neighbors_lt[r1][c1].append((r2, c2))
        neighbors_gt[r2][c2].append((r1, c1))

    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]

    # Transitive depth bounds from inequality DAG-like structure
    # lower_steps[r][c]: at least this many smaller distinct values before it
    # upper_steps[r][c]: at least this many larger distinct values after it
    def longest_paths():
        memo_low = {}
        memo_high = {}

        def dfs_low(r, c):
            key = (r, c)
            if key in memo_low:
                return memo_low[key]
            best = 0
            for pr, pc in neighbors_gt[r][c]:
                v = 1 + dfs_low(pr, pc)
                if v > best:
                    best = v
            memo_low[key] = best
            return best

        def dfs_high(r, c):
            key = (r, c)
            if key in memo_high:
                return memo_high[key]
            best = 0
            for nr, nc in neighbors_lt[r][c]:
                v = 1 + dfs_high(nr, nc)
                if v > best:
                    best = v
            memo_high[key] = best
            return best

        lows = [[0] * n for _ in range(n)]
        highs = [[0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                lows[r][c] = dfs_low(r, c)
                highs[r][c] = dfs_high(r, c)
        return lows, highs

    lower_steps, upper_steps = longest_paths()

    def restrict_min(mask, lo):
        if lo <= 1:
            return mask
        return mask & (full_mask ^ ((1 << (lo - 1)) - 1))

    def restrict_max(mask, hi):
        if hi >= n:
            return mask
        return mask & ((1 << hi) - 1)

    def assign(dom, r, c, value, q):
        nm = bit(value)
        if dom[r][c] == nm:
            return True
        if not (dom[r][c] & nm):
            return False
        dom[r][c] = nm
        q.append((r, c))
        return True

    def remove_mask(dom, r, c, rem, q):
        old = dom[r][c]
        new = old & ~rem
        if new == old:
            return True
        if new == 0:
            return False
        dom[r][c] = new
        q.append((r, c))
        return True

    def apply_bounds(dom, r, c, q):
        lo = 1 + lower_steps[r][c]
        hi = n - upper_steps[r][c]
        new = restrict_max(restrict_min(dom[r][c], lo), hi)
        if new == 0:
            return False
        if new != dom[r][c]:
            dom[r][c] = new
            q.append((r, c))
        return True

    def inequality_prune_pair(dom, a, b, q):
        r1, c1 = a
        r2, c2 = b
        m1 = dom[r1][c1]
        m2 = dom[r2][c2]

        max2 = max_val(m2)
        min1v = min_val(m1)
        nm1 = restrict_max(m1, max2 - 1)
        nm2 = restrict_min(m2, min1v + 1)
        if nm1 == 0 or nm2 == 0:
            return False
        if nm1 != m1:
            dom[r1][c1] = nm1
            q.append((r1, c1))
        if nm2 != m2:
            dom[r2][c2] = nm2
            q.append((r2, c2))
        return True

    def hidden_singles_unit(dom, cells, q):
        changed = False
        pos = [[] for _ in range(n + 1)]
        for r, c in cells:
            m = dom[r][c]
            x = m
            while x:
                lsb = x & -x
                v = lsb.bit_length()
                pos[v].append((r, c))
                x ^= lsb
        for v in range(1, n + 1):
            if len(pos[v]) == 0:
                return None
            if len(pos[v]) == 1:
                r, c = pos[v][0]
                if dom[r][c] != bit(v):
                    if not assign(dom, r, c, v, q):
                        return None
                    changed = True
        return changed

    def naked_subsets_unit(dom, cells, q):
        # Human-style subset elimination, restricted to small subsets for efficiency.
        buckets = {}
        for r, c in cells:
            m = dom[r][c]
            pc = popcount(m)
            if 2 <= pc <= 4:
                buckets.setdefault(m, []).append((r, c))
        changed = False
        for m, group in buckets.items():
            k = popcount(m)
            if len(group) == k:
                for r, c in cells:
                    if (r, c) not in group:
                        if dom[r][c] & m:
                            if not remove_mask(dom, r, c, m, q):
                                return None
                            changed = True
        return changed

    def line_uniqueness_propagation(dom, q, r, c):
        # If singleton in row/col, remove from peers.
        m = dom[r][c]
        if popcount(m) != 1:
            return True
        for cc in range(n):
            if cc != c and (dom[r][cc] & m):
                if not remove_mask(dom, r, cc, m, q):
                    return False
        for rr in range(n):
            if rr != r and (dom[rr][c] & m):
                if not remove_mask(dom, rr, c, m, q):
                    return False
        return True

    def hall_interval_check(dom, cells):
        # Necessary condition on sorted candidate unions for Latin units.
        vals = [dom[r][c] for r, c in cells]
        arr = sorted(vals, key=lambda x: (min_val(x), max_val(x), popcount(x)))
        for i in range(len(arr)):
            union = 0
            min_seen = n + 1
            max_seen = 0
            for j in range(i, len(arr)):
                union |= arr[j]
                min_seen = min(min_seen, min_val(arr[j]))
                max_seen = max(max_seen, max_val(arr[j]))
                width = max_seen - min_seen + 1
                need = j - i + 1
                if width == need and popcount(union) < need:
                    return False
        return True

    def propagate(dom):
        q = deque()

        for r in range(n):
            for c in range(n):
                if not apply_bounds(dom, r, c, q):
                    return False

        for r1, c1, r2, c2 in less_pairs:
            if not inequality_prune_pair(dom, (r1, c1), (r2, c2), q):
                return False

        for r in range(n):
            for c in range(n):
                q.append((r, c))

        while q:
            r, c = q.popleft()
            if dom[r][c] == 0:
                return False

            if not apply_bounds(dom, r, c, q):
                return False

            if not line_uniqueness_propagation(dom, q, r, c):
                return False

            for nr, nc in neighbors_lt[r][c]:
                if not inequality_prune_pair(dom, (r, c), (nr, nc), q):
                    return False
            for pr, pc in neighbors_gt[r][c]:
                if not inequality_prune_pair(dom, (pr, pc), (r, c), q):
                    return False

            hr = hidden_singles_unit(dom, row_cells[r], q)
            if hr is None:
                return False
            hc = hidden_singles_unit(dom, col_cells[c], q)
            if hc is None:
                return False

            nrw = naked_subsets_unit(dom, row_cells[r], q)
            if nrw is None:
                return False
            ncl = naked_subsets_unit(dom, col_cells[c], q)
            if ncl is None:
                return False

            if not hall_interval_check(dom, row_cells[r]):
                return False
            if not hall_interval_check(dom, col_cells[c]):
                return False

        # Final all-different feasibility per unit
        for r in range(n):
            seen_fixed = 0
            union = 0
            for c in range(n):
                m = dom[r][c]
                if popcount(m) == 1:
                    if seen_fixed & m:
                        return False
                    seen_fixed |= m
                union |= m
            if union != full_mask:
                return False

        for c in range(n):
            seen_fixed = 0
            union = 0
            for r in range(n):
                m = dom[r][c]
                if popcount(m) == 1:
                    if seen_fixed & m:
                        return False
                    seen_fixed |= m
                union |= m
            if union != full_mask:
                return False

        return True

    def solved(dom):
        return all(popcount(dom[r][c]) == 1 for r in range(n) for c in range(n))

    def choose_cell(dom):
        # Most constrained + most connected heuristic
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                pc = popcount(dom[r][c])
                if pc > 1:
                    deg = len(neighbors_lt[r][c]) + len(neighbors_gt[r][c])
                    key = (pc, -deg, r, c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def order_values(dom, r, c):
        # Least-constraining values with inequality awareness
        vals = mask_to_list(dom[r][c])
        scored = []
        for v in vals:
            score = 0
            for nr, nc in neighbors_lt[r][c]:
                score += popcount(restrict_min(dom[nr][nc], v + 1))
            for pr, pc in neighbors_gt[r][c]:
                score += popcount(restrict_max(dom[pr][pc], v - 1))
            row_hits = 0
            col_hits = 0
            bv = bit(v)
            for cc in range(n):
                if cc != c and (dom[r][cc] & bv):
                    row_hits += 1
            for rr in range(n):
                if rr != r and (dom[rr][c] & bv):
                    col_hits += 1
            scored.append((score - row_hits - col_hits, v))
        scored.sort(reverse=True)
        return [v for _, v in scored]

    def clone(dom):
        return [row[:] for row in dom]

    def search(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        r, c = choose_cell(dom)
        for v in order_values(dom, r, c):
            nd = clone(dom)
            q = deque()
            if not assign(nd, r, c, v, q):
                continue
            # Immediate propagation from assignment
            while q:
                rr, cc = q.popleft()
                if not apply_bounds(nd, rr, cc, q):
                    break
                if not line_uniqueness_propagation(nd, q, rr, cc):
                    break
                ok = True
                for nr, nc in neighbors_lt[rr][cc]:
                    if not inequality_prune_pair(nd, (rr, cc), (nr, nc), q):
                        ok = False
                        break
                if ok:
                    for pr, pc in neighbors_gt[rr][cc]:
                        if not inequality_prune_pair(nd, (pr, pc), (rr, cc), q):
                            ok = False
                            break
                if not ok:
                    break
            else:
                res = search(nd)
                if res is not None:
                    return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(min_val(result[r][c]))
        grid.append(row)
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B', None, None, None, None, 'W', None], [None, 'B', None, None, None, None, 'W', None], [None, None, 'B', None, None, 'B', None, None], [None, None, None, None, None, None, None, None], [None, None, None, 'W', 'B', None, None, None], ['W', None, None, None, None, None, None, 'W'], [None, None, None, 'B', 'W', None, None, None], [None, 'W', None, None, None, None, 'B', None]], 'horizontal': {'(5, 1.5)': '=', '(1, 0.5)': 'x', '(3, 1.5)': '=', '(2, 5.5)': 'x'}, 'vertical': {'(0.5, 4)': '=', '(5.5, 5)': '=', '(0.5, 6)': '=', '(2.5, 6)': 'x'}}

# Generalized Binairo / Takuzu variant solver with adjacency equality/inequality constraints.
# Uses strong propagation that mirrors common human deductions, plus tightly-pruned search.

def solve(observation):
    data = observation['data']
    hcons_raw = observation.get('horizontal', {})
    vcons_raw = observation.get('vertical', {})

    n = len(data)
    m = len(data[0]) if n else 0
    if n == 0 or m == 0:
        return "No Solution"
    if n % 2 != 0 or m % 2 != 0:
        return "No Solution"

    def parse_key(s):
        s = s.strip()[1:-1]
        a, b = s.split(',')
        a = float(a.strip())
        b = float(b.strip())
        return a, b

    # Build edge constraints as neighbor pairs.
    edge = {}
    neighbors = {}
    for r in range(n):
        for c in range(m):
            neighbors[(r, c)] = []

    for k, sym in hcons_raw.items():
        r, c05 = parse_key(k)
        r = int(round(r))
        c = int(round(c05 - 0.5))
        if 0 <= r < n and 0 <= c < m - 1:
            a = (r, c)
            b = (r, c + 1)
            edge[(a, b)] = sym
            edge[(b, a)] = sym
            neighbors[a].append((b, sym))
            neighbors[b].append((a, sym))

    for k, sym in vcons_raw.items():
        r05, c = parse_key(k)
        r = int(round(r05 - 0.5))
        c = int(round(c))
        if 0 <= r < n - 1 and 0 <= c < m:
            a = (r, c)
            b = (r + 1, c)
            edge[(a, b)] = sym
            edge[(b, a)] = sym
            neighbors[a].append((b, sym))
            neighbors[b].append((a, sym))

    # Domain bitmasks: B=1, W=2, both=3.
    B, W, BW = 1, 2, 3

    dom = [[BW] * m for _ in range(n)]
    for r in range(n):
        for c in range(m):
            if data[r][c] == 'B':
                dom[r][c] = B
            elif data[r][c] == 'W':
                dom[r][c] = W

    target_row = m // 2
    target_col = n // 2

    row_patterns_cache = {}
    col_patterns_cache = {}

    def popcount(x):
        return (x & 1) + ((x >> 1) & 1)

    def mask_to_vals(mask):
        if mask == B:
            return (0,)
        if mask == W:
            return (1,)
        return (0, 1)

    def val_to_mask(v):
        return B if v == 0 else W

    def opposite_mask(mask):
        if mask == B:
            return W
        if mask == W:
            return B
        return BW

    def set_mask(state, r, c, newmask):
        old = state[r][c]
        nm = old & newmask
        if nm == 0:
            return False, True
        if nm != old:
            state[r][c] = nm
            return True, False
        return False, False

    def row_patterns(dom_row):
        key = tuple(dom_row)
        if key in row_patterns_cache:
            return row_patterns_cache[key]

        patterns = []
        arr = [0] * m

        def rec(i, bcnt):
            if bcnt > target_row:
                return
            if i - bcnt > target_row:
                return
            if i >= 2 and arr[i - 1] == arr[i - 2]:
                forced = 1 - arr[i - 1]
                if val_to_mask(forced) & dom_row[i]:
                    arr[i] = forced
                    rec(i + 1, bcnt + (forced == 0))
                return

            allowed = mask_to_vals(dom_row[i])
            for v in allowed:
                if i >= 2 and arr[i - 1] == arr[i - 2] == v:
                    continue
                arr[i] = v
                rec(i + 1, bcnt + (v == 0))
            if i == m:
                pass

        def rec(i, bcnt):
            if bcnt > target_row:
                return
            wcnt = i - bcnt
            if wcnt > target_row:
                return
            if i == m:
                if bcnt == target_row and wcnt == target_row:
                    patterns.append(tuple(arr))
                return
            allowed = mask_to_vals(dom_row[i])
            for v in allowed:
                if i >= 2 and arr[i - 1] == arr[i - 2] == v:
                    continue
                rem = m - (i + 1)
                nb = bcnt + (v == 0)
                nw = wcnt + (v == 1)
                if nb > target_row or nw > target_row:
                    continue
                if nb + rem < target_row or nw + rem < target_row:
                    continue
                arr[i] = v
                rec(i + 1, nb)

        rec(0, 0)
        row_patterns_cache[key] = patterns
        return patterns

    def col_patterns(dom_col):
        key = tuple(dom_col)
        if key in col_patterns_cache:
            return col_patterns_cache[key]

        patterns = []
        arr = [0] * n

        def rec(i, bcnt):
            if bcnt > target_col:
                return
            wcnt = i - bcnt
            if wcnt > target_col:
                return
            if i == n:
                if bcnt == target_col and wcnt == target_col:
                    patterns.append(tuple(arr))
                return
            allowed = mask_to_vals(dom_col[i])
            for v in allowed:
                if i >= 2 and arr[i - 1] == arr[i - 2] == v:
                    continue
                rem = n - (i + 1)
                nb = bcnt + (v == 0)
                nw = wcnt + (v == 1)
                if nb > target_col or nw > target_col:
                    continue
                if nb + rem < target_col or nw + rem < target_col:
                    continue
                arr[i] = v
                rec(i + 1, nb)

        rec(0, 0)
        col_patterns_cache[key] = patterns
        return patterns

    def apply_local_triples(state):
        changed = False
        for r in range(n):
            for c in range(m):
                mask = state[r][c]
                if mask == 0:
                    return None
                # Horizontal pattern deductions
                if c >= 2 and state[r][c - 1] in (B, W) and state[r][c - 2] == state[r][c - 1]:
                    ch, bad = set_mask(state, r, c, opposite_mask(state[r][c - 1]))
                    if bad:
                        return None
                    changed |= ch
                if 0 < c < m - 1 and state[r][c - 1] in (B, W) and state[r][c + 1] == state[r][c - 1]:
                    ch, bad = set_mask(state, r, c, opposite_mask(state[r][c - 1]))
                    if bad:
                        return None
                    changed |= ch
                if c + 2 < m and state[r][c + 1] in (B, W) and state[r][c + 2] == state[r][c + 1]:
                    ch, bad = set_mask(state, r, c, opposite_mask(state[r][c + 1]))
                    if bad:
                        return None
                    changed |= ch

                # Vertical pattern deductions
                if r >= 2 and state[r - 1][c] in (B, W) and state[r - 2][c] == state[r - 1][c]:
                    ch, bad = set_mask(state, r, c, opposite_mask(state[r - 1][c]))
                    if bad:
                        return None
                    changed |= ch
                if 0 < r < n - 1 and state[r - 1][c] in (B, W) and state[r + 1][c] == state[r - 1][c]:
                    ch, bad = set_mask(state, r, c, opposite_mask(state[r - 1][c]))
                    if bad:
                        return None
                    changed |= ch
                if r + 2 < n and state[r + 1][c] in (B, W) and state[r + 2][c] == state[r + 1][c]:
                    ch, bad = set_mask(state, r, c, opposite_mask(state[r + 1][c]))
                    if bad:
                        return None
                    changed |= ch
        return changed

    def apply_count_rules(state):
        changed = False
        # Rows
        for r in range(n):
            b_fixed = sum(state[r][c] == B for c in range(m))
            w_fixed = sum(state[r][c] == W for c in range(m))
            unk = [c for c in range(m) if state[r][c] == BW]
            if b_fixed > target_row or w_fixed > target_row:
                return None
            if b_fixed + len(unk) < target_row or w_fixed + len(unk) < target_row:
                return None
            if b_fixed == target_row:
                for c in unk:
                    ch, bad = set_mask(state, r, c, W)
                    if bad:
                        return None
                    changed |= ch
            elif w_fixed == target_row:
                for c in unk:
                    ch, bad = set_mask(state, r, c, B)
                    if bad:
                        return None
                    changed |= ch

        # Columns
        for c in range(m):
            b_fixed = sum(state[r][c] == B for r in range(n))
            w_fixed = sum(state[r][c] == W for r in range(n))
            unk = [r for r in range(n) if state[r][c] == BW]
            if b_fixed > target_col or w_fixed > target_col:
                return None
            if b_fixed + len(unk) < target_col or w_fixed + len(unk) < target_col:
                return None
            if b_fixed == target_col:
                for r in unk:
                    ch, bad = set_mask(state, r, c, W)
                    if bad:
                        return None
                    changed |= ch
            elif w_fixed == target_col:
                for r in unk:
                    ch, bad = set_mask(state, r, c, B)
                    if bad:
                        return None
                    changed |= ch
        return changed

    def apply_edge_constraints(state):
        changed = False
        for r in range(n):
            for c in range(m):
                here = state[r][c]
                if here == 0:
                    return None
                for (nr, nc), sym in neighbors[(r, c)]:
                    there = state[nr][nc]
                    if sym == '=':
                        allowed = there
                    else:
                        if there == B:
                            allowed = W
                        elif there == W:
                            allowed = B
                        else:
                            allowed = BW
                    ch, bad = set_mask(state, r, c, allowed)
                    if bad:
                        return None
                    changed |= ch
        return changed

    def line_signature(line):
        if all(x in (B, W) for x in line):
            return tuple(line)
        return None

    def apply_uniqueness_rules(state):
        changed = False

        # Completed rows cannot duplicate another completed row.
        completed_rows = {}
        for r in range(n):
            sig = line_signature(state[r])
            if sig is not None:
                if sig in completed_rows:
                    return None
                completed_rows[sig] = r

        for r in range(n):
            if any(state[r][c] == BW for c in range(m)):
                for sig, rr in completed_rows.items():
                    compat = True
                    diff_positions = []
                    for c in range(m):
                        if state[r][c] in (B, W):
                            if state[r][c] != sig[c]:
                                compat = False
                                break
                        else:
                            diff_positions.append(c)
                    if compat:
                        if not diff_positions:
                            return None
                        if len(diff_positions) == 1:
                            c = diff_positions[0]
                            ch, bad = set_mask(state, r, c, opposite_mask(sig[c]))
                            if bad:
                                return None
                            changed |= ch

        # Completed columns cannot duplicate another completed column.
        completed_cols = {}
        for c in range(m):
            col = [state[r][c] for r in range(n)]
            sig = line_signature(col)
            if sig is not None:
                if sig in completed_cols:
                    return None
                completed_cols[sig] = c

        for c in range(m):
            col = [state[r][c] for r in range(n)]
            if any(v == BW for v in col):
                for sig, cc in completed_cols.items():
                    compat = True
                    diff_positions = []
                    for r in range(n):
                        if state[r][c] in (B, W):
                            if state[r][c] != sig[r]:
                                compat = False
                                break
                        else:
                            diff_positions.append(r)
                    if compat:
                        if not diff_positions:
                            return None
                        if len(diff_positions) == 1:
                            r = diff_positions[0]
                            ch, bad = set_mask(state, r, c, opposite_mask(sig[r]))
                            if bad:
                                return None
                            changed |= ch
        return changed

    def apply_pattern_filtering(state):
        changed = False

        # Rows
        row_pattern_sets = []
        complete_rows = {}
        for r in range(n):
            pats = row_patterns(state[r])
            if not pats:
                return None
            row_pattern_sets.append(pats)
            if len(pats) == 1 and all(state[r][c] in (B, W) for c in range(m)):
                complete_rows[pats[0]] = r

        # Enforce row uniqueness against already-complete rows by pattern filtering.
        for r in range(n):
            pats = row_pattern_sets[r]
            if len(pats) > 1:
                filtered = [p for p in pats if p not in complete_rows or complete_rows[p] == r]
                if not filtered:
                    return None
                row_pattern_sets[r] = filtered

        for r in range(n):
            pats = row_pattern_sets[r]
            for c in range(m):
                vals = {p[c] for p in pats}
                newmask = 0
                if 0 in vals:
                    newmask |= B
                if 1 in vals:
                    newmask |= W
                ch, bad = set_mask(state, r, c, newmask)
                if bad:
                    return None
                changed |= ch

        # Columns
        col_pattern_sets = []
        complete_cols = {}
        for c in range(m):
            dom_col = [state[r][c] for r in range(n)]
            pats = col_patterns(dom_col)
            if not pats:
                return None
            col_pattern_sets.append(pats)
            if len(pats) == 1 and all(state[r][c] in (B, W) for r in range(n)):
                complete_cols[pats[0]] = c

        for c in range(m):
            pats = col_pattern_sets[c]
            if len(pats) > 1:
                filtered = [p for p in pats if p not in complete_cols or complete_cols[p] == c]
                if not filtered:
                    return None
                col_pattern_sets[c] = filtered

        for c in range(m):
            pats = col_pattern_sets[c]
            for r in range(n):
                vals = {p[r] for p in pats}
                newmask = 0
                if 0 in vals:
                    newmask |= B
                if 1 in vals:
                    newmask |= W
                ch, bad = set_mask(state, r, c, newmask)
                if bad:
                    return None
                changed |= ch

        return changed

    def check_final(state):
        # Fixed domains
        for r in range(n):
            for c in range(m):
                if state[r][c] not in (B, W):
                    return False

        # Counts and triples
        for r in range(n):
            if sum(state[r][c] == B for c in range(m)) != target_row:
                return False
            for c in range(m - 2):
                if state[r][c] == state[r][c + 1] == state[r][c + 2]:
                    return False

        for c in range(m):
            if sum(state[r][c] == B for r in range(n)) != target_col:
                return False
            for r in range(n - 2):
                if state[r][c] == state[r + 1][c] == state[r + 2][c]:
                    return False

        # Edge constraints
        for r in range(n):
            for c in range(m):
                for (nr, nc), sym in neighbors[(r, c)]:
                    if (r, c) < (nr, nc):
                        if sym == '=' and state[r][c] != state[nr][nc]:
                            return False
                        if sym == 'x' and state[r][c] == state[nr][nc]:
                            return False

        # Uniqueness
        rowsigs = set()
        for r in range(n):
            sig = tuple(state[r])
            if sig in rowsigs:
                return False
            rowsigs.add(sig)

        colsigs = set()
        for c in range(m):
            sig = tuple(state[r][c] for r in range(n))
            if sig in colsigs:
                return False
            colsigs.add(sig)

        return True

    def propagate(state):
        while True:
            any_change = False
            for fn in (
                apply_edge_constraints,
                apply_local_triples,
                apply_count_rules,
                apply_pattern_filtering,
                apply_uniqueness_rules,
            ):
                res = fn(state)
                if res is None:
                    return None
                any_change |= res
            if not any_change:
                return state

    def clone_state(state):
        return [row[:] for row in state]

    def choose_branch_cell(state):
        best = None
        best_score = None
        for r in range(n):
            for c in range(m):
                if state[r][c] == BW:
                    score = len(neighbors[(r, c)])
                    if c >= 2 or (0 < c < m - 1) or c + 2 < m:
                        score += 1
                    if r >= 2 or (0 < r < n - 1) or r + 2 < n:
                        score += 1
                    row_known = sum(state[r][j] in (B, W) for j in range(m))
                    col_known = sum(state[i][c] in (B, W) for i in range(n))
                    score += row_known + col_known
                    if best is None or score > best_score:
                        best = (r, c)
                        best_score = score
        return best

    def branch_order(state, r, c):
        # Try value favored by row/column balance and neighbor constraints.
        b_bias = 0
        w_bias = 0

        row_b = sum(state[r][j] == B for j in range(m))
        row_w = sum(state[r][j] == W for j in range(m))
        col_b = sum(state[i][c] == B for i in range(n))
        col_w = sum(state[i][c] == W for i in range(n))

        if row_b > row_w:
            w_bias += 1
        elif row_w > row_b:
            b_bias += 1

        if col_b > col_w:
            w_bias += 1
        elif col_w > col_b:
            b_bias += 1

        for (nr, nc), sym in neighbors[(r, c)]:
            v = state[nr][nc]
            if v == B:
                if sym == '=':
                    b_bias += 2
                else:
                    w_bias += 2
            elif v == W:
                if sym == '=':
                    w_bias += 2
                else:
                    b_bias += 2

        if b_bias >= w_bias:
            return (B, W)
        return (W, B)

    def search(state):
        state = propagate(state)
        if state is None:
            return None

        done = True
        for r in range(n):
            for c in range(m):
                if state[r][c] == BW:
                    done = False
                    break
            if not done:
                break

        if done:
            return state if check_final(state) else None

        r, c = choose_branch_cell(state)
        for guess in branch_order(state, r, c):
            nxt = clone_state(state)
            nxt[r][c] = guess
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    result = search(dom)
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        out.append(['B' if result[r][c] == B else 'W' for c in range(m)])
    return str(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B', 'B', 'W', 'W', None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, 'W', 'W', 'B', 'B', None]], 'horizontal': {'(1, 2.5)': '=', '(3, 4.5)': '=', '(3, 5.5)': '='}, 'vertical': {'(0.5, 5)': 'x', '(2.5, 2)': 'x', '(3.5, 0)': 'x', '(4.5, 0)': 'x'}}

# Generalized Takuzu / Binairo-style solver with adjacency equality/inequality constraints.
# The solver emphasizes human-like propagation first, then bounded search only if needed.

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0
    if n == 0 or m == 0:
        return "No Solution"
    if n % 2 or m % 2:
        return "No Solution"

    grid = [row[:] for row in data]

    hcons = {}
    for k, v in observation.get('horizontal', {}).items():
        r, c = parse_coord_key(k)
        # key means between (r, floor(c-0.5)) and (r, floor(c+0.5))
        left = int(c - 0.5)
        hcons[(int(r), left)] = v

    vcons = {}
    for k, v in observation.get('vertical', {}).items():
        r, c = parse_coord_key(k)
        # key means between (floor(r-0.5), c) and (floor(r+0.5), c)
        up = int(r - 0.5)
        vcons[(up, int(c))] = v

    neighbors = build_neighbors(n, m, hcons, vcons)

    # Precompute all valid row/column patterns by length.
    row_patterns = valid_patterns_with_constraints(m, m // 2, horizontal_constraints_by_row(m, hcons))
    col_patterns = valid_patterns_with_constraints(n, n // 2, vertical_constraints_by_col(n, vcons))

    # Fast contradiction check for givens and direct constraints
    if not initial_consistency(grid, neighbors):
        return "No Solution"

    state = {
        'grid': grid,
        'row_patterns': row_patterns,
        'col_patterns': col_patterns,
        'neighbors': neighbors,
        'n': n,
        'm': m,
    }

    if not propagate(state):
        return "No Solution"

    sol = search(state)
    if sol is None:
        return "No Solution"
    return '\n'.join(''.join(sol[r][c] for c in range(m)) for r in range(n))


def parse_coord_key(s):
    s = s.strip()
    if s[0] == '(' and s[-1] == ')':
        s = s[1:-1]
    a, b = s.split(',')
    a = a.strip()
    b = b.strip()
    if '.' in a:
        a = float(a)
    else:
        a = int(a)
    if '.' in b:
        b = float(b)
    else:
        b = int(b)
    return a, b


def build_neighbors(n, m, hcons, vcons):
    neighbors = {}
    for r in range(n):
        for c in range(m):
            arr = []
            if c - 1 >= 0 and (r, c - 1) in hcons:
                arr.append(((r, c - 1), hcons[(r, c - 1)]))
            if c + 1 < m and (r, c) in hcons:
                arr.append(((r, c + 1), hcons[(r, c)]))
            if r - 1 >= 0 and (r - 1, c) in vcons:
                arr.append(((r - 1, c), vcons[(r - 1, c)]))
            if r + 1 < n and (r, c) in vcons:
                arr.append(((r + 1, c), vcons[(r, c)]))
            neighbors[(r, c)] = arr
    return neighbors


def horizontal_constraints_by_row(m, hcons):
    out = {}
    for (r, c), sign in hcons.items():
        out.setdefault(r, {})[c] = sign
    return out


def vertical_constraints_by_col(n, vcons):
    out = {}
    for (r, c), sign in vcons.items():
        out.setdefault(c, {})[r] = sign
    return out


def valid_patterns_with_constraints(length, half, indexed_constraints):
    # indexed_constraints: line_index -> {pos_between_i_i1: sign}
    res = {}
    all_patterns = []

    def gen(pos, cur, blacks, whites):
        if blacks > half or whites > half:
            return
        if pos >= 3 and cur[pos - 1] == cur[pos - 2] == cur[pos - 3]:
            return
        if pos == length:
            if blacks == half and whites == half:
                all_patterns.append(tuple(cur))
            return
        cur.append('B')
        gen(pos + 1, cur, blacks + 1, whites)
        cur.pop()
        cur.append('W')
        gen(pos + 1, cur, blacks, whites + 1)
        cur.pop()

    gen(0, [], 0, 0)

    if not indexed_constraints:
        return {'*': all_patterns}

    for idx, cons in indexed_constraints.items():
        ok = []
        for pat in all_patterns:
            good = True
            for c, sign in cons.items():
                if sign == '=' and pat[c] != pat[c + 1]:
                    good = False
                    break
                if sign == 'x' and pat[c] == pat[c + 1]:
                    good = False
                    break
            if good:
                ok.append(pat)
        res[idx] = ok
    res['*'] = all_patterns
    return res


def initial_consistency(grid, neighbors):
    n = len(grid)
    m = len(grid[0])
    for r in range(n):
        b = sum(1 for x in grid[r] if x == 'B')
        w = sum(1 for x in grid[r] if x == 'W')
        if b > m // 2 or w > m // 2:
            return False
        for c in range(m - 2):
            vals = grid[r][c:c + 3]
            if vals[0] is not None and vals[0] == vals[1] == vals[2]:
                return False
    for c in range(m):
        col = [grid[r][c] for r in range(n)]
        b = sum(1 for x in col if x == 'B')
        w = sum(1 for x in col if x == 'W')
        if b > n // 2 or w > n // 2:
            return False
        for r in range(n - 2):
            vals = col[r:r + 3]
            if vals[0] is not None and vals[0] == vals[1] == vals[2]:
                return False
    for r in range(n):
        for c in range(m):
            v = grid[r][c]
            if v is None:
                continue
            for (rr, cc), sign in neighbors[(r, c)]:
                u = grid[rr][cc]
                if u is None:
                    continue
                if sign == '=' and u != v:
                    return False
                if sign == 'x' and u == v:
                    return False
    return True


def copy_state(state):
    return {
        'grid': [row[:] for row in state['grid']],
        'row_patterns': state['row_patterns'],
        'col_patterns': state['col_patterns'],
        'neighbors': state['neighbors'],
        'n': state['n'],
        'm': state['m'],
    }


def opposite(v):
    return 'W' if v == 'B' else 'B'


def allowed_cell_values(state, r, c):
    grid = state['grid']
    if grid[r][c] is not None:
        return {grid[r][c]}
    vals = {'B', 'W'}

    # adjacency constraints
    for (rr, cc), sign in state['neighbors'][(r, c)]:
        u = grid[rr][cc]
        if u is None:
            continue
        if sign == '=':
            vals &= {u}
        else:
            vals &= {opposite(u)}
        if not vals:
            return set()

    # row pattern support
    row_cands = feasible_row_patterns(state, r)
    if not row_cands:
        return set()
    vals &= {pat[c] for pat in row_cands}
    if not vals:
        return set()

    # col pattern support
    col_cands = feasible_col_patterns(state, c)
    if not col_cands:
        return set()
    vals &= {pat[r] for pat in col_cands}
    return vals


def feasible_row_patterns(state, r):
    grid = state['grid']
    m = state['m']
    base = state['row_patterns'].get(r, state['row_patterns']['*'])
    row = grid[r]

    patterns = []
    for pat in base:
        good = True
        for c in range(m):
            if row[c] is not None and row[c] != pat[c]:
                good = False
                break
        if not good:
            continue
        # column capacity / local consistency
        for c in range(m):
            if not pattern_fits_column_position(state, c, r, pat[c]):
                good = False
                break
        if good:
            patterns.append(pat)
    return patterns


def feasible_col_patterns(state, c):
    grid = state['grid']
    n = state['n']
    base = state['col_patterns'].get(c, state['col_patterns']['*'])
    col = [grid[r][c] for r in range(n)]

    patterns = []
    for pat in base:
        good = True
        for r in range(n):
            if col[r] is not None and col[r] != pat[r]:
                good = False
                break
        if not good:
            continue
        for r in range(n):
            if not pattern_fits_row_position(state, r, c, pat[r]):
                good = False
                break
        if good:
            patterns.append(pat)
    return patterns


def pattern_fits_column_position(state, c, target_r, value):
    grid = state['grid']
    n = state['n']
    col_vals = [grid[r][c] if r != target_r else value for r in range(n)]
    b = sum(1 for x in col_vals if x == 'B')
    w = sum(1 for x in col_vals if x == 'W')
    if b > n // 2 or w > n // 2:
        return False
    for r in range(n - 2):
        a, b1, d = col_vals[r], col_vals[r + 1], col_vals[r + 2]
        if a is not None and a == b1 == d:
            return False
    # vertical constraints touching this cell
    for rr in range(n):
        v = col_vals[rr]
        if v is None:
            continue
        for (r2, c2), sign in state['neighbors'][(rr, c)]:
            if c2 != c:
                continue
            u = col_vals[r2]
            if u is None:
                continue
            if sign == '=' and u != v:
                return False
            if sign == 'x' and u == v:
                return False
    return True


def pattern_fits_row_position(state, r, target_c, value):
    grid = state['grid']
    m = state['m']
    row_vals = [grid[r][c] if c != target_c else value for c in range(m)]
    b = sum(1 for x in row_vals if x == 'B')
    w = sum(1 for x in row_vals if x == 'W')
    if b > m // 2 or w > m // 2:
        return False
    for c in range(m - 2):
        a, b1, d = row_vals[c], row_vals[c + 1], row_vals[c + 2]
        if a is not None and a == b1 == d:
            return False
    for cc in range(m):
        v = row_vals[cc]
        if v is None:
            continue
        for (r2, c2), sign in state['neighbors'][(r, cc)]:
            if r2 != r:
                continue
            u = row_vals[c2]
            if u is None:
                continue
            if sign == '=' and u != v:
                return False
            if sign == 'x' and u == v:
                return False
    return True


def assign(state, r, c, val):
    cur = state['grid'][r][c]
    if cur is not None:
        return cur == val
    state['grid'][r][c] = val
    return True


def propagate(state):
    n, m = state['n'], state['m']
    changed = True

    while changed:
        changed = False

        # Basic contradiction scans and direct rule propagation
        for r in range(n):
            if not propagate_line_row(state, r):
                return False
        for c in range(m):
            if not propagate_line_col(state, c):
                return False

        # Constraint-neighbor propagation and domain intersection
        progress = True
        while progress:
            progress = False
            for r in range(n):
                for c in range(m):
                    vals = allowed_cell_values(state, r, c)
                    if not vals:
                        return False
                    if state['grid'][r][c] is None and len(vals) == 1:
                        if not assign(state, r, c, next(iter(vals))):
                            return False
                        progress = True
                        changed = True

        # Unique row / column completion via candidate patterns
        for r in range(n):
            if not refine_by_row_candidates(state, r):
                return False
        for c in range(m):
            if not refine_by_col_candidates(state, c):
                return False

        # Enforce row/column uniqueness when one line completed or nearly matched.
        if not uniqueness_propagation(state):
            return False

    return final_consistency(state)


def propagate_line_row(state, r):
    row = state['grid'][r]
    m = state['m']

    # count balancing
    b = row.count('B')
    w = row.count('W')
    if b > m // 2 or w > m // 2:
        return False
    if b == m // 2:
        for c in range(m):
            if row[c] is None and not assign(state, r, c, 'W'):
                return False
    if w == m // 2:
        for c in range(m):
            if row[c] is None and not assign(state, r, c, 'B'):
                return False

    # no triples
    for c in range(m - 2):
        a, b1, d = row[c], row[c + 1], row[c + 2]
        if a is not None and a == b1 == d:
            return False
        if a is not None and a == b1 and d is None:
            if not assign(state, r, c + 2, opposite(a)):
                return False
        if a is not None and d is not None and a == d and b1 is None:
            if not assign(state, r, c + 1, opposite(a)):
                return False
        if b1 is not None and b1 == d and a is None:
            if not assign(state, r, c, opposite(b1)):
                return False
    return True


def propagate_line_col(state, c):
    n = state['n']
    col = [state['grid'][r][c] for r in range(n)]

    b = col.count('B')
    w = col.count('W')
    if b > n // 2 or w > n // 2:
        return False
    if b == n // 2:
        for r in range(n):
            if state['grid'][r][c] is None and not assign(state, r, c, 'W'):
                return False
    if w == n // 2:
        for r in range(n):
            if state['grid'][r][c] is None and not assign(state, r, c, 'B'):
                return False

    for r in range(n - 2):
        a, b1, d = col[r], col[r + 1], col[r + 2]
        if a is not None and a == b1 == d:
            return False
        if a is not None and a == b1 and d is None:
            if not assign(state, r + 2, c, opposite(a)):
                return False
        if a is not None and d is not None and a == d and b1 is None:
            if not assign(state, r + 1, c, opposite(a)):
                return False
        if b1 is not None and b1 == d and a is None:
            if not assign(state, r, c, opposite(b1)):
                return False
    return True


def refine_by_row_candidates(state, r):
    cands = feasible_row_patterns(state, r)
    if not cands:
        return False
    m = state['m']
    for c in range(m):
        if state['grid'][r][c] is None:
            vals = {pat[c] for pat in cands}
            if len(vals) == 1:
                if not assign(state, r, c, next(iter(vals))):
                    return False
    return True


def refine_by_col_candidates(state, c):
    cands = feasible_col_patterns(state, c)
    if not cands:
        return False
    n = state['n']
    for r in range(n):
        if state['grid'][r][c] is None:
            vals = {pat[r] for pat in cands}
            if len(vals) == 1:
                if not assign(state, r, c, next(iter(vals))):
                    return False
    return True


def uniqueness_propagation(state):
    n, m = state['n'], state['m']
    grid = state['grid']

    # Completed rows must be unique; partial rows cannot match a completed row once all unknowns forced equal.
    complete_rows = {}
    for r in range(n):
        if None not in grid[r]:
            t = tuple(grid[r])
            if t in complete_rows:
                return False
            complete_rows[t] = r

    for r in range(n):
        row = grid[r]
        if None in row:
            for t in complete_rows:
                same_positions = [c for c in range(m) if row[c] is None]
                fixed_match = all(row[c] is None or row[c] == t[c] for c in range(m))
                if fixed_match:
                    # To avoid duplication, at least one unknown must differ.
                    possible_breaks = []
                    for c in same_positions:
                        vals = allowed_cell_values(state, r, c)
                        if opposite(t[c]) in vals:
                            possible_breaks.append(c)
                    if not possible_breaks:
                        return False
                    if len(possible_breaks) == 1:
                        c = possible_breaks[0]
                        if not assign(state, r, c, opposite(t[c])):
                            return False

    complete_cols = {}
    for c in range(m):
        col = tuple(grid[r][c] for r in range(n))
        if None not in col:
            if col in complete_cols:
                return False
            complete_cols[col] = c

    for c in range(m):
        col = [grid[r][c] for r in range(n)]
        if None in col:
            for t in complete_cols:
                fixed_match = all(col[r] is None or col[r] == t[r] for r in range(n))
                if fixed_match:
                    possible_breaks = []
                    for r in range(n):
                        if col[r] is None:
                            vals = allowed_cell_values(state, r, c)
                            if opposite(t[r]) in vals:
                                possible_breaks.append(r)
                    if not possible_breaks:
                        return False
                    if len(possible_breaks) == 1:
                        r = possible_breaks[0]
                        if not assign(state, r, c, opposite(t[r])):
                            return False
    return True


def final_consistency(state):
    if not initial_consistency(state['grid'], state['neighbors']):
        return False

    n, m = state['n'], state['m']
    grid = state['grid']

    for r in range(n):
        cands = feasible_row_patterns(state, r)
        if not cands:
            return False
    for c in range(m):
        cands = feasible_col_patterns(state, c)
        if not cands:
            return False

    # uniqueness for completed rows/cols
    seen = set()
    for r in range(n):
        if None not in grid[r]:
            t = tuple(grid[r])
            if t in seen:
                return False
            seen.add(t)
    seen = set()
    for c in range(m):
        t = tuple(grid[r][c] for r in range(n))
        if None not in t:
            if t in seen:
                return False
            seen.add(t)
    return True


def is_solved(state):
    return all(cell is not None for row in state['grid'] for cell in row) and final_consistency(state)


def choose_branch(state):
    n, m = state['n'], state['m']
    best = None

    # Prefer most constrained cell
    for r in range(n):
        for c in range(m):
            if state['grid'][r][c] is None:
                vals = allowed_cell_values(state, r, c)
                if not vals:
                    return ('cell', r, c, [])
                score = len(vals)
                if best is None or score < best[0]:
                    best = (score, r, c, vals)
                    if score == 2:
                        pass
    if best is not None:
        _, r, c, vals = best
        # value ordering: use row/col candidate support counts
        order = []
        for v in vals:
            rc = sum(1 for pat in feasible_row_patterns(state, r) if pat[c] == v)
            cc = sum(1 for pat in feasible_col_patterns(state, c) if pat[r] == v)
            order.append((rc + cc, v))
        order.sort()
        return ('cell', r, c, [v for _, v in order])

    return None


def search(state):
    if is_solved(state):
        return state['grid']

    branch = choose_branch(state)
    if branch is None:
        return None

    _, r, c, vals = branch
    for v in vals:
        child = copy_state(state)
        if not assign(child, r, c, v):
            continue
        if not propagate(child):
            continue
        sol = search(child)
        if sol is not None:
            return sol
    return None


if __name__ == "__main__":
    print(solve(OBSERVATION))
